pub fn collect_news_snapshots(
    config: &NewsCollectionConfig,
) -> Result<NewsCollectionResult, String> {
    validate_news_collection_config(config)?;
    let mut collected_items = config.inline_items.clone();
    let mut rejected_source_count = 0;
    let mut source_count = 0;
    if let Some(path) = &config.local_fixture_path {
        source_count += 1;
        collected_items.extend(load_collected_news_items_from_local_json(Path::new(path))?);
    }
    for source in &config.sources {
        source_count += 1;
        match source.mode {
            NewsCollectionSourceMode::LocalFixture => {
                let Some(path) = &source.path else {
                    rejected_source_count += 1;
                    continue;
                };
                collected_items.extend(load_collected_news_items_from_local_json(Path::new(path))?);
            }
            NewsCollectionSourceMode::RssFeed | NewsCollectionSourceMode::HttpHeadline => {
                rejected_source_count += 1;
                if !config.allow_network {
                    continue;
                }
                return Err("network news collection is deferred; use LocalFixture".to_string());
            }
        }
    }
    if source_count == 0 && collected_items.is_empty() {
        source_count = 1;
    }
    let news_snapshots =
        convert_collected_news_to_snapshots(&collected_items, config.max_items_per_symbol);
    Ok(NewsCollectionResult {
        source_count,
        collected_item_count: collected_items.len(),
        snapshot_count: news_snapshots.len(),
        rejected_source_count,
        collected_items,
        news_snapshots,
        safety_notes: vec![
            "automated news intake uses local fixtures by default".to_string(),
            "tests and default path perform no network access".to_string(),
            "headlines and summaries only; no full article copying".to_string(),
        ],
    })
}

pub fn load_news_provider_configs_from_local_file(
    path: &Path,
) -> Result<Vec<NewsProviderConfig>, String> {
    validate_local_json_or_toml_path(path, "news provider config path")?;
    if path_has_parent_component(path) {
        return Err(
            "news provider config path must not contain parent-directory traversal".to_string(),
        );
    }
    let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
    reject_unsafe_news_collection_text(&text)?;
    if let Ok(mut configs) = serde_json::from_str::<Vec<NewsProviderConfig>>(&text) {
        normalize_news_provider_config_order(&mut configs);
        validate_news_provider_configs(&configs)?;
        return Ok(configs);
    }
    #[derive(Deserialize)]
    struct NewsProviderConfigFile {
        providers: Vec<NewsProviderConfig>,
    }
    let file: NewsProviderConfigFile =
        if path.extension().and_then(|ext| ext.to_str()) == Some("toml") {
            toml::from_str(&text).map_err(|err| err.to_string())?
        } else {
            serde_json::from_str(&text).map_err(|err| err.to_string())?
        };
    let mut providers = file.providers;
    normalize_news_provider_config_order(&mut providers);
    validate_news_provider_configs(&providers)?;
    Ok(providers)
}

pub fn collect_news_from_providers(
    configs: &[NewsProviderConfig],
) -> Result<NewsCollectionRun, String> {
    let mut configs = configs.to_vec();
    normalize_news_provider_config_order(&mut configs);
    validate_news_provider_configs(&configs)?;
    let policy = SafeNewsFetchPolicy::default();
    let mut provider_results = Vec::new();
    let mut collected_news = Vec::new();
    let mut rejected_news = Vec::new();
    for config in &configs {
        let result = run_news_provider(config, &policy)?;
        provider_results.push(NewsProviderRunResult {
            provider_id: config.provider_id.clone(),
            kind: config.kind,
            status: news_provider_run_status_from_status(result.status),
            collected_count: result.collected_items.len(),
            rejected_count: result.rejected_items.len(),
            message: result
                .error
                .clone()
                .unwrap_or_else(|| result.safety_notes.join("; ")),
        });
        collected_news.extend(result.collected_items);
        rejected_news.extend(result.rejected_items);
    }
    let max_items = configs
        .iter()
        .filter(|config| config.enabled)
        .map(|config| config.max_items)
        .max()
        .unwrap_or_else(default_max_news_items_per_symbol);
    let news_snapshots = convert_collected_news_to_snapshots(&collected_news, max_items);
    let run_seed = configs
        .iter()
        .map(|config| config.provider_id.as_str())
        .collect::<Vec<_>>()
        .join("|");
    Ok(NewsCollectionRun {
        run_id: format!("news-collection-run-{:016x}", stable_fnv1a64(&run_seed)),
        provider_results,
        collected_news,
        rejected_news,
        news_snapshots,
        safety_summary: safety_summary(),
    })
}

pub fn run_news_provider(
    config: &NewsProviderConfig,
    policy: &SafeNewsFetchPolicy,
) -> Result<NewsProviderExecutionResult, String> {
    validate_safe_news_fetch_policy(policy)?;
    validate_news_provider_config_for_policy(config, policy)?;
    if !config.enabled || matches!(config.kind, NewsProviderKind::Disabled) {
        return Ok(news_provider_execution_result(
            config,
            NewsProviderStatus::Disabled,
            Vec::new(),
            Vec::new(),
            None,
            None,
            false,
            vec!["provider disabled by config".to_string()],
        ));
    }
    match config.kind {
        NewsProviderKind::LocalFixture => {
            let path = config.source_path_or_url.as_deref().ok_or_else(|| {
                "local fixture news provider requires source_path_or_url".to_string()
            })?;
            let items = normalize_provider_collected_news_items(
                filter_collected_news_items_for_provider(
                    load_collected_news_items_from_local_json(Path::new(path))?,
                    config,
                ),
                config,
                policy,
            )?;
            Ok(news_provider_execution_result(
                config,
                NewsProviderStatus::LocalFixtureReady,
                items,
                Vec::new(),
                None,
                None,
                false,
                vec![
                    "LocalFixture provider loaded local headline summaries".to_string(),
                    "network_used=false".to_string(),
                ],
            ))
        }
        NewsProviderKind::RssFeed | NewsProviderKind::HttpHeadline => {
            let url = config
                .source_path_or_url
                .as_deref()
                .ok_or_else(|| "remote news provider requires source_path_or_url".to_string())?;
            let host = extract_url_host(url);
            validate_remote_news_source(url, config, policy)?;
            if !policy.network_enabled {
                let mut safety_notes = vec![
                    "remote provider deferred because SafeNewsFetchPolicy.network_enabled=false"
                        .to_string(),
                    "no network call performed".to_string(),
                ];
                if matches!(config.kind, NewsProviderKind::HttpHeadline) {
                    safety_notes
                        .push("no browser, JS, or full article fetch performed".to_string());
                }
                return Ok(news_provider_execution_result(
                    config,
                    NewsProviderStatus::Deferred,
                    Vec::new(),
                    Vec::new(),
                    None,
                    host,
                    false,
                    safety_notes,
                ));
            }
            Ok(news_provider_execution_result(
                config,
                match config.kind {
                    NewsProviderKind::RssFeed => NewsProviderStatus::Deferred,
                    NewsProviderKind::HttpHeadline => NewsProviderStatus::Deferred,
                    _ => unreachable!(),
                },
                Vec::new(),
                Vec::new(),
                Some(
                    "safe network fetch parser is deferred; no browser or full-body fetch"
                        .to_string(),
                ),
                host,
                false,
                vec![
                    "explicit network allowed but provider returned deferred safely".to_string(),
                    "headline-only network pilot is not active without a safe parser".to_string(),
                ],
            ))
        }
        NewsProviderKind::Disabled => unreachable!("disabled handled before match"),
    }
}

pub fn parse_rss_xml_fixture(xml_text: &str, config: RssXmlParseConfig) -> RssXmlParseResult {
    let mut safety_notes = vec![
        "RSS XML fixture parsed locally; network_used=false".to_string(),
        "RSS links are copied as source URLs only; no article link is fetched".to_string(),
        "headline and capped summary only; no full article body storage".to_string(),
    ];
    if let Err(err) = validate_rss_xml_parse_config(&config) {
        return rss_xml_parse_result(
            config,
            Vec::new(),
            Vec::new(),
            RssXmlParseStatus::Rejected,
            vec![err],
        );
    }
    let trimmed = xml_text.trim();
    if trimmed.is_empty() || !trimmed.contains('<') || !trimmed.contains('>') {
        return rss_xml_parse_result(
            config,
            Vec::new(),
            Vec::new(),
            RssXmlParseStatus::InvalidXml,
            vec!["RSS XML fixture is empty or malformed".to_string()],
        );
    }
    let item_blocks = extract_xml_tag_blocks(trimmed, "item");
    if item_blocks.is_empty() {
        let lower = trimmed.to_ascii_lowercase();
        let status = if lower.contains("<rss") || lower.contains("<channel") {
            RssXmlParseStatus::EmptyFeed
        } else {
            RssXmlParseStatus::InvalidXml
        };
        return rss_xml_parse_result(
            config,
            Vec::new(),
            Vec::new(),
            status,
            vec!["RSS XML fixture contains no <item> entries".to_string()],
        );
    }

    let mut parsed_items = Vec::new();
    let mut rejected_items = Vec::new();
    for block in item_blocks.into_iter().take(config.max_items) {
        let title = extract_first_xml_tag_text(&block, "title").unwrap_or_default();
        let link = extract_first_xml_tag_text(&block, "link").filter(|value| !value.is_empty());
        let description =
            extract_first_xml_tag_text(&block, "description").filter(|value| !value.is_empty());
        let pub_date =
            extract_first_xml_tag_text(&block, "pubDate").filter(|value| !value.is_empty());
        let item = RssXmlItem {
            title: title.clone(),
            link,
            description: description
                .as_ref()
                .map(|text| truncate_to_char_limit(text, config.max_summary_chars)),
            pub_date,
            source_label: config.source_label.clone(),
            symbol_hint: config.symbol_hint.clone(),
            market_scope: config.market_scope,
        };
        let safety_text = format!(
            "{} {}",
            item.title,
            item.description.clone().unwrap_or_default()
        );
        if item.title.trim().is_empty() {
            safety_notes.push("RSS item rejected because title is missing".to_string());
            rejected_items.push(item);
            continue;
        }
        if reject_unsafe_rss_item_text(&safety_text).is_err()
            || item
                .description
                .as_deref()
                .map(reject_full_article_like_summary)
                .transpose()
                .is_err()
        {
            safety_notes.push(format!(
                "RSS item rejected by safety filter: {}",
                item.title.trim()
            ));
            rejected_items.push(item);
            continue;
        }
        parsed_items.push(item);
    }
    let parse_status = match (parsed_items.is_empty(), rejected_items.is_empty()) {
        (true, false) => RssXmlParseStatus::Rejected,
        (false, true) => RssXmlParseStatus::Parsed,
        (false, false) => RssXmlParseStatus::ParsedWithWarnings,
        (true, true) => RssXmlParseStatus::EmptyFeed,
    };
    rss_xml_parse_result(
        config,
        parsed_items,
        rejected_items,
        parse_status,
        safety_notes,
    )
}

pub fn convert_rss_items_to_collected_news(items: &[RssXmlItem]) -> Vec<CollectedNewsItem> {
    items
        .iter()
        .filter(|item| !item.title.trim().is_empty())
        .map(|item| CollectedNewsItem {
            symbol: item
                .symbol_hint
                .clone()
                .unwrap_or_else(|| "UNKNOWN".to_string()),
            market_scope: item.market_scope,
            headline: item.title.trim().to_string(),
            summary: item
                .description
                .as_deref()
                .map(str::trim)
                .filter(|summary| !summary.is_empty())
                .unwrap_or("headline-only RSS item")
                .to_string(),
            sentiment_hint: Some("Unknown".to_string()),
            source_label: item.source_label.trim().to_string(),
            timestamp: item
                .pub_date
                .as_deref()
                .map(str::trim)
                .filter(|date| !date.is_empty())
                .unwrap_or("rss-fixture")
                .to_string(),
            url: item.link.clone(),
            license_note: Some(
                "RSS headline, link, short description, and raw pubDate only; no article fetch"
                    .to_string(),
            ),
        })
        .collect()
}

pub fn run_single_allowlisted_rss_fetch_pilot(
    config: &RssFetchPilotConfig,
    policy: &SafeNewsFetchPolicy,
) -> Result<RssFetchPilotResult, String> {
    run_single_allowlisted_rss_fetch_pilot_with_transport(
        config,
        policy,
        &DeferredRealHttpTransport,
    )
}

pub fn run_single_allowlisted_rss_fetch_pilot_with_transport(
    config: &RssFetchPilotConfig,
    policy: &SafeNewsFetchPolicy,
    transport: &dyn SafeHttpTransport,
) -> Result<RssFetchPilotResult, String> {
    validate_rss_fetch_pilot_config(config)?;
    validate_safe_news_fetch_policy(policy)?;
    let http_policy = safe_http_policy_from_rss_fetch_config(config, policy);
    run_single_allowlisted_rss_fetch_pilot_with_http_policy(config, &http_policy, transport)
}

pub fn run_single_allowlisted_rss_fetch_pilot_with_http_policy(
    config: &RssFetchPilotConfig,
    http_policy: &SafeHttpClientPolicy,
    transport: &dyn SafeHttpTransport,
) -> Result<RssFetchPilotResult, String> {
    validate_rss_fetch_pilot_config(config)?;
    validate_safe_http_client_policy(http_policy)?;
    if !config.enabled {
        return Ok(rss_fetch_pilot_result(
            config,
            false,
            false,
            extract_url_host(&config.rss_url),
            false,
            None,
            Some(SafeHttpFetchStatus::Disabled),
            None,
            None,
            Vec::new(),
            RssFetchPilotStatus::Disabled,
            vec!["RSS fetch pilot disabled by config".to_string()],
        ));
    }
    let host = extract_url_host(&config.rss_url)
        .ok_or_else(|| "RSS fetch pilot requires host".to_string())?;
    let request = SafeHttpRequest {
        request_id: format!("safe-http-rss-{:016x}", stable_fnv1a64(&config.rss_url)),
        method: SafeHttpMethod::Get,
        url: config.rss_url.clone(),
        host: host.clone(),
        source_label: config.source_label.clone(),
        paper_only: true,
    };
    let fetch_result = fetch_safe_http_text(request, http_policy, transport);
    if fetch_result.status == SafeHttpFetchStatus::HostRejected {
        return Ok(rss_fetch_pilot_result(
            config,
            true,
            false,
            Some(host),
            false,
            None,
            Some(fetch_result.status),
            None,
            None,
            Vec::new(),
            RssFetchPilotStatus::HostRejected,
            fetch_result.safety_notes,
        ));
    }
    if fetch_result.status != SafeHttpFetchStatus::Fetched {
        let rss_status = match fetch_result.status {
            SafeHttpFetchStatus::ContentTypeRejected
            | SafeHttpFetchStatus::ResponseTooLarge
            | SafeHttpFetchStatus::SchemeRejected
            | SafeHttpFetchStatus::MethodRejected
            | SafeHttpFetchStatus::RedirectRejected
            | SafeHttpFetchStatus::FetchFailed
            | SafeHttpFetchStatus::TimedOut => RssFetchPilotStatus::FetchFailed,
            SafeHttpFetchStatus::Disabled | SafeHttpFetchStatus::FetchDeferred => {
                RssFetchPilotStatus::FetchDeferred
            }
            SafeHttpFetchStatus::HostRejected | SafeHttpFetchStatus::Fetched => unreachable!(),
        };
        return Ok(rss_fetch_pilot_result(
            config,
            true,
            fetch_result
                .response
                .as_ref()
                .map(|response| response.network_used)
                .unwrap_or(false),
            Some(host),
            true,
            fetch_result
                .response
                .as_ref()
                .map(|response| response.received_bytes),
            Some(fetch_result.status),
            fetch_result
                .response
                .as_ref()
                .and_then(|response| response.content_type.as_deref())
                .map(|content_type| {
                    validate_rss_content_type(
                        Some(content_type),
                        &rss_content_type_gate_from_policy(http_policy),
                    )
                })
                .or_else(|| {
                    if fetch_result.status == SafeHttpFetchStatus::ContentTypeRejected {
                        Some(validate_rss_content_type(
                            None,
                            &rss_content_type_gate_from_policy(http_policy),
                        ))
                    } else {
                        None
                    }
                }),
            None,
            Vec::new(),
            rss_status,
            fetch_result.safety_notes,
        ));
    }
    let response = fetch_result
        .response
        .as_ref()
        .ok_or_else(|| "safe HTTP fetch returned Fetched without response".to_string())?;
    let body_text = response
        .body_text
        .clone()
        .unwrap_or_else(|| String::from_utf8_lossy(&response.body_bytes).to_string());
    let parse_result = parse_rss_xml_fixture(
        &body_text,
        RssXmlParseConfig {
            parser_id: format!("{}-safe-http-rss", config.pilot_id),
            source_label: config.source_label.clone(),
            symbol_hint: config.symbol_hint.clone(),
            market_scope: config.market_scope,
            max_items: config.max_items,
            max_summary_chars: config.max_summary_chars,
            trust_level: NewsProviderTrustLevel::ReviewRequired,
            paper_only: true,
        },
    );
    let collected_news = convert_rss_items_to_collected_news(&parse_result.parsed_items);
    let rss_status = match parse_result.parse_status {
        RssXmlParseStatus::Parsed => RssFetchPilotStatus::FetchedAndParsed,
        RssXmlParseStatus::ParsedWithWarnings => RssFetchPilotStatus::ParsedWithWarnings,
        RssXmlParseStatus::EmptyFeed
        | RssXmlParseStatus::InvalidXml
        | RssXmlParseStatus::Rejected => RssFetchPilotStatus::FetchFailed,
    };
    let content_type_status = response.content_type.as_deref().map(|content_type| {
        validate_rss_content_type(
            Some(content_type),
            &rss_content_type_gate_from_policy(http_policy),
        )
    });
    Ok(rss_fetch_pilot_result(
        config,
        true,
        response.network_used,
        Some(host),
        true,
        Some(response.received_bytes),
        Some(fetch_result.status),
        content_type_status,
        Some(parse_result),
        collected_news,
        rss_status,
        fetch_result.safety_notes,
    ))
}

pub fn validate_safe_http_request(
    request: &SafeHttpRequest,
    policy: &SafeHttpClientPolicy,
) -> SafeHttpFetchStatus {
    if !request.paper_only || !policy.paper_only {
        return SafeHttpFetchStatus::FetchFailed;
    }
    if !matches!(request.method, SafeHttpMethod::Get) && !policy.allow_post {
        return SafeHttpFetchStatus::MethodRejected;
    }
    if policy.require_https && !request.url.starts_with("https://") {
        return SafeHttpFetchStatus::SchemeRejected;
    }
    let Some(url_host) = extract_url_host(&request.url) else {
        return SafeHttpFetchStatus::HostRejected;
    };
    if url_host != request.host {
        return SafeHttpFetchStatus::HostRejected;
    }
    let allowed = policy
        .allowed_hosts
        .iter()
        .map(|host| host.trim().trim_start_matches('.').to_ascii_lowercase())
        .any(|host| !host.is_empty() && host == request.host);
    if !allowed {
        return SafeHttpFetchStatus::HostRejected;
    }
    if !policy.network_enabled {
        return SafeHttpFetchStatus::FetchDeferred;
    }
    SafeHttpFetchStatus::Fetched
}

pub fn validate_safe_http_response(
    response: &SafeHttpResponse,
    policy: &SafeHttpClientPolicy,
) -> SafeHttpFetchStatus {
    if !response.paper_only || !policy.paper_only {
        return SafeHttpFetchStatus::FetchFailed;
    }
    if response.received_bytes > policy.max_response_bytes
        || response.body_bytes.len() > policy.max_response_bytes
        || response
            .body_text
            .as_ref()
            .map(|text| text.len() > policy.max_response_bytes)
            .unwrap_or(false)
    {
        return SafeHttpFetchStatus::ResponseTooLarge;
    }
    if let Some(status) = response.status_code {
        if (300..400).contains(&status) && !policy.allow_redirects {
            return SafeHttpFetchStatus::RedirectRejected;
        }
        if !(200..300).contains(&status) {
            return SafeHttpFetchStatus::FetchFailed;
        }
    }
    let gate = rss_content_type_gate_from_policy(policy);
    if validate_rss_content_type(response.content_type.as_deref(), &gate)
        != RssContentTypeStatus::Allowed
    {
        return SafeHttpFetchStatus::ContentTypeRejected;
    }
    let body_text = response
        .body_text
        .clone()
        .unwrap_or_else(|| String::from_utf8_lossy(&response.body_bytes).to_string());
    let lower = body_text.to_ascii_lowercase();
    if !policy.allow_text_html && (lower.contains("<html") || lower.contains("<body")) {
        return SafeHttpFetchStatus::ContentTypeRejected;
    }
    SafeHttpFetchStatus::Fetched
}

pub fn validate_rss_content_type(
    content_type: Option<&str>,
    gate: &RssContentTypeGate,
) -> RssContentTypeStatus {
    let Some(content_type) = content_type else {
        return if gate.allow_missing_content_type {
            RssContentTypeStatus::Allowed
        } else {
            RssContentTypeStatus::MissingRejected
        };
    };
    let normalized = content_type
        .split(';')
        .next()
        .unwrap_or_default()
        .trim()
        .to_ascii_lowercase();
    if gate
        .rejected_content_types
        .iter()
        .map(|value| value.trim().to_ascii_lowercase())
        .any(|value| {
            if value.ends_with('/') {
                normalized.starts_with(&value)
            } else {
                normalized == value
            }
        })
    {
        return RssContentTypeStatus::Rejected;
    }
    if gate
        .allowed_content_types
        .iter()
        .map(|value| value.trim().to_ascii_lowercase())
        .any(|value| normalized == value)
    {
        RssContentTypeStatus::Allowed
    } else {
        RssContentTypeStatus::Rejected
    }
}

pub fn fetch_safe_http_text(
    request: SafeHttpRequest,
    policy: &SafeHttpClientPolicy,
    transport: &dyn SafeHttpTransport,
) -> SafeHttpFetchResult {
    if let Err(err) = validate_safe_http_client_policy(policy) {
        return safe_http_fetch_result(
            request,
            None,
            SafeHttpFetchStatus::FetchFailed,
            Some(err),
            vec!["safe HTTP policy rejected before transport".to_string()],
        );
    }
    let request_status = validate_safe_http_request(&request, policy);
    if request_status != SafeHttpFetchStatus::Fetched {
        return safe_http_fetch_result(
            request,
            None,
            request_status,
            safe_http_rejection_reason(request_status),
            vec![
                "safe HTTP request guard ran before transport".to_string(),
                "no article links, browser, JS, cookies, auth, or custom headers used".to_string(),
            ],
        );
    }
    let transport_result = transport.get_text(&request, policy);
    if transport_result.status != SafeHttpFetchStatus::Fetched {
        return transport_result;
    }
    let Some(response) = transport_result.response.clone() else {
        return safe_http_fetch_result(
            request,
            None,
            SafeHttpFetchStatus::FetchFailed,
            Some("transport returned Fetched without response".to_string()),
            vec!["safe HTTP transport response missing".to_string()],
        );
    };
    let response_status = validate_safe_http_response(&response, policy);
    if response_status != SafeHttpFetchStatus::Fetched {
        return safe_http_fetch_result(
            request,
            Some(response),
            response_status,
            safe_http_rejection_reason(response_status),
            vec![
                "safe HTTP response guard rejected response".to_string(),
                "response was not parsed or cached".to_string(),
            ],
        );
    }
    safe_http_fetch_result(
        request,
        Some(response),
        SafeHttpFetchStatus::Fetched,
        None,
        vec![
            "safe HTTP request and response guards passed".to_string(),
            "RSS XML text only; RSS item links are not fetched".to_string(),
        ],
    )
}

