fn safe_http_fetch_result(
    request: SafeHttpRequest,
    response: Option<SafeHttpResponse>,
    status: SafeHttpFetchStatus,
    rejection_reason: Option<String>,
    safety_notes: Vec<String>,
) -> SafeHttpFetchResult {
    SafeHttpFetchResult {
        request,
        response,
        status,
        rejection_reason,
        safety_notes,
    }
}

fn safe_http_rejection_reason(status: SafeHttpFetchStatus) -> Option<String> {
    match status {
        SafeHttpFetchStatus::Disabled => Some("safe HTTP network disabled".to_string()),
        SafeHttpFetchStatus::SchemeRejected => Some("safe HTTP requires https".to_string()),
        SafeHttpFetchStatus::HostRejected => {
            Some("safe HTTP host is not in exact allowlist".to_string())
        }
        SafeHttpFetchStatus::MethodRejected => Some("safe HTTP allows GET only".to_string()),
        SafeHttpFetchStatus::RedirectRejected => {
            Some("safe HTTP redirects rejected by policy".to_string())
        }
        SafeHttpFetchStatus::ContentTypeRejected => {
            Some("safe HTTP content-type rejected".to_string())
        }
        SafeHttpFetchStatus::ResponseTooLarge => {
            Some("safe HTTP response exceeded max bytes".to_string())
        }
        SafeHttpFetchStatus::TimedOut => Some("safe HTTP request timed out".to_string()),
        SafeHttpFetchStatus::FetchFailed => Some("safe HTTP fetch failed".to_string()),
        SafeHttpFetchStatus::FetchDeferred => Some("safe HTTP fetch deferred".to_string()),
        SafeHttpFetchStatus::Fetched => None,
    }
}

fn validate_safe_http_client_policy(policy: &SafeHttpClientPolicy) -> Result<(), String> {
    if !policy.paper_only {
        return Err("safe HTTP client policy must be paper-only".to_string());
    }
    if policy.allow_post || policy.allow_custom_headers || policy.allow_text_html {
        return Err("safe HTTP client policy enables a forbidden mode".to_string());
    }
    if !policy.require_https {
        return Err("safe HTTP client policy must require HTTPS".to_string());
    }
    if policy.allow_redirects || policy.max_redirects > 0 {
        return Err("safe HTTP client policy must not allow redirects".to_string());
    }
    if policy.timeout_ms == 0 || policy.rate_limit_ms == 0 || policy.max_response_bytes == 0 {
        return Err("safe HTTP client policy limits must be positive".to_string());
    }
    if policy.allowed_content_types.is_empty() {
        return Err("safe HTTP client policy requires allowed content types".to_string());
    }
    Ok(())
}

fn safe_http_policy_from_rss_fetch_config(
    config: &RssFetchPilotConfig,
    policy: &SafeNewsFetchPolicy,
) -> SafeHttpClientPolicy {
    let mut allowed_hosts = config.allowed_domains.clone();
    for domain in &policy.allowed_domains {
        if !allowed_hosts.contains(domain) {
            allowed_hosts.push(domain.clone());
        }
    }
    SafeHttpClientPolicy {
        network_enabled: policy.network_enabled,
        allowed_hosts,
        timeout_ms: config.timeout_ms.max(1),
        rate_limit_ms: config.rate_limit_ms.max(1),
        max_response_bytes: default_safe_http_max_response_bytes(),
        ..SafeHttpClientPolicy::default()
    }
}

fn rss_content_type_gate_from_policy(policy: &SafeHttpClientPolicy) -> RssContentTypeGate {
    RssContentTypeGate {
        allowed_content_types: policy.allowed_content_types.clone(),
        allow_missing_content_type: policy.allow_missing_content_type,
        ..RssContentTypeGate::default()
    }
}

