fn validate_rss_xml_parse_config(config: &RssXmlParseConfig) -> Result<(), String> {
    if !config.paper_only {
        return Err("RSS XML parser config must be paper-only".to_string());
    }
    if config.parser_id.trim().is_empty() || config.source_label.trim().is_empty() {
        return Err("RSS XML parser config requires parser_id and source_label".to_string());
    }
    if config.max_items == 0 || config.max_summary_chars == 0 {
        return Err(
            "RSS XML parser config requires positive max_items and max_summary_chars".to_string(),
        );
    }
    Ok(())
}

fn validate_rss_fetch_pilot_config(config: &RssFetchPilotConfig) -> Result<(), String> {
    if !config.paper_only {
        return Err("RSS fetch pilot config must be paper-only".to_string());
    }
    if config.pilot_id.trim().is_empty() || config.source_label.trim().is_empty() {
        return Err("RSS fetch pilot config requires pilot_id and source_label".to_string());
    }
    if config.max_items == 0 || config.max_summary_chars == 0 {
        return Err(
            "RSS fetch pilot config requires positive max_items and max_summary_chars".to_string(),
        );
    }
    if config.enabled {
        if !config.rss_url.starts_with("https://") {
            return Err("RSS fetch pilot requires https URL when enabled".to_string());
        }
        if config.allowed_domains.is_empty() {
            return Err("RSS fetch pilot requires allowed_domains when enabled".to_string());
        }
    }
    Ok(())
}

fn extract_xml_tag_blocks(xml_text: &str, tag: &str) -> Vec<String> {
    let lower = xml_text.to_ascii_lowercase();
    let open_prefix = format!("<{}", tag.to_ascii_lowercase());
    let close = format!("</{}>", tag.to_ascii_lowercase());
    let mut blocks = Vec::new();
    let mut cursor = 0;
    while let Some(open_rel) = lower[cursor..].find(&open_prefix) {
        let open_start = cursor + open_rel;
        let Some(open_end_rel) = lower[open_start..].find('>') else {
            break;
        };
        let content_start = open_start + open_end_rel + 1;
        let Some(close_rel) = lower[content_start..].find(&close) else {
            break;
        };
        let close_start = content_start + close_rel;
        blocks.push(xml_text[content_start..close_start].to_string());
        cursor = close_start + close.len();
    }
    blocks
}

fn extract_first_xml_tag_text(xml_text: &str, tag: &str) -> Option<String> {
    extract_xml_tag_blocks(xml_text, tag)
        .into_iter()
        .next()
        .map(|value| normalize_xml_text(&value))
        .filter(|value| !value.trim().is_empty())
}

fn normalize_xml_text(text: &str) -> String {
    let cdata_stripped = text
        .replace("<![CDATA[", "")
        .replace("]]>", "")
        .replace('\n', " ");
    let mut without_tags = String::new();
    let mut in_tag = false;
    for ch in cdata_stripped.chars() {
        match ch {
            '<' => in_tag = true,
            '>' => in_tag = false,
            _ if !in_tag => without_tags.push(ch),
            _ => {}
        }
    }
    decode_basic_xml_entities(&without_tags)
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
}

fn decode_basic_xml_entities(text: &str) -> String {
    text.replace("&amp;", "&")
        .replace("&lt;", "<")
        .replace("&gt;", ">")
        .replace("&quot;", "\"")
        .replace("&apos;", "'")
}

fn reject_unsafe_rss_item_text(text: &str) -> Result<(), String> {
    reject_unsafe_news_collection_text(text)?;
    let lower = text.to_ascii_lowercase();
    for prohibited in [
        "broker",
        "brokerage",
        "place order",
        "execute order",
        "submit order",
        "order execution",
        "trading account",
        "account balance",
        "full article",
        "article body",
        "copyrighted article",
    ] {
        if lower.contains(prohibited) {
            return Err(format!("RSS item rejected unsafe text: {prohibited}"));
        }
    }
    Ok(())
}

fn news_provider_run_status_from_status(status: NewsProviderStatus) -> NewsProviderRunStatus {
    match status {
        NewsProviderStatus::Disabled => NewsProviderRunStatus::Disabled,
        NewsProviderStatus::LocalFixtureReady
        | NewsProviderStatus::RssReady
        | NewsProviderStatus::HttpHeadlineReady => NewsProviderRunStatus::Collected,
        NewsProviderStatus::Deferred => NewsProviderRunStatus::ProviderDeferred,
        NewsProviderStatus::Rejected | NewsProviderStatus::Failed => {
            NewsProviderRunStatus::Rejected
        }
    }
}

fn normalize_provider_collected_news_items(
    items: Vec<CollectedNewsItem>,
    config: &NewsProviderConfig,
    policy: &SafeNewsFetchPolicy,
) -> Result<Vec<CollectedNewsItem>, String> {
    let mut normalized = Vec::new();
    for mut item in items
        .into_iter()
        .take(policy.max_items_per_source.min(config.max_items))
    {
        reject_unsafe_news_collection_text(
            &serde_json::to_string(&item).map_err(|err| err.to_string())?,
        )?;
        item.headline = item
            .headline
            .split_whitespace()
            .collect::<Vec<_>>()
            .join(" ");
        item.summary = truncate_to_char_limit(
            &item
                .summary
                .split_whitespace()
                .collect::<Vec<_>>()
                .join(" "),
            policy.max_summary_chars,
        );
        item.source_label = if item.source_label.trim().is_empty() {
            config.source_label.clone()
        } else {
            item.source_label.trim().to_string()
        };
        if item.timestamp.trim().is_empty() {
            item.timestamp = "local-fixture".to_string();
        }
        normalized.push(item);
    }
    normalized.sort_by(|left, right| {
        left.symbol
            .cmp(&right.symbol)
            .then_with(|| left.source_label.cmp(&right.source_label))
            .then_with(|| left.headline.cmp(&right.headline))
    });
    Ok(normalized)
}

fn truncate_to_char_limit(text: &str, limit: usize) -> String {
    if text.chars().count() <= limit {
        return text.to_string();
    }
    text.chars().take(limit).collect()
}

