fn news_collection_result_from_items(
    items: Vec<CollectedNewsItem>,
    max_items_per_symbol: usize,
    safety_notes: Vec<String>,
) -> NewsCollectionResult {
    let news_snapshots = convert_collected_news_to_snapshots(&items, max_items_per_symbol);
    NewsCollectionResult {
        source_count: 1,
        collected_item_count: items.len(),
        snapshot_count: news_snapshots.len(),
        rejected_source_count: 0,
        collected_items: items,
        news_snapshots,
        safety_notes,
    }
}

pub fn convert_collected_news_to_snapshots(
    items: &[CollectedNewsItem],
    max_items_per_symbol: usize,
) -> Vec<NewsSnapshot> {
    let mut per_symbol = std::collections::BTreeMap::<String, usize>::new();
    let mut snapshots = Vec::new();
    let limit = max_items_per_symbol.max(1);
    for item in items {
        let symbol = item.symbol.trim();
        let headline = item.headline.trim();
        let summary = item.summary.trim();
        if symbol.is_empty() || headline.is_empty() || summary.is_empty() {
            continue;
        }
        let count = per_symbol.entry(symbol.to_string()).or_insert(0);
        if *count >= limit {
            continue;
        }
        *count += 1;
        snapshots.push(NewsSnapshot {
            symbol: symbol.to_string(),
            headline: headline.to_string(),
            summary: summary.to_string(),
            sentiment_hint: item
                .sentiment_hint
                .clone()
                .unwrap_or_else(|| infer_news_sentiment_hint(headline, summary).to_string()),
            source_label: item.source_label.trim().to_string(),
            timestamp: item.timestamp.trim().to_string(),
        });
    }
    snapshots
}

pub fn build_ai_research_packets(
    market_data: Vec<MarketDataSnapshot>,
    news: Vec<NewsSnapshot>,
    members: Vec<AICommitteeMember>,
    owner_context: Option<String>,
) -> AIResearchPacketBatch {
    let router_output = route_data_to_ai_members(DataRouterInput {
        market_data,
        news,
        members,
        owner_context,
    });
    let packets: Vec<AIResearchPacket> = router_output
        .packets
        .into_iter()
        .map(|packet| {
            let seed = format!(
                "{}|{}|{:?}",
                packet.member_id, packet.market_data.symbol, packet.market_data.market_scope
            );
            AIResearchPacket {
                packet_id: format!("ai-research-packet-{:016x}", stable_fnv1a64(&seed)),
                member_id: packet.member_id,
                symbol: packet.market_data.symbol.clone(),
                market_scope: packet.market_data.market_scope,
                market_data: packet.market_data,
                news: packet.news,
                owner_context: packet.owner_context,
                previous_member_score: packet.previous_member_score,
                routing_notes: vec![
                    "research packet only; AI member still judges at member boundary".to_string(),
                    "packet does not contain orders, broker credentials, or account data"
                        .to_string(),
                ],
                paper_only: true,
            }
        })
        .collect();
    AIResearchPacketBatch {
        packet_count: packets.len(),
        routed_member_count: router_output.routed_member_count,
        unrouted_symbol_count: router_output.unrouted_symbol_count,
        packets,
        safety_notes: router_output
            .safety_notes
            .into_iter()
            .chain([
                "research packet router does not produce opinions".to_string(),
                "Risk Governor remains final after member/chairman stages".to_string(),
            ])
            .collect(),
    }
}

impl Default for NewsCacheStore {
    fn default() -> Self {
        Self {
            cache_store_id: "minimal-news-cache-store".to_string(),
            entries: Vec::new(),
            latest_collected_at: None,
            paper_only: true,
        }
    }
}

impl NewsCacheStore {
    pub fn load_from_local_json(path: &Path) -> Result<Self, String> {
        validate_local_json_path(path, "news cache path")?;
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        reject_unsafe_news_collection_text(&text)?;
        let mut store: Self = serde_json::from_str(&text).map_err(|err| err.to_string())?;
        validate_news_cache_store(&store)?;
        store.dedupe_by_fingerprint();
        Ok(store)
    }

    pub fn save_to_local_json(&self, path: &Path) -> Result<(), String> {
        validate_local_json_path(path, "news cache path")?;
        validate_news_cache_store(self)?;
        let text = serde_json::to_string_pretty(self).map_err(|err| err.to_string())?;
        reject_unsafe_news_collection_text(&text)?;
        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent).map_err(|err| err.to_string())?;
        }
        fs::write(path, text).map_err(|err| err.to_string())
    }

    pub fn add_entries(&mut self, entries: Vec<NewsCacheEntry>) -> NewsCacheUpdateResult {
        let mut seen: std::collections::BTreeSet<String> = self
            .entries
            .iter()
            .map(|entry| entry.fingerprint.clone())
            .collect();
        let mut added_count = 0;
        let mut duplicate_count = 0;
        let mut rejected_count = 0;
        for entry in entries {
            if validate_news_cache_entry(&entry).is_err() {
                rejected_count += 1;
                continue;
            }
            if !seen.insert(entry.fingerprint.clone()) {
                duplicate_count += 1;
                continue;
            }
            self.latest_collected_at = entry
                .collected_at
                .clone()
                .or(self.latest_collected_at.clone());
            self.entries.push(entry);
            added_count += 1;
        }
        self.dedupe_by_fingerprint();
        NewsCacheUpdateResult {
            added_count,
            duplicate_count,
            rejected_count,
            total_count: self.entries.len(),
            cache_path: None,
            safety_summary: safety_summary(),
        }
    }

    pub fn add_rss_parse_result(
        &mut self,
        parse_result: &RssXmlParseResult,
    ) -> NewsCacheUpdateResult {
        let collected_news = convert_rss_items_to_collected_news(&parse_result.parsed_items);
        let entries = news_cache_entries_from_collected_items(
            &collected_news,
            &parse_result.parser_id,
            parse_result.trust_level,
        );
        self.add_entries(entries)
    }

    pub fn add_provider_execution_result(
        &mut self,
        provider_result: &NewsProviderExecutionResult,
    ) -> NewsCacheUpdateResult {
        let entries = news_cache_entries_from_collected_items(
            &provider_result.collected_items,
            &provider_result.provider_id,
            NewsProviderTrustLevel::ReviewRequired,
        );
        self.add_entries(entries)
    }

    pub fn enforce_max_summary_chars(&mut self, max_summary_chars: usize) {
        for entry in &mut self.entries {
            entry.summary = truncate_to_char_limit(&entry.summary, max_summary_chars);
        }
    }

    pub fn dedupe_by_fingerprint(&mut self) {
        let mut seen = std::collections::BTreeSet::new();
        self.entries.sort_by(|left, right| {
            left.fingerprint
                .cmp(&right.fingerprint)
                .then_with(|| left.cache_id.cmp(&right.cache_id))
        });
        self.entries
            .retain(|entry| seen.insert(entry.fingerprint.clone()));
    }

    pub fn entries_by_symbol(&self, symbol: &str) -> Vec<NewsCacheEntry> {
        self.entries
            .iter()
            .filter(|entry| entry.symbol.as_deref() == Some(symbol))
            .cloned()
            .collect()
    }

    pub fn entries_by_scope(&self, scope: MarketScope) -> Vec<NewsCacheEntry> {
        self.entries
            .iter()
            .filter(|entry| entry.market_scope == Some(scope))
            .cloned()
            .collect()
    }

    pub fn latest(&self, limit: usize) -> Vec<NewsCacheEntry> {
        let mut entries = self.entries.clone();
        entries.sort_by(|left, right| {
            right
                .collected_at
                .cmp(&left.collected_at)
                .then_with(|| left.fingerprint.cmp(&right.fingerprint))
        });
        entries.into_iter().take(limit).collect()
    }

    pub fn trim(&mut self, max_entries: usize) {
        let mut latest = self.latest(max_entries);
        latest.sort_by(|left, right| left.fingerprint.cmp(&right.fingerprint));
        self.entries = latest;
    }
}

pub fn reject_full_article_like_summary(summary: &str) -> Result<(), String> {
    let lower = summary.to_ascii_lowercase();
    for prohibited in [
        "full article",
        "article body",
        "full text",
        "copyright_full_text",
        "content_html",
        "<html",
        "<body",
    ] {
        if lower.contains(prohibited) {
            return Err(format!(
                "news summary rejected full-article-like text: {prohibited}"
            ));
        }
    }
    Ok(())
}

fn empty_news_cache_update(total_count: usize) -> NewsCacheUpdateResult {
    NewsCacheUpdateResult {
        added_count: 0,
        duplicate_count: 0,
        rejected_count: 0,
        total_count,
        cache_path: None,
        safety_summary: safety_summary(),
    }
}

fn merge_news_cache_update(target: &mut NewsCacheUpdateResult, update: NewsCacheUpdateResult) {
    target.added_count += update.added_count;
    target.duplicate_count += update.duplicate_count;
    target.rejected_count += update.rejected_count;
    target.total_count = update.total_count;
    if update.cache_path.is_some() {
        target.cache_path = update.cache_path;
    }
}

pub fn news_cache_entries_from_collected_items(
    items: &[CollectedNewsItem],
    provider_id: &str,
    trust_level: NewsProviderTrustLevel,
) -> Vec<NewsCacheEntry> {
    items
        .iter()
        .filter(|item| {
            !item.headline.trim().is_empty()
                && !item.summary.trim().is_empty()
                && !item.source_label.trim().is_empty()
        })
        .map(|item| {
            let fingerprint = news_fingerprint(
                &item.headline,
                &item.source_label,
                item.url.as_deref(),
                Some(&item.symbol),
                item.market_scope,
            );
            NewsCacheEntry {
                cache_id: format!("news-cache-entry-{fingerprint}"),
                news_id: format!("news-{fingerprint}"),
                symbol: Some(item.symbol.clone()),
                market_scope: item.market_scope,
                headline: item.headline.clone(),
                summary: item.summary.clone(),
                source_label: item.source_label.clone(),
                source_url: item.url.clone(),
                collected_at: Some(item.timestamp.clone()),
                trust_level,
                provider_id: provider_id.to_string(),
                fingerprint,
                paper_only: true,
            }
        })
        .collect()
}

pub fn news_cache_entries_to_news_snapshots(entries: &[NewsCacheEntry]) -> Vec<NewsSnapshot> {
    let items: Vec<CollectedNewsItem> = entries
        .iter()
        .map(|entry| CollectedNewsItem {
            symbol: entry
                .symbol
                .clone()
                .unwrap_or_else(|| "UNKNOWN".to_string()),
            market_scope: entry.market_scope,
            headline: entry.headline.clone(),
            summary: entry.summary.clone(),
            sentiment_hint: None,
            source_label: entry.source_label.clone(),
            timestamp: entry
                .collected_at
                .clone()
                .unwrap_or_else(|| "cache".to_string()),
            url: entry.source_url.clone(),
            license_note: Some("cached headline and short summary only".to_string()),
        })
        .collect();
    convert_collected_news_to_snapshots(&items, default_max_news_items_per_symbol())
}

fn news_fingerprint(
    headline: &str,
    source_label: &str,
    source_url: Option<&str>,
    symbol: Option<&str>,
    market_scope: Option<MarketScope>,
) -> String {
    let normalized_headline = headline.split_whitespace().collect::<Vec<_>>().join(" ");
    let seed = format!(
        "{}|{}|{}|{}|{}",
        normalized_headline.to_ascii_lowercase(),
        source_label.trim().to_ascii_lowercase(),
        source_url.unwrap_or("").trim().to_ascii_lowercase(),
        symbol.unwrap_or("").trim().to_ascii_lowercase(),
        market_scope
            .map(|scope| format!("{scope:?}"))
            .unwrap_or_default()
    );
    format!("{:016x}", stable_fnv1a64(&seed))
}

pub fn run_research_packet_pipeline(
    config: ResearchRunConfig,
) -> Result<ResearchRunResult, String> {
    validate_research_run_config(&config)?;
    let (market_data, members) = load_research_market_data_and_members(&config)?;
    let policy = match &config.owner_intent_policy_path {
        Some(path) => load_owner_intent_policy_from_local_file(Path::new(path))?.policy,
        None => built_in_owner_intent_policy(),
    };
    let (owner_context, owner_feedback_generated_count) =
        load_research_owner_context(&config, &policy)?;
    let provider_configs = match &config.news_provider_config_path {
        Some(path) => load_news_provider_configs_from_local_file(Path::new(path))?,
        None => Vec::new(),
    };
    let news_collection_run = collect_news_from_providers(&provider_configs)?;
    let research_packet_batch = build_ai_research_packets(
        market_data.clone(),
        news_collection_run.news_snapshots.clone(),
        members.clone(),
        owner_context.clone(),
    );
    let mut member_opinion_count = 0;
    let mut event_count = 0;
    let mut committee_session_count = 0;
    let cycle_count = match config.run_mode {
        ResearchRunMode::SingleShot | ResearchRunMode::ManualStep => 1,
        ResearchRunMode::FixedCount => config.max_cycles.max(1),
    };
    for _ in 0..cycle_count {
        let batch_result = run_batch_committee_cycle(BatchCommitteeCycleInput {
            market_data: market_data.clone(),
            news: news_collection_run.news_snapshots.clone(),
            members: members.clone(),
            offline_output_batch: load_research_offline_output_batch(&config)?,
            owner_context: owner_context.clone(),
            paper_outcome: None,
        })?;
        member_opinion_count += batch_result.member_opinion_count;
        event_count += batch_result.event_queue.events.len();
        committee_session_count += batch_result.committee_sessions.len();
    }
    let research_packet_summary = summarize_research_packets(&research_packet_batch, event_count);
    Ok(ResearchRunResult {
        research_run_id: config.research_run_id,
        news_collection_run,
        research_packet_batch,
        member_opinion_count,
        event_count,
        committee_session_count,
        owner_feedback_generated_count,
        research_packet_summary,
        safety_summary: safety_summary(),
    })
}

pub fn run_research_auto_run(
    config: ResearchAutoRunConfig,
) -> Result<ResearchAutoRunResult, String> {
    run_research_auto_run_with_rss_transport(config, &DeferredRealHttpTransport)
}

pub fn run_research_auto_run_with_rss_transport(
    config: ResearchAutoRunConfig,
    rss_transport: &dyn SafeHttpTransport,
) -> Result<ResearchAutoRunResult, String> {
    validate_research_auto_run_config(&config)?;
    let research_config = ResearchRunConfig {
        research_run_id: config.run_id.clone(),
        market_scopes: Vec::new(),
        symbols: Vec::new(),
        market_data_path: Some(config.market_data_path.clone()),
        news_provider_config_path: config.news_provider_config_path.clone(),
        owner_intent_policy_path: config.owner_intent_policy_path.clone(),
        owner_comment_text: config.owner_comment_text.clone(),
        owner_comment_path: config.owner_comment_path.clone(),
        member_state_input_path: config.member_state_input_path.clone(),
        offline_member_output_batch_path: config.offline_member_output_batch_path.clone(),
        run_mode: ResearchRunMode::SingleShot,
        max_cycles: 1,
        paper_only: true,
    };
    let (market_data, members) = load_research_market_data_and_members(&research_config)?;
    let owner_policy = match &config.owner_intent_policy_path {
        Some(path) => load_owner_intent_policy_from_local_file(Path::new(path))?.policy,
        None => built_in_owner_intent_policy(),
    };
    let (owner_context, owner_feedback_generated_count) =
        load_research_owner_context(&research_config, &owner_policy)?;
    let provider_configs = match &config.news_provider_config_path {
        Some(path) => load_news_provider_configs_from_local_file(Path::new(path))?,
        None => Vec::new(),
    };
    let fetch_policy = safe_news_fetch_policy_for_auto_run(&config, &provider_configs);
    let safe_http_policy = safe_http_policy_for_rss_auto_run(&config, &fetch_policy);
    let mut provider_results = Vec::new();
    let mut collected_items = Vec::new();
    for provider_config in &provider_configs {
        let result = run_news_provider(provider_config, &fetch_policy)?;
        collected_items.extend(result.collected_items.clone());
        provider_results.push(result);
    }
    let rss_source_label = config
        .rss_fetch_source_label
        .clone()
        .unwrap_or_else(|| "sample-rss".to_string());
    let rss_symbol_hint = market_data.first().map(|market| market.symbol.clone());
    let rss_market_scope = market_data.first().map(|market| market.market_scope);
    let rss_parse_result = if let Some(path) = &config.rss_xml_fixture_path {
        let xml_text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        Some(parse_rss_xml_fixture(
            &xml_text,
            RssXmlParseConfig {
                parser_id: format!("{}-rss-xml-fixture", config.run_id),
                source_label: rss_source_label.clone(),
                symbol_hint: rss_symbol_hint.clone(),
                market_scope: rss_market_scope,
                max_items: fetch_policy.max_items_per_source,
                max_summary_chars: fetch_policy.max_summary_chars,
                trust_level: NewsProviderTrustLevel::ReviewRequired,
                paper_only: true,
            },
        ))
    } else {
        None
    };
    if let Some(parse_result) = &rss_parse_result {
        collected_items.extend(convert_rss_items_to_collected_news(
            &parse_result.parsed_items,
        ));
    }
    let rss_fetch_pilot_result = if config.rss_fetch_pilot_enabled {
        let pilot_url = config
            .rss_fetch_pilot_url
            .clone()
            .ok_or_else(|| "RSS fetch pilot URL is required when enabled".to_string())?;
        Some(run_single_allowlisted_rss_fetch_pilot_with_http_policy(
            &RssFetchPilotConfig {
                pilot_id: format!("{}-single-rss-pilot", config.run_id),
                enabled: true,
                rss_url: pilot_url,
                allowed_domains: config.rss_fetch_allowed_domains.clone(),
                timeout_ms: fetch_policy.timeout_ms,
                rate_limit_ms: fetch_policy.rate_limit_ms,
                max_items: fetch_policy.max_items_per_source,
                max_summary_chars: fetch_policy.max_summary_chars,
                source_label: rss_source_label.clone(),
                symbol_hint: rss_symbol_hint,
                market_scope: rss_market_scope,
                paper_only: true,
            },
            &safe_http_policy,
            rss_transport,
        )?)
    } else {
        None
    };
    if let Some(pilot_result) = &rss_fetch_pilot_result {
        collected_items.extend(pilot_result.collected_news.clone());
    }
    let mut cache = if let Some(path) = &config.news_cache_input_path {
        if Path::new(path).exists() {
            NewsCacheStore::load_from_local_json(Path::new(path))?
        } else {
            NewsCacheStore::default()
        }
    } else {
        NewsCacheStore::default()
    };
    let mut news_cache_update = empty_news_cache_update(cache.entries.len());
    for result in &provider_results {
        merge_news_cache_update(
            &mut news_cache_update,
            cache.add_provider_execution_result(result),
        );
    }
    if let Some(parse_result) = &rss_parse_result {
        merge_news_cache_update(
            &mut news_cache_update,
            cache.add_rss_parse_result(parse_result),
        );
    }
    if let Some(pilot_result) = &rss_fetch_pilot_result {
        let entries = news_cache_entries_from_collected_items(
            &pilot_result.collected_news,
            &pilot_result.pilot_id,
            NewsProviderTrustLevel::ReviewRequired,
        );
        merge_news_cache_update(&mut news_cache_update, cache.add_entries(entries));
    }
    cache.enforce_max_summary_chars(fetch_policy.max_summary_chars);
    news_cache_update.total_count = cache.entries.len();
    if let Some(path) = &config.news_cache_output_path {
        cache.save_to_local_json(Path::new(path))?;
        news_cache_update.cache_path = Some(path.clone());
    }
    let news_snapshots = news_cache_entries_to_news_snapshots(&cache.entries);
    let research_packet_batch = build_ai_research_packets(
        market_data.clone(),
        news_snapshots.clone(),
        members.clone(),
        owner_context.clone(),
    );
    let committee_cycle_result = if config.run_committee_cycle {
        Some(run_batch_committee_cycle(BatchCommitteeCycleInput {
            market_data: market_data.clone(),
            news: news_snapshots.clone(),
            members: members.clone(),
            offline_output_batch: load_research_offline_output_batch(&research_config)?,
            owner_context: owner_context.clone(),
            paper_outcome: None,
        })?)
    } else {
        None
    };
    let member_opinion_count = committee_cycle_result
        .as_ref()
        .map(|result| result.member_opinion_count)
        .unwrap_or(0);
    let event_count = committee_cycle_result
        .as_ref()
        .map(|result| result.event_queue.events.len())
        .unwrap_or(0);
    let committee_session_count = committee_cycle_result
        .as_ref()
        .map(|result| result.committee_sessions.len())
        .unwrap_or(0);
    let news_collection_run = NewsCollectionRun {
        run_id: format!(
            "news-collection-run-{:016x}",
            stable_fnv1a64(&config.run_id)
        ),
        provider_results: provider_results
            .iter()
            .zip(provider_configs.iter())
            .map(|(result, provider_config)| NewsProviderRunResult {
                provider_id: result.provider_id.clone(),
                kind: provider_config.kind,
                status: news_provider_run_status_from_status(result.status),
                collected_count: result.collected_items.len(),
                rejected_count: result.rejected_items.len(),
                message: result
                    .error
                    .clone()
                    .unwrap_or_else(|| result.safety_notes.join("; ")),
            })
            .collect(),
        collected_news: collected_items,
        rejected_news: provider_results
            .iter()
            .flat_map(|result| result.rejected_items.clone())
            .collect(),
        news_snapshots: news_snapshots.clone(),
        safety_summary: safety_summary(),
    };
    let research_run_result = ResearchRunResult {
        research_run_id: config.run_id.clone(),
        news_collection_run,
        research_packet_batch: research_packet_batch.clone(),
        member_opinion_count,
        event_count,
        committee_session_count,
        owner_feedback_generated_count,
        research_packet_summary: summarize_research_packets(&research_packet_batch, event_count),
        safety_summary: safety_summary(),
    };
    let rss_parse_status = rss_parse_result
        .as_ref()
        .map(|parse_result| parse_result.parse_status);
    let rss_items_parsed = rss_parse_result
        .as_ref()
        .map(|parse_result| parse_result.parsed_count)
        .unwrap_or(0);
    let network_used = provider_results.iter().any(|result| result.network_used)
        || rss_fetch_pilot_result
            .as_ref()
            .map(|result| result.network_used)
            .unwrap_or(false);
    let host_allowed = rss_fetch_pilot_result.as_ref().map(|result| result.allowed);
    let safe_http_fetch_status = rss_fetch_pilot_result
        .as_ref()
        .and_then(|result| result.safe_http_status);
    let rss_content_type_status = rss_fetch_pilot_result
        .as_ref()
        .and_then(|result| result.content_type_status);
    let network_used_count = usize::from(network_used);
    let rss_fetched_count = rss_fetch_pilot_result
        .as_ref()
        .map(|result| usize::from(result.status == RssFetchPilotStatus::FetchedAndParsed))
        .unwrap_or(0);
    let rss_rejected_count = rss_parse_result
        .as_ref()
        .map(|result| result.rejected_count)
        .unwrap_or(0)
        + rss_fetch_pilot_result
            .as_ref()
            .and_then(|result| result.parse_result.as_ref())
            .map(|result| result.rejected_count)
            .unwrap_or(0);
    let cache_added_count = news_cache_update.added_count;
    let research_packet_count = research_packet_batch.packet_count;
    Ok(ResearchAutoRunResult {
        run_id: config.run_id,
        news_provider_results: provider_results,
        rss_parse_result,
        rss_fetch_pilot_result,
        news_cache_update,
        research_packet_batch,
        research_run_result,
        committee_cycle_result,
        owner_summary: None,
        rss_parse_status,
        rss_items_parsed,
        network_used,
        host_allowed,
        safe_http_fetch_status,
        rss_content_type_status,
        network_used_count,
        rss_fetched_count,
        rss_rejected_count,
        cache_added_count,
        research_packet_count,
        paper_only_warning:
            "paper-only research routing; AI members judge and Risk Governor remains final"
                .to_string(),
        safety_summary: safety_summary(),
    })
}

pub fn run_research_auto_run_from_minimal_config_path(
    path: &Path,
) -> Result<ResearchAutoRunResult, String> {
    let config = MinimalAiCommitteeCycleConfig::from_toml_path(path)?;
    config.validate()?;
    let market_data_path = config
        .local_market_data_path
        .clone()
        .or(config.input_path.clone())
        .ok_or_else(|| "research auto run requires market data path".to_string())?;
    let auto_config = ResearchAutoRunConfig {
        run_id: config
            .run_id
            .clone()
            .unwrap_or_else(|| "minimal-research-auto-run".to_string()),
        market_data_path,
        news_provider_config_path: config.news_provider_config_path.clone(),
        news_cache_input_path: config.news_cache_input_path.clone(),
        news_cache_output_path: config.news_cache_output_path.clone(),
        owner_intent_policy_path: config.owner_intent_policy_path.clone(),
        owner_comment_text: config.owner_comment_text.clone(),
        owner_comment_path: config.owner_comment_path.clone(),
        member_state_input_path: config.member_state_input_path.clone(),
        offline_member_output_batch_path: config.offline_member_output_batch_path.clone(),
        network_mode: match config.news_network_mode {
            NewsProviderRunMode::OfflineOnly => ResearchNetworkMode::OfflineOnly,
            NewsProviderRunMode::ExplicitNetworkAllowed => {
                ResearchNetworkMode::ExplicitNetworkAllowed
            }
        },
        news_fetch_policy: config.news_fetch_policy.clone(),
        rss_xml_fixture_path: config.rss_xml_fixture_path.clone(),
        rss_fetch_pilot_enabled: config.rss_fetch_pilot_enabled,
        rss_fetch_pilot_url: config.rss_fetch_pilot_url.clone(),
        rss_fetch_allowed_domains: config.rss_fetch_allowed_domains.clone(),
        rss_fetch_source_label: config.rss_fetch_source_label.clone(),
        rss_network_enabled: config.rss_network_enabled,
        rss_safe_http_timeout_ms: config.rss_safe_http_timeout_ms,
        rss_safe_http_rate_limit_ms: config.rss_safe_http_rate_limit_ms,
        rss_safe_http_max_response_bytes: config.rss_safe_http_max_response_bytes,
        rss_allowed_content_types: config.rss_allowed_content_types.clone(),
        rss_allow_redirects: config.rss_allow_redirects,
        rss_allow_missing_content_type: config.rss_allow_missing_content_type,
        run_committee_cycle: config.run_committee_cycle_from_research_packets,
        emit_research_summary: config.emit_research_run_summary,
        paper_only: true,
    };
    run_research_auto_run(auto_config)
}

fn validate_research_auto_run_config(config: &ResearchAutoRunConfig) -> Result<(), String> {
    if !config.paper_only {
        return Err("research auto run config must be paper-only".to_string());
    }
    if config.run_id.trim().is_empty() {
        return Err("research auto run requires run_id".to_string());
    }
    for path in [
        Some(&config.market_data_path),
        config.news_provider_config_path.as_ref(),
        config.news_cache_input_path.as_ref(),
        config.news_cache_output_path.as_ref(),
        config.rss_xml_fixture_path.as_ref(),
        config.owner_intent_policy_path.as_ref(),
        config.owner_comment_path.as_ref(),
        config.member_state_input_path.as_ref(),
        config.offline_member_output_batch_path.as_ref(),
    ]
    .into_iter()
    .flatten()
    {
        if !local_only(path) {
            return Err("research auto run paths must be local".to_string());
        }
        if path_has_parent_component(Path::new(path)) {
            return Err(
                "research auto run paths must not contain parent-directory traversal".to_string(),
            );
        }
    }
    if let Some(policy) = &config.news_fetch_policy {
        validate_safe_news_fetch_policy(policy)?;
    }
    if config.rss_safe_http_timeout_ms == 0
        || config.rss_safe_http_rate_limit_ms == 0
        || config.rss_safe_http_max_response_bytes == 0
    {
        return Err("research auto run RSS safe HTTP limits must be positive".to_string());
    }
    if config.rss_fetch_pilot_enabled {
        let Some(url) = &config.rss_fetch_pilot_url else {
            return Err("research auto run RSS fetch pilot requires URL when enabled".to_string());
        };
        if !url.starts_with("https://") {
            return Err("research auto run RSS fetch pilot URL must be https".to_string());
        }
        if config.rss_fetch_allowed_domains.is_empty() {
            return Err(
                "research auto run RSS fetch pilot requires exact allowed domains".to_string(),
            );
        }
    }
    Ok(())
}

fn safe_news_fetch_policy_for_auto_run(
    config: &ResearchAutoRunConfig,
    provider_configs: &[NewsProviderConfig],
) -> SafeNewsFetchPolicy {
    let mut policy = config.news_fetch_policy.clone().unwrap_or_default();
    policy.network_enabled = matches!(
        config.network_mode,
        ResearchNetworkMode::ExplicitNetworkAllowed
    ) && policy.network_enabled;
    for provider_config in provider_configs {
        for domain in &provider_config.allowed_domains {
            if !policy.allowed_domains.contains(domain) {
                policy.allowed_domains.push(domain.clone());
            }
        }
    }
    for domain in &config.rss_fetch_allowed_domains {
        if !policy.allowed_domains.contains(domain) {
            policy.allowed_domains.push(domain.clone());
        }
    }
    policy
}

fn safe_http_policy_for_rss_auto_run(
    config: &ResearchAutoRunConfig,
    news_policy: &SafeNewsFetchPolicy,
) -> SafeHttpClientPolicy {
    let mut allowed_hosts = config.rss_fetch_allowed_domains.clone();
    for domain in &news_policy.allowed_domains {
        if !allowed_hosts.contains(domain) {
            allowed_hosts.push(domain.clone());
        }
    }
    SafeHttpClientPolicy {
        network_enabled: matches!(
            config.network_mode,
            ResearchNetworkMode::ExplicitNetworkAllowed
        ) && config.rss_network_enabled
            && news_policy.network_enabled,
        allowed_hosts,
        timeout_ms: config.rss_safe_http_timeout_ms.max(1),
        rate_limit_ms: config.rss_safe_http_rate_limit_ms.max(1),
        max_response_bytes: config.rss_safe_http_max_response_bytes.max(1),
        allowed_content_types: if config.rss_allowed_content_types.is_empty() {
            default_safe_http_allowed_content_types()
        } else {
            config.rss_allowed_content_types.clone()
        },
        allow_redirects: config.rss_allow_redirects,
        max_redirects: usize::from(config.rss_allow_redirects),
        allow_missing_content_type: config.rss_allow_missing_content_type,
        ..SafeHttpClientPolicy::default()
    }
}

fn validate_research_run_config(config: &ResearchRunConfig) -> Result<(), String> {
    if !config.paper_only {
        return Err("research run config must be paper-only".to_string());
    }
    if config.research_run_id.trim().is_empty() {
        return Err("research run config requires research_run_id".to_string());
    }
    if config.max_cycles == 0 {
        return Err("research run max_cycles must be greater than zero".to_string());
    }
    for path in [
        config.market_data_path.as_ref(),
        config.news_provider_config_path.as_ref(),
        config.owner_intent_policy_path.as_ref(),
        config.owner_comment_path.as_ref(),
        config.member_state_input_path.as_ref(),
        config.offline_member_output_batch_path.as_ref(),
    ]
    .into_iter()
    .flatten()
    {
        if !local_only(path) {
            return Err("research run paths must be local".to_string());
        }
        if path_has_parent_component(Path::new(path)) {
            return Err(
                "research run paths must not contain parent-directory traversal".to_string(),
            );
        }
    }
    Ok(())
}

fn load_research_market_data_and_members(
    config: &ResearchRunConfig,
) -> Result<(Vec<MarketDataSnapshot>, Vec<AICommitteeMember>), String> {
    let path = config
        .market_data_path
        .as_ref()
        .ok_or_else(|| "research run requires market_data_path".to_string())?;
    validate_local_json_path(Path::new(path), "research run market_data_path")?;
    let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
    reject_unsafe_offline_batch_text(&text)?;
    let (mut market_data, mut members) =
        if let Ok(input) = serde_json::from_str::<DataRouterInput>(&text) {
            (input.market_data, input.members)
        } else {
            let market_data: Vec<MarketDataSnapshot> =
                serde_json::from_str(&text).map_err(|err| err.to_string())?;
            let scopes = market_data
                .iter()
                .map(|market| market.market_scope)
                .collect();
            (
                market_data,
                create_three_member_pilot_roster_for_scopes(scopes, CoreRuntimeStatus::MockLocal),
            )
        };
    if !config.symbols.is_empty() {
        market_data.retain(|market| config.symbols.contains(&market.symbol));
    }
    if !config.market_scopes.is_empty() {
        market_data.retain(|market| config.market_scopes.contains(&market.market_scope));
        for member in &mut members {
            member
                .market_scopes
                .retain(|scope| config.market_scopes.contains(scope));
        }
    }
    members.retain(|member| !member.market_scopes.is_empty());
    if market_data.is_empty() {
        return Err("research run requires filtered market data".to_string());
    }
    if members.is_empty() {
        let scopes = market_data
            .iter()
            .map(|market| market.market_scope)
            .collect();
        members = create_three_member_pilot_roster_for_scopes(scopes, CoreRuntimeStatus::MockLocal);
    }
    Ok((market_data, members))
}

fn load_research_owner_context(
    config: &ResearchRunConfig,
    policy: &OwnerIntentPolicy,
) -> Result<(Option<String>, usize), String> {
    let text = match (&config.owner_comment_text, &config.owner_comment_path) {
        (Some(text), _) => Some(text.clone()),
        (None, Some(path)) => Some(fs::read_to_string(path).map_err(|err| err.to_string())?),
        (None, None) => None,
    };
    let Some(text) = text else {
        return Ok((None, 0));
    };
    let parsed = parse_owner_natural_input_with_policy(
        OwnerNaturalInput {
            input_id: format!("{}-owner-comment", config.research_run_id),
            text,
            symbol: config.symbols.first().cloned(),
            market_scope: config.market_scopes.first().copied(),
            target_member_id: None,
            target_item_id: None,
            source_label: Some("research-run-config".to_string()),
            created_at: None,
            paper_only: true,
        },
        policy,
    )?;
    Ok((
        Some(format!(
            "owner-natural-input:{:?}: {}",
            parsed.detected_intent, parsed.normalized_text
        )),
        usize::from(parsed.generated_feedback.is_some()),
    ))
}

fn load_research_offline_output_batch(
    config: &ResearchRunConfig,
) -> Result<Option<OfflineMemberOutputBatch>, String> {
    let Some(path) = &config.offline_member_output_batch_path else {
        return Ok(None);
    };
    let load = OfflineMemberOutputBatch::from_json_path(Path::new(path))?;
    Ok(Some(OfflineMemberOutputBatch {
        batch_id: load.batch_id,
        created_at: "loaded-from-research-run-config".to_string(),
        source_label: path.clone(),
        opinions: load.opinions,
    }))
}

fn summarize_research_packets(
    batch: &AIResearchPacketBatch,
    event_count: usize,
) -> ResearchPacketSummary {
    let mut symbols_covered: Vec<String> = batch
        .packets
        .iter()
        .map(|packet| packet.symbol.clone())
        .collect();
    symbols_covered.sort();
    symbols_covered.dedup();
    ResearchPacketSummary {
        symbols_covered,
        news_items_attached: batch.packets.iter().map(|packet| packet.news.len()).sum(),
        owner_context_attached: batch
            .packets
            .iter()
            .any(|packet| packet.owner_context.is_some()),
        members_routed: batch.routed_member_count,
        packets_generated: batch.packet_count,
        events_generated: event_count,
    }
}

fn normalize_owner_natural_text(text: &str) -> Result<String, String> {
    let normalized = text.split_whitespace().collect::<Vec<_>>().join(" ");
    if normalized.is_empty() {
        return Err("owner natural input text is empty".to_string());
    }
    if normalized.chars().count() > 600 {
        return Err("owner natural input text is too long".to_string());
    }
    Ok(normalized)
}

fn owner_feedback_type_for_natural_intent(intent: OwnerNaturalInputIntent) -> OwnerFeedbackType {
    match intent {
        OwnerNaturalInputIntent::Comment => OwnerFeedbackType::Comment,
        OwnerNaturalInputIntent::Disagreement => OwnerFeedbackType::Disagree,
        OwnerNaturalInputIntent::RiskConcern => OwnerFeedbackType::RiskConcern,
        OwnerNaturalInputIntent::EvidenceRequest => OwnerFeedbackType::EvidenceRequest,
        OwnerNaturalInputIntent::WatchlistRequest => OwnerFeedbackType::WatchlistRequest,
        OwnerNaturalInputIntent::PaperOutcomeLabel => OwnerFeedbackType::PaperOutcomeLabel,
        OwnerNaturalInputIntent::ReconsiderationRequest => {
            OwnerFeedbackType::ReconsiderationRequest
        }
        OwnerNaturalInputIntent::Unknown => OwnerFeedbackType::Comment,
    }
}

fn owner_action_type_for_natural_intent(
    intent: OwnerNaturalInputIntent,
) -> OwnerAttentionActionType {
    match intent {
        OwnerNaturalInputIntent::EvidenceRequest => OwnerAttentionActionType::RequestMoreEvidence,
        OwnerNaturalInputIntent::WatchlistRequest => OwnerAttentionActionType::ConvertToWatchlist,
        OwnerNaturalInputIntent::ReconsiderationRequest => {
            OwnerAttentionActionType::RequestReconsideration
        }
        OwnerNaturalInputIntent::PaperOutcomeLabel | OwnerNaturalInputIntent::Unknown => {
            OwnerAttentionActionType::AddComment
        }
        OwnerNaturalInputIntent::Comment
        | OwnerNaturalInputIntent::Disagreement
        | OwnerNaturalInputIntent::RiskConcern => OwnerAttentionActionType::AddComment,
    }
}

fn owner_general_feedback_type(action_type: OwnerAttentionActionType) -> Option<OwnerFeedbackType> {
    match action_type {
        OwnerAttentionActionType::AddComment => Some(OwnerFeedbackType::Comment),
        OwnerAttentionActionType::RequestMoreEvidence => Some(OwnerFeedbackType::EvidenceRequest),
        OwnerAttentionActionType::RequestReconsideration => {
            Some(OwnerFeedbackType::ReconsiderationRequest)
        }
        OwnerAttentionActionType::ConvertToWatchlist => Some(OwnerFeedbackType::WatchlistRequest),
        OwnerAttentionActionType::Acknowledge
        | OwnerAttentionActionType::Defer
        | OwnerAttentionActionType::Dismiss => None,
    }
}

fn owner_feedback_priority_for_natural_intent(
    intent: OwnerNaturalInputIntent,
) -> OwnerFeedbackPriority {
    match intent {
        OwnerNaturalInputIntent::RiskConcern
        | OwnerNaturalInputIntent::EvidenceRequest
        | OwnerNaturalInputIntent::ReconsiderationRequest => OwnerFeedbackPriority::High,
        OwnerNaturalInputIntent::Disagreement | OwnerNaturalInputIntent::WatchlistRequest => {
            OwnerFeedbackPriority::Normal
        }
        OwnerNaturalInputIntent::PaperOutcomeLabel => OwnerFeedbackPriority::Normal,
        OwnerNaturalInputIntent::Comment | OwnerNaturalInputIntent::Unknown => {
            OwnerFeedbackPriority::Low
        }
    }
}

fn validate_news_collection_config(config: &NewsCollectionConfig) -> Result<(), String> {
    if !config.paper_only {
        return Err("news collection config must be paper-only".to_string());
    }
    if config.max_items_per_symbol == 0 {
        return Err("news collection max_items_per_symbol must be greater than zero".to_string());
    }
    if matches!(
        config.source_mode,
        NewsCollectionSourceMode::RssFeed | NewsCollectionSourceMode::HttpHeadline
    ) && !config.allow_network
    {
        return Err("remote news collection requires explicit allow_network".to_string());
    }
    if let Some(path) = &config.local_fixture_path {
        validate_local_json_path(Path::new(path), "news collection local_fixture_path")?;
    }
    for source in &config.sources {
        if !source.paper_only {
            return Err("news source descriptor must be paper-only".to_string());
        }
        if let Some(path) = &source.path {
            validate_local_json_path(Path::new(path), "news source local path")?;
        }
        if matches!(
            source.mode,
            NewsCollectionSourceMode::RssFeed | NewsCollectionSourceMode::HttpHeadline
        ) && !config.allow_network
        {
            return Err("remote news source requires explicit allow_network".to_string());
        }
        if config.allow_network {
            let Some(url) = &source.url else {
                return Err("network news source requires url".to_string());
            };
            let allowed = source
                .allowed_domain
                .as_ref()
                .map(|domain| url_matches_allowed_domain(url, domain))
                .unwrap_or(false)
                || config
                    .allowed_domains
                    .iter()
                    .any(|domain| url_matches_allowed_domain(url, domain));
            if !allowed {
                return Err("network news source requires explicit allowed domain".to_string());
            }
        }
    }
    Ok(())
}

fn validate_news_cache_store(store: &NewsCacheStore) -> Result<(), String> {
    if !store.paper_only {
        return Err("news cache store must be paper-only".to_string());
    }
    if store.cache_store_id.trim().is_empty() {
        return Err("news cache store requires cache_store_id".to_string());
    }
    for entry in &store.entries {
        validate_news_cache_entry(entry)?;
    }
    Ok(())
}

fn validate_news_cache_entry(entry: &NewsCacheEntry) -> Result<(), String> {
    if !entry.paper_only {
        return Err("news cache entry must be paper-only".to_string());
    }
    if entry.cache_id.trim().is_empty()
        || entry.news_id.trim().is_empty()
        || entry.headline.trim().is_empty()
        || entry.summary.trim().is_empty()
        || entry.source_label.trim().is_empty()
        || entry.provider_id.trim().is_empty()
        || entry.fingerprint.trim().is_empty()
    {
        return Err(
            "news cache entry requires ids, headline, summary, source, provider, fingerprint"
                .to_string(),
        );
    }
    reject_full_article_like_summary(&entry.summary)?;
    let text = serde_json::to_string(entry).map_err(|err| err.to_string())?;
    reject_unsafe_news_collection_text(&text)
}

fn validate_news_provider_configs(configs: &[NewsProviderConfig]) -> Result<(), String> {
    let mut ids = std::collections::BTreeSet::new();
    for config in configs {
        validate_news_provider_config(config)?;
        if !ids.insert(config.provider_id.clone()) {
            return Err(format!(
                "duplicate news provider_id: {}",
                config.provider_id
            ));
        }
    }
    Ok(())
}

fn validate_news_provider_config(config: &NewsProviderConfig) -> Result<(), String> {
    validate_news_provider_config_with_optional_policy(config, None)
}

fn validate_news_provider_config_for_policy(
    config: &NewsProviderConfig,
    policy: &SafeNewsFetchPolicy,
) -> Result<(), String> {
    validate_news_provider_config_with_optional_policy(config, Some(policy))
}

fn validate_news_provider_config_with_optional_policy(
    config: &NewsProviderConfig,
    policy: Option<&SafeNewsFetchPolicy>,
) -> Result<(), String> {
    if !config.paper_only {
        return Err("news provider config must be paper-only".to_string());
    }
    if config.provider_id.trim().is_empty() {
        return Err("news provider config requires provider_id".to_string());
    }
    if config.max_items == 0 {
        return Err("news provider max_items must be greater than zero".to_string());
    }
    match config.kind {
        NewsProviderKind::Disabled => Ok(()),
        NewsProviderKind::LocalFixture => {
            let Some(path) = &config.source_path_or_url else {
                return Err("local fixture news provider requires source_path_or_url".to_string());
            };
            validate_local_json_path(Path::new(path), "local fixture news provider path")
        }
        NewsProviderKind::RssFeed | NewsProviderKind::HttpHeadline => {
            if !config.enabled {
                return Ok(());
            }
            let Some(url) = &config.source_path_or_url else {
                return Err("remote news provider requires source_path_or_url".to_string());
            };
            if !url.starts_with("https://") {
                return Err("remote news provider requires https URL".to_string());
            }
            let policy_domains_empty = policy
                .map(|policy| policy.allowed_domains.is_empty())
                .unwrap_or(true);
            if config.allowed_domains.is_empty() && policy_domains_empty {
                return Err("remote news provider requires allowed_domains".to_string());
            }
            if let Some(policy) = policy {
                validate_remote_news_source(url, config, policy)?;
            } else if !config
                .allowed_domains
                .iter()
                .any(|domain| url_matches_allowed_domain(url, domain))
            {
                return Err(
                    "remote news provider URL host is not in exact allowed_domains".to_string(),
                );
            }
            Ok(())
        }
    }
}

fn validate_safe_news_fetch_policy(policy: &SafeNewsFetchPolicy) -> Result<(), String> {
    if !policy.paper_only {
        return Err("safe news fetch policy must be paper-only".to_string());
    }
    if policy.allow_browser_scraping
        || policy.allow_js_execution
        || policy.allow_full_article_body
        || policy.allow_paywall_content
        || policy.allow_login_content
    {
        return Err("safe news fetch policy enables a forbidden collection mode".to_string());
    }
    if policy.max_items_per_source == 0 {
        return Err(
            "safe news fetch policy max_items_per_source must be greater than zero".to_string(),
        );
    }
    if policy.max_summary_chars == 0 {
        return Err(
            "safe news fetch policy max_summary_chars must be greater than zero".to_string(),
        );
    }
    Ok(())
}

fn validate_remote_news_source(
    url: &str,
    config: &NewsProviderConfig,
    policy: &SafeNewsFetchPolicy,
) -> Result<(), String> {
    if !url.starts_with("https://") {
        return Err("remote news provider requires https URL".to_string());
    }
    let host =
        extract_url_host(url).ok_or_else(|| "remote news provider requires host".to_string())?;
    let allowed = config
        .allowed_domains
        .iter()
        .chain(policy.allowed_domains.iter())
        .map(|domain| domain.trim().trim_start_matches('.').to_ascii_lowercase())
        .any(|domain| !domain.is_empty() && host == domain);
    if !allowed {
        return Err("remote news provider URL host is not in exact allowed_domains".to_string());
    }
    Ok(())
}

fn url_matches_allowed_domain(url: &str, domain: &str) -> bool {
    let Some(host) = extract_url_host(url) else {
        return false;
    };
    let domain = domain.trim().trim_start_matches('.').to_ascii_lowercase();
    !domain.is_empty() && host == domain
}

fn extract_url_host(url: &str) -> Option<String> {
    let host_port_path = url.split_once("://").map(|(_, rest)| rest).unwrap_or(url);
    let host = host_port_path
        .split(['/', ':', '?', '#'])
        .next()
        .unwrap_or_default()
        .to_ascii_lowercase();
    if host.is_empty() { None } else { Some(host) }
}

fn normalize_news_provider_config_order(configs: &mut [NewsProviderConfig]) {
    configs.sort_by(|left, right| left.provider_id.cmp(&right.provider_id));
}

fn filter_collected_news_items_for_provider(
    items: Vec<CollectedNewsItem>,
    config: &NewsProviderConfig,
) -> Vec<CollectedNewsItem> {
    items
        .into_iter()
        .filter(|item| {
            config.symbols.is_empty() || config.symbols.iter().any(|symbol| symbol == &item.symbol)
        })
        .filter(|item| {
            config.market_scopes.is_empty()
                || item
                    .market_scope
                    .map(|scope| config.market_scopes.contains(&scope))
                    .unwrap_or(true)
        })
        .take(config.max_items)
        .collect()
}

fn load_collected_news_items_from_local_json(
    path: &Path,
) -> Result<Vec<CollectedNewsItem>, String> {
    validate_local_json_path(path, "collected news fixture path")?;
    let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
    reject_unsafe_news_collection_text(&text)?;
    if let Ok(items) = serde_json::from_str::<Vec<CollectedNewsItem>>(&text) {
        return Ok(items);
    }
    if let Ok(snapshots) = serde_json::from_str::<Vec<NewsSnapshot>>(&text) {
        return Ok(snapshots
            .into_iter()
            .map(|snapshot| CollectedNewsItem {
                symbol: snapshot.symbol,
                market_scope: None,
                headline: snapshot.headline,
                summary: snapshot.summary,
                sentiment_hint: Some(snapshot.sentiment_hint),
                source_label: snapshot.source_label,
                timestamp: snapshot.timestamp,
                url: None,
                license_note: Some("existing local NewsSnapshot fixture".to_string()),
            })
            .collect());
    }
    #[derive(Deserialize)]
    struct LocalNewsItemsFile {
        items: Vec<CollectedNewsItem>,
    }
    serde_json::from_str::<LocalNewsItemsFile>(&text)
        .map(|file| file.items)
        .map_err(|err| err.to_string())
}

fn reject_unsafe_news_collection_text(text: &str) -> Result<(), String> {
    let lower = text.to_ascii_lowercase();
    for prohibited in [
        "broker",
        "account_id",
        "order_id",
        "execution",
        "position_size",
        "live_trade",
        "full_article",
        "article_body",
        "content_html",
        "copyright_full_text",
    ] {
        if lower.contains(prohibited) {
            return Err(format!(
                "news collection rejected unsafe field: {prohibited}"
            ));
        }
    }
    Ok(())
}

fn infer_news_sentiment_hint(headline: &str, summary: &str) -> &'static str {
    let lower = format!("{headline} {summary}").to_ascii_lowercase();
    if lower.contains("beat")
        || lower.contains("growth")
        || lower.contains("upgrade")
        || lower.contains("상승")
        || lower.contains("호조")
    {
        "positive"
    } else if lower.contains("miss")
        || lower.contains("risk")
        || lower.contains("downgrade")
        || lower.contains("하락")
        || lower.contains("부진")
    {
        "negative"
    } else {
        "neutral"
    }
}

fn filter_batch_input_for_autonomous_scope(
    input: &mut BatchCommitteeCycleInput,
    symbols: &[String],
    market_scopes: &[MarketScope],
) {
    if !symbols.is_empty() {
        input
            .market_data
            .retain(|market| symbols.contains(&market.symbol));
        input.news.retain(|news| symbols.contains(&news.symbol));
        if let Some(batch) = &mut input.offline_output_batch {
            batch
                .opinions
                .retain(|opinion| symbols.contains(&opinion.symbol));
        }
    }
    if !market_scopes.is_empty() {
        input
            .market_data
            .retain(|market| market_scopes.contains(&market.market_scope));
        if let Some(batch) = &mut input.offline_output_batch {
            batch
                .opinions
                .retain(|opinion| market_scopes.contains(&opinion.market_scope));
        }
        input.members.retain(|member| {
            member
                .market_scopes
                .iter()
                .any(|scope| market_scopes.contains(scope))
        });
    }
}

pub fn load_owner_feedback_from_local_json(path: &Path) -> Result<Vec<OwnerFeedback>, String> {
    if !local_only(&path.to_string_lossy()) {
        return Err("owner feedback path must be local".to_string());
    }
    let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
    reject_unsafe_owner_feedback_text(&text)?;
    let feedback: Vec<OwnerFeedback> =
        serde_json::from_str(&text).map_err(|err| err.to_string())?;
    for item in &feedback {
        validate_owner_feedback(item)?;
    }
    Ok(feedback)
}

fn validate_owner_feedback(feedback: &OwnerFeedback) -> Result<(), String> {
    if !feedback.paper_only {
        return Err("owner feedback must be paper-only".to_string());
    }
    if feedback.feedback_id.trim().is_empty() {
        return Err("owner feedback requires feedback_id".to_string());
    }
    reject_unsafe_owner_feedback_text(&feedback.text)
}

fn reject_unsafe_owner_feedback_text(text: &str) -> Result<(), String> {
    if let Ok(value) = serde_json::from_str::<serde_json::Value>(text) {
        reject_unsafe_offline_batch_value(&value)?;
        reject_unsafe_owner_feedback_value(&value)
    } else {
        reject_unsafe_owner_feedback_string(text)
    }
}

fn reject_unsafe_owner_feedback_value(value: &serde_json::Value) -> Result<(), String> {
    match value {
        serde_json::Value::Object(map) => {
            for (key, value) in map {
                reject_unsafe_owner_feedback_string(key)?;
                reject_unsafe_owner_feedback_value(value)?;
            }
        }
        serde_json::Value::Array(items) => {
            for item in items {
                reject_unsafe_owner_feedback_value(item)?;
            }
        }
        serde_json::Value::String(text) => reject_unsafe_owner_feedback_string(text)?,
        _ => {}
    }
    Ok(())
}

fn reject_unsafe_owner_feedback_string(text: &str) -> Result<(), String> {
    let lower = text.to_ascii_lowercase();
    for prohibited in [
        "buy now",
        "buy now with real money",
        "place order",
        "execute order",
        "submit order",
        "execute trade",
        "place trade",
        "broker order",
        "order account",
        "account order",
        "real trade",
        "live execution",
        "live trading",
        "real money",
        "broker account",
        "trading account",
        "use my account",
        "from account",
        "guaranteed return",
        "guaranteed returns",
        "guaranteed profit",
        "guaranteed profits",
        "private data",
        "illegal data",
        "inside information",
        "nonpublic",
        "max leverage",
        "maximum leverage",
        "계좌",
        "주문",
        "실거래",
        "레버리지 최대로",
    ] {
        if lower.contains(prohibited) {
            return Err(format!(
                "owner feedback rejected unsafe instruction: {prohibited}"
            ));
        }
    }
    Ok(())
}

impl MemberStateStore {
    pub fn from_members(store_id: &str, members: &[AICommitteeMember], source_label: &str) -> Self {
        Self {
            store_id: store_id.to_string(),
            members: members
                .iter()
                .map(|member| MemberStateSnapshot {
                    member_id: member.member_id.clone(),
                    score: member.score,
                    voice_weight: member.voice_weight,
                    status: member.status,
                    memory_state: member
                        .memory_state
                        .clone()
                        .unwrap_or_else(|| MemberMemoryState::new(&member.member_id)),
                    learning_journal_summary: empty_learning_journal_summary(),
                    last_updated_at: None,
                })
                .collect(),
            source_label: source_label.to_string(),
            paper_only: true,
        }
    }

    pub fn load_from_local_json(path: &Path) -> Result<Self, String> {
        if !local_only(&path.to_string_lossy()) {
            return Err("member state store path must be local".to_string());
        }
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        reject_unsafe_offline_batch_text(&text)?;
        let store: MemberStateStore = serde_json::from_str(&text).map_err(|err| err.to_string())?;
        store.validate()?;
        Ok(store)
    }

    pub fn save_to_local_json(&self, path: &Path) -> Result<(), String> {
        if !local_only(&path.to_string_lossy()) {
            return Err("member state store path must be local".to_string());
        }
        self.validate()?;
        let text = serde_json::to_string_pretty(self).map_err(|err| err.to_string())?;
        fs::write(path, text).map_err(|err| err.to_string())
    }

    pub fn apply_score_updates(&mut self, score_updates: &[MemberScoreUpdate]) {
        for update in score_updates {
            if let Some(state) = self
                .members
                .iter_mut()
                .find(|state| state.member_id == update.member_id)
            {
                let previous_score = state.score;
                let score_delta = update.new_score - update.previous_score;
                let voice_delta = update.new_voice_weight - update.previous_voice_weight;
                state.score = clamp_unit(state.score + score_delta);
                state.voice_weight = clamp_unit(state.voice_weight + voice_delta);
                if previous_score >= 0.3 && state.score < 0.3 {
                    state.status = AICommitteeMemberStatus::Demoted;
                } else if previous_score < 0.8 && state.score >= 0.8 {
                    state.status = AICommitteeMemberStatus::Active;
                }
                state.last_updated_at = Some("offline-batch-cycle".to_string());
            }
        }
    }

    pub fn apply_memory_updates(&mut self, memory_updates: &[MemberMemoryState]) {
        for update in memory_updates {
            if let Some(state) = self
                .members
                .iter_mut()
                .find(|state| state.member_id == update.member_id)
            {
                merge_memory_state(&mut state.memory_state, update);
                state.last_updated_at = Some("offline-batch-cycle".to_string());
            }
        }
    }

    pub fn append_learning_journal_entries(&mut self, entries: &[MemberLearningJournalEntry]) {
        for entry in entries {
            if let Some(state) = self
                .members
                .iter_mut()
                .find(|state| state.member_id == entry.member_id)
            {
                match entry.learning_signal {
                    MemberLearningSignal::Reinforce => {
                        state.learning_journal_summary.reinforce_count += 1;
                    }
                    MemberLearningSignal::Penalize => {
                        state.learning_journal_summary.penalize_count += 1;
                    }
                    MemberLearningSignal::Watch => {
                        state.learning_journal_summary.watch_count += 1;
                    }
                    MemberLearningSignal::Ignore => {
                        state.learning_journal_summary.ignore_count += 1;
                    }
                }
                state.last_updated_at = Some("offline-batch-cycle".to_string());
            }
        }
    }

    pub fn get_member_state(&self, member_id: &str) -> Option<&MemberStateSnapshot> {
        self.members
            .iter()
            .find(|state| state.member_id == member_id)
    }

    fn validate(&self) -> Result<(), String> {
        if !self.paper_only {
            return Err("member state store must be paper-only".to_string());
        }
        if self.store_id.trim().is_empty() {
            return Err("member state store requires store_id".to_string());
        }
        Ok(())
    }
}

fn empty_learning_journal_summary() -> MemberLearningJournalSummary {
    MemberLearningJournalSummary {
        reinforce_count: 0,
        penalize_count: 0,
        watch_count: 0,
        ignore_count: 0,
    }
}

fn merge_memory_state(current: &mut MemberMemoryState, update: &MemberMemoryState) {
    for symbol in &update.recent_symbols {
        if !current.recent_symbols.contains(symbol) {
            current.recent_symbols.push(symbol.clone());
        }
    }
    current.recent_opinion_count += update.recent_opinion_count;
    current.recent_event_count += update.recent_event_count;
    current.recent_good_call_count += update.recent_good_call_count;
    current.recent_bad_call_count += update.recent_bad_call_count;
    current.recent_risk_veto_count += update.recent_risk_veto_count;
    for note in &update.notes {
        if !current.notes.contains(note) {
            current.notes.push(note.clone());
        }
    }
}

fn persist_member_learning_outputs_from_config(
    config: &MinimalAiCommitteeCycleConfig,
    result: &mut BatchCommitteeCycleResult,
) -> Result<(), String> {
    let mut store = if let Some(path) = &config.member_experience_store_input_path {
        MemberExperienceStore::load_from_local_json(Path::new(path))?
    } else {
        MemberExperienceStore::new(format!("{}-experience-store", result.batch_id), Vec::new())
    };
    store.append_records(result.member_experience_records.clone());
    let raw_replay_dataset =
        build_replay_dataset_from_experience_store(&store, &ReplayDatasetFilter::default());
    let sanitized_build = should_build_sanitized_replay_dataset(config).then(|| {
        build_sanitized_replay_dataset_from_experience_store(
            &store,
            SanitizedReplayDatasetBuildConfig {
                source_experience_store_id: store.store_id.clone(),
                strict_temporal_boundary: config.strict_temporal_boundary,
                include_post_decision_context_for_audit: config
                    .include_post_decision_context_for_audit,
                include_prior_memory_buckets: true,
                reject_on_blocking_leakage: config.reject_on_blocking_leakage,
                paper_only: true,
            },
        )
    });
    let mut active_replay_dataset = sanitized_build
        .as_ref()
        .map(|build| build.dataset.clone())
        .unwrap_or_else(|| raw_replay_dataset.clone());

    if config.emit_learning_summary || config.member_experience_store_output_path.is_some() {
        result.calibration_summaries = compute_member_calibration_summaries(&store);
        result.self_review_notes = generate_member_self_review_notes(&store);
        result.self_review_note_count = result.self_review_notes.len();
    }
    if config.emit_replay_dataset_summary
        || config.replay_dataset_output_path.is_some()
        || sanitized_build.is_some()
    {
        result.replay_example_count = active_replay_dataset.example_count;
        result.replay_dataset = active_replay_dataset.clone();
    }
    result.sanitized_replay_build = sanitized_build.clone();
    if config.label_validation_enabled
        || config.validated_replay_dataset_output_path.is_some()
        || config.label_quality_summary_output_path.is_some()
        || config.label_validation_with_evidence_enabled
        || config.paper_outcome_evidence_path.is_some()
        || config.paper_outcome_evidence_quality_output_path.is_some()
        || config.validated_replay_with_evidence_output_path.is_some()
        || config.validated_ratio_expansion_enabled
        || config.validated_ratio_expansion_output_path.is_some()
        || config.evidence_backfill_enabled
        || config.evidence_backfill_output_path.is_some()
        || config.validated_ratio_expansion_enabled
        || config.validated_ratio_expansion_output_path.is_some()
        || config.weak_label_review_enabled
        || config.weak_label_review_decision_path.is_some()
        || config.weak_label_review_output_path.is_some()
        || config.replay_training_inclusion_mask_output_path.is_some()
        || config.weak_label_closure_enabled
        || config.training_candidate_dataset_output_path.is_some()
        || config.training_split_output_path.is_some()
        || config.offline_trainer_dry_run_enabled
        || config.offline_trainer_dry_run_output_path.is_some()
    {
        let label_validation_policy = if let Some(path) = &config.paper_label_validation_policy_path
        {
            load_paper_label_validation_policy_from_local_file(Path::new(path))?
        } else {
            PaperLabelValidationPolicy::default()
        };
        let backtest_label_contract = if let Some(path) = &config.backtest_label_contract_path {
            Some(load_backtest_label_contract_from_local_file(Path::new(
                path,
            ))?)
        } else {
            None
        };
        let build_config = ValidatedReplayDatasetBuildConfig {
            source_sanitized_dataset_id: active_replay_dataset.dataset_id.clone(),
            label_validation_policy: label_validation_policy.clone(),
            backtest_label_contract,
            require_validated_labels_for_training: true,
            allow_ready_with_warnings_for_medium_confidence: true,
            reject_rejected_labels: true,
            paper_only: true,
        };
        let evidence_load = if let Some(path) = &config.paper_outcome_evidence_path {
            Some(load_paper_outcome_evidence_from_local_json(Path::new(
                path,
            ))?)
        } else {
            None
        };
        let evidence_enabled = config.label_validation_with_evidence_enabled
            || config.paper_outcome_evidence_path.is_some()
            || config.paper_outcome_evidence_quality_output_path.is_some()
            || config.validated_replay_with_evidence_output_path.is_some()
            || config.evidence_backfill_enabled
            || config.evidence_backfill_output_path.is_some()
            || config.validated_ratio_expansion_enabled
            || config.validated_ratio_expansion_output_path.is_some()
            || config.weak_label_review_enabled
            || config.weak_label_review_decision_path.is_some()
            || config.weak_label_closure_enabled;
        let validated_build = if evidence_enabled {
            build_validated_replay_dataset_with_paper_evidence(
                &active_replay_dataset,
                evidence_load
                    .as_ref()
                    .map(|load| load.records.as_slice())
                    .unwrap_or(&[]),
                &label_validation_policy,
                build_config,
            )
        } else {
            build_validated_replay_dataset(&active_replay_dataset, &[], build_config)
        };
        let label_quality_summary = summarize_label_quality(&validated_build);
        let evidence_quality_summary = evidence_load.as_ref().and_then(|load| {
            validated_build
                .paper_evidence_matching_result
                .as_ref()
                .map(|matching| {
                    summarize_paper_outcome_evidence_quality(
                        load,
                        matching,
                        &validated_build.paper_evidence_promotion_results,
                    )
                })
        });
        if config.evidence_backfill_enabled || config.evidence_backfill_output_path.is_some() {
            let evidence_input_path =
                config.paper_outcome_evidence_path.as_ref().ok_or_else(|| {
                    "evidence_backfill_enabled requires paper_outcome_evidence_path".to_string()
                })?;
            result.evidence_backfill_and_promotion_run =
                Some(run_evidence_backfill_and_promotion_with_inputs(
                    &EvidenceBackfillAndPromotionRunConfig {
                        evidence_input_path: evidence_input_path.clone(),
                        evidence_backfill_output_path: config.evidence_backfill_output_path.clone(),
                        sanitized_dataset_path: None,
                        experience_store_path: None,
                        validated_replay_output_path: config
                            .validated_replay_with_evidence_output_path
                            .clone(),
                        label_quality_output_path: config.label_quality_summary_output_path.clone(),
                        min_validated_label_ratio_required: config
                            .evidence_backfill_min_validated_ratio,
                        dry_run: config.evidence_backfill_dry_run,
                        apply_backfill_patch: config.evidence_backfill_apply_patch,
                        rebuild_validated_dataset: true,
                        paper_only: true,
                    },
                    &active_replay_dataset,
                    &store,
                    &label_validation_policy,
                )?);
        }
        let mut final_validated_build = validated_build.clone();
        let mut final_label_quality_summary = label_quality_summary.clone();
        if config.validated_ratio_expansion_enabled
            || config.validated_ratio_expansion_output_path.is_some()
        {
            let paper_price_series_path =
                config.paper_price_series_path.as_ref().ok_or_else(|| {
                    "validated_ratio_expansion_enabled requires paper_price_series_path".to_string()
                })?;
            let price_series_store =
                load_price_series_store_from_local_json(Path::new(paper_price_series_path))?;
            let expansion_run = run_validated_ratio_expansion_with_inputs(
                &ValidatedRatioExpansionRunConfig {
                    run_id: format!("{}-validated-ratio-expansion", result.batch_id),
                    target_validated_label_ratio: config.validated_ratio_target,
                    sanitized_dataset_path: None,
                    experience_store_path: None,
                    existing_evidence_path: None,
                    price_series_path: Some(paper_price_series_path.clone()),
                    generated_evidence_output_path: config
                        .generated_paper_evidence_output_path
                        .clone(),
                    validated_replay_output_path: config
                        .validated_replay_with_evidence_output_path
                        .clone()
                        .or(config.validated_replay_dataset_output_path.clone()),
                    label_quality_output_path: config.label_quality_summary_output_path.clone(),
                    readiness_output_path: None,
                    dry_run: config.validated_ratio_expansion_dry_run,
                    paper_only: true,
                },
                &active_replay_dataset,
                &store,
                evidence_load
                    .as_ref()
                    .map(|load| load.records.as_slice())
                    .unwrap_or(&[]),
                &price_series_store,
                &label_validation_policy,
            )?;
            if !config.validated_ratio_expansion_dry_run {
                if let Some(path) = &config.validated_ratio_expansion_output_path {
                    write_safe_json(Path::new(path), &expansion_run)?;
                }
            }
            final_validated_build = expansion_run.validated_build_result.clone();
            final_label_quality_summary = expansion_run.label_quality_summary.clone();
            result.validated_ratio_expansion_run = Some(expansion_run);
        }
        if config.weak_label_review_enabled
            || config.weak_label_review_decision_path.is_some()
            || config.weak_label_review_output_path.is_some()
            || config.replay_training_inclusion_mask_output_path.is_some()
        {
            let (weak_label_review_result, inclusion_mask) =
                apply_weak_label_review_decisions_with_inputs(
                    &WeakLabelReviewApplyConfig {
                        validated_dataset_path: None,
                        review_decision_path: config.weak_label_review_decision_path.clone(),
                        evidence_path: config.paper_outcome_evidence_path.clone(),
                        output_validated_dataset_path: config
                            .validated_replay_with_evidence_output_path
                            .clone()
                            .or(config.validated_replay_dataset_output_path.clone()),
                        output_label_quality_path: config.label_quality_summary_output_path.clone(),
                        output_readiness_path: config.replay_quality_eval_output_path.clone(),
                        min_validated_label_ratio_required: config
                            .min_validated_label_ratio_required,
                        dry_run: config.weak_label_review_dry_run,
                        paper_only: true,
                    },
                    &final_validated_build.dataset,
                    &store,
                    evidence_load
                        .as_ref()
                        .map(|load| load.records.as_slice())
                        .unwrap_or(&[]),
                    config.min_replay_examples_required,
                    config.min_examples_per_member_required,
                    config.exclude_weak_labels_from_training_design,
                    config.weak_label_review_output_path.as_ref(),
                    config.replay_training_inclusion_mask_output_path.as_ref(),
                )?;
            final_validated_build = rebuild_validated_replay_build_from_dataset(
                &weak_label_review_result.updated_validated_dataset,
            );
            final_label_quality_summary = weak_label_review_result.label_quality_summary.clone();
            result.weak_label_review_apply_result = Some(weak_label_review_result);
            result.replay_training_inclusion_mask = Some(inclusion_mask);
        }
        let training_contract_requested = config.training_candidate_dataset_output_path.is_some()
            || config.training_split_output_path.is_some()
            || config.offline_trainer_dry_run_enabled
            || config.offline_trainer_dry_run_output_path.is_some();
        if config.weak_label_closure_enabled || training_contract_requested {
            let price_series_store = if let Some(path) = &config.paper_price_series_path {
                Some(load_price_series_store_from_local_json(Path::new(path))?)
            } else {
                None
            };
            let closure_evidence_records = evidence_load
                .as_ref()
                .map(closure_evidence_records_from_load)
                .unwrap_or_default();
            let closure_result = if config.weak_label_closure_enabled {
                Some(apply_weak_label_closure_plan_with_inputs(
                    &WeakLabelClosureApplyConfig {
                        validated_dataset_path: None,
                        evidence_path: config.paper_outcome_evidence_path.clone(),
                        price_series_path: config.paper_price_series_path.clone(),
                        owner_review_decision_path: config.weak_label_review_decision_path.clone(),
                        output_validated_dataset_path: config
                            .validated_replay_with_evidence_output_path
                            .clone()
                            .or(config.validated_replay_dataset_output_path.clone()),
                        output_closure_result_path: None,
                        dry_run: config.weak_label_closure_dry_run,
                        paper_only: true,
                    },
                    &final_validated_build.dataset,
                    &closure_evidence_records,
                    price_series_store.as_ref(),
                )?)
            } else {
                None
            };
            if let Some(closure_result) = closure_result {
                if !config.weak_label_closure_dry_run {
                    final_validated_build = rebuild_validated_replay_build_from_dataset(
                        &closure_result.updated_validated_dataset,
                    );
                    final_label_quality_summary = summarize_label_quality(&final_validated_build);
                    result.replay_training_inclusion_mask =
                        Some(closure_result.updated_training_inclusion_mask.clone());
                }
                result.weak_label_closure_apply_result = Some(closure_result);
            }
            let current_inclusion_mask = result
                .replay_training_inclusion_mask
                .clone()
                .unwrap_or_else(|| {
                    build_replay_training_inclusion_mask(
                        &final_validated_build.dataset,
                        &ReplayTrainingInclusionPolicy::default(),
                    )
                });
            if result.replay_training_inclusion_mask.is_none() && training_contract_requested {
                result.replay_training_inclusion_mask = Some(current_inclusion_mask.clone());
            }
            if training_contract_requested {
                let candidate_dataset = build_training_candidate_dataset(
                    &final_validated_build.dataset,
                    &current_inclusion_mask,
                    &TrainingCandidateBuildConfig::default(),
                );
                if let Some(path) = &config.training_candidate_dataset_output_path {
                    write_safe_json(Path::new(path), &candidate_dataset)?;
                }
                let split_result = build_training_split(
                    &candidate_dataset,
                    &TrainingSplitConfig {
                        train_ratio: 0.7,
                        validation_ratio: 0.15,
                        test_ratio: 0.15,
                        split_seed: format!("{}-training-split", result.batch_id),
                        stratify_by: TrainingSplitStratifyBy::Member,
                        paper_only: true,
                    },
                );
                if let Some(path) = &config.training_split_output_path {
                    write_safe_json(Path::new(path), &split_result)?;
                }
                let dry_run_result = if config.offline_trainer_dry_run_enabled
                    || config.offline_trainer_dry_run_output_path.is_some()
                {
                    let spec =
                        build_offline_trainer_dry_run_spec(&candidate_dataset, &split_result);
                    let dry_run_result = run_offline_trainer_data_loader_dry_run(
                        &candidate_dataset,
                        &split_result,
                        &spec,
                    );
                    if let Some(path) = &config.offline_trainer_dry_run_output_path {
                        write_safe_json(Path::new(path), &dry_run_result)?;
                    }
                    Some(dry_run_result)
                } else {
                    None
                };
                result.training_candidate_dataset = Some(candidate_dataset);
                result.training_split_result = Some(split_result);
                result.offline_trainer_data_loader_dry_run_result = dry_run_result;
            }
        }
        active_replay_dataset = final_validated_build.dataset.clone();
        result.replay_example_count = active_replay_dataset.example_count;
        result.replay_dataset = active_replay_dataset.clone();
        if !(config.validated_ratio_expansion_enabled && config.validated_ratio_expansion_dry_run)
            && !((config.weak_label_review_enabled
                || config.weak_label_review_decision_path.is_some()
                || config.weak_label_review_output_path.is_some()
                || config.replay_training_inclusion_mask_output_path.is_some())
                && config.weak_label_review_dry_run)
            && !((config.weak_label_closure_enabled) && config.weak_label_closure_dry_run)
        {
            if let Some(path) = config
                .validated_replay_with_evidence_output_path
                .as_ref()
                .or(config.validated_replay_dataset_output_path.as_ref())
            {
                active_replay_dataset.save_to_local_json(Path::new(path))?;
            }
        }
        if !(config.validated_ratio_expansion_enabled && config.validated_ratio_expansion_dry_run)
            && !((config.weak_label_review_enabled
                || config.weak_label_review_decision_path.is_some()
                || config.weak_label_review_output_path.is_some()
                || config.replay_training_inclusion_mask_output_path.is_some())
                && config.weak_label_review_dry_run)
            && !((config.weak_label_closure_enabled) && config.weak_label_closure_dry_run)
        {
            if let Some(path) = &config.label_quality_summary_output_path {
                final_label_quality_summary.save_to_local_json(Path::new(path))?;
            }
        }
        if let (Some(summary), Some(path)) = (
            evidence_quality_summary.as_ref(),
            config.paper_outcome_evidence_quality_output_path.as_ref(),
        ) {
            summary.save_to_local_json(Path::new(path))?;
        }
        result.paper_outcome_evidence_load = evidence_load;
        result.paper_outcome_evidence_matching =
            final_validated_build.paper_evidence_matching_result.clone();
        result.paper_outcome_evidence_quality_summary = evidence_quality_summary;
        result.validated_replay_build = Some(final_validated_build);
        result.label_quality_summary = Some(final_label_quality_summary);
    }
    if config.replay_quality_eval_enabled
        || config.replay_quality_eval_output_path.is_some()
        || config.weak_label_closure_enabled
        || config.training_candidate_dataset_output_path.is_some()
        || config.training_split_output_path.is_some()
        || config.offline_trainer_dry_run_enabled
        || config.offline_trainer_dry_run_output_path.is_some()
    {
        let mut replay_quality_eval = run_replay_quality_evaluation_with_label_ratio_threshold(
            &store,
            &active_replay_dataset,
            config.min_replay_examples_required,
            config.min_examples_per_member_required,
            config.min_validated_label_ratio_required,
        );
        if let Some(build) = result.validated_replay_build.as_ref() {
            let gate = &mut replay_quality_eval.offline_training_readiness_gate;
            gate.validated_label_ratio_after_evidence = gate.validated_label_ratio;
            gate.promoted_by_paper_evidence_count = build.promoted_count;
            gate.unmatched_evidence_count = build.unmatched_evidence_count;
            gate.ambiguous_evidence_count = build.ambiguous_match_count;
            gate.rejected_evidence_count = build.rejected_count;
        }
        if let Some(apply_result) = result.weak_label_review_apply_result.as_ref() {
            replay_quality_eval.offline_training_readiness_gate =
                apply_result.readiness_gate.clone();
        }
        if let (Some(candidate_dataset), Some(split_result)) = (
            result.training_candidate_dataset.as_ref(),
            result.training_split_result.as_ref(),
        ) {
            let dry_run_result = result
                .offline_trainer_data_loader_dry_run_result
                .clone()
                .unwrap_or_else(|| {
                    run_offline_trainer_data_loader_dry_run(
                        candidate_dataset,
                        split_result,
                        &build_offline_trainer_dry_run_spec(candidate_dataset, split_result),
                    )
                });
            let mut design_gate = evaluate_offline_training_design_gate(
                candidate_dataset,
                split_result,
                &dry_run_result,
                &replay_quality_eval,
            );
            if let Some(min_examples) = config.training_candidate_min_examples {
                if candidate_dataset.example_count < min_examples
                    && !matches!(
                        design_gate.design_status,
                        OfflineTrainingDesignGateStatus::BlockedBySafety
                    )
                {
                    design_gate.design_status =
                        OfflineTrainingDesignGateStatus::NeedsMoreValidatedLabels;
                    design_gate.warnings.push(format!(
                        "candidate dataset below configured minimum: {} < {}",
                        candidate_dataset.example_count, min_examples
                    ));
                }
            }
            let readiness_gate = &mut replay_quality_eval.offline_training_readiness_gate;
            readiness_gate.training_included_example_count = candidate_dataset.example_count;
            readiness_gate.weak_labels_remaining = build_weak_replay_label_inventory(
                &active_replay_dataset,
                result.paper_outcome_evidence_quality_summary.as_ref(),
            )
            .weak_label_count;
            readiness_gate.offline_training_design_status = match design_gate.design_status {
                OfflineTrainingDesignGateStatus::ReadyForOfflineTrainerDryRun => {
                    OfflineTrainingDesignStatus::ReadyForDesign
                }
                OfflineTrainingDesignGateStatus::ReadyWithWarnings => {
                    OfflineTrainingDesignStatus::ReadyWithWarnings
                }
                OfflineTrainingDesignGateStatus::NeedsMoreValidatedLabels
                | OfflineTrainingDesignGateStatus::NeedsMoreCoverage => {
                    OfflineTrainingDesignStatus::NeedsMoreValidatedCoverage
                }
                OfflineTrainingDesignGateStatus::BlockedBySafety => {
                    OfflineTrainingDesignStatus::BlockedBySafety
                }
            };
            readiness_gate.ready_for_offline_training = matches!(
                design_gate.design_status,
                OfflineTrainingDesignGateStatus::ReadyForOfflineTrainerDryRun
                    | OfflineTrainingDesignGateStatus::ReadyWithWarnings
            );
            for blocker in &design_gate.blockers {
                if !readiness_gate.blockers.contains(blocker) {
                    readiness_gate.blockers.push(blocker.clone());
                }
            }
            result.offline_training_design_gate = Some(design_gate);
        }
        if let Some(path) = &config.replay_quality_eval_output_path {
            replay_quality_eval.save_to_local_json(Path::new(path))?;
        }
        result.replay_quality_eval = Some(replay_quality_eval);
    }
    if config.replay_coverage_eval_enabled
        || config
            .replay_coverage_collection_queue_output_path
            .is_some()
        || config.paper_scenario_collection_enabled
        || config.scenario_run_output_path.is_some()
        || config.label_validation_enabled
        || config.validated_replay_dataset_output_path.is_some()
        || config.label_quality_summary_output_path.is_some()
    {
        let coverage_eval = evaluate_replay_coverage_targets(
            &active_replay_dataset,
            ReplayCoverageTargetConfig {
                min_examples_total: config.replay_coverage_target_min_total,
                min_total_examples: config.replay_coverage_target_min_total,
                min_examples_per_member: config.min_examples_per_member_required,
                min_examples_per_market_scope: 1,
                min_examples_per_event_type: 1,
                require_non_weak_label_source: true,
                allowed_weak_label_ratio: 0.25,
                paper_only: true,
                ..ReplayCoverageTargetConfig::default()
            },
        );
        let queue = build_collection_queue_from_gaps(
            format!("{}-paper-scenario-collection-queue", result.batch_id),
            &active_replay_dataset,
            &coverage_eval.gaps,
        );
        if let Some(path) = &config.replay_coverage_collection_queue_output_path {
            queue.save_to_local_json(Path::new(path))?;
        }
        if config.paper_scenario_collection_enabled || config.scenario_run_output_path.is_some() {
            let scenario_result = run_paper_scenario_collection(PaperScenarioRunConfig {
                scenario_run_id: format!("{}-paper-scenario-run", result.batch_id),
                collection_items: queue.items.clone(),
                collection_queue: queue.clone(),
                market_data_path: config.local_market_data_path.clone(),
                news_path: config.local_news_path.clone(),
                news_cache_path: None,
                offline_member_output_batch_path: config.offline_member_output_batch_path.clone(),
                member_state_input_path: config.member_state_input_path.clone(),
                paper_outcome_fixture_path: config.paper_outcome_fixture_path.clone(),
                max_items: None,
                sanitize_after_run: true,
                outcome_fixtures: Vec::new(),
                paper_only: true,
            })?;
            if let Some(path) = &config.scenario_run_output_path {
                scenario_result.save_to_local_json(Path::new(path))?;
            }
            result.paper_scenario_run_result = Some(scenario_result);
        }
        result.paper_scenario_collection_queue = Some(queue);
        result.replay_coverage_eval = Some(coverage_eval);
    }
    let self_growing_replay_dataset = active_replay_dataset.clone();
    let self_growing_coverage_eval = result.replay_coverage_eval.clone();
    let smartcore_mismatch_research_tasks = result
        .smartcore_mismatch_self_growing_run_result
        .as_ref()
        .map(|run| run.research_task_generation_result.generated_tasks.clone());
    maybe_run_self_growing_replay_for_batch_result(
        format!("{}-self-growing-replay", result.batch_id),
        config.self_growing_replay_enabled,
        config.research_source_registry_path.as_ref(),
        config.self_growing_max_tasks,
        config.self_growing_max_evidence_records,
        config.self_growing_allow_network_sources,
        config.research_evidence_output_path.as_ref(),
        config.self_growing_replay_output_path.as_ref(),
        config.emit_research_task_summary,
        &store,
        &self_growing_replay_dataset,
        self_growing_coverage_eval.as_ref(),
        None,
        smartcore_mismatch_research_tasks.as_ref(),
        config.min_validated_label_ratio_required,
        result,
    )?;
    maybe_run_self_growing_promotion_for_batch_result(
        format!("{}-self-growing-promotion", result.batch_id),
        config.self_growing_evidence_staging_enabled,
        config.self_growing_evidence_promotion_enabled,
        config.self_growing_evidence_promotion_dry_run,
        config.self_growing_evidence_apply_promotions,
        config.self_growing_refresh_training_candidates,
        config.self_growing_staging_store_path.as_ref(),
        config.self_growing_approved_evidence_output_path.as_ref(),
        config.self_growing_training_candidate_output_path.as_ref(),
        config
            .validated_replay_with_evidence_output_path
            .as_ref()
            .or(config.validated_replay_dataset_output_path.as_ref()),
        &self_growing_replay_dataset,
        &store,
        result,
    )?;
    maybe_run_enriched_evidence_promotion_for_batch_result(
        format!("{}-enriched-evidence-promotion", result.batch_id),
        config.enriched_evidence_promotion_enabled,
        config.enriched_evidence_promotion_dry_run,
        config.enriched_evidence_apply_patch,
        config.enriched_evidence_apply_promotions,
        config.enriched_evidence_refresh_training_candidates,
        config.paper_price_series_path.as_ref(),
        config.enriched_staging_output_path.as_ref(),
        config.enriched_approved_evidence_output_path.as_ref(),
        config.enriched_training_candidate_output_path.as_ref(),
        config
            .validated_replay_with_evidence_output_path
            .as_ref()
            .or(config.validated_replay_dataset_output_path.as_ref()),
        &self_growing_replay_dataset,
        &store,
        result,
    )?;
    maybe_run_auto_approval_end_to_end_for_batch_result(
        format!("{}-auto-approval-e2e", result.batch_id),
        config.auto_approval_e2e_enabled,
        config.auto_approval_e2e_dry_run,
        config.auto_approval_apply_promotions,
        config.auto_approval_refresh_training_candidates,
        config.auto_approval_success_staging_path.as_ref(),
        config.auto_approval_success_price_series_path.as_ref(),
        config.auto_approval_approved_evidence_output_path.as_ref(),
        config.auto_approval_training_candidate_output_path.as_ref(),
        &self_growing_replay_dataset,
        &store,
        result,
    )?;
    active_replay_dataset = result.replay_dataset.clone();
    if let (Some(path), Some(replay_quality_eval)) = (
        config.replay_quality_eval_output_path.as_ref(),
        result.replay_quality_eval.as_ref(),
    ) {
        replay_quality_eval.save_to_local_json(Path::new(path))?;
    }
    if let Some(path) = &config.member_experience_store_output_path {
        store.save_to_local_json(Path::new(path))?;
    }
    if let Some(path) = &config.replay_dataset_output_path {
        active_replay_dataset.save_to_local_json(Path::new(path))?;
    }
    if let Some(path) = &config.sanitized_replay_dataset_output_path {
        active_replay_dataset.save_to_local_json(Path::new(path))?;
    }
    Ok(())
}

