fn apply_style_influence_to_opinion(
    mut opinion: MemberOpinion,
    profile: &StyleInfluencedMemberProfile,
) -> MemberOpinion {
    let blend_weight = profile
        .style_blend
        .archetype_weights
        .iter()
        .map(|weight| weight.weight)
        .sum::<f64>()
        .min(1.0);
    match profile.base_role {
        IndependentMemberRole::TrendEntry
            if matches!(opinion.stance, MemberStance::BuyProposal) =>
        {
            opinion.confidence = clamp_unit(opinion.confidence + 0.02 * blend_weight);
            opinion.evidence_notes.push(
                "style influence: trend/momentum archetype cards lightly support entry proposal"
                    .to_string(),
            );
        }
        IndependentMemberRole::RiskGuard
            if matches!(
                opinion.stance,
                MemberStance::NoTrade | MemberStance::NeedMoreEvidence
            ) =>
        {
            opinion.confidence = clamp_unit(opinion.confidence + 0.02 * blend_weight);
            opinion.risk_hint = clamp_unit(opinion.risk_hint + 0.02 * blend_weight);
            opinion.evidence_notes.push(
                "style influence: risk/volatility archetype cards strengthen defensive view"
                    .to_string(),
            );
        }
        IndependentMemberRole::EvidenceRegime => {
            if matches!(
                opinion.stance,
                MemberStance::Hold | MemberStance::NeedMoreEvidence
            ) {
                opinion.confidence = clamp_unit(opinion.confidence + 0.01 * blend_weight);
            }
            opinion.evidence_notes.push(
                "style influence: evidence-quality archetype cards affect evidence threshold only"
                    .to_string(),
            );
        }
        _ => {}
    }
    opinion
        .evidence_notes
        .push("archetype style card influence only; not a real investor clone".to_string());
    opinion
}

fn deferred_core_opinion(packet: &MemberInputPacket, reason: &str) -> MemberOpinion {
    MemberOpinion {
        member_id: packet.member_id.clone(),
        symbol: packet.market_data.symbol.clone(),
        market_scope: packet.market_data.market_scope,
        stance: MemberStance::NeedMoreEvidence,
        confidence: 0.5,
        expected_return_hint: 0.0,
        risk_hint: clamp_unit(packet.market_data.volatility_hint),
        evidence_notes: vec![
            format!("Mamba3 + Gated DeltaNet core {}", reason),
            "NeedMoreEvidence only; no fake AI inference, training, or order".to_string(),
        ],
        event_triggered: false,
        event_reason: Some(reason.to_string()),
    }
}

fn outcome_from_return(simulated_outcome_return: Option<f64>) -> SimulatedPaperOutcome {
    match simulated_outcome_return {
        Some(value) if value > 0.0 => SimulatedPaperOutcome::Positive,
        Some(value) if value < 0.0 => SimulatedPaperOutcome::Negative,
        Some(_) => SimulatedPaperOutcome::Neutral,
        None => SimulatedPaperOutcome::Unknown,
    }
}

pub fn apply_paper_outcome_feedback(
    members: &[AICommitteeMember],
    member_opinions: &[MemberOpinion],
    chairman_decision: Option<&ChairmanDecision>,
    paper_outcome_feedback: &PaperOutcomeFeedback,
) -> PaperOutcomeFeedbackResult {
    let score_updates: Vec<MemberScoreUpdate> = members
        .iter()
        .filter_map(|member| {
            let opinion = member_opinions
                .iter()
                .find(|opinion| opinion.member_id == member.member_id)?;
            Some(score_update_for(
                member,
                opinion,
                chairman_decision,
                outcome_return_for_feedback(paper_outcome_feedback.simulated_result),
            ))
        })
        .collect();

    let mut learning_journal_entries = Vec::new();
    let mut updated_memory_states = Vec::new();
    for member in members {
        let Some(opinion) = member_opinions
            .iter()
            .find(|opinion| opinion.member_id == member.member_id)
        else {
            continue;
        };
        let update_reason = score_updates
            .iter()
            .find(|update| update.member_id == member.member_id)
            .map(|update| update.update_reason)
            .unwrap_or(MemberScoreUpdateReason::Neutral);
        let learning_signal =
            learning_signal_for(update_reason, paper_outcome_feedback.simulated_result);
        let decision_id = chairman_decision
            .map(|decision| decision.decision_id.clone())
            .unwrap_or_else(|| paper_outcome_feedback.decision_id.clone());
        learning_journal_entries.push(MemberLearningJournalEntry {
            journal_id: format!(
                "journal-{}-{}-{}",
                member.member_id, paper_outcome_feedback.symbol, decision_id
            ),
            member_id: member.member_id.clone(),
            symbol: paper_outcome_feedback.symbol.clone(),
            market_scope: paper_outcome_feedback.market_scope,
            opinion_stance: opinion.stance,
            confidence: opinion.confidence,
            chairman_action: chairman_decision.map(|decision| decision.final_action),
            risk_governor_status: chairman_decision.map(|decision| decision.risk_governor_status),
            simulated_outcome: paper_outcome_feedback.simulated_result,
            learning_signal,
            note: "offline learning journal only; no model training or weight mutation".to_string(),
        });

        let mut memory_state = member
            .memory_state
            .clone()
            .unwrap_or_else(|| MemberMemoryState::new(&member.member_id));
        if !memory_state
            .recent_symbols
            .contains(&paper_outcome_feedback.symbol)
        {
            memory_state
                .recent_symbols
                .push(paper_outcome_feedback.symbol.clone());
        }
        memory_state.recent_opinion_count += 1;
        if opinion.event_triggered {
            memory_state.recent_event_count += 1;
        }
        match update_reason {
            MemberScoreUpdateReason::GoodCall | MemberScoreUpdateReason::HelpfulDissent => {
                memory_state.recent_good_call_count += 1;
            }
            MemberScoreUpdateReason::BadCall
            | MemberScoreUpdateReason::RiskyCall
            | MemberScoreUpdateReason::LowEvidence => {
                memory_state.recent_bad_call_count += 1;
            }
            MemberScoreUpdateReason::Neutral => {}
        }
        if chairman_decision
            .is_some_and(|decision| decision.risk_governor_status == RiskGovernorStatus::Vetoed)
        {
            memory_state.recent_risk_veto_count += 1;
        }
        memory_state
            .notes
            .push(format!("last_learning_signal={:?}", learning_signal));
        updated_memory_states.push(memory_state);
    }

    PaperOutcomeFeedbackResult {
        score_updates,
        learning_journal_entries,
        updated_memory_states,
    }
}

fn outcome_return_for_feedback(outcome: SimulatedPaperOutcome) -> Option<f64> {
    match outcome {
        SimulatedPaperOutcome::Positive => Some(0.01),
        SimulatedPaperOutcome::Negative => Some(-0.01),
        SimulatedPaperOutcome::Neutral => Some(0.0),
        SimulatedPaperOutcome::Unknown => None,
    }
}

fn learning_signal_for(
    update_reason: MemberScoreUpdateReason,
    outcome: SimulatedPaperOutcome,
) -> MemberLearningSignal {
    match update_reason {
        MemberScoreUpdateReason::GoodCall | MemberScoreUpdateReason::HelpfulDissent => {
            MemberLearningSignal::Reinforce
        }
        MemberScoreUpdateReason::BadCall
        | MemberScoreUpdateReason::RiskyCall
        | MemberScoreUpdateReason::LowEvidence => MemberLearningSignal::Penalize,
        MemberScoreUpdateReason::Neutral if matches!(outcome, SimulatedPaperOutcome::Unknown) => {
            MemberLearningSignal::Ignore
        }
        MemberScoreUpdateReason::Neutral => MemberLearningSignal::Watch,
    }
}

fn build_learning_journals(entries: &[MemberLearningJournalEntry]) -> Vec<MemberLearningJournal> {
    let mut member_ids: Vec<String> = entries
        .iter()
        .map(|entry| entry.member_id.clone())
        .collect();
    member_ids.sort();
    member_ids.dedup();
    member_ids
        .into_iter()
        .map(|member_id| {
            let entries: Vec<MemberLearningJournalEntry> = entries
                .iter()
                .filter(|entry| entry.member_id == member_id)
                .cloned()
                .collect();
            let summary = MemberLearningJournalSummary {
                reinforce_count: entries
                    .iter()
                    .filter(|entry| {
                        matches!(entry.learning_signal, MemberLearningSignal::Reinforce)
                    })
                    .count(),
                penalize_count: entries
                    .iter()
                    .filter(|entry| matches!(entry.learning_signal, MemberLearningSignal::Penalize))
                    .count(),
                watch_count: entries
                    .iter()
                    .filter(|entry| matches!(entry.learning_signal, MemberLearningSignal::Watch))
                    .count(),
                ignore_count: entries
                    .iter()
                    .filter(|entry| matches!(entry.learning_signal, MemberLearningSignal::Ignore))
                    .count(),
            };
            MemberLearningJournal {
                member_id,
                entries,
                summary,
            }
        })
        .collect()
}

impl MemberExperienceStore {
    pub fn new(store_id: impl Into<String>, records: Vec<MemberExperienceRecord>) -> Self {
        let mut records = records;
        records.sort_by(|left, right| {
            left.member_id
                .cmp(&right.member_id)
                .then(left.symbol.cmp(&right.symbol))
                .then(left.experience_id.cmp(&right.experience_id))
        });
        let mut member_ids: Vec<String> = records
            .iter()
            .map(|record| record.member_id.clone())
            .collect();
        member_ids.sort();
        member_ids.dedup();
        Self {
            store_id: store_id.into(),
            record_count: records.len(),
            member_count: member_ids.len(),
            records,
            paper_only: true,
        }
    }

    pub fn load_from_local_json(path: &Path) -> Result<Self, String> {
        validate_member_experience_path(path, "member experience store input path")?;
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        let store: Self = serde_json::from_str(&text).map_err(|err| err.to_string())?;
        if !store.paper_only {
            return Err("member experience store must be paper-only".to_string());
        }
        if store.records.iter().any(|record| !record.paper_only) {
            return Err("member experience records must be paper-only".to_string());
        }
        Ok(Self::new(store.store_id, store.records))
    }

    pub fn save_to_local_json(&self, path: &Path) -> Result<(), String> {
        validate_member_experience_path(path, "member experience store output path")?;
        if let Some(parent) = path.parent() {
            if !parent.as_os_str().is_empty() {
                fs::create_dir_all(parent).map_err(|err| err.to_string())?;
            }
        }
        let text = serde_json::to_string_pretty(self).map_err(|err| err.to_string())?;
        fs::write(path, text).map_err(|err| err.to_string())
    }

    pub fn append_records(&mut self, records: Vec<MemberExperienceRecord>) {
        self.records.extend(records);
        let refreshed = Self::new(self.store_id.clone(), self.records.clone());
        self.records = refreshed.records;
        self.record_count = refreshed.record_count;
        self.member_count = refreshed.member_count;
        self.paper_only = true;
    }

    pub fn records_by_member(&self, member_id: &str) -> Vec<MemberExperienceRecord> {
        self.records
            .iter()
            .filter(|record| record.member_id == member_id)
            .cloned()
            .collect()
    }

    pub fn records_by_symbol(&self, symbol: &str) -> Vec<MemberExperienceRecord> {
        self.records
            .iter()
            .filter(|record| record.symbol == symbol)
            .cloned()
            .collect()
    }

    pub fn recent_records(&self, member_id: &str, limit: usize) -> Vec<MemberExperienceRecord> {
        let mut records = self.records_by_member(member_id);
        records.sort_by(|left, right| right.experience_id.cmp(&left.experience_id));
        records.truncate(limit);
        records
    }

    pub fn summarize_member_learning(&self, member_id: &str) -> Option<MemberCalibrationSummary> {
        let records = self.records_by_member(member_id);
        if records.is_empty() {
            None
        } else {
            Some(compute_member_calibration_summary(&records))
        }
    }

    pub fn export_replay_examples(&self, filter: &ReplayDatasetFilter) -> Vec<ReplayExample> {
        build_replay_dataset_from_experience_store(self, filter).examples
    }
}

impl ReplayDataset {
    pub fn load_from_local_json(path: &Path) -> Result<Self, String> {
        validate_member_experience_path(path, "replay dataset input path")?;
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        let dataset: Self = serde_json::from_str(&text).map_err(|err| err.to_string())?;
        if !dataset.paper_only {
            return Err("replay dataset must be paper-only".to_string());
        }
        if dataset.examples.iter().any(|example| !example.paper_only) {
            return Err("replay examples must be paper-only".to_string());
        }
        Ok(Self::new(
            dataset.dataset_id,
            dataset.generated_from_store_id,
            dataset.examples,
        ))
    }

    pub fn save_to_local_json(&self, path: &Path) -> Result<(), String> {
        validate_member_experience_path(path, "replay dataset output path")?;
        if let Some(parent) = path.parent() {
            if !parent.as_os_str().is_empty() {
                fs::create_dir_all(parent).map_err(|err| err.to_string())?;
            }
        }
        let text = serde_json::to_string_pretty(self).map_err(|err| err.to_string())?;
        fs::write(path, text).map_err(|err| err.to_string())
    }

    fn new(
        dataset_id: impl Into<String>,
        generated_from_store_id: impl Into<String>,
        examples: Vec<ReplayExample>,
    ) -> Self {
        let mut examples = examples;
        examples.sort_by(|left, right| {
            left.member_id
                .cmp(&right.member_id)
                .then(left.symbol.cmp(&right.symbol))
                .then(left.replay_id.cmp(&right.replay_id))
        });
        let mut member_ids: Vec<String> = examples
            .iter()
            .map(|example| example.member_id.clone())
            .collect();
        member_ids.sort();
        member_ids.dedup();
        Self {
            dataset_id: dataset_id.into(),
            example_count: examples.len(),
            member_count: member_ids.len(),
            examples,
            generated_from_store_id: generated_from_store_id.into(),
            paper_only: true,
        }
    }
}

pub fn extract_member_experiences_from_batch_cycle(
    batch_result: &BatchCommitteeCycleResult,
    state_update: Option<&BatchCycleStateUpdate>,
    owner_summary: Option<&OwnerCommitteeSummary>,
    paper_outcome_feedback: Option<&PaperOutcomeFeedback>,
) -> Vec<MemberExperienceRecord> {
    batch_result
        .member_opinions
        .iter()
        .enumerate()
        .map(|(index, opinion)| {
            let session = batch_result.committee_sessions.iter().find(|session| {
                session.event.symbol == opinion.symbol
                    && session.event.market_scope == opinion.market_scope
                    && session
                        .member_opinions
                        .iter()
                        .any(|session_opinion| session_opinion.member_id == opinion.member_id)
            });
            let decision = session.and_then(|session| {
                batch_result
                    .chairman_decisions
                    .iter()
                    .find(|decision| decision.session_id == session.session_id)
            });
            let update_reason = batch_result
                .score_updates
                .iter()
                .find(|update| update.member_id == opinion.member_id)
                .map(|update| update.update_reason)
                .unwrap_or(MemberScoreUpdateReason::Neutral);
            let outcome =
                member_experience_outcome(update_reason, decision, paper_outcome_feedback);
            let learning_label = member_learning_label_for(update_reason, outcome);
            let memory_state_summary = state_update.and_then(|state_update| {
                state_update
                    .memory_updates
                    .iter()
                    .find(|memory| memory.member_id == opinion.member_id)
                    .map(memory_state_summary)
            });
            let owner_context_summary =
                owner_summary.map(|summary| summary.owner_readable_summary.clone());
            MemberExperienceRecord {
                experience_id: format!(
                    "experience-{}-{}-{}-{}",
                    batch_result.batch_id, opinion.symbol, opinion.member_id, index
                ),
                member_id: opinion.member_id.clone(),
                symbol: opinion.symbol.clone(),
                market_scope: opinion.market_scope,
                cycle_id: Some(batch_result.batch_id.clone()),
                event_id: session.map(|session| session.event.event_id.clone()),
                session_id: session.map(|session| session.session_id.clone()),
                decision_id: decision.map(|decision| decision.decision_id.clone()),
                input_context: MemberExperienceInputContext {
                    market_data_summary: format!(
                        "symbol={} scope={:?}",
                        opinion.symbol, opinion.market_scope
                    ),
                    news_summary:
                        "headline/summary-only news context; full article body not stored"
                            .to_string(),
                    owner_context_summary,
                    style_blend_summary: None,
                    memory_state_summary,
                },
                member_opinion: MemberExperienceOpinionSnapshot {
                    stance: opinion.stance,
                    confidence: opinion.confidence,
                    expected_return_hint: opinion.expected_return_hint,
                    risk_hint: opinion.risk_hint,
                    evidence_notes: opinion.evidence_notes.clone(),
                    event_triggered: opinion.event_triggered,
                },
                committee_context: MemberExperienceCommitteeContext {
                    disagreement_level: session
                        .map(|session| session.disagreement_level)
                        .unwrap_or(0.0),
                    other_member_stances: session
                        .map(|session| {
                            session
                                .member_opinions
                                .iter()
                                .filter(|session_opinion| {
                                    session_opinion.member_id != opinion.member_id
                                })
                                .map(|session_opinion| {
                                    format!(
                                        "{}:{:?}",
                                        session_opinion.member_id, session_opinion.stance
                                    )
                                })
                                .collect()
                        })
                        .unwrap_or_default(),
                    chairman_action: decision.map(|decision| decision.final_action),
                    risk_governor_status: decision.map(|decision| decision.risk_governor_status),
                    risk_flags: session
                        .map(|session| session.risk_flags.clone())
                        .unwrap_or_default(),
                },
                outcome,
                attribution: update_reason,
                learning_label,
                created_at: None,
                paper_only: true,
            }
        })
        .collect()
}

pub fn build_replay_dataset_from_experience_store(
    store: &MemberExperienceStore,
    filter: &ReplayDatasetFilter,
) -> ReplayDataset {
    let examples: Vec<ReplayExample> = store
        .records
        .iter()
        .filter(|record| replay_filter_matches(record, filter))
        .map(|record| ReplayExample {
            replay_id: format!("replay-{}", record.experience_id),
            member_id: record.member_id.clone(),
            symbol: record.symbol.clone(),
            market_scope: record.market_scope,
            input_features: ReplayInputFeatures {
                market_data_summary: record.input_context.market_data_summary.clone(),
                news_summary: record.input_context.news_summary.clone(),
                owner_context_summary: record.input_context.owner_context_summary.clone(),
                memory_state_summary: record.input_context.memory_state_summary.clone(),
            },
            target: ReplayTarget {
                stance: record.member_opinion.stance,
                confidence_calibration: record.learning_label,
                risk_label: format!("{:?}", record.attribution),
                evidence_label: evidence_label_for(record),
                outcome_label: record.outcome,
            },
            sanitized_input_features: None,
            target_labels: None,
            post_decision_context: None,
            sample_weight: replay_sample_weight(record),
            paper_only: true,
        })
        .collect();
    ReplayDataset::new(
        format!("replay-dataset-{}", store.store_id),
        store.store_id.clone(),
        examples,
    )
}

pub fn compute_member_calibration_summaries(
    store: &MemberExperienceStore,
) -> Vec<MemberCalibrationSummary> {
    let mut member_ids: Vec<String> = store
        .records
        .iter()
        .map(|record| record.member_id.clone())
        .collect();
    member_ids.sort();
    member_ids.dedup();
    member_ids
        .into_iter()
        .map(|member_id| {
            let records: Vec<&MemberExperienceRecord> = store
                .records
                .iter()
                .filter(|record| record.member_id == member_id)
                .collect();
            let high_confidence_count = records
                .iter()
                .filter(|record| record.member_opinion.confidence >= 0.75)
                .count();
            let high_confidence_bad_call_count = records
                .iter()
                .filter(|record| {
                    record.member_opinion.confidence >= 0.75
                        && matches!(
                            record.attribution,
                            MemberScoreUpdateReason::BadCall
                                | MemberScoreUpdateReason::RiskyCall
                                | MemberScoreUpdateReason::LowEvidence
                        )
                })
                .count();
            let risk_veto_count = records
                .iter()
                .filter(|record| {
                    matches!(record.outcome, MemberExperienceOutcome::RiskVetoSavedLoss)
                })
                .count();
            let helpful_dissent_count = records
                .iter()
                .filter(|record| matches!(record.outcome, MemberExperienceOutcome::HelpfulDissent))
                .count();
            let need_more_evidence_count = records
                .iter()
                .filter(|record| {
                    matches!(record.learning_label, MemberLearningLabel::NeedMoreEvidence)
                })
                .count();
            let (calibration_warning, suggested_adjustment) = if high_confidence_bad_call_count > 0
            {
                (
                    CalibrationWarning::Overconfident,
                    CalibrationSuggestedAdjustment::LowerConfidence,
                )
            } else if need_more_evidence_count > 0 {
                (
                    CalibrationWarning::NeedsMoreEvidence,
                    CalibrationSuggestedAdjustment::RaiseEvidenceThreshold,
                )
            } else if risk_veto_count > 0 {
                (
                    CalibrationWarning::Risky,
                    CalibrationSuggestedAdjustment::RaiseRiskSensitivity,
                )
            } else {
                (
                    CalibrationWarning::None,
                    CalibrationSuggestedAdjustment::Keep,
                )
            };
            MemberCalibrationSummary {
                member_id,
                total_records: records.len(),
                high_confidence_count,
                high_confidence_bad_call_count,
                risk_veto_count,
                helpful_dissent_count,
                need_more_evidence_count,
                calibration_warning,
                suggested_adjustment,
            }
        })
        .collect()
}

pub fn compute_member_calibration_summary(
    records: &[MemberExperienceRecord],
) -> MemberCalibrationSummary {
    let store = MemberExperienceStore::new("single-member-calibration", records.to_vec());
    compute_member_calibration_summaries(&store)
        .into_iter()
        .next()
        .unwrap_or_else(|| MemberCalibrationSummary {
            member_id: "unknown".to_string(),
            total_records: 0,
            high_confidence_count: 0,
            high_confidence_bad_call_count: 0,
            risk_veto_count: 0,
            helpful_dissent_count: 0,
            need_more_evidence_count: 0,
            calibration_warning: CalibrationWarning::None,
            suggested_adjustment: CalibrationSuggestedAdjustment::Keep,
        })
}

pub fn generate_member_self_review_notes(
    store: &MemberExperienceStore,
) -> Vec<MemberSelfReviewNote> {
    store
        .records
        .iter()
        .filter_map(|record| {
            let (review_type, summary, next_behavior_hint) = match record.learning_label {
                MemberLearningLabel::Penalize | MemberLearningLabel::CalibrateDown => (
                    MemberSelfReviewType::MistakeReview,
                    format!(
                        "{} should review {:?} on {}",
                        record.member_id, record.attribution, record.symbol
                    ),
                    "lower confidence unless evidence and risk checks agree".to_string(),
                ),
                MemberLearningLabel::NeedMoreEvidence => (
                    MemberSelfReviewType::EvidenceReview,
                    format!(
                        "{} lacked enough evidence on {}",
                        record.member_id, record.symbol
                    ),
                    "ask for more evidence before proposing paper action".to_string(),
                ),
                MemberLearningLabel::Reinforce => (
                    MemberSelfReviewType::GoodCallReview,
                    format!(
                        "{} can reinforce the {} pattern",
                        record.member_id, record.symbol
                    ),
                    "reuse the evidence pattern without increasing live risk".to_string(),
                ),
                MemberLearningLabel::CalibrateUp | MemberLearningLabel::Keep => return None,
            };
            Some(MemberSelfReviewNote {
                note_id: format!("self-review-{}", record.experience_id),
                member_id: record.member_id.clone(),
                experience_id: record.experience_id.clone(),
                review_type,
                summary,
                next_behavior_hint,
                paper_only: true,
            })
        })
        .collect()
}

pub fn generate_deterministic_self_review_notes(
    records: &[MemberExperienceRecord],
) -> Vec<MemberSelfReviewNote> {
    let store = MemberExperienceStore::new("self-review-records", records.to_vec());
    generate_member_self_review_notes(&store)
}

impl Default for SanitizedReplayDatasetBuildConfig {
    fn default() -> Self {
        Self {
            source_experience_store_id: "experience-store".to_string(),
            strict_temporal_boundary: true,
            include_post_decision_context_for_audit: true,
            include_prior_memory_buckets: true,
            reject_on_blocking_leakage: true,
            paper_only: true,
        }
    }
}

impl ReplayFeatureSanitizer {
    pub fn sanitize_input_text(&self, field_name: &str, text: &str) -> SanitizedField {
        let removed_terms = self.detect_blocked_terms(text);
        let field_blocked = self
            .blocked_field_names
            .iter()
            .any(|blocked| field_name.to_ascii_lowercase().contains(blocked));
        let original_present = !text.trim().is_empty();
        let contains_blocking_safety_term = removed_terms.iter().any(|term| {
            matches!(
                term.as_str(),
                "broker"
                    | "order"
                    | "account"
                    | "position"
                    | "holdings"
                    | "buying_power"
                    | "real_pnl"
                    | "pnl"
            )
        }) || field_blocked
            && matches!(
                field_name,
                "broker"
                    | "order"
                    | "account"
                    | "position"
                    | "holdings"
                    | "buying_power"
                    | "real_pnl"
                    | "pnl"
            );
        let safety_status = if contains_blocking_safety_term {
            SanitizedFieldSafetyStatus::BlockingLeakage
        } else if removed_terms.is_empty() && !field_blocked {
            SanitizedFieldSafetyStatus::Clean
        } else {
            SanitizedFieldSafetyStatus::Sanitized
        };
        let sanitized_text = if removed_terms.is_empty() && !field_blocked {
            text.to_string()
        } else if contains_blocking_safety_term {
            self.replacement_note.clone()
        } else {
            remove_blocked_terms(text, &removed_terms, &self.replacement_note)
        };
        SanitizedField {
            original_present,
            sanitized_text,
            removed_terms,
            safety_status,
        }
    }

    pub fn sanitize_memory_summary(&self, summary: &str) -> SanitizedField {
        self.sanitize_input_text("prior_member_memory_summary", summary)
    }

    pub fn sanitize_owner_context(&self, summary: &str) -> SanitizedField {
        self.sanitize_input_text("owner_pre_decision_context", summary)
    }

    pub fn sanitize_replay_input_features(
        &self,
        features: &ReplayInputFeatures,
    ) -> SanitizedReplayInputFeatures {
        let market = self.sanitize_input_text("market_data_summary", &features.market_data_summary);
        let news = self.sanitize_input_text("news_summary", &features.news_summary);
        let owner = features
            .owner_context_summary
            .as_ref()
            .map(|text| self.sanitize_owner_context(text));
        let memory = features
            .memory_state_summary
            .as_ref()
            .map(|text| self.sanitize_memory_summary(text));
        let mut feature_safety_notes = Vec::new();
        for (field, sanitized) in [("market_data_summary", &market), ("news_summary", &news)] {
            if !sanitized.removed_terms.is_empty() {
                feature_safety_notes.push(format!("{field}: removed blocked signal"));
            }
        }
        if let Some(owner) = &owner {
            if !owner.removed_terms.is_empty() {
                feature_safety_notes.push(format!(
                    "owner_pre_decision_context: removed blocked signal"
                ));
            }
        }
        if let Some(memory) = &memory {
            if !memory.removed_terms.is_empty() {
                feature_safety_notes.push(format!(
                    "prior_member_memory_summary: removed blocked signal"
                ));
            }
        }
        if feature_safety_notes.is_empty() {
            feature_safety_notes
                .push("strict temporal boundary: input features are pre-decision only".to_string());
        }
        SanitizedReplayInputFeatures {
            market_data_summary: market.sanitized_text,
            news_summary: news.sanitized_text,
            owner_pre_decision_context: owner.map(|field| field.sanitized_text),
            prior_member_memory_summary: memory.map(|field| field.sanitized_text),
            prior_style_blend_summary: None,
            prior_calibration_summary: None,
            feature_safety_notes,
            paper_only: true,
        }
    }

    pub fn detect_blocked_terms(&self, text: &str) -> Vec<String> {
        detect_blocked_terms_with_list(text, &self.blocked_terms)
    }
}

pub fn build_pre_decision_memory_snapshot(
    member_state: &MemberMemoryState,
    _before_cycle_id: Option<&str>,
) -> MemberPreDecisionMemorySnapshot {
    MemberPreDecisionMemorySnapshot {
        member_id: member_state.member_id.clone(),
        recent_opinion_count: member_state.recent_opinion_count,
        recent_event_count: member_state.recent_event_count,
        recent_good_call_count_bucket: memory_count_bucket(member_state.recent_good_call_count),
        recent_bad_call_count_bucket: memory_count_bucket(member_state.recent_bad_call_count),
        recent_risk_veto_count_bucket: memory_count_bucket(member_state.recent_risk_veto_count),
        evidence_need_tendency: evidence_need_tendency_from_notes(&member_state.notes),
        calibration_warning_prior: None,
        paper_only: true,
    }
}

pub fn build_sanitized_replay_dataset_from_experience_store(
    store: &MemberExperienceStore,
    config: SanitizedReplayDatasetBuildConfig,
) -> SanitizedReplayDatasetBuildResult {
    let sanitizer = ReplayFeatureSanitizer::default();
    let mut examples = Vec::new();
    let mut leakage_findings = Vec::new();
    let mut sanitized_count = 0;
    let mut rejected_count = 0;

    for record in &store.records {
        let raw_features = ReplayInputFeatures {
            market_data_summary: record.input_context.market_data_summary.clone(),
            news_summary: record.input_context.news_summary.clone(),
            owner_context_summary: record.input_context.owner_context_summary.clone(),
            memory_state_summary: record.input_context.memory_state_summary.clone(),
        };
        let sanitized = sanitizer.sanitize_replay_input_features(&raw_features);
        let sanitized_fields = [
            (
                "market_data_summary",
                sanitizer
                    .sanitize_input_text("market_data_summary", &raw_features.market_data_summary),
            ),
            (
                "news_summary",
                sanitizer.sanitize_input_text("news_summary", &raw_features.news_summary),
            ),
            (
                "owner_pre_decision_context",
                raw_features
                    .owner_context_summary
                    .as_ref()
                    .map(|text| sanitizer.sanitize_owner_context(text))
                    .unwrap_or_else(|| sanitizer.sanitize_owner_context("")),
            ),
            (
                "prior_member_memory_summary",
                raw_features
                    .memory_state_summary
                    .as_ref()
                    .map(|text| sanitizer.sanitize_memory_summary(text))
                    .unwrap_or_else(|| sanitizer.sanitize_memory_summary("")),
            ),
        ];
        let mut blocking = false;
        for (field_name, field) in sanitized_fields {
            if !field.removed_terms.is_empty() {
                sanitized_count += 1;
                for term in field.removed_terms {
                    let issue_type = leakage_issue_type_for_term(&term);
                    let severity = if matches!(
                        issue_type,
                        ReplayLeakageIssueType::BrokerAccountFieldDetected
                            | ReplayLeakageIssueType::RealTradeFieldDetected
                    ) {
                        ReplayLeakageSeverity::Blocking
                    } else {
                        ReplayLeakageSeverity::Warning
                    };
                    if severity == ReplayLeakageSeverity::Blocking {
                        blocking = true;
                    }
                    leakage_findings.push(ReplayLeakageFinding {
                        replay_id: format!("replay-{}", record.experience_id),
                        member_id: record.member_id.clone(),
                        section: ReplaySection::InputFeatures,
                        issue_type,
                        field_name: field_name.to_string(),
                        severity,
                        note: format!("sanitizer removed {term} from pre-decision input"),
                    });
                }
            }
            if field.safety_status == SanitizedFieldSafetyStatus::BlockingLeakage {
                blocking = true;
            }
        }
        if blocking && config.reject_on_blocking_leakage {
            rejected_count += 1;
            continue;
        }

        let target_labels = ReplayTargetLabels {
            stance_target: record.member_opinion.stance,
            confidence_calibration_target: record.learning_label,
            risk_label: format!("{:?}", record.attribution),
            evidence_label: evidence_label_for(record),
            outcome_label: record.outcome,
            attribution_label: record.attribution,
            label_source: ReplayLabelSource::ReviewRequired,
            label_confidence: ReplayLabelConfidence::ReviewRequired,
            paper_only: true,
        };
        let post_decision_context =
            config
                .include_post_decision_context_for_audit
                .then(|| ReplayPostDecisionContext {
                    chairman_action: record.committee_context.chairman_action,
                    risk_governor_status: record.committee_context.risk_governor_status,
                    disagreement_level: record.committee_context.disagreement_level,
                    other_member_stances: record.committee_context.other_member_stances.clone(),
                    risk_flags: record.committee_context.risk_flags.clone(),
                    paper_only: true,
                });
        examples.push(ReplayExample {
            replay_id: format!("replay-{}", record.experience_id),
            member_id: record.member_id.clone(),
            symbol: record.symbol.clone(),
            market_scope: record.market_scope,
            input_features: ReplayInputFeatures {
                market_data_summary: sanitized.market_data_summary.clone(),
                news_summary: sanitized.news_summary.clone(),
                owner_context_summary: sanitized.owner_pre_decision_context.clone(),
                memory_state_summary: if config.include_prior_memory_buckets {
                    sanitized.prior_member_memory_summary.clone()
                } else {
                    None
                },
            },
            target: ReplayTarget {
                stance: target_labels.stance_target,
                confidence_calibration: target_labels.confidence_calibration_target,
                risk_label: target_labels.risk_label.clone(),
                evidence_label: target_labels.evidence_label.clone(),
                outcome_label: target_labels.outcome_label,
            },
            sanitized_input_features: Some(sanitized),
            target_labels: Some(target_labels),
            post_decision_context,
            sample_weight: replay_sample_weight(record),
            paper_only: true,
        });
    }

    let dataset = ReplayDataset::new(
        format!(
            "sanitized-replay-dataset-{}",
            config.source_experience_store_id
        ),
        config.source_experience_store_id,
        examples,
    );
    let leakage_check = check_replay_data_leakage(&dataset);
    leakage_findings.extend(leakage_check.leakage_findings);
    leakage_findings.sort_by(|left, right| {
        left.replay_id
            .cmp(&right.replay_id)
            .then(left.field_name.cmp(&right.field_name))
            .then(format!("{:?}", left.issue_type).cmp(&format!("{:?}", right.issue_type)))
    });
    leakage_findings.dedup_by(|left, right| {
        left.replay_id == right.replay_id
            && left.member_id == right.member_id
            && left.section == right.section
            && left.issue_type == right.issue_type
            && left.field_name == right.field_name
    });

    let has_blocking = leakage_findings
        .iter()
        .any(|finding| finding.severity == ReplayLeakageSeverity::Blocking);
    let build_status = if dataset.examples.is_empty() {
        SanitizedReplayDatasetBuildStatus::Empty
    } else if has_blocking && config.reject_on_blocking_leakage {
        SanitizedReplayDatasetBuildStatus::BlockedByLeakage
    } else if sanitized_count > 0 || rejected_count > 0 || has_blocking {
        SanitizedReplayDatasetBuildStatus::BuiltWithWarnings
    } else {
        SanitizedReplayDatasetBuildStatus::Built
    };

    SanitizedReplayDatasetBuildResult {
        dataset,
        sanitized_count,
        rejected_count,
        leakage_findings,
        build_status,
        paper_only: true,
    }
}

fn default_replay_sanitizer_blocked_terms() -> Vec<String> {
    [
        "RiskVeto",
        "risk_veto",
        "risk veto",
        "vetoed",
        "Vetoed",
        "RiskGovernor",
        "Risk Governor",
        "risk_governor_status",
        "ChairmanDecision",
        "Chairman Decision",
        "의장 결정",
        "chairman_action",
        "final_action",
        "outcome",
        "paper_positive",
        "paper_negative",
        "paper_neutral",
        "PaperPositive",
        "PaperNegative",
        "PaperNeutral",
        "PaperNoTrade",
        "helpful_dissent",
        "HelpfulDissent",
        "bad_call",
        "BadCall",
        "good_call",
        "GoodCall",
        "attribution",
        "learning_label",
        "broker",
        "order",
        "account",
        "position",
        "holdings",
        "buying_power",
        "real_pnl",
        "pnl",
    ]
    .into_iter()
    .map(str::to_string)
    .collect()
}

fn detect_blocked_terms_with_list(text: &str, blocked_terms: &[String]) -> Vec<String> {
    let lower = text.to_ascii_lowercase();
    let mut terms: Vec<String> = blocked_terms
        .iter()
        .filter(|term| lower.contains(&term.to_ascii_lowercase()))
        .cloned()
        .collect();
    terms.sort();
    terms.dedup();
    terms
}

fn remove_blocked_terms(text: &str, removed_terms: &[String], replacement: &str) -> String {
    let mut sanitized = text.to_string();
    for term in removed_terms {
        sanitized = replace_ascii_case_insensitive(&sanitized, term, replacement);
    }
    sanitized
}

fn replace_ascii_case_insensitive(text: &str, needle: &str, replacement: &str) -> String {
    if needle.is_empty() {
        return text.to_string();
    }
    let mut result = String::new();
    let mut remaining = text;
    let needle_lower = needle.to_ascii_lowercase();
    while let Some(index) = remaining.to_ascii_lowercase().find(&needle_lower) {
        result.push_str(&remaining[..index]);
        result.push_str(replacement);
        remaining = &remaining[index + needle.len()..];
    }
    result.push_str(remaining);
    result
}

fn replay_label_source_for_example(example: &ReplayExample) -> ReplayLabelSource {
    example
        .target_labels
        .as_ref()
        .map(|labels| labels.label_source)
        .unwrap_or(ReplayLabelSource::ReviewRequired)
}

fn replay_label_confidence_for_example(example: &ReplayExample) -> ReplayLabelConfidence {
    example
        .target_labels
        .as_ref()
        .map(|labels| labels.label_confidence)
        .unwrap_or(ReplayLabelConfidence::ReviewRequired)
}

fn is_weak_replay_label(example: &ReplayExample) -> bool {
    !matches!(
        replay_label_source_for_example(example),
        ReplayLabelSource::ValidatedPaperLabel | ReplayLabelSource::ValidatedBacktestLabel
    ) || matches!(
        replay_label_confidence_for_example(example),
        ReplayLabelConfidence::Low | ReplayLabelConfidence::ReviewRequired
    )
}

fn is_validated_replay_label(example: &ReplayExample) -> bool {
    matches!(
        replay_label_source_for_example(example),
        ReplayLabelSource::ValidatedPaperLabel | ReplayLabelSource::ValidatedBacktestLabel
    ) && matches!(
        replay_label_confidence_for_example(example),
        ReplayLabelConfidence::High | ReplayLabelConfidence::Medium
    )
}

fn is_rejected_replay_label(example: &ReplayExample) -> bool {
    matches!(
        replay_label_source_for_example(example),
        ReplayLabelSource::RejectedLabel
    )
}

fn label_evidence_contains_unsafe_fields(record: &LabelEvidenceRecord) -> Vec<String> {
    let text = serde_json::to_string(record).unwrap_or_default();
    let lower = text.to_ascii_lowercase();
    [
        "broker",
        "order",
        "account",
        "real pnl",
        "real_pnl",
        "live trading",
        "execute trade",
    ]
    .into_iter()
    .filter(|term| lower.contains(term))
    .map(str::to_string)
    .collect()
}

fn has_label_evidence(record: &LabelEvidenceRecord, policy: &PaperLabelValidationPolicy) -> bool {
    record.evidence_items.price_move_evidence.is_some()
        && (!policy.require_decision_trace
            || record
                .evidence_items
                .decision_trace_evidence
                .as_ref()
                .map(|text| !text.trim().is_empty())
                .unwrap_or(false))
        && (!policy.require_risk_governor_status
            || record.evidence_items.risk_veto_evidence.is_some())
}

fn evidence_supports_candidate_label(
    record: &LabelEvidenceRecord,
    policy: &PaperLabelValidationPolicy,
) -> Option<bool> {
    let move_pct = record.evidence_items.price_move_evidence?;
    Some(match record.candidate_label {
        MemberExperienceOutcome::PaperPositive => {
            move_pct >= policy.min_abs_price_move_pct_for_positive
        }
        MemberExperienceOutcome::PaperNegative
        | MemberExperienceOutcome::RiskVetoSavedLoss
        | MemberExperienceOutcome::BadRiskCall => {
            move_pct <= -policy.min_abs_price_move_pct_for_negative
        }
        MemberExperienceOutcome::PaperNeutral | MemberExperienceOutcome::Unknown => {
            move_pct.abs() <= policy.neutral_band_pct
        }
        MemberExperienceOutcome::MissedOpportunity | MemberExperienceOutcome::HelpfulDissent => {
            true
        }
    })
}

pub fn validate_paper_label(
    evidence_record: &LabelEvidenceRecord,
    policy: &PaperLabelValidationPolicy,
) -> PaperLabelValidationResult {
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    if !evidence_record.paper_only || !policy.paper_only {
        blockers.push("label validation must stay paper-only".to_string());
    }
    blockers.extend(label_evidence_contains_unsafe_fields(evidence_record));
    if matches!(
        evidence_record.candidate_source,
        ReplayLabelSource::SimulatedFixture
    ) && matches!(evidence_record.confidence, ReplayLabelConfidence::High)
        && !policy.allow_simulated_fixture_high_confidence
    {
        blockers.push("SimulatedFixture cannot promote to High confidence".to_string());
    }
    if matches!(
        evidence_record.candidate_source,
        ReplayLabelSource::ManualPaperLabel
    ) && !policy.allow_manual_label_without_evidence
        && !has_label_evidence(evidence_record, policy)
    {
        warnings.push("manual paper label needs supporting local evidence".to_string());
    }

    let support = evidence_supports_candidate_label(evidence_record, policy);
    if support == Some(false) {
        blockers.push("candidate label contradicts local evidence".to_string());
    }
    if support.is_none() {
        warnings.push("missing market movement evidence".to_string());
    }
    if matches!(
        evidence_record.candidate_source,
        ReplayLabelSource::PaperBacktestDeferred
    ) {
        warnings.push(
            "backtest labels remain deferred until a real backtest engine exists".to_string(),
        );
    }

    let validation_status = if !blockers.is_empty() {
        LabelEvidenceValidationStatus::Rejected
    } else if !warnings.is_empty() || !has_label_evidence(evidence_record, policy) {
        LabelEvidenceValidationStatus::NeedsReview
    } else if matches!(
        evidence_record.candidate_source,
        ReplayLabelSource::PaperOutcomeUnknown
    ) {
        LabelEvidenceValidationStatus::NeedsReview
    } else {
        LabelEvidenceValidationStatus::Validated
    };

    let (promoted_label_source, promoted_confidence) = match validation_status {
        LabelEvidenceValidationStatus::Validated => match evidence_record.candidate_source {
            ReplayLabelSource::PaperBacktestDeferred
            | ReplayLabelSource::ValidatedBacktestLabel => (
                ReplayLabelSource::ValidatedBacktestLabel,
                evidence_record.confidence,
            ),
            ReplayLabelSource::SimulatedFixture => (
                ReplayLabelSource::SimulatedFixture,
                ReplayLabelConfidence::Low,
            ),
            ReplayLabelSource::ReviewRequired => (
                ReplayLabelSource::ValidatedPaperLabel,
                ReplayLabelConfidence::Medium,
            ),
            _ => (
                ReplayLabelSource::ValidatedPaperLabel,
                evidence_record.confidence,
            ),
        },
        LabelEvidenceValidationStatus::Rejected => (
            ReplayLabelSource::RejectedLabel,
            ReplayLabelConfidence::ReviewRequired,
        ),
        LabelEvidenceValidationStatus::Ambiguous => (
            ReplayLabelSource::AmbiguousLabel,
            ReplayLabelConfidence::Low,
        ),
        LabelEvidenceValidationStatus::Unchecked | LabelEvidenceValidationStatus::NeedsReview => (
            ReplayLabelSource::ReviewRequired,
            ReplayLabelConfidence::ReviewRequired,
        ),
    };

    PaperLabelValidationResult {
        evidence_record: evidence_record.clone(),
        promoted_label_source,
        promoted_confidence,
        validation_status,
        blockers,
        warnings,
        paper_only: true,
    }
}

pub fn check_backtest_label_contract(
    contract: &BacktestLabelContract,
) -> BacktestLabelContractCheck {
    let mut missing_fields = Vec::new();
    if matches!(
        contract.entry_price_source,
        BacktestEntryPriceSource::Deferred
    ) {
        missing_fields.push("entry_price_source".to_string());
    }
    if matches!(
        contract.exit_price_source,
        BacktestExitPriceSource::Deferred
    ) {
        missing_fields.push("exit_price_source".to_string());
    }
    if matches!(contract.slippage_model, BacktestCostModel::Deferred) {
        missing_fields.push("slippage_model".to_string());
    }
    if matches!(contract.fee_model, BacktestCostModel::Deferred) {
        missing_fields.push("fee_model".to_string());
    }
    if contract.leakage_guard.is_empty() {
        missing_fields.push("leakage_guard".to_string());
    }
    let leakage_safe = contract.paper_only
        && contract
            .leakage_guard
            .contains(&BacktestLeakageGuard::NoFutureInput)
        && contract
            .leakage_guard
            .contains(&BacktestLeakageGuard::NoPostDecisionFeature);
    let status = if !contract.paper_only || !leakage_safe {
        BacktestLabelContractStatus::ContractUnsafe
    } else if !missing_fields.is_empty() {
        BacktestLabelContractStatus::ContractIncomplete
    } else if matches!(contract.slippage_model, BacktestCostModel::None)
        || matches!(contract.fee_model, BacktestCostModel::None)
    {
        BacktestLabelContractStatus::ContractReadyWithWarnings
    } else {
        BacktestLabelContractStatus::ContractReady
    };
    let contract_valid = matches!(
        status,
        BacktestLabelContractStatus::ContractReady
            | BacktestLabelContractStatus::ContractReadyWithWarnings
    );
    BacktestLabelContractCheck {
        contract_id: contract.contract_id.clone(),
        contract_valid,
        missing_fields,
        leakage_safe,
        can_generate_validated_backtest_label: false,
        status,
        paper_only: true,
    }
}

pub fn evaluate_label_promotion(
    replay_example: &ReplayExample,
    evidence_record: &LabelEvidenceRecord,
    policy: &PaperLabelValidationPolicy,
) -> LabelPromotionGate {
    let validation_result = validate_paper_label(evidence_record, policy);
    let original_label_source = replay_label_source_for_example(replay_example);
    let original_confidence = replay_label_confidence_for_example(replay_example);
    let (promotion_allowed, promotion_status, reason) = match validation_result.validation_status {
        LabelEvidenceValidationStatus::Validated
            if matches!(
                validation_result.promoted_label_source,
                ReplayLabelSource::ValidatedPaperLabel | ReplayLabelSource::ValidatedBacktestLabel
            ) =>
        {
            (
                true,
                LabelPromotionStatus::Promoted,
                "validated evidence permits label promotion",
            )
        }
        LabelEvidenceValidationStatus::Rejected => (
            false,
            LabelPromotionStatus::Rejected,
            "label evidence rejected",
        ),
        LabelEvidenceValidationStatus::Ambiguous => (
            false,
            LabelPromotionStatus::NeedsReview,
            "label evidence is ambiguous",
        ),
        _ if validation_result
            .warnings
            .iter()
            .any(|warning| warning.contains("backtest labels remain deferred")) =>
        {
            (
                false,
                LabelPromotionStatus::NeedsReview,
                "backtest label promotion requires a real backtest engine",
            )
        }
        _ => (
            false,
            LabelPromotionStatus::NeedsReview,
            "label requires review or stronger evidence",
        ),
    };

    LabelPromotionGate {
        replay_id: replay_example.replay_id.clone(),
        original_label_source,
        original_confidence,
        promoted_label_source: if promotion_allowed {
            validation_result.promoted_label_source
        } else if matches!(promotion_status, LabelPromotionStatus::Rejected) {
            ReplayLabelSource::RejectedLabel
        } else {
            original_label_source
        },
        promoted_confidence: if promotion_allowed {
            validation_result.promoted_confidence
        } else if matches!(promotion_status, LabelPromotionStatus::Rejected) {
            ReplayLabelConfidence::ReviewRequired
        } else {
            original_confidence
        },
        promotion_allowed,
        promotion_status,
        reason: reason.to_string(),
        validation_result,
        paper_only: true,
    }
}

fn evidence_record_for_replay_example(
    example: &ReplayExample,
    evidence_records: &[LabelEvidenceRecord],
) -> LabelEvidenceRecord {
    evidence_records
        .iter()
        .find(|record| {
            record
                .replay_id
                .as_ref()
                .map(|replay_id| replay_id == &example.replay_id)
                .unwrap_or(false)
                || (record.symbol == example.symbol && record.market_scope == example.market_scope)
        })
        .cloned()
        .unwrap_or_else(|| LabelEvidenceRecord {
            evidence_id: format!("missing-evidence-{}", example.replay_id),
            replay_id: Some(example.replay_id.clone()),
            experience_id: None,
            symbol: example.symbol.clone(),
            market_scope: example.market_scope,
            decision_id: None,
            candidate_label: example.target.outcome_label,
            candidate_source: replay_label_source_for_example(example),
            evidence_items: LabelEvidenceItems {
                price_move_evidence: None,
                risk_veto_evidence: None,
                news_context_evidence: None,
                decision_trace_evidence: None,
                paper_horizon_evidence: None,
            },
            validation_status: LabelEvidenceValidationStatus::Unchecked,
            confidence: replay_label_confidence_for_example(example),
            validator_notes: vec!["no matching label evidence record".to_string()],
            paper_only: true,
        })
}

pub fn build_validated_replay_dataset(
    sanitized_dataset: &ReplayDataset,
    evidence_records: &[LabelEvidenceRecord],
    config: ValidatedReplayDatasetBuildConfig,
) -> ValidatedReplayDatasetBuildResult {
    let backtest_contract_check = config
        .backtest_label_contract
        .as_ref()
        .map(check_backtest_label_contract);
    let mut examples = Vec::new();
    let mut promotion_gates = Vec::new();
    let mut promoted_count = 0;
    let mut not_promoted_count = 0;
    let mut rejected_count = 0;
    let mut needs_review_count = 0;

    for example in &sanitized_dataset.examples {
        let evidence = evidence_record_for_replay_example(example, evidence_records);
        let mut gate =
            evaluate_label_promotion(example, &evidence, &config.label_validation_policy);
        if gate.promotion_allowed
            && matches!(
                gate.promoted_label_source,
                ReplayLabelSource::ValidatedBacktestLabel
            )
        {
            let can_generate_validated_backtest_label = backtest_contract_check
                .as_ref()
                .map(|check| {
                    check.contract_valid
                        && check.leakage_safe
                        && check.can_generate_validated_backtest_label
                })
                .unwrap_or(false);
            if !can_generate_validated_backtest_label {
                gate.promotion_allowed = false;
                gate.promotion_status = LabelPromotionStatus::NeedsReview;
                gate.promoted_label_source = gate.original_label_source;
                gate.promoted_confidence = gate.original_confidence;
                gate.reason = backtest_contract_check
                    .as_ref()
                    .map(|check| {
                        format!(
                            "validated backtest label remains deferred until an engine can generate labels ({:?})",
                            check.status
                        )
                    })
                    .unwrap_or_else(|| {
                        "validated backtest label requires a backtest label contract and engine"
                            .to_string()
                    });
            }
        }
        let mut updated = example.clone();
        match gate.promotion_status {
            LabelPromotionStatus::Promoted => {
                promoted_count += 1;
                if let Some(labels) = &mut updated.target_labels {
                    labels.label_source = gate.promoted_label_source;
                    labels.label_confidence = gate.promoted_confidence;
                }
                examples.push(updated);
            }
            LabelPromotionStatus::Rejected => {
                rejected_count += 1;
                if !config.reject_rejected_labels {
                    if let Some(labels) = &mut updated.target_labels {
                        labels.label_source = ReplayLabelSource::RejectedLabel;
                        labels.label_confidence = ReplayLabelConfidence::ReviewRequired;
                    }
                    examples.push(updated);
                }
            }
            LabelPromotionStatus::NeedsReview => {
                needs_review_count += 1;
                if let Some(labels) = &mut updated.target_labels {
                    labels.label_source = ReplayLabelSource::ReviewRequired;
                    labels.label_confidence = ReplayLabelConfidence::ReviewRequired;
                }
                examples.push(updated);
            }
            LabelPromotionStatus::NotPromoted => {
                not_promoted_count += 1;
                examples.push(updated);
            }
        }
        promotion_gates.push(gate);
    }

    let dataset = ReplayDataset::new(
        format!("validated-{}", sanitized_dataset.dataset_id),
        sanitized_dataset.generated_from_store_id.clone(),
        examples,
    );
    let build_status = if dataset.examples.is_empty() {
        ValidatedReplayDatasetBuildStatus::Empty
    } else if rejected_count > 0 && config.reject_rejected_labels {
        ValidatedReplayDatasetBuildStatus::BlockedByRejectedLabels
    } else if config.require_validated_labels_for_training && promoted_count == 0 {
        ValidatedReplayDatasetBuildStatus::BlockedByWeakLabels
    } else if needs_review_count > 0 || not_promoted_count > 0 {
        ValidatedReplayDatasetBuildStatus::BuiltWithWarnings
    } else {
        ValidatedReplayDatasetBuildStatus::Built
    };

    ValidatedReplayDatasetBuildResult {
        dataset,
        label_evidence_records: evidence_records.to_vec(),
        promotion_gates,
        paper_evidence_matching_result: None,
        paper_evidence_promotion_results: Vec::new(),
        promoted_count,
        not_promoted_count,
        rejected_count,
        needs_review_count,
        unmatched_evidence_count: 0,
        ambiguous_match_count: 0,
        build_status,
        paper_only: true,
    }
}

fn summarize_label_quality_for_dataset(
    dataset: &ReplayDataset,
    rejected_label_count: usize,
    needs_review_count: usize,
) -> LabelQualitySummary {
    let total_examples = dataset.examples.len();
    let validated_label_count = dataset
        .examples
        .iter()
        .filter(|example| is_validated_replay_label(example))
        .count();
    let weak_label_count = dataset
        .examples
        .iter()
        .filter(|example| is_weak_replay_label(example))
        .count();
    let validated_label_ratio = ratio(validated_label_count, total_examples);
    let mut source_distribution = std::collections::BTreeMap::new();
    let mut confidence_distribution = std::collections::BTreeMap::new();
    for example in &dataset.examples {
        *source_distribution
            .entry(format!("{:?}", replay_label_source_for_example(example)))
            .or_insert(0) += 1;
        *confidence_distribution
            .entry(format!(
                "{:?}",
                replay_label_confidence_for_example(example)
            ))
            .or_insert(0) += 1;
    }
    let label_quality_status = if rejected_label_count > 0 {
        LabelQualityStatus::Blocked
    } else if validated_label_ratio >= 0.8 {
        LabelQualityStatus::Strong
    } else if validated_label_ratio >= 0.5 {
        LabelQualityStatus::Acceptable
    } else {
        LabelQualityStatus::Weak
    };
    let mut recommended_next_label_actions = Vec::new();
    if weak_label_count > 0 || needs_review_count > 0 {
        recommended_next_label_actions.push(RecommendedLabelAction::AddPaperOutcomeEvidence);
        recommended_next_label_actions.push(RecommendedLabelAction::ReviewManualLabels);
    }
    if rejected_label_count > 0 {
        recommended_next_label_actions.push(RecommendedLabelAction::RejectContradictoryLabels);
    }
    if validated_label_ratio < 0.8 {
        recommended_next_label_actions.push(RecommendedLabelAction::CollectMoreValidatedOutcomes);
    }
    recommended_next_label_actions.push(RecommendedLabelAction::AddBacktestContract);
    recommended_next_label_actions.sort();
    recommended_next_label_actions.dedup();

    LabelQualitySummary {
        total_examples,
        validated_label_count,
        weak_label_count,
        rejected_label_count,
        needs_review_count,
        validated_label_ratio,
        source_distribution,
        confidence_distribution,
        label_quality_status,
        recommended_next_label_actions,
        paper_only: true,
    }
}

pub fn summarize_label_quality(
    build_result: &ValidatedReplayDatasetBuildResult,
) -> LabelQualitySummary {
    summarize_label_quality_for_dataset(
        &build_result.dataset,
        build_result
            .dataset
            .examples
            .iter()
            .filter(|example| is_rejected_replay_label(example))
            .count()
            + build_result.rejected_count,
        build_result.needs_review_count,
    )
}

fn paper_outcome_evidence_unsafe_reasons(value: &serde_json::Value) -> Vec<String> {
    let mut reasons = Vec::new();
    match value {
        serde_json::Value::Object(map) => {
            for (key, child) in map {
                let lower = key.to_ascii_lowercase();
                for prohibited in [
                    "order",
                    "account",
                    "order_id",
                    "account_id",
                    "broker",
                    "execution_id",
                    "real_trade",
                    "real trade",
                    "position_size",
                    "quantity",
                    "holdings",
                    "buying_power",
                    "live_trade",
                    "real_pnl",
                    "pnl",
                    "api_key",
                    "secret",
                ] {
                    if lower.contains(prohibited) {
                        reasons.push(format!(
                            "paper outcome evidence rejected unsafe field: {key}"
                        ));
                    }
                }
                reasons.extend(paper_outcome_evidence_unsafe_reasons(child));
            }
        }
        serde_json::Value::Array(items) => {
            for item in items {
                reasons.extend(paper_outcome_evidence_unsafe_reasons(item));
            }
        }
        serde_json::Value::String(text) => {
            let lower = text.to_ascii_lowercase();
            for prohibited in [
                "broker",
                "order",
                "account",
                "broker account",
                "trading account",
                "place order",
                "execute order",
                "live trade",
                "live trading",
                "real pnl",
                "pnl",
                "api key",
                "secret key",
            ] {
                if lower.contains(prohibited) {
                    reasons.push(format!(
                        "paper outcome evidence rejected unsafe claim: {prohibited}"
                    ));
                }
            }
        }
        _ => {}
    }
    reasons
}

fn paper_outcome_record_has_needs_review_note(record: &PaperOutcomeEvidenceRecord) -> bool {
    record.evidence_notes.iter().any(|note| {
        let lower = note.to_ascii_lowercase();
        lower.contains("needsreview")
            || lower.contains("needs review")
            || lower.contains("review required")
    }) || matches!(
        record.validation_hint,
        Some(PaperOutcomeEvidenceValidationHint::KeepReviewRequired)
    )
}

fn paper_outcome_evidence_price_change(record: &PaperOutcomeEvidenceRecord) -> Option<f64> {
    record.price_change_pct.or_else(|| {
        let reference = record.reference_price?;
        let horizon = record.horizon_price?;
        if reference.abs() <= f64::EPSILON {
            None
        } else {
            Some((horizon - reference) / reference)
        }
    })
}

fn paper_outcome_evidence_contradiction(
    record: &PaperOutcomeEvidenceRecord,
    policy: &PaperLabelValidationPolicy,
) -> bool {
    let Some(change) = paper_outcome_evidence_price_change(record) else {
        return false;
    };
    match record.candidate_label {
        MemberExperienceOutcome::PaperPositive => {
            change <= -policy.min_abs_price_move_pct_for_negative
        }
        MemberExperienceOutcome::PaperNegative
        | MemberExperienceOutcome::RiskVetoSavedLoss
        | MemberExperienceOutcome::BadRiskCall => {
            change >= policy.min_abs_price_move_pct_for_positive
        }
        _ => false,
    }
}

fn paper_outcome_record_to_label_evidence(
    record: &PaperOutcomeEvidenceRecord,
    policy: &PaperLabelValidationPolicy,
) -> LabelEvidenceRecord {
    let needs_review = paper_outcome_record_has_needs_review_note(record)
        || matches!(
            record.validation_hint,
            Some(PaperOutcomeEvidenceValidationHint::KeepReviewRequired)
        );
    let contradictory_needs_review =
        needs_review && paper_outcome_evidence_contradiction(record, policy);
    let confidence = match record.label_source {
        ReplayLabelSource::ReviewRequired => ReplayLabelConfidence::Medium,
        ReplayLabelSource::SimulatedFixture => ReplayLabelConfidence::Low,
        ReplayLabelSource::PaperBacktestDeferred => ReplayLabelConfidence::ReviewRequired,
        _ => record.label_confidence,
    };
    LabelEvidenceRecord {
        evidence_id: record.evidence_id.clone(),
        replay_id: record.replay_id.clone(),
        experience_id: record.experience_id.clone(),
        symbol: record.symbol.clone(),
        market_scope: record.market_scope,
        decision_id: record.decision_id.clone(),
        candidate_label: record.candidate_label,
        candidate_source: if needs_review {
            ReplayLabelSource::ReviewRequired
        } else {
            record.label_source
        },
        evidence_items: LabelEvidenceItems {
            price_move_evidence: if contradictory_needs_review {
                None
            } else {
                paper_outcome_evidence_price_change(record)
            },
            risk_veto_evidence: None,
            news_context_evidence: None,
            decision_trace_evidence: (!record.evidence_notes.is_empty())
                .then(|| record.evidence_notes.join(" | ")),
            paper_horizon_evidence: Some(format!(
                "{:?}:{}",
                record.horizon,
                record
                    .horizon_bars
                    .map(|bars| bars.to_string())
                    .unwrap_or_else(|| "unknown-bars".to_string())
            )),
        },
        validation_status: LabelEvidenceValidationStatus::Unchecked,
        confidence,
        validator_notes: record.evidence_notes.clone(),
        paper_only: record.paper_only,
    }
}

pub fn validate_paper_outcome_evidence_file(
    file: PaperOutcomeEvidenceFile,
) -> PaperOutcomeEvidenceLoadResult {
    let evidence_file_id = file.evidence_file_id.clone();
    let mut records = Vec::new();
    let mut rejected_records = Vec::new();
    let mut safety_warnings = Vec::new();
    let mut duplicate_count = 0;
    let mut seen_ids = std::collections::BTreeSet::new();
    let policy = PaperLabelValidationPolicy::default();

    if !file.paper_only {
        safety_warnings.push("paper outcome evidence file must be paper-only".to_string());
        rejected_records.extend(file.records);
        return PaperOutcomeEvidenceLoadResult {
            loaded: false,
            evidence_file_id,
            record_count: 0,
            rejected_count: rejected_records.len(),
            duplicate_count,
            records,
            rejected_records,
            safety_warnings,
            paper_only: true,
        };
    }

    for record in file.records {
        let record_value = serde_json::to_value(&record).unwrap_or(serde_json::Value::Null);
        let mut record_warnings = paper_outcome_evidence_unsafe_reasons(&record_value);
        if !record.paper_only {
            record_warnings.push(format!(
                "paper outcome evidence {} must be paper-only",
                record.evidence_id
            ));
        }
        if !matches!(
            record.label_source,
            ReplayLabelSource::ManualPaperLabel
                | ReplayLabelSource::PaperBacktestDeferred
                | ReplayLabelSource::ReviewRequired
                | ReplayLabelSource::SimulatedFixture
        ) {
            record_warnings.push(format!(
                "paper outcome evidence {} uses unsupported source {:?}",
                record.evidence_id, record.label_source
            ));
        }
        if !seen_ids.insert(record.evidence_id.clone()) {
            duplicate_count += 1;
            record_warnings.push(format!(
                "duplicate paper outcome evidence id {}",
                record.evidence_id
            ));
        }
        if paper_outcome_evidence_contradiction(&record, &policy)
            && !paper_outcome_record_has_needs_review_note(&record)
        {
            record_warnings.push(format!(
                "paper outcome evidence {} contradicts price movement",
                record.evidence_id
            ));
        }

        if record_warnings.is_empty() {
            records.push(record);
        } else {
            safety_warnings.extend(record_warnings);
            rejected_records.push(record);
        }
    }

    PaperOutcomeEvidenceLoadResult {
        loaded: true,
        evidence_file_id,
        record_count: records.len(),
        rejected_count: rejected_records.len(),
        duplicate_count,
        records,
        rejected_records,
        safety_warnings,
        paper_only: true,
    }
}

pub fn load_paper_outcome_evidence_from_local_json(
    path: &Path,
) -> Result<PaperOutcomeEvidenceLoadResult, String> {
    validate_local_json_path(path, "paper outcome evidence path")?;
    let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
    let value: serde_json::Value = serde_json::from_str(&text).map_err(|err| err.to_string())?;
    let mut file: PaperOutcomeEvidenceFile =
        serde_json::from_value(value.clone()).map_err(|err| err.to_string())?;
    let raw_records = value
        .get("records")
        .and_then(|records| records.as_array())
        .cloned()
        .unwrap_or_default();
    let mut pre_rejected = Vec::new();
    let mut pre_warnings = paper_outcome_evidence_unsafe_reasons(
        value
            .as_object()
            .map(|map| {
                let mut clone = map.clone();
                clone.remove("records");
                serde_json::Value::Object(clone)
            })
            .as_ref()
            .unwrap_or(&serde_json::Value::Null),
    );
    let mut safe_records = Vec::new();
    for raw_record in raw_records {
        let reasons = paper_outcome_evidence_unsafe_reasons(&raw_record);
        let parsed_record =
            serde_json::from_value::<PaperOutcomeEvidenceRecord>(raw_record.clone())
                .map_err(|err| err.to_string())?;
        if reasons.is_empty() {
            safe_records.push(parsed_record);
        } else {
            pre_warnings.extend(reasons);
            pre_rejected.push(parsed_record);
        }
    }
    file.records = safe_records;
    let mut result = validate_paper_outcome_evidence_file(file);
    result.rejected_count += pre_rejected.len();
    result.rejected_records.extend(pre_rejected);
    result.safety_warnings.extend(pre_warnings);
    Ok(result)
}

fn replay_example_experience_id(example: &ReplayExample) -> Option<String> {
    example
        .replay_id
        .strip_prefix("replay-")
        .map(|value| value.to_string())
}

fn unique_match<'a>(
    matches: Vec<&'a ReplayExample>,
) -> Result<Option<&'a ReplayExample>, PaperOutcomeEvidenceMatchConfidence> {
    match matches.len() {
        0 => Ok(None),
        1 => Ok(matches.first().copied()),
        _ => Err(PaperOutcomeEvidenceMatchConfidence::Low),
    }
}

pub fn match_paper_outcome_evidence_to_replay(
    dataset: &ReplayDataset,
    evidence_records: &[PaperOutcomeEvidenceRecord],
) -> PaperOutcomeEvidenceMatchingResult {
    let mut matches = Vec::new();
    let mut unmatched_evidence_ids = Vec::new();
    let mut ambiguous_evidence_ids = Vec::new();

    for evidence in evidence_records {
        let mut match_type = PaperOutcomeEvidenceMatchType::NoMatch;
        let mut match_confidence = PaperOutcomeEvidenceMatchConfidence::None;
        let mut matched_example: Option<&ReplayExample> = None;
        let mut ambiguous = false;

        if let Some(replay_id) = &evidence.replay_id {
            match unique_match(
                dataset
                    .examples
                    .iter()
                    .filter(|example| &example.replay_id == replay_id)
                    .collect(),
            ) {
                Ok(Some(example)) => {
                    matched_example = Some(example);
                    match_type = PaperOutcomeEvidenceMatchType::ReplayId;
                    match_confidence = PaperOutcomeEvidenceMatchConfidence::High;
                }
                Err(_) => ambiguous = true,
                Ok(None) => {}
            }
        }

        if matched_example.is_none() && !ambiguous {
            if let Some(experience_id) = &evidence.experience_id {
                match unique_match(
                    dataset
                        .examples
                        .iter()
                        .filter(|example| {
                            replay_example_experience_id(example)
                                .map(|value| value == *experience_id)
                                .unwrap_or(false)
                        })
                        .collect(),
                ) {
                    Ok(Some(example)) => {
                        matched_example = Some(example);
                        match_type = PaperOutcomeEvidenceMatchType::ExperienceId;
                        match_confidence = PaperOutcomeEvidenceMatchConfidence::High;
                    }
                    Err(_) => ambiguous = true,
                    Ok(None) => {}
                }
            }
        }

        if matched_example.is_none() && !ambiguous {
            if let Some(decision_id) = &evidence.decision_id {
                match unique_match(
                    dataset
                        .examples
                        .iter()
                        .filter(|example| {
                            &example.replay_id == decision_id
                                || replay_example_experience_id(example)
                                    .map(|value| value == *decision_id)
                                    .unwrap_or(false)
                        })
                        .collect(),
                ) {
                    Ok(Some(example)) => {
                        matched_example = Some(example);
                        match_type = PaperOutcomeEvidenceMatchType::DecisionId;
                        match_confidence = PaperOutcomeEvidenceMatchConfidence::Medium;
                    }
                    Err(_) => ambiguous = true,
                    Ok(None) => {}
                }
            }
        }

        if matched_example.is_none()
            && !ambiguous
            && !matches!(evidence.horizon, PaperOutcomeEvidenceHorizon::Unknown)
        {
            match unique_match(
                dataset
                    .examples
                    .iter()
                    .filter(|example| {
                        example.symbol == evidence.symbol
                            && example.market_scope == evidence.market_scope
                    })
                    .collect(),
            ) {
                Ok(Some(example)) => {
                    matched_example = Some(example);
                    match_type = PaperOutcomeEvidenceMatchType::SymbolScopeOnly;
                    match_confidence = PaperOutcomeEvidenceMatchConfidence::Low;
                }
                Err(_) => ambiguous = true,
                Ok(None) => {}
            }
        }

        if ambiguous {
            ambiguous_evidence_ids.push(evidence.evidence_id.clone());
            matches.push(PaperOutcomeEvidenceMatch {
                replay_id: String::new(),
                experience_id: evidence.experience_id.clone(),
                evidence_id: evidence.evidence_id.clone(),
                match_type: PaperOutcomeEvidenceMatchType::NoMatch,
                match_confidence: PaperOutcomeEvidenceMatchConfidence::None,
                paper_only: true,
            });
        } else if let Some(example) = matched_example {
            matches.push(PaperOutcomeEvidenceMatch {
                replay_id: example.replay_id.clone(),
                experience_id: replay_example_experience_id(example),
                evidence_id: evidence.evidence_id.clone(),
                match_type,
                match_confidence,
                paper_only: true,
            });
        } else {
            unmatched_evidence_ids.push(evidence.evidence_id.clone());
            matches.push(PaperOutcomeEvidenceMatch {
                replay_id: String::new(),
                experience_id: evidence.experience_id.clone(),
                evidence_id: evidence.evidence_id.clone(),
                match_type: PaperOutcomeEvidenceMatchType::NoMatch,
                match_confidence: PaperOutcomeEvidenceMatchConfidence::None,
                paper_only: true,
            });
        }
    }

    let matched_count = matches
        .iter()
        .filter(|item| item.match_type != PaperOutcomeEvidenceMatchType::NoMatch)
        .count();
    PaperOutcomeEvidenceMatchingResult {
        matched_count,
        unmatched_count: unmatched_evidence_ids.len(),
        ambiguous_count: ambiguous_evidence_ids.len(),
        matches,
        unmatched_evidence_ids,
        ambiguous_evidence_ids,
        paper_only: true,
    }
}

fn apply_promoted_label_metadata(
    example: &mut ReplayExample,
    evidence: &PaperOutcomeEvidenceRecord,
    source: ReplayLabelSource,
    confidence: ReplayLabelConfidence,
) {
    if example.target_labels.is_none() {
        example.target_labels = Some(ReplayTargetLabels {
            stance_target: example.target.stance,
            confidence_calibration_target: example.target.confidence_calibration,
            risk_label: example.target.risk_label.clone(),
            evidence_label: example.target.evidence_label.clone(),
            outcome_label: example.target.outcome_label,
            attribution_label: MemberScoreUpdateReason::Neutral,
            label_source: ReplayLabelSource::ReviewRequired,
            label_confidence: ReplayLabelConfidence::ReviewRequired,
            paper_only: true,
        });
    }
    if let Some(labels) = &mut example.target_labels {
        labels.outcome_label = evidence.candidate_label;
        labels.label_source = source;
        labels.label_confidence = confidence;
    }
}

pub fn promote_labels_with_paper_evidence(
    sanitized_dataset: &ReplayDataset,
    evidence_records: &[PaperOutcomeEvidenceRecord],
    policy: &PaperLabelValidationPolicy,
) -> Vec<ValidatedPaperEvidencePromotionResult> {
    build_validated_replay_dataset_with_paper_evidence(
        sanitized_dataset,
        evidence_records,
        policy,
        ValidatedReplayDatasetBuildConfig {
            source_sanitized_dataset_id: sanitized_dataset.dataset_id.clone(),
            label_validation_policy: policy.clone(),
            backtest_label_contract: None,
            require_validated_labels_for_training: true,
            allow_ready_with_warnings_for_medium_confidence: true,
            reject_rejected_labels: true,
            paper_only: true,
        },
    )
    .paper_evidence_promotion_results
}

pub fn build_validated_replay_dataset_with_paper_evidence(
    sanitized_dataset: &ReplayDataset,
    evidence_records: &[PaperOutcomeEvidenceRecord],
    policy: &PaperLabelValidationPolicy,
    config: ValidatedReplayDatasetBuildConfig,
) -> ValidatedReplayDatasetBuildResult {
    let matching_result =
        match_paper_outcome_evidence_to_replay(sanitized_dataset, evidence_records);
    let mut evidence_by_id = std::collections::BTreeMap::new();
    for evidence in evidence_records {
        evidence_by_id.insert(evidence.evidence_id.clone(), evidence.clone());
    }
    let ambiguous_ids: std::collections::BTreeSet<String> = matching_result
        .ambiguous_evidence_ids
        .iter()
        .cloned()
        .collect();
    let unmatched_ids: std::collections::BTreeSet<String> = matching_result
        .unmatched_evidence_ids
        .iter()
        .cloned()
        .collect();
    let mut evidence_by_replay_id = std::collections::BTreeMap::new();
    for item in &matching_result.matches {
        if item.match_type != PaperOutcomeEvidenceMatchType::NoMatch {
            if let Some(evidence) = evidence_by_id.get(&item.evidence_id) {
                evidence_by_replay_id.insert(item.replay_id.clone(), evidence.clone());
            }
        }
    }

    let mut examples = Vec::new();
    let mut label_evidence_records = Vec::new();
    let mut promotion_gates = Vec::new();
    let mut paper_evidence_promotion_results = Vec::new();
    let mut promoted_count = 0;
    let mut not_promoted_count = 0;
    let mut rejected_count = 0;
    let mut needs_review_count = 0;

    for evidence_id in &matching_result.unmatched_evidence_ids {
        if let Some(evidence) = evidence_by_id.get(evidence_id) {
            paper_evidence_promotion_results.push(ValidatedPaperEvidencePromotionResult {
                evidence_id: evidence.evidence_id.clone(),
                replay_id: None,
                original_label_source: evidence.label_source,
                original_confidence: evidence.label_confidence,
                promoted_label_source: evidence.label_source,
                promoted_confidence: evidence.label_confidence,
                promotion_status: ValidatedPaperEvidencePromotionStatus::NoMatch,
                reason: "paper outcome evidence did not match a replay example".to_string(),
                paper_only: true,
            });
        }
    }
    for evidence_id in &matching_result.ambiguous_evidence_ids {
        if let Some(evidence) = evidence_by_id.get(evidence_id) {
            paper_evidence_promotion_results.push(ValidatedPaperEvidencePromotionResult {
                evidence_id: evidence.evidence_id.clone(),
                replay_id: None,
                original_label_source: evidence.label_source,
                original_confidence: evidence.label_confidence,
                promoted_label_source: evidence.label_source,
                promoted_confidence: evidence.label_confidence,
                promotion_status: ValidatedPaperEvidencePromotionStatus::AmbiguousMatch,
                reason: "paper outcome evidence matched multiple replay examples".to_string(),
                paper_only: true,
            });
        }
    }

    for example in &sanitized_dataset.examples {
        let mut updated = example.clone();
        if let Some(evidence) = evidence_by_replay_id.get(&example.replay_id) {
            let label_evidence = paper_outcome_record_to_label_evidence(evidence, policy);
            let gate = evaluate_label_promotion(example, &label_evidence, policy);
            let promotion_status = match gate.promotion_status {
                LabelPromotionStatus::Promoted => {
                    promoted_count += 1;
                    apply_promoted_label_metadata(
                        &mut updated,
                        evidence,
                        gate.promoted_label_source,
                        gate.promoted_confidence,
                    );
                    ValidatedPaperEvidencePromotionStatus::Promoted
                }
                LabelPromotionStatus::Rejected => {
                    rejected_count += 1;
                    if !config.reject_rejected_labels {
                        apply_promoted_label_metadata(
                            &mut updated,
                            evidence,
                            ReplayLabelSource::RejectedLabel,
                            ReplayLabelConfidence::ReviewRequired,
                        );
                    }
                    ValidatedPaperEvidencePromotionStatus::Rejected
                }
                LabelPromotionStatus::NeedsReview => {
                    needs_review_count += 1;
                    apply_promoted_label_metadata(
                        &mut updated,
                        evidence,
                        ReplayLabelSource::ReviewRequired,
                        ReplayLabelConfidence::ReviewRequired,
                    );
                    ValidatedPaperEvidencePromotionStatus::NeedsReview
                }
                LabelPromotionStatus::NotPromoted => {
                    not_promoted_count += 1;
                    ValidatedPaperEvidencePromotionStatus::NotPromoted
                }
            };
            paper_evidence_promotion_results.push(ValidatedPaperEvidencePromotionResult {
                evidence_id: evidence.evidence_id.clone(),
                replay_id: Some(example.replay_id.clone()),
                original_label_source: gate.original_label_source,
                original_confidence: gate.original_confidence,
                promoted_label_source: gate.promoted_label_source,
                promoted_confidence: gate.promoted_confidence,
                promotion_status,
                reason: gate.reason.clone(),
                paper_only: true,
            });
            label_evidence_records.push(label_evidence);
            promotion_gates.push(gate);
            if matches!(
                promotion_status,
                ValidatedPaperEvidencePromotionStatus::Rejected
            ) && config.reject_rejected_labels
            {
                continue;
            }
        } else {
            needs_review_count += 1;
            if let Some(labels) = &mut updated.target_labels {
                labels.label_source = ReplayLabelSource::ReviewRequired;
                labels.label_confidence = ReplayLabelConfidence::ReviewRequired;
            }
        }
        examples.push(updated);
    }

    let dataset = ReplayDataset::new(
        format!("validated-evidence-{}", sanitized_dataset.dataset_id),
        sanitized_dataset.generated_from_store_id.clone(),
        examples,
    );
    let build_status = if dataset.examples.is_empty() {
        ValidatedReplayDatasetBuildStatus::Empty
    } else if rejected_count > 0 && config.reject_rejected_labels {
        ValidatedReplayDatasetBuildStatus::BlockedByRejectedLabels
    } else if config.require_validated_labels_for_training && promoted_count == 0 {
        ValidatedReplayDatasetBuildStatus::BlockedByWeakLabels
    } else if needs_review_count > 0 || not_promoted_count > 0 {
        ValidatedReplayDatasetBuildStatus::BuiltWithWarnings
    } else {
        ValidatedReplayDatasetBuildStatus::Built
    };

    ValidatedReplayDatasetBuildResult {
        dataset,
        label_evidence_records,
        promotion_gates,
        paper_evidence_matching_result: Some(matching_result.clone()),
        paper_evidence_promotion_results,
        promoted_count,
        not_promoted_count,
        rejected_count,
        needs_review_count,
        unmatched_evidence_count: unmatched_ids.len(),
        ambiguous_match_count: ambiguous_ids.len(),
        build_status,
        paper_only: true,
    }
}

pub fn summarize_paper_outcome_evidence_quality(
    load_result: &PaperOutcomeEvidenceLoadResult,
    matching_result: &PaperOutcomeEvidenceMatchingResult,
    promotion_results: &[ValidatedPaperEvidencePromotionResult],
) -> PaperOutcomeEvidenceQualitySummary {
    let mut source_distribution = std::collections::BTreeMap::new();
    let mut confidence_distribution = std::collections::BTreeMap::new();
    let mut label_distribution = std::collections::BTreeMap::new();
    for record in load_result
        .records
        .iter()
        .chain(load_result.rejected_records.iter())
    {
        *source_distribution
            .entry(format!("{:?}", record.label_source))
            .or_insert(0) += 1;
        *confidence_distribution
            .entry(format!("{:?}", record.label_confidence))
            .or_insert(0) += 1;
        *label_distribution
            .entry(format!("{:?}", record.candidate_label))
            .or_insert(0) += 1;
    }
    let promoted_records = promotion_results
        .iter()
        .filter(|result| result.promotion_status == ValidatedPaperEvidencePromotionStatus::Promoted)
        .count();
    let needs_review_records = promotion_results
        .iter()
        .filter(|result| {
            matches!(
                result.promotion_status,
                ValidatedPaperEvidencePromotionStatus::NeedsReview
                    | ValidatedPaperEvidencePromotionStatus::NoMatch
                    | ValidatedPaperEvidencePromotionStatus::AmbiguousMatch
            )
        })
        .count();
    let contradicted_records = load_result
        .safety_warnings
        .iter()
        .filter(|warning| warning.contains("contradicts"))
        .count()
        + promotion_results
            .iter()
            .filter(|result| {
                result.promotion_status == ValidatedPaperEvidencePromotionStatus::Rejected
            })
            .count();
    let mut candidate_evidence_ids = matching_result.unmatched_evidence_ids.clone();
    candidate_evidence_ids.extend(matching_result.ambiguous_evidence_ids.clone());
    candidate_evidence_ids.extend(promotion_results.iter().filter_map(|result| {
        matches!(
            result.promotion_status,
            ValidatedPaperEvidencePromotionStatus::NeedsReview
                | ValidatedPaperEvidencePromotionStatus::NoMatch
                | ValidatedPaperEvidencePromotionStatus::AmbiguousMatch
        )
        .then(|| result.evidence_id.clone())
    }));
    candidate_evidence_ids.sort();
    candidate_evidence_ids.dedup();
    let mut ambiguous_evidence_ids = matching_result.ambiguous_evidence_ids.clone();
    ambiguous_evidence_ids.sort();
    ambiguous_evidence_ids.dedup();
    let quality_status = if load_result.rejected_count > 0 || contradicted_records > 0 {
        LabelQualityStatus::Blocked
    } else if promoted_records >= 3 && matching_result.unmatched_count == 0 {
        LabelQualityStatus::Strong
    } else if promoted_records > 0 {
        LabelQualityStatus::Acceptable
    } else {
        LabelQualityStatus::Weak
    };
    let mut recommended_next_actions = Vec::new();
    if load_result.records.iter().any(|record| {
        paper_outcome_evidence_price_change(record).is_none()
            || record.reference_price.is_none()
            || record.horizon_price.is_none()
    }) {
        recommended_next_actions.push(RecommendedPaperEvidenceAction::AddPriceEvidence);
    }
    if matching_result.ambiguous_count > 0 {
        recommended_next_actions.push(RecommendedPaperEvidenceAction::ResolveAmbiguousMatches);
        recommended_next_actions.push(RecommendedPaperEvidenceAction::AddReplayIds);
    }
    if matching_result.unmatched_count > 0 {
        recommended_next_actions.push(RecommendedPaperEvidenceAction::AddDecisionIds);
        recommended_next_actions.push(RecommendedPaperEvidenceAction::AddReplayIds);
    }
    if contradicted_records > 0 {
        recommended_next_actions.push(RecommendedPaperEvidenceAction::ReviewContradictoryLabels);
    }
    if !label_distribution.contains_key("PaperNegative") {
        recommended_next_actions.push(RecommendedPaperEvidenceAction::AddMoreNegativeOutcomes);
    }
    if !label_distribution.contains_key("PaperPositive") {
        recommended_next_actions.push(RecommendedPaperEvidenceAction::AddMorePositiveOutcomes);
    }
    recommended_next_actions.push(RecommendedPaperEvidenceAction::AddBacktestEngine);
    recommended_next_actions.sort();
    recommended_next_actions.dedup();

    PaperOutcomeEvidenceQualitySummary {
        evidence_file_id: load_result.evidence_file_id.clone(),
        total_records: load_result.record_count + load_result.rejected_count,
        valid_records: load_result.record_count,
        rejected_records: load_result.rejected_count,
        matched_records: matching_result.matched_count,
        unmatched_records: matching_result.unmatched_count,
        ambiguous_records: matching_result.ambiguous_count,
        promoted_records,
        needs_review_records,
        contradicted_records,
        source_distribution,
        confidence_distribution,
        label_distribution,
        candidate_evidence_ids,
        ambiguous_evidence_ids,
        quality_status,
        recommended_next_actions,
        paper_only: true,
    }
}

fn evidence_resolution_rank(confidence: PaperOutcomeEvidenceMatchConfidence) -> u8 {
    match confidence {
        PaperOutcomeEvidenceMatchConfidence::None => 0,
        PaperOutcomeEvidenceMatchConfidence::Low => 1,
        PaperOutcomeEvidenceMatchConfidence::Medium => 2,
        PaperOutcomeEvidenceMatchConfidence::High => 3,
    }
}

fn evidence_summary_reason(
    evidence: &PaperOutcomeEvidenceRecord,
    ambiguous: bool,
) -> AmbiguousEvidenceReason {
    if matches!(evidence.horizon, PaperOutcomeEvidenceHorizon::Unknown) {
        AmbiguousEvidenceReason::UnknownHorizon
    } else if evidence.replay_id.is_none() {
        AmbiguousEvidenceReason::MissingReplayId
    } else if evidence.experience_id.is_none() {
        AmbiguousEvidenceReason::MissingExperienceId
    } else if evidence.decision_id.is_none() {
        AmbiguousEvidenceReason::MissingDecisionId
    } else if ambiguous {
        AmbiguousEvidenceReason::MultipleSymbolScopeMatches
    } else {
        AmbiguousEvidenceReason::NoCandidateReplay
    }
}

fn evidence_record_summary(
    evidence: &PaperOutcomeEvidenceRecord,
    ambiguous: bool,
    candidate_count: usize,
) -> AmbiguousEvidenceRecordSummary {
    AmbiguousEvidenceRecordSummary {
        evidence_id: evidence.evidence_id.clone(),
        symbol: evidence.symbol.clone(),
        market_scope: evidence.market_scope,
        horizon: evidence.horizon,
        decision_id: evidence.decision_id.clone(),
        replay_id: evidence.replay_id.clone(),
        experience_id: evidence.experience_id.clone(),
        ambiguity_reason: evidence_summary_reason(evidence, ambiguous),
        candidate_count,
        paper_only: true,
    }
}

pub fn build_ambiguous_evidence_inventory(
    matching_result: &PaperOutcomeEvidenceMatchingResult,
    evidence_records: &[PaperOutcomeEvidenceRecord],
) -> AmbiguousEvidenceInventory {
    let ambiguous_ids: std::collections::BTreeSet<&str> = matching_result
        .ambiguous_evidence_ids
        .iter()
        .map(String::as_str)
        .collect();
    let no_match_ids: std::collections::BTreeSet<&str> = matching_result
        .unmatched_evidence_ids
        .iter()
        .map(String::as_str)
        .collect();
    let mut ambiguous_records = Vec::new();
    let mut no_match_records = Vec::new();
    let mut missing_replay_id_count = 0;
    let mut missing_experience_id_count = 0;
    let mut missing_decision_id_count = 0;
    let mut unknown_horizon_count = 0;

    for evidence in evidence_records {
        if evidence.replay_id.is_none() {
            missing_replay_id_count += 1;
        }
        if evidence.experience_id.is_none() {
            missing_experience_id_count += 1;
        }
        if evidence.decision_id.is_none() {
            missing_decision_id_count += 1;
        }
        if matches!(evidence.horizon, PaperOutcomeEvidenceHorizon::Unknown) {
            unknown_horizon_count += 1;
        }
        if ambiguous_ids.contains(evidence.evidence_id.as_str()) {
            ambiguous_records.push(evidence_record_summary(evidence, true, 0));
        } else if no_match_ids.contains(evidence.evidence_id.as_str()) {
            no_match_records.push(evidence_record_summary(evidence, false, 0));
        }
    }

    AmbiguousEvidenceInventory {
        inventory_id: format!("ambiguous-evidence-{}", matching_result.matches.len()),
        total_evidence_count: evidence_records.len(),
        ambiguous_count: ambiguous_records.len(),
        no_match_count: no_match_records.len(),
        missing_replay_id_count,
        missing_experience_id_count,
        missing_decision_id_count,
        unknown_horizon_count,
        ambiguous_records,
        no_match_records,
        paper_only: true,
    }
}

fn evidence_candidate_from_example(
    evidence: &PaperOutcomeEvidenceRecord,
    example: &ReplayExample,
    experience_store: &MemberExperienceStore,
    match_type: PaperOutcomeEvidenceMatchType,
    match_confidence: PaperOutcomeEvidenceMatchConfidence,
) -> EvidenceMatchCandidate {
    let experience_id = replay_example_experience_id(example);
    let decision_id = experience_id.as_ref().and_then(|id| {
        experience_store
            .records
            .iter()
            .find(|record| &record.experience_id == id)
            .and_then(|record| record.decision_id.clone())
    });
    let label_compatible = example
        .target_labels
        .as_ref()
        .map(|labels| {
            labels.outcome_label == evidence.candidate_label
                || labels.label_source == ReplayLabelSource::ReviewRequired
        })
        .unwrap_or(true);
    EvidenceMatchCandidate {
        evidence_id: evidence.evidence_id.clone(),
        replay_id: Some(example.replay_id.clone()),
        experience_id,
        decision_id,
        symbol: example.symbol.clone(),
        market_scope: example.market_scope,
        horizon: Some(evidence.horizon),
        match_type,
        match_confidence,
        promotion_safe: label_compatible && match_type != PaperOutcomeEvidenceMatchType::NoMatch,
        unsafe_reason: (!label_compatible)
            .then(|| "candidate target label conflicts with paper outcome evidence".to_string()),
        paper_only: true,
    }
}

fn unique_example_candidates<'a>(
    examples: impl IntoIterator<Item = &'a ReplayExample>,
) -> Vec<&'a ReplayExample> {
    let mut by_id = std::collections::BTreeMap::new();
    for example in examples {
        by_id.entry(example.replay_id.clone()).or_insert(example);
    }
    by_id.into_values().collect()
}

pub fn generate_evidence_match_candidates(
    evidence: &PaperOutcomeEvidenceRecord,
    sanitized_dataset: &ReplayDataset,
    experience_store: &MemberExperienceStore,
) -> Vec<EvidenceMatchCandidate> {
    let mut candidates = Vec::new();

    if let Some(replay_id) = &evidence.replay_id {
        for example in unique_example_candidates(
            sanitized_dataset
                .examples
                .iter()
                .filter(|example| &example.replay_id == replay_id),
        ) {
            candidates.push(evidence_candidate_from_example(
                evidence,
                example,
                experience_store,
                PaperOutcomeEvidenceMatchType::ReplayId,
                PaperOutcomeEvidenceMatchConfidence::High,
            ));
        }
    }

    if let Some(experience_id) = &evidence.experience_id {
        for example in
            unique_example_candidates(sanitized_dataset.examples.iter().filter(|example| {
                replay_example_experience_id(example)
                    .map(|value| value == *experience_id)
                    .unwrap_or(false)
            }))
        {
            candidates.push(evidence_candidate_from_example(
                evidence,
                example,
                experience_store,
                PaperOutcomeEvidenceMatchType::ExperienceId,
                PaperOutcomeEvidenceMatchConfidence::High,
            ));
        }
    }

    if let Some(decision_id) = &evidence.decision_id {
        let experience_ids_for_decision: std::collections::BTreeSet<&str> = experience_store
            .records
            .iter()
            .filter(|record| record.decision_id.as_ref() == Some(decision_id))
            .map(|record| record.experience_id.as_str())
            .collect();
        for example in
            unique_example_candidates(sanitized_dataset.examples.iter().filter(|example| {
                &example.replay_id == decision_id
                    || replay_example_experience_id(example)
                        .map(|value| value == *decision_id)
                        .unwrap_or(false)
                    || replay_example_experience_id(example)
                        .map(|value| experience_ids_for_decision.contains(value.as_str()))
                        .unwrap_or(false)
            }))
        {
            candidates.push(evidence_candidate_from_example(
                evidence,
                example,
                experience_store,
                PaperOutcomeEvidenceMatchType::DecisionId,
                PaperOutcomeEvidenceMatchConfidence::Medium,
            ));
        }
    }

    if !matches!(evidence.horizon, PaperOutcomeEvidenceHorizon::Unknown) {
        for example in
            unique_example_candidates(sanitized_dataset.examples.iter().filter(|example| {
                example.symbol == evidence.symbol && example.market_scope == evidence.market_scope
            }))
        {
            candidates.push(evidence_candidate_from_example(
                evidence,
                example,
                experience_store,
                PaperOutcomeEvidenceMatchType::SymbolScopeOnly,
                PaperOutcomeEvidenceMatchConfidence::Low,
            ));
        }
    }

    let mut counts_by_type = std::collections::BTreeMap::new();
    for candidate in &candidates {
        *counts_by_type.entry(candidate.match_type).or_insert(0usize) += 1;
    }
    for candidate in &mut candidates {
        let type_count = counts_by_type
            .get(&candidate.match_type)
            .copied()
            .unwrap_or(0);
        if type_count > 1 {
            candidate.promotion_safe = false;
            candidate.unsafe_reason = Some("multiple candidates require manual review".to_string());
        }
        if candidate.match_type == PaperOutcomeEvidenceMatchType::DecisionId && type_count == 1 {
            candidate.match_confidence = PaperOutcomeEvidenceMatchConfidence::High;
        }
        if candidate.match_type == PaperOutcomeEvidenceMatchType::SymbolScopeOnly {
            if type_count == 1 {
                candidate.match_type = PaperOutcomeEvidenceMatchType::SymbolScopeHorizon;
                candidate.match_confidence = PaperOutcomeEvidenceMatchConfidence::Medium;
            } else {
                candidate.promotion_safe = false;
                candidate.unsafe_reason =
                    Some("symbol/scope-only fallback is unsafe by default".to_string());
            }
        }
    }

    candidates.sort_by(|left, right| {
        evidence_resolution_rank(right.match_confidence)
            .cmp(&evidence_resolution_rank(left.match_confidence))
            .then_with(|| left.replay_id.cmp(&right.replay_id))
            .then_with(|| format!("{:?}", left.match_type).cmp(&format!("{:?}", right.match_type)))
    });
    candidates.dedup_by(|left, right| {
        left.replay_id == right.replay_id && left.match_type == right.match_type
    });
    candidates
}

fn evidence_candidate_allowed(
    candidate: &EvidenceMatchCandidate,
    evidence: &PaperOutcomeEvidenceRecord,
    policy: &AmbiguousEvidenceResolutionPolicy,
) -> bool {
    if !candidate.promotion_safe {
        return false;
    }
    if evidence_resolution_rank(candidate.match_confidence)
        < evidence_resolution_rank(policy.min_match_confidence)
    {
        return false;
    }
    if policy.reject_unknown_horizon_fallback
        && matches!(evidence.horizon, PaperOutcomeEvidenceHorizon::Unknown)
        && matches!(
            candidate.match_type,
            PaperOutcomeEvidenceMatchType::SymbolScopeHorizon
                | PaperOutcomeEvidenceMatchType::SymbolScopeOnly
        )
    {
        return false;
    }
    match candidate.match_type {
        PaperOutcomeEvidenceMatchType::ReplayId => policy.allow_replay_id_resolution,
        PaperOutcomeEvidenceMatchType::ExperienceId => policy.allow_experience_id_resolution,
        PaperOutcomeEvidenceMatchType::DecisionId => policy.allow_decision_id_resolution,
        PaperOutcomeEvidenceMatchType::SymbolScopeHorizon => {
            policy.allow_unique_symbol_scope_horizon_resolution
        }
        PaperOutcomeEvidenceMatchType::SymbolScopeOnly => policy.allow_symbol_scope_only_resolution,
        PaperOutcomeEvidenceMatchType::NoMatch => false,
    }
}

pub fn resolve_ambiguous_evidence(
    inventory: &AmbiguousEvidenceInventory,
    evidence_records: &[PaperOutcomeEvidenceRecord],
    sanitized_dataset: &ReplayDataset,
    experience_store: &MemberExperienceStore,
    policy: &AmbiguousEvidenceResolutionPolicy,
) -> AmbiguousEvidenceResolutionResult {
    let evidence_by_id: std::collections::BTreeMap<&str, &PaperOutcomeEvidenceRecord> =
        evidence_records
            .iter()
            .map(|record| (record.evidence_id.as_str(), record))
            .collect();
    let mut target_ids: std::collections::BTreeSet<&str> = inventory
        .ambiguous_records
        .iter()
        .map(|record| record.evidence_id.as_str())
        .collect();
    target_ids.extend(
        inventory
            .no_match_records
            .iter()
            .map(|record| record.evidence_id.as_str()),
    );

    let mut resolved_suggestions = Vec::new();
    let mut unresolved_evidence_ids = Vec::new();
    let mut rejected_evidence_ids = Vec::new();

    for evidence_id in target_ids {
        let Some(evidence) = evidence_by_id.get(evidence_id) else {
            rejected_evidence_ids.push(evidence_id.to_string());
            continue;
        };
        let candidates =
            generate_evidence_match_candidates(evidence, sanitized_dataset, experience_store);
        let safe_candidates: Vec<&EvidenceMatchCandidate> = candidates
            .iter()
            .filter(|candidate| evidence_candidate_allowed(candidate, evidence, policy))
            .collect();
        if safe_candidates.is_empty() {
            unresolved_evidence_ids.push(evidence.evidence_id.clone());
            continue;
        }
        if policy.require_single_candidate && safe_candidates.len() != 1 {
            unresolved_evidence_ids.push(evidence.evidence_id.clone());
            continue;
        }
        let candidate = safe_candidates[0];
        let required_manual_confirmation = matches!(
            candidate.match_type,
            PaperOutcomeEvidenceMatchType::SymbolScopeHorizon
                | PaperOutcomeEvidenceMatchType::SymbolScopeOnly
        );
        resolved_suggestions.push(EvidenceResolutionSuggestion {
            evidence_id: evidence.evidence_id.clone(),
            suggested_replay_id: candidate.replay_id.clone(),
            suggested_experience_id: candidate.experience_id.clone(),
            suggested_decision_id: candidate.decision_id.clone(),
            suggested_match_type: candidate.match_type,
            suggested_confidence: candidate.match_confidence,
            promotion_safe_after_patch: candidate.promotion_safe,
            reason: format!(
                "safe local paper evidence backfill suggestion via {:?}",
                candidate.match_type
            ),
            required_manual_confirmation,
            paper_only: true,
        });
    }

    let safe_suggestion_count = resolved_suggestions
        .iter()
        .filter(|suggestion| {
            suggestion.promotion_safe_after_patch && !suggestion.required_manual_confirmation
        })
        .count();
    let manual_review_count = unresolved_evidence_ids.len()
        + resolved_suggestions
            .iter()
            .filter(|suggestion| suggestion.required_manual_confirmation)
            .count();
    let result_status = if !rejected_evidence_ids.is_empty() {
        AmbiguousEvidenceResolutionStatus::Blocked
    } else if resolved_suggestions.is_empty() {
        AmbiguousEvidenceResolutionStatus::NoSafeSuggestions
    } else if manual_review_count > 0 {
        AmbiguousEvidenceResolutionStatus::SuggestionsReadyWithWarnings
    } else {
        AmbiguousEvidenceResolutionStatus::SuggestionsReady
    };

    AmbiguousEvidenceResolutionResult {
        resolved_suggestions,
        unresolved_evidence_ids,
        rejected_evidence_ids,
        safe_suggestion_count,
        manual_review_count,
        result_status,
        paper_only: true,
    }
}

pub fn build_evidence_backfill_patch(
    evidence_file: &PaperOutcomeEvidenceFile,
    suggestions: &[EvidenceResolutionSuggestion],
) -> EvidenceBackfillPatch {
    let suggestions_by_id: std::collections::BTreeMap<&str, &EvidenceResolutionSuggestion> =
        suggestions
            .iter()
            .map(|suggestion| (suggestion.evidence_id.as_str(), suggestion))
            .collect();
    let mut suggestions_applied = Vec::new();
    let mut patched_records = Vec::new();
    let mut skipped_records = Vec::new();

    for record in &evidence_file.records {
        if let Some(suggestion) = suggestions_by_id.get(record.evidence_id.as_str()) {
            if suggestion.promotion_safe_after_patch && !suggestion.required_manual_confirmation {
                let mut patched = record.clone();
                if patched.replay_id.is_none() {
                    patched.replay_id = suggestion.suggested_replay_id.clone();
                }
                if patched.experience_id.is_none() {
                    patched.experience_id = suggestion.suggested_experience_id.clone();
                }
                if patched.decision_id.is_none() {
                    patched.decision_id = suggestion.suggested_decision_id.clone();
                }
                patched.evidence_notes.push(format!(
                    "backfilled by local resolver using {:?}",
                    suggestion.suggested_match_type
                ));
                patched_records.push(patched);
                suggestions_applied.push((*suggestion).clone());
            } else {
                skipped_records.push(record.clone());
            }
        } else {
            skipped_records.push(record.clone());
        }
    }

    EvidenceBackfillPatch {
        patch_id: format!("patch-{}", evidence_file.evidence_file_id),
        source_evidence_file_id: evidence_file.evidence_file_id.clone(),
        suggestions_applied,
        patched_records,
        skipped_records,
        paper_only: true,
    }
}

pub fn apply_evidence_backfill_patch_to_local_json(
    evidence_file: &PaperOutcomeEvidenceFile,
    patch: &EvidenceBackfillPatch,
    output_path: &str,
) -> Result<EvidenceBackfillPatchResult, String> {
    if !local_only(output_path) {
        return Err("evidence backfill output path must be local".to_string());
    }
    if path_has_parent_component(Path::new(output_path)) {
        return Err(
            "evidence backfill output path must not contain parent-directory traversal".to_string(),
        );
    }
    let mut records = patch.patched_records.clone();
    records.extend(patch.skipped_records.clone());
    records.sort_by(|left, right| left.evidence_id.cmp(&right.evidence_id));
    let output_file = PaperOutcomeEvidenceFile {
        schema_version: evidence_file.schema_version.clone(),
        evidence_file_id: format!("{}-backfilled", evidence_file.evidence_file_id),
        created_at: evidence_file.created_at.clone(),
        source_label: evidence_file.source_label.clone(),
        records,
        paper_only: true,
    };
    write_safe_json(Path::new(output_path), &output_file)?;
    Ok(EvidenceBackfillPatchResult {
        patch: patch.clone(),
        applied_count: patch.patched_records.len(),
        skipped_count: patch.skipped_records.len(),
        unsafe_skip_count: patch
            .suggestions_applied
            .iter()
            .filter(|suggestion| {
                !suggestion.promotion_safe_after_patch || suggestion.required_manual_confirmation
            })
            .count(),
        output_path: Some(output_path.to_string()),
        paper_only: true,
    })
}

pub fn build_validated_label_ratio_expansion_plan(
    validated_dataset: &ReplayDataset,
    evidence_quality_summary: &PaperOutcomeEvidenceQualitySummary,
    target_ratio: f64,
) -> ValidatedLabelRatioExpansionPlan {
    let current_total_examples = validated_dataset.examples.len();
    let current_validated_label_count = validated_dataset
        .examples
        .iter()
        .filter(|example| is_validated_replay_label(example))
        .count();
    let current_validated_label_ratio =
        ratio(current_validated_label_count, current_total_examples);
    let target_validated_label_ratio = target_ratio.clamp(0.0, 1.0);
    let target_count =
        ((current_total_examples as f64) * target_validated_label_ratio).ceil() as usize;
    let additional_validated_labels_needed =
        target_count.saturating_sub(current_validated_label_count);
    let candidate_evidence_ids = evidence_quality_summary.candidate_evidence_ids.clone();
    let mut priority_actions = Vec::new();
    if evidence_quality_summary.ambiguous_records > 0 {
        priority_actions.push(ValidatedLabelRatioExpansionAction::ResolveAmbiguousMatches);
        priority_actions.push(ValidatedLabelRatioExpansionAction::AddReplayIds);
    }
    if evidence_quality_summary.unmatched_records > 0 {
        priority_actions.push(ValidatedLabelRatioExpansionAction::AddDecisionIds);
        priority_actions.push(ValidatedLabelRatioExpansionAction::AddExperienceIds);
    }
    if additional_validated_labels_needed > 0 {
        priority_actions.push(ValidatedLabelRatioExpansionAction::AddPriceEvidence);
        priority_actions.push(ValidatedLabelRatioExpansionAction::AddPositiveOutcomeEvidence);
        priority_actions.push(ValidatedLabelRatioExpansionAction::AddNegativeOutcomeEvidence);
        priority_actions.push(ValidatedLabelRatioExpansionAction::AddNeutralOutcomeEvidence);
    }
    priority_actions.push(ValidatedLabelRatioExpansionAction::AddBacktestEngine);
    priority_actions.sort();
    priority_actions.dedup();
    ValidatedLabelRatioExpansionPlan {
        current_total_examples,
        current_validated_label_count,
        current_validated_label_ratio,
        target_validated_label_ratio,
        additional_validated_labels_needed,
        candidate_evidence_ids,
        ambiguous_evidence_ids: evidence_quality_summary.ambiguous_evidence_ids.clone(),
        suggested_new_evidence_count: additional_validated_labels_needed,
        priority_actions,
        paper_only: true,
    }
}

pub fn build_paper_evidence_expansion_batch(
    seeds: &[AdditionalPaperEvidenceSeed],
    _policy: &PaperLabelValidationPolicy,
) -> PaperEvidenceExpansionBatch {
    let mut generated_records = Vec::new();
    let mut rejected_count = 0;
    for seed in seeds {
        if !seed.paper_only {
            rejected_count += 1;
            continue;
        }
        if seed.label_source == ReplayLabelSource::SimulatedFixture
            && seed.label_confidence == ReplayLabelConfidence::High
        {
            rejected_count += 1;
            continue;
        }
        if let Some(change) = seed.price_change_pct {
            let contradictory = match seed.candidate_label {
                MemberExperienceOutcome::PaperPositive => change < 0.0,
                MemberExperienceOutcome::PaperNegative => change > 0.0,
                MemberExperienceOutcome::PaperNeutral => change.abs() > 0.03,
                _ => false,
            };
            if contradictory {
                rejected_count += 1;
                continue;
            }
        }
        let missing_price_evidence = seed.price_change_pct.is_none()
            || seed.reference_price.is_none()
            || seed.horizon_price.is_none();
        generated_records.push(PaperOutcomeEvidenceRecord {
            evidence_id: seed.seed_id.clone(),
            symbol: seed.symbol.clone(),
            market_scope: seed.market_scope,
            decision_id: seed.decision_id.clone(),
            event_id: None,
            replay_id: seed.replay_id.clone(),
            experience_id: seed.experience_id.clone(),
            horizon: seed.horizon,
            horizon_bars: None,
            reference_price: seed.reference_price,
            horizon_price: seed.horizon_price,
            price_change_pct: seed.price_change_pct,
            candidate_label: seed.candidate_label,
            label_source: if missing_price_evidence {
                ReplayLabelSource::ReviewRequired
            } else {
                seed.label_source
            },
            label_confidence: if missing_price_evidence {
                ReplayLabelConfidence::ReviewRequired
            } else {
                seed.label_confidence
            },
            evidence_notes: seed.evidence_notes.clone(),
            validation_hint: Some(PaperOutcomeEvidenceValidationHint::PromoteIfPolicyPasses),
            paper_only: true,
        });
    }
    PaperEvidenceExpansionBatch {
        batch_id: "paper-evidence-expansion-batch".to_string(),
        seeds: seeds.to_vec(),
        generated_count: generated_records.len(),
        rejected_count,
        generated_records,
        paper_only: true,
    }
}

pub fn run_evidence_backfill_and_promotion(
    config: &EvidenceBackfillAndPromotionRunConfig,
) -> Result<EvidenceBackfillAndPromotionRunResult, String> {
    let sanitized_dataset_path = config.sanitized_dataset_path.as_ref().ok_or_else(|| {
        "evidence backfill run requires sanitized_dataset_path when run without in-memory inputs"
            .to_string()
    })?;
    let sanitized_dataset = ReplayDataset::load_from_local_json(Path::new(sanitized_dataset_path))?;
    let experience_store = if let Some(path) = &config.experience_store_path {
        MemberExperienceStore::load_from_local_json(Path::new(path))?
    } else {
        MemberExperienceStore::new("evidence-backfill-empty-experience-store", Vec::new())
    };
    run_evidence_backfill_and_promotion_with_inputs(
        config,
        &sanitized_dataset,
        &experience_store,
        &PaperLabelValidationPolicy::default(),
    )
}

pub fn run_evidence_backfill_and_promotion_with_inputs(
    config: &EvidenceBackfillAndPromotionRunConfig,
    sanitized_dataset: &ReplayDataset,
    experience_store: &MemberExperienceStore,
    policy: &PaperLabelValidationPolicy,
) -> Result<EvidenceBackfillAndPromotionRunResult, String> {
    let load_result =
        load_paper_outcome_evidence_from_local_json(Path::new(&config.evidence_input_path))?;
    let evidence_file = PaperOutcomeEvidenceFile {
        schema_version: "soma.paper_outcome_evidence.v1".to_string(),
        evidence_file_id: load_result.evidence_file_id.clone(),
        created_at: None,
        source_label: "loaded-valid-paper-evidence".to_string(),
        records: load_result.records.clone(),
        paper_only: true,
    };
    let matching_result =
        match_paper_outcome_evidence_to_replay(sanitized_dataset, &load_result.records);
    let ambiguous_inventory =
        build_ambiguous_evidence_inventory(&matching_result, &load_result.records);
    let resolution_result = resolve_ambiguous_evidence(
        &ambiguous_inventory,
        &load_result.records,
        sanitized_dataset,
        experience_store,
        &AmbiguousEvidenceResolutionPolicy::default(),
    );
    let patch =
        build_evidence_backfill_patch(&evidence_file, &resolution_result.resolved_suggestions);
    let patch_applied = config.apply_backfill_patch
        && !config.dry_run
        && config.evidence_backfill_output_path.is_some();
    let patch_result = if let Some(path) = &config.evidence_backfill_output_path {
        if patch_applied {
            Some(apply_evidence_backfill_patch_to_local_json(
                &evidence_file,
                &patch,
                path,
            )?)
        } else {
            Some(EvidenceBackfillPatchResult {
                applied_count: 0,
                skipped_count: evidence_file.records.len(),
                unsafe_skip_count: resolution_result.manual_review_count,
                output_path: None,
                patch,
                paper_only: true,
            })
        }
    } else {
        None
    };
    let effective_records = patch_result
        .as_ref()
        .filter(|_| patch_applied)
        .map(|result| {
            let mut records = result.patch.patched_records.clone();
            records.extend(result.patch.skipped_records.clone());
            records
        })
        .unwrap_or_else(|| load_result.records.clone());
    let validated_build_result = config.rebuild_validated_dataset.then(|| {
        build_validated_replay_dataset_with_paper_evidence(
            sanitized_dataset,
            &effective_records,
            policy,
            ValidatedReplayDatasetBuildConfig {
                source_sanitized_dataset_id: sanitized_dataset.dataset_id.clone(),
                label_validation_policy: policy.clone(),
                backtest_label_contract: None,
                require_validated_labels_for_training: true,
                allow_ready_with_warnings_for_medium_confidence: true,
                reject_rejected_labels: true,
                paper_only: true,
            },
        )
    });
    if let (Some(path), Some(build_result)) = (
        config.validated_replay_output_path.as_ref(),
        validated_build_result.as_ref(),
    ) {
        write_safe_json(Path::new(path), build_result)?;
    }
    let label_quality_summary = validated_build_result.as_ref().map(summarize_label_quality);
    if let (Some(path), Some(summary)) = (
        config.label_quality_output_path.as_ref(),
        label_quality_summary.as_ref(),
    ) {
        write_safe_json(Path::new(path), summary)?;
    }
    let evidence_quality_summary =
        summarize_paper_outcome_evidence_quality(&load_result, &matching_result, &[]);
    let expansion_plan = build_validated_label_ratio_expansion_plan(
        validated_build_result
            .as_ref()
            .map(|result| &result.dataset)
            .unwrap_or(sanitized_dataset),
        &evidence_quality_summary,
        config.min_validated_label_ratio_required,
    );
    let readiness_gate = validated_build_result.as_ref().map(|build_result| {
        let mut gate = evaluate_offline_training_readiness_with_label_ratio_threshold(
            &build_result.dataset,
            experience_store,
            1,
            0,
            config.min_validated_label_ratio_required,
        );
        gate.readiness_status = match gate.readiness_status {
            OfflineTrainingReadinessStatus::ReadyForOfflineTraining => {
                OfflineTrainingReadinessStatus::ReadyForOfflineTrainingDesign
            }
            OfflineTrainingReadinessStatus::ReadyWithWarnings => {
                OfflineTrainingReadinessStatus::ReadyWithWarningsForOfflineTrainingDesign
            }
            other => other,
        };
        gate
    });
    Ok(EvidenceBackfillAndPromotionRunResult {
        ambiguous_inventory,
        resolution_result,
        patch_result,
        expansion_plan,
        validated_build_result,
        label_quality_summary,
        readiness_gate,
        safety_summary: safety_summary(),
        paper_only: true,
    })
}

fn replay_evidence_horizon_for_scope(market_scope: MarketScope) -> PaperOutcomeEvidenceHorizon {
    match market_scope {
        MarketScope::KoreaShortTerm | MarketScope::UsShortTerm | MarketScope::CryptoShortTerm => {
            PaperOutcomeEvidenceHorizon::ShortTerm
        }
        MarketScope::KoreaLongTerm | MarketScope::UsLongTerm | MarketScope::CryptoLongTerm => {
            PaperOutcomeEvidenceHorizon::LongTerm
        }
    }
}

fn replay_example_decision_id(
    example: &ReplayExample,
    experience_store: &MemberExperienceStore,
) -> Option<String> {
    let experience_id = replay_example_experience_id(example)?;
    experience_store
        .records
        .iter()
        .find(|record| record.experience_id == experience_id)
        .and_then(|record| record.decision_id.clone())
}

fn validate_optional_local_json_path(path: Option<&String>, label: &str) -> Result<(), String> {
    if let Some(path) = path {
        validate_local_json_path(Path::new(path), label)?;
    }
    Ok(())
}

pub fn build_replay_evidence_workbench(
    dataset: &ReplayDataset,
    experience_store: &MemberExperienceStore,
    existing_evidence: &[PaperOutcomeEvidenceRecord],
    config: &ReplayEvidenceWorkbenchConfig,
) -> ReplayEvidenceWorkbench {
    let existing_matching = match_paper_outcome_evidence_to_replay(dataset, existing_evidence);
    let evidence_by_id: std::collections::BTreeMap<&str, &PaperOutcomeEvidenceRecord> =
        existing_evidence
            .iter()
            .map(|record| (record.evidence_id.as_str(), record))
            .collect();
    let mut evidenced_replay_ids: std::collections::BTreeSet<String> = existing_evidence
        .iter()
        .filter_map(|record| record.replay_id.clone())
        .collect();
    for item in &existing_matching.matches {
        if item.match_type != PaperOutcomeEvidenceMatchType::NoMatch {
            evidenced_replay_ids.insert(item.replay_id.clone());
        }
    }
    let ambiguous_symbol_scopes: std::collections::BTreeSet<(String, MarketScope)> =
        existing_matching
            .ambiguous_evidence_ids
            .iter()
            .filter_map(|evidence_id| evidence_by_id.get(evidence_id.as_str()))
            .map(|record| (record.symbol.clone(), record.market_scope))
            .collect();

    let mut draft_rows = Vec::new();
    for example in &dataset.examples {
        let current_label_source = replay_label_source_for_example(example);
        let current_label_confidence = replay_label_confidence_for_example(example);
        let current_outcome_label = example
            .target_labels
            .as_ref()
            .map(|labels| labels.outcome_label)
            .unwrap_or(example.target.outcome_label);
        let needs_evidence = !is_validated_replay_label(example);
        if config.include_only_unvalidated && !needs_evidence {
            continue;
        }
        if !config.include_review_required
            && current_label_source == ReplayLabelSource::ReviewRequired
        {
            continue;
        }
        let is_ambiguous = current_label_source == ReplayLabelSource::AmbiguousLabel
            || ambiguous_symbol_scopes.contains(&(example.symbol.clone(), example.market_scope));
        if is_ambiguous && !config.include_ambiguous {
            continue;
        }
        if evidenced_replay_ids.contains(&example.replay_id) && !is_ambiguous {
            continue;
        }
        let experience_id = replay_example_experience_id(example);
        let decision_id = replay_example_decision_id(example, experience_store);
        let suggested_evidence_type = if example.replay_id.trim().is_empty() {
            ReplayEvidenceType::NeedsReplayId
        } else if current_label_source == ReplayLabelSource::PaperBacktestDeferred {
            ReplayEvidenceType::BacktestDeferred
        } else if current_label_source == ReplayLabelSource::AmbiguousLabel || is_ambiguous {
            ReplayEvidenceType::ManualPaperReview
        } else if decision_id.is_none() {
            ReplayEvidenceType::NeedsDecisionId
        } else if experience_id.is_none() {
            ReplayEvidenceType::NeedsExperienceId
        } else {
            ReplayEvidenceType::PriceMove
        };
        draft_rows.push(ReplayEvidenceDraftRow {
            draft_id: format!("{}-draft-{}", config.workbench_id, example.replay_id),
            replay_id: example.replay_id.clone(),
            experience_id,
            decision_id,
            member_id: example.member_id.clone(),
            symbol: example.symbol.clone(),
            market_scope: example.market_scope,
            horizon: replay_evidence_horizon_for_scope(example.market_scope),
            current_label_source,
            current_label_confidence,
            current_outcome_label,
            needs_evidence,
            suggested_evidence_type,
            paper_only: true,
        });
    }
    draft_rows.sort_by(|left, right| {
        left.replay_id
            .cmp(&right.replay_id)
            .then_with(|| left.member_id.cmp(&right.member_id))
    });
    draft_rows.truncate(config.max_drafts);
    let draft_count = draft_rows.len();
    let unvalidated_count = draft_rows.iter().filter(|row| row.needs_evidence).count();
    let review_required_count = draft_rows
        .iter()
        .filter(|row| row.current_label_source == ReplayLabelSource::ReviewRequired)
        .count();
    let ambiguous_count = draft_rows
        .iter()
        .filter(|row| {
            row.current_label_source == ReplayLabelSource::AmbiguousLabel
                || row.suggested_evidence_type == ReplayEvidenceType::ManualPaperReview
        })
        .count();
    let current_validated_label_count = dataset
        .examples
        .iter()
        .filter(|example| is_validated_replay_label(example))
        .count();
    let target_validated_count = ((dataset.examples.len() as f64)
        * config.target_validated_label_ratio.clamp(0.0, 1.0))
    .ceil() as usize;

    ReplayEvidenceWorkbench {
        workbench_id: config.workbench_id.clone(),
        draft_rows,
        draft_count,
        unvalidated_count,
        review_required_count,
        ambiguous_count,
        target_validated_label_ratio: config.target_validated_label_ratio.clamp(0.0, 1.0),
        additional_validated_labels_needed: target_validated_count
            .saturating_sub(current_validated_label_count),
        paper_only: true,
    }
}

fn normalize_price_series_store(mut store: PaperPriceSeriesStore) -> PaperPriceSeriesStore {
    for series in &mut store.series {
        series
            .bars
            .sort_by(|left, right| left.timestamp.cmp(&right.timestamp));
    }
    store.series.sort_by(|left, right| {
        left.symbol.cmp(&right.symbol).then_with(|| {
            format!("{:?}", left.market_scope).cmp(&format!("{:?}", right.market_scope))
        })
    });
    store
}

fn paper_price_series_unsafe_reasons(value: &serde_json::Value) -> Vec<String> {
    let mut reasons = Vec::new();
    match value {
        serde_json::Value::Object(map) => {
            for (key, child) in map {
                let lower = key.to_ascii_lowercase();
                for prohibited in [
                    "order",
                    "account",
                    "broker",
                    "execution",
                    "real_trade",
                    "position_size",
                    "quantity",
                    "holdings",
                    "buying_power",
                    "live_trade",
                    "real_pnl",
                    "pnl",
                    "api_key",
                    "secret",
                ] {
                    if lower.contains(prohibited) {
                        reasons.push(format!("paper price series rejected unsafe field: {key}"));
                    }
                }
                reasons.extend(paper_price_series_unsafe_reasons(child));
            }
        }
        serde_json::Value::Array(items) => {
            for item in items {
                reasons.extend(paper_price_series_unsafe_reasons(item));
            }
        }
        serde_json::Value::String(text) => {
            let lower = text.to_ascii_lowercase();
            for prohibited in [
                "broker",
                "order",
                "account",
                "broker account",
                "trading account",
                "place order",
                "execute order",
                "live trade",
                "live trading",
                "real pnl",
                "pnl",
                "api key",
                "secret key",
            ] {
                if lower.contains(prohibited) {
                    reasons.push(format!(
                        "paper price series rejected unsafe claim: {prohibited}"
                    ));
                }
            }
        }
        _ => {}
    }
    reasons
}

fn validate_price_series_store(
    store: &PaperPriceSeriesStore,
    raw_value: Option<&serde_json::Value>,
) -> Result<(), String> {
    if let Some(value) = raw_value {
        let reasons = paper_price_series_unsafe_reasons(value);
        if let Some(reason) = reasons.first() {
            return Err(reason.clone());
        }
    }
    if !store.paper_only {
        return Err("paper price series store must be paper-only".to_string());
    }
    for series in &store.series {
        if !series.paper_only {
            return Err("paper price series contents must be paper-only".to_string());
        }
        if series.symbol.trim().is_empty() {
            return Err("paper price series symbol is required".to_string());
        }
        for bar in &series.bars {
            if !bar.paper_only {
                return Err("paper price series bars must be paper-only".to_string());
            }
            if bar.symbol != series.symbol || bar.market_scope != series.market_scope {
                return Err(
                    "paper price series bar symbol/scope must match parent series".to_string(),
                );
            }
            if !bar.close.is_finite() {
                return Err("paper price series close must be finite".to_string());
            }
        }
    }
    Ok(())
}

impl PaperPriceSeriesStore {
    pub fn series_for_symbol_scope(
        &self,
        symbol: &str,
        market_scope: MarketScope,
    ) -> Option<&PaperPriceSeries> {
        self.series
            .iter()
            .find(|series| series.symbol == symbol && series.market_scope == market_scope)
    }
}

pub fn load_price_series_store_from_local_json(
    path: &Path,
) -> Result<PaperPriceSeriesStore, String> {
    validate_local_json_path(path, "paper price series path")?;
    let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
    let value: serde_json::Value = serde_json::from_str(&text).map_err(|err| err.to_string())?;
    let store: PaperPriceSeriesStore =
        serde_json::from_value(value.clone()).map_err(|err| err.to_string())?;
    validate_price_series_store(&store, Some(&value))?;
    Ok(normalize_price_series_store(store))
}

pub fn save_price_series_store_to_local_json(
    store: &PaperPriceSeriesStore,
    path: &Path,
) -> Result<(), String> {
    validate_local_json_path(path, "paper price series output path")?;
    validate_price_series_store(store, None)?;
    write_safe_json(path, &normalize_price_series_store(store.clone()))
}

fn price_horizon_bars(horizon: PaperOutcomeEvidenceHorizon) -> Option<u32> {
    match horizon {
        PaperOutcomeEvidenceHorizon::Intraday => Some(1),
        PaperOutcomeEvidenceHorizon::ShortTerm => Some(2),
        PaperOutcomeEvidenceHorizon::Swing => Some(3),
        PaperOutcomeEvidenceHorizon::LongTerm => Some(4),
        PaperOutcomeEvidenceHorizon::Unknown => None,
    }
}

pub fn find_reference_and_horizon_price(
    price_series_store: &PaperPriceSeriesStore,
    symbol: &str,
    market_scope: MarketScope,
    horizon: PaperOutcomeEvidenceHorizon,
    decision_timestamp: Option<&str>,
) -> Option<(f64, f64, u32)> {
    let horizon_bars = price_horizon_bars(horizon)?;
    let series = price_series_store.series_for_symbol_scope(symbol, market_scope)?;
    if series.bars.is_empty() {
        return None;
    }
    let start_index = decision_timestamp
        .and_then(|timestamp| {
            series
                .bars
                .iter()
                .position(|bar| bar.timestamp.as_str() >= timestamp)
        })
        .unwrap_or(0);
    let horizon_index = start_index + horizon_bars as usize;
    if horizon_index >= series.bars.len() {
        return None;
    }
    Some((
        series.bars[start_index].close,
        series.bars[horizon_index].close,
        horizon_bars,
    ))
}

pub fn generate_price_move_label_candidates(
    workbench: &ReplayEvidenceWorkbench,
    price_series_store: &PaperPriceSeriesStore,
    policy: &PaperPriceMoveLabelPolicy,
) -> PaperPriceMoveLabelResult {
    let mut candidates = Vec::new();
    let mut rejected_drafts = Vec::new();
    let mut needs_review_count = 0;

    for draft in &workbench.draft_rows {
        if !draft.paper_only {
            rejected_drafts.push(draft.clone());
            continue;
        }
        let effective_horizon = if draft.horizon == PaperOutcomeEvidenceHorizon::Unknown {
            if policy.allow_unknown_horizon {
                policy.horizon
            } else {
                PaperOutcomeEvidenceHorizon::Unknown
            }
        } else {
            draft.horizon
        };
        let mut evidence_notes = vec![format!(
            "local paper price series candidate for replay {}",
            draft.replay_id
        )];
        let (reference_price, horizon_price, price_change_pct, label_confidence, candidate_label) =
            if effective_horizon == PaperOutcomeEvidenceHorizon::Unknown {
                evidence_notes
                    .push("unknown horizon cannot validate deterministic price move".to_string());
                needs_review_count += 1;
                (
                    None,
                    None,
                    None,
                    ReplayLabelConfidence::ReviewRequired,
                    MemberExperienceOutcome::Unknown,
                )
            } else if let Some((reference_price, horizon_price, horizon_bars)) =
                find_reference_and_horizon_price(
                    price_series_store,
                    &draft.symbol,
                    draft.market_scope,
                    effective_horizon,
                    None,
                )
            {
                let change = if reference_price.abs() <= f64::EPSILON {
                    None
                } else {
                    Some((horizon_price - reference_price) / reference_price)
                };
                evidence_notes.push(format!(
                    "deterministic local price move over {} bars",
                    horizon_bars
                ));
                match change {
                    Some(change) if horizon_bars >= policy.min_bars_required => {
                        let candidate_label = if change >= policy.positive_threshold_pct {
                            MemberExperienceOutcome::PaperPositive
                        } else if change <= policy.negative_threshold_pct {
                            MemberExperienceOutcome::PaperNegative
                        } else if change.abs() <= policy.neutral_band_pct {
                            MemberExperienceOutcome::PaperNeutral
                        } else {
                            MemberExperienceOutcome::Unknown
                        };
                        let confidence = if candidate_label == MemberExperienceOutcome::Unknown {
                            needs_review_count += 1;
                            ReplayLabelConfidence::Low
                        } else {
                            ReplayLabelConfidence::Medium
                        };
                        (
                            Some(reference_price),
                            Some(horizon_price),
                            Some(change),
                            confidence,
                            candidate_label,
                        )
                    }
                    _ => {
                        evidence_notes
                            .push("insufficient local bars for deterministic label".to_string());
                        needs_review_count += 1;
                        (
                            Some(reference_price),
                            Some(horizon_price),
                            change,
                            ReplayLabelConfidence::ReviewRequired,
                            MemberExperienceOutcome::Unknown,
                        )
                    }
                }
            } else {
                evidence_notes
                    .push("missing local price series for symbol/scope horizon".to_string());
                needs_review_count += 1;
                (
                    None,
                    None,
                    None,
                    ReplayLabelConfidence::ReviewRequired,
                    MemberExperienceOutcome::Unknown,
                )
            };
        candidates.push(PaperPriceMoveLabelCandidate {
            candidate_id: format!("candidate-{}", draft.draft_id),
            replay_id: draft.replay_id.clone(),
            experience_id: draft.experience_id.clone(),
            decision_id: draft.decision_id.clone(),
            symbol: draft.symbol.clone(),
            market_scope: draft.market_scope,
            reference_price,
            horizon_price,
            price_change_pct,
            candidate_label,
            label_confidence,
            evidence_notes,
            paper_only: true,
        });
    }

    PaperPriceMoveLabelResult {
        generated_count: candidates.len(),
        needs_review_count,
        rejected_count: rejected_drafts.len(),
        candidates,
        rejected_drafts,
        paper_only: true,
    }
}

pub fn build_paper_evidence_records_from_price_move_candidates(
    candidates: &[PaperPriceMoveLabelCandidate],
) -> GeneratedPaperEvidenceBatch {
    let source_workbench_id = candidates
        .first()
        .and_then(|candidate| {
            candidate
                .candidate_id
                .strip_prefix("candidate-")
                .and_then(|value| value.split("-draft-").next())
                .map(str::to_string)
        })
        .unwrap_or_else(|| "replay-evidence-workbench".to_string());
    let mut generated_records = Vec::new();
    let mut needs_review_count = 0;
    let mut rejected_count = 0;

    for candidate in candidates {
        if !candidate.paper_only {
            rejected_count += 1;
            continue;
        }
        let needs_review = candidate.candidate_label == MemberExperienceOutcome::Unknown
            || matches!(
                candidate.label_confidence,
                ReplayLabelConfidence::Low | ReplayLabelConfidence::ReviewRequired
            );
        if needs_review {
            needs_review_count += 1;
        }
        generated_records.push(PaperOutcomeEvidenceRecord {
            evidence_id: candidate.candidate_id.clone(),
            symbol: candidate.symbol.clone(),
            market_scope: candidate.market_scope,
            decision_id: candidate.decision_id.clone(),
            event_id: None,
            replay_id: Some(candidate.replay_id.clone()),
            experience_id: candidate.experience_id.clone(),
            horizon: replay_evidence_horizon_for_scope(candidate.market_scope),
            horizon_bars: price_horizon_bars(replay_evidence_horizon_for_scope(
                candidate.market_scope,
            )),
            reference_price: candidate.reference_price,
            horizon_price: candidate.horizon_price,
            price_change_pct: candidate.price_change_pct,
            candidate_label: candidate.candidate_label,
            label_source: if needs_review {
                ReplayLabelSource::ReviewRequired
            } else {
                ReplayLabelSource::ManualPaperLabel
            },
            label_confidence: if needs_review {
                ReplayLabelConfidence::ReviewRequired
            } else {
                candidate.label_confidence
            },
            evidence_notes: candidate.evidence_notes.clone(),
            validation_hint: Some(if needs_review {
                PaperOutcomeEvidenceValidationHint::KeepReviewRequired
            } else {
                PaperOutcomeEvidenceValidationHint::PromoteIfPolicyPasses
            }),
            paper_only: true,
        });
    }

    GeneratedPaperEvidenceBatch {
        batch_id: format!("generated-paper-evidence-{}", source_workbench_id),
        source_workbench_id,
        generated_count: generated_records.len(),
        needs_review_count,
        rejected_count,
        generated_records,
        paper_only: true,
    }
}

fn offline_training_design_status_for_readiness(
    readiness_status: OfflineTrainingReadinessStatus,
) -> OfflineTrainingDesignStatus {
    match readiness_status {
        OfflineTrainingReadinessStatus::ReadyForOfflineTraining
        | OfflineTrainingReadinessStatus::ReadyForOfflineTrainingDesign => {
            OfflineTrainingDesignStatus::ReadyForDesign
        }
        OfflineTrainingReadinessStatus::ReadyWithWarnings
        | OfflineTrainingReadinessStatus::ReadyWithWarningsForOfflineTrainingDesign => {
            OfflineTrainingDesignStatus::ReadyWithWarnings
        }
        OfflineTrainingReadinessStatus::BlockedByLeakage
        | OfflineTrainingReadinessStatus::BlockedBySafety => {
            OfflineTrainingDesignStatus::BlockedBySafety
        }
        OfflineTrainingReadinessStatus::NeedsMoreData
        | OfflineTrainingReadinessStatus::TrainingDeferred => {
            OfflineTrainingDesignStatus::NeedsMoreValidatedCoverage
        }
    }
}

fn normalize_offline_training_design_readiness(gate: &mut OfflineTrainingReadinessGate) {
    gate.readiness_status = match gate.readiness_status {
        OfflineTrainingReadinessStatus::ReadyForOfflineTraining => {
            OfflineTrainingReadinessStatus::ReadyForOfflineTrainingDesign
        }
        OfflineTrainingReadinessStatus::ReadyWithWarnings => {
            OfflineTrainingReadinessStatus::ReadyWithWarningsForOfflineTrainingDesign
        }
        other => other,
    };
    gate.offline_training_design_status =
        offline_training_design_status_for_readiness(gate.readiness_status);
}

pub fn run_validated_ratio_expansion(
    config: &ValidatedRatioExpansionRunConfig,
) -> Result<ValidatedRatioExpansionRunResult, String> {
    let sanitized_dataset_path = config
        .sanitized_dataset_path
        .as_ref()
        .ok_or_else(|| "validated ratio expansion requires sanitized_dataset_path".to_string())?;
    let price_series_path = config
        .price_series_path
        .as_ref()
        .ok_or_else(|| "validated ratio expansion requires price_series_path".to_string())?;
    let sanitized_dataset = ReplayDataset::load_from_local_json(Path::new(sanitized_dataset_path))?;
    let experience_store = if let Some(path) = &config.experience_store_path {
        MemberExperienceStore::load_from_local_json(Path::new(path))?
    } else {
        MemberExperienceStore::new("validated-ratio-expansion-empty-store", Vec::new())
    };
    let existing_evidence = if let Some(path) = &config.existing_evidence_path {
        load_paper_outcome_evidence_from_local_json(Path::new(path))?.records
    } else {
        Vec::new()
    };
    let price_series_store = load_price_series_store_from_local_json(Path::new(price_series_path))?;
    run_validated_ratio_expansion_with_inputs(
        config,
        &sanitized_dataset,
        &experience_store,
        &existing_evidence,
        &price_series_store,
        &PaperLabelValidationPolicy::default(),
    )
}

pub fn run_validated_ratio_expansion_with_inputs(
    config: &ValidatedRatioExpansionRunConfig,
    sanitized_dataset: &ReplayDataset,
    experience_store: &MemberExperienceStore,
    existing_evidence: &[PaperOutcomeEvidenceRecord],
    price_series_store: &PaperPriceSeriesStore,
    label_validation_policy: &PaperLabelValidationPolicy,
) -> Result<ValidatedRatioExpansionRunResult, String> {
    if !config.paper_only {
        return Err("validated ratio expansion run must be paper-only".to_string());
    }
    validate_price_series_store(price_series_store, None)?;
    if !(0.0..=1.0).contains(&config.target_validated_label_ratio) {
        return Err(
            "validated ratio expansion target_validated_label_ratio must be 0..1".to_string(),
        );
    }
    validate_optional_local_json_path(
        config.generated_evidence_output_path.as_ref(),
        "validated ratio generated_evidence_output_path",
    )?;
    validate_optional_local_json_path(
        config.validated_replay_output_path.as_ref(),
        "validated ratio validated_replay_output_path",
    )?;
    validate_optional_local_json_path(
        config.label_quality_output_path.as_ref(),
        "validated ratio label_quality_output_path",
    )?;
    validate_optional_local_json_path(
        config.readiness_output_path.as_ref(),
        "validated ratio readiness_output_path",
    )?;

    let base_build = build_validated_replay_dataset_with_paper_evidence(
        sanitized_dataset,
        existing_evidence,
        label_validation_policy,
        ValidatedReplayDatasetBuildConfig {
            source_sanitized_dataset_id: sanitized_dataset.dataset_id.clone(),
            label_validation_policy: label_validation_policy.clone(),
            backtest_label_contract: None,
            require_validated_labels_for_training: true,
            allow_ready_with_warnings_for_medium_confidence: true,
            reject_rejected_labels: true,
            paper_only: true,
        },
    );
    let previous_validated_ratio = ratio(
        base_build
            .dataset
            .examples
            .iter()
            .filter(|example| is_validated_replay_label(example))
            .count(),
        base_build.dataset.examples.len(),
    );
    let workbench = build_replay_evidence_workbench(
        &base_build.dataset,
        experience_store,
        existing_evidence,
        &ReplayEvidenceWorkbenchConfig {
            workbench_id: format!("{}-workbench", config.run_id),
            sanitized_dataset_path: None,
            experience_store_path: None,
            validated_dataset_path: None,
            existing_evidence_path: None,
            output_evidence_draft_path: None,
            output_generated_evidence_path: None,
            output_validated_replay_path: None,
            target_validated_label_ratio: config.target_validated_label_ratio,
            max_drafts: default_max_generated_evidence_drafts(),
            include_only_unvalidated: true,
            include_review_required: true,
            include_ambiguous: false,
            paper_only: true,
        },
    );
    let price_label_result = generate_price_move_label_candidates(
        &workbench,
        price_series_store,
        &PaperPriceMoveLabelPolicy::default(),
    );
    let generated_evidence_batch =
        build_paper_evidence_records_from_price_move_candidates(&price_label_result.candidates);

    let mut combined_evidence = existing_evidence.to_vec();
    let mut replay_ids_seen: std::collections::BTreeSet<String> = combined_evidence
        .iter()
        .filter_map(|record| record.replay_id.clone())
        .collect();
    for record in &generated_evidence_batch.generated_records {
        if record
            .replay_id
            .as_ref()
            .map(|replay_id| replay_ids_seen.insert(replay_id.clone()))
            .unwrap_or(true)
        {
            combined_evidence.push(record.clone());
        }
    }

    let validated_build_result = build_validated_replay_dataset_with_paper_evidence(
        sanitized_dataset,
        &combined_evidence,
        label_validation_policy,
        ValidatedReplayDatasetBuildConfig {
            source_sanitized_dataset_id: sanitized_dataset.dataset_id.clone(),
            label_validation_policy: label_validation_policy.clone(),
            backtest_label_contract: None,
            require_validated_labels_for_training: true,
            allow_ready_with_warnings_for_medium_confidence: true,
            reject_rejected_labels: true,
            paper_only: true,
        },
    );
    let label_quality_summary = summarize_label_quality(&validated_build_result);
    let new_validated_ratio = label_quality_summary.validated_label_ratio;
    let mut readiness_gate = evaluate_offline_training_readiness_with_label_ratio_threshold(
        &validated_build_result.dataset,
        experience_store,
        1,
        0,
        config.target_validated_label_ratio,
    );
    normalize_offline_training_design_readiness(&mut readiness_gate);
    let target_validated_count = ((validated_build_result.dataset.examples.len() as f64)
        * config.target_validated_label_ratio)
        .ceil() as usize;
    let additional_labels_needed_before = target_validated_count.saturating_sub(
        base_build
            .dataset
            .examples
            .iter()
            .filter(|example| is_validated_replay_label(example))
            .count(),
    );
    let additional_labels_needed_after =
        target_validated_count.saturating_sub(label_quality_summary.validated_label_count);

    let generated_evidence_file = PaperOutcomeEvidenceFile {
        schema_version: "paper-outcome-evidence.v1".to_string(),
        evidence_file_id: format!("generated-paper-evidence-{}", config.run_id),
        created_at: None,
        source_label: "generated-local-price-move-evidence".to_string(),
        records: generated_evidence_batch.generated_records.clone(),
        paper_only: true,
    };

    if !config.dry_run {
        if let Some(path) = &config.generated_evidence_output_path {
            write_safe_json(Path::new(path), &generated_evidence_file)?;
        }
        if let Some(path) = &config.validated_replay_output_path {
            validated_build_result
                .dataset
                .save_to_local_json(Path::new(path))?;
        }
        if let Some(path) = &config.label_quality_output_path {
            write_safe_json(Path::new(path), &label_quality_summary)?;
        }
        if let Some(path) = &config.readiness_output_path {
            write_safe_json(Path::new(path), &readiness_gate)?;
        }
    }

    Ok(ValidatedRatioExpansionRunResult {
        workbench,
        price_label_result,
        generated_evidence_batch,
        validated_build_result,
        label_quality_summary,
        readiness_gate,
        previous_validated_ratio,
        new_validated_ratio,
        additional_labels_needed_before,
        additional_labels_needed_after,
        safety_summary: safety_summary(),
        paper_only: true,
    })
}

pub fn recheck_training_readiness_after_paper_evidence(
    validated_build_result: &ValidatedReplayDatasetBuildResult,
    coverage_eval: &ReplayCoverageTargetEval,
    leakage_check: &ReplayDataLeakageCheck,
) -> OfflineTrainingReadinessGate {
    let empty_store = MemberExperienceStore::new("paper-evidence-readiness-recheck", Vec::new());
    let mut gate = evaluate_offline_training_readiness_with_label_ratio_threshold(
        &validated_build_result.dataset,
        &empty_store,
        coverage_eval.target_config.min_examples_total,
        0,
        default_min_validated_label_ratio_required(),
    );
    gate.leakage_status = leakage_check.leakage_status;
    gate.coverage_target_status = coverage_eval.target_status;
    gate.coverage_matrix = coverage_eval.coverage_matrix.clone();
    gate.remaining_coverage_gaps = coverage_eval.gaps.clone();
    gate.collection_queue_size = coverage_eval.coverage_gap_count;
    gate.validated_label_ratio_after_evidence = gate.validated_label_ratio;
    gate.promoted_by_paper_evidence_count = validated_build_result.promoted_count;
    gate.unmatched_evidence_count = validated_build_result.unmatched_evidence_count;
    gate.ambiguous_evidence_count = validated_build_result.ambiguous_match_count;
    gate.rejected_evidence_count = validated_build_result.rejected_count;
    if leakage_check.leakage_status != ReplayLeakageStatus::NoLeakageDetected {
        gate.ready_for_offline_training = false;
        gate.readiness_status = OfflineTrainingReadinessStatus::BlockedByLeakage;
        gate.blockers
            .push("paper evidence readiness recheck found leakage".to_string());
    }
    gate
}

fn weak_label_current_outcome(example: &ReplayExample) -> MemberExperienceOutcome {
    example
        .target_labels
        .as_ref()
        .map(|labels| labels.outcome_label)
        .unwrap_or(example.target.outcome_label)
}

fn ensure_replay_target_labels(example: &mut ReplayExample) {
    if example.target_labels.is_none() {
        example.target_labels = Some(ReplayTargetLabels {
            stance_target: example.target.stance,
            confidence_calibration_target: example.target.confidence_calibration,
            risk_label: example.target.risk_label.clone(),
            evidence_label: example.target.evidence_label.clone(),
            outcome_label: example.target.outcome_label,
            attribution_label: MemberScoreUpdateReason::Neutral,
            label_source: ReplayLabelSource::ReviewRequired,
            label_confidence: ReplayLabelConfidence::ReviewRequired,
            paper_only: true,
        });
    }
}

fn apply_review_label_metadata(
    example: &mut ReplayExample,
    outcome_label: MemberExperienceOutcome,
    source: ReplayLabelSource,
    confidence: ReplayLabelConfidence,
) {
    ensure_replay_target_labels(example);
    if let Some(labels) = &mut example.target_labels {
        labels.outcome_label = outcome_label;
        labels.label_source = source;
        labels.label_confidence = confidence;
    }
}

fn weak_label_priority(reasons: &[WeakReplayLabelReason]) -> WeakReplayLabelPriority {
    if reasons.iter().any(|reason| {
        matches!(
            reason,
            WeakReplayLabelReason::ContradictoryEvidence
                | WeakReplayLabelReason::AmbiguousMatch
                | WeakReplayLabelReason::MissingReplayId
                | WeakReplayLabelReason::MissingDecisionId
                | WeakReplayLabelReason::MissingExperienceId
        )
    }) {
        WeakReplayLabelPriority::High
    } else if reasons.iter().any(|reason| {
        matches!(
            reason,
            WeakReplayLabelReason::ReviewRequiredSource
                | WeakReplayLabelReason::LowConfidence
                | WeakReplayLabelReason::MissingPriceEvidence
                | WeakReplayLabelReason::ManualLabelNeedsEvidence
                | WeakReplayLabelReason::SimulatedFixtureOnly
        )
    }) {
        WeakReplayLabelPriority::Normal
    } else {
        WeakReplayLabelPriority::Low
    }
}

fn weak_label_suggested_evidence(
    example: &ReplayExample,
    reasons: &[WeakReplayLabelReason],
) -> WeakReplaySuggestedEvidence {
    if reasons.contains(&WeakReplayLabelReason::MissingReplayId) {
        WeakReplaySuggestedEvidence::AddReplayId
    } else if reasons.contains(&WeakReplayLabelReason::MissingDecisionId) {
        WeakReplaySuggestedEvidence::AddDecisionId
    } else if reasons.contains(&WeakReplayLabelReason::MissingExperienceId) {
        WeakReplaySuggestedEvidence::AddExperienceId
    } else if reasons.contains(&WeakReplayLabelReason::ContradictoryEvidence) {
        WeakReplaySuggestedEvidence::RejectLabel
    } else if matches!(
        replay_label_source_for_example(example),
        ReplayLabelSource::PaperBacktestDeferred
    ) {
        WeakReplaySuggestedEvidence::AddBacktestContract
    } else if reasons.contains(&WeakReplayLabelReason::MissingPriceEvidence) {
        WeakReplaySuggestedEvidence::AddPriceMoveEvidence
    } else if reasons.contains(&WeakReplayLabelReason::ReviewRequiredSource) {
        WeakReplaySuggestedEvidence::KeepReviewRequired
    } else {
        WeakReplaySuggestedEvidence::AddPaperOutcomeReview
    }
}

pub fn build_weak_replay_label_inventory(
    validated_dataset: &ReplayDataset,
    evidence_quality_summary: Option<&PaperOutcomeEvidenceQualitySummary>,
) -> WeakReplayLabelInventory {
    let has_ambiguous_evidence = evidence_quality_summary
        .map(|summary| summary.ambiguous_records > 0)
        .unwrap_or(false);
    let has_contradictory_evidence = evidence_quality_summary
        .map(|summary| summary.contradicted_records > 0)
        .unwrap_or(false);
    let mut weak_items = Vec::new();
    for example in &validated_dataset.examples {
        if !is_weak_replay_label(example) {
            continue;
        }
        let current_label_source = replay_label_source_for_example(example);
        let current_label_confidence = replay_label_confidence_for_example(example);
        let current_outcome_label = weak_label_current_outcome(example);
        let experience_id = replay_example_experience_id(example);
        let decision_id = None;
        let mut weakness_reasons = Vec::new();
        if matches!(current_label_source, ReplayLabelSource::ReviewRequired) {
            weakness_reasons.push(WeakReplayLabelReason::ReviewRequiredSource);
        }
        if matches!(
            current_label_confidence,
            ReplayLabelConfidence::Low | ReplayLabelConfidence::ReviewRequired
        ) {
            weakness_reasons.push(WeakReplayLabelReason::LowConfidence);
        }
        if example.replay_id.trim().is_empty() {
            weakness_reasons.push(WeakReplayLabelReason::MissingReplayId);
            weakness_reasons.push(WeakReplayLabelReason::MissingExperienceId);
            weakness_reasons.push(WeakReplayLabelReason::MissingDecisionId);
        }
        if current_outcome_label == MemberExperienceOutcome::Unknown {
            weakness_reasons.push(WeakReplayLabelReason::UnknownOutcome);
            weakness_reasons.push(WeakReplayLabelReason::MissingPriceEvidence);
        }
        if matches!(
            current_label_source,
            ReplayLabelSource::AmbiguousLabel
                | ReplayLabelSource::PaperOutcomeUnknown
                | ReplayLabelSource::ManualPaperOutcome
        ) || (has_ambiguous_evidence
            && matches!(
                current_label_source,
                ReplayLabelSource::ReviewRequired | ReplayLabelSource::AmbiguousLabel
            ))
        {
            weakness_reasons.push(WeakReplayLabelReason::AmbiguousMatch);
        }
        if matches!(current_label_source, ReplayLabelSource::SimulatedFixture) {
            weakness_reasons.push(WeakReplayLabelReason::SimulatedFixtureOnly);
        }
        if matches!(
            current_label_source,
            ReplayLabelSource::ManualPaperLabel
                | ReplayLabelSource::ManualPaperOutcome
                | ReplayLabelSource::PaperOutcomeUnknown
        ) {
            weakness_reasons.push(WeakReplayLabelReason::ManualLabelNeedsEvidence);
        }
        if matches!(current_label_source, ReplayLabelSource::RejectedLabel)
            || (has_contradictory_evidence
                && matches!(
                    current_label_source,
                    ReplayLabelSource::RejectedLabel
                        | ReplayLabelSource::ReviewRequired
                        | ReplayLabelSource::ManualPaperLabel
                ))
        {
            weakness_reasons.push(WeakReplayLabelReason::ContradictoryEvidence);
        }
        weakness_reasons.sort();
        weakness_reasons.dedup();
        let suggested_next_evidence = weak_label_suggested_evidence(example, &weakness_reasons);
        let priority = weak_label_priority(&weakness_reasons);
        weak_items.push(WeakReplayLabelItem {
            item_id: format!(
                "weak-{}",
                if example.replay_id.trim().is_empty() {
                    format!("{}-{:?}", example.symbol, example.market_scope)
                } else {
                    example.replay_id.clone()
                }
            ),
            replay_id: example.replay_id.clone(),
            experience_id,
            decision_id,
            member_id: example.member_id.clone(),
            symbol: example.symbol.clone(),
            market_scope: example.market_scope,
            current_label_source,
            current_label_confidence,
            current_outcome_label,
            weakness_reasons,
            suggested_next_evidence,
            priority,
            paper_only: true,
        });
    }
    weak_items.sort_by(|left, right| {
        left.replay_id
            .cmp(&right.replay_id)
            .then_with(|| left.member_id.cmp(&right.member_id))
            .then_with(|| left.item_id.cmp(&right.item_id))
    });
    WeakReplayLabelInventory {
        inventory_id: format!("{}-weak-label-inventory", validated_dataset.dataset_id),
        dataset_id: validated_dataset.dataset_id.clone(),
        total_examples: validated_dataset.examples.len(),
        weak_label_count: weak_items.len(),
        review_required_count: weak_items
            .iter()
            .filter(|item| {
                item.weakness_reasons
                    .contains(&WeakReplayLabelReason::ReviewRequiredSource)
            })
            .count(),
        low_confidence_count: weak_items
            .iter()
            .filter(|item| {
                item.weakness_reasons
                    .contains(&WeakReplayLabelReason::LowConfidence)
            })
            .count(),
        ambiguous_label_count: weak_items
            .iter()
            .filter(|item| {
                item.weakness_reasons
                    .contains(&WeakReplayLabelReason::AmbiguousMatch)
            })
            .count(),
        missing_evidence_count: weak_items
            .iter()
            .filter(|item| {
                matches!(
                    item.suggested_next_evidence,
                    WeakReplaySuggestedEvidence::AddPriceMoveEvidence
                        | WeakReplaySuggestedEvidence::AddPaperOutcomeReview
                        | WeakReplaySuggestedEvidence::AddBacktestContract
                )
            })
            .count(),
        weak_items,
        paper_only: true,
    }
}

fn weak_label_recommended_action(item: &WeakReplayLabelItem) -> WeakLabelRecommendedAction {
    match item.suggested_next_evidence {
        WeakReplaySuggestedEvidence::AddReplayId
        | WeakReplaySuggestedEvidence::AddDecisionId
        | WeakReplaySuggestedEvidence::AddExperienceId => WeakLabelRecommendedAction::AddMissingIds,
        WeakReplaySuggestedEvidence::RejectLabel => {
            WeakLabelRecommendedAction::RejectContradictoryLabel
        }
        WeakReplaySuggestedEvidence::AddPriceMoveEvidence => {
            WeakLabelRecommendedAction::ValidateWithPriceEvidence
        }
        WeakReplaySuggestedEvidence::AddBacktestContract => {
            WeakLabelRecommendedAction::BacktestDeferred
        }
        WeakReplaySuggestedEvidence::KeepReviewRequired => {
            WeakLabelRecommendedAction::KeepReviewRequired
        }
        WeakReplaySuggestedEvidence::AddPaperOutcomeReview => {
            WeakLabelRecommendedAction::ManualPaperReview
        }
    }
}

fn review_item_priority(item: &WeakLabelReviewQueueItem) -> WeakReplayLabelPriority {
    weak_label_priority(&item.weakness_reasons)
}

pub fn build_weak_label_review_queue(inventory: &WeakReplayLabelInventory) -> WeakLabelReviewQueue {
    let mut items: Vec<WeakLabelReviewQueueItem> = inventory
        .weak_items
        .iter()
        .map(|item| WeakLabelReviewQueueItem {
            review_item_id: format!("review-{}", item.item_id),
            replay_id: item.replay_id.clone(),
            experience_id: item.experience_id.clone(),
            decision_id: item.decision_id.clone(),
            symbol: item.symbol.clone(),
            market_scope: item.market_scope,
            member_id: item.member_id.clone(),
            current_label_source: item.current_label_source,
            current_confidence: item.current_label_confidence,
            weakness_reasons: item.weakness_reasons.clone(),
            required_evidence: item.suggested_next_evidence,
            recommended_action: weak_label_recommended_action(item),
            paper_only: true,
        })
        .collect();
    items.sort_by(|left, right| {
        review_item_priority(right)
            .cmp(&review_item_priority(left))
            .then_with(|| left.replay_id.cmp(&right.replay_id))
            .then_with(|| left.review_item_id.cmp(&right.review_item_id))
    });
    WeakLabelReviewQueue {
        queue_id: format!("{}-review-queue", inventory.inventory_id),
        high_priority_count: items
            .iter()
            .filter(|item| review_item_priority(item) == WeakReplayLabelPriority::High)
            .count(),
        items,
        paper_only: true,
    }
}

fn paper_label_review_decision_unsafe_reasons(value: &serde_json::Value) -> Vec<String> {
    let mut reasons = Vec::new();
    match value {
        serde_json::Value::Object(map) => {
            for (key, child) in map {
                let lower = key.to_ascii_lowercase();
                for prohibited in [
                    "broker",
                    "order",
                    "account",
                    "pnl",
                    "real_pnl",
                    "real trade",
                    "live trade",
                    "live_trading",
                    "api_key",
                    "secret",
                ] {
                    if lower.contains(prohibited) {
                        reasons.push(format!(
                            "paper label review decision rejected unsafe field: {key}"
                        ));
                    }
                }
                reasons.extend(paper_label_review_decision_unsafe_reasons(child));
            }
        }
        serde_json::Value::Array(items) => {
            for item in items {
                reasons.extend(paper_label_review_decision_unsafe_reasons(item));
            }
        }
        serde_json::Value::String(text) => {
            let lower = text.to_ascii_lowercase();
            for prohibited in [
                "broker",
                "order",
                "account",
                "pnl",
                "real pnl",
                "live trade",
                "live trading",
                "api key",
                "secret key",
            ] {
                if lower.contains(prohibited) {
                    reasons.push(format!(
                        "paper label review decision rejected unsafe claim: {prohibited}"
                    ));
                }
            }
        }
        _ => {}
    }
    reasons
}

pub fn validate_paper_label_review_decision_file(
    mut file: PaperLabelReviewDecisionFile,
) -> Result<PaperLabelReviewDecisionFile, String> {
    if !file.paper_only {
        return Err("paper label review decision file must be paper-only".to_string());
    }
    let mut seen_decision_ids = std::collections::BTreeSet::new();
    let mut seen_review_items = std::collections::BTreeSet::new();
    for decision in &file.decisions {
        if !decision.paper_only {
            return Err(format!(
                "paper label review decision {} must be paper-only",
                decision.decision_id
            ));
        }
        if decision.decision_id.trim().is_empty() {
            return Err("paper label review decision_id is required".to_string());
        }
        if decision.review_item_id.trim().is_empty() {
            return Err("paper label review review_item_id is required".to_string());
        }
        if !seen_decision_ids.insert(decision.decision_id.clone()) {
            return Err(format!(
                "duplicate paper label review decision id {}",
                decision.decision_id
            ));
        }
        if !seen_review_items.insert(decision.review_item_id.clone()) {
            return Err(format!(
                "duplicate paper label review item {}",
                decision.review_item_id
            ));
        }
    }
    file.decisions.sort_by(|left, right| {
        left.review_item_id
            .cmp(&right.review_item_id)
            .then_with(|| left.replay_id.cmp(&right.replay_id))
            .then_with(|| left.decision_id.cmp(&right.decision_id))
    });
    Ok(file)
}

pub fn load_paper_label_review_decisions_from_local_json(
    path: &Path,
) -> Result<PaperLabelReviewDecisionFile, String> {
    validate_local_json_path(path, "paper label review decision path")?;
    let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
    let value: serde_json::Value = serde_json::from_str(&text).map_err(|err| err.to_string())?;
    if let Some(reason) = paper_label_review_decision_unsafe_reasons(&value).first() {
        return Err(reason.clone());
    }
    let file: PaperLabelReviewDecisionFile =
        serde_json::from_value(value).map_err(|err| err.to_string())?;
    validate_paper_label_review_decision_file(file)
}

fn strong_price_evidence(record: &PaperOutcomeEvidenceRecord) -> bool {
    paper_outcome_evidence_price_change(record)
        .map(|change| change.abs() >= 0.02)
        .unwrap_or(false)
}

pub fn evaluate_label_confidence_upgrade(
    review_decision: &PaperLabelReviewDecision,
    evidence_record: &PaperOutcomeEvidenceRecord,
    policy: &LabelConfidenceUpgradePolicy,
) -> LabelConfidenceUpgradeResult {
    let previous_source = evidence_record.label_source;
    let previous_confidence = evidence_record.label_confidence;
    let replay_id = review_decision.replay_id.clone();
    let mut result = LabelConfidenceUpgradeResult {
        replay_id,
        previous_source,
        previous_confidence,
        new_source: previous_source,
        new_confidence: previous_confidence,
        upgrade_allowed: false,
        upgrade_status: LabelConfidenceUpgradeStatus::KeptWeak,
        reason: "review decision kept current label metadata".to_string(),
        paper_only: true,
    };
    if policy.require_paper_only && (!policy.paper_only || !evidence_record.paper_only) {
        result.upgrade_status = LabelConfidenceUpgradeStatus::BlockedByPolicy;
        result.reason = "paper-only policy blocked label review upgrade".to_string();
        return result;
    }
    if matches!(
        review_decision.decision,
        PaperLabelReviewDecisionKind::RejectLabel
    ) {
        result.new_source = ReplayLabelSource::RejectedLabel;
        result.new_confidence = ReplayLabelConfidence::ReviewRequired;
        result.upgrade_allowed = true;
        result.upgrade_status = LabelConfidenceUpgradeStatus::Rejected;
        result.reason = "review decision rejected the weak label".to_string();
        return result;
    }
    if matches!(
        review_decision.decision,
        PaperLabelReviewDecisionKind::MarkAmbiguous
    ) {
        result.new_source = ReplayLabelSource::AmbiguousLabel;
        result.new_confidence = ReplayLabelConfidence::ReviewRequired;
        result.upgrade_status = LabelConfidenceUpgradeStatus::KeptWeak;
        result.reason = "review decision marked the label as ambiguous".to_string();
        return result;
    }
    if matches!(
        review_decision.decision,
        PaperLabelReviewDecisionKind::KeepReviewRequired
    ) {
        result.new_source = ReplayLabelSource::ReviewRequired;
        result.new_confidence = ReplayLabelConfidence::ReviewRequired;
        result.upgrade_status = LabelConfidenceUpgradeStatus::KeptWeak;
        result.reason = "review decision kept the label review-required".to_string();
        return result;
    }
    if matches!(
        review_decision.decision,
        PaperLabelReviewDecisionKind::NeedMoreEvidence
    ) {
        result.new_source = ReplayLabelSource::ReviewRequired;
        result.new_confidence = ReplayLabelConfidence::ReviewRequired;
        result.upgrade_status = LabelConfidenceUpgradeStatus::NeedsMoreEvidence;
        result.reason = "review decision requires more paper evidence".to_string();
        return result;
    }
    if policy.require_replay_id_for_upgrade && review_decision.replay_id.trim().is_empty() {
        result.new_source = ReplayLabelSource::ReviewRequired;
        result.new_confidence = ReplayLabelConfidence::ReviewRequired;
        result.upgrade_status = LabelConfidenceUpgradeStatus::BlockedByPolicy;
        result.reason = "missing replay_id blocks weak label upgrade".to_string();
        return result;
    }
    if evidence_record.replay_id.as_deref() != Some(review_decision.replay_id.as_str()) {
        result.new_source = ReplayLabelSource::ReviewRequired;
        result.new_confidence = ReplayLabelConfidence::ReviewRequired;
        result.upgrade_status = LabelConfidenceUpgradeStatus::BlockedByPolicy;
        result.reason = "review decision replay_id must match paper evidence replay_id".to_string();
        return result;
    }
    if !policy.allow_upgrade_from_simulated_fixture
        && matches!(previous_source, ReplayLabelSource::SimulatedFixture)
    {
        result.upgrade_status = LabelConfidenceUpgradeStatus::BlockedByPolicy;
        result.reason = "simulated fixture labels cannot upgrade".to_string();
        return result;
    }
    if policy.require_non_contradictory_price_evidence
        && paper_outcome_evidence_contradiction(
            evidence_record,
            &PaperLabelValidationPolicy::default(),
        )
    {
        result.new_source = ReplayLabelSource::RejectedLabel;
        result.new_confidence = ReplayLabelConfidence::ReviewRequired;
        result.upgrade_allowed = true;
        result.upgrade_status = LabelConfidenceUpgradeStatus::Rejected;
        result.reason = "contradictory paper evidence rejected the label".to_string();
        return result;
    }
    let Some(_) = paper_outcome_evidence_price_change(evidence_record) else {
        result.new_source = ReplayLabelSource::ReviewRequired;
        result.new_confidence = ReplayLabelConfidence::ReviewRequired;
        result.upgrade_status = LabelConfidenceUpgradeStatus::NeedsMoreEvidence;
        result.reason = "price evidence is required before upgrading".to_string();
        return result;
    };
    let requested_confidence = match review_decision.confidence {
        ReplayLabelConfidence::High => {
            if strong_price_evidence(evidence_record)
                && policy.allow_high_confidence_with_price_evidence
                && matches!(
                    review_decision.reviewer,
                    PaperLabelReviewer::PriceEvidenceRule | PaperLabelReviewer::SystemRule
                )
            {
                ReplayLabelConfidence::High
            } else if policy.allow_medium_confidence_with_price_evidence {
                ReplayLabelConfidence::Medium
            } else {
                ReplayLabelConfidence::ReviewRequired
            }
        }
        ReplayLabelConfidence::Medium => {
            if policy.allow_medium_confidence_with_price_evidence {
                ReplayLabelConfidence::Medium
            } else {
                ReplayLabelConfidence::ReviewRequired
            }
        }
        ReplayLabelConfidence::Low | ReplayLabelConfidence::ReviewRequired => {
            ReplayLabelConfidence::ReviewRequired
        }
    };
    if matches!(requested_confidence, ReplayLabelConfidence::ReviewRequired) {
        result.new_source = ReplayLabelSource::ReviewRequired;
        result.new_confidence = ReplayLabelConfidence::ReviewRequired;
        result.upgrade_status = LabelConfidenceUpgradeStatus::NeedsMoreEvidence;
        result.reason = "review evidence did not satisfy upgrade confidence policy".to_string();
        return result;
    }
    if matches!(
        review_decision.reviewer,
        PaperLabelReviewer::OwnerNaturalComment | PaperLabelReviewer::ManualPaperReview
    ) && matches!(requested_confidence, ReplayLabelConfidence::High)
        && !policy.allow_high_confidence_manual_review
    {
        result.new_source = ReplayLabelSource::ValidatedPaperLabel;
        result.new_confidence = ReplayLabelConfidence::Medium;
        result.upgrade_allowed = true;
        result.upgrade_status = LabelConfidenceUpgradeStatus::Upgraded;
        result.reason = "manual review can upgrade only to medium confidence".to_string();
        return result;
    }
    result.new_source = ReplayLabelSource::ValidatedPaperLabel;
    result.new_confidence = requested_confidence;
    result.upgrade_allowed = true;
    result.upgrade_status = LabelConfidenceUpgradeStatus::Upgraded;
    result.reason = "paper review decision promoted the label with price evidence".to_string();
    result
}

fn inclusion_reason_for_example(
    example: &ReplayExample,
    policy: &ReplayTrainingInclusionPolicy,
) -> Option<String> {
    let source = replay_label_source_for_example(example);
    let confidence = replay_label_confidence_for_example(example);
    if matches!(
        source,
        ReplayLabelSource::ValidatedPaperLabel | ReplayLabelSource::ValidatedBacktestLabel
    ) && policy.include_validated_labels
        && matches!(confidence, ReplayLabelConfidence::High)
    {
        return None;
    }
    if matches!(
        source,
        ReplayLabelSource::ValidatedPaperLabel | ReplayLabelSource::ValidatedBacktestLabel
    ) && policy.include_validated_labels
        && policy.include_medium_confidence_validated
        && matches!(confidence, ReplayLabelConfidence::Medium)
    {
        return None;
    }
    if policy.include_review_required
        && !matches!(
            source,
            ReplayLabelSource::RejectedLabel
                | ReplayLabelSource::SimulatedFixture
                | ReplayLabelSource::AmbiguousLabel
        )
    {
        return None;
    }
    if policy.include_simulated_fixture && matches!(source, ReplayLabelSource::SimulatedFixture) {
        return None;
    }
    if policy.include_ambiguous && matches!(source, ReplayLabelSource::AmbiguousLabel) {
        return None;
    }
    if policy.include_rejected && matches!(source, ReplayLabelSource::RejectedLabel) {
        return None;
    }
    Some(format!("excluded {:?}/{:?}", source, confidence))
}

pub fn build_replay_training_inclusion_mask(
    validated_dataset: &ReplayDataset,
    policy: &ReplayTrainingInclusionPolicy,
) -> ReplayTrainingInclusionMask {
    let mut included_replay_ids = Vec::new();
    let mut excluded_replay_ids = Vec::new();
    let mut excluded_reasons = std::collections::BTreeMap::new();
    for example in &validated_dataset.examples {
        if inclusion_reason_for_example(example, policy).is_none() {
            included_replay_ids.push(example.replay_id.clone());
        } else {
            excluded_replay_ids.push(example.replay_id.clone());
            excluded_reasons.insert(
                example.replay_id.clone(),
                inclusion_reason_for_example(example, policy).unwrap_or_default(),
            );
        }
    }
    included_replay_ids.sort();
    included_replay_ids.dedup();
    excluded_replay_ids.sort();
    excluded_replay_ids.dedup();
    ReplayTrainingInclusionMask {
        included_count: included_replay_ids.len(),
        excluded_count: excluded_replay_ids.len(),
        included_replay_ids,
        excluded_replay_ids,
        excluded_reasons,
        paper_only: true,
    }
}

fn placeholder_review_evidence(example: &ReplayExample) -> PaperOutcomeEvidenceRecord {
    PaperOutcomeEvidenceRecord {
        evidence_id: format!("weak-review-placeholder-{}", example.replay_id),
        symbol: example.symbol.clone(),
        market_scope: example.market_scope,
        decision_id: None,
        event_id: None,
        replay_id: (!example.replay_id.trim().is_empty()).then(|| example.replay_id.clone()),
        experience_id: replay_example_experience_id(example),
        horizon: replay_evidence_horizon_for_scope(example.market_scope),
        horizon_bars: None,
        reference_price: None,
        horizon_price: None,
        price_change_pct: None,
        candidate_label: weak_label_current_outcome(example),
        label_source: replay_label_source_for_example(example),
        label_confidence: replay_label_confidence_for_example(example),
        evidence_notes: vec!["weak label review placeholder evidence".to_string()],
        validation_hint: Some(PaperOutcomeEvidenceValidationHint::KeepReviewRequired),
        paper_only: true,
    }
}

fn training_inclusion_policy_from_flag(
    exclude_weak_labels_from_training_design: bool,
) -> ReplayTrainingInclusionPolicy {
    if exclude_weak_labels_from_training_design {
        ReplayTrainingInclusionPolicy::default()
    } else {
        ReplayTrainingInclusionPolicy {
            include_review_required: true,
            include_simulated_fixture: true,
            include_ambiguous: true,
            ..ReplayTrainingInclusionPolicy::default()
        }
    }
}

fn rebuild_validated_replay_build_from_dataset(
    dataset: &ReplayDataset,
) -> ValidatedReplayDatasetBuildResult {
    let rejected_count = dataset
        .examples
        .iter()
        .filter(|example| is_rejected_replay_label(example))
        .count();
    let needs_review_count = dataset
        .examples
        .iter()
        .filter(|example| {
            matches!(
                replay_label_confidence_for_example(example),
                ReplayLabelConfidence::ReviewRequired
            ) || matches!(
                replay_label_source_for_example(example),
                ReplayLabelSource::ReviewRequired | ReplayLabelSource::AmbiguousLabel
            )
        })
        .count();
    let weak_label_count = dataset
        .examples
        .iter()
        .filter(|example| is_weak_replay_label(example))
        .count();
    let build_status = if dataset.examples.is_empty() {
        ValidatedReplayDatasetBuildStatus::Empty
    } else if rejected_count > 0 {
        ValidatedReplayDatasetBuildStatus::BlockedByRejectedLabels
    } else if weak_label_count > 0 {
        ValidatedReplayDatasetBuildStatus::BuiltWithWarnings
    } else {
        ValidatedReplayDatasetBuildStatus::Built
    };
    ValidatedReplayDatasetBuildResult {
        dataset: dataset.clone(),
        label_evidence_records: Vec::new(),
        promotion_gates: Vec::new(),
        paper_evidence_matching_result: None,
        paper_evidence_promotion_results: Vec::new(),
        promoted_count: 0,
        not_promoted_count: weak_label_count,
        rejected_count,
        needs_review_count,
        unmatched_evidence_count: 0,
        ambiguous_match_count: 0,
        build_status,
        paper_only: true,
    }
}

fn apply_weak_label_review_decisions_with_inputs(
    config: &WeakLabelReviewApplyConfig,
    validated_dataset: &ReplayDataset,
    experience_store: &MemberExperienceStore,
    evidence_records: &[PaperOutcomeEvidenceRecord],
    min_examples_required: usize,
    per_member_min_examples_required: usize,
    exclude_weak_labels_from_training_design: bool,
    review_output_path: Option<&String>,
    inclusion_mask_output_path: Option<&String>,
) -> Result<(WeakLabelReviewApplyResult, ReplayTrainingInclusionMask), String> {
    if !config.paper_only {
        return Err("weak label review apply config must be paper-only".to_string());
    }
    if !(0.0..=1.0).contains(&config.min_validated_label_ratio_required) {
        return Err(
            "weak label review min_validated_label_ratio_required must be 0..1".to_string(),
        );
    }
    validate_optional_local_json_path(
        config.output_validated_dataset_path.as_ref(),
        "weak label review output_validated_dataset_path",
    )?;
    validate_optional_local_json_path(
        config.output_label_quality_path.as_ref(),
        "weak label review output_label_quality_path",
    )?;
    validate_optional_local_json_path(
        config.output_readiness_path.as_ref(),
        "weak label review output_readiness_path",
    )?;
    validate_optional_local_json_path(review_output_path, "weak label review output path")?;
    validate_optional_local_json_path(
        inclusion_mask_output_path,
        "weak label replay training inclusion mask output path",
    )?;

    let evidence_quality_summary = if evidence_records.is_empty() {
        None
    } else {
        let load_result = PaperOutcomeEvidenceLoadResult {
            loaded: true,
            evidence_file_id: "weak-label-review-evidence".to_string(),
            record_count: evidence_records.len(),
            rejected_count: 0,
            duplicate_count: 0,
            records: evidence_records.to_vec(),
            rejected_records: Vec::new(),
            safety_warnings: Vec::new(),
            paper_only: true,
        };
        let matching = match_paper_outcome_evidence_to_replay(validated_dataset, evidence_records);
        Some(summarize_paper_outcome_evidence_quality(
            &load_result,
            &matching,
            &[],
        ))
    };
    let inventory =
        build_weak_replay_label_inventory(validated_dataset, evidence_quality_summary.as_ref());
    let queue = build_weak_label_review_queue(&inventory);

    let mut updated_validated_dataset = validated_dataset.clone();
    let queue_by_replay_id: std::collections::BTreeMap<String, WeakLabelReviewQueueItem> = queue
        .items
        .iter()
        .cloned()
        .map(|item| (item.replay_id.clone(), item))
        .collect();
    let mut evidence_by_replay_id = std::collections::BTreeMap::new();
    let mut sorted_evidence = evidence_records.to_vec();
    sorted_evidence.sort_by(|left, right| left.evidence_id.cmp(&right.evidence_id));
    for record in sorted_evidence {
        if let Some(replay_id) = &record.replay_id {
            evidence_by_replay_id
                .entry(replay_id.clone())
                .or_insert(record);
        }
    }
    let decision_file = if let Some(path) = &config.review_decision_path {
        Some(load_paper_label_review_decisions_from_local_json(
            Path::new(path),
        )?)
    } else {
        None
    };
    let decisions = decision_file
        .as_ref()
        .map(|file| file.decisions.clone())
        .unwrap_or_default();
    let decision_by_review_item: std::collections::BTreeMap<String, PaperLabelReviewDecision> =
        decisions
            .iter()
            .cloned()
            .map(|decision| (decision.review_item_id.clone(), decision))
            .collect();
    let decision_by_replay_id: std::collections::BTreeMap<String, PaperLabelReviewDecision> =
        decisions
            .iter()
            .cloned()
            .map(|decision| (decision.replay_id.clone(), decision))
            .collect();

    let previous_validated_ratio = ratio(
        validated_dataset
            .examples
            .iter()
            .filter(|example| is_validated_replay_label(example))
            .count(),
        validated_dataset.examples.len(),
    );
    let mut matched_decision_ids = std::collections::BTreeSet::new();
    let mut upgrade_results = Vec::new();
    let mut applied_count = 0;
    let mut rejected_count = 0;
    let mut kept_weak_count = 0;
    let mut needs_more_evidence_count = 0;
    for example in &mut updated_validated_dataset.examples {
        let Some(queue_item) = queue_by_replay_id.get(&example.replay_id) else {
            continue;
        };
        let decision = decision_by_review_item
            .get(&queue_item.review_item_id)
            .or_else(|| decision_by_replay_id.get(&example.replay_id));
        let Some(decision) = decision else {
            continue;
        };
        if decision.replay_id != example.replay_id {
            continue;
        }
        matched_decision_ids.insert(decision.decision_id.clone());
        let mut evidence_record = evidence_by_replay_id
            .get(&example.replay_id)
            .cloned()
            .unwrap_or_else(|| placeholder_review_evidence(example));
        evidence_record.label_source = replay_label_source_for_example(example);
        evidence_record.label_confidence = replay_label_confidence_for_example(example);
        let upgrade_result = evaluate_label_confidence_upgrade(
            decision,
            &evidence_record,
            &LabelConfidenceUpgradePolicy::default(),
        );
        match upgrade_result.upgrade_status {
            LabelConfidenceUpgradeStatus::Upgraded => {
                apply_review_label_metadata(
                    example,
                    evidence_record.candidate_label,
                    upgrade_result.new_source,
                    upgrade_result.new_confidence,
                );
                applied_count += 1;
            }
            LabelConfidenceUpgradeStatus::Rejected => {
                apply_review_label_metadata(
                    example,
                    evidence_record.candidate_label,
                    upgrade_result.new_source,
                    upgrade_result.new_confidence,
                );
                applied_count += 1;
                rejected_count += 1;
            }
            LabelConfidenceUpgradeStatus::KeptWeak => {
                if matches!(
                    decision.decision,
                    PaperLabelReviewDecisionKind::MarkAmbiguous
                        | PaperLabelReviewDecisionKind::KeepReviewRequired
                ) {
                    apply_review_label_metadata(
                        example,
                        weak_label_current_outcome(example),
                        upgrade_result.new_source,
                        upgrade_result.new_confidence,
                    );
                    applied_count += 1;
                }
                kept_weak_count += 1;
            }
            LabelConfidenceUpgradeStatus::NeedsMoreEvidence => {
                apply_review_label_metadata(
                    example,
                    weak_label_current_outcome(example),
                    ReplayLabelSource::ReviewRequired,
                    ReplayLabelConfidence::ReviewRequired,
                );
                needs_more_evidence_count += 1;
            }
            LabelConfidenceUpgradeStatus::BlockedByPolicy => {
                kept_weak_count += 1;
            }
        }
        upgrade_results.push(upgrade_result);
    }

    let label_quality_summary = summarize_label_quality_for_dataset(
        &updated_validated_dataset,
        updated_validated_dataset
            .examples
            .iter()
            .filter(|example| is_rejected_replay_label(example))
            .count(),
        updated_validated_dataset
            .examples
            .iter()
            .filter(|example| {
                matches!(
                    replay_label_confidence_for_example(example),
                    ReplayLabelConfidence::ReviewRequired
                ) || matches!(
                    replay_label_source_for_example(example),
                    ReplayLabelSource::ReviewRequired | ReplayLabelSource::AmbiguousLabel
                )
            })
            .count(),
    );
    let inclusion_mask = build_replay_training_inclusion_mask(
        &updated_validated_dataset,
        &training_inclusion_policy_from_flag(exclude_weak_labels_from_training_design),
    );
    let included_replay_ids: std::collections::BTreeSet<String> =
        inclusion_mask.included_replay_ids.iter().cloned().collect();
    let excluded_replay_ids: std::collections::BTreeSet<String> =
        inclusion_mask.excluded_replay_ids.iter().cloned().collect();
    let filtered_training_dataset = ReplayDataset::new(
        format!(
            "{}-training-inclusion",
            updated_validated_dataset.dataset_id
        ),
        updated_validated_dataset.generated_from_store_id.clone(),
        updated_validated_dataset
            .examples
            .iter()
            .filter(|example| included_replay_ids.contains(&example.replay_id))
            .cloned()
            .collect(),
    );
    let mut filtered_member_counts = std::collections::BTreeMap::new();
    for example in &filtered_training_dataset.examples {
        *filtered_member_counts
            .entry(example.member_id.clone())
            .or_insert(0usize) += 1;
    }
    let post_inventory = build_weak_replay_label_inventory(
        &updated_validated_dataset,
        evidence_quality_summary.as_ref(),
    );
    let weak_training_included_count = updated_validated_dataset
        .examples
        .iter()
        .filter(|example| {
            is_weak_replay_label(example) && included_replay_ids.contains(&example.replay_id)
        })
        .count();
    let excluded_weak_label_count = updated_validated_dataset
        .examples
        .iter()
        .filter(|example| {
            is_weak_replay_label(example) && excluded_replay_ids.contains(&example.replay_id)
        })
        .count();
    let mut readiness_gate = evaluate_offline_training_readiness_with_label_ratio_threshold(
        &updated_validated_dataset,
        experience_store,
        min_examples_required,
        per_member_min_examples_required,
        config.min_validated_label_ratio_required,
    );
    normalize_offline_training_design_readiness(&mut readiness_gate);
    readiness_gate.training_included_example_count = inclusion_mask.included_count;
    readiness_gate.excluded_weak_label_count = excluded_weak_label_count;
    readiness_gate.weak_labels_remaining = post_inventory.weak_label_count;
    readiness_gate.weak_labels_required_for_coverage = post_inventory.weak_label_count > 0
        && (filtered_training_dataset.example_count < min_examples_required
            || filtered_member_counts
                .values()
                .any(|count| *count < per_member_min_examples_required));
    readiness_gate.offline_training_design_status = if matches!(
        readiness_gate.readiness_status,
        OfflineTrainingReadinessStatus::BlockedBySafety
            | OfflineTrainingReadinessStatus::BlockedByLeakage
    ) {
        OfflineTrainingDesignStatus::BlockedBySafety
    } else if label_quality_summary.validated_label_ratio
        < config.min_validated_label_ratio_required
        || readiness_gate.weak_labels_required_for_coverage
    {
        OfflineTrainingDesignStatus::NeedsMoreValidatedCoverage
    } else if weak_training_included_count > 0 {
        OfflineTrainingDesignStatus::BlockedByWeakLabels
    } else if post_inventory.weak_label_count > 0 {
        OfflineTrainingDesignStatus::ReadyWithWarnings
    } else {
        OfflineTrainingDesignStatus::ReadyForDesign
    };
    readiness_gate.readiness_status = match readiness_gate.offline_training_design_status {
        OfflineTrainingDesignStatus::ReadyForDesign => {
            OfflineTrainingReadinessStatus::ReadyForOfflineTrainingDesign
        }
        OfflineTrainingDesignStatus::ReadyWithWarnings => {
            OfflineTrainingReadinessStatus::ReadyWithWarningsForOfflineTrainingDesign
        }
        OfflineTrainingDesignStatus::NeedsMoreValidatedCoverage
        | OfflineTrainingDesignStatus::BlockedByWeakLabels => {
            OfflineTrainingReadinessStatus::NeedsMoreData
        }
        OfflineTrainingDesignStatus::BlockedBySafety => {
            OfflineTrainingReadinessStatus::BlockedBySafety
        }
    };
    readiness_gate.ready_for_offline_training = matches!(
        readiness_gate.offline_training_design_status,
        OfflineTrainingDesignStatus::ReadyForDesign
            | OfflineTrainingDesignStatus::ReadyWithWarnings
    );
    if weak_training_included_count > 0 {
        readiness_gate
            .blockers
            .push("weak labels remain training-included for offline design".to_string());
    }
    let result = WeakLabelReviewApplyResult {
        inventory,
        queue,
        decision_count: matched_decision_ids.len(),
        applied_count,
        rejected_count,
        kept_weak_count,
        needs_more_evidence_count,
        upgrade_results,
        updated_validated_dataset: updated_validated_dataset.clone(),
        previous_validated_ratio,
        new_validated_ratio: label_quality_summary.validated_label_ratio,
        label_quality_summary: label_quality_summary.clone(),
        readiness_gate: readiness_gate.clone(),
        paper_only: true,
    };

    if !config.dry_run {
        if let Some(path) = &config.output_validated_dataset_path {
            updated_validated_dataset.save_to_local_json(Path::new(path))?;
        }
        if let Some(path) = &config.output_label_quality_path {
            label_quality_summary.save_to_local_json(Path::new(path))?;
        }
        if let Some(path) = &config.output_readiness_path {
            let path = Path::new(path);
            if let Some(parent) = path.parent() {
                if !parent.as_os_str().is_empty() {
                    fs::create_dir_all(parent).map_err(|err| err.to_string())?;
                }
            }
            write_safe_json(path, &readiness_gate)?;
        }
        if let Some(path) = review_output_path {
            result.save_to_local_json(Path::new(path))?;
        }
        if let Some(path) = inclusion_mask_output_path {
            inclusion_mask.save_to_local_json(Path::new(path))?;
        }
    }

    Ok((result, inclusion_mask))
}

pub fn apply_weak_label_review_decisions(
    config: &WeakLabelReviewApplyConfig,
) -> Result<WeakLabelReviewApplyResult, String> {
    let validated_dataset_path = config
        .validated_dataset_path
        .as_ref()
        .ok_or_else(|| "weak label review requires validated_dataset_path".to_string())?;
    if let Some(path) = &config.review_decision_path {
        validate_local_json_path(Path::new(path), "weak label review decision path")?;
    }
    if let Some(path) = &config.evidence_path {
        validate_local_json_path(Path::new(path), "weak label review evidence path")?;
    }
    let validated_dataset = ReplayDataset::load_from_local_json(Path::new(validated_dataset_path))?;
    let evidence_records = if let Some(path) = &config.evidence_path {
        load_paper_outcome_evidence_from_local_json(Path::new(path))?.records
    } else {
        Vec::new()
    };
    let empty_store = MemberExperienceStore::new("weak-label-review-empty-store", Vec::new());
    let (result, _) = apply_weak_label_review_decisions_with_inputs(
        config,
        &validated_dataset,
        &empty_store,
        &evidence_records,
        1,
        0,
        true,
        None,
        None,
    )?;
    Ok(result)
}

fn build_closure_evidence_quality_summary(
    validated_dataset: &ReplayDataset,
    evidence_records: &[PaperOutcomeEvidenceRecord],
) -> Option<PaperOutcomeEvidenceQualitySummary> {
    if evidence_records.is_empty() {
        return None;
    }
    let load_result = PaperOutcomeEvidenceLoadResult {
        loaded: true,
        evidence_file_id: "weak-label-closure-evidence".to_string(),
        record_count: evidence_records.len(),
        rejected_count: 0,
        duplicate_count: 0,
        records: evidence_records.to_vec(),
        rejected_records: Vec::new(),
        safety_warnings: Vec::new(),
        paper_only: true,
    };
    let matching = match_paper_outcome_evidence_to_replay(validated_dataset, evidence_records);
    Some(summarize_paper_outcome_evidence_quality(
        &load_result,
        &matching,
        &[],
    ))
}

fn closure_evidence_records_from_load(
    load_result: &PaperOutcomeEvidenceLoadResult,
) -> Vec<PaperOutcomeEvidenceRecord> {
    let mut records = load_result.records.clone();
    records.extend(load_result.rejected_records.iter().filter_map(|record| {
        if record.paper_only
            && paper_outcome_evidence_contradiction(record, &PaperLabelValidationPolicy::default())
        {
            Some(record.clone())
        } else {
            None
        }
    }));
    records.sort_by(|left, right| left.evidence_id.cmp(&right.evidence_id));
    records.dedup_by(|left, right| left.evidence_id == right.evidence_id);
    records
}

fn build_generated_closure_price_evidence(
    validated_dataset: &ReplayDataset,
    price_series_store: Option<&PaperPriceSeriesStore>,
) -> std::collections::BTreeMap<String, PaperOutcomeEvidenceRecord> {
    let Some(price_series_store) = price_series_store else {
        return std::collections::BTreeMap::new();
    };
    let empty_store = MemberExperienceStore::new("weak-label-closure-empty-store", Vec::new());
    let workbench = build_replay_evidence_workbench(
        validated_dataset,
        &empty_store,
        &[],
        &ReplayEvidenceWorkbenchConfig {
            workbench_id: format!("{}-weak-label-closure", validated_dataset.dataset_id),
            sanitized_dataset_path: None,
            experience_store_path: None,
            validated_dataset_path: None,
            existing_evidence_path: None,
            output_evidence_draft_path: None,
            output_generated_evidence_path: None,
            output_validated_replay_path: None,
            include_only_unvalidated: true,
            include_review_required: true,
            include_ambiguous: true,
            target_validated_label_ratio: 1.0,
            max_drafts: validated_dataset.examples.len().max(1),
            paper_only: true,
        },
    );
    let generated = build_paper_evidence_records_from_price_move_candidates(
        &generate_price_move_label_candidates(
            &workbench,
            price_series_store,
            &PaperPriceMoveLabelPolicy::default(),
        )
        .candidates,
    );
    let mut by_replay_id = std::collections::BTreeMap::new();
    for record in generated.generated_records {
        if let Some(replay_id) = &record.replay_id {
            by_replay_id.entry(replay_id.clone()).or_insert(record);
        }
    }
    by_replay_id
}

fn closure_auto_close_supported(record: &PaperOutcomeEvidenceRecord) -> bool {
    record.paper_only
        && record
            .replay_id
            .as_deref()
            .map(|replay_id| !replay_id.trim().is_empty())
            .unwrap_or(false)
        && matches!(
            record.validation_hint,
            Some(PaperOutcomeEvidenceValidationHint::PromoteIfPolicyPasses)
        )
        && paper_outcome_evidence_price_change(record).is_some()
        && !paper_outcome_evidence_contradiction(record, &PaperLabelValidationPolicy::default())
        && !matches!(record.candidate_label, MemberExperienceOutcome::Unknown)
        && !matches!(
            record.label_source,
            ReplayLabelSource::ReviewRequired
                | ReplayLabelSource::AmbiguousLabel
                | ReplayLabelSource::SimulatedFixture
                | ReplayLabelSource::RejectedLabel
                | ReplayLabelSource::PaperBacktestDeferred
                | ReplayLabelSource::PaperOutcomeUnknown
        )
        && matches!(
            record.label_confidence,
            ReplayLabelConfidence::Medium | ReplayLabelConfidence::High
        )
}

fn weak_label_current_exclusion_reasons(
    validated_dataset: &ReplayDataset,
) -> std::collections::BTreeMap<String, String> {
    build_replay_training_inclusion_mask(
        validated_dataset,
        &ReplayTrainingInclusionPolicy::default(),
    )
    .excluded_reasons
}

fn closure_status_for_weak_item(
    item: &WeakReplayLabelItem,
    current_exclusion_reason: Option<String>,
    existing_evidence: Option<&PaperOutcomeEvidenceRecord>,
    generated_price_evidence: Option<&PaperOutcomeEvidenceRecord>,
) -> (WeakLabelClosureStatus, WeakLabelClosureNextStep, String) {
    let missing_replay_id = item.replay_id.trim().is_empty()
        || item
            .weakness_reasons
            .contains(&WeakReplayLabelReason::MissingReplayId);
    let missing_decision_id = item
        .weakness_reasons
        .contains(&WeakReplayLabelReason::MissingDecisionId)
        && item.decision_id.as_deref().unwrap_or("").trim().is_empty();
    let missing_experience_id = item
        .weakness_reasons
        .contains(&WeakReplayLabelReason::MissingExperienceId)
        && item
            .experience_id
            .as_deref()
            .unwrap_or("")
            .trim()
            .is_empty();
    if missing_replay_id || missing_decision_id || missing_experience_id {
        let next_step = if missing_replay_id {
            WeakLabelClosureNextStep::AddReplayId
        } else if missing_decision_id {
            WeakLabelClosureNextStep::AddDecisionId
        } else {
            WeakLabelClosureNextStep::AddExperienceId
        };
        return (
            WeakLabelClosureStatus::NeedsIdBackfill,
            next_step,
            "required replay/decision/experience id is missing".to_string(),
        );
    }
    if existing_evidence
        .map(|record| {
            paper_outcome_evidence_contradiction(record, &PaperLabelValidationPolicy::default())
        })
        .unwrap_or(false)
        || matches!(item.current_label_source, ReplayLabelSource::RejectedLabel)
    {
        return (
            WeakLabelClosureStatus::RejectCandidate,
            WeakLabelClosureNextStep::RejectLabel,
            "contradictory paper evidence marks this label unsafe".to_string(),
        );
    }
    if matches!(
        item.current_label_source,
        ReplayLabelSource::SimulatedFixture
    ) {
        return (
            WeakLabelClosureStatus::KeepExcluded,
            WeakLabelClosureNextStep::KeepOutOfTraining,
            "simulated fixture labels stay excluded from offline training candidates".to_string(),
        );
    }
    if existing_evidence
        .map(closure_auto_close_supported)
        .unwrap_or(false)
        || generated_price_evidence
            .map(closure_auto_close_supported)
            .unwrap_or(false)
    {
        return (
            WeakLabelClosureStatus::ClosableWithExistingEvidence,
            WeakLabelClosureNextStep::UseExistingPriceEvidence,
            "deterministic local price evidence can close this weak label".to_string(),
        );
    }
    if item.current_outcome_label == MemberExperienceOutcome::Unknown
        || item
            .weakness_reasons
            .contains(&WeakReplayLabelReason::MissingPriceEvidence)
    {
        return (
            WeakLabelClosureStatus::NeedsPriceEvidence,
            WeakLabelClosureNextStep::AddPriceBars,
            "more local paper price bars are needed for exact-safe closure".to_string(),
        );
    }
    if matches!(
        item.current_label_source,
        ReplayLabelSource::AmbiguousLabel
            | ReplayLabelSource::ManualPaperLabel
            | ReplayLabelSource::ManualPaperOutcome
            | ReplayLabelSource::PaperOutcomeUnknown
            | ReplayLabelSource::ReviewRequired
    ) {
        return (
            WeakLabelClosureStatus::NeedsOwnerReview,
            WeakLabelClosureNextStep::AskOwnerForPaperReview,
            "owner paper review is required because exact-safe auto-closure is unavailable"
                .to_string(),
        );
    }
    (
        WeakLabelClosureStatus::KeepExcluded,
        WeakLabelClosureNextStep::KeepOutOfTraining,
        current_exclusion_reason.unwrap_or_else(|| {
            "weak label remains excluded until stronger paper evidence exists".to_string()
        }),
    )
}

pub fn build_weak_label_closure_inventory(
    validated_dataset: &ReplayDataset,
    evidence_store: &[PaperOutcomeEvidenceRecord],
    price_series_store: Option<&PaperPriceSeriesStore>,
) -> WeakLabelClosureInventory {
    let evidence_quality_summary =
        build_closure_evidence_quality_summary(validated_dataset, evidence_store);
    let weak_inventory =
        build_weak_replay_label_inventory(validated_dataset, evidence_quality_summary.as_ref());
    let existing_evidence_by_replay_id = closure_existing_evidence_by_replay_id(evidence_store);
    let generated_price_evidence_by_replay_id =
        build_generated_closure_price_evidence(validated_dataset, price_series_store);
    let current_exclusion_reasons = weak_label_current_exclusion_reasons(validated_dataset);
    let mut items = Vec::new();
    let mut closable_with_existing_evidence_count = 0;
    let mut needs_price_evidence_count = 0;
    let mut needs_id_backfill_count = 0;
    let mut needs_owner_review_count = 0;
    let mut keep_excluded_count = 0;
    let mut reject_count = 0;
    for weak_item in weak_inventory.weak_items {
        let current_exclusion_reason = current_exclusion_reasons.get(&weak_item.replay_id).cloned();
        let (closure_status, suggested_next_step, closure_reason) = closure_status_for_weak_item(
            &weak_item,
            current_exclusion_reason.clone(),
            select_existing_closure_evidence_for_weak_item(
                &weak_item,
                &existing_evidence_by_replay_id,
            ),
            generated_price_evidence_by_replay_id
                .get(&weak_item.replay_id)
                .filter(|record| closure_evidence_exact_for_weak_item(&weak_item, record)),
        );
        match closure_status {
            WeakLabelClosureStatus::ClosableWithExistingEvidence => {
                closable_with_existing_evidence_count += 1
            }
            WeakLabelClosureStatus::NeedsPriceEvidence => needs_price_evidence_count += 1,
            WeakLabelClosureStatus::NeedsIdBackfill => needs_id_backfill_count += 1,
            WeakLabelClosureStatus::NeedsOwnerReview => needs_owner_review_count += 1,
            WeakLabelClosureStatus::KeepExcluded => keep_excluded_count += 1,
            WeakLabelClosureStatus::RejectCandidate => reject_count += 1,
        }
        items.push(WeakLabelClosureItem {
            item_id: format!("closure-{}", weak_item.item_id),
            replay_id: weak_item.replay_id,
            experience_id: weak_item.experience_id,
            decision_id: weak_item.decision_id,
            member_id: weak_item.member_id,
            symbol: weak_item.symbol,
            market_scope: weak_item.market_scope,
            current_label_source: weak_item.current_label_source,
            current_label_confidence: weak_item.current_label_confidence,
            current_outcome_label: weak_item.current_outcome_label,
            current_exclusion_reason,
            closure_status,
            closure_reason,
            suggested_next_step,
            priority: weak_item.priority,
            paper_only: true,
        });
    }
    items.sort_by(|left, right| {
        left.replay_id
            .cmp(&right.replay_id)
            .then_with(|| left.member_id.cmp(&right.member_id))
            .then_with(|| left.item_id.cmp(&right.item_id))
    });
    WeakLabelClosureInventory {
        inventory_id: format!("{}-weak-label-closure", validated_dataset.dataset_id),
        source_validated_dataset_id: validated_dataset.dataset_id.clone(),
        weak_label_count: items.len(),
        closable_with_existing_evidence_count,
        needs_price_evidence_count,
        needs_id_backfill_count,
        needs_owner_review_count,
        keep_excluded_count,
        reject_count,
        items,
        paper_only: true,
    }
}

pub fn build_weak_label_closure_plan(
    inventory: &WeakLabelClosureInventory,
) -> WeakLabelClosurePlan {
    let mut planned_actions = Vec::new();
    for item in &inventory.items {
        let action_type = match item.closure_status {
            WeakLabelClosureStatus::ClosableWithExistingEvidence => {
                WeakLabelClosureActionType::AutoCloseWithExistingEvidence
            }
            WeakLabelClosureStatus::NeedsOwnerReview => {
                WeakLabelClosureActionType::GenerateOwnerReviewPrompt
            }
            WeakLabelClosureStatus::NeedsPriceEvidence => {
                WeakLabelClosureActionType::RequestMorePriceBars
            }
            WeakLabelClosureStatus::NeedsIdBackfill => {
                WeakLabelClosureActionType::RequestIdBackfill
            }
            WeakLabelClosureStatus::KeepExcluded => WeakLabelClosureActionType::KeepExcluded,
            WeakLabelClosureStatus::RejectCandidate => WeakLabelClosureActionType::Reject,
        };
        planned_actions.push(WeakLabelClosurePlannedAction {
            action_id: format!("plan-{}", item.item_id),
            replay_id: item.replay_id.clone(),
            action_type,
            reason: item.closure_reason.clone(),
            requires_owner_input: matches!(
                action_type,
                WeakLabelClosureActionType::GenerateOwnerReviewPrompt
            ),
            paper_only: true,
        });
    }
    WeakLabelClosurePlan {
        plan_id: format!("{}-plan", inventory.inventory_id),
        inventory_id: inventory.inventory_id.clone(),
        expected_closable_count: inventory.closable_with_existing_evidence_count,
        expected_remaining_weak_count: inventory
            .weak_label_count
            .saturating_sub(inventory.closable_with_existing_evidence_count),
        expected_training_included_count_after: inventory.closable_with_existing_evidence_count,
        planned_actions,
        paper_only: true,
    }
}

pub fn generate_owner_paper_review_prompts(
    closure_plan: &WeakLabelClosurePlan,
    inventory: &WeakLabelClosureInventory,
) -> OwnerPaperReviewPromptSet {
    let items_by_replay_id: std::collections::BTreeMap<&str, &WeakLabelClosureItem> = inventory
        .items
        .iter()
        .map(|item| (item.replay_id.as_str(), item))
        .collect();
    let prompts: Vec<OwnerPaperReviewPrompt> = closure_plan
        .planned_actions
        .iter()
        .filter(|action| {
            matches!(
                action.action_type,
                WeakLabelClosureActionType::GenerateOwnerReviewPrompt
            )
        })
        .filter_map(|action| {
            let item = items_by_replay_id.get(action.replay_id.as_str())?;
            Some(OwnerPaperReviewPrompt {
                prompt_id: action.action_id.clone(),
                replay_id: item.replay_id.clone(),
                symbol: item.symbol.clone(),
                market_scope: item.market_scope,
                member_id: item.member_id.clone(),
                question: format!(
                    "이 paper 판단은 replay {} / {} {:?} 기준으로 결과를 Positive, Negative, Neutral 중 무엇으로 기록할까요? 증거가 부족하면 KeepReviewRequired, 안전하지 않으면 Reject를 선택하세요.",
                    item.replay_id, item.symbol, item.market_scope
                ),
                context_summary: format!(
                    "member={} current={:?}/{:?} outcome={:?} next_step={:?} reason={}",
                    item.member_id,
                    item.current_label_source,
                    item.current_label_confidence,
                    item.current_outcome_label,
                    item.suggested_next_step,
                    item.closure_reason
                ),
                allowed_answers: vec![
                    OwnerPaperReviewAnswer::Positive,
                    OwnerPaperReviewAnswer::Negative,
                    OwnerPaperReviewAnswer::Neutral,
                    OwnerPaperReviewAnswer::KeepReviewRequired,
                    OwnerPaperReviewAnswer::Reject,
                ],
                paper_only_warning: "이 답변은 paper label 검토 전용이며 자동 실행, 자금 연결, 모델 변경과 분리됩니다.".to_string(),
                paper_only: true,
            })
        })
        .collect();
    OwnerPaperReviewPromptSet {
        prompt_set_id: format!("{}-owner-prompts", closure_plan.plan_id),
        prompt_count: prompts.len(),
        prompts,
        paper_only: true,
    }
}

fn owner_decision_for_closure_action(
    decisions_by_review_item: &std::collections::BTreeMap<String, PaperLabelReviewDecision>,
    decisions_by_replay_id: &std::collections::BTreeMap<String, PaperLabelReviewDecision>,
    action: &WeakLabelClosurePlannedAction,
) -> Option<PaperLabelReviewDecision> {
    decisions_by_review_item
        .get(&action.action_id)
        .cloned()
        .or_else(|| decisions_by_replay_id.get(&action.replay_id).cloned())
}

fn closure_review_decision_from_generated_evidence(
    action: &WeakLabelClosurePlannedAction,
    evidence_record: &PaperOutcomeEvidenceRecord,
) -> PaperLabelReviewDecision {
    PaperLabelReviewDecision {
        decision_id: format!("decision-{}", action.action_id),
        review_item_id: action.action_id.clone(),
        replay_id: action.replay_id.clone(),
        decision: PaperLabelReviewDecisionKind::PromoteToValidatedPaperLabel,
        reviewer: PaperLabelReviewer::PriceEvidenceRule,
        confidence: match evidence_record.label_confidence {
            ReplayLabelConfidence::High => ReplayLabelConfidence::High,
            ReplayLabelConfidence::Medium => ReplayLabelConfidence::Medium,
            ReplayLabelConfidence::Low | ReplayLabelConfidence::ReviewRequired => {
                ReplayLabelConfidence::Medium
            }
        },
        evidence_notes: vec!["exact-safe local price evidence auto-closed weak label".to_string()],
        paper_only: true,
    }
}

fn closure_existing_evidence_by_replay_id(
    evidence_store: &[PaperOutcomeEvidenceRecord],
) -> std::collections::BTreeMap<String, Vec<PaperOutcomeEvidenceRecord>> {
    let mut sorted_evidence = evidence_store.to_vec();
    sorted_evidence.sort_by(|left, right| left.evidence_id.cmp(&right.evidence_id));
    let mut by_replay_id = std::collections::BTreeMap::new();
    for record in sorted_evidence {
        if let Some(replay_id) = &record.replay_id {
            by_replay_id
                .entry(replay_id.clone())
                .or_insert_with(Vec::new)
                .push(record);
        }
    }
    by_replay_id
}

fn closure_evidence_exact_for_parts(
    replay_id: &str,
    symbol: &str,
    market_scope: MarketScope,
    record: &PaperOutcomeEvidenceRecord,
) -> bool {
    record.replay_id.as_deref() == Some(replay_id)
        && record.symbol == symbol
        && record.market_scope == market_scope
}

fn closure_evidence_exact_for_weak_item(
    item: &WeakReplayLabelItem,
    record: &PaperOutcomeEvidenceRecord,
) -> bool {
    closure_evidence_exact_for_parts(&item.replay_id, &item.symbol, item.market_scope, record)
}

fn closure_evidence_exact_for_example(
    example: &ReplayExample,
    record: &PaperOutcomeEvidenceRecord,
) -> bool {
    closure_evidence_exact_for_parts(
        &example.replay_id,
        &example.symbol,
        example.market_scope,
        record,
    )
}

fn select_existing_closure_evidence_for_weak_item<'a>(
    item: &WeakReplayLabelItem,
    evidence_by_replay_id: &'a std::collections::BTreeMap<String, Vec<PaperOutcomeEvidenceRecord>>,
) -> Option<&'a PaperOutcomeEvidenceRecord> {
    evidence_by_replay_id
        .get(&item.replay_id)?
        .iter()
        .find(|record| closure_evidence_exact_for_weak_item(item, record))
}

fn select_existing_closure_evidence_for_example<'a>(
    example: &ReplayExample,
    evidence_by_replay_id: &'a std::collections::BTreeMap<String, Vec<PaperOutcomeEvidenceRecord>>,
) -> Option<&'a PaperOutcomeEvidenceRecord> {
    evidence_by_replay_id
        .get(&example.replay_id)?
        .iter()
        .find(|record| closure_evidence_exact_for_example(example, record))
}

fn apply_weak_label_closure_plan_with_inputs(
    config: &WeakLabelClosureApplyConfig,
    validated_dataset: &ReplayDataset,
    evidence_store: &[PaperOutcomeEvidenceRecord],
    price_series_store: Option<&PaperPriceSeriesStore>,
) -> Result<WeakLabelClosureApplyResult, String> {
    if !config.paper_only {
        return Err("weak label closure apply config must be paper-only".to_string());
    }
    validate_optional_local_json_path(
        config.output_validated_dataset_path.as_ref(),
        "weak label closure output_validated_dataset_path",
    )?;
    validate_optional_local_json_path(
        config.output_closure_result_path.as_ref(),
        "weak label closure output_closure_result_path",
    )?;
    let inventory =
        build_weak_label_closure_inventory(validated_dataset, evidence_store, price_series_store);
    let plan = build_weak_label_closure_plan(&inventory);
    let owner_review_prompts = generate_owner_paper_review_prompts(&plan, &inventory);
    let previous_inclusion_mask = build_replay_training_inclusion_mask(
        validated_dataset,
        &ReplayTrainingInclusionPolicy::default(),
    );
    let previous_training_included_count = previous_inclusion_mask.included_count;
    let previous_weak_label_count = inventory.weak_label_count;
    let mut updated_validated_dataset = validated_dataset.clone();
    let existing_evidence_by_replay_id = closure_existing_evidence_by_replay_id(evidence_store);
    let generated_price_evidence_by_replay_id =
        build_generated_closure_price_evidence(validated_dataset, price_series_store);
    let actions_by_replay_id: std::collections::BTreeMap<String, WeakLabelClosurePlannedAction> =
        plan.planned_actions
            .iter()
            .cloned()
            .map(|action| (action.replay_id.clone(), action))
            .collect();
    let decision_file = if let Some(path) = &config.owner_review_decision_path {
        Some(load_paper_label_review_decisions_from_local_json(
            Path::new(path),
        )?)
    } else {
        None
    };
    let decisions_by_review_item: std::collections::BTreeMap<String, PaperLabelReviewDecision> =
        decision_file
            .as_ref()
            .map(|file| {
                file.decisions
                    .iter()
                    .cloned()
                    .map(|decision| (decision.review_item_id.clone(), decision))
                    .collect()
            })
            .unwrap_or_default();
    let decisions_by_replay_id: std::collections::BTreeMap<String, PaperLabelReviewDecision> =
        decision_file
            .as_ref()
            .map(|file| {
                file.decisions
                    .iter()
                    .cloned()
                    .map(|decision| (decision.replay_id.clone(), decision))
                    .collect()
            })
            .unwrap_or_default();
    let mut auto_closed_count = 0;
    let owner_review_needed_count = owner_review_prompts.prompt_count;
    let mut kept_excluded_count = 0;
    let mut rejected_count = 0;
    for example in &mut updated_validated_dataset.examples {
        let Some(action) = actions_by_replay_id.get(&example.replay_id) else {
            continue;
        };
        match action.action_type {
            WeakLabelClosureActionType::AutoCloseWithExistingEvidence => {
                let evidence_record = select_existing_closure_evidence_for_example(
                    example,
                    &existing_evidence_by_replay_id,
                )
                .or_else(|| {
                    generated_price_evidence_by_replay_id
                        .get(&example.replay_id)
                        .filter(|record| closure_evidence_exact_for_example(example, record))
                });
                let Some(evidence_record) = evidence_record else {
                    kept_excluded_count += 1;
                    continue;
                };
                let upgrade = evaluate_label_confidence_upgrade(
                    &closure_review_decision_from_generated_evidence(action, evidence_record),
                    evidence_record,
                    &LabelConfidenceUpgradePolicy::default(),
                );
                match upgrade.upgrade_status {
                    LabelConfidenceUpgradeStatus::Upgraded => {
                        apply_review_label_metadata(
                            example,
                            evidence_record.candidate_label,
                            upgrade.new_source,
                            upgrade.new_confidence,
                        );
                        auto_closed_count += 1;
                    }
                    LabelConfidenceUpgradeStatus::Rejected => {
                        apply_review_label_metadata(
                            example,
                            evidence_record.candidate_label,
                            upgrade.new_source,
                            upgrade.new_confidence,
                        );
                        rejected_count += 1;
                    }
                    LabelConfidenceUpgradeStatus::KeptWeak
                    | LabelConfidenceUpgradeStatus::NeedsMoreEvidence
                    | LabelConfidenceUpgradeStatus::BlockedByPolicy => {
                        kept_excluded_count += 1;
                    }
                }
            }
            WeakLabelClosureActionType::GenerateOwnerReviewPrompt => {
                let Some(decision) = owner_decision_for_closure_action(
                    &decisions_by_review_item,
                    &decisions_by_replay_id,
                    action,
                ) else {
                    kept_excluded_count += 1;
                    continue;
                };
                let mut evidence_record = select_existing_closure_evidence_for_example(
                    example,
                    &existing_evidence_by_replay_id,
                )
                .cloned()
                .or_else(|| {
                    generated_price_evidence_by_replay_id
                        .get(&example.replay_id)
                        .filter(|record| closure_evidence_exact_for_example(example, record))
                        .cloned()
                })
                .unwrap_or_else(|| placeholder_review_evidence(example));
                evidence_record.label_source = replay_label_source_for_example(example);
                evidence_record.label_confidence = replay_label_confidence_for_example(example);
                let upgrade = evaluate_label_confidence_upgrade(
                    &decision,
                    &evidence_record,
                    &LabelConfidenceUpgradePolicy::default(),
                );
                match upgrade.upgrade_status {
                    LabelConfidenceUpgradeStatus::Upgraded => {
                        apply_review_label_metadata(
                            example,
                            evidence_record.candidate_label,
                            upgrade.new_source,
                            upgrade.new_confidence,
                        );
                        auto_closed_count += 1;
                    }
                    LabelConfidenceUpgradeStatus::Rejected => {
                        apply_review_label_metadata(
                            example,
                            evidence_record.candidate_label,
                            upgrade.new_source,
                            upgrade.new_confidence,
                        );
                        rejected_count += 1;
                    }
                    LabelConfidenceUpgradeStatus::KeptWeak => {
                        apply_review_label_metadata(
                            example,
                            weak_label_current_outcome(example),
                            upgrade.new_source,
                            upgrade.new_confidence,
                        );
                        kept_excluded_count += 1;
                    }
                    LabelConfidenceUpgradeStatus::NeedsMoreEvidence
                    | LabelConfidenceUpgradeStatus::BlockedByPolicy => {
                        kept_excluded_count += 1;
                    }
                }
            }
            WeakLabelClosureActionType::Reject => {
                apply_review_label_metadata(
                    example,
                    weak_label_current_outcome(example),
                    ReplayLabelSource::RejectedLabel,
                    ReplayLabelConfidence::ReviewRequired,
                );
                rejected_count += 1;
            }
            WeakLabelClosureActionType::RequestMorePriceBars
            | WeakLabelClosureActionType::RequestIdBackfill
            | WeakLabelClosureActionType::KeepExcluded => {
                kept_excluded_count += 1;
            }
        }
    }
    let updated_training_inclusion_mask = build_replay_training_inclusion_mask(
        &updated_validated_dataset,
        &ReplayTrainingInclusionPolicy::default(),
    );
    let post_inventory = build_weak_label_closure_inventory(
        &updated_validated_dataset,
        evidence_store,
        price_series_store,
    );
    let result = WeakLabelClosureApplyResult {
        inventory,
        plan,
        owner_review_prompts,
        auto_closed_count,
        owner_review_needed_count,
        kept_excluded_count,
        rejected_count,
        updated_validated_dataset: updated_validated_dataset.clone(),
        updated_training_inclusion_mask: updated_training_inclusion_mask.clone(),
        previous_training_included_count,
        new_training_included_count: updated_training_inclusion_mask.included_count,
        previous_weak_label_count,
        new_weak_label_count: post_inventory.weak_label_count,
        paper_only: true,
    };
    if !config.dry_run {
        if let Some(path) = &config.output_validated_dataset_path {
            updated_validated_dataset.save_to_local_json(Path::new(path))?;
        }
        if let Some(path) = &config.output_closure_result_path {
            if let Some(parent) = Path::new(path).parent() {
                if !parent.as_os_str().is_empty() {
                    fs::create_dir_all(parent).map_err(|err| err.to_string())?;
                }
            }
            write_safe_json(Path::new(path), &result)?;
        }
    }
    Ok(result)
}

pub fn apply_weak_label_closure_plan(
    config: &WeakLabelClosureApplyConfig,
) -> Result<WeakLabelClosureApplyResult, String> {
    let validated_dataset_path = config
        .validated_dataset_path
        .as_ref()
        .ok_or_else(|| "weak label closure requires validated_dataset_path".to_string())?;
    if let Some(path) = &config.evidence_path {
        validate_local_json_path(Path::new(path), "weak label closure evidence path")?;
    }
    if let Some(path) = &config.price_series_path {
        validate_local_json_path(Path::new(path), "weak label closure price series path")?;
    }
    if let Some(path) = &config.owner_review_decision_path {
        validate_local_json_path(
            Path::new(path),
            "weak label closure owner_review_decision_path",
        )?;
    }
    let validated_dataset = ReplayDataset::load_from_local_json(Path::new(validated_dataset_path))?;
    let evidence_records = if let Some(path) = &config.evidence_path {
        closure_evidence_records_from_load(&load_paper_outcome_evidence_from_local_json(
            Path::new(path),
        )?)
    } else {
        Vec::new()
    };
    let price_series_store = if let Some(path) = &config.price_series_path {
        Some(load_price_series_store_from_local_json(Path::new(path))?)
    } else {
        None
    };
    apply_weak_label_closure_plan_with_inputs(
        config,
        &validated_dataset,
        &evidence_records,
        price_series_store.as_ref(),
    )
}

fn replay_target_labels_for_training(example: &ReplayExample) -> ReplayTargetLabels {
    example.target_labels.clone().unwrap_or(ReplayTargetLabels {
        stance_target: example.target.stance,
        confidence_calibration_target: example.target.confidence_calibration,
        risk_label: example.target.risk_label.clone(),
        evidence_label: example.target.evidence_label.clone(),
        outcome_label: example.target.outcome_label,
        attribution_label: MemberScoreUpdateReason::Neutral,
        label_source: ReplayLabelSource::ReviewRequired,
        label_confidence: ReplayLabelConfidence::ReviewRequired,
        paper_only: true,
    })
}

pub fn build_training_candidate_dataset(
    validated_dataset: &ReplayDataset,
    inclusion_mask: &ReplayTrainingInclusionMask,
    config: &TrainingCandidateBuildConfig,
) -> TrainingCandidateDataset {
    let included_ids: std::collections::BTreeSet<&str> = inclusion_mask
        .included_replay_ids
        .iter()
        .map(String::as_str)
        .collect();
    let sanitizer = ReplayFeatureSanitizer::default();
    let mut examples = Vec::new();
    for example in &validated_dataset.examples {
        if !included_ids.contains(example.replay_id.as_str()) {
            continue;
        }
        let label_source = replay_label_source_for_example(example);
        let label_confidence = replay_label_confidence_for_example(example);
        if config.include_only_validated_labels
            && !matches!(
                label_source,
                ReplayLabelSource::ValidatedPaperLabel | ReplayLabelSource::ValidatedBacktestLabel
            )
        {
            continue;
        }
        if config.exclude_review_required
            && matches!(
                label_source,
                ReplayLabelSource::ReviewRequired | ReplayLabelSource::AmbiguousLabel
            )
        {
            continue;
        }
        if config.exclude_simulated_fixture
            && matches!(label_source, ReplayLabelSource::SimulatedFixture)
        {
            continue;
        }
        if config.exclude_rejected && matches!(label_source, ReplayLabelSource::RejectedLabel) {
            continue;
        }
        if matches!(label_confidence, ReplayLabelConfidence::Medium)
            && !config.include_medium_confidence
        {
            continue;
        }
        if matches!(label_confidence, ReplayLabelConfidence::High)
            && !config.include_high_confidence
        {
            continue;
        }
        if matches!(
            label_confidence,
            ReplayLabelConfidence::Low | ReplayLabelConfidence::ReviewRequired
        ) {
            continue;
        }
        if let Some(min_sample_weight) = config.min_sample_weight {
            if example.sample_weight < min_sample_weight {
                continue;
            }
        }
        let sanitized_input_features = example
            .sanitized_input_features
            .clone()
            .unwrap_or_else(|| sanitizer.sanitize_replay_input_features(&example.input_features));
        examples.push(TrainingCandidateExample {
            training_example_id: format!("train-{}", example.replay_id),
            replay_id: example.replay_id.clone(),
            member_id: example.member_id.clone(),
            symbol: example.symbol.clone(),
            market_scope: example.market_scope,
            sanitized_input_features,
            target_labels: replay_target_labels_for_training(example),
            label_source,
            label_confidence,
            sample_weight: example.sample_weight,
            inclusion_reason: format!("included {:?}/{:?}", label_source, label_confidence),
            paper_only: true,
        });
    }
    examples.sort_by(|left, right| {
        left.training_example_id
            .cmp(&right.training_example_id)
            .then_with(|| left.replay_id.cmp(&right.replay_id))
    });
    let member_count = {
        let mut members: Vec<String> = examples
            .iter()
            .map(|example| example.member_id.clone())
            .collect();
        members.sort();
        members.dedup();
        members.len()
    };
    let symbol_count = {
        let mut symbols: Vec<String> = examples
            .iter()
            .map(|example| example.symbol.clone())
            .collect();
        symbols.sort();
        symbols.dedup();
        symbols.len()
    };
    let market_scope_count = {
        let mut scopes: Vec<String> = examples
            .iter()
            .map(|example| format!("{:?}", example.market_scope))
            .collect();
        scopes.sort();
        scopes.dedup();
        scopes.len()
    };
    let mut label_source_distribution = std::collections::BTreeMap::new();
    let mut confidence_distribution = std::collections::BTreeMap::new();
    for example in &examples {
        *label_source_distribution
            .entry(format!("{:?}", example.label_source))
            .or_insert(0usize) += 1;
        *confidence_distribution
            .entry(format!("{:?}", example.label_confidence))
            .or_insert(0usize) += 1;
    }
    TrainingCandidateDataset {
        dataset_id: format!("{}-training-candidates", validated_dataset.dataset_id),
        source_validated_dataset_id: validated_dataset.dataset_id.clone(),
        example_count: examples.len(),
        member_count,
        symbol_count,
        market_scope_count,
        label_source_distribution,
        confidence_distribution,
        examples,
        paper_only: true,
    }
}

fn training_split_group_key(
    example: &TrainingCandidateExample,
    stratify_by: TrainingSplitStratifyBy,
) -> String {
    match stratify_by {
        TrainingSplitStratifyBy::Member => example.member_id.clone(),
        TrainingSplitStratifyBy::MarketScope => format!("{:?}", example.market_scope),
        TrainingSplitStratifyBy::OutcomeLabel => {
            format!("{:?}", example.target_labels.outcome_label)
        }
        TrainingSplitStratifyBy::None => "all".to_string(),
    }
}

fn normalized_split_ratios(config: &TrainingSplitConfig) -> (f64, f64, f64) {
    let train = config.train_ratio.max(0.0);
    let validation = config.validation_ratio.max(0.0);
    let test = config.test_ratio.max(0.0);
    let total = train + validation + test;
    if total <= f64::EPSILON {
        (1.0, 0.0, 0.0)
    } else {
        (train / total, validation / total, test / total)
    }
}

fn largest_remainder_split_counts(
    total: usize,
    train_ratio: f64,
    validation_ratio: f64,
) -> (usize, usize, usize) {
    if total == 0 {
        return (0, 0, 0);
    }
    let train_exact = (total as f64) * train_ratio;
    let validation_exact = (total as f64) * validation_ratio;
    let test_exact = (total as f64) - train_exact - validation_exact;
    let mut counts = [
        train_exact.floor() as usize,
        validation_exact.floor() as usize,
        test_exact.floor() as usize,
    ];
    let mut remainder = total.saturating_sub(counts.iter().sum());
    let mut fractional = [
        (0usize, train_exact.fract()),
        (1usize, validation_exact.fract()),
        (2usize, test_exact.fract()),
    ];
    fractional.sort_by(|left, right| {
        right
            .1
            .total_cmp(&left.1)
            .then_with(|| left.0.cmp(&right.0))
    });
    for (index, _) in fractional {
        if remainder == 0 {
            break;
        }
        counts[index] += 1;
        remainder -= 1;
    }
    if counts[0] == 0 {
        counts[0] = 1;
        if counts[2] > 0 {
            counts[2] -= 1;
        } else if counts[1] > 0 {
            counts[1] -= 1;
        }
    }
    (counts[0], counts[1], counts[2])
}

pub fn build_training_split(
    dataset: &TrainingCandidateDataset,
    config: &TrainingSplitConfig,
) -> TrainingSplitResult {
    if dataset.examples.is_empty() {
        return TrainingSplitResult {
            dataset_id: dataset.dataset_id.clone(),
            train_ids: Vec::new(),
            validation_ids: Vec::new(),
            test_ids: Vec::new(),
            train_count: 0,
            validation_count: 0,
            test_count: 0,
            split_warnings: vec!["no training candidate examples available".to_string()],
            paper_only: true,
        };
    }
    if dataset.examples.len() < 3 {
        let train_ids: Vec<String> = dataset
            .examples
            .iter()
            .map(|example| example.training_example_id.clone())
            .collect();
        return TrainingSplitResult {
            dataset_id: dataset.dataset_id.clone(),
            train_count: train_ids.len(),
            validation_count: 0,
            test_count: 0,
            train_ids,
            validation_ids: Vec::new(),
            test_ids: Vec::new(),
            split_warnings: vec![
                "dataset too small for validation/test split; assigned all examples to train"
                    .to_string(),
            ],
            paper_only: true,
        };
    }
    let (train_ratio, validation_ratio, _test_ratio) = normalized_split_ratios(config);
    let mut grouped = std::collections::BTreeMap::<String, Vec<String>>::new();
    for example in &dataset.examples {
        grouped
            .entry(training_split_group_key(example, config.stratify_by))
            .or_default()
            .push(example.training_example_id.clone());
    }
    for (key, ids) in &mut grouped {
        ids.sort_by(|left, right| {
            stable_fnv1a64(&format!("{}:{key}:{left}", config.split_seed))
                .cmp(&stable_fnv1a64(&format!(
                    "{}:{key}:{right}",
                    config.split_seed
                )))
                .then_with(|| left.cmp(right))
        });
    }
    let mut ordered_ids = Vec::with_capacity(dataset.examples.len());
    let mut cursor = 0usize;
    loop {
        let mut pushed = false;
        for ids in grouped.values() {
            if let Some(id) = ids.get(cursor) {
                ordered_ids.push(id.clone());
                pushed = true;
            }
        }
        if !pushed {
            break;
        }
        cursor += 1;
    }
    let (train_target, validation_target, _) =
        largest_remainder_split_counts(ordered_ids.len(), train_ratio, validation_ratio);
    let train_ids = ordered_ids[..train_target].to_vec();
    let validation_end = (train_target + validation_target).min(ordered_ids.len());
    let validation_ids = ordered_ids[train_target..validation_end].to_vec();
    let test_ids = ordered_ids[validation_end..].to_vec();
    let mut split_warnings = Vec::new();
    if validation_ids.is_empty() {
        split_warnings.push("validation split is empty".to_string());
    }
    if test_ids.is_empty() {
        split_warnings.push("test split is empty".to_string());
    }
    TrainingSplitResult {
        dataset_id: dataset.dataset_id.clone(),
        train_count: train_ids.len(),
        validation_count: validation_ids.len(),
        test_count: test_ids.len(),
        train_ids,
        validation_ids,
        test_ids,
        split_warnings,
        paper_only: true,
    }
}

pub fn build_offline_trainer_dry_run_spec(
    dataset: &TrainingCandidateDataset,
    split: &TrainingSplitResult,
) -> OfflineTrainerDryRunSpec {
    OfflineTrainerDryRunSpec {
        spec_id: format!("{}-offline-trainer-dry-run", dataset.dataset_id),
        core_family: OfflineTrainerCoreFamily::SmartMemberCoreV2,
        temporal_core: SmartCoreV2ComponentStatus::Mamba3Deferred,
        memory_core: SmartCoreV2ComponentStatus::GatedDeltaNetDeferred,
        event_attention_core: SmartCoreV2ComponentStatus::SparseEventAttentionDeferred,
        heads: vec![
            OfflineTrainerHead::Stance,
            OfflineTrainerHead::ConfidenceCalibration,
            OfflineTrainerHead::Risk,
            OfflineTrainerHead::EvidenceNeed,
            OfflineTrainerHead::Uncertainty,
        ],
        dataset_id: dataset.dataset_id.clone(),
        split_summary: split.clone(),
        batch_size: dataset.example_count.clamp(1, 8),
        max_sequence_len_hint: 1,
        feature_schema_version: "sanitized-replay-input.v1".to_string(),
        target_schema_version: "replay-target-labels.v1".to_string(),
        training_execution: OfflineTrainerExecution::Deferred,
        paper_only: true,
    }
}

pub fn run_offline_trainer_data_loader_dry_run(
    dataset: &TrainingCandidateDataset,
    split: &TrainingSplitResult,
    spec: &OfflineTrainerDryRunSpec,
) -> OfflineTrainerDataLoaderDryRunResult {
    let known_ids: std::collections::BTreeSet<&str> = dataset
        .examples
        .iter()
        .map(|example| example.training_example_id.as_str())
        .collect();
    let train_id_set: std::collections::BTreeSet<&str> =
        split.train_ids.iter().map(String::as_str).collect();
    let mut warnings = split.split_warnings.clone();
    let feature_schema_valid = dataset
        .examples
        .iter()
        .all(|example| example.paper_only && example.sanitized_input_features.paper_only);
    let target_schema_valid = dataset.examples.iter().all(|example| {
        example.target_labels.paper_only
            && example.target_labels.outcome_label != MemberExperienceOutcome::Unknown
    });
    let split_ids_valid = split
        .train_ids
        .iter()
        .chain(split.validation_ids.iter())
        .chain(split.test_ids.iter())
        .all(|id| known_ids.contains(id.as_str()));
    if !split_ids_valid {
        warnings.push("split contains unknown training example ids".to_string());
    }
    let member_coverage_valid = {
        let dataset_members: std::collections::BTreeSet<&str> = dataset
            .examples
            .iter()
            .map(|example| example.member_id.as_str())
            .collect();
        let train_members: std::collections::BTreeSet<&str> = dataset
            .examples
            .iter()
            .filter(|example| train_id_set.contains(example.training_example_id.as_str()))
            .map(|example| example.member_id.as_str())
            .collect();
        dataset_members.is_subset(&train_members)
    };
    if !member_coverage_valid {
        warnings.push("train split does not cover every member".to_string());
    }
    let dry_run_status = if !feature_schema_valid || !target_schema_valid || !split_ids_valid {
        OfflineTrainerDryRunStatus::Failed
    } else if warnings.is_empty() {
        OfflineTrainerDryRunStatus::Passed
    } else {
        OfflineTrainerDryRunStatus::PassedWithWarnings
    };
    OfflineTrainerDataLoaderDryRunResult {
        spec_id: spec.spec_id.clone(),
        dataset_id: dataset.dataset_id.clone(),
        batch_count: if dataset.example_count == 0 {
            0
        } else {
            dataset.example_count.div_ceil(spec.batch_size)
        },
        example_count: dataset.example_count,
        feature_schema_valid,
        target_schema_valid,
        member_coverage_valid,
        no_training_executed: true,
        no_weight_mutation: true,
        dry_run_status,
        warnings,
        paper_only: true,
    }
}

pub fn evaluate_offline_training_design_gate(
    candidate_dataset: &TrainingCandidateDataset,
    split: &TrainingSplitResult,
    dry_run_result: &OfflineTrainerDataLoaderDryRunResult,
    quality_eval: &ReplayQualityEvalResult,
) -> OfflineTrainingDesignGate {
    let split_status = if split.train_count == 0 {
        TrainingSplitStatus::Invalid
    } else if split.validation_count == 0 || split.test_count == 0 {
        TrainingSplitStatus::TooSmall
    } else {
        TrainingSplitStatus::Ready
    };
    let member_coverage_status = if dry_run_result.member_coverage_valid {
        ReplayCoverageStatus::Sufficient
    } else {
        ReplayCoverageStatus::ThinCoverage
    };
    let label_quality_status = quality_eval
        .offline_training_readiness_gate
        .label_promotion_status;
    let leakage_status = quality_eval.leakage_check.leakage_status;
    let mut blockers = Vec::new();
    let mut warnings = dry_run_result.warnings.clone();
    if matches!(
        leakage_status,
        ReplayLeakageStatus::LeakageDetected | ReplayLeakageStatus::UnsafeForTraining
    ) {
        blockers.push("replay leakage safety gate blocked offline training design".to_string());
    }
    if !dry_run_result.no_training_executed || !dry_run_result.no_weight_mutation {
        blockers.push(
            "offline trainer dry-run must not execute training or mutate weights".to_string(),
        );
    }
    if matches!(
        dry_run_result.dry_run_status,
        OfflineTrainerDryRunStatus::Failed
    ) {
        blockers.push("offline trainer data-loader dry-run contract failed".to_string());
    }
    let design_status = if !blockers.is_empty() {
        OfflineTrainingDesignGateStatus::BlockedBySafety
    } else if candidate_dataset.example_count
        < quality_eval
            .offline_training_readiness_gate
            .min_examples_required
    {
        OfflineTrainingDesignGateStatus::NeedsMoreValidatedLabels
    } else if matches!(
        member_coverage_status,
        ReplayCoverageStatus::ThinCoverage | ReplayCoverageStatus::MissingCriticalCases
    ) {
        OfflineTrainingDesignGateStatus::NeedsMoreCoverage
    } else if matches!(split_status, TrainingSplitStatus::TooSmall)
        || matches!(
            dry_run_result.dry_run_status,
            OfflineTrainerDryRunStatus::PassedWithWarnings
        )
    {
        OfflineTrainingDesignGateStatus::ReadyWithWarnings
    } else {
        OfflineTrainingDesignGateStatus::ReadyForOfflineTrainerDryRun
    };
    if matches!(split_status, TrainingSplitStatus::TooSmall) {
        warnings.push(
            "candidate dataset is too small for a full train/validation/test split".to_string(),
        );
    }
    OfflineTrainingDesignGate {
        training_candidate_dataset_id: candidate_dataset.dataset_id.clone(),
        candidate_example_count: candidate_dataset.example_count,
        split_status,
        dry_run_status: dry_run_result.dry_run_status,
        member_coverage_status,
        label_quality_status,
        leakage_status,
        design_status,
        blockers,
        warnings,
        paper_only: true,
    }
}

fn research_source_is_local(kind: ResearchSourceKind) -> bool {
    matches!(
        kind,
        ResearchSourceKind::LocalMarketData
            | ResearchSourceKind::LocalNewsFixture
            | ResearchSourceKind::LocalPriceSeries
            | ResearchSourceKind::LocalRssFixture
    )
}

fn research_source_is_network(kind: ResearchSourceKind) -> bool {
    matches!(
        kind,
        ResearchSourceKind::AllowlistedRssFeed | ResearchSourceKind::AllowlistedHeadlineEndpoint
    )
}

fn research_source_unsafe_reasons(text: &str) -> Vec<String> {
    let lower = text.to_ascii_lowercase();
    let mut reasons = Vec::new();
    for prohibited in [
        "broker",
        "order",
        "account",
        "execution",
        "live trade",
        "live_trading",
        "real pnl",
        "article_body",
        "full_article",
        "content_html",
    ] {
        if lower.contains(prohibited) {
            reasons.push(format!(
                "research source rejected unsafe content: {prohibited}"
            ));
        }
    }
    reasons
}

fn validate_research_source_descriptor(source: &ResearchSourceDescriptor) -> Result<(), String> {
    if !source.paper_only {
        return Err("research source descriptor must be paper-only".to_string());
    }
    if source.source_id.trim().is_empty() || source.label.trim().is_empty() {
        return Err("research source descriptor requires source_id and label".to_string());
    }
    if source.max_items == 0 || source.max_summary_chars == 0 {
        return Err("research source descriptor limits must be positive".to_string());
    }
    if let Some(reason) = research_source_unsafe_reasons(&source.source_path_or_url).first() {
        return Err(reason.clone());
    }
    match source.kind {
        ResearchSourceKind::Disabled => Ok(()),
        kind if research_source_is_local(kind) => {
            if !local_only(&source.source_path_or_url) {
                return Err("local research source requires local path".to_string());
            }
            let path = Path::new(&source.source_path_or_url);
            let path_text = path
                .to_str()
                .ok_or_else(|| "research source local path must be valid UTF-8".to_string())?;
            if path_has_parent_component(path) {
                return Err(
                    "research source local path must not contain parent-directory traversal"
                        .to_string(),
                );
            }
            match kind {
                ResearchSourceKind::LocalRssFixture => {
                    if path.extension().and_then(|value| value.to_str()) != Some("xml") {
                        return Err("research source RSS fixture must point to XML".to_string());
                    }
                    if !local_only(path_text) {
                        return Err("research source local path must be local".to_string());
                    }
                    Ok(())
                }
                _ => validate_local_json_path(path, "research source local path"),
            }
        }
        kind if research_source_is_network(kind) => {
            let host = extract_url_host(&source.source_path_or_url)
                .ok_or_else(|| "network research source requires exact host".to_string())?;
            let allowed_host = source
                .allowed_host
                .as_ref()
                .ok_or_else(|| "network research source requires allowed_host".to_string())?
                .trim()
                .to_ascii_lowercase();
            if allowed_host.is_empty()
                || allowed_host.contains('*')
                || allowed_host.contains("://")
                || allowed_host.contains('/')
            {
                return Err("network research source requires exact non-wildcard host".to_string());
            }
            if host != allowed_host {
                return Err("network research source URL host must equal allowed_host".to_string());
            }
            if !source.source_path_or_url.starts_with("https://") {
                return Err("network research source requires https URL".to_string());
            }
            Ok(())
        }
        _ => Ok(()),
    }
}

fn normalize_research_source_registry(
    mut registry: ResearchSourceRegistry,
) -> ResearchSourceRegistry {
    registry
        .sources
        .sort_by(|left, right| left.source_id.cmp(&right.source_id));
    registry.enabled_count = registry
        .sources
        .iter()
        .filter(|source| source.enabled)
        .count();
    registry.network_enabled_count = registry
        .sources
        .iter()
        .filter(|source| source.enabled && research_source_is_network(source.kind))
        .count();
    registry.local_source_count = registry
        .sources
        .iter()
        .filter(|source| research_source_is_local(source.kind))
        .count();
    registry.paper_only = true;
    registry
}

fn self_growing_replay_requested_from_flags(
    enabled: bool,
    registry_path: Option<&String>,
    research_evidence_output_path: Option<&String>,
    self_growing_replay_output_path: Option<&String>,
    emit_research_task_summary: bool,
) -> bool {
    enabled
        || registry_path.is_some()
        || research_evidence_output_path.is_some()
        || self_growing_replay_output_path.is_some()
        || emit_research_task_summary
}

fn self_growing_promotion_requested_from_flags(
    staging_enabled: bool,
    promotion_enabled: bool,
    apply_promotions: bool,
    refresh_training_candidates: bool,
    staging_store_path: Option<&String>,
    approved_evidence_output_path: Option<&String>,
    training_candidate_output_path: Option<&String>,
) -> bool {
    staging_enabled
        || promotion_enabled
        || apply_promotions
        || refresh_training_candidates
        || staging_store_path.is_some()
        || approved_evidence_output_path.is_some()
        || training_candidate_output_path.is_some()
}

fn enriched_evidence_promotion_requested_from_flags(
    promotion_enabled: bool,
    apply_patch: bool,
    apply_promotions: bool,
    refresh_training_candidates: bool,
    staging_output_path: Option<&String>,
    approved_evidence_output_path: Option<&String>,
    training_candidate_output_path: Option<&String>,
) -> bool {
    promotion_enabled
        || apply_patch
        || apply_promotions
        || refresh_training_candidates
        || staging_output_path.is_some()
        || approved_evidence_output_path.is_some()
        || training_candidate_output_path.is_some()
}

fn auto_approval_e2e_requested_from_flags(
    enabled: bool,
    apply_promotions: bool,
    refresh_training_candidates: bool,
    success_staging_path: Option<&String>,
    success_price_series_path: Option<&String>,
    approved_evidence_output_path: Option<&String>,
    training_candidate_output_path: Option<&String>,
) -> bool {
    enabled
        || apply_promotions
        || refresh_training_candidates
        || success_staging_path.is_some()
        || success_price_series_path.is_some()
        || approved_evidence_output_path.is_some()
        || training_candidate_output_path.is_some()
}

impl ResearchSourceRegistry {
    pub fn validate_sources(&self) -> Result<(), String> {
        if !self.paper_only {
            return Err("research source registry must be paper-only".to_string());
        }
        let mut ids = std::collections::BTreeSet::new();
        for source in &self.sources {
            validate_research_source_descriptor(source)?;
            if !ids.insert(source.source_id.clone()) {
                return Err(format!("duplicate research source id {}", source.source_id));
            }
        }
        Ok(())
    }

    pub fn load_from_local_json(path: &Path) -> Result<Self, String> {
        validate_local_json_path(path, "research source registry path")?;
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        if let Some(reason) = research_source_unsafe_reasons(&text).first() {
            return Err(reason.clone());
        }
        let registry: ResearchSourceRegistry =
            serde_json::from_str(&text).map_err(|err| err.to_string())?;
        registry.validate_sources()?;
        Ok(normalize_research_source_registry(registry))
    }

    pub fn enabled_sources(&self) -> Vec<ResearchSourceDescriptor> {
        self.sources
            .iter()
            .filter(|source| source.enabled)
            .cloned()
            .collect()
    }

    pub fn disabled_sources(&self) -> Vec<ResearchSourceDescriptor> {
        self.sources
            .iter()
            .filter(|source| !source.enabled)
            .cloned()
            .collect()
    }

    pub fn sources_for_symbol(&self, symbol: &str) -> Vec<ResearchSourceDescriptor> {
        self.sources
            .iter()
            .filter(|source| source.enabled)
            .filter(|source| {
                source.symbols.is_empty() || source.symbols.iter().any(|item| item == symbol)
            })
            .cloned()
            .collect()
    }

    pub fn sources_for_scope(&self, scope: MarketScope) -> Vec<ResearchSourceDescriptor> {
        self.sources
            .iter()
            .filter(|source| source.enabled)
            .filter(|source| {
                source.market_scopes.is_empty() || source.market_scopes.contains(&scope)
            })
            .cloned()
            .collect()
    }
}

fn research_trust_level_base_score(level: ResearchSourceTrustLevel) -> f64 {
    match level {
        ResearchSourceTrustLevel::High => 0.95,
        ResearchSourceTrustLevel::Medium => 0.75,
        ResearchSourceTrustLevel::Low => 0.4,
        ResearchSourceTrustLevel::ReviewRequired => 0.15,
    }
}

pub fn evaluate_research_source_trust(
    registry: &ResearchSourceRegistry,
    recent_evidence: Option<&ResearchEvidenceBundle>,
) -> SourceTrustEvaluationResult {
    let evidence_counts: std::collections::BTreeMap<&str, usize> = recent_evidence
        .map(|bundle| {
            let mut counts = std::collections::BTreeMap::new();
            for record in &bundle.records {
                if let Some(source_id) = record.source_id.as_deref() {
                    *counts.entry(source_id).or_insert(0usize) += 1;
                }
            }
            counts
        })
        .unwrap_or_default();
    let mut source_scores = Vec::new();
    let mut trusted_count = 0;
    let mut review_required_count = 0;
    let mut rejected_count = 0;
    for source in &registry.sources {
        let base = research_trust_level_base_score(source.trust_level);
        let evidence_count = evidence_counts
            .get(source.source_id.as_str())
            .copied()
            .unwrap_or(0);
        let freshness_score = if source.enabled { 0.8 } else { 0.2 };
        let consistency_score = if evidence_count > 0 { 0.8 } else { 0.6 };
        let coverage_score = if !source.symbols.is_empty() || !source.market_scopes.is_empty() {
            0.8
        } else {
            0.6
        };
        let safety_score = if source.enabled || matches!(source.kind, ResearchSourceKind::Disabled)
        {
            1.0
        } else {
            0.7
        };
        let final_score = clamp_unit(
            (base + freshness_score + consistency_score + coverage_score + safety_score) / 5.0,
        );
        let mut reasons = Vec::new();
        if !source.enabled {
            reasons.push("source disabled by config".to_string());
        }
        if research_source_is_network(source.kind) {
            reasons.push("network source remains allowlisted-only".to_string());
        }
        let trust_status = if !source.enabled {
            SourceTrustStatus::Rejected
        } else if matches!(source.trust_level, ResearchSourceTrustLevel::ReviewRequired) {
            SourceTrustStatus::ReviewRequired
        } else if final_score >= 0.75 {
            SourceTrustStatus::Trusted
        } else if final_score >= 0.5 {
            SourceTrustStatus::UsableWithWarnings
        } else {
            SourceTrustStatus::ReviewRequired
        };
        match trust_status {
            SourceTrustStatus::Trusted => trusted_count += 1,
            SourceTrustStatus::ReviewRequired => review_required_count += 1,
            SourceTrustStatus::Rejected => rejected_count += 1,
            SourceTrustStatus::UsableWithWarnings => {}
        }
        source_scores.push(SourceTrustScore {
            source_id: source.source_id.clone(),
            base_trust_level: source.trust_level,
            freshness_score,
            consistency_score,
            coverage_score,
            safety_score,
            final_score,
            trust_status,
            reasons,
            paper_only: true,
        });
    }
    SourceTrustEvaluationResult {
        source_scores,
        trusted_count,
        review_required_count,
        rejected_count,
        paper_only: true,
    }
}

fn member_research_preferences_for_role(
    role: Option<IndependentMemberRole>,
) -> (Vec<MemberResearchTaskType>, Vec<ResearchSourceKind>) {
    match role {
        Some(IndependentMemberRole::TrendEntry) => (
            vec![
                MemberResearchTaskType::GatherNewsContext,
                MemberResearchTaskType::GatherPriceEvidence,
                MemberResearchTaskType::BuildReplayEvidenceCandidate,
            ],
            vec![
                ResearchSourceKind::LocalPriceSeries,
                ResearchSourceKind::LocalNewsFixture,
                ResearchSourceKind::LocalRssFixture,
                ResearchSourceKind::AllowlistedHeadlineEndpoint,
            ],
        ),
        Some(IndependentMemberRole::RiskGuard) => (
            vec![
                MemberResearchTaskType::ReviewRiskVetoCase,
                MemberResearchTaskType::FindContradictoryEvidence,
                MemberResearchTaskType::GatherPriceEvidence,
            ],
            vec![
                ResearchSourceKind::LocalPriceSeries,
                ResearchSourceKind::LocalMarketData,
                ResearchSourceKind::LocalNewsFixture,
            ],
        ),
        Some(IndependentMemberRole::EvidenceRegime) => (
            vec![
                MemberResearchTaskType::VerifyPaperOutcome,
                MemberResearchTaskType::ReviewNeedMoreEvidenceCase,
                MemberResearchTaskType::FillCoverageGap,
            ],
            vec![
                ResearchSourceKind::LocalNewsFixture,
                ResearchSourceKind::LocalRssFixture,
                ResearchSourceKind::LocalPriceSeries,
                ResearchSourceKind::LocalMarketData,
            ],
        ),
        None => (
            vec![MemberResearchTaskType::BuildReplayEvidenceCandidate],
            vec![
                ResearchSourceKind::LocalNewsFixture,
                ResearchSourceKind::LocalPriceSeries,
            ],
        ),
    }
}

fn member_task_type_for_weak_item(item: &WeakReplayLabelItem) -> MemberResearchTaskType {
    match role_for_member_id(&item.member_id) {
        Some(IndependentMemberRole::TrendEntry) => {
            if item.current_outcome_label == MemberExperienceOutcome::Unknown {
                MemberResearchTaskType::GatherPriceEvidence
            } else {
                MemberResearchTaskType::GatherNewsContext
            }
        }
        Some(IndependentMemberRole::RiskGuard) => {
            if item
                .weakness_reasons
                .contains(&WeakReplayLabelReason::ContradictoryEvidence)
            {
                MemberResearchTaskType::FindContradictoryEvidence
            } else {
                MemberResearchTaskType::ReviewRiskVetoCase
            }
        }
        Some(IndependentMemberRole::EvidenceRegime) => {
            if item.current_outcome_label == MemberExperienceOutcome::Unknown {
                MemberResearchTaskType::ReviewNeedMoreEvidenceCase
            } else {
                MemberResearchTaskType::VerifyPaperOutcome
            }
        }
        None => MemberResearchTaskType::BuildReplayEvidenceCandidate,
    }
}

fn member_task_type_for_gap(gap: &ReplayCoverageGap) -> (String, MemberResearchTaskType) {
    match gap.gap_type {
        ReplayCoverageGapType::RiskVetoMissing
        | ReplayCoverageGapType::HighConfidenceMistakeMissing => (
            "RiskGuardAI".to_string(),
            MemberResearchTaskType::ReviewRiskVetoCase,
        ),
        ReplayCoverageGapType::EvidenceGapMissing | ReplayCoverageGapType::LabelSourceWeak => (
            "EvidenceRegimeAI".to_string(),
            MemberResearchTaskType::FillCoverageGap,
        ),
        _ => (
            "TrendEntryAI".to_string(),
            MemberResearchTaskType::BuildReplayEvidenceCandidate,
        ),
    }
}

pub fn build_tasks_from_weak_labels(
    weak_inventory: &WeakReplayLabelInventory,
) -> MemberResearchTaskQueue {
    let mut tasks: Vec<MemberResearchTask> = weak_inventory
        .weak_items
        .iter()
        .map(|item| {
            let member_id = display_name_for_member_id(&item.member_id).to_string();
            let role = role_for_member_id(&item.member_id);
            let (_, source_preferences) = member_research_preferences_for_role(role);
            MemberResearchTask {
                task_id: format!("research-weak-{}", item.item_id),
                member_id,
                task_type: member_task_type_for_weak_item(item),
                symbol: Some(item.symbol.clone()),
                market_scope: Some(item.market_scope),
                related_replay_id: (!item.replay_id.trim().is_empty())
                    .then(|| item.replay_id.clone()),
                related_experience_id: item.experience_id.clone(),
                related_decision_id: item.decision_id.clone(),
                priority: item.priority,
                source_preferences,
                task_reason: format!("weak label follow-up: {:?}", item.weakness_reasons),
                paper_only: true,
            }
        })
        .collect();
    tasks.sort_by(|left, right| {
        right
            .priority
            .cmp(&left.priority)
            .then_with(|| left.member_id.cmp(&right.member_id))
            .then_with(|| left.task_id.cmp(&right.task_id))
    });
    MemberResearchTaskQueue {
        queue_id: format!("{}-member-research-tasks", weak_inventory.inventory_id),
        high_priority_count: tasks
            .iter()
            .filter(|task| task.priority == WeakReplayLabelPriority::High)
            .count(),
        tasks,
        paper_only: true,
    }
}

pub fn build_tasks_from_coverage_gaps(gaps: &[ReplayCoverageGap]) -> MemberResearchTaskQueue {
    let mut tasks: Vec<MemberResearchTask> = gaps
        .iter()
        .enumerate()
        .map(|(index, gap)| {
            let (member_id, task_type) = member_task_type_for_gap(gap);
            let role = role_for_member_id(&member_id);
            let (_, source_preferences) = member_research_preferences_for_role(role);
            MemberResearchTask {
                task_id: format!("research-gap-{}-{index}", gap.gap_id),
                member_id,
                task_type,
                symbol: gap.symbol.clone(),
                market_scope: gap.market_scope,
                related_replay_id: None,
                related_experience_id: None,
                related_decision_id: None,
                priority: match gap.priority {
                    ReplayCoverageGapPriority::High => WeakReplayLabelPriority::High,
                    ReplayCoverageGapPriority::Normal => WeakReplayLabelPriority::Normal,
                    ReplayCoverageGapPriority::Medium => WeakReplayLabelPriority::Normal,
                    ReplayCoverageGapPriority::Low => WeakReplayLabelPriority::Low,
                },
                source_preferences,
                task_reason: gap.reason.clone(),
                paper_only: true,
            }
        })
        .collect();
    tasks.sort_by(|left, right| {
        right
            .priority
            .cmp(&left.priority)
            .then_with(|| left.member_id.cmp(&right.member_id))
            .then_with(|| left.task_id.cmp(&right.task_id))
    });
    MemberResearchTaskQueue {
        queue_id: "coverage-gap-member-research-tasks".to_string(),
        high_priority_count: tasks
            .iter()
            .filter(|task| task.priority == WeakReplayLabelPriority::High)
            .count(),
        tasks,
        paper_only: true,
    }
}

pub fn build_tasks_from_attention_queue(
    attention_queue: &OwnerAttentionQueue,
) -> MemberResearchTaskQueue {
    let mut tasks: Vec<MemberResearchTask> = attention_queue
        .items
        .iter()
        .map(|item| {
            let (member_id, task_type, source_preferences) = match item.attention_type {
                OwnerAttentionType::RiskVeto => (
                    "RiskGuardAI".to_string(),
                    MemberResearchTaskType::ReviewRiskVetoCase,
                    vec![
                        ResearchSourceKind::LocalPriceSeries,
                        ResearchSourceKind::LocalMarketData,
                    ],
                ),
                OwnerAttentionType::NeedMoreEvidence => (
                    "EvidenceRegimeAI".to_string(),
                    MemberResearchTaskType::ReviewNeedMoreEvidenceCase,
                    vec![
                        ResearchSourceKind::LocalNewsFixture,
                        ResearchSourceKind::LocalRssFixture,
                        ResearchSourceKind::LocalPriceSeries,
                    ],
                ),
                _ => (
                    "TrendEntryAI".to_string(),
                    MemberResearchTaskType::GatherNewsContext,
                    vec![
                        ResearchSourceKind::LocalNewsFixture,
                        ResearchSourceKind::LocalRssFixture,
                    ],
                ),
            };
            MemberResearchTask {
                task_id: format!("research-attention-{}", item.item_id),
                member_id,
                task_type,
                symbol: item.symbol.clone(),
                market_scope: item.market_scope,
                related_replay_id: None,
                related_experience_id: None,
                related_decision_id: item.related_decision_id.clone(),
                priority: match item.priority {
                    OwnerAttentionPriority::High => WeakReplayLabelPriority::High,
                    OwnerAttentionPriority::Normal => WeakReplayLabelPriority::Normal,
                    OwnerAttentionPriority::Low => WeakReplayLabelPriority::Low,
                },
                source_preferences,
                task_reason: item.reason.clone(),
                paper_only: true,
            }
        })
        .collect();
    tasks.sort_by(|left, right| {
        right
            .priority
            .cmp(&left.priority)
            .then_with(|| left.member_id.cmp(&right.member_id))
            .then_with(|| left.task_id.cmp(&right.task_id))
    });
    MemberResearchTaskQueue {
        queue_id: format!("{}-member-research-tasks", attention_queue.queue_id),
        high_priority_count: tasks
            .iter()
            .filter(|task| task.priority == WeakReplayLabelPriority::High)
            .count(),
        tasks,
        paper_only: true,
    }
}

impl MemberResearchTaskQueue {
    pub fn sort_by_priority(&self) -> Self {
        let mut queue = self.clone();
        queue.tasks.sort_by(|left, right| {
            right
                .priority
                .cmp(&left.priority)
                .then_with(|| left.member_id.cmp(&right.member_id))
                .then_with(|| left.task_id.cmp(&right.task_id))
        });
        queue
    }

    pub fn next_tasks(&self, limit: usize) -> Vec<MemberResearchTask> {
        self.tasks.iter().take(limit).cloned().collect()
    }
}

fn research_source_matches_task(
    task: &MemberResearchTask,
    source: &ResearchSourceDescriptor,
) -> bool {
    if !task.source_preferences.is_empty() && !task.source_preferences.contains(&source.kind) {
        return false;
    }
    if let Some(symbol) = task.symbol.as_deref() {
        if !source.symbols.is_empty() && !source.symbols.iter().any(|item| item == symbol) {
            return false;
        }
    }
    if let Some(scope) = task.market_scope {
        if !source.market_scopes.is_empty() && !source.market_scopes.contains(&scope) {
            return false;
        }
    }
    true
}

fn truncate_research_summary(text: &str, max_chars: usize) -> String {
    text.chars().take(max_chars).collect()
}

fn build_news_research_records(
    task: &MemberResearchTask,
    source: &ResearchSourceDescriptor,
    items: &[CollectedNewsItem],
    trust_score: Option<f64>,
) -> Vec<ResearchEvidenceRecord> {
    items
        .iter()
        .take(source.max_items)
        .enumerate()
        .map(|(index, item)| ResearchEvidenceRecord {
            evidence_id: format!("evidence-{}-{}-{index}", source.source_id, task.task_id),
            task_id: Some(task.task_id.clone()),
            member_id: task.member_id.clone(),
            symbol: Some(item.symbol.clone()),
            market_scope: item.market_scope.or(task.market_scope),
            kind: ResearchEvidenceKind::NewsHeadline,
            headline: Some(item.headline.clone()),
            summary: Some(truncate_research_summary(
                &item.summary,
                source.max_summary_chars,
            )),
            source_id: Some(source.source_id.clone()),
            source_trust_score: trust_score,
            related_replay_id: task.related_replay_id.clone(),
            related_experience_id: task.related_experience_id.clone(),
            related_decision_id: task.related_decision_id.clone(),
            related_attention_item_id: None,
            evidence_confidence: ReplayLabelConfidence::ReviewRequired,
            evidence_notes: vec![
                "headline-only research evidence; no full article body stored".to_string(),
            ],
            paper_only: true,
        })
        .collect()
}

fn build_price_research_record(
    task: &MemberResearchTask,
    source: &ResearchSourceDescriptor,
    series: &PaperPriceSeries,
    trust_score: Option<f64>,
) -> Option<ResearchEvidenceRecord> {
    let first = series.bars.first()?;
    let last = series.bars.last()?;
    if first.close.abs() <= f64::EPSILON {
        return None;
    }
    let change = (last.close - first.close) / first.close;
    Some(ResearchEvidenceRecord {
        evidence_id: format!(
            "evidence-{}-{}-{}",
            source.source_id, task.task_id, series.series_id
        ),
        task_id: Some(task.task_id.clone()),
        member_id: task.member_id.clone(),
        symbol: Some(series.symbol.clone()),
        market_scope: Some(series.market_scope),
        kind: ResearchEvidenceKind::PriceMove,
        headline: Some(format!("paper price move for {}", series.symbol)),
        summary: Some(format!("price_change_pct={change:.6}")),
        source_id: Some(source.source_id.clone()),
        source_trust_score: trust_score,
        related_replay_id: task.related_replay_id.clone(),
        related_experience_id: task.related_experience_id.clone(),
        related_decision_id: task.related_decision_id.clone(),
        related_attention_item_id: None,
        evidence_confidence: if change.abs() >= 0.01 {
            ReplayLabelConfidence::Medium
        } else {
            ReplayLabelConfidence::Low
        },
        evidence_notes: vec![format!("price_change_pct={change:.6}")],
        paper_only: true,
    })
}

fn price_series_matches_research_task(
    series: &PaperPriceSeries,
    task: &MemberResearchTask,
) -> bool {
    task.symbol
        .as_ref()
        .map(|symbol| series.symbol == *symbol)
        .unwrap_or(true)
        && task
            .market_scope
            .map(|scope| series.market_scope == scope)
            .unwrap_or(true)
}

fn collect_research_evidence_with_network_mode(
    tasks: &[MemberResearchTask],
    registry: &ResearchSourceRegistry,
    source_scores: &[SourceTrustScore],
    allow_network_sources: bool,
) -> Result<ResearchEvidenceBundle, String> {
    registry.validate_sources()?;
    let score_by_source: std::collections::BTreeMap<&str, &SourceTrustScore> = source_scores
        .iter()
        .map(|score| (score.source_id.as_str(), score))
        .collect();
    let mut records = Vec::new();
    for task in tasks {
        for source in registry.enabled_sources() {
            if !research_source_matches_task(task, &source) {
                continue;
            }
            let trust_score = score_by_source
                .get(source.source_id.as_str())
                .map(|score| score.final_score);
            match source.kind {
                ResearchSourceKind::LocalNewsFixture => {
                    let items = load_collected_news_items_from_local_json(Path::new(
                        &source.source_path_or_url,
                    ))?;
                    let filtered: Vec<CollectedNewsItem> = items
                        .into_iter()
                        .filter(|item| {
                            task.symbol
                                .as_ref()
                                .map(|symbol| &item.symbol == symbol)
                                .unwrap_or(true)
                        })
                        .filter(|item| {
                            task.market_scope
                                .map(|scope| {
                                    item.market_scope == Some(scope) || item.market_scope.is_none()
                                })
                                .unwrap_or(true)
                        })
                        .collect();
                    records.extend(build_news_research_records(
                        task,
                        &source,
                        &filtered,
                        trust_score,
                    ));
                }
                ResearchSourceKind::LocalRssFixture => {
                    let xml_text = fs::read_to_string(&source.source_path_or_url)
                        .map_err(|err| err.to_string())?;
                    let parse_result = parse_rss_xml_fixture(
                        &xml_text,
                        RssXmlParseConfig {
                            parser_id: format!("{}-{}", source.source_id, task.task_id),
                            source_label: source.label.clone(),
                            symbol_hint: task.symbol.clone(),
                            market_scope: task.market_scope,
                            max_items: source.max_items,
                            max_summary_chars: source.max_summary_chars,
                            trust_level: NewsProviderTrustLevel::ReviewRequired,
                            paper_only: true,
                        },
                    );
                    let items = convert_rss_items_to_collected_news(&parse_result.parsed_items);
                    records.extend(build_news_research_records(
                        task,
                        &source,
                        &items,
                        trust_score,
                    ));
                }
                ResearchSourceKind::LocalPriceSeries => {
                    let store = load_price_series_store_from_local_json(Path::new(
                        &source.source_path_or_url,
                    ))?;
                    for series in store
                        .series
                        .iter()
                        .filter(|series| price_series_matches_research_task(series, task))
                        .take(source.max_items)
                    {
                        if let Some(record) =
                            build_price_research_record(task, &source, series, trust_score)
                        {
                            records.push(record);
                        }
                    }
                }
                ResearchSourceKind::LocalMarketData => {
                    let market_data =
                        load_market_data_from_local_json(Path::new(&source.source_path_or_url))?;
                    for (index, snapshot) in market_data
                        .into_iter()
                        .filter(|snapshot| {
                            task.symbol
                                .as_ref()
                                .map(|symbol| snapshot.symbol == *symbol)
                                .unwrap_or(true)
                                && task
                                    .market_scope
                                    .map(|scope| snapshot.market_scope == scope)
                                    .unwrap_or(true)
                        })
                        .take(source.max_items)
                        .enumerate()
                    {
                        records.push(ResearchEvidenceRecord {
                            evidence_id: format!(
                                "evidence-{}-{}-{index}",
                                source.source_id, task.task_id
                            ),
                            task_id: Some(task.task_id.clone()),
                            member_id: task.member_id.clone(),
                            symbol: Some(snapshot.symbol),
                            market_scope: Some(snapshot.market_scope),
                            kind: ResearchEvidenceKind::SupportingEvidence,
                            headline: Some("local market context".to_string()),
                            summary: Some(format!(
                                "price={} change_pct={} volatility_hint={}",
                                snapshot.price, snapshot.change_pct, snapshot.volatility_hint
                            )),
                            source_id: Some(source.source_id.clone()),
                            source_trust_score: trust_score,
                            related_replay_id: task.related_replay_id.clone(),
                            related_experience_id: task.related_experience_id.clone(),
                            related_decision_id: task.related_decision_id.clone(),
                            related_attention_item_id: None,
                            evidence_confidence: ReplayLabelConfidence::Low,
                            evidence_notes: vec![
                                "local market snapshot only; no trade execution".to_string(),
                            ],
                            paper_only: true,
                        });
                    }
                }
                ResearchSourceKind::AllowlistedRssFeed => {
                    if allow_network_sources {
                        let allowed_host = source.allowed_host.clone().unwrap_or_else(|| {
                            extract_url_host(&source.source_path_or_url).unwrap_or_default()
                        });
                        let result = run_single_allowlisted_rss_fetch_pilot_with_http_policy(
                            &RssFetchPilotConfig {
                                pilot_id: format!("{}-{}", source.source_id, task.task_id),
                                enabled: source.enabled,
                                rss_url: source.source_path_or_url.clone(),
                                allowed_domains: vec![allowed_host.clone()],
                                timeout_ms: default_safe_http_timeout_ms(),
                                rate_limit_ms: default_safe_news_rate_limit_ms(),
                                max_items: source.max_items,
                                max_summary_chars: source.max_summary_chars,
                                source_label: source.label.clone(),
                                symbol_hint: task.symbol.clone(),
                                market_scope: task.market_scope,
                                paper_only: true,
                            },
                            &SafeHttpClientPolicy {
                                network_enabled: true,
                                allowed_hosts: vec![allowed_host],
                                ..SafeHttpClientPolicy::default()
                            },
                            &DeferredRealHttpTransport,
                        )?;
                        records.extend(build_news_research_records(
                            task,
                            &source,
                            &result.collected_news,
                            trust_score,
                        ));
                    }
                }
                ResearchSourceKind::AllowlistedHeadlineEndpoint | ResearchSourceKind::Disabled => {}
            }
        }
    }
    records.sort_by(|left, right| left.evidence_id.cmp(&right.evidence_id));
    Ok(ResearchEvidenceBundle {
        bundle_id: format!("{}-research-evidence", registry.registry_id),
        source_scores: source_scores.to_vec(),
        task_count: tasks.len(),
        evidence_count: records.len(),
        records,
        paper_only: true,
    })
}

pub fn collect_research_evidence(
    tasks: &[MemberResearchTask],
    registry: &ResearchSourceRegistry,
    source_scores: &[SourceTrustScore],
) -> Result<ResearchEvidenceBundle, String> {
    collect_research_evidence_with_network_mode(tasks, registry, source_scores, false)
}

impl ResearchEvidenceBundle {
    pub fn evidence_by_member(&self, member_id: &str) -> Vec<ResearchEvidenceRecord> {
        self.records
            .iter()
            .filter(|record| record.member_id == member_id)
            .cloned()
            .collect()
    }

    pub fn evidence_by_symbol(&self, symbol: &str) -> Vec<ResearchEvidenceRecord> {
        self.records
            .iter()
            .filter(|record| record.symbol.as_deref() == Some(symbol))
            .cloned()
            .collect()
    }

    pub fn evidence_by_replay_id(&self, replay_id: &str) -> Vec<ResearchEvidenceRecord> {
        self.records
            .iter()
            .filter(|record| record.related_replay_id.as_deref() == Some(replay_id))
            .cloned()
            .collect()
    }
}

fn research_price_change_from_record(record: &ResearchEvidenceRecord) -> Option<f64> {
    record
        .evidence_notes
        .iter()
        .find_map(|note| {
            note.strip_prefix("price_change_pct=")
                .and_then(|value| value.parse().ok())
        })
        .or_else(|| {
            record.summary.as_deref().and_then(|summary| {
                summary
                    .strip_prefix("price_change_pct=")
                    .and_then(|value| value.parse().ok())
            })
        })
}

fn research_source_can_promote_label(score: Option<&SourceTrustScore>) -> bool {
    let Some(score) = score else {
        return false;
    };
    matches!(
        score.trust_status,
        SourceTrustStatus::Trusted | SourceTrustStatus::UsableWithWarnings
    ) && !matches!(
        score.base_trust_level,
        ResearchSourceTrustLevel::Low | ResearchSourceTrustLevel::ReviewRequired
    ) && score.final_score >= 0.5
}

pub fn convert_research_evidence_to_paper_outcome_evidence(
    bundle: &ResearchEvidenceBundle,
    policy: &ResearchToPaperEvidenceConversionPolicy,
) -> ResearchToPaperEvidenceConversionResult {
    let mut converted_records = Vec::new();
    let mut skipped_records = Vec::new();
    let mut skip_reasons = Vec::new();
    let score_by_source: std::collections::BTreeMap<&str, &SourceTrustScore> = bundle
        .source_scores
        .iter()
        .map(|score| (score.source_id.as_str(), score))
        .collect();
    let thresholds = PaperPriceMoveLabelPolicy::default();
    for record in &bundle.records {
        match record.kind {
            ResearchEvidenceKind::PriceMove if policy.allow_price_move_to_paper_evidence => {
                if policy.require_replay_or_decision_id
                    && record.related_replay_id.is_none()
                    && record.related_decision_id.is_none()
                {
                    skipped_records.push(record.clone());
                    skip_reasons
                        .push("price evidence requires replay_id or decision_id".to_string());
                    continue;
                }
                if !policy.allow_low_trust_source_promotion
                    && !research_source_can_promote_label(
                        record
                            .source_id
                            .as_deref()
                            .and_then(|source_id| score_by_source.get(source_id).copied()),
                    )
                {
                    skipped_records.push(record.clone());
                    skip_reasons.push(
                        "low or review-required trust price evidence cannot promote labels"
                            .to_string(),
                    );
                    continue;
                }
                let Some(change) = research_price_change_from_record(record) else {
                    skipped_records.push(record.clone());
                    skip_reasons.push("price evidence missing change percentage".to_string());
                    continue;
                };
                let candidate_label = if change >= thresholds.positive_threshold_pct {
                    MemberExperienceOutcome::PaperPositive
                } else if change <= thresholds.negative_threshold_pct {
                    MemberExperienceOutcome::PaperNegative
                } else if change.abs() <= thresholds.neutral_band_pct {
                    MemberExperienceOutcome::PaperNeutral
                } else {
                    MemberExperienceOutcome::Unknown
                };
                let confidence = if matches!(candidate_label, MemberExperienceOutcome::Unknown) {
                    ReplayLabelConfidence::ReviewRequired
                } else {
                    ReplayLabelConfidence::Medium
                };
                converted_records.push(PaperOutcomeEvidenceRecord {
                    evidence_id: format!("paper-evidence-{}", record.evidence_id),
                    symbol: record
                        .symbol
                        .clone()
                        .unwrap_or_else(|| "UNKNOWN".to_string()),
                    market_scope: record.market_scope.unwrap_or(MarketScope::UsShortTerm),
                    decision_id: record.related_decision_id.clone(),
                    event_id: None,
                    replay_id: record.related_replay_id.clone(),
                    experience_id: record.related_experience_id.clone(),
                    horizon: replay_evidence_horizon_for_scope(
                        record.market_scope.unwrap_or(MarketScope::UsShortTerm),
                    ),
                    horizon_bars: price_horizon_bars(replay_evidence_horizon_for_scope(
                        record.market_scope.unwrap_or(MarketScope::UsShortTerm),
                    )),
                    reference_price: None,
                    horizon_price: None,
                    price_change_pct: Some(change),
                    candidate_label,
                    label_source: if matches!(confidence, ReplayLabelConfidence::Medium) {
                        ReplayLabelSource::ManualPaperLabel
                    } else {
                        ReplayLabelSource::ReviewRequired
                    },
                    label_confidence: confidence,
                    evidence_notes: record.evidence_notes.clone(),
                    validation_hint: Some(if matches!(confidence, ReplayLabelConfidence::Medium) {
                        PaperOutcomeEvidenceValidationHint::PromoteIfPolicyPasses
                    } else {
                        PaperOutcomeEvidenceValidationHint::KeepReviewRequired
                    }),
                    paper_only: true,
                });
            }
            ResearchEvidenceKind::NewsHeadline
                if policy.allow_news_headline_to_context_evidence =>
            {
                skipped_records.push(record.clone());
                skip_reasons
                    .push("news headline alone cannot become validated label evidence".to_string());
            }
            _ => {
                skipped_records.push(record.clone());
                skip_reasons.push(
                    "research evidence kind not convertible to paper label evidence".to_string(),
                );
            }
        }
    }
    ResearchToPaperEvidenceConversionResult {
        converted_count: converted_records.len(),
        skipped_count: skipped_records.len(),
        converted_records,
        skipped_records,
        skip_reasons,
        paper_only: true,
    }
}

fn self_growing_evidence_kind_for_record(kind: ResearchEvidenceKind) -> SelfGrowingEvidenceKind {
    match kind {
        ResearchEvidenceKind::PriceMove => SelfGrowingEvidenceKind::PriceMove,
        ResearchEvidenceKind::NewsHeadline => SelfGrowingEvidenceKind::NewsContext,
        ResearchEvidenceKind::SourceTrust => SelfGrowingEvidenceKind::SourceTrust,
        ResearchEvidenceKind::ContradictoryEvidence => {
            SelfGrowingEvidenceKind::ContradictoryEvidence
        }
        ResearchEvidenceKind::SupportingEvidence => SelfGrowingEvidenceKind::SupportingEvidence,
        ResearchEvidenceKind::PaperOutcomeEvidenceCandidate => {
            SelfGrowingEvidenceKind::PaperOutcomeCandidate
        }
        ResearchEvidenceKind::CoverageGapEvidence => SelfGrowingEvidenceKind::CoverageGapEvidence,
    }
}

fn self_growing_label_source_for_kind(
    kind: SelfGrowingEvidenceKind,
) -> SelfGrowingEvidenceLabelSource {
    match kind {
        SelfGrowingEvidenceKind::PriceMove | SelfGrowingEvidenceKind::PaperOutcomeCandidate => {
            SelfGrowingEvidenceLabelSource::SelfGrowingPriceEvidence
        }
        SelfGrowingEvidenceKind::NewsContext => {
            SelfGrowingEvidenceLabelSource::SelfGrowingNewsContext
        }
        SelfGrowingEvidenceKind::SourceTrust => {
            SelfGrowingEvidenceLabelSource::SelfGrowingSourceTrust
        }
        SelfGrowingEvidenceKind::ContradictoryEvidence
        | SelfGrowingEvidenceKind::SupportingEvidence
        | SelfGrowingEvidenceKind::CoverageGapEvidence => {
            SelfGrowingEvidenceLabelSource::ReviewRequired
        }
    }
}

fn self_growing_candidate_label_from_record(
    record: &ResearchEvidenceRecord,
) -> Option<MemberExperienceOutcome> {
    match record.kind {
        ResearchEvidenceKind::PriceMove | ResearchEvidenceKind::PaperOutcomeEvidenceCandidate => {
            let thresholds = PaperPriceMoveLabelPolicy::default();
            research_price_change_from_record(record).map(|change| {
                if change >= thresholds.positive_threshold_pct {
                    MemberExperienceOutcome::PaperPositive
                } else if change <= thresholds.negative_threshold_pct {
                    MemberExperienceOutcome::PaperNegative
                } else if change.abs() <= thresholds.neutral_band_pct {
                    MemberExperienceOutcome::PaperNeutral
                } else {
                    MemberExperienceOutcome::Unknown
                }
            })
        }
        _ => None,
    }
}

fn self_growing_candidate_contains_unsafe_content(
    candidate: &SelfGrowingEvidenceCandidate,
) -> bool {
    let text =
        serde_json::to_string(candidate).unwrap_or_else(|_| candidate.evidence_notes.join("\n"));
    !research_source_unsafe_reasons(&text).is_empty()
}

fn normalize_self_growing_evidence_staging_store(
    mut store: SelfGrowingEvidenceStagingStore,
) -> SelfGrowingEvidenceStagingStore {
    store
        .candidates
        .sort_by(|left, right| left.candidate_id.cmp(&right.candidate_id));
    store.candidate_count = store.candidates.len();
    store.pending_count = store
        .candidates
        .iter()
        .filter(|candidate| {
            matches!(
                candidate.status,
                SelfGrowingEvidenceCandidateStatus::Pending
            )
        })
        .count();
    store.approved_count = store
        .candidates
        .iter()
        .filter(|candidate| {
            matches!(
                candidate.status,
                SelfGrowingEvidenceCandidateStatus::Approved
            )
        })
        .count();
    store.rejected_count = store
        .candidates
        .iter()
        .filter(|candidate| {
            matches!(
                candidate.status,
                SelfGrowingEvidenceCandidateStatus::Rejected
            )
        })
        .count();
    store.review_required_count = store
        .candidates
        .iter()
        .filter(|candidate| {
            matches!(
                candidate.status,
                SelfGrowingEvidenceCandidateStatus::ReviewRequired
            )
        })
        .count();
    store.paper_only = true;
    store
}

impl SelfGrowingEvidenceStagingStore {
    pub fn load_from_local_json(path: &Path) -> Result<Self, String> {
        validate_local_json_path(path, "self-growing evidence staging store path")?;
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        if let Some(reason) = research_source_unsafe_reasons(&text).first() {
            return Err(reason.clone());
        }
        let store: SelfGrowingEvidenceStagingStore =
            serde_json::from_str(&text).map_err(|err| err.to_string())?;
        if !store.paper_only {
            return Err("self-growing evidence staging store must be paper-only".to_string());
        }
        Ok(normalize_self_growing_evidence_staging_store(store))
    }

    pub fn save_to_local_json(&self, path: &Path) -> Result<(), String> {
        validate_local_json_path(path, "self-growing evidence staging store output path")?;
        if !self.paper_only {
            return Err("self-growing evidence staging store must be paper-only".to_string());
        }
        if self.candidates.iter().any(|candidate| {
            !candidate.paper_only || self_growing_candidate_contains_unsafe_content(candidate)
        }) {
            return Err(
                "self-growing evidence staging store contains unsafe candidate".to_string(),
            );
        }
        if let Some(parent) = path.parent() {
            if !parent.as_os_str().is_empty() {
                fs::create_dir_all(parent).map_err(|err| err.to_string())?;
            }
        }
        let text = serde_json::to_string_pretty(self).map_err(|err| err.to_string())?;
        fs::write(path, text).map_err(|err| err.to_string())
    }

    pub fn add_candidates(&mut self, candidates: Vec<SelfGrowingEvidenceCandidate>) {
        self.candidates.extend(candidates);
        *self = normalize_self_growing_evidence_staging_store(self.clone());
    }

    pub fn dedupe_by_candidate_id(&mut self) {
        let mut seen = std::collections::BTreeSet::new();
        self.candidates
            .retain(|candidate| seen.insert(candidate.candidate_id.clone()));
        *self = normalize_self_growing_evidence_staging_store(self.clone());
    }

    pub fn candidates_by_symbol(&self, symbol: &str) -> Vec<SelfGrowingEvidenceCandidate> {
        self.candidates
            .iter()
            .filter(|candidate| candidate.symbol.as_deref() == Some(symbol))
            .cloned()
            .collect()
    }

    pub fn candidates_by_member(&self, member_id: &str) -> Vec<SelfGrowingEvidenceCandidate> {
        self.candidates
            .iter()
            .filter(|candidate| candidate.member_id == member_id)
            .cloned()
            .collect()
    }

    pub fn pending_candidates(&self) -> Vec<SelfGrowingEvidenceCandidate> {
        self.candidates
            .iter()
            .filter(|candidate| {
                matches!(
                    candidate.status,
                    SelfGrowingEvidenceCandidateStatus::Pending
                )
            })
            .cloned()
            .collect()
    }

    pub fn approved_candidates(&self) -> Vec<SelfGrowingEvidenceCandidate> {
        self.candidates
            .iter()
            .filter(|candidate| {
                matches!(
                    candidate.status,
                    SelfGrowingEvidenceCandidateStatus::Approved
                )
            })
            .cloned()
            .collect()
    }

    pub fn rejected_candidates(&self) -> Vec<SelfGrowingEvidenceCandidate> {
        self.candidates
            .iter()
            .filter(|candidate| {
                matches!(
                    candidate.status,
                    SelfGrowingEvidenceCandidateStatus::Rejected
                )
            })
            .cloned()
            .collect()
    }
}

fn build_self_growing_evidence_staging_store_from_bundle(
    bundle: &ResearchEvidenceBundle,
) -> SelfGrowingEvidenceStagingStore {
    let trust_by_source: std::collections::BTreeMap<&str, SourceTrustStatus> = bundle
        .source_scores
        .iter()
        .map(|score| (score.source_id.as_str(), score.trust_status))
        .collect();
    let candidates = bundle
        .records
        .iter()
        .map(|record| SelfGrowingEvidenceCandidate {
            candidate_id: format!("candidate-{}", record.evidence_id),
            source_research_evidence_id: record.evidence_id.clone(),
            member_id: record.member_id.clone(),
            symbol: record.symbol.clone(),
            market_scope: record.market_scope,
            related_replay_id: record.related_replay_id.clone(),
            related_experience_id: record.related_experience_id.clone(),
            related_decision_id: record.related_decision_id.clone(),
            evidence_kind: self_growing_evidence_kind_for_record(record.kind),
            source_id: record.source_id.clone(),
            source_trust_status: record
                .source_id
                .as_deref()
                .and_then(|source_id| trust_by_source.get(source_id).copied())
                .unwrap_or(SourceTrustStatus::ReviewRequired),
            evidence_confidence: record.evidence_confidence,
            candidate_label: self_growing_candidate_label_from_record(record),
            label_source: self_growing_label_source_for_kind(
                self_growing_evidence_kind_for_record(record.kind),
            ),
            reference_price: None,
            horizon_price: None,
            price_change_pct: research_price_change_from_record(record),
            evidence_notes: record.evidence_notes.clone(),
            status: SelfGrowingEvidenceCandidateStatus::Pending,
            paper_only: true,
        })
        .collect();
    normalize_self_growing_evidence_staging_store(SelfGrowingEvidenceStagingStore {
        store_id: format!("{}-staging-store", bundle.bundle_id),
        candidates,
        candidate_count: 0,
        pending_count: 0,
        approved_count: 0,
        rejected_count: 0,
        review_required_count: 0,
        paper_only: true,
    })
}

fn self_growing_source_trust_score(status: SourceTrustStatus) -> f64 {
    match status {
        SourceTrustStatus::Trusted => 1.0,
        SourceTrustStatus::UsableWithWarnings => 0.75,
        SourceTrustStatus::ReviewRequired => 0.35,
        SourceTrustStatus::Rejected => 0.0,
    }
}

fn self_growing_replay_link_score(candidate: &SelfGrowingEvidenceCandidate) -> f64 {
    if candidate.related_replay_id.is_some() {
        1.0
    } else if candidate.related_decision_id.is_some() && candidate.related_experience_id.is_some() {
        0.8
    } else if candidate.related_decision_id.is_some() || candidate.related_experience_id.is_some() {
        0.55
    } else {
        0.1
    }
}

fn self_growing_evidence_type_score(kind: SelfGrowingEvidenceKind) -> f64 {
    match kind {
        SelfGrowingEvidenceKind::PriceMove => 1.0,
        SelfGrowingEvidenceKind::PaperOutcomeCandidate => 0.9,
        SelfGrowingEvidenceKind::ContradictoryEvidence => 0.7,
        SelfGrowingEvidenceKind::SupportingEvidence => 0.6,
        SelfGrowingEvidenceKind::CoverageGapEvidence => 0.5,
        SelfGrowingEvidenceKind::SourceTrust => 0.35,
        SelfGrowingEvidenceKind::NewsContext => 0.2,
    }
}

fn self_growing_label_strength_score(candidate: &SelfGrowingEvidenceCandidate) -> f64 {
    match candidate.candidate_label {
        Some(MemberExperienceOutcome::PaperPositive)
        | Some(MemberExperienceOutcome::PaperNegative)
        | Some(MemberExperienceOutcome::PaperNeutral) => 1.0,
        Some(MemberExperienceOutcome::Unknown) | None => 0.2,
        Some(_) => 0.4,
    }
}

pub fn score_self_growing_evidence_candidate(
    candidate: &SelfGrowingEvidenceCandidate,
    source_scores: &[SourceTrustScore],
) -> EvidenceCandidateScore {
    let source_score_lookup: std::collections::BTreeMap<&str, &SourceTrustScore> = source_scores
        .iter()
        .map(|score| (score.source_id.as_str(), score))
        .collect();
    let source_score = candidate
        .source_id
        .as_deref()
        .and_then(|source_id| source_score_lookup.get(source_id).copied());
    let effective_trust_status = source_score
        .map(|score| score.trust_status)
        .unwrap_or(candidate.source_trust_status);
    let source_trust_score = source_score
        .map(|score| score.final_score)
        .unwrap_or_else(|| self_growing_source_trust_score(effective_trust_status));
    let replay_link_score = self_growing_replay_link_score(candidate);
    let evidence_type_score = self_growing_evidence_type_score(candidate.evidence_kind);
    let label_strength_score = self_growing_label_strength_score(candidate);
    let unsafe_candidate =
        self_growing_candidate_contains_unsafe_content(candidate) || !candidate.paper_only;
    let safety_score = if unsafe_candidate { 0.0 } else { 1.0 };
    let mut total_score = clamp_unit(
        (source_trust_score
            + replay_link_score
            + evidence_type_score
            + label_strength_score
            + safety_score)
            / 5.0,
    );
    let mut reasons = Vec::new();
    if candidate.related_replay_id.is_some() {
        reasons.push("exact replay_id linked".to_string());
    } else if candidate.related_decision_id.is_some() || candidate.related_experience_id.is_some() {
        reasons.push("partial replay linkage only".to_string());
    } else {
        reasons.push("missing replay linkage".to_string());
    }
    if matches!(
        candidate.evidence_kind,
        SelfGrowingEvidenceKind::NewsContext
    ) {
        reasons.push("news-only evidence cannot auto-promote label".to_string());
    }
    let score_status =
        if unsafe_candidate || matches!(effective_trust_status, SourceTrustStatus::Rejected) {
            total_score = 0.0;
            reasons.push("unsafe or rejected source".to_string());
            EvidenceCandidateScoreStatus::Rejected
        } else if matches!(effective_trust_status, SourceTrustStatus::ReviewRequired) {
            reasons.push("source review required caps candidate strength".to_string());
            EvidenceCandidateScoreStatus::Weak
        } else if source_trust_score < 0.5 {
            total_score = total_score.min(0.49);
            reasons.push("low-trust source caps score".to_string());
            EvidenceCandidateScoreStatus::Weak
        } else if total_score >= 0.8 {
            EvidenceCandidateScoreStatus::Strong
        } else if total_score >= 0.65 {
            EvidenceCandidateScoreStatus::Acceptable
        } else {
            EvidenceCandidateScoreStatus::Weak
        };
    EvidenceCandidateScore {
        candidate_id: candidate.candidate_id.clone(),
        source_trust_score,
        replay_link_score,
        evidence_type_score,
        label_strength_score,
        safety_score,
        total_score,
        score_status,
        reasons,
        paper_only: true,
    }
}

fn self_growing_candidate_has_exact_match(candidate: &SelfGrowingEvidenceCandidate) -> bool {
    candidate.related_replay_id.is_some()
}

fn self_growing_candidate_missing_all_links(candidate: &SelfGrowingEvidenceCandidate) -> bool {
    candidate.related_replay_id.is_none()
        && candidate.related_decision_id.is_none()
        && candidate.related_experience_id.is_none()
}

fn self_growing_generated_paper_evidence(
    candidate: &SelfGrowingEvidenceCandidate,
) -> Option<PaperOutcomeEvidenceRecord> {
    let candidate_label = candidate.candidate_label?;
    if matches!(candidate_label, MemberExperienceOutcome::Unknown) {
        return None;
    }
    let market_scope = candidate.market_scope.unwrap_or(MarketScope::UsShortTerm);
    Some(PaperOutcomeEvidenceRecord {
        evidence_id: format!("approved-{}", candidate.candidate_id),
        symbol: candidate
            .symbol
            .clone()
            .unwrap_or_else(|| "UNKNOWN".to_string()),
        market_scope,
        decision_id: candidate.related_decision_id.clone(),
        event_id: None,
        replay_id: candidate.related_replay_id.clone(),
        experience_id: candidate.related_experience_id.clone(),
        horizon: replay_evidence_horizon_for_scope(market_scope),
        horizon_bars: price_horizon_bars(replay_evidence_horizon_for_scope(market_scope)),
        reference_price: candidate.reference_price,
        horizon_price: candidate.horizon_price,
        price_change_pct: candidate.price_change_pct.or_else(|| {
            candidate.evidence_notes.iter().find_map(|note| {
                note.strip_prefix("price_change_pct=")
                    .and_then(|value| value.parse().ok())
            })
        }),
        candidate_label,
        label_source: ReplayLabelSource::ManualPaperLabel,
        label_confidence: match candidate.evidence_confidence {
            ReplayLabelConfidence::High => ReplayLabelConfidence::High,
            ReplayLabelConfidence::Medium => ReplayLabelConfidence::Medium,
            ReplayLabelConfidence::Low | ReplayLabelConfidence::ReviewRequired => {
                ReplayLabelConfidence::Medium
            }
        },
        evidence_notes: candidate.evidence_notes.clone(),
        validation_hint: Some(PaperOutcomeEvidenceValidationHint::PromoteIfPolicyPasses),
        paper_only: true,
    })
}

pub fn evaluate_self_growing_evidence_promotion(
    candidate: &SelfGrowingEvidenceCandidate,
    score: &EvidenceCandidateScore,
    policy: &SelfGrowingEvidencePromotionPolicy,
) -> SelfGrowingEvidencePromotionDecision {
    let unsafe_candidate =
        self_growing_candidate_contains_unsafe_content(candidate) || !candidate.paper_only;
    let missing_price_label = policy.require_price_move_label
        && matches!(
            candidate.evidence_kind,
            SelfGrowingEvidenceKind::PriceMove | SelfGrowingEvidenceKind::PaperOutcomeCandidate
        )
        && !matches!(
            candidate.candidate_label,
            Some(MemberExperienceOutcome::PaperPositive)
                | Some(MemberExperienceOutcome::PaperNegative)
                | Some(MemberExperienceOutcome::PaperNeutral)
        );
    let missing_link = policy.require_replay_or_decision_id
        && candidate.related_replay_id.is_none()
        && candidate.related_decision_id.is_none();
    let ambiguous_match = !self_growing_candidate_has_exact_match(candidate)
        && !self_growing_candidate_missing_all_links(candidate);
    let news_only = matches!(
        candidate.evidence_kind,
        SelfGrowingEvidenceKind::NewsContext
    );
    let low_trust = matches!(
        candidate.source_trust_status,
        SourceTrustStatus::ReviewRequired | SourceTrustStatus::Rejected
    ) || score.source_trust_score < 0.5;
    let strong_enough = matches!(
        score.score_status,
        EvidenceCandidateScoreStatus::Strong | EvidenceCandidateScoreStatus::Acceptable
    ) && score.total_score >= policy.min_score_for_auto_approval;
    let trusted_enough = if policy.require_validated_source_trust {
        matches!(
            candidate.source_trust_status,
            SourceTrustStatus::Trusted | SourceTrustStatus::UsableWithWarnings
        )
    } else {
        !matches!(candidate.source_trust_status, SourceTrustStatus::Rejected)
    };
    let decision = if unsafe_candidate
        || matches!(score.score_status, EvidenceCandidateScoreStatus::Rejected)
    {
        SelfGrowingEvidencePromotionDecisionStatus::Rejected
    } else if news_only && !policy.allow_auto_approve_news_only {
        SelfGrowingEvidencePromotionDecisionStatus::NeedsReview
    } else if low_trust && !policy.allow_low_trust_promotion {
        SelfGrowingEvidencePromotionDecisionStatus::NeedsReview
    } else if missing_link {
        SelfGrowingEvidencePromotionDecisionStatus::NeedsReview
    } else if ambiguous_match && !policy.allow_ambiguous_match_promotion {
        SelfGrowingEvidencePromotionDecisionStatus::NeedsReview
    } else if missing_price_label {
        SelfGrowingEvidencePromotionDecisionStatus::NeedsReview
    } else if policy.allow_auto_approve_exact_price_evidence
        && matches!(
            candidate.evidence_kind,
            SelfGrowingEvidenceKind::PriceMove | SelfGrowingEvidenceKind::PaperOutcomeCandidate
        )
        && self_growing_candidate_has_exact_match(candidate)
        && trusted_enough
        && strong_enough
    {
        SelfGrowingEvidencePromotionDecisionStatus::AutoApproved
    } else {
        SelfGrowingEvidencePromotionDecisionStatus::KeptStaged
    };
    let reason = match decision {
        SelfGrowingEvidencePromotionDecisionStatus::AutoApproved => {
            "exact price evidence passed promotion gate".to_string()
        }
        SelfGrowingEvidencePromotionDecisionStatus::NeedsReview if news_only => {
            "news-only evidence must stay in review".to_string()
        }
        SelfGrowingEvidencePromotionDecisionStatus::NeedsReview if low_trust => {
            "low-trust or review-required source must stay in review".to_string()
        }
        SelfGrowingEvidencePromotionDecisionStatus::NeedsReview if missing_link => {
            "missing replay or decision linkage".to_string()
        }
        SelfGrowingEvidencePromotionDecisionStatus::NeedsReview if ambiguous_match => {
            "ambiguous replay linkage".to_string()
        }
        SelfGrowingEvidencePromotionDecisionStatus::NeedsReview if missing_price_label => {
            "price evidence missing promotable label".to_string()
        }
        SelfGrowingEvidencePromotionDecisionStatus::Rejected => {
            "unsafe or rejected candidate blocked".to_string()
        }
        SelfGrowingEvidencePromotionDecisionStatus::KeptStaged => {
            "candidate kept staged pending stronger evidence".to_string()
        }
        SelfGrowingEvidencePromotionDecisionStatus::NeedsReview => {
            "candidate requires review".to_string()
        }
    };
    SelfGrowingEvidencePromotionDecision {
        candidate_id: candidate.candidate_id.clone(),
        score: score.clone(),
        decision,
        reason,
        generated_paper_evidence: matches!(
            decision,
            SelfGrowingEvidencePromotionDecisionStatus::AutoApproved
        )
        .then(|| self_growing_generated_paper_evidence(candidate))
        .flatten(),
        paper_only: true,
    }
}

pub fn build_staged_evidence_review_queue(
    candidates: &[SelfGrowingEvidenceCandidate],
    promotion_decisions: &[SelfGrowingEvidencePromotionDecision],
) -> StagedEvidenceReviewQueue {
    let candidate_by_id: std::collections::BTreeMap<&str, &SelfGrowingEvidenceCandidate> =
        candidates
            .iter()
            .map(|candidate| (candidate.candidate_id.as_str(), candidate))
            .collect();
    let mut items = Vec::new();
    for decision in promotion_decisions {
        let Some(candidate) = candidate_by_id.get(decision.candidate_id.as_str()).copied() else {
            continue;
        };
        let Some((review_reason, suggested_action, priority)) = (match decision.decision {
            SelfGrowingEvidencePromotionDecisionStatus::AutoApproved => None,
            SelfGrowingEvidencePromotionDecisionStatus::Rejected => Some((
                StagedEvidenceReviewReason::UnsafeRejected,
                StagedEvidenceReviewSuggestedAction::Reject,
                WeakReplayLabelPriority::High,
            )),
            SelfGrowingEvidencePromotionDecisionStatus::NeedsReview
                if matches!(
                    candidate.evidence_kind,
                    SelfGrowingEvidenceKind::NewsContext
                ) =>
            {
                Some((
                    StagedEvidenceReviewReason::NewsOnlyEvidence,
                    StagedEvidenceReviewSuggestedAction::AddPriceEvidence,
                    WeakReplayLabelPriority::Normal,
                ))
            }
            SelfGrowingEvidencePromotionDecisionStatus::NeedsReview
                if self_growing_candidate_missing_all_links(candidate) =>
            {
                Some((
                    StagedEvidenceReviewReason::MissingReplayId,
                    StagedEvidenceReviewSuggestedAction::AddReplayId,
                    WeakReplayLabelPriority::High,
                ))
            }
            SelfGrowingEvidencePromotionDecisionStatus::NeedsReview
                if !self_growing_candidate_has_exact_match(candidate) =>
            {
                Some((
                    StagedEvidenceReviewReason::AmbiguousReplayMatch,
                    StagedEvidenceReviewSuggestedAction::AddDecisionId,
                    WeakReplayLabelPriority::High,
                ))
            }
            SelfGrowingEvidencePromotionDecisionStatus::NeedsReview
                if matches!(
                    candidate.source_trust_status,
                    SourceTrustStatus::ReviewRequired
                ) =>
            {
                Some((
                    StagedEvidenceReviewReason::SourceReviewRequired,
                    StagedEvidenceReviewSuggestedAction::AddSourceValidation,
                    WeakReplayLabelPriority::Normal,
                ))
            }
            SelfGrowingEvidencePromotionDecisionStatus::NeedsReview
                if decision.score.source_trust_score < 0.5 =>
            {
                Some((
                    StagedEvidenceReviewReason::LowTrustSource,
                    StagedEvidenceReviewSuggestedAction::AddSourceValidation,
                    WeakReplayLabelPriority::High,
                ))
            }
            SelfGrowingEvidencePromotionDecisionStatus::NeedsReview => Some((
                StagedEvidenceReviewReason::MissingPriceEvidence,
                StagedEvidenceReviewSuggestedAction::KeepStaged,
                WeakReplayLabelPriority::Normal,
            )),
            SelfGrowingEvidencePromotionDecisionStatus::KeptStaged => Some((
                StagedEvidenceReviewReason::MissingPriceEvidence,
                StagedEvidenceReviewSuggestedAction::KeepStaged,
                WeakReplayLabelPriority::Low,
            )),
        }) else {
            continue;
        };
        items.push(StagedEvidenceReviewItem {
            review_item_id: format!("review-{}", candidate.candidate_id),
            candidate_id: candidate.candidate_id.clone(),
            member_id: candidate.member_id.clone(),
            symbol: candidate.symbol.clone(),
            market_scope: candidate.market_scope,
            review_reason,
            suggested_action,
            priority,
            paper_only: true,
        });
    }
    items.sort_by(|left, right| {
        right
            .priority
            .cmp(&left.priority)
            .then_with(|| left.review_item_id.cmp(&right.review_item_id))
    });
    StagedEvidenceReviewQueue {
        queue_id: "self-growing-evidence-review-queue".to_string(),
        high_priority_count: items
            .iter()
            .filter(|item| item.priority == WeakReplayLabelPriority::High)
            .count(),
        items,
        paper_only: true,
    }
}

fn self_growing_candidate_has_price_evidence(candidate: &SelfGrowingEvidenceCandidate) -> bool {
    candidate.price_change_pct.is_some()
        || candidate
            .evidence_notes
            .iter()
            .any(|note| note.starts_with("price_change_pct="))
}

fn self_growing_candidate_is_news_only(candidate: &SelfGrowingEvidenceCandidate) -> bool {
    matches!(
        candidate.evidence_kind,
        SelfGrowingEvidenceKind::NewsContext
    )
}

fn self_growing_candidate_is_low_trust(
    candidate: &SelfGrowingEvidenceCandidate,
    score: &EvidenceCandidateScore,
) -> bool {
    matches!(
        candidate.source_trust_status,
        SourceTrustStatus::ReviewRequired | SourceTrustStatus::Rejected
    ) || score.source_trust_score < 0.5
}

fn self_growing_candidate_is_ambiguous(candidate: &SelfGrowingEvidenceCandidate) -> bool {
    !self_growing_candidate_has_exact_match(candidate)
        && !self_growing_candidate_missing_all_links(candidate)
}

fn self_growing_candidate_is_safe_exact_price_evidence(
    candidate: &SelfGrowingEvidenceCandidate,
    score: &EvidenceCandidateScore,
) -> bool {
    matches!(
        candidate.evidence_kind,
        SelfGrowingEvidenceKind::PriceMove | SelfGrowingEvidenceKind::PaperOutcomeCandidate
    ) && self_growing_candidate_has_exact_match(candidate)
        && self_growing_candidate_has_price_evidence(candidate)
        && matches!(
            candidate.candidate_label,
            Some(MemberExperienceOutcome::PaperPositive)
                | Some(MemberExperienceOutcome::PaperNegative)
                | Some(MemberExperienceOutcome::PaperNeutral)
        )
        && !self_growing_candidate_is_low_trust(candidate, score)
        && !self_growing_candidate_is_ambiguous(candidate)
        && !self_growing_candidate_contains_unsafe_content(candidate)
        && candidate.paper_only
}

fn push_unique_note(notes: &mut Vec<String>, note: String) {
    if !notes.iter().any(|existing| existing == &note) {
        notes.push(note);
    }
}

fn staged_evidence_failure_reasons(
    candidate: &SelfGrowingEvidenceCandidate,
    decision: &SelfGrowingEvidencePromotionDecision,
) -> Vec<StagedEvidenceFailureReason> {
    let mut reasons = Vec::new();
    if !candidate.paper_only {
        reasons.push(StagedEvidenceFailureReason::NotPaperOnly);
    }
    if self_growing_candidate_contains_unsafe_content(candidate) {
        reasons.push(StagedEvidenceFailureReason::UnsafeEvidence);
    }
    if candidate.related_replay_id.is_none() {
        reasons.push(StagedEvidenceFailureReason::MissingReplayId);
    }
    if candidate.related_decision_id.is_none() {
        reasons.push(StagedEvidenceFailureReason::MissingDecisionId);
    }
    if candidate.related_experience_id.is_none() {
        reasons.push(StagedEvidenceFailureReason::MissingExperienceId);
    }
    if self_growing_candidate_is_news_only(candidate) {
        reasons.push(StagedEvidenceFailureReason::NewsOnlyEvidence);
    }
    if matches!(
        candidate.source_trust_status,
        SourceTrustStatus::ReviewRequired
    ) {
        reasons.push(StagedEvidenceFailureReason::SourceReviewRequired);
    }
    if self_growing_candidate_is_low_trust(candidate, &decision.score) {
        reasons.push(StagedEvidenceFailureReason::LowTrustSource);
    }
    if self_growing_candidate_is_ambiguous(candidate) {
        reasons.push(StagedEvidenceFailureReason::AmbiguousReplayMatch);
    }
    if !self_growing_candidate_has_price_evidence(candidate)
        && matches!(
            candidate.evidence_kind,
            SelfGrowingEvidenceKind::PriceMove
                | SelfGrowingEvidenceKind::PaperOutcomeCandidate
                | SelfGrowingEvidenceKind::NewsContext
        )
    {
        reasons.push(StagedEvidenceFailureReason::MissingPriceEvidence);
    }
    if matches!(
        decision.decision,
        SelfGrowingEvidencePromotionDecisionStatus::Rejected
    ) && !reasons.contains(&StagedEvidenceFailureReason::UnsafeEvidence)
    {
        reasons.push(StagedEvidenceFailureReason::UnsafeEvidence);
    }
    reasons
}

fn staged_evidence_suggested_fix(
    reasons: &[StagedEvidenceFailureReason],
) -> StagedEvidenceSuggestedFix {
    if reasons.contains(&StagedEvidenceFailureReason::UnsafeEvidence)
        || reasons.contains(&StagedEvidenceFailureReason::NotPaperOnly)
    {
        return StagedEvidenceSuggestedFix::RejectCandidate;
    }
    if reasons.contains(&StagedEvidenceFailureReason::MissingReplayId) {
        return StagedEvidenceSuggestedFix::LinkReplayId;
    }
    if reasons.contains(&StagedEvidenceFailureReason::MissingDecisionId) {
        return StagedEvidenceSuggestedFix::LinkDecisionId;
    }
    if reasons.contains(&StagedEvidenceFailureReason::MissingExperienceId) {
        return StagedEvidenceSuggestedFix::LinkExperienceId;
    }
    if reasons.contains(&StagedEvidenceFailureReason::MissingPriceEvidence)
        || reasons.contains(&StagedEvidenceFailureReason::NewsOnlyEvidence)
    {
        return StagedEvidenceSuggestedFix::AttachLocalPriceEvidence;
    }
    if reasons.contains(&StagedEvidenceFailureReason::LowTrustSource)
        || reasons.contains(&StagedEvidenceFailureReason::SourceReviewRequired)
    {
        return StagedEvidenceSuggestedFix::ImproveSourceTrust;
    }
    StagedEvidenceSuggestedFix::KeepInReview
}

pub fn analyze_staged_evidence_review_queue(
    candidates: &[SelfGrowingEvidenceCandidate],
    promotion_decisions: &[SelfGrowingEvidencePromotionDecision],
) -> StagedEvidenceReviewAnalysis {
    let candidate_by_id: std::collections::BTreeMap<&str, &SelfGrowingEvidenceCandidate> =
        candidates
            .iter()
            .map(|candidate| (candidate.candidate_id.as_str(), candidate))
            .collect();
    let mut review_items = Vec::new();
    let mut missing_replay_link_count = 0;
    let mut news_only_count = 0;
    let mut low_trust_count = 0;
    let mut ambiguous_count = 0;
    let mut missing_price_evidence_count = 0;
    let mut unsafe_count = 0;
    for decision in promotion_decisions {
        let Some(candidate) = candidate_by_id.get(decision.candidate_id.as_str()).copied() else {
            continue;
        };
        let reasons = staged_evidence_failure_reasons(candidate, decision);
        if reasons.contains(&StagedEvidenceFailureReason::MissingReplayId) {
            missing_replay_link_count += 1;
        }
        if reasons.contains(&StagedEvidenceFailureReason::NewsOnlyEvidence) {
            news_only_count += 1;
        }
        if reasons.contains(&StagedEvidenceFailureReason::LowTrustSource)
            || reasons.contains(&StagedEvidenceFailureReason::SourceReviewRequired)
        {
            low_trust_count += 1;
        }
        if reasons.contains(&StagedEvidenceFailureReason::AmbiguousReplayMatch) {
            ambiguous_count += 1;
        }
        if reasons.contains(&StagedEvidenceFailureReason::MissingPriceEvidence) {
            missing_price_evidence_count += 1;
        }
        if reasons.contains(&StagedEvidenceFailureReason::UnsafeEvidence)
            || reasons.contains(&StagedEvidenceFailureReason::NotPaperOnly)
        {
            unsafe_count += 1;
        }
        if matches!(
            decision.decision,
            SelfGrowingEvidencePromotionDecisionStatus::AutoApproved
        ) {
            continue;
        }
        review_items.push(StagedEvidenceReviewAnalysisItem {
            candidate_id: candidate.candidate_id.clone(),
            member_id: candidate.member_id.clone(),
            symbol: candidate.symbol.clone(),
            market_scope: candidate.market_scope,
            evidence_kind: candidate.evidence_kind,
            current_score_status: decision.score.score_status,
            current_promotion_decision: decision.decision,
            suggested_fix: staged_evidence_suggested_fix(&reasons),
            failure_reasons: reasons,
            paper_only: candidate.paper_only,
        });
    }
    StagedEvidenceReviewAnalysis {
        analysis_id: "staged-evidence-review-analysis".to_string(),
        candidate_count: promotion_decisions.len(),
        auto_approved_count: promotion_decisions
            .iter()
            .filter(|decision| {
                matches!(
                    decision.decision,
                    SelfGrowingEvidencePromotionDecisionStatus::AutoApproved
                )
            })
            .count(),
        needs_review_count: promotion_decisions
            .iter()
            .filter(|decision| {
                matches!(
                    decision.decision,
                    SelfGrowingEvidencePromotionDecisionStatus::NeedsReview
                        | SelfGrowingEvidencePromotionDecisionStatus::KeptStaged
                )
            })
            .count(),
        rejected_count: promotion_decisions
            .iter()
            .filter(|decision| {
                matches!(
                    decision.decision,
                    SelfGrowingEvidencePromotionDecisionStatus::Rejected
                )
            })
            .count(),
        missing_replay_link_count,
        news_only_count,
        low_trust_count,
        ambiguous_count,
        missing_price_evidence_count,
        unsafe_count,
        review_items,
        paper_only: true,
    }
}

fn replay_examples_for_experience_id<'a>(
    dataset: &'a ReplayDataset,
    experience_id: &str,
) -> Vec<&'a ReplayExample> {
    dataset
        .examples
        .iter()
        .filter(|example| replay_example_experience_id(example).as_deref() == Some(experience_id))
        .collect()
}

fn replay_examples_for_decision_id<'a>(
    dataset: &'a ReplayDataset,
    experience_store: &MemberExperienceStore,
    decision_id: &str,
) -> Vec<&'a ReplayExample> {
    dataset
        .examples
        .iter()
        .filter(|example| {
            replay_example_decision_id(example, experience_store).as_deref() == Some(decision_id)
        })
        .collect()
}

fn replay_examples_for_symbol_scope<'a>(
    dataset: &'a ReplayDataset,
    symbol: &str,
    market_scope: MarketScope,
) -> Vec<&'a ReplayExample> {
    dataset
        .examples
        .iter()
        .filter(|example| example.symbol == symbol && example.market_scope == market_scope)
        .collect()
}

fn filter_link_matches_for_candidate<'a>(
    candidate: &SelfGrowingEvidenceCandidate,
    matches: Vec<&'a ReplayExample>,
) -> Vec<&'a ReplayExample> {
    matches
        .into_iter()
        .filter(|example| {
            candidate
                .symbol
                .as_deref()
                .map(|symbol| example.symbol == symbol)
                .unwrap_or(true)
                && candidate
                    .market_scope
                    .map(|market_scope| example.market_scope == market_scope)
                    .unwrap_or(true)
                && example.member_id == candidate.member_id
        })
        .collect()
}

fn staged_link_candidate_from_example(
    candidate: &SelfGrowingEvidenceCandidate,
    example: &ReplayExample,
    experience_store: &MemberExperienceStore,
    match_type: StagedEvidenceLinkMatchType,
    match_confidence: StagedEvidenceLinkMatchConfidence,
    link_safe: bool,
    unsafe_reason: Option<String>,
) -> StagedEvidenceLinkCandidate {
    StagedEvidenceLinkCandidate {
        candidate_id: candidate.candidate_id.clone(),
        suggested_replay_id: Some(example.replay_id.clone()),
        suggested_experience_id: replay_example_experience_id(example)
            .or_else(|| candidate.related_experience_id.clone()),
        suggested_decision_id: replay_example_decision_id(example, experience_store)
            .or_else(|| candidate.related_decision_id.clone()),
        match_type,
        match_confidence,
        link_safe,
        unsafe_reason,
        paper_only: true,
    }
}

pub fn resolve_staged_evidence_links(
    candidates: &[SelfGrowingEvidenceCandidate],
    dataset: &ReplayDataset,
    experience_store: &MemberExperienceStore,
    policy: &StagedEvidenceLinkResolutionPolicy,
) -> StagedEvidenceLinkResolutionResult {
    if !policy.paper_only {
        return StagedEvidenceLinkResolutionResult {
            resolved_count: 0,
            unresolved_count: candidates.len(),
            unsafe_count: candidates.len(),
            link_candidates: candidates
                .iter()
                .map(|candidate| StagedEvidenceLinkCandidate {
                    candidate_id: candidate.candidate_id.clone(),
                    suggested_replay_id: None,
                    suggested_experience_id: candidate.related_experience_id.clone(),
                    suggested_decision_id: candidate.related_decision_id.clone(),
                    match_type: StagedEvidenceLinkMatchType::NoMatch,
                    match_confidence: StagedEvidenceLinkMatchConfidence::None,
                    link_safe: false,
                    unsafe_reason: Some(
                        "staged evidence link resolution policy must remain paper-only".to_string(),
                    ),
                    paper_only: true,
                })
                .collect(),
            paper_only: true,
        };
    }
    let link_candidates: Vec<StagedEvidenceLinkCandidate> = candidates
        .iter()
        .map(|candidate| {
            if !candidate.paper_only || self_growing_candidate_contains_unsafe_content(candidate) {
                return StagedEvidenceLinkCandidate {
                    candidate_id: candidate.candidate_id.clone(),
                    suggested_replay_id: None,
                    suggested_experience_id: candidate.related_experience_id.clone(),
                    suggested_decision_id: candidate.related_decision_id.clone(),
                    match_type: StagedEvidenceLinkMatchType::NoMatch,
                    match_confidence: StagedEvidenceLinkMatchConfidence::None,
                    link_safe: false,
                    unsafe_reason: Some("candidate is not safe for link resolution".to_string()),
                    paper_only: true,
                };
            }
            if policy.reject_unknown_horizon && candidate.market_scope.is_none() {
                return StagedEvidenceLinkCandidate {
                    candidate_id: candidate.candidate_id.clone(),
                    suggested_replay_id: None,
                    suggested_experience_id: candidate.related_experience_id.clone(),
                    suggested_decision_id: candidate.related_decision_id.clone(),
                    match_type: StagedEvidenceLinkMatchType::NoMatch,
                    match_confidence: StagedEvidenceLinkMatchConfidence::None,
                    link_safe: false,
                    unsafe_reason: Some("candidate market_scope is required for exact replay linking".to_string()),
                    paper_only: true,
                };
            }
            if policy.allow_replay_id_link {
                if let Some(replay_id) = candidate.related_replay_id.as_deref() {
                    let exact_matches = filter_link_matches_for_candidate(
                        candidate,
                        dataset
                            .examples
                            .iter()
                            .filter(|example| example.replay_id == replay_id)
                            .collect(),
                    );
                    match unique_match(exact_matches) {
                        Ok(Some(example)) => {
                            return staged_link_candidate_from_example(
                                candidate,
                                example,
                                experience_store,
                                StagedEvidenceLinkMatchType::ReplayId,
                                StagedEvidenceLinkMatchConfidence::High,
                                true,
                                None,
                            );
                        }
                        Err(_) | Ok(None) => {
                            return StagedEvidenceLinkCandidate {
                                candidate_id: candidate.candidate_id.clone(),
                                suggested_replay_id: candidate.related_replay_id.clone(),
                                suggested_experience_id: candidate.related_experience_id.clone(),
                                suggested_decision_id: candidate.related_decision_id.clone(),
                                match_type: StagedEvidenceLinkMatchType::ReplayId,
                                match_confidence: StagedEvidenceLinkMatchConfidence::Low,
                                link_safe: false,
                                unsafe_reason: Some(
                                    "candidate replay_id did not resolve to a unique replay example".to_string(),
                                ),
                                paper_only: true,
                            };
                        }
                    }
                }
            }
            if policy.allow_experience_id_link {
                if let Some(experience_id) = candidate.related_experience_id.as_deref() {
                    let matches = filter_link_matches_for_candidate(
                        candidate,
                        replay_examples_for_experience_id(dataset, experience_id),
                    );
                    match unique_match(matches) {
                        Ok(Some(example)) => {
                            return staged_link_candidate_from_example(
                                candidate,
                                example,
                                experience_store,
                                StagedEvidenceLinkMatchType::ExperienceId,
                                StagedEvidenceLinkMatchConfidence::High,
                                true,
                                None,
                            );
                        }
                        Err(_) => {
                            return StagedEvidenceLinkCandidate {
                                candidate_id: candidate.candidate_id.clone(),
                                suggested_replay_id: None,
                                suggested_experience_id: candidate.related_experience_id.clone(),
                                suggested_decision_id: candidate.related_decision_id.clone(),
                                match_type: StagedEvidenceLinkMatchType::ExperienceId,
                                match_confidence: StagedEvidenceLinkMatchConfidence::Low,
                                link_safe: false,
                                unsafe_reason: Some(
                                    "experience_id resolves to multiple replay examples".to_string(),
                                ),
                                paper_only: true,
                            };
                        }
                        Ok(None) => {}
                    }
                }
            }
            if policy.allow_decision_id_link {
                if let Some(decision_id) = candidate.related_decision_id.as_deref() {
                    let matches = filter_link_matches_for_candidate(
                        candidate,
                        replay_examples_for_decision_id(dataset, experience_store, decision_id),
                    );
                    match unique_match(matches) {
                        Ok(Some(example)) => {
                            return staged_link_candidate_from_example(
                                candidate,
                                example,
                                experience_store,
                                StagedEvidenceLinkMatchType::DecisionId,
                                StagedEvidenceLinkMatchConfidence::High,
                                true,
                                None,
                            );
                        }
                        Err(_) => {
                            return StagedEvidenceLinkCandidate {
                                candidate_id: candidate.candidate_id.clone(),
                                suggested_replay_id: None,
                                suggested_experience_id: candidate.related_experience_id.clone(),
                                suggested_decision_id: candidate.related_decision_id.clone(),
                                match_type: StagedEvidenceLinkMatchType::DecisionId,
                                match_confidence: StagedEvidenceLinkMatchConfidence::Low,
                                link_safe: false,
                                unsafe_reason: Some(
                                    "decision_id resolves to multiple replay examples".to_string(),
                                ),
                                paper_only: true,
                            };
                        }
                        Ok(None) => {}
                    }
                }
            }
            if policy.allow_symbol_scope_unique_match {
                if let (Some(symbol), Some(market_scope)) =
                    (candidate.symbol.as_deref(), candidate.market_scope)
                {
                    let matches =
                        replay_examples_for_symbol_scope(dataset, symbol, market_scope)
                            .into_iter()
                            .filter(|example| example.member_id == candidate.member_id)
                            .collect::<Vec<_>>();
                    match unique_match(matches) {
                        Ok(Some(example)) => {
                            let symbol_scope_only = candidate.related_replay_id.is_none()
                                && candidate.related_experience_id.is_none()
                                && candidate.related_decision_id.is_none();
                            let link_safe = !(symbol_scope_only && policy.reject_symbol_scope_only);
                            let match_type = if symbol_scope_only {
                                StagedEvidenceLinkMatchType::SymbolScopeOnly
                            } else {
                                StagedEvidenceLinkMatchType::UniqueSymbolScopeHorizon
                            };
                            return staged_link_candidate_from_example(
                                candidate,
                                example,
                                experience_store,
                                match_type,
                                if link_safe {
                                    StagedEvidenceLinkMatchConfidence::Medium
                                } else {
                                    StagedEvidenceLinkMatchConfidence::Low
                                },
                                link_safe,
                                (!link_safe).then(|| {
                                    "symbol/scope-only replay linking stays review-only".to_string()
                                }),
                            );
                        }
                        Err(_) => {
                            return StagedEvidenceLinkCandidate {
                                candidate_id: candidate.candidate_id.clone(),
                                suggested_replay_id: None,
                                suggested_experience_id: candidate.related_experience_id.clone(),
                                suggested_decision_id: candidate.related_decision_id.clone(),
                                match_type: StagedEvidenceLinkMatchType::UniqueSymbolScopeHorizon,
                                match_confidence: StagedEvidenceLinkMatchConfidence::Low,
                                link_safe: false,
                                unsafe_reason: Some(
                                    "symbol/scope resolves to multiple replay examples".to_string(),
                                ),
                                paper_only: true,
                            };
                        }
                        Ok(None) => {}
                    }
                }
            }
            StagedEvidenceLinkCandidate {
                candidate_id: candidate.candidate_id.clone(),
                suggested_replay_id: None,
                suggested_experience_id: candidate.related_experience_id.clone(),
                suggested_decision_id: candidate.related_decision_id.clone(),
                match_type: StagedEvidenceLinkMatchType::NoMatch,
                match_confidence: StagedEvidenceLinkMatchConfidence::None,
                link_safe: false,
                unsafe_reason: Some("no safe exact replay link candidate found".to_string()),
                paper_only: true,
            }
        })
        .collect();
    StagedEvidenceLinkResolutionResult {
        resolved_count: link_candidates
            .iter()
            .filter(|candidate| candidate.link_safe && candidate.suggested_replay_id.is_some())
            .count(),
        unresolved_count: link_candidates
            .iter()
            .filter(|candidate| candidate.suggested_replay_id.is_none())
            .count(),
        unsafe_count: link_candidates
            .iter()
            .filter(|candidate| !candidate.link_safe)
            .count(),
        link_candidates,
        paper_only: true,
    }
}

fn self_growing_candidate_label_from_price_change(
    change: f64,
    policy: &StagedEvidencePriceEnrichmentPolicy,
) -> MemberExperienceOutcome {
    if change >= policy.positive_threshold_pct {
        MemberExperienceOutcome::PaperPositive
    } else if change <= policy.negative_threshold_pct {
        MemberExperienceOutcome::PaperNegative
    } else if change.abs() <= policy.neutral_band_pct {
        MemberExperienceOutcome::PaperNeutral
    } else {
        MemberExperienceOutcome::Unknown
    }
}

fn apply_link_resolutions_to_candidates(
    candidates: &[SelfGrowingEvidenceCandidate],
    link_resolution_result: &StagedEvidenceLinkResolutionResult,
) -> Vec<SelfGrowingEvidenceCandidate> {
    let link_by_candidate: std::collections::BTreeMap<&str, &StagedEvidenceLinkCandidate> =
        link_resolution_result
            .link_candidates
            .iter()
            .map(|candidate| (candidate.candidate_id.as_str(), candidate))
            .collect();
    candidates
        .iter()
        .map(|candidate| {
            let mut updated = candidate.clone();
            if let Some(link) = link_by_candidate.get(candidate.candidate_id.as_str()) {
                if link.link_safe {
                    if updated.related_replay_id.is_none() {
                        updated.related_replay_id = link.suggested_replay_id.clone();
                    }
                    if updated.related_experience_id.is_none() {
                        updated.related_experience_id = link.suggested_experience_id.clone();
                    }
                    if updated.related_decision_id.is_none() {
                        updated.related_decision_id = link.suggested_decision_id.clone();
                    }
                    if let Some(replay_id) = link.suggested_replay_id.as_deref() {
                        push_unique_note(
                            &mut updated.evidence_notes,
                            format!("resolved_replay_id={replay_id}"),
                        );
                    }
                }
            }
            updated
        })
        .collect()
}

pub fn enrich_staged_evidence_with_local_price_series(
    candidates: &[SelfGrowingEvidenceCandidate],
    price_series_store: &PaperPriceSeriesStore,
    policy: &StagedEvidencePriceEnrichmentPolicy,
) -> StagedEvidencePriceEnrichmentResult {
    if !policy.paper_only || !policy.allow_local_price_series {
        return StagedEvidencePriceEnrichmentResult {
            enriched_count: 0,
            needs_more_price_data_count: candidates.len(),
            rejected_count: 0,
            enrichments: candidates
                .iter()
                .map(|candidate| StagedEvidencePriceEnrichment {
                    candidate_id: candidate.candidate_id.clone(),
                    replay_id: candidate.related_replay_id.clone(),
                    symbol: candidate
                        .symbol
                        .clone()
                        .unwrap_or_else(|| "UNKNOWN".to_string()),
                    market_scope: candidate.market_scope.unwrap_or(MarketScope::UsShortTerm),
                    reference_price: None,
                    horizon_price: None,
                    price_change_pct: None,
                    candidate_label: candidate
                        .candidate_label
                        .unwrap_or(MemberExperienceOutcome::Unknown),
                    enrichment_status: StagedEvidencePriceEnrichmentStatus::NotApplicable,
                    evidence_notes: vec![
                        "local price enrichment policy is disabled or not paper-only".to_string(),
                    ],
                    paper_only: true,
                })
                .collect(),
            paper_only: true,
        };
    }
    let enrichments: Vec<StagedEvidencePriceEnrichment> = candidates
        .iter()
        .map(|candidate| {
            let Some(symbol) = candidate.symbol.as_deref() else {
                return StagedEvidencePriceEnrichment {
                    candidate_id: candidate.candidate_id.clone(),
                    replay_id: candidate.related_replay_id.clone(),
                    symbol: "UNKNOWN".to_string(),
                    market_scope: candidate.market_scope.unwrap_or(MarketScope::UsShortTerm),
                    reference_price: None,
                    horizon_price: None,
                    price_change_pct: None,
                    candidate_label: MemberExperienceOutcome::Unknown,
                    enrichment_status: StagedEvidencePriceEnrichmentStatus::NotApplicable,
                    evidence_notes: vec![
                        "candidate symbol missing for local price enrichment".to_string(),
                    ],
                    paper_only: true,
                };
            };
            let Some(market_scope) = candidate.market_scope else {
                return StagedEvidencePriceEnrichment {
                    candidate_id: candidate.candidate_id.clone(),
                    replay_id: candidate.related_replay_id.clone(),
                    symbol: symbol.to_string(),
                    market_scope: MarketScope::UsShortTerm,
                    reference_price: None,
                    horizon_price: None,
                    price_change_pct: None,
                    candidate_label: MemberExperienceOutcome::Unknown,
                    enrichment_status: StagedEvidencePriceEnrichmentStatus::NotApplicable,
                    evidence_notes: vec![
                        "candidate market_scope missing for local price enrichment".to_string(),
                    ],
                    paper_only: true,
                };
            };
            let horizon = replay_evidence_horizon_for_scope(market_scope);
            let Some(series) = price_series_store.series_for_symbol_scope(symbol, market_scope)
            else {
                return StagedEvidencePriceEnrichment {
                    candidate_id: candidate.candidate_id.clone(),
                    replay_id: candidate.related_replay_id.clone(),
                    symbol: symbol.to_string(),
                    market_scope,
                    reference_price: None,
                    horizon_price: None,
                    price_change_pct: None,
                    candidate_label: MemberExperienceOutcome::Unknown,
                    enrichment_status: StagedEvidencePriceEnrichmentStatus::SymbolScopeMismatch,
                    evidence_notes: vec![
                        "no exact local price series for symbol/scope".to_string(),
                    ],
                    paper_only: true,
                };
            };
            let horizon_bars = price_horizon_bars(horizon).unwrap_or(0);
            if policy.require_min_bars && series.bars.len() <= horizon_bars as usize {
                return StagedEvidencePriceEnrichment {
                    candidate_id: candidate.candidate_id.clone(),
                    replay_id: candidate.related_replay_id.clone(),
                    symbol: symbol.to_string(),
                    market_scope,
                    reference_price: None,
                    horizon_price: None,
                    price_change_pct: None,
                    candidate_label: MemberExperienceOutcome::Unknown,
                    enrichment_status: StagedEvidencePriceEnrichmentStatus::NeedsMorePriceData,
                    evidence_notes: vec!["local price series has insufficient bars".to_string()],
                    paper_only: true,
                };
            }
            match find_reference_and_horizon_price(
                price_series_store,
                symbol,
                market_scope,
                horizon,
                None,
            ) {
                Some((reference_price, horizon_price, resolved_bars))
                    if (!policy.require_finite_prices
                        || (reference_price.is_finite() && horizon_price.is_finite()))
                        && reference_price.abs() > f64::EPSILON =>
                {
                    let change = (horizon_price - reference_price) / reference_price;
                    let candidate_label =
                        self_growing_candidate_label_from_price_change(change, policy);
                    let status = if matches!(candidate_label, MemberExperienceOutcome::Unknown) {
                        StagedEvidencePriceEnrichmentStatus::NeedsMorePriceData
                    } else {
                        StagedEvidencePriceEnrichmentStatus::Enriched
                    };
                    StagedEvidencePriceEnrichment {
                        candidate_id: candidate.candidate_id.clone(),
                        replay_id: candidate.related_replay_id.clone(),
                        symbol: symbol.to_string(),
                        market_scope,
                        reference_price: Some(reference_price),
                        horizon_price: Some(horizon_price),
                        price_change_pct: Some(change),
                        candidate_label,
                        enrichment_status: status,
                        evidence_notes: vec![
                            format!("local price series enrichment over {resolved_bars} bars"),
                            format!("price_change_pct={change:.6}"),
                        ],
                        paper_only: true,
                    }
                }
                Some(_) => StagedEvidencePriceEnrichment {
                    candidate_id: candidate.candidate_id.clone(),
                    replay_id: candidate.related_replay_id.clone(),
                    symbol: symbol.to_string(),
                    market_scope,
                    reference_price: None,
                    horizon_price: None,
                    price_change_pct: None,
                    candidate_label: MemberExperienceOutcome::Unknown,
                    enrichment_status: StagedEvidencePriceEnrichmentStatus::InvalidPriceSeries,
                    evidence_notes: vec![
                        "local price series contains invalid price values".to_string(),
                    ],
                    paper_only: true,
                },
                None => StagedEvidencePriceEnrichment {
                    candidate_id: candidate.candidate_id.clone(),
                    replay_id: candidate.related_replay_id.clone(),
                    symbol: symbol.to_string(),
                    market_scope,
                    reference_price: None,
                    horizon_price: None,
                    price_change_pct: None,
                    candidate_label: MemberExperienceOutcome::Unknown,
                    enrichment_status: StagedEvidencePriceEnrichmentStatus::NeedsMorePriceData,
                    evidence_notes: vec![
                        "unable to compute deterministic local price move".to_string(),
                    ],
                    paper_only: true,
                },
            }
        })
        .collect();
    StagedEvidencePriceEnrichmentResult {
        enriched_count: enrichments
            .iter()
            .filter(|item| {
                matches!(
                    item.enrichment_status,
                    StagedEvidencePriceEnrichmentStatus::Enriched
                )
            })
            .count(),
        needs_more_price_data_count: enrichments
            .iter()
            .filter(|item| {
                matches!(
                    item.enrichment_status,
                    StagedEvidencePriceEnrichmentStatus::NeedsMorePriceData
                        | StagedEvidencePriceEnrichmentStatus::NotApplicable
                )
            })
            .count(),
        rejected_count: enrichments
            .iter()
            .filter(|item| {
                matches!(
                    item.enrichment_status,
                    StagedEvidencePriceEnrichmentStatus::SymbolScopeMismatch
                        | StagedEvidencePriceEnrichmentStatus::InvalidPriceSeries
                )
            })
            .count(),
        enrichments,
        paper_only: true,
    }
}

pub fn build_self_growing_candidate_enrichment_patch(
    store: &SelfGrowingEvidenceStagingStore,
    link_resolution_result: StagedEvidenceLinkResolutionResult,
    price_enrichment_result: StagedEvidencePriceEnrichmentResult,
) -> SelfGrowingCandidateEnrichmentPatch {
    let original_by_candidate: std::collections::BTreeMap<&str, &SelfGrowingEvidenceCandidate> =
        store
            .candidates
            .iter()
            .map(|candidate| (candidate.candidate_id.as_str(), candidate))
            .collect();
    let link_applied_candidates =
        apply_link_resolutions_to_candidates(&store.candidates, &link_resolution_result);
    let enrichment_by_candidate: std::collections::BTreeMap<&str, &StagedEvidencePriceEnrichment> =
        price_enrichment_result
            .enrichments
            .iter()
            .map(|enrichment| (enrichment.candidate_id.as_str(), enrichment))
            .collect();
    let mut patched_candidates = Vec::new();
    let mut skipped_candidates = Vec::new();
    for candidate in link_applied_candidates {
        let mut updated = candidate.clone();
        let mut patched = original_by_candidate
            .get(candidate.candidate_id.as_str())
            .map(|original| {
                updated.related_replay_id != original.related_replay_id
                    || updated.related_decision_id != original.related_decision_id
                    || updated.related_experience_id != original.related_experience_id
            })
            .unwrap_or(false);
        if let Some(enrichment) = enrichment_by_candidate.get(candidate.candidate_id.as_str()) {
            if matches!(
                enrichment.enrichment_status,
                StagedEvidencePriceEnrichmentStatus::Enriched
            ) {
                updated.reference_price = enrichment.reference_price;
                updated.horizon_price = enrichment.horizon_price;
                updated.price_change_pct = enrichment.price_change_pct;
                updated.candidate_label = Some(enrichment.candidate_label);
                updated.label_source = SelfGrowingEvidenceLabelSource::SelfGrowingPriceEvidence;
                for note in &enrichment.evidence_notes {
                    push_unique_note(&mut updated.evidence_notes, note.clone());
                }
                patched = true;
            }
        }
        if patched {
            patched_candidates.push(updated);
        } else {
            skipped_candidates.push(candidate.candidate_id.clone());
            patched_candidates.push(candidate);
        }
    }
    SelfGrowingCandidateEnrichmentPatch {
        patch_id: format!("{}-enrichment-patch", store.store_id),
        link_resolutions: link_resolution_result,
        price_enrichments: price_enrichment_result,
        patched_candidates,
        skipped_candidates,
        paper_only: true,
    }
}

pub fn apply_self_growing_candidate_enrichment_patch(
    store: &SelfGrowingEvidenceStagingStore,
    patch: &SelfGrowingCandidateEnrichmentPatch,
) -> SelfGrowingEvidenceStagingStore {
    let patched_by_candidate: std::collections::BTreeMap<&str, &SelfGrowingEvidenceCandidate> =
        patch
            .patched_candidates
            .iter()
            .map(|candidate| (candidate.candidate_id.as_str(), candidate))
            .collect();
    normalize_self_growing_evidence_staging_store(SelfGrowingEvidenceStagingStore {
        store_id: store.store_id.clone(),
        candidates: store
            .candidates
            .iter()
            .map(|candidate| {
                patched_by_candidate
                    .get(candidate.candidate_id.as_str())
                    .copied()
                    .cloned()
                    .unwrap_or_else(|| candidate.clone())
            })
            .collect(),
        candidate_count: 0,
        pending_count: 0,
        approved_count: 0,
        rejected_count: 0,
        review_required_count: 0,
        paper_only: true,
    })
}

pub fn compute_promotion_safety_delta(
    candidates_after_patch: &[SelfGrowingEvidenceCandidate],
    before: &[SelfGrowingEvidencePromotionDecision],
    after: &[SelfGrowingEvidencePromotionDecision],
) -> PromotionSafetyDelta {
    let before_by_candidate: std::collections::BTreeMap<
        &str,
        &SelfGrowingEvidencePromotionDecision,
    > = before
        .iter()
        .map(|decision| (decision.candidate_id.as_str(), decision))
        .collect();
    let candidate_by_id: std::collections::BTreeMap<&str, &SelfGrowingEvidenceCandidate> =
        candidates_after_patch
            .iter()
            .map(|candidate| (candidate.candidate_id.as_str(), candidate))
            .collect();
    let mut policy_violations = Vec::new();
    let mut unsafe_approval_count = 0;
    for decision in after {
        if !matches!(
            decision.decision,
            SelfGrowingEvidencePromotionDecisionStatus::AutoApproved
        ) {
            continue;
        }
        let Some(candidate) = candidate_by_id.get(decision.candidate_id.as_str()).copied() else {
            continue;
        };
        let Some(previous) = before_by_candidate
            .get(decision.candidate_id.as_str())
            .copied()
        else {
            continue;
        };
        if matches!(
            previous.decision,
            SelfGrowingEvidencePromotionDecisionStatus::AutoApproved
        ) {
            continue;
        }
        if !self_growing_candidate_is_safe_exact_price_evidence(candidate, &decision.score) {
            unsafe_approval_count += 1;
            policy_violations.push(format!(
                "candidate {} became auto-approved without safe exact price evidence",
                candidate.candidate_id
            ));
        }
    }
    let auto_approved_before = before
        .iter()
        .filter(|decision| {
            matches!(
                decision.decision,
                SelfGrowingEvidencePromotionDecisionStatus::AutoApproved
            )
        })
        .count();
    let auto_approved_after = after
        .iter()
        .filter(|decision| {
            matches!(
                decision.decision,
                SelfGrowingEvidencePromotionDecisionStatus::AutoApproved
            )
        })
        .count();
    let needs_review_before = before
        .iter()
        .filter(|decision| {
            matches!(
                decision.decision,
                SelfGrowingEvidencePromotionDecisionStatus::NeedsReview
                    | SelfGrowingEvidencePromotionDecisionStatus::KeptStaged
            )
        })
        .count();
    let needs_review_after = after
        .iter()
        .filter(|decision| {
            matches!(
                decision.decision,
                SelfGrowingEvidencePromotionDecisionStatus::NeedsReview
                    | SelfGrowingEvidencePromotionDecisionStatus::KeptStaged
            )
        })
        .count();
    let rejected_before = before
        .iter()
        .filter(|decision| {
            matches!(
                decision.decision,
                SelfGrowingEvidencePromotionDecisionStatus::Rejected
            )
        })
        .count();
    let rejected_after = after
        .iter()
        .filter(|decision| {
            matches!(
                decision.decision,
                SelfGrowingEvidencePromotionDecisionStatus::Rejected
            )
        })
        .count();
    let delta_status = if unsafe_approval_count > 0 {
        PromotionSafetyDeltaStatus::UnsafeRegression
    } else if auto_approved_after > auto_approved_before
        && needs_review_after <= needs_review_before
    {
        PromotionSafetyDeltaStatus::ImprovedSafely
    } else if auto_approved_after == auto_approved_before
        && needs_review_after == needs_review_before
        && rejected_after == rejected_before
    {
        PromotionSafetyDeltaStatus::NoChange
    } else {
        PromotionSafetyDeltaStatus::NeedsReview
    };
    PromotionSafetyDelta {
        auto_approved_before,
        auto_approved_after,
        needs_review_before,
        needs_review_after,
        rejected_before,
        rejected_after,
        unsafe_approval_count,
        policy_violations,
        delta_status,
        paper_only: true,
    }
}

fn run_enriched_evidence_promotion_with_inputs(
    config: &EnrichedEvidencePromotionRunConfig,
    staging_store: SelfGrowingEvidenceStagingStore,
    source_scores: &[SourceTrustScore],
    price_series_store: &PaperPriceSeriesStore,
    validated_dataset: &ReplayDataset,
    experience_store: &MemberExperienceStore,
) -> Result<EnrichedEvidencePromotionRunResult, String> {
    if !config.paper_only {
        return Err("enriched evidence promotion config must be paper-only".to_string());
    }
    let baseline_promotion = run_self_growing_evidence_promotion_with_inputs(
        &SelfGrowingEvidencePromotionRunConfig {
            run_id: format!("{}-baseline", config.run_id),
            staging_store_input_path: None,
            staging_store_output_path: None,
            research_evidence_bundle_path: None,
            source_trust_input_path: None,
            validated_dataset_input_path: None,
            sanitized_dataset_input_path: None,
            experience_store_input_path: None,
            approved_paper_evidence_output_path: None,
            validated_replay_output_path: None,
            training_candidate_dataset_output_path: None,
            dry_run: true,
            apply_promotions: false,
            refresh_training_candidates: false,
            paper_only: true,
        },
        staging_store.clone(),
        source_scores,
        Some(validated_dataset),
        Some(experience_store),
    )?;
    let review_analysis = analyze_staged_evidence_review_queue(
        &staging_store.candidates,
        &baseline_promotion.promotion_decisions,
    );
    let link_resolution_result = resolve_staged_evidence_links(
        &staging_store.candidates,
        validated_dataset,
        experience_store,
        &StagedEvidenceLinkResolutionPolicy::default(),
    );
    let candidates_with_links =
        apply_link_resolutions_to_candidates(&staging_store.candidates, &link_resolution_result);
    let price_enrichment_result = enrich_staged_evidence_with_local_price_series(
        &candidates_with_links,
        price_series_store,
        &StagedEvidencePriceEnrichmentPolicy::default(),
    );
    let patch = build_self_growing_candidate_enrichment_patch(
        &staging_store,
        link_resolution_result.clone(),
        price_enrichment_result.clone(),
    );
    let mut enrichment_patch_result = SelfGrowingCandidateEnrichmentPatchResult {
        patch: patch.clone(),
        patched_count: patch
            .patched_candidates
            .iter()
            .filter(|candidate| !patch.skipped_candidates.contains(&candidate.candidate_id))
            .count(),
        skipped_count: patch.skipped_candidates.len(),
        unsafe_skip_count: patch
            .link_resolutions
            .link_candidates
            .iter()
            .filter(|candidate| !candidate.link_safe)
            .count(),
        output_path: None,
        paper_only: true,
    };
    let enriched_store = apply_self_growing_candidate_enrichment_patch(&staging_store, &patch);
    let preview_enriched_promotion = run_self_growing_evidence_promotion_with_inputs(
        &SelfGrowingEvidencePromotionRunConfig {
            run_id: format!("{}-preview", config.run_id),
            staging_store_input_path: None,
            staging_store_output_path: None,
            research_evidence_bundle_path: None,
            source_trust_input_path: None,
            validated_dataset_input_path: None,
            sanitized_dataset_input_path: None,
            experience_store_input_path: None,
            approved_paper_evidence_output_path: None,
            validated_replay_output_path: None,
            training_candidate_dataset_output_path: None,
            dry_run: true,
            apply_promotions: false,
            refresh_training_candidates: false,
            paper_only: true,
        },
        enriched_store.clone(),
        source_scores,
        Some(validated_dataset),
        Some(experience_store),
    )?;
    let safety_delta = compute_promotion_safety_delta(
        &enriched_store.candidates,
        &baseline_promotion.promotion_decisions,
        &preview_enriched_promotion.promotion_decisions,
    );
    let safe_to_apply = !matches!(
        safety_delta.delta_status,
        PromotionSafetyDeltaStatus::UnsafeRegression
    );
    let final_enriched_promotion = if !config.dry_run && safe_to_apply {
        let promotion = run_self_growing_evidence_promotion_with_inputs(
            &SelfGrowingEvidencePromotionRunConfig {
                run_id: config.run_id.clone(),
                staging_store_input_path: None,
                staging_store_output_path: config
                    .apply_enrichment_patch
                    .then(|| config.enriched_staging_output_path.clone())
                    .flatten(),
                research_evidence_bundle_path: None,
                source_trust_input_path: None,
                validated_dataset_input_path: None,
                sanitized_dataset_input_path: None,
                experience_store_input_path: None,
                approved_paper_evidence_output_path: config
                    .apply_promotions
                    .then(|| config.approved_evidence_output_path.clone())
                    .flatten(),
                validated_replay_output_path: config.validated_replay_output_path.clone(),
                training_candidate_dataset_output_path: config
                    .training_candidate_output_path
                    .clone(),
                dry_run: false,
                apply_promotions: config.apply_promotions,
                refresh_training_candidates: config.refresh_training_candidates,
                paper_only: true,
            },
            enriched_store.clone(),
            source_scores,
            Some(validated_dataset),
            Some(experience_store),
        )?;
        if config.apply_enrichment_patch {
            if let Some(path) = &config.enriched_staging_output_path {
                enriched_store.save_to_local_json(Path::new(path))?;
                enrichment_patch_result.output_path = Some(path.clone());
            }
        }
        promotion
    } else {
        preview_enriched_promotion
    };
    Ok(EnrichedEvidencePromotionRunResult {
        review_analysis,
        link_resolution_result,
        price_enrichment_result,
        enrichment_patch_result,
        rescored_count: final_enriched_promotion.scored_count,
        auto_approved_count_before: baseline_promotion.auto_approved_count,
        auto_approved_count_after: final_enriched_promotion.auto_approved_count,
        needs_review_count_after: final_enriched_promotion.needs_review_count
            + final_enriched_promotion.kept_staged_count,
        rejected_count_after: final_enriched_promotion.rejected_count,
        generated_paper_evidence_records: final_enriched_promotion.generated_paper_evidence_records,
        validated_replay_build_result: final_enriched_promotion.validated_replay_build_result,
        training_candidate_refresh_result: final_enriched_promotion
            .training_candidate_dataset
            .as_ref()
            .map(|candidate_dataset| TrainingCandidateRefreshResult {
                previous_candidate_count: baseline_promotion
                    .training_candidate_dataset
                    .as_ref()
                    .map(|dataset| dataset.example_count)
                    .unwrap_or(0),
                new_candidate_count: candidate_dataset.example_count,
                added_candidate_count: candidate_dataset.example_count.saturating_sub(
                    baseline_promotion
                        .training_candidate_dataset
                        .as_ref()
                        .map(|dataset| dataset.example_count)
                        .unwrap_or(0),
                ),
                excluded_candidate_count: baseline_promotion
                    .training_candidate_dataset
                    .as_ref()
                    .map(|dataset| dataset.example_count)
                    .unwrap_or(0)
                    .saturating_sub(candidate_dataset.example_count),
                refresh_status: if config.refresh_training_candidates {
                    TrainingCandidateRefreshStatus::Refreshed
                } else {
                    TrainingCandidateRefreshStatus::NoChange
                },
                blockers: if safe_to_apply {
                    Vec::new()
                } else {
                    safety_delta.policy_violations.clone()
                },
                paper_only: true,
            }),
        design_gate: final_enriched_promotion.design_gate,
        safety_delta,
        safety_summary: safety_summary(),
        paper_only: true,
    })
}

pub fn run_enriched_evidence_promotion(
    config: EnrichedEvidencePromotionRunConfig,
) -> Result<EnrichedEvidencePromotionRunResult, String> {
    for (path, label) in [
        (
            config.staging_store_input_path.as_ref(),
            "enriched evidence staging store input path",
        ),
        (
            config.price_series_path.as_ref(),
            "enriched evidence local price series path",
        ),
        (
            config.sanitized_dataset_path.as_ref(),
            "enriched evidence sanitized dataset path",
        ),
        (
            config.experience_store_path.as_ref(),
            "enriched evidence experience store path",
        ),
        (
            config.enriched_staging_output_path.as_ref(),
            "enriched evidence staging output path",
        ),
        (
            config.approved_evidence_output_path.as_ref(),
            "enriched evidence approved evidence output path",
        ),
        (
            config.validated_replay_output_path.as_ref(),
            "enriched evidence validated replay output path",
        ),
        (
            config.training_candidate_output_path.as_ref(),
            "enriched evidence training candidate output path",
        ),
    ] {
        if let Some(path) = path {
            validate_local_json_path(Path::new(path), label)?;
        }
    }
    let staging_store_path = config.staging_store_input_path.as_ref().ok_or_else(|| {
        "enriched evidence promotion requires staging_store_input_path".to_string()
    })?;
    let price_series_path = config
        .price_series_path
        .as_ref()
        .ok_or_else(|| "enriched evidence promotion requires price_series_path".to_string())?;
    let sanitized_dataset_path = config
        .sanitized_dataset_path
        .as_ref()
        .ok_or_else(|| "enriched evidence promotion requires sanitized_dataset_path".to_string())?;
    let experience_store_path = config
        .experience_store_path
        .as_ref()
        .ok_or_else(|| "enriched evidence promotion requires experience_store_path".to_string())?;
    let staging_store =
        SelfGrowingEvidenceStagingStore::load_from_local_json(Path::new(staging_store_path))?;
    let price_series_store = load_price_series_store_from_local_json(Path::new(price_series_path))?;
    let validated_dataset = ReplayDataset::load_from_local_json(Path::new(sanitized_dataset_path))?;
    let experience_store =
        MemberExperienceStore::load_from_local_json(Path::new(experience_store_path))?;
    run_enriched_evidence_promotion_with_inputs(
        &config,
        staging_store,
        &[],
        &price_series_store,
        &validated_dataset,
        &experience_store,
    )
}

fn auto_approval_exact_link_type(
    candidate: &SelfGrowingEvidenceCandidate,
) -> AutoApprovalSuccessExactLinkType {
    if candidate.related_replay_id.is_some() {
        AutoApprovalSuccessExactLinkType::ReplayId
    } else if candidate.related_experience_id.is_some() {
        AutoApprovalSuccessExactLinkType::ExperienceId
    } else if candidate.related_decision_id.is_some() {
        AutoApprovalSuccessExactLinkType::DecisionId
    } else {
        AutoApprovalSuccessExactLinkType::None
    }
}

pub fn check_auto_approval_success_path(
    candidate: &SelfGrowingEvidenceCandidate,
    score: &EvidenceCandidateScore,
    price_enrichment: Option<&StagedEvidencePriceEnrichment>,
    policy: &SelfGrowingEvidencePromotionPolicy,
) -> AutoApprovalSuccessPathCheck {
    let price_evidence_present = price_enrichment
        .map(|enrichment| {
            matches!(
                enrichment.enrichment_status,
                StagedEvidencePriceEnrichmentStatus::Enriched
            ) && enrichment.price_change_pct.is_some()
        })
        .unwrap_or_else(|| self_growing_candidate_has_price_evidence(candidate));
    let source_trust_ok = if policy.require_validated_source_trust {
        matches!(
            candidate.source_trust_status,
            SourceTrustStatus::Trusted | SourceTrustStatus::UsableWithWarnings
        ) && score.source_trust_score >= 0.5
    } else {
        !matches!(candidate.source_trust_status, SourceTrustStatus::Rejected)
    };
    let evidence_kind_ok = matches!(
        candidate.evidence_kind,
        SelfGrowingEvidenceKind::PriceMove | SelfGrowingEvidenceKind::PaperOutcomeCandidate
    );
    let label_ok = matches!(
        candidate.candidate_label,
        Some(MemberExperienceOutcome::PaperPositive)
            | Some(MemberExperienceOutcome::PaperNegative)
            | Some(MemberExperienceOutcome::PaperNeutral)
    );
    let replay_link_present = candidate.related_replay_id.is_some();
    let exact_link_type = auto_approval_exact_link_type(candidate);
    let safety_ok = candidate.paper_only
        && !self_growing_candidate_contains_unsafe_content(candidate)
        && !self_growing_candidate_is_news_only(candidate)
        && !self_growing_candidate_is_low_trust(candidate, score)
        && !self_growing_candidate_is_ambiguous(candidate);
    let promotion_allowed = matches!(
        evaluate_self_growing_evidence_promotion(candidate, score, policy).decision,
        SelfGrowingEvidencePromotionDecisionStatus::AutoApproved
    );
    let mut failure_reasons = Vec::new();
    if !replay_link_present {
        failure_reasons.push("missing exact replay link".to_string());
    }
    if !price_evidence_present {
        failure_reasons.push("missing deterministic price evidence".to_string());
    }
    if !source_trust_ok {
        failure_reasons.push("source trust below promotion threshold".to_string());
    }
    if !evidence_kind_ok {
        failure_reasons.push("evidence_kind is not price evidence".to_string());
    }
    if !label_ok {
        failure_reasons.push("candidate label is not promotable".to_string());
    }
    if !safety_ok {
        failure_reasons.push("candidate violates promotion safety".to_string());
    }
    if !promotion_allowed {
        failure_reasons.push("promotion gate still blocks candidate".to_string());
    }
    AutoApprovalSuccessPathCheck {
        check_id: format!("success-path-{}", candidate.candidate_id),
        candidate_id: candidate.candidate_id.clone(),
        replay_link_present,
        exact_link_type,
        price_evidence_present,
        source_trust_ok,
        evidence_kind_ok,
        label_ok,
        safety_ok,
        promotion_allowed,
        failure_reasons,
        paper_only: true,
    }
}

fn build_auto_approval_success_path_checks(
    candidates: &[SelfGrowingEvidenceCandidate],
    source_scores: &[SourceTrustScore],
    price_enrichment_result: &StagedEvidencePriceEnrichmentResult,
) -> Vec<AutoApprovalSuccessPathCheck> {
    let enrichment_by_candidate: std::collections::BTreeMap<&str, &StagedEvidencePriceEnrichment> =
        price_enrichment_result
            .enrichments
            .iter()
            .map(|enrichment| (enrichment.candidate_id.as_str(), enrichment))
            .collect();
    let policy = SelfGrowingEvidencePromotionPolicy::default();
    candidates
        .iter()
        .map(|candidate| {
            let score = score_self_growing_evidence_candidate(candidate, source_scores);
            check_auto_approval_success_path(
                candidate,
                &score,
                enrichment_by_candidate
                    .get(candidate.candidate_id.as_str())
                    .copied(),
                &policy,
            )
        })
        .collect()
}

fn approved_evidence_record_is_safe(record: &PaperOutcomeEvidenceRecord) -> bool {
    if !record.paper_only || record.replay_id.is_none() {
        return false;
    }
    if record.decision_id.is_none() && record.experience_id.is_none() {
        return false;
    }
    if !matches!(
        record.candidate_label,
        MemberExperienceOutcome::PaperPositive
            | MemberExperienceOutcome::PaperNegative
            | MemberExperienceOutcome::PaperNeutral
    ) {
        return false;
    }
    serde_json::to_string(record)
        .map(|text| research_source_unsafe_reasons(&text).is_empty())
        .unwrap_or(false)
}

fn replay_input_features_unchanged(before: &ReplayDataset, after: &ReplayDataset) -> bool {
    let before_by_replay: std::collections::BTreeMap<&str, &ReplayInputFeatures> = before
        .examples
        .iter()
        .map(|example| (example.replay_id.as_str(), &example.input_features))
        .collect();
    after.examples.iter().all(|example| {
        before_by_replay
            .get(example.replay_id.as_str())
            .map(|features| **features == example.input_features)
            .unwrap_or(true)
    })
}

fn apply_approved_evidence_to_training_candidates_with_inputs(
    config: &ApprovedEvidenceApplyConfig,
    approved_evidence: &[PaperOutcomeEvidenceRecord],
    validated_dataset: &ReplayDataset,
) -> Result<
    (
        ApprovedEvidenceApplyResult,
        Option<ValidatedReplayDatasetBuildResult>,
        Option<ReplayTrainingInclusionMask>,
        Option<TrainingCandidateDataset>,
    ),
    String,
> {
    if !config.paper_only {
        return Err("approved evidence apply config must be paper-only".to_string());
    }
    let approved_evidence_count = approved_evidence.len();
    let safe_records: Vec<PaperOutcomeEvidenceRecord> = approved_evidence
        .iter()
        .filter(|record| approved_evidence_record_is_safe(record))
        .cloned()
        .collect();
    let rejected_evidence_count = approved_evidence_count.saturating_sub(safe_records.len());
    let previous_mask = build_replay_training_inclusion_mask(
        validated_dataset,
        &ReplayTrainingInclusionPolicy::default(),
    );
    let previous_candidate_dataset = build_training_candidate_dataset(
        validated_dataset,
        &previous_mask,
        &TrainingCandidateBuildConfig::default(),
    );
    let mut build_result = None;
    let mut inclusion_mask = None;
    let mut training_candidate_dataset = None;
    if (config.refresh_validated_replay || config.refresh_training_candidates)
        && !safe_records.is_empty()
    {
        let (new_build, new_mask, new_candidate_dataset, _) =
            rebuild_training_candidate_dataset_from_approved_evidence(
                validated_dataset,
                &safe_records,
                &TrainingCandidateRefreshPolicy::default(),
            );
        build_result = Some(new_build);
        inclusion_mask = Some(new_mask);
        training_candidate_dataset = Some(new_candidate_dataset);
    }
    let input_features_unchanged = build_result
        .as_ref()
        .map(|build| replay_input_features_unchanged(validated_dataset, &build.dataset))
        .unwrap_or(true);
    if matches!(config.apply_mode, ApprovedEvidenceApplyMode::Apply) && !input_features_unchanged {
        return Ok((
            ApprovedEvidenceApplyResult {
                approved_evidence_count,
                applied_evidence_count: 0,
                skipped_evidence_count: safe_records.len(),
                rejected_evidence_count,
                validated_replay_refreshed: false,
                training_candidates_refreshed: false,
                previous_training_candidate_count: Some(previous_candidate_dataset.example_count),
                new_training_candidate_count: training_candidate_dataset
                    .as_ref()
                    .map(|dataset| dataset.example_count),
                input_features_unchanged: false,
                apply_status: ApprovedEvidenceApplyStatus::Blocked,
                paper_only: true,
            },
            None,
            None,
            None,
        ));
    }
    if matches!(config.apply_mode, ApprovedEvidenceApplyMode::Apply) && safe_records.is_empty() {
        return Ok((
            ApprovedEvidenceApplyResult {
                approved_evidence_count,
                applied_evidence_count: 0,
                skipped_evidence_count: 0,
                rejected_evidence_count,
                validated_replay_refreshed: false,
                training_candidates_refreshed: false,
                previous_training_candidate_count: Some(previous_candidate_dataset.example_count),
                new_training_candidate_count: Some(previous_candidate_dataset.example_count),
                input_features_unchanged,
                apply_status: ApprovedEvidenceApplyStatus::Blocked,
                paper_only: true,
            },
            None,
            None,
            None,
        ));
    }
    if matches!(config.apply_mode, ApprovedEvidenceApplyMode::Apply) {
        if let Some(path) = &config.approved_evidence_output_path {
            write_safe_json(Path::new(path), &safe_records)?;
        }
        if let Some(build) = &build_result {
            if config.refresh_validated_replay {
                if let Some(path) = &config.validated_replay_output_path {
                    build.dataset.save_to_local_json(Path::new(path))?;
                }
            }
        }
        if let Some(candidate_dataset) = &training_candidate_dataset {
            if config.refresh_training_candidates {
                if let Some(path) = &config.training_candidate_output_path {
                    write_safe_json(Path::new(path), candidate_dataset)?;
                }
            }
        }
    }
    let apply_status = match config.apply_mode {
        ApprovedEvidenceApplyMode::DryRun => ApprovedEvidenceApplyStatus::DryRunPreview,
        ApprovedEvidenceApplyMode::Apply if rejected_evidence_count > 0 => {
            ApprovedEvidenceApplyStatus::AppliedWithWarnings
        }
        ApprovedEvidenceApplyMode::Apply => ApprovedEvidenceApplyStatus::Applied,
    };
    let applied_evidence_count = if matches!(config.apply_mode, ApprovedEvidenceApplyMode::Apply) {
        safe_records.len()
    } else {
        0
    };
    let skipped_evidence_count = if matches!(config.apply_mode, ApprovedEvidenceApplyMode::DryRun) {
        safe_records.len()
    } else {
        0
    };
    Ok((
        ApprovedEvidenceApplyResult {
            approved_evidence_count,
            applied_evidence_count,
            skipped_evidence_count,
            rejected_evidence_count,
            validated_replay_refreshed: matches!(
                config.apply_mode,
                ApprovedEvidenceApplyMode::Apply
            ) && config.refresh_validated_replay
                && build_result.is_some(),
            training_candidates_refreshed: matches!(
                config.apply_mode,
                ApprovedEvidenceApplyMode::Apply
            ) && config.refresh_training_candidates
                && training_candidate_dataset.is_some(),
            previous_training_candidate_count: Some(previous_candidate_dataset.example_count),
            new_training_candidate_count: training_candidate_dataset
                .as_ref()
                .map(|dataset| dataset.example_count)
                .or(Some(previous_candidate_dataset.example_count)),
            input_features_unchanged,
            apply_status,
            paper_only: true,
        },
        build_result,
        inclusion_mask,
        training_candidate_dataset,
    ))
}

pub fn apply_approved_evidence_to_training_candidates(
    config: ApprovedEvidenceApplyConfig,
    approved_evidence: &[PaperOutcomeEvidenceRecord],
    validated_dataset: &ReplayDataset,
) -> Result<ApprovedEvidenceApplyResult, String> {
    for (path, label) in [
        (
            config.approved_evidence_input_path.as_ref(),
            "approved evidence input path",
        ),
        (
            config.approved_evidence_output_path.as_ref(),
            "approved evidence output path",
        ),
        (
            config.validated_replay_input_path.as_ref(),
            "approved evidence validated replay input path",
        ),
        (
            config.validated_replay_output_path.as_ref(),
            "approved evidence validated replay output path",
        ),
        (
            config.training_candidate_output_path.as_ref(),
            "approved evidence training candidate output path",
        ),
    ] {
        if let Some(path) = path {
            validate_local_json_path(Path::new(path), label)?;
        }
    }
    apply_approved_evidence_to_training_candidates_with_inputs(
        &config,
        approved_evidence,
        validated_dataset,
    )
    .map(|(result, _, _, _)| result)
}

pub fn compute_promotion_success_metrics(
    auto_approved_before: usize,
    auto_approved_after: usize,
    generated_paper_evidence_count: usize,
    apply_result: Option<&ApprovedEvidenceApplyResult>,
    review_analysis: &StagedEvidenceReviewAnalysis,
    safety_delta_status: PromotionSafetyDeltaStatus,
) -> PromotionSuccessMetrics {
    let previous_training_candidate_count = apply_result
        .and_then(|result| result.previous_training_candidate_count)
        .unwrap_or(0);
    let new_training_candidate_count = apply_result
        .and_then(|result| result.new_training_candidate_count)
        .unwrap_or(previous_training_candidate_count);
    PromotionSuccessMetrics {
        auto_approved_before,
        auto_approved_after,
        auto_approval_delta: auto_approved_after as isize - auto_approved_before as isize,
        generated_paper_evidence_count,
        validated_replay_promoted_count: apply_result
            .map(|result| result.applied_evidence_count)
            .unwrap_or(generated_paper_evidence_count),
        training_candidate_delta: new_training_candidate_count as isize
            - previous_training_candidate_count as isize,
        news_only_blocked_count: review_analysis.news_only_count,
        low_trust_blocked_count: review_analysis.low_trust_count,
        ambiguous_blocked_count: review_analysis.ambiguous_count,
        missing_link_blocked_count: review_analysis.missing_replay_link_count,
        safety_delta_status,
        paper_only: true,
    }
}

fn run_auto_approval_end_to_end_with_inputs(
    config: &AutoApprovalEndToEndRunConfig,
    success_staging_store: SelfGrowingEvidenceStagingStore,
    success_price_series_store: PaperPriceSeriesStore,
    validated_dataset: &ReplayDataset,
    experience_store: &MemberExperienceStore,
) -> Result<AutoApprovalEndToEndRunResult, String> {
    if !config.paper_only {
        return Err("auto-approval end-to-end config must be paper-only".to_string());
    }
    let enriched_promotion_result = run_enriched_evidence_promotion_with_inputs(
        &EnrichedEvidencePromotionRunConfig {
            run_id: format!("{}-enriched-preview", config.run_id),
            staging_store_input_path: None,
            price_series_path: None,
            sanitized_dataset_path: None,
            experience_store_path: None,
            enriched_staging_output_path: None,
            approved_evidence_output_path: None,
            validated_replay_output_path: None,
            training_candidate_output_path: None,
            dry_run: true,
            apply_enrichment_patch: false,
            apply_promotions: false,
            refresh_training_candidates: false,
            paper_only: true,
        },
        success_staging_store.clone(),
        &[],
        &success_price_series_store,
        validated_dataset,
        experience_store,
    )?;
    let success_path_checks = build_auto_approval_success_path_checks(
        &enriched_promotion_result
            .enrichment_patch_result
            .patch
            .patched_candidates,
        &[],
        &enriched_promotion_result.price_enrichment_result,
    );
    let (approved_evidence_apply_result, design_gate) = if config.apply_promotions
        || config.refresh_training_candidates
    {
        let apply_config = ApprovedEvidenceApplyConfig {
            run_id: format!("{}-approved-evidence-apply", config.run_id),
            approved_evidence_input_path: None,
            approved_evidence_output_path: config.approved_evidence_output_path.clone(),
            validated_replay_input_path: None,
            validated_replay_output_path: None,
            training_candidate_output_path: config.training_candidate_output_path.clone(),
            apply_mode: if config.dry_run {
                ApprovedEvidenceApplyMode::DryRun
            } else {
                ApprovedEvidenceApplyMode::Apply
            },
            refresh_validated_replay: true,
            refresh_training_candidates: config.refresh_training_candidates,
            paper_only: true,
        };
        let (apply_result, build_result, _, candidate_dataset) =
            apply_approved_evidence_to_training_candidates_with_inputs(
                &apply_config,
                &enriched_promotion_result.generated_paper_evidence_records,
                validated_dataset,
            )?;
        let design_gate = if config.refresh_training_candidates {
            if let (Some(build_result), Some(candidate_dataset)) =
                (build_result.as_ref(), candidate_dataset.as_ref())
            {
                let split_result = build_training_split(
                    candidate_dataset,
                    &TrainingSplitConfig {
                        train_ratio: 0.7,
                        validation_ratio: 0.15,
                        test_ratio: 0.15,
                        split_seed: format!("{}-success-training-split", config.run_id),
                        stratify_by: TrainingSplitStratifyBy::Member,
                        paper_only: true,
                    },
                );
                let replay_quality_eval = run_replay_quality_evaluation_with_label_ratio_threshold(
                    experience_store,
                    &build_result.dataset,
                    default_min_replay_examples_required(),
                    default_min_examples_per_member_required(),
                    default_min_validated_label_ratio_required(),
                );
                let dry_run_result = run_offline_trainer_data_loader_dry_run(
                    candidate_dataset,
                    &split_result,
                    &build_offline_trainer_dry_run_spec(candidate_dataset, &split_result),
                );
                Some(evaluate_offline_training_design_gate(
                    candidate_dataset,
                    &split_result,
                    &dry_run_result,
                    &replay_quality_eval,
                ))
            } else {
                None
            }
        } else {
            None
        };
        (Some(apply_result), design_gate)
    } else {
        (None, None)
    };
    let promotion_success_metrics = compute_promotion_success_metrics(
        enriched_promotion_result.auto_approved_count_before,
        enriched_promotion_result.auto_approved_count_after,
        enriched_promotion_result
            .generated_paper_evidence_records
            .len(),
        approved_evidence_apply_result.as_ref(),
        &enriched_promotion_result.review_analysis,
        enriched_promotion_result.safety_delta.delta_status,
    );
    Ok(AutoApprovalEndToEndRunResult {
        enriched_promotion_result,
        success_path_checks,
        approved_evidence_apply_result,
        promotion_success_metrics,
        design_gate,
        safety_summary: safety_summary(),
        paper_only: true,
    })
}

pub fn run_auto_approval_end_to_end(
    config: AutoApprovalEndToEndRunConfig,
) -> Result<AutoApprovalEndToEndRunResult, String> {
    if !config.paper_only {
        return Err("auto-approval end-to-end config must be paper-only".to_string());
    }
    for (path, label) in [
        (
            Some(&config.success_staging_path),
            "auto-approval success staging path",
        ),
        (
            Some(&config.success_price_series_path),
            "auto-approval success price series path",
        ),
        (
            config
                .sanitized_dataset_path
                .as_ref()
                .or(config.validated_dataset_path.as_ref()),
            "auto-approval dataset path",
        ),
        (
            config.experience_store_path.as_ref(),
            "auto-approval experience store path",
        ),
        (
            config.approved_evidence_output_path.as_ref(),
            "auto-approval approved evidence output path",
        ),
        (
            config.training_candidate_output_path.as_ref(),
            "auto-approval training candidate output path",
        ),
    ] {
        if let Some(path) = path {
            validate_local_json_path(Path::new(path), label)?;
        }
    }
    let success_staging_store = SelfGrowingEvidenceStagingStore::load_from_local_json(Path::new(
        &config.success_staging_path,
    ))?;
    let success_price_series_store =
        load_price_series_store_from_local_json(Path::new(&config.success_price_series_path))?;
    let validated_dataset_path = config
        .validated_dataset_path
        .as_ref()
        .or(config.sanitized_dataset_path.as_ref())
        .ok_or_else(|| "auto-approval end-to-end requires dataset path".to_string())?;
    let validated_dataset = ReplayDataset::load_from_local_json(Path::new(validated_dataset_path))?;
    let experience_store = if let Some(path) = &config.experience_store_path {
        MemberExperienceStore::load_from_local_json(Path::new(path))?
    } else {
        MemberExperienceStore::new("auto-approval-empty-experience-store", Vec::new())
    };
    run_auto_approval_end_to_end_with_inputs(
        &config,
        success_staging_store,
        success_price_series_store,
        &validated_dataset,
        &experience_store,
    )
}

fn training_feature_text_is_safe(text: &str) -> bool {
    let normalized = text.to_ascii_lowercase();
    ![
        "paperpositive",
        "papernegative",
        "paperneutral",
        "papernotrade",
        "reviewrequired",
        "simulatedfixture",
        "chairman",
        "의장 결정",
        "risk governor",
        "riskveto",
        "broker",
        "account",
        "order",
    ]
    .iter()
    .any(|term| normalized.contains(term))
}

pub fn build_training_feature_row(
    candidate_example: &TrainingCandidateExample,
    schema: &TrainingFeatureSchema,
) -> Result<TrainingFeatureRow, String> {
    if !schema.paper_only || !candidate_example.paper_only {
        return Err("training feature row must remain paper-only".to_string());
    }
    let features = &candidate_example.sanitized_input_features;
    let fields = [
        features.market_data_summary.as_str(),
        features.news_summary.as_str(),
        features.owner_pre_decision_context.as_deref().unwrap_or(""),
        features
            .prior_member_memory_summary
            .as_deref()
            .unwrap_or(""),
        features.prior_style_blend_summary.as_deref().unwrap_or(""),
        features.prior_calibration_summary.as_deref().unwrap_or(""),
    ];
    if fields
        .iter()
        .any(|text| !training_feature_text_is_safe(text))
        || features
            .feature_safety_notes
            .iter()
            .any(|text| !training_feature_text_is_safe(text))
    {
        return Err("training feature row contains leaked target or forbidden term".to_string());
    }
    Ok(TrainingFeatureRow {
        replay_id: candidate_example.replay_id.clone(),
        member_id: candidate_example.member_id.clone(),
        symbol: candidate_example.symbol.clone(),
        market_scope: candidate_example.market_scope,
        market_features: vec![features.market_data_summary.clone()],
        news_features: vec![features.news_summary.clone()],
        owner_context_features: features
            .owner_pre_decision_context
            .clone()
            .map(|value| vec![value]),
        prior_memory_features: features
            .prior_member_memory_summary
            .clone()
            .map(|value| vec![value]),
        style_features: features
            .prior_style_blend_summary
            .clone()
            .map(|value| vec![value]),
        calibration_features: features
            .prior_calibration_summary
            .clone()
            .map(|value| vec![value]),
        feature_safety_notes: features.feature_safety_notes.clone(),
        paper_only: true,
    })
}

pub fn build_training_target_row(
    candidate_example: &TrainingCandidateExample,
    schema: &TrainingTargetSchema,
) -> Option<TrainingTargetRow> {
    if !schema.paper_only
        || !candidate_example.paper_only
        || matches!(
            candidate_example.label_source,
            ReplayLabelSource::ReviewRequired
                | ReplayLabelSource::SimulatedFixture
                | ReplayLabelSource::RejectedLabel
        )
        || !schema
            .min_label_confidence
            .contains(&candidate_example.label_confidence)
    {
        return None;
    }
    Some(TrainingTargetRow {
        replay_id: candidate_example.replay_id.clone(),
        member_id: candidate_example.member_id.clone(),
        stance_target: candidate_example.target_labels.stance_target,
        confidence_target: candidate_example
            .target_labels
            .confidence_calibration_target,
        risk_target: candidate_example.target_labels.risk_label.clone(),
        evidence_target: candidate_example.target_labels.evidence_label.clone(),
        uncertainty_target: Some(match candidate_example.label_confidence {
            ReplayLabelConfidence::High => 0.1,
            ReplayLabelConfidence::Medium => 0.3,
            ReplayLabelConfidence::Low => 0.6,
            ReplayLabelConfidence::ReviewRequired => 1.0,
        }),
        expected_return_target: None,
        outcome_label: candidate_example.target_labels.outcome_label,
        attribution_label: candidate_example.target_labels.attribution_label,
        label_source: candidate_example.label_source,
        label_confidence: candidate_example.label_confidence,
        sample_weight: candidate_example.sample_weight,
        paper_only: true,
    })
}

fn smartcore_v2_feature_dim(schema: &TrainingFeatureSchema) -> usize {
    schema.numeric_feature_count + schema.categorical_feature_count + schema.text_feature_count
}

fn default_smartcore_v2_batch_spec(
    batch_size: usize,
    feature_schema: &TrainingFeatureSchema,
    target_schema: &TrainingTargetSchema,
) -> SmartCoreV2BatchSpec {
    SmartCoreV2BatchSpec {
        spec_id: format!(
            "smartcore-v2-batch-spec-{}-{}",
            feature_schema.schema_version, target_schema.schema_version
        ),
        core_family: SmartCoreV2Family::Mamba3GatedDeltaNetSparseEvent,
        temporal_core: SmartCoreV2ComponentStatus::Mamba3Deferred,
        memory_core: SmartCoreV2ComponentStatus::GatedDeltaNetDeferred,
        event_attention_core: SmartCoreV2ComponentStatus::SparseEventAttentionDeferred,
        sequence_len: feature_schema.sequence_len_hint,
        feature_dim: smartcore_v2_feature_dim(feature_schema),
        target_heads: target_schema.target_heads.clone(),
        batch_size,
        paper_only: true,
    }
}

pub fn build_smartcore_v2_batch_spec(
    batch_size: usize,
    feature_schema: &TrainingFeatureSchema,
    target_schema: &TrainingTargetSchema,
) -> SmartCoreV2BatchSpec {
    default_smartcore_v2_batch_spec(batch_size, feature_schema, target_schema)
}

pub fn build_smartcore_v2_training_batch(
    examples: &[TrainingCandidateExample],
    feature_schema: &TrainingFeatureSchema,
    target_schema: &TrainingTargetSchema,
    spec: &SmartCoreV2BatchSpec,
) -> Result<SmartCoreV2TrainingBatch, String> {
    if examples.is_empty() {
        return Err("smartcore v2 training batch requires at least one example".to_string());
    }
    let member_id = &examples[0].member_id;
    if examples
        .iter()
        .any(|example| example.member_id != *member_id)
    {
        return Err("smartcore v2 training batch must stay per-member".to_string());
    }
    let mut ordered = examples.to_vec();
    ordered.sort_by(|left, right| left.training_example_id.cmp(&right.training_example_id));
    let mut feature_rows = Vec::new();
    let mut target_rows = Vec::new();
    for example in &ordered {
        feature_rows.push(build_training_feature_row(example, feature_schema)?);
        let Some(target_row) = build_training_target_row(example, target_schema) else {
            return Err(format!(
                "training target row unavailable for {}",
                example.training_example_id
            ));
        };
        target_rows.push(target_row);
    }
    Ok(SmartCoreV2TrainingBatch {
        batch_id: format!("{}-{}", spec.spec_id, member_id),
        member_id: member_id.clone(),
        split: TrainingBatchSplit::All,
        example_ids: ordered
            .iter()
            .map(|example| example.training_example_id.clone())
            .collect(),
        batch_size: ordered.len(),
        feature_rows,
        target_rows,
        feature_schema_id: feature_schema.schema_id.clone(),
        target_schema_id: target_schema.schema_id.clone(),
        spec_id: spec.spec_id.clone(),
        paper_only: true,
    })
}

fn training_example_ids_for_split(
    split: &TrainingSplitResult,
    split_kind: TrainingBatchSplit,
) -> std::collections::BTreeSet<&str> {
    match split_kind {
        TrainingBatchSplit::Train => split.train_ids.iter().map(String::as_str).collect(),
        TrainingBatchSplit::Validation => split.validation_ids.iter().map(String::as_str).collect(),
        TrainingBatchSplit::Test => split.test_ids.iter().map(String::as_str).collect(),
        TrainingBatchSplit::All => split
            .train_ids
            .iter()
            .chain(split.validation_ids.iter())
            .chain(split.test_ids.iter())
            .map(String::as_str)
            .collect(),
    }
}

pub fn build_training_batches(
    dataset: &TrainingCandidateDataset,
    split: &TrainingSplitResult,
    feature_schema: &TrainingFeatureSchema,
    target_schema: &TrainingTargetSchema,
    batch_config: &TrainingBatchIteratorConfig,
) -> Result<TrainingBatchIteratorResult, String> {
    if !batch_config.paper_only || !dataset.paper_only {
        return Err("training batch iterator must remain paper-only".to_string());
    }
    if batch_config.shuffle {
        return Err("training batch iterator does not allow shuffle".to_string());
    }
    if batch_config.batch_size == 0 {
        return Err("training batch iterator batch_size must be positive".to_string());
    }
    let selected_ids = training_example_ids_for_split(split, batch_config.split);
    let mut selected_examples: Vec<&TrainingCandidateExample> = dataset
        .examples
        .iter()
        .filter(|example| selected_ids.contains(example.training_example_id.as_str()))
        .filter(|example| {
            batch_config
                .member_id
                .as_deref()
                .map(|member_id| example.member_id == member_id)
                .unwrap_or(true)
        })
        .collect();
    selected_examples.sort_by(|left, right| {
        left.member_id
            .cmp(&right.member_id)
            .then_with(|| left.training_example_id.cmp(&right.training_example_id))
    });
    let mut grouped: std::collections::BTreeMap<String, Vec<&TrainingCandidateExample>> =
        std::collections::BTreeMap::new();
    let mut skipped_reasons = Vec::new();
    for example in selected_examples {
        if build_training_target_row(example, target_schema).is_none() {
            skipped_reasons.push(format!(
                "{} excluded by target schema",
                example.training_example_id
            ));
            continue;
        }
        grouped
            .entry(example.member_id.clone())
            .or_default()
            .push(example);
    }
    let spec =
        default_smartcore_v2_batch_spec(batch_config.batch_size, feature_schema, target_schema);
    let mut batches = Vec::new();
    let mut example_count = 0;
    for (member_id, member_examples) in grouped {
        for chunk in member_examples.chunks(batch_config.batch_size) {
            if batch_config.drop_last && chunk.len() < batch_config.batch_size {
                skipped_reasons.push(format!(
                    "{member_id} trailing batch dropped by drop_last policy"
                ));
                continue;
            }
            let owned_examples: Vec<TrainingCandidateExample> =
                chunk.iter().map(|example| (*example).clone()).collect();
            example_count += owned_examples.len();
            let mut batch = build_smartcore_v2_training_batch(
                &owned_examples,
                feature_schema,
                target_schema,
                &spec,
            )?;
            batch.split = batch_config.split;
            batches.push(batch);
        }
    }
    Ok(TrainingBatchIteratorResult {
        batch_count: batches.len(),
        skipped_count: skipped_reasons.len(),
        batches,
        example_count,
        skipped_reasons,
        paper_only: true,
    })
}

fn loss_head_name(head: SmartCoreV2LossHead) -> &'static str {
    match head {
        SmartCoreV2LossHead::StanceLoss => "StanceLoss",
        SmartCoreV2LossHead::ConfidenceCalibrationLoss => "ConfidenceCalibrationLoss",
        SmartCoreV2LossHead::RiskLoss => "RiskLoss",
        SmartCoreV2LossHead::EvidenceNeedLoss => "EvidenceNeedLoss",
        SmartCoreV2LossHead::UncertaintyLoss => "UncertaintyLoss",
        SmartCoreV2LossHead::ExpectedReturnHintLoss => "ExpectedReturnHintLoss",
    }
}

pub fn validate_loss_contract_against_batch(
    batch: &SmartCoreV2TrainingBatch,
    loss_contract: &SmartCoreV2LossContract,
) -> LossContractValidationResult {
    let mut missing_targets = Vec::new();
    if loss_contract
        .enabled_heads
        .contains(&SmartCoreV2LossHead::UncertaintyLoss)
        && batch
            .target_rows
            .iter()
            .any(|row| row.uncertainty_target.is_none())
    {
        missing_targets.push("uncertainty_target".to_string());
    }
    if loss_contract
        .enabled_heads
        .contains(&SmartCoreV2LossHead::ExpectedReturnHintLoss)
        && batch
            .target_rows
            .iter()
            .any(|row| row.expected_return_target.is_none())
    {
        missing_targets.push("expected_return_target".to_string());
    }
    let disabled_heads: Vec<String> = [
        SmartCoreV2LossHead::StanceLoss,
        SmartCoreV2LossHead::ConfidenceCalibrationLoss,
        SmartCoreV2LossHead::RiskLoss,
        SmartCoreV2LossHead::EvidenceNeedLoss,
        SmartCoreV2LossHead::UncertaintyLoss,
        SmartCoreV2LossHead::ExpectedReturnHintLoss,
    ]
    .into_iter()
    .filter(|head| !loss_contract.enabled_heads.contains(head))
    .map(loss_head_name)
    .map(str::to_string)
    .collect();
    LossContractValidationResult {
        valid: missing_targets.is_empty() && loss_contract.paper_only && batch.paper_only,
        missing_targets,
        disabled_heads,
        warnings: vec!["loss contract remains contract-only; runtime deferred".to_string()],
        paper_only: true,
    }
}

pub fn validate_metric_contract_against_dataset(
    dataset: &TrainingCandidateDataset,
    metric_contract: &OfflineTrainingMetricContract,
) -> MetricContractValidationResult {
    let target_schema = TrainingTargetSchema::default();
    let required_targets_present = dataset.examples.iter().all(|example| {
        example.paper_only
            && example.target_labels.paper_only
            && build_training_target_row(example, &target_schema).is_some()
    });
    let mut warnings = Vec::new();
    if metric_contract
        .metrics
        .contains(&OfflineTrainingMetric::ExpectedReturnRankCorrelationDeferred)
    {
        warnings.push("expected return metric remains deferred without model outputs".to_string());
    }
    MetricContractValidationResult {
        valid: required_targets_present && metric_contract.paper_only,
        required_targets_present,
        warnings,
        paper_only: true,
    }
}

pub fn run_offline_trainer_dry_run_v2(
    dataset: &TrainingCandidateDataset,
    split: &TrainingSplitResult,
    config: &OfflineTrainerDryRunConfigV2,
) -> OfflineTrainerDryRunResultV2 {
    let feature_schema = TrainingFeatureSchema {
        schema_version: config.feature_schema_version.clone(),
        ..TrainingFeatureSchema::default()
    };
    let target_schema = TrainingTargetSchema {
        schema_version: config.target_schema_version.clone(),
        ..TrainingTargetSchema::default()
    };
    let train_batches = build_training_batches(
        dataset,
        split,
        &feature_schema,
        &target_schema,
        &TrainingBatchIteratorConfig {
            batch_size: config.batch_size,
            shuffle: false,
            split: TrainingBatchSplit::Train,
            member_id: None,
            drop_last: false,
            paper_only: true,
        },
    );
    let validation_batches = build_training_batches(
        dataset,
        split,
        &feature_schema,
        &target_schema,
        &TrainingBatchIteratorConfig {
            batch_size: config.batch_size,
            shuffle: false,
            split: TrainingBatchSplit::Validation,
            member_id: None,
            drop_last: false,
            paper_only: true,
        },
    );
    let test_batches = build_training_batches(
        dataset,
        split,
        &feature_schema,
        &target_schema,
        &TrainingBatchIteratorConfig {
            batch_size: config.batch_size,
            shuffle: false,
            split: TrainingBatchSplit::Test,
            member_id: None,
            drop_last: false,
            paper_only: true,
        },
    );
    let mut warnings = Vec::new();
    let mut member_batch_counts = std::collections::BTreeMap::new();
    let mut feature_schema_valid = true;
    let mut target_schema_valid = true;
    let mut batch_shapes_valid = true;
    let mut loss_contract_valid = true;
    let mut metric_contract_valid = true;
    let loss_contract = SmartCoreV2LossContract::default();
    let metric_contract = OfflineTrainingMetricContract::default();
    let train_batches = match train_batches {
        Ok(result) => result,
        Err(err) => {
            warnings.push(err);
            feature_schema_valid = false;
            target_schema_valid = false;
            batch_shapes_valid = false;
            TrainingBatchIteratorResult {
                batches: Vec::new(),
                batch_count: 0,
                example_count: 0,
                skipped_count: 0,
                skipped_reasons: Vec::new(),
                paper_only: true,
            }
        }
    };
    let validation_batches = validation_batches.unwrap_or_else(|err| {
        warnings.push(err);
        batch_shapes_valid = false;
        TrainingBatchIteratorResult {
            batches: Vec::new(),
            batch_count: 0,
            example_count: 0,
            skipped_count: 0,
            skipped_reasons: Vec::new(),
            paper_only: true,
        }
    });
    let test_batches = test_batches.unwrap_or_else(|err| {
        warnings.push(err);
        batch_shapes_valid = false;
        TrainingBatchIteratorResult {
            batches: Vec::new(),
            batch_count: 0,
            example_count: 0,
            skipped_count: 0,
            skipped_reasons: Vec::new(),
            paper_only: true,
        }
    });
    for batch in train_batches
        .batches
        .iter()
        .chain(validation_batches.batches.iter())
        .chain(test_batches.batches.iter())
    {
        *member_batch_counts
            .entry(batch.member_id.clone())
            .or_insert(0) += 1;
        batch_shapes_valid &= batch.feature_rows.len() == batch.target_rows.len()
            && batch.batch_size == batch.feature_rows.len()
            && batch.paper_only
            && batch.feature_rows.iter().all(|row| row.paper_only)
            && batch.target_rows.iter().all(|row| row.paper_only);
        if config.validate_loss_contract {
            let loss_validation = validate_loss_contract_against_batch(batch, &loss_contract);
            loss_contract_valid &= loss_validation.valid;
            warnings.extend(loss_validation.warnings);
        }
    }
    if config.validate_metric_contract {
        let metric_validation = validate_metric_contract_against_dataset(dataset, &metric_contract);
        metric_contract_valid = metric_validation.valid;
        warnings.extend(metric_validation.warnings);
    }
    feature_schema_valid &= dataset.examples.iter().all(|example| {
        build_training_feature_row(example, &feature_schema)
            .map(|row| row.paper_only)
            .unwrap_or(false)
    });
    target_schema_valid &= dataset
        .examples
        .iter()
        .filter(|example| split.train_ids.contains(&example.training_example_id))
        .all(|example| build_training_target_row(example, &target_schema).is_some());
    let dry_run_status = if !feature_schema_valid
        || !target_schema_valid
        || !batch_shapes_valid
        || !loss_contract_valid
        || !metric_contract_valid
        || train_batches.batch_count == 0
    {
        OfflineTrainerDryRunStatus::Failed
    } else if warnings.is_empty() {
        OfflineTrainerDryRunStatus::Passed
    } else {
        OfflineTrainerDryRunStatus::PassedWithWarnings
    };
    OfflineTrainerDryRunResultV2 {
        run_id: config.run_id.clone(),
        dataset_id: dataset.dataset_id.clone(),
        example_count: dataset.example_count,
        batch_size: config.batch_size,
        train_batch_count: train_batches.batch_count,
        validation_batch_count: validation_batches.batch_count,
        test_batch_count: test_batches.batch_count,
        member_batch_counts,
        feature_schema_valid,
        target_schema_valid,
        batch_shapes_valid,
        loss_contract_valid,
        metric_contract_valid,
        no_training_executed: true,
        no_weight_mutation: true,
        no_checkpoint_written: true,
        dry_run_status,
        warnings,
        paper_only: true,
    }
}

pub fn evaluate_offline_trainer_design_status(
    dry_run_result: &OfflineTrainerDryRunResultV2,
    design_gate: &OfflineTrainingDesignGate,
    label_quality_summary: &LabelQualitySummary,
) -> OfflineTrainerDesignStatus {
    let batch_contract_status = if dry_run_result.batch_shapes_valid {
        OfflineTrainerContractStatus::Ready
    } else {
        OfflineTrainerContractStatus::Blocked
    };
    let loss_contract_status = if dry_run_result.loss_contract_valid {
        OfflineTrainerContractStatus::ContractOnly
    } else {
        OfflineTrainerContractStatus::Blocked
    };
    let metric_contract_status = if dry_run_result.metric_contract_valid {
        OfflineTrainerContractStatus::ContractOnly
    } else {
        OfflineTrainerContractStatus::Blocked
    };
    let mut blockers = Vec::new();
    let mut warnings = dry_run_result.warnings.clone();
    if !dry_run_result.no_training_executed
        || !dry_run_result.no_weight_mutation
        || !dry_run_result.no_checkpoint_written
    {
        blockers.push(
            "offline trainer v2 must not train, mutate weights, or write checkpoints".to_string(),
        );
    }
    if matches!(
        design_gate.design_status,
        OfflineTrainingDesignGateStatus::BlockedBySafety
    ) {
        blockers.push("existing offline training design gate blocked by safety".to_string());
    }
    let design_status = if !blockers.is_empty() {
        OfflineTrainerDesignStatusLevel::BlockedBySafety
    } else if !dry_run_result.batch_shapes_valid {
        OfflineTrainerDesignStatusLevel::BlockedByShapeError
    } else if matches!(
        label_quality_summary.label_quality_status,
        LabelQualityStatus::Blocked
    ) {
        OfflineTrainerDesignStatusLevel::BlockedByLabelQuality
    } else if dry_run_result.train_batch_count == 0
        || matches!(
            design_gate.design_status,
            OfflineTrainingDesignGateStatus::NeedsMoreValidatedLabels
                | OfflineTrainingDesignGateStatus::NeedsMoreCoverage
        )
    {
        OfflineTrainerDesignStatusLevel::NeedsMoreData
    } else if matches!(
        dry_run_result.dry_run_status,
        OfflineTrainerDryRunStatus::Passed
    ) && matches!(
        design_gate.design_status,
        OfflineTrainingDesignGateStatus::ReadyForOfflineTrainerDryRun
            | OfflineTrainingDesignGateStatus::ReadyWithWarnings
    ) {
        if warnings.is_empty() {
            OfflineTrainerDesignStatusLevel::ReadyForTinyTrainingDryRun
        } else {
            OfflineTrainerDesignStatusLevel::ReadyWithWarnings
        }
    } else {
        OfflineTrainerDesignStatusLevel::ReadyWithWarnings
    };
    if matches!(
        design_status,
        OfflineTrainerDesignStatusLevel::NeedsMoreData
    ) {
        warnings
            .push("trainer skeleton is ready but more validated data is still needed".to_string());
    }
    OfflineTrainerDesignStatus {
        dataset_id: dry_run_result.dataset_id.clone(),
        dry_run_status: dry_run_result.dry_run_status,
        batch_contract_status,
        loss_contract_status,
        metric_contract_status,
        member_coverage_status: design_gate.member_coverage_status,
        label_quality_status: label_quality_summary.label_quality_status,
        design_status,
        blockers,
        warnings,
        paper_only: true,
    }
}

impl Default for TinyTrainingEligibilityPolicy {
    fn default() -> Self {
        Self {
            min_training_examples_required: default_min_tiny_training_examples_required(),
            min_members_required: default_min_tiny_training_members_required(),
            allow_expected_deferred_warnings: true,
            allow_ready_with_warnings: true,
            require_no_blocking_warnings: true,
            require_no_leakage: true,
            require_no_broker_order_account: true,
            require_no_live_inference: true,
            paper_only: true,
        }
    }
}

