pub fn validate_mamba3_temporal_adapter_spec(
    spec: &Mamba3TemporalAdapterSpec,
) -> AdapterShapeValidationResult {
    let mut warnings = Vec::new();
    if spec.sequence_len_hint == 0 {
        warnings.push("Mamba3 adapter sequence_len_hint must be positive".to_string());
    }
    if spec.feature_dim_hint == 0 {
        warnings.push("Mamba3 adapter feature_dim_hint must be positive".to_string());
    }
    if !matches!(
        spec.runtime_status,
        SmartCoreV2AdapterStatus::RuntimeDeferred
    ) {
        warnings.push("Mamba3 adapter runtime must remain deferred".to_string());
    }
    if !matches!(
        spec.training_status,
        SmartCoreV2AdapterStatus::TrainingDeferred
    ) {
        warnings.push("Mamba3 adapter training must remain deferred".to_string());
    }
    if !spec.paper_only {
        warnings.push("Mamba3 adapter spec must remain paper-only".to_string());
    }
    AdapterShapeValidationResult {
        shape_id: spec.spec_id.clone(),
        validation_status: if warnings.is_empty() {
            AdapterShapeValidationStatus::Valid
        } else {
            AdapterShapeValidationStatus::Invalid
        },
        warnings,
        paper_only: true,
    }
}

pub fn validate_gated_deltanet_memory_adapter_spec(
    spec: &GatedDeltaNetMemoryAdapterSpec,
) -> AdapterShapeValidationResult {
    let mut warnings = Vec::new();
    if spec.memory_dim_hint == 0 {
        warnings.push("Gated DeltaNet memory_dim_hint must be positive".to_string());
    }
    if !matches!(
        spec.runtime_status,
        SmartCoreV2AdapterStatus::RuntimeDeferred
    ) {
        warnings.push("Gated DeltaNet adapter runtime must remain deferred".to_string());
    }
    if !matches!(
        spec.training_status,
        SmartCoreV2AdapterStatus::TrainingDeferred
    ) {
        warnings.push("Gated DeltaNet adapter training must remain deferred".to_string());
    }
    if !spec.paper_only {
        warnings.push("Gated DeltaNet adapter spec must remain paper-only".to_string());
    }
    AdapterShapeValidationResult {
        shape_id: spec.spec_id.clone(),
        validation_status: if warnings.is_empty() {
            AdapterShapeValidationStatus::Valid
        } else {
            AdapterShapeValidationStatus::Invalid
        },
        warnings,
        paper_only: true,
    }
}

pub fn validate_sparse_event_attention_adapter_spec(
    spec: &SparseEventAttentionAdapterSpec,
) -> AdapterShapeValidationResult {
    let mut warnings = Vec::new();
    if spec.enabled && spec.event_types.is_empty() {
        warnings.push("Sparse/Event adapter enabled without event types".to_string());
    }
    if spec.enabled && spec.max_events_per_sequence == 0 {
        warnings.push("Sparse/Event adapter max_events_per_sequence must be positive".to_string());
    }
    if !matches!(
        spec.attention_runtime_status,
        AdapterDeferredStatus::Deferred
    ) {
        warnings.push("Sparse/Event adapter runtime must remain deferred".to_string());
    }
    if !spec.paper_only {
        warnings.push("Sparse/Event adapter spec must remain paper-only".to_string());
    }
    AdapterShapeValidationResult {
        shape_id: spec.spec_id.clone(),
        validation_status: if warnings.is_empty() {
            AdapterShapeValidationStatus::Valid
        } else {
            AdapterShapeValidationStatus::Invalid
        },
        warnings,
        paper_only: true,
    }
}

pub fn validate_head_adapter_spec(
    spec: &SmartCoreV2HeadAdapterSpec,
) -> AdapterShapeValidationResult {
    let mut warnings = Vec::new();
    if spec.output_dim == 0 {
        warnings.push("head adapter output_dim must be positive".to_string());
    }
    if !matches!(
        spec.runtime_status,
        SmartCoreV2AdapterStatus::RuntimeDeferred
    ) {
        warnings.push("head adapter runtime must remain deferred".to_string());
    }
    if !matches!(
        spec.training_status,
        SmartCoreV2AdapterStatus::TrainingDeferred
    ) {
        warnings.push("head adapter training must remain deferred".to_string());
    }
    if !spec.paper_only {
        warnings.push("head adapter spec must remain paper-only".to_string());
    }
    AdapterShapeValidationResult {
        shape_id: spec.spec_id.clone(),
        validation_status: if warnings.is_empty() {
            AdapterShapeValidationStatus::Valid
        } else {
            AdapterShapeValidationStatus::Invalid
        },
        warnings,
        paper_only: true,
    }
}

pub fn default_head_specs_for_member(member_id: &str) -> Vec<SmartCoreV2HeadAdapterSpec> {
    role_head_order(role_for_member_id(member_id).unwrap_or(IndependentMemberRole::TrendEntry))
        .into_iter()
        .map(|head| build_head_adapter_spec(member_id, head))
        .collect()
}

fn adapter_profile_status(
    core_v2_spec: &SmartMemberCoreV2Spec,
    head_specs: &[SmartCoreV2HeadAdapterSpec],
) -> SmartCoreV2AdapterStatus {
    let required_heads_valid = head_specs.iter().all(|head| {
        head.output_dim > 0
            && matches!(
                head.runtime_status,
                SmartCoreV2AdapterStatus::RuntimeDeferred
            )
            && matches!(
                head.training_status,
                SmartCoreV2AdapterStatus::TrainingDeferred
            )
    });
    if core_v2_spec.base_core_spec.max_context_tokens_hint == 0
        || core_v2_spec.base_core_spec.memory_budget_mb_hint == 0
        || !required_heads_valid
    {
        SmartCoreV2AdapterStatus::Invalid
    } else {
        SmartCoreV2AdapterStatus::ShapeOnly
    }
}

pub fn build_member_smartcore_adapter_profile(
    member: &AICommitteeMember,
    core_v2_spec: &SmartMemberCoreV2Spec,
    include_sparse_event_attention: bool,
) -> MemberSmartCoreAdapterProfile {
    let role = member
        .role
        .or_else(|| role_for_member_id(member.member_id.as_str()))
        .unwrap_or(IndependentMemberRole::TrendEntry);
    let head_specs = role_head_order(role)
        .into_iter()
        .map(|head| build_head_adapter_spec(&member.member_id, head))
        .collect::<Vec<_>>();
    MemberSmartCoreAdapterProfile {
        profile_id: format!("{}-smartcore-adapter-profile", member.member_id),
        member_id: member.member_id.clone(),
        role,
        core_v2_spec: core_v2_spec.clone(),
        mamba3_spec: build_mamba3_temporal_adapter_spec(core_v2_spec),
        gated_deltanet_spec: build_gated_deltanet_memory_adapter_spec(core_v2_spec),
        sparse_event_attention_spec: build_sparse_event_attention_adapter_spec(
            &member.member_id,
            include_sparse_event_attention,
        ),
        adapter_status: adapter_profile_status(core_v2_spec, &head_specs),
        head_specs,
        paper_only: true,
    }
}

pub fn build_adapter_registry_for_members(
    members: &[AICommitteeMember],
    include_sparse_event_attention: bool,
) -> SmartCoreAdapterRegistry {
    let core_v2_specs = build_smart_core_v2_specs_for_members(members);
    let profiles = members
        .iter()
        .filter_map(|member| {
            core_v2_specs
                .iter()
                .find(|spec| spec.member_id == member.member_id)
                .map(|spec| {
                    build_member_smartcore_adapter_profile(
                        member,
                        spec,
                        include_sparse_event_attention,
                    )
                })
        })
        .collect::<Vec<_>>();
    let runtime_ready_count = 0;
    let training_ready_count = 0;
    let shape_only_count = profiles
        .iter()
        .filter(|profile| matches!(profile.adapter_status, SmartCoreV2AdapterStatus::ShapeOnly))
        .count();
    SmartCoreAdapterRegistry {
        registry_id: "smartcore-v2-adapter-registry".to_string(),
        profile_count: profiles.len(),
        profiles,
        runtime_ready_count,
        training_ready_count,
        shape_only_count,
        paper_only: true,
    }
}

fn build_adapter_input_shape_from_batch(
    batch: &SmartCoreV2TrainingBatch,
    feature_schema: &TrainingFeatureSchema,
) -> SmartCoreV2AdapterInputShape {
    let canonical_member_id =
        resolve_canonical_member_id(&batch.member_id).unwrap_or_else(|| batch.member_id.clone());
    let first_row = batch.feature_rows.first();
    let market_feature_dim = first_row.map(|row| row.market_features.len()).unwrap_or(0);
    let news_feature_dim = first_row.map(|row| row.news_features.len()).unwrap_or(0);
    let owner_context_dim = first_row
        .and_then(|row| row.owner_context_features.as_ref())
        .map(|features| features.len())
        .unwrap_or(0);
    let memory_feature_dim = first_row
        .and_then(|row| row.prior_memory_features.as_ref())
        .map(|features| features.len())
        .unwrap_or(0);
    let style_feature_dim = first_row
        .and_then(|row| row.style_features.as_ref())
        .map(|features| features.len())
        .unwrap_or(0);
    let calibration_feature_dim = first_row
        .and_then(|row| row.calibration_features.as_ref())
        .map(|features| features.len())
        .unwrap_or(0);
    SmartCoreV2AdapterInputShape {
        shape_id: format!("{}-adapter-input-shape", batch.batch_id),
        member_id: canonical_member_id,
        batch_id: Some(batch.batch_id.clone()),
        example_count: batch.batch_size,
        sequence_len: feature_schema.sequence_len_hint.max(1),
        feature_dim: market_feature_dim
            + news_feature_dim
            + owner_context_dim
            + memory_feature_dim
            + style_feature_dim
            + calibration_feature_dim,
        market_feature_dim,
        news_feature_dim,
        owner_context_dim,
        memory_feature_dim,
        style_feature_dim,
        calibration_feature_dim,
        has_news_features: news_feature_dim > 0,
        has_owner_context: owner_context_dim > 0,
        has_prior_memory: memory_feature_dim > 0,
        paper_only: true,
    }
}

pub fn build_adapter_input_shape_from_training_batch(
    batch: &SmartCoreV2TrainingBatch,
    feature_schema: &TrainingFeatureSchema,
) -> SmartCoreV2AdapterInputShape {
    build_adapter_input_shape_from_batch(batch, feature_schema)
}

fn head_output_dim_by_kind(
    head_specs: &[SmartCoreV2HeadAdapterSpec],
    target_head: SmartCoreV2HeadKind,
) -> Option<usize> {
    head_specs
        .iter()
        .find(|spec| spec.head_kind == target_head)
        .map(|spec| spec.output_dim)
}

fn build_adapter_output_shape_for_batch(
    batch: &SmartCoreV2TrainingBatch,
    head_specs: &[SmartCoreV2HeadAdapterSpec],
    target_schema: &TrainingTargetSchema,
) -> SmartCoreV2AdapterOutputShape {
    let canonical_member_id =
        resolve_canonical_member_id(&batch.member_id).unwrap_or_else(|| batch.member_id.clone());
    let target_contains = |target_head: TrainingTargetHead| {
        target_schema
            .target_heads
            .iter()
            .any(|head| *head == target_head)
    };
    let enabled_heads = head_specs
        .iter()
        .filter(|spec| {
            target_schema
                .target_heads
                .iter()
                .any(|head| adapter_head_kind(*head) == spec.head_kind && spec.output_dim > 0)
        })
        .map(|spec| spec.head_kind)
        .collect::<Vec<_>>();
    SmartCoreV2AdapterOutputShape {
        shape_id: format!("{}-adapter-output-shape", batch.batch_id),
        member_id: canonical_member_id,
        batch_id: Some(batch.batch_id.clone()),
        example_count: batch.batch_size,
        enabled_heads,
        stance_output_dim: head_output_dim_by_kind(head_specs, SmartCoreV2HeadKind::Stance)
            .unwrap_or(0),
        confidence_output_dim: head_output_dim_by_kind(
            head_specs,
            SmartCoreV2HeadKind::ConfidenceCalibration,
        )
        .unwrap_or(0),
        risk_output_dim: head_output_dim_by_kind(head_specs, SmartCoreV2HeadKind::Risk)
            .unwrap_or(0),
        evidence_output_dim: head_output_dim_by_kind(head_specs, SmartCoreV2HeadKind::EvidenceNeed)
            .unwrap_or(0),
        uncertainty_output_dim: target_contains(TrainingTargetHead::Uncertainty).then(|| {
            head_output_dim_by_kind(head_specs, SmartCoreV2HeadKind::Uncertainty).unwrap_or(0)
        }),
        expected_return_output_dim: target_contains(TrainingTargetHead::ExpectedReturnHint).then(
            || {
                head_output_dim_by_kind(head_specs, SmartCoreV2HeadKind::ExpectedReturnHint)
                    .unwrap_or(0)
            },
        ),
        paper_only: true,
    }
}

pub fn build_expected_adapter_output_shape(
    batch: &SmartCoreV2TrainingBatch,
    target_schema: &TrainingTargetSchema,
    enabled_heads: &[TrainingTargetHead],
) -> SmartCoreV2AdapterOutputShape {
    let member_id = display_name_for_member_id(&batch.member_id).to_string();
    let head_specs = enabled_heads
        .iter()
        .copied()
        .map(|head| build_head_adapter_spec(&member_id, head))
        .collect::<Vec<_>>();
    build_adapter_output_shape_for_batch(batch, &head_specs, target_schema)
}

pub fn validate_no_adapter_output_values(output_summary: &str) -> AdapterOutputValueGuard {
    let lower = output_summary.to_ascii_lowercase();
    let logits_present = lower.contains("logit");
    let probabilities_present = lower.contains("probab");
    let predictions_present = lower.contains("prediction");
    let model_scores_present = lower.contains("model score") || lower.contains("model_score");
    let mut violations = Vec::new();
    if logits_present {
        violations.push("adapter output summary exposed logits".to_string());
    }
    if probabilities_present {
        violations.push("adapter output summary exposed probabilities".to_string());
    }
    if predictions_present {
        violations.push("adapter output summary exposed predictions".to_string());
    }
    if model_scores_present {
        violations.push("adapter output summary exposed model scores".to_string());
    }
    AdapterOutputValueGuard {
        logits_present,
        probabilities_present,
        predictions_present,
        model_scores_present,
        guard_status: if violations.is_empty() {
            AdapterOutputValueGuardStatus::Preserved
        } else {
            AdapterOutputValueGuardStatus::Violated
        },
        violations,
        paper_only: true,
    }
}

pub fn validate_batch_against_adapter_profile(
    batch: &SmartCoreV2TrainingBatch,
    feature_schema: &TrainingFeatureSchema,
    target_schema: &TrainingTargetSchema,
    profile: &MemberSmartCoreAdapterProfile,
) -> BatchAdapterShapeValidation {
    let canonical_profile_member_id = resolve_canonical_member_id(&profile.member_id)
        .unwrap_or_else(|| profile.member_id.clone());
    let adapter = ShapeOnlySmartCoreV2Adapter {
        adapter_id: format!("{}-shape-only-adapter", profile.member_id),
        member_id: canonical_profile_member_id.clone(),
        adapter_kind: adapter_kind_for_profile(
            &profile.core_v2_spec,
            profile.sparse_event_attention_spec.is_some(),
        ),
        status: profile.adapter_status,
        paper_only: true,
    };
    let input_shape = build_adapter_input_shape_from_batch(batch, feature_schema);
    let expected_output_shape =
        build_adapter_output_shape_for_batch(batch, &profile.head_specs, target_schema);
    let input_validation = adapter.validate_input_shape(&input_shape);
    let output_validation = adapter.validate_output_shape(&expected_output_shape);
    let output_value_guard =
        validate_no_adapter_output_values(&format!("{:?}", expected_output_shape));
    let mut warnings = input_validation.warnings.clone();
    warnings.extend(output_validation.warnings.clone());
    warnings.extend(output_value_guard.violations.clone());
    let canonical_batch_member_id =
        resolve_canonical_member_id(&batch.member_id).unwrap_or_else(|| batch.member_id.clone());
    if canonical_batch_member_id != canonical_profile_member_id {
        warnings.push("batch member id does not match adapter profile member id".to_string());
    }
    let validation_status = if matches!(profile.adapter_status, SmartCoreV2AdapterStatus::Invalid)
        || matches!(
            input_validation.validation_status,
            AdapterShapeValidationStatus::Invalid
        )
        || matches!(
            output_validation.validation_status,
            AdapterShapeValidationStatus::Invalid
        )
        || matches!(
            output_value_guard.guard_status,
            AdapterOutputValueGuardStatus::Violated
        ) {
        AdapterShapeValidationStatus::Invalid
    } else if warnings.is_empty() {
        AdapterShapeValidationStatus::Valid
    } else {
        AdapterShapeValidationStatus::ValidWithWarnings
    };
    BatchAdapterShapeValidation {
        validation_id: format!("{}-adapter-shape-validation", batch.batch_id),
        batch_id: batch.batch_id.clone(),
        member_id: display_name_for_member_id(&batch.member_id).to_string(),
        input_shape,
        expected_output_shape,
        input_shape_status: input_validation.validation_status,
        output_shape_status: output_validation.validation_status,
        adapter_profile_status: profile.adapter_status,
        validation_status,
        warnings,
        output_value_guard,
        paper_only: true,
    }
}

pub fn run_adapter_skeleton_dry_run(
    members: &[AICommitteeMember],
    batches: &[SmartCoreV2TrainingBatch],
    feature_schema: &TrainingFeatureSchema,
    target_schema: &TrainingTargetSchema,
    config: &AdapterSkeletonDryRunConfig,
) -> AdapterSkeletonDryRunResult {
    let registry =
        build_adapter_registry_for_members(members, config.include_sparse_event_attention);
    let valid_profile_count = registry
        .profiles
        .iter()
        .filter(|profile| matches!(profile.adapter_status, SmartCoreV2AdapterStatus::ShapeOnly))
        .count();
    let invalid_profile_count = registry.profile_count.saturating_sub(valid_profile_count);
    let mut warnings = Vec::new();
    let mut unmatched_batch_count = 0usize;
    let batch_validations = if config.validate_batches {
        batches
            .iter()
            .filter_map(|batch| {
                if let Some(profile) = registry.get_profile(&batch.member_id) {
                    Some(validate_batch_against_adapter_profile(
                        batch,
                        feature_schema,
                        target_schema,
                        profile,
                    ))
                } else {
                    unmatched_batch_count += 1;
                    None
                }
            })
            .collect::<Vec<_>>()
    } else {
        Vec::new()
    };
    if unmatched_batch_count > 0 {
        warnings.push(format!(
            "{unmatched_batch_count} adapter batch(es) had no matching member profile"
        ));
    }
    if config.validate_batches && batch_validations.len() != batches.len() {
        warnings.push("adapter dry-run did not validate every requested batch".to_string());
    }
    if !config.include_mamba3 {
        warnings.push("Mamba3 adapter skeleton excluded by config".to_string());
    }
    if !config.include_gated_deltanet {
        warnings.push("Gated DeltaNet adapter skeleton excluded by config".to_string());
    }
    if !registry.validate_registry() {
        warnings.push("adapter registry failed shape-only registry validation".to_string());
    }
    if config.require_runtime_deferred && registry.runtime_ready_count > 0 {
        warnings.push("runtime-ready adapter detected during deferred-only dry run".to_string());
    }
    if config.require_training_deferred && registry.training_ready_count > 0 {
        warnings.push("training-ready adapter detected during deferred-only dry run".to_string());
    }
    if batch_validations.iter().any(|validation| {
        matches!(
            validation.validation_status,
            AdapterShapeValidationStatus::Invalid
        )
    }) {
        warnings.push("invalid batch-to-adapter shape validation detected".to_string());
    }
    let dry_run_status = if config.require_runtime_deferred && registry.runtime_ready_count > 0
        || config.require_training_deferred && registry.training_ready_count > 0
        || invalid_profile_count > 0
        || unmatched_batch_count > 0
        || config.validate_batches && batch_validations.len() != batches.len()
        || batch_validations.iter().any(|validation| {
            matches!(
                validation.validation_status,
                AdapterShapeValidationStatus::Invalid
            )
        }) {
        AdapterSkeletonDryRunStatus::Failed
    } else if warnings.is_empty() {
        AdapterSkeletonDryRunStatus::Passed
    } else {
        AdapterSkeletonDryRunStatus::PassedWithWarnings
    };
    AdapterSkeletonDryRunResult {
        run_id: config.run_id.clone(),
        registry,
        batch_validations,
        profile_count: members.len(),
        valid_profile_count,
        invalid_profile_count,
        runtime_ready_count: 0,
        training_ready_count: 0,
        all_runtime_deferred: true,
        all_training_deferred: true,
        no_forward_method_present: true,
        no_weight_access_present: true,
        no_checkpoint_present: true,
        dry_run_status,
        warnings,
        paper_only: true,
    }
}

pub fn evaluate_adapter_skeleton_safety(
    dry_run_result: &AdapterSkeletonDryRunResult,
) -> AdapterSkeletonSafetyGuard {
    let forward_method_detected = !dry_run_result.no_forward_method_present;
    let train_method_detected = dry_run_result.training_ready_count > 0;
    let infer_method_detected = dry_run_result.runtime_ready_count > 0;
    let weight_access_detected = !dry_run_result.no_weight_access_present;
    let checkpoint_path_detected = !dry_run_result.no_checkpoint_present;
    let model_parameter_detected = weight_access_detected;
    let runtime_ready_detected = dry_run_result.runtime_ready_count > 0;
    let training_ready_detected = dry_run_result.training_ready_count > 0;
    let live_inference_detected = infer_method_detected;
    let broker_order_account_detected = false;
    let mut violations = Vec::new();
    if forward_method_detected {
        violations.push("forward method detected on shape-only adapter skeleton".to_string());
    }
    if train_method_detected {
        violations.push("train method detected on adapter skeleton".to_string());
    }
    if infer_method_detected {
        violations.push("infer method detected on adapter skeleton".to_string());
    }
    if weight_access_detected {
        violations.push("weight access detected on adapter skeleton".to_string());
    }
    if checkpoint_path_detected {
        violations.push("checkpoint path detected on adapter skeleton".to_string());
    }
    if model_parameter_detected {
        violations.push("model parameter exposure detected on adapter skeleton".to_string());
    }
    if runtime_ready_detected {
        violations.push("runtime-ready adapter detected on skeleton pass".to_string());
    }
    if training_ready_detected {
        violations.push("training-ready adapter detected on skeleton pass".to_string());
    }
    if live_inference_detected {
        violations.push("live inference detected on adapter skeleton".to_string());
    }
    if broker_order_account_detected {
        violations.push("broker/order/account path detected on adapter skeleton".to_string());
    }
    AdapterSkeletonSafetyGuard {
        forward_method_detected,
        train_method_detected,
        infer_method_detected,
        weight_access_detected,
        checkpoint_path_detected,
        model_parameter_detected,
        runtime_ready_detected,
        training_ready_detected,
        live_inference_detected,
        broker_order_account_detected,
        safety_status: if violations.is_empty() {
            TrainingSimulationSafetyStatus::Preserved
        } else {
            TrainingSimulationSafetyStatus::Violated
        },
        violations,
        paper_only: true,
    }
}

pub fn default_adapter_input_schema_v1() -> AdapterInputSchemaV1 {
    AdapterInputSchemaV1 {
        schema_id: "adapter-input-schema-v1".to_string(),
        version: AdapterInputSchemaVersion::V1,
        allowed_feature_groups: vec![
            AdapterInputFeatureGroup::Market,
            AdapterInputFeatureGroup::News,
            AdapterInputFeatureGroup::OwnerContext,
            AdapterInputFeatureGroup::PriorMemory,
            AdapterInputFeatureGroup::StyleBlend,
            AdapterInputFeatureGroup::CalibrationPrior,
        ],
        required_feature_groups: vec![AdapterInputFeatureGroup::Market],
        sequence_len_policy: AdapterSequenceLenPolicy::FixedWindow,
        feature_dim_policy: AdapterFeatureDimPolicy::PositiveOnly,
        text_feature_policy: AdapterFieldPolicy::Allowed,
        categorical_feature_policy: AdapterFieldPolicy::Allowed,
        numeric_feature_policy: AdapterFieldPolicy::Allowed,
        temporal_order_policy: AdapterTemporalOrderPolicy::PreDecisionOnly,
        leakage_policy: AdapterInputLeakagePolicy {
            forbid_target_labels: true,
            forbid_outcome_labels: true,
            forbid_chairman_labels: true,
            forbid_risk_veto_labels: true,
            forbid_broker_order_account: true,
            forbid_live_inference: true,
            paper_only: true,
        },
        paper_only: true,
    }
}

pub fn validate_adapter_input_schema_v1(
    schema: &AdapterInputSchemaV1,
) -> AdapterInputSchemaValidationResult {
    let missing_required_groups = schema
        .required_feature_groups
        .iter()
        .copied()
        .filter(|group| !schema.allowed_feature_groups.contains(group))
        .collect::<Vec<_>>();
    let forbidden_groups = schema
        .allowed_feature_groups
        .iter()
        .copied()
        .filter(|group| {
            !matches!(
                group,
                AdapterInputFeatureGroup::Market
                    | AdapterInputFeatureGroup::News
                    | AdapterInputFeatureGroup::OwnerContext
                    | AdapterInputFeatureGroup::PriorMemory
                    | AdapterInputFeatureGroup::StyleBlend
                    | AdapterInputFeatureGroup::CalibrationPrior
            )
        })
        .collect::<Vec<_>>();
    let mut leakage_findings = Vec::new();
    if !schema.leakage_policy.forbid_target_labels {
        leakage_findings.push("target labels must be forbidden from adapter input".to_string());
    }
    if !schema.leakage_policy.forbid_outcome_labels {
        leakage_findings.push("outcome labels must be forbidden from adapter input".to_string());
    }
    if !schema.leakage_policy.forbid_chairman_labels {
        leakage_findings.push("chairman labels must be forbidden from adapter input".to_string());
    }
    if !schema.leakage_policy.forbid_risk_veto_labels {
        leakage_findings.push("risk-veto labels must be forbidden from adapter input".to_string());
    }
    if !schema.leakage_policy.forbid_broker_order_account {
        leakage_findings
            .push("broker/order/account fields must be forbidden from adapter input".to_string());
    }
    let mut dimension_warnings = Vec::new();
    if !matches!(
        schema.sequence_len_policy,
        AdapterSequenceLenPolicy::FixedWindow
    ) {
        dimension_warnings.push("adapter input schema must use fixed sequence window".to_string());
    }
    if !matches!(
        schema.feature_dim_policy,
        AdapterFeatureDimPolicy::PositiveOnly
    ) {
        dimension_warnings
            .push("adapter input feature dim policy must remain positive-only".to_string());
    }
    if !matches!(
        schema.temporal_order_policy,
        AdapterTemporalOrderPolicy::PreDecisionOnly
    ) {
        leakage_findings
            .push("adapter input temporal ordering must remain pre-decision only".to_string());
    }
    let valid = missing_required_groups.is_empty()
        && forbidden_groups.is_empty()
        && leakage_findings.is_empty();
    AdapterInputSchemaValidationResult {
        schema_id: schema.schema_id.clone(),
        valid,
        missing_required_groups,
        forbidden_groups,
        leakage_findings,
        dimension_warnings: dimension_warnings.clone(),
        validation_status: if !valid {
            AdapterSchemaValidationStatus::Invalid
        } else if dimension_warnings.is_empty() {
            AdapterSchemaValidationStatus::Valid
        } else {
            AdapterSchemaValidationStatus::ValidWithWarnings
        },
        paper_only: true,
    }
}

fn training_target_head_from_output_group(group: AdapterOutputHeadGroup) -> TrainingTargetHead {
    match group {
        AdapterOutputHeadGroup::Stance => TrainingTargetHead::Stance,
        AdapterOutputHeadGroup::ConfidenceCalibration => TrainingTargetHead::ConfidenceCalibration,
        AdapterOutputHeadGroup::Risk => TrainingTargetHead::Risk,
        AdapterOutputHeadGroup::EvidenceNeed => TrainingTargetHead::EvidenceNeed,
        AdapterOutputHeadGroup::Uncertainty => TrainingTargetHead::Uncertainty,
        AdapterOutputHeadGroup::ExpectedReturnHint => TrainingTargetHead::ExpectedReturnHint,
    }
}

pub fn default_adapter_output_schema_v1() -> AdapterOutputSchemaV1 {
    let enabled_heads = vec![
        AdapterOutputHeadGroup::Stance,
        AdapterOutputHeadGroup::ConfidenceCalibration,
        AdapterOutputHeadGroup::Risk,
        AdapterOutputHeadGroup::EvidenceNeed,
        AdapterOutputHeadGroup::Uncertainty,
        AdapterOutputHeadGroup::ExpectedReturnHint,
    ];
    let mut output_dim_by_head = std::collections::BTreeMap::new();
    let mut output_kind_by_head = std::collections::BTreeMap::new();
    for head in &enabled_heads {
        let spec = head_shape_spec(training_target_head_from_output_group(*head));
        output_dim_by_head.insert(*head, spec.expected_dim);
        output_kind_by_head.insert(*head, spec.output_kind);
    }
    AdapterOutputSchemaV1 {
        schema_id: "adapter-output-schema-v1".to_string(),
        version: AdapterOutputSchemaVersion::V1,
        enabled_heads,
        required_heads: vec![
            AdapterOutputHeadGroup::Stance,
            AdapterOutputHeadGroup::ConfidenceCalibration,
            AdapterOutputHeadGroup::Risk,
            AdapterOutputHeadGroup::EvidenceNeed,
        ],
        optional_heads: vec![
            AdapterOutputHeadGroup::Uncertainty,
            AdapterOutputHeadGroup::ExpectedReturnHint,
        ],
        output_dim_by_head,
        output_kind_by_head,
        value_policy: AdapterOutputValuePolicy::ShapeOnlyNoValues,
        paper_only: true,
    }
}

pub fn validate_adapter_output_schema_v1(
    schema: &AdapterOutputSchemaV1,
) -> AdapterOutputSchemaValidationResult {
    let missing_required_heads = schema
        .required_heads
        .iter()
        .copied()
        .filter(|head| !schema.enabled_heads.contains(head))
        .collect::<Vec<_>>();
    let invalid_head_dims = schema
        .enabled_heads
        .iter()
        .filter_map(
            |head| match schema.output_dim_by_head.get(head).copied().unwrap_or(0) {
                0 => Some(format!("{head:?} output dim must be positive")),
                _ => None,
            },
        )
        .collect::<Vec<_>>();
    let mut value_policy_violations = Vec::new();
    if !matches!(
        schema.value_policy,
        AdapterOutputValuePolicy::ShapeOnlyNoValues
    ) {
        value_policy_violations
            .push("adapter output schema must remain shape-only with no values".to_string());
    }
    let valid = missing_required_heads.is_empty()
        && invalid_head_dims.is_empty()
        && value_policy_violations.is_empty();
    AdapterOutputSchemaValidationResult {
        schema_id: schema.schema_id.clone(),
        valid,
        missing_required_heads,
        invalid_head_dims,
        value_policy_violations,
        validation_status: if valid {
            AdapterSchemaValidationStatus::Valid
        } else {
            AdapterSchemaValidationStatus::Invalid
        },
        paper_only: true,
    }
}

