fn normalize_member_alias(raw_member_id: &str) -> String {
    raw_member_id.trim().to_ascii_lowercase()
}

fn resolve_canonical_member_id_with_map(
    canonical_map: &CanonicalMemberIdMap,
    raw_member_id: &str,
) -> Option<String> {
    let normalized = normalize_member_alias(raw_member_id);
    canonical_map.entries.iter().find_map(|entry| {
        let accepted = std::iter::once(entry.canonical_member_id.as_str())
            .chain(std::iter::once(entry.display_name.as_str()))
            .chain(entry.accepted_aliases.iter().map(|alias| alias.as_str()))
            .any(|alias| normalize_member_alias(alias) == normalized);
        let rejected = entry
            .rejected_aliases
            .iter()
            .any(|alias| normalize_member_alias(alias) == normalized);
        if accepted && !rejected {
            Some(entry.canonical_member_id.clone())
        } else {
            None
        }
    })
}

fn canonical_member_entry_for_id<'a>(
    canonical_map: &'a CanonicalMemberIdMap,
    canonical_member_id: &str,
) -> Option<&'a CanonicalMemberIdEntry> {
    canonical_map
        .entries
        .iter()
        .find(|entry| entry.canonical_member_id == canonical_member_id)
}

pub fn resolve_canonical_member_id(raw_member_id: &str) -> Option<String> {
    resolve_canonical_member_id_with_map(&default_three_member_canonical_id_map(), raw_member_id)
}

pub fn validate_member_id_mapping(
    raw_member_id: &str,
    expected_role: IndependentMemberRole,
) -> MemberIdMappingValidationResult {
    let canonical_map = default_three_member_canonical_id_map();
    let canonical_member_id = resolve_canonical_member_id_with_map(&canonical_map, raw_member_id);
    let mut violations = Vec::new();
    if let Some(ref canonical_member_id) = canonical_member_id {
        if canonical_member_entry_for_id(&canonical_map, canonical_member_id)
            .map(|entry| entry.role != expected_role)
            .unwrap_or(true)
        {
            violations.push("member alias resolved to unexpected role".to_string());
        }
    } else {
        violations.push("unknown member alias rejected".to_string());
    }
    MemberIdMappingValidationResult {
        raw_member_id: raw_member_id.to_string(),
        canonical_member_id,
        valid: violations.is_empty(),
        validation_status: if violations.is_empty() {
            MemberIdMappingStatus::Valid
        } else {
            MemberIdMappingStatus::Invalid
        },
        violations,
        paper_only: true,
    }
}

