pub fn build_member_learning_data_contract_for_profile(
    profile: &MemberSmartCoreAdapterProfile,
    input_schema: &AdapterInputSchemaV1,
    output_schema: &AdapterOutputSchemaV1,
) -> MemberLearningDataContractV1 {
    let canonical_member_id = resolve_canonical_member_id(&profile.member_id)
        .unwrap_or_else(|| profile.member_id.clone());
    MemberLearningDataContractV1 {
        contract_id: format!("{}-learning-data-contract-v1", canonical_member_id),
        member_id: profile.member_id.clone(),
        canonical_member_id,
        role: profile.role,
        allowed_market_scopes: all_market_scopes(),
        adapter_input_schema_id: input_schema.schema_id.clone(),
        adapter_output_schema_id: output_schema.schema_id.clone(),
        allowed_training_splits: vec![
            TrainingBatchSplit::Train,
            TrainingBatchSplit::Validation,
            TrainingBatchSplit::Test,
        ],
        min_examples_required: 1,
        allow_mixed_member_batches: false,
        require_validated_labels: true,
        forbid_review_required_labels: true,
        forbid_simulated_fixture_labels: true,
        forbid_broker_order_account: true,
        forbid_live_inference: true,
        paper_only: true,
    }
}

pub fn build_member_learning_data_contracts_for_registry(
    registry: &SmartCoreAdapterRegistry,
    input_schema: &AdapterInputSchemaV1,
    output_schema: &AdapterOutputSchemaV1,
) -> Vec<MemberLearningDataContractV1> {
    registry
        .profiles
        .iter()
        .map(|profile| {
            build_member_learning_data_contract_for_profile(profile, input_schema, output_schema)
        })
        .collect()
}

fn contains_forbidden_account_terms(value: &str) -> bool {
    let lower = value.to_ascii_lowercase();
    lower.contains("broker")
        || lower.contains("order")
        || lower.contains("account")
        || lower.contains("live trade")
}

fn contains_forbidden_adapter_input_terms(value: &str) -> bool {
    let lower = value.to_ascii_lowercase();
    lower.contains("future outcome")
        || lower.contains("outcome label")
        || lower.contains("target label")
        || lower.contains("learning_label")
        || lower.contains("chairman")
        || lower.contains("risk_veto")
        || lower.contains("riskveto")
}

fn example_has_forbidden_adapter_input_leakage(example: &TrainingCandidateExample) -> bool {
    contains_forbidden_adapter_input_terms(&example.sanitized_input_features.market_data_summary)
        || contains_forbidden_adapter_input_terms(&example.sanitized_input_features.news_summary)
        || example
            .sanitized_input_features
            .owner_pre_decision_context
            .as_deref()
            .map(contains_forbidden_adapter_input_terms)
            .unwrap_or(false)
        || example
            .sanitized_input_features
            .prior_member_memory_summary
            .as_deref()
            .map(contains_forbidden_adapter_input_terms)
            .unwrap_or(false)
        || example
            .sanitized_input_features
            .prior_style_blend_summary
            .as_deref()
            .map(contains_forbidden_adapter_input_terms)
            .unwrap_or(false)
        || example
            .sanitized_input_features
            .prior_calibration_summary
            .as_deref()
            .map(contains_forbidden_adapter_input_terms)
            .unwrap_or(false)
        || example
            .sanitized_input_features
            .feature_safety_notes
            .iter()
            .any(|note| contains_forbidden_adapter_input_terms(note))
}

pub fn validate_member_learning_data_contract(
    contract: &MemberLearningDataContractV1,
    dataset: &TrainingCandidateDataset,
    split: &TrainingSplitResult,
    adapter_profile: &MemberSmartCoreAdapterProfile,
) -> MemberLearningDataContractValidationResult {
    let canonical_map = default_three_member_canonical_id_map();
    let matching_examples = dataset
        .examples
        .iter()
        .filter(|example| {
            resolve_canonical_member_id_with_map(&canonical_map, &example.member_id).as_deref()
                == Some(contract.canonical_member_id.as_str())
        })
        .collect::<Vec<_>>();
    let example_ids = matching_examples
        .iter()
        .map(|example| example.training_example_id.clone())
        .collect::<std::collections::BTreeSet<_>>();
    let mut split_coverage = Vec::new();
    if split.train_ids.iter().any(|id| example_ids.contains(id)) {
        split_coverage.push(TrainingBatchSplit::Train);
    }
    if split
        .validation_ids
        .iter()
        .any(|id| example_ids.contains(id))
    {
        split_coverage.push(TrainingBatchSplit::Validation);
    }
    if split.test_ids.iter().any(|id| example_ids.contains(id)) {
        split_coverage.push(TrainingBatchSplit::Test);
    }
    let mut label_source_violations = Vec::new();
    for example in &matching_examples {
        if contract.require_validated_labels
            && !matches!(
                example.label_source,
                ReplayLabelSource::ValidatedPaperLabel | ReplayLabelSource::ValidatedBacktestLabel
            )
        {
            label_source_violations.push(format!(
                "{} uses non-validated label source {:?}",
                example.training_example_id, example.label_source
            ));
        }
        if contract.forbid_review_required_labels
            && (matches!(example.label_source, ReplayLabelSource::ReviewRequired)
                || matches!(
                    example.label_confidence,
                    ReplayLabelConfidence::ReviewRequired
                ))
        {
            label_source_violations.push(format!(
                "{} includes review-required label",
                example.training_example_id
            ));
        }
        if contract.forbid_simulated_fixture_labels
            && matches!(example.label_source, ReplayLabelSource::SimulatedFixture)
        {
            label_source_violations.push(format!(
                "{} includes simulated fixture label",
                example.training_example_id
            ));
        }
        if contract.forbid_broker_order_account
            && (contains_forbidden_account_terms(
                &example.sanitized_input_features.market_data_summary,
            ) || contains_forbidden_account_terms(
                &example.sanitized_input_features.news_summary,
            ) || example
                .sanitized_input_features
                .owner_pre_decision_context
                .as_deref()
                .map(contains_forbidden_account_terms)
                .unwrap_or(false))
        {
            label_source_violations.push(format!(
                "{} includes forbidden broker/order/account text",
                example.training_example_id
            ));
        }
    }
    let mut schema_violations = Vec::new();
    if contract.adapter_input_schema_id.is_empty() || contract.adapter_output_schema_id.is_empty() {
        schema_violations.push("member learning contract must reference schema ids".to_string());
    }
    if !matches!(
        adapter_profile.adapter_status,
        SmartCoreV2AdapterStatus::ShapeOnly
    ) {
        schema_violations.push("adapter profile must remain shape-only".to_string());
    }
    for example in &matching_examples {
        if example_has_forbidden_adapter_input_leakage(example) {
            schema_violations.push(format!(
                "{} includes forbidden target/outcome/chairman/risk-veto input leakage",
                example.training_example_id
            ));
        }
    }
    let mut member_mapping_violations = Vec::new();
    let canonical_profile_member_id = resolve_canonical_member_id(&adapter_profile.member_id)
        .unwrap_or_else(|| adapter_profile.member_id.clone());
    if canonical_profile_member_id != contract.canonical_member_id {
        member_mapping_violations
            .push("adapter profile/member contract canonical id mismatch".to_string());
    }
    if !validate_member_id_mapping(&contract.member_id, contract.role).valid {
        member_mapping_violations.push("member id mapping validation failed".to_string());
    }
    let validation_status = if !label_source_violations.is_empty()
        || !schema_violations.is_empty()
        || !member_mapping_violations.is_empty()
    {
        MemberLearningDataContractValidationStatus::Invalid
    } else if matching_examples.len() < contract.min_examples_required {
        MemberLearningDataContractValidationStatus::ValidWithWarnings
    } else {
        MemberLearningDataContractValidationStatus::Valid
    };
    MemberLearningDataContractValidationResult {
        member_id: contract.canonical_member_id.clone(),
        valid: !matches!(
            validation_status,
            MemberLearningDataContractValidationStatus::Invalid
        ),
        example_count: matching_examples.len(),
        split_coverage,
        label_source_violations,
        schema_violations,
        member_mapping_violations,
        validation_status,
        paper_only: true,
    }
}

pub fn summarize_member_learning_data_contracts(
    results: &[MemberLearningDataContractValidationResult],
) -> MemberLearningDataContractSummary {
    let valid_member_count = results
        .iter()
        .filter(|result| {
            matches!(
                result.validation_status,
                MemberLearningDataContractValidationStatus::Valid
                    | MemberLearningDataContractValidationStatus::ValidWithWarnings
            )
        })
        .count();
    let invalid_member_count = results.len().saturating_sub(valid_member_count);
    let warning_count = results
        .iter()
        .filter(|result| {
            matches!(
                result.validation_status,
                MemberLearningDataContractValidationStatus::ValidWithWarnings
            )
        })
        .count();
    MemberLearningDataContractSummary {
        summary_id: "member-learning-data-contract-summary".to_string(),
        member_count: results.len(),
        valid_member_count,
        invalid_member_count,
        warning_count,
        member_results: results.to_vec(),
        status: if invalid_member_count > 0 {
            MemberLearningDataContractSummaryStatus::Invalid
        } else if warning_count > 0 {
            MemberLearningDataContractSummaryStatus::ValidWithWarnings
        } else {
            MemberLearningDataContractSummaryStatus::Valid
        },
        paper_only: true,
    }
}

fn build_training_candidate_dataset_from_batch(
    batch: &SmartCoreV2TrainingBatch,
) -> TrainingCandidateDataset {
    let examples = batch
        .feature_rows
        .iter()
        .zip(batch.target_rows.iter())
        .enumerate()
        .map(
            |(index, (feature_row, target_row))| TrainingCandidateExample {
                training_example_id: batch
                    .example_ids
                    .get(index)
                    .cloned()
                    .unwrap_or_else(|| format!("{}-example-{}", batch.batch_id, index + 1)),
                replay_id: feature_row.replay_id.clone(),
                member_id: feature_row.member_id.clone(),
                symbol: feature_row.symbol.clone(),
                market_scope: feature_row.market_scope,
                sanitized_input_features: SanitizedReplayInputFeatures {
                    market_data_summary: feature_row.market_features.join(" "),
                    news_summary: feature_row.news_features.join(" "),
                    owner_pre_decision_context: feature_row
                        .owner_context_features
                        .as_ref()
                        .map(|values| values.join(" ")),
                    prior_member_memory_summary: feature_row
                        .prior_memory_features
                        .as_ref()
                        .map(|values| values.join(" ")),
                    prior_style_blend_summary: feature_row
                        .style_features
                        .as_ref()
                        .map(|values| values.join(" ")),
                    prior_calibration_summary: feature_row
                        .calibration_features
                        .as_ref()
                        .map(|values| values.join(" ")),
                    feature_safety_notes: feature_row.feature_safety_notes.clone(),
                    paper_only: true,
                },
                target_labels: ReplayTargetLabels {
                    stance_target: target_row.stance_target,
                    confidence_calibration_target: target_row.confidence_target,
                    risk_label: target_row.risk_target.clone(),
                    evidence_label: target_row.evidence_target.clone(),
                    outcome_label: target_row.outcome_label,
                    attribution_label: target_row.attribution_label,
                    label_source: target_row.label_source,
                    label_confidence: target_row.label_confidence,
                    paper_only: true,
                },
                label_source: target_row.label_source,
                label_confidence: target_row.label_confidence,
                sample_weight: target_row.sample_weight,
                inclusion_reason: format!("synthetic-from-{}", batch.batch_id),
                paper_only: true,
            },
        )
        .collect::<Vec<_>>();
    let member_count = examples
        .iter()
        .map(|example| example.member_id.as_str())
        .collect::<std::collections::BTreeSet<_>>()
        .len();
    let symbol_count = examples
        .iter()
        .map(|example| example.symbol.as_str())
        .collect::<std::collections::BTreeSet<_>>()
        .len();
    let market_scope_count = examples
        .iter()
        .map(|example| example.market_scope)
        .collect::<std::collections::BTreeSet<_>>()
        .len();
    let mut label_source_distribution = std::collections::BTreeMap::new();
    let mut confidence_distribution = std::collections::BTreeMap::new();
    for example in &examples {
        *label_source_distribution
            .entry(format!("{:?}", example.label_source))
            .or_insert(0usize) += 1;
        *confidence_distribution
            .entry(format!("{:?}", example.label_confidence))
            .or_insert(0usize) += 1;
    }
    TrainingCandidateDataset {
        dataset_id: format!("{}-synthetic-dataset", batch.batch_id),
        source_validated_dataset_id: format!("{}-synthetic-source", batch.batch_id),
        example_count: examples.len(),
        member_count,
        symbol_count,
        market_scope_count,
        label_source_distribution,
        confidence_distribution,
        examples,
        paper_only: true,
    }
}

fn build_training_split_result_from_batch(batch: &SmartCoreV2TrainingBatch) -> TrainingSplitResult {
    let mut train_ids = Vec::new();
    let mut validation_ids = Vec::new();
    let mut test_ids = Vec::new();
    match batch.split {
        TrainingBatchSplit::Train => train_ids.extend(batch.example_ids.clone()),
        TrainingBatchSplit::Validation => validation_ids.extend(batch.example_ids.clone()),
        TrainingBatchSplit::Test => test_ids.extend(batch.example_ids.clone()),
        TrainingBatchSplit::All => train_ids.extend(batch.example_ids.clone()),
    }
    TrainingSplitResult {
        dataset_id: format!("{}-synthetic-split", batch.batch_id),
        train_count: train_ids.len(),
        validation_count: validation_ids.len(),
        test_count: test_ids.len(),
        train_ids,
        validation_ids,
        test_ids,
        split_warnings: Vec::new(),
        paper_only: true,
    }
}

fn synthetic_adapter_safety_guard_from_registry(
    registry: &SmartCoreAdapterRegistry,
) -> AdapterSkeletonSafetyGuard {
    evaluate_adapter_skeleton_safety(&AdapterSkeletonDryRunResult {
        run_id: format!("{}-synthetic-safety", registry.registry_id),
        registry: registry.clone(),
        batch_validations: Vec::new(),
        profile_count: registry.profile_count,
        valid_profile_count: registry.shape_only_count,
        invalid_profile_count: registry
            .profile_count
            .saturating_sub(registry.shape_only_count),
        runtime_ready_count: registry.runtime_ready_count,
        training_ready_count: registry.training_ready_count,
        all_runtime_deferred: registry.runtime_ready_count == 0,
        all_training_deferred: registry.training_ready_count == 0,
        no_forward_method_present: true,
        no_weight_access_present: true,
        no_checkpoint_present: true,
        dry_run_status: AdapterSkeletonDryRunStatus::Passed,
        warnings: Vec::new(),
        paper_only: true,
    })
}

fn validate_batch_against_adapter_contract_v2_with_context(
    batch: &SmartCoreV2TrainingBatch,
    adapter_profile: &MemberSmartCoreAdapterProfile,
    input_schema: &AdapterInputSchemaV1,
    output_schema: &AdapterOutputSchemaV1,
    member_contract: &MemberLearningDataContractV1,
    canonical_map: &CanonicalMemberIdMap,
    dataset: &TrainingCandidateDataset,
    split: &TrainingSplitResult,
) -> BatchAdapterContractValidationV2 {
    let canonical_member_id = resolve_canonical_member_id_with_map(canonical_map, &batch.member_id);
    let row_member_resolution = batch
        .feature_rows
        .iter()
        .map(|row| {
            (
                row.member_id.clone(),
                resolve_canonical_member_id_with_map(canonical_map, &row.member_id),
            )
        })
        .chain(batch.target_rows.iter().map(|row| {
            (
                row.member_id.clone(),
                resolve_canonical_member_id_with_map(canonical_map, &row.member_id),
            )
        }))
        .collect::<Vec<_>>();
    let canonical_batch_member_ids = row_member_resolution
        .iter()
        .filter_map(|(_, canonical)| canonical.clone())
        .collect::<std::collections::BTreeSet<_>>();
    let unknown_row_aliases = row_member_resolution
        .iter()
        .filter_map(|(raw, canonical)| canonical.is_none().then(|| raw.clone()))
        .collect::<std::collections::BTreeSet<_>>();
    let mixed_member_batch = canonical_batch_member_ids.len() > 1;
    let input_schema_result = validate_adapter_input_schema_v1(input_schema);
    let output_schema_result = validate_adapter_output_schema_v1(output_schema);
    let member_contract_result =
        validate_member_learning_data_contract(member_contract, dataset, split, adapter_profile);
    let batch_shape_result = validate_batch_against_adapter_profile(
        batch,
        &TrainingFeatureSchema::default(),
        &TrainingTargetSchema {
            target_heads: output_schema
                .enabled_heads
                .iter()
                .map(|head| training_target_head_from_output_group(*head))
                .collect(),
            ..TrainingTargetSchema::default()
        },
        adapter_profile,
    );
    let canonical_profile_member_id =
        resolve_canonical_member_id_with_map(canonical_map, &adapter_profile.member_id)
            .unwrap_or_else(|| adapter_profile.member_id.clone());
    let unmatched_batch = canonical_member_id.as_deref()
        != Some(canonical_profile_member_id.as_str())
        || canonical_member_id.as_deref() != Some(member_contract.canonical_member_id.as_str());
    let mut warnings = Vec::new();
    warnings.extend(input_schema_result.leakage_findings.clone());
    warnings.extend(output_schema_result.value_policy_violations.clone());
    warnings.extend(member_contract_result.label_source_violations.clone());
    warnings.extend(batch_shape_result.warnings.clone());
    if unmatched_batch {
        warnings.push("batch member id did not resolve to matching adapter profile".to_string());
    }
    if mixed_member_batch {
        warnings.push("mixed member batch rejected by contract validation".to_string());
    }
    if !unknown_row_aliases.is_empty() {
        warnings.push(format!(
            "unknown row member aliases rejected: {}",
            unknown_row_aliases
                .iter()
                .cloned()
                .collect::<Vec<_>>()
                .join(", ")
        ));
    }
    BatchAdapterContractValidationV2 {
        validation_id: format!("{}-adapter-contract-v2", batch.batch_id),
        batch_id: batch.batch_id.clone(),
        raw_member_id: batch.member_id.clone(),
        canonical_member_id,
        adapter_profile_id: Some(adapter_profile.profile_id.clone()),
        input_schema_result,
        output_schema_result,
        member_contract_result: member_contract_result.clone(),
        batch_shape_result: batch_shape_result.clone(),
        unmatched_batch,
        validation_status: if unmatched_batch
            || mixed_member_batch
            || !unknown_row_aliases.is_empty()
            || !member_contract_result.valid
            || !batch_shape_result.output_value_guard.violations.is_empty()
            || matches!(
                batch_shape_result.validation_status,
                AdapterShapeValidationStatus::Invalid
            )
            || matches!(
                member_contract_result.validation_status,
                MemberLearningDataContractValidationStatus::Invalid
            ) {
            AdapterContractValidationStatus::Invalid
        } else if warnings.is_empty() {
            AdapterContractValidationStatus::Valid
        } else {
            AdapterContractValidationStatus::ValidWithWarnings
        },
        warnings,
        paper_only: true,
    }
}

pub fn validate_batch_against_adapter_contract_v2(
    batch: &SmartCoreV2TrainingBatch,
    adapter_profile: &MemberSmartCoreAdapterProfile,
    input_schema: &AdapterInputSchemaV1,
    output_schema: &AdapterOutputSchemaV1,
    member_contract: &MemberLearningDataContractV1,
    canonical_map: &CanonicalMemberIdMap,
) -> BatchAdapterContractValidationV2 {
    let dataset = build_training_candidate_dataset_from_batch(batch);
    let split = build_training_split_result_from_batch(batch);
    validate_batch_against_adapter_contract_v2_with_context(
        batch,
        adapter_profile,
        input_schema,
        output_schema,
        member_contract,
        canonical_map,
        &dataset,
        &split,
    )
}

fn adapter_schema_version_text() -> String {
    "V1".to_string()
}

fn baseline_input_group_dim(
    input_schema: &AdapterInputSchemaV1,
    group: AdapterInputFeatureGroup,
) -> usize {
    usize::from(input_schema.allowed_feature_groups.contains(&group))
}

fn build_adapter_contract_baseline_input_shape(
    member_id: &str,
    batch_id: &str,
    input_schema: &AdapterInputSchemaV1,
) -> SmartCoreV2AdapterInputShape {
    let market_feature_dim =
        baseline_input_group_dim(input_schema, AdapterInputFeatureGroup::Market);
    let news_feature_dim = baseline_input_group_dim(input_schema, AdapterInputFeatureGroup::News);
    let owner_context_dim =
        baseline_input_group_dim(input_schema, AdapterInputFeatureGroup::OwnerContext);
    let memory_feature_dim =
        baseline_input_group_dim(input_schema, AdapterInputFeatureGroup::PriorMemory);
    let style_feature_dim =
        baseline_input_group_dim(input_schema, AdapterInputFeatureGroup::StyleBlend);
    let calibration_feature_dim =
        baseline_input_group_dim(input_schema, AdapterInputFeatureGroup::CalibrationPrior);
    SmartCoreV2AdapterInputShape {
        shape_id: format!("{member_id}-adapter-contract-baseline-input-shape"),
        member_id: member_id.to_string(),
        batch_id: Some(batch_id.to_string()),
        example_count: 1,
        sequence_len: TrainingFeatureSchema::default().sequence_len_hint.max(1),
        feature_dim: market_feature_dim
            + news_feature_dim
            + owner_context_dim
            + memory_feature_dim
            + style_feature_dim
            + calibration_feature_dim,
        market_feature_dim,
        news_feature_dim,
        owner_context_dim,
        memory_feature_dim,
        style_feature_dim,
        calibration_feature_dim,
        has_news_features: news_feature_dim > 0,
        has_owner_context: owner_context_dim > 0,
        has_prior_memory: memory_feature_dim > 0,
        paper_only: true,
    }
}

fn build_adapter_contract_baseline_output_shape(
    member_id: &str,
    batch_id: &str,
    adapter_profile: &MemberSmartCoreAdapterProfile,
    output_schema: &AdapterOutputSchemaV1,
) -> SmartCoreV2AdapterOutputShape {
    let target_schema = TrainingTargetSchema {
        target_heads: output_schema
            .enabled_heads
            .iter()
            .map(|head| training_target_head_from_output_group(*head))
            .collect(),
        ..TrainingTargetSchema::default()
    };
    let target_contains = |target_head: TrainingTargetHead| {
        target_schema
            .target_heads
            .iter()
            .any(|head| *head == target_head)
    };
    SmartCoreV2AdapterOutputShape {
        shape_id: format!("{member_id}-adapter-contract-baseline-output-shape"),
        member_id: member_id.to_string(),
        batch_id: Some(batch_id.to_string()),
        example_count: 1,
        enabled_heads: adapter_profile
            .head_specs
            .iter()
            .filter(|spec| {
                target_schema
                    .target_heads
                    .iter()
                    .any(|head| adapter_head_kind(*head) == spec.head_kind && spec.output_dim > 0)
            })
            .map(|spec| spec.head_kind)
            .collect(),
        stance_output_dim: head_output_dim_by_kind(
            &adapter_profile.head_specs,
            SmartCoreV2HeadKind::Stance,
        )
        .unwrap_or(0),
        confidence_output_dim: head_output_dim_by_kind(
            &adapter_profile.head_specs,
            SmartCoreV2HeadKind::ConfidenceCalibration,
        )
        .unwrap_or(0),
        risk_output_dim: head_output_dim_by_kind(
            &adapter_profile.head_specs,
            SmartCoreV2HeadKind::Risk,
        )
        .unwrap_or(0),
        evidence_output_dim: head_output_dim_by_kind(
            &adapter_profile.head_specs,
            SmartCoreV2HeadKind::EvidenceNeed,
        )
        .unwrap_or(0),
        uncertainty_output_dim: target_contains(TrainingTargetHead::Uncertainty).then(|| {
            head_output_dim_by_kind(
                &adapter_profile.head_specs,
                SmartCoreV2HeadKind::Uncertainty,
            )
            .unwrap_or(0)
        }),
        expected_return_output_dim: target_contains(TrainingTargetHead::ExpectedReturnHint).then(
            || {
                head_output_dim_by_kind(
                    &adapter_profile.head_specs,
                    SmartCoreV2HeadKind::ExpectedReturnHint,
                )
                .unwrap_or(0)
            },
        ),
        paper_only: true,
    }
}

pub fn build_adapter_shape_golden_snapshots(
    _batches: &[SmartCoreV2TrainingBatch],
    registry: &SmartCoreAdapterRegistry,
    schemas: &AdapterContractSchemasV1,
    contracts: &[MemberLearningDataContractV1],
) -> AdapterShapeGoldenSnapshotSet {
    let canonical_map = default_three_member_canonical_id_map();
    let mut snapshots = registry
        .profiles
        .iter()
        .filter_map(|profile| {
            let canonical_member_id =
                resolve_canonical_member_id_with_map(&canonical_map, &profile.member_id)?;
            let contract = contracts
                .iter()
                .find(|contract| contract.canonical_member_id == canonical_member_id)?;
            let batch_id = format!("{canonical_member_id}-contract-batch");
            Some(AdapterShapeGoldenSnapshot {
                snapshot_id: format!("{canonical_member_id}::contract-baseline"),
                schema_version: adapter_schema_version_text(),
                member_id: canonical_member_id.clone(),
                batch_id: batch_id.clone(),
                input_shape: build_adapter_contract_baseline_input_shape(
                    &canonical_member_id,
                    &batch_id,
                    &schemas.input_schema,
                ),
                output_shape: build_adapter_contract_baseline_output_shape(
                    &canonical_member_id,
                    &batch_id,
                    profile,
                    &schemas.output_schema,
                ),
                member_contract_summary: format!("{}::contract-locked", contract.contract_id),
                paper_only: true,
            })
        })
        .collect::<Vec<_>>();
    snapshots.sort_by(|left, right| {
        left.member_id
            .cmp(&right.member_id)
            .then(left.batch_id.cmp(&right.batch_id))
            .then(left.snapshot_id.cmp(&right.snapshot_id))
    });
    AdapterShapeGoldenSnapshotSet {
        snapshot_set_id: "adapter-shape-golden-baseline-snapshot-set".to_string(),
        snapshot_count: snapshots.len(),
        snapshots,
        schema_version: adapter_schema_version_text(),
        paper_only: true,
    }
}

pub fn compare_adapter_shape_golden_snapshots(
    current: &AdapterShapeGoldenSnapshotSet,
    expected: &AdapterShapeGoldenSnapshotSet,
) -> AdapterShapeGoldenSnapshotDiff {
    let current_map = current
        .snapshots
        .iter()
        .map(|snapshot| (snapshot.snapshot_id.clone(), snapshot))
        .collect::<std::collections::BTreeMap<_, _>>();
    let expected_map = expected
        .snapshots
        .iter()
        .map(|snapshot| (snapshot.snapshot_id.clone(), snapshot))
        .collect::<std::collections::BTreeMap<_, _>>();
    let added_snapshots = current_map
        .keys()
        .filter(|id| !expected_map.contains_key(*id))
        .cloned()
        .collect::<Vec<_>>();
    let removed_snapshots = expected_map
        .keys()
        .filter(|id| !current_map.contains_key(*id))
        .cloned()
        .collect::<Vec<_>>();
    let mut changed_snapshots = Vec::new();
    let mut dimension_changes = Vec::new();
    let mut schema_version_changes = Vec::new();
    for (snapshot_id, current_snapshot) in &current_map {
        if let Some(expected_snapshot) = expected_map.get(snapshot_id) {
            if current_snapshot != expected_snapshot {
                changed_snapshots.push(snapshot_id.clone());
            }
            if current_snapshot.input_shape.feature_dim != expected_snapshot.input_shape.feature_dim
                || current_snapshot.output_shape.stance_output_dim
                    != expected_snapshot.output_shape.stance_output_dim
                || current_snapshot.output_shape.confidence_output_dim
                    != expected_snapshot.output_shape.confidence_output_dim
                || current_snapshot.output_shape.risk_output_dim
                    != expected_snapshot.output_shape.risk_output_dim
                || current_snapshot.output_shape.evidence_output_dim
                    != expected_snapshot.output_shape.evidence_output_dim
                || current_snapshot.output_shape.uncertainty_output_dim
                    != expected_snapshot.output_shape.uncertainty_output_dim
                || current_snapshot.output_shape.expected_return_output_dim
                    != expected_snapshot.output_shape.expected_return_output_dim
            {
                dimension_changes.push(snapshot_id.clone());
            }
            if current_snapshot.schema_version != expected_snapshot.schema_version {
                schema_version_changes.push(format!(
                    "{}: {} -> {}",
                    snapshot_id, expected_snapshot.schema_version, current_snapshot.schema_version
                ));
            }
        }
    }
    if current.schema_version != expected.schema_version {
        schema_version_changes.push(format!(
            "{} -> {}",
            expected.schema_version, current.schema_version
        ));
    }
    AdapterShapeGoldenSnapshotDiff {
        diff_status: if added_snapshots.is_empty()
            && removed_snapshots.is_empty()
            && changed_snapshots.is_empty()
            && schema_version_changes.is_empty()
        {
            AdapterShapeGoldenSnapshotDiffStatus::NoDiff
        } else {
            AdapterShapeGoldenSnapshotDiffStatus::ExpectedDiff
        },
        added_snapshots,
        removed_snapshots,
        changed_snapshots,
        dimension_changes,
        schema_version_changes,
        paper_only: true,
    }
}

fn input_group_diff_messages(
    snapshot_id: &str,
    current: &SmartCoreV2AdapterInputShape,
    expected: &SmartCoreV2AdapterInputShape,
) -> Vec<String> {
    let mut diffs = Vec::new();
    for (label, left, right) in [
        (
            "market_feature_dim",
            current.market_feature_dim,
            expected.market_feature_dim,
        ),
        (
            "news_feature_dim",
            current.news_feature_dim,
            expected.news_feature_dim,
        ),
        (
            "owner_context_dim",
            current.owner_context_dim,
            expected.owner_context_dim,
        ),
        (
            "memory_feature_dim",
            current.memory_feature_dim,
            expected.memory_feature_dim,
        ),
        (
            "style_feature_dim",
            current.style_feature_dim,
            expected.style_feature_dim,
        ),
        (
            "calibration_feature_dim",
            current.calibration_feature_dim,
            expected.calibration_feature_dim,
        ),
    ] {
        if left != right {
            diffs.push(format!("{snapshot_id}: {label} {right} -> {left}"));
        }
    }
    for (label, left, right) in [
        (
            "has_news_features",
            current.has_news_features,
            expected.has_news_features,
        ),
        (
            "has_owner_context",
            current.has_owner_context,
            expected.has_owner_context,
        ),
        (
            "has_prior_memory",
            current.has_prior_memory,
            expected.has_prior_memory,
        ),
    ] {
        if left != right {
            diffs.push(format!("{snapshot_id}: {label} {right} -> {left}"));
        }
    }
    diffs
}

fn output_head_diff_messages(
    snapshot_id: &str,
    current: &SmartCoreV2AdapterOutputShape,
    expected: &SmartCoreV2AdapterOutputShape,
) -> Vec<String> {
    if current.enabled_heads == expected.enabled_heads {
        Vec::new()
    } else {
        vec![format!(
            "{snapshot_id}: {:?} -> {:?}",
            expected.enabled_heads, current.enabled_heads
        )]
    }
}

fn schema_drift_status_from_baseline_comparison(
    comparison: &AdapterGoldenBaselineComparisonResult,
) -> AdapterSchemaDriftStatus {
    match comparison.diff_status {
        AdapterGoldenBaselineDiffStatus::NoDiff => AdapterSchemaDriftStatus::NoDrift,
        AdapterGoldenBaselineDiffStatus::ExpectedVersionedDiff => {
            AdapterSchemaDriftStatus::DriftAllowedWithVersionBump
        }
        AdapterGoldenBaselineDiffStatus::UnexpectedDrift => {
            AdapterSchemaDriftStatus::UnexpectedDrift
        }
        AdapterGoldenBaselineDiffStatus::MissingBaseline => {
            AdapterSchemaDriftStatus::MissingBaseline
        }
    }
}

fn summarize_batch_contract_status(
    validations: &[BatchAdapterContractValidationV2],
) -> AdapterContractLockBatchStatus {
    if validations.iter().any(|validation| {
        matches!(
            validation.validation_status,
            AdapterContractValidationStatus::Invalid
        )
    }) {
        AdapterContractLockBatchStatus::Invalid
    } else if validations.iter().any(|validation| {
        matches!(
            validation.validation_status,
            AdapterContractValidationStatus::ValidWithWarnings
        )
    }) {
        AdapterContractLockBatchStatus::ValidWithWarnings
    } else {
        AdapterContractLockBatchStatus::Valid
    }
}

fn validate_baseline_snapshot_text(text: &str) -> Result<(), String> {
    let lowered = text.to_ascii_lowercase();
    for forbidden in [
        "logit",
        "probab",
        "prediction",
        "model score",
        "model_score",
        "broker",
        "order",
        "account",
        "checkpoint",
        "runtime_ready",
        "training_ready",
        "runtimeready",
        "trainingready",
    ] {
        if lowered.contains(forbidden) {
            return Err(format!(
                "adapter golden baseline contains forbidden term: {forbidden}"
            ));
        }
    }
    Ok(())
}

pub fn validate_adapter_golden_snapshot_baseline(
    baseline: &AdapterGoldenSnapshotBaselineFile,
) -> Result<(), String> {
    if !baseline.paper_only
        || !baseline.snapshot_set.paper_only
        || !baseline.baseline_policy.paper_only
    {
        return Err("adapter golden baseline must remain paper-only".to_string());
    }
    if baseline.snapshot_set.snapshots.is_empty() || baseline.snapshot_set.snapshot_count == 0 {
        return Err("adapter golden baseline snapshot_set must be non-empty".to_string());
    }
    if baseline.snapshot_set.snapshot_count != baseline.snapshot_set.snapshots.len() {
        return Err("adapter golden baseline snapshot_count mismatch".to_string());
    }
    let expected_schema_version = adapter_schema_version_text();
    if !baseline.baseline_policy.allow_schema_version_bump
        && baseline.schema_version != expected_schema_version
    {
        return Err(
            "adapter golden baseline schema_version must match current adapter schema".to_string(),
        );
    }
    if baseline.snapshot_set.schema_version != baseline.schema_version {
        return Err("adapter golden baseline snapshot_set schema_version mismatch".to_string());
    }
    let mut seen_snapshot_ids = std::collections::BTreeSet::new();
    for snapshot in &baseline.snapshot_set.snapshots {
        if !seen_snapshot_ids.insert(snapshot.snapshot_id.clone()) {
            return Err(format!(
                "adapter golden baseline snapshot id must be unique: {}",
                snapshot.snapshot_id
            ));
        }
        if !snapshot.paper_only
            || !snapshot.input_shape.paper_only
            || !snapshot.output_shape.paper_only
        {
            return Err("adapter golden baseline snapshots must remain paper-only".to_string());
        }
        if snapshot.input_shape.example_count == 0 || snapshot.output_shape.example_count == 0 {
            return Err(
                "adapter golden baseline snapshots must expose positive example counts".to_string(),
            );
        }
        if snapshot.schema_version != baseline.schema_version
            && !baseline.baseline_policy.allow_schema_version_bump
        {
            return Err(format!(
                "adapter golden baseline snapshot schema_version mismatch: {}",
                snapshot.snapshot_id
            ));
        }
        if snapshot.output_shape.enabled_heads.is_empty() {
            return Err(format!(
                "adapter golden baseline snapshot has no output heads: {}",
                snapshot.snapshot_id
            ));
        }
        validate_baseline_snapshot_text(
            &serde_json::to_string(snapshot).map_err(|err| err.to_string())?,
        )?;
    }
    validate_baseline_snapshot_text(
        &serde_json::to_string(baseline).map_err(|err| err.to_string())?,
    )?;
    Ok(())
}

pub fn load_adapter_golden_snapshot_baseline_from_local_json(
    path: &Path,
) -> Result<AdapterGoldenSnapshotBaselineFile, String> {
    validate_local_json_path(path, "adapter golden baseline path")?;
    let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
    let baseline: AdapterGoldenSnapshotBaselineFile =
        serde_json::from_str(&text).map_err(|err| err.to_string())?;
    validate_adapter_golden_snapshot_baseline(&baseline)?;
    Ok(baseline)
}

pub fn save_adapter_golden_snapshot_baseline_to_local_json(
    path: &Path,
    baseline: &AdapterGoldenSnapshotBaselineFile,
) -> Result<(), String> {
    validate_local_json_path(path, "adapter golden baseline path")?;
    validate_adapter_golden_snapshot_baseline(baseline)?;
    write_safe_json(path, baseline)
}

pub fn bootstrap_adapter_golden_baseline(
    config: &AdapterGoldenBaselineBootstrapConfig,
) -> Result<AdapterGoldenBaselineBootstrapResult, String> {
    if !config.paper_only || !config.baseline_policy.paper_only {
        return Err("adapter golden baseline bootstrap must remain paper-only".to_string());
    }
    let output_path = Path::new(&config.output_baseline_path);
    validate_local_json_path(output_path, "adapter golden baseline bootstrap output path")?;
    if config.require_clean_contract_lock && config.source_snapshot_set.snapshots.is_empty() {
        return Ok(AdapterGoldenBaselineBootstrapResult {
            bootstrap_id: config.bootstrap_id.clone(),
            wrote_baseline: false,
            output_path: config.output_baseline_path.clone(),
            snapshot_count: config.source_snapshot_set.snapshot_count,
            validation_status: AdapterGoldenBaselineValidationStatus::Invalid,
            bootstrap_status: AdapterGoldenBaselineBootstrapStatus::Blocked,
            warnings: vec![
                "baseline bootstrap requires a non-empty contract snapshot set".to_string(),
            ],
            paper_only: true,
        });
    }
    if output_path.exists() && !config.allow_overwrite {
        return Ok(AdapterGoldenBaselineBootstrapResult {
            bootstrap_id: config.bootstrap_id.clone(),
            wrote_baseline: false,
            output_path: config.output_baseline_path.clone(),
            snapshot_count: config.source_snapshot_set.snapshot_count,
            validation_status: AdapterGoldenBaselineValidationStatus::Valid,
            bootstrap_status: AdapterGoldenBaselineBootstrapStatus::SkippedExisting,
            warnings: vec!["baseline bootstrap skipped existing file".to_string()],
            paper_only: true,
        });
    }
    let baseline = AdapterGoldenSnapshotBaselineFile {
        schema_version: config.source_snapshot_set.schema_version.clone(),
        baseline_id: format!("{}-baseline", config.bootstrap_id),
        created_from_run_id: config.created_from_run_id.clone(),
        snapshot_set: config.source_snapshot_set.clone(),
        baseline_policy: config.baseline_policy.clone(),
        paper_only: true,
    };
    let validation_status = if validate_adapter_golden_snapshot_baseline(&baseline).is_ok() {
        AdapterGoldenBaselineValidationStatus::Valid
    } else {
        AdapterGoldenBaselineValidationStatus::Invalid
    };
    if matches!(
        validation_status,
        AdapterGoldenBaselineValidationStatus::Invalid
    ) {
        return Ok(AdapterGoldenBaselineBootstrapResult {
            bootstrap_id: config.bootstrap_id.clone(),
            wrote_baseline: false,
            output_path: config.output_baseline_path.clone(),
            snapshot_count: config.source_snapshot_set.snapshot_count,
            validation_status,
            bootstrap_status: AdapterGoldenBaselineBootstrapStatus::Blocked,
            warnings: vec!["baseline bootstrap validation failed".to_string()],
            paper_only: true,
        });
    }
    save_adapter_golden_snapshot_baseline_to_local_json(output_path, &baseline)?;
    Ok(AdapterGoldenBaselineBootstrapResult {
        bootstrap_id: config.bootstrap_id.clone(),
        wrote_baseline: true,
        output_path: config.output_baseline_path.clone(),
        snapshot_count: config.source_snapshot_set.snapshot_count,
        validation_status,
        bootstrap_status: AdapterGoldenBaselineBootstrapStatus::WroteBaseline,
        warnings: Vec::new(),
        paper_only: true,
    })
}

pub fn compare_current_snapshot_to_expected_baseline(
    current: &AdapterShapeGoldenSnapshotSet,
    expected: Option<&AdapterGoldenSnapshotBaselineFile>,
    policy: &AdapterGoldenBaselinePolicy,
) -> AdapterGoldenBaselineComparisonResult {
    if expected.is_none() {
        return AdapterGoldenBaselineComparisonResult {
            current_baseline_id: None,
            expected_baseline_id: None,
            current_snapshot_count: current.snapshot_count,
            expected_snapshot_count: 0,
            added_snapshot_ids: current
                .snapshots
                .iter()
                .map(|snapshot| snapshot.snapshot_id.clone())
                .collect(),
            removed_snapshot_ids: Vec::new(),
            changed_snapshot_ids: Vec::new(),
            dimension_diffs: Vec::new(),
            member_set_diffs: Vec::new(),
            batch_set_diffs: Vec::new(),
            input_group_diffs: Vec::new(),
            output_head_diffs: Vec::new(),
            schema_version_diffs: Vec::new(),
            diff_status: AdapterGoldenBaselineDiffStatus::MissingBaseline,
            paper_only: true,
        };
    }
    let expected = expected.expect("checked is_some");
    let current_map = current
        .snapshots
        .iter()
        .map(|snapshot| (snapshot.snapshot_id.clone(), snapshot))
        .collect::<std::collections::BTreeMap<_, _>>();
    let expected_map = expected
        .snapshot_set
        .snapshots
        .iter()
        .map(|snapshot| (snapshot.snapshot_id.clone(), snapshot))
        .collect::<std::collections::BTreeMap<_, _>>();
    let added_snapshot_ids = current_map
        .keys()
        .filter(|id| !expected_map.contains_key(*id))
        .cloned()
        .collect::<Vec<_>>();
    let removed_snapshot_ids = expected_map
        .keys()
        .filter(|id| !current_map.contains_key(*id))
        .cloned()
        .collect::<Vec<_>>();
    let mut changed_snapshot_ids = Vec::new();
    let mut dimension_diffs = Vec::new();
    let mut input_group_diffs = Vec::new();
    let mut output_head_diffs = Vec::new();
    let mut schema_version_diffs = Vec::new();
    for (snapshot_id, current_snapshot) in &current_map {
        if let Some(expected_snapshot) = expected_map.get(snapshot_id) {
            if *current_snapshot != *expected_snapshot {
                changed_snapshot_ids.push(snapshot_id.clone());
            }
            if current_snapshot.input_shape.sequence_len
                != expected_snapshot.input_shape.sequence_len
                || current_snapshot.input_shape.feature_dim
                    != expected_snapshot.input_shape.feature_dim
                || current_snapshot.input_shape.example_count
                    != expected_snapshot.input_shape.example_count
                || current_snapshot.output_shape.stance_output_dim
                    != expected_snapshot.output_shape.stance_output_dim
                || current_snapshot.output_shape.confidence_output_dim
                    != expected_snapshot.output_shape.confidence_output_dim
                || current_snapshot.output_shape.risk_output_dim
                    != expected_snapshot.output_shape.risk_output_dim
                || current_snapshot.output_shape.evidence_output_dim
                    != expected_snapshot.output_shape.evidence_output_dim
                || current_snapshot.output_shape.uncertainty_output_dim
                    != expected_snapshot.output_shape.uncertainty_output_dim
                || current_snapshot.output_shape.expected_return_output_dim
                    != expected_snapshot.output_shape.expected_return_output_dim
            {
                dimension_diffs.push(snapshot_id.clone());
            }
            input_group_diffs.extend(input_group_diff_messages(
                snapshot_id,
                &current_snapshot.input_shape,
                &expected_snapshot.input_shape,
            ));
            output_head_diffs.extend(output_head_diff_messages(
                snapshot_id,
                &current_snapshot.output_shape,
                &expected_snapshot.output_shape,
            ));
            if current_snapshot.schema_version != expected_snapshot.schema_version {
                schema_version_diffs.push(format!(
                    "{snapshot_id}: {} -> {}",
                    expected_snapshot.schema_version, current_snapshot.schema_version
                ));
            }
        }
    }
    if current.schema_version != expected.snapshot_set.schema_version {
        schema_version_diffs.push(format!(
            "snapshot-set: {} -> {}",
            expected.snapshot_set.schema_version, current.schema_version
        ));
    }
    if current.schema_version != expected.schema_version {
        schema_version_diffs.push(format!(
            "baseline: {} -> {}",
            expected.schema_version, current.schema_version
        ));
    }
    let current_member_set = current
        .snapshots
        .iter()
        .map(|snapshot| snapshot.member_id.clone())
        .collect::<std::collections::BTreeSet<_>>();
    let expected_member_set = expected
        .snapshot_set
        .snapshots
        .iter()
        .map(|snapshot| snapshot.member_id.clone())
        .collect::<std::collections::BTreeSet<_>>();
    let member_set_diffs = current_member_set
        .symmetric_difference(&expected_member_set)
        .cloned()
        .collect::<Vec<_>>();
    let current_batch_set = current
        .snapshots
        .iter()
        .map(|snapshot| snapshot.batch_id.clone())
        .collect::<std::collections::BTreeSet<_>>();
    let expected_batch_set = expected
        .snapshot_set
        .snapshots
        .iter()
        .map(|snapshot| snapshot.batch_id.clone())
        .collect::<std::collections::BTreeSet<_>>();
    let batch_set_diffs = current_batch_set
        .symmetric_difference(&expected_batch_set)
        .cloned()
        .collect::<Vec<_>>();
    let has_any_diff = !added_snapshot_ids.is_empty()
        || !removed_snapshot_ids.is_empty()
        || !changed_snapshot_ids.is_empty()
        || !dimension_diffs.is_empty()
        || !member_set_diffs.is_empty()
        || !batch_set_diffs.is_empty()
        || !input_group_diffs.is_empty()
        || !output_head_diffs.is_empty()
        || !schema_version_diffs.is_empty();
    let only_versioned_dimension_diff = has_any_diff
        && !schema_version_diffs.is_empty()
        && added_snapshot_ids.is_empty()
        && removed_snapshot_ids.is_empty()
        && member_set_diffs.is_empty()
        && batch_set_diffs.is_empty()
        && input_group_diffs.is_empty()
        && output_head_diffs.is_empty()
        && (dimension_diffs.len() == changed_snapshot_ids.len() || changed_snapshot_ids.is_empty());
    let diff_status = if !has_any_diff {
        AdapterGoldenBaselineDiffStatus::NoDiff
    } else if policy.allow_schema_version_bump && only_versioned_dimension_diff {
        AdapterGoldenBaselineDiffStatus::ExpectedVersionedDiff
    } else {
        AdapterGoldenBaselineDiffStatus::UnexpectedDrift
    };
    AdapterGoldenBaselineComparisonResult {
        current_baseline_id: None,
        expected_baseline_id: Some(expected.baseline_id.clone()),
        current_snapshot_count: current.snapshot_count,
        expected_snapshot_count: expected.snapshot_set.snapshot_count,
        added_snapshot_ids,
        removed_snapshot_ids,
        changed_snapshot_ids,
        dimension_diffs,
        member_set_diffs,
        batch_set_diffs,
        input_group_diffs,
        output_head_diffs,
        schema_version_diffs,
        diff_status,
        paper_only: true,
    }
}

pub fn evaluate_adapter_contract_lock_acceptance(
    lock_result: &AdapterContractLockRunResult,
    baseline_comparison: &AdapterGoldenBaselineComparisonResult,
    policy: &AdapterGoldenBaselinePolicy,
) -> AdapterContractLockAcceptanceGate {
    let batch_contract_status =
        summarize_batch_contract_status(&lock_result.batch_contract_validations);
    let schema_drift_status = schema_drift_status_from_baseline_comparison(baseline_comparison);
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    let has_output_value_violation = !lock_result
        .output_schema_result
        .value_policy_violations
        .is_empty()
        || lock_result
            .batch_contract_validations
            .iter()
            .any(|validation| {
                !validation
                    .batch_shape_result
                    .output_value_guard
                    .violations
                    .is_empty()
            });
    if !lock_result.input_schema_result.valid {
        blockers.push("adapter input schema validation failed".to_string());
    }
    if !lock_result.output_schema_result.valid {
        blockers.push("adapter output schema validation failed".to_string());
    }
    if matches!(
        lock_result.member_contract_summary.status,
        MemberLearningDataContractSummaryStatus::Invalid
    ) {
        blockers.push("member learning data contract validation failed".to_string());
    }
    if matches!(
        batch_contract_status,
        AdapterContractLockBatchStatus::Invalid
    ) {
        blockers.push("batch contract validation failed".to_string());
    } else if matches!(
        batch_contract_status,
        AdapterContractLockBatchStatus::ValidWithWarnings
    ) {
        warnings.push("batch contract validation produced warnings".to_string());
    }
    match baseline_comparison.diff_status {
        AdapterGoldenBaselineDiffStatus::NoDiff => {}
        AdapterGoldenBaselineDiffStatus::ExpectedVersionedDiff => {
            warnings
                .push("adapter baseline accepted with explicit schema version bump".to_string());
        }
        AdapterGoldenBaselineDiffStatus::UnexpectedDrift => {
            blockers.push("unexpected adapter baseline drift detected".to_string());
        }
        AdapterGoldenBaselineDiffStatus::MissingBaseline => {
            if policy.baseline_required && !policy.allow_missing_baseline_bootstrap {
                blockers.push("expected adapter golden baseline is missing".to_string());
            } else {
                warnings.push(
                    "expected adapter golden baseline missing during bootstrap mode".to_string(),
                );
            }
        }
    }
    if !lock_result.adapter_safety_guard.violations.is_empty()
        || !matches!(
            lock_result.adapter_safety_guard.safety_status,
            TrainingSimulationSafetyStatus::Preserved
        )
    {
        blockers.push("adapter safety guard reported a preserved-safety violation".to_string());
    }
    if has_output_value_violation {
        blockers.push("adapter output values were exposed".to_string());
    }
    let gate_status = if blockers
        .iter()
        .any(|blocker| blocker.contains("baseline is missing"))
    {
        AdapterContractLockAcceptanceGateStatus::BlockedByMissingBaseline
    } else if blockers
        .iter()
        .any(|blocker| blocker.contains("unexpected adapter baseline drift"))
    {
        AdapterContractLockAcceptanceGateStatus::BlockedBySchemaDrift
    } else if blockers
        .iter()
        .any(|blocker| blocker.contains("safety guard") || blocker.contains("output values"))
    {
        AdapterContractLockAcceptanceGateStatus::BlockedBySafety
    } else if !blockers.is_empty() {
        AdapterContractLockAcceptanceGateStatus::BlockedByContractViolation
    } else if warnings.is_empty() {
        AdapterContractLockAcceptanceGateStatus::Locked
    } else {
        AdapterContractLockAcceptanceGateStatus::LockedWithWarnings
    };
    AdapterContractLockAcceptanceGate {
        gate_id: format!("{}-acceptance-gate", lock_result.run_id),
        input_schema_status: lock_result.input_schema_result.validation_status,
        output_schema_status: lock_result.output_schema_result.validation_status,
        member_contract_status: lock_result.member_contract_summary.status,
        batch_contract_status,
        golden_baseline_status: baseline_comparison.diff_status,
        schema_drift_status,
        adapter_safety_status: lock_result.adapter_safety_guard.safety_status,
        lock_accepted: blockers.is_empty(),
        gate_status,
        blockers,
        warnings,
        paper_only: true,
    }
}

fn synthetic_safe_adapter_safety_guard() -> AdapterSkeletonSafetyGuard {
    AdapterSkeletonSafetyGuard {
        forward_method_detected: false,
        train_method_detected: false,
        infer_method_detected: false,
        weight_access_detected: false,
        checkpoint_path_detected: false,
        model_parameter_detected: false,
        runtime_ready_detected: false,
        training_ready_detected: false,
        live_inference_detected: false,
        broker_order_account_detected: false,
        safety_status: TrainingSimulationSafetyStatus::Preserved,
        violations: Vec::new(),
        paper_only: true,
    }
}

fn synthetic_lock_result_from_snapshot_set(
    snapshot_set: &AdapterShapeGoldenSnapshotSet,
) -> AdapterContractLockRunResult {
    let input_schema_result = validate_adapter_input_schema_v1(&default_adapter_input_schema_v1());
    let output_schema_result =
        validate_adapter_output_schema_v1(&default_adapter_output_schema_v1());
    let member_contract_summary = MemberLearningDataContractSummary {
        summary_id: "synthetic-adapter-contract-summary".to_string(),
        member_count: snapshot_set.snapshot_count,
        valid_member_count: snapshot_set.snapshot_count,
        invalid_member_count: 0,
        warning_count: 0,
        member_results: Vec::new(),
        status: MemberLearningDataContractSummaryStatus::Valid,
        paper_only: true,
    };
    let baseline_policy = AdapterGoldenBaselinePolicy::default();
    let baseline_comparison_result =
        compare_current_snapshot_to_expected_baseline(snapshot_set, None, &baseline_policy);
    let schema_drift_guard = evaluate_adapter_schema_drift(snapshot_set, None);
    let adapter_safety_guard = synthetic_safe_adapter_safety_guard();
    let mut lock_result = AdapterContractLockRunResult {
        run_id: "synthetic-adapter-contract-lock".to_string(),
        schema_version: snapshot_set.schema_version.clone(),
        input_schema_result,
        output_schema_result,
        member_contract_summary,
        batch_contract_validations: Vec::new(),
        batch_contract_validation_count: 0,
        unmatched_batch_count: 0,
        golden_snapshot_set: snapshot_set.clone(),
        golden_snapshot_count: snapshot_set.snapshot_count,
        schema_drift_guard,
        adapter_safety_guard,
        loaded_expected_baseline: None,
        baseline_bootstrap_result: None,
        baseline_comparison_result: baseline_comparison_result.clone(),
        contract_lock_acceptance_gate: AdapterContractLockAcceptanceGate {
            gate_id: "synthetic-adapter-contract-gate".to_string(),
            input_schema_status: AdapterSchemaValidationStatus::Valid,
            output_schema_status: AdapterSchemaValidationStatus::Valid,
            member_contract_status: MemberLearningDataContractSummaryStatus::Valid,
            batch_contract_status: AdapterContractLockBatchStatus::Valid,
            golden_baseline_status: baseline_comparison_result.diff_status,
            schema_drift_status: AdapterSchemaDriftStatus::MissingBaseline,
            adapter_safety_status: TrainingSimulationSafetyStatus::Preserved,
            lock_accepted: false,
            gate_status: AdapterContractLockAcceptanceGateStatus::BlockedByMissingBaseline,
            blockers: vec!["synthetic baseline missing".to_string()],
            warnings: Vec::new(),
            paper_only: true,
        },
        regression_harness_result: None,
        no_forward_runtime_training_warning:
            "shape-only contract lock only; no forward/runtime/training path added".to_string(),
        lock_status: AdapterContractLockStatus::LockedWithWarnings,
        paper_only: true,
    };
    lock_result.contract_lock_acceptance_gate = evaluate_adapter_contract_lock_acceptance(
        &lock_result,
        &baseline_comparison_result,
        &baseline_policy,
    );
    lock_result
}

pub fn run_adapter_contract_regression_harness(
    baseline: &AdapterGoldenSnapshotBaselineFile,
    current_snapshot_set: &AdapterShapeGoldenSnapshotSet,
    policy: &AdapterGoldenBaselinePolicy,
) -> AdapterContractRegressionHarnessResult {
    let base_lock_result = synthetic_lock_result_from_snapshot_set(current_snapshot_set);
    let cases = vec![
        AdapterContractRegressionCase {
            case_id: "missing-baseline-normal".to_string(),
            mutation_type: AdapterContractRegressionMutationType::MissingBaseline,
            expected_status: AdapterContractLockAcceptanceGateStatus::BlockedByMissingBaseline,
            paper_only: true,
        },
        AdapterContractRegressionCase {
            case_id: "missing-baseline-bootstrap".to_string(),
            mutation_type: AdapterContractRegressionMutationType::MissingBaseline,
            expected_status: AdapterContractLockAcceptanceGateStatus::LockedWithWarnings,
            paper_only: true,
        },
        AdapterContractRegressionCase {
            case_id: "output-dimension-change".to_string(),
            mutation_type: AdapterContractRegressionMutationType::OutputDimensionChange,
            expected_status: AdapterContractLockAcceptanceGateStatus::BlockedBySchemaDrift,
            paper_only: true,
        },
        AdapterContractRegressionCase {
            case_id: "input-dimension-change".to_string(),
            mutation_type: AdapterContractRegressionMutationType::InputDimensionChange,
            expected_status: AdapterContractLockAcceptanceGateStatus::BlockedBySchemaDrift,
            paper_only: true,
        },
        AdapterContractRegressionCase {
            case_id: "schema-version-bump".to_string(),
            mutation_type: AdapterContractRegressionMutationType::SchemaVersionBump,
            expected_status: AdapterContractLockAcceptanceGateStatus::LockedWithWarnings,
            paper_only: true,
        },
        AdapterContractRegressionCase {
            case_id: "member-alias-unknown".to_string(),
            mutation_type: AdapterContractRegressionMutationType::MemberAliasUnknown,
            expected_status: AdapterContractLockAcceptanceGateStatus::BlockedByContractViolation,
            paper_only: true,
        },
        AdapterContractRegressionCase {
            case_id: "batch-member-mismatch".to_string(),
            mutation_type: AdapterContractRegressionMutationType::BatchMemberMismatch,
            expected_status: AdapterContractLockAcceptanceGateStatus::BlockedByContractViolation,
            paper_only: true,
        },
        AdapterContractRegressionCase {
            case_id: "output-logits-injected".to_string(),
            mutation_type: AdapterContractRegressionMutationType::OutputLogitsInjected,
            expected_status: AdapterContractLockAcceptanceGateStatus::BlockedBySafety,
            paper_only: true,
        },
        AdapterContractRegressionCase {
            case_id: "input-outcome-leakage".to_string(),
            mutation_type: AdapterContractRegressionMutationType::InputOutcomeLeakage,
            expected_status: AdapterContractLockAcceptanceGateStatus::BlockedByContractViolation,
            paper_only: true,
        },
    ];
    let mut case_results = Vec::new();
    for case in cases {
        let (comparison, case_policy, mutated_lock_result) = match case.mutation_type {
            AdapterContractRegressionMutationType::MissingBaseline
                if case.case_id == "missing-baseline-bootstrap" =>
            {
                let mut bootstrap_policy = policy.clone();
                bootstrap_policy.allow_missing_baseline_bootstrap = true;
                (
                    compare_current_snapshot_to_expected_baseline(
                        current_snapshot_set,
                        None,
                        &bootstrap_policy,
                    ),
                    bootstrap_policy,
                    base_lock_result.clone(),
                )
            }
            AdapterContractRegressionMutationType::MissingBaseline => (
                compare_current_snapshot_to_expected_baseline(current_snapshot_set, None, policy),
                policy.clone(),
                base_lock_result.clone(),
            ),
            AdapterContractRegressionMutationType::OutputDimensionChange => {
                let mut changed = current_snapshot_set.clone();
                changed.snapshots[0].output_shape.stance_output_dim += 1;
                (
                    compare_current_snapshot_to_expected_baseline(&changed, Some(baseline), policy),
                    policy.clone(),
                    synthetic_lock_result_from_snapshot_set(&changed),
                )
            }
            AdapterContractRegressionMutationType::SchemaVersionBump => {
                let mut changed = current_snapshot_set.clone();
                changed.schema_version = "V2".to_string();
                changed.snapshots[0].schema_version = "V2".to_string();
                changed.snapshots[0].output_shape.stance_output_dim += 1;
                let mut bumped_policy = policy.clone();
                bumped_policy.allow_schema_version_bump = true;
                (
                    compare_current_snapshot_to_expected_baseline(
                        &changed,
                        Some(baseline),
                        &bumped_policy,
                    ),
                    bumped_policy,
                    synthetic_lock_result_from_snapshot_set(&changed),
                )
            }
            AdapterContractRegressionMutationType::MemberAliasUnknown => {
                let comparison = compare_current_snapshot_to_expected_baseline(
                    current_snapshot_set,
                    Some(baseline),
                    policy,
                );
                let mut lock_result = base_lock_result.clone();
                lock_result
                    .batch_contract_validations
                    .push(BatchAdapterContractValidationV2 {
                        validation_id: "synthetic-unknown-alias".to_string(),
                        batch_id: "synthetic-unknown-alias".to_string(),
                        raw_member_id: "UnknownPilotAI".to_string(),
                        canonical_member_id: None,
                        adapter_profile_id: None,
                        input_schema_result: lock_result.input_schema_result.clone(),
                        output_schema_result: lock_result.output_schema_result.clone(),
                        member_contract_result: MemberLearningDataContractValidationResult {
                            member_id: "UnknownPilotAI".to_string(),
                            valid: false,
                            example_count: 0,
                            split_coverage: Vec::new(),
                            label_source_violations: Vec::new(),
                            schema_violations: vec!["unknown member alias rejected".to_string()],
                            member_mapping_violations: vec![
                                "unknown member alias rejected".to_string(),
                            ],
                            validation_status: MemberLearningDataContractValidationStatus::Invalid,
                            paper_only: true,
                        },
                        batch_shape_result: BatchAdapterShapeValidation {
                            validation_id: "synthetic-unknown-alias-shape".to_string(),
                            batch_id: "synthetic-unknown-alias".to_string(),
                            member_id: "UnknownPilotAI".to_string(),
                            input_shape: build_adapter_contract_baseline_input_shape(
                                "trend-kr-short",
                                "synthetic-unknown-alias",
                                &default_adapter_input_schema_v1(),
                            ),
                            expected_output_shape: build_adapter_contract_baseline_output_shape(
                                "trend-kr-short",
                                "synthetic-unknown-alias",
                                &build_adapter_registry_for_members(
                                    &create_three_member_pilot_roster(MarketScope::UsShortTerm),
                                    true,
                                )
                                .profiles[0],
                                &default_adapter_output_schema_v1(),
                            ),
                            input_shape_status: AdapterShapeValidationStatus::Invalid,
                            output_shape_status: AdapterShapeValidationStatus::Invalid,
                            adapter_profile_status: SmartCoreV2AdapterStatus::Invalid,
                            validation_status: AdapterShapeValidationStatus::Invalid,
                            warnings: vec!["unknown member alias rejected".to_string()],
                            output_value_guard: validate_no_adapter_output_values("shape-only"),
                            paper_only: true,
                        },
                        unmatched_batch: true,
                        validation_status: AdapterContractValidationStatus::Invalid,
                        warnings: vec!["unknown member alias rejected".to_string()],
                        paper_only: true,
                    });
                lock_result.batch_contract_validation_count =
                    lock_result.batch_contract_validations.len();
                lock_result.unmatched_batch_count = 1;
                (comparison, policy.clone(), lock_result)
            }
            AdapterContractRegressionMutationType::BatchMemberMismatch => {
                let comparison = compare_current_snapshot_to_expected_baseline(
                    current_snapshot_set,
                    Some(baseline),
                    policy,
                );
                let mut lock_result = base_lock_result.clone();
                lock_result
                    .batch_contract_validations
                    .push(BatchAdapterContractValidationV2 {
                        validation_id: "synthetic-unmatched-batch".to_string(),
                        batch_id: "synthetic-unmatched-batch".to_string(),
                        raw_member_id: "trend-kr-short".to_string(),
                        canonical_member_id: Some("trend-kr-short".to_string()),
                        adapter_profile_id: Some("synthetic".to_string()),
                        input_schema_result: lock_result.input_schema_result.clone(),
                        output_schema_result: lock_result.output_schema_result.clone(),
                        member_contract_result: MemberLearningDataContractValidationResult {
                            member_id: "trend-kr-short".to_string(),
                            valid: false,
                            example_count: 0,
                            split_coverage: Vec::new(),
                            label_source_violations: Vec::new(),
                            schema_violations: vec![
                                "unmatched batch has no member contract".to_string(),
                            ],
                            member_mapping_violations: Vec::new(),
                            validation_status: MemberLearningDataContractValidationStatus::Invalid,
                            paper_only: true,
                        },
                        batch_shape_result: BatchAdapterShapeValidation {
                            validation_id: "synthetic-unmatched-batch-shape".to_string(),
                            batch_id: "synthetic-unmatched-batch".to_string(),
                            member_id: "trend-kr-short".to_string(),
                            input_shape: build_adapter_contract_baseline_input_shape(
                                "trend-kr-short",
                                "synthetic-unmatched-batch",
                                &default_adapter_input_schema_v1(),
                            ),
                            expected_output_shape: baseline.snapshot_set.snapshots[0]
                                .output_shape
                                .clone(),
                            input_shape_status: AdapterShapeValidationStatus::Invalid,
                            output_shape_status: AdapterShapeValidationStatus::Invalid,
                            adapter_profile_status: SmartCoreV2AdapterStatus::Invalid,
                            validation_status: AdapterShapeValidationStatus::Invalid,
                            warnings: vec!["unmatched batch rejected".to_string()],
                            output_value_guard: validate_no_adapter_output_values("shape-only"),
                            paper_only: true,
                        },
                        unmatched_batch: true,
                        validation_status: AdapterContractValidationStatus::Invalid,
                        warnings: vec!["unmatched batch rejected".to_string()],
                        paper_only: true,
                    });
                lock_result.batch_contract_validation_count =
                    lock_result.batch_contract_validations.len();
                lock_result.unmatched_batch_count = 1;
                (comparison, policy.clone(), lock_result)
            }
            AdapterContractRegressionMutationType::OutputLogitsInjected => {
                let comparison = compare_current_snapshot_to_expected_baseline(
                    current_snapshot_set,
                    Some(baseline),
                    policy,
                );
                let mut lock_result = base_lock_result.clone();
                lock_result.output_schema_result.value_policy_violations =
                    vec!["adapter output schema exposed logits".to_string()];
                lock_result.output_schema_result.valid = false;
                lock_result.output_schema_result.validation_status =
                    AdapterSchemaValidationStatus::Invalid;
                (comparison, policy.clone(), lock_result)
            }
            AdapterContractRegressionMutationType::InputOutcomeLeakage => {
                let comparison = compare_current_snapshot_to_expected_baseline(
                    current_snapshot_set,
                    Some(baseline),
                    policy,
                );
                let mut lock_result = base_lock_result.clone();
                lock_result.input_schema_result.valid = false;
                lock_result.input_schema_result.validation_status =
                    AdapterSchemaValidationStatus::Invalid;
                lock_result.input_schema_result.leakage_findings =
                    vec!["adapter input schema exposed outcome leakage".to_string()];
                (comparison, policy.clone(), lock_result)
            }
            AdapterContractRegressionMutationType::InputDimensionChange => {
                let mut changed = current_snapshot_set.clone();
                changed.snapshots[0].input_shape.feature_dim += 1;
                (
                    compare_current_snapshot_to_expected_baseline(&changed, Some(baseline), policy),
                    policy.clone(),
                    synthetic_lock_result_from_snapshot_set(&changed),
                )
            }
        };
        let gate = evaluate_adapter_contract_lock_acceptance(
            &mutated_lock_result,
            &comparison,
            &case_policy,
        );
        case_results.push(AdapterContractRegressionCaseResult {
            case_id: case.case_id,
            mutation_type: case.mutation_type,
            expected_status: case.expected_status,
            actual_status: gate.gate_status,
            passed: gate.gate_status == case.expected_status,
            notes: gate
                .blockers
                .iter()
                .chain(gate.warnings.iter())
                .cloned()
                .collect(),
            paper_only: true,
        });
    }
    let passed_count = case_results.iter().filter(|result| result.passed).count();
    let failed_count = case_results.len().saturating_sub(passed_count);
    AdapterContractRegressionHarnessResult {
        harness_id: format!("{}-regression-harness", baseline.baseline_id),
        case_count: case_results.len(),
        passed_count,
        failed_count,
        case_results,
        harness_status: if failed_count == 0 {
            AdapterContractRegressionHarnessStatus::Passed
        } else {
            AdapterContractRegressionHarnessStatus::Failed
        },
        paper_only: true,
    }
}

pub fn evaluate_adapter_schema_drift(
    current: &AdapterShapeGoldenSnapshotSet,
    expected: Option<&AdapterShapeGoldenSnapshotSet>,
) -> AdapterSchemaDriftGuard {
    let diff = if let Some(expected) = expected {
        compare_adapter_shape_golden_snapshots(current, expected)
    } else {
        AdapterShapeGoldenSnapshotDiff {
            added_snapshots: current
                .snapshots
                .iter()
                .map(|snapshot| snapshot.snapshot_id.clone())
                .collect(),
            removed_snapshots: Vec::new(),
            changed_snapshots: Vec::new(),
            dimension_changes: Vec::new(),
            schema_version_changes: Vec::new(),
            diff_status: AdapterShapeGoldenSnapshotDiffStatus::ExpectedDiff,
            paper_only: true,
        }
    };
    let (drift_status, requires_schema_version_bump) = if expected.is_none() {
        (AdapterSchemaDriftStatus::MissingBaseline, false)
    } else if matches!(
        diff.diff_status,
        AdapterShapeGoldenSnapshotDiffStatus::NoDiff
    ) {
        (AdapterSchemaDriftStatus::NoDrift, false)
    } else if !diff.dimension_changes.is_empty() && diff.schema_version_changes.is_empty() {
        (AdapterSchemaDriftStatus::UnexpectedDrift, true)
    } else if !diff.dimension_changes.is_empty() || !diff.schema_version_changes.is_empty() {
        (AdapterSchemaDriftStatus::DriftAllowedWithVersionBump, false)
    } else {
        (AdapterSchemaDriftStatus::NoDrift, false)
    };
    AdapterSchemaDriftGuard {
        guard_id: "adapter-schema-drift-guard".to_string(),
        current_snapshot_set: current.clone(),
        expected_snapshot_set: expected.cloned(),
        diff,
        drift_status,
        requires_schema_version_bump,
        paper_only: true,
    }
}

pub fn run_adapter_contract_lock(
    batches: &[SmartCoreV2TrainingBatch],
    registry: &SmartCoreAdapterRegistry,
    dataset: &TrainingCandidateDataset,
    split: &TrainingSplitResult,
    config: &AdapterContractLockRunConfig,
) -> Result<AdapterContractLockRunResult, String> {
    let schemas = AdapterContractSchemasV1 {
        input_schema: default_adapter_input_schema_v1(),
        output_schema: default_adapter_output_schema_v1(),
    };
    let input_schema_result = validate_adapter_input_schema_v1(&schemas.input_schema);
    let output_schema_result = validate_adapter_output_schema_v1(&schemas.output_schema);
    let canonical_map = default_three_member_canonical_id_map();
    let contracts = build_member_learning_data_contracts_for_registry(
        registry,
        &schemas.input_schema,
        &schemas.output_schema,
    );
    let member_results = registry
        .profiles
        .iter()
        .filter_map(|profile| {
            contracts
                .iter()
                .find(|contract| contract.canonical_member_id == profile.member_id)
                .map(|contract| {
                    validate_member_learning_data_contract(contract, dataset, split, profile)
                })
        })
        .collect::<Vec<_>>();
    let member_contract_summary = summarize_member_learning_data_contracts(&member_results);
    let batch_contract_validations = batches
        .iter()
        .map(|batch| {
            let canonical_member_id =
                resolve_canonical_member_id_with_map(&canonical_map, &batch.member_id);
            if let Some(canonical_member_id) = canonical_member_id {
                if let (Some(profile), Some(contract)) = (
                    registry.get_profile(&canonical_member_id),
                    contracts
                        .iter()
                        .find(|contract| contract.canonical_member_id == canonical_member_id),
                ) {
                    return validate_batch_against_adapter_contract_v2_with_context(
                        batch,
                        profile,
                        &schemas.input_schema,
                        &schemas.output_schema,
                        contract,
                        &canonical_map,
                        dataset,
                        split,
                    );
                }
            }
            BatchAdapterContractValidationV2 {
                validation_id: format!("{}-adapter-contract-v2", batch.batch_id),
                batch_id: batch.batch_id.clone(),
                raw_member_id: batch.member_id.clone(),
                canonical_member_id: resolve_canonical_member_id_with_map(
                    &canonical_map,
                    &batch.member_id,
                ),
                adapter_profile_id: None,
                input_schema_result: input_schema_result.clone(),
                output_schema_result: output_schema_result.clone(),
                member_contract_result: MemberLearningDataContractValidationResult {
                    member_id: batch.member_id.clone(),
                    valid: false,
                    example_count: 0,
                    split_coverage: Vec::new(),
                    label_source_violations: Vec::new(),
                    schema_violations: vec!["unmatched batch has no member contract".to_string()],
                    member_mapping_violations: vec!["unknown member alias rejected".to_string()],
                    validation_status: MemberLearningDataContractValidationStatus::Invalid,
                    paper_only: true,
                },
                batch_shape_result: BatchAdapterShapeValidation {
                    validation_id: format!("{}-adapter-shape-validation", batch.batch_id),
                    batch_id: batch.batch_id.clone(),
                    member_id: batch.member_id.clone(),
                    input_shape: build_adapter_input_shape_from_training_batch(
                        batch,
                        &TrainingFeatureSchema::default(),
                    ),
                    expected_output_shape: build_adapter_output_shape_for_batch(
                        batch,
                        &default_head_specs_for_member(&batch.member_id),
                        &TrainingTargetSchema::default(),
                    ),
                    input_shape_status: AdapterShapeValidationStatus::Invalid,
                    output_shape_status: AdapterShapeValidationStatus::Invalid,
                    adapter_profile_status: SmartCoreV2AdapterStatus::Invalid,
                    validation_status: AdapterShapeValidationStatus::Invalid,
                    warnings: vec!["unmatched batch rejected".to_string()],
                    output_value_guard: validate_no_adapter_output_values("unmatched"),
                    paper_only: true,
                },
                unmatched_batch: true,
                validation_status: AdapterContractValidationStatus::Invalid,
                warnings: vec!["unmatched batch rejected".to_string()],
                paper_only: true,
            }
        })
        .collect::<Vec<_>>();
    let golden_snapshot_set =
        build_adapter_shape_golden_snapshots(batches, registry, &schemas, &contracts);
    if let Some(path) = &config.write_golden_snapshot_path {
        write_safe_json(Path::new(path), &golden_snapshot_set)?;
    }
    let expected_snapshot_set = if let Some(path) = &config.expected_golden_snapshot_path {
        Some(
            serde_json::from_str::<AdapterShapeGoldenSnapshotSet>(
                &fs::read_to_string(path).map_err(|err| err.to_string())?,
            )
            .map_err(|err| err.to_string())?,
        )
    } else {
        None
    };
    let schema_drift_guard =
        evaluate_adapter_schema_drift(&golden_snapshot_set, expected_snapshot_set.as_ref());
    let adapter_safety_guard = synthetic_adapter_safety_guard_from_registry(registry);
    let unmatched_batch_count = batch_contract_validations
        .iter()
        .filter(|validation| validation.unmatched_batch)
        .count();
    let has_output_value_violation = batch_contract_validations.iter().any(|validation| {
        !validation
            .batch_shape_result
            .output_value_guard
            .violations
            .is_empty()
    }) || !output_schema_result.value_policy_violations.is_empty();
    let failed = !input_schema_result.valid
        || !output_schema_result.valid
        || matches!(
            member_contract_summary.status,
            MemberLearningDataContractSummaryStatus::Invalid
        )
        || batch_contract_validations.iter().any(|validation| {
            matches!(
                validation.validation_status,
                AdapterContractValidationStatus::Invalid
            )
        })
        || (config.fail_on_unmatched_batch && unmatched_batch_count > 0)
        || (config.fail_on_output_values && has_output_value_violation)
        || (config.fail_on_unknown_member_alias
            && batch_contract_validations
                .iter()
                .any(|validation| validation.canonical_member_id.is_none()))
        || (config.require_schema_version_match
            && !schema_drift_guard.diff.schema_version_changes.is_empty())
        || matches!(
            schema_drift_guard.drift_status,
            AdapterSchemaDriftStatus::UnexpectedDrift
        );
    let warning_status = matches!(
        member_contract_summary.status,
        MemberLearningDataContractSummaryStatus::ValidWithWarnings
    ) || batch_contract_validations.iter().any(|validation| {
        matches!(
            validation.validation_status,
            AdapterContractValidationStatus::ValidWithWarnings
        )
    }) || matches!(
        schema_drift_guard.drift_status,
        AdapterSchemaDriftStatus::MissingBaseline
            | AdapterSchemaDriftStatus::DriftAllowedWithVersionBump
    );
    let baseline_policy = AdapterGoldenBaselinePolicy {
        baseline_required: config.fail_on_missing_baseline,
        allow_missing_baseline_bootstrap: config.bootstrap_missing_baseline,
        allow_schema_version_bump: config.allow_schema_version_bump,
        fail_on_unknown_member_alias: config.fail_on_unknown_member_alias,
        fail_on_unmatched_batch: config.fail_on_unmatched_batch,
        ..AdapterGoldenBaselinePolicy::default()
    };
    let baseline_comparison_result = AdapterGoldenBaselineComparisonResult {
        current_baseline_id: None,
        expected_baseline_id: None,
        current_snapshot_count: golden_snapshot_set.snapshot_count,
        expected_snapshot_count: expected_snapshot_set
            .as_ref()
            .map(|snapshot_set| snapshot_set.snapshot_count)
            .unwrap_or(0),
        added_snapshot_ids: schema_drift_guard.diff.added_snapshots.clone(),
        removed_snapshot_ids: schema_drift_guard.diff.removed_snapshots.clone(),
        changed_snapshot_ids: schema_drift_guard.diff.changed_snapshots.clone(),
        dimension_diffs: schema_drift_guard.diff.dimension_changes.clone(),
        member_set_diffs: Vec::new(),
        batch_set_diffs: Vec::new(),
        input_group_diffs: Vec::new(),
        output_head_diffs: Vec::new(),
        schema_version_diffs: schema_drift_guard.diff.schema_version_changes.clone(),
        diff_status: match schema_drift_guard.drift_status {
            AdapterSchemaDriftStatus::NoDrift => AdapterGoldenBaselineDiffStatus::NoDiff,
            AdapterSchemaDriftStatus::DriftAllowedWithVersionBump => {
                AdapterGoldenBaselineDiffStatus::ExpectedVersionedDiff
            }
            AdapterSchemaDriftStatus::UnexpectedDrift => {
                AdapterGoldenBaselineDiffStatus::UnexpectedDrift
            }
            AdapterSchemaDriftStatus::MissingBaseline => {
                AdapterGoldenBaselineDiffStatus::MissingBaseline
            }
        },
        paper_only: true,
    };
    let mut result = AdapterContractLockRunResult {
        run_id: config.run_id.clone(),
        schema_version: adapter_schema_version_text(),
        batch_contract_validation_count: batch_contract_validations.len(),
        unmatched_batch_count,
        golden_snapshot_count: golden_snapshot_set.snapshot_count,
        input_schema_result,
        output_schema_result,
        member_contract_summary,
        batch_contract_validations,
        golden_snapshot_set,
        schema_drift_guard,
        adapter_safety_guard,
        loaded_expected_baseline: None,
        baseline_bootstrap_result: None,
        baseline_comparison_result: baseline_comparison_result.clone(),
        contract_lock_acceptance_gate: AdapterContractLockAcceptanceGate {
            gate_id: format!("{}-acceptance-gate", config.run_id),
            input_schema_status: AdapterSchemaValidationStatus::Valid,
            output_schema_status: AdapterSchemaValidationStatus::Valid,
            member_contract_status: MemberLearningDataContractSummaryStatus::Valid,
            batch_contract_status: AdapterContractLockBatchStatus::Valid,
            golden_baseline_status: baseline_comparison_result.diff_status,
            schema_drift_status: schema_drift_status_from_baseline_comparison(
                &baseline_comparison_result,
            ),
            adapter_safety_status: TrainingSimulationSafetyStatus::Preserved,
            lock_accepted: false,
            gate_status: AdapterContractLockAcceptanceGateStatus::BlockedByMissingBaseline,
            blockers: Vec::new(),
            warnings: Vec::new(),
            paper_only: true,
        },
        regression_harness_result: None,
        no_forward_runtime_training_warning:
            "shape-only contract lock only; no forward/runtime/training path added".to_string(),
        lock_status: if failed {
            AdapterContractLockStatus::Failed
        } else if warning_status {
            AdapterContractLockStatus::LockedWithWarnings
        } else {
            AdapterContractLockStatus::Locked
        },
        paper_only: true,
    };
    result.contract_lock_acceptance_gate = evaluate_adapter_contract_lock_acceptance(
        &result,
        &baseline_comparison_result,
        &baseline_policy,
    );
    Ok(result)
}

pub fn run_adapter_contract_lock_v2(
    batches: &[SmartCoreV2TrainingBatch],
    registry: &SmartCoreAdapterRegistry,
    dataset: &TrainingCandidateDataset,
    split: &TrainingSplitResult,
    config: &AdapterContractLockRunConfig,
) -> Result<AdapterContractLockRunResult, String> {
    let mut legacy_config = config.clone();
    legacy_config.expected_golden_snapshot_path = None;
    let mut result = run_adapter_contract_lock(batches, registry, dataset, split, &legacy_config)?;
    let baseline_policy = AdapterGoldenBaselinePolicy {
        baseline_required: config.fail_on_missing_baseline,
        allow_missing_baseline_bootstrap: config.bootstrap_missing_baseline,
        allow_schema_version_bump: config.allow_schema_version_bump,
        fail_on_unknown_member_alias: config.fail_on_unknown_member_alias,
        fail_on_unmatched_batch: config.fail_on_unmatched_batch,
        ..AdapterGoldenBaselinePolicy::default()
    };
    let loaded_expected_baseline = if let Some(path) = config.expected_golden_baseline_path.as_ref()
    {
        Some(load_adapter_golden_snapshot_baseline_from_local_json(
            Path::new(path),
        )?)
    } else if let Some(path) = config.expected_golden_snapshot_path.as_ref() {
        let snapshot_path = Path::new(path);
        validate_local_json_path(snapshot_path, "adapter contract expected snapshot path")?;
        let text = fs::read_to_string(snapshot_path).map_err(|err| err.to_string())?;
        Some(
            serde_json::from_str::<AdapterGoldenSnapshotBaselineFile>(&text)
                .or_else(|_| {
                    serde_json::from_str::<AdapterShapeGoldenSnapshotSet>(&text).map(
                        |snapshot_set| AdapterGoldenSnapshotBaselineFile {
                            schema_version: snapshot_set.schema_version.clone(),
                            baseline_id: "legacy-expected-adapter-snapshot".to_string(),
                            created_from_run_id: None,
                            snapshot_set,
                            baseline_policy: baseline_policy.clone(),
                            paper_only: true,
                        },
                    )
                })
                .map_err(|err| err.to_string())?,
        )
    } else {
        None
    };
    let mut baseline_bootstrap_result = None;
    if loaded_expected_baseline.is_none()
        && config.bootstrap_missing_baseline
        && config.write_golden_baseline_if_missing
    {
        if matches!(result.lock_status, AdapterContractLockStatus::Failed) {
            baseline_bootstrap_result = Some(AdapterGoldenBaselineBootstrapResult {
                bootstrap_id: format!("{}-bootstrap", config.run_id),
                wrote_baseline: false,
                output_path: config
                    .bootstrap_golden_baseline_path
                    .clone()
                    .unwrap_or_else(|| "<missing>".to_string()),
                snapshot_count: result.golden_snapshot_set.snapshot_count,
                validation_status: AdapterGoldenBaselineValidationStatus::Invalid,
                bootstrap_status: AdapterGoldenBaselineBootstrapStatus::Blocked,
                warnings: vec![
                    "baseline bootstrap blocked because current contract lock failed".to_string(),
                ],
                paper_only: true,
            });
        } else if let Some(path) = config.bootstrap_golden_baseline_path.as_ref() {
            let bootstrap_result =
                bootstrap_adapter_golden_baseline(&AdapterGoldenBaselineBootstrapConfig {
                    bootstrap_id: format!("{}-bootstrap", config.run_id),
                    output_baseline_path: path.clone(),
                    source_snapshot_set: result.golden_snapshot_set.clone(),
                    allow_overwrite: false,
                    require_clean_contract_lock: true,
                    baseline_policy: baseline_policy.clone(),
                    created_from_run_id: Some(config.run_id.clone()),
                    paper_only: true,
                })?;
            baseline_bootstrap_result = Some(bootstrap_result);
        }
    }
    let baseline_comparison_result = compare_current_snapshot_to_expected_baseline(
        &result.golden_snapshot_set,
        loaded_expected_baseline.as_ref(),
        &baseline_policy,
    );
    let contract_lock_acceptance_gate = evaluate_adapter_contract_lock_acceptance(
        &result,
        &baseline_comparison_result,
        &baseline_policy,
    );
    let regression_harness_result = if config.run_regression_harness {
        let synthetic_baseline;
        let harness_baseline = if let Some(loaded) = loaded_expected_baseline.as_ref() {
            loaded
        } else {
            synthetic_baseline = AdapterGoldenSnapshotBaselineFile {
                schema_version: result.golden_snapshot_set.schema_version.clone(),
                baseline_id: format!("{}-synthetic-baseline", config.run_id),
                created_from_run_id: Some(config.run_id.clone()),
                snapshot_set: result.golden_snapshot_set.clone(),
                baseline_policy: baseline_policy.clone(),
                paper_only: true,
            };
            &synthetic_baseline
        };
        Some(run_adapter_contract_regression_harness(
            harness_baseline,
            &result.golden_snapshot_set,
            &baseline_policy,
        ))
    } else {
        None
    };
    result.loaded_expected_baseline = loaded_expected_baseline;
    result.baseline_bootstrap_result = baseline_bootstrap_result;
    result.baseline_comparison_result = baseline_comparison_result.clone();
    result.contract_lock_acceptance_gate = contract_lock_acceptance_gate.clone();
    result.regression_harness_result = regression_harness_result;
    result.schema_drift_guard.drift_status =
        schema_drift_status_from_baseline_comparison(&baseline_comparison_result);
    result.schema_drift_guard.requires_schema_version_bump =
        matches!(
            result.schema_drift_guard.drift_status,
            AdapterSchemaDriftStatus::UnexpectedDrift
        ) && !baseline_comparison_result.schema_version_diffs.is_empty();
    result.lock_status = match contract_lock_acceptance_gate.gate_status {
        AdapterContractLockAcceptanceGateStatus::Locked => AdapterContractLockStatus::Locked,
        AdapterContractLockAcceptanceGateStatus::LockedWithWarnings => {
            AdapterContractLockStatus::LockedWithWarnings
        }
        AdapterContractLockAcceptanceGateStatus::BlockedByMissingBaseline
        | AdapterContractLockAcceptanceGateStatus::BlockedBySchemaDrift
        | AdapterContractLockAcceptanceGateStatus::BlockedByContractViolation
        | AdapterContractLockAcceptanceGateStatus::BlockedBySafety => {
            AdapterContractLockStatus::Failed
        }
    };
    Ok(result)
}

