pub fn project_toy_uncertainty_head_v0(
    pooled_output: &TinyTensor1D,
    params: &SmartCoreHeadProjectionParamsV0,
    _config: &SmartCoreHeadProjectionConfigV0,
) -> ToyUncertaintyHeadOutputV0 {
    let raw_score = params
        .uncertainty_projection
        .as_ref()
        .and_then(|weights| {
            project_head_hidden_v0(pooled_output, params)
                .ok()
                .and_then(|hidden| project_head_raw_score(&hidden, weights).ok())
        })
        .unwrap_or(0.0);
    ToyUncertaintyHeadOutputV0 {
        raw_score,
        bucket: if raw_score < -0.25 {
            ToyUncertaintyBucketV0::LowUncertainty
        } else if raw_score > 0.35 {
            ToyUncertaintyBucketV0::HighUncertainty
        } else {
            ToyUncertaintyBucketV0::MediumUncertainty
        },
        uncertainty_hint: raw_score.abs(),
        debug_only: true,
        paper_only: true,
    }
}

pub fn project_toy_expected_return_head_v0(
    pooled_output: &TinyTensor1D,
    params: &SmartCoreHeadProjectionParamsV0,
    config: &SmartCoreHeadProjectionConfigV0,
) -> ToyExpectedReturnHeadOutputV0 {
    if !config
        .enabled_heads
        .contains(&SmartCoreV2HeadKind::ExpectedReturnHint)
    {
        return ToyExpectedReturnHeadOutputV0 {
            raw_score: None,
            bucket: ToyExpectedReturnBucketV0::Deferred,
            expected_return_hint: 0.0,
            debug_only: true,
            paper_only: true,
        };
    }
    let raw_score = params
        .expected_return_projection
        .as_ref()
        .and_then(|weights| {
            project_head_hidden_v0(pooled_output, params)
                .ok()
                .and_then(|hidden| project_head_raw_score(&hidden, weights).ok())
        });
    let score = raw_score.unwrap_or(0.0);
    ToyExpectedReturnHeadOutputV0 {
        raw_score,
        bucket: if score > 0.2 {
            ToyExpectedReturnBucketV0::PositiveHint
        } else if score < -0.2 {
            ToyExpectedReturnBucketV0::NegativeHint
        } else {
            ToyExpectedReturnBucketV0::NeutralHint
        },
        expected_return_hint: score,
        debug_only: true,
        paper_only: true,
    }
}

pub fn evaluate_smartcore_debug_output_safety_v0(
    output: &SmartCoreDebugOutputV0,
) -> SmartCoreDebugOutputSafetyGuardV0 {
    let finite_scores = output
        .stance_head
        .as_ref()
        .map(|head| head.raw_score.is_finite())
        .unwrap_or(true)
        && output
            .risk_head
            .as_ref()
            .map(|head| head.raw_score.is_finite())
            .unwrap_or(true)
        && output
            .evidence_need_head
            .as_ref()
            .map(|head| head.raw_score.is_finite())
            .unwrap_or(true)
        && output
            .confidence_calibration_head
            .as_ref()
            .map(|head| head.raw_score.is_finite())
            .unwrap_or(true)
        && output
            .uncertainty_head
            .as_ref()
            .map(|head| head.raw_score.is_finite())
            .unwrap_or(true)
        && output
            .expected_return_head
            .as_ref()
            .and_then(|head| head.raw_score)
            .map(|score| score.is_finite())
            .unwrap_or(true);
    let leakage_scan_text = format!(
        "{} {} {}",
        output.debug_output_id,
        output.member_id,
        output.source_microkernel_run_id.as_deref().unwrap_or("")
    );
    let no_label_leakage = microkernel_forbidden_terms(&leakage_scan_text).is_empty();
    let mut violations = Vec::new();
    if !finite_scores {
        violations.push("debug head scores must remain finite".to_string());
    }
    if !output.debug_only {
        violations.push("debug output must remain debug_only=true".to_string());
    }
    if !output.not_investment_signal {
        violations.push("debug output must not claim investment signal".to_string());
    }
    if !output.not_committee_opinion {
        violations.push("debug output must not claim committee opinion".to_string());
    }
    if !output.not_order {
        violations.push("debug output must not claim order output".to_string());
    }
    if !output.paper_only {
        violations.push("debug output must remain paper-only".to_string());
    }
    if !no_label_leakage {
        violations.push("debug output leaked forbidden label/outcome/order terms".to_string());
    }
    SmartCoreDebugOutputSafetyGuardV0 {
        finite_scores,
        debug_only: output.debug_only,
        not_investment_signal: output.not_investment_signal,
        not_committee_opinion: output.not_committee_opinion,
        not_order: output.not_order,
        no_broker_order_account: true,
        no_live_inference: true,
        no_training: true,
        no_weight_update: true,
        no_checkpoint: true,
        no_label_leakage,
        safety_status: if violations.is_empty() {
            SmartCoreDebugOutputSafetyStatusV0::Preserved
        } else {
            SmartCoreDebugOutputSafetyStatusV0::Violated
        },
        violations,
        paper_only: true,
    }
}

pub fn build_smartcore_debug_output_v0(
    microkernel_output: &SmartCoreMicroKernelMemberOutputV0,
    projection_params: &SmartCoreHeadProjectionParamsV0,
    config: &SmartCoreHeadProjectionConfigV0,
) -> Result<SmartCoreDebugOutputV0, String> {
    validate_head_projection_config_v0(config)?;
    validate_head_projection_params_v0(projection_params)?;
    let mut output = SmartCoreDebugOutputV0 {
        debug_output_id: format!("{}-debug-output", config.projection_id),
        member_id: microkernel_output.member_id.clone(),
        source_microkernel_run_id: Some(config.projection_id.clone()),
        stance_head: config
            .enabled_heads
            .contains(&SmartCoreV2HeadKind::Stance)
            .then(|| {
                project_toy_stance_head_v0(
                    &microkernel_output.output.pooled_output,
                    projection_params,
                    config,
                )
            }),
        risk_head: config
            .enabled_heads
            .contains(&SmartCoreV2HeadKind::Risk)
            .then(|| {
                project_toy_risk_head_v0(
                    &microkernel_output.output.pooled_output,
                    projection_params,
                    config,
                )
            }),
        evidence_need_head: config
            .enabled_heads
            .contains(&SmartCoreV2HeadKind::EvidenceNeed)
            .then(|| {
                project_toy_evidence_need_head_v0(
                    &microkernel_output.output.pooled_output,
                    projection_params,
                    config,
                )
            }),
        confidence_calibration_head: config
            .enabled_heads
            .contains(&SmartCoreV2HeadKind::ConfidenceCalibration)
            .then(|| {
                project_toy_confidence_calibration_head_v0(
                    &microkernel_output.output.pooled_output,
                    projection_params,
                    config,
                )
            }),
        uncertainty_head: config
            .enabled_heads
            .contains(&SmartCoreV2HeadKind::Uncertainty)
            .then(|| {
                project_toy_uncertainty_head_v0(
                    &microkernel_output.output.pooled_output,
                    projection_params,
                    config,
                )
            }),
        expected_return_head: Some(project_toy_expected_return_head_v0(
            &microkernel_output.output.pooled_output,
            projection_params,
            config,
        )),
        output_safety: SmartCoreDebugOutputSafetyGuardV0 {
            finite_scores: true,
            debug_only: true,
            not_investment_signal: true,
            not_committee_opinion: true,
            not_order: true,
            no_broker_order_account: true,
            no_live_inference: true,
            no_training: true,
            no_weight_update: true,
            no_checkpoint: true,
            no_label_leakage: true,
            safety_status: SmartCoreDebugOutputSafetyStatusV0::Preserved,
            violations: Vec::new(),
            paper_only: true,
        },
        debug_only: true,
        not_investment_signal: true,
        not_committee_opinion: true,
        not_order: true,
        paper_only: true,
    };
    output.output_safety = evaluate_smartcore_debug_output_safety_v0(&output);
    Ok(output)
}

pub fn build_smartcore_debug_output_batch_v0(
    microkernel_outputs: &[SmartCoreMicroKernelMemberOutputV0],
    configs: &[SmartCoreHeadProjectionConfigV0],
) -> Result<SmartCoreDebugOutputBatchV0, String> {
    let mut member_outputs = Vec::new();
    for member_output in microkernel_outputs {
        let config = configs
            .iter()
            .find(|config| {
                runtime_entry_member_matches(&config.member_id, &member_output.member_id)
            })
            .ok_or_else(|| {
                format!(
                    "missing head projection config for {}",
                    member_output.member_id
                )
            })?;
        let params = init_head_projection_params_v0(
            config,
            deterministic_seed_from_member_id(&member_output.member_id, 97),
        )?;
        member_outputs.push(build_smartcore_debug_output_v0(
            member_output,
            &params,
            config,
        )?);
    }
    Ok(SmartCoreDebugOutputBatchV0 {
        batch_id: configs
            .first()
            .map(|config| format!("{}-debug-batch", config.projection_id))
            .unwrap_or_else(|| "smartcore-debug-output-batch".to_string()),
        output_count: member_outputs.len(),
        member_count: member_outputs.len(),
        member_outputs,
        debug_only: true,
        paper_only: true,
    })
}

impl Default for SmartCoreDebugInterpretationPolicyV0 {
    fn default() -> Self {
        Self {
            allow_as_member_opinion: false,
            allow_as_committee_input: false,
            allow_as_trade_signal: false,
            allow_as_research_diagnostic: true,
            allow_owner_console_debug: true,
            paper_only: true,
        }
    }
}

pub fn interpret_smartcore_debug_output_v0(
    output: &SmartCoreDebugOutputV0,
    policy: &SmartCoreDebugInterpretationPolicyV0,
) -> SmartCoreDebugInterpretationResultV0 {
    let mut warnings = Vec::new();
    let mut allowed_uses = Vec::new();
    if policy.allow_as_research_diagnostic {
        allowed_uses.push(SmartCoreDebugAllowedUseV0::ResearchDiagnostic);
    }
    if policy.allow_owner_console_debug {
        allowed_uses.push(SmartCoreDebugAllowedUseV0::OwnerConsoleDebug);
    }
    let forbidden_uses = vec![
        SmartCoreDebugForbiddenUseV0::MemberOpinion,
        SmartCoreDebugForbiddenUseV0::CommitteeDecision,
        SmartCoreDebugForbiddenUseV0::TradeSignal,
        SmartCoreDebugForbiddenUseV0::OrderExecution,
        SmartCoreDebugForbiddenUseV0::LiveInference,
    ];
    let violated = policy.allow_as_member_opinion
        || policy.allow_as_committee_input
        || policy.allow_as_trade_signal
        || !output.debug_only
        || !output.not_investment_signal
        || !output.not_committee_opinion
        || !output.not_order;
    if violated {
        warnings.push("debug output interpretation policy must remain debug-only".to_string());
    }
    SmartCoreDebugInterpretationResultV0 {
        debug_output_id: output.debug_output_id.clone(),
        allowed_uses,
        forbidden_uses,
        interpretation_status: if violated {
            SmartCoreDebugInterpretationStatusV0::Violated
        } else {
            SmartCoreDebugInterpretationStatusV0::DebugOnly
        },
        warnings,
        paper_only: true,
    }
}

fn aggregate_smartcore_debug_output_safety(
    guards: &[SmartCoreDebugOutputSafetyGuardV0],
) -> SmartCoreDebugOutputSafetyGuardV0 {
    let mut combined = SmartCoreDebugOutputSafetyGuardV0 {
        finite_scores: true,
        debug_only: true,
        not_investment_signal: true,
        not_committee_opinion: true,
        not_order: true,
        no_broker_order_account: true,
        no_live_inference: true,
        no_training: true,
        no_weight_update: true,
        no_checkpoint: true,
        no_label_leakage: true,
        safety_status: SmartCoreDebugOutputSafetyStatusV0::Preserved,
        violations: Vec::new(),
        paper_only: true,
    };
    for guard in guards {
        combined.finite_scores &= guard.finite_scores;
        combined.debug_only &= guard.debug_only;
        combined.not_investment_signal &= guard.not_investment_signal;
        combined.not_committee_opinion &= guard.not_committee_opinion;
        combined.not_order &= guard.not_order;
        combined.no_broker_order_account &= guard.no_broker_order_account;
        combined.no_live_inference &= guard.no_live_inference;
        combined.no_training &= guard.no_training;
        combined.no_weight_update &= guard.no_weight_update;
        combined.no_checkpoint &= guard.no_checkpoint;
        combined.no_label_leakage &= guard.no_label_leakage;
        combined.violations.extend(guard.violations.clone());
    }
    combined.safety_status = if combined.violations.is_empty() {
        SmartCoreDebugOutputSafetyStatusV0::Preserved
    } else {
        SmartCoreDebugOutputSafetyStatusV0::Violated
    };
    combined
}

pub fn run_smartcore_head_projection_dry_run_v0(
    microkernel_result: &SmartCoreMicroKernelDryRunResultV0,
    config: &SmartCoreHeadProjectionDryRunConfigV0,
) -> Result<SmartCoreHeadProjectionDryRunResultV0, String> {
    if !config.paper_only {
        return Err("head projection dry-run must remain paper-only".to_string());
    }
    if matches!(
        microkernel_result.microkernel_status,
        SmartCoreMicroKernelStatusV0::Failed
    ) {
        return Err("head projection dry-run requires non-failed microkernel result".to_string());
    }
    let projection_configs: Vec<_> = microkernel_result
        .member_outputs
        .iter()
        .map(|member_output| SmartCoreHeadProjectionConfigV0 {
            projection_id: format!("{}-{}", config.run_id, member_output.member_id),
            member_id: member_output.member_id.clone(),
            input_dim: member_output.output.pooled_output.dim,
            hidden_dim: member_output.output.pooled_output.dim.max(1),
            enabled_heads: [
                (config.enable_stance_head, SmartCoreV2HeadKind::Stance),
                (config.enable_risk_head, SmartCoreV2HeadKind::Risk),
                (
                    config.enable_evidence_head,
                    SmartCoreV2HeadKind::EvidenceNeed,
                ),
                (
                    config.enable_confidence_head,
                    SmartCoreV2HeadKind::ConfidenceCalibration,
                ),
                (
                    config.enable_uncertainty_head,
                    SmartCoreV2HeadKind::Uncertainty,
                ),
                (
                    config.enable_expected_return_head,
                    SmartCoreV2HeadKind::ExpectedReturnHint,
                ),
            ]
            .into_iter()
            .filter_map(|(enabled, head)| enabled.then_some(head))
            .collect(),
            output_mode: SmartCoreHeadProjectionOutputModeV0::DebugOnly,
            parameter_init: TinyParameterInitPolicyV0::DeterministicTiny,
            paper_only: true,
        })
        .collect();
    let debug_output_batch = build_smartcore_debug_output_batch_v0(
        &microkernel_result.member_outputs,
        &projection_configs,
    )?;
    let safety_guards: Vec<_> = debug_output_batch
        .member_outputs
        .iter()
        .map(|output| output.output_safety.clone())
        .collect();
    let output_safety_summary = aggregate_smartcore_debug_output_safety(&safety_guards);
    let interpretation_summary: Vec<_> = debug_output_batch
        .member_outputs
        .iter()
        .map(|output| {
            interpret_smartcore_debug_output_v0(
                output,
                &SmartCoreDebugInterpretationPolicyV0::default(),
            )
        })
        .collect();
    let mut warnings = Vec::new();
    if !config.enable_expected_return_head {
        warnings.push("toy expected return head remains deferred by default".to_string());
    }
    let per_member_head_buckets = debug_output_batch
        .member_outputs
        .iter()
        .map(|output| {
            let mut buckets = Vec::new();
            if let Some(head) = output.stance_head.as_ref() {
                buckets.push(format!("stance:{:?}", head.bucket));
            }
            if let Some(head) = output.risk_head.as_ref() {
                buckets.push(format!("risk:{:?}", head.bucket));
            }
            if let Some(head) = output.evidence_need_head.as_ref() {
                buckets.push(format!("evidence:{:?}", head.bucket));
            }
            if let Some(head) = output.confidence_calibration_head.as_ref() {
                buckets.push(format!("confidence:{:?}", head.bucket));
            }
            if let Some(head) = output.uncertainty_head.as_ref() {
                buckets.push(format!("uncertainty:{:?}", head.bucket));
            }
            if let Some(head) = output.expected_return_head.as_ref() {
                buckets.push(format!("expected_return:{:?}", head.bucket));
            }
            (output.member_id.clone(), buckets)
        })
        .collect();
    let dry_run_status = if matches!(
        output_safety_summary.safety_status,
        SmartCoreDebugOutputSafetyStatusV0::Violated
    ) || interpretation_summary.iter().any(|result| {
        matches!(
            result.interpretation_status,
            SmartCoreDebugInterpretationStatusV0::Violated
        )
    }) {
        SmartCoreHeadProjectionDryRunStatusV0::Failed
    } else if warnings.is_empty()
        && matches!(
            microkernel_result.microkernel_status,
            SmartCoreMicroKernelStatusV0::Passed
        )
    {
        SmartCoreHeadProjectionDryRunStatusV0::Passed
    } else {
        SmartCoreHeadProjectionDryRunStatusV0::PassedWithWarnings
    };
    let result = SmartCoreHeadProjectionDryRunResultV0 {
        run_id: config.run_id.clone(),
        source_microkernel_status: microkernel_result.microkernel_status,
        debug_output_batch,
        output_safety_summary,
        interpretation_summary,
        per_member_head_buckets,
        head_projection_status: dry_run_status,
        dry_run_status,
        warnings,
        no_training: true,
        no_weight_update: true,
        no_checkpoint: true,
        no_live_inference: true,
        debug_only: true,
        not_investment_signal: true,
        not_committee_opinion: true,
        not_order: true,
        no_broker_order_account: true,
        paper_only_warning:
            "smartcore head projection remains a paper-only debug artifact; not an order, not a committee opinion, and not live inference"
                .to_string(),
        paper_only: true,
    };
    if let Some(path) = config.output_path.as_ref() {
        write_safe_json(Path::new(path), &result)?;
    }
    Ok(result)
}

fn smartcore_shadow_head_key(head: SmartCoreShadowHeadKind) -> &'static str {
    match head {
        SmartCoreShadowHeadKind::Stance => "stance",
        SmartCoreShadowHeadKind::Risk => "risk",
        SmartCoreShadowHeadKind::EvidenceNeed => "evidence",
        SmartCoreShadowHeadKind::ConfidenceCalibration => "confidence",
        SmartCoreShadowHeadKind::Uncertainty => "uncertainty",
        SmartCoreShadowHeadKind::ExpectedReturnHint => "expected_return",
    }
}

fn normalized_bucket_label(value: SmartCoreHeadBucketNormalizedValue) -> String {
    format!("{value:?}")
}

fn member_stance_shadow_target(stance: MemberStance) -> Option<SmartCoreHeadBucketNormalizedValue> {
    match stance {
        MemberStance::BuyProposal => Some(SmartCoreHeadBucketNormalizedValue::PositiveLike),
        MemberStance::SellProposal | MemberStance::NoTrade => {
            Some(SmartCoreHeadBucketNormalizedValue::NegativeLike)
        }
        MemberStance::Hold => Some(SmartCoreHeadBucketNormalizedValue::NeutralLike),
        MemberStance::NeedMoreEvidence => None,
    }
}

fn confidence_target_from_score(score: f64) -> SmartCoreHeadBucketNormalizedValue {
    if score >= 0.75 {
        SmartCoreHeadBucketNormalizedValue::ConfidenceHigh
    } else if score >= 0.45 {
        SmartCoreHeadBucketNormalizedValue::ConfidenceMedium
    } else {
        SmartCoreHeadBucketNormalizedValue::ConfidenceLow
    }
}

fn confidence_target_from_learning_label(
    label: MemberLearningLabel,
) -> SmartCoreHeadBucketNormalizedValue {
    match label {
        MemberLearningLabel::Reinforce | MemberLearningLabel::CalibrateUp => {
            SmartCoreHeadBucketNormalizedValue::ConfidenceHigh
        }
        MemberLearningLabel::Keep => SmartCoreHeadBucketNormalizedValue::ConfidenceMedium,
        MemberLearningLabel::Penalize
        | MemberLearningLabel::CalibrateDown
        | MemberLearningLabel::NeedMoreEvidence => {
            SmartCoreHeadBucketNormalizedValue::ConfidenceLow
        }
    }
}

fn risk_target_from_hint(risk_hint: f64) -> SmartCoreHeadBucketNormalizedValue {
    if risk_hint >= 0.65 {
        SmartCoreHeadBucketNormalizedValue::RiskHigh
    } else if risk_hint >= 0.25 {
        SmartCoreHeadBucketNormalizedValue::RiskMedium
    } else {
        SmartCoreHeadBucketNormalizedValue::RiskLow
    }
}

fn risk_target_from_label(label: &str) -> SmartCoreHeadBucketNormalizedValue {
    let normalized = label.to_ascii_lowercase();
    if normalized.contains("veto") || normalized.contains("blocked") || normalized.contains("high")
    {
        SmartCoreHeadBucketNormalizedValue::RiskHigh
    } else if normalized.contains("review")
        || normalized.contains("warning")
        || normalized.contains("medium")
    {
        SmartCoreHeadBucketNormalizedValue::RiskMedium
    } else if normalized.contains("passed")
        || normalized.contains("low")
        || normalized.contains("safe")
    {
        SmartCoreHeadBucketNormalizedValue::RiskLow
    } else {
        SmartCoreHeadBucketNormalizedValue::Unknown
    }
}

fn risk_target_from_status(status: RiskGovernorStatus) -> SmartCoreHeadBucketNormalizedValue {
    match status {
        RiskGovernorStatus::Passed => SmartCoreHeadBucketNormalizedValue::RiskLow,
        RiskGovernorStatus::NeedsReview => SmartCoreHeadBucketNormalizedValue::RiskMedium,
        RiskGovernorStatus::Vetoed => SmartCoreHeadBucketNormalizedValue::RiskHigh,
    }
}

fn evidence_target_from_label(label: &str) -> SmartCoreHeadBucketNormalizedValue {
    let normalized = label.to_ascii_lowercase();
    if normalized.contains("sufficient") {
        SmartCoreHeadBucketNormalizedValue::EvidenceSufficient
    } else if normalized.contains("need")
        || normalized.contains("pending")
        || normalized.contains("review")
    {
        SmartCoreHeadBucketNormalizedValue::NeedMoreEvidence
    } else {
        SmartCoreHeadBucketNormalizedValue::Unknown
    }
}

fn evidence_target_from_opinion(opinion: &MemberOpinion) -> SmartCoreHeadBucketNormalizedValue {
    if opinion.stance == MemberStance::NeedMoreEvidence
        || opinion
            .evidence_notes
            .iter()
            .any(|note| note.to_ascii_lowercase().contains("evidence"))
    {
        SmartCoreHeadBucketNormalizedValue::NeedMoreEvidence
    } else {
        SmartCoreHeadBucketNormalizedValue::EvidenceSufficient
    }
}

fn outcome_target_from_member_outcome(
    outcome: MemberExperienceOutcome,
) -> SmartCoreHeadBucketNormalizedValue {
    match outcome {
        MemberExperienceOutcome::PaperPositive
        | MemberExperienceOutcome::HelpfulDissent
        | MemberExperienceOutcome::MissedOpportunity => {
            SmartCoreHeadBucketNormalizedValue::PositiveLike
        }
        MemberExperienceOutcome::PaperNeutral => SmartCoreHeadBucketNormalizedValue::NeutralLike,
        MemberExperienceOutcome::PaperNegative
        | MemberExperienceOutcome::RiskVetoSavedLoss
        | MemberExperienceOutcome::BadRiskCall => SmartCoreHeadBucketNormalizedValue::NegativeLike,
        MemberExperienceOutcome::Unknown => SmartCoreHeadBucketNormalizedValue::Unknown,
    }
}

fn majority_shadow_bucket(
    values: impl IntoIterator<Item = SmartCoreHeadBucketNormalizedValue>,
) -> Option<SmartCoreHeadBucketNormalizedValue> {
    let mut counts = std::collections::BTreeMap::new();
    for value in values {
        *counts.entry(value).or_insert(0usize) += 1;
    }
    counts
        .into_iter()
        .max_by(|(left_value, left_count), (right_value, right_count)| {
            left_count
                .cmp(right_count)
                .then_with(|| left_value.cmp(right_value))
        })
        .map(|(value, _)| value)
}

fn maybe_only_symbol(values: impl IntoIterator<Item = String>) -> Option<String> {
    let mut iter = values.into_iter();
    let first = iter.next()?;
    if iter.all(|value| value == first) {
        Some(first)
    } else {
        None
    }
}

fn maybe_only_market_scope(values: impl IntoIterator<Item = MarketScope>) -> Option<MarketScope> {
    let mut iter = values.into_iter();
    let first = iter.next()?;
    if iter.all(|value| value == first) {
        Some(first)
    } else {
        None
    }
}

pub fn build_shadow_alignment_targets_from_batch_cycle(
    batch_result: &BatchCommitteeCycleResult,
) -> Vec<SmartCoreShadowAlignmentTarget> {
    let mut targets = Vec::new();
    let mut opinions_by_member: std::collections::BTreeMap<String, Vec<&MemberOpinion>> =
        std::collections::BTreeMap::new();
    for opinion in &batch_result.member_opinions {
        opinions_by_member
            .entry(opinion.member_id.clone())
            .or_default()
            .push(opinion);
    }
    for (member_id, opinions) in opinions_by_member {
        targets.push(SmartCoreShadowAlignmentTarget {
            target_id: format!("{}-member-opinion-{member_id}", batch_result.batch_id),
            member_id: member_id.clone(),
            symbol: maybe_only_symbol(opinions.iter().map(|opinion| opinion.symbol.clone())),
            market_scope: maybe_only_market_scope(
                opinions.iter().map(|opinion| opinion.market_scope),
            ),
            source_type: SmartCoreShadowAlignmentTargetSourceType::MemberOpinion,
            stance_target: majority_shadow_bucket(
                opinions
                    .iter()
                    .filter_map(|opinion| member_stance_shadow_target(opinion.stance)),
            ),
            risk_target: majority_shadow_bucket(
                opinions
                    .iter()
                    .map(|opinion| risk_target_from_hint(opinion.risk_hint)),
            ),
            evidence_target: majority_shadow_bucket(
                opinions
                    .iter()
                    .map(|opinion| evidence_target_from_opinion(opinion)),
            ),
            confidence_target: majority_shadow_bucket(
                opinions
                    .iter()
                    .map(|opinion| confidence_target_from_score(opinion.confidence)),
            ),
            outcome_target: None,
            paper_only: true,
        });
    }
    let mut risk_targets_by_member: std::collections::BTreeMap<
        String,
        Vec<(
            Option<String>,
            Option<MarketScope>,
            SmartCoreHeadBucketNormalizedValue,
        )>,
    > = std::collections::BTreeMap::new();
    for opinion in &batch_result.member_opinions {
        for decision in &batch_result.chairman_decisions {
            let related_symbol = batch_result
                .committee_sessions
                .iter()
                .find(|session| session.session_id == decision.session_id)
                .map(|session| (session.event.symbol.clone(), session.event.market_scope));
            if let Some((symbol, market_scope)) = related_symbol {
                if symbol == opinion.symbol && market_scope == opinion.market_scope {
                    risk_targets_by_member
                        .entry(opinion.member_id.clone())
                        .or_default()
                        .push((
                            Some(symbol),
                            Some(market_scope),
                            risk_target_from_status(decision.risk_governor_status),
                        ));
                }
            }
        }
    }
    for (member_id, targets_for_member) in risk_targets_by_member {
        targets.push(SmartCoreShadowAlignmentTarget {
            target_id: format!("{}-risk-governor-{member_id}", batch_result.batch_id),
            member_id,
            symbol: maybe_only_symbol(
                targets_for_member
                    .iter()
                    .filter_map(|(symbol, _, _)| symbol.clone()),
            ),
            market_scope: maybe_only_market_scope(
                targets_for_member.iter().filter_map(|(_, scope, _)| *scope),
            ),
            source_type: SmartCoreShadowAlignmentTargetSourceType::RiskGovernorStatus,
            stance_target: None,
            risk_target: majority_shadow_bucket(
                targets_for_member.iter().map(|(_, _, value)| *value),
            ),
            evidence_target: if targets_for_member.iter().any(|(_, _, value)| {
                *value == SmartCoreHeadBucketNormalizedValue::RiskHigh
                    || *value == SmartCoreHeadBucketNormalizedValue::RiskMedium
            }) {
                Some(SmartCoreHeadBucketNormalizedValue::NeedMoreEvidence)
            } else {
                Some(SmartCoreHeadBucketNormalizedValue::EvidenceSufficient)
            },
            confidence_target: None,
            outcome_target: None,
            paper_only: true,
        });
    }
    targets
}

pub fn build_shadow_alignment_targets_from_replay_dataset(
    dataset: &ReplayDataset,
) -> Vec<SmartCoreShadowAlignmentTarget> {
    let mut examples_by_member: std::collections::BTreeMap<String, Vec<&ReplayExample>> =
        std::collections::BTreeMap::new();
    for example in &dataset.examples {
        examples_by_member
            .entry(example.member_id.clone())
            .or_default()
            .push(example);
    }
    examples_by_member
        .into_iter()
        .map(|(member_id, examples)| {
            let stance_target = majority_shadow_bucket(examples.iter().filter_map(|example| {
                example
                    .target_labels
                    .as_ref()
                    .map(|labels| labels.stance_target)
                    .or(Some(example.target.stance))
                    .and_then(member_stance_shadow_target)
            }));
            let confidence_target = majority_shadow_bucket(examples.iter().map(|example| {
                example
                    .target_labels
                    .as_ref()
                    .map(|labels| {
                        confidence_target_from_learning_label(labels.confidence_calibration_target)
                    })
                    .unwrap_or_else(|| {
                        confidence_target_from_learning_label(example.target.confidence_calibration)
                    })
            }));
            let risk_target = majority_shadow_bucket(examples.iter().map(|example| {
                example
                    .target_labels
                    .as_ref()
                    .map(|labels| risk_target_from_label(&labels.risk_label))
                    .unwrap_or_else(|| risk_target_from_label(&example.target.risk_label))
            }));
            let evidence_target = majority_shadow_bucket(examples.iter().map(|example| {
                example
                    .target_labels
                    .as_ref()
                    .map(|labels| evidence_target_from_label(&labels.evidence_label))
                    .unwrap_or_else(|| evidence_target_from_label(&example.target.evidence_label))
            }));
            let outcome_target = majority_shadow_bucket(examples.iter().map(|example| {
                example
                    .target_labels
                    .as_ref()
                    .map(|labels| outcome_target_from_member_outcome(labels.outcome_label))
                    .unwrap_or_else(|| {
                        outcome_target_from_member_outcome(example.target.outcome_label)
                    })
            }));
            SmartCoreShadowAlignmentTarget {
                target_id: format!("{}-replay-target-{member_id}", dataset.dataset_id),
                member_id,
                symbol: maybe_only_symbol(examples.iter().map(|example| example.symbol.clone())),
                market_scope: maybe_only_market_scope(
                    examples.iter().map(|example| example.market_scope),
                ),
                source_type: SmartCoreShadowAlignmentTargetSourceType::ReplayTargetLabel,
                stance_target,
                risk_target,
                evidence_target,
                confidence_target,
                outcome_target,
                paper_only: true,
            }
        })
        .collect()
}

pub fn build_shadow_alignment_targets_from_owner_summary(
    summary: &OwnerCommitteeSummary,
) -> Vec<SmartCoreShadowAlignmentTarget> {
    let mut member_ids = summary.top_supporting_members.clone();
    member_ids.extend(summary.top_dissenting_members.clone());
    member_ids.sort();
    member_ids.dedup();
    let stance_target = summary
        .chairman_actions
        .iter()
        .rev()
        .find_map(|action| match action {
            ChairmanFinalAction::PaperBuy => Some(SmartCoreHeadBucketNormalizedValue::PositiveLike),
            ChairmanFinalAction::PaperSell | ChairmanFinalAction::PaperNoTrade => {
                Some(SmartCoreHeadBucketNormalizedValue::NegativeLike)
            }
            ChairmanFinalAction::PaperHold => Some(SmartCoreHeadBucketNormalizedValue::NeutralLike),
            ChairmanFinalAction::NeedMoreEvidence | ChairmanFinalAction::RiskVetoed => None,
        });
    member_ids
        .into_iter()
        .map(|member_id| SmartCoreShadowAlignmentTarget {
            target_id: format!("{}-owner-summary-{member_id}", summary.cycle_id),
            member_id,
            symbol: None,
            market_scope: None,
            source_type: SmartCoreShadowAlignmentTargetSourceType::ChairmanDecision,
            stance_target,
            risk_target: (summary.risk_veto_count > 0)
                .then_some(SmartCoreHeadBucketNormalizedValue::RiskHigh),
            evidence_target: (summary.need_more_evidence_count > 0)
                .then_some(SmartCoreHeadBucketNormalizedValue::NeedMoreEvidence),
            confidence_target: None,
            outcome_target: None,
            paper_only: true,
        })
        .collect()
}

pub fn normalize_smartcore_head_bucket(
    head: SmartCoreShadowHeadKind,
    source_bucket: impl Into<String>,
) -> SmartCoreHeadBucketNormalized {
    let source_bucket = source_bucket.into();
    let normalized_value = match (head, source_bucket.as_str()) {
        (SmartCoreShadowHeadKind::Stance, "BuyLike") => {
            SmartCoreHeadBucketNormalizedValue::PositiveLike
        }
        (SmartCoreShadowHeadKind::Stance, "HoldLike") => {
            SmartCoreHeadBucketNormalizedValue::NeutralLike
        }
        (SmartCoreShadowHeadKind::Stance, "NoTradeLike") => {
            SmartCoreHeadBucketNormalizedValue::NegativeLike
        }
        (SmartCoreShadowHeadKind::Risk, "LowRisk") => SmartCoreHeadBucketNormalizedValue::RiskLow,
        (SmartCoreShadowHeadKind::Risk, "MediumRisk") => {
            SmartCoreHeadBucketNormalizedValue::RiskMedium
        }
        (SmartCoreShadowHeadKind::Risk, "HighRisk") => SmartCoreHeadBucketNormalizedValue::RiskHigh,
        (SmartCoreShadowHeadKind::EvidenceNeed, "EvidenceSufficient") => {
            SmartCoreHeadBucketNormalizedValue::EvidenceSufficient
        }
        (SmartCoreShadowHeadKind::EvidenceNeed, "NeedMoreEvidence") => {
            SmartCoreHeadBucketNormalizedValue::NeedMoreEvidence
        }
        (SmartCoreShadowHeadKind::ConfidenceCalibration, "LowConfidence") => {
            SmartCoreHeadBucketNormalizedValue::ConfidenceLow
        }
        (SmartCoreShadowHeadKind::ConfidenceCalibration, "MediumConfidence") => {
            SmartCoreHeadBucketNormalizedValue::ConfidenceMedium
        }
        (SmartCoreShadowHeadKind::ConfidenceCalibration, "HighConfidence") => {
            SmartCoreHeadBucketNormalizedValue::ConfidenceHigh
        }
        (SmartCoreShadowHeadKind::Uncertainty, "LowUncertainty") => {
            SmartCoreHeadBucketNormalizedValue::ConfidenceHigh
        }
        (SmartCoreShadowHeadKind::Uncertainty, "MediumUncertainty") => {
            SmartCoreHeadBucketNormalizedValue::ConfidenceMedium
        }
        (SmartCoreShadowHeadKind::Uncertainty, "HighUncertainty") => {
            SmartCoreHeadBucketNormalizedValue::ConfidenceLow
        }
        (SmartCoreShadowHeadKind::ExpectedReturnHint, "PositiveHint") => {
            SmartCoreHeadBucketNormalizedValue::PositiveLike
        }
        (SmartCoreShadowHeadKind::ExpectedReturnHint, "NeutralHint") => {
            SmartCoreHeadBucketNormalizedValue::NeutralLike
        }
        (SmartCoreShadowHeadKind::ExpectedReturnHint, "NegativeHint") => {
            SmartCoreHeadBucketNormalizedValue::NegativeLike
        }
        (SmartCoreShadowHeadKind::ExpectedReturnHint, "Deferred") => {
            SmartCoreHeadBucketNormalizedValue::Deferred
        }
        _ => SmartCoreHeadBucketNormalizedValue::Unknown,
    };
    SmartCoreHeadBucketNormalized {
        head,
        normalized_value,
        source_bucket,
        paper_only: true,
    }
}

fn normalized_shadow_buckets_from_debug_output(
    output: &SmartCoreDebugOutputV0,
) -> std::collections::BTreeMap<SmartCoreShadowHeadKind, SmartCoreHeadBucketNormalized> {
    let mut buckets = std::collections::BTreeMap::new();
    if let Some(head) = output.stance_head.as_ref() {
        buckets.insert(
            SmartCoreShadowHeadKind::Stance,
            normalize_smartcore_head_bucket(
                SmartCoreShadowHeadKind::Stance,
                format!("{:?}", head.bucket),
            ),
        );
    }
    if let Some(head) = output.risk_head.as_ref() {
        buckets.insert(
            SmartCoreShadowHeadKind::Risk,
            normalize_smartcore_head_bucket(
                SmartCoreShadowHeadKind::Risk,
                format!("{:?}", head.bucket),
            ),
        );
    }
    if let Some(head) = output.evidence_need_head.as_ref() {
        buckets.insert(
            SmartCoreShadowHeadKind::EvidenceNeed,
            normalize_smartcore_head_bucket(
                SmartCoreShadowHeadKind::EvidenceNeed,
                format!("{:?}", head.bucket),
            ),
        );
    }
    if let Some(head) = output.confidence_calibration_head.as_ref() {
        buckets.insert(
            SmartCoreShadowHeadKind::ConfidenceCalibration,
            normalize_smartcore_head_bucket(
                SmartCoreShadowHeadKind::ConfidenceCalibration,
                format!("{:?}", head.bucket),
            ),
        );
    }
    if let Some(head) = output.uncertainty_head.as_ref() {
        buckets.insert(
            SmartCoreShadowHeadKind::Uncertainty,
            normalize_smartcore_head_bucket(
                SmartCoreShadowHeadKind::Uncertainty,
                format!("{:?}", head.bucket),
            ),
        );
    }
    if let Some(head) = output.expected_return_head.as_ref() {
        buckets.insert(
            SmartCoreShadowHeadKind::ExpectedReturnHint,
            normalize_smartcore_head_bucket(
                SmartCoreShadowHeadKind::ExpectedReturnHint,
                format!("{:?}", head.bucket),
            ),
        );
    }
    buckets
}

fn compare_shadow_bucket(
    actual: Option<&SmartCoreHeadBucketNormalized>,
    expected: Option<SmartCoreHeadBucketNormalizedValue>,
) -> SmartCoreShadowAlignmentStatus {
    match expected {
        None => SmartCoreShadowAlignmentStatus::Unknown,
        Some(expected) => match actual {
            None => SmartCoreShadowAlignmentStatus::Deferred,
            Some(actual)
                if actual.normalized_value == SmartCoreHeadBucketNormalizedValue::Deferred =>
            {
                SmartCoreShadowAlignmentStatus::Deferred
            }
            Some(actual) if actual.normalized_value == expected => {
                SmartCoreShadowAlignmentStatus::Match
            }
            Some(actual)
                if actual.normalized_value == SmartCoreHeadBucketNormalizedValue::Unknown
                    || expected == SmartCoreHeadBucketNormalizedValue::Unknown =>
            {
                SmartCoreShadowAlignmentStatus::Unknown
            }
            Some(_) => SmartCoreShadowAlignmentStatus::Mismatch,
        },
    }
}

pub fn compare_smartcore_debug_output_to_target(
    debug_output: &SmartCoreDebugOutputV0,
    target: &SmartCoreShadowAlignmentTarget,
) -> SmartCoreShadowAlignmentRecord {
    let normalized = normalized_shadow_buckets_from_debug_output(debug_output);
    let mut mismatch_reasons = Vec::new();
    let mut normalized_debug_buckets = std::collections::BTreeMap::new();
    let mut normalized_target_values = std::collections::BTreeMap::new();
    let compare_head =
        |head: SmartCoreShadowHeadKind,
         expected: Option<SmartCoreHeadBucketNormalizedValue>,
         mismatch_reasons: &mut Vec<String>,
         normalized_debug_buckets: &mut std::collections::BTreeMap<String, String>,
         normalized_target_values: &mut std::collections::BTreeMap<String, String>| {
            let actual = normalized.get(&head);
            if let Some(actual) = actual {
                normalized_debug_buckets.insert(
                    smartcore_shadow_head_key(head).to_string(),
                    normalized_bucket_label(actual.normalized_value),
                );
            }
            if let Some(expected) = expected {
                normalized_target_values.insert(
                    smartcore_shadow_head_key(head).to_string(),
                    normalized_bucket_label(expected),
                );
            }
            let status = compare_shadow_bucket(actual, expected);
            if matches!(status, SmartCoreShadowAlignmentStatus::Mismatch) {
                mismatch_reasons.push(format!(
                    "{}:{}!={}",
                    smartcore_shadow_head_key(head),
                    actual
                        .map(|value| normalized_bucket_label(value.normalized_value))
                        .unwrap_or_else(|| "Deferred".to_string()),
                    expected
                        .map(normalized_bucket_label)
                        .unwrap_or_else(|| "Unknown".to_string())
                ));
            }
            status
        };
    let stance_alignment = compare_head(
        SmartCoreShadowHeadKind::Stance,
        target.stance_target,
        &mut mismatch_reasons,
        &mut normalized_debug_buckets,
        &mut normalized_target_values,
    );
    let risk_alignment = compare_head(
        SmartCoreShadowHeadKind::Risk,
        target.risk_target,
        &mut mismatch_reasons,
        &mut normalized_debug_buckets,
        &mut normalized_target_values,
    );
    let evidence_alignment = compare_head(
        SmartCoreShadowHeadKind::EvidenceNeed,
        target.evidence_target,
        &mut mismatch_reasons,
        &mut normalized_debug_buckets,
        &mut normalized_target_values,
    );
    let confidence_alignment = compare_head(
        SmartCoreShadowHeadKind::ConfidenceCalibration,
        target.confidence_target,
        &mut mismatch_reasons,
        &mut normalized_debug_buckets,
        &mut normalized_target_values,
    );
    SmartCoreShadowAlignmentRecord {
        alignment_id: format!("{}-{}", debug_output.debug_output_id, target.target_id),
        member_id: debug_output.member_id.clone(),
        debug_output_id: debug_output.debug_output_id.clone(),
        target_id: Some(target.target_id.clone()),
        symbol: target.symbol.clone(),
        market_scope: target.market_scope,
        stance_alignment,
        risk_alignment,
        evidence_alignment,
        confidence_alignment,
        mismatch_reasons,
        normalized_debug_buckets,
        normalized_target_values,
        debug_only: true,
        not_decision_input: true,
        paper_only: true,
    }
}

fn per_member_alignment_status(
    summary: &PerMemberShadowAlignmentSummary,
) -> SmartCoreShadowAlignmentSummaryStatus {
    let total_matches = summary.stance_match_count
        + summary.risk_match_count
        + summary.evidence_match_count
        + summary.confidence_match_count;
    if summary.record_count == 0 {
        SmartCoreShadowAlignmentSummaryStatus::InsufficientTargets
    } else if summary.mismatch_count == 0 && total_matches == 0 {
        SmartCoreShadowAlignmentSummaryStatus::DebugOnly
    } else if summary.mismatch_count == 0 {
        SmartCoreShadowAlignmentSummaryStatus::Aligned
    } else if summary.mismatch_count < total_matches.max(1) {
        SmartCoreShadowAlignmentSummaryStatus::PartiallyAligned
    } else {
        SmartCoreShadowAlignmentSummaryStatus::MostlyMismatched
    }
}

pub fn summarize_smartcore_shadow_alignment(
    records: &[SmartCoreShadowAlignmentRecord],
) -> SmartCoreShadowAlignmentSummary {
    let count_alignment_status =
        |selector: fn(&SmartCoreShadowAlignmentRecord) -> SmartCoreShadowAlignmentStatus,
         wanted: SmartCoreShadowAlignmentStatus| {
            records.iter().filter(|row| selector(row) == wanted).count()
        };
    let mut per_member_records: std::collections::BTreeMap<
        String,
        Vec<&SmartCoreShadowAlignmentRecord>,
    > = std::collections::BTreeMap::new();
    for record in records {
        per_member_records
            .entry(record.member_id.clone())
            .or_default()
            .push(record);
    }
    let per_member_summary: Vec<_> = per_member_records
        .into_iter()
        .map(|(member_id, rows)| {
            let stance_mismatches = rows
                .iter()
                .filter(|row| {
                    matches!(
                        row.stance_alignment,
                        SmartCoreShadowAlignmentStatus::Mismatch
                    )
                })
                .count();
            let risk_mismatches = rows
                .iter()
                .filter(|row| {
                    matches!(row.risk_alignment, SmartCoreShadowAlignmentStatus::Mismatch)
                })
                .count();
            let evidence_mismatches = rows
                .iter()
                .filter(|row| {
                    matches!(
                        row.evidence_alignment,
                        SmartCoreShadowAlignmentStatus::Mismatch
                    )
                })
                .count();
            let confidence_mismatches = rows
                .iter()
                .filter(|row| {
                    matches!(
                        row.confidence_alignment,
                        SmartCoreShadowAlignmentStatus::Mismatch
                    )
                })
                .count();
            let mismatch_count =
                stance_mismatches + risk_mismatches + evidence_mismatches + confidence_mismatches;
            let suggested_next_core_data = if mismatch_count == 0 {
                SmartCoreShadowSuggestedNextCoreData::KeepObserving
            } else if risk_mismatches >= stance_mismatches
                && risk_mismatches >= evidence_mismatches
                && risk_mismatches >= confidence_mismatches
            {
                SmartCoreShadowSuggestedNextCoreData::MoreRiskLabels
            } else if evidence_mismatches >= stance_mismatches
                && evidence_mismatches >= confidence_mismatches
            {
                SmartCoreShadowSuggestedNextCoreData::MoreEvidenceLabels
            } else if confidence_mismatches >= stance_mismatches {
                SmartCoreShadowSuggestedNextCoreData::MoreConfidenceCalibrationLabels
            } else {
                SmartCoreShadowSuggestedNextCoreData::MoreStanceLabels
            };
            PerMemberShadowAlignmentSummary {
                member_id,
                record_count: rows.len(),
                stance_match_count: rows
                    .iter()
                    .filter(|row| {
                        matches!(row.stance_alignment, SmartCoreShadowAlignmentStatus::Match)
                    })
                    .count(),
                risk_match_count: rows
                    .iter()
                    .filter(|row| {
                        matches!(row.risk_alignment, SmartCoreShadowAlignmentStatus::Match)
                    })
                    .count(),
                evidence_match_count: rows
                    .iter()
                    .filter(|row| {
                        matches!(
                            row.evidence_alignment,
                            SmartCoreShadowAlignmentStatus::Match
                        )
                    })
                    .count(),
                confidence_match_count: rows
                    .iter()
                    .filter(|row| {
                        matches!(
                            row.confidence_alignment,
                            SmartCoreShadowAlignmentStatus::Match
                        )
                    })
                    .count(),
                mismatch_count,
                suggested_next_core_data,
                paper_only: true,
            }
        })
        .collect();
    let per_head_summary = vec![
        (
            SmartCoreShadowHeadKind::Stance,
            (|row: &SmartCoreShadowAlignmentRecord| row.stance_alignment)
                as fn(&SmartCoreShadowAlignmentRecord) -> SmartCoreShadowAlignmentStatus,
        ),
        (
            SmartCoreShadowHeadKind::Risk,
            (|row: &SmartCoreShadowAlignmentRecord| row.risk_alignment)
                as fn(&SmartCoreShadowAlignmentRecord) -> SmartCoreShadowAlignmentStatus,
        ),
        (
            SmartCoreShadowHeadKind::EvidenceNeed,
            (|row: &SmartCoreShadowAlignmentRecord| row.evidence_alignment)
                as fn(&SmartCoreShadowAlignmentRecord) -> SmartCoreShadowAlignmentStatus,
        ),
        (
            SmartCoreShadowHeadKind::ConfidenceCalibration,
            (|row: &SmartCoreShadowAlignmentRecord| row.confidence_alignment)
                as fn(&SmartCoreShadowAlignmentRecord) -> SmartCoreShadowAlignmentStatus,
        ),
    ]
    .into_iter()
    .map(|(head, selector)| PerHeadShadowAlignmentSummary {
        head,
        match_count: count_alignment_status(selector, SmartCoreShadowAlignmentStatus::Match),
        mismatch_count: count_alignment_status(selector, SmartCoreShadowAlignmentStatus::Mismatch),
        unknown_count: count_alignment_status(selector, SmartCoreShadowAlignmentStatus::Unknown),
        deferred_count: count_alignment_status(selector, SmartCoreShadowAlignmentStatus::Deferred),
        paper_only: true,
    })
    .collect::<Vec<_>>();
    let mismatch_count = per_head_summary
        .iter()
        .map(|summary| summary.mismatch_count)
        .sum();
    let unknown_count = per_head_summary
        .iter()
        .map(|summary| summary.unknown_count)
        .sum();
    let deferred_count = per_head_summary
        .iter()
        .map(|summary| summary.deferred_count)
        .sum();
    let total_match_count: usize = per_head_summary
        .iter()
        .map(|summary| summary.match_count)
        .sum();
    let alignment_status = if records.is_empty() {
        SmartCoreShadowAlignmentSummaryStatus::InsufficientTargets
    } else if mismatch_count == 0 && total_match_count == 0 {
        SmartCoreShadowAlignmentSummaryStatus::DebugOnly
    } else if mismatch_count == 0 {
        SmartCoreShadowAlignmentSummaryStatus::Aligned
    } else if mismatch_count < total_match_count.max(1) {
        SmartCoreShadowAlignmentSummaryStatus::PartiallyAligned
    } else {
        SmartCoreShadowAlignmentSummaryStatus::MostlyMismatched
    };
    SmartCoreShadowAlignmentSummary {
        summary_id: format!("smartcore-shadow-summary-{}", records.len()),
        record_count: records.len(),
        member_count: per_member_summary.len(),
        per_member_summary,
        per_head_summary,
        mismatch_count,
        unknown_count,
        deferred_count,
        alignment_status,
        paper_only: true,
    }
}

pub fn build_smartcore_shadow_mismatch_records(
    alignment_records: &[SmartCoreShadowAlignmentRecord],
) -> Vec<SmartCoreShadowMismatchRecord> {
    let mut records = Vec::new();
    for record in alignment_records {
        for head in [
            SmartCoreShadowHeadKind::Stance,
            SmartCoreShadowHeadKind::Risk,
            SmartCoreShadowHeadKind::EvidenceNeed,
            SmartCoreShadowHeadKind::ConfidenceCalibration,
        ] {
            let key = smartcore_shadow_head_key(head);
            let Some(debug_bucket) = record.normalized_debug_buckets.get(key).cloned() else {
                continue;
            };
            let Some(target_value) = record.normalized_target_values.get(key).cloned() else {
                continue;
            };
            let status = match head {
                SmartCoreShadowHeadKind::Stance => record.stance_alignment,
                SmartCoreShadowHeadKind::Risk => record.risk_alignment,
                SmartCoreShadowHeadKind::EvidenceNeed => record.evidence_alignment,
                SmartCoreShadowHeadKind::ConfidenceCalibration => record.confidence_alignment,
                SmartCoreShadowHeadKind::Uncertainty
                | SmartCoreShadowHeadKind::ExpectedReturnHint => {
                    SmartCoreShadowAlignmentStatus::Deferred
                }
            };
            if !matches!(status, SmartCoreShadowAlignmentStatus::Mismatch) {
                continue;
            }
            let (mismatch_type, severity, suggested_data_need) = match head {
                SmartCoreShadowHeadKind::Stance => (
                    SmartCoreShadowMismatchType::StanceDisagreement,
                    SmartCoreShadowMismatchSeverity::Medium,
                    SmartCoreShadowSuggestedNextCoreData::MoreStanceLabels,
                ),
                SmartCoreShadowHeadKind::Risk
                    if debug_bucket == "RiskLow"
                        && (target_value == "RiskMedium" || target_value == "RiskHigh") =>
                {
                    (
                        SmartCoreShadowMismatchType::RiskUnderestimation,
                        if target_value == "RiskHigh" {
                            SmartCoreShadowMismatchSeverity::High
                        } else {
                            SmartCoreShadowMismatchSeverity::Medium
                        },
                        SmartCoreShadowSuggestedNextCoreData::MoreRiskLabels,
                    )
                }
                SmartCoreShadowHeadKind::Risk => (
                    SmartCoreShadowMismatchType::RiskOverestimation,
                    SmartCoreShadowMismatchSeverity::Medium,
                    SmartCoreShadowSuggestedNextCoreData::MoreRiskLabels,
                ),
                SmartCoreShadowHeadKind::EvidenceNeed
                    if debug_bucket == "EvidenceSufficient"
                        && target_value == "NeedMoreEvidence" =>
                {
                    (
                        SmartCoreShadowMismatchType::EvidenceOverconfidence,
                        SmartCoreShadowMismatchSeverity::High,
                        SmartCoreShadowSuggestedNextCoreData::MoreEvidenceLabels,
                    )
                }
                SmartCoreShadowHeadKind::EvidenceNeed => (
                    SmartCoreShadowMismatchType::EvidenceUnderconfidence,
                    SmartCoreShadowMismatchSeverity::Medium,
                    SmartCoreShadowSuggestedNextCoreData::MoreEvidenceLabels,
                ),
                SmartCoreShadowHeadKind::ConfidenceCalibration
                    if debug_bucket == "ConfidenceHigh"
                        && (target_value == "ConfidenceLow"
                            || target_value == "ConfidenceMedium") =>
                {
                    (
                        SmartCoreShadowMismatchType::ConfidenceOverstatement,
                        SmartCoreShadowMismatchSeverity::Medium,
                        SmartCoreShadowSuggestedNextCoreData::MoreConfidenceCalibrationLabels,
                    )
                }
                SmartCoreShadowHeadKind::ConfidenceCalibration => (
                    SmartCoreShadowMismatchType::ConfidenceUnderstatement,
                    SmartCoreShadowMismatchSeverity::Medium,
                    SmartCoreShadowSuggestedNextCoreData::MoreConfidenceCalibrationLabels,
                ),
                SmartCoreShadowHeadKind::Uncertainty
                | SmartCoreShadowHeadKind::ExpectedReturnHint => (
                    SmartCoreShadowMismatchType::Unknown,
                    SmartCoreShadowMismatchSeverity::Low,
                    SmartCoreShadowSuggestedNextCoreData::KeepObserving,
                ),
            };
            records.push(SmartCoreShadowMismatchRecord {
                mismatch_id: format!("{}-{key}", record.alignment_id),
                member_id: record.member_id.clone(),
                head,
                debug_bucket,
                target_value,
                symbol: record.symbol.clone(),
                market_scope: record.market_scope,
                mismatch_type,
                severity,
                suggested_data_need,
                paper_only: true,
            });
        }
    }
    records
}

fn value_contains_debug_marker(value: &impl Serialize, debug_markers: &[String]) -> bool {
    serde_json::to_string(value)
        .map(|serialized| {
            debug_markers
                .iter()
                .any(|marker| serialized.contains(marker))
        })
        .unwrap_or(false)
}

fn value_debug_marker_count(value: &impl Serialize, marker: &str) -> usize {
    serde_json::to_string(value)
        .map(|serialized| serialized.matches(marker).count())
        .unwrap_or(0)
}

fn value_has_new_debug_marker(
    before: &impl Serialize,
    after: &impl Serialize,
    debug_markers: &[String],
) -> bool {
    debug_markers.iter().any(|marker| {
        value_debug_marker_count(after, marker) > value_debug_marker_count(before, marker)
    })
}

pub fn evaluate_smartcore_no_decision_bridge_guard(
    batch_result: &BatchCommitteeCycleResult,
    debug_output_batch: &SmartCoreDebugOutputBatchV0,
    _alignment_result: &SmartCoreShadowAlignmentRunResult,
) -> SmartCoreNoDecisionBridgeGuard {
    let debug_markers: Vec<String> = debug_output_batch
        .member_outputs
        .iter()
        .map(|output| output.debug_output_id.clone())
        .collect();
    let debug_output_used_as_member_opinion =
        value_contains_debug_marker(&batch_result.member_opinions, &debug_markers);
    let debug_output_used_in_committee_session =
        value_contains_debug_marker(&batch_result.committee_sessions, &debug_markers);
    let debug_output_used_in_chairman_decision =
        value_contains_debug_marker(&batch_result.chairman_decisions, &debug_markers);
    let debug_output_used_in_risk_governor =
        batch_result.chairman_decisions.iter().any(|decision| {
            decision.risk_governor_status != RiskGovernorStatus::Passed
                && value_contains_debug_marker(decision, &debug_markers)
        });
    let debug_output_used_as_trade_signal =
        value_contains_debug_marker(&batch_result.event_queue, &debug_markers);
    let debug_output_used_as_order = batch_result.chairman_decisions.iter().any(|decision| {
        matches!(
            decision.final_action,
            ChairmanFinalAction::PaperBuy | ChairmanFinalAction::PaperSell
        ) && value_contains_debug_marker(decision, &debug_markers)
    });
    let mut violations = Vec::new();
    if debug_output_used_as_member_opinion {
        violations.push("debug output leaked into member opinions".to_string());
    }
    if debug_output_used_in_committee_session {
        violations.push("debug output leaked into committee session".to_string());
    }
    if debug_output_used_in_chairman_decision {
        violations.push("debug output leaked into chairman decision".to_string());
    }
    if debug_output_used_in_risk_governor {
        violations.push("debug output leaked into risk governor path".to_string());
    }
    if debug_output_used_as_trade_signal {
        violations.push("debug output leaked into trade signal path".to_string());
    }
    if debug_output_used_as_order {
        violations.push("debug output leaked into order path".to_string());
    }
    SmartCoreNoDecisionBridgeGuard {
        guard_id: format!("{}-no-decision-bridge", batch_result.batch_id),
        debug_output_used_as_member_opinion,
        debug_output_used_in_committee_session,
        debug_output_used_in_chairman_decision,
        debug_output_used_in_risk_governor,
        debug_output_used_as_trade_signal,
        debug_output_used_as_order,
        guard_status: if violations.is_empty() {
            SmartCoreNoDecisionBridgeGuardStatus::Preserved
        } else {
            SmartCoreNoDecisionBridgeGuardStatus::Violated
        },
        violations,
        paper_only: true,
    }
}

pub fn build_owner_core_debug_section(
    debug_output_batch: &SmartCoreDebugOutputBatchV0,
    alignment_summary: &SmartCoreShadowAlignmentSummary,
) -> OwnerCoreDebugSection {
    let mut cards = debug_output_batch
        .member_outputs
        .iter()
        .map(|output| {
            let per_member = alignment_summary
                .per_member_summary
                .iter()
                .find(|summary| summary.member_id == output.member_id);
            let alignment_status = per_member
                .map(per_member_alignment_status)
                .unwrap_or(SmartCoreShadowAlignmentSummaryStatus::InsufficientTargets);
            OwnerCoreDebugCard {
                member_id: output.member_id.clone(),
                display_name: display_name_for_member_id(&output.member_id).to_string(),
                stance_bucket: output
                    .stance_head
                    .as_ref()
                    .map(|head| format!("{:?}", head.bucket))
                    .unwrap_or_else(|| "Unknown".to_string()),
                risk_bucket: output
                    .risk_head
                    .as_ref()
                    .map(|head| format!("{:?}", head.bucket))
                    .unwrap_or_else(|| "Unknown".to_string()),
                evidence_bucket: output
                    .evidence_need_head
                    .as_ref()
                    .map(|head| format!("{:?}", head.bucket))
                    .unwrap_or_else(|| "Unknown".to_string()),
                confidence_bucket: output
                    .confidence_calibration_head
                    .as_ref()
                    .map(|head| format!("{:?}", head.bucket))
                    .unwrap_or_else(|| "Unknown".to_string()),
                uncertainty_bucket: output
                    .uncertainty_head
                    .as_ref()
                    .map(|head| format!("{:?}", head.bucket)),
                expected_return_bucket: output
                    .expected_return_head
                    .as_ref()
                    .map(|head| format!("{:?}", head.bucket)),
                alignment_status,
                mismatch_count: per_member
                    .map(|summary| summary.mismatch_count)
                    .unwrap_or(0),
                debug_only: true,
                not_investment_signal: true,
                not_committee_opinion: true,
                paper_only: true,
            }
        })
        .collect::<Vec<_>>();
    cards.sort_by(|left, right| left.member_id.cmp(&right.member_id));
    OwnerCoreDebugSection {
        section_id: format!("{}-owner-core-debug", debug_output_batch.batch_id),
        summary: format!(
            "alignment={:?}, targets={}, mismatches={}, cards={}",
            alignment_summary.alignment_status,
            alignment_summary.record_count,
            alignment_summary.mismatch_count,
            cards.len()
        ),
        cards,
        paper_only_warning:
            "core debug cards are paper-only diagnostics; not investment advice, not trading, not orders"
                .to_string(),
        debug_only_warning:
            "debug cards are read-only shadow evaluation and must not feed member opinions or committee decisions"
                .to_string(),
        calibration_summary: None,
        recalibration_summary: None,
        shadow_opinion_summary: None,
        shadow_stability_summary: None,
        shadow_scenario_sweep_summary: None,
        observer_section: None,
        observer_coverage_closure_summary: None,
        observer_trend_summary: None,
        observer_seeded_target_summary: None,
        observer_apply_readiness_summary: None,
        paper_only: true,
    }
}

pub fn run_smartcore_shadow_alignment(
    debug_output_batch: &SmartCoreDebugOutputBatchV0,
    batch_result: &BatchCommitteeCycleResult,
    replay_dataset: Option<&ReplayDataset>,
    config: &SmartCoreShadowAlignmentRunConfig,
) -> Result<SmartCoreShadowAlignmentRunResult, String> {
    if !config.paper_only {
        return Err("smartcore shadow alignment must remain paper-only".to_string());
    }
    let batch_targets = build_shadow_alignment_targets_from_batch_cycle(batch_result);
    let mut targets = Vec::new();
    if config.include_batch_member_opinions {
        targets.extend(
            batch_targets
                .iter()
                .filter(|target| {
                    matches!(
                        target.source_type,
                        SmartCoreShadowAlignmentTargetSourceType::MemberOpinion
                    )
                })
                .cloned(),
        );
    }
    if config.include_risk_governor_targets {
        targets.extend(
            batch_targets
                .iter()
                .filter(|target| {
                    matches!(
                        target.source_type,
                        SmartCoreShadowAlignmentTargetSourceType::RiskGovernorStatus
                    )
                })
                .cloned(),
        );
    }
    if config.include_replay_targets {
        if let Some(replay_dataset) = replay_dataset {
            targets.extend(build_shadow_alignment_targets_from_replay_dataset(
                replay_dataset,
            ));
        }
    }
    let alignment_records = debug_output_batch
        .member_outputs
        .iter()
        .flat_map(|debug_output| {
            targets
                .iter()
                .filter(move |target| target.member_id == debug_output.member_id)
                .map(move |target| compare_smartcore_debug_output_to_target(debug_output, target))
        })
        .collect::<Vec<_>>();
    let alignment_summary = summarize_smartcore_shadow_alignment(&alignment_records);
    let mismatch_records = build_smartcore_shadow_mismatch_records(&alignment_records);
    let provisional = SmartCoreShadowAlignmentRunResult {
        run_id: config.run_id.clone(),
        target_count: targets.len(),
        alignment_records,
        alignment_status: alignment_summary.alignment_status,
        mismatch_count: mismatch_records.len(),
        no_decision_bridge_guard: SmartCoreNoDecisionBridgeGuard {
            guard_id: format!("{}-pending-guard", config.run_id),
            debug_output_used_as_member_opinion: false,
            debug_output_used_in_committee_session: false,
            debug_output_used_in_chairman_decision: false,
            debug_output_used_in_risk_governor: false,
            debug_output_used_as_trade_signal: false,
            debug_output_used_as_order: false,
            guard_status: SmartCoreNoDecisionBridgeGuardStatus::Preserved,
            violations: Vec::new(),
            paper_only: true,
        },
        no_decision_bridge_guard_status: SmartCoreNoDecisionBridgeGuardStatus::Preserved,
        owner_core_debug_section: None,
        owner_core_debug_card_count: 0,
        run_status: SmartCoreShadowAlignmentRunStatus::Passed,
        warnings: Vec::new(),
        debug_only: true,
        not_investment_signal: true,
        not_committee_opinion: true,
        paper_only_warning:
            "shadow alignment is paper-only diagnostics; it does not change committee decisions or trading"
                .to_string(),
        paper_only: true,
        alignment_summary,
        mismatch_records,
    };
    let no_decision_bridge_guard =
        evaluate_smartcore_no_decision_bridge_guard(batch_result, debug_output_batch, &provisional);
    let owner_core_debug_section = config.emit_owner_core_debug_cards.then(|| {
        build_owner_core_debug_section(debug_output_batch, &provisional.alignment_summary)
    });
    let mut warnings = Vec::new();
    if provisional.target_count == 0 {
        warnings.push("shadow alignment had no comparable targets".to_string());
    }
    if provisional.mismatch_count > 0 {
        warnings.push(format!(
            "shadow alignment found {} mismatches",
            provisional.mismatch_count
        ));
    }
    let run_status = if matches!(
        no_decision_bridge_guard.guard_status,
        SmartCoreNoDecisionBridgeGuardStatus::Violated
    ) {
        SmartCoreShadowAlignmentRunStatus::Failed
    } else if warnings.is_empty() {
        SmartCoreShadowAlignmentRunStatus::Passed
    } else {
        SmartCoreShadowAlignmentRunStatus::PassedWithWarnings
    };
    let result = SmartCoreShadowAlignmentRunResult {
        run_id: config.run_id.clone(),
        target_count: provisional.target_count,
        alignment_records: provisional.alignment_records,
        alignment_summary: provisional.alignment_summary,
        alignment_status: provisional.alignment_status,
        mismatch_records: provisional.mismatch_records,
        mismatch_count: provisional.mismatch_count,
        no_decision_bridge_guard_status: no_decision_bridge_guard.guard_status,
        no_decision_bridge_guard,
        owner_core_debug_card_count: owner_core_debug_section
            .as_ref()
            .map(|section| section.cards.len())
            .unwrap_or(0),
        owner_core_debug_section,
        run_status,
        warnings,
        debug_only: true,
        not_investment_signal: true,
        not_committee_opinion: true,
        paper_only_warning:
            "shadow alignment is paper-only diagnostics; it cannot train, trade, or override committee decisions"
                .to_string(),
        paper_only: true,
    };
    if let Some(path) = config.output_path.as_ref() {
        write_safe_json(Path::new(path), &result)?;
    }
    Ok(result)
}

impl Default for MismatchToResearchTaskPolicy {
    fn default() -> Self {
        Self {
            create_tasks_for_high_priority_only: false,
            max_tasks_per_member: default_smartcore_mismatch_max_tasks_per_member(),
            max_tasks_total: default_smartcore_mismatch_max_tasks_total(),
            include_price_evidence_tasks: true,
            include_news_context_tasks: true,
            include_risk_veto_tasks: true,
            include_evidence_gap_tasks: true,
            paper_only: true,
        }
    }
}

fn smartcore_mismatch_pipeline_requested_from_flags(
    enabled: bool,
    dataset_output_path: Option<&String>,
    mismatch_task_output_path: Option<&String>,
    _emit_owner_debug_summary: bool,
) -> bool {
    enabled || dataset_output_path.is_some() || mismatch_task_output_path.is_some()
}

fn increment_string_counter(
    counts: &mut std::collections::BTreeMap<String, usize>,
    key: impl Into<String>,
) {
    *counts.entry(key.into()).or_insert(0) += 1;
}

fn smartcore_head_keys() -> [(SmartCoreShadowHeadKind, &'static str); 4] {
    [
        (SmartCoreShadowHeadKind::Stance, "stance"),
        (SmartCoreShadowHeadKind::Risk, "risk"),
        (SmartCoreShadowHeadKind::EvidenceNeed, "evidence"),
        (SmartCoreShadowHeadKind::ConfidenceCalibration, "confidence"),
    ]
}

fn smartcore_alignment_status_for_head(
    record: &SmartCoreShadowAlignmentRecord,
    head: SmartCoreShadowHeadKind,
) -> SmartCoreShadowAlignmentStatus {
    match head {
        SmartCoreShadowHeadKind::Stance => record.stance_alignment,
        SmartCoreShadowHeadKind::Risk => record.risk_alignment,
        SmartCoreShadowHeadKind::EvidenceNeed => record.evidence_alignment,
        SmartCoreShadowHeadKind::ConfidenceCalibration => record.confidence_alignment,
        SmartCoreShadowHeadKind::Uncertainty | SmartCoreShadowHeadKind::ExpectedReturnHint => {
            SmartCoreShadowAlignmentStatus::Deferred
        }
    }
}

fn smartcore_mismatch_data_need_priority(
    mismatch_record: &SmartCoreShadowMismatchRecord,
    data_need: SmartCoreMismatchDataNeed,
) -> WeakReplayLabelPriority {
    match (mismatch_record.severity, data_need) {
        (
            SmartCoreShadowMismatchSeverity::High,
            SmartCoreMismatchDataNeed::MoreRiskVetoCases
            | SmartCoreMismatchDataNeed::MoreNeedMoreEvidenceCases
            | SmartCoreMismatchDataNeed::MoreStanceLabels
            | SmartCoreMismatchDataNeed::MoreContradictoryEvidence,
        ) => WeakReplayLabelPriority::High,
        (SmartCoreShadowMismatchSeverity::High, _) => WeakReplayLabelPriority::Normal,
        (
            SmartCoreShadowMismatchSeverity::Medium,
            SmartCoreMismatchDataNeed::MoreRiskVetoCases
            | SmartCoreMismatchDataNeed::MoreNeedMoreEvidenceCases,
        ) => WeakReplayLabelPriority::High,
        (SmartCoreShadowMismatchSeverity::Medium, _) => WeakReplayLabelPriority::Normal,
        _ => WeakReplayLabelPriority::Low,
    }
}

pub fn classify_smartcore_mismatch_data_need(
    mismatch_record: &SmartCoreShadowMismatchRecord,
) -> SmartCoreMismatchDataNeedRecord {
    let data_need = match mismatch_record.mismatch_type {
        SmartCoreShadowMismatchType::RiskUnderestimation => {
            SmartCoreMismatchDataNeed::MoreRiskVetoCases
        }
        SmartCoreShadowMismatchType::RiskOverestimation => {
            SmartCoreMismatchDataNeed::MoreRiskLabels
        }
        SmartCoreShadowMismatchType::EvidenceOverconfidence => {
            SmartCoreMismatchDataNeed::MoreNeedMoreEvidenceCases
        }
        SmartCoreShadowMismatchType::EvidenceUnderconfidence => {
            SmartCoreMismatchDataNeed::MoreEvidenceLabels
        }
        SmartCoreShadowMismatchType::StanceDisagreement => {
            SmartCoreMismatchDataNeed::MoreStanceLabels
        }
        SmartCoreShadowMismatchType::ConfidenceOverstatement
        | SmartCoreShadowMismatchType::ConfidenceUnderstatement => {
            SmartCoreMismatchDataNeed::MoreConfidenceCalibrationLabels
        }
        SmartCoreShadowMismatchType::Unknown => match mismatch_record.head {
            SmartCoreShadowHeadKind::Uncertainty => {
                SmartCoreMismatchDataNeed::MoreUncertaintyLabels
            }
            _ => SmartCoreMismatchDataNeed::KeepObserving,
        },
    };
    let priority = smartcore_mismatch_data_need_priority(mismatch_record, data_need);
    let reason = match data_need {
        SmartCoreMismatchDataNeed::MoreRiskVetoCases => {
            "risk underestimation suggests more risk veto examples and labels".to_string()
        }
        SmartCoreMismatchDataNeed::MoreRiskLabels => {
            "risk mismatch suggests more risk labels and boundary cases".to_string()
        }
        SmartCoreMismatchDataNeed::MoreNeedMoreEvidenceCases => {
            "evidence overconfidence suggests more need-more-evidence cases".to_string()
        }
        SmartCoreMismatchDataNeed::MoreEvidenceLabels => {
            "evidence mismatch suggests more evidence labels".to_string()
        }
        SmartCoreMismatchDataNeed::MoreStanceLabels => {
            if mismatch_record.debug_bucket == "PositiveLike" {
                "stance disagreement suggests more negative outcome and stance labels".to_string()
            } else if mismatch_record.debug_bucket == "NegativeLike" {
                "stance disagreement suggests more positive outcome and stance labels".to_string()
            } else {
                "stance disagreement suggests more stance labels".to_string()
            }
        }
        SmartCoreMismatchDataNeed::MoreConfidenceCalibrationLabels => {
            "confidence mismatch suggests more calibration labels".to_string()
        }
        SmartCoreMismatchDataNeed::MoreUncertaintyLabels => {
            "uncertainty mismatch suggests more uncertainty labels".to_string()
        }
        SmartCoreMismatchDataNeed::KeepObserving => {
            "unknown mismatch stays diagnostic-only until more labels exist".to_string()
        }
        SmartCoreMismatchDataNeed::MorePositiveOutcomeExamples => {
            "collect more positive outcome examples".to_string()
        }
        SmartCoreMismatchDataNeed::MoreNegativeOutcomeExamples => {
            "collect more negative outcome examples".to_string()
        }
        SmartCoreMismatchDataNeed::MoreContradictoryEvidence => {
            "collect contradictory evidence for this mismatch".to_string()
        }
        SmartCoreMismatchDataNeed::MoreMemberSpecificExamples => {
            "collect more member-specific calibration examples".to_string()
        }
        SmartCoreMismatchDataNeed::MoreMarketScopeCoverage => {
            "collect more market-scope coverage for this mismatch".to_string()
        }
        SmartCoreMismatchDataNeed::MoreNewsContext => {
            "collect more news context for this mismatch".to_string()
        }
        SmartCoreMismatchDataNeed::MorePriceEvidence => {
            "collect more price evidence for this mismatch".to_string()
        }
    };
    SmartCoreMismatchDataNeedRecord {
        need_id: format!("need-{}", mismatch_record.mismatch_id),
        mismatch_id: mismatch_record.mismatch_id.clone(),
        member_id: mismatch_record.member_id.clone(),
        head: mismatch_record.head,
        symbol: mismatch_record.symbol.clone(),
        market_scope: mismatch_record.market_scope,
        mismatch_type: mismatch_record.mismatch_type,
        data_need,
        priority,
        reason,
        paper_only: true,
    }
}

pub fn summarize_smartcore_mismatch_data_needs(
    records: &[SmartCoreMismatchDataNeedRecord],
) -> SmartCoreMismatchAnalysisSummary {
    let mut by_member = std::collections::BTreeMap::new();
    let mut by_head = std::collections::BTreeMap::new();
    let mut by_mismatch_type = std::collections::BTreeMap::new();
    let mut by_data_need = std::collections::BTreeMap::new();
    let mut high_priority_need_count = 0;
    for record in records {
        increment_string_counter(&mut by_member, record.member_id.clone());
        increment_string_counter(&mut by_head, format!("{:?}", record.head));
        increment_string_counter(&mut by_mismatch_type, format!("{:?}", record.mismatch_type));
        increment_string_counter(&mut by_data_need, format!("{:?}", record.data_need));
        if record.priority == WeakReplayLabelPriority::High {
            high_priority_need_count += 1;
        }
    }
    let max_need_count = by_data_need.values().copied().max().unwrap_or(0);
    let mut dominant_data_needs = records
        .iter()
        .filter(|record| {
            by_data_need
                .get(&format!("{:?}", record.data_need))
                .copied()
                .unwrap_or(0)
                == max_need_count
        })
        .map(|record| record.data_need)
        .collect::<Vec<_>>();
    dominant_data_needs.sort();
    dominant_data_needs.dedup();
    SmartCoreMismatchAnalysisSummary {
        summary_id: format!("smartcore-mismatch-analysis-{}", records.len()),
        mismatch_count: records.len(),
        by_member,
        by_head,
        by_mismatch_type,
        by_data_need,
        high_priority_need_count,
        dominant_data_needs,
        paper_only: true,
    }
}

fn smartcore_task_member_for_data_need(record: &SmartCoreMismatchDataNeedRecord) -> String {
    match record.data_need {
        SmartCoreMismatchDataNeed::MoreRiskLabels
        | SmartCoreMismatchDataNeed::MoreRiskVetoCases
        | SmartCoreMismatchDataNeed::MoreContradictoryEvidence => "RiskGuardAI".to_string(),
        SmartCoreMismatchDataNeed::MoreEvidenceLabels
        | SmartCoreMismatchDataNeed::MoreNeedMoreEvidenceCases
        | SmartCoreMismatchDataNeed::MoreMarketScopeCoverage => "EvidenceRegimeAI".to_string(),
        SmartCoreMismatchDataNeed::MoreStanceLabels
        | SmartCoreMismatchDataNeed::MorePositiveOutcomeExamples
        | SmartCoreMismatchDataNeed::MoreNegativeOutcomeExamples
        | SmartCoreMismatchDataNeed::MoreNewsContext
        | SmartCoreMismatchDataNeed::MorePriceEvidence => "TrendEntryAI".to_string(),
        SmartCoreMismatchDataNeed::MoreConfidenceCalibrationLabels
        | SmartCoreMismatchDataNeed::MoreUncertaintyLabels
        | SmartCoreMismatchDataNeed::MoreMemberSpecificExamples
        | SmartCoreMismatchDataNeed::KeepObserving => {
            display_name_for_member_id(&record.member_id).to_string()
        }
    }
}

fn smartcore_task_type_for_data_need(
    record: &SmartCoreMismatchDataNeedRecord,
    policy: &MismatchToResearchTaskPolicy,
) -> Option<MemberResearchTaskType> {
    match record.data_need {
        SmartCoreMismatchDataNeed::MoreRiskVetoCases => policy
            .include_risk_veto_tasks
            .then_some(MemberResearchTaskType::ReviewRiskVetoCase),
        SmartCoreMismatchDataNeed::MoreNeedMoreEvidenceCases => policy
            .include_evidence_gap_tasks
            .then_some(MemberResearchTaskType::ReviewNeedMoreEvidenceCase),
        SmartCoreMismatchDataNeed::MorePriceEvidence
        | SmartCoreMismatchDataNeed::MorePositiveOutcomeExamples
        | SmartCoreMismatchDataNeed::MoreNegativeOutcomeExamples => policy
            .include_price_evidence_tasks
            .then_some(MemberResearchTaskType::GatherPriceEvidence),
        SmartCoreMismatchDataNeed::MoreNewsContext
        | SmartCoreMismatchDataNeed::MoreStanceLabels => policy
            .include_news_context_tasks
            .then_some(MemberResearchTaskType::GatherNewsContext),
        SmartCoreMismatchDataNeed::MoreContradictoryEvidence => policy
            .include_risk_veto_tasks
            .then_some(MemberResearchTaskType::FindContradictoryEvidence),
        SmartCoreMismatchDataNeed::MoreMarketScopeCoverage => policy
            .include_evidence_gap_tasks
            .then_some(MemberResearchTaskType::FillCoverageGap),
        SmartCoreMismatchDataNeed::MoreRiskLabels => policy
            .include_risk_veto_tasks
            .then_some(MemberResearchTaskType::ReviewRiskVetoCase),
        SmartCoreMismatchDataNeed::MoreEvidenceLabels => policy
            .include_evidence_gap_tasks
            .then_some(MemberResearchTaskType::ReviewNeedMoreEvidenceCase),
        SmartCoreMismatchDataNeed::MoreConfidenceCalibrationLabels
        | SmartCoreMismatchDataNeed::MoreUncertaintyLabels
        | SmartCoreMismatchDataNeed::MoreMemberSpecificExamples => {
            Some(MemberResearchTaskType::BuildReplayEvidenceCandidate)
        }
        SmartCoreMismatchDataNeed::KeepObserving => None,
    }
}

pub fn generate_research_tasks_from_smartcore_mismatches(
    data_need_records: &[SmartCoreMismatchDataNeedRecord],
    policy: &MismatchToResearchTaskPolicy,
) -> MismatchResearchTaskGenerationResult {
    let mut sorted_records = data_need_records.to_vec();
    sorted_records.sort_by(|left, right| {
        right
            .priority
            .cmp(&left.priority)
            .then_with(|| left.member_id.cmp(&right.member_id))
            .then_with(|| left.need_id.cmp(&right.need_id))
    });
    let mut generated_tasks = Vec::new();
    let mut per_member_counts: std::collections::BTreeMap<String, usize> =
        std::collections::BTreeMap::new();
    let mut skipped_reasons = Vec::new();
    for record in sorted_records {
        if policy.create_tasks_for_high_priority_only
            && record.priority != WeakReplayLabelPriority::High
        {
            skipped_reasons.push(format!(
                "{} skipped because policy keeps only high priority tasks",
                record.need_id
            ));
            continue;
        }
        let task_type = if let Some(task_type) = smartcore_task_type_for_data_need(&record, policy)
        {
            task_type
        } else {
            skipped_reasons.push(format!(
                "{} skipped because {:?} stays observation-only",
                record.need_id, record.data_need
            ));
            continue;
        };
        if generated_tasks.len() >= policy.max_tasks_total {
            skipped_reasons.push(format!(
                "{} skipped because max_tasks_total={} was reached",
                record.need_id, policy.max_tasks_total
            ));
            continue;
        }
        let task_member_id = smartcore_task_member_for_data_need(&record);
        let per_member_count = per_member_counts
            .get(task_member_id.as_str())
            .copied()
            .unwrap_or(0);
        if per_member_count >= policy.max_tasks_per_member {
            skipped_reasons.push(format!(
                "{} skipped because max_tasks_per_member={} was reached for {}",
                record.need_id, policy.max_tasks_per_member, task_member_id
            ));
            continue;
        }
        let (_, source_preferences) =
            member_research_preferences_for_role(role_for_member_id(&task_member_id));
        generated_tasks.push(MemberResearchTask {
            task_id: format!("smartcore-mismatch-task-{}", record.need_id),
            member_id: task_member_id.clone(),
            task_type,
            symbol: record.symbol.clone(),
            market_scope: record.market_scope,
            related_replay_id: None,
            related_experience_id: None,
            related_decision_id: None,
            priority: record.priority,
            source_preferences,
            task_reason: format!(
                "smartcore mismatch {:?} on {:?} -> {:?}: {}",
                record.mismatch_type, record.head, record.data_need, record.reason
            ),
            paper_only: true,
        });
        *per_member_counts.entry(task_member_id).or_insert(0) += 1;
    }
    generated_tasks.sort_by(|left, right| {
        right
            .priority
            .cmp(&left.priority)
            .then_with(|| left.member_id.cmp(&right.member_id))
            .then_with(|| left.task_id.cmp(&right.task_id))
    });
    let queue = MemberResearchTaskQueue {
        queue_id: "smartcore-mismatch-research-tasks".to_string(),
        high_priority_count: generated_tasks
            .iter()
            .filter(|task| task.priority == WeakReplayLabelPriority::High)
            .count(),
        tasks: generated_tasks,
        paper_only: true,
    };
    MismatchResearchTaskGenerationResult {
        generated_count: queue.tasks.len(),
        skipped_count: skipped_reasons.len(),
        generated_tasks: queue,
        skipped_reasons,
        paper_only: true,
    }
}

fn core_calibration_label_source_from_target_id(
    target_id: Option<&str>,
) -> CoreCalibrationLabelSource {
    let target_id = target_id.unwrap_or_default().to_ascii_lowercase();
    if target_id.contains("risk-governor") {
        CoreCalibrationLabelSource::RiskGovernorStatus
    } else if target_id.contains("replay-target") {
        CoreCalibrationLabelSource::ReplayLabel
    } else if target_id.contains("paper-outcome") {
        CoreCalibrationLabelSource::PaperOutcomeLabel
    } else {
        CoreCalibrationLabelSource::ShadowMemberOpinion
    }
}

fn core_calibration_label_confidence_for_source(
    source: CoreCalibrationLabelSource,
    alignment: SmartCoreShadowAlignmentStatus,
) -> ReplayLabelConfidence {
    if matches!(
        alignment,
        SmartCoreShadowAlignmentStatus::Unknown | SmartCoreShadowAlignmentStatus::Deferred
    ) {
        return ReplayLabelConfidence::ReviewRequired;
    }
    match source {
        CoreCalibrationLabelSource::ReplayLabel
        | CoreCalibrationLabelSource::RiskGovernorStatus => ReplayLabelConfidence::High,
        CoreCalibrationLabelSource::PaperOutcomeLabel => ReplayLabelConfidence::Medium,
        CoreCalibrationLabelSource::ShadowMemberOpinion => ReplayLabelConfidence::Medium,
    }
}

fn find_shadow_mismatch_for_alignment_head<'a>(
    alignment_record: &SmartCoreShadowAlignmentRecord,
    head: SmartCoreShadowHeadKind,
    debug_bucket: &str,
    target_bucket: &str,
    mismatch_records: &'a [SmartCoreShadowMismatchRecord],
) -> Option<&'a SmartCoreShadowMismatchRecord> {
    mismatch_records
        .iter()
        .find(|record| {
            record.member_id == alignment_record.member_id
                && record.head == head
                && record.symbol == alignment_record.symbol
                && record.market_scope == alignment_record.market_scope
                && record.debug_bucket == debug_bucket
                && record.target_value == target_bucket
        })
        .or_else(|| {
            mismatch_records.iter().find(|record| {
                record.member_id == alignment_record.member_id && record.head == head
            })
        })
}

pub fn build_core_calibration_examples(
    alignment_records: &[SmartCoreShadowAlignmentRecord],
    mismatch_records: &[SmartCoreShadowMismatchRecord],
) -> Vec<CoreCalibrationExample> {
    let mut examples = Vec::new();
    for alignment_record in alignment_records {
        let label_source =
            core_calibration_label_source_from_target_id(alignment_record.target_id.as_deref());
        for (head, head_key) in smartcore_head_keys() {
            let alignment = smartcore_alignment_status_for_head(alignment_record, head);
            let debug_bucket = alignment_record
                .normalized_debug_buckets
                .get(head_key)
                .cloned()
                .unwrap_or_else(|| "Deferred".to_string());
            let target_bucket = alignment_record
                .normalized_target_values
                .get(head_key)
                .cloned()
                .unwrap_or_else(|| "Unknown".to_string());
            if matches!(alignment, SmartCoreShadowAlignmentStatus::Deferred)
                && debug_bucket == "Deferred"
                && target_bucket == "Unknown"
            {
                continue;
            }
            let mismatch = find_shadow_mismatch_for_alignment_head(
                alignment_record,
                head,
                &debug_bucket,
                &target_bucket,
                mismatch_records,
            );
            let suggested_data_need = mismatch
                .map(classify_smartcore_mismatch_data_need)
                .map(|record| record.data_need)
                .unwrap_or(SmartCoreMismatchDataNeed::KeepObserving);
            examples.push(CoreCalibrationExample {
                calibration_example_id: format!(
                    "core-calibration-{}-{}",
                    alignment_record.alignment_id, head_key
                ),
                member_id: alignment_record.member_id.clone(),
                debug_output_id: alignment_record.debug_output_id.clone(),
                target_id: alignment_record.target_id.clone(),
                symbol: alignment_record.symbol.clone(),
                market_scope: alignment_record.market_scope,
                head,
                debug_bucket,
                target_bucket,
                alignment,
                mismatch_type: mismatch.map(|record| record.mismatch_type),
                suggested_data_need,
                label_source,
                label_confidence: core_calibration_label_confidence_for_source(
                    label_source,
                    alignment,
                ),
                paper_only: true,
            });
        }
    }
    examples.sort_by(|left, right| {
        left.member_id.cmp(&right.member_id).then_with(|| {
            left.calibration_example_id
                .cmp(&right.calibration_example_id)
        })
    });
    examples
}

pub fn build_core_calibration_dataset(
    examples: &[CoreCalibrationExample],
) -> CoreCalibrationDataset {
    let mut sorted_examples = examples.to_vec();
    sorted_examples.sort_by(|left, right| {
        left.member_id.cmp(&right.member_id).then_with(|| {
            left.calibration_example_id
                .cmp(&right.calibration_example_id)
        })
    });
    let mut member_ids = sorted_examples
        .iter()
        .map(|example| example.member_id.clone())
        .collect::<Vec<_>>();
    member_ids.sort();
    member_ids.dedup();
    let mut head_distribution = std::collections::BTreeMap::new();
    let mut alignment_distribution = std::collections::BTreeMap::new();
    let mut mismatch_type_distribution = std::collections::BTreeMap::new();
    for example in &sorted_examples {
        increment_string_counter(&mut head_distribution, format!("{:?}", example.head));
        increment_string_counter(
            &mut alignment_distribution,
            format!("{:?}", example.alignment),
        );
        if let Some(mismatch_type) = example.mismatch_type {
            increment_string_counter(
                &mut mismatch_type_distribution,
                format!("{:?}", mismatch_type),
            );
        }
    }
    let dataset_id = sorted_examples
        .first()
        .map(|example| format!("{}-core-calibration-dataset", example.debug_output_id))
        .unwrap_or_else(|| "smartcore-core-calibration-dataset-empty".to_string());
    CoreCalibrationDataset {
        dataset_id,
        example_count: sorted_examples.len(),
        member_count: member_ids.len(),
        head_distribution,
        alignment_distribution,
        mismatch_type_distribution,
        examples: sorted_examples,
        paper_only: true,
    }
}

pub fn save_core_calibration_dataset_to_local_json(
    dataset: &CoreCalibrationDataset,
    path: &Path,
) -> Result<(), String> {
    validate_local_json_path(path, "core calibration dataset path")?;
    if !dataset.paper_only || dataset.examples.iter().any(|example| !example.paper_only) {
        return Err("core calibration dataset must stay paper_only".to_string());
    }
    write_safe_json(path, dataset)
}

pub fn load_core_calibration_dataset_from_local_json(
    path: &Path,
) -> Result<CoreCalibrationDataset, String> {
    validate_local_json_path(path, "core calibration dataset path")?;
    let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
    reject_unsafe_export_text(&text)?;
    let dataset =
        serde_json::from_str::<CoreCalibrationDataset>(&text).map_err(|err| err.to_string())?;
    if !dataset.paper_only || dataset.examples.iter().any(|example| !example.paper_only) {
        return Err("core calibration dataset must stay paper_only".to_string());
    }
    Ok(dataset)
}

pub fn summarize_core_calibration_quality(
    dataset: &CoreCalibrationDataset,
) -> CoreCalibrationQualitySummary {
    let matched_count = dataset
        .examples
        .iter()
        .filter(|example| example.alignment == SmartCoreShadowAlignmentStatus::Match)
        .count();
    let mismatched_count = dataset
        .examples
        .iter()
        .filter(|example| example.alignment == SmartCoreShadowAlignmentStatus::Mismatch)
        .count();
    let unknown_count = dataset
        .examples
        .iter()
        .filter(|example| example.alignment == SmartCoreShadowAlignmentStatus::Unknown)
        .count();
    let deferred_count = dataset
        .examples
        .iter()
        .filter(|example| example.alignment == SmartCoreShadowAlignmentStatus::Deferred)
        .count();
    let mismatch_rate = if dataset.example_count == 0 {
        0.0
    } else {
        mismatched_count as f64 / dataset.example_count as f64
    };
    let mut per_member_total = std::collections::BTreeMap::new();
    let mut per_member_mismatches = std::collections::BTreeMap::new();
    let mut per_head_total = std::collections::BTreeMap::new();
    let mut per_head_mismatches = std::collections::BTreeMap::new();
    for example in &dataset.examples {
        *per_member_total
            .entry(example.member_id.clone())
            .or_insert(0usize) += 1;
        *per_head_total
            .entry(format!("{:?}", example.head))
            .or_insert(0usize) += 1;
        if example.alignment == SmartCoreShadowAlignmentStatus::Mismatch {
            *per_member_mismatches
                .entry(example.member_id.clone())
                .or_insert(0usize) += 1;
            *per_head_mismatches
                .entry(format!("{:?}", example.head))
                .or_insert(0usize) += 1;
        }
    }
    let per_member_mismatch_rate = per_member_total
        .iter()
        .map(|(member_id, total)| {
            let mismatches = per_member_mismatches.get(member_id).copied().unwrap_or(0);
            (
                member_id.clone(),
                if *total == 0 {
                    0.0
                } else {
                    mismatches as f64 / *total as f64
                },
            )
        })
        .collect();
    let per_head_mismatch_rate = per_head_total
        .iter()
        .map(|(head, total)| {
            let mismatches = per_head_mismatches.get(head).copied().unwrap_or(0);
            (
                head.clone(),
                if *total == 0 {
                    0.0
                } else {
                    mismatches as f64 / *total as f64
                },
            )
        })
        .collect();
    let quality_status =
        if !dataset.paper_only || dataset.examples.iter().any(|example| !example.paper_only) {
            CoreCalibrationQualityStatus::Unsafe
        } else if dataset.example_count < 3 {
            CoreCalibrationQualityStatus::TooSparse
        } else if mismatch_rate >= 0.4 || (unknown_count + deferred_count) > matched_count {
            CoreCalibrationQualityStatus::NeedsMoreTargets
        } else {
            CoreCalibrationQualityStatus::UsefulForObservation
        };
    let mut recommended_next_actions = Vec::new();
    if dataset
        .examples
        .iter()
        .any(|example| example.head == SmartCoreShadowHeadKind::Risk)
    {
        recommended_next_actions.push(CoreCalibrationRecommendedNextAction::CollectMoreRiskLabels);
    }
    if dataset
        .examples
        .iter()
        .any(|example| example.head == SmartCoreShadowHeadKind::EvidenceNeed)
    {
        recommended_next_actions
            .push(CoreCalibrationRecommendedNextAction::CollectMoreEvidenceLabels);
    }
    if dataset
        .examples
        .iter()
        .any(|example| example.head == SmartCoreShadowHeadKind::Stance)
    {
        recommended_next_actions
            .push(CoreCalibrationRecommendedNextAction::CollectMoreStanceLabels);
    }
    if dataset
        .examples
        .iter()
        .any(|example| example.head == SmartCoreShadowHeadKind::ConfidenceCalibration)
    {
        recommended_next_actions
            .push(CoreCalibrationRecommendedNextAction::CollectMoreConfidenceLabels);
    }
    if matches!(
        quality_status,
        CoreCalibrationQualityStatus::UsefulForObservation
    ) {
        recommended_next_actions
            .push(CoreCalibrationRecommendedNextAction::ContinueShadowObservation);
    }
    recommended_next_actions.push(CoreCalibrationRecommendedNextAction::DoNotTrainYet);
    recommended_next_actions.sort();
    recommended_next_actions.dedup();
    CoreCalibrationQualitySummary {
        dataset_id: dataset.dataset_id.clone(),
        example_count: dataset.example_count,
        member_count: dataset.member_count,
        matched_count,
        mismatched_count,
        unknown_count,
        deferred_count,
        mismatch_rate,
        per_member_mismatch_rate,
        per_head_mismatch_rate,
        quality_status,
        recommended_next_actions,
        paper_only: true,
    }
}

pub fn build_owner_core_calibration_debug_summary(
    pipeline_result: &SmartCoreMismatchSelfGrowingRunResult,
) -> OwnerCoreCalibrationDebugSummary {
    OwnerCoreCalibrationDebugSummary {
        summary_id: format!("{}-owner-core-calibration", pipeline_result.run_id),
        mismatch_count: pipeline_result.mismatch_data_need_count,
        dominant_data_needs: pipeline_result
            .mismatch_analysis_summary
            .dominant_data_needs
            .clone(),
        generated_research_task_count: pipeline_result.generated_research_task_count,
        calibration_example_count: pipeline_result.calibration_example_count,
        research_task_executed_count: 0,
        evidence_generated_count: 0,
        calibration_target_candidate_count: 0,
        approved_calibration_target_count: 0,
        refreshed_calibration_example_count: 0,
        alignment_mismatch_delta: None,
        message: format!(
            "SmartCore debug output is being observed only. Mismatches generated research tasks. This is not used for trading or committee decisions. tasks={}, calibration_examples={}",
            pipeline_result.generated_research_task_count,
            pipeline_result.calibration_example_count
        ),
        debug_only: true,
        not_investment_signal: true,
        not_committee_opinion: true,
        paper_only: true,
    }
}

fn apply_owner_core_calibration_debug_update(
    batch_id: &str,
    section: Option<OwnerCoreDebugSection>,
    update: Option<OwnerCoreCalibrationDebugSummary>,
) -> Option<OwnerCoreDebugSection> {
    let Some(update) = update else {
        return section;
    };
    if let Some(mut section) = section {
        section.summary = format!(
            "{}; mismatch_tasks={}, calibration_examples={}",
            section.summary, update.generated_research_task_count, update.calibration_example_count
        );
        section.calibration_summary = Some(update);
        Some(section)
    } else {
        Some(OwnerCoreDebugSection {
            section_id: format!("{batch_id}-owner-core-debug"),
            cards: Vec::new(),
            summary: format!(
                "mismatches={}, tasks={}, calibration_examples={}",
                update.mismatch_count,
                update.generated_research_task_count,
                update.calibration_example_count
            ),
            paper_only_warning:
                "core calibration debug summary is paper-only diagnostics; not investment advice, not trading, not orders"
                    .to_string(),
            debug_only_warning:
                "debug calibration summary is read-only mismatch observation and must not feed member opinions or committee decisions"
                    .to_string(),
            calibration_summary: Some(update),
            recalibration_summary: None,
            shadow_opinion_summary: None,
            shadow_stability_summary: None,
            shadow_scenario_sweep_summary: None,
            observer_section: None,
            observer_coverage_closure_summary: None,
            observer_trend_summary: None,
            observer_seeded_target_summary: None,
            observer_apply_readiness_summary: None,
            paper_only: true,
        })
    }
}

pub fn recheck_smartcore_mismatch_no_decision_boundary(
    pipeline_result: &SmartCoreMismatchSelfGrowingRunResult,
    batch_result: &BatchCommitteeCycleResult,
) -> SmartCoreMismatchNoDecisionRecheck {
    let task_markers: Vec<String> = pipeline_result
        .research_task_generation_result
        .generated_tasks
        .tasks
        .iter()
        .map(|task| task.task_id.clone())
        .collect();
    let dataset_markers = vec![pipeline_result.core_calibration_dataset.dataset_id.clone()];
    let mismatch_tasks_used_for_decision =
        value_contains_debug_marker(&batch_result.member_opinions, &task_markers)
            || value_contains_debug_marker(&batch_result.committee_sessions, &task_markers)
            || value_contains_debug_marker(&batch_result.chairman_decisions, &task_markers);
    let calibration_dataset_used_for_decision =
        value_contains_debug_marker(&batch_result.member_opinions, &dataset_markers)
            || value_contains_debug_marker(&batch_result.committee_sessions, &dataset_markers)
            || value_contains_debug_marker(&batch_result.chairman_decisions, &dataset_markers);
    let research_tasks_used_as_order =
        value_contains_debug_marker(&batch_result.event_queue, &task_markers);
    let mut violations = Vec::new();
    if mismatch_tasks_used_for_decision {
        violations.push("mismatch research tasks leaked into decision path".to_string());
    }
    if calibration_dataset_used_for_decision {
        violations.push("calibration dataset leaked into decision path".to_string());
    }
    if research_tasks_used_as_order {
        violations.push("mismatch research tasks leaked into trade signal path".to_string());
    }
    SmartCoreMismatchNoDecisionRecheck {
        mismatch_tasks_used_for_decision,
        calibration_dataset_used_for_decision,
        research_tasks_used_as_order,
        no_decision_status: if violations.is_empty() {
            SmartCoreNoDecisionBridgeGuardStatus::Preserved
        } else {
            SmartCoreNoDecisionBridgeGuardStatus::Violated
        },
        violations,
        paper_only: true,
    }
}

pub fn run_smartcore_mismatch_self_growing_pipeline(
    shadow_alignment_result: &SmartCoreShadowAlignmentRunResult,
    config: &SmartCoreMismatchSelfGrowingRunConfig,
) -> Result<SmartCoreMismatchSelfGrowingRunResult, String> {
    if !config.paper_only {
        return Err("smartcore mismatch self-growing pipeline must be paper-only".to_string());
    }
    if config.max_tasks_total == 0 || config.max_tasks_per_member == 0 {
        return Err("smartcore mismatch self-growing task limits must be positive".to_string());
    }
    if let Some(path) = config.core_calibration_dataset_output_path.as_ref() {
        validate_local_json_path(Path::new(path), "smartcore calibration dataset output path")?;
    }
    if let Some(path) = config.mismatch_task_output_path.as_ref() {
        validate_local_json_path(Path::new(path), "smartcore mismatch task output path")?;
    }
    let mismatch_data_need_records = shadow_alignment_result
        .mismatch_records
        .iter()
        .map(classify_smartcore_mismatch_data_need)
        .collect::<Vec<_>>();
    let mismatch_analysis_summary =
        summarize_smartcore_mismatch_data_needs(&mismatch_data_need_records);
    let research_task_generation_result = generate_research_tasks_from_smartcore_mismatches(
        &mismatch_data_need_records,
        &MismatchToResearchTaskPolicy {
            max_tasks_per_member: config.max_tasks_per_member,
            max_tasks_total: config.max_tasks_total,
            ..MismatchToResearchTaskPolicy::default()
        },
    );
    let core_calibration_examples = build_core_calibration_examples(
        &shadow_alignment_result.alignment_records,
        &shadow_alignment_result.mismatch_records,
    );
    let core_calibration_dataset = build_core_calibration_dataset(&core_calibration_examples);
    let core_calibration_quality_summary =
        summarize_core_calibration_quality(&core_calibration_dataset);
    if let Some(path) = config.core_calibration_dataset_output_path.as_ref() {
        save_core_calibration_dataset_to_local_json(&core_calibration_dataset, Path::new(path))?;
    }
    if let Some(path) = config.mismatch_task_output_path.as_ref() {
        write_safe_json(
            Path::new(path),
            &research_task_generation_result.generated_tasks,
        )?;
    }
    let mut result = SmartCoreMismatchSelfGrowingRunResult {
        run_id: config.run_id.clone(),
        mismatch_data_need_count: mismatch_data_need_records.len(),
        mismatch_data_need_records,
        mismatch_analysis_summary,
        generated_research_task_count: research_task_generation_result.generated_count,
        research_task_generation_result,
        calibration_example_count: core_calibration_dataset.example_count,
        calibration_quality_status: core_calibration_quality_summary.quality_status,
        core_calibration_dataset,
        core_calibration_quality_summary,
        owner_core_debug_update: None,
        no_decision_recheck: None,
        no_decision_recheck_status: SmartCoreNoDecisionBridgeGuardStatus::Preserved,
        run_status: SmartCoreMismatchSelfGrowingRunStatus::Passed,
        safety_summary: safety_summary(),
        debug_only: true,
        not_investment_signal: true,
        not_committee_opinion: true,
        paper_only_warning:
            "smartcore mismatch pipeline is paper-only diagnostics; it can create research tasks and calibration data but cannot trade, train, or change committee decisions"
                .to_string(),
        paper_only: true,
    };
    if config.emit_owner_console_summary {
        result.owner_core_debug_update = Some(build_owner_core_calibration_debug_summary(&result));
    }
    if result.mismatch_data_need_count == 0
        || result.generated_research_task_count == 0
        || !matches!(
            result.calibration_quality_status,
            CoreCalibrationQualityStatus::UsefulForObservation
        )
    {
        result.run_status = SmartCoreMismatchSelfGrowingRunStatus::PassedWithWarnings;
    }
    Ok(result)
}

fn maybe_run_smartcore_mismatch_self_growing_for_batch_result(
    run_id: String,
    enabled: bool,
    max_tasks_total: usize,
    max_tasks_per_member: usize,
    core_calibration_dataset_output_path: Option<&String>,
    mismatch_task_output_path: Option<&String>,
    emit_owner_debug_summary: bool,
    batch_result: &mut BatchCommitteeCycleResult,
) -> Result<Option<SmartCoreMismatchSelfGrowingRunResult>, String> {
    if !smartcore_mismatch_pipeline_requested_from_flags(
        enabled,
        core_calibration_dataset_output_path,
        mismatch_task_output_path,
        emit_owner_debug_summary,
    ) {
        return Ok(None);
    }
    let shadow_alignment_result = batch_result
        .smartcore_shadow_alignment_run_result
        .as_ref()
        .ok_or_else(|| "smartcore mismatch pipeline requires shadow alignment result".to_string())?
        .clone();
    let mut result = run_smartcore_mismatch_self_growing_pipeline(
        &shadow_alignment_result,
        &SmartCoreMismatchSelfGrowingRunConfig {
            run_id,
            enabled,
            max_tasks_total,
            max_tasks_per_member,
            core_calibration_dataset_output_path: core_calibration_dataset_output_path.cloned(),
            mismatch_task_output_path: mismatch_task_output_path.cloned(),
            emit_owner_console_summary: emit_owner_debug_summary,
            paper_only: true,
        },
    )?;
    let no_decision_recheck =
        recheck_smartcore_mismatch_no_decision_boundary(&result, batch_result);
    result.no_decision_recheck_status = no_decision_recheck.no_decision_status;
    result.no_decision_recheck = Some(no_decision_recheck.clone());
    if matches!(
        no_decision_recheck.no_decision_status,
        SmartCoreNoDecisionBridgeGuardStatus::Violated
    ) {
        result.run_status = SmartCoreMismatchSelfGrowingRunStatus::Failed;
    }
    if let Some(shadow_alignment_result) =
        batch_result.smartcore_shadow_alignment_run_result.as_mut()
    {
        shadow_alignment_result.owner_core_debug_section =
            apply_owner_core_calibration_debug_update(
                &batch_result.batch_id,
                shadow_alignment_result.owner_core_debug_section.take(),
                result.owner_core_debug_update.clone(),
            );
        shadow_alignment_result.owner_core_debug_card_count = shadow_alignment_result
            .owner_core_debug_section
            .as_ref()
            .map(|section| section.cards.len())
            .unwrap_or(0);
    }
    batch_result.smartcore_mismatch_self_growing_run_result = Some(result.clone());
    Ok(Some(result))
}

impl Default for CoreCalibrationTargetApprovalPolicy {
    fn default() -> Self {
        Self {
            allow_trusted_price_evidence: true,
            allow_member_opinion_targets: true,
            allow_replay_label_targets: true,
            allow_risk_governor_targets: true,
            allow_news_only_targets: false,
            allow_low_trust_targets: false,
            require_member_id: true,
            require_head: true,
            require_target_bucket: true,
            paper_only: true,
        }
    }
}

fn empty_research_source_registry() -> ResearchSourceRegistry {
    ResearchSourceRegistry {
        registry_id: "smartcore-mismatch-empty-registry".to_string(),
        sources: Vec::new(),
        enabled_count: 0,
        network_enabled_count: 0,
        local_source_count: 0,
        paper_only: true,
    }
}

fn load_member_research_task_queue_from_local_json(
    path: &Path,
) -> Result<MemberResearchTaskQueue, String> {
    validate_local_json_path(path, "member research task queue path")?;
    let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
    reject_unsafe_export_text(&text)?;
    if let Ok(queue) = serde_json::from_str::<MemberResearchTaskQueue>(&text) {
        if !queue.paper_only || queue.tasks.iter().any(|task| !task.paper_only) {
            return Err("member research task queue must stay paper_only".to_string());
        }
        Ok(queue)
    } else {
        let tasks = serde_json::from_str::<Vec<MemberResearchTask>>(&text)
            .map_err(|err| err.to_string())?;
        if tasks.iter().any(|task| !task.paper_only) {
            return Err("member research tasks must stay paper_only".to_string());
        }
        Ok(MemberResearchTaskQueue {
            queue_id: "loaded-member-research-tasks".to_string(),
            high_priority_count: tasks
                .iter()
                .filter(|task| task.priority == WeakReplayLabelPriority::High)
                .count(),
            tasks,
            paper_only: true,
        })
    }
}

fn limited_research_evidence_bundle(
    bundle: &ResearchEvidenceBundle,
    max_evidence_per_task: usize,
) -> ResearchEvidenceBundle {
    let mut per_task_counts = std::collections::BTreeMap::new();
    let mut records = Vec::new();
    for record in &bundle.records {
        let task_key = record
            .task_id
            .clone()
            .unwrap_or_else(|| "no-task".to_string());
        let count = per_task_counts.entry(task_key).or_insert(0usize);
        if *count >= max_evidence_per_task {
            continue;
        }
        *count += 1;
        records.push(record.clone());
    }
    ResearchEvidenceBundle {
        bundle_id: bundle.bundle_id.clone(),
        source_scores: bundle.source_scores.clone(),
        task_count: bundle.task_count,
        evidence_count: records.len(),
        records,
        paper_only: true,
    }
}

pub fn execute_mismatch_research_tasks(
    tasks: &[MemberResearchTask],
    source_registry: &ResearchSourceRegistry,
    config: &MismatchResearchTaskExecutionConfig,
) -> Result<MismatchResearchTaskExecutionResult, String> {
    if !config.paper_only {
        return Err("mismatch research task execution must be paper-only".to_string());
    }
    if config.max_tasks == 0 || config.max_evidence_per_task == 0 {
        return Err("mismatch research task execution limits must be positive".to_string());
    }
    let loaded_queue = if let Some(path) = config.task_input_path.as_ref() {
        Some(load_member_research_task_queue_from_local_json(Path::new(
            path,
        ))?)
    } else {
        None
    };
    let provided_queue = MemberResearchTaskQueue {
        queue_id: "provided-mismatch-research-tasks".to_string(),
        high_priority_count: tasks
            .iter()
            .filter(|task| task.priority == WeakReplayLabelPriority::High)
            .count(),
        tasks: tasks.to_vec(),
        paper_only: true,
    };
    let loaded_task_count = loaded_queue
        .as_ref()
        .map(|queue| queue.tasks.len())
        .unwrap_or(tasks.len());
    let selected_tasks = loaded_queue
        .as_ref()
        .unwrap_or(&provided_queue)
        .sort_by_priority()
        .next_tasks(config.max_tasks);
    let mut execution_registry = if let Some(path) = config.source_registry_path.as_ref() {
        ResearchSourceRegistry::load_from_local_json(Path::new(path))?
    } else {
        source_registry.clone()
    };
    let network_source_present = execution_registry
        .sources
        .iter()
        .any(|source| research_source_is_network(source.kind));
    if !config.allow_network_sources {
        for source in &mut execution_registry.sources {
            if research_source_is_network(source.kind) {
                source.enabled = false;
            }
        }
        execution_registry.enabled_count = execution_registry
            .sources
            .iter()
            .filter(|source| source.enabled)
            .count();
        execution_registry.network_enabled_count = execution_registry
            .sources
            .iter()
            .filter(|source| source.enabled && research_source_is_network(source.kind))
            .count();
    }
    execution_registry.validate_sources()?;
    let source_trust_evaluation = evaluate_research_source_trust(&execution_registry, None);
    let evidence_bundle = limited_research_evidence_bundle(
        &collect_research_evidence_with_network_mode(
            &selected_tasks,
            &execution_registry,
            &source_trust_evaluation.source_scores,
            config.allow_network_sources,
        )?,
        config.max_evidence_per_task,
    );
    let mut skipped_reasons = Vec::new();
    if loaded_task_count > selected_tasks.len() {
        skipped_reasons.push(format!(
            "{} tasks were skipped by max_tasks={}",
            loaded_task_count - selected_tasks.len(),
            config.max_tasks
        ));
    }
    if !config.allow_network_sources && network_source_present {
        skipped_reasons.push("network research sources remain disabled".to_string());
    }
    Ok(MismatchResearchTaskExecutionResult {
        run_id: config.run_id.clone(),
        loaded_task_count,
        executed_task_count: selected_tasks.len(),
        skipped_task_count: loaded_task_count.saturating_sub(selected_tasks.len()),
        generated_evidence_count: evidence_bundle.evidence_count,
        evidence_bundle,
        skipped_reasons,
        safety_summary: safety_summary(),
        paper_only: true,
    })
}

fn mismatch_need_record_for_task_id<'a>(
    task_id: Option<&str>,
    mismatch_data_needs: &'a [SmartCoreMismatchDataNeedRecord],
) -> Option<&'a SmartCoreMismatchDataNeedRecord> {
    let task_id = task_id?;
    let need_id = task_id
        .strip_prefix("smartcore-mismatch-task-")
        .unwrap_or(task_id);
    mismatch_data_needs
        .iter()
        .find(|record| record.need_id == need_id)
}

fn trust_status_for_evidence(
    evidence_bundle: &ResearchEvidenceBundle,
    evidence: &ResearchEvidenceRecord,
) -> SourceTrustStatus {
    evidence
        .source_id
        .as_deref()
        .and_then(|source_id| {
            evidence_bundle
                .source_scores
                .iter()
                .find(|score| score.source_id == source_id)
                .map(|score| score.trust_status)
        })
        .unwrap_or(SourceTrustStatus::ReviewRequired)
}

fn parse_metric_from_text(text: &str, prefix: &str) -> Option<f64> {
    let start = text.find(prefix)?;
    let value = &text[start + prefix.len()..];
    let token = value
        .split(|ch: char| ch == ',' || ch.is_whitespace())
        .next()
        .unwrap_or_default();
    token.parse::<f64>().ok()
}

fn stance_bucket_from_evidence(
    evidence: &ResearchEvidenceRecord,
) -> SmartCoreHeadBucketNormalizedValue {
    let change = evidence
        .summary
        .as_deref()
        .and_then(|text| parse_metric_from_text(text, "price_change_pct="))
        .or_else(|| {
            evidence
                .evidence_notes
                .iter()
                .find_map(|note| parse_metric_from_text(note, "price_change_pct="))
        })
        .unwrap_or(0.0);
    if change >= 0.01 {
        SmartCoreHeadBucketNormalizedValue::PositiveLike
    } else if change <= -0.01 {
        SmartCoreHeadBucketNormalizedValue::NegativeLike
    } else {
        SmartCoreHeadBucketNormalizedValue::NeutralLike
    }
}

fn risk_bucket_from_evidence(
    evidence: &ResearchEvidenceRecord,
) -> SmartCoreHeadBucketNormalizedValue {
    let volatility = evidence
        .summary
        .as_deref()
        .and_then(|text| parse_metric_from_text(text, "volatility_hint="));
    let change = evidence
        .summary
        .as_deref()
        .and_then(|text| parse_metric_from_text(text, "price_change_pct="))
        .or_else(|| {
            evidence
                .evidence_notes
                .iter()
                .find_map(|note| parse_metric_from_text(note, "price_change_pct="))
        })
        .unwrap_or(0.0)
        .abs();
    match volatility.unwrap_or(change) {
        value if value >= 0.08 => SmartCoreHeadBucketNormalizedValue::RiskHigh,
        value if value >= 0.03 => SmartCoreHeadBucketNormalizedValue::RiskMedium,
        _ => SmartCoreHeadBucketNormalizedValue::RiskLow,
    }
}

fn confidence_bucket_from_replay_confidence(
    confidence: ReplayLabelConfidence,
) -> SmartCoreHeadBucketNormalizedValue {
    match confidence {
        ReplayLabelConfidence::High => SmartCoreHeadBucketNormalizedValue::ConfidenceHigh,
        ReplayLabelConfidence::Medium => SmartCoreHeadBucketNormalizedValue::ConfidenceMedium,
        ReplayLabelConfidence::Low | ReplayLabelConfidence::ReviewRequired => {
            SmartCoreHeadBucketNormalizedValue::ConfidenceLow
        }
    }
}

fn core_calibration_target_source_for_evidence(
    evidence: &ResearchEvidenceRecord,
) -> CoreCalibrationTargetSource {
    match evidence.kind {
        ResearchEvidenceKind::PriceMove => CoreCalibrationTargetSource::PriceMoveEvidence,
        ResearchEvidenceKind::NewsHeadline => CoreCalibrationTargetSource::ResearchEvidence,
        ResearchEvidenceKind::SourceTrust => CoreCalibrationTargetSource::ReviewRequired,
        ResearchEvidenceKind::ContradictoryEvidence
        | ResearchEvidenceKind::SupportingEvidence
        | ResearchEvidenceKind::PaperOutcomeEvidenceCandidate
        | ResearchEvidenceKind::CoverageGapEvidence => {
            CoreCalibrationTargetSource::ResearchEvidence
        }
    }
}

fn core_calibration_label_confidence_for_candidate(
    evidence: &ResearchEvidenceRecord,
    trust_status: SourceTrustStatus,
) -> ReplayLabelConfidence {
    match trust_status {
        SourceTrustStatus::Trusted => evidence.evidence_confidence,
        SourceTrustStatus::UsableWithWarnings => match evidence.evidence_confidence {
            ReplayLabelConfidence::High => ReplayLabelConfidence::Medium,
            ReplayLabelConfidence::Medium | ReplayLabelConfidence::Low => {
                ReplayLabelConfidence::Low
            }
            ReplayLabelConfidence::ReviewRequired => ReplayLabelConfidence::ReviewRequired,
        },
        SourceTrustStatus::ReviewRequired | SourceTrustStatus::Rejected => {
            ReplayLabelConfidence::ReviewRequired
        }
    }
}

pub fn build_core_calibration_target_candidates(
    evidence_bundle: &ResearchEvidenceBundle,
    mismatch_data_needs: &[SmartCoreMismatchDataNeedRecord],
) -> Vec<CoreCalibrationTargetCandidate> {
    let mut candidates = Vec::new();
    for evidence in &evidence_bundle.records {
        let Some(need_record) =
            mismatch_need_record_for_task_id(evidence.task_id.as_deref(), mismatch_data_needs)
        else {
            continue;
        };
        let trust_status = trust_status_for_evidence(evidence_bundle, evidence);
        let target_source = core_calibration_target_source_for_evidence(evidence);
        let (head, target_bucket) = match need_record.data_need {
            SmartCoreMismatchDataNeed::MoreRiskLabels
            | SmartCoreMismatchDataNeed::MoreRiskVetoCases => (
                Some(SmartCoreShadowHeadKind::Risk),
                Some(risk_bucket_from_evidence(evidence)),
            ),
            SmartCoreMismatchDataNeed::MoreNeedMoreEvidenceCases
            | SmartCoreMismatchDataNeed::MoreEvidenceLabels
            | SmartCoreMismatchDataNeed::MoreContradictoryEvidence => (
                Some(SmartCoreShadowHeadKind::EvidenceNeed),
                Some(SmartCoreHeadBucketNormalizedValue::NeedMoreEvidence),
            ),
            SmartCoreMismatchDataNeed::MoreStanceLabels
            | SmartCoreMismatchDataNeed::MorePositiveOutcomeExamples
            | SmartCoreMismatchDataNeed::MoreNegativeOutcomeExamples
            | SmartCoreMismatchDataNeed::MorePriceEvidence
            | SmartCoreMismatchDataNeed::MoreNewsContext => (
                Some(SmartCoreShadowHeadKind::Stance),
                Some(if evidence.kind == ResearchEvidenceKind::PriceMove {
                    stance_bucket_from_evidence(evidence)
                } else {
                    SmartCoreHeadBucketNormalizedValue::Unknown
                }),
            ),
            SmartCoreMismatchDataNeed::MoreConfidenceCalibrationLabels => (
                Some(SmartCoreShadowHeadKind::ConfidenceCalibration),
                Some(confidence_bucket_from_replay_confidence(
                    evidence.evidence_confidence,
                )),
            ),
            SmartCoreMismatchDataNeed::MoreUncertaintyLabels => (
                Some(SmartCoreShadowHeadKind::Uncertainty),
                Some(confidence_bucket_from_replay_confidence(
                    evidence.evidence_confidence,
                )),
            ),
            SmartCoreMismatchDataNeed::MoreMemberSpecificExamples
            | SmartCoreMismatchDataNeed::MoreMarketScopeCoverage
            | SmartCoreMismatchDataNeed::KeepObserving => (
                Some(need_record.head),
                Some(SmartCoreHeadBucketNormalizedValue::Unknown),
            ),
        };
        candidates.push(CoreCalibrationTargetCandidate {
            candidate_id: format!("core-calibration-candidate-{}", evidence.evidence_id),
            source_task_id: evidence
                .task_id
                .clone()
                .unwrap_or_else(|| "no-task".to_string()),
            source_evidence_id: evidence.evidence_id.clone(),
            member_id: evidence.member_id.clone(),
            symbol: evidence.symbol.clone(),
            market_scope: evidence.market_scope,
            head,
            target_bucket,
            target_source,
            source_trust_status: trust_status,
            label_confidence: core_calibration_label_confidence_for_candidate(
                evidence,
                trust_status,
            ),
            approval_status: CoreCalibrationTargetApprovalStatus::Candidate,
            paper_only: true,
        });
    }
    candidates.sort_by(|left, right| left.candidate_id.cmp(&right.candidate_id));
    candidates
}

pub fn approve_core_calibration_target_candidates(
    candidates: &[CoreCalibrationTargetCandidate],
    policy: &CoreCalibrationTargetApprovalPolicy,
) -> CoreCalibrationTargetApprovalResult {
    let mut approved_candidates = Vec::new();
    let mut review_candidates = Vec::new();
    let mut rejected_candidates = Vec::new();
    for candidate in candidates {
        let mut candidate = candidate.clone();
        let invalid_member = policy.require_member_id && candidate.member_id.trim().is_empty();
        let invalid_head = policy.require_head && candidate.head.is_none();
        let invalid_target = policy.require_target_bucket && candidate.target_bucket.is_none();
        let unknown_target = matches!(
            candidate.target_bucket,
            Some(SmartCoreHeadBucketNormalizedValue::Unknown)
                | Some(SmartCoreHeadBucketNormalizedValue::Deferred)
        );
        let trusted_price_target_supported = matches!(
            candidate.head,
            Some(SmartCoreShadowHeadKind::Stance) | Some(SmartCoreShadowHeadKind::Risk)
        ) && candidate.symbol.is_some()
            && candidate.market_scope.is_some();
        candidate.approval_status = if invalid_member || invalid_head || invalid_target {
            CoreCalibrationTargetApprovalStatus::Rejected
        } else if candidate.source_trust_status == SourceTrustStatus::Rejected {
            CoreCalibrationTargetApprovalStatus::Rejected
        } else if candidate.source_trust_status == SourceTrustStatus::ReviewRequired {
            CoreCalibrationTargetApprovalStatus::NeedsReview
        } else if candidate.source_trust_status == SourceTrustStatus::UsableWithWarnings
            && !policy.allow_low_trust_targets
        {
            CoreCalibrationTargetApprovalStatus::NeedsReview
        } else if unknown_target {
            CoreCalibrationTargetApprovalStatus::NeedsReview
        } else {
            match candidate.target_source {
                CoreCalibrationTargetSource::PriceMoveEvidence
                    if policy.allow_trusted_price_evidence && trusted_price_target_supported =>
                {
                    CoreCalibrationTargetApprovalStatus::Approved
                }
                CoreCalibrationTargetSource::PriceMoveEvidence => {
                    CoreCalibrationTargetApprovalStatus::NeedsReview
                }
                CoreCalibrationTargetSource::MemberOpinion
                    if policy.allow_member_opinion_targets =>
                {
                    CoreCalibrationTargetApprovalStatus::Approved
                }
                CoreCalibrationTargetSource::ReplayLabel if policy.allow_replay_label_targets => {
                    CoreCalibrationTargetApprovalStatus::Approved
                }
                CoreCalibrationTargetSource::RiskGovernorStatus
                    if policy.allow_risk_governor_targets =>
                {
                    CoreCalibrationTargetApprovalStatus::Approved
                }
                CoreCalibrationTargetSource::PaperOutcomeLabel
                    if policy.allow_replay_label_targets =>
                {
                    CoreCalibrationTargetApprovalStatus::Approved
                }
                CoreCalibrationTargetSource::ResearchEvidence if policy.allow_news_only_targets => {
                    CoreCalibrationTargetApprovalStatus::Approved
                }
                CoreCalibrationTargetSource::ReviewRequired
                | CoreCalibrationTargetSource::ResearchEvidence => {
                    CoreCalibrationTargetApprovalStatus::NeedsReview
                }
                _ => CoreCalibrationTargetApprovalStatus::Rejected,
            }
        };
        match candidate.approval_status {
            CoreCalibrationTargetApprovalStatus::Approved => approved_candidates.push(candidate),
            CoreCalibrationTargetApprovalStatus::NeedsReview => review_candidates.push(candidate),
            CoreCalibrationTargetApprovalStatus::Rejected => rejected_candidates.push(candidate),
            CoreCalibrationTargetApprovalStatus::Candidate => {}
        }
    }
    CoreCalibrationTargetApprovalResult {
        candidate_count: candidates.len(),
        approved_count: approved_candidates.len(),
        needs_review_count: review_candidates.len(),
        rejected_count: rejected_candidates.len(),
        approved_candidates,
        review_candidates,
        rejected_candidates,
        paper_only: true,
    }
}

fn core_calibration_label_source_from_candidate_source(
    source: CoreCalibrationTargetSource,
) -> CoreCalibrationLabelSource {
    match source {
        CoreCalibrationTargetSource::MemberOpinion => {
            CoreCalibrationLabelSource::ShadowMemberOpinion
        }
        CoreCalibrationTargetSource::ReplayLabel => CoreCalibrationLabelSource::ReplayLabel,
        CoreCalibrationTargetSource::RiskGovernorStatus => {
            CoreCalibrationLabelSource::RiskGovernorStatus
        }
        CoreCalibrationTargetSource::PaperOutcomeLabel
        | CoreCalibrationTargetSource::ResearchEvidence
        | CoreCalibrationTargetSource::PriceMoveEvidence
        | CoreCalibrationTargetSource::ReviewRequired => {
            CoreCalibrationLabelSource::PaperOutcomeLabel
        }
    }
}

fn core_calibration_example_from_candidate(
    candidate: &CoreCalibrationTargetCandidate,
) -> Option<CoreCalibrationExample> {
    let head = candidate.head?;
    let target_bucket = candidate.target_bucket?;
    Some(CoreCalibrationExample {
        calibration_example_id: format!("core-calibration-example-{}", candidate.candidate_id),
        member_id: candidate.member_id.clone(),
        debug_output_id: candidate.source_evidence_id.clone(),
        target_id: Some(candidate.candidate_id.clone()),
        symbol: candidate.symbol.clone(),
        market_scope: candidate.market_scope,
        head,
        debug_bucket: "Deferred".to_string(),
        target_bucket: normalized_bucket_label(target_bucket),
        alignment: SmartCoreShadowAlignmentStatus::Deferred,
        mismatch_type: None,
        suggested_data_need: SmartCoreMismatchDataNeed::KeepObserving,
        label_source: core_calibration_label_source_from_candidate_source(candidate.target_source),
        label_confidence: candidate.label_confidence,
        paper_only: true,
    })
}

fn core_calibration_example_dedupe_key(example: &CoreCalibrationExample) -> String {
    format!(
        "{}|{:?}|{:?}|{:?}|{}",
        example.member_id,
        example.head,
        example.symbol,
        example.market_scope,
        example.target_bucket
    )
}

pub fn refresh_core_calibration_dataset(
    existing_dataset: Option<&CoreCalibrationDataset>,
    approved_candidates: &[CoreCalibrationTargetCandidate],
    config: &CoreCalibrationDatasetRefreshConfig,
) -> Result<CoreCalibrationDatasetRefreshResult, String> {
    if !config.paper_only {
        return Err("core calibration dataset refresh must be paper-only".to_string());
    }
    if let Some(path) = config.output_dataset_path.as_ref() {
        validate_local_json_path(
            Path::new(path),
            "core calibration dataset refresh output path",
        )?;
    }
    let loaded_dataset = if let Some(path) = config.existing_dataset_path.as_ref() {
        Some(load_core_calibration_dataset_from_local_json(Path::new(
            path,
        ))?)
    } else {
        None
    };
    let base_dataset = existing_dataset
        .cloned()
        .or(loaded_dataset)
        .unwrap_or_else(|| build_core_calibration_dataset(&[]));
    let previous_example_count = if config.include_existing {
        base_dataset.example_count
    } else {
        0
    };
    let mut combined_examples = if config.include_existing {
        base_dataset.examples.clone()
    } else {
        Vec::new()
    };
    let mut seen = combined_examples
        .iter()
        .map(core_calibration_example_dedupe_key)
        .collect::<std::collections::BTreeSet<_>>();
    let mut duplicate_count = 0;
    let mut added_example_count = 0;
    if config.include_approved_candidates {
        for candidate in approved_candidates.iter().filter(|candidate| {
            candidate.approval_status == CoreCalibrationTargetApprovalStatus::Approved
        }) {
            let Some(example) = core_calibration_example_from_candidate(candidate) else {
                duplicate_count += 1;
                continue;
            };
            let key = core_calibration_example_dedupe_key(&example);
            if config.dedupe_by_member_head_symbol_target && !seen.insert(key) {
                duplicate_count += 1;
                continue;
            }
            combined_examples.push(example);
            added_example_count += 1;
        }
    }
    let refreshed_dataset = build_core_calibration_dataset(&combined_examples);
    if !config.dry_run {
        if let Some(path) = config.output_dataset_path.as_ref() {
            save_core_calibration_dataset_to_local_json(&refreshed_dataset, Path::new(path))?;
        }
    }
    let quality_summary = summarize_core_calibration_quality(&refreshed_dataset);
    let refresh_status = if added_example_count == 0 {
        CoreCalibrationDatasetRefreshStatus::NoChange
    } else if config.dry_run || duplicate_count > 0 {
        CoreCalibrationDatasetRefreshStatus::RefreshedWithWarnings
    } else {
        CoreCalibrationDatasetRefreshStatus::Refreshed
    };
    Ok(CoreCalibrationDatasetRefreshResult {
        previous_example_count,
        added_example_count,
        duplicate_count,
        new_example_count: refreshed_dataset.example_count,
        refreshed_dataset,
        quality_summary,
        refresh_status,
        paper_only: true,
    })
}

fn shadow_bucket_value_from_label(label: &str) -> SmartCoreHeadBucketNormalizedValue {
    match label {
        "PositiveLike" => SmartCoreHeadBucketNormalizedValue::PositiveLike,
        "NeutralLike" => SmartCoreHeadBucketNormalizedValue::NeutralLike,
        "NegativeLike" => SmartCoreHeadBucketNormalizedValue::NegativeLike,
        "RiskHigh" => SmartCoreHeadBucketNormalizedValue::RiskHigh,
        "RiskMedium" => SmartCoreHeadBucketNormalizedValue::RiskMedium,
        "RiskLow" => SmartCoreHeadBucketNormalizedValue::RiskLow,
        "NeedMoreEvidence" => SmartCoreHeadBucketNormalizedValue::NeedMoreEvidence,
        "EvidenceSufficient" => SmartCoreHeadBucketNormalizedValue::EvidenceSufficient,
        "ConfidenceHigh" => SmartCoreHeadBucketNormalizedValue::ConfidenceHigh,
        "ConfidenceMedium" => SmartCoreHeadBucketNormalizedValue::ConfidenceMedium,
        "ConfidenceLow" => SmartCoreHeadBucketNormalizedValue::ConfidenceLow,
        "Deferred" => SmartCoreHeadBucketNormalizedValue::Deferred,
        _ => SmartCoreHeadBucketNormalizedValue::Unknown,
    }
}

fn build_shadow_alignment_targets_from_core_calibration_dataset(
    dataset: &CoreCalibrationDataset,
) -> Vec<SmartCoreShadowAlignmentTarget> {
    dataset
        .examples
        .iter()
        .filter_map(|example| {
            let value = shadow_bucket_value_from_label(&example.target_bucket);
            let mut target = SmartCoreShadowAlignmentTarget {
                target_id: example
                    .target_id
                    .clone()
                    .unwrap_or_else(|| example.calibration_example_id.clone()),
                member_id: example.member_id.clone(),
                symbol: example.symbol.clone(),
                market_scope: example.market_scope,
                source_type: match example.label_source {
                    CoreCalibrationLabelSource::ShadowMemberOpinion => {
                        SmartCoreShadowAlignmentTargetSourceType::MemberOpinion
                    }
                    CoreCalibrationLabelSource::ReplayLabel => {
                        SmartCoreShadowAlignmentTargetSourceType::ReplayTargetLabel
                    }
                    CoreCalibrationLabelSource::RiskGovernorStatus => {
                        SmartCoreShadowAlignmentTargetSourceType::RiskGovernorStatus
                    }
                    CoreCalibrationLabelSource::PaperOutcomeLabel => {
                        SmartCoreShadowAlignmentTargetSourceType::PaperOutcomeLabel
                    }
                },
                stance_target: None,
                risk_target: None,
                evidence_target: None,
                confidence_target: None,
                outcome_target: None,
                paper_only: true,
            };
            match example.head {
                SmartCoreShadowHeadKind::Stance => target.stance_target = Some(value),
                SmartCoreShadowHeadKind::Risk => target.risk_target = Some(value),
                SmartCoreShadowHeadKind::EvidenceNeed => target.evidence_target = Some(value),
                SmartCoreShadowHeadKind::ConfidenceCalibration => {
                    target.confidence_target = Some(value)
                }
                SmartCoreShadowHeadKind::Uncertainty
                | SmartCoreShadowHeadKind::ExpectedReturnHint => return None,
            }
            Some(target)
        })
        .collect()
}

pub fn recheck_smartcore_shadow_alignment(
    debug_output_batch: &SmartCoreDebugOutputBatchV0,
    refreshed_calibration_dataset: &CoreCalibrationDataset,
    previous_alignment_summary: Option<&SmartCoreShadowAlignmentSummary>,
    config: &SmartCoreShadowAlignmentRecheckConfig,
) -> SmartCoreShadowAlignmentRecheckResult {
    let targets = if config.use_refreshed_calibration_targets {
        build_shadow_alignment_targets_from_core_calibration_dataset(refreshed_calibration_dataset)
    } else {
        Vec::new()
    };
    let mut alignment_records = Vec::new();
    for debug_output in &debug_output_batch.member_outputs {
        for target in targets
            .iter()
            .filter(|target| target.member_id == debug_output.member_id)
        {
            alignment_records.push(compare_smartcore_debug_output_to_target(
                debug_output,
                target,
            ));
        }
    }
    let alignment_summary = summarize_smartcore_shadow_alignment(&alignment_records);
    let mismatch_records = build_smartcore_shadow_mismatch_records(&alignment_records);
    let previous_mismatch_count = previous_alignment_summary.map(|summary| summary.mismatch_count);
    let previous_target_count = previous_alignment_summary.map(|summary| summary.record_count);
    let mismatch_delta =
        previous_mismatch_count.map(|count| mismatch_records.len() as isize - count as isize);
    let target_delta = previous_target_count.map(|count| targets.len() as isize - count as isize);
    let recheck_status = if targets.is_empty() {
        SmartCoreShadowAlignmentRecheckStatus::InsufficientTargets
    } else if matches!(
        alignment_summary.alignment_status,
        SmartCoreShadowAlignmentSummaryStatus::DebugOnly
    ) {
        SmartCoreShadowAlignmentRecheckStatus::DebugOnly
    } else if mismatch_delta.unwrap_or(0) < 0 {
        SmartCoreShadowAlignmentRecheckStatus::Improved
    } else if mismatch_delta.unwrap_or(0) > 0 {
        SmartCoreShadowAlignmentRecheckStatus::Worse
    } else {
        SmartCoreShadowAlignmentRecheckStatus::NoChange
    };
    SmartCoreShadowAlignmentRecheckResult {
        previous_alignment_status: previous_alignment_summary
            .map(|summary| summary.alignment_status),
        new_alignment_status: alignment_summary.alignment_status,
        previous_mismatch_count,
        new_mismatch_count: mismatch_records.len(),
        previous_target_count,
        new_target_count: targets.len(),
        mismatch_delta,
        target_delta,
        recheck_status,
        paper_only: true,
    }
}

fn mismatch_learning_loop_requested_from_flags(
    enabled: bool,
    _dry_run: bool,
    execute_research_tasks: bool,
    approve_targets: bool,
    refresh_calibration_dataset: bool,
    recheck_alignment: bool,
    calibration_dataset_input_path: Option<&String>,
    calibration_dataset_output_path: Option<&String>,
    loop_output_path: Option<&String>,
) -> bool {
    enabled
        || execute_research_tasks
        || approve_targets
        || refresh_calibration_dataset
        || recheck_alignment
        || calibration_dataset_input_path.is_some()
        || calibration_dataset_output_path.is_some()
        || loop_output_path.is_some()
}

fn build_owner_core_calibration_debug_summary_from_learning_loop(
    loop_result: &SmartCoreMismatchLearningLoopResult,
) -> OwnerCoreCalibrationDebugSummary {
    OwnerCoreCalibrationDebugSummary {
        summary_id: format!("{}-owner-core-calibration-loop", loop_result.run_id),
        mismatch_count: loop_result
            .alignment_recheck_result
            .as_ref()
            .and_then(|result| result.previous_mismatch_count)
            .unwrap_or(0),
        dominant_data_needs: Vec::new(),
        generated_research_task_count: loop_result.executed_research_task_count,
        calibration_example_count: loop_result.calibration_dataset_new_count,
        research_task_executed_count: loop_result.executed_research_task_count,
        evidence_generated_count: loop_result.generated_evidence_count,
        calibration_target_candidate_count: loop_result.target_candidate_count,
        approved_calibration_target_count: loop_result.approved_target_count,
        refreshed_calibration_example_count: loop_result.calibration_dataset_new_count,
        alignment_mismatch_delta: loop_result.alignment_mismatch_delta,
        message: format!(
            "Core mismatches produced research tasks. Approved calibration targets were added only for safe evidence. This remains debug-only and is not used for decisions. executed_tasks={}, approved_targets={}",
            loop_result.executed_research_task_count, loop_result.approved_target_count
        ),
        debug_only: true,
        not_investment_signal: true,
        not_committee_opinion: true,
        paper_only: true,
    }
}

pub fn evaluate_mismatch_learning_no_decision_guard(
    loop_result: &SmartCoreMismatchLearningLoopResult,
    batch_result_before: &BatchCommitteeCycleResult,
    batch_result_after: Option<&BatchCommitteeCycleResult>,
) -> SmartCoreMismatchLearningNoDecisionGuard {
    let task_markers = loop_result
        .task_execution_result
        .as_ref()
        .map(|result| {
            result
                .evidence_bundle
                .records
                .iter()
                .filter_map(|record| record.task_id.clone())
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    let target_markers = loop_result
        .target_approval_result
        .as_ref()
        .map(|result| {
            result
                .approved_candidates
                .iter()
                .map(|candidate| candidate.candidate_id.clone())
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    let dataset_markers = loop_result
        .calibration_dataset_refresh_result
        .as_ref()
        .map(|result| vec![result.refreshed_dataset.dataset_id.clone()])
        .unwrap_or_default();
    let debug_markers = vec![format!(
        "{}-owner-core-calibration-loop",
        loop_result.run_id
    )];
    let research_tasks_changed_decision =
        value_contains_debug_marker(&batch_result_before.committee_sessions, &task_markers)
            || value_contains_debug_marker(&batch_result_before.chairman_decisions, &task_markers)
            || batch_result_after
                .map(|after| after.chairman_decisions != batch_result_before.chairman_decisions)
                .unwrap_or(false);
    let calibration_targets_used_as_opinion =
        value_contains_debug_marker(&batch_result_before.member_opinions, &target_markers);
    let calibration_dataset_used_in_committee =
        value_contains_debug_marker(&batch_result_before.committee_sessions, &dataset_markers)
            || value_contains_debug_marker(
                &batch_result_before.chairman_decisions,
                &dataset_markers,
            );
    let alignment_recheck_changed_risk_governor = batch_result_after
        .map(|after| {
            after
                .chairman_decisions
                .iter()
                .map(|decision| decision.risk_governor_status)
                .collect::<Vec<_>>()
                != batch_result_before
                    .chairman_decisions
                    .iter()
                    .map(|decision| decision.risk_governor_status)
                    .collect::<Vec<_>>()
        })
        .unwrap_or(false);
    let owner_debug_summary_used_as_trade_signal =
        value_contains_debug_marker(&batch_result_before.event_queue, &debug_markers);
    let mut violations = Vec::new();
    if research_tasks_changed_decision {
        violations.push("mismatch learning research tasks changed decision boundary".to_string());
    }
    if calibration_targets_used_as_opinion {
        violations.push("approved calibration target leaked into member opinion".to_string());
    }
    if calibration_dataset_used_in_committee {
        violations.push("calibration dataset leaked into committee path".to_string());
    }
    if alignment_recheck_changed_risk_governor {
        violations.push("alignment recheck changed risk governor outcome".to_string());
    }
    if owner_debug_summary_used_as_trade_signal {
        violations.push("owner debug summary leaked into trade signal path".to_string());
    }
    SmartCoreMismatchLearningNoDecisionGuard {
        research_tasks_changed_decision,
        calibration_targets_used_as_opinion,
        calibration_dataset_used_in_committee,
        alignment_recheck_changed_risk_governor,
        owner_debug_summary_used_as_trade_signal,
        guard_status: if violations.is_empty() {
            SmartCoreNoDecisionBridgeGuardStatus::Preserved
        } else {
            SmartCoreNoDecisionBridgeGuardStatus::Violated
        },
        violations,
        paper_only: true,
    }
}

fn run_smartcore_mismatch_learning_loop_with_seed(
    shadow_alignment_result: &SmartCoreShadowAlignmentRunResult,
    source_registry: &ResearchSourceRegistry,
    existing_calibration_dataset: Option<&CoreCalibrationDataset>,
    debug_output_batch: &SmartCoreDebugOutputBatchV0,
    config: &SmartCoreMismatchLearningLoopConfig,
    seed_result: Option<&SmartCoreMismatchSelfGrowingRunResult>,
) -> Result<SmartCoreMismatchLearningLoopResult, String> {
    if !config.paper_only {
        return Err("smartcore mismatch learning loop must be paper-only".to_string());
    }
    let seed_storage;
    let seed = if let Some(seed_result) = seed_result {
        seed_result
    } else {
        seed_storage = run_smartcore_mismatch_self_growing_pipeline(
            shadow_alignment_result,
            &SmartCoreMismatchSelfGrowingRunConfig {
                run_id: format!("{}-seed", config.run_id),
                enabled: true,
                max_tasks_total: default_smartcore_mismatch_max_tasks_total(),
                max_tasks_per_member: default_smartcore_mismatch_max_tasks_per_member(),
                core_calibration_dataset_output_path: None,
                mismatch_task_output_path: None,
                emit_owner_console_summary: false,
                paper_only: true,
            },
        )?;
        &seed_storage
    };
    let task_execution_result = if config.execute_research_tasks {
        Some(execute_mismatch_research_tasks(
            &seed.research_task_generation_result.generated_tasks.tasks,
            source_registry,
            &MismatchResearchTaskExecutionConfig {
                run_id: format!("{}-task-execution", config.run_id),
                task_input_path: None,
                source_registry_path: None,
                max_tasks: seed
                    .research_task_generation_result
                    .generated_tasks
                    .tasks
                    .len()
                    .max(1),
                max_evidence_per_task: 8,
                allow_network_sources: false,
                paper_only: true,
            },
        )?)
    } else {
        None
    };
    let empty_bundle = ResearchEvidenceBundle {
        bundle_id: format!("{}-empty-evidence", config.run_id),
        records: Vec::new(),
        source_scores: Vec::new(),
        task_count: 0,
        evidence_count: 0,
        paper_only: true,
    };
    let evidence_bundle = task_execution_result
        .as_ref()
        .map(|result| &result.evidence_bundle)
        .unwrap_or(&empty_bundle);
    let target_candidates = if config.build_target_candidates {
        build_core_calibration_target_candidates(evidence_bundle, &seed.mismatch_data_need_records)
    } else {
        Vec::new()
    };
    let target_approval_result = if config.approve_targets {
        Some(approve_core_calibration_target_candidates(
            &target_candidates,
            &CoreCalibrationTargetApprovalPolicy::default(),
        ))
    } else {
        None
    };
    let base_dataset = existing_calibration_dataset.unwrap_or(&seed.core_calibration_dataset);
    let calibration_dataset_refresh_result = if config.refresh_calibration_dataset {
        Some(refresh_core_calibration_dataset(
            Some(base_dataset),
            target_approval_result
                .as_ref()
                .map(|result| result.approved_candidates.as_slice())
                .unwrap_or(&[]),
            &CoreCalibrationDatasetRefreshConfig {
                run_id: format!("{}-dataset-refresh", config.run_id),
                existing_dataset_path: None,
                output_dataset_path: None,
                include_existing: true,
                include_approved_candidates: true,
                dedupe_by_member_head_symbol_target: true,
                dry_run: config.dry_run,
                paper_only: true,
            },
        )?)
    } else {
        None
    };
    let recheck_dataset = calibration_dataset_refresh_result
        .as_ref()
        .map(|result| &result.refreshed_dataset)
        .unwrap_or(base_dataset);
    let alignment_recheck_result = if config.recheck_alignment {
        Some(recheck_smartcore_shadow_alignment(
            debug_output_batch,
            recheck_dataset,
            Some(&shadow_alignment_result.alignment_summary),
            &SmartCoreShadowAlignmentRecheckConfig {
                run_id: format!("{}-alignment-recheck", config.run_id),
                use_refreshed_calibration_targets: true,
                compare_previous_summary: true,
                paper_only: true,
            },
        ))
    } else {
        None
    };
    let calibration_dataset_previous_count = base_dataset.example_count;
    let calibration_dataset_new_count = calibration_dataset_refresh_result
        .as_ref()
        .map(|result| result.new_example_count)
        .unwrap_or(calibration_dataset_previous_count);
    let executed_research_task_count = task_execution_result
        .as_ref()
        .map(|result| result.executed_task_count)
        .unwrap_or(0);
    let generated_evidence_count = task_execution_result
        .as_ref()
        .map(|result| result.generated_evidence_count)
        .unwrap_or(0);
    let approved_target_count = target_approval_result
        .as_ref()
        .map(|result| result.approved_count)
        .unwrap_or(0);
    let mut loop_status = SmartCoreMismatchLearningLoopStatus::Passed;
    if config.dry_run
        || executed_research_task_count == 0
        || approved_target_count == 0
        || alignment_recheck_result.is_none()
    {
        loop_status = SmartCoreMismatchLearningLoopStatus::PassedWithWarnings;
    }
    Ok(SmartCoreMismatchLearningLoopResult {
        run_id: config.run_id.clone(),
        task_execution_result,
        target_candidate_count: target_candidates.len(),
        target_candidates,
        target_approval_result,
        approved_target_count,
        calibration_dataset_refresh_result,
        alignment_recheck_result: alignment_recheck_result.clone(),
        no_decision_guard: None,
        no_decision_guard_status: SmartCoreNoDecisionBridgeGuardStatus::Preserved,
        executed_research_task_count,
        generated_evidence_count,
        calibration_dataset_previous_count,
        calibration_dataset_new_count,
        alignment_mismatch_delta: alignment_recheck_result.and_then(|result| result.mismatch_delta),
        loop_status,
        safety_summary: safety_summary(),
        debug_only: true,
        not_investment_signal: true,
        not_committee_opinion: true,
        paper_only_warning:
            "smartcore mismatch learning loop is paper-only diagnostics; it can collect evidence, refresh calibration targets, and recheck shadow alignment but cannot trade, train, or alter decisions"
                .to_string(),
        paper_only: true,
    })
}

pub fn run_smartcore_mismatch_learning_loop(
    shadow_alignment_result: &SmartCoreShadowAlignmentRunResult,
    source_registry: &ResearchSourceRegistry,
    existing_calibration_dataset: Option<&CoreCalibrationDataset>,
    debug_output_batch: &SmartCoreDebugOutputBatchV0,
    config: &SmartCoreMismatchLearningLoopConfig,
) -> Result<SmartCoreMismatchLearningLoopResult, String> {
    run_smartcore_mismatch_learning_loop_with_seed(
        shadow_alignment_result,
        source_registry,
        existing_calibration_dataset,
        debug_output_batch,
        config,
        None,
    )
}

fn maybe_run_smartcore_mismatch_learning_loop_for_batch_result(
    run_id: String,
    enabled: bool,
    dry_run: bool,
    execute_research_tasks: bool,
    approve_calibration_targets: bool,
    refresh_calibration_dataset: bool,
    recheck_alignment: bool,
    research_source_registry_path: Option<&String>,
    calibration_dataset_input_path: Option<&String>,
    calibration_dataset_output_path: Option<&String>,
    loop_output_path: Option<&String>,
    batch_result: &mut BatchCommitteeCycleResult,
) -> Result<Option<SmartCoreMismatchLearningLoopResult>, String> {
    if !mismatch_learning_loop_requested_from_flags(
        enabled,
        dry_run,
        execute_research_tasks,
        approve_calibration_targets,
        refresh_calibration_dataset,
        recheck_alignment,
        calibration_dataset_input_path,
        calibration_dataset_output_path,
        loop_output_path,
    ) {
        return Ok(None);
    }
    if let Some(path) = loop_output_path {
        validate_local_json_path(
            Path::new(path),
            "smartcore mismatch learning loop output path",
        )?;
    }
    let shadow_alignment_result = batch_result
        .smartcore_shadow_alignment_run_result
        .as_ref()
        .ok_or_else(|| {
            "smartcore mismatch learning loop requires shadow alignment result".to_string()
        })?
        .clone();
    let debug_output_batch = batch_result
        .smartcore_head_projection_dry_run_result
        .as_ref()
        .ok_or_else(|| {
            "smartcore mismatch learning loop requires head projection debug output".to_string()
        })?
        .debug_output_batch
        .clone();
    let source_registry = if execute_research_tasks {
        let path = research_source_registry_path.ok_or_else(|| {
            "smartcore mismatch learning loop requires research_source_registry_path".to_string()
        })?;
        ResearchSourceRegistry::load_from_local_json(Path::new(path))?
    } else {
        empty_research_source_registry()
    };
    let loaded_dataset = if let Some(path) = calibration_dataset_input_path {
        let path = Path::new(path);
        validate_local_json_path(path, "smartcore calibration dataset input path")?;
        if path.exists() {
            Some(load_core_calibration_dataset_from_local_json(path)?)
        } else {
            None
        }
    } else {
        None
    };
    let existing_dataset = loaded_dataset.as_ref().or_else(|| {
        batch_result
            .smartcore_mismatch_self_growing_run_result
            .as_ref()
            .map(|result| &result.core_calibration_dataset)
    });
    let mut result = run_smartcore_mismatch_learning_loop_with_seed(
        &shadow_alignment_result,
        &source_registry,
        existing_dataset,
        &debug_output_batch,
        &SmartCoreMismatchLearningLoopConfig {
            run_id,
            execute_research_tasks,
            build_target_candidates: true,
            approve_targets: approve_calibration_targets,
            refresh_calibration_dataset,
            recheck_alignment,
            dry_run,
            paper_only: true,
        },
        batch_result
            .smartcore_mismatch_self_growing_run_result
            .as_ref(),
    )?;
    if refresh_calibration_dataset
        && !dry_run
        && calibration_dataset_output_path.is_some()
        && result.calibration_dataset_refresh_result.is_some()
    {
        let refresh_result = result
            .calibration_dataset_refresh_result
            .as_ref()
            .expect("refresh result just checked");
        let updated_refresh = refresh_core_calibration_dataset(
            existing_dataset,
            result
                .target_approval_result
                .as_ref()
                .map(|approval| approval.approved_candidates.as_slice())
                .unwrap_or(&[]),
            &CoreCalibrationDatasetRefreshConfig {
                run_id: format!("{}-dataset-refresh-write", result.run_id),
                existing_dataset_path: None,
                output_dataset_path: calibration_dataset_output_path.cloned(),
                include_existing: true,
                include_approved_candidates: true,
                dedupe_by_member_head_symbol_target: true,
                dry_run: false,
                paper_only: true,
            },
        )?;
        if updated_refresh.new_example_count != refresh_result.new_example_count {
            result.loop_status = SmartCoreMismatchLearningLoopStatus::PassedWithWarnings;
        }
        result.calibration_dataset_refresh_result = Some(updated_refresh);
        result.calibration_dataset_new_count = result
            .calibration_dataset_refresh_result
            .as_ref()
            .map(|refresh| refresh.new_example_count)
            .unwrap_or(result.calibration_dataset_new_count);
    }
    let no_decision_guard =
        evaluate_mismatch_learning_no_decision_guard(&result, batch_result, None);
    result.no_decision_guard_status = no_decision_guard.guard_status;
    result.no_decision_guard = Some(no_decision_guard.clone());
    if matches!(
        no_decision_guard.guard_status,
        SmartCoreNoDecisionBridgeGuardStatus::Violated
    ) {
        result.loop_status = SmartCoreMismatchLearningLoopStatus::Failed;
    }
    if let Some(path) = loop_output_path {
        write_safe_json(Path::new(path), &result)?;
    }
    if let Some(shadow_alignment_result) =
        batch_result.smartcore_shadow_alignment_run_result.as_mut()
    {
        shadow_alignment_result.owner_core_debug_section =
            apply_owner_core_calibration_debug_update(
                &batch_result.batch_id,
                shadow_alignment_result.owner_core_debug_section.take(),
                Some(build_owner_core_calibration_debug_summary_from_learning_loop(&result)),
            );
        shadow_alignment_result.owner_core_debug_card_count = shadow_alignment_result
            .owner_core_debug_section
            .as_ref()
            .map(|section| section.cards.len())
            .unwrap_or(0);
    }
    batch_result.smartcore_mismatch_learning_loop_result = Some(result.clone());
    Ok(Some(result))
}

impl Default for SmartCoreCalibrationOverlayPolicyV0 {
    fn default() -> Self {
        Self {
            min_support_for_active_rule: default_smartcore_recalibration_min_support(),
            max_rules_per_member_head: default_smartcore_recalibration_max_rules_per_member_head(),
            allow_stance_bucket_mapping: true,
            allow_risk_bucket_mapping: true,
            allow_evidence_bucket_mapping: true,
            allow_confidence_adjustment: true,
            allow_expected_return_mapping: false,
            allow_trade_signal_output: false,
            allow_member_opinion_output: false,
            allow_committee_decision_output: false,
            debug_only: true,
            paper_only: true,
        }
    }
}

fn dominant_counted_value<T: Copy + Ord>(values: impl IntoIterator<Item = T>) -> Option<T> {
    let mut counts = std::collections::BTreeMap::new();
    for value in values {
        *counts.entry(value).or_insert(0usize) += 1;
    }
    counts
        .into_iter()
        .max_by(|(left_value, left_count), (right_value, right_count)| {
            left_count
                .cmp(right_count)
                .then_with(|| left_value.cmp(right_value))
        })
        .map(|(value, _)| value)
}

fn dominant_counted_string(values: impl IntoIterator<Item = String>) -> Option<String> {
    let mut counts = std::collections::BTreeMap::new();
    for value in values {
        *counts.entry(value).or_insert(0usize) += 1;
    }
    counts
        .into_iter()
        .max_by(|(left_value, left_count), (right_value, right_count)| {
            left_count
                .cmp(right_count)
                .then_with(|| left_value.cmp(right_value))
        })
        .map(|(value, _)| value)
}

fn safe_ratio(numerator: usize, denominator: usize) -> f64 {
    if denominator == 0 {
        0.0
    } else {
        numerator as f64 / denominator as f64
    }
}

fn calibration_stats_status_for_dataset(
    dataset: &CoreCalibrationDataset,
    per_head_stats: &[SmartCoreHeadCalibrationStatsV0],
) -> SmartCoreCalibrationStatsStatusV0 {
    if !dataset.paper_only || dataset.examples.iter().any(|example| !example.paper_only) {
        return SmartCoreCalibrationStatsStatusV0::Unsafe;
    }
    if dataset.example_count < 4 || per_head_stats.is_empty() {
        SmartCoreCalibrationStatsStatusV0::NeedsMoreTargets
    } else if dataset.example_count < 12
        || per_head_stats.iter().any(|stats| stats.example_count < 2)
    {
        SmartCoreCalibrationStatsStatusV0::ThinData
    } else {
        SmartCoreCalibrationStatsStatusV0::Sufficient
    }
}

pub fn compute_smartcore_calibration_stats_v0(
    calibration_dataset: &CoreCalibrationDataset,
) -> SmartCoreCalibrationStatsSummaryV0 {
    let mut grouped: std::collections::BTreeMap<
        (String, SmartCoreShadowHeadKind),
        Vec<&CoreCalibrationExample>,
    > = std::collections::BTreeMap::new();
    for example in &calibration_dataset.examples {
        grouped
            .entry((example.member_id.clone(), example.head))
            .or_default()
            .push(example);
    }
    let per_head_stats = grouped
        .into_iter()
        .map(|((member_id, head), examples)| {
            let example_count = examples.len();
            let match_count = examples
                .iter()
                .filter(|example| example.alignment == SmartCoreShadowAlignmentStatus::Match)
                .count();
            let mismatch_count = examples
                .iter()
                .filter(|example| example.alignment == SmartCoreShadowAlignmentStatus::Mismatch)
                .count();
            let unknown_count = examples
                .iter()
                .filter(|example| example.alignment == SmartCoreShadowAlignmentStatus::Unknown)
                .count();
            let deferred_count = examples
                .iter()
                .filter(|example| example.alignment == SmartCoreShadowAlignmentStatus::Deferred)
                .count();
            SmartCoreHeadCalibrationStatsV0 {
                stats_id: format!(
                    "{}-{:?}-{}",
                    calibration_dataset.dataset_id, head, member_id
                ),
                member_id,
                head,
                example_count,
                match_count,
                mismatch_count,
                unknown_count,
                deferred_count,
                mismatch_rate: safe_ratio(mismatch_count, example_count),
                dominant_debug_bucket: dominant_counted_string(
                    examples.iter().map(|example| example.debug_bucket.clone()),
                ),
                dominant_target_bucket: dominant_counted_string(
                    examples.iter().map(|example| example.target_bucket.clone()),
                ),
                dominant_mismatch_type: dominant_counted_value(
                    examples.iter().filter_map(|example| example.mismatch_type),
                ),
                paper_only: true,
            }
        })
        .collect::<Vec<_>>();
    let mut per_member_examples: std::collections::BTreeMap<String, Vec<&CoreCalibrationExample>> =
        std::collections::BTreeMap::new();
    for example in &calibration_dataset.examples {
        per_member_examples
            .entry(example.member_id.clone())
            .or_default()
            .push(example);
    }
    let per_member_mismatch_rate = per_member_examples
        .into_iter()
        .map(|(member_id, examples)| {
            let mismatches = examples
                .iter()
                .filter(|example| example.alignment == SmartCoreShadowAlignmentStatus::Mismatch)
                .count();
            (member_id, safe_ratio(mismatches, examples.len()))
        })
        .collect::<std::collections::BTreeMap<_, _>>();
    let stats_status = calibration_stats_status_for_dataset(calibration_dataset, &per_head_stats);
    let member_count = calibration_dataset
        .examples
        .iter()
        .map(|example| example.member_id.clone())
        .collect::<std::collections::BTreeSet<_>>()
        .len();
    let head_count = calibration_dataset
        .examples
        .iter()
        .map(|example| example.head)
        .collect::<std::collections::BTreeSet<_>>()
        .len();
    let overall_mismatch_rate = safe_ratio(
        calibration_dataset
            .examples
            .iter()
            .filter(|example| example.alignment == SmartCoreShadowAlignmentStatus::Mismatch)
            .count(),
        calibration_dataset.example_count,
    );
    SmartCoreCalibrationStatsSummaryV0 {
        summary_id: format!(
            "{}-smartcore-calibration-stats",
            calibration_dataset.dataset_id
        ),
        dataset_id: calibration_dataset.dataset_id.clone(),
        member_count,
        head_count,
        total_examples: calibration_dataset.example_count,
        per_head_stats,
        per_member_mismatch_rate,
        overall_mismatch_rate,
        stats_status,
        paper_only: true,
    }
}

fn risk_bucket_rank(value: SmartCoreHeadBucketNormalizedValue) -> Option<i32> {
    match value {
        SmartCoreHeadBucketNormalizedValue::RiskLow => Some(0),
        SmartCoreHeadBucketNormalizedValue::RiskMedium => Some(1),
        SmartCoreHeadBucketNormalizedValue::RiskHigh => Some(2),
        _ => None,
    }
}

fn confidence_bucket_rank(value: SmartCoreHeadBucketNormalizedValue) -> Option<i32> {
    match value {
        SmartCoreHeadBucketNormalizedValue::ConfidenceLow => Some(0),
        SmartCoreHeadBucketNormalizedValue::ConfidenceMedium => Some(1),
        SmartCoreHeadBucketNormalizedValue::ConfidenceHigh => Some(2),
        _ => None,
    }
}

fn overlay_mapping_allowed(
    head: SmartCoreShadowHeadKind,
    policy: &SmartCoreCalibrationOverlayPolicyV0,
) -> bool {
    match head {
        SmartCoreShadowHeadKind::Stance => policy.allow_stance_bucket_mapping,
        SmartCoreShadowHeadKind::Risk => policy.allow_risk_bucket_mapping,
        SmartCoreShadowHeadKind::EvidenceNeed => policy.allow_evidence_bucket_mapping,
        SmartCoreShadowHeadKind::ConfidenceCalibration | SmartCoreShadowHeadKind::Uncertainty => {
            policy.allow_confidence_adjustment
        }
        SmartCoreShadowHeadKind::ExpectedReturnHint => policy.allow_expected_return_mapping,
    }
}

fn rule_confidence_for_stats(
    stats: &SmartCoreHeadCalibrationStatsV0,
    summary: &SmartCoreCalibrationStatsSummaryV0,
    policy: &SmartCoreCalibrationOverlayPolicyV0,
) -> ReplayLabelConfidence {
    let base = if stats.mismatch_count >= policy.min_support_for_active_rule.saturating_mul(2) {
        ReplayLabelConfidence::High
    } else if stats.mismatch_count >= policy.min_support_for_active_rule {
        ReplayLabelConfidence::Medium
    } else if stats.mismatch_count > 0 {
        ReplayLabelConfidence::Low
    } else {
        ReplayLabelConfidence::ReviewRequired
    };
    match summary.stats_status {
        SmartCoreCalibrationStatsStatusV0::Unsafe => ReplayLabelConfidence::ReviewRequired,
        SmartCoreCalibrationStatsStatusV0::NeedsMoreTargets => {
            if base == ReplayLabelConfidence::High {
                ReplayLabelConfidence::Low
            } else {
                base
            }
        }
        SmartCoreCalibrationStatsStatusV0::ThinData => match base {
            ReplayLabelConfidence::High => ReplayLabelConfidence::Medium,
            value => value,
        },
        SmartCoreCalibrationStatsStatusV0::Sufficient => base,
    }
}

fn rule_action_for_stats(
    stats: &SmartCoreHeadCalibrationStatsV0,
    policy: &SmartCoreCalibrationOverlayPolicyV0,
) -> (
    SmartCoreCalibrationRuleActionV0,
    Option<String>,
    SmartCoreCalibrationRuleStatusV0,
) {
    let Some(from_bucket) = stats.dominant_debug_bucket.as_ref() else {
        return (
            SmartCoreCalibrationRuleActionV0::KeepObserving,
            None,
            SmartCoreCalibrationRuleStatusV0::Disabled,
        );
    };
    let Some(to_bucket) = stats.dominant_target_bucket.as_ref() else {
        return (
            SmartCoreCalibrationRuleActionV0::KeepObserving,
            None,
            SmartCoreCalibrationRuleStatusV0::ObserveOnly,
        );
    };
    if !overlay_mapping_allowed(stats.head, policy) {
        return (
            SmartCoreCalibrationRuleActionV0::KeepObserving,
            None,
            SmartCoreCalibrationRuleStatusV0::Disabled,
        );
    }
    if from_bucket == to_bucket {
        return (
            SmartCoreCalibrationRuleActionV0::Keep,
            Some(to_bucket.clone()),
            SmartCoreCalibrationRuleStatusV0::ObserveOnly,
        );
    }
    let from_value = shadow_bucket_value_from_label(from_bucket);
    let to_value = shadow_bucket_value_from_label(to_bucket);
    match stats.head {
        SmartCoreShadowHeadKind::Risk => {
            let action = match (risk_bucket_rank(from_value), risk_bucket_rank(to_value)) {
                (Some(from_rank), Some(to_rank)) if to_rank > from_rank => {
                    SmartCoreCalibrationRuleActionV0::RaiseRiskBucket
                }
                (Some(from_rank), Some(to_rank)) if to_rank < from_rank => {
                    SmartCoreCalibrationRuleActionV0::LowerRiskBucket
                }
                _ => SmartCoreCalibrationRuleActionV0::MapBucket,
            };
            (
                action,
                Some(to_bucket.clone()),
                SmartCoreCalibrationRuleStatusV0::ObserveOnly,
            )
        }
        SmartCoreShadowHeadKind::EvidenceNeed => (
            if to_value == SmartCoreHeadBucketNormalizedValue::NeedMoreEvidence {
                SmartCoreCalibrationRuleActionV0::RaiseEvidenceNeed
            } else {
                SmartCoreCalibrationRuleActionV0::MapBucket
            },
            Some(to_bucket.clone()),
            SmartCoreCalibrationRuleStatusV0::ObserveOnly,
        ),
        SmartCoreShadowHeadKind::ConfidenceCalibration | SmartCoreShadowHeadKind::Uncertainty => (
            match (
                confidence_bucket_rank(from_value),
                confidence_bucket_rank(to_value),
            ) {
                (Some(from_rank), Some(to_rank)) if to_rank < from_rank => {
                    SmartCoreCalibrationRuleActionV0::LowerConfidence
                }
                _ => SmartCoreCalibrationRuleActionV0::MapBucket,
            },
            Some(to_bucket.clone()),
            SmartCoreCalibrationRuleStatusV0::ObserveOnly,
        ),
        SmartCoreShadowHeadKind::ExpectedReturnHint => (
            SmartCoreCalibrationRuleActionV0::KeepObserving,
            None,
            SmartCoreCalibrationRuleStatusV0::Disabled,
        ),
        SmartCoreShadowHeadKind::Stance => (
            SmartCoreCalibrationRuleActionV0::MapBucket,
            Some(to_bucket.clone()),
            SmartCoreCalibrationRuleStatusV0::ObserveOnly,
        ),
    }
}

pub fn build_smartcore_calibration_rule_table_v0(
    stats_summary: &SmartCoreCalibrationStatsSummaryV0,
    policy: &SmartCoreCalibrationOverlayPolicyV0,
) -> SmartCoreCalibrationRuleTableV0 {
    let mut rules = stats_summary
        .per_head_stats
        .iter()
        .filter(|stats| stats.mismatch_count > 0)
        .map(|stats| {
            let confidence = rule_confidence_for_stats(stats, stats_summary, policy);
            let (action, to_bucket, mut rule_status) = rule_action_for_stats(stats, policy);
            if action == SmartCoreCalibrationRuleActionV0::Keep {
                rule_status = SmartCoreCalibrationRuleStatusV0::ObserveOnly;
            }
            if confidence == ReplayLabelConfidence::ReviewRequired {
                rule_status = SmartCoreCalibrationRuleStatusV0::ObserveOnly;
            }
            if stats.mismatch_count >= policy.min_support_for_active_rule
                && matches!(rule_status, SmartCoreCalibrationRuleStatusV0::ObserveOnly)
                && to_bucket.is_some()
                && action != SmartCoreCalibrationRuleActionV0::KeepObserving
            {
                rule_status = SmartCoreCalibrationRuleStatusV0::Active;
            }
            SmartCoreCalibrationRuleV0 {
                rule_id: format!("{}-overlay-rule", stats.stats_id),
                member_id: stats.member_id.clone(),
                head: stats.head,
                from_bucket: stats
                    .dominant_debug_bucket
                    .clone()
                    .unwrap_or_else(|| "Unknown".to_string()),
                to_bucket,
                action,
                support_count: stats.mismatch_count,
                mismatch_reduction_estimate: (stats.mismatch_rate * stats.mismatch_count as f64)
                    .min(stats.mismatch_count as f64),
                confidence,
                rule_status,
                reason: format!(
                    "debug-only calibration overlay from dataset={} mismatch_rate={:.2} dominant_target={}",
                    stats_summary.dataset_id,
                    stats.mismatch_rate,
                    stats.dominant_target_bucket.as_deref().unwrap_or("Unknown")
                ),
                paper_only: true,
            }
        })
        .collect::<Vec<_>>();
    rules.sort_by(|left, right| {
        left.member_id
            .cmp(&right.member_id)
            .then_with(|| left.head.cmp(&right.head))
            .then_with(|| left.rule_id.cmp(&right.rule_id))
    });
    let mut kept = Vec::new();
    let mut counts: std::collections::BTreeMap<(String, SmartCoreShadowHeadKind), usize> =
        std::collections::BTreeMap::new();
    for rule in rules {
        let key = (rule.member_id.clone(), rule.head);
        let entry = counts.entry(key).or_insert(0);
        if *entry < policy.max_rules_per_member_head.max(1) {
            kept.push(rule);
            *entry += 1;
        }
    }
    let active_rule_count = kept
        .iter()
        .filter(|rule| rule.rule_status == SmartCoreCalibrationRuleStatusV0::Active)
        .count();
    let observe_only_rule_count = kept
        .iter()
        .filter(|rule| rule.rule_status == SmartCoreCalibrationRuleStatusV0::ObserveOnly)
        .count();
    let disabled_rule_count = kept
        .iter()
        .filter(|rule| rule.rule_status == SmartCoreCalibrationRuleStatusV0::Disabled)
        .count();
    SmartCoreCalibrationRuleTableV0 {
        table_id: format!("{}-overlay-rule-table", stats_summary.dataset_id),
        source_dataset_id: stats_summary.dataset_id.clone(),
        rules: kept,
        active_rule_count,
        observe_only_rule_count,
        disabled_rule_count,
        paper_only: true,
    }
}

fn calibrated_bucket_from_rule(
    original_bucket: &str,
    rule: Option<&SmartCoreCalibrationRuleV0>,
) -> (
    String,
    SmartCoreCalibrationRuleActionV0,
    Option<String>,
    ReplayLabelConfidence,
) {
    if let Some(rule) = rule {
        if rule.rule_status == SmartCoreCalibrationRuleStatusV0::Active {
            return (
                rule.to_bucket
                    .clone()
                    .unwrap_or_else(|| original_bucket.to_string()),
                rule.action,
                Some(rule.rule_id.clone()),
                rule.confidence,
            );
        }
        return (
            original_bucket.to_string(),
            rule.action,
            Some(rule.rule_id.clone()),
            rule.confidence,
        );
    }
    (
        original_bucket.to_string(),
        SmartCoreCalibrationRuleActionV0::Keep,
        None,
        ReplayLabelConfidence::ReviewRequired,
    )
}

fn apply_normalized_bucket_to_debug_output(
    output: &mut SmartCoreDebugOutputV0,
    head: SmartCoreShadowHeadKind,
    bucket_label: &str,
) {
    let value = shadow_bucket_value_from_label(bucket_label);
    match head {
        SmartCoreShadowHeadKind::Stance => {
            if let Some(head_output) = output.stance_head.as_mut() {
                head_output.bucket = match value {
                    SmartCoreHeadBucketNormalizedValue::PositiveLike => ToyStanceBucketV0::BuyLike,
                    SmartCoreHeadBucketNormalizedValue::NeutralLike => ToyStanceBucketV0::HoldLike,
                    SmartCoreHeadBucketNormalizedValue::NegativeLike => {
                        ToyStanceBucketV0::NoTradeLike
                    }
                    _ => ToyStanceBucketV0::Unknown,
                };
            }
        }
        SmartCoreShadowHeadKind::Risk => {
            if let Some(head_output) = output.risk_head.as_mut() {
                head_output.bucket = match value {
                    SmartCoreHeadBucketNormalizedValue::RiskHigh => ToyRiskBucketV0::HighRisk,
                    SmartCoreHeadBucketNormalizedValue::RiskMedium => ToyRiskBucketV0::MediumRisk,
                    SmartCoreHeadBucketNormalizedValue::RiskLow => ToyRiskBucketV0::LowRisk,
                    _ => ToyRiskBucketV0::Unknown,
                };
            }
        }
        SmartCoreShadowHeadKind::EvidenceNeed => {
            if let Some(head_output) = output.evidence_need_head.as_mut() {
                head_output.bucket = match value {
                    SmartCoreHeadBucketNormalizedValue::NeedMoreEvidence => {
                        ToyEvidenceNeedBucketV0::NeedMoreEvidence
                    }
                    SmartCoreHeadBucketNormalizedValue::EvidenceSufficient => {
                        ToyEvidenceNeedBucketV0::EvidenceSufficient
                    }
                    _ => ToyEvidenceNeedBucketV0::Unknown,
                };
            }
        }
        SmartCoreShadowHeadKind::ConfidenceCalibration => {
            if let Some(head_output) = output.confidence_calibration_head.as_mut() {
                head_output.bucket = match value {
                    SmartCoreHeadBucketNormalizedValue::ConfidenceHigh => {
                        ToyConfidenceCalibrationBucketV0::HighConfidence
                    }
                    SmartCoreHeadBucketNormalizedValue::ConfidenceMedium => {
                        ToyConfidenceCalibrationBucketV0::MediumConfidence
                    }
                    SmartCoreHeadBucketNormalizedValue::ConfidenceLow => {
                        ToyConfidenceCalibrationBucketV0::LowConfidence
                    }
                    _ => ToyConfidenceCalibrationBucketV0::Unknown,
                };
            }
        }
        SmartCoreShadowHeadKind::Uncertainty => {
            if let Some(head_output) = output.uncertainty_head.as_mut() {
                head_output.bucket = match value {
                    SmartCoreHeadBucketNormalizedValue::ConfidenceHigh => {
                        ToyUncertaintyBucketV0::LowUncertainty
                    }
                    SmartCoreHeadBucketNormalizedValue::ConfidenceMedium => {
                        ToyUncertaintyBucketV0::MediumUncertainty
                    }
                    SmartCoreHeadBucketNormalizedValue::ConfidenceLow => {
                        ToyUncertaintyBucketV0::HighUncertainty
                    }
                    _ => ToyUncertaintyBucketV0::Unknown,
                };
            }
        }
        SmartCoreShadowHeadKind::ExpectedReturnHint => {
            if let Some(head_output) = output.expected_return_head.as_mut() {
                head_output.bucket = match value {
                    SmartCoreHeadBucketNormalizedValue::PositiveLike => {
                        ToyExpectedReturnBucketV0::PositiveHint
                    }
                    SmartCoreHeadBucketNormalizedValue::NeutralLike => {
                        ToyExpectedReturnBucketV0::NeutralHint
                    }
                    SmartCoreHeadBucketNormalizedValue::NegativeLike => {
                        ToyExpectedReturnBucketV0::NegativeHint
                    }
                    SmartCoreHeadBucketNormalizedValue::Deferred
                    | SmartCoreHeadBucketNormalizedValue::Unknown => {
                        ToyExpectedReturnBucketV0::Deferred
                    }
                    _ => ToyExpectedReturnBucketV0::Deferred,
                };
            }
        }
    }
}

pub fn apply_smartcore_calibration_overlay_v0(
    debug_output_batch: &SmartCoreDebugOutputBatchV0,
    rule_table: &SmartCoreCalibrationRuleTableV0,
    policy: &SmartCoreCalibrationOverlayPolicyV0,
) -> CalibratedSmartCoreDebugOutputBatchV0 {
    let active_rules = rule_table
        .rules
        .iter()
        .filter(|rule| rule.rule_status == SmartCoreCalibrationRuleStatusV0::Active)
        .map(|rule| {
            (
                (rule.member_id.clone(), rule.head, rule.from_bucket.clone()),
                rule,
            )
        })
        .collect::<std::collections::BTreeMap<_, _>>();
    let member_outputs = debug_output_batch
        .member_outputs
        .iter()
        .map(|output| {
            let normalized = normalized_shadow_buckets_from_debug_output(output);
            let mut calibrated_heads = Vec::new();
            for head in [
                SmartCoreShadowHeadKind::Stance,
                SmartCoreShadowHeadKind::Risk,
                SmartCoreShadowHeadKind::EvidenceNeed,
                SmartCoreShadowHeadKind::ConfidenceCalibration,
                SmartCoreShadowHeadKind::Uncertainty,
                SmartCoreShadowHeadKind::ExpectedReturnHint,
            ] {
                let Some(normalized_bucket) = normalized.get(&head) else {
                    continue;
                };
                let original_bucket = normalized_bucket_label(normalized_bucket.normalized_value);
                let rule =
                    active_rules.get(&(output.member_id.clone(), head, original_bucket.clone()));
                let (calibrated_bucket, calibration_action, applied_rule_id, rule_confidence) =
                    calibrated_bucket_from_rule(&original_bucket, rule.copied());
                calibrated_heads.push(CalibratedSmartCoreHeadOutputV0 {
                    member_id: output.member_id.clone(),
                    head,
                    original_bucket: original_bucket.clone(),
                    calibrated_bucket: calibrated_bucket.clone(),
                    calibration_action,
                    applied_rule_id,
                    rule_confidence,
                    changed: original_bucket != calibrated_bucket,
                    debug_only: policy.debug_only,
                    not_investment_signal: !policy.allow_trade_signal_output,
                    not_committee_opinion: !policy.allow_member_opinion_output,
                    paper_only: true,
                });
            }
            let changed_head_count = calibrated_heads.iter().filter(|head| head.changed).count();
            let applied_rule_count = calibrated_heads
                .iter()
                .filter(|head| head.applied_rule_id.is_some())
                .count();
            CalibratedSmartCoreDebugOutputV0 {
                calibrated_output_id: format!("{}-calibrated", output.debug_output_id),
                source_debug_output_id: output.debug_output_id.clone(),
                member_id: output.member_id.clone(),
                calibrated_heads,
                applied_rule_count,
                changed_head_count,
                calibration_summary: format!(
                    "debug-only calibration overlay; applied_rules={}, changed_heads={}",
                    applied_rule_count, changed_head_count
                ),
                debug_only: true,
                not_investment_signal: true,
                not_committee_opinion: true,
                not_order: true,
                no_training: true,
                no_weight_update: true,
                no_checkpoint: true,
                paper_only: true,
            }
        })
        .collect::<Vec<_>>();
    let changed_output_count = member_outputs
        .iter()
        .filter(|output| output.changed_head_count > 0)
        .count();
    CalibratedSmartCoreDebugOutputBatchV0 {
        batch_id: format!("{}-calibrated", debug_output_batch.batch_id),
        source_debug_batch_id: Some(debug_output_batch.batch_id.clone()),
        output_count: member_outputs.len(),
        changed_output_count,
        member_outputs,
        debug_only: true,
        paper_only: true,
    }
}

fn build_recalibrated_debug_output_batch_v0(
    source_batch: &SmartCoreDebugOutputBatchV0,
    calibrated_batch: &CalibratedSmartCoreDebugOutputBatchV0,
) -> Result<SmartCoreDebugOutputBatchV0, String> {
    let source_map = source_batch
        .member_outputs
        .iter()
        .map(|output| (output.debug_output_id.clone(), output))
        .collect::<std::collections::BTreeMap<_, _>>();
    let mut member_outputs = Vec::new();
    for calibrated_output in &calibrated_batch.member_outputs {
        let source_output = source_map
            .get(&calibrated_output.source_debug_output_id)
            .ok_or_else(|| {
                format!(
                    "missing source debug output {} for recalibration overlay",
                    calibrated_output.source_debug_output_id
                )
            })?;
        let mut recalibrated = (*source_output).clone();
        recalibrated.debug_output_id = calibrated_output.calibrated_output_id.clone();
        for calibrated_head in &calibrated_output.calibrated_heads {
            apply_normalized_bucket_to_debug_output(
                &mut recalibrated,
                calibrated_head.head,
                &calibrated_head.calibrated_bucket,
            );
        }
        member_outputs.push(recalibrated);
    }
    Ok(SmartCoreDebugOutputBatchV0 {
        batch_id: calibrated_batch.batch_id.clone(),
        output_count: member_outputs.len(),
        member_count: member_outputs.len(),
        member_outputs,
        debug_only: true,
        paper_only: true,
    })
}

pub fn evaluate_smartcore_calibration_overlay_safety_v0(
    calibrated_batch: &CalibratedSmartCoreDebugOutputBatchV0,
    rule_table: &SmartCoreCalibrationRuleTableV0,
) -> SmartCoreCalibrationOverlaySafetyGuardV0 {
    let debug_only = calibrated_batch.debug_only
        && calibrated_batch
            .member_outputs
            .iter()
            .all(|output| output.debug_only);
    let no_training = calibrated_batch
        .member_outputs
        .iter()
        .all(|output| output.no_training);
    let no_weight_update = calibrated_batch
        .member_outputs
        .iter()
        .all(|output| output.no_weight_update);
    let no_checkpoint = calibrated_batch
        .member_outputs
        .iter()
        .all(|output| output.no_checkpoint);
    let no_live_inference = true;
    let not_member_opinion = calibrated_batch
        .member_outputs
        .iter()
        .all(|output| output.not_committee_opinion);
    let not_committee_decision = calibrated_batch
        .member_outputs
        .iter()
        .all(|output| output.not_committee_opinion);
    let not_trade_signal = calibrated_batch
        .member_outputs
        .iter()
        .all(|output| output.not_investment_signal);
    let not_order = calibrated_batch
        .member_outputs
        .iter()
        .all(|output| output.not_order);
    let no_broker_order_account = true;
    let calibrated_text = serde_json::to_string(calibrated_batch).unwrap_or_default();
    let rule_text = serde_json::to_string(rule_table).unwrap_or_default();
    let labels_not_in_input = !calibrated_text.contains("target_bucket")
        && !calibrated_text.contains("label_source")
        && !rule_text.contains("checkpoint")
        && !rule_text.contains("optimizer")
        && !rule_text.contains("gradient")
        && !rule_text.contains("weight_mutation");
    let mut violations = Vec::new();
    if !debug_only {
        violations.push("calibrated overlay must remain debug_only".to_string());
    }
    if !no_training {
        violations.push("calibrated overlay must not train".to_string());
    }
    if !no_weight_update {
        violations.push("calibrated overlay must not update weights".to_string());
    }
    if !no_checkpoint {
        violations.push("calibrated overlay must not write checkpoints".to_string());
    }
    if !no_live_inference {
        violations.push("calibrated overlay must not enable live inference".to_string());
    }
    if !not_member_opinion {
        violations.push("calibrated overlay must not claim MemberOpinion".to_string());
    }
    if !not_committee_decision {
        violations.push("calibrated overlay must not claim committee decision".to_string());
    }
    if !not_trade_signal {
        violations.push("calibrated overlay must not claim trade signal".to_string());
    }
    if !not_order {
        violations.push("calibrated overlay must not claim order output".to_string());
    }
    if !no_broker_order_account {
        violations.push("calibrated overlay must not expose broker/order/account path".to_string());
    }
    if !labels_not_in_input {
        violations
            .push("calibration labels must not be injected into debug input path".to_string());
    }
    SmartCoreCalibrationOverlaySafetyGuardV0 {
        debug_only,
        no_training,
        no_weight_update,
        no_checkpoint,
        no_live_inference,
        not_member_opinion,
        not_committee_decision,
        not_trade_signal,
        not_order,
        no_broker_order_account,
        labels_not_in_input,
        safety_status: if violations.is_empty() {
            SmartCoreCalibrationOverlaySafetyStatusV0::Preserved
        } else {
            SmartCoreCalibrationOverlaySafetyStatusV0::Violated
        },
        violations,
        paper_only: true,
    }
}

fn default_recalibration_interpretation_v0(run_id: &str) -> SmartCoreRecalibrationInterpretationV0 {
    SmartCoreRecalibrationInterpretationV0 {
        interpretation_id: format!("{run_id}-recalibration-interpretation"),
        mismatch_delta: 0,
        improved: false,
        worsened: false,
        no_change: true,
        data_sufficiency: SmartCoreRecalibrationDataSufficiencyV0::NeedsMoreTargets,
        next_recommended_step: SmartCoreRecalibrationRecommendedNextStepV0::KeepDebugOnly,
        human_readable_summary:
            "Calibration overlay stayed debug-only; collect more calibration targets before using stronger rules."
                .to_string(),
        debug_only: true,
        paper_only: true,
    }
}

pub fn interpret_smartcore_recalibration_result_v0(
    result: &SmartCoreShadowRecalibrationRunResult,
) -> SmartCoreRecalibrationInterpretationV0 {
    let improved = result.mismatch_delta < 0;
    let worsened = result.mismatch_delta > 0;
    let no_change = result.mismatch_delta == 0;
    let data_sufficiency = match result.stats_summary.stats_status {
        SmartCoreCalibrationStatsStatusV0::Sufficient => {
            SmartCoreRecalibrationDataSufficiencyV0::SufficientForOverlay
        }
        SmartCoreCalibrationStatsStatusV0::ThinData => {
            SmartCoreRecalibrationDataSufficiencyV0::TooSparse
        }
        SmartCoreCalibrationStatsStatusV0::NeedsMoreTargets
        | SmartCoreCalibrationStatsStatusV0::Unsafe => {
            SmartCoreRecalibrationDataSufficiencyV0::NeedsMoreTargets
        }
    };
    let safety_preserved = result.overlay_safety_guard.safety_status
        == SmartCoreCalibrationOverlaySafetyStatusV0::Preserved
        && result.no_decision_recheck.guard_status
            == SmartCoreNoDecisionBridgeGuardStatus::Preserved;
    let next_recommended_step = if improved && safety_preserved {
        SmartCoreRecalibrationRecommendedNextStepV0::ProceedToShadowOpinionCandidate
    } else if worsened {
        SmartCoreRecalibrationRecommendedNextStepV0::KeepDebugOnly
    } else if result.rule_table.active_rule_count > 0 {
        SmartCoreRecalibrationRecommendedNextStepV0::TuneCalibrationPolicy
    } else {
        SmartCoreRecalibrationRecommendedNextStepV0::KeepCollectingCalibrationTargets
    };
    let human_readable_summary = if improved && safety_preserved {
        format!(
            "Calibration overlay improved shadow mismatch by {} while staying debug-only.",
            result.mismatch_delta.abs()
        )
    } else if worsened {
        format!(
            "Calibration overlay worsened shadow mismatch by {} so it should remain debug-only.",
            result.mismatch_delta
        )
    } else {
        format!(
            "Calibration overlay changed output_count={} with mismatch_delta={}; keep collecting targets or tune policy while staying debug-only.",
            result.calibrated_debug_output_batch.changed_output_count, result.mismatch_delta
        )
    };
    SmartCoreRecalibrationInterpretationV0 {
        interpretation_id: format!("{}-recalibration-interpretation", result.run_id),
        mismatch_delta: result.mismatch_delta,
        improved,
        worsened,
        no_change,
        data_sufficiency,
        next_recommended_step,
        human_readable_summary,
        debug_only: true,
        paper_only: true,
    }
}

pub fn build_owner_core_recalibration_debug_summary(
    result: &SmartCoreShadowRecalibrationRunResult,
) -> OwnerCoreRecalibrationDebugSummary {
    OwnerCoreRecalibrationDebugSummary {
        summary_id: format!("{}-owner-core-recalibration", result.run_id),
        pre_mismatch_count: result.pre_mismatch_count,
        post_mismatch_count: result.post_mismatch_count,
        mismatch_delta: result.mismatch_delta,
        active_rule_count: result.rule_table.active_rule_count,
        changed_output_count: result.calibrated_debug_output_batch.changed_output_count,
        interpretation: result.interpretation.clone(),
        message: format!(
            "Calibration overlay is debug-only. It does not train or update weights. It is not used for committee decisions. It is not a trading signal. mismatch_delta={}, active_rules={}",
            result.mismatch_delta, result.rule_table.active_rule_count
        ),
        debug_only: true,
        not_investment_signal: true,
        not_committee_opinion: true,
        paper_only: true,
    }
}

fn apply_owner_core_recalibration_debug_update(
    batch_id: &str,
    section: Option<OwnerCoreDebugSection>,
    update: Option<OwnerCoreRecalibrationDebugSummary>,
) -> Option<OwnerCoreDebugSection> {
    let Some(update) = update else {
        return section;
    };
    if let Some(mut section) = section {
        section.summary = format!(
            "{}; recalibration_delta={}, active_rules={}",
            section.summary, update.mismatch_delta, update.active_rule_count
        );
        section.recalibration_summary = Some(update);
        Some(section)
    } else {
        Some(OwnerCoreDebugSection {
            section_id: format!("{batch_id}-owner-core-debug"),
            cards: Vec::new(),
            summary: format!(
                "pre_mismatch={}, post_mismatch={}, delta={}, active_rules={}",
                update.pre_mismatch_count,
                update.post_mismatch_count,
                update.mismatch_delta,
                update.active_rule_count
            ),
            paper_only_warning:
                "core recalibration debug summary is paper-only diagnostics; not investment advice, not trading, not orders"
                    .to_string(),
            debug_only_warning:
                "debug recalibration summary is read-only overlay observation and must not feed member opinions or committee decisions"
                    .to_string(),
            calibration_summary: None,
            recalibration_summary: Some(update),
            shadow_opinion_summary: None,
            shadow_stability_summary: None,
            shadow_scenario_sweep_summary: None,
            observer_section: None,
            observer_coverage_closure_summary: None,
            observer_trend_summary: None,
            observer_seeded_target_summary: None,
            observer_apply_readiness_summary: None,
            paper_only: true,
        })
    }
}

pub fn run_smartcore_shadow_recalibration_pass(
    debug_output_batch: &SmartCoreDebugOutputBatchV0,
    calibration_dataset: &CoreCalibrationDataset,
    previous_alignment_result: &SmartCoreShadowAlignmentRunResult,
    batch_result: &BatchCommitteeCycleResult,
    config: &SmartCoreShadowRecalibrationRunConfig,
) -> Result<SmartCoreShadowRecalibrationRunResult, String> {
    if !config.paper_only {
        return Err("smartcore recalibration pass must remain paper-only".to_string());
    }
    if config.min_support_for_active_rule == 0 || config.max_rules_per_member_head == 0 {
        return Err("smartcore recalibration policy limits must be positive".to_string());
    }
    for (path, label) in [
        (
            config.rule_table_output_path.as_ref(),
            "smartcore recalibration rule table output path",
        ),
        (
            config.calibrated_debug_output_path.as_ref(),
            "smartcore recalibrated debug output path",
        ),
        (
            config.recalibration_result_output_path.as_ref(),
            "smartcore recalibration result output path",
        ),
    ] {
        if let Some(path) = path {
            validate_local_json_path(Path::new(path), label)?;
        }
    }
    let stats_summary = compute_smartcore_calibration_stats_v0(calibration_dataset);
    let policy = SmartCoreCalibrationOverlayPolicyV0 {
        min_support_for_active_rule: config.min_support_for_active_rule,
        max_rules_per_member_head: config.max_rules_per_member_head,
        ..Default::default()
    };
    let rule_table = build_smartcore_calibration_rule_table_v0(&stats_summary, &policy);
    let calibrated_debug_output_batch =
        apply_smartcore_calibration_overlay_v0(debug_output_batch, &rule_table, &policy);
    let recalibrated_debug_output_batch = build_recalibrated_debug_output_batch_v0(
        debug_output_batch,
        &calibrated_debug_output_batch,
    )?;
    let recalibrated_alignment_result = recheck_smartcore_shadow_alignment(
        &recalibrated_debug_output_batch,
        calibration_dataset,
        Some(&previous_alignment_result.alignment_summary),
        &SmartCoreShadowAlignmentRecheckConfig {
            run_id: format!("{}-shadow-recheck", config.run_id),
            use_refreshed_calibration_targets: true,
            compare_previous_summary: true,
            paper_only: true,
        },
    );
    let overlay_safety_guard = evaluate_smartcore_calibration_overlay_safety_v0(
        &calibrated_debug_output_batch,
        &rule_table,
    );
    let no_decision_recheck = evaluate_smartcore_no_decision_bridge_guard(
        batch_result,
        &recalibrated_debug_output_batch,
        previous_alignment_result,
    );
    let pre_mismatch_count = previous_alignment_result.mismatch_count;
    let post_mismatch_count = recalibrated_alignment_result.new_mismatch_count;
    let mismatch_delta = post_mismatch_count as isize - pre_mismatch_count as isize;
    let mut warnings = Vec::new();
    if stats_summary.stats_status != SmartCoreCalibrationStatsStatusV0::Sufficient {
        warnings.push(format!(
            "recalibration stats are {:?}",
            stats_summary.stats_status
        ));
    }
    if rule_table.active_rule_count == 0 {
        warnings.push("recalibration produced no active overlay rules".to_string());
    }
    if calibrated_debug_output_batch.changed_output_count == 0 {
        warnings.push("calibration overlay changed no debug outputs".to_string());
    }
    if mismatch_delta >= 0 {
        warnings.push(format!(
            "recalibration did not improve mismatch count (delta={mismatch_delta})"
        ));
    }
    if config.dry_run {
        warnings.push("recalibration ran in dry-run mode".to_string());
    }
    let mut result = SmartCoreShadowRecalibrationRunResult {
        run_id: config.run_id.clone(),
        stats_summary,
        rule_table,
        calibrated_debug_output_batch,
        recalibrated_alignment_result,
        pre_mismatch_count,
        post_mismatch_count,
        mismatch_delta,
        pre_alignment_status: previous_alignment_result.alignment_status,
        post_alignment_status: previous_alignment_result.alignment_status,
        overlay_safety_guard,
        no_decision_recheck,
        interpretation: default_recalibration_interpretation_v0(&config.run_id),
        owner_core_debug_update: None,
        run_status: SmartCoreShadowRecalibrationRunStatus::Passed,
        warnings,
        safety_summary: safety_summary(),
        debug_only: true,
        not_investment_signal: true,
        not_committee_opinion: true,
        paper_only: true,
    };
    result.post_alignment_status = result.recalibrated_alignment_result.new_alignment_status;
    result.interpretation = interpret_smartcore_recalibration_result_v0(&result);
    if config.emit_owner_summary {
        result.owner_core_debug_update =
            Some(build_owner_core_recalibration_debug_summary(&result));
    }
    if result.overlay_safety_guard.safety_status
        == SmartCoreCalibrationOverlaySafetyStatusV0::Violated
        || result.no_decision_recheck.guard_status == SmartCoreNoDecisionBridgeGuardStatus::Violated
    {
        result.run_status = SmartCoreShadowRecalibrationRunStatus::Failed;
    } else if !result.warnings.is_empty() {
        result.run_status = SmartCoreShadowRecalibrationRunStatus::PassedWithWarnings;
    }
    if !config.dry_run {
        if let Some(path) = config.rule_table_output_path.as_ref() {
            write_safe_json(Path::new(path), &result.rule_table)?;
        }
        if let Some(path) = config.calibrated_debug_output_path.as_ref() {
            write_safe_json(Path::new(path), &result.calibrated_debug_output_batch)?;
        }
        if let Some(path) = config.recalibration_result_output_path.as_ref() {
            write_safe_json(Path::new(path), &result)?;
        }
    }
    Ok(result)
}

fn smartcore_recalibration_requested_from_flags(
    enabled: bool,
    rule_table_output_path: Option<&String>,
    calibrated_debug_output_path: Option<&String>,
    recalibration_result_output_path: Option<&String>,
    _emit_owner_summary: bool,
) -> bool {
    enabled
        || rule_table_output_path.is_some()
        || calibrated_debug_output_path.is_some()
        || recalibration_result_output_path.is_some()
}

fn maybe_run_smartcore_shadow_recalibration_for_batch_result(
    run_id: String,
    enabled: bool,
    dry_run: bool,
    calibration_dataset_input_path: Option<&String>,
    rule_table_output_path: Option<&String>,
    calibrated_debug_output_path: Option<&String>,
    recalibration_result_output_path: Option<&String>,
    min_support_for_active_rule: usize,
    max_rules_per_member_head: usize,
    emit_owner_summary: bool,
    batch_result: &mut BatchCommitteeCycleResult,
) -> Result<Option<SmartCoreShadowRecalibrationRunResult>, String> {
    if !smartcore_recalibration_requested_from_flags(
        enabled,
        rule_table_output_path,
        calibrated_debug_output_path,
        recalibration_result_output_path,
        emit_owner_summary,
    ) {
        return Ok(None);
    }
    let previous_alignment_result = batch_result
        .smartcore_shadow_alignment_run_result
        .as_ref()
        .ok_or_else(|| "smartcore recalibration requires shadow alignment result".to_string())?
        .clone();
    let debug_output_batch = batch_result
        .smartcore_head_projection_dry_run_result
        .as_ref()
        .ok_or_else(|| "smartcore recalibration requires head projection debug output".to_string())?
        .debug_output_batch
        .clone();
    let loaded_dataset = if let Some(path) = calibration_dataset_input_path {
        let path = Path::new(path);
        validate_local_json_path(path, "smartcore calibration dataset input path")?;
        if path.exists() {
            Some(load_core_calibration_dataset_from_local_json(path)?)
        } else {
            None
        }
    } else {
        None
    };
    let calibration_dataset = loaded_dataset
        .or_else(|| {
            batch_result
                .smartcore_mismatch_learning_loop_result
                .as_ref()
                .and_then(|result| {
                    result
                        .calibration_dataset_refresh_result
                        .as_ref()
                        .map(|refresh| refresh.refreshed_dataset.clone())
                })
        })
        .or_else(|| {
            batch_result
                .smartcore_mismatch_self_growing_run_result
                .as_ref()
                .map(|result| result.core_calibration_dataset.clone())
        })
        .ok_or_else(|| {
            "smartcore recalibration requires a calibration dataset from input path or prior mismatch pipeline"
                .to_string()
        })?;
    let result = run_smartcore_shadow_recalibration_pass(
        &debug_output_batch,
        &calibration_dataset,
        &previous_alignment_result,
        batch_result,
        &SmartCoreShadowRecalibrationRunConfig {
            run_id,
            enabled,
            calibration_dataset_path: calibration_dataset_input_path.cloned(),
            rule_table_output_path: rule_table_output_path.cloned(),
            calibrated_debug_output_path: calibrated_debug_output_path.cloned(),
            recalibration_result_output_path: recalibration_result_output_path.cloned(),
            min_support_for_active_rule,
            max_rules_per_member_head,
            emit_owner_summary,
            dry_run,
            paper_only: true,
        },
    )?;
    if let Some(shadow_alignment_result) =
        batch_result.smartcore_shadow_alignment_run_result.as_mut()
    {
        shadow_alignment_result.owner_core_debug_section =
            apply_owner_core_recalibration_debug_update(
                &batch_result.batch_id,
                shadow_alignment_result.owner_core_debug_section.take(),
                result.owner_core_debug_update.clone(),
            );
        shadow_alignment_result.owner_core_debug_card_count = shadow_alignment_result
            .owner_core_debug_section
            .as_ref()
            .map(|section| section.cards.len())
            .unwrap_or(0);
    }
    batch_result.smartcore_shadow_recalibration_run_result = Some(result.clone());
    Ok(Some(result))
}

fn calibrated_bucket_for_head(
    calibrated_output: &CalibratedSmartCoreDebugOutputV0,
    head: SmartCoreShadowHeadKind,
) -> String {
    calibrated_output
        .calibrated_heads
        .iter()
        .find(|candidate_head| candidate_head.head == head)
        .map(|candidate_head| candidate_head.calibrated_bucket.clone())
        .unwrap_or_else(|| "Unknown".to_string())
}

fn shadow_confidence_from_bucket(bucket: &str) -> SmartCoreShadowOpinionConfidence {
    match shadow_bucket_value_from_label(bucket) {
        SmartCoreHeadBucketNormalizedValue::ConfidenceLow => SmartCoreShadowOpinionConfidence::Low,
        SmartCoreHeadBucketNormalizedValue::ConfidenceMedium => {
            SmartCoreShadowOpinionConfidence::Medium
        }
        SmartCoreHeadBucketNormalizedValue::ConfidenceHigh => {
            SmartCoreShadowOpinionConfidence::High
        }
        _ => SmartCoreShadowOpinionConfidence::Unknown,
    }
}

fn shadow_risk_from_bucket(bucket: &str) -> SmartCoreShadowOpinionRisk {
    match shadow_bucket_value_from_label(bucket) {
        SmartCoreHeadBucketNormalizedValue::RiskLow => SmartCoreShadowOpinionRisk::Low,
        SmartCoreHeadBucketNormalizedValue::RiskMedium => SmartCoreShadowOpinionRisk::Medium,
        SmartCoreHeadBucketNormalizedValue::RiskHigh => SmartCoreShadowOpinionRisk::High,
        _ => SmartCoreShadowOpinionRisk::Unknown,
    }
}

fn shadow_evidence_from_bucket(bucket: &str) -> SmartCoreShadowOpinionEvidence {
    match shadow_bucket_value_from_label(bucket) {
        SmartCoreHeadBucketNormalizedValue::EvidenceSufficient => {
            SmartCoreShadowOpinionEvidence::EvidenceSufficient
        }
        SmartCoreHeadBucketNormalizedValue::NeedMoreEvidence => {
            SmartCoreShadowOpinionEvidence::NeedMoreEvidence
        }
        _ => SmartCoreShadowOpinionEvidence::Unknown,
    }
}

fn shadow_uncertainty_from_bucket(bucket: &str) -> SmartCoreShadowOpinionUncertainty {
    match shadow_bucket_value_from_label(bucket) {
        SmartCoreHeadBucketNormalizedValue::ConfidenceHigh => {
            SmartCoreShadowOpinionUncertainty::Low
        }
        SmartCoreHeadBucketNormalizedValue::ConfidenceMedium => {
            SmartCoreShadowOpinionUncertainty::Medium
        }
        SmartCoreHeadBucketNormalizedValue::ConfidenceLow => {
            SmartCoreShadowOpinionUncertainty::High
        }
        _ => SmartCoreShadowOpinionUncertainty::Unknown,
    }
}

fn shadow_action_from_source_heads(
    source_heads: &SmartCoreShadowOpinionSourceHeads,
    policy: &SmartCoreShadowOpinionPolicy,
) -> SmartCoreShadowOpinionAction {
    let risk = shadow_risk_from_bucket(&source_heads.risk_bucket);
    if matches!(risk, SmartCoreShadowOpinionRisk::High) && policy.allow_shadow_risk_warning {
        return SmartCoreShadowOpinionAction::ShadowRiskWarning;
    }
    let evidence = shadow_evidence_from_bucket(&source_heads.evidence_bucket);
    if matches!(evidence, SmartCoreShadowOpinionEvidence::NeedMoreEvidence)
        && policy.allow_shadow_need_more_evidence
    {
        return SmartCoreShadowOpinionAction::ShadowNeedMoreEvidence;
    }
    match shadow_bucket_value_from_label(&source_heads.stance_bucket) {
        SmartCoreHeadBucketNormalizedValue::PositiveLike if policy.allow_shadow_buy_like => {
            SmartCoreShadowOpinionAction::ShadowBuyLike
        }
        SmartCoreHeadBucketNormalizedValue::NeutralLike => {
            SmartCoreShadowOpinionAction::ShadowHoldLike
        }
        SmartCoreHeadBucketNormalizedValue::NegativeLike => {
            SmartCoreShadowOpinionAction::ShadowNoTradeLike
        }
        _ => SmartCoreShadowOpinionAction::ShadowUnknown,
    }
}

pub fn build_smartcore_shadow_opinion_candidate(
    calibrated_output: &CalibratedSmartCoreDebugOutputV0,
    policy: &SmartCoreShadowOpinionPolicy,
) -> Option<SmartCoreShadowOpinionCandidate> {
    if !policy.paper_only {
        return None;
    }
    if policy.require_calibrated_output && calibrated_output.calibrated_output_id.is_empty() {
        return None;
    }
    if policy.require_safety_preserved
        && (!calibrated_output.debug_only
            || !calibrated_output.not_investment_signal
            || !calibrated_output.not_committee_opinion
            || !calibrated_output.not_order
            || !calibrated_output.no_training
            || !calibrated_output.no_weight_update
            || !calibrated_output.no_checkpoint)
    {
        return None;
    }
    let source_heads = SmartCoreShadowOpinionSourceHeads {
        stance_bucket: calibrated_bucket_for_head(
            calibrated_output,
            SmartCoreShadowHeadKind::Stance,
        ),
        risk_bucket: calibrated_bucket_for_head(calibrated_output, SmartCoreShadowHeadKind::Risk),
        evidence_bucket: calibrated_bucket_for_head(
            calibrated_output,
            SmartCoreShadowHeadKind::EvidenceNeed,
        ),
        confidence_bucket: calibrated_bucket_for_head(
            calibrated_output,
            SmartCoreShadowHeadKind::ConfidenceCalibration,
        ),
        uncertainty_bucket: Some(calibrated_bucket_for_head(
            calibrated_output,
            SmartCoreShadowHeadKind::Uncertainty,
        )),
    };
    let shadow_action = shadow_action_from_source_heads(&source_heads, policy);
    Some(SmartCoreShadowOpinionCandidate {
        candidate_id: format!(
            "{}-shadow-candidate",
            calibrated_output.calibrated_output_id
        ),
        member_id: calibrated_output.member_id.clone(),
        source_calibrated_output_id: calibrated_output.calibrated_output_id.clone(),
        symbol: None,
        market_scope: None,
        shadow_action,
        shadow_confidence: shadow_confidence_from_bucket(&source_heads.confidence_bucket),
        shadow_risk: shadow_risk_from_bucket(&source_heads.risk_bucket),
        shadow_evidence: shadow_evidence_from_bucket(&source_heads.evidence_bucket),
        shadow_uncertainty: source_heads
            .uncertainty_bucket
            .as_deref()
            .map(shadow_uncertainty_from_bucket)
            .unwrap_or(SmartCoreShadowOpinionUncertainty::Unknown),
        rationale_debug: format!(
            "shadow-only candidate from calibrated output; stance={}, risk={}, evidence={}, confidence={}",
            source_heads.stance_bucket,
            source_heads.risk_bucket,
            source_heads.evidence_bucket,
            source_heads.confidence_bucket
        ),
        source_heads,
        debug_only: true,
        shadow_only: true,
        not_member_opinion: !policy.allow_as_member_opinion,
        not_committee_input: !policy.allow_as_committee_input,
        not_trade_signal: !policy.allow_as_trade_signal,
        not_order: true,
        paper_only: true,
    })
}

pub fn build_smartcore_shadow_opinion_candidate_batch(
    calibrated_debug_batch: &CalibratedSmartCoreDebugOutputBatchV0,
    policy: &SmartCoreShadowOpinionPolicy,
) -> SmartCoreShadowOpinionCandidateBatch {
    let mut candidates = calibrated_debug_batch
        .member_outputs
        .iter()
        .filter_map(|output| build_smartcore_shadow_opinion_candidate(output, policy))
        .collect::<Vec<_>>();
    candidates.sort_by(|left, right| {
        left.member_id
            .cmp(&right.member_id)
            .then_with(|| left.candidate_id.cmp(&right.candidate_id))
    });
    let member_count = candidates
        .iter()
        .map(|candidate| candidate.member_id.clone())
        .collect::<std::collections::BTreeSet<_>>()
        .len();
    SmartCoreShadowOpinionCandidateBatch {
        batch_id: format!(
            "{}-shadow-opinion-candidates",
            calibrated_debug_batch.batch_id
        ),
        source_calibrated_batch_id: Some(calibrated_debug_batch.batch_id.clone()),
        candidate_count: candidates.len(),
        member_count,
        candidates,
        shadow_only: true,
        debug_only: true,
        paper_only: true,
    }
}

fn enrich_shadow_candidate_batch_from_batch_result(
    candidate_batch: &SmartCoreShadowOpinionCandidateBatch,
    batch_result: &BatchCommitteeCycleResult,
) -> SmartCoreShadowOpinionCandidateBatch {
    let mut opinions_by_member: std::collections::BTreeMap<String, Vec<&MemberOpinion>> =
        std::collections::BTreeMap::new();
    for opinion in &batch_result.member_opinions {
        opinions_by_member
            .entry(comparable_member_key(&opinion.member_id))
            .or_default()
            .push(opinion);
    }
    let candidates = candidate_batch
        .candidates
        .iter()
        .map(|candidate| {
            let mut enriched = candidate.clone();
            let candidate_member_key = comparable_member_key(&candidate.member_id);
            if let Some(opinions) = opinions_by_member.get(&candidate_member_key) {
                enriched.symbol =
                    maybe_only_symbol(opinions.iter().map(|opinion| opinion.symbol.clone()));
                enriched.market_scope =
                    maybe_only_market_scope(opinions.iter().map(|opinion| opinion.market_scope));
            }
            enriched
        })
        .collect::<Vec<_>>();
    SmartCoreShadowOpinionCandidateBatch {
        batch_id: candidate_batch.batch_id.clone(),
        source_calibrated_batch_id: candidate_batch.source_calibrated_batch_id.clone(),
        candidate_count: candidates.len(),
        member_count: candidates
            .iter()
            .map(|candidate| candidate.member_id.clone())
            .collect::<std::collections::BTreeSet<_>>()
            .len(),
        candidates,
        shadow_only: true,
        debug_only: true,
        paper_only: true,
    }
}

fn member_shadow_action(opinion: &MemberOpinion) -> SmartCoreShadowOpinionAction {
    match opinion.stance {
        MemberStance::BuyProposal => SmartCoreShadowOpinionAction::ShadowBuyLike,
        MemberStance::Hold => SmartCoreShadowOpinionAction::ShadowHoldLike,
        MemberStance::SellProposal | MemberStance::NoTrade => {
            SmartCoreShadowOpinionAction::ShadowNoTradeLike
        }
        MemberStance::NeedMoreEvidence => SmartCoreShadowOpinionAction::ShadowNeedMoreEvidence,
    }
}

fn member_shadow_confidence(opinion: &MemberOpinion) -> SmartCoreShadowOpinionConfidence {
    match confidence_target_from_score(opinion.confidence) {
        SmartCoreHeadBucketNormalizedValue::ConfidenceLow => SmartCoreShadowOpinionConfidence::Low,
        SmartCoreHeadBucketNormalizedValue::ConfidenceMedium => {
            SmartCoreShadowOpinionConfidence::Medium
        }
        SmartCoreHeadBucketNormalizedValue::ConfidenceHigh => {
            SmartCoreShadowOpinionConfidence::High
        }
        _ => SmartCoreShadowOpinionConfidence::Unknown,
    }
}

fn member_shadow_risk(opinion: &MemberOpinion) -> SmartCoreShadowOpinionRisk {
    match risk_target_from_hint(opinion.risk_hint) {
        SmartCoreHeadBucketNormalizedValue::RiskLow => SmartCoreShadowOpinionRisk::Low,
        SmartCoreHeadBucketNormalizedValue::RiskMedium => SmartCoreShadowOpinionRisk::Medium,
        SmartCoreHeadBucketNormalizedValue::RiskHigh => SmartCoreShadowOpinionRisk::High,
        _ => SmartCoreShadowOpinionRisk::Unknown,
    }
}

pub fn compare_shadow_candidate_to_member_opinion(
    candidate: &SmartCoreShadowOpinionCandidate,
    member_opinion: Option<&MemberOpinion>,
) -> SmartCoreShadowVsMemberOpinionRecord {
    let mut disagreement_reasons = Vec::new();
    let (member_opinion_id, symbol, market_scope, member_action, member_confidence, member_risk) =
        if let Some(opinion) = member_opinion {
            (
                Some(format!(
                    "{}-{:?}-{}",
                    opinion.symbol, opinion.market_scope, opinion.member_id
                )),
                Some(opinion.symbol.clone()),
                Some(opinion.market_scope),
                Some(member_shadow_action(opinion)),
                Some(member_shadow_confidence(opinion)),
                Some(member_shadow_risk(opinion)),
            )
        } else {
            (
                None,
                candidate.symbol.clone(),
                candidate.market_scope,
                None,
                None,
                None,
            )
        };
    let agreement = match member_opinion {
        None => ShadowVsMemberOpinionAgreement::Unknown,
        Some(opinion) => {
            let opinion_action = member_shadow_action(opinion);
            let opinion_confidence = member_shadow_confidence(opinion);
            let opinion_risk = member_shadow_risk(opinion);
            if matches!(
                candidate.shadow_action,
                SmartCoreShadowOpinionAction::ShadowUnknown
            ) {
                disagreement_reasons.push("shadow candidate remained unknown".to_string());
                ShadowVsMemberOpinionAgreement::Deferred
            } else if opinion_action == candidate.shadow_action
                && opinion_risk == candidate.shadow_risk
                && opinion_confidence == candidate.shadow_confidence
            {
                ShadowVsMemberOpinionAgreement::Agree
            } else if opinion_action == candidate.shadow_action
                || (matches!(
                    candidate.shadow_action,
                    SmartCoreShadowOpinionAction::ShadowRiskWarning
                ) && matches!(
                    opinion_action,
                    SmartCoreShadowOpinionAction::ShadowNoTradeLike
                ))
                || (matches!(
                    candidate.shadow_action,
                    SmartCoreShadowOpinionAction::ShadowNeedMoreEvidence
                ) && matches!(opinion_action, SmartCoreShadowOpinionAction::ShadowHoldLike))
            {
                if opinion_risk != candidate.shadow_risk {
                    disagreement_reasons
                        .push("risk bucket differs from member opinion".to_string());
                }
                if opinion_confidence != candidate.shadow_confidence {
                    disagreement_reasons
                        .push("confidence bucket differs from member opinion".to_string());
                }
                ShadowVsMemberOpinionAgreement::PartiallyAgree
            } else {
                disagreement_reasons
                    .push("shadow action disagrees with member opinion".to_string());
                if opinion_risk != candidate.shadow_risk {
                    disagreement_reasons.push("risk bucket disagrees".to_string());
                }
                ShadowVsMemberOpinionAgreement::Disagree
            }
        }
    };
    SmartCoreShadowVsMemberOpinionRecord {
        comparison_id: format!("{}-vs-member-opinion", candidate.candidate_id),
        member_id: candidate.member_id.clone(),
        candidate_id: candidate.candidate_id.clone(),
        member_opinion_id,
        symbol,
        market_scope,
        shadow_action: candidate.shadow_action,
        member_action,
        shadow_confidence: candidate.shadow_confidence,
        member_confidence,
        shadow_risk: candidate.shadow_risk,
        member_risk,
        agreement,
        disagreement_reasons,
        paper_only: true,
    }
}

pub fn summarize_shadow_vs_member_opinion(
    records: &[SmartCoreShadowVsMemberOpinionRecord],
) -> SmartCoreShadowVsMemberOpinionSummary {
    let agree_count = records
        .iter()
        .filter(|record| record.agreement == ShadowVsMemberOpinionAgreement::Agree)
        .count();
    let partial_count = records
        .iter()
        .filter(|record| record.agreement == ShadowVsMemberOpinionAgreement::PartiallyAgree)
        .count();
    let disagree_count = records
        .iter()
        .filter(|record| record.agreement == ShadowVsMemberOpinionAgreement::Disagree)
        .count();
    let unknown_count = records
        .iter()
        .filter(|record| {
            matches!(
                record.agreement,
                ShadowVsMemberOpinionAgreement::Unknown | ShadowVsMemberOpinionAgreement::Deferred
            )
        })
        .count();
    let summary_status = if records.is_empty() {
        SmartCoreShadowVsMemberOpinionSummaryStatus::InsufficientComparisons
    } else if disagree_count > agree_count + partial_count {
        SmartCoreShadowVsMemberOpinionSummaryStatus::MostlyDisagree
    } else if agree_count + partial_count >= disagree_count.saturating_mul(2).max(1) {
        SmartCoreShadowVsMemberOpinionSummaryStatus::MostlyAgree
    } else {
        SmartCoreShadowVsMemberOpinionSummaryStatus::Mixed
    };
    SmartCoreShadowVsMemberOpinionSummary {
        summary_id: "smartcore-shadow-vs-member-opinion-summary".to_string(),
        comparison_count: records.len(),
        agree_count,
        partial_count,
        disagree_count,
        unknown_count,
        per_member_agreement: records
            .iter()
            .map(|record| (record.member_id.clone(), record.agreement))
            .collect(),
        summary_status,
        paper_only: true,
    }
}

fn shadow_action_stance_target(
    action: SmartCoreShadowOpinionAction,
) -> Option<SmartCoreHeadBucketNormalizedValue> {
    match action {
        SmartCoreShadowOpinionAction::ShadowBuyLike => {
            Some(SmartCoreHeadBucketNormalizedValue::PositiveLike)
        }
        SmartCoreShadowOpinionAction::ShadowHoldLike => {
            Some(SmartCoreHeadBucketNormalizedValue::NeutralLike)
        }
        SmartCoreShadowOpinionAction::ShadowNoTradeLike
        | SmartCoreShadowOpinionAction::ShadowRiskWarning => {
            Some(SmartCoreHeadBucketNormalizedValue::NegativeLike)
        }
        SmartCoreShadowOpinionAction::ShadowNeedMoreEvidence
        | SmartCoreShadowOpinionAction::ShadowUnknown => None,
    }
}

fn shadow_confidence_target(
    confidence: SmartCoreShadowOpinionConfidence,
) -> Option<SmartCoreHeadBucketNormalizedValue> {
    match confidence {
        SmartCoreShadowOpinionConfidence::Low => {
            Some(SmartCoreHeadBucketNormalizedValue::ConfidenceLow)
        }
        SmartCoreShadowOpinionConfidence::Medium => {
            Some(SmartCoreHeadBucketNormalizedValue::ConfidenceMedium)
        }
        SmartCoreShadowOpinionConfidence::High => {
            Some(SmartCoreHeadBucketNormalizedValue::ConfidenceHigh)
        }
        SmartCoreShadowOpinionConfidence::Unknown => None,
    }
}

fn shadow_risk_target(
    risk: SmartCoreShadowOpinionRisk,
) -> Option<SmartCoreHeadBucketNormalizedValue> {
    match risk {
        SmartCoreShadowOpinionRisk::Low => Some(SmartCoreHeadBucketNormalizedValue::RiskLow),
        SmartCoreShadowOpinionRisk::Medium => Some(SmartCoreHeadBucketNormalizedValue::RiskMedium),
        SmartCoreShadowOpinionRisk::High => Some(SmartCoreHeadBucketNormalizedValue::RiskHigh),
        SmartCoreShadowOpinionRisk::Unknown => None,
    }
}

fn shadow_evidence_target(
    evidence: SmartCoreShadowOpinionEvidence,
) -> Option<SmartCoreHeadBucketNormalizedValue> {
    match evidence {
        SmartCoreShadowOpinionEvidence::EvidenceSufficient => {
            Some(SmartCoreHeadBucketNormalizedValue::EvidenceSufficient)
        }
        SmartCoreShadowOpinionEvidence::NeedMoreEvidence => {
            Some(SmartCoreHeadBucketNormalizedValue::NeedMoreEvidence)
        }
        SmartCoreShadowOpinionEvidence::Unknown => None,
    }
}

fn shadow_target_alignment(
    candidate_value: Option<SmartCoreHeadBucketNormalizedValue>,
    target_value: Option<SmartCoreHeadBucketNormalizedValue>,
) -> SmartCoreShadowAlignmentStatus {
    match (candidate_value, target_value) {
        (Some(candidate), Some(target)) if candidate == target => {
            SmartCoreShadowAlignmentStatus::Match
        }
        (Some(_), Some(_)) => SmartCoreShadowAlignmentStatus::Mismatch,
        (None, Some(_)) => SmartCoreShadowAlignmentStatus::Deferred,
        _ => SmartCoreShadowAlignmentStatus::Unknown,
    }
}

fn target_matches_candidate(
    candidate: &SmartCoreShadowOpinionCandidate,
    target: &SmartCoreShadowAlignmentTarget,
) -> bool {
    target.member_id == candidate.member_id
        && (candidate.symbol.is_none()
            || target.symbol.is_none()
            || candidate.symbol == target.symbol)
        && (candidate.market_scope.is_none()
            || target.market_scope.is_none()
            || candidate.market_scope == target.market_scope)
}

pub fn evaluate_shadow_candidate_against_targets(
    candidate: &SmartCoreShadowOpinionCandidate,
    targets: &[SmartCoreShadowAlignmentTarget],
) -> Vec<SmartCoreShadowCandidateTargetEval> {
    targets
        .iter()
        .filter(|target| target_matches_candidate(candidate, target))
        .map(|target| {
            let stance_alignment = shadow_target_alignment(
                shadow_action_stance_target(candidate.shadow_action),
                target.stance_target,
            );
            let risk_alignment = shadow_target_alignment(
                shadow_risk_target(candidate.shadow_risk),
                target.risk_target,
            );
            let evidence_alignment = shadow_target_alignment(
                shadow_evidence_target(candidate.shadow_evidence),
                target.evidence_target,
            );
            let confidence_alignment = shadow_target_alignment(
                shadow_confidence_target(candidate.shadow_confidence),
                target.confidence_target,
            );
            let head_states = [
                stance_alignment,
                risk_alignment,
                evidence_alignment,
                confidence_alignment,
            ];
            let match_count = head_states
                .iter()
                .filter(|state| **state == SmartCoreShadowAlignmentStatus::Match)
                .count();
            let mismatch_count = head_states
                .iter()
                .filter(|state| **state == SmartCoreShadowAlignmentStatus::Mismatch)
                .count();
            let overall_alignment = if match_count > 0 && mismatch_count == 0 {
                SmartCoreShadowCandidateOverallAlignment::Match
            } else if match_count > 0 && mismatch_count > 0 {
                SmartCoreShadowCandidateOverallAlignment::Partial
            } else if mismatch_count > 0 {
                SmartCoreShadowCandidateOverallAlignment::Mismatch
            } else {
                SmartCoreShadowCandidateOverallAlignment::Unknown
            };
            SmartCoreShadowCandidateTargetEval {
                eval_id: format!(
                    "{}-target-eval-{}",
                    candidate.candidate_id, target.target_id
                ),
                candidate_id: candidate.candidate_id.clone(),
                member_id: candidate.member_id.clone(),
                target_id: Some(target.target_id.clone()),
                stance_alignment,
                risk_alignment,
                evidence_alignment,
                confidence_alignment,
                overall_alignment,
                paper_only: true,
            }
        })
        .collect()
}

fn increment_target_eval_summary_count_bucket(
    summary: &mut SmartCoreShadowTargetEvalCountSummary,
    overall: SmartCoreShadowCandidateOverallAlignment,
) {
    match overall {
        SmartCoreShadowCandidateOverallAlignment::Match => summary.match_count += 1,
        SmartCoreShadowCandidateOverallAlignment::Partial => summary.partial_count += 1,
        SmartCoreShadowCandidateOverallAlignment::Mismatch => summary.mismatch_count += 1,
        SmartCoreShadowCandidateOverallAlignment::Unknown => summary.unknown_count += 1,
    }
}

fn increment_head_alignment_summary(
    summary: &mut SmartCoreShadowTargetEvalCountSummary,
    alignment: SmartCoreShadowAlignmentStatus,
) {
    match alignment {
        SmartCoreShadowAlignmentStatus::Match => summary.match_count += 1,
        SmartCoreShadowAlignmentStatus::Mismatch => summary.mismatch_count += 1,
        SmartCoreShadowAlignmentStatus::Unknown | SmartCoreShadowAlignmentStatus::Deferred => {
            summary.unknown_count += 1
        }
    }
}

pub fn summarize_shadow_candidate_target_eval(
    evals: &[SmartCoreShadowCandidateTargetEval],
) -> SmartCoreShadowCandidateTargetEvalSummary {
    let mut per_member_summary = std::collections::BTreeMap::new();
    let mut per_head_summary = std::collections::BTreeMap::new();
    for eval in evals {
        increment_target_eval_summary_count_bucket(
            per_member_summary
                .entry(eval.member_id.clone())
                .or_default(),
            eval.overall_alignment,
        );
        increment_head_alignment_summary(
            per_head_summary.entry("stance".to_string()).or_default(),
            eval.stance_alignment,
        );
        increment_head_alignment_summary(
            per_head_summary.entry("risk".to_string()).or_default(),
            eval.risk_alignment,
        );
        increment_head_alignment_summary(
            per_head_summary.entry("evidence".to_string()).or_default(),
            eval.evidence_alignment,
        );
        increment_head_alignment_summary(
            per_head_summary
                .entry("confidence".to_string())
                .or_default(),
            eval.confidence_alignment,
        );
    }
    let mut summary = SmartCoreShadowCandidateTargetEvalSummary {
        summary_id: "smartcore-shadow-target-eval-summary".to_string(),
        eval_count: evals.len(),
        match_count: 0,
        partial_count: 0,
        mismatch_count: 0,
        unknown_count: 0,
        per_member_summary,
        per_head_summary,
        paper_only: true,
    };
    for eval in evals {
        match eval.overall_alignment {
            SmartCoreShadowCandidateOverallAlignment::Match => summary.match_count += 1,
            SmartCoreShadowCandidateOverallAlignment::Partial => summary.partial_count += 1,
            SmartCoreShadowCandidateOverallAlignment::Mismatch => summary.mismatch_count += 1,
            SmartCoreShadowCandidateOverallAlignment::Unknown => summary.unknown_count += 1,
        }
    }
    summary
}

pub fn evaluate_shadow_opinion_decision_isolation(
    candidate_batch: &SmartCoreShadowOpinionCandidateBatch,
    batch_result_before: &BatchCommitteeCycleResult,
    batch_result_after: Option<&BatchCommitteeCycleResult>,
) -> SmartCoreShadowOpinionDecisionIsolationGuard {
    let candidate_markers: Vec<String> = candidate_batch
        .candidates
        .iter()
        .flat_map(|candidate| {
            [
                candidate.candidate_id.clone(),
                candidate.source_calibrated_output_id.clone(),
            ]
        })
        .filter(|marker| !marker.is_empty())
        .collect();
    let shadow_candidate_used_as_member_opinion =
        value_contains_debug_marker(&batch_result_before.member_opinions, &candidate_markers);
    let shadow_candidate_used_in_committee_session =
        value_contains_debug_marker(&batch_result_before.committee_sessions, &candidate_markers);
    let shadow_candidate_used_in_chairman_decision =
        value_contains_debug_marker(&batch_result_before.chairman_decisions, &candidate_markers);
    let shadow_candidate_used_in_risk_governor = batch_result_before
        .chairman_decisions
        .iter()
        .any(|decision| value_contains_debug_marker(decision, &candidate_markers));
    let shadow_candidate_used_as_trade_signal =
        value_contains_debug_marker(&batch_result_before.event_queue, &candidate_markers);
    let shadow_candidate_used_as_order =
        batch_result_before
            .chairman_decisions
            .iter()
            .any(|decision| {
                matches!(
                    decision.final_action,
                    ChairmanFinalAction::PaperBuy | ChairmanFinalAction::PaperSell
                ) && value_contains_debug_marker(decision, &candidate_markers)
            });
    let shadow_candidate_changed_member_score = batch_result_after.is_some_and(|after| {
        batch_result_before.score_updates != after.score_updates
            || batch_result_before.score_update_count != after.score_update_count
    });
    let shadow_candidate_changed_committee_decision = batch_result_after.is_some_and(|after| {
        batch_result_before.committee_sessions != after.committee_sessions
            || batch_result_before.chairman_decisions != after.chairman_decisions
    });
    let mut violations = Vec::new();
    if shadow_candidate_used_as_member_opinion {
        violations.push("shadow candidate leaked into member opinions".to_string());
    }
    if shadow_candidate_used_in_committee_session {
        violations.push("shadow candidate leaked into committee session".to_string());
    }
    if shadow_candidate_used_in_chairman_decision {
        violations.push("shadow candidate leaked into chairman decision".to_string());
    }
    if shadow_candidate_used_in_risk_governor {
        violations.push("shadow candidate leaked into risk governor path".to_string());
    }
    if shadow_candidate_used_as_trade_signal {
        violations.push("shadow candidate leaked into trade signal path".to_string());
    }
    if shadow_candidate_used_as_order {
        violations.push("shadow candidate leaked into order path".to_string());
    }
    if shadow_candidate_changed_member_score {
        violations.push("shadow candidate changed member score".to_string());
    }
    if shadow_candidate_changed_committee_decision {
        violations.push("shadow candidate changed committee decision".to_string());
    }
    SmartCoreShadowOpinionDecisionIsolationGuard {
        guard_id: format!("{}-shadow-opinion-isolation", batch_result_before.batch_id),
        shadow_candidate_used_as_member_opinion,
        shadow_candidate_used_in_committee_session,
        shadow_candidate_used_in_chairman_decision,
        shadow_candidate_used_in_risk_governor,
        shadow_candidate_used_as_trade_signal,
        shadow_candidate_used_as_order,
        shadow_candidate_changed_member_score,
        shadow_candidate_changed_committee_decision,
        guard_status: if violations.is_empty() {
            SmartCoreShadowOpinionDecisionIsolationGuardStatus::Preserved
        } else {
            SmartCoreShadowOpinionDecisionIsolationGuardStatus::Violated
        },
        violations,
        paper_only: true,
    }
}

fn overall_target_alignment_for_member(
    evals: &[SmartCoreShadowCandidateTargetEval],
    member_id: &str,
) -> SmartCoreShadowCandidateOverallAlignment {
    let member_evals = evals
        .iter()
        .filter(|eval| eval.member_id == member_id)
        .map(|eval| eval.overall_alignment)
        .collect::<Vec<_>>();
    if member_evals
        .iter()
        .any(|alignment| *alignment == SmartCoreShadowCandidateOverallAlignment::Mismatch)
    {
        SmartCoreShadowCandidateOverallAlignment::Mismatch
    } else if member_evals
        .iter()
        .any(|alignment| *alignment == SmartCoreShadowCandidateOverallAlignment::Partial)
    {
        SmartCoreShadowCandidateOverallAlignment::Partial
    } else if member_evals
        .iter()
        .any(|alignment| *alignment == SmartCoreShadowCandidateOverallAlignment::Match)
    {
        SmartCoreShadowCandidateOverallAlignment::Match
    } else {
        SmartCoreShadowCandidateOverallAlignment::Unknown
    }
}

pub fn build_owner_shadow_opinion_debug_section(
    run_result: &SmartCoreShadowOpinionRunResult,
) -> OwnerShadowOpinionDebugSection {
    let cards = run_result
        .candidate_batch
        .candidates
        .iter()
        .map(|candidate| OwnerShadowOpinionDebugCard {
            member_id: candidate.member_id.clone(),
            display_name: display_name_for_member_id(&candidate.member_id).to_string(),
            shadow_action: candidate.shadow_action,
            shadow_confidence: candidate.shadow_confidence,
            shadow_risk: candidate.shadow_risk,
            shadow_evidence: candidate.shadow_evidence,
            agreement_with_member_opinion: run_result
                .member_opinion_summary
                .per_member_agreement
                .get(&candidate.member_id)
                .copied()
                .unwrap_or(ShadowVsMemberOpinionAgreement::Unknown),
            target_alignment: overall_target_alignment_for_member(
                &run_result.target_evals,
                &candidate.member_id,
            ),
            debug_only: true,
            shadow_only: true,
            not_investment_signal: true,
            not_committee_opinion: true,
            paper_only: true,
        })
        .collect::<Vec<_>>();
    OwnerShadowOpinionDebugSection {
        section_id: format!("{}-owner-shadow-opinion", run_result.run_id),
        cards,
        agreement_summary: format!(
            "agree={}, partial={}, disagree={}, status={:?}",
            run_result.member_opinion_summary.agree_count,
            run_result.member_opinion_summary.partial_count,
            run_result.member_opinion_summary.disagree_count,
            run_result.member_opinion_summary.summary_status
        ),
        target_eval_summary: format!(
            "match={}, partial={}, mismatch={}, unknown={}",
            run_result.target_eval_summary.match_count,
            run_result.target_eval_summary.partial_count,
            run_result.target_eval_summary.mismatch_count,
            run_result.target_eval_summary.unknown_count
        ),
        warning: "SmartCore shadow opinion candidates are not used for committee decisions."
            .to_string(),
        paper_only: true,
    }
}

pub fn build_shadow_opinion_feedback_plan(
    run_result: &SmartCoreShadowOpinionRunResult,
) -> ShadowOpinionFeedbackPlan {
    let mut feedback_needs = Vec::new();
    if run_result.member_opinion_summary.disagree_count > 0 {
        feedback_needs.push(ShadowOpinionFeedbackNeed::MoreAgreementTargets);
        feedback_needs.push(ShadowOpinionFeedbackNeed::MoreMemberSpecificCalibration);
    }
    if run_result
        .target_eval_summary
        .per_head_summary
        .get("risk")
        .is_some_and(|summary| summary.mismatch_count > 0)
    {
        feedback_needs.push(ShadowOpinionFeedbackNeed::MoreRiskTargets);
    }
    if run_result
        .target_eval_summary
        .per_head_summary
        .get("evidence")
        .is_some_and(|summary| summary.mismatch_count > 0)
    {
        feedback_needs.push(ShadowOpinionFeedbackNeed::MoreEvidenceTargets);
    }
    if run_result
        .target_eval_summary
        .per_head_summary
        .get("confidence")
        .is_some_and(|summary| summary.mismatch_count > 0)
    {
        feedback_needs.push(ShadowOpinionFeedbackNeed::MoreConfidenceTargets);
    }
    feedback_needs.push(ShadowOpinionFeedbackNeed::DoNotUseForDecisionYet);
    feedback_needs.sort();
    feedback_needs.dedup();
    let next_recommended_step = if run_result.decision_isolation_guard.guard_status
        == SmartCoreShadowOpinionDecisionIsolationGuardStatus::Violated
    {
        ShadowOpinionFeedbackNextStep::DoNotIntegrateDecision
    } else if run_result.member_opinion_summary.disagree_count
        > run_result.candidate_batch.candidate_count.saturating_div(2)
        || run_result.target_eval_summary.mismatch_count
            > run_result.candidate_batch.candidate_count.saturating_div(2)
    {
        ShadowOpinionFeedbackNextStep::CollectMoreTargets
    } else if run_result.candidate_batch.candidate_count > 0 {
        ShadowOpinionFeedbackNextStep::BuildShadowOpinionStabilityTest
    } else {
        ShadowOpinionFeedbackNextStep::KeepShadowOnly
    };
    ShadowOpinionFeedbackPlan {
        plan_id: format!("{}-shadow-opinion-feedback", run_result.run_id),
        candidate_count: run_result.candidate_batch.candidate_count,
        disagreement_count: run_result.member_opinion_summary.disagree_count,
        mismatch_count: run_result.target_eval_summary.mismatch_count,
        feedback_needs,
        next_recommended_step,
        paper_only: true,
    }
}

