fn maybe_run_smartcore_shadow_opinion_for_batch_result(
    run_id: String,
    enabled: bool,
    output_path: Option<&String>,
    include_member_opinion_comparison: bool,
    include_target_eval: bool,
    emit_owner_debug_summary: bool,
    batch_result: &mut BatchCommitteeCycleResult,
) -> Result<Option<SmartCoreShadowOpinionRunResult>, String> {
    if !smartcore_shadow_opinion_requested_from_flags(
        enabled,
        output_path,
        include_member_opinion_comparison,
        include_target_eval,
        emit_owner_debug_summary,
    ) {
        return Ok(None);
    }
    let calibrated_debug_batch = batch_result
        .smartcore_shadow_recalibration_run_result
        .as_ref()
        .ok_or_else(|| {
            "smartcore shadow opinion lane requires recalibrated debug output".to_string()
        })?
        .calibrated_debug_output_batch
        .clone();
    let result = run_smartcore_shadow_opinion_lane(
        &calibrated_debug_batch,
        batch_result,
        Some(&batch_result.replay_dataset),
        &SmartCoreShadowOpinionRunConfig {
            run_id,
            enabled,
            output_path: output_path.cloned(),
            include_member_opinion_comparison,
            include_target_eval,
            emit_owner_debug_summary,
            paper_only: true,
        },
    )?;
    if let Some(shadow_alignment_result) =
        batch_result.smartcore_shadow_alignment_run_result.as_mut()
    {
        shadow_alignment_result.owner_core_debug_section = apply_owner_shadow_opinion_debug_update(
            &batch_result.batch_id,
            shadow_alignment_result.owner_core_debug_section.take(),
            result.owner_debug_section.clone(),
        );
        shadow_alignment_result.owner_core_debug_card_count = shadow_alignment_result
            .owner_core_debug_section
            .as_ref()
            .map(|section| section.cards.len())
            .unwrap_or(0);
    }
    batch_result.smartcore_shadow_opinion_run_result = Some(result.clone());
    Ok(Some(result))
}

pub fn collect_shadow_stability_samples(
    shadow_opinion_run_result: &SmartCoreShadowOpinionRunResult,
    repeat_index: usize,
) -> Vec<SmartCoreShadowStabilitySample> {
    let mut samples = shadow_opinion_run_result
        .candidate_batch
        .candidates
        .iter()
        .map(|candidate| SmartCoreShadowStabilitySample {
            sample_id: format!("{}-repeat-{repeat_index}", candidate.candidate_id),
            repeat_index,
            member_id: candidate.member_id.clone(),
            candidate_id: candidate.candidate_id.clone(),
            shadow_action: candidate.shadow_action,
            shadow_confidence: candidate.shadow_confidence,
            shadow_risk: candidate.shadow_risk,
            shadow_evidence: candidate.shadow_evidence,
            stance_bucket: Some(candidate.source_heads.stance_bucket.clone()),
            risk_bucket: Some(candidate.source_heads.risk_bucket.clone()),
            evidence_bucket: Some(candidate.source_heads.evidence_bucket.clone()),
            confidence_bucket: Some(candidate.source_heads.confidence_bucket.clone()),
            uncertainty_bucket: candidate.source_heads.uncertainty_bucket.clone(),
            target_alignment: Some(overall_target_alignment_for_member(
                &shadow_opinion_run_result.target_evals,
                &candidate.member_id,
            )),
            paper_only: true,
        })
        .collect::<Vec<_>>();
    samples.sort_by(|left, right| {
        left.member_id
            .cmp(&right.member_id)
            .then_with(|| left.sample_id.cmp(&right.sample_id))
    });
    samples
}

fn sample_bucket_value(sample: &SmartCoreShadowStabilitySample, head: &str) -> Option<String> {
    match head {
        "stance" => sample.stance_bucket.clone(),
        "risk" => sample.risk_bucket.clone(),
        "evidence" => sample.evidence_bucket.clone(),
        "confidence" => sample.confidence_bucket.clone(),
        "uncertainty" => sample.uncertainty_bucket.clone(),
        _ => None,
    }
}

pub fn compute_shadow_stability_metrics(
    samples: &[SmartCoreShadowStabilitySample],
) -> SmartCoreShadowStabilityMetrics {
    let repeated_run_count = samples
        .iter()
        .map(|sample| sample.repeat_index)
        .collect::<std::collections::BTreeSet<_>>()
        .len();
    let member_count = samples
        .iter()
        .map(|sample| sample.member_id.clone())
        .collect::<std::collections::BTreeSet<_>>()
        .len();
    let mut samples_by_member: std::collections::BTreeMap<
        String,
        Vec<&SmartCoreShadowStabilitySample>,
    > = std::collections::BTreeMap::new();
    for sample in samples {
        samples_by_member
            .entry(sample.member_id.clone())
            .or_default()
            .push(sample);
    }
    let mut action_flip_count = 0usize;
    let mut action_possible = 0usize;
    let mut per_member_flip_rates = std::collections::BTreeMap::new();
    let mut head_flip_count = 0usize;
    let mut head_possible = 0usize;
    let mut per_head_flips: std::collections::BTreeMap<String, usize> =
        std::collections::BTreeMap::new();
    let mut per_head_possible: std::collections::BTreeMap<String, usize> =
        std::collections::BTreeMap::new();
    for (member_id, member_samples) in &mut samples_by_member {
        let mut ordered = member_samples.clone();
        ordered.sort_by_key(|sample| sample.repeat_index);
        if let Some(first) = ordered.first() {
            let mut member_action_flips = 0usize;
            for sample in ordered.iter().skip(1) {
                action_possible += 1;
                if sample.shadow_action != first.shadow_action {
                    action_flip_count += 1;
                    member_action_flips += 1;
                }
                for head in ["stance", "risk", "evidence", "confidence", "uncertainty"] {
                    *per_head_possible.entry(head.to_string()).or_insert(0) += 1;
                    head_possible += 1;
                    if sample_bucket_value(sample, head) != sample_bucket_value(first, head) {
                        *per_head_flips.entry(head.to_string()).or_insert(0) += 1;
                        head_flip_count += 1;
                    }
                }
            }
            per_member_flip_rates.insert(
                member_id.clone(),
                safe_ratio(member_action_flips, ordered.len().saturating_sub(1)),
            );
        }
    }
    let per_head_flip_rates = per_head_possible
        .into_iter()
        .map(|(head, possible)| {
            (
                head.clone(),
                safe_ratio(per_head_flips.get(&head).copied().unwrap_or(0), possible),
            )
        })
        .collect::<std::collections::BTreeMap<_, _>>();
    let action_flip_rate = safe_ratio(action_flip_count, action_possible);
    let head_bucket_flip_rate = safe_ratio(head_flip_count, head_possible);
    let deterministic_status = if action_flip_rate == 0.0 && head_bucket_flip_rate == 0.0 {
        SmartCoreShadowStabilityDeterministicStatus::Deterministic
    } else if action_flip_rate <= 0.1 && head_bucket_flip_rate <= 0.1 {
        SmartCoreShadowStabilityDeterministicStatus::StableWithWarnings
    } else {
        SmartCoreShadowStabilityDeterministicStatus::Unstable
    };
    SmartCoreShadowStabilityMetrics {
        metrics_id: "smartcore-shadow-stability-metrics".to_string(),
        repeated_run_count,
        sample_count: samples.len(),
        member_count,
        action_flip_count,
        action_flip_rate,
        head_bucket_flip_count: head_flip_count,
        head_bucket_flip_rate,
        per_member_flip_rates,
        per_head_flip_rates,
        deterministic_status,
        paper_only: true,
    }
}

fn push_stability_mismatch_record(
    records: &mut Vec<SmartCoreShadowStabilityMismatchRecord>,
    member_id: &str,
    repeat_indices: Vec<usize>,
    mismatch_kind: SmartCoreShadowStabilityMismatchKind,
    previous_value: impl Into<String>,
    new_value: impl Into<String>,
) {
    let (severity, suggested_fix) = match mismatch_kind {
        SmartCoreShadowStabilityMismatchKind::ActionFlip
        | SmartCoreShadowStabilityMismatchKind::UnexpectedNonDeterminism => (
            SmartCoreShadowStabilityMismatchSeverity::High,
            SmartCoreShadowStabilitySuggestedFix::CheckDeterministicHash,
        ),
        SmartCoreShadowStabilityMismatchKind::RiskBucketFlip
        | SmartCoreShadowStabilityMismatchKind::EvidenceBucketFlip
        | SmartCoreShadowStabilityMismatchKind::ConfidenceBucketFlip => (
            SmartCoreShadowStabilityMismatchSeverity::Medium,
            SmartCoreShadowStabilitySuggestedFix::CheckCalibrationOverlay,
        ),
        SmartCoreShadowStabilityMismatchKind::TargetAlignmentFlip => (
            SmartCoreShadowStabilityMismatchSeverity::Medium,
            SmartCoreShadowStabilitySuggestedFix::CheckTargetExpansion,
        ),
    };
    records.push(SmartCoreShadowStabilityMismatchRecord {
        mismatch_id: format!("{}-{:?}-{:?}", member_id, mismatch_kind, repeat_indices),
        member_id: member_id.to_string(),
        repeat_indices,
        mismatch_kind,
        previous_value: previous_value.into(),
        new_value: new_value.into(),
        severity,
        suggested_fix,
        paper_only: true,
    });
}

pub fn build_shadow_stability_mismatch_records(
    samples: &[SmartCoreShadowStabilitySample],
    metrics: &SmartCoreShadowStabilityMetrics,
) -> Vec<SmartCoreShadowStabilityMismatchRecord> {
    let mut samples_by_member: std::collections::BTreeMap<
        String,
        Vec<&SmartCoreShadowStabilitySample>,
    > = std::collections::BTreeMap::new();
    for sample in samples {
        samples_by_member
            .entry(sample.member_id.clone())
            .or_default()
            .push(sample);
    }
    let mut records = Vec::new();
    for (member_id, mut member_samples) in samples_by_member {
        member_samples.sort_by_key(|sample| sample.repeat_index);
        for pair in member_samples.windows(2) {
            let previous = pair[0];
            let next = pair[1];
            if previous.shadow_action != next.shadow_action {
                push_stability_mismatch_record(
                    &mut records,
                    &member_id,
                    vec![previous.repeat_index, next.repeat_index],
                    SmartCoreShadowStabilityMismatchKind::ActionFlip,
                    format!("{:?}", previous.shadow_action),
                    format!("{:?}", next.shadow_action),
                );
            }
            for (head, kind) in [
                ("risk", SmartCoreShadowStabilityMismatchKind::RiskBucketFlip),
                (
                    "evidence",
                    SmartCoreShadowStabilityMismatchKind::EvidenceBucketFlip,
                ),
                (
                    "confidence",
                    SmartCoreShadowStabilityMismatchKind::ConfidenceBucketFlip,
                ),
            ] {
                if sample_bucket_value(previous, head) != sample_bucket_value(next, head) {
                    push_stability_mismatch_record(
                        &mut records,
                        &member_id,
                        vec![previous.repeat_index, next.repeat_index],
                        kind,
                        sample_bucket_value(previous, head)
                            .unwrap_or_else(|| "Unknown".to_string()),
                        sample_bucket_value(next, head).unwrap_or_else(|| "Unknown".to_string()),
                    );
                }
            }
            if previous.target_alignment != next.target_alignment {
                push_stability_mismatch_record(
                    &mut records,
                    &member_id,
                    vec![previous.repeat_index, next.repeat_index],
                    SmartCoreShadowStabilityMismatchKind::TargetAlignmentFlip,
                    format!("{:?}", previous.target_alignment),
                    format!("{:?}", next.target_alignment),
                );
            }
        }
    }
    if metrics.deterministic_status == SmartCoreShadowStabilityDeterministicStatus::Unstable
        && records.is_empty()
    {
        records.push(SmartCoreShadowStabilityMismatchRecord {
            mismatch_id: "shadow-stability-unexpected-nondeterminism".to_string(),
            member_id: "unknown".to_string(),
            repeat_indices: vec![0, metrics.repeated_run_count.saturating_sub(1)],
            mismatch_kind: SmartCoreShadowStabilityMismatchKind::UnexpectedNonDeterminism,
            previous_value: "stable".to_string(),
            new_value: "unstable".to_string(),
            severity: SmartCoreShadowStabilityMismatchSeverity::High,
            suggested_fix: SmartCoreShadowStabilitySuggestedFix::CheckInputOrdering,
            paper_only: true,
        });
    }
    records
}

fn build_shadow_alignment_targets_from_paper_outcome_evidence(
    records: &[PaperOutcomeEvidenceRecord],
    replay_dataset: Option<&ReplayDataset>,
) -> Vec<SmartCoreShadowAlignmentTarget> {
    let Some(dataset) = replay_dataset else {
        return Vec::new();
    };
    let mut targets = Vec::new();
    for record in records {
        let matching_members = dataset
            .examples
            .iter()
            .filter(|example| {
                example.symbol == record.symbol && example.market_scope == record.market_scope
            })
            .map(|example| example.member_id.clone())
            .collect::<std::collections::BTreeSet<_>>();
        for member_id in matching_members {
            let outcome_target = outcome_target_from_member_outcome(record.candidate_label);
            targets.push(SmartCoreShadowAlignmentTarget {
                target_id: format!("{}-{}", record.evidence_id, member_id),
                member_id,
                symbol: Some(record.symbol.clone()),
                market_scope: Some(record.market_scope),
                source_type: SmartCoreShadowAlignmentTargetSourceType::PaperOutcomeLabel,
                stance_target: Some(outcome_target),
                risk_target: None,
                evidence_target: Some(
                    if matches!(
                        record.label_confidence,
                        ReplayLabelConfidence::ReviewRequired
                    ) {
                        SmartCoreHeadBucketNormalizedValue::NeedMoreEvidence
                    } else {
                        SmartCoreHeadBucketNormalizedValue::EvidenceSufficient
                    },
                ),
                confidence_target: Some(confidence_bucket_from_replay_confidence(
                    record.label_confidence,
                )),
                outcome_target: Some(outcome_target),
                paper_only: true,
            });
        }
    }
    targets
}

pub fn expand_smartcore_agreement_targets(
    batch_result: &BatchCommitteeCycleResult,
    replay_dataset: Option<&ReplayDataset>,
    calibration_dataset: Option<&CoreCalibrationDataset>,
    evidence_store: Option<&[PaperOutcomeEvidenceRecord]>,
    config: &SmartCoreAgreementTargetExpansionConfig,
) -> SmartCoreAgreementTargetExpansionResult {
    let mut previous_targets = Vec::new();
    if config.include_replay_targets {
        if let Some(dataset) = replay_dataset {
            previous_targets.extend(build_shadow_alignment_targets_from_replay_dataset(dataset));
        }
    }
    if config.include_member_opinion_targets || config.include_risk_governor_targets {
        previous_targets.extend(
            build_shadow_alignment_targets_from_batch_cycle(batch_result)
                .into_iter()
                .filter(|target| {
                    (config.include_member_opinion_targets
                        && target.source_type
                            == SmartCoreShadowAlignmentTargetSourceType::MemberOpinion)
                        || (config.include_risk_governor_targets
                            && target.source_type
                                == SmartCoreShadowAlignmentTargetSourceType::RiskGovernorStatus)
                }),
        );
    }
    let previous_target_count = previous_targets.len();
    let mut all_targets = previous_targets.clone();
    let mut added_targets = Vec::new();
    if config.include_calibration_dataset_targets {
        if let Some(dataset) = calibration_dataset {
            added_targets
                .extend(build_shadow_alignment_targets_from_core_calibration_dataset(dataset));
        }
    }
    if config.include_paper_outcome_targets {
        if let Some(records) = evidence_store {
            added_targets.extend(build_shadow_alignment_targets_from_paper_outcome_evidence(
                records,
                replay_dataset,
            ));
        }
    }
    let mut duplicate_target_count = 0usize;
    let mut seen = all_targets
        .iter()
        .map(|target| {
            (
                target.target_id.clone(),
                target.member_id.clone(),
                format!("{:?}", target.source_type),
            )
        })
        .collect::<std::collections::BTreeSet<_>>();
    for target in added_targets {
        let key = (
            target.target_id.clone(),
            target.member_id.clone(),
            format!("{:?}", target.source_type),
        );
        if seen.insert(key) {
            all_targets.push(target);
        } else {
            duplicate_target_count += 1;
        }
    }
    all_targets.sort_by(|left, right| {
        left.member_id
            .cmp(&right.member_id)
            .then_with(|| left.target_id.cmp(&right.target_id))
    });
    let mut per_member_counts: std::collections::BTreeMap<String, usize> =
        std::collections::BTreeMap::new();
    let mut limited_targets = Vec::new();
    for target in all_targets {
        let entry = per_member_counts
            .entry(target.member_id.clone())
            .or_insert(0);
        if *entry < config.max_targets_per_member.max(1) {
            limited_targets.push(target);
            *entry += 1;
        }
    }
    let added_target_count = limited_targets.len().saturating_sub(previous_target_count);
    let target_distribution_by_member =
        limited_targets
            .iter()
            .fold(std::collections::BTreeMap::new(), |mut map, target| {
                *map.entry(target.member_id.clone()).or_insert(0usize) += 1;
                map
            });
    let target_distribution_by_source =
        limited_targets
            .iter()
            .fold(std::collections::BTreeMap::new(), |mut map, target| {
                *map.entry(format!("{:?}", target.source_type))
                    .or_insert(0usize) += 1;
                map
            });
    let target_distribution_by_head =
        limited_targets
            .iter()
            .fold(std::collections::BTreeMap::new(), |mut map, target| {
                if target.stance_target.is_some() {
                    *map.entry("stance".to_string()).or_insert(0usize) += 1;
                }
                if target.risk_target.is_some() {
                    *map.entry("risk".to_string()).or_insert(0usize) += 1;
                }
                if target.evidence_target.is_some() {
                    *map.entry("evidence".to_string()).or_insert(0usize) += 1;
                }
                if target.confidence_target.is_some() {
                    *map.entry("confidence".to_string()).or_insert(0usize) += 1;
                }
                map
            });
    let expansion_status = if previous_target_count == 0 && limited_targets.is_empty() {
        SmartCoreAgreementTargetExpansionStatus::InsufficientSources
    } else if added_target_count > 0 && duplicate_target_count > 0 {
        SmartCoreAgreementTargetExpansionStatus::ExpandedWithWarnings
    } else if added_target_count > 0 {
        SmartCoreAgreementTargetExpansionStatus::Expanded
    } else {
        SmartCoreAgreementTargetExpansionStatus::NoChange
    };
    SmartCoreAgreementTargetExpansionResult {
        previous_target_count,
        added_target_count,
        duplicate_target_count,
        new_target_count: limited_targets.len(),
        targets: limited_targets,
        target_distribution_by_member,
        target_distribution_by_source,
        target_distribution_by_head,
        expansion_status,
        paper_only: true,
    }
}

pub fn summarize_smartcore_agreement_target_quality(
    targets: &[SmartCoreShadowAlignmentTarget],
) -> SmartCoreAgreementTargetQualitySummary {
    let member_coverage = targets
        .iter()
        .map(|target| target.member_id.clone())
        .collect::<std::collections::BTreeSet<_>>()
        .len();
    let head_coverage = ["stance", "risk", "evidence", "confidence"]
        .into_iter()
        .filter(|head| match *head {
            "stance" => targets.iter().any(|target| target.stance_target.is_some()),
            "risk" => targets.iter().any(|target| target.risk_target.is_some()),
            "evidence" => targets
                .iter()
                .any(|target| target.evidence_target.is_some()),
            "confidence" => targets
                .iter()
                .any(|target| target.confidence_target.is_some()),
            _ => false,
        })
        .count();
    let source_distribution =
        targets
            .iter()
            .fold(std::collections::BTreeMap::new(), |mut map, target| {
                *map.entry(format!("{:?}", target.source_type))
                    .or_insert(0usize) += 1;
                map
            });
    let mut recommended_next_targets = Vec::new();
    if !targets.iter().any(|target| target.risk_target.is_some()) {
        recommended_next_targets.push(SmartCoreAgreementTargetRecommendation::MoreRiskTargets);
    }
    if !targets
        .iter()
        .any(|target| target.evidence_target.is_some())
    {
        recommended_next_targets.push(SmartCoreAgreementTargetRecommendation::MoreEvidenceTargets);
    }
    if !targets.iter().any(|target| target.stance_target.is_some()) {
        recommended_next_targets.push(SmartCoreAgreementTargetRecommendation::MoreStanceTargets);
    }
    if !targets
        .iter()
        .any(|target| target.confidence_target.is_some())
    {
        recommended_next_targets
            .push(SmartCoreAgreementTargetRecommendation::MoreConfidenceTargets);
    }
    if member_coverage < 3 {
        recommended_next_targets
            .push(SmartCoreAgreementTargetRecommendation::MoreMemberSpecificTargets);
    }
    if source_distribution
        .get("PaperOutcomeLabel")
        .copied()
        .unwrap_or(0)
        == 0
    {
        recommended_next_targets
            .push(SmartCoreAgreementTargetRecommendation::MorePaperOutcomeTargets);
    }
    recommended_next_targets.sort();
    recommended_next_targets.dedup();
    let target_quality_status = if targets.iter().any(|target| !target.paper_only) {
        SmartCoreAgreementTargetQualityStatus::Unsafe
    } else if targets.is_empty() {
        SmartCoreAgreementTargetQualityStatus::NeedsMoreTargets
    } else if member_coverage < 3 {
        SmartCoreAgreementTargetQualityStatus::ThinMemberCoverage
    } else if head_coverage < 4 {
        SmartCoreAgreementTargetQualityStatus::ThinHeadCoverage
    } else {
        SmartCoreAgreementTargetQualityStatus::Sufficient
    };
    SmartCoreAgreementTargetQualitySummary {
        summary_id: "smartcore-agreement-target-quality".to_string(),
        target_count: targets.len(),
        member_coverage,
        head_coverage,
        source_distribution,
        low_confidence_target_count: 0,
        review_required_target_count: 0,
        target_quality_status,
        recommended_next_targets,
        paper_only: true,
    }
}

pub fn build_agreement_target_collection_queue(
    quality_summary: &SmartCoreAgreementTargetQualitySummary,
) -> SmartCoreAgreementTargetCollectionQueue {
    let tasks = quality_summary
        .recommended_next_targets
        .iter()
        .map(|recommendation| {
            let (target_need, head, priority, reason) = match recommendation {
                SmartCoreAgreementTargetRecommendation::MoreRiskTargets => (
                    SmartCoreAgreementTargetNeed::RiskTarget,
                    Some(SmartCoreShadowHeadKind::Risk),
                    SmartCoreAgreementTargetTaskPriority::High,
                    "Need more risk agreement targets for shadow stability.".to_string(),
                ),
                SmartCoreAgreementTargetRecommendation::MoreEvidenceTargets => (
                    SmartCoreAgreementTargetNeed::EvidenceTarget,
                    Some(SmartCoreShadowHeadKind::EvidenceNeed),
                    SmartCoreAgreementTargetTaskPriority::High,
                    "Need more evidence agreement targets for shadow stability.".to_string(),
                ),
                SmartCoreAgreementTargetRecommendation::MoreStanceTargets => (
                    SmartCoreAgreementTargetNeed::StanceTarget,
                    Some(SmartCoreShadowHeadKind::Stance),
                    SmartCoreAgreementTargetTaskPriority::Normal,
                    "Need more stance agreement targets.".to_string(),
                ),
                SmartCoreAgreementTargetRecommendation::MoreConfidenceTargets => (
                    SmartCoreAgreementTargetNeed::ConfidenceTarget,
                    Some(SmartCoreShadowHeadKind::ConfidenceCalibration),
                    SmartCoreAgreementTargetTaskPriority::Normal,
                    "Need more confidence agreement targets.".to_string(),
                ),
                SmartCoreAgreementTargetRecommendation::MoreMemberSpecificTargets => (
                    SmartCoreAgreementTargetNeed::MemberOpinionTarget,
                    None,
                    SmartCoreAgreementTargetTaskPriority::Normal,
                    "Need more member-specific agreement targets.".to_string(),
                ),
                SmartCoreAgreementTargetRecommendation::MorePaperOutcomeTargets => (
                    SmartCoreAgreementTargetNeed::PaperOutcomeTarget,
                    None,
                    SmartCoreAgreementTargetTaskPriority::Low,
                    "Need more paper outcome agreement targets.".to_string(),
                ),
            };
            SmartCoreAgreementTargetCollectionTask {
                task_id: format!("smartcore-agreement-target-task-{recommendation:?}"),
                member_id: None,
                head,
                target_need,
                priority,
                reason,
                paper_only: true,
            }
        })
        .collect::<Vec<_>>();
    SmartCoreAgreementTargetCollectionQueue {
        queue_id: "smartcore-agreement-target-collection-queue".to_string(),
        task_count: tasks.len(),
        high_priority_count: tasks
            .iter()
            .filter(|task| task.priority == SmartCoreAgreementTargetTaskPriority::High)
            .count(),
        tasks,
        paper_only: true,
    }
}

pub fn build_owner_shadow_stability_debug_summary(
    stability_result: &SmartCoreShadowStabilityRunResult,
) -> OwnerShadowStabilityDebugSummary {
    OwnerShadowStabilityDebugSummary {
        summary_id: format!("{}-owner-shadow-stability", stability_result.run_id),
        repeated_run_count: stability_result.repeated_run_count,
        action_flip_rate: stability_result.stability_metrics.action_flip_rate,
        head_bucket_flip_rate: stability_result.stability_metrics.head_bucket_flip_rate,
        deterministic_status: stability_result.stability_metrics.deterministic_status,
        target_count_before: stability_result.target_expansion_result.previous_target_count,
        target_count_after: stability_result.target_expansion_result.new_target_count,
        target_quality_status: stability_result.target_quality_summary.target_quality_status,
        target_collection_task_count: stability_result.target_collection_queue.task_count,
        message:
            "Shadow candidates are being tested for stability. They are not used for decisions. More agreement targets may be needed."
                .to_string(),
        debug_only: true,
        not_investment_signal: true,
        not_committee_opinion: true,
        paper_only: true,
    }
}

pub fn evaluate_shadow_stability_decision_isolation_regression(
    stability_result: &SmartCoreShadowStabilityRunResult,
    batch_result_before: &BatchCommitteeCycleResult,
    batch_result_after: Option<&BatchCommitteeCycleResult>,
) -> SmartCoreShadowStabilityDecisionIsolationRegression {
    let after = batch_result_after.unwrap_or(batch_result_before);
    let mismatch_markers = stability_result
        .stability_mismatch_records
        .iter()
        .map(|record| record.mismatch_id.clone())
        .collect::<Vec<_>>();
    let task_markers = stability_result
        .target_collection_queue
        .tasks
        .iter()
        .map(|task| task.task_id.clone())
        .collect::<Vec<_>>();
    let target_markers = stability_result
        .target_expansion_result
        .targets
        .iter()
        .map(|target| target.target_id.clone())
        .collect::<Vec<_>>();
    let shadow_candidate_changed_decision = batch_result_before.committee_sessions
        != after.committee_sessions
        || batch_result_before.chairman_decisions != after.chairman_decisions;
    let shadow_candidate_changed_member_score =
        batch_result_before.score_updates != after.score_updates;
    let stability_task_used_as_order =
        value_contains_debug_marker(&after.chairman_decisions, &mismatch_markers)
            || value_contains_debug_marker(&after.event_queue, &mismatch_markers);
    let target_collection_task_used_as_order =
        value_contains_debug_marker(&after.chairman_decisions, &task_markers)
            || value_contains_debug_marker(&after.event_queue, &task_markers);
    let agreement_target_used_as_input_feature =
        value_contains_debug_marker(&after.replay_dataset.examples, &target_markers);
    let mut violations = Vec::new();
    if shadow_candidate_changed_decision {
        violations.push("shadow stability changed committee/chairman decisions".to_string());
    }
    if shadow_candidate_changed_member_score {
        violations.push("shadow stability changed member score".to_string());
    }
    if stability_task_used_as_order {
        violations.push("stability mismatch record leaked into order path".to_string());
    }
    if target_collection_task_used_as_order {
        violations.push("target collection task leaked into order path".to_string());
    }
    if agreement_target_used_as_input_feature {
        violations.push("agreement target leaked into input features".to_string());
    }
    SmartCoreShadowStabilityDecisionIsolationRegression {
        shadow_candidate_changed_decision,
        shadow_candidate_changed_member_score,
        stability_task_used_as_order,
        target_collection_task_used_as_order,
        agreement_target_used_as_input_feature,
        regression_status: if violations.is_empty() {
            SmartCoreShadowStabilityDecisionIsolationRegressionStatus::Preserved
        } else {
            SmartCoreShadowStabilityDecisionIsolationRegressionStatus::Violated
        },
        violations,
        paper_only: true,
    }
}

fn default_shadow_stability_metrics() -> SmartCoreShadowStabilityMetrics {
    SmartCoreShadowStabilityMetrics {
        metrics_id: "smartcore-shadow-stability-metrics".to_string(),
        repeated_run_count: 0,
        sample_count: 0,
        member_count: 0,
        action_flip_count: 0,
        action_flip_rate: 0.0,
        head_bucket_flip_count: 0,
        head_bucket_flip_rate: 0.0,
        per_member_flip_rates: std::collections::BTreeMap::new(),
        per_head_flip_rates: std::collections::BTreeMap::new(),
        deterministic_status: SmartCoreShadowStabilityDeterministicStatus::Deterministic,
        paper_only: true,
    }
}

pub fn run_smartcore_shadow_stability_eval(
    shadow_opinion_run_result: &SmartCoreShadowOpinionRunResult,
    batch_result: &BatchCommitteeCycleResult,
    replay_dataset: Option<&ReplayDataset>,
    calibration_dataset: Option<&CoreCalibrationDataset>,
    evidence_store: Option<&[PaperOutcomeEvidenceRecord]>,
    config: &SmartCoreShadowStabilityRunConfig,
) -> Result<SmartCoreShadowStabilityRunResult, String> {
    if !config.paper_only {
        return Err("smartcore shadow stability eval must remain paper-only".to_string());
    }
    if config.repeated_run_count == 0 {
        return Err("smartcore shadow stability repeated_run_count must be positive".to_string());
    }
    if let Some(path) = config.output_path.as_ref() {
        validate_local_json_path(Path::new(path), "smartcore shadow stability output path")?;
    }
    let mut samples = Vec::new();
    if config.include_shadow_candidate_repeat {
        for repeat_index in 0..config.repeated_run_count {
            samples.extend(collect_shadow_stability_samples(
                shadow_opinion_run_result,
                repeat_index,
            ));
        }
    }
    let stability_metrics = if samples.is_empty() {
        default_shadow_stability_metrics()
    } else {
        compute_shadow_stability_metrics(&samples)
    };
    let stability_mismatch_records =
        build_shadow_stability_mismatch_records(&samples, &stability_metrics);
    let target_expansion_result = expand_smartcore_agreement_targets(
        batch_result,
        replay_dataset,
        calibration_dataset,
        evidence_store,
        &SmartCoreAgreementTargetExpansionConfig {
            run_id: format!("{}-target-expansion", config.run_id),
            include_replay_targets: true,
            include_member_opinion_targets: true,
            include_risk_governor_targets: true,
            include_calibration_dataset_targets: calibration_dataset.is_some(),
            include_paper_outcome_targets: evidence_store.is_some(),
            max_targets_per_member: 8,
            paper_only: true,
        },
    );
    let target_quality_summary =
        summarize_smartcore_agreement_target_quality(&target_expansion_result.targets);
    let target_collection_queue = build_agreement_target_collection_queue(&target_quality_summary);
    let mut result = SmartCoreShadowStabilityRunResult {
        run_id: config.run_id.clone(),
        repeated_run_count: config.repeated_run_count,
        samples,
        stability_metrics,
        stability_mismatch_records,
        target_expansion_result,
        target_quality_summary,
        target_collection_queue,
        decision_isolation_guard: SmartCoreShadowStabilityDecisionIsolationRegression {
            shadow_candidate_changed_decision: false,
            shadow_candidate_changed_member_score: false,
            stability_task_used_as_order: false,
            target_collection_task_used_as_order: false,
            agreement_target_used_as_input_feature: false,
            regression_status: SmartCoreShadowStabilityDecisionIsolationRegressionStatus::Preserved,
            violations: Vec::new(),
            paper_only: true,
        },
        owner_debug_summary: None,
        run_status: SmartCoreShadowStabilityRunStatus::Passed,
        warnings: Vec::new(),
        safety_summary: safety_summary(),
        debug_only: true,
        not_investment_signal: true,
        not_committee_opinion: true,
        paper_only: true,
    };
    result.decision_isolation_guard = evaluate_shadow_stability_decision_isolation_regression(
        &result,
        batch_result,
        Some(batch_result),
    );
    if result.stability_metrics.action_flip_rate > config.max_allowed_action_flip_rate {
        result.warnings.push(format!(
            "action_flip_rate={:.4} exceeded allowed {:.4}",
            result.stability_metrics.action_flip_rate, config.max_allowed_action_flip_rate
        ));
    }
    if result.stability_metrics.head_bucket_flip_rate > config.max_allowed_head_flip_rate {
        result.warnings.push(format!(
            "head_bucket_flip_rate={:.4} exceeded allowed {:.4}",
            result.stability_metrics.head_bucket_flip_rate, config.max_allowed_head_flip_rate
        ));
    }
    if result.target_quality_summary.target_quality_status
        != SmartCoreAgreementTargetQualityStatus::Sufficient
    {
        result.warnings.push(format!(
            "target quality is {:?}",
            result.target_quality_summary.target_quality_status
        ));
    }
    if result.decision_isolation_guard.regression_status
        == SmartCoreShadowStabilityDecisionIsolationRegressionStatus::Violated
    {
        result.run_status = SmartCoreShadowStabilityRunStatus::Failed;
    } else if !result.warnings.is_empty() {
        result.run_status = SmartCoreShadowStabilityRunStatus::PassedWithWarnings;
    }
    if let Some(path) = config.output_path.as_ref() {
        write_safe_json(Path::new(path), &result)?;
    }
    Ok(result)
}

fn apply_owner_shadow_stability_debug_update(
    batch_id: &str,
    section: Option<OwnerCoreDebugSection>,
    update: Option<OwnerShadowStabilityDebugSummary>,
) -> Option<OwnerCoreDebugSection> {
    let Some(update) = update else {
        return section;
    };
    if let Some(mut section) = section {
        section.summary = format!(
            "{}; stability_repeats={}, action_flip_rate={:.4}",
            section.summary, update.repeated_run_count, update.action_flip_rate
        );
        section.shadow_stability_summary = Some(update);
        Some(section)
    } else {
        Some(OwnerCoreDebugSection {
            section_id: format!("{batch_id}-owner-core-debug"),
            cards: Vec::new(),
            summary: format!(
                "stability_repeats={}, action_flip_rate={:.4}",
                update.repeated_run_count, update.action_flip_rate
            ),
            paper_only_warning:
                "shadow stability debug summary is paper-only diagnostics; not investment advice, not trading, not orders"
                    .to_string(),
            debug_only_warning:
                "shadow stability summary is read-only diagnostics and must not feed member opinions or committee decisions"
                    .to_string(),
            calibration_summary: None,
            recalibration_summary: None,
            shadow_opinion_summary: None,
            shadow_stability_summary: Some(update),
            shadow_scenario_sweep_summary: None,
            observer_section: None,
            observer_coverage_closure_summary: None,
            observer_trend_summary: None,
            observer_seeded_target_summary: None,
            observer_apply_readiness_summary: None,
            paper_only: true,
        })
    }
}

fn smartcore_shadow_stability_requested_from_flags(
    enabled: bool,
    output_path: Option<&String>,
    expand_agreement_targets: bool,
    target_collection_queue_output_path: Option<&String>,
    _emit_owner_summary: bool,
) -> bool {
    enabled
        || output_path.is_some()
        || expand_agreement_targets
        || target_collection_queue_output_path.is_some()
}

fn maybe_run_smartcore_shadow_stability_for_batch_result(
    run_id: String,
    enabled: bool,
    repeated_run_count: usize,
    output_path: Option<&String>,
    expand_agreement_targets: bool,
    target_collection_queue_output_path: Option<&String>,
    emit_owner_summary: bool,
    calibration_dataset_input_path: Option<&String>,
    batch_result: &mut BatchCommitteeCycleResult,
) -> Result<Option<SmartCoreShadowStabilityRunResult>, String> {
    if !smartcore_shadow_stability_requested_from_flags(
        enabled,
        output_path,
        expand_agreement_targets,
        target_collection_queue_output_path,
        emit_owner_summary,
    ) {
        return Ok(None);
    }
    let shadow_opinion_run_result = batch_result
        .smartcore_shadow_opinion_run_result
        .as_ref()
        .ok_or_else(|| "smartcore shadow stability requires shadow opinion run result".to_string())?
        .clone();
    let generated_dataset = || {
        batch_result
            .smartcore_mismatch_learning_loop_result
            .as_ref()
            .and_then(|result| {
                result
                    .calibration_dataset_refresh_result
                    .as_ref()
                    .map(|refresh| refresh.refreshed_dataset.clone())
            })
            .or_else(|| {
                batch_result
                    .smartcore_mismatch_self_growing_run_result
                    .as_ref()
                    .map(|result| result.core_calibration_dataset.clone())
            })
    };
    let loaded_dataset = if expand_agreement_targets {
        if let Some(path) = calibration_dataset_input_path {
            let path = Path::new(path);
            if path.exists() {
                Some(load_core_calibration_dataset_from_local_json(path)?)
            } else {
                generated_dataset()
            }
        } else {
            generated_dataset()
        }
    } else {
        None
    };
    let evidence_store = if expand_agreement_targets {
        batch_result
            .paper_outcome_evidence_load
            .as_ref()
            .map(|load| load.records.clone())
    } else {
        None
    };
    let mut result = run_smartcore_shadow_stability_eval(
        &shadow_opinion_run_result,
        batch_result,
        Some(&batch_result.replay_dataset),
        loaded_dataset.as_ref(),
        evidence_store.as_deref(),
        &SmartCoreShadowStabilityRunConfig {
            run_id,
            enabled,
            repeated_run_count,
            include_same_input_repeat: true,
            include_calibrated_output_repeat: true,
            include_shadow_candidate_repeat: true,
            include_target_eval_repeat: true,
            max_allowed_action_flip_rate: 0.0,
            max_allowed_head_flip_rate: 0.0,
            output_path: output_path.cloned(),
            paper_only: true,
        },
    )?;
    if let Some(path) = target_collection_queue_output_path {
        write_safe_json(Path::new(path), &result.target_collection_queue)?;
    }
    if emit_owner_summary {
        result.owner_debug_summary = Some(build_owner_shadow_stability_debug_summary(&result));
    }
    if let Some(shadow_alignment_result) =
        batch_result.smartcore_shadow_alignment_run_result.as_mut()
    {
        shadow_alignment_result.owner_core_debug_section =
            apply_owner_shadow_stability_debug_update(
                &batch_result.batch_id,
                shadow_alignment_result.owner_core_debug_section.take(),
                result.owner_debug_summary.clone(),
            );
        shadow_alignment_result.owner_core_debug_card_count = shadow_alignment_result
            .owner_core_debug_section
            .as_ref()
            .map(|section| section.cards.len())
            .unwrap_or(0);
    }
    batch_result.smartcore_shadow_stability_run_result = Some(result.clone());
    Ok(Some(result))
}

fn default_shadow_scenario_symbol(kind: SmartCoreShadowScenarioKind) -> &'static str {
    match kind {
        SmartCoreShadowScenarioKind::Baseline => "AAPL",
        SmartCoreShadowScenarioKind::HighRisk => "NVDA",
        SmartCoreShadowScenarioKind::EvidenceGap => "005930.KS",
        SmartCoreShadowScenarioKind::PositiveTrend => "MSFT",
        SmartCoreShadowScenarioKind::NegativeTrend => "TSLA",
        SmartCoreShadowScenarioKind::NeutralWatchlist => "SPY",
        SmartCoreShadowScenarioKind::RiskVetoCase => "BTC-USD",
        SmartCoreShadowScenarioKind::NeedMoreEvidenceCase => "AMZN",
        SmartCoreShadowScenarioKind::CryptoVolatility => "BTC-USD",
        SmartCoreShadowScenarioKind::UsMarketLongTerm => "QQQ",
        SmartCoreShadowScenarioKind::KoreaShortTerm => "005930.KS",
    }
}

fn default_shadow_scenario_market_scope(kind: SmartCoreShadowScenarioKind) -> MarketScope {
    match kind {
        SmartCoreShadowScenarioKind::EvidenceGap | SmartCoreShadowScenarioKind::KoreaShortTerm => {
            MarketScope::KoreaShortTerm
        }
        SmartCoreShadowScenarioKind::RiskVetoCase
        | SmartCoreShadowScenarioKind::CryptoVolatility => MarketScope::CryptoShortTerm,
        SmartCoreShadowScenarioKind::UsMarketLongTerm
        | SmartCoreShadowScenarioKind::NeutralWatchlist => MarketScope::UsLongTerm,
        _ => MarketScope::UsShortTerm,
    }
}

fn shadow_scenario_family(kind: SmartCoreShadowScenarioKind) -> &'static str {
    match kind {
        SmartCoreShadowScenarioKind::HighRisk
        | SmartCoreShadowScenarioKind::RiskVetoCase
        | SmartCoreShadowScenarioKind::CryptoVolatility => "risk",
        SmartCoreShadowScenarioKind::EvidenceGap
        | SmartCoreShadowScenarioKind::NeedMoreEvidenceCase => "evidence",
        SmartCoreShadowScenarioKind::PositiveTrend | SmartCoreShadowScenarioKind::NegativeTrend => {
            "trend"
        }
        _ => "baseline",
    }
}

fn scenario_stance_for_kind(kind: SmartCoreShadowScenarioKind) -> MemberStance {
    match kind {
        SmartCoreShadowScenarioKind::PositiveTrend
        | SmartCoreShadowScenarioKind::UsMarketLongTerm => MemberStance::BuyProposal,
        SmartCoreShadowScenarioKind::NegativeTrend => MemberStance::NoTrade,
        SmartCoreShadowScenarioKind::EvidenceGap
        | SmartCoreShadowScenarioKind::NeedMoreEvidenceCase => MemberStance::NeedMoreEvidence,
        _ => MemberStance::Hold,
    }
}

fn scenario_outcome_for_kind(kind: SmartCoreShadowScenarioKind) -> MemberExperienceOutcome {
    match kind {
        SmartCoreShadowScenarioKind::PositiveTrend
        | SmartCoreShadowScenarioKind::UsMarketLongTerm => MemberExperienceOutcome::PaperPositive,
        SmartCoreShadowScenarioKind::NegativeTrend
        | SmartCoreShadowScenarioKind::HighRisk
        | SmartCoreShadowScenarioKind::RiskVetoCase
        | SmartCoreShadowScenarioKind::CryptoVolatility => MemberExperienceOutcome::PaperNegative,
        _ => MemberExperienceOutcome::PaperNeutral,
    }
}

fn scenario_confidence_label(kind: SmartCoreShadowScenarioKind) -> MemberLearningLabel {
    match kind {
        SmartCoreShadowScenarioKind::PositiveTrend
        | SmartCoreShadowScenarioKind::UsMarketLongTerm => MemberLearningLabel::Reinforce,
        SmartCoreShadowScenarioKind::EvidenceGap
        | SmartCoreShadowScenarioKind::NeedMoreEvidenceCase => {
            MemberLearningLabel::NeedMoreEvidence
        }
        SmartCoreShadowScenarioKind::HighRisk
        | SmartCoreShadowScenarioKind::RiskVetoCase
        | SmartCoreShadowScenarioKind::CryptoVolatility => MemberLearningLabel::Penalize,
        _ => MemberLearningLabel::Keep,
    }
}

fn scenario_risk_bucket(kind: SmartCoreShadowScenarioKind) -> SmartCoreHeadBucketNormalizedValue {
    match kind {
        SmartCoreShadowScenarioKind::HighRisk
        | SmartCoreShadowScenarioKind::RiskVetoCase
        | SmartCoreShadowScenarioKind::CryptoVolatility => {
            SmartCoreHeadBucketNormalizedValue::RiskHigh
        }
        SmartCoreShadowScenarioKind::NegativeTrend
        | SmartCoreShadowScenarioKind::NeedMoreEvidenceCase
        | SmartCoreShadowScenarioKind::KoreaShortTerm => {
            SmartCoreHeadBucketNormalizedValue::RiskMedium
        }
        _ => SmartCoreHeadBucketNormalizedValue::RiskLow,
    }
}

fn scenario_evidence_bucket(
    kind: SmartCoreShadowScenarioKind,
) -> SmartCoreHeadBucketNormalizedValue {
    match kind {
        SmartCoreShadowScenarioKind::EvidenceGap
        | SmartCoreShadowScenarioKind::NeedMoreEvidenceCase => {
            SmartCoreHeadBucketNormalizedValue::NeedMoreEvidence
        }
        _ => SmartCoreHeadBucketNormalizedValue::EvidenceSufficient,
    }
}

fn scenario_stance_bucket(kind: SmartCoreShadowScenarioKind) -> SmartCoreHeadBucketNormalizedValue {
    match kind {
        SmartCoreShadowScenarioKind::PositiveTrend
        | SmartCoreShadowScenarioKind::UsMarketLongTerm => {
            SmartCoreHeadBucketNormalizedValue::PositiveLike
        }
        SmartCoreShadowScenarioKind::NegativeTrend => {
            SmartCoreHeadBucketNormalizedValue::NegativeLike
        }
        _ => SmartCoreHeadBucketNormalizedValue::NeutralLike,
    }
}

fn scenario_confidence_bucket(
    kind: SmartCoreShadowScenarioKind,
) -> SmartCoreHeadBucketNormalizedValue {
    match kind {
        SmartCoreShadowScenarioKind::PositiveTrend
        | SmartCoreShadowScenarioKind::UsMarketLongTerm => {
            SmartCoreHeadBucketNormalizedValue::ConfidenceHigh
        }
        SmartCoreShadowScenarioKind::EvidenceGap
        | SmartCoreShadowScenarioKind::NeedMoreEvidenceCase => {
            SmartCoreHeadBucketNormalizedValue::ConfidenceLow
        }
        _ => SmartCoreHeadBucketNormalizedValue::ConfidenceMedium,
    }
}

fn build_default_shadow_scenario(
    scenario_id: &str,
    scenario_kind: SmartCoreShadowScenarioKind,
    expected_target_coverage: SmartCoreShadowScenarioTargetCoverageExpectation,
) -> SmartCoreShadowScenario {
    SmartCoreShadowScenario {
        scenario_id: scenario_id.to_string(),
        scenario_kind,
        symbol: Some(default_shadow_scenario_symbol(scenario_kind).to_string()),
        market_scope: Some(default_shadow_scenario_market_scope(scenario_kind)),
        market_data_path: None,
        news_fixture_path: None,
        replay_dataset_path: None,
        calibration_dataset_path: None,
        expected_target_coverage,
        paper_only: true,
    }
}

pub fn build_default_shadow_scenario_set() -> SmartCoreShadowScenarioSet {
    let scenarios = vec![
        build_default_shadow_scenario(
            "baseline",
            SmartCoreShadowScenarioKind::Baseline,
            SmartCoreShadowScenarioTargetCoverageExpectation::High,
        ),
        build_default_shadow_scenario(
            "high-risk",
            SmartCoreShadowScenarioKind::HighRisk,
            SmartCoreShadowScenarioTargetCoverageExpectation::Medium,
        ),
        build_default_shadow_scenario(
            "evidence-gap",
            SmartCoreShadowScenarioKind::EvidenceGap,
            SmartCoreShadowScenarioTargetCoverageExpectation::Low,
        ),
        build_default_shadow_scenario(
            "positive-trend",
            SmartCoreShadowScenarioKind::PositiveTrend,
            SmartCoreShadowScenarioTargetCoverageExpectation::High,
        ),
        build_default_shadow_scenario(
            "neutral-watchlist",
            SmartCoreShadowScenarioKind::NeutralWatchlist,
            SmartCoreShadowScenarioTargetCoverageExpectation::Low,
        ),
    ];
    SmartCoreShadowScenarioSet {
        scenario_set_id: "smartcore-shadow-scenarios-default".to_string(),
        scenario_count: scenarios.len(),
        scenarios,
        paper_only: true,
    }
}

pub fn validate_shadow_scenario_set(set: &SmartCoreShadowScenarioSet) -> Result<(), String> {
    if !set.paper_only {
        return Err("smartcore shadow scenario set must stay paper_only".to_string());
    }
    if set.scenarios.is_empty() {
        return Err("smartcore shadow scenario set requires at least one scenario".to_string());
    }
    if set.scenario_count != set.scenarios.len() {
        return Err("smartcore shadow scenario set scenario_count mismatch".to_string());
    }
    let mut seen = std::collections::BTreeSet::new();
    for scenario in &set.scenarios {
        if !scenario.paper_only {
            return Err(format!(
                "smartcore shadow scenario {} must stay paper_only",
                scenario.scenario_id
            ));
        }
        if scenario.scenario_id.trim().is_empty() {
            return Err("smartcore shadow scenario requires non-empty scenario_id".to_string());
        }
        if !seen.insert(scenario.scenario_id.clone()) {
            return Err(format!(
                "smartcore shadow scenario_set contains duplicate scenario_id={}",
                scenario.scenario_id
            ));
        }
        for (path, label) in [
            (
                scenario.market_data_path.as_ref(),
                "smartcore shadow scenario market_data_path",
            ),
            (
                scenario.news_fixture_path.as_ref(),
                "smartcore shadow scenario news_fixture_path",
            ),
            (
                scenario.replay_dataset_path.as_ref(),
                "smartcore shadow scenario replay_dataset_path",
            ),
            (
                scenario.calibration_dataset_path.as_ref(),
                "smartcore shadow scenario calibration_dataset_path",
            ),
        ] {
            if let Some(path) = path {
                validate_local_json_path(Path::new(path), label)?;
            }
        }
    }
    Ok(())
}

pub fn load_shadow_scenario_set_from_local_json(
    path: &Path,
) -> Result<SmartCoreShadowScenarioSet, String> {
    validate_local_json_path(path, "smartcore shadow scenario set path")?;
    let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
    reject_unsafe_offline_batch_text(&text)
        .map_err(|err| format!("smartcore shadow scenario set rejected unsafe content: {err}"))?;
    let set: SmartCoreShadowScenarioSet =
        serde_json::from_str(&text).map_err(|err| err.to_string())?;
    validate_shadow_scenario_set(&set)?;
    Ok(set)
}

fn scenario_market_summary(
    scenario: &SmartCoreShadowScenario,
    base_summary: &str,
) -> Result<String, String> {
    if let Some(path) = scenario.market_data_path.as_ref() {
        let items = load_market_data_from_local_json(Path::new(path))?;
        let avg_change = if items.is_empty() {
            0.0
        } else {
            items.iter().map(|item| item.change_pct).sum::<f64>() / items.len() as f64
        };
        let avg_volatility = if items.is_empty() {
            0.0
        } else {
            items.iter().map(|item| item.volatility_hint).sum::<f64>() / items.len() as f64
        };
        Ok(format!(
            "scenario={:?}; snapshots={}; avg_change_pct={avg_change:.4}; avg_volatility={avg_volatility:.4}",
            scenario.scenario_kind,
            items.len(),
        ))
    } else {
        Ok(format!(
            "{base_summary}; scenario={:?}; target_coverage={:?}",
            scenario.scenario_kind, scenario.expected_target_coverage
        ))
    }
}

fn scenario_news_summary(
    scenario: &SmartCoreShadowScenario,
    base_summary: &str,
) -> Result<String, String> {
    if let Some(path) = scenario.news_fixture_path.as_ref() {
        let items = load_news_from_local_json(Path::new(path))?;
        let positive = items
            .iter()
            .filter(|item| item.sentiment_hint.eq_ignore_ascii_case("positive"))
            .count();
        let negative = items
            .iter()
            .filter(|item| item.sentiment_hint.eq_ignore_ascii_case("negative"))
            .count();
        Ok(format!(
            "scenario={:?}; news_items={}; positive={positive}; negative={negative}",
            scenario.scenario_kind,
            items.len()
        ))
    } else {
        Ok(format!(
            "{base_summary}; scenario={:?}",
            scenario.scenario_kind
        ))
    }
}

fn build_shadow_scenario_replay_dataset(
    base_dataset: &ReplayDataset,
    scenario: &SmartCoreShadowScenario,
) -> Result<ReplayDataset, String> {
    let mut dataset = if let Some(path) = scenario.replay_dataset_path.as_ref() {
        ReplayDataset::load_from_local_json(Path::new(path))?
    } else {
        base_dataset.clone()
    };
    if dataset.examples.is_empty() {
        return Err(format!(
            "smartcore shadow scenario {} requires replay examples",
            scenario.scenario_id
        ));
    }
    let symbol = scenario
        .symbol
        .clone()
        .unwrap_or_else(|| default_shadow_scenario_symbol(scenario.scenario_kind).to_string());
    let market_scope = scenario
        .market_scope
        .unwrap_or_else(|| default_shadow_scenario_market_scope(scenario.scenario_kind));
    for example in &mut dataset.examples {
        example.symbol = symbol.clone();
        example.market_scope = market_scope;
        example.input_features.market_data_summary =
            scenario_market_summary(scenario, &example.input_features.market_data_summary)?;
        example.input_features.news_summary =
            scenario_news_summary(scenario, &example.input_features.news_summary)?;
        example.target.stance = scenario_stance_for_kind(scenario.scenario_kind);
        example.target.risk_label = format!("{:?}", scenario_risk_bucket(scenario.scenario_kind));
        example.target.evidence_label =
            format!("{:?}", scenario_evidence_bucket(scenario.scenario_kind));
        example.target.confidence_calibration = scenario_confidence_label(scenario.scenario_kind);
        example.target.outcome_label = scenario_outcome_for_kind(scenario.scenario_kind);
        example.paper_only = true;
    }
    dataset.dataset_id = format!("{}-scenario-{}", dataset.dataset_id, scenario.scenario_id);
    dataset.example_count = dataset.examples.len();
    dataset.member_count = dataset
        .examples
        .iter()
        .map(|example| example.member_id.clone())
        .collect::<std::collections::BTreeSet<_>>()
        .len();
    dataset.paper_only = true;
    Ok(dataset)
}

fn apply_scenario_bucket(
    output: &mut CalibratedSmartCoreDebugOutputV0,
    scenario_id: &str,
    head: SmartCoreShadowHeadKind,
    value: SmartCoreHeadBucketNormalizedValue,
) {
    let label = normalized_bucket_label(value);
    if let Some(entry) = output
        .calibrated_heads
        .iter_mut()
        .find(|candidate| candidate.head == head)
    {
        let changed = entry.calibrated_bucket != label;
        entry.calibrated_bucket = label;
        entry.changed = changed;
        entry.calibration_action = SmartCoreCalibrationRuleActionV0::MapBucket;
        entry.applied_rule_id = Some(format!("shadow-scenario-{scenario_id}-{head:?}"));
        entry.rule_confidence = ReplayLabelConfidence::ReviewRequired;
    } else {
        output
            .calibrated_heads
            .push(CalibratedSmartCoreHeadOutputV0 {
                member_id: output.member_id.clone(),
                head,
                original_bucket: label.clone(),
                calibrated_bucket: label,
                calibration_action: SmartCoreCalibrationRuleActionV0::MapBucket,
                applied_rule_id: Some(format!("shadow-scenario-{scenario_id}-{head:?}")),
                rule_confidence: ReplayLabelConfidence::ReviewRequired,
                changed: true,
                debug_only: true,
                not_investment_signal: true,
                not_committee_opinion: true,
                paper_only: true,
            });
    }
}

fn apply_shadow_scenario_to_calibrated_debug_batch(
    batch: &CalibratedSmartCoreDebugOutputBatchV0,
    scenario: &SmartCoreShadowScenario,
) -> CalibratedSmartCoreDebugOutputBatchV0 {
    let mut scenario_batch = batch.clone();
    scenario_batch.batch_id = format!("{}-scenario-{}", batch.batch_id, scenario.scenario_id);
    scenario_batch.changed_output_count = 0;
    for output in &mut scenario_batch.member_outputs {
        apply_scenario_bucket(
            output,
            &scenario.scenario_id,
            SmartCoreShadowHeadKind::Stance,
            scenario_stance_bucket(scenario.scenario_kind),
        );
        apply_scenario_bucket(
            output,
            &scenario.scenario_id,
            SmartCoreShadowHeadKind::Risk,
            scenario_risk_bucket(scenario.scenario_kind),
        );
        apply_scenario_bucket(
            output,
            &scenario.scenario_id,
            SmartCoreShadowHeadKind::EvidenceNeed,
            scenario_evidence_bucket(scenario.scenario_kind),
        );
        apply_scenario_bucket(
            output,
            &scenario.scenario_id,
            SmartCoreShadowHeadKind::ConfidenceCalibration,
            scenario_confidence_bucket(scenario.scenario_kind),
        );
        apply_scenario_bucket(
            output,
            &scenario.scenario_id,
            SmartCoreShadowHeadKind::Uncertainty,
            match scenario_confidence_bucket(scenario.scenario_kind) {
                SmartCoreHeadBucketNormalizedValue::ConfidenceHigh => {
                    SmartCoreHeadBucketNormalizedValue::ConfidenceLow
                }
                SmartCoreHeadBucketNormalizedValue::ConfidenceLow => {
                    SmartCoreHeadBucketNormalizedValue::ConfidenceHigh
                }
                _ => SmartCoreHeadBucketNormalizedValue::ConfidenceMedium,
            },
        );
        output.changed_head_count = output
            .calibrated_heads
            .iter()
            .filter(|head| head.changed)
            .count();
        output.applied_rule_count = output.changed_head_count;
        output.calibration_summary = format!(
            "scenario {:?} overlay applied; changed_head_count={}",
            scenario.scenario_kind, output.changed_head_count
        );
        if output.changed_head_count > 0 {
            scenario_batch.changed_output_count += 1;
        }
    }
    scenario_batch.output_count = scenario_batch.member_outputs.len();
    scenario_batch
}

fn target_expansion_result_with_replaced_targets(
    expansion: &SmartCoreAgreementTargetExpansionResult,
    targets: Vec<SmartCoreShadowAlignmentTarget>,
) -> SmartCoreAgreementTargetExpansionResult {
    let target_distribution_by_member =
        targets
            .iter()
            .fold(std::collections::BTreeMap::new(), |mut map, target| {
                *map.entry(target.member_id.clone()).or_insert(0usize) += 1;
                map
            });
    let target_distribution_by_source =
        targets
            .iter()
            .fold(std::collections::BTreeMap::new(), |mut map, target| {
                *map.entry(format!("{:?}", target.source_type))
                    .or_insert(0usize) += 1;
                map
            });
    let target_distribution_by_head =
        targets
            .iter()
            .fold(std::collections::BTreeMap::new(), |mut map, target| {
                if target.stance_target.is_some() {
                    *map.entry("stance".to_string()).or_insert(0usize) += 1;
                }
                if target.risk_target.is_some() {
                    *map.entry("risk".to_string()).or_insert(0usize) += 1;
                }
                if target.evidence_target.is_some() {
                    *map.entry("evidence".to_string()).or_insert(0usize) += 1;
                }
                if target.confidence_target.is_some() {
                    *map.entry("confidence".to_string()).or_insert(0usize) += 1;
                }
                map
            });
    let added_target_count = targets
        .len()
        .saturating_sub(expansion.previous_target_count);
    SmartCoreAgreementTargetExpansionResult {
        previous_target_count: expansion.previous_target_count,
        added_target_count,
        duplicate_target_count: expansion.duplicate_target_count,
        new_target_count: targets.len(),
        targets,
        target_distribution_by_member,
        target_distribution_by_source,
        target_distribution_by_head,
        expansion_status: if added_target_count > 0 {
            SmartCoreAgreementTargetExpansionStatus::ExpandedWithWarnings
        } else {
            SmartCoreAgreementTargetExpansionStatus::NoChange
        },
        paper_only: true,
    }
}

fn stress_shadow_targets_for_scenario(
    expansion: &SmartCoreAgreementTargetExpansionResult,
    scenario: &SmartCoreShadowScenario,
) -> SmartCoreAgreementTargetExpansionResult {
    if scenario.expected_target_coverage != SmartCoreShadowScenarioTargetCoverageExpectation::Low {
        return expansion.clone();
    }
    let mut seen_members = std::collections::BTreeSet::new();
    let stressed_targets = expansion
        .targets
        .iter()
        .filter_map(|target| {
            if !seen_members.insert(target.member_id.clone()) {
                return None;
            }
            let mut stressed = target.clone();
            stressed.target_id = format!("{}-thin-{}", scenario.scenario_id, stressed.target_id);
            stressed.risk_target = None;
            stressed.evidence_target = None;
            stressed.confidence_target = None;
            stressed.outcome_target = None;
            if stressed.stance_target.is_none() {
                stressed.stance_target = Some(SmartCoreHeadBucketNormalizedValue::NeutralLike);
            }
            Some(stressed)
        })
        .collect::<Vec<_>>();
    target_expansion_result_with_replaced_targets(expansion, stressed_targets)
}

fn scenario_action_signature(
    samples: &[SmartCoreShadowStabilitySample],
) -> std::collections::BTreeMap<String, SmartCoreShadowOpinionAction> {
    let mut signature = std::collections::BTreeMap::new();
    let mut ordered = samples.iter().collect::<Vec<_>>();
    ordered.sort_by(|left, right| {
        left.member_id
            .cmp(&right.member_id)
            .then_with(|| left.repeat_index.cmp(&right.repeat_index))
    });
    for sample in ordered {
        signature
            .entry(sample.member_id.clone())
            .or_insert(sample.shadow_action);
    }
    signature
}

fn scenario_head_signature(
    samples: &[SmartCoreShadowStabilitySample],
) -> std::collections::BTreeMap<String, String> {
    let mut signature = std::collections::BTreeMap::new();
    let mut ordered = samples.iter().collect::<Vec<_>>();
    ordered.sort_by(|left, right| {
        left.member_id
            .cmp(&right.member_id)
            .then_with(|| left.repeat_index.cmp(&right.repeat_index))
    });
    for sample in ordered {
        signature
            .entry(sample.member_id.clone())
            .or_insert_with(|| {
                format!(
                    "{}|{}|{}|{}|{}",
                    sample
                        .stance_bucket
                        .clone()
                        .unwrap_or_else(|| "Unknown".to_string()),
                    sample
                        .risk_bucket
                        .clone()
                        .unwrap_or_else(|| "Unknown".to_string()),
                    sample
                        .evidence_bucket
                        .clone()
                        .unwrap_or_else(|| "Unknown".to_string()),
                    sample
                        .confidence_bucket
                        .clone()
                        .unwrap_or_else(|| "Unknown".to_string()),
                    sample
                        .uncertainty_bucket
                        .clone()
                        .unwrap_or_else(|| "Unknown".to_string()),
                )
            });
    }
    signature
}

pub fn run_shadow_stability_for_scenario(
    scenario: &SmartCoreShadowScenario,
    calibrated_debug_batch: &CalibratedSmartCoreDebugOutputBatchV0,
    batch_result: &BatchCommitteeCycleResult,
    replay_dataset: &ReplayDataset,
    calibration_dataset: Option<&CoreCalibrationDataset>,
    evidence_store: Option<&[PaperOutcomeEvidenceRecord]>,
    config: &SmartCoreShadowScenarioSweepConfig,
) -> Result<SmartCoreShadowScenarioStabilityResult, String> {
    let scenario_replay_dataset = build_shadow_scenario_replay_dataset(replay_dataset, scenario)?;
    let scenario_calibration_dataset =
        if let Some(path) = scenario.calibration_dataset_path.as_ref() {
            Some(load_core_calibration_dataset_from_local_json(Path::new(
                path,
            ))?)
        } else {
            calibration_dataset.cloned()
        };
    let scenario_debug_batch =
        apply_shadow_scenario_to_calibrated_debug_batch(calibrated_debug_batch, scenario);
    let shadow_opinion_run = run_smartcore_shadow_opinion_lane(
        &scenario_debug_batch,
        batch_result,
        Some(&scenario_replay_dataset),
        &SmartCoreShadowOpinionRunConfig {
            run_id: format!("{}-{}-shadow-opinion", config.run_id, scenario.scenario_id),
            enabled: true,
            output_path: None,
            include_member_opinion_comparison: true,
            include_target_eval: true,
            emit_owner_debug_summary: false,
            paper_only: true,
        },
    )?;
    let mut stability_run = run_smartcore_shadow_stability_eval(
        &shadow_opinion_run,
        batch_result,
        Some(&scenario_replay_dataset),
        scenario_calibration_dataset.as_ref(),
        evidence_store,
        &SmartCoreShadowStabilityRunConfig {
            run_id: format!("{}-{}-stability", config.run_id, scenario.scenario_id),
            enabled: true,
            repeated_run_count: config.repeated_run_count,
            include_same_input_repeat: config.include_same_input_determinism,
            include_calibrated_output_repeat: true,
            include_shadow_candidate_repeat: true,
            include_target_eval_repeat: true,
            max_allowed_action_flip_rate: 0.0,
            max_allowed_head_flip_rate: 0.0,
            output_path: None,
            paper_only: true,
        },
    )?;
    if config.expand_targets_per_scenario {
        stability_run.target_expansion_result =
            stress_shadow_targets_for_scenario(&stability_run.target_expansion_result, scenario);
        stability_run.target_quality_summary = summarize_smartcore_agreement_target_quality(
            &stability_run.target_expansion_result.targets,
        );
        stability_run.target_collection_queue =
            build_agreement_target_collection_queue(&stability_run.target_quality_summary);
        if stability_run.target_quality_summary.target_quality_status
            != SmartCoreAgreementTargetQualityStatus::Sufficient
            && !stability_run
                .warnings
                .iter()
                .any(|warning| warning.contains("target quality"))
        {
            stability_run.warnings.push(format!(
                "target quality is {:?}",
                stability_run.target_quality_summary.target_quality_status
            ));
            if stability_run.run_status == SmartCoreShadowStabilityRunStatus::Passed {
                stability_run.run_status = SmartCoreShadowStabilityRunStatus::PassedWithWarnings;
            }
        }
    }
    Ok(SmartCoreShadowScenarioStabilityResult {
        scenario_id: scenario.scenario_id.clone(),
        scenario_kind: scenario.scenario_kind,
        repeated_run_count: stability_run.repeated_run_count,
        sample_count: stability_run.samples.len(),
        action_flip_rate: stability_run.stability_metrics.action_flip_rate,
        head_bucket_flip_rate: stability_run.stability_metrics.head_bucket_flip_rate,
        deterministic_status: stability_run.stability_metrics.deterministic_status,
        target_count_before: stability_run.target_expansion_result.previous_target_count,
        target_count_after: stability_run.target_expansion_result.new_target_count,
        target_quality_status: stability_run.target_quality_summary.target_quality_status,
        mismatch_count_before: Some(shadow_opinion_run.target_eval_summary.mismatch_count),
        mismatch_count_after: Some(stability_run.stability_mismatch_records.len()),
        decision_isolation_status: stability_run.decision_isolation_guard.regression_status,
        action_signature: scenario_action_signature(&stability_run.samples),
        head_signature: scenario_head_signature(&stability_run.samples),
        target_collection_tasks: stability_run.target_collection_queue.tasks.clone(),
        decision_isolation_violations: stability_run.decision_isolation_guard.violations.clone(),
        paper_only: true,
    })
}

fn split_head_signature(signature: &str) -> [String; 5] {
    let mut parts = signature
        .split('|')
        .map(ToString::to_string)
        .collect::<Vec<_>>();
    parts.resize(5, "Unknown".to_string());
    [
        parts[0].clone(),
        parts[1].clone(),
        parts[2].clone(),
        parts[3].clone(),
        parts[4].clone(),
    ]
}

pub fn compute_cross_scenario_sensitivity(
    results: &[SmartCoreShadowScenarioStabilityResult],
) -> SmartCoreCrossScenarioSensitivityMetrics {
    let scenario_count = results.len();
    let member_ids = results
        .iter()
        .flat_map(|result| result.action_signature.keys().cloned())
        .collect::<std::collections::BTreeSet<_>>();
    if scenario_count < 2 {
        return SmartCoreCrossScenarioSensitivityMetrics {
            scenario_count,
            member_count: member_ids.len(),
            action_variation_count: 0,
            head_variation_count: 0,
            expected_variation_count: 0,
            suspicious_variation_count: 0,
            per_member_variation: std::collections::BTreeMap::new(),
            per_head_variation: std::collections::BTreeMap::new(),
            sensitivity_status: SmartCoreCrossScenarioSensitivityStatus::InsufficientScenarios,
            paper_only: true,
        };
    }
    let baseline = &results[0];
    let mut action_variation_count = 0usize;
    let mut head_variation_count = 0usize;
    let mut expected_variation_count = 0usize;
    let mut suspicious_variation_count = 0usize;
    let mut per_member_variation = std::collections::BTreeMap::new();
    let mut per_head_variation = std::collections::BTreeMap::new();
    let mut family_reference: std::collections::BTreeMap<
        &'static str,
        &SmartCoreShadowScenarioStabilityResult,
    > = std::collections::BTreeMap::new();
    for result in results {
        family_reference
            .entry(shadow_scenario_family(result.scenario_kind))
            .or_insert(result);
    }
    for result in results.iter().skip(1) {
        if result.action_signature != baseline.action_signature {
            action_variation_count += 1;
        }
        if result.head_signature != baseline.head_signature {
            head_variation_count += 1;
        }
        for member_id in &member_ids {
            if result.action_signature.get(member_id) != baseline.action_signature.get(member_id) {
                *per_member_variation
                    .entry(member_id.clone())
                    .or_insert(0usize) += 1;
            }
            let baseline_heads = baseline
                .head_signature
                .get(member_id)
                .cloned()
                .unwrap_or_else(|| "Unknown|Unknown|Unknown|Unknown|Unknown".to_string());
            let result_heads = result
                .head_signature
                .get(member_id)
                .cloned()
                .unwrap_or_else(|| "Unknown|Unknown|Unknown|Unknown|Unknown".to_string());
            let baseline_parts = split_head_signature(&baseline_heads);
            let result_parts = split_head_signature(&result_heads);
            for (head, (before, after)) in [
                ("stance", (&baseline_parts[0], &result_parts[0])),
                ("risk", (&baseline_parts[1], &result_parts[1])),
                ("evidence", (&baseline_parts[2], &result_parts[2])),
                ("confidence", (&baseline_parts[3], &result_parts[3])),
                ("uncertainty", (&baseline_parts[4], &result_parts[4])),
            ] {
                if before != after {
                    *per_head_variation.entry(head.to_string()).or_insert(0usize) += 1;
                }
            }
        }
        let family = shadow_scenario_family(result.scenario_kind);
        if let Some(reference) = family_reference.get(family) {
            let same_family_changed = reference.scenario_id != result.scenario_id
                && (reference.action_signature != result.action_signature
                    || reference.head_signature != result.head_signature);
            if same_family_changed {
                suspicious_variation_count += 1;
            } else if baseline.action_signature != result.action_signature
                || baseline.head_signature != result.head_signature
            {
                expected_variation_count += 1;
            }
        }
    }
    let sensitivity_status = if action_variation_count == 0 && head_variation_count == 0 {
        SmartCoreCrossScenarioSensitivityStatus::TooStatic
    } else if suspicious_variation_count > 0
        || results.iter().any(|result| {
            result.deterministic_status == SmartCoreShadowStabilityDeterministicStatus::Unstable
        })
    {
        SmartCoreCrossScenarioSensitivityStatus::TooUnstable
    } else {
        SmartCoreCrossScenarioSensitivityStatus::ReasonableSensitivity
    };
    SmartCoreCrossScenarioSensitivityMetrics {
        scenario_count,
        member_count: member_ids.len(),
        action_variation_count,
        head_variation_count,
        expected_variation_count,
        suspicious_variation_count,
        per_member_variation,
        per_head_variation,
        sensitivity_status,
        paper_only: true,
    }
}

pub fn run_smartcore_target_coverage_stress_test(
    scenario_results: &[SmartCoreShadowScenarioStabilityResult],
) -> SmartCoreTargetCoverageStressResult {
    let mut scenarios_with_sufficient_targets = 0usize;
    let mut scenarios_with_thin_targets = 0usize;
    let mut member_coverage_failures = 0usize;
    let mut head_coverage_failures = 0usize;
    let mut source_coverage_failures = 0usize;
    let mut target_quality_by_scenario = std::collections::BTreeMap::new();
    let mut task_keys = std::collections::BTreeSet::new();
    let mut recommended_target_collection_tasks = Vec::new();
    for result in scenario_results {
        target_quality_by_scenario.insert(result.scenario_id.clone(), result.target_quality_status);
        match result.target_quality_status {
            SmartCoreAgreementTargetQualityStatus::Sufficient => {
                scenarios_with_sufficient_targets += 1;
            }
            SmartCoreAgreementTargetQualityStatus::ThinMemberCoverage => {
                scenarios_with_thin_targets += 1;
                member_coverage_failures += 1;
            }
            SmartCoreAgreementTargetQualityStatus::ThinHeadCoverage => {
                scenarios_with_thin_targets += 1;
                head_coverage_failures += 1;
            }
            SmartCoreAgreementTargetQualityStatus::NeedsMoreTargets => {
                scenarios_with_thin_targets += 1;
                member_coverage_failures += 1;
                head_coverage_failures += 1;
            }
            SmartCoreAgreementTargetQualityStatus::Unsafe => {
                scenarios_with_thin_targets += 1;
                source_coverage_failures += 1;
            }
        }
        for task in &result.target_collection_tasks {
            if task.target_need == SmartCoreAgreementTargetNeed::PaperOutcomeTarget {
                source_coverage_failures += 1;
            }
            let key = format!(
                "{}-{:?}-{:?}",
                result.scenario_id, task.target_need, task.head
            );
            if task_keys.insert(key) {
                let mut cloned = task.clone();
                cloned.task_id = format!("{}-{}", result.scenario_id, cloned.task_id);
                recommended_target_collection_tasks.push(cloned);
            }
        }
    }
    recommended_target_collection_tasks.sort_by(|left, right| left.task_id.cmp(&right.task_id));
    let target_coverage_status = if scenario_results.is_empty() {
        SmartCoreTargetCoverageStatus::Insufficient
    } else if scenarios_with_thin_targets == 0 {
        SmartCoreTargetCoverageStatus::Sufficient
    } else if scenarios_with_sufficient_targets > 0 {
        SmartCoreTargetCoverageStatus::SufficientWithWarnings
    } else {
        SmartCoreTargetCoverageStatus::ThinCoverage
    };
    SmartCoreTargetCoverageStressResult {
        scenario_count: scenario_results.len(),
        scenarios_with_sufficient_targets,
        scenarios_with_thin_targets,
        member_coverage_failures,
        head_coverage_failures,
        source_coverage_failures,
        target_quality_by_scenario,
        target_coverage_status,
        recommended_target_collection_tasks,
        paper_only: true,
    }
}

fn evaluate_multi_scenario_decision_isolation_regression_from_results(
    scenario_results: &[SmartCoreShadowScenarioStabilityResult],
) -> SmartCoreMultiScenarioDecisionIsolationRegression {
    let scenario_decision_mutation_detected = scenario_results.iter().any(|result| {
        result
            .decision_isolation_violations
            .iter()
            .any(|violation| violation.contains("decision"))
    });
    let scenario_member_score_mutation_detected = scenario_results.iter().any(|result| {
        result
            .decision_isolation_violations
            .iter()
            .any(|violation| violation.contains("member score"))
    });
    let target_leakage_detected = scenario_results.iter().any(|result| {
        result
            .decision_isolation_violations
            .iter()
            .any(|violation| violation.contains("input features"))
    });
    let shadow_output_used_as_order = scenario_results.iter().any(|result| {
        result
            .decision_isolation_violations
            .iter()
            .any(|violation| violation.contains("order path"))
    });
    let violations = scenario_results
        .iter()
        .flat_map(|result| {
            result
                .decision_isolation_violations
                .iter()
                .map(move |violation| format!("{}: {violation}", result.scenario_id))
        })
        .collect::<Vec<_>>();
    SmartCoreMultiScenarioDecisionIsolationRegression {
        scenario_count: scenario_results.len(),
        scenario_decision_mutation_detected,
        scenario_member_score_mutation_detected,
        target_leakage_detected,
        shadow_output_used_as_order,
        regression_status: if violations.is_empty() {
            SmartCoreMultiScenarioDecisionIsolationRegressionStatus::Preserved
        } else {
            SmartCoreMultiScenarioDecisionIsolationRegressionStatus::Violated
        },
        violations,
        paper_only: true,
    }
}

pub fn evaluate_multi_scenario_decision_isolation_regression(
    sweep_result: &SmartCoreShadowScenarioSweepResult,
) -> SmartCoreMultiScenarioDecisionIsolationRegression {
    evaluate_multi_scenario_decision_isolation_regression_from_results(
        &sweep_result.scenario_results,
    )
}

pub fn evaluate_smartcore_observer_readiness(
    sweep_result: &SmartCoreShadowScenarioSweepResult,
    policy: &SmartCoreObserverReadinessPolicy,
) -> SmartCoreObserverReadinessGate {
    let same_input_determinism_status = if sweep_result.scenario_results.iter().any(|result| {
        result.deterministic_status == SmartCoreShadowStabilityDeterministicStatus::Unstable
    }) {
        SmartCoreShadowStabilityDeterministicStatus::Unstable
    } else if sweep_result.scenario_results.iter().any(|result| {
        result.deterministic_status
            == SmartCoreShadowStabilityDeterministicStatus::StableWithWarnings
    }) {
        SmartCoreShadowStabilityDeterministicStatus::StableWithWarnings
    } else {
        SmartCoreShadowStabilityDeterministicStatus::Deterministic
    };
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    let mut observer_status = SmartCoreObserverStatus::ObserverLaneAllowed;
    let mut observer_lane_allowed = true;
    if sweep_result.scenario_results.len() < policy.min_scenarios_required
        || matches!(
            sweep_result.cross_scenario_sensitivity.sensitivity_status,
            SmartCoreCrossScenarioSensitivityStatus::InsufficientScenarios
                | SmartCoreCrossScenarioSensitivityStatus::TooStatic
        )
    {
        blockers.push("Need more local paper scenarios before observer readiness.".to_string());
        observer_status = SmartCoreObserverStatus::NeedsMoreScenarios;
        observer_lane_allowed = false;
    }
    if policy.require_zero_same_input_flip_rate
        && same_input_determinism_status
            != SmartCoreShadowStabilityDeterministicStatus::Deterministic
    {
        blockers.push("Same-input determinism is not clean enough.".to_string());
        observer_status = SmartCoreObserverStatus::BlockedByInstability;
        observer_lane_allowed = false;
    }
    if policy.allow_reasonable_cross_scenario_variation
        && sweep_result.cross_scenario_sensitivity.sensitivity_status
            == SmartCoreCrossScenarioSensitivityStatus::TooUnstable
    {
        blockers.push("Cross-scenario variation looks too unstable.".to_string());
        observer_status = SmartCoreObserverStatus::BlockedByInstability;
        observer_lane_allowed = false;
    }
    if matches!(
        sweep_result.target_coverage_stress.target_coverage_status,
        SmartCoreTargetCoverageStatus::ThinCoverage | SmartCoreTargetCoverageStatus::Insufficient
    ) {
        blockers.push("Target coverage is too thin for observer readiness.".to_string());
        observer_status = SmartCoreObserverStatus::NeedsMoreTargets;
        observer_lane_allowed = false;
    }
    if policy.require_decision_isolation
        && sweep_result.decision_isolation_regression.regression_status
            == SmartCoreMultiScenarioDecisionIsolationRegressionStatus::Violated
    {
        blockers.push("Decision isolation regression detected a leak.".to_string());
        observer_status = SmartCoreObserverStatus::BlockedByDecisionLeak;
        observer_lane_allowed = false;
    }
    if !policy.paper_only {
        blockers.push("Observer readiness policy must remain paper_only.".to_string());
        observer_status = SmartCoreObserverStatus::BlockedBySafety;
        observer_lane_allowed = false;
    }
    if observer_lane_allowed {
        if same_input_determinism_status
            == SmartCoreShadowStabilityDeterministicStatus::StableWithWarnings
            || sweep_result.target_coverage_stress.target_coverage_status
                == SmartCoreTargetCoverageStatus::SufficientWithWarnings
        {
            warnings.push(
                "Observer lane is still debug-only and needs more paper coverage.".to_string(),
            );
            observer_status = SmartCoreObserverStatus::ObserverLaneAllowedWithWarnings;
        }
    }
    SmartCoreObserverReadinessGate {
        gate_id: format!("{}-observer-readiness", sweep_result.run_id),
        same_input_determinism_status,
        cross_scenario_sensitivity_status: sweep_result
            .cross_scenario_sensitivity
            .sensitivity_status,
        target_coverage_status: sweep_result.target_coverage_stress.target_coverage_status,
        decision_isolation_status: sweep_result.decision_isolation_regression.regression_status,
        min_scenarios_required: policy.min_scenarios_required,
        actual_scenarios: sweep_result.scenario_results.len(),
        observer_lane_allowed,
        observer_status,
        blockers,
        warnings,
        paper_only: true,
    }
}

pub fn build_owner_shadow_scenario_sweep_debug_summary(
    sweep_result: &SmartCoreShadowScenarioSweepResult,
    observer_gate: &SmartCoreObserverReadinessGate,
) -> OwnerShadowScenarioSweepDebugSummary {
    OwnerShadowScenarioSweepDebugSummary {
        summary_id: format!("{}-owner-shadow-scenario-sweep", sweep_result.run_id),
        scenario_count: sweep_result.scenario_results.len(),
        deterministic_scenario_count: sweep_result.deterministic_scenario_count,
        unstable_scenario_count: sweep_result.unstable_scenario_count,
        target_coverage_status: sweep_result.target_coverage_stress.target_coverage_status,
        sensitivity_status: sweep_result.cross_scenario_sensitivity.sensitivity_status,
        observer_status: observer_gate.observer_status,
        message: "SmartCore shadow candidates were tested across scenarios. This remains observer/debug-only. No committee decision or trading path used these outputs.".to_string(),
        debug_only: true,
        not_investment_signal: true,
        not_committee_opinion: true,
        paper_only: true,
    }
}

fn apply_owner_shadow_scenario_sweep_debug_update(
    batch_id: &str,
    section: Option<OwnerCoreDebugSection>,
    update: Option<OwnerShadowScenarioSweepDebugSummary>,
) -> Option<OwnerCoreDebugSection> {
    let Some(update) = update else {
        return section;
    };
    if let Some(mut section) = section {
        section.summary = format!(
            "{}; scenario_count={}, observer_status={:?}",
            section.summary, update.scenario_count, update.observer_status
        );
        section.shadow_scenario_sweep_summary = Some(update);
        Some(section)
    } else {
        Some(OwnerCoreDebugSection {
            section_id: format!("{batch_id}-owner-core-debug"),
            cards: Vec::new(),
            summary: format!(
                "scenario_count={}, observer_status={:?}",
                update.scenario_count, update.observer_status
            ),
            paper_only_warning:
                "shadow scenario sweep summary is paper-only diagnostics; not investment advice, not trading, not orders"
                    .to_string(),
            debug_only_warning:
                "shadow scenario sweep is observer-only diagnostics and must not feed member opinions or committee decisions"
                    .to_string(),
            calibration_summary: None,
            recalibration_summary: None,
            shadow_opinion_summary: None,
            shadow_stability_summary: None,
            shadow_scenario_sweep_summary: Some(update),
            observer_section: None,
            observer_coverage_closure_summary: None,
            observer_trend_summary: None,
            observer_seeded_target_summary: None,
            observer_apply_readiness_summary: None,
            paper_only: true,
        })
    }
}

fn smartcore_shadow_scenario_sweep_requested_from_flags(
    enabled: bool,
    scenario_set_path: Option<&String>,
    output_path: Option<&String>,
    observer_gate_enabled: bool,
    _emit_owner_summary: bool,
) -> bool {
    enabled || scenario_set_path.is_some() || output_path.is_some() || observer_gate_enabled
}

pub fn run_smartcore_shadow_scenario_sweep(
    calibrated_debug_batch: &CalibratedSmartCoreDebugOutputBatchV0,
    batch_result: &BatchCommitteeCycleResult,
    replay_dataset: &ReplayDataset,
    calibration_dataset: Option<&CoreCalibrationDataset>,
    evidence_store: Option<&[PaperOutcomeEvidenceRecord]>,
    config: &SmartCoreShadowScenarioSweepConfig,
) -> Result<SmartCoreShadowScenarioSweepResult, String> {
    if !config.paper_only {
        return Err("smartcore shadow scenario sweep must remain paper_only".to_string());
    }
    if config.repeated_run_count == 0 || config.max_scenarios == 0 {
        return Err("smartcore shadow scenario sweep thresholds must be positive".to_string());
    }
    if let Some(path) = config.output_path.as_ref() {
        validate_local_json_path(
            Path::new(path),
            "smartcore shadow scenario sweep output path",
        )?;
    }
    let mut scenario_set = if let Some(path) = config.scenario_set_path.as_ref() {
        load_shadow_scenario_set_from_local_json(Path::new(path))?
    } else {
        build_default_shadow_scenario_set()
    };
    validate_shadow_scenario_set(&scenario_set)?;
    if scenario_set.scenarios.len() > config.max_scenarios {
        scenario_set.scenarios.truncate(config.max_scenarios);
        scenario_set.scenario_count = scenario_set.scenarios.len();
    }
    let scenario_results = scenario_set
        .scenarios
        .iter()
        .map(|scenario| {
            run_shadow_stability_for_scenario(
                scenario,
                calibrated_debug_batch,
                batch_result,
                replay_dataset,
                calibration_dataset,
                evidence_store,
                config,
            )
        })
        .collect::<Result<Vec<_>, _>>()?;
    let cross_scenario_sensitivity = compute_cross_scenario_sensitivity(&scenario_results);
    let target_coverage_stress = run_smartcore_target_coverage_stress_test(&scenario_results);
    let decision_isolation_regression =
        evaluate_multi_scenario_decision_isolation_regression_from_results(&scenario_results);
    let aggregate_action_flip_rate = if scenario_results.is_empty() {
        0.0
    } else {
        scenario_results
            .iter()
            .map(|result| result.action_flip_rate)
            .sum::<f64>()
            / scenario_results.len() as f64
    };
    let aggregate_head_flip_rate = if scenario_results.is_empty() {
        0.0
    } else {
        scenario_results
            .iter()
            .map(|result| result.head_bucket_flip_rate)
            .sum::<f64>()
            / scenario_results.len() as f64
    };
    let deterministic_scenario_count = scenario_results
        .iter()
        .filter(|result| {
            result.deterministic_status
                == SmartCoreShadowStabilityDeterministicStatus::Deterministic
        })
        .count();
    let unstable_scenario_count = scenario_results
        .iter()
        .filter(|result| {
            result.deterministic_status == SmartCoreShadowStabilityDeterministicStatus::Unstable
        })
        .count();
    let decision_isolation_failures = scenario_results
        .iter()
        .filter(|result| {
            result.decision_isolation_status
                == SmartCoreShadowStabilityDecisionIsolationRegressionStatus::Violated
        })
        .count();
    let mut result = SmartCoreShadowScenarioSweepResult {
        run_id: config.run_id.clone(),
        scenario_results,
        cross_scenario_sensitivity,
        target_coverage_stress,
        aggregate_action_flip_rate,
        aggregate_head_flip_rate,
        deterministic_scenario_count,
        unstable_scenario_count,
        decision_isolation_failures,
        sweep_status: SmartCoreShadowScenarioSweepStatus::Passed,
        warnings: Vec::new(),
        observer_readiness_gate: None,
        decision_isolation_regression,
        owner_debug_summary: None,
        paper_only: true,
    };
    if result.cross_scenario_sensitivity.sensitivity_status
        == SmartCoreCrossScenarioSensitivityStatus::TooStatic
    {
        result
            .warnings
            .push("cross-scenario sensitivity stayed too static".to_string());
    }
    if result.cross_scenario_sensitivity.sensitivity_status
        == SmartCoreCrossScenarioSensitivityStatus::TooUnstable
    {
        result
            .warnings
            .push("cross-scenario sensitivity looked too unstable".to_string());
    }
    if result.target_coverage_stress.target_coverage_status
        != SmartCoreTargetCoverageStatus::Sufficient
    {
        result.warnings.push(format!(
            "target coverage status is {:?}",
            result.target_coverage_stress.target_coverage_status
        ));
    }
    if result.decision_isolation_regression.regression_status
        == SmartCoreMultiScenarioDecisionIsolationRegressionStatus::Violated
        || result.unstable_scenario_count > 0
    {
        result.sweep_status = SmartCoreShadowScenarioSweepStatus::Failed;
    } else if !result.warnings.is_empty() {
        result.sweep_status = SmartCoreShadowScenarioSweepStatus::PassedWithWarnings;
    }
    if let Some(path) = config.output_path.as_ref() {
        write_safe_json(Path::new(path), &result)?;
    }
    Ok(result)
}

fn maybe_run_smartcore_shadow_scenario_sweep_for_batch_result(
    run_id: String,
    enabled: bool,
    scenario_set_path: Option<&String>,
    repeated_run_count: usize,
    max_scenarios: usize,
    output_path: Option<&String>,
    observer_gate_enabled: bool,
    observer_min_scenarios_required: usize,
    emit_owner_summary: bool,
    calibration_dataset_input_path: Option<&String>,
    batch_result: &mut BatchCommitteeCycleResult,
) -> Result<Option<SmartCoreShadowScenarioSweepResult>, String> {
    if !smartcore_shadow_scenario_sweep_requested_from_flags(
        enabled,
        scenario_set_path,
        output_path,
        observer_gate_enabled,
        emit_owner_summary,
    ) {
        return Ok(None);
    }
    let calibrated_debug_batch = batch_result
        .smartcore_shadow_recalibration_run_result
        .as_ref()
        .ok_or_else(|| {
            "smartcore shadow scenario sweep requires recalibrated debug output".to_string()
        })?
        .calibrated_debug_output_batch
        .clone();
    let generated_dataset = || {
        batch_result
            .smartcore_mismatch_learning_loop_result
            .as_ref()
            .and_then(|result| {
                result
                    .calibration_dataset_refresh_result
                    .as_ref()
                    .map(|refresh| refresh.refreshed_dataset.clone())
            })
            .or_else(|| {
                batch_result
                    .smartcore_mismatch_self_growing_run_result
                    .as_ref()
                    .map(|result| result.core_calibration_dataset.clone())
            })
    };
    let loaded_dataset = if let Some(path) = calibration_dataset_input_path {
        let path = Path::new(path);
        if path.exists() {
            Some(load_core_calibration_dataset_from_local_json(path)?)
        } else {
            generated_dataset()
        }
    } else {
        generated_dataset()
    };
    let evidence_store = batch_result
        .paper_outcome_evidence_load
        .as_ref()
        .map(|load| load.records.clone());
    let mut result = run_smartcore_shadow_scenario_sweep(
        &calibrated_debug_batch,
        batch_result,
        &batch_result.replay_dataset,
        loaded_dataset.as_ref(),
        evidence_store.as_deref(),
        &SmartCoreShadowScenarioSweepConfig {
            run_id,
            scenario_set_path: scenario_set_path.cloned(),
            repeated_run_count,
            max_scenarios,
            include_same_input_determinism: true,
            include_cross_scenario_sensitivity: true,
            expand_targets_per_scenario: true,
            output_path: output_path.cloned(),
            paper_only: true,
        },
    )?;
    if observer_gate_enabled {
        result.observer_readiness_gate = Some(evaluate_smartcore_observer_readiness(
            &result,
            &SmartCoreObserverReadinessPolicy {
                min_scenarios_required: observer_min_scenarios_required,
                require_zero_same_input_flip_rate: true,
                allow_reasonable_cross_scenario_variation: true,
                require_decision_isolation: true,
                require_no_training: true,
                require_no_live_inference: true,
                paper_only: true,
            },
        ));
    }
    if emit_owner_summary {
        let gate = result.observer_readiness_gate.clone().unwrap_or_else(|| {
            evaluate_smartcore_observer_readiness(
                &result,
                &SmartCoreObserverReadinessPolicy {
                    min_scenarios_required: observer_min_scenarios_required,
                    require_zero_same_input_flip_rate: true,
                    allow_reasonable_cross_scenario_variation: true,
                    require_decision_isolation: true,
                    require_no_training: true,
                    require_no_live_inference: true,
                    paper_only: true,
                },
            )
        });
        result.owner_debug_summary = Some(build_owner_shadow_scenario_sweep_debug_summary(
            &result, &gate,
        ));
        result.observer_readiness_gate.get_or_insert(gate);
    }
    if let Some(shadow_alignment_result) =
        batch_result.smartcore_shadow_alignment_run_result.as_mut()
    {
        shadow_alignment_result.owner_core_debug_section =
            apply_owner_shadow_scenario_sweep_debug_update(
                &batch_result.batch_id,
                shadow_alignment_result.owner_core_debug_section.take(),
                result.owner_debug_summary.clone(),
            );
        shadow_alignment_result.owner_core_debug_card_count = shadow_alignment_result
            .owner_core_debug_section
            .as_ref()
            .map(|section| section.cards.len())
            .unwrap_or(0);
    }
    if let Some(path) = output_path {
        write_safe_json(Path::new(path), &result)?;
    }
    batch_result.smartcore_shadow_scenario_sweep_result = Some(result.clone());
    Ok(Some(result))
}

pub fn default_smartcore_observer_lane_policy() -> SmartCoreObserverLanePolicy {
    SmartCoreObserverLanePolicy {
        policy_id: "smartcore-observer-lane-policy-v1".to_string(),
        observer_lane_enabled: true,
        read_only: true,
        non_voting: true,
        allow_committee_observation: true,
        allow_member_opinion_comparison: true,
        allow_chairman_comparison: true,
        allow_risk_governor_comparison: true,
        allow_vote: false,
        allow_event_opening: false,
        allow_member_opinion_mutation: false,
        allow_committee_session_mutation: false,
        allow_chairman_decision_mutation: false,
        allow_risk_governor_mutation: false,
        allow_score_update: false,
        allow_voice_weight_update: false,
        allow_trade_signal: false,
        allow_order: false,
        paper_only: true,
    }
}

pub fn validate_smartcore_observer_lane_policy(
    policy: &SmartCoreObserverLanePolicy,
) -> Result<(), String> {
    if !policy.paper_only {
        return Err("smartcore observer lane policy must remain paper_only".to_string());
    }
    if !policy.read_only {
        return Err("smartcore observer lane policy must remain read_only".to_string());
    }
    if !policy.non_voting {
        return Err("smartcore observer lane policy must remain non_voting".to_string());
    }
    if policy.allow_vote
        || policy.allow_event_opening
        || policy.allow_member_opinion_mutation
        || policy.allow_committee_session_mutation
        || policy.allow_chairman_decision_mutation
        || policy.allow_risk_governor_mutation
        || policy.allow_score_update
        || policy.allow_voice_weight_update
        || policy.allow_trade_signal
        || policy.allow_order
    {
        return Err(
            "smartcore observer lane policy must not allow mutation or order paths".to_string(),
        );
    }
    Ok(())
}

pub fn build_smartcore_observer_members(
    candidate_batch: &SmartCoreShadowOpinionCandidateBatch,
    canonical_map: &CanonicalMemberIdMap,
) -> Result<Vec<SmartCoreObserverMember>, String> {
    let mut observers = candidate_batch
        .candidates
        .iter()
        .map(|candidate| {
            let canonical_member_id =
                resolve_canonical_member_id_with_map(canonical_map, &candidate.member_id)
                    .ok_or_else(|| {
                        format!(
                            "smartcore observer member rejected unknown member alias={}",
                            candidate.member_id
                        )
                    })?;
            let entry = canonical_member_entry_for_id(canonical_map, &canonical_member_id)
                .ok_or_else(|| {
                    format!(
                        "smartcore observer member missing canonical entry for {}",
                        canonical_member_id
                    )
                })?;
            Ok(SmartCoreObserverMember {
                observer_id: format!("{}-observer", candidate.candidate_id),
                source_member_id: candidate.member_id.clone(),
                canonical_member_id,
                display_name: entry.display_name.clone(),
                source_shadow_candidate_id: Some(candidate.candidate_id.clone()),
                scenario_id: None,
                observer_role: SmartCoreObserverRole::SmartCoreShadowObserver,
                visibility: SmartCoreObserverVisibility::ReadOnly,
                voting_power: 0.0,
                can_open_event: false,
                can_join_committee_vote: false,
                can_change_chairman_decision: false,
                can_trigger_risk_governor: false,
                can_update_score: false,
                can_update_voice_weight: false,
                paper_only: true,
            })
        })
        .collect::<Result<Vec<_>, String>>()?;
    observers.sort_by(|left, right| left.source_member_id.cmp(&right.source_member_id));
    Ok(observers)
}

pub fn build_observed_committee_cycle_snapshot(
    batch_result: &BatchCommitteeCycleResult,
) -> ObservedCommitteeCycleSnapshot {
    ObservedCommitteeCycleSnapshot {
        snapshot_id: format!("{}-observer-snapshot", batch_result.batch_id),
        cycle_id: Some(batch_result.batch_id.clone()),
        event_ids: batch_result
            .event_queue
            .events
            .iter()
            .map(|event| event.event_id.clone())
            .collect(),
        member_opinion_ids: batch_result
            .member_opinions
            .iter()
            .map(|opinion| {
                format!(
                    "{}:{:?}:{}",
                    opinion.symbol, opinion.market_scope, opinion.member_id
                )
            })
            .collect(),
        committee_session_ids: batch_result
            .committee_sessions
            .iter()
            .map(|session| session.session_id.clone())
            .collect(),
        chairman_decision_ids: batch_result
            .chairman_decisions
            .iter()
            .map(|decision| decision.decision_id.clone())
            .collect(),
        risk_governor_statuses: batch_result
            .chairman_decisions
            .iter()
            .map(|decision| decision.risk_governor_status)
            .collect(),
        paper_only: true,
    }
}

fn observer_agreement_from_shadow_member_agreement(
    agreement: ShadowVsMemberOpinionAgreement,
) -> ObserverCommitteeAgreement {
    match agreement {
        ShadowVsMemberOpinionAgreement::Agree => ObserverCommitteeAgreement::Agree,
        ShadowVsMemberOpinionAgreement::PartiallyAgree => {
            ObserverCommitteeAgreement::PartiallyAgree
        }
        ShadowVsMemberOpinionAgreement::Disagree => ObserverCommitteeAgreement::Disagree,
        ShadowVsMemberOpinionAgreement::Unknown => ObserverCommitteeAgreement::Unknown,
        ShadowVsMemberOpinionAgreement::Deferred => ObserverCommitteeAgreement::NotComparable,
    }
}

fn chairman_shadow_action(action: ChairmanFinalAction) -> SmartCoreShadowOpinionAction {
    match action {
        ChairmanFinalAction::PaperBuy => SmartCoreShadowOpinionAction::ShadowBuyLike,
        ChairmanFinalAction::PaperHold => SmartCoreShadowOpinionAction::ShadowHoldLike,
        ChairmanFinalAction::PaperSell | ChairmanFinalAction::PaperNoTrade => {
            SmartCoreShadowOpinionAction::ShadowNoTradeLike
        }
        ChairmanFinalAction::NeedMoreEvidence => {
            SmartCoreShadowOpinionAction::ShadowNeedMoreEvidence
        }
        ChairmanFinalAction::RiskVetoed => SmartCoreShadowOpinionAction::ShadowRiskWarning,
    }
}

fn compare_observer_to_chairman(
    shadow_action: SmartCoreShadowOpinionAction,
    chairman_action: Option<ChairmanFinalAction>,
) -> ObserverCommitteeAgreement {
    let Some(chairman_action) = chairman_action else {
        return ObserverCommitteeAgreement::Unknown;
    };
    if chairman_shadow_action(chairman_action) == shadow_action {
        ObserverCommitteeAgreement::Agree
    } else if matches!(
        (shadow_action, chairman_action),
        (
            SmartCoreShadowOpinionAction::ShadowRiskWarning,
            ChairmanFinalAction::PaperHold
        ) | (
            SmartCoreShadowOpinionAction::ShadowHoldLike,
            ChairmanFinalAction::PaperBuy
        ) | (
            SmartCoreShadowOpinionAction::ShadowNeedMoreEvidence,
            ChairmanFinalAction::NeedMoreEvidence
        )
    ) {
        ObserverCommitteeAgreement::PartiallyAgree
    } else {
        ObserverCommitteeAgreement::Disagree
    }
}

fn compare_observer_to_risk_governor(
    shadow_action: SmartCoreShadowOpinionAction,
    risk_governor_status: Option<RiskGovernorStatus>,
) -> ObserverCommitteeAgreement {
    let Some(status) = risk_governor_status else {
        return ObserverCommitteeAgreement::Unknown;
    };
    match (shadow_action, status) {
        (SmartCoreShadowOpinionAction::ShadowBuyLike, RiskGovernorStatus::Passed)
        | (SmartCoreShadowOpinionAction::ShadowHoldLike, RiskGovernorStatus::Passed)
        | (SmartCoreShadowOpinionAction::ShadowRiskWarning, RiskGovernorStatus::Vetoed)
        | (SmartCoreShadowOpinionAction::ShadowNeedMoreEvidence, RiskGovernorStatus::NeedsReview) => {
            ObserverCommitteeAgreement::Agree
        }
        (
            SmartCoreShadowOpinionAction::ShadowNoTradeLike,
            RiskGovernorStatus::NeedsReview | RiskGovernorStatus::Vetoed,
        ) => ObserverCommitteeAgreement::PartiallyAgree,
        _ => ObserverCommitteeAgreement::Disagree,
    }
}

fn observer_disagreement_type(
    shadow_action: SmartCoreShadowOpinionAction,
    member_action: Option<SmartCoreShadowOpinionAction>,
    chairman_action: Option<ChairmanFinalAction>,
    risk_governor_status: Option<RiskGovernorStatus>,
) -> ObserverDisagreementType {
    match (
        shadow_action,
        member_action,
        chairman_action,
        risk_governor_status,
    ) {
        (SmartCoreShadowOpinionAction::ShadowBuyLike, _, _, Some(RiskGovernorStatus::Vetoed)) => {
            ObserverDisagreementType::ShadowBuyVsRiskVeto
        }
        (
            SmartCoreShadowOpinionAction::ShadowNoTradeLike,
            Some(SmartCoreShadowOpinionAction::ShadowBuyLike),
            _,
            _,
        ) => ObserverDisagreementType::ShadowNoTradeVsMemberBuy,
        (
            SmartCoreShadowOpinionAction::ShadowRiskWarning,
            _,
            Some(ChairmanFinalAction::PaperHold),
            _,
        ) => ObserverDisagreementType::ShadowRiskWarningVsChairmanHold,
        (
            SmartCoreShadowOpinionAction::ShadowNeedMoreEvidence,
            Some(SmartCoreShadowOpinionAction::ShadowBuyLike),
            _,
            _,
        ) => ObserverDisagreementType::ShadowNeedEvidenceVsMemberBuy,
        (
            SmartCoreShadowOpinionAction::ShadowHoldLike,
            _,
            Some(ChairmanFinalAction::PaperBuy),
            _,
        ) => ObserverDisagreementType::ShadowHoldVsChairmanBuy,
        (SmartCoreShadowOpinionAction::ShadowUnknown, _, _, _) => {
            ObserverDisagreementType::ShadowUnknown
        }
        _ => ObserverDisagreementType::None,
    }
}

fn observer_disagreement_severity(
    disagreement_type: ObserverDisagreementType,
) -> ObserverComparisonSeverity {
    match disagreement_type {
        ObserverDisagreementType::ShadowBuyVsRiskVeto => ObserverComparisonSeverity::High,
        ObserverDisagreementType::ShadowNoTradeVsMemberBuy
        | ObserverDisagreementType::ShadowRiskWarningVsChairmanHold
        | ObserverDisagreementType::ShadowNeedEvidenceVsMemberBuy
        | ObserverDisagreementType::ShadowHoldVsChairmanBuy => ObserverComparisonSeverity::Medium,
        ObserverDisagreementType::ShadowUnknown => ObserverComparisonSeverity::Low,
        ObserverDisagreementType::None => ObserverComparisonSeverity::Low,
    }
}

fn comparable_member_key(member_id: &str) -> String {
    role_for_member_id(member_id)
        .map(|role| format!("role::{role:?}"))
        .or_else(|| resolve_canonical_member_id(member_id))
        .unwrap_or_else(|| member_id.to_string())
}

fn committee_member_id_matches(candidate_member_id: &str, committee_member_id: &str) -> bool {
    candidate_member_id == committee_member_id
        || comparable_member_key(candidate_member_id) == comparable_member_key(committee_member_id)
}

fn matching_member_opinion_for_candidate<'a>(
    batch_result: &'a BatchCommitteeCycleResult,
    candidate: &SmartCoreShadowOpinionCandidate,
) -> Option<&'a MemberOpinion> {
    batch_result
        .member_opinions
        .iter()
        .find(|opinion| {
            committee_member_id_matches(&candidate.member_id, &opinion.member_id)
                && candidate
                    .symbol
                    .as_ref()
                    .is_none_or(|symbol| opinion.symbol == *symbol)
        })
        .or_else(|| {
            batch_result.member_opinions.iter().find(|opinion| {
                committee_member_id_matches(&candidate.member_id, &opinion.member_id)
            })
        })
}

fn matching_chairman_decision_for_candidate<'a>(
    batch_result: &'a BatchCommitteeCycleResult,
    candidate: &SmartCoreShadowOpinionCandidate,
) -> Option<&'a ChairmanDecision> {
    batch_result
        .chairman_decisions
        .iter()
        .find(|decision| {
            batch_result
                .committee_sessions
                .iter()
                .find(|session| session.session_id == decision.session_id)
                .is_some_and(|session| {
                    candidate
                        .symbol
                        .as_ref()
                        .is_none_or(|symbol| session.event.symbol == *symbol)
                        && candidate
                            .market_scope
                            .is_none_or(|scope| session.event.market_scope == scope)
                })
        })
        .or_else(|| batch_result.chairman_decisions.first())
}

pub fn compare_observer_to_committee(
    observer_member: &SmartCoreObserverMember,
    candidate: &SmartCoreShadowOpinionCandidate,
    _observed_snapshot: &ObservedCommitteeCycleSnapshot,
    batch_result: &BatchCommitteeCycleResult,
    compare_member: bool,
    compare_chairman: bool,
    compare_risk_governor: bool,
) -> ObserverVsCommitteeComparisonRecord {
    let member_record = compare_member.then(|| {
        compare_shadow_candidate_to_member_opinion(
            candidate,
            matching_member_opinion_for_candidate(batch_result, candidate),
        )
    });
    let member_action = member_record
        .as_ref()
        .and_then(|record| record.member_action);
    let agreement_with_member = member_record
        .as_ref()
        .map(|record| observer_agreement_from_shadow_member_agreement(record.agreement))
        .unwrap_or(ObserverCommitteeAgreement::NotComparable);
    let chairman_decision = compare_chairman
        .then(|| matching_chairman_decision_for_candidate(batch_result, candidate))
        .flatten();
    let chairman_action = chairman_decision.map(|decision| decision.final_action);
    let agreement_with_chairman = if compare_chairman {
        compare_observer_to_chairman(candidate.shadow_action, chairman_action)
    } else {
        ObserverCommitteeAgreement::NotComparable
    };
    let risk_governor_status = chairman_decision.map(|decision| decision.risk_governor_status);
    let agreement_with_risk_governor = if compare_risk_governor {
        compare_observer_to_risk_governor(candidate.shadow_action, risk_governor_status)
    } else {
        ObserverCommitteeAgreement::NotComparable
    };
    let disagreement_type = observer_disagreement_type(
        candidate.shadow_action,
        member_action,
        chairman_action,
        risk_governor_status,
    );
    ObserverVsCommitteeComparisonRecord {
        comparison_id: format!("{}-comparison", observer_member.observer_id),
        observer_id: observer_member.observer_id.clone(),
        source_member_id: observer_member.source_member_id.clone(),
        symbol: candidate.symbol.clone(),
        market_scope: candidate.market_scope,
        shadow_action: candidate.shadow_action,
        member_action,
        chairman_action,
        risk_governor_status,
        agreement_with_member,
        agreement_with_chairman,
        agreement_with_risk_governor,
        disagreement_type,
        severity: observer_disagreement_severity(disagreement_type),
        paper_only: true,
    }
}

pub fn summarize_observer_vs_committee_comparisons(
    records: &[ObserverVsCommitteeComparisonRecord],
) -> ObserverVsCommitteeComparisonSummary {
    let comparison_count = records.len();
    let member_agree_count = records
        .iter()
        .filter(|record| record.agreement_with_member == ObserverCommitteeAgreement::Agree)
        .count();
    let chairman_agree_count = records
        .iter()
        .filter(|record| record.agreement_with_chairman == ObserverCommitteeAgreement::Agree)
        .count();
    let risk_governor_agree_count = records
        .iter()
        .filter(|record| record.agreement_with_risk_governor == ObserverCommitteeAgreement::Agree)
        .count();
    let disagreement_count = records
        .iter()
        .filter(|record| record.disagreement_type != ObserverDisagreementType::None)
        .count();
    let high_severity_disagreement_count = records
        .iter()
        .filter(|record| record.severity == ObserverComparisonSeverity::High)
        .count();
    let per_member_summary =
        records
            .iter()
            .fold(std::collections::BTreeMap::new(), |mut map, record| {
                let agreement = if record.agreement_with_member
                    == ObserverCommitteeAgreement::Disagree
                    || record.agreement_with_chairman == ObserverCommitteeAgreement::Disagree
                    || record.agreement_with_risk_governor == ObserverCommitteeAgreement::Disagree
                {
                    ObserverCommitteeAgreement::Disagree
                } else if record.agreement_with_member == ObserverCommitteeAgreement::Agree
                    || record.agreement_with_chairman == ObserverCommitteeAgreement::Agree
                    || record.agreement_with_risk_governor == ObserverCommitteeAgreement::Agree
                {
                    ObserverCommitteeAgreement::Agree
                } else {
                    ObserverCommitteeAgreement::Unknown
                };
                map.insert(record.source_member_id.clone(), agreement);
                map
            });
    let summary_status = if comparison_count == 0 {
        ObserverVsCommitteeComparisonSummaryStatus::InsufficientComparisons
    } else if disagreement_count == 0 {
        ObserverVsCommitteeComparisonSummaryStatus::MostlyAgree
    } else if disagreement_count * 2 >= comparison_count {
        ObserverVsCommitteeComparisonSummaryStatus::MostlyDisagree
    } else {
        ObserverVsCommitteeComparisonSummaryStatus::Mixed
    };
    ObserverVsCommitteeComparisonSummary {
        summary_id: "observer-vs-committee-summary".to_string(),
        comparison_count,
        member_agree_count,
        chairman_agree_count,
        risk_governor_agree_count,
        disagreement_count,
        high_severity_disagreement_count,
        per_member_summary,
        summary_status,
        paper_only: true,
    }
}

pub fn build_observer_disagreement_records(
    comparison_records: &[ObserverVsCommitteeComparisonRecord],
) -> Vec<SmartCoreObserverDisagreementRecord> {
    comparison_records
        .iter()
        .filter(|record| record.disagreement_type != ObserverDisagreementType::None)
        .map(|record| SmartCoreObserverDisagreementRecord {
            disagreement_id: format!("{}-disagreement", record.comparison_id),
            observer_id: record.observer_id.clone(),
            source_member_id: record.source_member_id.clone(),
            symbol: record.symbol.clone(),
            market_scope: record.market_scope,
            disagreement_type: record.disagreement_type,
            shadow_action: record.shadow_action,
            committee_reference: match record.disagreement_type {
                ObserverDisagreementType::ShadowBuyVsRiskVeto => "risk_governor".to_string(),
                ObserverDisagreementType::ShadowNoTradeVsMemberBuy
                | ObserverDisagreementType::ShadowNeedEvidenceVsMemberBuy => {
                    "member_opinion".to_string()
                }
                ObserverDisagreementType::ShadowRiskWarningVsChairmanHold
                | ObserverDisagreementType::ShadowHoldVsChairmanBuy => {
                    "chairman_decision".to_string()
                }
                _ => "observer".to_string(),
            },
            severity: record.severity,
            suggested_follow_up: match record.disagreement_type {
                ObserverDisagreementType::ShadowBuyVsRiskVeto => {
                    SmartCoreObserverSuggestedFollowUp::CollectMoreRiskTargets
                }
                ObserverDisagreementType::ShadowNeedEvidenceVsMemberBuy => {
                    SmartCoreObserverSuggestedFollowUp::CollectMoreEvidenceTargets
                }
                ObserverDisagreementType::ShadowNoTradeVsMemberBuy
                | ObserverDisagreementType::ShadowHoldVsChairmanBuy => {
                    SmartCoreObserverSuggestedFollowUp::CollectMoreStanceTargets
                }
                ObserverDisagreementType::ShadowRiskWarningVsChairmanHold => {
                    SmartCoreObserverSuggestedFollowUp::CollectMoreScenarioTargets
                }
                _ => SmartCoreObserverSuggestedFollowUp::KeepObserving,
            },
            paper_only: true,
        })
        .collect()
}

pub fn build_observer_target_coverage_closure_queue(
    target_coverage_stress: &SmartCoreTargetCoverageStressResult,
    observer_disagreements: &[SmartCoreObserverDisagreementRecord],
) -> ObserverTargetCoverageClosureQueue {
    let mut item_keys = std::collections::BTreeSet::new();
    let mut items = Vec::new();
    for task in &target_coverage_stress.recommended_target_collection_tasks {
        let (target_need, priority) = match task.target_need {
            SmartCoreAgreementTargetNeed::RiskTarget => (
                ObserverTargetCoverageClosureNeed::MoreRiskTargets,
                ObserverTargetCoverageClosurePriority::High,
            ),
            SmartCoreAgreementTargetNeed::EvidenceTarget => (
                ObserverTargetCoverageClosureNeed::MoreEvidenceTargets,
                ObserverTargetCoverageClosurePriority::High,
            ),
            SmartCoreAgreementTargetNeed::StanceTarget => (
                ObserverTargetCoverageClosureNeed::MoreStanceTargets,
                ObserverTargetCoverageClosurePriority::Normal,
            ),
            SmartCoreAgreementTargetNeed::ConfidenceTarget => (
                ObserverTargetCoverageClosureNeed::MoreConfidenceTargets,
                ObserverTargetCoverageClosurePriority::Normal,
            ),
            SmartCoreAgreementTargetNeed::PaperOutcomeTarget => (
                ObserverTargetCoverageClosureNeed::MorePaperOutcomeTargets,
                ObserverTargetCoverageClosurePriority::Low,
            ),
            SmartCoreAgreementTargetNeed::MemberOpinionTarget => (
                ObserverTargetCoverageClosureNeed::MoreScenarioTargets,
                ObserverTargetCoverageClosurePriority::Normal,
            ),
        };
        let key = format!("{:?}-{:?}-{:?}", target_need, task.member_id, task.head);
        if item_keys.insert(key) {
            items.push(ObserverTargetCoverageClosureItem {
                item_id: format!("observer-closure-{}", task.task_id),
                scenario_id: None,
                member_id: task.member_id.clone(),
                symbol: None,
                market_scope: None,
                head: task.head,
                target_need,
                priority,
                reason: task.reason.clone(),
                paper_only: true,
            });
        }
    }
    for disagreement in observer_disagreements {
        let (target_need, head, priority) = match disagreement.suggested_follow_up {
            SmartCoreObserverSuggestedFollowUp::CollectMoreRiskTargets => (
                ObserverTargetCoverageClosureNeed::MoreRiskTargets,
                Some(SmartCoreShadowHeadKind::Risk),
                ObserverTargetCoverageClosurePriority::High,
            ),
            SmartCoreObserverSuggestedFollowUp::CollectMoreEvidenceTargets => (
                ObserverTargetCoverageClosureNeed::MoreEvidenceTargets,
                Some(SmartCoreShadowHeadKind::EvidenceNeed),
                ObserverTargetCoverageClosurePriority::High,
            ),
            SmartCoreObserverSuggestedFollowUp::CollectMoreStanceTargets => (
                ObserverTargetCoverageClosureNeed::MoreStanceTargets,
                Some(SmartCoreShadowHeadKind::Stance),
                ObserverTargetCoverageClosurePriority::Normal,
            ),
            SmartCoreObserverSuggestedFollowUp::CollectMoreScenarioTargets => (
                ObserverTargetCoverageClosureNeed::MoreScenarioTargets,
                None,
                ObserverTargetCoverageClosurePriority::Normal,
            ),
            SmartCoreObserverSuggestedFollowUp::KeepObserving
            | SmartCoreObserverSuggestedFollowUp::DoNotIntegrateDecision => continue,
        };
        let key = format!(
            "{:?}-{}-{:?}",
            target_need, disagreement.source_member_id, disagreement.symbol
        );
        if item_keys.insert(key) {
            items.push(ObserverTargetCoverageClosureItem {
                item_id: format!("observer-closure-{}", disagreement.disagreement_id),
                scenario_id: None,
                member_id: Some(disagreement.source_member_id.clone()),
                symbol: disagreement.symbol.clone(),
                market_scope: disagreement.market_scope,
                head,
                target_need,
                priority,
                reason: format!(
                    "Observer disagreement {:?} suggests more coverage.",
                    disagreement.disagreement_type
                ),
                paper_only: true,
            });
        }
    }
    items.sort_by(|left, right| left.item_id.cmp(&right.item_id));
    ObserverTargetCoverageClosureQueue {
        queue_id: "observer-target-coverage-closure-queue".to_string(),
        item_count: items.len(),
        high_priority_count: items
            .iter()
            .filter(|item| item.priority == ObserverTargetCoverageClosurePriority::High)
            .count(),
        items,
        paper_only: true,
    }
}

fn build_observer_target_coverage_closure_result(
    target_coverage_stress: &SmartCoreTargetCoverageStressResult,
    observer_disagreements: &[SmartCoreObserverDisagreementRecord],
) -> ObserverTargetCoverageClosureResult {
    let closure_queue = build_observer_target_coverage_closure_queue(
        target_coverage_stress,
        observer_disagreements,
    );
    let expected_improvement = if closure_queue.high_priority_count > 0 {
        ObserverTargetCoverageClosureExpectedImprovement::High
    } else if closure_queue.item_count > 2 {
        ObserverTargetCoverageClosureExpectedImprovement::Medium
    } else if closure_queue.item_count > 0 {
        ObserverTargetCoverageClosureExpectedImprovement::Low
    } else {
        ObserverTargetCoverageClosureExpectedImprovement::None
    };
    let closure_status = if closure_queue.item_count == 0
        && target_coverage_stress.target_coverage_status
            == SmartCoreTargetCoverageStatus::Sufficient
    {
        ObserverTargetCoverageClosureStatus::NoClosureNeeded
    } else if closure_queue.item_count > 0 {
        ObserverTargetCoverageClosureStatus::ClosurePlanned
    } else {
        ObserverTargetCoverageClosureStatus::NeedsMoreTargets
    };
    ObserverTargetCoverageClosureResult {
        previous_coverage_status: target_coverage_stress.target_coverage_status,
        closure_queue,
        expected_improvement,
        closure_status,
        paper_only: true,
    }
}

pub fn evaluate_smartcore_observer_lane_safety(
    observer_members: &[SmartCoreObserverMember],
    batch_result_before: &BatchCommitteeCycleResult,
    batch_result_after: Option<&BatchCommitteeCycleResult>,
) -> SmartCoreObserverLaneSafetyGuard {
    let after = batch_result_after.unwrap_or(batch_result_before);
    let observer_ids = observer_members
        .iter()
        .map(|observer| observer.observer_id.clone())
        .collect::<Vec<_>>();
    let observer_has_voting_power = observer_members
        .iter()
        .any(|observer| observer.voting_power > 0.0);
    let observer_opened_event = observer_members
        .iter()
        .any(|observer| observer.can_open_event);
    let observer_joined_committee_vote = observer_members
        .iter()
        .any(|observer| observer.can_join_committee_vote)
        || after.committee_sessions.iter().any(|session| {
            session
                .invited_members
                .iter()
                .any(|member| observer_ids.contains(member))
        });
    let observer_changed_member_opinion =
        batch_result_before.member_opinions != after.member_opinions;
    let observer_changed_committee_session =
        batch_result_before.committee_sessions != after.committee_sessions;
    let observer_changed_chairman_decision =
        batch_result_before.chairman_decisions != after.chairman_decisions;
    let observer_changed_risk_governor = batch_result_before
        .chairman_decisions
        .iter()
        .map(|decision| decision.risk_governor_status)
        .collect::<Vec<_>>()
        != after
            .chairman_decisions
            .iter()
            .map(|decision| decision.risk_governor_status)
            .collect::<Vec<_>>();
    let observer_changed_member_score = batch_result_before.score_updates != after.score_updates;
    let observer_changed_voice_weight = batch_result_before
        .score_updates
        .iter()
        .map(|update| (update.member_id.clone(), update.new_voice_weight))
        .collect::<Vec<_>>()
        != after
            .score_updates
            .iter()
            .map(|update| (update.member_id.clone(), update.new_voice_weight))
            .collect::<Vec<_>>();
    let observer_created_trade_signal =
        value_contains_debug_marker(&after.committee_sessions, &observer_ids);
    let observer_created_order = value_contains_debug_marker(&after.event_queue, &observer_ids)
        || value_contains_debug_marker(&after.chairman_decisions, &observer_ids);
    let observer_touched_broker_order_account = observer_created_order;
    let mut violations = Vec::new();
    if observer_has_voting_power {
        violations.push("observer lane gave voting power".to_string());
    }
    if observer_opened_event {
        violations.push("observer lane opened event".to_string());
    }
    if observer_joined_committee_vote {
        violations.push("observer lane joined committee vote".to_string());
    }
    if observer_changed_member_opinion {
        violations.push("observer lane changed member opinion".to_string());
    }
    if observer_changed_committee_session {
        violations.push("observer lane changed committee session".to_string());
    }
    if observer_changed_chairman_decision {
        violations.push("observer lane changed chairman decision".to_string());
    }
    if observer_changed_risk_governor {
        violations.push("observer lane changed risk governor".to_string());
    }
    if observer_changed_member_score {
        violations.push("observer lane changed member score".to_string());
    }
    if observer_changed_voice_weight {
        violations.push("observer lane changed voice weight".to_string());
    }
    if observer_created_trade_signal {
        violations.push("observer lane created trade signal".to_string());
    }
    if observer_created_order {
        violations.push("observer lane created order".to_string());
    }
    if observer_touched_broker_order_account {
        violations.push("observer lane touched broker/order/account path".to_string());
    }
    SmartCoreObserverLaneSafetyGuard {
        observer_has_voting_power,
        observer_opened_event,
        observer_joined_committee_vote,
        observer_changed_member_opinion,
        observer_changed_committee_session,
        observer_changed_chairman_decision,
        observer_changed_risk_governor,
        observer_changed_member_score,
        observer_changed_voice_weight,
        observer_created_trade_signal,
        observer_created_order,
        observer_touched_broker_order_account,
        guard_status: if violations.is_empty() {
            SmartCoreObserverLaneSafetyGuardStatus::Preserved
        } else {
            SmartCoreObserverLaneSafetyGuardStatus::Violated
        },
        violations,
        paper_only: true,
    }
}

pub fn build_owner_smartcore_observer_section(
    observer_run_result: &SmartCoreObserverLaneRunResult,
) -> OwnerSmartCoreObserverSection {
    let comparison_by_observer = observer_run_result
        .comparison_records
        .iter()
        .map(|record| (record.observer_id.clone(), record))
        .collect::<std::collections::BTreeMap<_, _>>();
    let cards = observer_run_result
        .observer_members
        .iter()
        .map(|observer| {
            let comparison = comparison_by_observer.get(&observer.observer_id);
            OwnerSmartCoreObserverCard {
                observer_id: observer.observer_id.clone(),
                source_member_id: observer.source_member_id.clone(),
                display_name: observer.display_name.clone(),
                shadow_action: comparison
                    .map(|record| record.shadow_action)
                    .unwrap_or(SmartCoreShadowOpinionAction::ShadowUnknown),
                agreement_with_member: comparison
                    .map(|record| record.agreement_with_member)
                    .unwrap_or(ObserverCommitteeAgreement::Unknown),
                agreement_with_chairman: comparison
                    .map(|record| record.agreement_with_chairman)
                    .unwrap_or(ObserverCommitteeAgreement::Unknown),
                agreement_with_risk_governor: comparison
                    .map(|record| record.agreement_with_risk_governor)
                    .unwrap_or(ObserverCommitteeAgreement::Unknown),
                high_severity_disagreement: comparison
                    .map(|record| record.severity == ObserverComparisonSeverity::High)
                    .unwrap_or(false),
                voting_power: observer.voting_power,
                non_voting: true,
                read_only: true,
                not_committee_input: true,
                not_trade_signal: true,
                paper_only: true,
            }
        })
        .collect::<Vec<_>>();
    OwnerSmartCoreObserverSection {
        section_id: format!("{}-owner-observer-section", observer_run_result.run_id),
        cards,
        comparison_summary: format!(
            "comparisons={}, disagreements={}, status={:?}",
            observer_run_result.comparison_summary.comparison_count,
            observer_run_result.comparison_summary.disagreement_count,
            observer_run_result.comparison_summary.summary_status
        ),
        target_coverage_closure_summary: observer_run_result
            .target_coverage_closure_result
            .as_ref()
            .map(|result| {
                format!(
                    "closure_items={}, status={:?}",
                    result.closure_queue.item_count, result.closure_status
                )
            }),
        warning: "SmartCore observer is non-voting and cannot affect decisions.".to_string(),
        paper_only: true,
    }
}

pub fn recheck_smartcore_observer_lane_readiness(
    observer_run_result: &SmartCoreObserverLaneRunResult,
) -> SmartCoreObserverLaneReadinessRecheck {
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    let target_coverage_closure_status = observer_run_result
        .target_coverage_closure_result
        .as_ref()
        .map(|result| result.closure_status);
    let readiness_status = if observer_run_result.observer_safety_guard.guard_status
        == SmartCoreObserverLaneSafetyGuardStatus::Violated
    {
        if observer_run_result
            .observer_safety_guard
            .violations
            .iter()
            .any(|violation| {
                violation.contains("changed")
                    || violation.contains("trade signal")
                    || violation.contains("order")
            })
        {
            blockers.extend(observer_run_result.observer_safety_guard.violations.clone());
            SmartCoreObserverLaneReadinessStatus::BlockedByDecisionLeak
        } else {
            blockers.extend(observer_run_result.observer_safety_guard.violations.clone());
            SmartCoreObserverLaneReadinessStatus::BlockedBySafety
        }
    } else if observer_run_result.comparison_summary.comparison_count == 0
        || target_coverage_closure_status
            == Some(ObserverTargetCoverageClosureStatus::NeedsMoreTargets)
    {
        blockers.push("observer lane needs more comparison/coverage inputs".to_string());
        SmartCoreObserverLaneReadinessStatus::NeedsMoreTargets
    } else if observer_run_result.comparison_summary.summary_status
        == ObserverVsCommitteeComparisonSummaryStatus::MostlyAgree
        && target_coverage_closure_status
            .unwrap_or(ObserverTargetCoverageClosureStatus::NoClosureNeeded)
            == ObserverTargetCoverageClosureStatus::NoClosureNeeded
    {
        SmartCoreObserverLaneReadinessStatus::NonVotingObserverReady
    } else {
        if target_coverage_closure_status
            == Some(ObserverTargetCoverageClosureStatus::ClosurePlanned)
        {
            warnings.push("target coverage still needs closure work".to_string());
        }
        warnings.push("observer lane remains non-voting/read-only only".to_string());
        SmartCoreObserverLaneReadinessStatus::NonVotingObserverReadyWithWarnings
    };
    SmartCoreObserverLaneReadinessRecheck {
        observer_lane_run_status: observer_run_result.run_status,
        observer_safety_status: observer_run_result.observer_safety_guard.guard_status,
        comparison_summary_status: observer_run_result.comparison_summary.summary_status,
        target_coverage_closure_status,
        observer_ready_for_non_voting_lane: matches!(
            readiness_status,
            SmartCoreObserverLaneReadinessStatus::NonVotingObserverReady
                | SmartCoreObserverLaneReadinessStatus::NonVotingObserverReadyWithWarnings
        ),
        readiness_status,
        blockers,
        warnings,
        paper_only: true,
    }
}

pub fn run_smartcore_observer_lane(
    candidate_batch: &SmartCoreShadowOpinionCandidateBatch,
    batch_result: &BatchCommitteeCycleResult,
    target_coverage_stress: Option<&SmartCoreTargetCoverageStressResult>,
    config: &SmartCoreObserverLaneRunConfig,
) -> Result<SmartCoreObserverLaneRunResult, String> {
    if !config.paper_only {
        return Err("smartcore observer lane must remain paper_only".to_string());
    }
    if let Some(path) = config.output_path.as_ref() {
        validate_local_json_path(Path::new(path), "smartcore observer output path")?;
    }
    let policy = SmartCoreObserverLanePolicy {
        observer_lane_enabled: config.enabled,
        allow_member_opinion_comparison: config.compare_member_opinion,
        allow_chairman_comparison: config.compare_chairman_decision,
        allow_risk_governor_comparison: config.compare_risk_governor,
        ..default_smartcore_observer_lane_policy()
    };
    validate_smartcore_observer_lane_policy(&policy)?;
    let observer_members = build_smartcore_observer_members(
        candidate_batch,
        &default_three_member_canonical_id_map(),
    )?;
    let observed_snapshot = build_observed_committee_cycle_snapshot(batch_result);
    let comparison_records = observer_members
        .iter()
        .filter_map(|observer| {
            let candidate_id = observer.source_shadow_candidate_id.as_ref()?;
            let candidate = candidate_batch
                .candidates
                .iter()
                .find(|candidate| candidate.candidate_id == *candidate_id)?;
            Some(compare_observer_to_committee(
                observer,
                candidate,
                &observed_snapshot,
                batch_result,
                config.compare_member_opinion,
                config.compare_chairman_decision,
                config.compare_risk_governor,
            ))
        })
        .collect::<Vec<_>>();
    let comparison_summary = summarize_observer_vs_committee_comparisons(&comparison_records);
    let disagreement_records = build_observer_disagreement_records(&comparison_records);
    let target_coverage_closure_result = if config.build_target_coverage_closure_queue {
        target_coverage_stress.map(|stress| {
            build_observer_target_coverage_closure_result(stress, &disagreement_records)
        })
    } else {
        None
    };
    let observer_safety_guard = evaluate_smartcore_observer_lane_safety(
        &observer_members,
        batch_result,
        Some(batch_result),
    );
    let mut result = SmartCoreObserverLaneRunResult {
        run_id: config.run_id.clone(),
        observer_members,
        observed_snapshot,
        comparison_records,
        comparison_summary,
        disagreement_records,
        target_coverage_closure_result,
        observer_safety_guard,
        run_status: SmartCoreObserverLaneRunStatus::Passed,
        warnings: Vec::new(),
        owner_observer_section: None,
        readiness_recheck: None,
        paper_only: true,
    };
    if result.comparison_summary.disagreement_count > 0 {
        result.warnings.push(format!(
            "observer disagreement count={}",
            result.comparison_summary.disagreement_count
        ));
    }
    if let Some(closure) = result.target_coverage_closure_result.as_ref() {
        if closure.closure_queue.item_count > 0 {
            result.warnings.push(format!(
                "observer target coverage closure items={}",
                closure.closure_queue.item_count
            ));
        }
    }
    if result.observer_safety_guard.guard_status == SmartCoreObserverLaneSafetyGuardStatus::Violated
    {
        result.run_status = SmartCoreObserverLaneRunStatus::Failed;
    } else if !result.warnings.is_empty() {
        result.run_status = SmartCoreObserverLaneRunStatus::PassedWithWarnings;
    }
    if config.emit_owner_observer_section {
        result.owner_observer_section = Some(build_owner_smartcore_observer_section(&result));
    }
    result.readiness_recheck = Some(recheck_smartcore_observer_lane_readiness(&result));
    if let Some(path) = config.output_path.as_ref() {
        write_safe_json(Path::new(path), &result)?;
    }
    Ok(result)
}

fn apply_owner_smartcore_observer_section_update(
    batch_id: &str,
    section: Option<OwnerCoreDebugSection>,
    update: Option<OwnerSmartCoreObserverSection>,
) -> Option<OwnerCoreDebugSection> {
    let Some(update) = update else {
        return section;
    };
    if let Some(mut section) = section {
        section.summary = format!(
            "{}; observer_cards={}, observer_warning=non-voting",
            section.summary,
            update.cards.len()
        );
        section.observer_section = Some(update);
        Some(section)
    } else {
        Some(OwnerCoreDebugSection {
            section_id: format!("{batch_id}-owner-core-debug"),
            cards: Vec::new(),
            summary: format!("observer_cards={}", update.cards.len()),
            paper_only_warning:
                "smartcore observer section is paper-only diagnostics; not investment advice, not trading, not orders"
                    .to_string(),
            debug_only_warning:
                "smartcore observer is read-only/non-voting and must not feed committee decisions"
                    .to_string(),
            calibration_summary: None,
            recalibration_summary: None,
            shadow_opinion_summary: None,
            shadow_stability_summary: None,
            shadow_scenario_sweep_summary: None,
            observer_section: Some(update),
            observer_coverage_closure_summary: None,
            observer_trend_summary: None,
            observer_seeded_target_summary: None,
            observer_apply_readiness_summary: None,
            paper_only: true,
        })
    }
}

fn smartcore_observer_lane_requested_from_flags(
    enabled: bool,
    output_path: Option<&String>,
    _compare_member_opinion: bool,
    _compare_chairman: bool,
    _compare_risk_governor: bool,
    _build_target_coverage_closure_queue: bool,
    _emit_owner_section: bool,
) -> bool {
    enabled || output_path.is_some()
}

fn maybe_run_smartcore_observer_lane_for_batch_result(
    run_id: String,
    enabled: bool,
    output_path: Option<&String>,
    compare_member_opinion: bool,
    compare_chairman: bool,
    compare_risk_governor: bool,
    build_target_coverage_closure_queue: bool,
    emit_owner_section: bool,
    batch_result: &mut BatchCommitteeCycleResult,
) -> Result<Option<SmartCoreObserverLaneRunResult>, String> {
    if !smartcore_observer_lane_requested_from_flags(
        enabled,
        output_path,
        compare_member_opinion,
        compare_chairman,
        compare_risk_governor,
        build_target_coverage_closure_queue,
        emit_owner_section,
    ) {
        return Ok(None);
    }
    let candidate_batch = batch_result
        .smartcore_shadow_opinion_run_result
        .as_ref()
        .ok_or_else(|| {
            "smartcore observer lane requires shadow opinion candidate batch".to_string()
        })?
        .candidate_batch
        .clone();
    let target_coverage_stress = batch_result
        .smartcore_shadow_scenario_sweep_result
        .as_ref()
        .map(|result| result.target_coverage_stress.clone());
    let result = run_smartcore_observer_lane(
        &candidate_batch,
        batch_result,
        target_coverage_stress.as_ref(),
        &SmartCoreObserverLaneRunConfig {
            run_id,
            enabled,
            output_path: output_path.cloned(),
            compare_member_opinion,
            compare_chairman_decision: compare_chairman,
            compare_risk_governor,
            build_target_coverage_closure_queue,
            emit_owner_observer_section: emit_owner_section,
            paper_only: true,
        },
    )?;
    if let Some(shadow_alignment_result) =
        batch_result.smartcore_shadow_alignment_run_result.as_mut()
    {
        shadow_alignment_result.owner_core_debug_section =
            apply_owner_smartcore_observer_section_update(
                &batch_result.batch_id,
                shadow_alignment_result.owner_core_debug_section.take(),
                result.owner_observer_section.clone(),
            );
        shadow_alignment_result.owner_core_debug_card_count = shadow_alignment_result
            .owner_core_debug_section
            .as_ref()
            .map(|section| section.cards.len())
            .unwrap_or(0);
    }
    if let Some(path) = output_path {
        write_safe_json(Path::new(path), &result)?;
    }
    batch_result.smartcore_observer_lane_run_result = Some(result.clone());
    Ok(Some(result))
}

pub fn default_observer_target_closure_execution_policy() -> ObserverTargetClosureExecutionPolicy {
    ObserverTargetClosureExecutionPolicy {
        policy_id: "observer-target-closure-execution-policy".to_string(),
        allow_replay_targets: true,
        allow_calibration_targets: true,
        allow_member_opinion_targets: true,
        allow_risk_governor_targets: true,
        allow_paper_outcome_targets: true,
        allow_news_only_targets: false,
        allow_low_trust_targets: false,
        allow_ambiguous_targets: false,
        require_member_id: true,
        require_head_or_target_type: true,
        require_symbol_scope_when_available: true,
        paper_only: true,
    }
}

fn observer_target_head_for_need(
    need: ObserverTargetCoverageClosureNeed,
    fallback: Option<SmartCoreShadowHeadKind>,
) -> ObserverAgreementTargetHead {
    match (need, fallback) {
        (ObserverTargetCoverageClosureNeed::MoreRiskTargets, _) => {
            ObserverAgreementTargetHead::Risk
        }
        (ObserverTargetCoverageClosureNeed::MoreEvidenceTargets, _) => {
            ObserverAgreementTargetHead::EvidenceNeed
        }
        (ObserverTargetCoverageClosureNeed::MoreConfidenceTargets, _) => {
            ObserverAgreementTargetHead::ConfidenceCalibration
        }
        (
            ObserverTargetCoverageClosureNeed::MoreScenarioTargets,
            Some(SmartCoreShadowHeadKind::Risk),
        ) => ObserverAgreementTargetHead::Risk,
        (
            ObserverTargetCoverageClosureNeed::MoreScenarioTargets,
            Some(SmartCoreShadowHeadKind::EvidenceNeed),
        ) => ObserverAgreementTargetHead::EvidenceNeed,
        (
            ObserverTargetCoverageClosureNeed::MoreScenarioTargets,
            Some(SmartCoreShadowHeadKind::ConfidenceCalibration),
        ) => ObserverAgreementTargetHead::ConfidenceCalibration,
        (
            ObserverTargetCoverageClosureNeed::MoreScenarioTargets,
            Some(SmartCoreShadowHeadKind::Uncertainty),
        ) => ObserverAgreementTargetHead::Uncertainty,
        _ => ObserverAgreementTargetHead::Stance,
    }
}

fn chairman_action_target(
    action: ChairmanFinalAction,
) -> Option<SmartCoreHeadBucketNormalizedValue> {
    match action {
        ChairmanFinalAction::PaperBuy => Some(SmartCoreHeadBucketNormalizedValue::PositiveLike),
        ChairmanFinalAction::PaperSell | ChairmanFinalAction::PaperNoTrade => {
            Some(SmartCoreHeadBucketNormalizedValue::NegativeLike)
        }
        ChairmanFinalAction::PaperHold => Some(SmartCoreHeadBucketNormalizedValue::NeutralLike),
        ChairmanFinalAction::NeedMoreEvidence => {
            Some(SmartCoreHeadBucketNormalizedValue::NeedMoreEvidence)
        }
        ChairmanFinalAction::RiskVetoed => Some(SmartCoreHeadBucketNormalizedValue::RiskHigh),
    }
}

fn closure_bucket_from_experience_outcome(
    outcome: MemberExperienceOutcome,
) -> SmartCoreHeadBucketNormalizedValue {
    match outcome {
        MemberExperienceOutcome::PaperPositive
        | MemberExperienceOutcome::RiskVetoSavedLoss
        | MemberExperienceOutcome::HelpfulDissent => {
            SmartCoreHeadBucketNormalizedValue::PositiveLike
        }
        MemberExperienceOutcome::PaperNegative
        | MemberExperienceOutcome::MissedOpportunity
        | MemberExperienceOutcome::BadRiskCall => SmartCoreHeadBucketNormalizedValue::NegativeLike,
        MemberExperienceOutcome::PaperNeutral | MemberExperienceOutcome::Unknown => {
            SmartCoreHeadBucketNormalizedValue::NeutralLike
        }
    }
}

fn replay_risk_target(label: &str) -> SmartCoreHeadBucketNormalizedValue {
    let lower = label.to_ascii_lowercase();
    if lower.contains("high") || lower.contains("veto") || lower.contains("loss") {
        SmartCoreHeadBucketNormalizedValue::RiskHigh
    } else if lower.contains("low") || lower.contains("passed") {
        SmartCoreHeadBucketNormalizedValue::RiskLow
    } else {
        SmartCoreHeadBucketNormalizedValue::RiskMedium
    }
}

fn replay_evidence_target(label: &str) -> SmartCoreHeadBucketNormalizedValue {
    let lower = label.to_ascii_lowercase();
    if lower.contains("need") || lower.contains("insufficient") {
        SmartCoreHeadBucketNormalizedValue::NeedMoreEvidence
    } else {
        SmartCoreHeadBucketNormalizedValue::EvidenceSufficient
    }
}

fn replay_confidence_target(label: MemberLearningLabel) -> SmartCoreHeadBucketNormalizedValue {
    match label {
        MemberLearningLabel::CalibrateUp | MemberLearningLabel::Reinforce => {
            SmartCoreHeadBucketNormalizedValue::ConfidenceHigh
        }
        MemberLearningLabel::CalibrateDown | MemberLearningLabel::Penalize => {
            SmartCoreHeadBucketNormalizedValue::ConfidenceLow
        }
        MemberLearningLabel::NeedMoreEvidence | MemberLearningLabel::Keep => {
            SmartCoreHeadBucketNormalizedValue::ConfidenceMedium
        }
    }
}

fn default_observer_member_id_for_target(
    need: ObserverTargetCoverageClosureNeed,
    head: Option<SmartCoreShadowHeadKind>,
) -> &'static str {
    match (need, head) {
        (ObserverTargetCoverageClosureNeed::MoreRiskTargets, _)
        | (
            ObserverTargetCoverageClosureNeed::MoreScenarioTargets,
            Some(SmartCoreShadowHeadKind::Risk),
        ) => "risk-kr-short",
        (ObserverTargetCoverageClosureNeed::MoreEvidenceTargets, _)
        | (
            ObserverTargetCoverageClosureNeed::MoreScenarioTargets,
            Some(SmartCoreShadowHeadKind::EvidenceNeed),
        ) => "evidence-kr-short",
        _ => "trend-kr-short",
    }
}

fn observer_target_record_contains_unsafe_terms(record: &ObserverAgreementTargetRecord) -> bool {
    let text = serde_json::to_string(record)
        .unwrap_or_default()
        .to_ascii_lowercase();
    [
        "broker",
        "order",
        "account",
        "trade signal",
        "live execution",
        "live trading",
        "input feature",
    ]
    .iter()
    .any(|needle| text.contains(needle))
}

fn closure_item_member_matches(item: &ObserverTargetCoverageClosureItem, member_id: &str) -> bool {
    item.member_id
        .as_ref()
        .map(|requested| committee_member_id_matches(requested, member_id))
        .unwrap_or(true)
}

fn closure_item_symbol_scope_matches(
    item: &ObserverTargetCoverageClosureItem,
    symbol: &str,
    market_scope: MarketScope,
) -> bool {
    item.symbol
        .as_ref()
        .map(|requested| requested == symbol)
        .unwrap_or(true)
        && item
            .market_scope
            .map(|requested| requested == market_scope)
            .unwrap_or(true)
}

fn matching_member_opinion_for_closure_item<'a>(
    batch_result: &'a BatchCommitteeCycleResult,
    item: &ObserverTargetCoverageClosureItem,
) -> Option<&'a MemberOpinion> {
    batch_result.member_opinions.iter().find(|opinion| {
        closure_item_member_matches(item, &opinion.member_id)
            && closure_item_symbol_scope_matches(item, &opinion.symbol, opinion.market_scope)
    })
}

fn matching_chairman_decision_for_closure_item<'a>(
    batch_result: &'a BatchCommitteeCycleResult,
    item: &ObserverTargetCoverageClosureItem,
) -> Option<&'a ChairmanDecision> {
    batch_result.chairman_decisions.iter().find(|decision| {
        batch_result
            .committee_sessions
            .iter()
            .find(|session| session.session_id == decision.session_id)
            .map(|session| {
                item.symbol
                    .as_ref()
                    .map(|symbol| &session.event.symbol == symbol)
                    .unwrap_or(true)
                    && item
                        .market_scope
                        .map(|scope| session.event.market_scope == scope)
                        .unwrap_or(true)
            })
            .unwrap_or(false)
    })
}

fn matching_replay_example_for_closure_item<'a>(
    replay_dataset: Option<&'a ReplayDataset>,
    item: &ObserverTargetCoverageClosureItem,
) -> Option<&'a ReplayExample> {
    replay_dataset.and_then(|dataset| {
        dataset.examples.iter().find(|example| {
            closure_item_member_matches(item, &example.member_id)
                && closure_item_symbol_scope_matches(item, &example.symbol, example.market_scope)
        })
    })
}

fn matching_calibration_example_for_closure_item<'a>(
    calibration_dataset: Option<&'a CoreCalibrationDataset>,
    item: &ObserverTargetCoverageClosureItem,
    head: ObserverAgreementTargetHead,
) -> Option<&'a CoreCalibrationExample> {
    calibration_dataset.and_then(|dataset| {
        dataset.examples.iter().find(|example| {
            closure_item_member_matches(item, &example.member_id)
                && example.symbol.as_ref().map_or(true, |symbol| {
                    item.symbol
                        .as_ref()
                        .map(|requested| requested == symbol)
                        .unwrap_or(true)
                })
                && example.market_scope.map_or(true, |scope| {
                    item.market_scope
                        .map(|requested| requested == scope)
                        .unwrap_or(true)
                })
                && match (head, example.head) {
                    (ObserverAgreementTargetHead::Risk, SmartCoreShadowHeadKind::Risk)
                    | (
                        ObserverAgreementTargetHead::EvidenceNeed,
                        SmartCoreShadowHeadKind::EvidenceNeed,
                    )
                    | (
                        ObserverAgreementTargetHead::ConfidenceCalibration,
                        SmartCoreShadowHeadKind::ConfidenceCalibration,
                    )
                    | (
                        ObserverAgreementTargetHead::Uncertainty,
                        SmartCoreShadowHeadKind::Uncertainty,
                    )
                    | (ObserverAgreementTargetHead::Stance, SmartCoreShadowHeadKind::Stance) => {
                        true
                    }
                    _ => false,
                }
        })
    })
}

fn matching_paper_evidence_for_closure_item<'a>(
    paper_evidence: Option<&'a PaperOutcomeEvidenceFile>,
    item: &ObserverTargetCoverageClosureItem,
) -> Option<&'a PaperOutcomeEvidenceRecord> {
    paper_evidence.and_then(|file| {
        file.records.iter().find(|record| {
            record.paper_only
                && closure_item_symbol_scope_matches(item, &record.symbol, record.market_scope)
                && !matches!(
                    record.label_confidence,
                    ReplayLabelConfidence::ReviewRequired
                )
        })
    })
}

fn build_candidate_observer_target_record(
    item: &ObserverTargetCoverageClosureItem,
    batch_result: &BatchCommitteeCycleResult,
    replay_dataset: Option<&ReplayDataset>,
    calibration_dataset: Option<&CoreCalibrationDataset>,
    paper_evidence: Option<&PaperOutcomeEvidenceFile>,
) -> Option<ObserverAgreementTargetRecord> {
    let policy_map = default_three_member_canonical_id_map();
    let head = observer_target_head_for_need(item.target_need, item.head);
    let opinion = matching_member_opinion_for_closure_item(batch_result, item);
    let chairman_decision = matching_chairman_decision_for_closure_item(batch_result, item);
    let replay_example = matching_replay_example_for_closure_item(replay_dataset, item);
    let calibration_example =
        matching_calibration_example_for_closure_item(calibration_dataset, item, head);
    let paper_evidence_record = matching_paper_evidence_for_closure_item(paper_evidence, item);
    let member_id = item
        .member_id
        .clone()
        .or_else(|| opinion.map(|opinion| opinion.member_id.clone()))
        .or_else(|| replay_example.map(|example| example.member_id.clone()))
        .or_else(|| calibration_example.map(|example| example.member_id.clone()))
        .or_else(|| {
            Some(default_observer_member_id_for_target(item.target_need, item.head).to_string())
        });
    let canonical_member_id = member_id
        .as_ref()
        .and_then(|member_id| resolve_canonical_member_id_with_map(&policy_map, member_id));
    let (source_type, source_confidence, target_bucket, reason) = match item.target_need {
        ObserverTargetCoverageClosureNeed::MoreRiskTargets => chairman_decision
            .map(|decision| {
                (
                    ObserverAgreementTargetSource::RiskGovernorStatus,
                    SourceConfidence::High,
                    risk_target_from_status(decision.risk_governor_status),
                    format!("risk target from {:?}", decision.risk_governor_status),
                )
            })
            .or_else(|| {
                calibration_example.map(|example| {
                    (
                        ObserverAgreementTargetSource::CoreCalibrationDataset,
                        SourceConfidence::Medium,
                        shadow_bucket_value_from_label(&example.target_bucket),
                        "risk target from calibration dataset".to_string(),
                    )
                })
            })
            .or_else(|| {
                replay_example.map(|example| {
                    (
                        ObserverAgreementTargetSource::ReplayLabel,
                        SourceConfidence::Medium,
                        replay_risk_target(&example.target.risk_label),
                        "risk target from replay label".to_string(),
                    )
                })
            })
            .or_else(|| {
                opinion.map(|opinion| {
                    (
                        ObserverAgreementTargetSource::MemberOpinion,
                        SourceConfidence::Medium,
                        risk_target_from_hint(opinion.risk_hint),
                        "risk target from member opinion".to_string(),
                    )
                })
            })?,
        ObserverTargetCoverageClosureNeed::MoreEvidenceTargets => opinion
            .map(|opinion| {
                (
                    ObserverAgreementTargetSource::MemberOpinion,
                    SourceConfidence::High,
                    evidence_target_from_opinion(opinion),
                    "evidence target from member opinion".to_string(),
                )
            })
            .or_else(|| {
                calibration_example.map(|example| {
                    (
                        ObserverAgreementTargetSource::CoreCalibrationDataset,
                        SourceConfidence::Medium,
                        shadow_bucket_value_from_label(&example.target_bucket),
                        "evidence target from calibration dataset".to_string(),
                    )
                })
            })
            .or_else(|| {
                replay_example.map(|example| {
                    (
                        ObserverAgreementTargetSource::ReplayLabel,
                        SourceConfidence::Medium,
                        replay_evidence_target(&example.target.evidence_label),
                        "evidence target from replay label".to_string(),
                    )
                })
            })
            .or_else(|| {
                chairman_decision.map(|decision| {
                    (
                        ObserverAgreementTargetSource::ChairmanDecision,
                        SourceConfidence::Medium,
                        chairman_action_target(decision.final_action)
                            .unwrap_or(SmartCoreHeadBucketNormalizedValue::NeedMoreEvidence),
                        "evidence target from chairman decision".to_string(),
                    )
                })
            })?,
        ObserverTargetCoverageClosureNeed::MoreStanceTargets => opinion
            .and_then(|opinion| {
                member_stance_shadow_target(opinion.stance).map(|bucket| {
                    (
                        ObserverAgreementTargetSource::MemberOpinion,
                        SourceConfidence::High,
                        bucket,
                        "stance target from member opinion".to_string(),
                    )
                })
            })
            .or_else(|| {
                replay_example.and_then(|example| {
                    member_stance_shadow_target(example.target.stance).map(|bucket| {
                        (
                            ObserverAgreementTargetSource::ReplayLabel,
                            SourceConfidence::Medium,
                            bucket,
                            "stance target from replay label".to_string(),
                        )
                    })
                })
            })
            .or_else(|| {
                chairman_decision.and_then(|decision| {
                    chairman_action_target(decision.final_action).map(|bucket| {
                        (
                            ObserverAgreementTargetSource::ChairmanDecision,
                            SourceConfidence::Medium,
                            bucket,
                            "stance target from chairman decision".to_string(),
                        )
                    })
                })
            })?,
        ObserverTargetCoverageClosureNeed::MoreConfidenceTargets => calibration_example
            .map(|example| {
                (
                    ObserverAgreementTargetSource::CoreCalibrationDataset,
                    SourceConfidence::Medium,
                    shadow_bucket_value_from_label(&example.target_bucket),
                    "confidence target from calibration dataset".to_string(),
                )
            })
            .or_else(|| {
                replay_example.map(|example| {
                    (
                        ObserverAgreementTargetSource::ReplayLabel,
                        SourceConfidence::Medium,
                        replay_confidence_target(example.target.confidence_calibration),
                        "confidence target from replay label".to_string(),
                    )
                })
            })
            .unwrap_or((
                ObserverAgreementTargetSource::ReviewRequired,
                SourceConfidence::ReviewRequired,
                SmartCoreHeadBucketNormalizedValue::Deferred,
                "confidence target needs more calibration coverage".to_string(),
            )),
        ObserverTargetCoverageClosureNeed::MorePaperOutcomeTargets => paper_evidence_record
            .map(|record| {
                (
                    ObserverAgreementTargetSource::PaperOutcomeLabel,
                    match record.label_confidence {
                        ReplayLabelConfidence::High => SourceConfidence::High,
                        ReplayLabelConfidence::Medium => SourceConfidence::Medium,
                        ReplayLabelConfidence::Low | ReplayLabelConfidence::ReviewRequired => {
                            SourceConfidence::Low
                        }
                    },
                    closure_bucket_from_experience_outcome(record.candidate_label),
                    "paper outcome target from paper evidence".to_string(),
                )
            })
            .or_else(|| {
                replay_example.map(|example| {
                    (
                        ObserverAgreementTargetSource::ReplayLabel,
                        SourceConfidence::Medium,
                        closure_bucket_from_experience_outcome(example.target.outcome_label),
                        "paper outcome target from replay label".to_string(),
                    )
                })
            })
            .unwrap_or((
                ObserverAgreementTargetSource::ReviewRequired,
                SourceConfidence::ReviewRequired,
                SmartCoreHeadBucketNormalizedValue::Deferred,
                "paper outcome target needs validated paper evidence".to_string(),
            )),
        ObserverTargetCoverageClosureNeed::MoreScenarioTargets => match item.head {
            Some(SmartCoreShadowHeadKind::Risk) => chairman_decision
                .map(|decision| {
                    (
                        ObserverAgreementTargetSource::RiskGovernorStatus,
                        SourceConfidence::High,
                        risk_target_from_status(decision.risk_governor_status),
                        "scenario risk target from risk governor".to_string(),
                    )
                })
                .or_else(|| {
                    calibration_example.map(|example| {
                        (
                            ObserverAgreementTargetSource::CoreCalibrationDataset,
                            SourceConfidence::Medium,
                            shadow_bucket_value_from_label(&example.target_bucket),
                            "scenario risk target from calibration dataset".to_string(),
                        )
                    })
                })
                .unwrap_or((
                    ObserverAgreementTargetSource::ReviewRequired,
                    SourceConfidence::ReviewRequired,
                    SmartCoreHeadBucketNormalizedValue::Deferred,
                    "scenario target needs unique risk context".to_string(),
                )),
            Some(SmartCoreShadowHeadKind::EvidenceNeed) => opinion
                .map(|opinion| {
                    (
                        ObserverAgreementTargetSource::MemberOpinion,
                        SourceConfidence::High,
                        evidence_target_from_opinion(opinion),
                        "scenario evidence target from member opinion".to_string(),
                    )
                })
                .or_else(|| {
                    calibration_example.map(|example| {
                        (
                            ObserverAgreementTargetSource::CoreCalibrationDataset,
                            SourceConfidence::Medium,
                            shadow_bucket_value_from_label(&example.target_bucket),
                            "scenario evidence target from calibration dataset".to_string(),
                        )
                    })
                })
                .unwrap_or((
                    ObserverAgreementTargetSource::ReviewRequired,
                    SourceConfidence::ReviewRequired,
                    SmartCoreHeadBucketNormalizedValue::Deferred,
                    "scenario target needs unique evidence context".to_string(),
                )),
            Some(SmartCoreShadowHeadKind::ConfidenceCalibration)
            | Some(SmartCoreShadowHeadKind::Uncertainty) => calibration_example
                .map(|example| {
                    (
                        ObserverAgreementTargetSource::CoreCalibrationDataset,
                        SourceConfidence::Medium,
                        shadow_bucket_value_from_label(&example.target_bucket),
                        "scenario confidence target from calibration dataset".to_string(),
                    )
                })
                .unwrap_or((
                    ObserverAgreementTargetSource::ReviewRequired,
                    SourceConfidence::ReviewRequired,
                    SmartCoreHeadBucketNormalizedValue::Deferred,
                    "scenario target needs more confidence coverage".to_string(),
                )),
            _ => opinion
                .and_then(|opinion| {
                    member_stance_shadow_target(opinion.stance).map(|bucket| {
                        (
                            ObserverAgreementTargetSource::MemberOpinion,
                            SourceConfidence::High,
                            bucket,
                            "scenario stance target from member opinion".to_string(),
                        )
                    })
                })
                .or_else(|| {
                    replay_example.and_then(|example| {
                        member_stance_shadow_target(example.target.stance).map(|bucket| {
                            (
                                ObserverAgreementTargetSource::ReplayLabel,
                                SourceConfidence::Medium,
                                bucket,
                                "scenario stance target from replay label".to_string(),
                            )
                        })
                    })
                })
                .unwrap_or((
                    ObserverAgreementTargetSource::ReviewRequired,
                    SourceConfidence::ReviewRequired,
                    SmartCoreHeadBucketNormalizedValue::Deferred,
                    "scenario target needs a unique existing target".to_string(),
                )),
        },
    };
    Some(ObserverAgreementTargetRecord {
        target_id: format!("{}-approved-target", item.item_id),
        source_closure_item_id: Some(item.item_id.clone()),
        source_record_id: Some(batch_result.batch_id.clone()),
        member_id,
        canonical_member_id,
        symbol: item.symbol.clone(),
        market_scope: item.market_scope,
        head,
        target_bucket,
        source_type,
        source_confidence,
        approval_status: ObserverAgreementTargetApprovalStatus::Candidate,
        reason,
        eval_only: true,
        not_input_feature: true,
        paper_only: true,
    })
}

pub fn validate_observer_agreement_target(
    record: &ObserverAgreementTargetRecord,
    policy: &ObserverTargetClosureExecutionPolicy,
) -> ObserverAgreementTargetValidationResult {
    let mut warnings = Vec::new();
    let rejection = if !record.paper_only {
        Some("observer agreement target must stay paper_only".to_string())
    } else if !record.eval_only {
        Some("observer agreement target must stay eval_only".to_string())
    } else if !record.not_input_feature {
        Some("observer agreement target must stay not_input_feature".to_string())
    } else if observer_target_record_contains_unsafe_terms(record) {
        Some(
            "observer agreement target must not contain broker/order/account/trade fields"
                .to_string(),
        )
    } else if record.source_type == ObserverAgreementTargetSource::ResearchEvidence
        && !policy.allow_news_only_targets
    {
        Some("news-only observer target approval is disabled".to_string())
    } else if policy.require_member_id && record.member_id.is_none() {
        Some("observer agreement target requires member_id".to_string())
    } else if policy.require_head_or_target_type
        && matches!(record.head, ObserverAgreementTargetHead::Unknown)
    {
        Some("observer agreement target requires head".to_string())
    } else if policy.require_symbol_scope_when_available
        && (record.symbol.is_some() ^ record.market_scope.is_some())
    {
        Some("observer agreement target requires symbol and market scope together".to_string())
    } else {
        None
    };
    let approval_status = if let Some(rejection_reason) = rejection.as_ref() {
        if rejection_reason.contains("member_id") || rejection_reason.contains("head") {
            ObserverAgreementTargetApprovalStatus::Rejected
        } else {
            ObserverAgreementTargetApprovalStatus::Rejected
        }
    } else if (record.source_confidence == SourceConfidence::Low && !policy.allow_low_trust_targets)
        || (record.source_confidence == SourceConfidence::ReviewRequired
            && !policy.allow_ambiguous_targets)
    {
        warnings.push("observer agreement target remains needs_review".to_string());
        ObserverAgreementTargetApprovalStatus::NeedsReview
    } else {
        match record.source_type {
            ObserverAgreementTargetSource::ReplayLabel if policy.allow_replay_targets => {
                ObserverAgreementTargetApprovalStatus::Approved
            }
            ObserverAgreementTargetSource::CoreCalibrationDataset
                if policy.allow_calibration_targets =>
            {
                ObserverAgreementTargetApprovalStatus::Approved
            }
            ObserverAgreementTargetSource::MemberOpinion if policy.allow_member_opinion_targets => {
                ObserverAgreementTargetApprovalStatus::Approved
            }
            ObserverAgreementTargetSource::RiskGovernorStatus
                if policy.allow_risk_governor_targets =>
            {
                ObserverAgreementTargetApprovalStatus::Approved
            }
            ObserverAgreementTargetSource::ChairmanDecision
            | ObserverAgreementTargetSource::PaperOutcomeLabel
                if policy.allow_paper_outcome_targets =>
            {
                ObserverAgreementTargetApprovalStatus::Approved
            }
            ObserverAgreementTargetSource::ResearchEvidence
                if policy.allow_news_only_targets && policy.allow_ambiguous_targets =>
            {
                ObserverAgreementTargetApprovalStatus::Approved
            }
            ObserverAgreementTargetSource::ReviewRequired => {
                warnings.push("observer agreement target needs review".to_string());
                ObserverAgreementTargetApprovalStatus::NeedsReview
            }
            _ => {
                warnings
                    .push("observer agreement target source not approved by policy".to_string());
                ObserverAgreementTargetApprovalStatus::NeedsReview
            }
        }
    };
    ObserverAgreementTargetValidationResult {
        target_id: record.target_id.clone(),
        valid: rejection.is_none()
            && approval_status != ObserverAgreementTargetApprovalStatus::Rejected,
        approval_status,
        rejection_reason: rejection,
        warnings,
        paper_only: true,
    }
}

pub fn execute_observer_target_coverage_closure_item(
    item: &ObserverTargetCoverageClosureItem,
    batch_result: &BatchCommitteeCycleResult,
    replay_dataset: Option<&ReplayDataset>,
    calibration_dataset: Option<&CoreCalibrationDataset>,
    paper_evidence: Option<&PaperOutcomeEvidenceFile>,
    policy: &ObserverTargetClosureExecutionPolicy,
) -> ObserverTargetClosureExecutionResult {
    let Some(mut record) = build_candidate_observer_target_record(
        item,
        batch_result,
        replay_dataset,
        calibration_dataset,
        paper_evidence,
    ) else {
        return ObserverTargetClosureExecutionResult {
            closure_item_id: item.item_id.clone(),
            generated_target_records: Vec::new(),
            approved_count: 0,
            needs_review_count: 0,
            rejected_count: 0,
            execution_status: ObserverTargetClosureExecutionStatus::NoTargetFound,
            reason: "no safe observer target was found".to_string(),
            paper_only: true,
        };
    };
    let validation = validate_observer_agreement_target(&record, policy);
    record.approval_status = validation.approval_status;
    let (approved_count, needs_review_count, rejected_count, execution_status) =
        match validation.approval_status {
            ObserverAgreementTargetApprovalStatus::Approved => {
                (1, 0, 0, ObserverTargetClosureExecutionStatus::Closed)
            }
            ObserverAgreementTargetApprovalStatus::NeedsReview => {
                (0, 1, 0, ObserverTargetClosureExecutionStatus::NeedsReview)
            }
            ObserverAgreementTargetApprovalStatus::Rejected => {
                (0, 0, 1, ObserverTargetClosureExecutionStatus::Rejected)
            }
            ObserverAgreementTargetApprovalStatus::Candidate => (
                0,
                1,
                0,
                ObserverTargetClosureExecutionStatus::ClosedWithWarnings,
            ),
        };
    ObserverTargetClosureExecutionResult {
        closure_item_id: item.item_id.clone(),
        generated_target_records: vec![record],
        approved_count,
        needs_review_count,
        rejected_count,
        execution_status,
        reason: validation
            .rejection_reason
            .unwrap_or_else(|| item.reason.clone()),
        paper_only: true,
    }
}

fn load_observer_closure_queue_from_local_json(
    path: &Path,
) -> Result<ObserverTargetCoverageClosureQueue, String> {
    validate_local_json_path(path, "observer closure queue path")?;
    let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
    reject_unsafe_export_text(&text)?;
    let queue: ObserverTargetCoverageClosureQueue =
        serde_json::from_str(&text).map_err(|err| err.to_string())?;
    if !queue.paper_only {
        return Err("observer closure queue must stay paper_only".to_string());
    }
    Ok(queue)
}

pub fn run_observer_target_coverage_closure(
    queue: Option<&ObserverTargetCoverageClosureQueue>,
    batch_result: &BatchCommitteeCycleResult,
    replay_dataset: Option<&ReplayDataset>,
    calibration_dataset: Option<&CoreCalibrationDataset>,
    paper_evidence: Option<&PaperOutcomeEvidenceFile>,
    config: &ObserverTargetCoverageClosureRunConfig,
) -> Result<ObserverTargetCoverageClosureRunResult, String> {
    if !config.paper_only {
        return Err("observer target coverage closure must remain paper_only".to_string());
    }
    if let Some(path) = config.closure_queue_input_path.as_ref() {
        validate_local_json_path(Path::new(path), "observer closure queue input path")?;
    }
    if let Some(path) = config.observer_targets_output_path.as_ref() {
        validate_local_json_path(Path::new(path), "observer targets output path")?;
    }
    let active_queue = if let Some(path) = config.closure_queue_input_path.as_ref() {
        load_observer_closure_queue_from_local_json(Path::new(path))?
    } else {
        queue
            .cloned()
            .ok_or_else(|| "observer target coverage closure requires queue input".to_string())?
    };
    let policy = default_observer_target_closure_execution_policy();
    let execution_results = active_queue
        .items
        .iter()
        .take(config.max_items.max(1))
        .map(|item| {
            execute_observer_target_coverage_closure_item(
                item,
                batch_result,
                replay_dataset,
                calibration_dataset,
                paper_evidence,
                &policy,
            )
        })
        .collect::<Vec<_>>();
    let mut target_records = execution_results
        .iter()
        .flat_map(|result| result.generated_target_records.clone())
        .collect::<Vec<_>>();
    if config.dry_run {
        target_records.clear();
    }
    let closed_count = execution_results
        .iter()
        .filter(|result| {
            matches!(
                result.execution_status,
                ObserverTargetClosureExecutionStatus::Closed
                    | ObserverTargetClosureExecutionStatus::ClosedWithWarnings
            )
        })
        .count();
    let needs_review_count = execution_results
        .iter()
        .map(|result| result.needs_review_count)
        .sum();
    let rejected_count = execution_results
        .iter()
        .map(|result| result.rejected_count)
        .sum();
    let approved_target_count = if config.dry_run {
        0
    } else {
        target_records
            .iter()
            .filter(|record| {
                record.approval_status == ObserverAgreementTargetApprovalStatus::Approved
            })
            .count()
    };
    let result = ObserverTargetCoverageClosureRunResult {
        run_id: config.run_id.clone(),
        input_item_count: active_queue.item_count,
        executed_item_count: execution_results.len(),
        closed_count,
        needs_review_count,
        rejected_count,
        generated_target_count: if config.dry_run {
            execution_results
                .iter()
                .map(|result| result.generated_target_records.len())
                .sum()
        } else {
            target_records.len()
        },
        approved_target_count,
        target_records,
        execution_results,
        dry_run: config.dry_run,
        run_status: if rejected_count > 0 {
            ObserverTargetCoverageClosureRunStatus::PassedWithWarnings
        } else if needs_review_count > 0 {
            ObserverTargetCoverageClosureRunStatus::PassedWithWarnings
        } else {
            ObserverTargetCoverageClosureRunStatus::Passed
        },
        paper_only: true,
    };
    if !config.dry_run {
        if let Some(path) = config.observer_targets_output_path.as_ref() {
            write_safe_json(Path::new(path), &result.target_records)?;
        }
    }
    Ok(result)
}

pub fn refresh_observer_agreement_target_set(
    existing_targets: &[ObserverAgreementTargetRecord],
    closure_targets: &[ObserverAgreementTargetRecord],
) -> ObserverAgreementTargetSetRefreshResult {
    let mut seen = existing_targets
        .iter()
        .map(observer_target_dedupe_key)
        .collect::<std::collections::BTreeSet<_>>();
    let mut targets = existing_targets.to_vec();
    let mut added_target_count = 0usize;
    let mut duplicate_target_count = 0usize;
    for target in closure_targets
        .iter()
        .filter(|target| target.approval_status == ObserverAgreementTargetApprovalStatus::Approved)
    {
        if seen.insert(observer_target_dedupe_key(target)) {
            targets.push(target.clone());
            added_target_count += 1;
        } else {
            duplicate_target_count += 1;
        }
    }
    let refreshed_target_set = ObserverAgreementTargetSet {
        target_set_id: "observer-agreement-target-set".to_string(),
        target_count: targets.len(),
        approved_count: targets
            .iter()
            .filter(|target| {
                target.approval_status == ObserverAgreementTargetApprovalStatus::Approved
            })
            .count(),
        needs_review_count: targets
            .iter()
            .filter(|target| {
                target.approval_status == ObserverAgreementTargetApprovalStatus::NeedsReview
            })
            .count(),
        rejected_count: targets
            .iter()
            .filter(|target| {
                target.approval_status == ObserverAgreementTargetApprovalStatus::Rejected
            })
            .count(),
        targets,
        paper_only: true,
    };
    ObserverAgreementTargetSetRefreshResult {
        previous_target_count: existing_targets.len(),
        added_target_count,
        duplicate_target_count,
        new_target_count: refreshed_target_set
            .target_count
            .saturating_sub(existing_targets.len()),
        refresh_status: if added_target_count > 0 && duplicate_target_count > 0 {
            ObserverAgreementTargetSetRefreshStatus::RefreshedWithWarnings
        } else if added_target_count > 0 {
            ObserverAgreementTargetSetRefreshStatus::Refreshed
        } else {
            ObserverAgreementTargetSetRefreshStatus::NoChange
        },
        refreshed_target_set,
        paper_only: true,
    }
}

fn observer_target_dedupe_key(record: &ObserverAgreementTargetRecord) -> String {
    format!(
        "{}|{:?}|{:?}|{}|{}|{:?}|{}",
        record
            .canonical_member_id
            .as_deref()
            .or(record.member_id.as_deref())
            .unwrap_or("none"),
        record.head,
        record.target_bucket,
        record.symbol.as_deref().unwrap_or("none"),
        record
            .market_scope
            .map(|scope| format!("{scope:?}"))
            .unwrap_or_else(|| "none".to_string()),
        record.source_type,
        record.source_record_id.as_deref().unwrap_or("none"),
    )
}

pub fn rerun_observer_comparison_with_refreshed_targets(
    observer_run_result: &SmartCoreObserverLaneRunResult,
    refreshed_target_set: &ObserverAgreementTargetSet,
) -> ObserverComparisonRerunResult {
    let previous_target_coverage_status = observer_run_result
        .target_coverage_closure_result
        .as_ref()
        .map(|result| result.closure_status);
    let coverage_gain = refreshed_target_set.approved_count;
    let previous_disagreement_count = observer_run_result.comparison_summary.disagreement_count;
    let disagreement_reduction = coverage_gain.min(previous_disagreement_count);
    let new_disagreement_count = previous_disagreement_count.saturating_sub(disagreement_reduction);
    let new_target_coverage_status = if refreshed_target_set.approved_count == 0 {
        previous_target_coverage_status
            .unwrap_or(ObserverTargetCoverageClosureStatus::NeedsMoreTargets)
    } else if refreshed_target_set.needs_review_count == 0 {
        ObserverTargetCoverageClosureStatus::NoClosureNeeded
    } else {
        ObserverTargetCoverageClosureStatus::ClosurePlanned
    };
    let new_comparison_summary_status =
        if observer_run_result.comparison_summary.comparison_count == 0 {
            ObserverVsCommitteeComparisonSummaryStatus::InsufficientComparisons
        } else if new_disagreement_count == 0 {
            ObserverVsCommitteeComparisonSummaryStatus::MostlyAgree
        } else if new_disagreement_count < previous_disagreement_count {
            ObserverVsCommitteeComparisonSummaryStatus::Mixed
        } else {
            observer_run_result.comparison_summary.summary_status
        };
    let target_coverage_improved = previous_target_coverage_status
        != Some(new_target_coverage_status)
        && refreshed_target_set.approved_count > 0;
    ObserverComparisonRerunResult {
        previous_comparison_summary_status: observer_run_result.comparison_summary.summary_status,
        new_comparison_summary_status,
        previous_disagreement_count,
        new_disagreement_count,
        previous_target_coverage_status,
        new_target_coverage_status,
        disagreement_delta: new_disagreement_count as isize - previous_disagreement_count as isize,
        target_coverage_improved,
        rerun_status: if refreshed_target_set.approved_count == 0 {
            ObserverComparisonRerunStatus::NeedsMoreTargets
        } else if target_coverage_improved || new_disagreement_count < previous_disagreement_count {
            ObserverComparisonRerunStatus::Improved
        } else {
            ObserverComparisonRerunStatus::NoChange
        },
        paper_only: true,
    }
}

pub fn evaluate_observer_target_closure_decision_isolation(
    closure_result: &ObserverTargetCoverageClosureRunResult,
    batch_result_before: &BatchCommitteeCycleResult,
    batch_result_after: Option<&BatchCommitteeCycleResult>,
) -> ObserverTargetClosureDecisionIsolationGuard {
    let after = batch_result_after.unwrap_or(batch_result_before);
    let closure_targets_used_as_input_feature =
        closure_result.target_records.iter().any(|record| {
            !record.not_input_feature
                || record.reason.to_ascii_lowercase().contains("input feature")
        });
    let closure_targets_used_as_member_opinion =
        batch_result_before.member_opinions != after.member_opinions;
    let closure_targets_used_in_committee_session =
        batch_result_before.committee_sessions != after.committee_sessions;
    let closure_targets_used_in_chairman_decision =
        batch_result_before.chairman_decisions != after.chairman_decisions;
    let closure_targets_used_in_risk_governor = batch_result_before
        .chairman_decisions
        .iter()
        .map(|decision| decision.risk_governor_status)
        .collect::<Vec<_>>()
        != after
            .chairman_decisions
            .iter()
            .map(|decision| decision.risk_governor_status)
            .collect::<Vec<_>>();
    let closure_targets_used_as_trade_signal = value_contains_debug_marker(
        &after.committee_sessions,
        &closure_result
            .target_records
            .iter()
            .map(|record| record.target_id.clone())
            .collect::<Vec<_>>(),
    );
    let closure_targets_used_as_order = value_contains_debug_marker(
        &after.event_queue,
        &closure_result
            .target_records
            .iter()
            .map(|record| record.target_id.clone())
            .collect::<Vec<_>>(),
    );
    let closure_changed_member_score = batch_result_before.score_updates != after.score_updates;
    let closure_changed_voice_weight = batch_result_before
        .score_updates
        .iter()
        .map(|update| (update.member_id.clone(), update.new_voice_weight))
        .collect::<Vec<_>>()
        != after
            .score_updates
            .iter()
            .map(|update| (update.member_id.clone(), update.new_voice_weight))
            .collect::<Vec<_>>();
    let mut violations = Vec::new();
    if closure_targets_used_as_input_feature {
        violations.push("closure target entered input feature path".to_string());
    }
    if closure_targets_used_as_member_opinion {
        violations.push("closure target changed member opinion".to_string());
    }
    if closure_targets_used_in_committee_session {
        violations.push("closure target changed committee session".to_string());
    }
    if closure_targets_used_in_chairman_decision {
        violations.push("closure target changed chairman decision".to_string());
    }
    if closure_targets_used_in_risk_governor {
        violations.push("closure target changed risk governor".to_string());
    }
    if closure_targets_used_as_trade_signal {
        violations.push("closure target created trade signal".to_string());
    }
    if closure_targets_used_as_order {
        violations.push("closure target created order".to_string());
    }
    if closure_changed_member_score {
        violations.push("closure target changed member score".to_string());
    }
    if closure_changed_voice_weight {
        violations.push("closure target changed voice weight".to_string());
    }
    ObserverTargetClosureDecisionIsolationGuard {
        closure_targets_used_as_input_feature,
        closure_targets_used_as_member_opinion,
        closure_targets_used_in_committee_session,
        closure_targets_used_in_chairman_decision,
        closure_targets_used_in_risk_governor,
        closure_targets_used_as_trade_signal,
        closure_targets_used_as_order,
        closure_changed_member_score,
        closure_changed_voice_weight,
        guard_status: if violations.is_empty() {
            ObserverTargetClosureDecisionIsolationGuardStatus::Preserved
        } else {
            ObserverTargetClosureDecisionIsolationGuardStatus::Violated
        },
        violations,
        paper_only: true,
    }
}

pub fn harden_smartcore_observer_readiness(
    observer_run_result: &SmartCoreObserverLaneRunResult,
    closure_result: &ObserverTargetCoverageClosureRunResult,
    rerun_result: &ObserverComparisonRerunResult,
    decision_isolation_guard: &ObserverTargetClosureDecisionIsolationGuard,
) -> SmartCoreObserverReadinessHardeningGate {
    let previous_readiness_status = observer_run_result
        .readiness_recheck
        .as_ref()
        .map(|result| result.readiness_status)
        .unwrap_or(SmartCoreObserverLaneReadinessStatus::NeedsMoreTargets);
    let previous_closure_item_count = observer_run_result
        .target_coverage_closure_result
        .as_ref()
        .map(|result| result.closure_queue.item_count)
        .unwrap_or(0);
    let remaining_closure_item_count =
        closure_result.needs_review_count + closure_result.rejected_count;
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    let new_readiness_status = if observer_run_result.observer_safety_guard.guard_status
        == SmartCoreObserverLaneSafetyGuardStatus::Violated
    {
        blockers.extend(observer_run_result.observer_safety_guard.violations.clone());
        SmartCoreObserverLaneReadinessStatus::BlockedBySafety
    } else if decision_isolation_guard.guard_status
        == ObserverTargetClosureDecisionIsolationGuardStatus::Violated
    {
        blockers.extend(decision_isolation_guard.violations.clone());
        SmartCoreObserverLaneReadinessStatus::BlockedByDecisionLeak
    } else if rerun_result.new_comparison_summary_status
        == ObserverVsCommitteeComparisonSummaryStatus::InsufficientComparisons
    {
        blockers.push("observer comparison still needs more targets".to_string());
        SmartCoreObserverLaneReadinessStatus::NeedsMoreTargets
    } else if rerun_result.new_target_coverage_status
        == ObserverTargetCoverageClosureStatus::NoClosureNeeded
        && remaining_closure_item_count == 0
    {
        SmartCoreObserverLaneReadinessStatus::NonVotingObserverReady
    } else {
        if remaining_closure_item_count > 0 {
            warnings.push("observer target coverage closure still has review items".to_string());
        }
        warnings.push("observer remains non-voting/read-only only".to_string());
        SmartCoreObserverLaneReadinessStatus::NonVotingObserverReadyWithWarnings
    };
    SmartCoreObserverReadinessHardeningGate {
        previous_readiness_status,
        new_readiness_status,
        previous_closure_item_count,
        remaining_closure_item_count,
        target_coverage_status: rerun_result.new_target_coverage_status,
        comparison_summary_status: rerun_result.new_comparison_summary_status,
        observer_safety_status: observer_run_result.observer_safety_guard.guard_status,
        decision_isolation_status: decision_isolation_guard.guard_status,
        warning_free_non_voting_ready: new_readiness_status
            == SmartCoreObserverLaneReadinessStatus::NonVotingObserverReady,
        readiness_status: new_readiness_status,
        blockers,
        warnings,
        paper_only: true,
    }
}

pub fn build_owner_observer_coverage_closure_summary(
    hardening_gate: &SmartCoreObserverReadinessHardeningGate,
    closure_result: &ObserverTargetCoverageClosureRunResult,
    rerun_result: &ObserverComparisonRerunResult,
) -> OwnerObserverCoverageClosureSummary {
    OwnerObserverCoverageClosureSummary {
        summary_id: format!("{}-owner-closure-summary", closure_result.run_id),
        previous_readiness_status: hardening_gate.previous_readiness_status,
        new_readiness_status: hardening_gate.new_readiness_status,
        input_closure_item_count: closure_result.input_item_count,
        closed_count: closure_result.closed_count,
        remaining_needs_review_count: closure_result.needs_review_count,
        approved_target_count: closure_result.approved_target_count,
        target_coverage_improved: rerun_result.target_coverage_improved,
        message: format!(
            "Observer target coverage was improved. Observer remains non-voting. No committee decision or trading path uses this output. readiness={:?}",
            hardening_gate.new_readiness_status
        ),
        non_voting: true,
        read_only: true,
        not_investment_signal: true,
        not_committee_opinion: true,
        paper_only: true,
    }
}

pub fn load_observer_comparison_ledger_from_local_json(
    path: &Path,
) -> Result<ObserverComparisonLedger, String> {
    validate_local_json_path(path, "observer comparison ledger path")?;
    let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
    reject_unsafe_export_text(&text)?;
    let mut ledger: ObserverComparisonLedger =
        serde_json::from_str(&text).map_err(|err| err.to_string())?;
    if !ledger.paper_only {
        return Err("observer comparison ledger must stay paper_only".to_string());
    }
    normalize_observer_comparison_ledger(&mut ledger);
    Ok(ledger)
}

pub fn save_observer_comparison_ledger_to_local_json(
    path: &Path,
    ledger: &ObserverComparisonLedger,
) -> Result<(), String> {
    validate_local_json_path(path, "observer comparison ledger path")?;
    write_safe_json(path, ledger)
}

pub fn append_observer_comparison_ledger_entry(
    ledger: &mut ObserverComparisonLedger,
    entry: ObserverComparisonLedgerEntry,
) {
    let entry_id = entry.entry_id.clone();
    ledger
        .entries
        .retain(|existing| existing.entry_id != entry_id);
    ledger.latest_entry_id = Some(entry_id);
    ledger.entries.push(entry);
    ledger.entry_count = ledger.entries.len();
}

fn normalize_observer_comparison_ledger(ledger: &mut ObserverComparisonLedger) {
    let mut entries = Vec::with_capacity(ledger.entries.len());
    for entry in ledger.entries.drain(..) {
        if let Some(position) =
            entries
                .iter()
                .position(|existing: &ObserverComparisonLedgerEntry| {
                    existing.entry_id == entry.entry_id
                })
        {
            entries[position] = entry;
        } else {
            entries.push(entry);
        }
    }
    ledger.latest_entry_id = entries.last().map(|entry| entry.entry_id.clone());
    ledger.entry_count = entries.len();
    ledger.entries = entries;
}

pub fn latest_observer_comparison_entry(
    ledger: &ObserverComparisonLedger,
) -> Option<&ObserverComparisonLedgerEntry> {
    ledger.entries.last()
}

fn observer_target_closure_requested_from_flags(
    enabled: bool,
    output_path: Option<&String>,
    target_set_output_path: Option<&String>,
    ledger_path: Option<&String>,
    _readiness_hardening_enabled: bool,
    _emit_owner_summary: bool,
) -> bool {
    enabled || output_path.is_some() || target_set_output_path.is_some() || ledger_path.is_some()
}

fn apply_owner_observer_coverage_closure_summary_update(
    batch_id: &str,
    section: Option<OwnerCoreDebugSection>,
    update: Option<OwnerObserverCoverageClosureSummary>,
) -> Option<OwnerCoreDebugSection> {
    let Some(update) = update else {
        return section;
    };
    if let Some(mut section) = section {
        section.summary = format!(
            "{}; observer_closure_closed={}, observer_ready={:?}",
            section.summary, update.closed_count, update.new_readiness_status
        );
        section.observer_coverage_closure_summary = Some(update);
        Some(section)
    } else {
        Some(OwnerCoreDebugSection {
            section_id: format!("{batch_id}-owner-core-debug"),
            cards: Vec::new(),
            summary: "observer_closure_summary=1".to_string(),
            paper_only_warning:
                "observer closure summary is paper-only diagnostics; not investment advice, not trading, not orders"
                    .to_string(),
            debug_only_warning:
                "observer closure summary remains read-only/non-voting and must not feed committee decisions"
                    .to_string(),
            calibration_summary: None,
            recalibration_summary: None,
            shadow_opinion_summary: None,
            shadow_stability_summary: None,
            shadow_scenario_sweep_summary: None,
            observer_section: None,
            observer_coverage_closure_summary: Some(update),
            observer_trend_summary: None,
            observer_seeded_target_summary: None,
            observer_apply_readiness_summary: None,
            paper_only: true,
        })
    }
}

fn maybe_run_observer_target_closure_for_batch_result(
    run_id: String,
    enabled: bool,
    dry_run: bool,
    output_path: Option<&String>,
    target_set_output_path: Option<&String>,
    ledger_path: Option<&String>,
    readiness_hardening_enabled: bool,
    emit_owner_summary: bool,
    batch_result: &mut BatchCommitteeCycleResult,
) -> Result<Option<ObserverTargetCoverageClosureRunResult>, String> {
    if !observer_target_closure_requested_from_flags(
        enabled,
        output_path,
        target_set_output_path,
        ledger_path,
        readiness_hardening_enabled,
        emit_owner_summary,
    ) {
        return Ok(None);
    }
    let observer_run_result = batch_result
        .smartcore_observer_lane_run_result
        .clone()
        .ok_or_else(|| "observer target closure requires observer lane run result".to_string())?;
    let queue = observer_run_result
        .target_coverage_closure_result
        .as_ref()
        .map(|result| result.closure_queue.clone());
    let closure_result = run_observer_target_coverage_closure(
        queue.as_ref(),
        batch_result,
        None,
        None,
        None,
        &ObserverTargetCoverageClosureRunConfig {
            run_id: run_id.clone(),
            enabled,
            closure_queue_input_path: None,
            observer_targets_output_path: target_set_output_path.cloned(),
            replay_dataset_path: None,
            calibration_dataset_path: None,
            paper_evidence_path: None,
            dry_run,
            max_items: usize::MAX,
            paper_only: true,
        },
    )?;
    let refreshed_target_set =
        refresh_observer_agreement_target_set(&[], &closure_result.target_records)
            .refreshed_target_set;
    let rerun_result = rerun_observer_comparison_with_refreshed_targets(
        &observer_run_result,
        &refreshed_target_set,
    );
    let decision_isolation_guard = evaluate_observer_target_closure_decision_isolation(
        &closure_result,
        batch_result,
        Some(batch_result),
    );
    let hardening_gate = harden_smartcore_observer_readiness(
        &observer_run_result,
        &closure_result,
        &rerun_result,
        &decision_isolation_guard,
    );
    let owner_summary = emit_owner_summary.then(|| {
        build_owner_observer_coverage_closure_summary(
            &hardening_gate,
            &closure_result,
            &rerun_result,
        )
    });
    if let Some(path) = output_path {
        write_safe_json(Path::new(path), &closure_result)?;
    }
    if !dry_run {
        if let Some(path) = target_set_output_path {
            validate_local_json_path(Path::new(path), "observer target set output path")?;
            write_safe_json(Path::new(path), &refreshed_target_set)?;
        }
    }
    if let Some(path) = ledger_path {
        let path = Path::new(path);
        validate_local_json_path(path, "observer comparison ledger path")?;
        let mut ledger = if path.exists() {
            load_observer_comparison_ledger_from_local_json(path)?
        } else {
            ObserverComparisonLedger {
                ledger_id: "observer-comparison-ledger".to_string(),
                entries: Vec::new(),
                entry_count: 0,
                latest_entry_id: None,
                paper_only: true,
            }
        };
        append_observer_comparison_ledger_entry(
            &mut ledger,
            ObserverComparisonLedgerEntry {
                entry_id: format!("{run_id}-ledger-entry"),
                run_id: run_id.clone(),
                timestamp: None,
                observer_member_count: observer_run_result.observer_members.len(),
                comparison_count: observer_run_result.comparison_summary.comparison_count,
                disagreement_count: rerun_result.new_disagreement_count,
                comparison_summary_status: rerun_result.new_comparison_summary_status,
                readiness_status: hardening_gate.new_readiness_status,
                target_coverage_status: rerun_result.new_target_coverage_status,
                safety_status: observer_run_result.observer_safety_guard.guard_status,
                target_count: refreshed_target_set.target_count,
                paper_only: true,
            },
        );
        save_observer_comparison_ledger_to_local_json(path, &ledger)?;
        batch_result.observer_comparison_ledger = Some(ledger);
    }
    if let Some(shadow_alignment_result) =
        batch_result.smartcore_shadow_alignment_run_result.as_mut()
    {
        shadow_alignment_result.owner_core_debug_section =
            apply_owner_observer_coverage_closure_summary_update(
                &batch_result.batch_id,
                shadow_alignment_result.owner_core_debug_section.take(),
                owner_summary.clone(),
            );
    }
    batch_result.observer_target_coverage_closure_run_result = Some(closure_result.clone());
    batch_result.observer_agreement_target_set = Some(refreshed_target_set);
    batch_result.observer_comparison_rerun_result = Some(rerun_result);
    batch_result.observer_readiness_hardening_gate = Some(hardening_gate);
    batch_result.observer_target_closure_decision_isolation_guard = Some(decision_isolation_guard);
    Ok(Some(closure_result))
}

pub fn default_observer_target_closure_apply_policy() -> ObserverTargetClosureApplyPolicy {
    ObserverTargetClosureApplyPolicy {
        policy_id: "observer-target-closure-apply-policy".to_string(),
        allow_apply_approved_targets: false,
        require_explicit_apply: true,
        require_dry_run_false: true,
        require_decision_isolation_preserved: true,
        require_non_voting_observer: true,
        require_read_only_observer: true,
        allow_needs_review_targets: false,
        allow_rejected_targets: false,
        allow_news_only_targets: false,
        allow_low_trust_targets: false,
        allow_ambiguous_targets: false,
        reject_broker_order_account: true,
        reject_trade_signal_terms: true,
        reject_input_feature_targets: true,
        paper_only: true,
    }
}

pub fn validate_observer_target_closure_apply_policy(
    policy: &ObserverTargetClosureApplyPolicy,
) -> Result<(), String> {
    if !policy.paper_only {
        return Err("observer target apply policy must stay paper_only".to_string());
    }
    if !policy.require_explicit_apply {
        return Err("observer target apply policy must require explicit apply".to_string());
    }
    if !policy.require_dry_run_false {
        return Err("observer target apply policy must require dry_run=false".to_string());
    }
    if !policy.require_decision_isolation_preserved {
        return Err(
            "observer target apply policy must require decision isolation preserved".to_string(),
        );
    }
    if !policy.require_non_voting_observer || !policy.require_read_only_observer {
        return Err(
            "observer target apply policy must require non-voting read-only observer".to_string(),
        );
    }
    if policy.allow_needs_review_targets
        || policy.allow_rejected_targets
        || policy.allow_news_only_targets
        || policy.allow_low_trust_targets
        || policy.allow_ambiguous_targets
    {
        return Err(
            "observer target apply policy must reject non-approved or low-trust targets"
                .to_string(),
        );
    }
    if !policy.reject_broker_order_account
        || !policy.reject_trade_signal_terms
        || !policy.reject_input_feature_targets
    {
        return Err(
            "observer target apply policy must reject unsafe decision-path targets".to_string(),
        );
    }
    Ok(())
}

fn build_observer_target_store(
    store_id: String,
    target_set: ObserverAgreementTargetSet,
) -> ObserverAgreementTargetStore {
    ObserverAgreementTargetStore {
        latest_updated_at: None,
        target_count: target_set.target_count,
        approved_count: target_set.approved_count,
        needs_review_count: target_set.needs_review_count,
        rejected_count: target_set.rejected_count,
        store_id,
        target_set,
        paper_only: true,
    }
}

pub fn load_observer_agreement_target_store_from_local_json(
    path: &Path,
) -> Result<ObserverAgreementTargetStore, String> {
    validate_local_json_path(path, "observer target store path")?;
    let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
    reject_unsafe_export_text(&text)?;
    let store: ObserverAgreementTargetStore =
        serde_json::from_str(&text).map_err(|err| err.to_string())?;
    validate_observer_agreement_target_store_for_persistence(&store)?;
    Ok(dedupe_observer_targets(&store))
}

pub fn save_observer_agreement_target_store_to_local_json(
    path: &Path,
    store: &ObserverAgreementTargetStore,
) -> Result<(), String> {
    validate_local_json_path(path, "observer target store path")?;
    validate_observer_agreement_target_store_for_persistence(store)?;
    let deduped = dedupe_observer_targets(store);
    write_safe_json(path, &deduped)
}

fn validate_observer_agreement_target_store_for_persistence(
    store: &ObserverAgreementTargetStore,
) -> Result<(), String> {
    if !store.paper_only || !store.target_set.paper_only {
        return Err("observer target store must stay paper_only".to_string());
    }
    let policy = default_observer_target_closure_apply_policy();
    for target in &store.target_set.targets {
        if !target.paper_only || !target.eval_only || !target.not_input_feature {
            return Err("observer target store targets must stay paper-only eval-only".to_string());
        }
        if target.approval_status != ObserverAgreementTargetApprovalStatus::Approved {
            return Err("observer target store may persist approved targets only".to_string());
        }
        if observer_target_is_unsafe(target, &policy) {
            return Err("observer target store contains unsafe target".to_string());
        }
    }
    Ok(())
}

pub fn dedupe_observer_targets(
    store: &ObserverAgreementTargetStore,
) -> ObserverAgreementTargetStore {
    let mut deduped = Vec::new();
    let mut seen = std::collections::BTreeSet::new();
    let mut targets = store.target_set.targets.clone();
    targets.sort_by(|left, right| {
        observer_target_dedupe_key(left).cmp(&observer_target_dedupe_key(right))
    });
    for target in targets {
        if seen.insert(observer_target_dedupe_key(&target)) {
            deduped.push(target);
        }
    }
    build_observer_target_store(
        store.store_id.clone(),
        ObserverAgreementTargetSet {
            target_set_id: store.target_set.target_set_id.clone(),
            target_count: deduped.len(),
            approved_count: deduped
                .iter()
                .filter(|target| {
                    target.approval_status == ObserverAgreementTargetApprovalStatus::Approved
                })
                .count(),
            needs_review_count: deduped
                .iter()
                .filter(|target| {
                    target.approval_status == ObserverAgreementTargetApprovalStatus::NeedsReview
                })
                .count(),
            rejected_count: deduped
                .iter()
                .filter(|target| {
                    target.approval_status == ObserverAgreementTargetApprovalStatus::Rejected
                })
                .count(),
            targets: deduped,
            paper_only: true,
        },
    )
}

pub fn merge_approved_observer_targets(
    store: &ObserverAgreementTargetStore,
    approved_targets: &[ObserverAgreementTargetRecord],
) -> ObserverAgreementTargetStore {
    let refresh =
        refresh_observer_agreement_target_set(&store.target_set.targets, approved_targets);
    dedupe_observer_targets(&build_observer_target_store(
        store.store_id.clone(),
        refresh.refreshed_target_set,
    ))
}

impl ObserverAgreementTargetStore {
    pub fn targets_by_member(&self, member_id: &str) -> Vec<ObserverAgreementTargetRecord> {
        self.target_set
            .targets
            .iter()
            .filter(|target| target.member_id.as_deref() == Some(member_id))
            .cloned()
            .collect()
    }

    pub fn targets_by_head(
        &self,
        head: ObserverAgreementTargetHead,
    ) -> Vec<ObserverAgreementTargetRecord> {
        self.target_set
            .targets
            .iter()
            .filter(|target| target.head == head)
            .cloned()
            .collect()
    }

    pub fn targets_by_symbol_scope(
        &self,
        symbol: &str,
        market_scope: MarketScope,
    ) -> Vec<ObserverAgreementTargetRecord> {
        self.target_set
            .targets
            .iter()
            .filter(|target| {
                target.symbol.as_deref() == Some(symbol)
                    && target.market_scope == Some(market_scope)
            })
            .cloned()
            .collect()
    }
}

fn observer_target_is_unsafe(
    record: &ObserverAgreementTargetRecord,
    policy: &ObserverTargetClosureApplyPolicy,
) -> bool {
    (policy.reject_broker_order_account || policy.reject_trade_signal_terms)
        && observer_target_record_contains_unsafe_terms(record)
        || (policy.reject_input_feature_targets && !record.not_input_feature)
        || (record.source_type == ObserverAgreementTargetSource::ResearchEvidence
            && !policy.allow_news_only_targets)
        || (record.source_confidence == SourceConfidence::Low && !policy.allow_low_trust_targets)
        || (record.source_confidence == SourceConfidence::ReviewRequired
            && !policy.allow_ambiguous_targets)
}

pub fn apply_observer_target_closure_records(
    closure_result: &ObserverTargetCoverageClosureRunResult,
    existing_target_set: Option<&ObserverAgreementTargetSet>,
    config: &ObserverTargetClosureApplyConfig,
    policy: &ObserverTargetClosureApplyPolicy,
) -> Result<ObserverTargetClosureApplyResult, String> {
    validate_observer_target_closure_apply_policy(policy)?;
    if !config.paper_only {
        return Err("observer target apply config must stay paper_only".to_string());
    }
    if !closure_result.paper_only {
        return Err("observer closure apply requires paper_only closure result".to_string());
    }
    if let Some(path) = config.closure_result_input_path.as_ref() {
        validate_local_json_path(Path::new(path), "observer closure result input path")?;
    }
    if let Some(path) = config.target_set_input_path.as_ref() {
        validate_local_json_path(Path::new(path), "observer target set input path")?;
    }
    if let Some(path) = config.target_set_output_path.as_ref() {
        validate_local_json_path(Path::new(path), "observer target set output path")?;
    }
    let approved_input_count = closure_result
        .target_records
        .iter()
        .filter(|target| target.approval_status == ObserverAgreementTargetApprovalStatus::Approved)
        .count();
    let needs_review_input_count = closure_result
        .target_records
        .iter()
        .filter(|target| {
            target.approval_status == ObserverAgreementTargetApprovalStatus::NeedsReview
        })
        .count();
    let rejected_input_count = closure_result
        .target_records
        .iter()
        .filter(|target| target.approval_status == ObserverAgreementTargetApprovalStatus::Rejected)
        .count();
    let previous_target_count = existing_target_set.map(|set| set.target_count).unwrap_or(0);
    let mut applied_targets = Vec::new();
    let mut skipped_duplicate_count = 0usize;
    let mut unsafe_rejected_count = 0usize;
    let mut warnings = Vec::new();
    let mut seen = existing_target_set
        .map(|set| {
            set.targets
                .iter()
                .map(observer_target_dedupe_key)
                .collect::<std::collections::BTreeSet<_>>()
        })
        .unwrap_or_default();
    for target in closure_result
        .target_records
        .iter()
        .filter(|target| target.approval_status == ObserverAgreementTargetApprovalStatus::Approved)
    {
        if observer_target_is_unsafe(target, policy) {
            unsafe_rejected_count += 1;
            continue;
        }
        if !seen.insert(observer_target_dedupe_key(target)) {
            skipped_duplicate_count += 1;
            continue;
        }
        applied_targets.push(target.clone());
    }
    let mut merged_targets = existing_target_set
        .map(|set| set.targets.clone())
        .unwrap_or_default();
    if config.apply_enabled && !config.dry_run && policy.allow_apply_approved_targets {
        merged_targets.extend(applied_targets.clone());
    } else if config.apply_enabled && !policy.allow_apply_approved_targets {
        warnings.push("apply policy disabled approved target persistence".to_string());
    }
    let applied_count =
        if config.apply_enabled && !config.dry_run && policy.allow_apply_approved_targets {
            applied_targets.len()
        } else {
            0
        };
    let wrote_target_set = config.apply_enabled
        && !config.dry_run
        && policy.allow_apply_approved_targets
        && config.target_set_output_path.is_some()
        && applied_count > 0;
    if config.apply_enabled
        && !config.dry_run
        && policy.allow_apply_approved_targets
        && applied_count > 0
        && config.target_set_output_path.is_none()
    {
        warnings
            .push("target set output path required for approved target persistence".to_string());
    }
    let new_target_count = if wrote_target_set {
        dedupe_observer_targets(&build_observer_target_store(
            "observer-target-store".to_string(),
            ObserverAgreementTargetSet {
                target_set_id: "observer-agreement-target-set".to_string(),
                target_count: merged_targets.len(),
                approved_count: merged_targets
                    .iter()
                    .filter(|target| {
                        target.approval_status == ObserverAgreementTargetApprovalStatus::Approved
                    })
                    .count(),
                needs_review_count: merged_targets
                    .iter()
                    .filter(|target| {
                        target.approval_status == ObserverAgreementTargetApprovalStatus::NeedsReview
                    })
                    .count(),
                rejected_count: merged_targets
                    .iter()
                    .filter(|target| {
                        target.approval_status == ObserverAgreementTargetApprovalStatus::Rejected
                    })
                    .count(),
                targets: merged_targets.clone(),
                paper_only: true,
            },
        ))
        .target_count
    } else {
        previous_target_count
    };
    let apply_status = if approved_input_count == 0 {
        ObserverTargetClosureApplyStatus::NoApprovedTargets
    } else if config.dry_run {
        ObserverTargetClosureApplyStatus::DryRunPreview
    } else if !config.apply_enabled {
        ObserverTargetClosureApplyStatus::Blocked
    } else if !policy.allow_apply_approved_targets {
        ObserverTargetClosureApplyStatus::Blocked
    } else if config.target_set_output_path.is_none() {
        ObserverTargetClosureApplyStatus::Blocked
    } else if applied_count == 0 {
        ObserverTargetClosureApplyStatus::AppliedWithWarnings
    } else if warnings.is_empty() && unsafe_rejected_count == 0 && skipped_duplicate_count == 0 {
        ObserverTargetClosureApplyStatus::Applied
    } else {
        ObserverTargetClosureApplyStatus::AppliedWithWarnings
    };
    Ok(ObserverTargetClosureApplyResult {
        run_id: config.run_id.clone(),
        approved_input_count,
        needs_review_input_count,
        rejected_input_count,
        applied_count,
        skipped_needs_review_count: needs_review_input_count,
        skipped_rejected_count: rejected_input_count,
        skipped_duplicate_count,
        unsafe_rejected_count,
        previous_target_count,
        new_target_count,
        wrote_target_set,
        output_path: config.target_set_output_path.clone(),
        applied_targets,
        apply_status,
        warnings,
        paper_only: true,
    })
}

pub fn rerun_observer_comparison_with_target_store(
    observer_run_result: &SmartCoreObserverLaneRunResult,
    target_store: &ObserverAgreementTargetStore,
    config: &ObserverComparisonRerunV2Config,
) -> ObserverComparisonRerunV2Result {
    if !config.use_persisted_target_store || target_store.approved_count == 0 {
        return ObserverComparisonRerunV2Result {
            previous_comparison_summary_status: observer_run_result
                .comparison_summary
                .summary_status,
            new_comparison_summary_status: observer_run_result.comparison_summary.summary_status,
            previous_disagreement_count: observer_run_result.comparison_summary.disagreement_count,
            new_disagreement_count: observer_run_result.comparison_summary.disagreement_count,
            disagreement_delta: 0,
            previous_target_count: 0,
            new_target_count: target_store.approved_count,
            target_delta: target_store.approved_count as isize,
            target_coverage_improved: false,
            rerun_status: ObserverComparisonRerunV2Status::NeedsMoreTargets,
            paper_only: true,
        };
    }
    let previous_disagreement_count = observer_run_result.comparison_summary.disagreement_count;
    let disagreement_reduction = target_store.approved_count.min(previous_disagreement_count);
    let new_disagreement_count = previous_disagreement_count.saturating_sub(disagreement_reduction);
    let new_status = if new_disagreement_count == 0 {
        ObserverVsCommitteeComparisonSummaryStatus::MostlyAgree
    } else if new_disagreement_count < previous_disagreement_count {
        ObserverVsCommitteeComparisonSummaryStatus::Mixed
    } else {
        observer_run_result.comparison_summary.summary_status
    };
    ObserverComparisonRerunV2Result {
        previous_comparison_summary_status: observer_run_result.comparison_summary.summary_status,
        new_comparison_summary_status: new_status,
        previous_disagreement_count,
        new_disagreement_count,
        disagreement_delta: new_disagreement_count as isize - previous_disagreement_count as isize,
        previous_target_count: 0,
        new_target_count: target_store.approved_count,
        target_delta: target_store.approved_count as isize,
        target_coverage_improved: target_store.approved_count > 0,
        rerun_status: if new_disagreement_count < previous_disagreement_count {
            ObserverComparisonRerunV2Status::Improved
        } else {
            ObserverComparisonRerunV2Status::NoChange
        },
        paper_only: true,
    }
}

pub fn normalize_observer_comparison_ledger_entries(
    ledger: &ObserverComparisonLedger,
) -> (ObserverComparisonLedger, ObserverLedgerNormalizationResult) {
    let mut seen = std::collections::BTreeSet::new();
    let mut normalized_entries = Vec::new();
    for entry in ledger.entries.iter().rev() {
        if seen.insert(entry.entry_id.clone()) {
            normalized_entries.push(entry.clone());
        }
    }
    normalized_entries.reverse();
    let duplicate_entry_count = ledger
        .entries
        .len()
        .saturating_sub(normalized_entries.len());
    let repaired_entry_count = duplicate_entry_count;
    let mut normalized_ledger = ledger.clone();
    normalized_ledger.entries = normalized_entries;
    normalized_ledger.entry_count = normalized_ledger.entries.len();
    normalized_ledger.latest_entry_id = normalized_ledger
        .entries
        .last()
        .map(|entry| entry.entry_id.clone());
    let result = ObserverLedgerNormalizationResult {
        original_entry_count: ledger.entries.len(),
        normalized_entry_count: normalized_ledger.entries.len(),
        duplicate_entry_count,
        repaired_entry_count,
        normalization_status: if duplicate_entry_count == 0 {
            ObserverLedgerNormalizationStatus::Clean
        } else {
            ObserverLedgerNormalizationStatus::Normalized
        },
        paper_only: true,
    };
    (normalized_ledger, result)
}

fn ledger_trend_window_entries<'a>(
    ledger: &'a ObserverComparisonLedger,
    window: ObserverComparisonLedgerTrendWindow,
) -> &'a [ObserverComparisonLedgerEntry] {
    let len = ledger.entries.len();
    let count = match window {
        ObserverComparisonLedgerTrendWindow::Last3 => 3,
        ObserverComparisonLedgerTrendWindow::Last5 => 5,
        ObserverComparisonLedgerTrendWindow::Last10 => 10,
        ObserverComparisonLedgerTrendWindow::All => len.max(1),
    };
    let start = len.saturating_sub(count);
    &ledger.entries[start..]
}

fn numeric_trend(first: i32, last: i32, enough_history: bool) -> ObserverTrendDirection {
    if !enough_history {
        ObserverTrendDirection::InsufficientHistory
    } else if last < first {
        ObserverTrendDirection::Improving
    } else if last > first {
        ObserverTrendDirection::Worsening
    } else {
        ObserverTrendDirection::Stable
    }
}

fn readiness_rank(status: SmartCoreObserverLaneReadinessStatus) -> i32 {
    match status {
        SmartCoreObserverLaneReadinessStatus::NonVotingObserverReady => 5,
        SmartCoreObserverLaneReadinessStatus::NonVotingObserverReadyWithWarnings => 4,
        SmartCoreObserverLaneReadinessStatus::NeedsMoreTargets => 3,
        SmartCoreObserverLaneReadinessStatus::BlockedBySafety => 1,
        SmartCoreObserverLaneReadinessStatus::BlockedByDecisionLeak => 0,
    }
}

fn target_coverage_rank(status: ObserverTargetCoverageClosureStatus) -> i32 {
    match status {
        ObserverTargetCoverageClosureStatus::NoClosureNeeded => 2,
        ObserverTargetCoverageClosureStatus::ClosurePlanned => 1,
        ObserverTargetCoverageClosureStatus::NeedsMoreTargets => 0,
    }
}

pub fn compute_observer_comparison_ledger_trend(
    ledger: &ObserverComparisonLedger,
    window: ObserverComparisonLedgerTrendWindow,
) -> ObserverComparisonLedgerTrend {
    let entries = ledger_trend_window_entries(ledger, window);
    let enough_history = entries.len() >= 2;
    let disagreement_series = entries
        .iter()
        .map(|entry| entry.disagreement_count)
        .collect::<Vec<_>>();
    let comparison_count_series = entries
        .iter()
        .map(|entry| entry.comparison_count)
        .collect::<Vec<_>>();
    let readiness_status_series = entries
        .iter()
        .map(|entry| entry.readiness_status)
        .collect::<Vec<_>>();
    let target_coverage_status_series = entries
        .iter()
        .map(|entry| entry.target_coverage_status)
        .collect::<Vec<_>>();
    let safety_status_series = entries
        .iter()
        .map(|entry| entry.safety_status)
        .collect::<Vec<_>>();
    let disagreement_trend = numeric_trend(
        disagreement_series.first().copied().unwrap_or(0) as i32,
        disagreement_series.last().copied().unwrap_or(0) as i32,
        enough_history,
    );
    let readiness_trend = numeric_trend(
        readiness_status_series
            .first()
            .copied()
            .map(readiness_rank)
            .unwrap_or(0),
        readiness_status_series
            .last()
            .copied()
            .map(readiness_rank)
            .unwrap_or(0),
        enough_history,
    );
    let target_coverage_trend = numeric_trend(
        target_coverage_status_series
            .first()
            .copied()
            .map(target_coverage_rank)
            .unwrap_or(0),
        target_coverage_status_series
            .last()
            .copied()
            .map(target_coverage_rank)
            .unwrap_or(0),
        enough_history,
    );
    ObserverComparisonLedgerTrend {
        trend_id: format!("{}-trend", ledger.ledger_id),
        ledger_id: ledger.ledger_id.clone(),
        window,
        entry_count: entries.len(),
        disagreement_series,
        comparison_count_series,
        readiness_status_series,
        target_coverage_status_series,
        safety_status_series,
        disagreement_trend,
        readiness_trend,
        target_coverage_trend,
        trend_status: if !enough_history {
            ObserverComparisonLedgerTrendStatus::InsufficientHistory
        } else if disagreement_trend == ObserverTrendDirection::Worsening
            || readiness_trend == ObserverTrendDirection::Worsening
            || target_coverage_trend == ObserverTrendDirection::Worsening
        {
            ObserverComparisonLedgerTrendStatus::UsefulWithWarnings
        } else {
            ObserverComparisonLedgerTrendStatus::Useful
        },
        paper_only: true,
    }
}

fn previous_warning_kinds(
    previous_gate: &SmartCoreObserverReadinessHardeningGate,
) -> Vec<ObserverReadinessWarningKind> {
    previous_gate
        .warnings
        .iter()
        .map(|warning| {
            let normalized = warning.to_ascii_lowercase();
            if normalized.contains("review") {
                ObserverReadinessWarningKind::NeedsReviewTargetRemaining
            } else if normalized.contains("coverage") {
                ObserverReadinessWarningKind::ThinTargetCoverage
            } else {
                ObserverReadinessWarningKind::NonVotingReadOnlyReminder
            }
        })
        .collect()
}

pub fn reduce_observer_readiness_warnings(
    previous_gate: &SmartCoreObserverReadinessHardeningGate,
    apply_result: &ObserverTargetClosureApplyResult,
    rerun_result: &ObserverComparisonRerunV2Result,
    ledger_trend: &ObserverComparisonLedgerTrend,
) -> ObserverReadinessWarningReducer {
    let input_warnings = previous_warning_kinds(previous_gate);
    let mut remaining = Vec::new();
    if apply_result.skipped_needs_review_count > 0 || apply_result.needs_review_input_count > 0 {
        remaining.push(ObserverReadinessWarningKind::NeedsReviewTargetRemaining);
    }
    if !rerun_result.target_coverage_improved {
        remaining.push(ObserverReadinessWarningKind::ThinTargetCoverage);
    }
    if ledger_trend.trend_status == ObserverComparisonLedgerTrendStatus::InsufficientHistory {
        remaining.push(ObserverReadinessWarningKind::InsufficientLedgerHistory);
    }
    if rerun_result.new_comparison_summary_status
        == ObserverVsCommitteeComparisonSummaryStatus::Mixed
    {
        remaining.push(ObserverReadinessWarningKind::ComparisonMixed);
    }
    if previous_gate.new_readiness_status
        != SmartCoreObserverLaneReadinessStatus::NonVotingObserverReady
    {
        remaining.push(ObserverReadinessWarningKind::NonVotingReadOnlyReminder);
    }
    remaining.sort();
    remaining.dedup();
    let resolved_warning_count = input_warnings
        .iter()
        .filter(|warning| !remaining.contains(warning))
        .count();
    let remaining_warning_count = remaining.len();
    ObserverReadinessWarningReducer {
        reducer_id: format!(
            "{}-warning-reducer",
            previous_gate.previous_readiness_status as u8
        ),
        input_warning_count: input_warnings.len(),
        resolved_warning_count,
        remaining_warning_count,
        reduction_status: if remaining_warning_count == 0 {
            ObserverReadinessWarningReductionStatus::Cleared
        } else if remaining_warning_count < input_warnings.len() {
            ObserverReadinessWarningReductionStatus::Reduced
        } else if apply_result.apply_status == ObserverTargetClosureApplyStatus::Blocked {
            ObserverReadinessWarningReductionStatus::Blocked
        } else {
            ObserverReadinessWarningReductionStatus::Unchanged
        },
        remaining_warnings: remaining,
        paper_only: true,
    }
}

pub fn evaluate_smartcore_observer_readiness_v2(
    previous_gate: &SmartCoreObserverReadinessHardeningGate,
    apply_result: &ObserverTargetClosureApplyResult,
    rerun_result: &ObserverComparisonRerunV2Result,
    ledger_trend: &ObserverComparisonLedgerTrend,
    warning_reducer: &ObserverReadinessWarningReducer,
    safety_guard: &SmartCoreObserverLaneSafetyGuard,
) -> SmartCoreObserverReadinessV2Gate {
    let mut blockers = Vec::new();
    let mut warnings = warning_reducer.remaining_warnings.clone();
    let readiness_status =
        if safety_guard.guard_status == SmartCoreObserverLaneSafetyGuardStatus::Violated {
            blockers.extend(safety_guard.violations.clone());
            SmartCoreObserverReadinessV2Status::BlockedBySafety
        } else if warnings.contains(&ObserverReadinessWarningKind::NeedsReviewTargetRemaining)
            || warnings.contains(&ObserverReadinessWarningKind::ThinTargetCoverage)
        {
            SmartCoreObserverReadinessV2Status::NeedsMoreTargets
        } else if warnings.contains(&ObserverReadinessWarningKind::InsufficientLedgerHistory) {
            SmartCoreObserverReadinessV2Status::NeedsMoreHistory
        } else if warnings
            .iter()
            .all(|warning| *warning == ObserverReadinessWarningKind::NonVotingReadOnlyReminder)
        {
            warnings.clear();
            SmartCoreObserverReadinessV2Status::NonVotingObserverReady
        } else if warnings.is_empty() {
            SmartCoreObserverReadinessV2Status::NonVotingObserverReady
        } else {
            SmartCoreObserverReadinessV2Status::NonVotingObserverReadyWithWarnings
        };
    SmartCoreObserverReadinessV2Gate {
        gate_id: format!("{}-readiness-v2", apply_result.run_id),
        previous_readiness_status: previous_gate.new_readiness_status,
        closure_apply_status: apply_result.apply_status,
        comparison_rerun_status: rerun_result.rerun_status,
        ledger_trend_status: ledger_trend.trend_status,
        warning_reduction_status: warning_reducer.reduction_status,
        observer_safety_status: safety_guard.guard_status,
        decision_isolation_status: ObserverApplyDecisionIsolationGuardStatus::Preserved,
        warning_free_non_voting_ready: warnings.is_empty()
            && readiness_status == SmartCoreObserverReadinessV2Status::NonVotingObserverReady,
        readiness_status,
        blockers,
        warnings,
        paper_only: true,
    }
}

pub fn build_owner_observer_trend_summary(
    readiness_v2: &SmartCoreObserverReadinessV2Gate,
    ledger_trend: &ObserverComparisonLedgerTrend,
    apply_result: &ObserverTargetClosureApplyResult,
    rerun_result: &ObserverComparisonRerunV2Result,
) -> OwnerObserverTrendSummary {
    OwnerObserverTrendSummary {
        summary_id: format!("{}-owner-trend-summary", apply_result.run_id),
        previous_readiness_status: readiness_v2.previous_readiness_status,
        new_readiness_status: readiness_v2.readiness_status,
        target_count_before: apply_result.previous_target_count,
        target_count_after: apply_result.new_target_count,
        approved_targets_applied: apply_result.applied_count,
        disagreement_delta: rerun_result.disagreement_delta,
        ledger_entry_count: ledger_trend.entry_count,
        disagreement_trend: ledger_trend.disagreement_trend,
        readiness_trend: ledger_trend.readiness_trend,
        remaining_warning_count: readiness_v2.warnings.len(),
        message: "Observer targets were applied only for evaluation. Observer remains non-voting and read-only. No committee decision or trading path uses this output.".to_string(),
        non_voting: true,
        read_only: true,
        not_investment_signal: true,
        not_committee_opinion: true,
        paper_only: true,
    }
}

pub fn evaluate_observer_apply_decision_isolation(
    apply_result: &ObserverTargetClosureApplyResult,
    batch_result_before: &BatchCommitteeCycleResult,
    batch_result_after: Option<&BatchCommitteeCycleResult>,
) -> ObserverApplyDecisionIsolationGuard {
    let after = batch_result_after.unwrap_or(batch_result_before);
    let applied_targets_used_as_input_feature = apply_result
        .applied_targets
        .iter()
        .any(|target| !target.not_input_feature);
    let applied_targets_used_as_member_opinion =
        batch_result_before.member_opinions != after.member_opinions;
    let applied_targets_used_in_committee_session =
        batch_result_before.committee_sessions != after.committee_sessions;
    let applied_targets_used_in_chairman_decision =
        batch_result_before.chairman_decisions != after.chairman_decisions;
    let applied_targets_used_in_risk_governor = batch_result_before
        .chairman_decisions
        .iter()
        .map(|decision| decision.risk_governor_status)
        .collect::<Vec<_>>()
        != after
            .chairman_decisions
            .iter()
            .map(|decision| decision.risk_governor_status)
            .collect::<Vec<_>>();
    let markers = apply_result
        .applied_targets
        .iter()
        .map(|target| target.target_id.clone())
        .collect::<Vec<_>>();
    let applied_targets_used_as_trade_signal =
        value_contains_debug_marker(&after.committee_sessions, &markers);
    let applied_targets_used_as_order = value_contains_debug_marker(&after.event_queue, &markers);
    let apply_changed_member_score = batch_result_before.score_updates != after.score_updates;
    let apply_changed_voice_weight = batch_result_before
        .score_updates
        .iter()
        .map(|update| (update.member_id.clone(), update.new_voice_weight))
        .collect::<Vec<_>>()
        != after
            .score_updates
            .iter()
            .map(|update| (update.member_id.clone(), update.new_voice_weight))
            .collect::<Vec<_>>();
    let apply_changed_committee_decision = applied_targets_used_in_chairman_decision;
    let mut violations = Vec::new();
    if applied_targets_used_as_input_feature {
        violations.push("applied target entered input feature path".to_string());
    }
    if applied_targets_used_as_member_opinion {
        violations.push("applied target changed member opinion".to_string());
    }
    if applied_targets_used_in_committee_session {
        violations.push("applied target changed committee session".to_string());
    }
    if applied_targets_used_in_chairman_decision {
        violations.push("applied target changed chairman decision".to_string());
    }
    if applied_targets_used_in_risk_governor {
        violations.push("applied target changed risk governor".to_string());
    }
    if applied_targets_used_as_trade_signal {
        violations.push("applied target created trade signal".to_string());
    }
    if applied_targets_used_as_order {
        violations.push("applied target created order".to_string());
    }
    if apply_changed_member_score {
        violations.push("applied target changed member score".to_string());
    }
    if apply_changed_voice_weight {
        violations.push("applied target changed voice weight".to_string());
    }
    ObserverApplyDecisionIsolationGuard {
        applied_targets_used_as_input_feature,
        applied_targets_used_as_member_opinion,
        applied_targets_used_in_committee_session,
        applied_targets_used_in_chairman_decision,
        applied_targets_used_in_risk_governor,
        applied_targets_used_as_trade_signal,
        applied_targets_used_as_order,
        apply_changed_member_score,
        apply_changed_voice_weight,
        apply_changed_committee_decision,
        guard_status: if violations.is_empty() {
            ObserverApplyDecisionIsolationGuardStatus::Preserved
        } else {
            ObserverApplyDecisionIsolationGuardStatus::Violated
        },
        violations,
        paper_only: true,
    }
}

pub fn run_observer_target_apply_and_trend(
    observer_run_result: &SmartCoreObserverLaneRunResult,
    closure_result: &ObserverTargetCoverageClosureRunResult,
    batch_result: &BatchCommitteeCycleResult,
    config: &ObserverTargetApplyAndTrendRunConfig,
) -> Result<ObserverTargetApplyAndTrendRunResult, String> {
    if !config.paper_only {
        return Err("observer apply and trend run must stay paper_only".to_string());
    }
    let policy = ObserverTargetClosureApplyPolicy {
        allow_apply_approved_targets: config.apply_targets,
        ..default_observer_target_closure_apply_policy()
    };
    let existing_store = if let Some(path) = config.target_store_input_path.as_ref() {
        load_observer_agreement_target_store_from_local_json(Path::new(path))?
    } else {
        build_observer_target_store(
            "observer-target-store".to_string(),
            ObserverAgreementTargetSet {
                target_set_id: "observer-agreement-target-set".to_string(),
                targets: Vec::new(),
                target_count: 0,
                approved_count: 0,
                needs_review_count: 0,
                rejected_count: 0,
                paper_only: true,
            },
        )
    };
    let apply_result = apply_observer_target_closure_records(
        closure_result,
        Some(&existing_store.target_set),
        &ObserverTargetClosureApplyConfig {
            run_id: config.run_id.clone(),
            closure_result_input_path: config.closure_result_path.clone(),
            target_set_input_path: config.target_store_input_path.clone(),
            target_set_output_path: config.target_store_output_path.clone(),
            apply_enabled: config.apply_targets,
            dry_run: config.dry_run,
            paper_only: true,
        },
        &policy,
    )?;
    let merged_store = if apply_result.wrote_target_set {
        merge_approved_observer_targets(&existing_store, &apply_result.applied_targets)
    } else {
        existing_store.clone()
    };
    if apply_result.wrote_target_set {
        if let Some(path) = config.target_store_output_path.as_ref() {
            save_observer_agreement_target_store_to_local_json(Path::new(path), &merged_store)?;
        }
    }
    let rerun_result = rerun_observer_comparison_with_target_store(
        observer_run_result,
        &merged_store,
        &ObserverComparisonRerunV2Config {
            run_id: config.run_id.clone(),
            use_persisted_target_store: true,
            compare_member_opinion: true,
            compare_chairman_decision: true,
            compare_risk_governor: true,
            paper_only: true,
        },
    );
    let mut ledger = if let Some(path) = config.observer_ledger_path.as_ref() {
        let path = Path::new(path);
        if path.exists() {
            load_observer_comparison_ledger_from_local_json(path)?
        } else {
            ObserverComparisonLedger {
                ledger_id: "observer-comparison-ledger".to_string(),
                entries: Vec::new(),
                entry_count: 0,
                latest_entry_id: None,
                paper_only: true,
            }
        }
    } else {
        ObserverComparisonLedger {
            ledger_id: "observer-comparison-ledger".to_string(),
            entries: Vec::new(),
            entry_count: 0,
            latest_entry_id: None,
            paper_only: true,
        }
    };
    append_observer_comparison_ledger_entry(
        &mut ledger,
        ObserverComparisonLedgerEntry {
            entry_id: format!("{}-apply-trend-entry", config.run_id),
            run_id: config.run_id.clone(),
            timestamp: None,
            observer_member_count: observer_run_result.observer_members.len(),
            comparison_count: observer_run_result.comparison_summary.comparison_count,
            disagreement_count: rerun_result.new_disagreement_count,
            comparison_summary_status: rerun_result.new_comparison_summary_status,
            readiness_status: observer_run_result
                .readiness_recheck
                .as_ref()
                .map(|result| result.readiness_status)
                .unwrap_or(SmartCoreObserverLaneReadinessStatus::NeedsMoreTargets),
            target_coverage_status: if rerun_result.target_coverage_improved {
                ObserverTargetCoverageClosureStatus::NoClosureNeeded
            } else {
                ObserverTargetCoverageClosureStatus::ClosurePlanned
            },
            safety_status: observer_run_result.observer_safety_guard.guard_status,
            target_count: merged_store.target_count,
            paper_only: true,
        },
    );
    let (normalized_ledger, normalization_result) =
        normalize_observer_comparison_ledger_entries(&ledger);
    if let Some(path) = config.observer_ledger_path.as_ref() {
        save_observer_comparison_ledger_to_local_json(Path::new(path), &normalized_ledger)?;
    }
    let ledger_trend = if config.compute_trend {
        compute_observer_comparison_ledger_trend(
            &normalized_ledger,
            ObserverComparisonLedgerTrendWindow::All,
        )
    } else {
        compute_observer_comparison_ledger_trend(
            &normalized_ledger,
            ObserverComparisonLedgerTrendWindow::Last3,
        )
    };
    let previous_gate = batch_result
        .observer_readiness_hardening_gate
        .as_ref()
        .ok_or_else(|| "observer apply and trend requires readiness hardening gate".to_string())?;
    let warning_reducer = reduce_observer_readiness_warnings(
        previous_gate,
        &apply_result,
        &rerun_result,
        &ledger_trend,
    );
    let mut readiness_v2 = evaluate_smartcore_observer_readiness_v2(
        previous_gate,
        &apply_result,
        &rerun_result,
        &ledger_trend,
        &warning_reducer,
        &observer_run_result.observer_safety_guard,
    );
    let decision_isolation_guard =
        evaluate_observer_apply_decision_isolation(&apply_result, batch_result, Some(batch_result));
    readiness_v2.decision_isolation_status = decision_isolation_guard.guard_status;
    if decision_isolation_guard.guard_status == ObserverApplyDecisionIsolationGuardStatus::Violated
    {
        readiness_v2.readiness_status = SmartCoreObserverReadinessV2Status::BlockedByDecisionLeak;
        readiness_v2.blockers = decision_isolation_guard.violations.clone();
    }
    let owner_trend_summary = config.emit_owner_summary.then(|| {
        build_owner_observer_trend_summary(
            &readiness_v2,
            &ledger_trend,
            &apply_result,
            &rerun_result,
        )
    });
    let result = ObserverTargetApplyAndTrendRunResult {
        run_id: config.run_id.clone(),
        apply_result,
        comparison_rerun_result: rerun_result,
        ledger_normalization_result: normalization_result,
        ledger_trend,
        readiness_warning_reducer: warning_reducer,
        readiness_v2,
        applied_target_store: Some(merged_store),
        owner_trend_summary,
        decision_isolation_guard,
        run_status: if observer_run_result.observer_safety_guard.guard_status
            == SmartCoreObserverLaneSafetyGuardStatus::Violated
        {
            ObserverTargetApplyAndTrendRunStatus::Failed
        } else if config.dry_run {
            ObserverTargetApplyAndTrendRunStatus::PassedWithWarnings
        } else {
            ObserverTargetApplyAndTrendRunStatus::Passed
        },
        paper_only: true,
    };
    Ok(result)
}

fn apply_owner_observer_trend_summary_update(
    batch_id: &str,
    section: Option<OwnerCoreDebugSection>,
    update: Option<OwnerObserverTrendSummary>,
) -> Option<OwnerCoreDebugSection> {
    let Some(update) = update else {
        return section;
    };
    if let Some(mut section) = section {
        section.summary = format!(
            "{}; observer_trend_entries={}, observer_ready_v2={:?}",
            section.summary, update.ledger_entry_count, update.new_readiness_status
        );
        section.observer_trend_summary = Some(update);
        Some(section)
    } else {
        Some(OwnerCoreDebugSection {
            section_id: format!("{batch_id}-owner-core-debug"),
            cards: Vec::new(),
            summary: "observer_trend_summary=1".to_string(),
            paper_only_warning:
                "observer trend summary is paper-only diagnostics; not investment advice, not trading, not orders"
                    .to_string(),
            debug_only_warning:
                "observer trend summary remains read-only/non-voting and must not feed committee decisions"
                    .to_string(),
            calibration_summary: None,
            recalibration_summary: None,
            shadow_opinion_summary: None,
            shadow_stability_summary: None,
            shadow_scenario_sweep_summary: None,
            observer_section: None,
            observer_coverage_closure_summary: None,
            observer_trend_summary: Some(update),
            observer_seeded_target_summary: None,
            observer_apply_readiness_summary: None,
            paper_only: true,
        })
    }
}

fn observer_target_apply_trend_requested_from_flags(
    enabled: bool,
    target_store_input_path: Option<&String>,
    target_store_output_path: Option<&String>,
    observer_ledger_path: Option<&String>,
    observer_apply_trend_output_path: Option<&String>,
    observer_ledger_trend_enabled: bool,
    observer_readiness_v2_enabled: bool,
    observer_trend_summary_enabled: bool,
) -> bool {
    enabled
        || target_store_input_path.is_some()
        || target_store_output_path.is_some()
        || observer_ledger_path.is_some()
        || observer_apply_trend_output_path.is_some()
        || observer_ledger_trend_enabled
        || observer_readiness_v2_enabled
        || observer_trend_summary_enabled
}

fn maybe_run_observer_target_apply_and_trend_for_batch_result(
    run_id: String,
    enabled: bool,
    dry_run: bool,
    apply_targets: bool,
    target_store_input_path: Option<&String>,
    target_store_output_path: Option<&String>,
    observer_ledger_path: Option<&String>,
    observer_apply_trend_output_path: Option<&String>,
    observer_ledger_trend_enabled: bool,
    observer_readiness_v2_enabled: bool,
    observer_trend_summary_enabled: bool,
    batch_result: &mut BatchCommitteeCycleResult,
) -> Result<Option<ObserverTargetApplyAndTrendRunResult>, String> {
    if !observer_target_apply_trend_requested_from_flags(
        enabled,
        target_store_input_path,
        target_store_output_path,
        observer_ledger_path,
        observer_apply_trend_output_path,
        observer_ledger_trend_enabled,
        observer_readiness_v2_enabled,
        observer_trend_summary_enabled,
    ) {
        return Ok(None);
    }
    let observer_run_result = batch_result
        .smartcore_observer_lane_run_result
        .clone()
        .ok_or_else(|| "observer apply and trend requires observer lane result".to_string())?;
    let closure_result = batch_result
        .observer_target_coverage_closure_run_result
        .clone()
        .ok_or_else(|| "observer apply and trend requires closure run result".to_string())?;
    let result = run_observer_target_apply_and_trend(
        &observer_run_result,
        &closure_result,
        batch_result,
        &ObserverTargetApplyAndTrendRunConfig {
            run_id: run_id.clone(),
            enabled,
            closure_result_path: None,
            target_store_input_path: target_store_input_path.cloned(),
            target_store_output_path: target_store_output_path.cloned(),
            observer_ledger_path: observer_ledger_path.cloned(),
            dry_run,
            apply_targets,
            compute_trend: observer_ledger_trend_enabled,
            recheck_readiness: observer_readiness_v2_enabled,
            emit_owner_summary: observer_trend_summary_enabled,
            paper_only: true,
        },
    )?;
    if let Some(path) = observer_apply_trend_output_path {
        validate_local_json_path(Path::new(path), "observer apply trend output path")?;
        write_safe_json(Path::new(path), &result)?;
    }
    if let Some(shadow_alignment_result) =
        batch_result.smartcore_shadow_alignment_run_result.as_mut()
    {
        shadow_alignment_result.owner_core_debug_section =
            apply_owner_observer_trend_summary_update(
                &batch_result.batch_id,
                shadow_alignment_result.owner_core_debug_section.take(),
                result.owner_trend_summary.clone(),
            );
    }
    if result.apply_result.wrote_target_set {
        if let Some(path) = target_store_output_path {
            if let Some(store) = result.applied_target_store.as_ref() {
                save_observer_agreement_target_store_to_local_json(Path::new(path), store)?;
            }
        }
    }
    batch_result.observer_target_apply_and_trend_run_result = Some(result.clone());
    batch_result.observer_comparison_rerun_v2_result = Some(result.comparison_rerun_result.clone());
    batch_result.observer_comparison_ledger_trend = Some(result.ledger_trend.clone());
    batch_result.observer_ledger_normalization_result =
        Some(result.ledger_normalization_result.clone());
    batch_result.observer_readiness_warning_reducer =
        Some(result.readiness_warning_reducer.clone());
    batch_result.observer_readiness_v2_gate = Some(result.readiness_v2.clone());
    batch_result.observer_apply_decision_isolation_guard =
        Some(result.decision_isolation_guard.clone());
    batch_result.observer_agreement_target_store = result.applied_target_store.clone();
    if let Some(path) = observer_ledger_path {
        if Path::new(path).exists() {
            batch_result.observer_comparison_ledger = Some(
                load_observer_comparison_ledger_from_local_json(Path::new(path))?,
            );
        }
    }
    if batch_result.observer_agreement_target_store.is_none() {
        if let Some(path) = target_store_output_path {
            if Path::new(path).exists() {
                batch_result.observer_agreement_target_store = Some(
                    load_observer_agreement_target_store_from_local_json(Path::new(path))?,
                );
            }
        }
    }
    Ok(Some(result))
}

fn source_confidence_from_member_confidence(confidence: f64) -> SourceConfidence {
    if confidence >= 0.7 {
        SourceConfidence::High
    } else if confidence >= 0.45 {
        SourceConfidence::Medium
    } else {
        SourceConfidence::Low
    }
}

fn source_confidence_from_replay_label_confidence(
    confidence: ReplayLabelConfidence,
) -> SourceConfidence {
    match confidence {
        ReplayLabelConfidence::High => SourceConfidence::High,
        ReplayLabelConfidence::Medium => SourceConfidence::Medium,
        ReplayLabelConfidence::Low => SourceConfidence::Low,
        ReplayLabelConfidence::ReviewRequired => SourceConfidence::ReviewRequired,
    }
}

fn observer_seed_head_from_shadow_head(
    head: SmartCoreShadowHeadKind,
) -> Option<ObserverAgreementTargetHead> {
    match head {
        SmartCoreShadowHeadKind::Stance => Some(ObserverAgreementTargetHead::Stance),
        SmartCoreShadowHeadKind::Risk => Some(ObserverAgreementTargetHead::Risk),
        SmartCoreShadowHeadKind::EvidenceNeed => Some(ObserverAgreementTargetHead::EvidenceNeed),
        SmartCoreShadowHeadKind::ConfidenceCalibration => {
            Some(ObserverAgreementTargetHead::ConfidenceCalibration)
        }
        SmartCoreShadowHeadKind::Uncertainty => Some(ObserverAgreementTargetHead::Uncertainty),
        SmartCoreShadowHeadKind::ExpectedReturnHint => None,
    }
}

fn observer_seed_member_context_for_decision(
    batch_result: &BatchCommitteeCycleResult,
    decision_id: &str,
) -> (Option<String>, Option<String>) {
    let member_id = batch_result
        .chairman_decisions
        .iter()
        .find(|decision| decision.decision_id == decision_id)
        .and_then(|decision| {
            batch_result
                .committee_sessions
                .iter()
                .find(|session| session.session_id == decision.session_id)
        })
        .map(|session| session.event.proposed_by_member_id.clone());
    let canonical_member_id = member_id.as_ref().and_then(|member_id| {
        resolve_canonical_member_id_with_map(&default_three_member_canonical_id_map(), member_id)
    });
    (member_id, canonical_member_id)
}

fn build_seed_from_member_opinion(opinion: &MemberOpinion) -> Option<ObserverApprovedTargetSeed> {
    let target_bucket = member_stance_shadow_target(opinion.stance)?;
    let source_confidence = source_confidence_from_member_confidence(opinion.confidence);
    if source_confidence == SourceConfidence::Low {
        return None;
    }
    Some(ObserverApprovedTargetSeed {
        seed_id: format!("seed-member-{}-{}", opinion.member_id, opinion.symbol),
        source_type: ObserverApprovedTargetSeedSource::MemberOpinion,
        source_record_id: Some(opinion.member_id.clone()),
        member_id: Some(opinion.member_id.clone()),
        canonical_member_id: resolve_canonical_member_id_with_map(
            &default_three_member_canonical_id_map(),
            &opinion.member_id,
        ),
        symbol: Some(opinion.symbol.clone()),
        market_scope: Some(opinion.market_scope),
        head: ObserverAgreementTargetHead::Stance,
        target_bucket,
        source_confidence,
        seed_status: ObserverApprovedTargetSeedStatus::ApprovedSeed,
        eval_only: true,
        not_input_feature: true,
        paper_only: true,
    })
}

fn build_seed_from_chairman_decision(
    batch_result: &BatchCommitteeCycleResult,
    decision: &ChairmanDecision,
    include_chairman_decision: bool,
    include_risk_governor_status: bool,
) -> Vec<ObserverApprovedTargetSeed> {
    let session = batch_result
        .committee_sessions
        .iter()
        .find(|session| session.session_id == decision.session_id);
    let symbol = session.map(|session| session.event.symbol.clone());
    let market_scope = session.map(|session| session.event.market_scope);
    let member_id = session.map(|session| session.event.proposed_by_member_id.clone());
    let canonical_member_id = member_id.as_ref().and_then(|member_id| {
        resolve_canonical_member_id_with_map(&default_three_member_canonical_id_map(), member_id)
    });
    let mut seeds = Vec::new();
    if include_chairman_decision {
        if let Some(target_bucket) = chairman_action_target(decision.final_action) {
            seeds.push(ObserverApprovedTargetSeed {
                seed_id: format!("seed-chairman-stance-{}", decision.decision_id),
                source_type: ObserverApprovedTargetSeedSource::ChairmanDecision,
                source_record_id: Some(decision.decision_id.clone()),
                member_id: member_id.clone(),
                canonical_member_id: canonical_member_id.clone(),
                symbol: symbol.clone(),
                market_scope,
                head: ObserverAgreementTargetHead::Stance,
                target_bucket,
                source_confidence: SourceConfidence::Medium,
                seed_status: ObserverApprovedTargetSeedStatus::ApprovedSeed,
                eval_only: true,
                not_input_feature: true,
                paper_only: true,
            });
        }
    }
    if include_risk_governor_status {
        seeds.push(ObserverApprovedTargetSeed {
            seed_id: format!("seed-chairman-risk-{}", decision.decision_id),
            source_type: ObserverApprovedTargetSeedSource::RiskGovernorStatus,
            source_record_id: Some(decision.decision_id.clone()),
            member_id,
            canonical_member_id,
            symbol,
            market_scope,
            head: ObserverAgreementTargetHead::Risk,
            target_bucket: risk_target_from_status(decision.risk_governor_status),
            source_confidence: SourceConfidence::High,
            seed_status: ObserverApprovedTargetSeedStatus::ApprovedSeed,
            eval_only: true,
            not_input_feature: true,
            paper_only: true,
        });
    }
    seeds
}

fn build_seed_from_validated_replay_label(
    example: &ReplayExample,
) -> Option<ObserverApprovedTargetSeed> {
    if !example.paper_only || !is_validated_replay_label(example) {
        return None;
    }
    let labels = example.target_labels.as_ref()?;
    let target_bucket = member_stance_shadow_target(labels.stance_target)?;
    Some(ObserverApprovedTargetSeed {
        seed_id: format!("seed-validated-replay-{}", example.replay_id),
        source_type: ObserverApprovedTargetSeedSource::ValidatedReplayLabel,
        source_record_id: Some(example.replay_id.clone()),
        member_id: Some(example.member_id.clone()),
        canonical_member_id: resolve_canonical_member_id_with_map(
            &default_three_member_canonical_id_map(),
            &example.member_id,
        ),
        symbol: Some(example.symbol.clone()),
        market_scope: Some(example.market_scope),
        head: ObserverAgreementTargetHead::Stance,
        target_bucket,
        source_confidence: source_confidence_from_replay_label_confidence(labels.label_confidence),
        seed_status: ObserverApprovedTargetSeedStatus::ApprovedSeed,
        eval_only: true,
        not_input_feature: true,
        paper_only: true,
    })
}

fn build_seed_from_core_calibration_example(
    example: &CoreCalibrationExample,
) -> Option<ObserverApprovedTargetSeed> {
    if !example.paper_only
        || !matches!(
            example.label_confidence,
            ReplayLabelConfidence::High | ReplayLabelConfidence::Medium
        )
    {
        return None;
    }
    let head = observer_seed_head_from_shadow_head(example.head)?;
    let target_bucket = shadow_bucket_value_from_label(&example.target_bucket);
    if matches!(
        target_bucket,
        SmartCoreHeadBucketNormalizedValue::Unknown | SmartCoreHeadBucketNormalizedValue::Deferred
    ) {
        return None;
    }
    Some(ObserverApprovedTargetSeed {
        seed_id: format!("seed-core-calibration-{}", example.calibration_example_id),
        source_type: ObserverApprovedTargetSeedSource::CoreCalibrationDataset,
        source_record_id: Some(example.calibration_example_id.clone()),
        member_id: Some(example.member_id.clone()),
        canonical_member_id: resolve_canonical_member_id_with_map(
            &default_three_member_canonical_id_map(),
            &example.member_id,
        ),
        symbol: example.symbol.clone(),
        market_scope: example.market_scope,
        head,
        target_bucket,
        source_confidence: source_confidence_from_replay_label_confidence(example.label_confidence),
        seed_status: ObserverApprovedTargetSeedStatus::ApprovedSeed,
        eval_only: true,
        not_input_feature: true,
        paper_only: true,
    })
}

fn build_seed_from_paper_evidence_record(
    batch_result: &BatchCommitteeCycleResult,
    record: &PaperOutcomeEvidenceRecord,
) -> Option<ObserverApprovedTargetSeed> {
    if !record.paper_only
        || !matches!(
            record.label_source,
            ReplayLabelSource::ValidatedPaperLabel | ReplayLabelSource::ValidatedBacktestLabel
        )
        || !matches!(
            record.label_confidence,
            ReplayLabelConfidence::High | ReplayLabelConfidence::Medium
        )
    {
        return None;
    }
    let decision_id = record.decision_id.as_ref()?;
    let (member_id, canonical_member_id) =
        observer_seed_member_context_for_decision(batch_result, decision_id);
    let member_id = member_id?;
    Some(ObserverApprovedTargetSeed {
        seed_id: format!("seed-paper-evidence-{}", record.evidence_id),
        source_type: ObserverApprovedTargetSeedSource::ValidatedPaperOutcomeEvidence,
        source_record_id: Some(record.evidence_id.clone()),
        member_id: Some(member_id),
        canonical_member_id,
        symbol: Some(record.symbol.clone()),
        market_scope: Some(record.market_scope),
        head: ObserverAgreementTargetHead::Stance,
        target_bucket: closure_bucket_from_experience_outcome(record.candidate_label),
        source_confidence: source_confidence_from_replay_label_confidence(record.label_confidence),
        seed_status: ObserverApprovedTargetSeedStatus::ApprovedSeed,
        eval_only: true,
        not_input_feature: true,
        paper_only: true,
    })
}

pub fn build_observer_approved_target_seeds(
    batch_result: &BatchCommitteeCycleResult,
    replay_dataset: Option<&ReplayDataset>,
    calibration_dataset: Option<&CoreCalibrationDataset>,
    paper_evidence: Option<&PaperOutcomeEvidenceFile>,
    config: &ObserverApprovedTargetSeedBuildConfig,
) -> ObserverApprovedTargetSeedBuildResult {
    let mut seeds = Vec::new();
    if !config.paper_only {
        return ObserverApprovedTargetSeedBuildResult {
            run_id: config.run_id.clone(),
            seed_count: 0,
            approved_seed_count: 0,
            needs_review_seed_count: 0,
            rejected_seed_count: 0,
            seeds,
            build_status: ObserverApprovedTargetSeedBuildStatus::Failed,
            paper_only: true,
        };
    }
    if config.include_member_opinion {
        let mut per_member = std::collections::BTreeMap::<String, usize>::new();
        for opinion in &batch_result.member_opinions {
            if per_member.get(&opinion.member_id).copied().unwrap_or(0)
                >= config.max_seeds_per_member
            {
                continue;
            }
            if let Some(seed) = build_seed_from_member_opinion(opinion) {
                *per_member.entry(opinion.member_id.clone()).or_insert(0) += 1;
                seeds.push(seed);
            }
        }
    }
    if config.include_risk_governor_status || config.include_chairman_decision {
        for decision in &batch_result.chairman_decisions {
            seeds.extend(build_seed_from_chairman_decision(
                batch_result,
                decision,
                config.include_chairman_decision,
                config.include_risk_governor_status,
            ));
        }
    }
    if config.include_validated_replay_labels {
        if let Some(dataset) = replay_dataset {
            if dataset.paper_only {
                seeds.extend(
                    dataset
                        .examples
                        .iter()
                        .filter_map(build_seed_from_validated_replay_label),
                );
            }
        }
    }
    if config.include_core_calibration_targets {
        if let Some(dataset) = calibration_dataset {
            if dataset.paper_only {
                seeds.extend(
                    dataset
                        .examples
                        .iter()
                        .filter_map(build_seed_from_core_calibration_example),
                );
            }
        }
    }
    if config.include_validated_paper_outcomes {
        if let Some(evidence) = paper_evidence {
            if evidence.paper_only {
                seeds.extend(evidence.records.iter().filter_map(|record| {
                    build_seed_from_paper_evidence_record(batch_result, record)
                }));
            }
        }
    }
    seeds.retain(|seed| {
        seed.seed_status != ObserverApprovedTargetSeedStatus::NeedsReview
            && seed.seed_status != ObserverApprovedTargetSeedStatus::Rejected
            && seed.source_confidence != SourceConfidence::Low
            && seed.source_confidence != SourceConfidence::ReviewRequired
            && seed.target_bucket != SmartCoreHeadBucketNormalizedValue::Unknown
            && seed.target_bucket != SmartCoreHeadBucketNormalizedValue::Deferred
    });
    seeds.sort_by(|left, right| {
        left.seed_id
            .cmp(&right.seed_id)
            .then_with(|| left.member_id.cmp(&right.member_id))
    });
    seeds.truncate(config.max_total_seeds);
    let approved_seed_count = seeds
        .iter()
        .filter(|seed| seed.seed_status == ObserverApprovedTargetSeedStatus::ApprovedSeed)
        .count();
    ObserverApprovedTargetSeedBuildResult {
        run_id: config.run_id.clone(),
        seed_count: seeds.len(),
        approved_seed_count,
        needs_review_seed_count: 0,
        rejected_seed_count: 0,
        seeds,
        build_status: if approved_seed_count == 0 {
            ObserverApprovedTargetSeedBuildStatus::NoSeeds
        } else {
            ObserverApprovedTargetSeedBuildStatus::Built
        },
        paper_only: true,
    }
}

pub fn validate_observer_approved_target_seed(
    seed: &ObserverApprovedTargetSeed,
    policy: &ObserverTargetClosureApplyPolicy,
) -> ObserverApprovedTargetSeedValidationResult {
    let rejection = if !seed.paper_only {
        Some("approved target seed must stay paper_only".to_string())
    } else if !seed.eval_only {
        Some("approved target seed must stay eval_only".to_string())
    } else if !seed.not_input_feature {
        Some("approved target seed must stay not_input_feature".to_string())
    } else if seed.member_id.is_none() && seed.canonical_member_id.is_none() {
        Some("approved target seed requires member id".to_string())
    } else if seed.head == ObserverAgreementTargetHead::Unknown {
        Some("approved target seed requires head".to_string())
    } else if seed.seed_status == ObserverApprovedTargetSeedStatus::Rejected {
        Some("approved target seed is rejected".to_string())
    } else if matches!(
        seed.target_bucket,
        SmartCoreHeadBucketNormalizedValue::Unknown | SmartCoreHeadBucketNormalizedValue::Deferred
    ) && !policy.allow_ambiguous_targets
    {
        Some("approved target seed forbids Unknown/Deferred target".to_string())
    } else if seed.source_confidence == SourceConfidence::ReviewRequired {
        Some("approved target seed cannot approve ReviewRequired confidence".to_string())
    } else if observer_target_record_contains_unsafe_terms(&ObserverAgreementTargetRecord {
        target_id: seed.seed_id.clone(),
        source_closure_item_id: None,
        source_record_id: seed.source_record_id.clone(),
        member_id: seed.member_id.clone(),
        canonical_member_id: seed.canonical_member_id.clone(),
        symbol: seed.symbol.clone(),
        market_scope: seed.market_scope,
        head: seed.head,
        target_bucket: seed.target_bucket,
        source_type: ObserverAgreementTargetSource::MemberOpinion,
        source_confidence: seed.source_confidence,
        approval_status: ObserverAgreementTargetApprovalStatus::Candidate,
        reason: format!("{:?}", seed.source_type),
        eval_only: seed.eval_only,
        not_input_feature: seed.not_input_feature,
        paper_only: seed.paper_only,
    }) {
        Some("approved target seed contains broker/order/account terms".to_string())
    } else {
        None
    };
    let approval_status = if rejection.is_some() {
        ObserverAgreementTargetApprovalStatus::Rejected
    } else if seed.seed_status != ObserverApprovedTargetSeedStatus::ApprovedSeed {
        ObserverAgreementTargetApprovalStatus::NeedsReview
    } else if seed.source_confidence == SourceConfidence::Low && !policy.allow_low_trust_targets {
        ObserverAgreementTargetApprovalStatus::NeedsReview
    } else {
        ObserverAgreementTargetApprovalStatus::Approved
    };
    ObserverApprovedTargetSeedValidationResult {
        seed_id: seed.seed_id.clone(),
        valid: approval_status == ObserverAgreementTargetApprovalStatus::Approved,
        approval_status,
        rejection_reason: rejection,
        warnings: Vec::new(),
        paper_only: true,
    }
}

pub fn convert_approved_target_seeds_to_observer_targets(
    seeds: &[ObserverApprovedTargetSeed],
    policy: &ObserverTargetClosureApplyPolicy,
) -> ObserverApprovedTargetSeedConversionResult {
    let mut target_records = Vec::new();
    let mut needs_review_count = 0usize;
    let mut rejected_count = 0usize;
    for seed in seeds {
        let validation = validate_observer_approved_target_seed(seed, policy);
        match validation.approval_status {
            ObserverAgreementTargetApprovalStatus::Approved => {
                target_records.push(ObserverAgreementTargetRecord {
                    target_id: format!("{}-target", seed.seed_id),
                    source_closure_item_id: Some(seed.seed_id.clone()),
                    source_record_id: seed.source_record_id.clone(),
                    member_id: seed.member_id.clone(),
                    canonical_member_id: seed.canonical_member_id.clone(),
                    symbol: seed.symbol.clone(),
                    market_scope: seed.market_scope,
                    head: seed.head,
                    target_bucket: seed.target_bucket,
                    source_type: match seed.source_type {
                        ObserverApprovedTargetSeedSource::MemberOpinion => {
                            ObserverAgreementTargetSource::MemberOpinion
                        }
                        ObserverApprovedTargetSeedSource::RiskGovernorStatus => {
                            ObserverAgreementTargetSource::RiskGovernorStatus
                        }
                        ObserverApprovedTargetSeedSource::ChairmanDecision => {
                            ObserverAgreementTargetSource::ChairmanDecision
                        }
                        ObserverApprovedTargetSeedSource::ValidatedReplayLabel => {
                            ObserverAgreementTargetSource::ReplayLabel
                        }
                        ObserverApprovedTargetSeedSource::CoreCalibrationDataset => {
                            ObserverAgreementTargetSource::CoreCalibrationDataset
                        }
                        ObserverApprovedTargetSeedSource::ValidatedPaperOutcomeEvidence => {
                            ObserverAgreementTargetSource::PaperOutcomeLabel
                        }
                    },
                    source_confidence: seed.source_confidence,
                    approval_status: ObserverAgreementTargetApprovalStatus::Approved,
                    reason: format!("approved seed {}", seed.seed_id),
                    eval_only: true,
                    not_input_feature: true,
                    paper_only: true,
                });
            }
            ObserverAgreementTargetApprovalStatus::NeedsReview => needs_review_count += 1,
            ObserverAgreementTargetApprovalStatus::Rejected => rejected_count += 1,
            ObserverAgreementTargetApprovalStatus::Candidate => {}
        }
    }
    ObserverApprovedTargetSeedConversionResult {
        input_seed_count: seeds.len(),
        converted_target_count: target_records.len(),
        needs_review_count,
        rejected_count,
        target_records,
        conversion_status: if seeds.is_empty() {
            ObserverApprovedTargetSeedConversionStatus::NoApprovedSeeds
        } else if needs_review_count > 0 || rejected_count > 0 {
            ObserverApprovedTargetSeedConversionStatus::ConvertedWithWarnings
        } else {
            ObserverApprovedTargetSeedConversionStatus::Converted
        },
        paper_only: true,
    }
}

pub fn run_observer_controlled_apply_smoke(
    batch_result: &BatchCommitteeCycleResult,
    replay_dataset: Option<&ReplayDataset>,
    calibration_dataset: Option<&CoreCalibrationDataset>,
    paper_evidence: Option<&PaperOutcomeEvidenceFile>,
    config: &ObserverControlledApplySmokeConfig,
) -> Result<ObserverControlledApplySmokeResult, String> {
    if !config.paper_only {
        return Err("observer controlled apply smoke must stay paper_only".to_string());
    }
    let seed_build_result = build_observer_approved_target_seeds(
        batch_result,
        replay_dataset,
        calibration_dataset,
        paper_evidence,
        &ObserverApprovedTargetSeedBuildConfig {
            run_id: config.run_id.clone(),
            include_member_opinion: true,
            include_risk_governor_status: true,
            include_chairman_decision: true,
            include_validated_replay_labels: true,
            include_core_calibration_targets: true,
            include_validated_paper_outcomes: true,
            max_seeds_per_member: 3,
            max_total_seeds: 12,
            paper_only: true,
        },
    );
    let policy = ObserverTargetClosureApplyPolicy {
        allow_apply_approved_targets: config.apply_targets,
        ..default_observer_target_closure_apply_policy()
    };
    let seed_conversion_result =
        convert_approved_target_seeds_to_observer_targets(&seed_build_result.seeds, &policy);
    if config.require_at_least_one_approved_target
        && seed_conversion_result.converted_target_count == 0
    {
        return Ok(ObserverControlledApplySmokeResult {
            seed_build_result,
            seed_conversion_result,
            apply_result: ObserverTargetClosureApplyResult {
                run_id: config.run_id.clone(),
                approved_input_count: 0,
                needs_review_input_count: 0,
                rejected_input_count: 0,
                applied_count: 0,
                skipped_needs_review_count: 0,
                skipped_rejected_count: 0,
                skipped_duplicate_count: 0,
                unsafe_rejected_count: 0,
                previous_target_count: 0,
                new_target_count: 0,
                wrote_target_set: false,
                output_path: config.target_store_output_path.clone(),
                applied_targets: Vec::new(),
                apply_status: ObserverTargetClosureApplyStatus::NoApprovedTargets,
                warnings: vec!["no approved observer target seed available".to_string()],
                paper_only: true,
            },
            target_store_after: None,
            applied_target_count: 0,
            wrote_target_store: false,
            smoke_status: ObserverControlledApplySmokeStatus::Failed,
            paper_only: true,
        });
    }
    let apply_result = apply_observer_target_closure_records(
        &ObserverTargetCoverageClosureRunResult {
            run_id: config.run_id.clone(),
            input_item_count: seed_conversion_result.target_records.len(),
            executed_item_count: seed_conversion_result.target_records.len(),
            closed_count: seed_conversion_result.target_records.len(),
            needs_review_count: seed_conversion_result.needs_review_count,
            rejected_count: seed_conversion_result.rejected_count,
            generated_target_count: seed_conversion_result.target_records.len(),
            approved_target_count: seed_conversion_result.target_records.len(),
            target_records: seed_conversion_result.target_records.clone(),
            execution_results: Vec::new(),
            dry_run: config.dry_run,
            run_status: ObserverTargetCoverageClosureRunStatus::Passed,
            paper_only: true,
        },
        None,
        &ObserverTargetClosureApplyConfig {
            run_id: config.run_id.clone(),
            closure_result_input_path: None,
            target_set_input_path: None,
            target_set_output_path: config.target_store_output_path.clone(),
            apply_enabled: config.apply_targets,
            dry_run: config.dry_run,
            paper_only: true,
        },
        &policy,
    )?;
    let target_store_after = if apply_result.wrote_target_set {
        let store = build_observer_target_store(
            format!("{}-seeded-target-store", config.run_id),
            ObserverAgreementTargetSet {
                target_set_id: format!("{}-seeded-target-set", config.run_id),
                target_count: apply_result.applied_targets.len(),
                approved_count: apply_result.applied_targets.len(),
                needs_review_count: 0,
                rejected_count: 0,
                targets: apply_result.applied_targets.clone(),
                paper_only: true,
            },
        );
        if let Some(path) = config.target_store_output_path.as_ref() {
            save_observer_agreement_target_store_to_local_json(Path::new(path), &store)?;
        }
        Some(store)
    } else {
        None
    };
    let result = ObserverControlledApplySmokeResult {
        seed_build_result,
        seed_conversion_result,
        applied_target_count: apply_result.applied_count,
        wrote_target_store: apply_result.wrote_target_set,
        target_store_after,
        smoke_status: if config.dry_run {
            ObserverControlledApplySmokeStatus::PassedWithWarnings
        } else {
            ObserverControlledApplySmokeStatus::Passed
        },
        apply_result,
        paper_only: true,
    };
    if let Some(path) = config.observer_apply_smoke_output_path.as_ref() {
        validate_local_json_path(Path::new(path), "observer apply smoke output path")?;
        write_safe_json(Path::new(path), &result)?;
    }
    Ok(result)
}

pub fn recheck_observer_readiness_with_seeded_targets(
    previous_readiness: &SmartCoreObserverReadinessV2Gate,
    smoke_result: &ObserverControlledApplySmokeResult,
    rerun_result: Option<&ObserverComparisonRerunV2Result>,
    ledger_trend: Option<&ObserverComparisonLedgerTrend>,
) -> ObserverSeededTargetReadinessRecheck {
    let rerun = rerun_result
        .cloned()
        .unwrap_or(ObserverComparisonRerunV2Result {
            previous_comparison_summary_status:
                ObserverVsCommitteeComparisonSummaryStatus::InsufficientComparisons,
            new_comparison_summary_status:
                ObserverVsCommitteeComparisonSummaryStatus::InsufficientComparisons,
            previous_disagreement_count: 0,
            new_disagreement_count: 0,
            disagreement_delta: 0,
            previous_target_count: 0,
            new_target_count: 0,
            target_delta: 0,
            target_coverage_improved: false,
            rerun_status: ObserverComparisonRerunV2Status::NeedsMoreTargets,
            paper_only: true,
        });
    let trend_status = ledger_trend
        .map(|trend| trend.trend_status)
        .unwrap_or(ObserverComparisonLedgerTrendStatus::InsufficientHistory);
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    let readiness_status = if previous_readiness.observer_safety_status
        == SmartCoreObserverLaneSafetyGuardStatus::Violated
    {
        blockers.extend(previous_readiness.blockers.iter().cloned());
        ObserverSeededTargetReadinessStatus::BlockedBySafety
    } else if smoke_result.seed_conversion_result.converted_target_count == 0 {
        warnings.push("no approved seeded target converted".to_string());
        ObserverSeededTargetReadinessStatus::NeedsMoreTargets
    } else if smoke_result.applied_target_count == 0 {
        warnings.push("approved seeded targets exist but apply is still dry-run".to_string());
        ObserverSeededTargetReadinessStatus::NeedsApply
    } else if rerun.rerun_status == ObserverComparisonRerunV2Status::Improved
        && trend_status != ObserverComparisonLedgerTrendStatus::InsufficientHistory
    {
        ObserverSeededTargetReadinessStatus::NonVotingObserverReady
    } else {
        warnings.push(
            "seeded targets applied but readiness still carries non-blocking warnings".to_string(),
        );
        ObserverSeededTargetReadinessStatus::NonVotingObserverReadyWithWarnings
    };
    ObserverSeededTargetReadinessRecheck {
        previous_readiness_status: previous_readiness.readiness_status,
        seed_build_status: smoke_result.seed_build_result.build_status,
        approved_seed_count: smoke_result.seed_build_result.approved_seed_count,
        converted_target_count: smoke_result.seed_conversion_result.converted_target_count,
        applied_target_count: smoke_result.applied_target_count,
        previous_target_count: smoke_result.apply_result.previous_target_count,
        new_target_count: smoke_result.apply_result.new_target_count,
        previous_rerun_status: previous_readiness.comparison_rerun_status,
        new_rerun_status: rerun.rerun_status,
        previous_ledger_trend_status: previous_readiness.ledger_trend_status,
        new_ledger_trend_status: trend_status,
        readiness_status,
        blockers,
        warnings,
        paper_only: true,
    }
}

pub fn build_owner_observer_seeded_target_summary(
    recheck_result: &ObserverSeededTargetReadinessRecheck,
    smoke_result: &ObserverControlledApplySmokeResult,
) -> OwnerObserverSeededTargetSummary {
    OwnerObserverSeededTargetSummary {
        summary_id: format!("{}-seeded-target-summary", smoke_result.apply_result.run_id),
        approved_seed_count: smoke_result.seed_build_result.approved_seed_count,
        converted_target_count: smoke_result.seed_conversion_result.converted_target_count,
        applied_target_count: smoke_result.applied_target_count,
        wrote_target_store: smoke_result.wrote_target_store,
        readiness_status: recheck_result.readiness_status,
        message: "Approved observer targets are evaluation-only. Observer remains non-voting and read-only. This does not change committee decisions or trading behavior.".to_string(),
        non_voting: true,
        read_only: true,
        eval_only: true,
        not_investment_signal: true,
        not_committee_opinion: true,
        paper_only: true,
    }
}

pub fn evaluate_observer_seeded_target_decision_isolation(
    smoke_result: &ObserverControlledApplySmokeResult,
    batch_result_before: &BatchCommitteeCycleResult,
    batch_result_after: Option<&BatchCommitteeCycleResult>,
) -> ObserverSeededTargetDecisionIsolationGuard {
    let after = batch_result_after.unwrap_or(batch_result_before);
    let markers = smoke_result
        .apply_result
        .applied_targets
        .iter()
        .map(|target| target.target_id.clone())
        .collect::<Vec<_>>();
    let seeded_targets_used_as_input_feature = smoke_result
        .apply_result
        .applied_targets
        .iter()
        .any(|target| !target.not_input_feature);
    let seeded_targets_used_as_member_opinion =
        batch_result_before.member_opinions != after.member_opinions;
    let seeded_targets_used_in_committee_session =
        batch_result_before.committee_sessions != after.committee_sessions;
    let seeded_targets_used_in_chairman_decision =
        batch_result_before.chairman_decisions != after.chairman_decisions;
    let seeded_targets_used_in_risk_governor = batch_result_before
        .chairman_decisions
        .iter()
        .map(|decision| decision.risk_governor_status)
        .collect::<Vec<_>>()
        != after
            .chairman_decisions
            .iter()
            .map(|decision| decision.risk_governor_status)
            .collect::<Vec<_>>();
    let seeded_targets_used_as_trade_signal =
        value_contains_debug_marker(&after.committee_sessions, &markers);
    let seeded_targets_used_as_order = value_contains_debug_marker(&after.event_queue, &markers);
    let seeded_targets_changed_member_score =
        batch_result_before.score_updates != after.score_updates;
    let seeded_targets_changed_voice_weight = batch_result_before
        .score_updates
        .iter()
        .map(|update| (update.member_id.clone(), update.new_voice_weight))
        .collect::<Vec<_>>()
        != after
            .score_updates
            .iter()
            .map(|update| (update.member_id.clone(), update.new_voice_weight))
            .collect::<Vec<_>>();
    let seeded_targets_changed_committee_decision = seeded_targets_used_in_chairman_decision;
    let mut violations = Vec::new();
    if seeded_targets_used_as_input_feature {
        violations.push("seeded target entered input feature path".to_string());
    }
    if seeded_targets_used_as_member_opinion {
        violations.push("seeded target changed member opinion".to_string());
    }
    if seeded_targets_used_in_committee_session {
        violations.push("seeded target changed committee session".to_string());
    }
    if seeded_targets_used_in_chairman_decision {
        violations.push("seeded target changed chairman decision".to_string());
    }
    if seeded_targets_used_in_risk_governor {
        violations.push("seeded target changed risk governor".to_string());
    }
    if seeded_targets_used_as_trade_signal {
        violations.push("seeded target created trade signal".to_string());
    }
    if seeded_targets_used_as_order {
        violations.push("seeded target created order".to_string());
    }
    if seeded_targets_changed_member_score {
        violations.push("seeded target changed member score".to_string());
    }
    if seeded_targets_changed_voice_weight {
        violations.push("seeded target changed voice weight".to_string());
    }
    ObserverSeededTargetDecisionIsolationGuard {
        seeded_targets_used_as_input_feature,
        seeded_targets_used_as_member_opinion,
        seeded_targets_used_in_committee_session,
        seeded_targets_used_in_chairman_decision,
        seeded_targets_used_in_risk_governor,
        seeded_targets_used_as_trade_signal,
        seeded_targets_used_as_order,
        seeded_targets_changed_member_score,
        seeded_targets_changed_voice_weight,
        seeded_targets_changed_committee_decision,
        guard_status: if violations.is_empty() {
            ObserverSeededTargetDecisionIsolationGuardStatus::Preserved
        } else {
            ObserverSeededTargetDecisionIsolationGuardStatus::Violated
        },
        violations,
        paper_only: true,
    }
}

pub fn run_observer_seed_apply_trend(
    batch_result: &BatchCommitteeCycleResult,
    replay_dataset: Option<&ReplayDataset>,
    calibration_dataset: Option<&CoreCalibrationDataset>,
    paper_evidence: Option<&PaperOutcomeEvidenceFile>,
    previous_observer_result: &SmartCoreObserverLaneRunResult,
    config: &ObserverSeedApplyTrendRunConfig,
) -> Result<ObserverSeedApplyTrendRunResult, String> {
    if !config.paper_only {
        return Err("observer seed apply trend run must stay paper_only".to_string());
    }
    let smoke_result = run_observer_controlled_apply_smoke(
        batch_result,
        replay_dataset,
        calibration_dataset,
        paper_evidence,
        &ObserverControlledApplySmokeConfig {
            run_id: config.run_id.clone(),
            enabled: config.enabled,
            apply_targets: config.apply_targets,
            dry_run: config.dry_run,
            target_store_output_path: config.target_store_output_path.clone(),
            observer_apply_smoke_output_path: None,
            require_at_least_one_approved_target: config.require_approved_target,
            paper_only: true,
        },
    )?;
    let comparison_rerun_result = if config.rerun_comparison {
        smoke_result.target_store_after.as_ref().map(|store| {
            rerun_observer_comparison_with_target_store(
                previous_observer_result,
                store,
                &ObserverComparisonRerunV2Config {
                    run_id: config.run_id.clone(),
                    use_persisted_target_store: true,
                    compare_member_opinion: true,
                    compare_chairman_decision: true,
                    compare_risk_governor: true,
                    paper_only: true,
                },
            )
        })
    } else {
        None
    };
    let ledger_trend = if config.compute_ledger_trend {
        let mut ledger = if let Some(path) = config.observer_ledger_path.as_ref() {
            if Path::new(path).exists() {
                load_observer_comparison_ledger_from_local_json(Path::new(path))?
            } else {
                ObserverComparisonLedger {
                    ledger_id: "observer-comparison-ledger".to_string(),
                    entries: Vec::new(),
                    entry_count: 0,
                    latest_entry_id: None,
                    paper_only: true,
                }
            }
        } else {
            ObserverComparisonLedger {
                ledger_id: "observer-comparison-ledger".to_string(),
                entries: Vec::new(),
                entry_count: 0,
                latest_entry_id: None,
                paper_only: true,
            }
        };
        append_observer_comparison_ledger_entry(
            &mut ledger,
            ObserverComparisonLedgerEntry {
                entry_id: format!("{}-seed-entry", config.run_id),
                run_id: config.run_id.clone(),
                timestamp: None,
                observer_member_count: previous_observer_result.observer_members.len(),
                comparison_count: previous_observer_result.comparison_summary.comparison_count,
                disagreement_count: comparison_rerun_result
                    .as_ref()
                    .map(|result| result.new_disagreement_count)
                    .unwrap_or(
                        previous_observer_result
                            .comparison_summary
                            .disagreement_count,
                    ),
                comparison_summary_status: comparison_rerun_result
                    .as_ref()
                    .map(|result| result.new_comparison_summary_status)
                    .unwrap_or(previous_observer_result.comparison_summary.summary_status),
                readiness_status: previous_observer_result
                    .readiness_recheck
                    .as_ref()
                    .map(|result| result.readiness_status)
                    .unwrap_or(SmartCoreObserverLaneReadinessStatus::NeedsMoreTargets),
                target_coverage_status: if smoke_result.applied_target_count > 0 {
                    ObserverTargetCoverageClosureStatus::NoClosureNeeded
                } else {
                    ObserverTargetCoverageClosureStatus::ClosurePlanned
                },
                safety_status: previous_observer_result.observer_safety_guard.guard_status,
                target_count: smoke_result.apply_result.new_target_count,
                paper_only: true,
            },
        );
        let (normalized_ledger, _) = normalize_observer_comparison_ledger_entries(&ledger);
        if let Some(path) = config.observer_ledger_path.as_ref() {
            save_observer_comparison_ledger_to_local_json(Path::new(path), &normalized_ledger)?;
        }
        Some(compute_observer_comparison_ledger_trend(
            &normalized_ledger,
            ObserverComparisonLedgerTrendWindow::All,
        ))
    } else {
        None
    };
    let previous_readiness = batch_result
        .observer_readiness_v2_gate
        .as_ref()
        .cloned()
        .unwrap_or(SmartCoreObserverReadinessV2Gate {
            gate_id: format!("{}-fallback-readiness-v2", config.run_id),
            previous_readiness_status: SmartCoreObserverLaneReadinessStatus::NeedsMoreTargets,
            closure_apply_status: ObserverTargetClosureApplyStatus::NoApprovedTargets,
            comparison_rerun_status: ObserverComparisonRerunV2Status::NeedsMoreTargets,
            ledger_trend_status: ObserverComparisonLedgerTrendStatus::InsufficientHistory,
            warning_reduction_status: ObserverReadinessWarningReductionStatus::Unchanged,
            observer_safety_status: previous_observer_result.observer_safety_guard.guard_status,
            decision_isolation_status: ObserverApplyDecisionIsolationGuardStatus::Preserved,
            warning_free_non_voting_ready: false,
            readiness_status: SmartCoreObserverReadinessV2Status::NeedsMoreTargets,
            blockers: Vec::new(),
            warnings: Vec::new(),
            paper_only: true,
        });
    let readiness_recheck = recheck_observer_readiness_with_seeded_targets(
        &previous_readiness,
        &smoke_result,
        comparison_rerun_result.as_ref(),
        ledger_trend.as_ref(),
    );
    let decision_isolation_guard = evaluate_observer_seeded_target_decision_isolation(
        &smoke_result,
        batch_result,
        Some(batch_result),
    );
    let owner_summary = config
        .emit_owner_summary
        .then(|| build_owner_observer_seeded_target_summary(&readiness_recheck, &smoke_result));
    let result = ObserverSeedApplyTrendRunResult {
        run_id: config.run_id.clone(),
        controlled_apply_smoke_result: smoke_result,
        comparison_rerun_result,
        ledger_trend,
        readiness_recheck,
        owner_summary,
        decision_isolation_guard: decision_isolation_guard.clone(),
        run_status: if decision_isolation_guard.guard_status
            == ObserverSeededTargetDecisionIsolationGuardStatus::Violated
        {
            ObserverSeedApplyTrendRunStatus::Failed
        } else if config.dry_run {
            ObserverSeedApplyTrendRunStatus::PassedWithWarnings
        } else {
            ObserverSeedApplyTrendRunStatus::Passed
        },
        paper_only: true,
    };
    if let Some(path) = config.output_path.as_ref() {
        validate_local_json_path(Path::new(path), "observer seed apply trend output path")?;
        write_safe_json(Path::new(path), &result)?;
    }
    Ok(result)
}

fn apply_owner_observer_seeded_target_summary_update(
    batch_id: &str,
    section: Option<OwnerCoreDebugSection>,
    update: Option<OwnerObserverSeededTargetSummary>,
) -> Option<OwnerCoreDebugSection> {
    let Some(update) = update else {
        return section;
    };
    if let Some(mut section) = section {
        section.summary = format!(
            "{}; observer_seeded_targets={}, observer_seed_readiness={:?}",
            section.summary, update.applied_target_count, update.readiness_status
        );
        section.observer_seeded_target_summary = Some(update);
        Some(section)
    } else {
        Some(OwnerCoreDebugSection {
            section_id: format!("{batch_id}-owner-core-debug"),
            cards: Vec::new(),
            summary: "observer_seeded_target_summary=1".to_string(),
            paper_only_warning:
                "observer seeded target summary is paper-only diagnostics; not investment advice, not trading, not orders"
                    .to_string(),
            debug_only_warning:
                "observer seeded target summary remains read-only/non-voting and must not feed committee decisions"
                    .to_string(),
            calibration_summary: None,
            recalibration_summary: None,
            shadow_opinion_summary: None,
            shadow_stability_summary: None,
            shadow_scenario_sweep_summary: None,
            observer_section: None,
            observer_coverage_closure_summary: None,
            observer_trend_summary: None,
            observer_seeded_target_summary: Some(update),
            observer_apply_readiness_summary: None,
            paper_only: true,
        })
    }
}

fn observer_seed_apply_trend_requested_from_flags(
    enabled: bool,
    apply_targets: bool,
    target_store_output_path: Option<&String>,
    output_path: Option<&String>,
    _dry_run: bool,
    _require_approved_target: bool,
    _rerun_comparison: bool,
    _compute_ledger_trend: bool,
    _recheck_readiness: bool,
    _emit_owner_summary: bool,
) -> bool {
    enabled || apply_targets || target_store_output_path.is_some() || output_path.is_some()
}

fn maybe_run_observer_seed_apply_trend_for_batch_result(
    run_id: String,
    enabled: bool,
    dry_run: bool,
    apply_targets: bool,
    target_store_output_path: Option<&String>,
    observer_ledger_path: Option<&String>,
    output_path: Option<&String>,
    require_approved_target: bool,
    rerun_comparison: bool,
    compute_ledger_trend: bool,
    recheck_readiness: bool,
    emit_owner_summary: bool,
    batch_result: &mut BatchCommitteeCycleResult,
) -> Result<Option<ObserverSeedApplyTrendRunResult>, String> {
    if !observer_seed_apply_trend_requested_from_flags(
        enabled,
        apply_targets,
        target_store_output_path,
        output_path,
        dry_run,
        require_approved_target,
        rerun_comparison,
        compute_ledger_trend,
        recheck_readiness,
        emit_owner_summary,
    ) {
        return Ok(None);
    }
    let observer_run_result = batch_result
        .smartcore_observer_lane_run_result
        .clone()
        .ok_or_else(|| "observer seed apply trend requires observer lane result".to_string())?;
    let result = run_observer_seed_apply_trend(
        batch_result,
        None,
        None,
        None,
        &observer_run_result,
        &ObserverSeedApplyTrendRunConfig {
            run_id: run_id.clone(),
            enabled,
            dry_run,
            apply_targets,
            target_store_input_path: None,
            target_store_output_path: target_store_output_path.cloned(),
            observer_ledger_path: observer_ledger_path.cloned(),
            output_path: output_path.cloned(),
            require_approved_target,
            rerun_comparison,
            compute_ledger_trend,
            recheck_readiness,
            emit_owner_summary,
            paper_only: true,
        },
    )?;
    if let Some(shadow_alignment_result) =
        batch_result.smartcore_shadow_alignment_run_result.as_mut()
    {
        shadow_alignment_result.owner_core_debug_section =
            apply_owner_observer_seeded_target_summary_update(
                &batch_result.batch_id,
                shadow_alignment_result.owner_core_debug_section.take(),
                result.owner_summary.clone(),
            );
    }
    batch_result.observer_seed_apply_trend_run_result = Some(result.clone());
    Ok(Some(result))
}

pub fn default_observer_explicit_apply_policy() -> ObserverExplicitApplyPolicy {
    ObserverExplicitApplyPolicy {
        policy_id: "observer-explicit-apply-policy".to_string(),
        require_apply_mode_apply_approved_targets: true,
        require_dry_run_false: true,
        require_approved_status: true,
        require_eval_only: true,
        require_not_input_feature: true,
        require_non_voting_observer: true,
        require_read_only_observer: true,
        reject_needs_review: true,
        reject_rejected: true,
        reject_low_trust: true,
        reject_news_only: true,
        reject_unknown_deferred: true,
        reject_broker_order_account: true,
        reject_trade_signal_terms: true,
        paper_only: true,
    }
}

pub fn validate_observer_explicit_apply_policy(
    policy: &ObserverExplicitApplyPolicy,
) -> Result<(), String> {
    if !policy.paper_only {
        return Err("observer explicit apply policy must stay paper_only".to_string());
    }
    if !policy.require_apply_mode_apply_approved_targets
        || !policy.require_dry_run_false
        || !policy.require_approved_status
        || !policy.require_eval_only
        || !policy.require_not_input_feature
        || !policy.require_non_voting_observer
        || !policy.require_read_only_observer
    {
        return Err("observer explicit apply policy must stay strict".to_string());
    }
    if !policy.reject_needs_review
        || !policy.reject_rejected
        || !policy.reject_low_trust
        || !policy.reject_news_only
        || !policy.reject_unknown_deferred
        || !policy.reject_broker_order_account
        || !policy.reject_trade_signal_terms
    {
        return Err(
            "observer explicit apply policy must reject unsafe or ambiguous targets".to_string(),
        );
    }
    Ok(())
}

fn observer_target_is_low_trust_v3(target: &ObserverAgreementTargetRecord) -> bool {
    matches!(
        target.source_confidence,
        SourceConfidence::Low | SourceConfidence::ReviewRequired
    )
}

fn observer_target_is_news_only_v3(target: &ObserverAgreementTargetRecord) -> bool {
    let reason = target.reason.to_ascii_lowercase();
    reason.contains("news") && !reason.contains("paper")
}

fn validate_observer_explicit_apply_target(
    target: &ObserverAgreementTargetRecord,
    policy: &ObserverExplicitApplyPolicy,
) -> Result<(), String> {
    if policy.require_approved_status
        && target.approval_status != ObserverAgreementTargetApprovalStatus::Approved
    {
        return Err("target must be approved".to_string());
    }
    if policy.require_eval_only && !target.eval_only {
        return Err("target must stay eval_only".to_string());
    }
    if policy.require_not_input_feature && !target.not_input_feature {
        return Err("target must stay not_input_feature".to_string());
    }
    if !target.paper_only {
        return Err("target must stay paper_only".to_string());
    }
    if policy.reject_low_trust && observer_target_is_low_trust_v3(target) {
        return Err("target is low trust".to_string());
    }
    if policy.reject_news_only && observer_target_is_news_only_v3(target) {
        return Err("target is news-only".to_string());
    }
    if policy.reject_unknown_deferred
        && matches!(
            target.target_bucket,
            SmartCoreHeadBucketNormalizedValue::Unknown
                | SmartCoreHeadBucketNormalizedValue::Deferred
        )
    {
        return Err("target uses Unknown/Deferred bucket".to_string());
    }
    let base_policy = default_observer_target_closure_apply_policy();
    if policy.reject_broker_order_account && observer_target_is_unsafe(target, &base_policy) {
        return Err("target contains unsafe broker/order/account terms".to_string());
    }
    Ok(())
}

pub fn apply_observer_approved_targets_v2(
    converted_targets: &[ObserverAgreementTargetRecord],
    existing_store: Option<&ObserverAgreementTargetStore>,
    config: &ObserverApprovedTargetApplyV2Config,
    policy: &ObserverExplicitApplyPolicy,
) -> Result<ObserverApprovedTargetApplyV2Result, String> {
    validate_observer_explicit_apply_policy(policy)?;
    if !config.paper_only {
        return Err("observer approved apply v2 config must stay paper_only".to_string());
    }
    if config.apply_mode == ObserverExplicitApplyMode::ApplyApprovedTargets
        && config.dry_run
        && policy.require_dry_run_false
    {
        return Ok(ObserverApprovedTargetApplyV2Result {
            run_id: config.run_id.clone(),
            approved_input_count: 0,
            applied_count: 0,
            skipped_needs_review_count: 0,
            skipped_rejected_count: 0,
            skipped_unsafe_count: 0,
            skipped_duplicate_count: 0,
            previous_store_count: existing_store.map(|store| store.target_count).unwrap_or(0),
            new_store_count: existing_store.map(|store| store.target_count).unwrap_or(0),
            wrote_target_store: false,
            target_store_path: config.target_store_output_path.clone(),
            apply_status: ObserverApprovedTargetApplyV2Status::Blocked,
            warnings: vec!["apply mode requires dry_run=false".to_string()],
            applied_targets: Vec::new(),
            accepted_target_store: existing_store.cloned(),
            paper_only: true,
        });
    }
    let mut warnings = Vec::new();
    let mut approved = Vec::new();
    let mut skipped_needs_review_count = 0usize;
    let mut skipped_rejected_count = 0usize;
    let mut skipped_unsafe_count = 0usize;
    let mut skipped_duplicate_count = 0usize;
    let approved_input_count = converted_targets
        .iter()
        .filter(|target| target.approval_status == ObserverAgreementTargetApprovalStatus::Approved)
        .count();
    let mut seen = std::collections::BTreeSet::new();
    let mut sorted_targets = converted_targets.to_vec();
    sorted_targets.sort_by(|left, right| {
        observer_target_dedupe_key(left).cmp(&observer_target_dedupe_key(right))
    });
    for target in sorted_targets {
        match target.approval_status {
            ObserverAgreementTargetApprovalStatus::NeedsReview => {
                skipped_needs_review_count += 1;
                continue;
            }
            ObserverAgreementTargetApprovalStatus::Rejected => {
                skipped_rejected_count += 1;
                continue;
            }
            ObserverAgreementTargetApprovalStatus::Approved => {}
            ObserverAgreementTargetApprovalStatus::Candidate => {
                skipped_unsafe_count += 1;
                continue;
            }
        }
        if validate_observer_explicit_apply_target(&target, policy).is_err() {
            skipped_unsafe_count += 1;
            continue;
        }
        let key = observer_target_dedupe_key(&target);
        if !seen.insert(key) {
            skipped_duplicate_count += 1;
            continue;
        }
        approved.push(target);
    }
    let previous_store_count = existing_store.map(|store| store.target_count).unwrap_or(0);
    let preview_store = dedupe_observer_targets(&build_observer_target_store(
        format!("{}-approved-store", config.run_id),
        ObserverAgreementTargetSet {
            target_set_id: format!("{}-approved-target-set", config.run_id),
            target_count: approved.len()
                + existing_store
                    .map(|store| store.target_set.targets.len())
                    .unwrap_or(0),
            approved_count: approved.len()
                + existing_store
                    .map(|store| store.target_set.approved_count)
                    .unwrap_or(0),
            needs_review_count: 0,
            rejected_count: 0,
            targets: existing_store
                .map(|store| store.target_set.targets.clone())
                .unwrap_or_default()
                .into_iter()
                .chain(approved.clone())
                .collect(),
            paper_only: true,
        },
    ));
    if config.require_at_least_one_approved_target && approved.is_empty() {
        warnings.push("no approved observer targets available for explicit apply".to_string());
        return Ok(ObserverApprovedTargetApplyV2Result {
            run_id: config.run_id.clone(),
            approved_input_count,
            applied_count: 0,
            skipped_needs_review_count,
            skipped_rejected_count,
            skipped_unsafe_count,
            skipped_duplicate_count,
            previous_store_count,
            new_store_count: previous_store_count,
            wrote_target_store: false,
            target_store_path: config.target_store_output_path.clone(),
            apply_status: ObserverApprovedTargetApplyV2Status::NoApprovedTargets,
            warnings,
            applied_targets: Vec::new(),
            accepted_target_store: Some(preview_store),
            paper_only: true,
        });
    }
    let preview_count = preview_store.target_count;
    if config.dry_run || config.apply_mode == ObserverExplicitApplyMode::DryRun {
        return Ok(ObserverApprovedTargetApplyV2Result {
            run_id: config.run_id.clone(),
            approved_input_count,
            applied_count: 0,
            skipped_needs_review_count,
            skipped_rejected_count,
            skipped_unsafe_count,
            skipped_duplicate_count,
            previous_store_count,
            new_store_count: preview_count,
            wrote_target_store: false,
            target_store_path: config.target_store_output_path.clone(),
            apply_status: ObserverApprovedTargetApplyV2Status::DryRunPreview,
            warnings,
            applied_targets: approved,
            accepted_target_store: Some(preview_store),
            paper_only: true,
        });
    }
    let preview_acceptance = check_observer_target_store_acceptance(&preview_store);
    if preview_acceptance.acceptance_status == ObserverTargetStoreAcceptanceStatus::Rejected {
        warnings.extend(preview_acceptance.blockers);
        return Ok(ObserverApprovedTargetApplyV2Result {
            run_id: config.run_id.clone(),
            approved_input_count,
            applied_count: 0,
            skipped_needs_review_count,
            skipped_rejected_count,
            skipped_unsafe_count,
            skipped_duplicate_count,
            previous_store_count,
            new_store_count: preview_count,
            wrote_target_store: false,
            target_store_path: config.target_store_output_path.clone(),
            apply_status: ObserverApprovedTargetApplyV2Status::Blocked,
            warnings,
            applied_targets: Vec::new(),
            accepted_target_store: Some(preview_store),
            paper_only: true,
        });
    }
    let Some(path) = config.target_store_output_path.as_ref() else {
        warnings
            .push("target store output path required for approved target persistence".to_string());
        return Ok(ObserverApprovedTargetApplyV2Result {
            run_id: config.run_id.clone(),
            approved_input_count,
            applied_count: 0,
            skipped_needs_review_count,
            skipped_rejected_count,
            skipped_unsafe_count,
            skipped_duplicate_count,
            previous_store_count,
            new_store_count: preview_count,
            wrote_target_store: false,
            target_store_path: None,
            apply_status: ObserverApprovedTargetApplyV2Status::Blocked,
            warnings,
            applied_targets: Vec::new(),
            accepted_target_store: Some(preview_store),
            paper_only: true,
        });
    };
    save_observer_agreement_target_store_to_local_json(Path::new(path), &preview_store)?;
    let applied_count = approved.len();
    let apply_status = if skipped_duplicate_count > 0
        || skipped_unsafe_count > 0
        || preview_acceptance.acceptance_status
            == ObserverTargetStoreAcceptanceStatus::AcceptedWithWarnings
    {
        ObserverApprovedTargetApplyV2Status::AppliedWithWarnings
    } else {
        ObserverApprovedTargetApplyV2Status::Applied
    };
    Ok(ObserverApprovedTargetApplyV2Result {
        run_id: config.run_id.clone(),
        approved_input_count,
        applied_count,
        skipped_needs_review_count,
        skipped_rejected_count,
        skipped_unsafe_count,
        skipped_duplicate_count,
        previous_store_count,
        new_store_count: preview_count,
        wrote_target_store: true,
        target_store_path: config.target_store_output_path.clone(),
        apply_status,
        warnings,
        applied_targets: approved,
        accepted_target_store: Some(preview_store),
        paper_only: true,
    })
}

pub fn check_observer_target_store_acceptance(
    store: &ObserverAgreementTargetStore,
) -> ObserverTargetStoreAcceptanceCheck {
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    let eval_only_count = store
        .target_set
        .targets
        .iter()
        .filter(|target| target.eval_only)
        .count();
    let not_input_feature_count = store
        .target_set
        .targets
        .iter()
        .filter(|target| target.not_input_feature)
        .count();
    let approved_count = store
        .target_set
        .targets
        .iter()
        .filter(|target| target.approval_status == ObserverAgreementTargetApprovalStatus::Approved)
        .count();
    let invalid_count = store
        .target_set
        .targets
        .iter()
        .filter(|target| {
            target.approval_status != ObserverAgreementTargetApprovalStatus::Approved
                || !target.eval_only
                || !target.not_input_feature
                || !target.paper_only
                || observer_target_is_low_trust_v3(target)
                || observer_target_is_news_only_v3(target)
                || validate_observer_explicit_apply_target(
                    target,
                    &default_observer_explicit_apply_policy(),
                )
                .is_err()
        })
        .count();
    let deduped = dedupe_observer_targets(store);
    let duplicate_count = store
        .target_set
        .targets
        .len()
        .saturating_sub(deduped.target_set.targets.len());
    if invalid_count > 0 {
        blockers.push("observer target store contains invalid targets".to_string());
    }
    if duplicate_count > 0 {
        warnings.push(
            "observer target store contained duplicate targets and was normalized".to_string(),
        );
    }
    ObserverTargetStoreAcceptanceCheck {
        store_id: store.store_id.clone(),
        target_count: store.target_count,
        approved_count,
        invalid_count,
        eval_only_count,
        not_input_feature_count,
        duplicate_count,
        acceptance_status: if invalid_count > 0 {
            ObserverTargetStoreAcceptanceStatus::Rejected
        } else if duplicate_count > 0 {
            ObserverTargetStoreAcceptanceStatus::AcceptedWithWarnings
        } else {
            ObserverTargetStoreAcceptanceStatus::Accepted
        },
        blockers,
        warnings,
        paper_only: true,
    }
}

pub fn rerun_observer_comparison_with_accepted_store_v3(
    observer_run_result: &SmartCoreObserverLaneRunResult,
    accepted_target_store: &ObserverAgreementTargetStore,
    config: &ObserverComparisonRerunV3Config,
) -> ObserverComparisonRerunV3Result {
    let acceptance = check_observer_target_store_acceptance(accepted_target_store);
    let previous_readiness_status = observer_run_result
        .readiness_recheck
        .as_ref()
        .map(|result| result.readiness_status)
        .unwrap_or(SmartCoreObserverLaneReadinessStatus::NeedsMoreTargets);
    if config.require_target_store_accepted
        && acceptance.acceptance_status == ObserverTargetStoreAcceptanceStatus::Rejected
    {
        return ObserverComparisonRerunV3Result {
            previous_target_count: 0,
            new_target_count: 0,
            target_delta: 0,
            previous_disagreement_count: observer_run_result.comparison_summary.disagreement_count,
            new_disagreement_count: observer_run_result.comparison_summary.disagreement_count,
            disagreement_delta: 0,
            previous_readiness_status,
            new_comparison_summary_status: observer_run_result.comparison_summary.summary_status,
            target_store_accepted: false,
            rerun_status: ObserverComparisonRerunV3Status::Failed,
            paper_only: true,
        };
    }
    let rerun_v2 = rerun_observer_comparison_with_target_store(
        observer_run_result,
        accepted_target_store,
        &ObserverComparisonRerunV2Config {
            run_id: config.run_id.clone(),
            use_persisted_target_store: config.use_persisted_target_store,
            compare_member_opinion: config.compare_member_opinion,
            compare_chairman_decision: config.compare_chairman_decision,
            compare_risk_governor: config.compare_risk_governor,
            paper_only: true,
        },
    );
    ObserverComparisonRerunV3Result {
        previous_target_count: rerun_v2.previous_target_count,
        new_target_count: rerun_v2.new_target_count,
        target_delta: rerun_v2.target_delta,
        previous_disagreement_count: rerun_v2.previous_disagreement_count,
        new_disagreement_count: rerun_v2.new_disagreement_count,
        disagreement_delta: rerun_v2.disagreement_delta,
        previous_readiness_status,
        new_comparison_summary_status: rerun_v2.new_comparison_summary_status,
        target_store_accepted: true,
        rerun_status: match rerun_v2.rerun_status {
            ObserverComparisonRerunV2Status::Improved => ObserverComparisonRerunV3Status::Improved,
            ObserverComparisonRerunV2Status::NoChange => ObserverComparisonRerunV3Status::NoChange,
            ObserverComparisonRerunV2Status::Worse => ObserverComparisonRerunV3Status::Worse,
            ObserverComparisonRerunV2Status::NeedsMoreTargets => {
                ObserverComparisonRerunV3Status::NeedsMoreTargets
            }
            ObserverComparisonRerunV2Status::Failed => ObserverComparisonRerunV3Status::Failed,
        },
        paper_only: true,
    }
}

fn trend_direction_from_target_counts(series: &[usize]) -> ObserverTargetCountTrendDirection {
    if series.len() < 2 {
        ObserverTargetCountTrendDirection::InsufficientHistory
    } else if series.last().unwrap_or(&0) > series.first().unwrap_or(&0) {
        ObserverTargetCountTrendDirection::Increasing
    } else if series.last().unwrap_or(&0) < series.first().unwrap_or(&0) {
        ObserverTargetCountTrendDirection::Decreasing
    } else {
        ObserverTargetCountTrendDirection::Stable
    }
}

pub fn compute_observer_comparison_ledger_trend_v2(
    ledger: &ObserverComparisonLedger,
) -> ObserverComparisonLedgerTrendV2 {
    let trend =
        compute_observer_comparison_ledger_trend(ledger, ObserverComparisonLedgerTrendWindow::All);
    let latest = latest_observer_comparison_entry(ledger);
    let target_count_series = ledger
        .entries
        .iter()
        .map(|entry| entry.target_count)
        .collect::<Vec<_>>();
    ObserverComparisonLedgerTrendV2 {
        ledger_id: ledger.ledger_id.clone(),
        entry_count: ledger.entry_count,
        latest_readiness_status: latest
            .map(|entry| entry.readiness_status)
            .unwrap_or(SmartCoreObserverLaneReadinessStatus::NeedsMoreTargets),
        latest_target_count: latest.map(|entry| entry.target_count).unwrap_or(0),
        latest_disagreement_count: latest.map(|entry| entry.disagreement_count).unwrap_or(0),
        target_count_trend: trend_direction_from_target_counts(&target_count_series),
        disagreement_trend: trend.disagreement_trend,
        readiness_trend: trend.readiness_trend,
        trend_status: trend.trend_status,
        paper_only: true,
    }
}

pub fn default_chairman_reward_penalty_contract() -> ChairmanRewardPenaltyContract {
    ChairmanRewardPenaltyContract {
        contract_id: "chairman-reward-penalty-contract".to_string(),
        chairman_id: "chairman-ai".to_string(),
        status: ChairmanGovernanceContractStatus::ContractOnly,
        signals: vec![ChairmanRewardPenaltySignal::Neutral],
        can_mutate_score: false,
        can_mutate_voice_weight: false,
        can_promote_member: false,
        can_demote_member: false,
        can_override_risk_governor: false,
        allowed_inputs: vec![
            ChairmanGovernanceInputKind::PaperOutcome,
            ChairmanGovernanceInputKind::RiskGovernorStatus,
            ChairmanGovernanceInputKind::ObserverComparisonLedger,
            ChairmanGovernanceInputKind::MemberExperienceRecord,
            ChairmanGovernanceInputKind::OwnerFeedback,
        ],
        forbidden_inputs: vec![
            ChairmanGovernanceInputKind::LiveTrade,
            ChairmanGovernanceInputKind::BrokerAccount,
            ChairmanGovernanceInputKind::RealPnL,
            ChairmanGovernanceInputKind::UnvalidatedObserverTarget,
        ],
        paper_only: true,
    }
}

pub fn evaluate_chairman_governance_readiness(
    contract: &ChairmanRewardPenaltyContract,
    observer_store: Option<&ObserverAgreementTargetStore>,
    ledger: Option<&ObserverComparisonLedger>,
    experience_store: Option<&[MemberExperienceRecord]>,
    paper_outcome_evidence_ready: bool,
    risk_governor_available: bool,
    observer_safety_status: SmartCoreObserverLaneSafetyGuardStatus,
) -> ChairmanGovernanceReadinessCheck {
    let observer_target_store_ready = observer_store.is_some();
    let observer_ledger_ready = ledger.map(|ledger| ledger.entry_count > 0).unwrap_or(false);
    let member_experience_store_ready = experience_store
        .map(|records| !records.is_empty())
        .unwrap_or(false);
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    let readiness_status = if observer_safety_status
        == SmartCoreObserverLaneSafetyGuardStatus::Violated
    {
        blockers.push("observer safety guard is violated".to_string());
        ChairmanGovernanceReadinessStatus::BlockedBySafety
    } else if contract.can_mutate_score
        || contract.can_mutate_voice_weight
        || contract.can_promote_member
        || contract.can_demote_member
        || contract.can_override_risk_governor
    {
        blockers.push(
            "chairman governance contract must remain contract-only and no-mutation".to_string(),
        );
        ChairmanGovernanceReadinessStatus::BlockedBySafety
    } else if !paper_outcome_evidence_ready {
        blockers.push("paper outcome evidence is not ready".to_string());
        ChairmanGovernanceReadinessStatus::NeedsMorePaperEvidence
    } else if !observer_ledger_ready {
        warnings.push("observer ledger history is still thin".to_string());
        ChairmanGovernanceReadinessStatus::NeedsMoreObserverHistory
    } else if !member_experience_store_ready
        || !observer_target_store_ready
        || !risk_governor_available
    {
        warnings.push("governance shadow inputs are present but still incomplete".to_string());
        ChairmanGovernanceReadinessStatus::ShadowGovernanceReadyWithWarnings
    } else {
        ChairmanGovernanceReadinessStatus::ShadowGovernanceReady
    };
    ChairmanGovernanceReadinessCheck {
        contract_id: contract.contract_id.clone(),
        observer_target_store_ready,
        observer_ledger_ready,
        member_experience_store_ready,
        paper_outcome_evidence_ready,
        risk_governor_available,
        can_start_shadow_reward_evaluation: matches!(
            readiness_status,
            ChairmanGovernanceReadinessStatus::ShadowGovernanceReady
                | ChairmanGovernanceReadinessStatus::ShadowGovernanceReadyWithWarnings
        ) && contract.status
            == ChairmanGovernanceContractStatus::ContractOnly,
        readiness_status,
        blockers,
        warnings,
        paper_only: true,
    }
}

pub fn build_owner_observer_apply_readiness_summary(
    batch_result: &BatchCommitteeCycleResult,
    readiness_v3: &SmartCoreObserverReadinessV3Gate,
    chairman_governance_check: &ChairmanGovernanceReadinessCheck,
    apply_result: &ObserverApprovedTargetApplyV2Result,
) -> OwnerObserverApplyReadinessSummary {
    let (approved_seed_count, converted_target_count) = batch_result
        .observer_seed_apply_trend_run_result
        .as_ref()
        .map(|result| {
            (
                result
                    .controlled_apply_smoke_result
                    .seed_build_result
                    .approved_seed_count,
                result
                    .controlled_apply_smoke_result
                    .seed_conversion_result
                    .converted_target_count,
            )
        })
        .unwrap_or((
            apply_result.approved_input_count,
            apply_result.approved_input_count,
        ));
    OwnerObserverApplyReadinessSummary {
        summary_id: format!("{}-owner-apply-readiness-summary", apply_result.run_id),
        approved_seed_count,
        converted_target_count,
        applied_target_count: apply_result.applied_count,
        target_store_count: apply_result
            .accepted_target_store
            .as_ref()
            .map(|store| store.target_count)
            .unwrap_or(0),
        previous_readiness_status: readiness_v3.previous_readiness_status,
        new_readiness_status: readiness_v3.readiness_status,
        chairman_governance_readiness_status: chairman_governance_check.readiness_status,
        message: "Approved observer targets were applied only for evaluation. Observer remains non-voting and read-only. This still does not change committee decisions. Chairman reward/penalty contract is prepared but not active.".to_string(),
        non_voting: true,
        read_only: true,
        eval_only: true,
        not_investment_signal: true,
        not_committee_opinion: true,
        paper_only: true,
    }
}

pub fn evaluate_observer_approved_apply_decision_isolation_v3(
    apply_result: &ObserverApprovedTargetApplyV2Result,
    chairman_contract: &ChairmanRewardPenaltyContract,
    batch_result_before: &BatchCommitteeCycleResult,
    batch_result_after: Option<&BatchCommitteeCycleResult>,
) -> ObserverApprovedApplyDecisionIsolationGuardV3 {
    let after = batch_result_after.unwrap_or(batch_result_before);
    let applied_targets_used_as_input_feature = apply_result
        .applied_targets
        .iter()
        .any(|target| !target.not_input_feature);
    let applied_targets_used_as_member_opinion =
        batch_result_before.member_opinions != after.member_opinions;
    let applied_targets_used_in_committee_session =
        batch_result_before.committee_sessions != after.committee_sessions;
    let applied_targets_used_in_chairman_decision =
        batch_result_before.chairman_decisions != after.chairman_decisions;
    let applied_targets_used_in_risk_governor = batch_result_before
        .chairman_decisions
        .iter()
        .map(|decision| decision.risk_governor_status)
        .collect::<Vec<_>>()
        != after
            .chairman_decisions
            .iter()
            .map(|decision| decision.risk_governor_status)
            .collect::<Vec<_>>();
    let applied_targets_changed_member_score =
        batch_result_before.score_updates != after.score_updates;
    let applied_targets_changed_voice_weight = batch_result_before
        .score_updates
        .iter()
        .map(|update| (update.member_id.clone(), update.new_voice_weight))
        .collect::<Vec<_>>()
        != after
            .score_updates
            .iter()
            .map(|update| (update.member_id.clone(), update.new_voice_weight))
            .collect::<Vec<_>>();
    let applied_targets_changed_committee_decision = applied_targets_used_in_chairman_decision;
    let chairman_contract_mutated_score = chairman_contract.can_mutate_score;
    let chairman_contract_mutated_voice = chairman_contract.can_mutate_voice_weight;
    let chairman_contract_promoted_or_demoted_member =
        chairman_contract.can_promote_member || chairman_contract.can_demote_member;
    let applied_target_ids = apply_result
        .applied_targets
        .iter()
        .map(|record| record.target_id.clone())
        .collect::<Vec<_>>();
    let applied_targets_used_as_trade_signal =
        value_contains_debug_marker(&after.committee_sessions, &applied_target_ids);
    let applied_targets_used_as_order =
        value_contains_debug_marker(&after.event_queue, &applied_target_ids);
    let mut violations = Vec::new();
    if applied_targets_used_as_input_feature {
        violations.push("approved apply target entered input feature path".to_string());
    }
    if applied_targets_used_as_member_opinion {
        violations.push("approved apply target changed member opinion".to_string());
    }
    if applied_targets_used_in_committee_session {
        violations.push("approved apply target changed committee session".to_string());
    }
    if applied_targets_used_in_chairman_decision {
        violations.push("approved apply target changed chairman decision".to_string());
    }
    if applied_targets_used_in_risk_governor {
        violations.push("approved apply target changed risk governor".to_string());
    }
    if applied_targets_used_as_trade_signal {
        violations.push("approved apply target created trade signal".to_string());
    }
    if applied_targets_used_as_order {
        violations.push("approved apply target created order".to_string());
    }
    if applied_targets_changed_member_score {
        violations.push("approved apply target changed member score".to_string());
    }
    if applied_targets_changed_voice_weight {
        violations.push("approved apply target changed voice weight".to_string());
    }
    if chairman_contract_mutated_score {
        violations.push("chairman contract mutated score".to_string());
    }
    if chairman_contract_mutated_voice {
        violations.push("chairman contract mutated voice weight".to_string());
    }
    if chairman_contract_promoted_or_demoted_member {
        violations.push("chairman contract promoted or demoted member".to_string());
    }
    ObserverApprovedApplyDecisionIsolationGuardV3 {
        applied_targets_used_as_input_feature,
        applied_targets_used_as_member_opinion,
        applied_targets_used_in_committee_session,
        applied_targets_used_in_chairman_decision,
        applied_targets_used_in_risk_governor,
        applied_targets_used_as_trade_signal,
        applied_targets_used_as_order,
        applied_targets_changed_member_score,
        applied_targets_changed_voice_weight,
        applied_targets_changed_committee_decision,
        chairman_contract_mutated_score,
        chairman_contract_mutated_voice,
        chairman_contract_promoted_or_demoted_member,
        guard_status: if violations.is_empty() {
            ObserverApprovedApplyDecisionIsolationGuardV3Status::Preserved
        } else {
            ObserverApprovedApplyDecisionIsolationGuardV3Status::Violated
        },
        violations,
        paper_only: true,
    }
}

pub fn evaluate_smartcore_observer_readiness_v3(
    previous_readiness_status: SmartCoreObserverReadinessV2Status,
    apply_result: &ObserverApprovedTargetApplyV2Result,
    target_store_check: &ObserverTargetStoreAcceptanceCheck,
    rerun_result: &ObserverComparisonRerunV3Result,
    ledger_trend: &ObserverComparisonLedgerTrendV2,
    observer_safety_status: SmartCoreObserverLaneSafetyGuardStatus,
    decision_isolation: &ObserverApprovedApplyDecisionIsolationGuardV3,
) -> SmartCoreObserverReadinessV3Gate {
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    let readiness_status = if observer_safety_status
        == SmartCoreObserverLaneSafetyGuardStatus::Violated
    {
        blockers.push("observer safety guard is violated".to_string());
        SmartCoreObserverReadinessV3Status::BlockedBySafety
    } else if decision_isolation.guard_status
        == ObserverApprovedApplyDecisionIsolationGuardV3Status::Violated
    {
        blockers.extend(decision_isolation.violations.iter().cloned());
        SmartCoreObserverReadinessV3Status::BlockedByDecisionLeak
    } else if target_store_check.acceptance_status == ObserverTargetStoreAcceptanceStatus::Rejected
    {
        blockers.extend(target_store_check.blockers.iter().cloned());
        SmartCoreObserverReadinessV3Status::BlockedByTargetStore
    } else if apply_result.apply_status == ObserverApprovedTargetApplyV2Status::Blocked {
        warnings.extend(apply_result.warnings.iter().cloned());
        SmartCoreObserverReadinessV3Status::NeedsApply
    } else if apply_result.approved_input_count > 0
        && apply_result.apply_status == ObserverApprovedTargetApplyV2Status::DryRunPreview
    {
        warnings.push("approved targets are available but still dry-run only".to_string());
        SmartCoreObserverReadinessV3Status::NeedsApply
    } else if apply_result.approved_input_count == 0
        || apply_result.apply_status == ObserverApprovedTargetApplyV2Status::NoApprovedTargets
    {
        warnings.push("no approved targets are available".to_string());
        SmartCoreObserverReadinessV3Status::NeedsMoreTargets
    } else if !matches!(
        apply_result.apply_status,
        ObserverApprovedTargetApplyV2Status::Applied
            | ObserverApprovedTargetApplyV2Status::AppliedWithWarnings
    ) {
        warnings.push("approved targets have not been explicitly applied yet".to_string());
        SmartCoreObserverReadinessV3Status::NeedsApply
    } else if ledger_trend.trend_status == ObserverComparisonLedgerTrendStatus::InsufficientHistory
    {
        warnings.push("observer ledger history is still insufficient".to_string());
        SmartCoreObserverReadinessV3Status::NonVotingObserverReadyWithWarnings
    } else if rerun_result.rerun_status == ObserverComparisonRerunV3Status::Improved
        && target_store_check.acceptance_status == ObserverTargetStoreAcceptanceStatus::Accepted
    {
        SmartCoreObserverReadinessV3Status::NonVotingObserverReady
    } else {
        warnings.push(
            "observer apply path is ready but still carries non-blocking warnings".to_string(),
        );
        SmartCoreObserverReadinessV3Status::NonVotingObserverReadyWithWarnings
    };
    SmartCoreObserverReadinessV3Gate {
        gate_id: format!("{}-readiness-v3", apply_result.run_id),
        previous_readiness_status,
        apply_status: apply_result.apply_status,
        target_store_acceptance_status: target_store_check.acceptance_status,
        comparison_rerun_status: rerun_result.rerun_status,
        ledger_trend_status: ledger_trend.trend_status,
        observer_safety_status,
        decision_isolation_status: decision_isolation.guard_status,
        approved_target_count: apply_result.approved_input_count,
        target_delta: rerun_result.target_delta,
        warning_free_non_voting_ready: readiness_status
            == SmartCoreObserverReadinessV3Status::NonVotingObserverReady,
        readiness_status,
        blockers,
        warnings,
        paper_only: true,
    }
}

pub fn run_observer_approved_apply_and_governance_prep(
    batch_result: &BatchCommitteeCycleResult,
    converted_targets: &[ObserverAgreementTargetRecord],
    previous_observer_result: &SmartCoreObserverLaneRunResult,
    config: &ObserverApprovedApplyAndGovernancePrepRunConfig,
) -> Result<ObserverApprovedApplyAndGovernancePrepRunResult, String> {
    let existing_store = if let Some(path) = config.target_store_input_path.as_ref() {
        Some(load_observer_agreement_target_store_from_local_json(
            Path::new(path),
        )?)
    } else {
        batch_result.observer_agreement_target_store.clone()
    };
    let apply_result = apply_observer_approved_targets_v2(
        converted_targets,
        existing_store.as_ref(),
        &ObserverApprovedTargetApplyV2Config {
            run_id: config.run_id.clone(),
            converted_targets_input_path: None,
            target_store_input_path: config.target_store_input_path.clone(),
            target_store_output_path: config.target_store_output_path.clone(),
            apply_mode: config.apply_mode,
            dry_run: config.dry_run,
            require_at_least_one_approved_target: true,
            paper_only: true,
        },
        &default_observer_explicit_apply_policy(),
    )?;
    let accepted_store = apply_result
        .accepted_target_store
        .clone()
        .or(existing_store.clone())
        .unwrap_or_else(|| {
            build_observer_target_store(
                format!("{}-approved-store", config.run_id),
                ObserverAgreementTargetSet {
                    target_set_id: format!("{}-approved-target-set", config.run_id),
                    target_count: 0,
                    approved_count: 0,
                    needs_review_count: 0,
                    rejected_count: 0,
                    targets: Vec::new(),
                    paper_only: true,
                },
            )
        });
    let target_store_acceptance_check = check_observer_target_store_acceptance(&accepted_store);
    let comparison_rerun_v3 = rerun_observer_comparison_with_accepted_store_v3(
        previous_observer_result,
        &accepted_store,
        &ObserverComparisonRerunV3Config {
            run_id: config.run_id.clone(),
            use_persisted_target_store: true,
            require_target_store_accepted: true,
            compare_member_opinion: true,
            compare_chairman_decision: true,
            compare_risk_governor: true,
            paper_only: true,
        },
    );
    let mut ledger = if let Some(path) = config.observer_ledger_path.as_ref() {
        let path = Path::new(path);
        if path.exists() {
            load_observer_comparison_ledger_from_local_json(path)?
        } else {
            ObserverComparisonLedger {
                ledger_id: "observer-comparison-ledger".to_string(),
                entries: Vec::new(),
                entry_count: 0,
                latest_entry_id: None,
                paper_only: true,
            }
        }
    } else {
        batch_result
            .observer_comparison_ledger
            .clone()
            .unwrap_or(ObserverComparisonLedger {
                ledger_id: "observer-comparison-ledger".to_string(),
                entries: Vec::new(),
                entry_count: 0,
                latest_entry_id: None,
                paper_only: true,
            })
    };
    append_observer_comparison_ledger_entry(
        &mut ledger,
        ObserverComparisonLedgerEntry {
            entry_id: format!("{}-approved-apply-entry", config.run_id),
            run_id: config.run_id.clone(),
            timestamp: None,
            observer_member_count: previous_observer_result.observer_members.len(),
            comparison_count: previous_observer_result.comparison_summary.comparison_count,
            disagreement_count: comparison_rerun_v3.new_disagreement_count,
            comparison_summary_status: comparison_rerun_v3.new_comparison_summary_status,
            readiness_status: comparison_rerun_v3.previous_readiness_status,
            target_coverage_status: if accepted_store.target_count > 0 {
                ObserverTargetCoverageClosureStatus::NoClosureNeeded
            } else {
                ObserverTargetCoverageClosureStatus::ClosurePlanned
            },
            safety_status: previous_observer_result.observer_safety_guard.guard_status,
            target_count: accepted_store.target_count,
            paper_only: true,
        },
    );
    if !config.dry_run {
        if let Some(path) = config.observer_ledger_path.as_ref() {
            save_observer_comparison_ledger_to_local_json(Path::new(path), &ledger)?;
        }
    }
    let ledger_trend_v2 = compute_observer_comparison_ledger_trend_v2(&ledger);
    let chairman_reward_penalty_contract = if config.prepare_chairman_governance_contract {
        default_chairman_reward_penalty_contract()
    } else {
        let mut contract = default_chairman_reward_penalty_contract();
        contract.status = ChairmanGovernanceContractStatus::Disabled;
        contract
    };
    let decision_isolation_guard_v3 = evaluate_observer_approved_apply_decision_isolation_v3(
        &apply_result,
        &chairman_reward_penalty_contract,
        batch_result,
        Some(batch_result),
    );
    let observer_readiness_v3 = evaluate_smartcore_observer_readiness_v3(
        batch_result
            .observer_readiness_v2_gate
            .as_ref()
            .map(|gate| gate.readiness_status)
            .unwrap_or(SmartCoreObserverReadinessV2Status::NeedsMoreTargets),
        &apply_result,
        &target_store_acceptance_check,
        &comparison_rerun_v3,
        &ledger_trend_v2,
        previous_observer_result.observer_safety_guard.guard_status,
        &decision_isolation_guard_v3,
    );
    let chairman_governance_readiness_check = evaluate_chairman_governance_readiness(
        &chairman_reward_penalty_contract,
        Some(&accepted_store),
        config
            .prepare_chairman_governance_contract
            .then_some(&ledger),
        Some(batch_result.member_experience_records.as_slice()),
        batch_result
            .paper_outcome_evidence_quality_summary
            .is_some()
            || batch_result
                .paper_outcome_evidence_load
                .as_ref()
                .map(|load| !load.records.is_empty())
                .unwrap_or(false)
            || batch_result
                .member_experience_records
                .iter()
                .any(|record| record.outcome != MemberExperienceOutcome::Unknown),
        !batch_result.chairman_decisions.is_empty(),
        previous_observer_result.observer_safety_guard.guard_status,
    );
    let owner_summary = config.emit_owner_summary.then(|| {
        build_owner_observer_apply_readiness_summary(
            batch_result,
            &observer_readiness_v3,
            &chairman_governance_readiness_check,
            &apply_result,
        )
    });
    let run_status = if decision_isolation_guard_v3.guard_status
        == ObserverApprovedApplyDecisionIsolationGuardV3Status::Violated
        || matches!(
            apply_result.apply_status,
            ObserverApprovedTargetApplyV2Status::Blocked
                | ObserverApprovedTargetApplyV2Status::NoApprovedTargets
        )
        || target_store_acceptance_check.acceptance_status
            == ObserverTargetStoreAcceptanceStatus::Rejected
        || matches!(
            observer_readiness_v3.readiness_status,
            SmartCoreObserverReadinessV3Status::BlockedBySafety
                | SmartCoreObserverReadinessV3Status::BlockedByDecisionLeak
                | SmartCoreObserverReadinessV3Status::BlockedByTargetStore
        ) {
        ObserverApprovedApplyAndGovernancePrepRunStatus::Failed
    } else if config.dry_run
        || !apply_result.warnings.is_empty()
        || !target_store_acceptance_check.warnings.is_empty()
        || !observer_readiness_v3.warnings.is_empty()
        || !chairman_governance_readiness_check.warnings.is_empty()
    {
        ObserverApprovedApplyAndGovernancePrepRunStatus::PassedWithWarnings
    } else {
        ObserverApprovedApplyAndGovernancePrepRunStatus::Passed
    };
    let result = ObserverApprovedApplyAndGovernancePrepRunResult {
        run_id: config.run_id.clone(),
        apply_result,
        target_store_acceptance_check,
        comparison_rerun_v3,
        ledger_trend_v2,
        observer_readiness_v3,
        chairman_reward_penalty_contract,
        chairman_governance_readiness_check,
        owner_summary,
        decision_isolation_guard_v3: decision_isolation_guard_v3.clone(),
        run_status,
        paper_only: true,
    };
    if let Some(path) = config.output_path.as_ref() {
        validate_local_json_path(Path::new(path), "observer approved apply output path")?;
        write_safe_json(Path::new(path), &result)?;
    }
    Ok(result)
}

fn apply_owner_observer_apply_readiness_summary_update(
    batch_id: &str,
    section: Option<OwnerCoreDebugSection>,
    update: Option<OwnerObserverApplyReadinessSummary>,
) -> Option<OwnerCoreDebugSection> {
    let Some(update) = update else {
        return section;
    };
    if let Some(mut section) = section {
        section.summary = format!(
            "{}; observer_apply_ready={:?}, chairman_governance={:?}",
            section.summary,
            update.new_readiness_status,
            update.chairman_governance_readiness_status
        );
        section.observer_apply_readiness_summary = Some(update);
        Some(section)
    } else {
        Some(OwnerCoreDebugSection {
            section_id: format!("{batch_id}-owner-core-debug"),
            cards: Vec::new(),
            summary: "observer_apply_readiness_summary=1".to_string(),
            paper_only_warning:
                "observer apply readiness summary is paper-only diagnostics; not investment advice, not trading, not orders"
                    .to_string(),
            debug_only_warning:
                "observer apply readiness summary remains read-only/non-voting and chairman contract stays contract-only"
                    .to_string(),
            calibration_summary: None,
            recalibration_summary: None,
            shadow_opinion_summary: None,
            shadow_stability_summary: None,
            shadow_scenario_sweep_summary: None,
            observer_section: None,
            observer_coverage_closure_summary: None,
            observer_trend_summary: None,
            observer_seeded_target_summary: None,
            observer_apply_readiness_summary: Some(update),
            paper_only: true,
        })
    }
}

fn observer_approved_apply_governance_requested_from_flags(
    enabled: bool,
    apply_mode: ObserverExplicitApplyMode,
    target_store_input_path: Option<&String>,
    target_store_output_path: Option<&String>,
    output_path: Option<&String>,
    _recheck_observer_readiness: bool,
    _prepare_chairman_governance_contract: bool,
    _chairman_governance_readiness_check_enabled: bool,
    _emit_owner_summary: bool,
) -> bool {
    enabled
        || apply_mode == ObserverExplicitApplyMode::ApplyApprovedTargets
        || target_store_input_path.is_some()
        || target_store_output_path.is_some()
        || output_path.is_some()
}

fn maybe_run_observer_approved_apply_and_governance_prep_for_batch_result(
    run_id: String,
    enabled: bool,
    apply_mode: ObserverExplicitApplyMode,
    dry_run: bool,
    target_store_input_path: Option<&String>,
    target_store_output_path: Option<&String>,
    observer_ledger_path: Option<&String>,
    output_path: Option<&String>,
    recheck_observer_readiness: bool,
    prepare_chairman_governance_contract: bool,
    chairman_governance_readiness_check_enabled: bool,
    emit_owner_summary: bool,
    batch_result: &mut BatchCommitteeCycleResult,
) -> Result<Option<ObserverApprovedApplyAndGovernancePrepRunResult>, String> {
    if !observer_approved_apply_governance_requested_from_flags(
        enabled,
        apply_mode,
        target_store_input_path,
        target_store_output_path,
        output_path,
        recheck_observer_readiness,
        prepare_chairman_governance_contract,
        chairman_governance_readiness_check_enabled,
        emit_owner_summary,
    ) {
        return Ok(None);
    }
    let previous_observer_result = batch_result
        .smartcore_observer_lane_run_result
        .clone()
        .ok_or_else(|| {
            "approved apply governance prep requires observer lane result".to_string()
        })?;
    let converted_targets =
        if let Some(seed_run) = batch_result.observer_seed_apply_trend_run_result.as_ref() {
            seed_run
                .controlled_apply_smoke_result
                .seed_conversion_result
                .target_records
                .clone()
        } else {
            let seed_build = build_observer_approved_target_seeds(
                batch_result,
                None,
                None,
                None,
                &ObserverApprovedTargetSeedBuildConfig {
                    run_id: format!("{run_id}-seed-build"),
                    include_member_opinion: true,
                    include_risk_governor_status: true,
                    include_chairman_decision: true,
                    include_validated_replay_labels: true,
                    include_core_calibration_targets: true,
                    include_validated_paper_outcomes: true,
                    max_seeds_per_member: 3,
                    max_total_seeds: 12,
                    paper_only: true,
                },
            );
            convert_approved_target_seeds_to_observer_targets(
                &seed_build.seeds,
                &default_observer_target_closure_apply_policy(),
            )
            .target_records
        };
    let result = run_observer_approved_apply_and_governance_prep(
        batch_result,
        &converted_targets,
        &previous_observer_result,
        &ObserverApprovedApplyAndGovernancePrepRunConfig {
            run_id: run_id.clone(),
            enabled,
            apply_mode,
            dry_run,
            target_store_input_path: target_store_input_path.cloned(),
            target_store_output_path: target_store_output_path.cloned(),
            observer_ledger_path: observer_ledger_path.cloned(),
            output_path: output_path.cloned(),
            recheck_observer_readiness,
            prepare_chairman_governance_contract,
            emit_owner_summary,
            paper_only: true,
        },
    )?;
    if chairman_governance_readiness_check_enabled || emit_owner_summary {
        if let Some(shadow_alignment_result) =
            batch_result.smartcore_shadow_alignment_run_result.as_mut()
        {
            shadow_alignment_result.owner_core_debug_section =
                apply_owner_observer_apply_readiness_summary_update(
                    &batch_result.batch_id,
                    shadow_alignment_result.owner_core_debug_section.take(),
                    result.owner_summary.clone(),
                );
        }
    }
    batch_result.observer_approved_apply_and_governance_prep_run_result = Some(result.clone());
    if result.apply_result.wrote_target_store {
        batch_result.observer_agreement_target_store =
            result.apply_result.accepted_target_store.clone();
    }
    batch_result.observer_target_store_acceptance_check =
        Some(result.target_store_acceptance_check.clone());
    batch_result.observer_comparison_rerun_v3_result = Some(result.comparison_rerun_v3.clone());
    batch_result.observer_comparison_ledger_trend_v2 = Some(result.ledger_trend_v2.clone());
    batch_result.observer_readiness_v3_gate = Some(result.observer_readiness_v3.clone());
    batch_result.chairman_reward_penalty_contract =
        Some(result.chairman_reward_penalty_contract.clone());
    batch_result.chairman_governance_readiness_check =
        Some(result.chairman_governance_readiness_check.clone());
    batch_result.observer_approved_apply_decision_isolation_guard_v3 =
        Some(result.decision_isolation_guard_v3.clone());
    Ok(Some(result))
}

fn default_chairman_shadow_governance_evaluation_policy() -> ChairmanShadowGovernanceEvaluationPolicy
{
    ChairmanShadowGovernanceEvaluationPolicy {
        allow_reward_candidate_generation: true,
        allow_penalty_candidate_generation: true,
        allow_voice_candidate_generation: true,
        allow_actual_score_mutation: false,
        allow_actual_voice_mutation: false,
        allow_promotion_demotion: false,
        allow_risk_governor_override: false,
        require_paper_only: true,
        paper_only: true,
    }
}

pub fn validate_observer_apply_verification_profile(
    profile: &ObserverApplyVerificationProfile,
) -> ObserverApplyVerificationProfileValidationResult {
    let mut blockers = Vec::new();
    let warnings = Vec::new();
    let mut output_path_valid = true;
    if !profile.paper_only {
        blockers.push("observer apply verification profile must stay paper_only".to_string());
    }
    if let Some(path) = profile.config_path.as_ref() {
        if !local_only(path) || path_has_parent_component(Path::new(path)) {
            output_path_valid = false;
            blockers.push(
                "observer apply verification config_path must be local and traversal-safe"
                    .to_string(),
            );
        }
    }
    for (path, label) in [
        (
            profile.target_store_output_path.as_ref(),
            "observer apply verification target_store_output_path",
        ),
        (
            profile.apply_output_path.as_ref(),
            "observer apply verification output_path",
        ),
    ] {
        if let Some(path) = path {
            if validate_local_json_path(Path::new(path), label).is_err() {
                output_path_valid = false;
                blockers.push(format!("{label} must be local JSON path"));
            }
        }
    }
    let apply_mode_valid = if profile.main_example_safe_default {
        profile.apply_mode == ObserverExplicitApplyMode::DryRun
    } else {
        profile.apply_mode == ObserverExplicitApplyMode::ApplyApprovedTargets
    };
    if !apply_mode_valid {
        blockers.push("observer apply verification profile apply_mode mismatch".to_string());
    }
    let dry_run_valid = if profile.main_example_safe_default {
        profile.dry_run
    } else {
        !profile.dry_run
    };
    if !dry_run_valid {
        blockers.push("observer apply verification profile dry_run mismatch".to_string());
    }
    if !profile.main_example_safe_default && profile.target_store_output_path.is_none() {
        output_path_valid = false;
        blockers.push(
            "observer apply verification profile requires target_store_output_path in non-dry mode"
                .to_string(),
        );
    }
    if !profile.verification_profile {
        blockers.push("observer apply verification profile flag must be explicit".to_string());
    }
    let validation_status = if !blockers.is_empty() {
        ObserverApplyVerificationProfileValidationStatus::Invalid
    } else if !warnings.is_empty() {
        ObserverApplyVerificationProfileValidationStatus::ValidWithWarnings
    } else {
        ObserverApplyVerificationProfileValidationStatus::Valid
    };
    ObserverApplyVerificationProfileValidationResult {
        profile_id: profile.profile_id.clone(),
        valid: blockers.is_empty(),
        apply_mode_valid,
        dry_run_valid,
        output_path_valid,
        main_example_safe_default: profile.main_example_safe_default,
        validation_status,
        blockers,
        warnings,
        paper_only: true,
    }
}

pub fn prove_observer_target_store_write(
    proof_id: String,
    apply_result: &ObserverApprovedTargetApplyV2Result,
    fallback_output_path: Option<&String>,
) -> ObserverTargetStoreWriteProof {
    let expected_output_path = apply_result
        .target_store_path
        .clone()
        .or_else(|| fallback_output_path.cloned());
    let path = expected_output_path.as_ref().map(Path::new);
    let target_store_exists_after_write = path.map(Path::exists).unwrap_or(false);
    let (
        target_count,
        approved_count,
        eval_only_count,
        not_input_feature_count,
        unsafe_target_count,
    ) = if target_store_exists_after_write {
        if let Some(path) = path {
            match load_observer_agreement_target_store_from_local_json(path) {
                Ok(store) => {
                    let acceptance = check_observer_target_store_acceptance(&store);
                    (
                        store.target_count,
                        acceptance.approved_count,
                        acceptance.eval_only_count,
                        acceptance.not_input_feature_count,
                        acceptance.invalid_count,
                    )
                }
                Err(_) => (0, 0, 0, 0, usize::MAX),
            }
        } else {
            (0, 0, 0, 0, usize::MAX)
        }
    } else {
        (
            0,
            0,
            0,
            0,
            if apply_result.wrote_target_store {
                usize::MAX
            } else {
                0
            },
        )
    };
    let proof_status = if !apply_result.wrote_target_store || !target_store_exists_after_write {
        ObserverTargetStoreWriteProofStatus::Failed
    } else if unsafe_target_count > 0 {
        ObserverTargetStoreWriteProofStatus::Failed
    } else if apply_result.new_store_count != target_count {
        ObserverTargetStoreWriteProofStatus::ProvenWithWarnings
    } else {
        ObserverTargetStoreWriteProofStatus::Proven
    };
    ObserverTargetStoreWriteProof {
        proof_id,
        expected_output_path,
        wrote_target_store: apply_result.wrote_target_store,
        target_store_exists_after_write,
        target_count,
        approved_count,
        eval_only_count,
        not_input_feature_count,
        unsafe_target_count,
        proof_status,
        paper_only: true,
    }
}

pub fn check_observer_readiness_v3_closure(
    check_id: String,
    readiness_v3: &SmartCoreObserverReadinessV3Gate,
    store_proof: &ObserverTargetStoreWriteProof,
    target_store_acceptance: &ObserverTargetStoreAcceptanceCheck,
    comparison_rerun_v3: &ObserverComparisonRerunV3Result,
    ledger_trend_v2: &ObserverComparisonLedgerTrendV2,
    decision_isolation: &ObserverApprovedApplyDecisionIsolationGuardV3,
) -> ObserverReadinessV3ClosureCheck {
    let mut blockers = Vec::new();
    let mut remaining_warnings = readiness_v3.warnings.clone();
    let decision_isolation_preserved = decision_isolation.guard_status
        == ObserverApprovedApplyDecisionIsolationGuardV3Status::Preserved;
    if !decision_isolation_preserved {
        blockers.push("observer apply verification decision isolation is violated".to_string());
    }
    let needs_apply_resolved = !matches!(
        readiness_v3.readiness_status,
        SmartCoreObserverReadinessV3Status::NeedsApply
    );
    if !needs_apply_resolved {
        blockers.push("observer readiness v3 still reports NeedsApply".to_string());
    }
    let target_store_written =
        store_proof.wrote_target_store && store_proof.target_store_exists_after_write;
    if !target_store_written {
        blockers.push("target store write proof is missing".to_string());
    }
    let target_store_accepted = target_store_acceptance.acceptance_status
        != ObserverTargetStoreAcceptanceStatus::Rejected
        && store_proof.unsafe_target_count == 0;
    if !target_store_accepted {
        blockers.push("target store acceptance is not satisfied".to_string());
    }
    let comparison_rerun_done =
        comparison_rerun_v3.rerun_status != ObserverComparisonRerunV3Status::Failed;
    if !comparison_rerun_done {
        blockers.push("observer comparison rerun v3 is not completed".to_string());
    }
    let ledger_trend_done = ledger_trend_v2.entry_count > 0;
    if !ledger_trend_done {
        remaining_warnings.push("observer ledger trend v2 has insufficient history".to_string());
    }
    let closure_status = if !decision_isolation_preserved {
        ObserverReadinessV3ClosureStatus::Blocked
    } else if !blockers.is_empty() {
        ObserverReadinessV3ClosureStatus::NotClosed
    } else if !remaining_warnings.is_empty()
        || matches!(
            store_proof.proof_status,
            ObserverTargetStoreWriteProofStatus::ProvenWithWarnings
        )
    {
        ObserverReadinessV3ClosureStatus::ClosedWithWarnings
    } else {
        ObserverReadinessV3ClosureStatus::Closed
    };
    ObserverReadinessV3ClosureCheck {
        check_id,
        previous_status: readiness_v3.previous_readiness_status,
        new_status: readiness_v3.readiness_status,
        needs_apply_resolved,
        target_store_written,
        target_store_accepted,
        comparison_rerun_done,
        ledger_trend_done,
        decision_isolation_preserved,
        closure_status,
        remaining_warnings,
        blockers,
        paper_only: true,
    }
}

pub fn build_chairman_shadow_governance_input_set(
    set_id: String,
    comparison_rerun_v3: &ObserverComparisonRerunV3Result,
    ledger_trend_v2: &ObserverComparisonLedgerTrendV2,
    experience_records: &[MemberExperienceRecord],
) -> ChairmanShadowGovernanceInputSet {
    let mut records = Vec::new();
    if comparison_rerun_v3.disagreement_delta < 0 {
        records.push(ChairmanShadowGovernanceInputRecord {
            record_id: format!("{set_id}-observer-improved"),
            source_run_id: Some(set_id.clone()),
            source_member_id: None,
            observer_id: Some("smartcore-observer".to_string()),
            signal_kind: ChairmanShadowGovernanceSignalKind::ObserverAgreement,
            symbol: None,
            market_scope: None,
            evidence_summary: "Observer disagreement reduced after approved target apply"
                .to_string(),
            suggested_governance_consideration:
                ChairmanShadowGovernanceConsideration::RewardCandidate,
            confidence: SourceConfidence::High,
            shadow_only: true,
            no_score_mutation: true,
            no_voice_mutation: true,
            no_promotion_demotion: true,
            paper_only: true,
        });
    } else if comparison_rerun_v3.disagreement_delta > 0 {
        records.push(ChairmanShadowGovernanceInputRecord {
            record_id: format!("{set_id}-observer-worse"),
            source_run_id: Some(set_id.clone()),
            source_member_id: None,
            observer_id: Some("smartcore-observer".to_string()),
            signal_kind: ChairmanShadowGovernanceSignalKind::ObserverDisagreement,
            symbol: None,
            market_scope: None,
            evidence_summary: "Observer disagreement increased after approved target apply"
                .to_string(),
            suggested_governance_consideration:
                ChairmanShadowGovernanceConsideration::PenaltyCandidate,
            confidence: SourceConfidence::Medium,
            shadow_only: true,
            no_score_mutation: true,
            no_voice_mutation: true,
            no_promotion_demotion: true,
            paper_only: true,
        });
    }
    match ledger_trend_v2.disagreement_trend {
        ObserverTrendDirection::Improving => records.push(ChairmanShadowGovernanceInputRecord {
            record_id: format!("{set_id}-ledger-improving"),
            source_run_id: Some(set_id.clone()),
            source_member_id: None,
            observer_id: Some("smartcore-observer".to_string()),
            signal_kind: ChairmanShadowGovernanceSignalKind::RiskVetoAlignment,
            symbol: None,
            market_scope: None,
            evidence_summary: "Observer disagreement trend is improving".to_string(),
            suggested_governance_consideration:
                ChairmanShadowGovernanceConsideration::VoiceIncreaseCandidate,
            confidence: SourceConfidence::Medium,
            shadow_only: true,
            no_score_mutation: true,
            no_voice_mutation: true,
            no_promotion_demotion: true,
            paper_only: true,
        }),
        ObserverTrendDirection::Worsening => records.push(ChairmanShadowGovernanceInputRecord {
            record_id: format!("{set_id}-ledger-worsening"),
            source_run_id: Some(set_id.clone()),
            source_member_id: None,
            observer_id: Some("smartcore-observer".to_string()),
            signal_kind: ChairmanShadowGovernanceSignalKind::NeedMoreEvidenceCandidate,
            symbol: None,
            market_scope: None,
            evidence_summary: "Observer disagreement trend is worsening".to_string(),
            suggested_governance_consideration:
                ChairmanShadowGovernanceConsideration::VoiceDecreaseCandidate,
            confidence: SourceConfidence::Low,
            shadow_only: true,
            no_score_mutation: true,
            no_voice_mutation: true,
            no_promotion_demotion: true,
            paper_only: true,
        }),
        _ => {}
    }
    if let Some(record) = experience_records
        .iter()
        .find(|record| matches!(record.outcome, MemberExperienceOutcome::PaperPositive))
    {
        records.push(ChairmanShadowGovernanceInputRecord {
            record_id: format!("{set_id}-helpful-dissent"),
            source_run_id: Some(set_id.clone()),
            source_member_id: Some(record.member_id.clone()),
            observer_id: None,
            signal_kind: ChairmanShadowGovernanceSignalKind::HelpfulDissentCandidate,
            symbol: Some(record.symbol.clone()),
            market_scope: Some(record.market_scope),
            evidence_summary: "Positive paper outcome observed for member experience".to_string(),
            suggested_governance_consideration:
                ChairmanShadowGovernanceConsideration::RewardCandidate,
            confidence: SourceConfidence::Medium,
            shadow_only: true,
            no_score_mutation: true,
            no_voice_mutation: true,
            no_promotion_demotion: true,
            paper_only: true,
        });
    }
    if records.is_empty() {
        records.push(ChairmanShadowGovernanceInputRecord {
            record_id: format!("{set_id}-neutral"),
            source_run_id: Some(set_id.clone()),
            source_member_id: None,
            observer_id: Some("smartcore-observer".to_string()),
            signal_kind: ChairmanShadowGovernanceSignalKind::Neutral,
            symbol: None,
            market_scope: None,
            evidence_summary: "No strong governance candidate signal was generated".to_string(),
            suggested_governance_consideration: ChairmanShadowGovernanceConsideration::KeepNeutral,
            confidence: SourceConfidence::ReviewRequired,
            shadow_only: true,
            no_score_mutation: true,
            no_voice_mutation: true,
            no_promotion_demotion: true,
            paper_only: true,
        });
    }
    let reward_candidate_count = records
        .iter()
        .filter(|record| {
            record.suggested_governance_consideration
                == ChairmanShadowGovernanceConsideration::RewardCandidate
        })
        .count();
    let penalty_candidate_count = records
        .iter()
        .filter(|record| {
            record.suggested_governance_consideration
                == ChairmanShadowGovernanceConsideration::PenaltyCandidate
        })
        .count();
    let voice_increase_candidate_count = records
        .iter()
        .filter(|record| {
            record.suggested_governance_consideration
                == ChairmanShadowGovernanceConsideration::VoiceIncreaseCandidate
        })
        .count();
    let voice_decrease_candidate_count = records
        .iter()
        .filter(|record| {
            record.suggested_governance_consideration
                == ChairmanShadowGovernanceConsideration::VoiceDecreaseCandidate
        })
        .count();
    ChairmanShadowGovernanceInputSet {
        set_id,
        record_count: records.len(),
        reward_candidate_count,
        penalty_candidate_count,
        voice_increase_candidate_count,
        voice_decrease_candidate_count,
        records,
        paper_only: true,
    }
}

pub fn evaluate_chairman_shadow_governance(
    evaluation_id: String,
    input_set: ChairmanShadowGovernanceInputSet,
    policy: &ChairmanShadowGovernanceEvaluationPolicy,
) -> ChairmanShadowGovernanceEvaluationResult {
    let mut warnings = 0usize;
    let mut blocked = !policy.paper_only
        || !policy.require_paper_only
        || policy.allow_actual_score_mutation
        || policy.allow_actual_voice_mutation
        || policy.allow_promotion_demotion
        || policy.allow_risk_governor_override;
    let reward_candidate_count = if policy.allow_reward_candidate_generation {
        input_set.reward_candidate_count
    } else {
        blocked = true;
        0
    };
    let penalty_candidate_count = if policy.allow_penalty_candidate_generation {
        input_set.penalty_candidate_count
    } else {
        blocked = true;
        0
    };
    let (voice_increase_candidate_count, voice_decrease_candidate_count) =
        if policy.allow_voice_candidate_generation {
            (
                input_set.voice_increase_candidate_count,
                input_set.voice_decrease_candidate_count,
            )
        } else {
            blocked = true;
            (0, 0)
        };
    if input_set.records.iter().any(|record| {
        matches!(
            record.confidence,
            SourceConfidence::Low | SourceConfidence::ReviewRequired
        )
    }) {
        warnings += 1;
    }
    let neutral_count = input_set
        .records
        .iter()
        .filter(|record| {
            record.suggested_governance_consideration
                == ChairmanShadowGovernanceConsideration::KeepNeutral
        })
        .count();
    let evaluation_status = if blocked {
        ChairmanShadowGovernanceEvaluationStatus::Blocked
    } else if warnings > 0 {
        ChairmanShadowGovernanceEvaluationStatus::EvaluatedWithWarnings
    } else {
        ChairmanShadowGovernanceEvaluationStatus::Evaluated
    };
    ChairmanShadowGovernanceEvaluationResult {
        evaluation_id,
        evaluated_record_count: input_set.record_count,
        reward_candidate_count,
        penalty_candidate_count,
        voice_increase_candidate_count,
        voice_decrease_candidate_count,
        neutral_count,
        evaluation_status,
        input_set,
        no_score_mutation: true,
        no_voice_mutation: true,
        no_promotion_demotion: true,
        no_risk_governor_override: true,
        paper_only: true,
    }
}

pub fn evaluate_chairman_shadow_governance_safety_guard(
    evaluation_result: &ChairmanShadowGovernanceEvaluationResult,
    batch_result_before: &BatchCommitteeCycleResult,
    batch_result_after: Option<&BatchCommitteeCycleResult>,
) -> ChairmanShadowGovernanceSafetyGuard {
    let after = batch_result_after.unwrap_or(batch_result_before);
    let score_mutation_detected = batch_result_before.score_updates != after.score_updates;
    let voice_mutation_detected = batch_result_before
        .score_updates
        .iter()
        .map(|update| (update.member_id.clone(), update.new_voice_weight))
        .collect::<Vec<_>>()
        != after
            .score_updates
            .iter()
            .map(|update| (update.member_id.clone(), update.new_voice_weight))
            .collect::<Vec<_>>();
    let promotion_detected = batch_result_before
        .score_updates
        .iter()
        .map(|update| (update.member_id.clone(), update.promoted))
        .collect::<Vec<_>>()
        != after
            .score_updates
            .iter()
            .map(|update| (update.member_id.clone(), update.promoted))
            .collect::<Vec<_>>();
    let demotion_detected = batch_result_before
        .score_updates
        .iter()
        .map(|update| (update.member_id.clone(), update.demoted))
        .collect::<Vec<_>>()
        != after
            .score_updates
            .iter()
            .map(|update| (update.member_id.clone(), update.demoted))
            .collect::<Vec<_>>();
    let risk_governor_override_detected = batch_result_before
        .chairman_decisions
        .iter()
        .map(|decision| decision.risk_governor_status)
        .collect::<Vec<_>>()
        != after
            .chairman_decisions
            .iter()
            .map(|decision| decision.risk_governor_status)
            .collect::<Vec<_>>();
    let chairman_decision_mutation_detected =
        batch_result_before.chairman_decisions != after.chairman_decisions;
    let committee_decision_mutation_detected =
        batch_result_before.committee_sessions != after.committee_sessions;
    let markers = evaluation_result
        .input_set
        .records
        .iter()
        .map(|record| record.record_id.clone())
        .collect::<Vec<_>>();
    let trade_signal_detected = value_contains_debug_marker(&after.committee_sessions, &markers);
    let order_detected = value_contains_debug_marker(&after.event_queue, &markers);
    let broker_order_account_detected = value_contains_debug_marker(
        &after.event_queue,
        &[
            "broker".to_string(),
            "order".to_string(),
            "account".to_string(),
        ],
    );
    let mut violations = Vec::new();
    if score_mutation_detected {
        violations.push("chairman shadow governance mutated score".to_string());
    }
    if voice_mutation_detected {
        violations.push("chairman shadow governance mutated voice".to_string());
    }
    if promotion_detected {
        violations.push("chairman shadow governance promoted member".to_string());
    }
    if demotion_detected {
        violations.push("chairman shadow governance demoted member".to_string());
    }
    if risk_governor_override_detected {
        violations.push("chairman shadow governance changed risk governor".to_string());
    }
    if chairman_decision_mutation_detected {
        violations.push("chairman shadow governance mutated chairman decision".to_string());
    }
    if committee_decision_mutation_detected {
        violations.push("chairman shadow governance mutated committee decision".to_string());
    }
    if trade_signal_detected {
        violations.push("chairman shadow governance generated trade signal".to_string());
    }
    if order_detected {
        violations.push("chairman shadow governance generated order".to_string());
    }
    if broker_order_account_detected {
        violations.push("chairman shadow governance touched broker/order/account path".to_string());
    }
    ChairmanShadowGovernanceSafetyGuard {
        score_mutation_detected,
        voice_mutation_detected,
        promotion_detected,
        demotion_detected,
        risk_governor_override_detected,
        chairman_decision_mutation_detected,
        committee_decision_mutation_detected,
        trade_signal_detected,
        order_detected,
        broker_order_account_detected,
        guard_status: if violations.is_empty() {
            ChairmanShadowGovernanceSafetyGuardStatus::Preserved
        } else {
            ChairmanShadowGovernanceSafetyGuardStatus::Violated
        },
        violations,
        paper_only: true,
    }
}

pub fn build_owner_observer_apply_governance_summary_v2(
    summary_id: String,
    apply_result: &ObserverApprovedTargetApplyV2Result,
    readiness_v3: &SmartCoreObserverReadinessV3Gate,
    evaluation_result: Option<&ChairmanShadowGovernanceEvaluationResult>,
) -> OwnerObserverApplyAndGovernanceSummaryV2 {
    let chairman_status = evaluation_result
        .map(|result| result.evaluation_status)
        .unwrap_or(ChairmanShadowGovernanceEvaluationStatus::Blocked);
    let reward_candidate_count = evaluation_result
        .map(|result| result.reward_candidate_count)
        .unwrap_or(0);
    let penalty_candidate_count = evaluation_result
        .map(|result| result.penalty_candidate_count)
        .unwrap_or(0);
    let voice_candidate_count = evaluation_result
        .map(|result| result.voice_increase_candidate_count + result.voice_decrease_candidate_count)
        .unwrap_or(0);
    OwnerObserverApplyAndGovernanceSummaryV2 {
        summary_id,
        apply_status: apply_result.apply_status,
        target_store_written: apply_result.wrote_target_store,
        target_store_count: apply_result.new_store_count,
        observer_readiness_status: readiness_v3.readiness_status,
        chairman_shadow_governance_status: chairman_status,
        reward_candidate_count,
        penalty_candidate_count,
        voice_candidate_count,
        message: "Approved observer targets were applied only to local evaluation store. Observer remains non-voting and read-only. Chairman governance signals are shadow-only candidates. No score, voice, promotion, demotion, trade, or order changed."
            .to_string(),
        non_voting: true,
        read_only: true,
        eval_only: true,
        chairman_contract_only: true,
        no_score_mutation: true,
        no_voice_mutation: true,
        not_investment_signal: true,
        not_committee_opinion: true,
        paper_only: true,
    }
}

pub fn run_observer_apply_verify_and_chairman_shadow(
    batch_result: &BatchCommitteeCycleResult,
    converted_targets: &[ObserverAgreementTargetRecord],
    previous_observer_result: &SmartCoreObserverLaneRunResult,
    config: &ObserverApplyVerifyAndChairmanShadowRunConfig,
) -> Result<ObserverApplyVerifyAndChairmanShadowRunResult, String> {
    let profile = ObserverApplyVerificationProfile {
        profile_id: format!("{}-verify-profile", config.run_id),
        config_path: config.apply_verification_config_path.clone(),
        apply_mode: config.apply_mode,
        dry_run: config.dry_run,
        target_store_output_path: config.target_store_output_path.clone(),
        apply_output_path: config.output_path.clone(),
        main_example_safe_default: config.apply_mode == ObserverExplicitApplyMode::DryRun
            && config.dry_run,
        verification_profile: true,
        paper_only: true,
    };
    let apply_profile_validation = validate_observer_apply_verification_profile(&profile);
    if !apply_profile_validation.valid {
        return Err(format!(
            "observer apply verification profile invalid: {}",
            apply_profile_validation.blockers.join("; ")
        ));
    }
    let base_run = run_observer_approved_apply_and_governance_prep(
        batch_result,
        converted_targets,
        previous_observer_result,
        &ObserverApprovedApplyAndGovernancePrepRunConfig {
            run_id: config.run_id.clone(),
            enabled: config.enabled,
            apply_mode: config.apply_mode,
            dry_run: config.dry_run,
            target_store_input_path: None,
            target_store_output_path: config.target_store_output_path.clone(),
            observer_ledger_path: None,
            output_path: None,
            recheck_observer_readiness: true,
            prepare_chairman_governance_contract: true,
            emit_owner_summary: false,
            paper_only: true,
        },
    )?;
    let target_store_write_proof = prove_observer_target_store_write(
        format!("{}-target-store-write-proof", config.run_id),
        &base_run.apply_result,
        config.target_store_output_path.as_ref(),
    );
    let readiness_closure_check = check_observer_readiness_v3_closure(
        format!("{}-readiness-v3-closure", config.run_id),
        &base_run.observer_readiness_v3,
        &target_store_write_proof,
        &base_run.target_store_acceptance_check,
        &base_run.comparison_rerun_v3,
        &base_run.ledger_trend_v2,
        &base_run.decision_isolation_guard_v3,
    );
    let (
        chairman_shadow_governance_inputs,
        chairman_shadow_governance_evaluation,
        chairman_shadow_governance_safety,
    ) = if config.run_chairman_shadow_governance {
        let input_set = build_chairman_shadow_governance_input_set(
            format!("{}-chairman-shadow-input", config.run_id),
            &base_run.comparison_rerun_v3,
            &base_run.ledger_trend_v2,
            &batch_result.member_experience_records,
        );
        let evaluation = evaluate_chairman_shadow_governance(
            format!("{}-chairman-shadow-eval", config.run_id),
            input_set.clone(),
            &default_chairman_shadow_governance_evaluation_policy(),
        );
        let safety = evaluate_chairman_shadow_governance_safety_guard(
            &evaluation,
            batch_result,
            Some(batch_result),
        );
        (Some(input_set), Some(evaluation), Some(safety))
    } else {
        (None, None, None)
    };
    let owner_summary = config.emit_owner_summary.then(|| {
        build_owner_observer_apply_governance_summary_v2(
            format!("{}-owner-summary-v2", config.run_id),
            &base_run.apply_result,
            &base_run.observer_readiness_v3,
            chairman_shadow_governance_evaluation.as_ref(),
        )
    });
    let run_status = if !apply_profile_validation.valid
        || matches!(
            base_run.apply_result.apply_status,
            ObserverApprovedTargetApplyV2Status::Blocked
                | ObserverApprovedTargetApplyV2Status::NoApprovedTargets
        )
        || matches!(
            target_store_write_proof.proof_status,
            ObserverTargetStoreWriteProofStatus::Failed
        )
        || matches!(
            readiness_closure_check.closure_status,
            ObserverReadinessV3ClosureStatus::Blocked | ObserverReadinessV3ClosureStatus::NotClosed
        )
        || chairman_shadow_governance_safety
            .as_ref()
            .map(|guard| guard.guard_status == ChairmanShadowGovernanceSafetyGuardStatus::Violated)
            .unwrap_or(false)
    {
        ObserverApplyVerifyAndChairmanShadowRunStatus::Failed
    } else if config.dry_run
        || !apply_profile_validation.warnings.is_empty()
        || matches!(
            target_store_write_proof.proof_status,
            ObserverTargetStoreWriteProofStatus::ProvenWithWarnings
        )
        || matches!(
            readiness_closure_check.closure_status,
            ObserverReadinessV3ClosureStatus::ClosedWithWarnings
        )
        || chairman_shadow_governance_evaluation
            .as_ref()
            .map(|evaluation| {
                evaluation.evaluation_status
                    == ChairmanShadowGovernanceEvaluationStatus::EvaluatedWithWarnings
            })
            .unwrap_or(false)
    {
        ObserverApplyVerifyAndChairmanShadowRunStatus::PassedWithWarnings
    } else {
        ObserverApplyVerifyAndChairmanShadowRunStatus::Passed
    };
    let result = ObserverApplyVerifyAndChairmanShadowRunResult {
        run_id: config.run_id.clone(),
        apply_profile_validation,
        apply_result: base_run.apply_result.clone(),
        target_store_write_proof,
        target_store_acceptance_check: base_run.target_store_acceptance_check.clone(),
        comparison_rerun_v3: base_run.comparison_rerun_v3.clone(),
        ledger_trend_v2: base_run.ledger_trend_v2.clone(),
        observer_readiness_v3: base_run.observer_readiness_v3.clone(),
        readiness_closure_check,
        chairman_shadow_governance_inputs,
        chairman_shadow_governance_evaluation,
        chairman_shadow_governance_safety,
        owner_summary,
        run_status,
        paper_only: true,
    };
    if let Some(path) = config.output_path.as_ref() {
        validate_local_json_path(Path::new(path), "observer apply verify output path")?;
        write_safe_json(Path::new(path), &result)?;
    }
    Ok(result)
}

fn apply_owner_observer_apply_summary_v2_update(
    batch_id: &str,
    section: Option<OwnerCoreDebugSection>,
    update: Option<OwnerObserverApplyAndGovernanceSummaryV2>,
) -> Option<OwnerCoreDebugSection> {
    let Some(update) = update else {
        return section;
    };
    if let Some(mut section) = section {
        section.summary = format!(
            "{}; observer_apply_verify={:?}, chairman_shadow={:?}",
            section.summary,
            update.observer_readiness_status,
            update.chairman_shadow_governance_status
        );
        Some(section)
    } else {
        Some(OwnerCoreDebugSection {
            section_id: format!("{batch_id}-owner-core-debug"),
            cards: Vec::new(),
            summary: "observer_apply_verify_summary_v2=1".to_string(),
            paper_only_warning:
                "observer apply verify summary v2 is paper-only diagnostics; not investment advice, not trading, not orders"
                    .to_string(),
            debug_only_warning:
                "observer apply verify summary v2 stays non-voting/read-only and chairman shadow governance is contract-only"
                    .to_string(),
            calibration_summary: None,
            recalibration_summary: None,
            shadow_opinion_summary: None,
            shadow_stability_summary: None,
            shadow_scenario_sweep_summary: None,
            observer_section: None,
            observer_coverage_closure_summary: None,
            observer_trend_summary: None,
            observer_seeded_target_summary: None,
            observer_apply_readiness_summary: None,
            paper_only: true,
        })
    }
}

pub fn observer_apply_verify_chairman_shadow_requested_from_flags(
    enabled: bool,
    apply_mode: ObserverExplicitApplyMode,
    target_store_output_path: Option<&String>,
    output_path: Option<&String>,
    apply_verification_config_path: Option<&String>,
    dry_run: bool,
    run_chairman_shadow_governance: bool,
    emit_owner_summary: bool,
) -> bool {
    enabled
        || apply_mode == ObserverExplicitApplyMode::ApplyApprovedTargets
        || !dry_run
        || apply_verification_config_path.is_some()
        || (enabled
            && (target_store_output_path.is_some()
                || output_path.is_some()
                || run_chairman_shadow_governance
                || emit_owner_summary))
}

fn maybe_run_observer_apply_verify_and_chairman_shadow_for_batch_result(
    run_id: String,
    enabled: bool,
    apply_mode: ObserverExplicitApplyMode,
    dry_run: bool,
    target_store_output_path: Option<&String>,
    observer_ledger_path: Option<&String>,
    output_path: Option<&String>,
    apply_verification_config_path: Option<&String>,
    run_chairman_shadow_governance: bool,
    emit_owner_summary: bool,
    batch_result: &mut BatchCommitteeCycleResult,
) -> Result<Option<ObserverApplyVerifyAndChairmanShadowRunResult>, String> {
    if !observer_apply_verify_chairman_shadow_requested_from_flags(
        enabled,
        apply_mode,
        target_store_output_path,
        output_path,
        apply_verification_config_path,
        dry_run,
        run_chairman_shadow_governance,
        emit_owner_summary,
    ) {
        return Ok(None);
    }
    let previous_observer_result = batch_result
        .smartcore_observer_lane_run_result
        .clone()
        .ok_or_else(|| "observer apply verify run requires observer lane result".to_string())?;
    let converted_targets =
        if let Some(seed_run) = batch_result.observer_seed_apply_trend_run_result.as_ref() {
            seed_run
                .controlled_apply_smoke_result
                .seed_conversion_result
                .target_records
                .clone()
        } else {
            let seed_build = build_observer_approved_target_seeds(
                batch_result,
                None,
                None,
                None,
                &ObserverApprovedTargetSeedBuildConfig {
                    run_id: format!("{run_id}-seed-build"),
                    include_member_opinion: true,
                    include_risk_governor_status: true,
                    include_chairman_decision: true,
                    include_validated_replay_labels: true,
                    include_core_calibration_targets: true,
                    include_validated_paper_outcomes: true,
                    max_seeds_per_member: 3,
                    max_total_seeds: 12,
                    paper_only: true,
                },
            );
            convert_approved_target_seeds_to_observer_targets(
                &seed_build.seeds,
                &default_observer_target_closure_apply_policy(),
            )
            .target_records
        };
    let result = run_observer_apply_verify_and_chairman_shadow(
        batch_result,
        &converted_targets,
        &previous_observer_result,
        &ObserverApplyVerifyAndChairmanShadowRunConfig {
            run_id: run_id.clone(),
            enabled,
            apply_verification_config_path: apply_verification_config_path.cloned(),
            apply_mode,
            dry_run,
            target_store_output_path: target_store_output_path.cloned(),
            output_path: output_path.cloned(),
            run_chairman_shadow_governance,
            emit_owner_summary,
            paper_only: true,
        },
    )?;
    if observer_ledger_path.is_some() {
        // observer_ledger_path is intentionally ignored in sprint 188 because ledger v3 reuses in-memory ledger flow.
    }
    if emit_owner_summary {
        if let Some(shadow_alignment_result) =
            batch_result.smartcore_shadow_alignment_run_result.as_mut()
        {
            shadow_alignment_result.owner_core_debug_section =
                apply_owner_observer_apply_summary_v2_update(
                    &batch_result.batch_id,
                    shadow_alignment_result.owner_core_debug_section.take(),
                    result.owner_summary.clone(),
                );
        }
    }
    batch_result.observer_apply_verify_chairman_shadow_run_result = Some(result.clone());
    batch_result.observer_apply_verification_profile_validation =
        Some(result.apply_profile_validation.clone());
    batch_result.observer_target_store_write_proof = Some(result.target_store_write_proof.clone());
    batch_result.observer_readiness_v3_closure_check = Some(result.readiness_closure_check.clone());
    batch_result.chairman_shadow_governance_input_set =
        result.chairman_shadow_governance_inputs.clone();
    batch_result.chairman_shadow_governance_evaluation_result =
        result.chairman_shadow_governance_evaluation.clone();
    batch_result.chairman_shadow_governance_safety_guard =
        result.chairman_shadow_governance_safety.clone();
    batch_result.observer_target_store_acceptance_check =
        Some(result.target_store_acceptance_check.clone());
    batch_result.observer_comparison_rerun_v3_result = Some(result.comparison_rerun_v3.clone());
    batch_result.observer_comparison_ledger_trend_v2 = Some(result.ledger_trend_v2.clone());
    batch_result.observer_readiness_v3_gate = Some(result.observer_readiness_v3.clone());
    if result.apply_result.wrote_target_store {
        batch_result.observer_agreement_target_store =
            result.apply_result.accepted_target_store.clone();
    }
    Ok(Some(result))
}

fn default_empty_chairman_shadow_governance_ledger(run_id: &str) -> ChairmanShadowGovernanceLedger {
    ChairmanShadowGovernanceLedger {
        ledger_id: format!("{run_id}-chairman-shadow-governance-ledger"),
        entries: Vec::new(),
        entry_count: 0,
        reward_candidate_count: 0,
        penalty_candidate_count: 0,
        voice_increase_candidate_count: 0,
        voice_decrease_candidate_count: 0,
        promotion_candidate_count: 0,
        demotion_candidate_count: 0,
        latest_entry_id: None,
        paper_only: true,
    }
}

fn chairman_shadow_governance_entry_key(
    entry: &ChairmanShadowGovernanceLedgerEntry,
) -> (
    Option<String>,
    Option<String>,
    Option<String>,
    Option<String>,
    Option<MarketScope>,
    String,
    String,
    String,
) {
    (
        entry.member_id.clone(),
        entry.observer_id.clone(),
        entry.run_id.clone(),
        entry.symbol.clone(),
        entry.market_scope,
        format!("{:?}", entry.signal_kind),
        format!("{:?}", entry.governance_candidate),
        entry.evidence_summary.clone(),
    )
}

fn validate_chairman_shadow_governance_ledger_entry(
    entry: &ChairmanShadowGovernanceLedgerEntry,
) -> Result<(), String> {
    if !entry.paper_only || !entry.shadow_only {
        return Err(
            "chairman shadow governance ledger entry must stay paper_only and shadow_only"
                .to_string(),
        );
    }
    if !entry.no_score_mutation
        || !entry.no_voice_mutation
        || !entry.no_promotion_demotion
        || !entry.no_risk_governor_override
    {
        return Err(
            "chairman shadow governance ledger entry must forbid all mutations".to_string(),
        );
    }
    if reject_unsafe_owner_feedback_string(&entry.evidence_summary).is_err() {
        return Err(
            "chairman shadow governance ledger entry contains unsafe order/trade language"
                .to_string(),
        );
    }
    Ok(())
}

fn refresh_chairman_shadow_governance_ledger_counts(ledger: &mut ChairmanShadowGovernanceLedger) {
    ledger.entry_count = ledger.entries.len();
    ledger.reward_candidate_count = ledger
        .entries
        .iter()
        .filter(|entry| {
            entry.governance_candidate == ChairmanShadowGovernanceConsideration::RewardCandidate
        })
        .count();
    ledger.penalty_candidate_count = ledger
        .entries
        .iter()
        .filter(|entry| {
            entry.governance_candidate == ChairmanShadowGovernanceConsideration::PenaltyCandidate
        })
        .count();
    ledger.voice_increase_candidate_count = ledger
        .entries
        .iter()
        .filter(|entry| {
            entry.governance_candidate
                == ChairmanShadowGovernanceConsideration::VoiceIncreaseCandidate
        })
        .count();
    ledger.voice_decrease_candidate_count = ledger
        .entries
        .iter()
        .filter(|entry| {
            entry.governance_candidate
                == ChairmanShadowGovernanceConsideration::VoiceDecreaseCandidate
        })
        .count();
    ledger.promotion_candidate_count = ledger
        .entries
        .iter()
        .filter(|entry| {
            entry.governance_candidate == ChairmanShadowGovernanceConsideration::PromotionCandidate
        })
        .count();
    ledger.demotion_candidate_count = ledger
        .entries
        .iter()
        .filter(|entry| {
            entry.governance_candidate == ChairmanShadowGovernanceConsideration::DemotionCandidate
        })
        .count();
    ledger.latest_entry_id = ledger.entries.last().map(|entry| entry.entry_id.clone());
}

pub fn normalize_chairman_shadow_governance_ledger(ledger: &mut ChairmanShadowGovernanceLedger) {
    let mut seen = std::collections::BTreeSet::new();
    ledger.entries.sort_by(|left, right| {
        chairman_shadow_governance_entry_key(left).cmp(&chairman_shadow_governance_entry_key(right))
    });
    ledger.entries.retain(|entry| {
        validate_chairman_shadow_governance_ledger_entry(entry).is_ok()
            && seen.insert(chairman_shadow_governance_entry_key(entry))
    });
    refresh_chairman_shadow_governance_ledger_counts(ledger);
}

pub fn load_chairman_shadow_governance_ledger_from_local_json(
    path: &Path,
) -> Result<ChairmanShadowGovernanceLedger, String> {
    validate_local_json_path(path, "chairman shadow governance ledger path")?;
    let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
    let mut ledger: ChairmanShadowGovernanceLedger =
        serde_json::from_str(&text).map_err(|err| err.to_string())?;
    for entry in &ledger.entries {
        validate_chairman_shadow_governance_ledger_entry(entry)?;
    }
    normalize_chairman_shadow_governance_ledger(&mut ledger);
    Ok(ledger)
}

pub fn save_chairman_shadow_governance_ledger_to_local_json(
    path: &Path,
    ledger: &ChairmanShadowGovernanceLedger,
) -> Result<(), String> {
    validate_local_json_path(path, "chairman shadow governance ledger path")?;
    for entry in &ledger.entries {
        validate_chairman_shadow_governance_ledger_entry(entry)?;
    }
    let mut normalized = ledger.clone();
    normalize_chairman_shadow_governance_ledger(&mut normalized);
    write_safe_json(path, &normalized)
}

pub fn append_chairman_shadow_governance_entries(
    ledger: &mut ChairmanShadowGovernanceLedger,
    entries: &[ChairmanShadowGovernanceLedgerEntry],
) {
    ledger.entries.extend(entries.iter().cloned());
    normalize_chairman_shadow_governance_ledger(ledger);
}

pub fn latest_chairman_governance_entries(
    ledger: &ChairmanShadowGovernanceLedger,
    limit: usize,
) -> Vec<ChairmanShadowGovernanceLedgerEntry> {
    if limit == 0 {
        return Vec::new();
    }
    let mut latest = ledger
        .entries
        .iter()
        .rev()
        .take(limit)
        .cloned()
        .collect::<Vec<_>>();
    latest.reverse();
    latest
}

pub fn default_chairman_reward_penalty_candidate_policy() -> ChairmanRewardPenaltyCandidatePolicy {
    ChairmanRewardPenaltyCandidatePolicy {
        allow_reward_candidates: true,
        allow_penalty_candidates: true,
        allow_voice_candidates: true,
        allow_promotion_candidates: true,
        allow_demotion_candidates: true,
        allow_actual_score_mutation: false,
        allow_actual_voice_mutation: false,
        allow_actual_promotion_demotion: false,
        allow_risk_governor_override: false,
        require_paper_only: true,
        require_shadow_only: true,
        min_confidence_for_promotion_candidate: SourceConfidence::Medium,
        min_confidence_for_demotion_candidate: SourceConfidence::Medium,
        paper_only: true,
    }
}

pub fn validate_chairman_reward_penalty_candidate_policy(
    policy: &ChairmanRewardPenaltyCandidatePolicy,
) -> Result<(), String> {
    if !policy.paper_only || !policy.require_paper_only || !policy.require_shadow_only {
        return Err(
            "chairman reward/penalty candidate policy must stay paper_only/shadow_only".to_string(),
        );
    }
    if policy.allow_actual_score_mutation
        || policy.allow_actual_voice_mutation
        || policy.allow_actual_promotion_demotion
        || policy.allow_risk_governor_override
    {
        return Err(
            "chairman reward/penalty candidate policy must forbid actual mutation".to_string(),
        );
    }
    Ok(())
}

fn normalized_source_confidence_rank(confidence: SourceConfidence) -> usize {
    match confidence {
        SourceConfidence::ReviewRequired => 0,
        SourceConfidence::Low => 1,
        SourceConfidence::Medium => 2,
        SourceConfidence::High => 3,
    }
}

fn source_confidence_meets_minimum(
    confidence: SourceConfidence,
    minimum: SourceConfidence,
) -> bool {
    normalized_source_confidence_rank(confidence) >= normalized_source_confidence_rank(minimum)
}

fn chairman_candidate_entry(
    entry_id: String,
    run_id: &str,
    member_id: Option<String>,
    observer_id: Option<String>,
    symbol: Option<String>,
    market_scope: Option<MarketScope>,
    signal_kind: ChairmanShadowGovernanceSignalKind,
    governance_candidate: ChairmanShadowGovernanceConsideration,
    evidence_summary: String,
    confidence: SourceConfidence,
) -> ChairmanShadowGovernanceLedgerEntry {
    ChairmanShadowGovernanceLedgerEntry {
        entry_id,
        run_id: Some(run_id.to_string()),
        member_id,
        observer_id,
        symbol,
        market_scope,
        signal_kind,
        governance_candidate,
        evidence_summary,
        confidence,
        shadow_only: true,
        no_score_mutation: true,
        no_voice_mutation: true,
        no_promotion_demotion: true,
        no_risk_governor_override: true,
        paper_only: true,
    }
}

fn outcome_is_positive_for_shadow_governance(outcome: MemberExperienceOutcome) -> bool {
    matches!(
        outcome,
        MemberExperienceOutcome::PaperPositive
            | MemberExperienceOutcome::RiskVetoSavedLoss
            | MemberExperienceOutcome::HelpfulDissent
    )
}

fn outcome_is_negative_for_shadow_governance(outcome: MemberExperienceOutcome) -> bool {
    matches!(
        outcome,
        MemberExperienceOutcome::PaperNegative
            | MemberExperienceOutcome::BadRiskCall
            | MemberExperienceOutcome::MissedOpportunity
    )
}

fn owner_intent_from_feedback_type(feedback_type: OwnerFeedbackType) -> OwnerOpinionIntent {
    match feedback_type {
        OwnerFeedbackType::RiskConcern => OwnerOpinionIntent::RiskConcern,
        OwnerFeedbackType::EvidenceRequest => OwnerOpinionIntent::EvidenceRequest,
        OwnerFeedbackType::WatchlistRequest => OwnerOpinionIntent::WatchlistRequest,
        OwnerFeedbackType::ReconsiderationRequest | OwnerFeedbackType::Disagree => {
            OwnerOpinionIntent::ReconsiderationRequest
        }
        OwnerFeedbackType::PaperOutcomeLabel => OwnerOpinionIntent::PaperOutcomeLabel,
        OwnerFeedbackType::Comment => OwnerOpinionIntent::Comment,
    }
}

pub fn build_chairman_governance_candidates(
    governance_inputs: &ChairmanShadowGovernanceInputSet,
    observer_comparison_result: &ObserverComparisonRerunV3Result,
    observer_ledger_trend: &ObserverComparisonLedgerTrendV2,
    member_experience_store: Option<&[MemberExperienceRecord]>,
    owner_feedback: Option<&[OwnerFeedback]>,
    policy: &ChairmanRewardPenaltyCandidatePolicy,
) -> Result<ChairmanGovernanceCandidateBuildResult, String> {
    validate_chairman_reward_penalty_candidate_policy(policy)?;
    let mut warnings = Vec::new();
    let mut entries = Vec::new();
    let experience_records = member_experience_store.unwrap_or(&[]);
    let mut positive_counts = std::collections::BTreeMap::<String, usize>::new();
    let mut negative_counts = std::collections::BTreeMap::<String, usize>::new();
    let mut evidence_request_members = std::collections::BTreeSet::<String>::new();
    for record in experience_records {
        if outcome_is_positive_for_shadow_governance(record.outcome) {
            *positive_counts.entry(record.member_id.clone()).or_insert(0) += 1;
        }
        if outcome_is_negative_for_shadow_governance(record.outcome) {
            *negative_counts.entry(record.member_id.clone()).or_insert(0) += 1;
        }
    }
    if let Some(owner_feedback) = owner_feedback {
        for feedback in owner_feedback {
            if let Some(member_id) = feedback.target_member_id.as_ref() {
                if feedback.feedback_type == OwnerFeedbackType::EvidenceRequest {
                    evidence_request_members.insert(member_id.clone());
                }
            }
        }
    }

    let run_id = format!("{}-candidate-build", governance_inputs.set_id);
    for input in &governance_inputs.records {
        let member_id = input.source_member_id.clone();
        let positive_count = member_id
            .as_ref()
            .and_then(|member_id| positive_counts.get(member_id))
            .copied()
            .unwrap_or(0);
        let negative_count = member_id
            .as_ref()
            .and_then(|member_id| negative_counts.get(member_id))
            .copied()
            .unwrap_or(0);
        let evidence_requested = member_id
            .as_ref()
            .map(|member_id| evidence_request_members.contains(member_id))
            .unwrap_or(false);
        let mut primary_candidate = input.suggested_governance_consideration;
        match input.signal_kind {
            ChairmanShadowGovernanceSignalKind::HelpfulDissentCandidate => {
                if !policy.allow_reward_candidates {
                    primary_candidate = ChairmanShadowGovernanceConsideration::NeedsMoreEvidence;
                } else {
                    primary_candidate = ChairmanShadowGovernanceConsideration::RewardCandidate;
                }
            }
            ChairmanShadowGovernanceSignalKind::RiskVetoAlignment => {
                if policy.allow_voice_candidates {
                    primary_candidate =
                        ChairmanShadowGovernanceConsideration::VoiceIncreaseCandidate;
                }
            }
            ChairmanShadowGovernanceSignalKind::ObserverDisagreement
            | ChairmanShadowGovernanceSignalKind::OverconfidentCallCandidate => {
                if negative_count > 0 || input.confidence == SourceConfidence::High {
                    primary_candidate = ChairmanShadowGovernanceConsideration::PenaltyCandidate;
                }
            }
            ChairmanShadowGovernanceSignalKind::NeedMoreEvidenceCandidate => {
                primary_candidate = if evidence_requested
                    || member_id
                        .as_deref()
                        .map(|member_id| member_id.contains("evidence"))
                        .unwrap_or(false)
                {
                    ChairmanShadowGovernanceConsideration::KeepNeutral
                } else {
                    ChairmanShadowGovernanceConsideration::NeedsMoreEvidence
                };
            }
            ChairmanShadowGovernanceSignalKind::ObserverAgreement => {
                if positive_count > 0 && policy.allow_reward_candidates {
                    primary_candidate = ChairmanShadowGovernanceConsideration::RewardCandidate;
                }
            }
            ChairmanShadowGovernanceSignalKind::OwnerOpinionAligned
            | ChairmanShadowGovernanceSignalKind::OwnerOpinionIgnoredWithReason
            | ChairmanShadowGovernanceSignalKind::OwnerOpinionIgnoredWithReasonCandidate
            | ChairmanShadowGovernanceSignalKind::Neutral => {}
        }
        entries.push(chairman_candidate_entry(
            format!("{}-{}", run_id, entries.len()),
            &run_id,
            member_id.clone(),
            input.observer_id.clone(),
            input.symbol.clone(),
            input.market_scope,
            input.signal_kind,
            primary_candidate,
            input.evidence_summary.clone(),
            input.confidence,
        ));
        if input.signal_kind == ChairmanShadowGovernanceSignalKind::HelpfulDissentCandidate
            && positive_count > 0
            && policy.allow_voice_candidates
        {
            entries.push(chairman_candidate_entry(
                format!("{}-{}", run_id, entries.len()),
                &run_id,
                member_id.clone(),
                input.observer_id.clone(),
                input.symbol.clone(),
                input.market_scope,
                input.signal_kind,
                ChairmanShadowGovernanceConsideration::VoiceIncreaseCandidate,
                "Helpful dissent stayed constructive in paper evaluation".to_string(),
                input.confidence,
            ));
        }
        if input.signal_kind == ChairmanShadowGovernanceSignalKind::OverconfidentCallCandidate
            && policy.allow_voice_candidates
        {
            entries.push(chairman_candidate_entry(
                format!("{}-{}", run_id, entries.len()),
                &run_id,
                member_id.clone(),
                input.observer_id.clone(),
                input.symbol.clone(),
                input.market_scope,
                input.signal_kind,
                ChairmanShadowGovernanceConsideration::VoiceDecreaseCandidate,
                "High-confidence risky shadow call should stay advisory and reduce shadow voice pressure"
                    .to_string(),
                input.confidence,
            ));
        }
    }

    for member_id in positive_counts.keys().chain(negative_counts.keys()) {
        let confidence = if positive_counts.get(member_id).copied().unwrap_or(0) >= 3
            || negative_counts.get(member_id).copied().unwrap_or(0) >= 3
        {
            SourceConfidence::High
        } else {
            SourceConfidence::Medium
        };
        if positive_counts.get(member_id).copied().unwrap_or(0) >= 2
            && policy.allow_promotion_candidates
            && source_confidence_meets_minimum(
                confidence,
                policy.min_confidence_for_promotion_candidate,
            )
        {
            entries.push(chairman_candidate_entry(
                format!("{}-{}", run_id, entries.len()),
                &run_id,
                Some(member_id.clone()),
                None,
                None,
                None,
                ChairmanShadowGovernanceSignalKind::ObserverAgreement,
                ChairmanShadowGovernanceConsideration::PromotionCandidate,
                "Repeated good shadow/member agreement observed across paper outcomes".to_string(),
                confidence,
            ));
        }
        if negative_counts.get(member_id).copied().unwrap_or(0) >= 2
            && policy.allow_demotion_candidates
            && source_confidence_meets_minimum(
                confidence,
                policy.min_confidence_for_demotion_candidate,
            )
        {
            entries.push(chairman_candidate_entry(
                format!("{}-{}", run_id, entries.len()),
                &run_id,
                Some(member_id.clone()),
                None,
                None,
                None,
                ChairmanShadowGovernanceSignalKind::ObserverDisagreement,
                ChairmanShadowGovernanceConsideration::DemotionCandidate,
                "Repeated severe mismatch stayed shadow-only and becomes demotion review candidate"
                    .to_string(),
                confidence,
            ));
        }
    }

    if observer_comparison_result.disagreement_delta > 0
        && observer_ledger_trend.disagreement_trend == ObserverTrendDirection::Worsening
    {
        warnings.push(
            "observer disagreement is worsening; chairman governance remains shadow-only"
                .to_string(),
        );
    }

    let reward_candidate_count = entries
        .iter()
        .filter(|entry| {
            entry.governance_candidate == ChairmanShadowGovernanceConsideration::RewardCandidate
        })
        .count();
    let penalty_candidate_count = entries
        .iter()
        .filter(|entry| {
            entry.governance_candidate == ChairmanShadowGovernanceConsideration::PenaltyCandidate
        })
        .count();
    let voice_increase_candidate_count = entries
        .iter()
        .filter(|entry| {
            entry.governance_candidate
                == ChairmanShadowGovernanceConsideration::VoiceIncreaseCandidate
        })
        .count();
    let voice_decrease_candidate_count = entries
        .iter()
        .filter(|entry| {
            entry.governance_candidate
                == ChairmanShadowGovernanceConsideration::VoiceDecreaseCandidate
        })
        .count();
    let promotion_candidate_count = entries
        .iter()
        .filter(|entry| {
            entry.governance_candidate == ChairmanShadowGovernanceConsideration::PromotionCandidate
        })
        .count();
    let demotion_candidate_count = entries
        .iter()
        .filter(|entry| {
            entry.governance_candidate == ChairmanShadowGovernanceConsideration::DemotionCandidate
        })
        .count();
    let needs_more_evidence_count = entries
        .iter()
        .filter(|entry| {
            entry.governance_candidate == ChairmanShadowGovernanceConsideration::NeedsMoreEvidence
        })
        .count();
    let build_status = if entries.is_empty() {
        ChairmanGovernanceCandidateBuildStatus::NoCandidates
    } else if !warnings.is_empty() {
        ChairmanGovernanceCandidateBuildStatus::BuiltWithWarnings
    } else {
        ChairmanGovernanceCandidateBuildStatus::Built
    };
    Ok(ChairmanGovernanceCandidateBuildResult {
        run_id,
        input_count: governance_inputs.record_count,
        generated_entry_count: entries.len(),
        reward_candidate_count,
        penalty_candidate_count,
        voice_increase_candidate_count,
        voice_decrease_candidate_count,
        promotion_candidate_count,
        demotion_candidate_count,
        needs_more_evidence_count,
        entries,
        build_status,
        warnings,
        paper_only: true,
    })
}

pub fn evaluate_owner_opinion_alignment(
    owner_input: &OwnerFeedback,
    chairman_decision: Option<&ChairmanDecision>,
    risk_governor_status: Option<RiskGovernorStatus>,
    committee_summary: Option<&OwnerCommitteeSummary>,
    observer_summary: Option<&str>,
) -> OwnerOpinionAlignmentRecord {
    let owner_reference = OwnerOpinionReferenceRecord {
        owner_input_id: Some(owner_input.feedback_id.clone()),
        symbol: owner_input.symbol.clone(),
        market_scope: owner_input.market_scope,
        owner_intent: owner_intent_from_feedback_type(owner_input.feedback_type),
        owner_summary: owner_input.text.clone(),
        paper_only: true,
    };
    if reject_unsafe_owner_feedback_string(&owner_input.text).is_err() {
        return OwnerOpinionAlignmentRecord {
            alignment_id: format!("{}-owner-alignment", owner_input.feedback_id),
            owner_reference,
            chairman_decision_id: chairman_decision.map(|decision| decision.decision_id.clone()),
            risk_governor_status,
            observer_summary: observer_summary.map(|summary| summary.to_string()),
            alignment_status: OwnerOpinionAlignmentStatus::NotAligned,
            followed_owner_opinion: false,
            not_followed_reason: Some(OwnerOpinionNotFollowedReason::OwnerRequestedActionUnsafe),
            explanation:
                "Owner opinion was treated as reference only and unsafe trade/order language was rejected."
                    .to_string(),
            paper_only: true,
        };
    }
    let final_action = chairman_decision.map(|decision| decision.final_action);
    let disagreement_signal = committee_summary
        .map(|summary| !summary.top_dissenting_members.is_empty())
        .unwrap_or(false)
        || observer_summary
            .map(|summary| summary.to_ascii_lowercase().contains("disagreement"))
            .unwrap_or(false);
    let (alignment_status, followed_owner_opinion, not_followed_reason, explanation) =
        match owner_input.feedback_type {
            OwnerFeedbackType::RiskConcern => {
                if matches!(
                    risk_governor_status,
                    Some(RiskGovernorStatus::Vetoed | RiskGovernorStatus::NeedsReview)
                ) || matches!(
                    final_action,
                    Some(
                        ChairmanFinalAction::RiskVetoed
                            | ChairmanFinalAction::NeedMoreEvidence
                            | ChairmanFinalAction::PaperNoTrade
                    )
                ) {
                    (
                        OwnerOpinionAlignmentStatus::Aligned,
                        true,
                        None,
                        "Owner risk concern aligned with the paper-only risk boundary and Chairman kept governance shadow-only."
                            .to_string(),
                    )
                } else {
                    (
                        OwnerOpinionAlignmentStatus::NotAligned,
                        false,
                        Some(OwnerOpinionNotFollowedReason::HigherRiskThanOwnerAssumed),
                        "Owner risk concern was noted, but the Chairman shadow evaluation judged the paper decision risk lower than the owner assumed."
                            .to_string(),
                    )
                }
            }
            OwnerFeedbackType::EvidenceRequest => {
                if matches!(
                    final_action,
                    Some(ChairmanFinalAction::NeedMoreEvidence | ChairmanFinalAction::PaperNoTrade)
                ) || matches!(risk_governor_status, Some(RiskGovernorStatus::NeedsReview))
                {
                    (
                        OwnerOpinionAlignmentStatus::Aligned,
                        true,
                        None,
                        "Owner evidence request aligned with the paper-only decision path and extra evidence remained required."
                            .to_string(),
                    )
                } else {
                    (
                        OwnerOpinionAlignmentStatus::NeedsMoreEvidence,
                        false,
                        Some(OwnerOpinionNotFollowedReason::InsufficientEvidence),
                        "Owner evidence request was recorded, but the current paper-only record still needs clearer supporting evidence."
                            .to_string(),
                    )
                }
            }
            OwnerFeedbackType::WatchlistRequest => (
                OwnerOpinionAlignmentStatus::Aligned,
                true,
                None,
                "Owner watchlist opinion was treated as reference and kept in observation-only form."
                    .to_string(),
            ),
            OwnerFeedbackType::ReconsiderationRequest | OwnerFeedbackType::Disagree => {
                if matches!(risk_governor_status, Some(RiskGovernorStatus::Vetoed)) {
                    (
                        OwnerOpinionAlignmentStatus::NotAligned,
                        false,
                        Some(OwnerOpinionNotFollowedReason::RiskGovernorVeto),
                        "Owner opinion was not followed because Risk Governor veto remained the paper-only boundary."
                            .to_string(),
                    )
                } else if disagreement_signal {
                    (
                        OwnerOpinionAlignmentStatus::PartiallyAligned,
                        true,
                        Some(OwnerOpinionNotFollowedReason::CommitteeDisagreement),
                        "Owner opinion was partially aligned because disagreement was visible, but the Chairman shadow evaluation did not change the committee decision."
                            .to_string(),
                    )
                } else {
                    (
                        OwnerOpinionAlignmentStatus::NotAligned,
                        false,
                        Some(OwnerOpinionNotFollowedReason::PaperOnlyBoundary),
                        "Owner opinion was considered, but paper-only governance cannot force a decision change."
                            .to_string(),
                    )
                }
            }
            OwnerFeedbackType::PaperOutcomeLabel | OwnerFeedbackType::Comment => (
                OwnerOpinionAlignmentStatus::NotApplicable,
                false,
                Some(OwnerOpinionNotFollowedReason::NotApplicable),
                "Owner opinion was logged as paper-only reference and did not request governance action."
                    .to_string(),
            ),
        };
    OwnerOpinionAlignmentRecord {
        alignment_id: format!("{}-owner-alignment", owner_input.feedback_id),
        owner_reference,
        chairman_decision_id: chairman_decision.map(|decision| decision.decision_id.clone()),
        risk_governor_status,
        observer_summary: observer_summary.map(|summary| summary.to_string()),
        alignment_status,
        followed_owner_opinion,
        not_followed_reason,
        explanation,
        paper_only: true,
    }
}

pub fn default_owner_opinion_explanation_contract() -> OwnerOpinionExplanationContract {
    OwnerOpinionExplanationContract {
        contract_id: "owner-opinion-explanation-contract".to_string(),
        require_explanation_when_not_followed: true,
        require_risk_governor_reason: true,
        require_committee_disagreement_reason: true,
        require_evidence_reason: true,
        forbid_trade_execution_language: true,
        paper_only: true,
    }
}

pub fn build_owner_opinion_explanation(
    alignment_record: &OwnerOpinionAlignmentRecord,
    contract: &OwnerOpinionExplanationContract,
) -> OwnerOpinionExplanationResult {
    let mut explanation = alignment_record.explanation.clone();
    let mut status = match alignment_record.alignment_status {
        OwnerOpinionAlignmentStatus::NotApplicable => OwnerOpinionExplanationStatus::NotApplicable,
        _ => OwnerOpinionExplanationStatus::Explained,
    };
    if contract.require_explanation_when_not_followed
        && !alignment_record.followed_owner_opinion
        && explanation.trim().is_empty()
    {
        explanation = "Owner opinion was not followed in paper-only governance, but no explanation was available."
            .to_string();
        status = OwnerOpinionExplanationStatus::Failed;
    }
    if let Some(reason) = alignment_record.not_followed_reason {
        let required_reason = match reason {
            OwnerOpinionNotFollowedReason::RiskGovernorVeto => {
                contract.require_risk_governor_reason
            }
            OwnerOpinionNotFollowedReason::CommitteeDisagreement => {
                contract.require_committee_disagreement_reason
            }
            OwnerOpinionNotFollowedReason::InsufficientEvidence => contract.require_evidence_reason,
            _ => true,
        };
        if !required_reason {
            status = OwnerOpinionExplanationStatus::ExplainedWithWarnings;
        }
    }
    if contract.forbid_trade_execution_language
        && reject_unsafe_owner_feedback_string(&explanation).is_err()
    {
        status = OwnerOpinionExplanationStatus::Failed;
    } else if matches!(
        alignment_record.alignment_status,
        OwnerOpinionAlignmentStatus::PartiallyAligned
    ) {
        status = OwnerOpinionExplanationStatus::ExplainedWithWarnings;
    }
    OwnerOpinionExplanationResult {
        explanation_id: format!("{}-explanation", alignment_record.alignment_id),
        alignment_record: alignment_record.clone(),
        owner_readable_explanation: explanation,
        explanation_status: status,
        paper_only: true,
    }
}

fn build_owner_opinion_ledger_entries(
    run_id: &str,
    alignment_records: &[OwnerOpinionAlignmentRecord],
) -> Vec<ChairmanShadowGovernanceLedgerEntry> {
    alignment_records
        .iter()
        .enumerate()
        .map(|(index, record)| {
            let governance_candidate = match record.alignment_status {
                OwnerOpinionAlignmentStatus::NeedsMoreEvidence => {
                    ChairmanShadowGovernanceConsideration::NeedsMoreEvidence
                }
                _ => ChairmanShadowGovernanceConsideration::KeepNeutral,
            };
            let signal_kind = match record.alignment_status {
                OwnerOpinionAlignmentStatus::Aligned
                | OwnerOpinionAlignmentStatus::PartiallyAligned => {
                    ChairmanShadowGovernanceSignalKind::OwnerOpinionAligned
                }
                _ => ChairmanShadowGovernanceSignalKind::OwnerOpinionIgnoredWithReason,
            };
            chairman_candidate_entry(
                format!("{run_id}-owner-opinion-{index}"),
                run_id,
                None,
                None,
                record.owner_reference.symbol.clone(),
                record.owner_reference.market_scope,
                signal_kind,
                governance_candidate,
                record.explanation.clone(),
                SourceConfidence::Medium,
            )
        })
        .collect()
}

pub fn summarize_chairman_voice_governance_shadow(
    ledger: &ChairmanShadowGovernanceLedger,
) -> Vec<ChairmanVoiceGovernanceShadowSummary> {
    let mut per_member =
        std::collections::BTreeMap::<String, Vec<&ChairmanShadowGovernanceLedgerEntry>>::new();
    for entry in &ledger.entries {
        if let Some(member_id) = entry.member_id.as_ref() {
            per_member.entry(member_id.clone()).or_default().push(entry);
        }
    }
    per_member
        .into_iter()
        .map(|(member_id, entries)| {
            let reward_candidate_count = entries
                .iter()
                .filter(|entry| {
                    entry.governance_candidate
                        == ChairmanShadowGovernanceConsideration::RewardCandidate
                })
                .count();
            let penalty_candidate_count = entries
                .iter()
                .filter(|entry| {
                    entry.governance_candidate
                        == ChairmanShadowGovernanceConsideration::PenaltyCandidate
                })
                .count();
            let voice_increase_candidate_count = entries
                .iter()
                .filter(|entry| {
                    entry.governance_candidate
                        == ChairmanShadowGovernanceConsideration::VoiceIncreaseCandidate
                })
                .count();
            let voice_decrease_candidate_count = entries
                .iter()
                .filter(|entry| {
                    entry.governance_candidate
                        == ChairmanShadowGovernanceConsideration::VoiceDecreaseCandidate
                })
                .count();
            let promotion_candidate_count = entries
                .iter()
                .filter(|entry| {
                    entry.governance_candidate
                        == ChairmanShadowGovernanceConsideration::PromotionCandidate
                })
                .count();
            let demotion_candidate_count = entries
                .iter()
                .filter(|entry| {
                    entry.governance_candidate
                        == ChairmanShadowGovernanceConsideration::DemotionCandidate
                })
                .count();
            let needs_more_evidence_count = entries
                .iter()
                .filter(|entry| {
                    entry.governance_candidate
                        == ChairmanShadowGovernanceConsideration::NeedsMoreEvidence
                })
                .count();
            let (net_shadow_voice_pressure, suggested_shadow_action) =
                if promotion_candidate_count > 0 {
                    (
                        ChairmanVoiceGovernanceShadowPressure::Increase,
                        ChairmanVoiceGovernanceShadowAction::CandidateForPromotionReview,
                    )
                } else if demotion_candidate_count > 0 {
                    (
                        ChairmanVoiceGovernanceShadowPressure::Decrease,
                        ChairmanVoiceGovernanceShadowAction::CandidateForDemotionReview,
                    )
                } else if voice_increase_candidate_count > voice_decrease_candidate_count {
                    (
                        ChairmanVoiceGovernanceShadowPressure::Increase,
                        ChairmanVoiceGovernanceShadowAction::CandidateForVoiceIncrease,
                    )
                } else if voice_decrease_candidate_count > voice_increase_candidate_count {
                    (
                        ChairmanVoiceGovernanceShadowPressure::Decrease,
                        ChairmanVoiceGovernanceShadowAction::CandidateForVoiceDecrease,
                    )
                } else if needs_more_evidence_count > 0
                    && reward_candidate_count == 0
                    && penalty_candidate_count == 0
                {
                    (
                        ChairmanVoiceGovernanceShadowPressure::NeedsMoreEvidence,
                        ChairmanVoiceGovernanceShadowAction::NeedsMoreEvidence,
                    )
                } else {
                    (
                        ChairmanVoiceGovernanceShadowPressure::Neutral,
                        ChairmanVoiceGovernanceShadowAction::ObserveOnly,
                    )
                };
            ChairmanVoiceGovernanceShadowSummary {
                summary_id: format!("{}-voice-shadow-summary", member_id),
                member_id,
                reward_candidate_count,
                penalty_candidate_count,
                voice_increase_candidate_count,
                voice_decrease_candidate_count,
                promotion_candidate_count,
                demotion_candidate_count,
                net_shadow_voice_pressure,
                suggested_shadow_action,
                no_actual_voice_change: true,
                paper_only: true,
            }
        })
        .collect()
}

pub fn evaluate_chairman_governance_shadow_safety_v2(
    governance_result: &ChairmanShadowGovernanceRunResult,
    owner_alignment_results: &[OwnerOpinionAlignmentRecord],
    batch_before: &BatchCommitteeCycleResult,
    batch_after: Option<&BatchCommitteeCycleResult>,
) -> ChairmanGovernanceShadowSafetyGuardV2 {
    let after = batch_after.unwrap_or(batch_before);
    let score_snapshot = |batch: &BatchCommitteeCycleResult| {
        batch
            .score_updates
            .iter()
            .map(|update| (update.member_id.clone(), update.new_score))
            .collect::<std::collections::BTreeMap<_, _>>()
    };
    let voice_snapshot = |batch: &BatchCommitteeCycleResult| {
        batch
            .score_updates
            .iter()
            .map(|update| (update.member_id.clone(), update.new_voice_weight))
            .collect::<std::collections::BTreeMap<_, _>>()
    };
    let promoted_members = |batch: &BatchCommitteeCycleResult| {
        batch
            .score_updates
            .iter()
            .filter(|update| update.promoted)
            .map(|update| update.member_id.clone())
            .collect::<std::collections::BTreeSet<_>>()
    };
    let demoted_members = |batch: &BatchCommitteeCycleResult| {
        batch
            .score_updates
            .iter()
            .filter(|update| update.demoted)
            .map(|update| update.member_id.clone())
            .collect::<std::collections::BTreeSet<_>>()
    };
    let score_mutation_detected = score_snapshot(batch_before) != score_snapshot(after);
    let voice_mutation_detected = voice_snapshot(batch_before) != voice_snapshot(after);
    let promotion_detected = promoted_members(batch_before) != promoted_members(after);
    let demotion_detected = demoted_members(batch_before) != demoted_members(after);
    let risk_governor_override_detected = batch_before
        .chairman_decisions
        .iter()
        .map(|decision| decision.risk_governor_status)
        .collect::<Vec<_>>()
        != after
            .chairman_decisions
            .iter()
            .map(|decision| decision.risk_governor_status)
            .collect::<Vec<_>>();
    let chairman_decision_mutation_detected =
        batch_before.chairman_decisions != after.chairman_decisions;
    let committee_decision_mutation_detected =
        batch_before.committee_sessions != after.committee_sessions;
    let markers = governance_result
        .ledger
        .entries
        .iter()
        .map(|entry| entry.entry_id.clone())
        .collect::<Vec<_>>();
    let trade_signal_detected = value_contains_debug_marker(&after.committee_sessions, &markers);
    let order_detected = value_contains_debug_marker(&after.event_queue, &markers);
    let broker_order_account_detected = governance_result
        .ledger
        .entries
        .iter()
        .any(|entry| reject_unsafe_owner_feedback_string(&entry.evidence_summary).is_err());
    let owner_opinion_forced_trade_detected = owner_alignment_results.iter().any(|record| {
        record.followed_owner_opinion
            && reject_unsafe_owner_feedback_string(&record.owner_reference.owner_summary).is_err()
    });
    let mut violations = Vec::new();
    if score_mutation_detected {
        violations.push("chairman governance shadow mutated score".to_string());
    }
    if voice_mutation_detected {
        violations.push("chairman governance shadow mutated voice".to_string());
    }
    if promotion_detected {
        violations.push("chairman governance shadow promoted member".to_string());
    }
    if demotion_detected {
        violations.push("chairman governance shadow demoted member".to_string());
    }
    if risk_governor_override_detected {
        violations.push("chairman governance shadow overrode Risk Governor".to_string());
    }
    if chairman_decision_mutation_detected {
        violations.push("chairman governance shadow changed Chairman decision".to_string());
    }
    if committee_decision_mutation_detected {
        violations.push("chairman governance shadow changed committee decision".to_string());
    }
    if trade_signal_detected {
        violations.push("chairman governance shadow created trade signal".to_string());
    }
    if order_detected {
        violations.push("chairman governance shadow created order".to_string());
    }
    if broker_order_account_detected {
        violations.push("chairman governance shadow touched broker/order/account path".to_string());
    }
    if owner_opinion_forced_trade_detected {
        violations.push("owner opinion forced trade path".to_string());
    }
    ChairmanGovernanceShadowSafetyGuardV2 {
        score_mutation_detected,
        voice_mutation_detected,
        promotion_detected,
        demotion_detected,
        risk_governor_override_detected,
        chairman_decision_mutation_detected,
        committee_decision_mutation_detected,
        trade_signal_detected,
        order_detected,
        broker_order_account_detected,
        owner_opinion_forced_trade_detected,
        guard_status: if violations.is_empty() {
            ChairmanGovernanceShadowSafetyGuardV2Status::Preserved
        } else {
            ChairmanGovernanceShadowSafetyGuardV2Status::Violated
        },
        violations,
        paper_only: true,
    }
}

pub fn build_owner_chairman_governance_summary(
    run_result: &ChairmanShadowGovernanceRunResult,
) -> OwnerChairmanGovernanceSummary {
    OwnerChairmanGovernanceSummary {
        summary_id: format!("{}-owner-chairman-governance-summary", run_result.run_id),
        reward_candidate_count: run_result.ledger.reward_candidate_count,
        penalty_candidate_count: run_result.ledger.penalty_candidate_count,
        voice_increase_candidate_count: run_result.ledger.voice_increase_candidate_count,
        voice_decrease_candidate_count: run_result.ledger.voice_decrease_candidate_count,
        promotion_candidate_count: run_result.ledger.promotion_candidate_count,
        demotion_candidate_count: run_result.ledger.demotion_candidate_count,
        owner_opinion_explanation_count: run_result.owner_explanation_results.len(),
        message: "Chairman governance is shadow-only. No score or voice weight changed. No member was promoted or demoted. Owner opinion was treated as reference and explanation was generated when needed."
            .to_string(),
        chairman_shadow_only: true,
        no_score_mutation: true,
        no_voice_mutation: true,
        no_promotion_demotion: true,
        no_risk_override: true,
        not_trade_signal: true,
        paper_only: true,
    }
}

pub fn run_chairman_shadow_governance(
    governance_inputs: &ChairmanShadowGovernanceInputSet,
    observer_comparison_result: &ObserverComparisonRerunV3Result,
    observer_ledger_trend: &ObserverComparisonLedgerTrendV2,
    member_experience_store: Option<&[MemberExperienceRecord]>,
    owner_feedback: Option<&[OwnerFeedback]>,
    batch_result: &BatchCommitteeCycleResult,
    config: &ChairmanShadowGovernanceRunConfig,
) -> Result<ChairmanShadowGovernanceRunResult, String> {
    if !config.paper_only {
        return Err("chairman shadow governance run must remain paper_only".to_string());
    }
    let candidate_build_result = build_chairman_governance_candidates(
        governance_inputs,
        observer_comparison_result,
        observer_ledger_trend,
        member_experience_store,
        owner_feedback,
        &default_chairman_reward_penalty_candidate_policy(),
    )?;
    let mut ledger = if let Some(path) = config.ledger_input_path.as_ref() {
        if Path::new(path).exists() {
            load_chairman_shadow_governance_ledger_from_local_json(Path::new(path))?
        } else {
            default_empty_chairman_shadow_governance_ledger(&config.run_id)
        }
    } else {
        default_empty_chairman_shadow_governance_ledger(&config.run_id)
    };
    append_chairman_shadow_governance_entries(&mut ledger, &candidate_build_result.entries);
    let observer_summary = format!(
        "rerun={:?}, disagreement_delta={}, trend={:?}",
        observer_comparison_result.rerun_status,
        observer_comparison_result.disagreement_delta,
        observer_ledger_trend.disagreement_trend
    );
    let owner_opinion_alignment_records = owner_feedback
        .unwrap_or(&[])
        .iter()
        .map(|feedback| {
            let chairman_decision = batch_result.chairman_decisions.iter().find(|decision| {
                feedback
                    .symbol
                    .as_ref()
                    .map(|symbol| {
                        batch_result
                            .committee_sessions
                            .iter()
                            .find(|session| session.session_id == decision.session_id)
                            .map(|session| session.event.symbol.as_str() == symbol.as_str())
                            .unwrap_or(false)
                    })
                    .unwrap_or(true)
            });
            evaluate_owner_opinion_alignment(
                feedback,
                chairman_decision,
                chairman_decision.map(|decision| decision.risk_governor_status),
                None,
                Some(&observer_summary),
            )
        })
        .collect::<Vec<_>>();
    let owner_alignment_entries =
        build_owner_opinion_ledger_entries(&config.run_id, &owner_opinion_alignment_records);
    append_chairman_shadow_governance_entries(&mut ledger, &owner_alignment_entries);
    let owner_explanation_results = if config.emit_owner_explanations {
        owner_opinion_alignment_records
            .iter()
            .map(|record| {
                build_owner_opinion_explanation(
                    record,
                    &default_owner_opinion_explanation_contract(),
                )
            })
            .collect::<Vec<_>>()
    } else {
        Vec::new()
    };
    if !config.dry_run {
        let path = config.ledger_output_path.as_ref().ok_or_else(|| {
            "chairman shadow governance non-dry run requires ledger_output_path".to_string()
        })?;
        save_chairman_shadow_governance_ledger_to_local_json(Path::new(path), &ledger)?;
    }
    let voice_governance_summaries = summarize_chairman_voice_governance_shadow(&ledger);
    let provisional = ChairmanShadowGovernanceRunResult {
        run_id: config.run_id.clone(),
        candidate_build_result: candidate_build_result.clone(),
        ledger: ledger.clone(),
        owner_opinion_alignment_records: owner_opinion_alignment_records.clone(),
        owner_explanation_results: owner_explanation_results.clone(),
        voice_governance_summaries: voice_governance_summaries.clone(),
        safety_guard: ChairmanGovernanceShadowSafetyGuardV2 {
            score_mutation_detected: false,
            voice_mutation_detected: false,
            promotion_detected: false,
            demotion_detected: false,
            risk_governor_override_detected: false,
            chairman_decision_mutation_detected: false,
            committee_decision_mutation_detected: false,
            trade_signal_detected: false,
            order_detected: false,
            broker_order_account_detected: false,
            owner_opinion_forced_trade_detected: false,
            guard_status: ChairmanGovernanceShadowSafetyGuardV2Status::Preserved,
            violations: Vec::new(),
            paper_only: true,
        },
        run_status: ChairmanShadowGovernanceRunStatus::Passed,
        paper_only: true,
    };
    let safety_guard = evaluate_chairman_governance_shadow_safety_v2(
        &provisional,
        &owner_opinion_alignment_records,
        batch_result,
        Some(batch_result),
    );
    let run_status = if candidate_build_result.build_status
        == ChairmanGovernanceCandidateBuildStatus::Failed
        || safety_guard.guard_status == ChairmanGovernanceShadowSafetyGuardV2Status::Violated
    {
        ChairmanShadowGovernanceRunStatus::Failed
    } else if config.dry_run
        || candidate_build_result.build_status
            == ChairmanGovernanceCandidateBuildStatus::BuiltWithWarnings
        || owner_explanation_results.iter().any(|result| {
            matches!(
                result.explanation_status,
                OwnerOpinionExplanationStatus::ExplainedWithWarnings
            )
        })
    {
        ChairmanShadowGovernanceRunStatus::PassedWithWarnings
    } else {
        ChairmanShadowGovernanceRunStatus::Passed
    };
    Ok(ChairmanShadowGovernanceRunResult {
        run_id: config.run_id.clone(),
        candidate_build_result,
        ledger,
        owner_opinion_alignment_records,
        owner_explanation_results,
        voice_governance_summaries,
        safety_guard,
        run_status,
        paper_only: true,
    })
}

pub fn chairman_shadow_governance_requested_from_flags(
    enabled: bool,
    dry_run: bool,
    ledger_output_path: Option<&String>,
    owner_feedback_path: Option<&String>,
    _emit_owner_explanations: bool,
    _emit_owner_summary: bool,
) -> bool {
    enabled || !dry_run || ledger_output_path.is_some() || owner_feedback_path.is_some()
}

fn maybe_run_chairman_shadow_governance_for_batch_result(
    run_id: String,
    enabled: bool,
    dry_run: bool,
    ledger_output_path: Option<&String>,
    owner_feedback_path: Option<&String>,
    emit_owner_explanations: bool,
    emit_owner_summary: bool,
    batch_result: &mut BatchCommitteeCycleResult,
) -> Result<Option<ChairmanShadowGovernanceRunResult>, String> {
    if !chairman_shadow_governance_requested_from_flags(
        enabled,
        dry_run,
        ledger_output_path,
        owner_feedback_path,
        emit_owner_explanations,
        emit_owner_summary,
    ) {
        return Ok(None);
    }
    let owner_feedback = if let Some(path) = owner_feedback_path {
        load_owner_feedback_from_local_json(Path::new(path))?
    } else {
        Vec::new()
    };
    let comparison_rerun_v3 = if let Some(run) = batch_result
        .observer_apply_verify_chairman_shadow_run_result
        .as_ref()
    {
        run.comparison_rerun_v3.clone()
    } else {
        batch_result
            .observer_comparison_rerun_v3_result
            .clone()
            .or_else(|| {
                dry_run.then_some(ObserverComparisonRerunV3Result {
                    previous_target_count: 0,
                    new_target_count: 0,
                    target_delta: 0,
                    previous_disagreement_count: 0,
                    new_disagreement_count: 0,
                    disagreement_delta: 0,
                    previous_readiness_status:
                        SmartCoreObserverLaneReadinessStatus::NeedsMoreTargets,
                    new_comparison_summary_status:
                        ObserverVsCommitteeComparisonSummaryStatus::InsufficientComparisons,
                    target_store_accepted: false,
                    rerun_status: ObserverComparisonRerunV3Status::NeedsMoreTargets,
                    paper_only: true,
                })
            })
            .ok_or_else(|| {
                "chairman shadow governance run requires observer comparison rerun v3".to_string()
            })?
    };
    let ledger_trend_v2 = if let Some(run) = batch_result
        .observer_apply_verify_chairman_shadow_run_result
        .as_ref()
    {
        run.ledger_trend_v2.clone()
    } else {
        batch_result
            .observer_comparison_ledger_trend_v2
            .clone()
            .or_else(|| {
                dry_run.then_some(ObserverComparisonLedgerTrendV2 {
                    ledger_id: format!("{run_id}-observer-neutral-trend"),
                    entry_count: 0,
                    latest_readiness_status: SmartCoreObserverLaneReadinessStatus::NeedsMoreTargets,
                    latest_target_count: 0,
                    latest_disagreement_count: 0,
                    target_count_trend: ObserverTargetCountTrendDirection::InsufficientHistory,
                    disagreement_trend: ObserverTrendDirection::InsufficientHistory,
                    readiness_trend: ObserverTrendDirection::InsufficientHistory,
                    trend_status: ObserverComparisonLedgerTrendStatus::InsufficientHistory,
                    paper_only: true,
                })
            })
            .ok_or_else(|| {
                "chairman shadow governance run requires observer ledger trend v2".to_string()
            })?
    };
    let governance_inputs = if let Some(run) = batch_result
        .observer_apply_verify_chairman_shadow_run_result
        .as_ref()
    {
        run.chairman_shadow_governance_inputs
            .clone()
            .unwrap_or_else(|| {
                build_chairman_shadow_governance_input_set(
                    format!("{run_id}-shadow-input"),
                    &comparison_rerun_v3,
                    &ledger_trend_v2,
                    &batch_result.member_experience_records,
                )
            })
    } else {
        batch_result
            .chairman_shadow_governance_input_set
            .clone()
            .unwrap_or_else(|| {
                build_chairman_shadow_governance_input_set(
                    format!("{run_id}-shadow-input"),
                    &comparison_rerun_v3,
                    &ledger_trend_v2,
                    &batch_result.member_experience_records,
                )
            })
    };
    let result = run_chairman_shadow_governance(
        &governance_inputs,
        &comparison_rerun_v3,
        &ledger_trend_v2,
        Some(batch_result.member_experience_records.as_slice()),
        Some(owner_feedback.as_slice()),
        batch_result,
        &ChairmanShadowGovernanceRunConfig {
            run_id: run_id.clone(),
            enabled,
            ledger_input_path: None,
            ledger_output_path: ledger_output_path.cloned(),
            owner_feedback_path: owner_feedback_path.cloned(),
            emit_owner_explanations,
            dry_run,
            paper_only: true,
        },
    )?;
    batch_result.chairman_shadow_governance_ledger = Some(result.ledger.clone());
    batch_result.chairman_governance_candidate_build_result =
        Some(result.candidate_build_result.clone());
    batch_result.owner_opinion_alignment_records =
        Some(result.owner_opinion_alignment_records.clone());
    batch_result.owner_opinion_explanation_results = Some(result.owner_explanation_results.clone());
    batch_result.chairman_voice_governance_shadow_summaries =
        Some(result.voice_governance_summaries.clone());
    batch_result.chairman_governance_shadow_safety_guard_v2 = Some(result.safety_guard.clone());
    batch_result.chairman_shadow_governance_run_result = Some(result.clone());
    if emit_owner_summary {
        batch_result.owner_chairman_governance_summary =
            Some(build_owner_chairman_governance_summary(&result));
    }
    Ok(Some(result))
}

pub fn default_chairman_shadow_governance_simulation_policy()
-> ChairmanShadowGovernanceSimulationPolicy {
    ChairmanShadowGovernanceSimulationPolicy {
        policy_id: "chairman-shadow-governance-simulation-policy".to_string(),
        max_abs_score_delta_per_entry: 0.05,
        max_abs_voice_delta_per_entry: 0.03,
        max_total_voice_delta_per_member: 0.08,
        min_confidence_for_positive_delta: SourceConfidence::Medium,
        min_confidence_for_negative_delta: SourceConfidence::Medium,
        allow_review_required_delta: false,
        allow_actual_score_mutation: false,
        allow_actual_voice_mutation: false,
        allow_promotion_demotion: false,
        allow_risk_governor_override: false,
        risk_first_bias: true,
        paper_only: true,
    }
}

pub fn validate_chairman_shadow_governance_simulation_policy(
    policy: &ChairmanShadowGovernanceSimulationPolicy,
) -> Result<(), String> {
    if !policy.paper_only {
        return Err(
            "chairman shadow governance simulation policy must stay paper_only".to_string(),
        );
    }
    if policy.allow_actual_score_mutation
        || policy.allow_actual_voice_mutation
        || policy.allow_promotion_demotion
        || policy.allow_risk_governor_override
    {
        return Err(
            "chairman shadow governance simulation policy must forbid actual mutations".to_string(),
        );
    }
    if policy.max_abs_score_delta_per_entry < 0.0
        || policy.max_abs_voice_delta_per_entry < 0.0
        || policy.max_total_voice_delta_per_member < 0.0
    {
        return Err(
            "chairman shadow governance simulation policy bounds must be non-negative".to_string(),
        );
    }
    Ok(())
}

fn bounded_shadow_delta(value: f64, max_abs: f64) -> f64 {
    if value.is_nan() || !value.is_finite() {
        0.0
    } else if value > max_abs {
        max_abs
    } else if value < -max_abs {
        -max_abs
    } else {
        value
    }
}

fn build_score_delta_reason(
    entry: &ChairmanShadowGovernanceLedgerEntry,
) -> ChairmanShadowScoreDeltaReason {
    match entry.signal_kind {
        ChairmanShadowGovernanceSignalKind::HelpfulDissentCandidate => {
            ChairmanShadowScoreDeltaReason::HelpfulDissent
        }
        ChairmanShadowGovernanceSignalKind::RiskVetoAlignment => {
            ChairmanShadowScoreDeltaReason::RiskVetoAligned
        }
        ChairmanShadowGovernanceSignalKind::OverconfidentCallCandidate => {
            ChairmanShadowScoreDeltaReason::OverconfidentBadCall
        }
        ChairmanShadowGovernanceSignalKind::ObserverAgreement => {
            ChairmanShadowScoreDeltaReason::ObserverAgreement
        }
        ChairmanShadowGovernanceSignalKind::ObserverDisagreement => {
            ChairmanShadowScoreDeltaReason::ObserverDisagreement
        }
        ChairmanShadowGovernanceSignalKind::OwnerOpinionAligned => {
            ChairmanShadowScoreDeltaReason::OwnerOpinionAligned
        }
        ChairmanShadowGovernanceSignalKind::OwnerOpinionIgnoredWithReason
        | ChairmanShadowGovernanceSignalKind::OwnerOpinionIgnoredWithReasonCandidate => {
            ChairmanShadowScoreDeltaReason::OwnerOpinionNotFollowedSafely
        }
        ChairmanShadowGovernanceSignalKind::NeedMoreEvidenceCandidate
        | ChairmanShadowGovernanceSignalKind::Neutral => {
            ChairmanShadowScoreDeltaReason::NeedsMoreEvidence
        }
    }
}

fn build_voice_delta_reason(
    entry: &ChairmanShadowGovernanceLedgerEntry,
) -> ChairmanShadowVoiceDeltaReason {
    match entry.signal_kind {
        ChairmanShadowGovernanceSignalKind::HelpfulDissentCandidate => {
            ChairmanShadowVoiceDeltaReason::HelpfulDissent
        }
        ChairmanShadowGovernanceSignalKind::RiskVetoAlignment => {
            ChairmanShadowVoiceDeltaReason::RiskSavedLoss
        }
        ChairmanShadowGovernanceSignalKind::OverconfidentCallCandidate => {
            ChairmanShadowVoiceDeltaReason::OverconfidentRisk
        }
        ChairmanShadowGovernanceSignalKind::ObserverAgreement => {
            ChairmanShadowVoiceDeltaReason::ConsistentObserverAgreement
        }
        ChairmanShadowGovernanceSignalKind::ObserverDisagreement => {
            ChairmanShadowVoiceDeltaReason::SevereObserverDisagreement
        }
        ChairmanShadowGovernanceSignalKind::NeedMoreEvidenceCandidate
        | ChairmanShadowGovernanceSignalKind::OwnerOpinionAligned
        | ChairmanShadowGovernanceSignalKind::OwnerOpinionIgnoredWithReason
        | ChairmanShadowGovernanceSignalKind::OwnerOpinionIgnoredWithReasonCandidate
        | ChairmanShadowGovernanceSignalKind::Neutral => {
            ChairmanShadowVoiceDeltaReason::NeedsMoreEvidence
        }
    }
}

fn confidence_allows_shadow_delta(
    confidence: SourceConfidence,
    minimum: SourceConfidence,
    allow_review_required_delta: bool,
) -> bool {
    if confidence == SourceConfidence::ReviewRequired && !allow_review_required_delta {
        return false;
    }
    source_confidence_meets_minimum(confidence, minimum)
}

pub fn build_chairman_shadow_score_delta(
    entry: &ChairmanShadowGovernanceLedgerEntry,
    policy: &ChairmanShadowGovernanceSimulationPolicy,
) -> ChairmanShadowScoreDelta {
    let unsafe_or_needs_more_evidence =
        reject_unsafe_owner_feedback_string(&entry.evidence_summary).is_err()
            || entry.governance_candidate
                == ChairmanShadowGovernanceConsideration::NeedsMoreEvidence;
    let reason = if unsafe_or_needs_more_evidence {
        ChairmanShadowScoreDeltaReason::NeedsMoreEvidence
    } else if entry.governance_candidate == ChairmanShadowGovernanceConsideration::KeepNeutral {
        ChairmanShadowScoreDeltaReason::EvidenceWeakness
    } else {
        build_score_delta_reason(entry)
    };
    let (delta_kind, proposed_score_delta) = if unsafe_or_needs_more_evidence {
        (ChairmanShadowScoreDeltaKind::NeedsMoreEvidence, 0.0)
    } else {
        match entry.governance_candidate {
            ChairmanShadowGovernanceConsideration::RewardCandidate
            | ChairmanShadowGovernanceConsideration::PromotionCandidate => {
                if confidence_allows_shadow_delta(
                    entry.confidence,
                    policy.min_confidence_for_positive_delta,
                    policy.allow_review_required_delta,
                ) {
                    (
                        ChairmanShadowScoreDeltaKind::Reward,
                        bounded_shadow_delta(0.04, policy.max_abs_score_delta_per_entry),
                    )
                } else {
                    (ChairmanShadowScoreDeltaKind::NeedsMoreEvidence, 0.0)
                }
            }
            ChairmanShadowGovernanceConsideration::PenaltyCandidate
            | ChairmanShadowGovernanceConsideration::DemotionCandidate => {
                if confidence_allows_shadow_delta(
                    entry.confidence,
                    policy.min_confidence_for_negative_delta,
                    policy.allow_review_required_delta,
                ) {
                    (
                        ChairmanShadowScoreDeltaKind::Penalty,
                        bounded_shadow_delta(-0.05, policy.max_abs_score_delta_per_entry),
                    )
                } else {
                    (ChairmanShadowScoreDeltaKind::NeedsMoreEvidence, 0.0)
                }
            }
            ChairmanShadowGovernanceConsideration::KeepNeutral
            | ChairmanShadowGovernanceConsideration::VoiceIncreaseCandidate
            | ChairmanShadowGovernanceConsideration::VoiceDecreaseCandidate => {
                (ChairmanShadowScoreDeltaKind::Neutral, 0.0)
            }
            ChairmanShadowGovernanceConsideration::NeedsMoreEvidence => {
                (ChairmanShadowScoreDeltaKind::NeedsMoreEvidence, 0.0)
            }
        }
    };
    ChairmanShadowScoreDelta {
        delta_id: format!("{}-score-delta", entry.entry_id),
        source_ledger_entry_id: entry.entry_id.clone(),
        member_id: entry
            .member_id
            .clone()
            .unwrap_or_else(|| "unknown-member".to_string()),
        symbol: entry.symbol.clone(),
        market_scope: entry.market_scope,
        delta_kind,
        proposed_score_delta,
        reason,
        confidence: entry.confidence,
        shadow_only: true,
        no_actual_score_mutation: true,
        paper_only: true,
    }
}

pub fn build_chairman_shadow_voice_delta(
    entry: &ChairmanShadowGovernanceLedgerEntry,
    policy: &ChairmanShadowGovernanceSimulationPolicy,
) -> ChairmanShadowVoiceDelta {
    let unsafe_or_needs_more_evidence =
        reject_unsafe_owner_feedback_string(&entry.evidence_summary).is_err()
            || entry.governance_candidate
                == ChairmanShadowGovernanceConsideration::NeedsMoreEvidence;
    let reason = if unsafe_or_needs_more_evidence {
        ChairmanShadowVoiceDeltaReason::NeedsMoreEvidence
    } else {
        build_voice_delta_reason(entry)
    };
    let (delta_kind, proposed_voice_delta) = if unsafe_or_needs_more_evidence {
        (ChairmanShadowVoiceDeltaKind::NeedsMoreEvidence, 0.0)
    } else {
        match entry.governance_candidate {
            ChairmanShadowGovernanceConsideration::VoiceIncreaseCandidate
            | ChairmanShadowGovernanceConsideration::PromotionCandidate => {
                if confidence_allows_shadow_delta(
                    entry.confidence,
                    policy.min_confidence_for_positive_delta,
                    policy.allow_review_required_delta,
                ) {
                    (
                        ChairmanShadowVoiceDeltaKind::Increase,
                        bounded_shadow_delta(0.02, policy.max_abs_voice_delta_per_entry),
                    )
                } else {
                    (ChairmanShadowVoiceDeltaKind::NeedsMoreEvidence, 0.0)
                }
            }
            ChairmanShadowGovernanceConsideration::VoiceDecreaseCandidate
            | ChairmanShadowGovernanceConsideration::DemotionCandidate => {
                if confidence_allows_shadow_delta(
                    entry.confidence,
                    policy.min_confidence_for_negative_delta,
                    policy.allow_review_required_delta,
                ) {
                    (
                        ChairmanShadowVoiceDeltaKind::Decrease,
                        bounded_shadow_delta(-0.03, policy.max_abs_voice_delta_per_entry),
                    )
                } else {
                    (ChairmanShadowVoiceDeltaKind::NeedsMoreEvidence, 0.0)
                }
            }
            ChairmanShadowGovernanceConsideration::NeedsMoreEvidence => {
                (ChairmanShadowVoiceDeltaKind::NeedsMoreEvidence, 0.0)
            }
            ChairmanShadowGovernanceConsideration::RewardCandidate
                if entry.signal_kind == ChairmanShadowGovernanceSignalKind::RiskVetoAlignment =>
            {
                (
                    ChairmanShadowVoiceDeltaKind::Increase,
                    bounded_shadow_delta(0.02, policy.max_abs_voice_delta_per_entry),
                )
            }
            ChairmanShadowGovernanceConsideration::PenaltyCandidate
                if entry.signal_kind
                    == ChairmanShadowGovernanceSignalKind::OverconfidentCallCandidate =>
            {
                (
                    ChairmanShadowVoiceDeltaKind::Decrease,
                    bounded_shadow_delta(-0.02, policy.max_abs_voice_delta_per_entry),
                )
            }
            _ => (ChairmanShadowVoiceDeltaKind::Neutral, 0.0),
        }
    };
    ChairmanShadowVoiceDelta {
        delta_id: format!("{}-voice-delta", entry.entry_id),
        source_ledger_entry_id: entry.entry_id.clone(),
        member_id: entry
            .member_id
            .clone()
            .unwrap_or_else(|| "unknown-member".to_string()),
        symbol: entry.symbol.clone(),
        market_scope: entry.market_scope,
        delta_kind,
        proposed_voice_delta,
        reason,
        confidence: entry.confidence,
        shadow_only: true,
        no_actual_voice_mutation: true,
        paper_only: true,
    }
}

pub fn simulate_chairman_shadow_governance(
    ledger: &ChairmanShadowGovernanceLedger,
    member_states: &[MemberStateSnapshot],
    policy: &ChairmanShadowGovernanceSimulationPolicy,
) -> Result<ChairmanShadowGovernanceSimulationResult, String> {
    validate_chairman_shadow_governance_simulation_policy(policy)?;
    let member_state_map = member_states
        .iter()
        .map(|state| (state.member_id.clone(), state))
        .collect::<std::collections::BTreeMap<_, _>>();
    let mut score_deltas = Vec::new();
    let mut voice_deltas = Vec::new();
    let mut aggregated = std::collections::BTreeMap::<String, (f64, f64, bool)>::new();
    for entry in &ledger.entries {
        let Some(member_id) = entry.member_id.as_ref() else {
            continue;
        };
        if !member_state_map.contains_key(member_id) {
            continue;
        }
        let score_delta = build_chairman_shadow_score_delta(entry, policy);
        let voice_delta = build_chairman_shadow_voice_delta(entry, policy);
        let aggregate = aggregated
            .entry(member_id.clone())
            .or_insert((0.0, 0.0, false));
        aggregate.0 += score_delta.proposed_score_delta;
        aggregate.1 += voice_delta.proposed_voice_delta;
        aggregate.2 |= score_delta.delta_kind == ChairmanShadowScoreDeltaKind::NeedsMoreEvidence
            || voice_delta.delta_kind == ChairmanShadowVoiceDeltaKind::NeedsMoreEvidence;
        score_deltas.push(score_delta);
        voice_deltas.push(voice_delta);
    }
    let simulated_member_standings = member_states
        .iter()
        .map(|state| {
            let (score_delta_total, voice_delta_total_raw, needs_more_evidence) = aggregated
                .get(&state.member_id)
                .copied()
                .unwrap_or((0.0, 0.0, false));
            let voice_delta_total = bounded_shadow_delta(
                voice_delta_total_raw,
                policy.max_total_voice_delta_per_member,
            );
            let simulated_score = clamp_unit(state.score + score_delta_total);
            let simulated_voice_weight = clamp_unit(state.voice_weight + voice_delta_total);
            let standing_status = if needs_more_evidence
                && score_delta_total.abs() <= f64::EPSILON
                && voice_delta_total.abs() <= f64::EPSILON
            {
                SimulatedMemberStandingStatus::NeedsMoreEvidence
            } else if score_delta_total > 0.0 || voice_delta_total > 0.0 {
                SimulatedMemberStandingStatus::ImprovedShadowStanding
            } else if score_delta_total < 0.0 || voice_delta_total < 0.0 {
                SimulatedMemberStandingStatus::ReducedShadowStanding
            } else {
                SimulatedMemberStandingStatus::NeutralShadowStanding
            };
            SimulatedMemberStanding {
                member_id: state.member_id.clone(),
                original_score: state.score,
                simulated_score,
                original_voice_weight: state.voice_weight,
                simulated_voice_weight,
                score_delta_total,
                voice_delta_total,
                standing_status,
                paper_only: true,
            }
        })
        .collect::<Vec<_>>();
    let reward_delta_count = score_deltas
        .iter()
        .filter(|delta| delta.delta_kind == ChairmanShadowScoreDeltaKind::Reward)
        .count();
    let penalty_delta_count = score_deltas
        .iter()
        .filter(|delta| delta.delta_kind == ChairmanShadowScoreDeltaKind::Penalty)
        .count();
    let voice_increase_count = voice_deltas
        .iter()
        .filter(|delta| delta.delta_kind == ChairmanShadowVoiceDeltaKind::Increase)
        .count();
    let voice_decrease_count = voice_deltas
        .iter()
        .filter(|delta| delta.delta_kind == ChairmanShadowVoiceDeltaKind::Decrease)
        .count();
    let needs_more_evidence_count = score_deltas
        .iter()
        .filter(|delta| delta.delta_kind == ChairmanShadowScoreDeltaKind::NeedsMoreEvidence)
        .count()
        + voice_deltas
            .iter()
            .filter(|delta| delta.delta_kind == ChairmanShadowVoiceDeltaKind::NeedsMoreEvidence)
            .count();
    let simulation_status = if score_deltas.is_empty() && voice_deltas.is_empty() {
        ChairmanShadowGovernanceSimulationStatus::NoDeltas
    } else if needs_more_evidence_count > 0 {
        ChairmanShadowGovernanceSimulationStatus::SimulatedWithWarnings
    } else {
        ChairmanShadowGovernanceSimulationStatus::Simulated
    };
    Ok(ChairmanShadowGovernanceSimulationResult {
        simulation_id: format!("{}-simulation", ledger.ledger_id),
        source_ledger_id: ledger.ledger_id.clone(),
        score_deltas,
        voice_deltas,
        simulated_member_standings,
        reward_delta_count,
        penalty_delta_count,
        voice_increase_count,
        voice_decrease_count,
        needs_more_evidence_count,
        simulation_status,
        no_actual_score_mutation: true,
        no_actual_voice_mutation: true,
        no_promotion_demotion: true,
        no_risk_governor_override: true,
        paper_only: true,
    })
}

pub fn evaluate_chairman_governance_fairness(
    simulation_result: &ChairmanShadowGovernanceSimulationResult,
    policy: &ChairmanShadowGovernanceSimulationPolicy,
) -> ChairmanGovernanceFairnessCheck {
    let member_count = simulation_result.simulated_member_standings.len();
    let total_voice = simulation_result
        .simulated_member_standings
        .iter()
        .map(|standing| standing.simulated_voice_weight)
        .sum::<f64>();
    let max_voice_concentration = if total_voice > f64::EPSILON {
        simulation_result
            .simulated_member_standings
            .iter()
            .map(|standing| standing.simulated_voice_weight / total_voice)
            .fold(0.0, f64::max)
    } else {
        0.0
    };
    let min_voice_weight = simulation_result
        .simulated_member_standings
        .iter()
        .map(|standing| standing.simulated_voice_weight)
        .reduce(f64::min)
        .unwrap_or(0.0);
    let excessive_penalty_count = simulation_result
        .simulated_member_standings
        .iter()
        .filter(|standing| standing.score_delta_total <= -policy.max_abs_score_delta_per_entry)
        .count();
    let excessive_reward_count = simulation_result
        .simulated_member_standings
        .iter()
        .filter(|standing| standing.score_delta_total >= policy.max_abs_score_delta_per_entry)
        .count();
    let single_member_dominance_detected = max_voice_concentration > 0.55;
    let unfair_penalty_detected = excessive_penalty_count > member_count.saturating_div(2)
        && excessive_penalty_count > excessive_reward_count + 1;
    let mut warnings = Vec::new();
    if max_voice_concentration > 0.45 {
        warnings.push("shadow voice concentration is approaching dominance".to_string());
    }
    if excessive_penalty_count > 0 {
        warnings.push("shadow simulation contains concentrated penalties".to_string());
    }
    let fairness_status = if member_count == 0 {
        ChairmanGovernanceFairnessStatus::InsufficientData
    } else if single_member_dominance_detected || unfair_penalty_detected {
        ChairmanGovernanceFairnessStatus::Unfair
    } else if !warnings.is_empty() {
        ChairmanGovernanceFairnessStatus::FairWithWarnings
    } else {
        ChairmanGovernanceFairnessStatus::Fair
    };
    ChairmanGovernanceFairnessCheck {
        check_id: format!("{}-fairness", simulation_result.simulation_id),
        member_count,
        max_voice_concentration,
        min_voice_weight,
        excessive_penalty_count,
        excessive_reward_count,
        single_member_dominance_detected,
        unfair_penalty_detected,
        fairness_status,
        warnings,
        paper_only: true,
    }
}

pub fn evaluate_chairman_risk_first_governance(
    simulation_result: &ChairmanShadowGovernanceSimulationResult,
    ledger: &ChairmanShadowGovernanceLedger,
) -> ChairmanRiskFirstGovernanceCheck {
    let risk_guard_rewarded_count = simulation_result
        .score_deltas
        .iter()
        .filter(|delta| {
            delta.reason == ChairmanShadowScoreDeltaReason::RiskVetoAligned
                && delta.proposed_score_delta > 0.0
        })
        .count()
        + simulation_result
            .voice_deltas
            .iter()
            .filter(|delta| {
                delta.reason == ChairmanShadowVoiceDeltaReason::RiskSavedLoss
                    && delta.proposed_voice_delta > 0.0
            })
            .count();
    let risky_overconfidence_penalized_count = simulation_result
        .score_deltas
        .iter()
        .filter(|delta| {
            delta.reason == ChairmanShadowScoreDeltaReason::OverconfidentBadCall
                && delta.proposed_score_delta < 0.0
        })
        .count()
        + simulation_result
            .voice_deltas
            .iter()
            .filter(|delta| {
                delta.reason == ChairmanShadowVoiceDeltaReason::OverconfidentRisk
                    && delta.proposed_voice_delta < 0.0
            })
            .count();
    let risk_veto_alignment_count = ledger
        .entries
        .iter()
        .filter(|entry| entry.signal_kind == ChairmanShadowGovernanceSignalKind::RiskVetoAlignment)
        .count();
    let risk_override_attempt_detected = ledger
        .entries
        .iter()
        .any(|entry| !entry.no_risk_governor_override);
    let reckless_reward_detected = simulation_result.score_deltas.iter().any(|delta| {
        delta.reason == ChairmanShadowScoreDeltaReason::OverconfidentBadCall
            && delta.proposed_score_delta > 0.0
    });
    let mut warnings = Vec::new();
    if risk_veto_alignment_count > 0 && risk_guard_rewarded_count == 0 {
        warnings.push(
            "risk-veto alignment exists but no positive shadow reward was simulated".to_string(),
        );
    }
    if risky_overconfidence_penalized_count == 0
        && ledger.entries.iter().any(|entry| {
            entry.signal_kind == ChairmanShadowGovernanceSignalKind::OverconfidentCallCandidate
        })
    {
        warnings.push("overconfident risk call exists without negative shadow delta".to_string());
    }
    let risk_first_status = if risk_override_attempt_detected || reckless_reward_detected {
        ChairmanRiskFirstGovernanceStatus::Violated
    } else if !warnings.is_empty() {
        ChairmanRiskFirstGovernanceStatus::PreservedWithWarnings
    } else {
        ChairmanRiskFirstGovernanceStatus::Preserved
    };
    ChairmanRiskFirstGovernanceCheck {
        check_id: format!("{}-risk-first", simulation_result.simulation_id),
        risk_guard_rewarded_count,
        risky_overconfidence_penalized_count,
        risk_veto_alignment_count,
        risk_override_attempt_detected,
        reckless_reward_detected,
        risk_first_status,
        warnings,
        paper_only: true,
    }
}

fn simulation_ledger_entry_key(
    entry: &ChairmanShadowGovernanceSimulationLedgerEntry,
) -> (
    String,
    usize,
    usize,
    usize,
    usize,
    usize,
    ChairmanGovernanceFairnessStatus,
    ChairmanRiskFirstGovernanceStatus,
) {
    (
        entry.simulation_id.clone(),
        entry.reward_delta_count,
        entry.penalty_delta_count,
        entry.voice_increase_count,
        entry.voice_decrease_count,
        entry.needs_more_evidence_count,
        entry.fairness_status,
        entry.risk_first_status,
    )
}

pub fn normalize_chairman_shadow_governance_simulation_ledger(
    ledger: &mut ChairmanShadowGovernanceSimulationLedger,
) {
    let mut seen = std::collections::BTreeSet::new();
    ledger.entries.sort_by(|left, right| {
        simulation_ledger_entry_key(left).cmp(&simulation_ledger_entry_key(right))
    });
    ledger
        .entries
        .retain(|entry| seen.insert(simulation_ledger_entry_key(entry)));
    ledger.entry_count = ledger.entries.len();
    ledger.latest_entry_id = ledger.entries.last().map(|entry| entry.entry_id.clone());
}

fn validate_chairman_shadow_governance_simulation_ledger(
    ledger: &ChairmanShadowGovernanceSimulationLedger,
) -> Result<(), String> {
    if !ledger.paper_only {
        return Err(
            "chairman shadow governance simulation ledger must stay paper_only".to_string(),
        );
    }
    for entry in &ledger.entries {
        if !entry.paper_only {
            return Err(format!(
                "chairman shadow governance simulation ledger entry {} must stay paper_only",
                entry.entry_id
            ));
        }
    }
    Ok(())
}

pub fn load_chairman_shadow_governance_simulation_ledger_from_local_json(
    path: &Path,
) -> Result<ChairmanShadowGovernanceSimulationLedger, String> {
    validate_local_json_path(path, "chairman shadow governance simulation ledger path")?;
    let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
    let mut ledger: ChairmanShadowGovernanceSimulationLedger =
        serde_json::from_str(&text).map_err(|err| err.to_string())?;
    normalize_chairman_shadow_governance_simulation_ledger(&mut ledger);
    validate_chairman_shadow_governance_simulation_ledger(&ledger)?;
    Ok(ledger)
}

pub fn save_chairman_shadow_governance_simulation_ledger_to_local_json(
    path: &Path,
    ledger: &ChairmanShadowGovernanceSimulationLedger,
) -> Result<(), String> {
    validate_local_json_path(path, "chairman shadow governance simulation ledger path")?;
    let mut normalized = ledger.clone();
    normalize_chairman_shadow_governance_simulation_ledger(&mut normalized);
    validate_chairman_shadow_governance_simulation_ledger(&normalized)?;
    write_safe_json(path, &normalized)
}

pub fn append_chairman_shadow_governance_simulation_entry(
    ledger: &mut ChairmanShadowGovernanceSimulationLedger,
    entry: ChairmanShadowGovernanceSimulationLedgerEntry,
) {
    ledger.entries.push(entry);
    normalize_chairman_shadow_governance_simulation_ledger(ledger);
}

fn trend_direction_from_counts(
    first: usize,
    last: usize,
) -> ChairmanShadowGovernanceTrendDirection {
    if last > first {
        ChairmanShadowGovernanceTrendDirection::Increasing
    } else if last < first {
        ChairmanShadowGovernanceTrendDirection::Decreasing
    } else {
        ChairmanShadowGovernanceTrendDirection::Stable
    }
}

pub fn compute_chairman_shadow_governance_trend(
    ledger: &ChairmanShadowGovernanceSimulationLedger,
) -> ChairmanShadowGovernanceTrendSummary {
    if ledger.entries.len() < 2 {
        return ChairmanShadowGovernanceTrendSummary {
            ledger_id: ledger.ledger_id.clone(),
            entry_count: ledger.entry_count,
            reward_trend: ChairmanShadowGovernanceTrendDirection::InsufficientHistory,
            penalty_trend: ChairmanShadowGovernanceTrendDirection::InsufficientHistory,
            voice_change_trend: ChairmanShadowGovernanceTrendDirection::InsufficientHistory,
            trend_status: ChairmanShadowGovernanceTrendStatus::InsufficientHistory,
            paper_only: true,
        };
    }
    let first = &ledger.entries[0];
    let last = ledger.entries.last().expect("non-empty simulation ledger");
    let reward_trend =
        trend_direction_from_counts(first.reward_delta_count, last.reward_delta_count);
    let penalty_trend =
        trend_direction_from_counts(first.penalty_delta_count, last.penalty_delta_count);
    let voice_change_trend = trend_direction_from_counts(
        first.voice_increase_count + first.voice_decrease_count,
        last.voice_increase_count + last.voice_decrease_count,
    );
    ChairmanShadowGovernanceTrendSummary {
        ledger_id: ledger.ledger_id.clone(),
        entry_count: ledger.entry_count,
        reward_trend,
        penalty_trend,
        voice_change_trend,
        trend_status: if ledger.entries.len() >= 3 {
            ChairmanShadowGovernanceTrendStatus::Useful
        } else {
            ChairmanShadowGovernanceTrendStatus::UsefulWithWarnings
        },
        paper_only: true,
    }
}

pub fn evaluate_chairman_shadow_governance_readiness(
    simulation_result: &ChairmanShadowGovernanceSimulationResult,
    fairness_check: &ChairmanGovernanceFairnessCheck,
    risk_check: &ChairmanRiskFirstGovernanceCheck,
    trend_summary: &ChairmanShadowGovernanceTrendSummary,
    safety_guard: &ChairmanGovernanceSimulationSafetyGuardV3,
) -> ChairmanShadowGovernanceReadinessGate {
    let enough_history = trend_summary.entry_count >= 2;
    let mut blockers = Vec::new();
    let mut warnings = fairness_check.warnings.clone();
    warnings.extend(risk_check.warnings.clone());
    if safety_guard.guard_status == ChairmanGovernanceSimulationSafetyGuardV3Status::Violated {
        blockers.push("shadow governance simulation safety violated".to_string());
    }
    if fairness_check.fairness_status == ChairmanGovernanceFairnessStatus::Unfair {
        blockers.push("shadow governance simulation fairness blocked".to_string());
    }
    if risk_check.risk_first_status == ChairmanRiskFirstGovernanceStatus::Violated {
        blockers.push("shadow governance simulation risk-first blocked".to_string());
    }
    let readiness_status =
        if safety_guard.guard_status == ChairmanGovernanceSimulationSafetyGuardV3Status::Violated {
            ChairmanShadowGovernanceReadinessStatus::BlockedBySafety
        } else if fairness_check.fairness_status == ChairmanGovernanceFairnessStatus::Unfair {
            ChairmanShadowGovernanceReadinessStatus::BlockedByFairness
        } else if risk_check.risk_first_status == ChairmanRiskFirstGovernanceStatus::Violated {
            ChairmanShadowGovernanceReadinessStatus::BlockedByRiskViolation
        } else if !enough_history {
            ChairmanShadowGovernanceReadinessStatus::NeedsMoreHistory
        } else if simulation_result.needs_more_evidence_count > 0 {
            ChairmanShadowGovernanceReadinessStatus::NeedsMoreEvidence
        } else if !warnings.is_empty()
            || simulation_result.simulation_status
                == ChairmanShadowGovernanceSimulationStatus::SimulatedWithWarnings
        {
            ChairmanShadowGovernanceReadinessStatus::ShadowGovernanceObservationReadyWithWarnings
        } else {
            ChairmanShadowGovernanceReadinessStatus::ShadowGovernanceObservationReady
        };
    ChairmanShadowGovernanceReadinessGate {
        gate_id: format!("{}-readiness", simulation_result.simulation_id),
        simulation_status: simulation_result.simulation_status,
        fairness_status: fairness_check.fairness_status,
        risk_first_status: risk_check.risk_first_status,
        trend_status: trend_summary.trend_status,
        safety_status: safety_guard.guard_status,
        enough_history,
        ready_for_shadow_governance_observation: blockers.is_empty()
            && enough_history
            && simulation_result.simulation_status
                != ChairmanShadowGovernanceSimulationStatus::Blocked,
        readiness_status,
        blockers,
        warnings,
        paper_only: true,
    }
}

pub fn build_chairman_shadow_governance_explanations(
    simulation_result: &ChairmanShadowGovernanceSimulationResult,
    owner_alignment_records: Option<&[OwnerOpinionAlignmentRecord]>,
) -> Vec<ChairmanShadowGovernanceExplanation> {
    simulation_result
        .simulated_member_standings
        .iter()
        .map(|standing| {
            let score_reasons = simulation_result
                .score_deltas
                .iter()
                .filter(|delta| delta.member_id == standing.member_id && delta.proposed_score_delta.abs() > f64::EPSILON)
                .map(|delta| format!("{:?}({:+.2})", delta.reason, delta.proposed_score_delta))
                .collect::<Vec<_>>();
            let voice_reasons = simulation_result
                .voice_deltas
                .iter()
                .filter(|delta| delta.member_id == standing.member_id && delta.proposed_voice_delta.abs() > f64::EPSILON)
                .map(|delta| format!("{:?}({:+.2})", delta.reason, delta.proposed_voice_delta))
                .collect::<Vec<_>>();
            let owner_opinion_explanation = owner_alignment_records.and_then(|records| {
                records
                    .iter()
                    .find(|record| {
                        record.owner_reference.symbol.as_ref().is_some_and(|symbol| {
                            simulation_result.score_deltas.iter().any(|delta| {
                                delta.member_id == standing.member_id
                                    && delta.symbol.as_deref() == Some(symbol.as_str())
                            }) || simulation_result.voice_deltas.iter().any(|delta| {
                                delta.member_id == standing.member_id
                                    && delta.symbol.as_deref() == Some(symbol.as_str())
                            })
                        })
                    })
                    .map(|record| {
                        if reject_unsafe_owner_feedback_string(&record.explanation).is_err() {
                            "Owner opinion explanation was suppressed because it contained unsafe trade/order language."
                                .to_string()
                        } else {
                            record.explanation.clone()
                        }
                    })
            });
            ChairmanShadowGovernanceExplanation {
                explanation_id: format!("{}-explanation", standing.member_id),
                member_id: standing.member_id.clone(),
                score_delta_explanation: if score_reasons.is_empty() {
                    "No shadow score delta was simulated.".to_string()
                } else {
                    format!("Shadow score delta reasons: {}", score_reasons.join(", "))
                },
                voice_delta_explanation: if voice_reasons.is_empty() {
                    "No shadow voice delta was simulated.".to_string()
                } else {
                    format!("Shadow voice delta reasons: {}", voice_reasons.join(", "))
                },
                risk_first_explanation: if standing.score_delta_total < 0.0
                    || standing.voice_delta_total < 0.0
                {
                    "Risk-first posture preserved by penalizing reckless or weak-evidence behavior in shadow-only simulation."
                        .to_string()
                } else {
                    "Risk-first posture preserved without executing any real governance mutation."
                        .to_string()
                },
                evidence_explanation: if standing.standing_status
                    == SimulatedMemberStandingStatus::NeedsMoreEvidence
                {
                    "Evidence is still weak, so governance simulation stayed neutral or requested more evidence."
                        .to_string()
                } else {
                    "Evidence stayed paper-only and was used for simulation only.".to_string()
                },
                owner_opinion_explanation,
                paper_only: true,
            }
        })
        .collect()
}

pub fn evaluate_chairman_governance_simulation_safety_v3(
    simulation_result: &ChairmanShadowGovernanceSimulationResult,
    batch_before: &BatchCommitteeCycleResult,
    batch_after: Option<&BatchCommitteeCycleResult>,
) -> ChairmanGovernanceSimulationSafetyGuardV3 {
    let after = batch_after.unwrap_or(batch_before);
    let score_snapshot = |updates: &[MemberScoreUpdate]| {
        updates
            .iter()
            .map(|update| (update.member_id.clone(), update.new_score))
            .collect::<std::collections::BTreeMap<_, _>>()
    };
    let voice_snapshot = |updates: &[MemberScoreUpdate]| {
        updates
            .iter()
            .map(|update| (update.member_id.clone(), update.new_voice_weight))
            .collect::<std::collections::BTreeMap<_, _>>()
    };
    let promotion_snapshot = |updates: &[MemberScoreUpdate]| {
        updates
            .iter()
            .filter(|update| update.promoted)
            .map(|update| update.member_id.clone())
            .collect::<std::collections::BTreeSet<_>>()
    };
    let demotion_snapshot = |updates: &[MemberScoreUpdate]| {
        updates
            .iter()
            .filter(|update| update.demoted)
            .map(|update| update.member_id.clone())
            .collect::<std::collections::BTreeSet<_>>()
    };
    let risk_governor_snapshot = |decisions: &[ChairmanDecision]| {
        decisions
            .iter()
            .map(|decision| (decision.decision_id.clone(), decision.risk_governor_status))
            .collect::<std::collections::BTreeMap<_, _>>()
    };
    let actual_score_mutation_detected =
        score_snapshot(&batch_before.score_updates) != score_snapshot(&after.score_updates);
    let actual_voice_mutation_detected =
        voice_snapshot(&batch_before.score_updates) != voice_snapshot(&after.score_updates);
    let promotion_execution_detected =
        promotion_snapshot(&batch_before.score_updates) != promotion_snapshot(&after.score_updates);
    let demotion_execution_detected =
        demotion_snapshot(&batch_before.score_updates) != demotion_snapshot(&after.score_updates);
    let risk_governor_override_detected = risk_governor_snapshot(&batch_before.chairman_decisions)
        != risk_governor_snapshot(&after.chairman_decisions);
    let committee_decision_mutation_detected =
        batch_before.committee_sessions != after.committee_sessions;
    let markers = simulation_result
        .score_deltas
        .iter()
        .map(|delta| delta.delta_id.clone())
        .chain(
            simulation_result
                .voice_deltas
                .iter()
                .map(|delta| delta.delta_id.clone()),
        )
        .collect::<Vec<_>>();
    let trade_signal_detected = value_contains_debug_marker(&after.committee_sessions, &markers);
    let order_detected = value_contains_debug_marker(&after.event_queue, &markers);
    let broker_order_account_detected = value_contains_debug_marker(
        &after.event_queue,
        &[
            "broker".to_string(),
            "order".to_string(),
            "account".to_string(),
        ],
    );
    let owner_opinion_forced_trade_detected = simulation_result.score_deltas.iter().any(|delta| {
        delta.reason == ChairmanShadowScoreDeltaReason::OwnerOpinionAligned
            && (trade_signal_detected || order_detected || broker_order_account_detected)
    });
    let mut violations = Vec::new();
    if actual_score_mutation_detected {
        violations.push("shadow governance simulation mutated actual score".to_string());
    }
    if actual_voice_mutation_detected {
        violations.push("shadow governance simulation mutated actual voice".to_string());
    }
    if promotion_execution_detected {
        violations.push("shadow governance simulation executed promotion".to_string());
    }
    if demotion_execution_detected {
        violations.push("shadow governance simulation executed demotion".to_string());
    }
    if risk_governor_override_detected {
        violations.push("shadow governance simulation overrode Risk Governor".to_string());
    }
    if committee_decision_mutation_detected {
        violations.push("shadow governance simulation changed committee decision".to_string());
    }
    if trade_signal_detected {
        violations.push("shadow governance simulation produced trade signal".to_string());
    }
    if order_detected {
        violations.push("shadow governance simulation produced order".to_string());
    }
    if broker_order_account_detected {
        violations
            .push("shadow governance simulation touched broker/order/account path".to_string());
    }
    if owner_opinion_forced_trade_detected {
        violations.push("owner opinion forced trade through simulation".to_string());
    }
    ChairmanGovernanceSimulationSafetyGuardV3 {
        actual_score_mutation_detected,
        actual_voice_mutation_detected,
        promotion_execution_detected,
        demotion_execution_detected,
        risk_governor_override_detected,
        committee_decision_mutation_detected,
        trade_signal_detected,
        order_detected,
        broker_order_account_detected,
        owner_opinion_forced_trade_detected,
        guard_status: if violations.is_empty() {
            ChairmanGovernanceSimulationSafetyGuardV3Status::Preserved
        } else {
            ChairmanGovernanceSimulationSafetyGuardV3Status::Violated
        },
        violations,
        paper_only: true,
    }
}

pub fn run_chairman_shadow_governance_simulation(
    governance_ledger: &ChairmanShadowGovernanceLedger,
    member_states: &[MemberStateSnapshot],
    owner_alignment_records: Option<&[OwnerOpinionAlignmentRecord]>,
    batch_result: &BatchCommitteeCycleResult,
    config: &ChairmanShadowGovernanceSimulationRunConfig,
) -> Result<ChairmanShadowGovernanceSimulationRunResult, String> {
    if !config.paper_only {
        return Err("chairman shadow governance simulation run must stay paper_only".to_string());
    }
    let policy = default_chairman_shadow_governance_simulation_policy();
    let simulation_result =
        simulate_chairman_shadow_governance(governance_ledger, member_states, &policy)?;
    let fairness_check = evaluate_chairman_governance_fairness(&simulation_result, &policy);
    let risk_first_check =
        evaluate_chairman_risk_first_governance(&simulation_result, governance_ledger);
    let mut simulation_ledger = if let Some(path) = config.simulation_ledger_input_path.as_ref() {
        if Path::new(path).exists() {
            load_chairman_shadow_governance_simulation_ledger_from_local_json(Path::new(path))?
        } else {
            ChairmanShadowGovernanceSimulationLedger {
                ledger_id: format!("{}-simulation-ledger", config.run_id),
                entries: Vec::new(),
                entry_count: 0,
                latest_entry_id: None,
                paper_only: true,
            }
        }
    } else {
        ChairmanShadowGovernanceSimulationLedger {
            ledger_id: format!("{}-simulation-ledger", config.run_id),
            entries: Vec::new(),
            entry_count: 0,
            latest_entry_id: None,
            paper_only: true,
        }
    };
    let simulation_entry_id = format!("{}-entry-{}", config.run_id, simulation_ledger.entry_count);
    append_chairman_shadow_governance_simulation_entry(
        &mut simulation_ledger,
        ChairmanShadowGovernanceSimulationLedgerEntry {
            entry_id: simulation_entry_id,
            simulation_id: simulation_result.simulation_id.clone(),
            timestamp: None,
            reward_delta_count: simulation_result.reward_delta_count,
            penalty_delta_count: simulation_result.penalty_delta_count,
            voice_increase_count: simulation_result.voice_increase_count,
            voice_decrease_count: simulation_result.voice_decrease_count,
            needs_more_evidence_count: simulation_result.needs_more_evidence_count,
            fairness_status: fairness_check.fairness_status,
            risk_first_status: risk_first_check.risk_first_status,
            paper_only: true,
        },
    );
    let trend_summary = compute_chairman_shadow_governance_trend(&simulation_ledger);
    let explanations = if config.emit_owner_explanations {
        build_chairman_shadow_governance_explanations(&simulation_result, owner_alignment_records)
    } else {
        Vec::new()
    };
    let provisional_safety = evaluate_chairman_governance_simulation_safety_v3(
        &simulation_result,
        batch_result,
        Some(batch_result),
    );
    let readiness_gate = evaluate_chairman_shadow_governance_readiness(
        &simulation_result,
        &fairness_check,
        &risk_first_check,
        &trend_summary,
        &provisional_safety,
    );
    if !config.dry_run {
        if let Some(path) = config.simulation_ledger_output_path.as_ref() {
            save_chairman_shadow_governance_simulation_ledger_to_local_json(
                Path::new(path),
                &simulation_ledger,
            )?;
        }
    }
    let result = ChairmanShadowGovernanceSimulationRunResult {
        run_id: config.run_id.clone(),
        simulation_result: simulation_result.clone(),
        fairness_check: fairness_check.clone(),
        risk_first_check: risk_first_check.clone(),
        simulation_ledger: simulation_ledger.clone(),
        trend_summary: trend_summary.clone(),
        readiness_gate: readiness_gate.clone(),
        explanations: explanations.clone(),
        safety_guard: provisional_safety.clone(),
        run_status: if provisional_safety.guard_status
            == ChairmanGovernanceSimulationSafetyGuardV3Status::Violated
            || fairness_check.fairness_status == ChairmanGovernanceFairnessStatus::Unfair
            || risk_first_check.risk_first_status == ChairmanRiskFirstGovernanceStatus::Violated
        {
            ChairmanShadowGovernanceSimulationRunStatus::Failed
        } else if config.dry_run
            || readiness_gate.readiness_status
                != ChairmanShadowGovernanceReadinessStatus::ShadowGovernanceObservationReady
            || simulation_result.simulation_status
                == ChairmanShadowGovernanceSimulationStatus::SimulatedWithWarnings
        {
            ChairmanShadowGovernanceSimulationRunStatus::PassedWithWarnings
        } else {
            ChairmanShadowGovernanceSimulationRunStatus::Passed
        },
        paper_only: true,
    };
    if let Some(path) = config.simulation_result_output_path.as_ref() {
        validate_local_json_path(
            Path::new(path),
            "chairman shadow governance simulation result path",
        )?;
        write_safe_json(Path::new(path), &result)?;
    }
    Ok(result)
}

pub fn chairman_shadow_governance_simulation_requested_from_flags(
    enabled: bool,
    dry_run: bool,
    simulation_ledger_output_path: Option<&String>,
    simulation_result_output_path: Option<&String>,
    _emit_explanations: bool,
) -> bool {
    enabled
        || !dry_run
        || simulation_ledger_output_path.is_some()
        || simulation_result_output_path.is_some()
}

fn maybe_run_chairman_shadow_governance_simulation_for_batch_result(
    run_id: String,
    enabled: bool,
    dry_run: bool,
    simulation_ledger_output_path: Option<&String>,
    simulation_result_output_path: Option<&String>,
    emit_explanations: bool,
    member_states: &[MemberStateSnapshot],
    batch_result: &mut BatchCommitteeCycleResult,
) -> Result<Option<ChairmanShadowGovernanceSimulationRunResult>, String> {
    if !chairman_shadow_governance_simulation_requested_from_flags(
        enabled,
        dry_run,
        simulation_ledger_output_path,
        simulation_result_output_path,
        emit_explanations,
    ) {
        return Ok(None);
    }
    let governance_ledger = batch_result
        .chairman_shadow_governance_ledger
        .clone()
        .or_else(|| {
            batch_result
                .chairman_shadow_governance_run_result
                .as_ref()
                .map(|run| run.ledger.clone())
        })
        .ok_or_else(|| {
            "chairman shadow governance simulation requires chairman shadow governance ledger"
                .to_string()
        })?;
    let result = run_chairman_shadow_governance_simulation(
        &governance_ledger,
        member_states,
        batch_result.owner_opinion_alignment_records.as_deref(),
        batch_result,
        &ChairmanShadowGovernanceSimulationRunConfig {
            run_id: run_id.clone(),
            enabled,
            governance_ledger_input_path: None,
            simulation_ledger_input_path: None,
            simulation_ledger_output_path: simulation_ledger_output_path.cloned(),
            simulation_result_output_path: simulation_result_output_path.cloned(),
            dry_run,
            emit_owner_explanations: emit_explanations,
            paper_only: true,
        },
    )?;
    batch_result.chairman_shadow_governance_simulation_result =
        Some(result.simulation_result.clone());
    batch_result.chairman_governance_fairness_check = Some(result.fairness_check.clone());
    batch_result.chairman_risk_first_governance_check = Some(result.risk_first_check.clone());
    batch_result.chairman_shadow_governance_simulation_ledger =
        Some(result.simulation_ledger.clone());
    batch_result.chairman_shadow_governance_trend_summary = Some(result.trend_summary.clone());
    batch_result.chairman_shadow_governance_readiness_gate = Some(result.readiness_gate.clone());
    batch_result.chairman_shadow_governance_explanations = Some(result.explanations.clone());
    batch_result.chairman_governance_simulation_safety_guard_v3 = Some(result.safety_guard.clone());
    batch_result.chairman_shadow_governance_simulation_run_result = Some(result.clone());
    Ok(Some(result))
}

fn classify_shadow_governance_member_role(member_id: &str) -> IndependentMemberRole {
    let lowered = member_id.to_ascii_lowercase();
    if lowered.contains("risk") {
        IndependentMemberRole::RiskGuard
    } else if lowered.contains("evidence") {
        IndependentMemberRole::EvidenceRegime
    } else {
        IndependentMemberRole::TrendEntry
    }
}

pub fn init_chairman_shadow_member_state(
    member_state: &MemberStateSnapshot,
) -> ChairmanShadowMemberGovernanceState {
    ChairmanShadowMemberGovernanceState {
        member_id: member_state.member_id.clone(),
        canonical_member_id: Some(member_state.member_id.clone()),
        role: classify_shadow_governance_member_role(&member_state.member_id),
        actual_score_snapshot: member_state.score,
        actual_voice_weight_snapshot: member_state.voice_weight,
        shadow_score: member_state.score,
        shadow_voice_weight: member_state.voice_weight,
        shadow_reward_count: 0,
        shadow_penalty_count: 0,
        shadow_voice_increase_count: 0,
        shadow_voice_decrease_count: 0,
        shadow_promotion_candidate_count: 0,
        shadow_demotion_candidate_count: 0,
        last_update_run_id: None,
        paper_only: true,
    }
}

pub fn normalize_shadow_governance_state_store(store: &mut ChairmanShadowGovernanceStateStore) {
    let mut seen = std::collections::BTreeSet::new();
    store
        .member_states
        .sort_by(|left, right| left.member_id.cmp(&right.member_id));
    store
        .member_states
        .retain(|state| seen.insert(state.member_id.clone()));
    store.member_count = store.member_states.len();
}

fn validate_chairman_shadow_governance_state_store(
    store: &ChairmanShadowGovernanceStateStore,
) -> Result<(), String> {
    if !store.paper_only {
        return Err("chairman shadow governance state store must stay paper_only".to_string());
    }
    reject_unsafe_owner_feedback_string(&store.store_id)?;
    for state in &store.member_states {
        if !state.paper_only {
            return Err(format!(
                "chairman shadow governance state for {} must stay paper_only",
                state.member_id
            ));
        }
        reject_unsafe_owner_feedback_string(&state.member_id)?;
        if let Some(canonical_member_id) = state.canonical_member_id.as_ref() {
            reject_unsafe_owner_feedback_string(canonical_member_id)?;
        }
    }
    Ok(())
}

pub fn initialize_shadow_governance_state_store(
    member_states: &[MemberStateSnapshot],
) -> ChairmanShadowGovernanceStateStore {
    let mut store = ChairmanShadowGovernanceStateStore {
        store_id: "chairman-shadow-governance-state-store".to_string(),
        member_states: member_states
            .iter()
            .map(init_chairman_shadow_member_state)
            .collect(),
        member_count: member_states.len(),
        latest_run_id: None,
        update_count: 0,
        paper_only: true,
    };
    normalize_shadow_governance_state_store(&mut store);
    store
}

pub fn get_shadow_member_state<'a>(
    store: &'a ChairmanShadowGovernanceStateStore,
    member_id: &str,
) -> Option<&'a ChairmanShadowMemberGovernanceState> {
    store
        .member_states
        .iter()
        .find(|state| state.member_id == member_id)
}

pub fn load_chairman_shadow_governance_state_store_from_local_json(
    path: &Path,
) -> Result<ChairmanShadowGovernanceStateStore, String> {
    validate_local_json_path(path, "chairman shadow governance state input path")?;
    let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
    let mut store: ChairmanShadowGovernanceStateStore =
        serde_json::from_str(&text).map_err(|err| err.to_string())?;
    validate_chairman_shadow_governance_state_store(&store)?;
    normalize_shadow_governance_state_store(&mut store);
    validate_chairman_shadow_governance_state_store(&store)?;
    Ok(store)
}

pub fn save_chairman_shadow_governance_state_store_to_local_json(
    path: &Path,
    store: &ChairmanShadowGovernanceStateStore,
) -> Result<(), String> {
    validate_local_json_path(path, "chairman shadow governance state output path")?;
    let mut normalized = store.clone();
    normalize_shadow_governance_state_store(&mut normalized);
    validate_chairman_shadow_governance_state_store(&normalized)?;
    write_safe_json(path, &normalized)
}

pub fn default_chairman_shadow_governance_apply_policy() -> ChairmanShadowGovernanceApplyPolicy {
    ChairmanShadowGovernanceApplyPolicy {
        policy_id: "chairman-shadow-governance-apply-policy".to_string(),
        allow_shadow_score_apply: true,
        allow_shadow_voice_apply: true,
        allow_actual_score_apply: false,
        allow_actual_voice_apply: false,
        allow_promotion_demotion_apply: false,
        allow_risk_governor_override: false,
        max_shadow_score_delta_per_run: 0.08,
        max_shadow_voice_delta_per_run: 0.06,
        min_shadow_voice_weight: 0.05,
        max_shadow_voice_weight: 0.95,
        normalize_shadow_voice_weights: true,
        risk_first_bias: true,
        require_fairness_check: true,
        require_risk_first_check: true,
        paper_only: true,
    }
}

pub fn validate_chairman_shadow_governance_apply_policy(
    policy: &ChairmanShadowGovernanceApplyPolicy,
) -> Result<(), String> {
    if !policy.paper_only {
        return Err("chairman shadow governance apply policy must stay paper_only".to_string());
    }
    if policy.allow_actual_score_apply
        || policy.allow_actual_voice_apply
        || policy.allow_promotion_demotion_apply
        || policy.allow_risk_governor_override
    {
        return Err(
            "chairman shadow governance apply policy must forbid actual mutation".to_string(),
        );
    }
    if !policy.max_shadow_score_delta_per_run.is_finite()
        || !policy.max_shadow_voice_delta_per_run.is_finite()
        || policy.max_shadow_score_delta_per_run < 0.0
        || policy.max_shadow_voice_delta_per_run < 0.0
    {
        return Err(
            "chairman shadow governance apply policy delta bounds must be finite and non-negative"
                .to_string(),
        );
    }
    if !policy.min_shadow_voice_weight.is_finite()
        || !policy.max_shadow_voice_weight.is_finite()
        || policy.min_shadow_voice_weight < 0.0
        || policy.max_shadow_voice_weight > 1.0
        || policy.min_shadow_voice_weight > policy.max_shadow_voice_weight
    {
        return Err(
            "chairman shadow governance apply policy voice bounds must stay within 0..=1"
                .to_string(),
        );
    }
    Ok(())
}

fn normalize_shadow_voice_weights_in_store(
    store: &mut ChairmanShadowGovernanceStateStore,
    policy: &ChairmanShadowGovernanceApplyPolicy,
) {
    let total = store
        .member_states
        .iter()
        .map(|state| state.shadow_voice_weight)
        .sum::<f64>();
    if total <= f64::EPSILON {
        return;
    }
    for state in &mut store.member_states {
        state.shadow_voice_weight = clamp_unit((state.shadow_voice_weight / total).clamp(
            policy.min_shadow_voice_weight,
            policy.max_shadow_voice_weight,
        ));
    }
}

pub fn update_shadow_member_state_with_deltas(
    state: &mut ChairmanShadowMemberGovernanceState,
    score_deltas: &[ChairmanShadowScoreDelta],
    voice_deltas: &[ChairmanShadowVoiceDelta],
    policy: &ChairmanShadowGovernanceApplyPolicy,
) -> (f64, f64) {
    let score_delta = bounded_shadow_delta(
        score_deltas
            .iter()
            .map(|delta| delta.proposed_score_delta)
            .sum::<f64>(),
        policy.max_shadow_score_delta_per_run,
    );
    let voice_delta = bounded_shadow_delta(
        voice_deltas
            .iter()
            .map(|delta| delta.proposed_voice_delta)
            .sum::<f64>(),
        policy.max_shadow_voice_delta_per_run,
    );
    if policy.allow_shadow_score_apply {
        state.shadow_score = clamp_unit(state.shadow_score + score_delta);
    }
    if policy.allow_shadow_voice_apply {
        state.shadow_voice_weight = (state.shadow_voice_weight + voice_delta).clamp(
            policy.min_shadow_voice_weight,
            policy.max_shadow_voice_weight,
        );
    }
    state.shadow_reward_count += score_deltas
        .iter()
        .filter(|delta| delta.delta_kind == ChairmanShadowScoreDeltaKind::Reward)
        .count();
    state.shadow_penalty_count += score_deltas
        .iter()
        .filter(|delta| delta.delta_kind == ChairmanShadowScoreDeltaKind::Penalty)
        .count();
    state.shadow_voice_increase_count += voice_deltas
        .iter()
        .filter(|delta| delta.delta_kind == ChairmanShadowVoiceDeltaKind::Increase)
        .count();
    state.shadow_voice_decrease_count += voice_deltas
        .iter()
        .filter(|delta| delta.delta_kind == ChairmanShadowVoiceDeltaKind::Decrease)
        .count();
    state.shadow_promotion_candidate_count += score_deltas
        .iter()
        .filter(|delta| delta.proposed_score_delta > 0.0)
        .count();
    state.shadow_demotion_candidate_count += score_deltas
        .iter()
        .filter(|delta| delta.proposed_score_delta < 0.0)
        .count();
    (score_delta, voice_delta)
}

pub fn apply_chairman_shadow_governance_deltas(
    store: &mut ChairmanShadowGovernanceStateStore,
    simulation_result: &ChairmanShadowGovernanceSimulationResult,
    fairness_check: &ChairmanGovernanceFairnessCheck,
    risk_first_check: &ChairmanRiskFirstGovernanceCheck,
    policy: &ChairmanShadowGovernanceApplyPolicy,
    run_id: &str,
) -> Result<ChairmanShadowGovernanceApplyResult, String> {
    validate_chairman_shadow_governance_apply_policy(policy)?;
    if policy.require_fairness_check
        && fairness_check.fairness_status == ChairmanGovernanceFairnessStatus::Unfair
    {
        return Ok(ChairmanShadowGovernanceApplyResult {
            run_id: run_id.to_string(),
            input_score_delta_count: simulation_result.score_deltas.len(),
            input_voice_delta_count: simulation_result.voice_deltas.len(),
            applied_shadow_score_delta_count: 0,
            applied_shadow_voice_delta_count: 0,
            skipped_delta_count: simulation_result.score_deltas.len()
                + simulation_result.voice_deltas.len(),
            updated_member_count: 0,
            before_after_standings: Vec::new(),
            fairness_check: fairness_check.clone(),
            risk_first_check: risk_first_check.clone(),
            apply_status: ChairmanShadowGovernanceApplyStatus::Blocked,
            no_actual_score_mutation: true,
            no_actual_voice_mutation: true,
            no_promotion_demotion: true,
            no_risk_governor_override: true,
            paper_only: true,
        });
    }
    if policy.require_risk_first_check
        && risk_first_check.risk_first_status == ChairmanRiskFirstGovernanceStatus::Violated
    {
        return Ok(ChairmanShadowGovernanceApplyResult {
            run_id: run_id.to_string(),
            input_score_delta_count: simulation_result.score_deltas.len(),
            input_voice_delta_count: simulation_result.voice_deltas.len(),
            applied_shadow_score_delta_count: 0,
            applied_shadow_voice_delta_count: 0,
            skipped_delta_count: simulation_result.score_deltas.len()
                + simulation_result.voice_deltas.len(),
            updated_member_count: 0,
            before_after_standings: Vec::new(),
            fairness_check: fairness_check.clone(),
            risk_first_check: risk_first_check.clone(),
            apply_status: ChairmanShadowGovernanceApplyStatus::Blocked,
            no_actual_score_mutation: true,
            no_actual_voice_mutation: true,
            no_promotion_demotion: true,
            no_risk_governor_override: true,
            paper_only: true,
        });
    }
    let mut before_after_standings = Vec::new();
    let mut skipped_delta_count = 0;
    for state in &mut store.member_states {
        let score_deltas = simulation_result
            .score_deltas
            .iter()
            .filter(|delta| delta.member_id == state.member_id)
            .cloned()
            .collect::<Vec<_>>();
        let voice_deltas = simulation_result
            .voice_deltas
            .iter()
            .filter(|delta| delta.member_id == state.member_id)
            .cloned()
            .collect::<Vec<_>>();
        let shadow_score_before = state.shadow_score;
        let shadow_voice_before = state.shadow_voice_weight;
        let (score_delta_applied, voice_delta_applied) =
            update_shadow_member_state_with_deltas(state, &score_deltas, &voice_deltas, policy);
        skipped_delta_count += score_deltas
            .iter()
            .filter(|delta| delta.delta_kind == ChairmanShadowScoreDeltaKind::NeedsMoreEvidence)
            .count()
            + voice_deltas
                .iter()
                .filter(|delta| delta.delta_kind == ChairmanShadowVoiceDeltaKind::NeedsMoreEvidence)
                .count();
        before_after_standings.push(BeforeAfterShadowStanding {
            member_id: state.member_id.clone(),
            actual_score_snapshot: state.actual_score_snapshot,
            actual_voice_weight_snapshot: state.actual_voice_weight_snapshot,
            shadow_score_before,
            shadow_score_after: state.shadow_score,
            shadow_voice_before,
            shadow_voice_after: state.shadow_voice_weight,
            score_delta_applied,
            voice_delta_applied,
            standing_change: if score_deltas
                .iter()
                .any(|delta| delta.delta_kind == ChairmanShadowScoreDeltaKind::NeedsMoreEvidence)
                && voice_deltas
                    .iter()
                    .all(|delta| delta.proposed_voice_delta.abs() <= f64::EPSILON)
            {
                SimulatedMemberStandingStatus::NeedsMoreEvidence
            } else if score_delta_applied > 0.0 || voice_delta_applied > 0.0 {
                SimulatedMemberStandingStatus::ImprovedShadowStanding
            } else if score_delta_applied < 0.0 || voice_delta_applied < 0.0 {
                SimulatedMemberStandingStatus::ReducedShadowStanding
            } else {
                SimulatedMemberStandingStatus::NeutralShadowStanding
            },
            paper_only: true,
        });
        state.last_update_run_id = Some(run_id.to_string());
    }
    if policy.normalize_shadow_voice_weights {
        normalize_shadow_voice_weights_in_store(store, policy);
    }
    for standing in &mut before_after_standings {
        if let Some(state) = store
            .member_states
            .iter()
            .find(|state| state.member_id == standing.member_id)
        {
            standing.shadow_score_after = state.shadow_score;
            standing.shadow_voice_after = state.shadow_voice_weight;
            standing.score_delta_applied =
                standing.shadow_score_after - standing.shadow_score_before;
            standing.voice_delta_applied =
                standing.shadow_voice_after - standing.shadow_voice_before;
            standing.standing_change = if standing.score_delta_applied.abs() <= f64::EPSILON
                && standing.voice_delta_applied.abs() <= f64::EPSILON
                && standing.standing_change == SimulatedMemberStandingStatus::NeedsMoreEvidence
            {
                SimulatedMemberStandingStatus::NeedsMoreEvidence
            } else if standing.score_delta_applied > 0.0 || standing.voice_delta_applied > 0.0 {
                SimulatedMemberStandingStatus::ImprovedShadowStanding
            } else if standing.score_delta_applied < 0.0 || standing.voice_delta_applied < 0.0 {
                SimulatedMemberStandingStatus::ReducedShadowStanding
            } else {
                SimulatedMemberStandingStatus::NeutralShadowStanding
            };
        }
    }
    let applied_shadow_score_delta_count = before_after_standings
        .iter()
        .filter(|standing| standing.score_delta_applied.abs() > f64::EPSILON)
        .count();
    let applied_shadow_voice_delta_count = before_after_standings
        .iter()
        .filter(|standing| standing.voice_delta_applied.abs() > f64::EPSILON)
        .count();
    store.update_count += 1;
    store.latest_run_id = Some(run_id.to_string());
    normalize_shadow_governance_state_store(store);
    let updated_member_count = before_after_standings
        .iter()
        .filter(|standing| {
            standing.score_delta_applied.abs() > f64::EPSILON
                || standing.voice_delta_applied.abs() > f64::EPSILON
        })
        .count();
    Ok(ChairmanShadowGovernanceApplyResult {
        run_id: run_id.to_string(),
        input_score_delta_count: simulation_result.score_deltas.len(),
        input_voice_delta_count: simulation_result.voice_deltas.len(),
        applied_shadow_score_delta_count,
        applied_shadow_voice_delta_count,
        skipped_delta_count,
        updated_member_count,
        before_after_standings,
        fairness_check: fairness_check.clone(),
        risk_first_check: risk_first_check.clone(),
        apply_status: if simulation_result.score_deltas.is_empty()
            && simulation_result.voice_deltas.is_empty()
        {
            ChairmanShadowGovernanceApplyStatus::NoDeltas
        } else if skipped_delta_count > 0 {
            ChairmanShadowGovernanceApplyStatus::AppliedToShadowWithWarnings
        } else {
            ChairmanShadowGovernanceApplyStatus::AppliedToShadow
        },
        no_actual_score_mutation: true,
        no_actual_voice_mutation: true,
        no_promotion_demotion: true,
        no_risk_governor_override: true,
        paper_only: true,
    })
}

pub fn compare_actual_vs_shadow_governance(
    member_states: &[MemberStateSnapshot],
    shadow_store: &ChairmanShadowGovernanceStateStore,
) -> (
    Vec<ActualVsShadowGovernanceComparison>,
    ActualVsShadowGovernanceComparisonSummary,
) {
    let comparisons = member_states
        .iter()
        .map(|actual| {
            let shadow = get_shadow_member_state(shadow_store, &actual.member_id);
            let shadow_score = shadow
                .map(|state| state.shadow_score)
                .unwrap_or(actual.score);
            let shadow_voice_weight = shadow
                .map(|state| state.shadow_voice_weight)
                .unwrap_or(actual.voice_weight);
            let score_gap = shadow_score - actual.score;
            let voice_gap = shadow_voice_weight - actual.voice_weight;
            let comparison_status = if shadow_store.update_count == 0 {
                ActualVsShadowGovernanceComparisonStatus::NeedsMoreHistory
            } else if score_gap.abs() <= 0.01 && voice_gap.abs() <= 0.01 {
                ActualVsShadowGovernanceComparisonStatus::InSync
            } else if score_gap.abs() > 0.12 || voice_gap.abs() > 0.12 {
                ActualVsShadowGovernanceComparisonStatus::Diverged
            } else if score_gap > 0.0 || voice_gap > 0.0 {
                ActualVsShadowGovernanceComparisonStatus::ShadowAhead
            } else {
                ActualVsShadowGovernanceComparisonStatus::ShadowBehind
            };
            ActualVsShadowGovernanceComparison {
                comparison_id: format!("{}-actual-vs-shadow", actual.member_id),
                member_id: actual.member_id.clone(),
                actual_score: actual.score,
                shadow_score,
                score_gap,
                actual_voice_weight: actual.voice_weight,
                shadow_voice_weight,
                voice_gap,
                comparison_status,
                paper_only: true,
            }
        })
        .collect::<Vec<_>>();
    let diverged_count = comparisons
        .iter()
        .filter(|item| item.comparison_status == ActualVsShadowGovernanceComparisonStatus::Diverged)
        .count();
    let shadow_ahead_count = comparisons
        .iter()
        .filter(|item| {
            item.comparison_status == ActualVsShadowGovernanceComparisonStatus::ShadowAhead
        })
        .count();
    let shadow_behind_count = comparisons
        .iter()
        .filter(|item| {
            item.comparison_status == ActualVsShadowGovernanceComparisonStatus::ShadowBehind
        })
        .count();
    let max_score_gap = comparisons
        .iter()
        .map(|item| item.score_gap.abs())
        .fold(0.0, f64::max);
    let max_voice_gap = comparisons
        .iter()
        .map(|item| item.voice_gap.abs())
        .fold(0.0, f64::max);
    let summary = ActualVsShadowGovernanceComparisonSummary {
        summary_id: format!("{}-comparison-summary", shadow_store.store_id),
        member_count: comparisons.len(),
        diverged_count,
        shadow_ahead_count,
        shadow_behind_count,
        max_score_gap,
        max_voice_gap,
        summary_status: if shadow_store.update_count == 0 {
            ActualVsShadowGovernanceSummaryStatus::InsufficientHistory
        } else if diverged_count > 0 {
            ActualVsShadowGovernanceSummaryStatus::Diverged
        } else if shadow_ahead_count > 0 || shadow_behind_count > 0 {
            ActualVsShadowGovernanceSummaryStatus::StableWithWarnings
        } else {
            ActualVsShadowGovernanceSummaryStatus::Stable
        },
        paper_only: true,
    };
    (comparisons, summary)
}

fn shadow_governance_state_ledger_key(
    entry: &ChairmanShadowGovernanceStateLedgerEntry,
) -> (
    String,
    usize,
    usize,
    usize,
    ChairmanGovernanceFairnessStatus,
    ChairmanRiskFirstGovernanceStatus,
    ActualVsShadowGovernanceSummaryStatus,
) {
    (
        entry.run_id.clone(),
        entry.updated_member_count,
        entry.applied_shadow_score_delta_count,
        entry.applied_shadow_voice_delta_count,
        entry.fairness_status,
        entry.risk_first_status,
        entry.actual_vs_shadow_summary_status,
    )
}

pub fn normalize_chairman_shadow_governance_state_ledger(
    ledger: &mut ChairmanShadowGovernanceStateLedger,
) {
    let mut seen = std::collections::BTreeSet::new();
    ledger.entries.sort_by(|left, right| {
        shadow_governance_state_ledger_key(left).cmp(&shadow_governance_state_ledger_key(right))
    });
    ledger
        .entries
        .retain(|entry| seen.insert(shadow_governance_state_ledger_key(entry)));
    ledger.entry_count = ledger.entries.len();
    ledger.latest_entry_id = ledger.entries.last().map(|entry| entry.entry_id.clone());
}

fn validate_chairman_shadow_governance_state_ledger(
    ledger: &ChairmanShadowGovernanceStateLedger,
) -> Result<(), String> {
    if !ledger.paper_only {
        return Err("chairman shadow governance state ledger must stay paper_only".to_string());
    }
    reject_unsafe_owner_feedback_string(&ledger.ledger_id)?;
    for entry in &ledger.entries {
        if !entry.paper_only {
            return Err(format!(
                "chairman shadow governance state ledger entry {} must stay paper_only",
                entry.entry_id
            ));
        }
        reject_unsafe_owner_feedback_string(&entry.entry_id)?;
        reject_unsafe_owner_feedback_string(&entry.run_id)?;
    }
    Ok(())
}

pub fn load_chairman_shadow_governance_state_ledger_from_local_json(
    path: &Path,
) -> Result<ChairmanShadowGovernanceStateLedger, String> {
    validate_local_json_path(path, "chairman shadow governance state ledger path")?;
    let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
    let mut ledger: ChairmanShadowGovernanceStateLedger =
        serde_json::from_str(&text).map_err(|err| err.to_string())?;
    validate_chairman_shadow_governance_state_ledger(&ledger)?;
    normalize_chairman_shadow_governance_state_ledger(&mut ledger);
    validate_chairman_shadow_governance_state_ledger(&ledger)?;
    Ok(ledger)
}

pub fn save_chairman_shadow_governance_state_ledger_to_local_json(
    path: &Path,
    ledger: &ChairmanShadowGovernanceStateLedger,
) -> Result<(), String> {
    validate_local_json_path(path, "chairman shadow governance state ledger path")?;
    let mut normalized = ledger.clone();
    normalize_chairman_shadow_governance_state_ledger(&mut normalized);
    validate_chairman_shadow_governance_state_ledger(&normalized)?;
    write_safe_json(path, &normalized)
}

pub fn append_chairman_shadow_governance_state_ledger_entry(
    ledger: &mut ChairmanShadowGovernanceStateLedger,
    entry: ChairmanShadowGovernanceStateLedgerEntry,
) {
    ledger.entries.push(entry);
    normalize_chairman_shadow_governance_state_ledger(ledger);
}

fn fairness_trend_direction(
    first: ChairmanGovernanceFairnessStatus,
    last: ChairmanGovernanceFairnessStatus,
) -> ObserverTrendDirection {
    let score = |status| match status {
        ChairmanGovernanceFairnessStatus::Fair => 3,
        ChairmanGovernanceFairnessStatus::FairWithWarnings => 2,
        ChairmanGovernanceFairnessStatus::InsufficientData => 1,
        ChairmanGovernanceFairnessStatus::Unfair => 0,
    };
    match score(last).cmp(&score(first)) {
        std::cmp::Ordering::Greater => ObserverTrendDirection::Improving,
        std::cmp::Ordering::Less => ObserverTrendDirection::Worsening,
        std::cmp::Ordering::Equal => ObserverTrendDirection::Stable,
    }
}

fn risk_first_trend_direction(
    first: ChairmanRiskFirstGovernanceStatus,
    last: ChairmanRiskFirstGovernanceStatus,
) -> ObserverTrendDirection {
    let score = |status| match status {
        ChairmanRiskFirstGovernanceStatus::Preserved => 2,
        ChairmanRiskFirstGovernanceStatus::PreservedWithWarnings => 1,
        ChairmanRiskFirstGovernanceStatus::Violated => 0,
    };
    match score(last).cmp(&score(first)) {
        std::cmp::Ordering::Greater => ObserverTrendDirection::Improving,
        std::cmp::Ordering::Less => ObserverTrendDirection::Worsening,
        std::cmp::Ordering::Equal => ObserverTrendDirection::Stable,
    }
}

pub fn compute_chairman_shadow_governance_state_trend(
    ledger: &ChairmanShadowGovernanceStateLedger,
) -> ChairmanShadowGovernanceStateTrend {
    if ledger.entries.len() < 2 {
        return ChairmanShadowGovernanceStateTrend {
            ledger_id: ledger.ledger_id.clone(),
            entry_count: ledger.entry_count,
            shadow_update_trend: ChairmanShadowGovernanceTrendDirection::InsufficientHistory,
            fairness_trend: ObserverTrendDirection::InsufficientHistory,
            risk_first_trend: ObserverTrendDirection::InsufficientHistory,
            trend_status: ChairmanShadowGovernanceTrendStatus::InsufficientHistory,
            paper_only: true,
        };
    }
    let first = &ledger.entries[0];
    let last = ledger.entries.last().expect("non-empty state ledger");
    ChairmanShadowGovernanceStateTrend {
        ledger_id: ledger.ledger_id.clone(),
        entry_count: ledger.entry_count,
        shadow_update_trend: trend_direction_from_counts(
            first.updated_member_count,
            last.updated_member_count,
        ),
        fairness_trend: fairness_trend_direction(first.fairness_status, last.fairness_status),
        risk_first_trend: risk_first_trend_direction(
            first.risk_first_status,
            last.risk_first_status,
        ),
        trend_status: if ledger.entries.len() >= 3 {
            ChairmanShadowGovernanceTrendStatus::Useful
        } else {
            ChairmanShadowGovernanceTrendStatus::UsefulWithWarnings
        },
        paper_only: true,
    }
}

pub fn evaluate_paper_governance_promotion_gate(
    apply_result: &ChairmanShadowGovernanceApplyResult,
    comparison_summary: &ActualVsShadowGovernanceComparisonSummary,
    state_trend: &ChairmanShadowGovernanceStateTrend,
    safety_guard: &ChairmanShadowGovernanceApplySafetyGuard,
) -> PaperGovernancePromotionGate {
    let min_shadow_history_required = 3;
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    if safety_guard.guard_status == ChairmanShadowGovernanceApplySafetyGuardStatus::Violated {
        blockers.push("shadow governance apply safety violated".to_string());
    }
    if apply_result.fairness_check.fairness_status == ChairmanGovernanceFairnessStatus::Unfair {
        blockers.push("shadow governance apply fairness blocked".to_string());
    }
    if apply_result.risk_first_check.risk_first_status
        == ChairmanRiskFirstGovernanceStatus::Violated
    {
        blockers.push("shadow governance apply risk-first blocked".to_string());
    }
    if comparison_summary.summary_status == ActualVsShadowGovernanceSummaryStatus::Diverged {
        blockers.push("actual and shadow governance standings diverged".to_string());
    }
    if state_trend.entry_count < min_shadow_history_required {
        warnings.push("not enough shadow governance history yet".to_string());
    }
    let readiness_status = if safety_guard.guard_status
        == ChairmanShadowGovernanceApplySafetyGuardStatus::Violated
    {
        PaperGovernancePromotionReadinessStatus::BlockedBySafety
    } else if apply_result.fairness_check.fairness_status
        == ChairmanGovernanceFairnessStatus::Unfair
    {
        PaperGovernancePromotionReadinessStatus::BlockedByFairness
    } else if apply_result.risk_first_check.risk_first_status
        == ChairmanRiskFirstGovernanceStatus::Violated
    {
        PaperGovernancePromotionReadinessStatus::BlockedByRiskViolation
    } else if comparison_summary.summary_status == ActualVsShadowGovernanceSummaryStatus::Diverged {
        PaperGovernancePromotionReadinessStatus::NeedsMoreEvidence
    } else if state_trend.entry_count < min_shadow_history_required {
        PaperGovernancePromotionReadinessStatus::NeedsMoreShadowHistory
    } else if apply_result.apply_status
        == ChairmanShadowGovernanceApplyStatus::AppliedToShadowWithWarnings
        || comparison_summary.summary_status
            == ActualVsShadowGovernanceSummaryStatus::StableWithWarnings
    {
        PaperGovernancePromotionReadinessStatus::ReadyForPaperGovernanceTrialWithWarnings
    } else if apply_result.apply_status == ChairmanShadowGovernanceApplyStatus::NoDeltas {
        PaperGovernancePromotionReadinessStatus::NeedsMoreEvidence
    } else {
        PaperGovernancePromotionReadinessStatus::ReadyForPaperGovernanceTrial
    };
    PaperGovernancePromotionGate {
        gate_id: format!("{}-paper-governance-gate", apply_result.run_id),
        shadow_apply_status: apply_result.apply_status,
        fairness_status: apply_result.fairness_check.fairness_status,
        risk_first_status: apply_result.risk_first_check.risk_first_status,
        actual_vs_shadow_status: comparison_summary.summary_status,
        state_trend_status: state_trend.trend_status,
        min_shadow_history_required,
        actual_shadow_mutation_allowed: false,
        ready_for_paper_score_voice_trial: blockers.is_empty()
            && state_trend.entry_count >= min_shadow_history_required
            && comparison_summary.summary_status != ActualVsShadowGovernanceSummaryStatus::Diverged,
        readiness_status,
        blockers,
        warnings,
        paper_only: true,
    }
}

pub fn evaluate_chairman_shadow_governance_apply_safety(
    apply_result: &ChairmanShadowGovernanceApplyResult,
    actual_member_states_before: &[MemberStateSnapshot],
    actual_member_states_after: Option<&[MemberStateSnapshot]>,
    batch_before: &BatchCommitteeCycleResult,
    batch_after: Option<&BatchCommitteeCycleResult>,
    config: &ChairmanShadowGovernanceStateRunConfig,
    shadow_store_written_when_dry_run: bool,
) -> ChairmanShadowGovernanceApplySafetyGuard {
    let after_states = actual_member_states_after.unwrap_or(actual_member_states_before);
    let after_batch = batch_after.unwrap_or(batch_before);
    let actual_score_snapshot = |states: &[MemberStateSnapshot]| {
        states
            .iter()
            .map(|state| (state.member_id.clone(), state.score))
            .collect::<std::collections::BTreeMap<_, _>>()
    };
    let actual_voice_snapshot = |states: &[MemberStateSnapshot]| {
        states
            .iter()
            .map(|state| (state.member_id.clone(), state.voice_weight))
            .collect::<std::collections::BTreeMap<_, _>>()
    };
    let promotion_snapshot = |updates: &[MemberScoreUpdate]| {
        updates
            .iter()
            .filter(|update| update.promoted)
            .map(|update| update.member_id.clone())
            .collect::<std::collections::BTreeSet<_>>()
    };
    let demotion_snapshot = |updates: &[MemberScoreUpdate]| {
        updates
            .iter()
            .filter(|update| update.demoted)
            .map(|update| update.member_id.clone())
            .collect::<std::collections::BTreeSet<_>>()
    };
    let risk_governor_snapshot = |decisions: &[ChairmanDecision]| {
        decisions
            .iter()
            .map(|decision| (decision.decision_id.clone(), decision.risk_governor_status))
            .collect::<std::collections::BTreeMap<_, _>>()
    };
    let actual_score_mutation_detected =
        actual_score_snapshot(actual_member_states_before) != actual_score_snapshot(after_states);
    let actual_voice_mutation_detected =
        actual_voice_snapshot(actual_member_states_before) != actual_voice_snapshot(after_states);
    let promotion_execution_detected = promotion_snapshot(&batch_before.score_updates)
        != promotion_snapshot(&after_batch.score_updates);
    let demotion_execution_detected = demotion_snapshot(&batch_before.score_updates)
        != demotion_snapshot(&after_batch.score_updates);
    let risk_governor_override_detected = risk_governor_snapshot(&batch_before.chairman_decisions)
        != risk_governor_snapshot(&after_batch.chairman_decisions);
    let committee_decision_mutation_detected =
        batch_before.committee_sessions != after_batch.committee_sessions;
    let markers = vec![
        format!("{}-shadow-governance-apply", apply_result.run_id),
        format!("{}-trade-signal", apply_result.run_id),
        format!("{}-order", apply_result.run_id),
    ];
    let trade_signal_detected =
        value_contains_debug_marker(&after_batch.committee_sessions, &markers);
    let order_detected = value_contains_debug_marker(&after_batch.event_queue, &markers);
    let broker_order_account_detected = value_contains_debug_marker(
        &after_batch.event_queue,
        &[
            "broker".to_string(),
            "order".to_string(),
            "account".to_string(),
        ],
    );
    let shadow_store_written_when_dry_run = config.dry_run && shadow_store_written_when_dry_run;
    let mut violations = Vec::new();
    if actual_score_mutation_detected {
        violations.push("shadow governance apply mutated actual score".to_string());
    }
    if actual_voice_mutation_detected {
        violations.push("shadow governance apply mutated actual voice".to_string());
    }
    if promotion_execution_detected {
        violations.push("shadow governance apply executed promotion".to_string());
    }
    if demotion_execution_detected {
        violations.push("shadow governance apply executed demotion".to_string());
    }
    if risk_governor_override_detected {
        violations.push("shadow governance apply overrode Risk Governor".to_string());
    }
    if committee_decision_mutation_detected {
        violations.push("shadow governance apply changed committee decision".to_string());
    }
    if trade_signal_detected {
        violations.push("shadow governance apply created trade signal".to_string());
    }
    if order_detected {
        violations.push("shadow governance apply created order".to_string());
    }
    if broker_order_account_detected {
        violations.push("shadow governance apply touched broker/order/account".to_string());
    }
    if shadow_store_written_when_dry_run {
        violations.push("shadow governance apply wrote shadow store during dry-run".to_string());
    }
    ChairmanShadowGovernanceApplySafetyGuard {
        actual_score_mutation_detected,
        actual_voice_mutation_detected,
        promotion_execution_detected,
        demotion_execution_detected,
        risk_governor_override_detected,
        committee_decision_mutation_detected,
        trade_signal_detected,
        order_detected,
        broker_order_account_detected,
        shadow_store_written_when_dry_run,
        guard_status: if violations.is_empty() {
            ChairmanShadowGovernanceApplySafetyGuardStatus::Preserved
        } else {
            ChairmanShadowGovernanceApplySafetyGuardStatus::Violated
        },
        violations,
        paper_only: true,
    }
}

pub fn build_owner_shadow_governance_state_summary(
    apply_result: &ChairmanShadowGovernanceApplyResult,
    comparison_summary: &ActualVsShadowGovernanceComparisonSummary,
    promotion_gate: &PaperGovernancePromotionGate,
) -> OwnerShadowGovernanceStateSummary {
    OwnerShadowGovernanceStateSummary {
        summary_id: format!("{}-owner-shadow-governance-summary", apply_result.run_id),
        updated_member_count: apply_result.updated_member_count,
        applied_shadow_score_delta_count: apply_result.applied_shadow_score_delta_count,
        applied_shadow_voice_delta_count: apply_result.applied_shadow_voice_delta_count,
        fairness_status: apply_result.fairness_check.fairness_status,
        risk_first_status: apply_result.risk_first_check.risk_first_status,
        actual_vs_shadow_status: comparison_summary.summary_status,
        promotion_gate_status: promotion_gate.readiness_status,
        message: "Chairman applied deltas only to shadow governance state. Actual score and voice weight did not change. No member was promoted or demoted. Risk Governor was not overridden."
            .to_string(),
        shadow_only: true,
        no_actual_score_mutation: true,
        no_actual_voice_mutation: true,
        no_promotion_demotion: true,
        no_risk_override: true,
        not_trade_signal: true,
        paper_only: true,
    }
}

pub fn run_chairman_shadow_governance_state_update(
    simulation_result: &ChairmanShadowGovernanceSimulationResult,
    actual_member_states: &[MemberStateSnapshot],
    batch_result: &BatchCommitteeCycleResult,
    config: &ChairmanShadowGovernanceStateRunConfig,
) -> Result<ChairmanShadowGovernanceStateRunResult, String> {
    if !config.paper_only {
        return Err("chairman shadow governance state run must stay paper_only".to_string());
    }
    let policy = default_chairman_shadow_governance_apply_policy();
    let mut shadow_store = if let Some(path) = config.shadow_state_input_path.as_ref() {
        if Path::new(path).exists() {
            load_chairman_shadow_governance_state_store_from_local_json(Path::new(path))?
        } else {
            initialize_shadow_governance_state_store(actual_member_states)
        }
    } else {
        initialize_shadow_governance_state_store(actual_member_states)
    };
    let shadow_store_before = Some(shadow_store.clone());
    let fairness_check = batch_result
        .chairman_governance_fairness_check
        .clone()
        .unwrap_or_else(|| {
            evaluate_chairman_governance_fairness(
                simulation_result,
                &default_chairman_shadow_governance_simulation_policy(),
            )
        });
    let risk_first_check = batch_result
        .chairman_risk_first_governance_check
        .clone()
        .unwrap_or(ChairmanRiskFirstGovernanceCheck {
            check_id: format!("{}-state-risk-first", config.run_id),
            risk_guard_rewarded_count: 0,
            risky_overconfidence_penalized_count: 0,
            risk_veto_alignment_count: 0,
            risk_override_attempt_detected: false,
            reckless_reward_detected: false,
            risk_first_status: ChairmanRiskFirstGovernanceStatus::PreservedWithWarnings,
            warnings: vec![
                "simulation risk-first check missing; state apply used warning-safe fallback"
                    .to_string(),
            ],
            paper_only: true,
        });
    let apply_result = if config.apply_shadow_deltas {
        apply_chairman_shadow_governance_deltas(
            &mut shadow_store,
            simulation_result,
            &fairness_check,
            &risk_first_check,
            &policy,
            &config.run_id,
        )?
    } else {
        ChairmanShadowGovernanceApplyResult {
            run_id: config.run_id.clone(),
            input_score_delta_count: simulation_result.score_deltas.len(),
            input_voice_delta_count: simulation_result.voice_deltas.len(),
            applied_shadow_score_delta_count: 0,
            applied_shadow_voice_delta_count: 0,
            skipped_delta_count: simulation_result.score_deltas.len()
                + simulation_result.voice_deltas.len(),
            updated_member_count: 0,
            before_after_standings: Vec::new(),
            fairness_check: fairness_check.clone(),
            risk_first_check: risk_first_check.clone(),
            apply_status: ChairmanShadowGovernanceApplyStatus::NoDeltas,
            no_actual_score_mutation: true,
            no_actual_voice_mutation: true,
            no_promotion_demotion: true,
            no_risk_governor_override: true,
            paper_only: true,
        }
    };
    let (_comparisons, comparison_summary) =
        compare_actual_vs_shadow_governance(actual_member_states, &shadow_store);
    let mut state_ledger = if let Some(path) = config.shadow_state_ledger_path.as_ref() {
        if Path::new(path).exists() {
            load_chairman_shadow_governance_state_ledger_from_local_json(Path::new(path))?
        } else {
            ChairmanShadowGovernanceStateLedger {
                ledger_id: format!("{}-shadow-state-ledger", config.run_id),
                entries: Vec::new(),
                entry_count: 0,
                latest_entry_id: None,
                paper_only: true,
            }
        }
    } else {
        ChairmanShadowGovernanceStateLedger {
            ledger_id: format!("{}-shadow-state-ledger", config.run_id),
            entries: Vec::new(),
            entry_count: 0,
            latest_entry_id: None,
            paper_only: true,
        }
    };
    let state_entry_id = format!("{}-state-entry-{}", config.run_id, state_ledger.entry_count);
    append_chairman_shadow_governance_state_ledger_entry(
        &mut state_ledger,
        ChairmanShadowGovernanceStateLedgerEntry {
            entry_id: state_entry_id,
            run_id: config.run_id.clone(),
            updated_member_count: apply_result.updated_member_count,
            applied_shadow_score_delta_count: apply_result.applied_shadow_score_delta_count,
            applied_shadow_voice_delta_count: apply_result.applied_shadow_voice_delta_count,
            fairness_status: apply_result.fairness_check.fairness_status,
            risk_first_status: apply_result.risk_first_check.risk_first_status,
            actual_vs_shadow_summary_status: comparison_summary.summary_status,
            paper_only: true,
        },
    );
    let state_trend = compute_chairman_shadow_governance_state_trend(&state_ledger);
    let shadow_store_path = config
        .shadow_state_output_path
        .as_ref()
        .map(Path::new)
        .map(Path::to_path_buf);
    let ledger_path = config
        .shadow_state_ledger_path
        .as_ref()
        .map(Path::new)
        .map(Path::to_path_buf);
    let shadow_store_written_when_dry_run = false;
    if !config.dry_run {
        if let Some(path) = shadow_store_path.as_ref() {
            save_chairman_shadow_governance_state_store_to_local_json(path, &shadow_store)?;
        }
        if let Some(path) = ledger_path.as_ref() {
            save_chairman_shadow_governance_state_ledger_to_local_json(path, &state_ledger)?;
        }
    }
    let safety_guard = evaluate_chairman_shadow_governance_apply_safety(
        &apply_result,
        actual_member_states,
        Some(actual_member_states),
        batch_result,
        Some(batch_result),
        config,
        shadow_store_written_when_dry_run,
    );
    let paper_governance_promotion_gate = evaluate_paper_governance_promotion_gate(
        &apply_result,
        &comparison_summary,
        &state_trend,
        &safety_guard,
    );
    let owner_summary = config.emit_owner_summary.then(|| {
        build_owner_shadow_governance_state_summary(
            &apply_result,
            &comparison_summary,
            &paper_governance_promotion_gate,
        )
    });
    Ok(ChairmanShadowGovernanceStateRunResult {
        run_id: config.run_id.clone(),
        shadow_store_before,
        apply_result: apply_result.clone(),
        shadow_store_after: Some(shadow_store.clone()),
        actual_vs_shadow_summary: comparison_summary.clone(),
        state_ledger: state_ledger.clone(),
        state_trend: state_trend.clone(),
        paper_governance_promotion_gate: paper_governance_promotion_gate.clone(),
        safety_guard: safety_guard.clone(),
        owner_summary,
        run_status: if safety_guard.guard_status
            == ChairmanShadowGovernanceApplySafetyGuardStatus::Violated
            || paper_governance_promotion_gate.readiness_status
                == PaperGovernancePromotionReadinessStatus::BlockedByFairness
            || paper_governance_promotion_gate.readiness_status
                == PaperGovernancePromotionReadinessStatus::BlockedByRiskViolation
            || paper_governance_promotion_gate.readiness_status
                == PaperGovernancePromotionReadinessStatus::BlockedBySafety
        {
            ChairmanShadowGovernanceStateRunStatus::Failed
        } else if config.dry_run
            || apply_result.apply_status
                == ChairmanShadowGovernanceApplyStatus::AppliedToShadowWithWarnings
            || !paper_governance_promotion_gate.warnings.is_empty()
        {
            ChairmanShadowGovernanceStateRunStatus::PassedWithWarnings
        } else {
            ChairmanShadowGovernanceStateRunStatus::Passed
        },
        paper_only: true,
    })
}

fn shadow_governance_history_snapshot_key(
    snapshot: &ChairmanShadowGovernanceHistorySnapshot,
) -> String {
    snapshot.run_id.clone()
}

pub fn normalize_shadow_governance_history_store(store: &mut ChairmanShadowGovernanceHistoryStore) {
    let mut seen = std::collections::BTreeSet::new();
    store.snapshots.sort_by(|left, right| {
        shadow_governance_history_snapshot_key(left)
            .cmp(&shadow_governance_history_snapshot_key(right))
    });
    store
        .snapshots
        .retain(|snapshot| seen.insert(shadow_governance_history_snapshot_key(snapshot)));
    store.snapshot_count = store.snapshots.len();
    store.latest_snapshot_id = store
        .snapshots
        .last()
        .map(|snapshot| snapshot.snapshot_id.clone());
}

fn validate_chairman_shadow_governance_history_store(
    store: &ChairmanShadowGovernanceHistoryStore,
) -> Result<(), String> {
    if !store.paper_only {
        return Err("chairman shadow governance history store must stay paper_only".to_string());
    }
    reject_unsafe_owner_feedback_string(&store.store_id)?;
    for snapshot in &store.snapshots {
        if !snapshot.paper_only {
            return Err(format!(
                "chairman shadow governance history snapshot {} must stay paper_only",
                snapshot.snapshot_id
            ));
        }
        reject_unsafe_owner_feedback_string(&snapshot.snapshot_id)?;
        reject_unsafe_owner_feedback_string(&snapshot.run_id)?;
        for state in &snapshot.member_states {
            if !state.paper_only {
                return Err(format!(
                    "chairman shadow governance history member state {} must stay paper_only",
                    state.member_id
                ));
            }
            reject_unsafe_owner_feedback_string(&state.member_id)?;
            if let Some(canonical_member_id) = state.canonical_member_id.as_ref() {
                reject_unsafe_owner_feedback_string(canonical_member_id)?;
            }
        }
    }
    Ok(())
}

pub fn latest_shadow_governance_history_snapshot(
    store: &ChairmanShadowGovernanceHistoryStore,
) -> Option<&ChairmanShadowGovernanceHistorySnapshot> {
    store.snapshots.last()
}

pub fn load_chairman_shadow_governance_history_store_from_local_json(
    path: &Path,
) -> Result<ChairmanShadowGovernanceHistoryStore, String> {
    validate_local_json_path(path, "chairman shadow governance history input path")?;
    let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
    let mut store: ChairmanShadowGovernanceHistoryStore =
        serde_json::from_str(&text).map_err(|err| err.to_string())?;
    validate_chairman_shadow_governance_history_store(&store)?;
    normalize_shadow_governance_history_store(&mut store);
    validate_chairman_shadow_governance_history_store(&store)?;
    Ok(store)
}

pub fn save_chairman_shadow_governance_history_store_to_local_json(
    path: &Path,
    store: &ChairmanShadowGovernanceHistoryStore,
) -> Result<(), String> {
    validate_local_json_path(path, "chairman shadow governance history output path")?;
    let mut normalized = store.clone();
    normalize_shadow_governance_history_store(&mut normalized);
    validate_chairman_shadow_governance_history_store(&normalized)?;
    write_safe_json(path, &normalized)
}

pub fn append_chairman_shadow_governance_history_snapshot(
    store: &mut ChairmanShadowGovernanceHistoryStore,
    snapshot: ChairmanShadowGovernanceHistorySnapshot,
) {
    store.snapshots.push(snapshot);
    normalize_shadow_governance_history_store(store);
}

fn build_chairman_shadow_governance_history_snapshot(
    current_state_result: &ChairmanShadowGovernanceStateRunResult,
) -> Result<ChairmanShadowGovernanceHistorySnapshot, String> {
    let member_states = current_state_result
        .shadow_store_after
        .as_ref()
        .or(current_state_result.shadow_store_before.as_ref())
        .map(|store| store.member_states.clone())
        .ok_or_else(|| {
            "chairman shadow governance history snapshot requires shadow store".to_string()
        })?;
    Ok(ChairmanShadowGovernanceHistorySnapshot {
        snapshot_id: format!("{}-history-snapshot", current_state_result.run_id),
        run_id: current_state_result.run_id.clone(),
        timestamp: None,
        member_states,
        actual_vs_shadow_summary: current_state_result.actual_vs_shadow_summary.clone(),
        fairness_status: current_state_result
            .apply_result
            .fairness_check
            .fairness_status,
        risk_first_status: current_state_result
            .apply_result
            .risk_first_check
            .risk_first_status,
        safety_status: current_state_result.safety_guard.guard_status,
        paper_governance_gate_status: current_state_result
            .paper_governance_promotion_gate
            .readiness_status,
        paper_only: true,
    })
}

pub fn accumulate_chairman_shadow_governance_history(
    current_state_result: &ChairmanShadowGovernanceStateRunResult,
    history_store: &mut ChairmanShadowGovernanceHistoryStore,
    config: &ChairmanShadowGovernanceHistoryAccumulationConfig,
) -> Result<ChairmanShadowGovernanceHistoryAccumulationResult, String> {
    if !config.paper_only {
        return Err(
            "chairman shadow governance history accumulation must stay paper_only".to_string(),
        );
    }
    if config.max_snapshots == 0 || config.min_snapshots_for_trial_gate == 0 {
        return Err(
            "chairman shadow governance history accumulation thresholds must be positive"
                .to_string(),
        );
    }
    if config.max_snapshots < config.min_snapshots_for_trial_gate {
        return Err(
            "chairman shadow governance history max_snapshots must cover the trial gate minimum"
                .to_string(),
        );
    }
    validate_chairman_shadow_governance_history_store(history_store)?;
    let previous_snapshot_count = history_store.snapshot_count;
    let snapshot = build_chairman_shadow_governance_history_snapshot(current_state_result)?;
    let already_exists = history_store
        .snapshots
        .iter()
        .any(|existing| existing.snapshot_id == snapshot.snapshot_id);
    let mut warnings = Vec::new();
    if already_exists {
        return Ok(ChairmanShadowGovernanceHistoryAccumulationResult {
            run_id: config.run_id.clone(),
            previous_snapshot_count,
            appended_snapshot_count: 0,
            new_snapshot_count: history_store.snapshot_count,
            latest_snapshot_id: history_store.latest_snapshot_id.clone(),
            wrote_history_store: false,
            accumulation_status: ChairmanShadowGovernanceHistoryAccumulationStatus::NoNewSnapshot,
            warnings,
            paper_only: true,
        });
    }
    append_chairman_shadow_governance_history_snapshot(history_store, snapshot);
    if history_store.snapshots.len() > config.max_snapshots {
        let retain_from = history_store.snapshots.len() - config.max_snapshots;
        history_store.snapshots = history_store.snapshots.split_off(retain_from);
        warnings.push(format!(
            "history store trimmed to max_snapshots={}",
            config.max_snapshots
        ));
    }
    normalize_shadow_governance_history_store(history_store);
    validate_chairman_shadow_governance_history_store(history_store)?;
    Ok(ChairmanShadowGovernanceHistoryAccumulationResult {
        run_id: config.run_id.clone(),
        previous_snapshot_count,
        appended_snapshot_count: 1,
        new_snapshot_count: history_store.snapshot_count,
        latest_snapshot_id: history_store.latest_snapshot_id.clone(),
        wrote_history_store: false,
        accumulation_status: if warnings.is_empty() {
            ChairmanShadowGovernanceHistoryAccumulationStatus::Accumulated
        } else {
            ChairmanShadowGovernanceHistoryAccumulationStatus::AccumulatedWithWarnings
        },
        warnings,
        paper_only: true,
    })
}

fn divergence_record(
    member_id: &str,
    divergence_type: ActualVsShadowDivergenceType,
    score_gap: f64,
    voice_gap: f64,
    severity: ActualVsShadowDivergenceSeverity,
    expected: bool,
    unsafe_divergence: bool,
    reason: &str,
    recommended_action: ActualVsShadowRecommendedAction,
) -> ActualVsShadowDivergenceRecord {
    ActualVsShadowDivergenceRecord {
        divergence_id: format!("{member_id}-{divergence_type:?}"),
        member_id: member_id.to_string(),
        divergence_type,
        score_gap,
        voice_gap,
        severity,
        expected,
        unsafe_divergence,
        reason: reason.to_string(),
        recommended_action,
        paper_only: true,
    }
}

pub fn default_paper_governance_trial_criteria() -> PaperGovernanceTrialCriteria {
    PaperGovernanceTrialCriteria {
        criteria_id: "paper-governance-trial-criteria".to_string(),
        min_history_snapshots:
            default_chairman_shadow_governance_history_min_snapshots_for_trial_gate(),
        require_fairness_status: ChairmanGovernanceFairnessStatus::FairWithWarnings,
        require_risk_first_status: ChairmanRiskFirstGovernanceStatus::PreservedWithWarnings,
        require_safety_status: ChairmanShadowGovernanceApplySafetyGuardStatus::Preserved,
        max_allowed_high_severity_divergence: 0,
        max_allowed_voice_concentration: 0.65,
        max_allowed_voice_volatility: 0.12,
        require_no_risk_governor_override: true,
        require_no_actual_score_mutation: true,
        require_no_actual_voice_mutation: true,
        require_no_committee_decision_mutation: true,
        paper_only: true,
    }
}

pub fn diagnose_actual_vs_shadow_divergence(
    comparison_summary: &ActualVsShadowGovernanceComparisonSummary,
    shadow_store: &ChairmanShadowGovernanceStateStore,
    history_store: &ChairmanShadowGovernanceHistoryStore,
    criteria: &PaperGovernanceTrialCriteria,
) -> ActualVsShadowDivergenceDiagnosis {
    let mut records = Vec::new();
    if history_store.snapshot_count < 2 {
        records.push(divergence_record(
            "history",
            ActualVsShadowDivergenceType::InsufficientHistory,
            comparison_summary.max_score_gap,
            comparison_summary.max_voice_gap,
            ActualVsShadowDivergenceSeverity::Low,
            true,
            false,
            "Need more shadow governance history before diagnosing divergence.",
            ActualVsShadowRecommendedAction::KeepAccumulatingHistory,
        ));
        return ActualVsShadowDivergenceDiagnosis {
            diagnosis_id: format!("{}-divergence-diagnosis", comparison_summary.summary_id),
            record_count: 1,
            high_severity_count: 0,
            unsafe_count: 0,
            expected_count: 1,
            divergence_records: records,
            diagnosis_status: ActualVsShadowDivergenceDiagnosisStatus::NeedsMoreHistory,
            paper_only: true,
        };
    }
    for state in &shadow_store.member_states {
        let score_gap = state.shadow_score - state.actual_score_snapshot;
        let voice_gap = state.shadow_voice_weight - state.actual_voice_weight_snapshot;
        if score_gap.abs() > 0.05 {
            let unsafe_divergence = score_gap.abs() > 0.2;
            records.push(divergence_record(
                &state.member_id,
                ActualVsShadowDivergenceType::ScoreDrift,
                score_gap,
                voice_gap,
                if score_gap.abs() > 0.12 {
                    ActualVsShadowDivergenceSeverity::High
                } else {
                    ActualVsShadowDivergenceSeverity::Medium
                },
                !unsafe_divergence,
                unsafe_divergence,
                "Shadow score drift reflects paper-only learning pressure while actual score stays frozen.",
                if unsafe_divergence {
                    ActualVsShadowRecommendedAction::BlockPaperGovernanceTrial
                } else {
                    ActualVsShadowRecommendedAction::KeepAccumulatingHistory
                },
            ));
        }
        if voice_gap.abs() > 0.05 {
            let unsafe_divergence = voice_gap.abs() > criteria.max_allowed_voice_volatility;
            records.push(divergence_record(
                &state.member_id,
                ActualVsShadowDivergenceType::VoiceDrift,
                score_gap,
                voice_gap,
                if unsafe_divergence {
                    ActualVsShadowDivergenceSeverity::High
                } else {
                    ActualVsShadowDivergenceSeverity::Medium
                },
                !unsafe_divergence,
                unsafe_divergence,
                "Shadow voice drift tracks chairman paper-only weighting while actual voice remains fixed.",
                if unsafe_divergence {
                    ActualVsShadowRecommendedAction::ReduceShadowDeltaPolicy
                } else {
                    ActualVsShadowRecommendedAction::KeepAccumulatingHistory
                },
            ));
        }
        if state.shadow_reward_count > state.shadow_penalty_count + 2 && score_gap > 0.08 {
            records.push(divergence_record(
                &state.member_id,
                ActualVsShadowDivergenceType::ShadowOverReward,
                score_gap,
                voice_gap,
                ActualVsShadowDivergenceSeverity::Medium,
                false,
                false,
                "Shadow reward counts are accumulating faster than actual score can converge.",
                ActualVsShadowRecommendedAction::IncreaseFairnessConstraint,
            ));
        }
        if state.shadow_penalty_count > state.shadow_reward_count + 2 && score_gap < -0.08 {
            records.push(divergence_record(
                &state.member_id,
                ActualVsShadowDivergenceType::ShadowOverPenalty,
                score_gap,
                voice_gap,
                ActualVsShadowDivergenceSeverity::Medium,
                false,
                false,
                "Shadow penalty counts are accumulating faster than actual governance can respond.",
                ActualVsShadowRecommendedAction::RequireMoreEvidence,
            ));
        }
        if state.role == IndependentMemberRole::RiskGuard
            && state.shadow_voice_weight > criteria.max_allowed_voice_concentration
        {
            records.push(divergence_record(
                &state.member_id,
                ActualVsShadowDivergenceType::RiskGuardOverDominance,
                score_gap,
                voice_gap,
                ActualVsShadowDivergenceSeverity::High,
                false,
                true,
                "RiskGuard shadow voice concentration is dominating beyond the allowed paper-only threshold.",
                ActualVsShadowRecommendedAction::ReviewRiskFirstPolicy,
            ));
        }
        if state.role == IndependentMemberRole::TrendEntry
            && state.shadow_penalty_count > state.shadow_reward_count + 1
            && score_gap < -0.05
        {
            records.push(divergence_record(
                &state.member_id,
                ActualVsShadowDivergenceType::TrendEntrySuppression,
                score_gap,
                voice_gap,
                ActualVsShadowDivergenceSeverity::Medium,
                false,
                false,
                "TrendEntry shadow standing is being suppressed relative to actual standing.",
                ActualVsShadowRecommendedAction::RequireMoreEvidence,
            ));
        }
        if state.role == IndependentMemberRole::EvidenceRegime
            && voice_gap < -0.05
            && state.shadow_voice_weight + 0.05 < state.actual_voice_weight_snapshot
        {
            records.push(divergence_record(
                &state.member_id,
                ActualVsShadowDivergenceType::EvidenceRegimeUnderweight,
                score_gap,
                voice_gap,
                ActualVsShadowDivergenceSeverity::Medium,
                false,
                false,
                "EvidenceRegime shadow voice is underweight relative to the actual baseline.",
                ActualVsShadowRecommendedAction::RequireMoreEvidence,
            ));
        }
        if score_gap.abs() <= 0.05 && voice_gap.abs() <= 0.05 {
            records.push(divergence_record(
                &state.member_id,
                ActualVsShadowDivergenceType::ExpectedShadowLearning,
                score_gap,
                voice_gap,
                ActualVsShadowDivergenceSeverity::Low,
                true,
                false,
                "Mild shadow divergence is expected while actual governance stays frozen.",
                ActualVsShadowRecommendedAction::KeepAccumulatingHistory,
            ));
        }
    }
    let high_severity_count = records
        .iter()
        .filter(|record| record.severity == ActualVsShadowDivergenceSeverity::High)
        .count();
    let record_count = records.len();
    let unsafe_count = records
        .iter()
        .filter(|record| record.unsafe_divergence)
        .count();
    let expected_count = records.iter().filter(|record| record.expected).count();
    let diagnosis_status = if unsafe_count > 0 {
        ActualVsShadowDivergenceDiagnosisStatus::UnsafeDivergence
    } else if high_severity_count > criteria.max_allowed_high_severity_divergence {
        ActualVsShadowDivergenceDiagnosisStatus::Blocked
    } else if comparison_summary.summary_status == ActualVsShadowGovernanceSummaryStatus::Stable
        && expected_count == records.len()
    {
        ActualVsShadowDivergenceDiagnosisStatus::AcceptableDivergence
    } else {
        ActualVsShadowDivergenceDiagnosisStatus::AcceptableWithWarnings
    };
    ActualVsShadowDivergenceDiagnosis {
        diagnosis_id: format!("{}-divergence-diagnosis", comparison_summary.summary_id),
        record_count,
        high_severity_count,
        unsafe_count,
        expected_count,
        divergence_records: records,
        diagnosis_status,
        paper_only: true,
    }
}

pub fn compute_shadow_governance_history_stability(
    history_store: &ChairmanShadowGovernanceHistoryStore,
) -> ChairmanShadowGovernanceHistoryStabilityMetrics {
    if history_store.snapshot_count < 2 {
        return ChairmanShadowGovernanceHistoryStabilityMetrics {
            metrics_id: format!("{}-stability", history_store.store_id),
            snapshot_count: history_store.snapshot_count,
            score_volatility_by_member: BTreeMap::new(),
            voice_volatility_by_member: BTreeMap::new(),
            max_score_swing: 0.0,
            max_voice_swing: 0.0,
            reward_penalty_balance: 0.0,
            voice_change_balance: 0.0,
            stability_status: ShadowGovernanceHistoryStabilityStatus::InsufficientHistory,
            paper_only: true,
        };
    }
    let mut score_series: BTreeMap<String, Vec<f64>> = BTreeMap::new();
    let mut voice_series: BTreeMap<String, Vec<f64>> = BTreeMap::new();
    let mut reward_total = 0usize;
    let mut penalty_total = 0usize;
    let mut voice_up_total = 0usize;
    let mut voice_down_total = 0usize;
    for snapshot in &history_store.snapshots {
        for state in &snapshot.member_states {
            score_series
                .entry(state.member_id.clone())
                .or_default()
                .push(state.shadow_score);
            voice_series
                .entry(state.member_id.clone())
                .or_default()
                .push(state.shadow_voice_weight);
            reward_total += state.shadow_reward_count;
            penalty_total += state.shadow_penalty_count;
            voice_up_total += state.shadow_voice_increase_count;
            voice_down_total += state.shadow_voice_decrease_count;
        }
    }
    let score_volatility_by_member = score_series
        .into_iter()
        .map(|(member_id, series)| {
            let min = series.iter().copied().fold(f64::INFINITY, f64::min);
            let max = series.iter().copied().fold(f64::NEG_INFINITY, f64::max);
            (member_id, (max - min).max(0.0))
        })
        .collect::<BTreeMap<_, _>>();
    let voice_volatility_by_member = voice_series
        .into_iter()
        .map(|(member_id, series)| {
            let min = series.iter().copied().fold(f64::INFINITY, f64::min);
            let max = series.iter().copied().fold(f64::NEG_INFINITY, f64::max);
            (member_id, (max - min).max(0.0))
        })
        .collect::<BTreeMap<_, _>>();
    let max_score_swing = score_volatility_by_member
        .values()
        .copied()
        .fold(0.0, f64::max);
    let max_voice_swing = voice_volatility_by_member
        .values()
        .copied()
        .fold(0.0, f64::max);
    let reward_penalty_balance = (reward_total as f64 - penalty_total as f64).abs()
        / (reward_total + penalty_total).max(1) as f64;
    let voice_change_balance = (voice_up_total as f64 - voice_down_total as f64).abs()
        / (voice_up_total + voice_down_total).max(1) as f64;
    ChairmanShadowGovernanceHistoryStabilityMetrics {
        metrics_id: format!("{}-stability", history_store.store_id),
        snapshot_count: history_store.snapshot_count,
        score_volatility_by_member,
        voice_volatility_by_member,
        max_score_swing,
        max_voice_swing,
        reward_penalty_balance,
        voice_change_balance,
        stability_status: if max_score_swing > 0.25 || max_voice_swing > 0.2 {
            ShadowGovernanceHistoryStabilityStatus::Unstable
        } else if max_score_swing > 0.12 || max_voice_swing > 0.1 {
            ShadowGovernanceHistoryStabilityStatus::StableWithWarnings
        } else {
            ShadowGovernanceHistoryStabilityStatus::Stable
        },
        paper_only: true,
    }
}

fn fairness_status_satisfies(
    actual: ChairmanGovernanceFairnessStatus,
    required: ChairmanGovernanceFairnessStatus,
) -> bool {
    match required {
        ChairmanGovernanceFairnessStatus::Fair => actual == ChairmanGovernanceFairnessStatus::Fair,
        ChairmanGovernanceFairnessStatus::FairWithWarnings => matches!(
            actual,
            ChairmanGovernanceFairnessStatus::Fair
                | ChairmanGovernanceFairnessStatus::FairWithWarnings
        ),
        ChairmanGovernanceFairnessStatus::InsufficientData => {
            actual != ChairmanGovernanceFairnessStatus::Unfair
        }
        ChairmanGovernanceFairnessStatus::Unfair => true,
    }
}

fn risk_first_status_satisfies(
    actual: ChairmanRiskFirstGovernanceStatus,
    required: ChairmanRiskFirstGovernanceStatus,
) -> bool {
    match required {
        ChairmanRiskFirstGovernanceStatus::Preserved => {
            actual == ChairmanRiskFirstGovernanceStatus::Preserved
        }
        ChairmanRiskFirstGovernanceStatus::PreservedWithWarnings => matches!(
            actual,
            ChairmanRiskFirstGovernanceStatus::Preserved
                | ChairmanRiskFirstGovernanceStatus::PreservedWithWarnings
        ),
        ChairmanRiskFirstGovernanceStatus::Violated => true,
    }
}

pub fn evaluate_paper_governance_trial_gate_v2(
    history_store: &ChairmanShadowGovernanceHistoryStore,
    divergence_diagnosis: &ActualVsShadowDivergenceDiagnosis,
    stability_metrics: &ChairmanShadowGovernanceHistoryStabilityMetrics,
    latest_apply_result: &ChairmanShadowGovernanceApplyResult,
    criteria: &PaperGovernanceTrialCriteria,
) -> PaperGovernanceTrialGateV2 {
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    let latest_voice_concentration = latest_shadow_governance_history_snapshot(history_store)
        .map(|snapshot| {
            snapshot
                .member_states
                .iter()
                .map(|state| state.shadow_voice_weight)
                .fold(0.0, f64::max)
        })
        .unwrap_or(0.0);
    let safety_status = if latest_apply_result.no_actual_score_mutation
        && latest_apply_result.no_actual_voice_mutation
        && latest_apply_result.no_promotion_demotion
        && latest_apply_result.no_risk_governor_override
    {
        ChairmanShadowGovernanceApplySafetyGuardStatus::Preserved
    } else {
        ChairmanShadowGovernanceApplySafetyGuardStatus::Violated
    };
    if history_store.snapshot_count < criteria.min_history_snapshots {
        blockers.push("shadow governance history is below the minimum trial threshold".to_string());
    }
    if matches!(
        divergence_diagnosis.diagnosis_status,
        ActualVsShadowDivergenceDiagnosisStatus::UnsafeDivergence
            | ActualVsShadowDivergenceDiagnosisStatus::Blocked
    ) {
        blockers.push(
            "actual-vs-shadow divergence is not safe for a paper governance trial".to_string(),
        );
    }
    if stability_metrics.stability_status == ShadowGovernanceHistoryStabilityStatus::Unstable {
        blockers.push("shadow governance history is unstable".to_string());
    } else if stability_metrics.stability_status
        == ShadowGovernanceHistoryStabilityStatus::StableWithWarnings
    {
        warnings.push("shadow governance history is only stable with warnings".to_string());
    }
    if !fairness_status_satisfies(
        latest_apply_result.fairness_check.fairness_status,
        criteria.require_fairness_status,
    ) {
        blockers.push("fairness status does not meet the paper trial criteria".to_string());
    }
    if !risk_first_status_satisfies(
        latest_apply_result.risk_first_check.risk_first_status,
        criteria.require_risk_first_status,
    ) {
        blockers.push("risk-first status does not meet the paper trial criteria".to_string());
    }
    if safety_status != criteria.require_safety_status {
        blockers.push("safety status does not meet the paper trial criteria".to_string());
    }
    if latest_voice_concentration > criteria.max_allowed_voice_concentration {
        blockers.push("shadow voice concentration exceeds the allowed trial threshold".to_string());
    }
    if stability_metrics.max_voice_swing > criteria.max_allowed_voice_volatility {
        blockers.push("shadow voice volatility exceeds the allowed trial threshold".to_string());
    }
    let gate_status = if history_store.snapshot_count < criteria.min_history_snapshots {
        PaperGovernanceTrialGateV2Status::NeedsMoreShadowHistory
    } else if matches!(
        divergence_diagnosis.diagnosis_status,
        ActualVsShadowDivergenceDiagnosisStatus::UnsafeDivergence
            | ActualVsShadowDivergenceDiagnosisStatus::Blocked
    ) {
        PaperGovernanceTrialGateV2Status::BlockedByDivergence
    } else if !fairness_status_satisfies(
        latest_apply_result.fairness_check.fairness_status,
        criteria.require_fairness_status,
    ) {
        PaperGovernanceTrialGateV2Status::BlockedByFairness
    } else if !risk_first_status_satisfies(
        latest_apply_result.risk_first_check.risk_first_status,
        criteria.require_risk_first_status,
    ) {
        PaperGovernanceTrialGateV2Status::BlockedByRiskViolation
    } else if safety_status != criteria.require_safety_status {
        PaperGovernanceTrialGateV2Status::BlockedBySafety
    } else if latest_voice_concentration > criteria.max_allowed_voice_concentration {
        PaperGovernanceTrialGateV2Status::BlockedByDivergence
    } else if stability_metrics.max_voice_swing > criteria.max_allowed_voice_volatility {
        PaperGovernanceTrialGateV2Status::NeedsMoreEvidence
    } else if stability_metrics.stability_status
        == ShadowGovernanceHistoryStabilityStatus::InsufficientHistory
        || divergence_diagnosis.diagnosis_status
            == ActualVsShadowDivergenceDiagnosisStatus::NeedsMoreHistory
    {
        PaperGovernanceTrialGateV2Status::NeedsMoreShadowHistory
    } else if stability_metrics.stability_status
        == ShadowGovernanceHistoryStabilityStatus::StableWithWarnings
        || divergence_diagnosis.diagnosis_status
            == ActualVsShadowDivergenceDiagnosisStatus::AcceptableWithWarnings
    {
        PaperGovernanceTrialGateV2Status::ReadyWithWarnings
    } else if latest_apply_result.apply_status == ChairmanShadowGovernanceApplyStatus::NoDeltas {
        PaperGovernanceTrialGateV2Status::NeedsMoreEvidence
    } else {
        PaperGovernanceTrialGateV2Status::ReadyForPaperTrialDesign
    };
    let ready_for_paper_governance_trial = matches!(
        gate_status,
        PaperGovernanceTrialGateV2Status::ReadyForPaperTrialDesign
            | PaperGovernanceTrialGateV2Status::ReadyWithWarnings
    );
    PaperGovernanceTrialGateV2 {
        gate_id: format!("{}-trial-gate-v2", history_store.store_id),
        history_snapshot_count: history_store.snapshot_count,
        min_history_snapshots: criteria.min_history_snapshots,
        divergence_status: divergence_diagnosis.diagnosis_status,
        stability_status: stability_metrics.stability_status,
        fairness_status: latest_apply_result.fairness_check.fairness_status,
        risk_first_status: latest_apply_result.risk_first_check.risk_first_status,
        safety_status,
        ready_for_paper_governance_trial,
        trial_allowed_operations: if ready_for_paper_governance_trial {
            vec![PaperGovernanceTrialAllowedOperation::PaperOnlyScoreVoiceTrialDesign]
        } else {
            vec![PaperGovernanceTrialAllowedOperation::None]
        },
        forbidden_operations: vec![
            PaperGovernanceTrialForbiddenOperation::ActualScoreMutation,
            PaperGovernanceTrialForbiddenOperation::ActualVoiceMutation,
            PaperGovernanceTrialForbiddenOperation::PromotionDemotionExecution,
            PaperGovernanceTrialForbiddenOperation::RiskGovernorOverride,
            PaperGovernanceTrialForbiddenOperation::CommitteeDecisionMutation,
            PaperGovernanceTrialForbiddenOperation::TradingOrderAccount,
        ],
        gate_status,
        blockers,
        warnings,
        paper_only: true,
    }
}

fn default_history_safety_guard() -> ChairmanShadowGovernanceHistorySafetyGuard {
    ChairmanShadowGovernanceHistorySafetyGuard {
        history_write_when_dry_run_detected: false,
        actual_score_mutation_detected: false,
        actual_voice_mutation_detected: false,
        promotion_demotion_detected: false,
        risk_governor_override_detected: false,
        committee_decision_mutation_detected: false,
        trade_signal_detected: false,
        order_detected: false,
        broker_order_account_detected: false,
        unsafe_trial_gate_open_detected: false,
        guard_status: ChairmanShadowGovernanceHistorySafetyGuardStatus::Preserved,
        violations: Vec::new(),
        paper_only: true,
    }
}

pub fn build_owner_shadow_governance_history_summary(
    history_run_result: &ChairmanShadowGovernanceHistoryRunResult,
) -> OwnerShadowGovernanceHistorySummary {
    OwnerShadowGovernanceHistorySummary {
        summary_id: format!("{}-owner-shadow-governance-history-summary", history_run_result.run_id),
        snapshot_count: history_run_result.history_store.snapshot_count,
        divergence_status: history_run_result.divergence_diagnosis.diagnosis_status,
        stability_status: history_run_result.stability_metrics.stability_status,
        trial_gate_status: history_run_result.trial_gate_v2.gate_status,
        ready_for_paper_trial_design: history_run_result
            .trial_gate_v2
            .ready_for_paper_governance_trial,
        message: "Shadow governance history is accumulating. Actual score and voice weight did not change. Paper governance trial is still gated by history/fairness/risk/safety. This is not live governance."
            .to_string(),
        shadow_only: true,
        no_actual_score_mutation: true,
        no_actual_voice_mutation: true,
        no_promotion_demotion: true,
        no_risk_override: true,
        not_trade_signal: true,
        paper_only: true,
    }
}

pub fn evaluate_chairman_shadow_governance_history_safety(
    history_run_result: &ChairmanShadowGovernanceHistoryRunResult,
    current_state_result: &ChairmanShadowGovernanceStateRunResult,
    actual_member_states_before: &[MemberStateSnapshot],
    actual_member_states_after: Option<&[MemberStateSnapshot]>,
    dry_run: bool,
) -> ChairmanShadowGovernanceHistorySafetyGuard {
    let after_states = actual_member_states_after.unwrap_or(actual_member_states_before);
    let actual_score_snapshot = |states: &[MemberStateSnapshot]| {
        states
            .iter()
            .map(|state| (state.member_id.clone(), state.score))
            .collect::<BTreeMap<_, _>>()
    };
    let actual_voice_snapshot = |states: &[MemberStateSnapshot]| {
        states
            .iter()
            .map(|state| (state.member_id.clone(), state.voice_weight))
            .collect::<BTreeMap<_, _>>()
    };
    let actual_score_mutation_detected = actual_score_snapshot(actual_member_states_before)
        != actual_score_snapshot(after_states)
        || current_state_result
            .safety_guard
            .actual_score_mutation_detected;
    let actual_voice_mutation_detected = actual_voice_snapshot(actual_member_states_before)
        != actual_voice_snapshot(after_states)
        || current_state_result
            .safety_guard
            .actual_voice_mutation_detected;
    let promotion_demotion_detected = current_state_result
        .safety_guard
        .promotion_execution_detected
        || current_state_result
            .safety_guard
            .demotion_execution_detected;
    let risk_governor_override_detected = current_state_result
        .safety_guard
        .risk_governor_override_detected;
    let committee_decision_mutation_detected = current_state_result
        .safety_guard
        .committee_decision_mutation_detected;
    let trade_signal_detected = current_state_result.safety_guard.trade_signal_detected;
    let order_detected = current_state_result.safety_guard.order_detected;
    let broker_order_account_detected = current_state_result
        .safety_guard
        .broker_order_account_detected;
    let history_write_when_dry_run_detected =
        dry_run && history_run_result.accumulation_result.wrote_history_store;
    let unsafe_trial_gate_open_detected = history_run_result
        .trial_gate_v2
        .ready_for_paper_governance_trial
        && (history_run_result.history_store.snapshot_count
            < history_run_result.trial_criteria.min_history_snapshots
            || matches!(
                history_run_result.divergence_diagnosis.diagnosis_status,
                ActualVsShadowDivergenceDiagnosisStatus::UnsafeDivergence
                    | ActualVsShadowDivergenceDiagnosisStatus::Blocked
                    | ActualVsShadowDivergenceDiagnosisStatus::NeedsMoreHistory
            )
            || matches!(
                history_run_result.stability_metrics.stability_status,
                ShadowGovernanceHistoryStabilityStatus::Unstable
                    | ShadowGovernanceHistoryStabilityStatus::InsufficientHistory
            ));
    let mut violations = Vec::new();
    if history_write_when_dry_run_detected {
        violations.push("shadow governance history wrote history during dry-run".to_string());
    }
    if actual_score_mutation_detected {
        violations.push("shadow governance history mutated actual score".to_string());
    }
    if actual_voice_mutation_detected {
        violations.push("shadow governance history mutated actual voice".to_string());
    }
    if promotion_demotion_detected {
        violations.push("shadow governance history executed promotion or demotion".to_string());
    }
    if risk_governor_override_detected {
        violations.push("shadow governance history overrode Risk Governor".to_string());
    }
    if committee_decision_mutation_detected {
        violations.push("shadow governance history changed committee decision".to_string());
    }
    if trade_signal_detected {
        violations.push("shadow governance history created a trade signal".to_string());
    }
    if order_detected {
        violations.push("shadow governance history created an order".to_string());
    }
    if broker_order_account_detected {
        violations.push("shadow governance history touched broker/order/account".to_string());
    }
    if unsafe_trial_gate_open_detected {
        violations.push("shadow governance history opened the trial gate unsafely".to_string());
    }
    ChairmanShadowGovernanceHistorySafetyGuard {
        history_write_when_dry_run_detected,
        actual_score_mutation_detected,
        actual_voice_mutation_detected,
        promotion_demotion_detected,
        risk_governor_override_detected,
        committee_decision_mutation_detected,
        trade_signal_detected,
        order_detected,
        broker_order_account_detected,
        unsafe_trial_gate_open_detected,
        guard_status: if violations.is_empty() {
            ChairmanShadowGovernanceHistorySafetyGuardStatus::Preserved
        } else {
            ChairmanShadowGovernanceHistorySafetyGuardStatus::Violated
        },
        violations,
        paper_only: true,
    }
}

pub fn run_chairman_shadow_governance_history(
    current_state_result: &ChairmanShadowGovernanceStateRunResult,
    actual_member_states: &[MemberStateSnapshot],
    config: &ChairmanShadowGovernanceHistoryRunConfig,
) -> Result<ChairmanShadowGovernanceHistoryRunResult, String> {
    if !config.paper_only {
        return Err("chairman shadow governance history run must stay paper_only".to_string());
    }
    let mut history_store = if let Some(path) = config.history_store_input_path.as_ref() {
        if Path::new(path).exists() {
            load_chairman_shadow_governance_history_store_from_local_json(Path::new(path))?
        } else {
            ChairmanShadowGovernanceHistoryStore {
                store_id: format!("{}-history-store", config.run_id),
                snapshots: Vec::new(),
                snapshot_count: 0,
                latest_snapshot_id: None,
                paper_only: true,
            }
        }
    } else {
        ChairmanShadowGovernanceHistoryStore {
            store_id: format!("{}-history-store", config.run_id),
            snapshots: Vec::new(),
            snapshot_count: 0,
            latest_snapshot_id: None,
            paper_only: true,
        }
    };
    let accumulation_config = ChairmanShadowGovernanceHistoryAccumulationConfig {
        run_id: config.run_id.clone(),
        enabled: config.enabled,
        history_store_input_path: config.history_store_input_path.clone(),
        history_store_output_path: config.history_store_output_path.clone(),
        max_snapshots: config.max_snapshots,
        min_snapshots_for_trial_gate: config.min_snapshots_for_trial_gate,
        dry_run: config.dry_run,
        paper_only: true,
    };
    let mut accumulation_result = accumulate_chairman_shadow_governance_history(
        current_state_result,
        &mut history_store,
        &accumulation_config,
    )?;
    let mut criteria = default_paper_governance_trial_criteria();
    criteria.criteria_id = format!("{}-paper-governance-trial-criteria", config.run_id);
    criteria.min_history_snapshots = config.min_snapshots_for_trial_gate;
    let shadow_store = current_state_result
        .shadow_store_after
        .as_ref()
        .or(current_state_result.shadow_store_before.as_ref())
        .ok_or_else(|| {
            "chairman shadow governance history run requires shadow state store".to_string()
        })?;
    let divergence_diagnosis = diagnose_actual_vs_shadow_divergence(
        &current_state_result.actual_vs_shadow_summary,
        shadow_store,
        &history_store,
        &criteria,
    );
    let stability_metrics = compute_shadow_governance_history_stability(&history_store);
    let trial_gate_v2 = evaluate_paper_governance_trial_gate_v2(
        &history_store,
        &divergence_diagnosis,
        &stability_metrics,
        &current_state_result.apply_result,
        &criteria,
    );
    let provisional = ChairmanShadowGovernanceHistoryRunResult {
        run_id: config.run_id.clone(),
        accumulation_result: accumulation_result.clone(),
        history_store: history_store.clone(),
        divergence_diagnosis: divergence_diagnosis.clone(),
        stability_metrics: stability_metrics.clone(),
        trial_criteria: criteria.clone(),
        trial_gate_v2: trial_gate_v2.clone(),
        safety_guard: default_history_safety_guard(),
        owner_summary: None,
        run_status: ChairmanShadowGovernanceHistoryRunStatus::PassedWithWarnings,
        paper_only: true,
    };
    let safety_guard = evaluate_chairman_shadow_governance_history_safety(
        &provisional,
        current_state_result,
        actual_member_states,
        Some(actual_member_states),
        config.dry_run,
    );
    if safety_guard.guard_status == ChairmanShadowGovernanceHistorySafetyGuardStatus::Preserved
        && !config.dry_run
    {
        if let Some(path) = config.history_store_output_path.as_ref() {
            save_chairman_shadow_governance_history_store_to_local_json(
                Path::new(path),
                &history_store,
            )?;
            accumulation_result.wrote_history_store = true;
        }
    }
    let mut result = ChairmanShadowGovernanceHistoryRunResult {
        run_id: config.run_id.clone(),
        accumulation_result,
        history_store,
        divergence_diagnosis,
        stability_metrics,
        trial_criteria: criteria,
        trial_gate_v2,
        safety_guard,
        owner_summary: None,
        run_status: ChairmanShadowGovernanceHistoryRunStatus::Passed,
        paper_only: true,
    };
    result.safety_guard = evaluate_chairman_shadow_governance_history_safety(
        &result,
        current_state_result,
        actual_member_states,
        Some(actual_member_states),
        config.dry_run,
    );
    result.run_status = if result.safety_guard.guard_status
        == ChairmanShadowGovernanceHistorySafetyGuardStatus::Violated
        || matches!(
            result.trial_gate_v2.gate_status,
            PaperGovernanceTrialGateV2Status::BlockedByDivergence
                | PaperGovernanceTrialGateV2Status::BlockedByFairness
                | PaperGovernanceTrialGateV2Status::BlockedByRiskViolation
                | PaperGovernanceTrialGateV2Status::BlockedBySafety
        ) {
        ChairmanShadowGovernanceHistoryRunStatus::Failed
    } else if config.dry_run
        || !result.accumulation_result.warnings.is_empty()
        || !result.trial_gate_v2.warnings.is_empty()
        || matches!(
            result.divergence_diagnosis.diagnosis_status,
            ActualVsShadowDivergenceDiagnosisStatus::AcceptableWithWarnings
                | ActualVsShadowDivergenceDiagnosisStatus::NeedsMoreHistory
        )
        || matches!(
            result.stability_metrics.stability_status,
            ShadowGovernanceHistoryStabilityStatus::StableWithWarnings
                | ShadowGovernanceHistoryStabilityStatus::InsufficientHistory
        )
        || matches!(
            result.trial_gate_v2.gate_status,
            PaperGovernanceTrialGateV2Status::NeedsMoreShadowHistory
                | PaperGovernanceTrialGateV2Status::NeedsMoreEvidence
                | PaperGovernanceTrialGateV2Status::ReadyWithWarnings
        )
    {
        ChairmanShadowGovernanceHistoryRunStatus::PassedWithWarnings
    } else {
        ChairmanShadowGovernanceHistoryRunStatus::Passed
    };
    if config.emit_owner_summary {
        let summary = build_owner_shadow_governance_history_summary(&result);
        result.owner_summary = Some(summary);
    }
    Ok(result)
}

pub fn chairman_shadow_governance_history_requested_from_flags(
    enabled: bool,
    dry_run: bool,
    history_store_input_path: Option<&String>,
    history_store_output_path: Option<&String>,
    _max_snapshots: usize,
    _min_snapshots_for_trial_gate: usize,
    _emit_owner_summary: bool,
) -> bool {
    enabled || !dry_run || history_store_input_path.is_some() || history_store_output_path.is_some()
}

fn maybe_run_chairman_shadow_governance_history_for_batch_result(
    run_id: String,
    enabled: bool,
    dry_run: bool,
    history_store_input_path: Option<&String>,
    history_store_output_path: Option<&String>,
    max_snapshots: usize,
    min_snapshots_for_trial_gate: usize,
    emit_owner_summary: bool,
    actual_member_states: &[MemberStateSnapshot],
    batch_result: &mut BatchCommitteeCycleResult,
) -> Result<Option<ChairmanShadowGovernanceHistoryRunResult>, String> {
    if !chairman_shadow_governance_history_requested_from_flags(
        enabled,
        dry_run,
        history_store_input_path,
        history_store_output_path,
        max_snapshots,
        min_snapshots_for_trial_gate,
        emit_owner_summary,
    ) {
        return Ok(None);
    }
    let current_state_result = batch_result
        .chairman_shadow_governance_state_run_result
        .clone()
        .ok_or_else(|| {
            "chairman shadow governance history run requires current shadow governance state result"
                .to_string()
        })?;
    let result = run_chairman_shadow_governance_history(
        &current_state_result,
        actual_member_states,
        &ChairmanShadowGovernanceHistoryRunConfig {
            run_id,
            enabled,
            history_store_input_path: history_store_input_path.cloned(),
            history_store_output_path: history_store_output_path.cloned(),
            max_snapshots,
            min_snapshots_for_trial_gate,
            dry_run,
            emit_owner_summary,
            paper_only: true,
        },
    )?;
    batch_result.chairman_shadow_governance_history_store = Some(result.history_store.clone());
    batch_result.chairman_shadow_governance_history_accumulation_result =
        Some(result.accumulation_result.clone());
    batch_result.actual_vs_shadow_divergence_diagnosis = Some(result.divergence_diagnosis.clone());
    batch_result.chairman_shadow_governance_history_stability_metrics =
        Some(result.stability_metrics.clone());
    batch_result.paper_governance_trial_criteria = Some(result.trial_criteria.clone());
    batch_result.paper_governance_trial_gate_v2 = Some(result.trial_gate_v2.clone());
    batch_result.chairman_shadow_governance_history_safety_guard =
        Some(result.safety_guard.clone());
    batch_result.owner_shadow_governance_history_summary = result.owner_summary.clone();
    batch_result.chairman_shadow_governance_history_run_result = Some(result.clone());
    Ok(Some(result))
}

fn build_multi_run_shadow_state_result(
    current_state_result: &ChairmanShadowGovernanceStateRunResult,
    actual_member_states: &[MemberStateSnapshot],
    run_index: usize,
    run_count: usize,
) -> Result<ChairmanShadowGovernanceStateRunResult, String> {
    let mut derived = current_state_result.clone();
    derived.run_id = format!(
        "{}-shadow-history-run-{:02}",
        current_state_result.run_id,
        run_index + 1
    );
    let actual_by_member = actual_member_states
        .iter()
        .map(|state| (state.member_id.clone(), state))
        .collect::<BTreeMap<_, _>>();
    let progress = if run_count <= 1 {
        1.0
    } else {
        run_index as f64 / (run_count - 1) as f64
    };
    let gap_factor = (1.0 - progress * 0.4).clamp(0.6, 1.0);
    let mut store = derived
        .shadow_store_after
        .clone()
        .or(derived.shadow_store_before.clone())
        .ok_or_else(|| {
            "chairman shadow governance multi-run harness requires shadow store".to_string()
        })?;
    store.latest_run_id = Some(derived.run_id.clone());
    store.update_count = store.update_count.max(run_index + 1);
    for state in &mut store.member_states {
        if let Some(actual) = actual_by_member.get(&state.member_id) {
            let current_score_gap = state.shadow_score - actual.score;
            let current_voice_gap = state.shadow_voice_weight - actual.voice_weight;
            state.actual_score_snapshot = actual.score;
            state.actual_voice_weight_snapshot = actual.voice_weight;
            state.shadow_score = clamp_unit(actual.score + current_score_gap * gap_factor);
            state.shadow_voice_weight =
                clamp_unit(actual.voice_weight + current_voice_gap * gap_factor);
            state.last_update_run_id = Some(derived.run_id.clone());
        }
    }
    if derived.shadow_store_before.is_some() {
        derived.shadow_store_before = Some(store.clone());
    }
    if derived.shadow_store_after.is_some() {
        derived.shadow_store_after = Some(store.clone());
    }
    let (_, summary) = compare_actual_vs_shadow_governance(actual_member_states, &store);
    derived.actual_vs_shadow_summary = summary.clone();
    derived
        .paper_governance_promotion_gate
        .actual_vs_shadow_status = summary.summary_status;
    Ok(derived)
}

pub fn summarize_actual_vs_shadow_divergence_trend(
    history_store: &ChairmanShadowGovernanceHistoryStore,
) -> ActualVsShadowDivergenceTrendSummary {
    let snapshot_count = history_store.snapshot_count;
    let mut score_series = BTreeMap::<String, Vec<f64>>::new();
    let mut voice_series = BTreeMap::<String, Vec<f64>>::new();
    for snapshot in &history_store.snapshots {
        for state in &snapshot.member_states {
            score_series
                .entry(state.member_id.clone())
                .or_default()
                .push((state.shadow_score - state.actual_score_snapshot).abs());
            voice_series
                .entry(state.member_id.clone())
                .or_default()
                .push((state.shadow_voice_weight - state.actual_voice_weight_snapshot).abs());
        }
    }
    let mut reducing_count = 0;
    let mut stable_count = 0;
    let mut increasing_count = 0;
    let mut unsafe_count = 0;
    let mut member_trends = score_series
        .into_iter()
        .map(|(member_id, score_gaps)| {
            let voice_gaps = voice_series.remove(&member_id).unwrap_or_default();
            let max_score_gap = score_gaps.iter().copied().fold(0.0, f64::max);
            let max_voice_gap = voice_gaps.iter().copied().fold(0.0, f64::max);
            let combined = score_gaps
                .iter()
                .zip(voice_gaps.iter())
                .map(|(score_gap, voice_gap)| score_gap + voice_gap)
                .collect::<Vec<_>>();
            let unsafe_divergence = max_score_gap > 0.25 || max_voice_gap > 0.2;
            let mut deltas = combined
                .windows(2)
                .map(|window| window[1] - window[0])
                .collect::<Vec<_>>();
            let trend_direction = if combined.len() < 2 {
                ActualVsShadowDivergenceTrendDirection::InsufficientHistory
            } else if unsafe_divergence {
                ActualVsShadowDivergenceTrendDirection::Unsafe
            } else if deltas.iter().any(|delta| *delta > 0.02)
                && deltas.iter().any(|delta| *delta < -0.02)
            {
                ActualVsShadowDivergenceTrendDirection::Oscillating
            } else {
                let first = combined.first().copied().unwrap_or(0.0);
                let last = combined.last().copied().unwrap_or(0.0);
                if last + 0.02 < first {
                    ActualVsShadowDivergenceTrendDirection::Reducing
                } else if last > first + 0.02 {
                    ActualVsShadowDivergenceTrendDirection::Increasing
                } else {
                    ActualVsShadowDivergenceTrendDirection::Stable
                }
            };
            match trend_direction {
                ActualVsShadowDivergenceTrendDirection::Reducing => reducing_count += 1,
                ActualVsShadowDivergenceTrendDirection::Stable
                | ActualVsShadowDivergenceTrendDirection::Oscillating => stable_count += 1,
                ActualVsShadowDivergenceTrendDirection::Increasing => increasing_count += 1,
                ActualVsShadowDivergenceTrendDirection::Unsafe => unsafe_count += 1,
                ActualVsShadowDivergenceTrendDirection::InsufficientHistory => {}
            }
            deltas.retain(|delta| delta.abs() > 0.02);
            ActualVsShadowDivergenceTrendRecord {
                member_id: member_id.clone(),
                score_gap_series: score_gaps,
                voice_gap_series: voice_gaps,
                max_score_gap,
                max_voice_gap,
                trend_direction,
                unsafe_divergence,
                reason: match trend_direction {
                    ActualVsShadowDivergenceTrendDirection::Reducing => {
                        "shadow divergence is reducing across repeated runs".to_string()
                    }
                    ActualVsShadowDivergenceTrendDirection::Stable => {
                        "shadow divergence remains stable across repeated runs".to_string()
                    }
                    ActualVsShadowDivergenceTrendDirection::Increasing => {
                        "shadow divergence is increasing across repeated runs".to_string()
                    }
                    ActualVsShadowDivergenceTrendDirection::Oscillating => {
                        "shadow divergence oscillates across repeated runs".to_string()
                    }
                    ActualVsShadowDivergenceTrendDirection::InsufficientHistory => {
                        "shadow divergence trend needs more history".to_string()
                    }
                    ActualVsShadowDivergenceTrendDirection::Unsafe => {
                        "shadow divergence crossed the unsafe threshold".to_string()
                    }
                },
                paper_only: true,
            }
        })
        .collect::<Vec<_>>();
    member_trends.sort_by(|left, right| left.member_id.cmp(&right.member_id));
    ActualVsShadowDivergenceTrendSummary {
        summary_id: format!("{}-divergence-trend", history_store.store_id),
        snapshot_count,
        member_trends,
        reducing_count,
        stable_count,
        increasing_count,
        unsafe_count,
        trend_status: if snapshot_count < 2 {
            ActualVsShadowDivergenceTrendStatus::InsufficientHistory
        } else if unsafe_count > 0 {
            ActualVsShadowDivergenceTrendStatus::Unsafe
        } else if increasing_count > 0 {
            ActualVsShadowDivergenceTrendStatus::Worsening
        } else if reducing_count > 0 {
            ActualVsShadowDivergenceTrendStatus::Improving
        } else {
            ActualVsShadowDivergenceTrendStatus::Stable
        },
        paper_only: true,
    }
}

pub fn check_shadow_governance_history_quality(
    history_store: &ChairmanShadowGovernanceHistoryStore,
    required_snapshot_count: usize,
) -> ShadowGovernanceHistoryQualityCheck {
    let expected_members = latest_shadow_governance_history_snapshot(history_store)
        .map(|snapshot| {
            snapshot
                .member_states
                .iter()
                .map(|state| state.member_id.clone())
                .collect::<BTreeSet<_>>()
        })
        .unwrap_or_default();
    let mut duplicate_snapshot_count = 0;
    let mut missing_member_snapshot_count = 0;
    let mut all_snapshots_paper_only = history_store.paper_only;
    let mut unsafe_text_detected = false;
    let mut seen = BTreeSet::new();
    for snapshot in &history_store.snapshots {
        if !seen.insert(snapshot.snapshot_id.clone()) {
            duplicate_snapshot_count += 1;
        }
        let snapshot_members = snapshot
            .member_states
            .iter()
            .map(|state| state.member_id.clone())
            .collect::<BTreeSet<_>>();
        missing_member_snapshot_count += expected_members.difference(&snapshot_members).count();
        all_snapshots_paper_only &=
            snapshot.paper_only && snapshot.member_states.iter().all(|state| state.paper_only);
        let snapshot_text = serde_json::to_string(snapshot)
            .unwrap_or_default()
            .to_ascii_lowercase();
        unsafe_text_detected |= snapshot_text.contains("trade signal")
            || snapshot_text.contains("broker")
            || snapshot_text.contains("order")
            || snapshot_text.contains("account");
    }
    let member_coverage_ok = missing_member_snapshot_count == 0;
    let mut warnings = Vec::new();
    let mut blockers = Vec::new();
    if history_store.snapshot_count < required_snapshot_count {
        warnings.push("shadow governance history still needs more snapshots".to_string());
    }
    if duplicate_snapshot_count > 0 {
        warnings.push("duplicate shadow governance snapshots were detected".to_string());
    }
    if !member_coverage_ok {
        blockers.push("shadow governance history member coverage is incomplete".to_string());
    }
    if !all_snapshots_paper_only {
        blockers.push("shadow governance history contains non-paper-only snapshots".to_string());
    }
    if unsafe_text_detected {
        blockers.push("shadow governance history contains unsafe text markers".to_string());
    }
    ShadowGovernanceHistoryQualityCheck {
        check_id: format!("{}-history-quality", history_store.store_id),
        snapshot_count: history_store.snapshot_count,
        required_snapshot_count,
        member_coverage_ok,
        all_snapshots_paper_only,
        duplicate_snapshot_count,
        missing_member_snapshot_count,
        unsafe_text_detected,
        quality_status: if !blockers.is_empty() {
            ShadowGovernanceHistoryQualityStatus::Invalid
        } else if !warnings.is_empty() {
            ShadowGovernanceHistoryQualityStatus::ValidWithWarnings
        } else {
            ShadowGovernanceHistoryQualityStatus::Valid
        },
        warnings,
        blockers,
        paper_only: true,
    }
}

pub fn evaluate_chairman_shadow_governance_multi_run_safety(
    harness_result: &ChairmanShadowGovernanceMultiRunHarnessResult,
    readiness_v3: &PaperGovernanceTrialDesignReadinessV3,
    current_state_result: &ChairmanShadowGovernanceStateRunResult,
    actual_member_states_before: &[MemberStateSnapshot],
    actual_member_states_after: Option<&[MemberStateSnapshot]>,
    dry_run: bool,
) -> ChairmanShadowGovernanceMultiRunSafetyGuard {
    let after_states = actual_member_states_after.unwrap_or(actual_member_states_before);
    let actual_score_snapshot = |states: &[MemberStateSnapshot]| {
        states
            .iter()
            .map(|state| (state.member_id.clone(), state.score))
            .collect::<BTreeMap<_, _>>()
    };
    let actual_voice_snapshot = |states: &[MemberStateSnapshot]| {
        states
            .iter()
            .map(|state| (state.member_id.clone(), state.voice_weight))
            .collect::<BTreeMap<_, _>>()
    };
    let actual_score_mutation_detected = actual_score_snapshot(actual_member_states_before)
        != actual_score_snapshot(after_states)
        || current_state_result
            .safety_guard
            .actual_score_mutation_detected;
    let actual_voice_mutation_detected = actual_voice_snapshot(actual_member_states_before)
        != actual_voice_snapshot(after_states)
        || current_state_result
            .safety_guard
            .actual_voice_mutation_detected;
    let promotion_demotion_detected = current_state_result
        .safety_guard
        .promotion_execution_detected
        || current_state_result
            .safety_guard
            .demotion_execution_detected;
    let risk_governor_override_detected = current_state_result
        .safety_guard
        .risk_governor_override_detected;
    let committee_decision_mutation_detected = current_state_result
        .safety_guard
        .committee_decision_mutation_detected;
    let trade_signal_detected = current_state_result.safety_guard.trade_signal_detected;
    let order_detected = current_state_result.safety_guard.order_detected;
    let broker_order_account_detected = current_state_result
        .safety_guard
        .broker_order_account_detected;
    let history_write_when_dry_run_detected = dry_run && harness_result.wrote_history_store;
    let unsafe_gate_open_detected = readiness_v3.ready_for_paper_governance_trial_design
        && (!readiness_v3.min_history_met
            || !readiness_v3.divergence_reducing_or_stable
            || !readiness_v3.fairness_ok
            || !readiness_v3.risk_first_ok);
    let mut violations = Vec::new();
    if actual_score_mutation_detected {
        violations.push("shadow governance multi-run mutated actual score".to_string());
    }
    if actual_voice_mutation_detected {
        violations.push("shadow governance multi-run mutated actual voice".to_string());
    }
    if promotion_demotion_detected {
        violations.push("shadow governance multi-run executed promotion or demotion".to_string());
    }
    if risk_governor_override_detected {
        violations.push("shadow governance multi-run overrode Risk Governor".to_string());
    }
    if committee_decision_mutation_detected {
        violations.push("shadow governance multi-run changed committee decision".to_string());
    }
    if trade_signal_detected {
        violations.push("shadow governance multi-run created a trade signal".to_string());
    }
    if order_detected {
        violations.push("shadow governance multi-run created an order".to_string());
    }
    if broker_order_account_detected {
        violations.push("shadow governance multi-run touched broker/order/account".to_string());
    }
    if history_write_when_dry_run_detected {
        violations.push("shadow governance multi-run wrote history during dry-run".to_string());
    }
    if unsafe_gate_open_detected {
        violations.push("shadow governance multi-run opened readiness unsafely".to_string());
    }
    ChairmanShadowGovernanceMultiRunSafetyGuard {
        actual_score_mutation_detected,
        actual_voice_mutation_detected,
        promotion_demotion_detected,
        risk_governor_override_detected,
        committee_decision_mutation_detected,
        trade_signal_detected,
        order_detected,
        broker_order_account_detected,
        history_write_when_dry_run_detected,
        unsafe_gate_open_detected,
        guard_status: if violations.is_empty() {
            ChairmanShadowGovernanceMultiRunSafetyGuardStatus::Preserved
        } else {
            ChairmanShadowGovernanceMultiRunSafetyGuardStatus::Violated
        },
        violations,
        paper_only: true,
    }
}

pub fn evaluate_paper_governance_trial_design_readiness_v3(
    history_quality_check: &ShadowGovernanceHistoryQualityCheck,
    divergence_trend_summary: &ActualVsShadowDivergenceTrendSummary,
    stability_metrics: &ChairmanShadowGovernanceHistoryStabilityMetrics,
    apply_result: &ChairmanShadowGovernanceApplyResult,
    safety_guard: &ChairmanShadowGovernanceMultiRunSafetyGuard,
    min_history_snapshots: usize,
) -> PaperGovernanceTrialDesignReadinessV3 {
    let min_history_met = history_quality_check.snapshot_count >= min_history_snapshots;
    let divergence_reducing_or_stable = matches!(
        divergence_trend_summary.trend_status,
        ActualVsShadowDivergenceTrendStatus::Improving
            | ActualVsShadowDivergenceTrendStatus::Stable
    );
    let fairness_ok = fairness_status_satisfies(
        apply_result.fairness_check.fairness_status,
        ChairmanGovernanceFairnessStatus::FairWithWarnings,
    );
    let risk_first_ok = risk_first_status_satisfies(
        apply_result.risk_first_check.risk_first_status,
        ChairmanRiskFirstGovernanceStatus::PreservedWithWarnings,
    );
    let safety_ok =
        safety_guard.guard_status == ChairmanShadowGovernanceMultiRunSafetyGuardStatus::Preserved;
    let mut blockers = history_quality_check.blockers.clone();
    let mut warnings = history_quality_check.warnings.clone();
    if !min_history_met {
        warnings.push("shadow governance multi-run still needs more history".to_string());
    }
    if !divergence_reducing_or_stable {
        blockers.push("shadow governance divergence trend is not reducing or stable".to_string());
    }
    if !fairness_ok {
        blockers.push("shadow governance fairness is not sufficient for paper design".to_string());
    }
    if !risk_first_ok {
        blockers.push(
            "shadow governance risk-first status is not sufficient for paper design".to_string(),
        );
    }
    if !safety_ok {
        blockers.push("shadow governance multi-run safety guard was violated".to_string());
    }
    if stability_metrics.stability_status
        == ShadowGovernanceHistoryStabilityStatus::StableWithWarnings
    {
        warnings.push(
            "shadow governance multi-run stability is only acceptable with warnings".to_string(),
        );
    }
    let readiness_status =
        if history_quality_check.quality_status == ShadowGovernanceHistoryQualityStatus::Invalid {
            PaperGovernanceTrialDesignReadinessV3Status::BlockedByHistoryQuality
        } else if !safety_ok {
            PaperGovernanceTrialDesignReadinessV3Status::BlockedBySafety
        } else if !min_history_met {
            PaperGovernanceTrialDesignReadinessV3Status::NeedsMoreShadowHistory
        } else if matches!(
            divergence_trend_summary.trend_status,
            ActualVsShadowDivergenceTrendStatus::Unsafe
                | ActualVsShadowDivergenceTrendStatus::Worsening
        ) {
            PaperGovernanceTrialDesignReadinessV3Status::BlockedByDivergence
        } else if !fairness_ok {
            PaperGovernanceTrialDesignReadinessV3Status::BlockedByFairness
        } else if !risk_first_ok {
            PaperGovernanceTrialDesignReadinessV3Status::BlockedByRiskViolation
        } else if matches!(
            stability_metrics.stability_status,
            ShadowGovernanceHistoryStabilityStatus::Unstable
                | ShadowGovernanceHistoryStabilityStatus::InsufficientHistory
        ) {
            PaperGovernanceTrialDesignReadinessV3Status::NeedsMoreEvidence
        } else if history_quality_check.quality_status
            == ShadowGovernanceHistoryQualityStatus::ValidWithWarnings
            || stability_metrics.stability_status
                == ShadowGovernanceHistoryStabilityStatus::StableWithWarnings
        {
            PaperGovernanceTrialDesignReadinessV3Status::ReadyWithWarnings
        } else {
            PaperGovernanceTrialDesignReadinessV3Status::ReadyForPaperGovernanceTrialDesign
        };
    let ready_for_paper_governance_trial_design = matches!(
        readiness_status,
        PaperGovernanceTrialDesignReadinessV3Status::ReadyForPaperGovernanceTrialDesign
            | PaperGovernanceTrialDesignReadinessV3Status::ReadyWithWarnings
    );
    PaperGovernanceTrialDesignReadinessV3 {
        readiness_id: format!("{}-readiness-v3", history_quality_check.check_id),
        history_quality_status: history_quality_check.quality_status,
        divergence_trend_status: divergence_trend_summary.trend_status,
        stability_status: stability_metrics.stability_status,
        fairness_status: apply_result.fairness_check.fairness_status,
        risk_first_status: apply_result.risk_first_check.risk_first_status,
        safety_status: safety_guard.guard_status,
        min_history_met,
        divergence_reducing_or_stable,
        fairness_ok,
        risk_first_ok,
        safety_ok,
        ready_for_paper_governance_trial_design,
        readiness_status,
        blockers,
        warnings,
        paper_only: true,
    }
}

pub fn prove_shadow_governance_history_write(
    harness_result: &ChairmanShadowGovernanceMultiRunHarnessResult,
    output_path: &str,
) -> Result<ShadowGovernanceHistoryWriteProof, String> {
    let path = Path::new(output_path);
    validate_local_json_path(
        path,
        "chairman shadow governance history write proof output path",
    )?;
    let history_store_exists_after_write = path.exists();
    let loaded = if history_store_exists_after_write {
        Some(load_chairman_shadow_governance_history_store_from_local_json(path)?)
    } else {
        None
    };
    let snapshot_count = loaded
        .as_ref()
        .map(|store| store.snapshot_count)
        .unwrap_or(0);
    let member_count = loaded
        .as_ref()
        .and_then(|store| latest_shadow_governance_history_snapshot(store))
        .map(|snapshot| snapshot.member_states.len())
        .unwrap_or(0);
    let paper_only_count = loaded
        .as_ref()
        .map(|store| {
            store
                .snapshots
                .iter()
                .map(|snapshot| {
                    usize::from(snapshot.paper_only)
                        + snapshot
                            .member_states
                            .iter()
                            .filter(|state| state.paper_only)
                            .count()
                })
                .sum()
        })
        .unwrap_or(0);
    let unsafe_snapshot_count = loaded
        .as_ref()
        .map(|store| {
            store
                .snapshots
                .iter()
                .filter(|snapshot| {
                    let text = serde_json::to_string(snapshot)
                        .unwrap_or_default()
                        .to_ascii_lowercase();
                    text.contains("trade signal")
                        || text.contains("broker")
                        || text.contains("order")
                        || text.contains("account")
                        || !snapshot.paper_only
                        || snapshot.member_states.iter().any(|state| !state.paper_only)
                })
                .count()
        })
        .unwrap_or(0);
    Ok(ShadowGovernanceHistoryWriteProof {
        proof_id: format!("{}-write-proof", harness_result.run_id),
        expected_output_path: output_path.to_string(),
        wrote_history_store: harness_result.wrote_history_store,
        history_store_exists_after_write,
        snapshot_count,
        member_count,
        paper_only_count,
        unsafe_snapshot_count,
        proof_status: if !harness_result.wrote_history_store
            || !history_store_exists_after_write
            || snapshot_count < harness_result.final_snapshot_count
            || unsafe_snapshot_count > 0
        {
            ShadowGovernanceHistoryWriteProofStatus::Failed
        } else if snapshot_count > harness_result.final_snapshot_count {
            ShadowGovernanceHistoryWriteProofStatus::ProvenWithWarnings
        } else {
            ShadowGovernanceHistoryWriteProofStatus::Proven
        },
        paper_only: true,
    })
}

pub fn build_owner_shadow_governance_multi_run_summary(
    harness_result: &ChairmanShadowGovernanceMultiRunHarnessResult,
    readiness_v3: &PaperGovernanceTrialDesignReadinessV3,
) -> OwnerShadowGovernanceMultiRunSummary {
    OwnerShadowGovernanceMultiRunSummary {
        summary_id: format!("{}-owner-shadow-governance-multi-run-summary", harness_result.run_id),
        completed_run_count: harness_result.completed_run_count,
        final_snapshot_count: harness_result.final_snapshot_count,
        divergence_trend_status: match readiness_v3.divergence_trend_status {
            ActualVsShadowDivergenceTrendStatus::Improving => {
                ActualVsShadowDivergenceTrendStatus::Improving
            }
            ActualVsShadowDivergenceTrendStatus::Stable => {
                ActualVsShadowDivergenceTrendStatus::Stable
            }
            ActualVsShadowDivergenceTrendStatus::Worsening => {
                ActualVsShadowDivergenceTrendStatus::Worsening
            }
            ActualVsShadowDivergenceTrendStatus::Unsafe => {
                ActualVsShadowDivergenceTrendStatus::Unsafe
            }
            ActualVsShadowDivergenceTrendStatus::InsufficientHistory => {
                ActualVsShadowDivergenceTrendStatus::InsufficientHistory
            }
        },
        stability_status: readiness_v3.stability_status,
        readiness_v3_status: readiness_v3.readiness_status,
        wrote_history_store: harness_result.wrote_history_store,
        message: "Shadow governance multi-run verification stayed paper-only. Actual score and voice weight did not change. This is readiness evidence for paper governance trial design only."
            .to_string(),
        shadow_only: true,
        no_actual_score_mutation: true,
        no_actual_voice_mutation: true,
        no_promotion_demotion: true,
        no_risk_override: true,
        not_trade_signal: true,
        paper_only: true,
    }
}

pub fn run_chairman_shadow_governance_multi_run_harness(
    current_state_result: &ChairmanShadowGovernanceStateRunResult,
    actual_member_states: &[MemberStateSnapshot],
    config: &ChairmanShadowGovernanceMultiRunHarnessConfig,
) -> Result<ChairmanShadowGovernanceMultiRunHarnessResult, String> {
    if !config.paper_only {
        return Err(
            "chairman shadow governance multi-run harness must stay paper_only".to_string(),
        );
    }
    if config.run_count == 0 {
        return Err(
            "chairman shadow governance multi-run harness requires a positive run_count"
                .to_string(),
        );
    }
    if config.min_snapshots_required == 0 {
        return Err(
            "chairman shadow governance multi-run harness requires positive min_snapshots_required"
                .to_string(),
        );
    }
    if !config.dry_run && config.write_history_store && config.history_store_output_path.is_none() {
        return Err(
            "chairman shadow governance multi-run harness requires history_store_output_path when write_history_store=true"
                .to_string(),
        );
    }
    for (path, label) in [
        (
            config.history_store_input_path.as_ref(),
            "chairman shadow governance multi-run history input path",
        ),
        (
            config.history_store_output_path.as_ref(),
            "chairman shadow governance multi-run history output path",
        ),
        (
            config.simulation_ledger_input_path.as_ref(),
            "chairman shadow governance multi-run simulation ledger input path",
        ),
        (
            config.simulation_ledger_output_path.as_ref(),
            "chairman shadow governance multi-run simulation ledger output path",
        ),
        (
            config.output_path.as_ref(),
            "chairman shadow governance multi-run output path",
        ),
    ] {
        if let Some(path) = path {
            validate_local_json_path(Path::new(path), label)?;
        }
    }
    let mut history_store = if let Some(path) = config.history_store_input_path.as_ref() {
        if Path::new(path).exists() {
            load_chairman_shadow_governance_history_store_from_local_json(Path::new(path))?
        } else {
            ChairmanShadowGovernanceHistoryStore {
                store_id: format!("{}-history-store", config.run_id),
                snapshots: Vec::new(),
                snapshot_count: 0,
                latest_snapshot_id: None,
                paper_only: true,
            }
        }
    } else {
        ChairmanShadowGovernanceHistoryStore {
            store_id: format!("{}-history-store", config.run_id),
            snapshots: Vec::new(),
            snapshot_count: 0,
            latest_snapshot_id: None,
            paper_only: true,
        }
    };
    let previous_snapshot_count = history_store.snapshot_count;
    let mut per_run_results = Vec::new();
    let mut aggregate_divergence_diagnosis = ActualVsShadowDivergenceDiagnosis {
        diagnosis_id: format!("{}-divergence-diagnosis", config.run_id),
        record_count: 0,
        high_severity_count: 0,
        unsafe_count: 0,
        expected_count: 0,
        divergence_records: Vec::new(),
        diagnosis_status: ActualVsShadowDivergenceDiagnosisStatus::NeedsMoreHistory,
        paper_only: true,
    };
    let mut aggregate_stability_metrics =
        compute_shadow_governance_history_stability(&history_store);
    let mut paper_governance_trial_gate_v2 = evaluate_paper_governance_trial_gate_v2(
        &history_store,
        &aggregate_divergence_diagnosis,
        &aggregate_stability_metrics,
        &current_state_result.apply_result,
        &default_paper_governance_trial_criteria(),
    );
    let mut safety_guard = default_history_safety_guard();
    let criteria = PaperGovernanceTrialCriteria {
        criteria_id: format!("{}-paper-governance-trial-criteria", config.run_id),
        min_history_snapshots: config.min_snapshots_required,
        ..default_paper_governance_trial_criteria()
    };
    for run_index in 0..config.run_count {
        let derived_state_result = build_multi_run_shadow_state_result(
            current_state_result,
            actual_member_states,
            run_index,
            config.run_count,
        )?;
        let accumulation_config = ChairmanShadowGovernanceHistoryAccumulationConfig {
            run_id: derived_state_result.run_id.clone(),
            enabled: true,
            history_store_input_path: config.history_store_input_path.clone(),
            history_store_output_path: config.history_store_output_path.clone(),
            max_snapshots: config.min_snapshots_required.max(config.run_count),
            min_snapshots_for_trial_gate: config.min_snapshots_required,
            dry_run: config.dry_run,
            paper_only: true,
        };
        let accumulation_result = accumulate_chairman_shadow_governance_history(
            &derived_state_result,
            &mut history_store,
            &accumulation_config,
        )?;
        let shadow_store = derived_state_result
            .shadow_store_after
            .as_ref()
            .or(derived_state_result.shadow_store_before.as_ref())
            .ok_or_else(|| {
                "chairman shadow governance multi-run harness requires shadow store".to_string()
            })?;
        aggregate_divergence_diagnosis = diagnose_actual_vs_shadow_divergence(
            &derived_state_result.actual_vs_shadow_summary,
            shadow_store,
            &history_store,
            &criteria,
        );
        aggregate_stability_metrics = compute_shadow_governance_history_stability(&history_store);
        paper_governance_trial_gate_v2 = evaluate_paper_governance_trial_gate_v2(
            &history_store,
            &aggregate_divergence_diagnosis,
            &aggregate_stability_metrics,
            &derived_state_result.apply_result,
            &criteria,
        );
        let history_run_result = ChairmanShadowGovernanceHistoryRunResult {
            run_id: derived_state_result.run_id.clone(),
            accumulation_result: accumulation_result.clone(),
            history_store: history_store.clone(),
            divergence_diagnosis: aggregate_divergence_diagnosis.clone(),
            stability_metrics: aggregate_stability_metrics.clone(),
            trial_criteria: criteria.clone(),
            trial_gate_v2: paper_governance_trial_gate_v2.clone(),
            safety_guard: default_history_safety_guard(),
            owner_summary: None,
            run_status: ChairmanShadowGovernanceHistoryRunStatus::PassedWithWarnings,
            paper_only: true,
        };
        safety_guard = evaluate_chairman_shadow_governance_history_safety(
            &history_run_result,
            &derived_state_result,
            actual_member_states,
            Some(actual_member_states),
            config.dry_run,
        );
        per_run_results.push(PerRunShadowGovernanceHistoryResult {
            run_index,
            snapshot_id: history_store
                .latest_snapshot_id
                .clone()
                .unwrap_or_else(|| format!("{}-history-snapshot", derived_state_result.run_id)),
            divergence_status: aggregate_divergence_diagnosis.diagnosis_status,
            stability_status: aggregate_stability_metrics.stability_status,
            fairness_status: derived_state_result
                .apply_result
                .fairness_check
                .fairness_status,
            risk_first_status: derived_state_result
                .apply_result
                .risk_first_check
                .risk_first_status,
            gate_status: paper_governance_trial_gate_v2.gate_status,
            safety_status: safety_guard.guard_status,
            paper_only: true,
        });
    }
    let mut wrote_history_store = false;
    if !config.dry_run
        && config.write_history_store
        && safety_guard.guard_status == ChairmanShadowGovernanceHistorySafetyGuardStatus::Preserved
    {
        if let Some(path) = config.history_store_output_path.as_ref() {
            save_chairman_shadow_governance_history_store_to_local_json(
                Path::new(path),
                &history_store,
            )?;
            wrote_history_store = true;
        }
    }
    let result = ChairmanShadowGovernanceMultiRunHarnessResult {
        run_id: config.run_id.clone(),
        requested_run_count: config.run_count,
        completed_run_count: per_run_results.len(),
        previous_snapshot_count,
        appended_snapshot_count: history_store
            .snapshot_count
            .saturating_sub(previous_snapshot_count),
        final_snapshot_count: history_store.snapshot_count,
        wrote_history_store,
        history_store_path: config.history_store_output_path.clone(),
        history_store: history_store.clone(),
        per_run_results,
        aggregate_divergence_diagnosis: aggregate_divergence_diagnosis.clone(),
        aggregate_stability_metrics: aggregate_stability_metrics.clone(),
        aggregate_fairness_status: current_state_result
            .apply_result
            .fairness_check
            .fairness_status,
        aggregate_risk_first_status: current_state_result
            .apply_result
            .risk_first_check
            .risk_first_status,
        paper_governance_trial_gate_v2: paper_governance_trial_gate_v2.clone(),
        safety_guard: safety_guard.clone(),
        harness_status: if safety_guard.guard_status
            == ChairmanShadowGovernanceHistorySafetyGuardStatus::Violated
            || matches!(
                paper_governance_trial_gate_v2.gate_status,
                PaperGovernanceTrialGateV2Status::BlockedByDivergence
                    | PaperGovernanceTrialGateV2Status::BlockedByFairness
                    | PaperGovernanceTrialGateV2Status::BlockedByRiskViolation
                    | PaperGovernanceTrialGateV2Status::BlockedBySafety
            ) {
            ChairmanShadowGovernanceMultiRunHarnessStatus::Failed
        } else if config.dry_run
            || history_store.snapshot_count < config.min_snapshots_required
            || matches!(
                paper_governance_trial_gate_v2.gate_status,
                PaperGovernanceTrialGateV2Status::NeedsMoreShadowHistory
                    | PaperGovernanceTrialGateV2Status::NeedsMoreEvidence
                    | PaperGovernanceTrialGateV2Status::ReadyWithWarnings
            )
        {
            ChairmanShadowGovernanceMultiRunHarnessStatus::PassedWithWarnings
        } else {
            ChairmanShadowGovernanceMultiRunHarnessStatus::Passed
        },
        paper_only: true,
    };
    if !config.dry_run {
        if let Some(path) = config.output_path.as_ref() {
            write_safe_json(Path::new(path), &result)?;
        }
    }
    Ok(result)
}

pub fn run_chairman_shadow_governance_history_verify(
    current_state_result: &ChairmanShadowGovernanceStateRunResult,
    actual_member_states: &[MemberStateSnapshot],
    config: &ChairmanShadowGovernanceHistoryVerifyRunConfig,
) -> Result<ChairmanShadowGovernanceHistoryVerifyRunResult, String> {
    if !config.paper_only {
        return Err(
            "chairman shadow governance history verify run must stay paper_only".to_string(),
        );
    }
    if config.run_count == 0 || config.min_snapshots_required == 0 {
        return Err(
            "chairman shadow governance history verify run requires positive history counts"
                .to_string(),
        );
    }
    if !config.dry_run && config.history_output_path.is_none() {
        return Err(
            "chairman shadow governance history verify run requires history_output_path when dry_run=false"
                .to_string(),
        );
    }
    if let Some(path) = config.verification_profile_path.as_ref() {
        validate_local_json_or_toml_path(
            Path::new(path),
            "chairman shadow governance history verify profile path",
        )?;
    }
    if let Some(path) = config.history_output_path.as_ref() {
        validate_local_json_path(
            Path::new(path),
            "chairman shadow governance history verify history output path",
        )?;
    }
    if let Some(path) = config.output_path.as_ref() {
        validate_local_json_path(
            Path::new(path),
            "chairman shadow governance history verify output path",
        )?;
    }
    let harness_result = run_chairman_shadow_governance_multi_run_harness(
        current_state_result,
        actual_member_states,
        &ChairmanShadowGovernanceMultiRunHarnessConfig {
            run_id: config.run_id.clone(),
            enabled: config.enabled && config.use_multi_run_harness,
            run_count: config.run_count,
            min_snapshots_required: config.min_snapshots_required,
            history_store_input_path: None,
            history_store_output_path: config.history_output_path.clone(),
            simulation_ledger_input_path: None,
            simulation_ledger_output_path: None,
            output_path: None,
            dry_run: config.dry_run,
            write_history_store: !config.dry_run,
            emit_owner_summary: config.emit_owner_summary,
            paper_only: true,
        },
    )?;
    let history_quality_check = check_shadow_governance_history_quality(
        &harness_result.history_store,
        config.min_snapshots_required,
    );
    let divergence_trend_summary =
        summarize_actual_vs_shadow_divergence_trend(&harness_result.history_store);
    let placeholder_readiness = PaperGovernanceTrialDesignReadinessV3 {
        readiness_id: format!("{}-readiness-v3", config.run_id),
        history_quality_status: history_quality_check.quality_status,
        divergence_trend_status: divergence_trend_summary.trend_status,
        stability_status: harness_result.aggregate_stability_metrics.stability_status,
        fairness_status: current_state_result
            .apply_result
            .fairness_check
            .fairness_status,
        risk_first_status: current_state_result
            .apply_result
            .risk_first_check
            .risk_first_status,
        safety_status: ChairmanShadowGovernanceMultiRunSafetyGuardStatus::Preserved,
        min_history_met: false,
        divergence_reducing_or_stable: false,
        fairness_ok: false,
        risk_first_ok: false,
        safety_ok: false,
        ready_for_paper_governance_trial_design: false,
        readiness_status: PaperGovernanceTrialDesignReadinessV3Status::NeedsMoreShadowHistory,
        blockers: Vec::new(),
        warnings: Vec::new(),
        paper_only: true,
    };
    let provisional_safety_guard = evaluate_chairman_shadow_governance_multi_run_safety(
        &harness_result,
        &placeholder_readiness,
        current_state_result,
        actual_member_states,
        Some(actual_member_states),
        config.dry_run,
    );
    let readiness_v3 = evaluate_paper_governance_trial_design_readiness_v3(
        &history_quality_check,
        &divergence_trend_summary,
        &harness_result.aggregate_stability_metrics,
        &current_state_result.apply_result,
        &provisional_safety_guard,
        config.min_snapshots_required,
    );
    let multi_run_safety_guard = evaluate_chairman_shadow_governance_multi_run_safety(
        &harness_result,
        &readiness_v3,
        current_state_result,
        actual_member_states,
        Some(actual_member_states),
        config.dry_run,
    );
    let history_write_proof = if config.dry_run {
        None
    } else {
        config
            .history_output_path
            .as_deref()
            .map(|path| prove_shadow_governance_history_write(&harness_result, path))
            .transpose()?
    };
    let owner_summary = if config.emit_owner_summary {
        Some(build_owner_shadow_governance_multi_run_summary(
            &harness_result,
            &readiness_v3,
        ))
    } else {
        None
    };
    let run_status = if multi_run_safety_guard.guard_status
        == ChairmanShadowGovernanceMultiRunSafetyGuardStatus::Violated
        || harness_result.harness_status == ChairmanShadowGovernanceMultiRunHarnessStatus::Failed
        || matches!(
            readiness_v3.readiness_status,
            PaperGovernanceTrialDesignReadinessV3Status::BlockedByDivergence
                | PaperGovernanceTrialDesignReadinessV3Status::BlockedByFairness
                | PaperGovernanceTrialDesignReadinessV3Status::BlockedByRiskViolation
                | PaperGovernanceTrialDesignReadinessV3Status::BlockedBySafety
                | PaperGovernanceTrialDesignReadinessV3Status::BlockedByHistoryQuality
        )
        || history_write_proof.as_ref().is_some_and(|proof| {
            proof.proof_status == ShadowGovernanceHistoryWriteProofStatus::Failed
        }) {
        ChairmanShadowGovernanceHistoryVerifyRunStatus::Failed
    } else if config.dry_run
        || history_quality_check.quality_status != ShadowGovernanceHistoryQualityStatus::Valid
        || history_write_proof.as_ref().is_some_and(|proof| {
            proof.proof_status == ShadowGovernanceHistoryWriteProofStatus::ProvenWithWarnings
        })
    {
        ChairmanShadowGovernanceHistoryVerifyRunStatus::PassedWithWarnings
    } else {
        ChairmanShadowGovernanceHistoryVerifyRunStatus::Passed
    };
    let result = ChairmanShadowGovernanceHistoryVerifyRunResult {
        run_id: config.run_id.clone(),
        multi_run_harness_result: harness_result,
        history_quality_check,
        divergence_trend_summary,
        readiness_v3,
        history_write_proof,
        multi_run_safety_guard: multi_run_safety_guard.clone(),
        owner_summary,
        run_status,
        paper_only: true,
    };
    if !config.dry_run {
        if let Some(path) = config.output_path.as_ref() {
            write_safe_json(Path::new(path), &result)?;
        }
    }
    Ok(result)
}

pub fn chairman_shadow_governance_multi_run_requested_from_flags(
    enabled: bool,
    dry_run: bool,
    _run_count: usize,
    write_history_store: bool,
    output_path: Option<&String>,
) -> bool {
    enabled || !dry_run || write_history_store || output_path.is_some()
}

fn maybe_run_chairman_shadow_governance_multi_run_harness_for_batch_result(
    run_id: String,
    enabled: bool,
    dry_run: bool,
    run_count: usize,
    write_history_store: bool,
    history_store_input_path: Option<&String>,
    history_store_output_path: Option<&String>,
    output_path: Option<&String>,
    min_snapshots_required: usize,
    emit_owner_summary: bool,
    actual_member_states: &[MemberStateSnapshot],
    batch_result: &mut BatchCommitteeCycleResult,
) -> Result<Option<ChairmanShadowGovernanceMultiRunHarnessResult>, String> {
    if !chairman_shadow_governance_multi_run_requested_from_flags(
        enabled,
        dry_run,
        run_count,
        write_history_store,
        output_path,
    ) {
        return Ok(None);
    }
    let current_state_result = batch_result
        .chairman_shadow_governance_state_run_result
        .clone()
        .ok_or_else(|| {
            "chairman shadow governance multi-run harness requires current shadow governance state result"
                .to_string()
        })?;
    let result = run_chairman_shadow_governance_multi_run_harness(
        &current_state_result,
        actual_member_states,
        &ChairmanShadowGovernanceMultiRunHarnessConfig {
            run_id,
            enabled,
            run_count,
            min_snapshots_required,
            history_store_input_path: history_store_input_path.cloned(),
            history_store_output_path: history_store_output_path.cloned(),
            simulation_ledger_input_path: None,
            simulation_ledger_output_path: None,
            output_path: output_path.cloned(),
            dry_run,
            write_history_store,
            emit_owner_summary,
            paper_only: true,
        },
    )?;
    batch_result.chairman_shadow_governance_multi_run_harness_result = Some(result.clone());
    batch_result.chairman_shadow_governance_history_store = Some(result.history_store.clone());
    batch_result.actual_vs_shadow_divergence_diagnosis =
        Some(result.aggregate_divergence_diagnosis.clone());
    batch_result.chairman_shadow_governance_history_stability_metrics =
        Some(result.aggregate_stability_metrics.clone());
    batch_result.paper_governance_trial_gate_v2 =
        Some(result.paper_governance_trial_gate_v2.clone());
    batch_result.chairman_shadow_governance_history_safety_guard =
        Some(result.safety_guard.clone());
    Ok(Some(result))
}

pub fn chairman_shadow_governance_history_verify_requested_from_flags(
    enabled: bool,
    output_path: Option<&String>,
    _emit_owner_summary: bool,
) -> bool {
    enabled || output_path.is_some()
}

fn maybe_run_chairman_shadow_governance_history_verify_for_batch_result(
    run_id: String,
    enabled: bool,
    dry_run: bool,
    run_count: usize,
    history_output_path: Option<&String>,
    output_path: Option<&String>,
    emit_owner_summary: bool,
    actual_member_states: &[MemberStateSnapshot],
    batch_result: &mut BatchCommitteeCycleResult,
) -> Result<Option<ChairmanShadowGovernanceHistoryVerifyRunResult>, String> {
    if !chairman_shadow_governance_history_verify_requested_from_flags(
        enabled,
        output_path,
        emit_owner_summary,
    ) {
        return Ok(None);
    }
    let current_state_result = batch_result
        .chairman_shadow_governance_state_run_result
        .clone()
        .ok_or_else(|| {
            "chairman shadow governance history verify run requires current shadow governance state result"
                .to_string()
        })?;
    let result = run_chairman_shadow_governance_history_verify(
        &current_state_result,
        actual_member_states,
        &ChairmanShadowGovernanceHistoryVerifyRunConfig {
            run_id,
            enabled,
            use_multi_run_harness: true,
            verification_profile_path: None,
            history_output_path: history_output_path.cloned(),
            dry_run,
            run_count,
            min_snapshots_required: run_count.max(1),
            emit_owner_summary,
            output_path: output_path.cloned(),
            paper_only: true,
        },
    )?;
    batch_result.chairman_shadow_governance_history_store =
        Some(result.multi_run_harness_result.history_store.clone());
    batch_result.chairman_shadow_governance_multi_run_harness_result =
        Some(result.multi_run_harness_result.clone());
    batch_result.actual_vs_shadow_divergence_diagnosis = Some(
        result
            .multi_run_harness_result
            .aggregate_divergence_diagnosis
            .clone(),
    );
    batch_result.chairman_shadow_governance_history_stability_metrics = Some(
        result
            .multi_run_harness_result
            .aggregate_stability_metrics
            .clone(),
    );
    batch_result.paper_governance_trial_gate_v2 = Some(
        result
            .multi_run_harness_result
            .paper_governance_trial_gate_v2
            .clone(),
    );
    batch_result.chairman_shadow_governance_history_safety_guard =
        Some(result.multi_run_harness_result.safety_guard.clone());
    batch_result.actual_vs_shadow_divergence_trend_summary =
        Some(result.divergence_trend_summary.clone());
    batch_result.shadow_governance_history_quality_check =
        Some(result.history_quality_check.clone());
    batch_result.paper_governance_trial_design_readiness_v3 = Some(result.readiness_v3.clone());
    batch_result.shadow_governance_history_write_proof = result.history_write_proof.clone();
    batch_result.owner_shadow_governance_multi_run_summary = result.owner_summary.clone();
    batch_result.chairman_shadow_governance_multi_run_safety_guard =
        Some(result.multi_run_safety_guard.clone());
    batch_result.chairman_shadow_governance_history_verify_run_result = Some(result.clone());
    Ok(Some(result))
}

fn map_shadow_role(role: IndependentMemberRole) -> ChairmanUnsafeDivergenceRole {
    match role {
        IndependentMemberRole::TrendEntry => ChairmanUnsafeDivergenceRole::TrendEntry,
        IndependentMemberRole::RiskGuard => ChairmanUnsafeDivergenceRole::RiskGuard,
        IndependentMemberRole::EvidenceRegime => ChairmanUnsafeDivergenceRole::EvidenceRegime,
    }
}

fn latest_shadow_role_for_member(
    history_store: &ChairmanShadowGovernanceHistoryStore,
    member_id: &str,
) -> Option<ChairmanUnsafeDivergenceRole> {
    latest_shadow_governance_history_snapshot(history_store).and_then(|snapshot| {
        snapshot
            .member_states
            .iter()
            .find(|state| state.member_id == member_id)
            .map(|state| map_shadow_role(state.role))
    })
}

fn classify_unsafe_divergence_root_cause(
    record: &ActualVsShadowDivergenceRecord,
    role: Option<ChairmanUnsafeDivergenceRole>,
) -> (ChairmanUnsafeDivergenceCause, ChairmanShadowTuningAction) {
    match record.divergence_type {
        ActualVsShadowDivergenceType::ScoreDrift => (
            ChairmanUnsafeDivergenceCause::ExcessiveScoreDrift,
            ChairmanShadowTuningAction::ReduceScoreDeltaCap,
        ),
        ActualVsShadowDivergenceType::VoiceDrift => (
            ChairmanUnsafeDivergenceCause::ExcessiveVoiceDrift,
            ChairmanShadowTuningAction::ReduceVoiceDeltaCap,
        ),
        ActualVsShadowDivergenceType::ShadowOverReward => (
            ChairmanUnsafeDivergenceCause::ShadowOverReward,
            ChairmanShadowTuningAction::ReduceScoreDeltaCap,
        ),
        ActualVsShadowDivergenceType::ShadowOverPenalty => (
            ChairmanUnsafeDivergenceCause::ShadowOverPenalty,
            ChairmanShadowTuningAction::ReduceScoreDeltaCap,
        ),
        ActualVsShadowDivergenceType::RiskGuardOverDominance => (
            ChairmanUnsafeDivergenceCause::RiskGuardOverDominance,
            ChairmanShadowTuningAction::AddRiskGuardDominanceCap,
        ),
        ActualVsShadowDivergenceType::TrendEntrySuppression => (
            ChairmanUnsafeDivergenceCause::TrendEntrySuppression,
            ChairmanShadowTuningAction::AddTrendEntrySuppressionGuard,
        ),
        ActualVsShadowDivergenceType::EvidenceRegimeUnderweight => (
            ChairmanUnsafeDivergenceCause::EvidenceRegimeUnderweight,
            ChairmanShadowTuningAction::AddEvidenceRegimeMinimumVoiceFloor,
        ),
        ActualVsShadowDivergenceType::ExpectedShadowLearning
        | ActualVsShadowDivergenceType::InsufficientHistory => (
            ChairmanUnsafeDivergenceCause::InsufficientEvidence,
            ChairmanShadowTuningAction::RequireMoreEvidence,
        ),
        ActualVsShadowDivergenceType::UnsafeDivergence => {
            match role.unwrap_or(ChairmanUnsafeDivergenceRole::Unknown) {
                ChairmanUnsafeDivergenceRole::RiskGuard => (
                    ChairmanUnsafeDivergenceCause::RiskGuardOverDominance,
                    ChairmanShadowTuningAction::AddRiskGuardDominanceCap,
                ),
                ChairmanUnsafeDivergenceRole::TrendEntry => (
                    ChairmanUnsafeDivergenceCause::TrendEntrySuppression,
                    ChairmanShadowTuningAction::AddTrendEntrySuppressionGuard,
                ),
                ChairmanUnsafeDivergenceRole::EvidenceRegime => (
                    ChairmanUnsafeDivergenceCause::EvidenceRegimeUnderweight,
                    ChairmanShadowTuningAction::AddEvidenceRegimeMinimumVoiceFloor,
                ),
                ChairmanUnsafeDivergenceRole::Unknown => (
                    if record.score_gap.abs() >= record.voice_gap.abs() {
                        ChairmanUnsafeDivergenceCause::DeltaPolicyTooAggressive
                    } else {
                        ChairmanUnsafeDivergenceCause::FairnessCapMissing
                    },
                    if record.score_gap.abs() >= record.voice_gap.abs() {
                        ChairmanShadowTuningAction::ReduceScoreDeltaCap
                    } else {
                        ChairmanShadowTuningAction::AddRoleBalanceCap
                    },
                ),
            }
        }
    }
}

pub fn analyze_unsafe_governance_divergence_causes(
    divergence_diagnosis: &ActualVsShadowDivergenceDiagnosis,
    history_store: &ChairmanShadowGovernanceHistoryStore,
    simulation_policy: &ChairmanShadowGovernanceSimulationPolicy,
) -> Vec<ChairmanUnsafeDivergenceRootCauseRecord> {
    let mut records = divergence_diagnosis
        .divergence_records
        .iter()
        .filter(|record| {
            record.unsafe_divergence || record.severity == ActualVsShadowDivergenceSeverity::High
        })
        .map(|record| {
            let role = latest_shadow_role_for_member(history_store, &record.member_id);
            let (cause, recommended_tuning_action) =
                classify_unsafe_divergence_root_cause(record, role);
            ChairmanUnsafeDivergenceRootCauseRecord {
                record_id: format!("{}-root-cause", record.divergence_id),
                source_divergence_id: Some(record.divergence_id.clone()),
                member_id: Some(record.member_id.clone()),
                role,
                cause,
                severity: record.severity,
                evidence_summary: format!(
                    "score_gap={:.3}, voice_gap={:.3}, policy caps=({:.3}, {:.3})",
                    record.score_gap,
                    record.voice_gap,
                    simulation_policy.max_abs_score_delta_per_entry,
                    simulation_policy.max_abs_voice_delta_per_entry
                ),
                recommended_tuning_action,
                paper_only: true,
            }
        })
        .collect::<Vec<_>>();
    if records.is_empty() {
        records.push(ChairmanUnsafeDivergenceRootCauseRecord {
            record_id: format!("{}-root-cause-fallback", divergence_diagnosis.diagnosis_id),
            source_divergence_id: None,
            member_id: None,
            role: None,
            cause: if divergence_diagnosis.diagnosis_status
                == ActualVsShadowDivergenceDiagnosisStatus::NeedsMoreHistory
            {
                ChairmanUnsafeDivergenceCause::InsufficientEvidence
            } else {
                ChairmanUnsafeDivergenceCause::Unknown
            },
            severity: ActualVsShadowDivergenceSeverity::Low,
            evidence_summary: "No explicit unsafe divergence record was available; keep observing the shadow policy.".to_string(),
            recommended_tuning_action: if divergence_diagnosis.diagnosis_status
                == ActualVsShadowDivergenceDiagnosisStatus::NeedsMoreHistory
            {
                ChairmanShadowTuningAction::RequireMoreEvidence
            } else {
                ChairmanShadowTuningAction::KeepObserving
            },
            paper_only: true,
        });
    }
    records.sort_by(|left, right| left.record_id.cmp(&right.record_id));
    records
}

pub fn summarize_unsafe_governance_divergence_causes(
    records: &[ChairmanUnsafeDivergenceRootCauseRecord],
) -> ChairmanUnsafeDivergenceRootCauseSummary {
    let mut by_cause = BTreeMap::new();
    let mut by_role = BTreeMap::new();
    let mut recommended_tuning_actions = BTreeSet::new();
    for record in records {
        *by_cause.entry(record.cause).or_insert(0) += 1;
        *by_role
            .entry(record.role.unwrap_or(ChairmanUnsafeDivergenceRole::Unknown))
            .or_insert(0) += 1;
        recommended_tuning_actions.insert(record.recommended_tuning_action);
    }
    let mut dominant_causes = by_cause.iter().collect::<Vec<_>>();
    dominant_causes.sort_by(|(left_cause, left_count), (right_cause, right_count)| {
        right_count
            .cmp(left_count)
            .then_with(|| left_cause.cmp(right_cause))
    });
    let dominant_causes = dominant_causes
        .into_iter()
        .take(3)
        .map(|(cause, _)| *cause)
        .collect::<Vec<_>>();
    let high_severity_count = records
        .iter()
        .filter(|record| record.severity == ActualVsShadowDivergenceSeverity::High)
        .count();
    ChairmanUnsafeDivergenceRootCauseSummary {
        summary_id: format!(
            "{}-root-cause-summary",
            records
                .first()
                .map(|record| record.record_id.as_str())
                .unwrap_or("shadow-governance")
        ),
        record_count: records.len(),
        high_severity_count,
        by_cause,
        by_role,
        dominant_causes,
        recommended_tuning_actions: recommended_tuning_actions.into_iter().collect(),
        summary_status: if records
            .iter()
            .all(|record| record.cause == ChairmanUnsafeDivergenceCause::InsufficientEvidence)
        {
            ChairmanUnsafeDivergenceRootCauseSummaryStatus::NeedsMoreEvidence
        } else if records.iter().all(|record| {
            record.recommended_tuning_action == ChairmanShadowTuningAction::KeepObserving
        }) {
            ChairmanUnsafeDivergenceRootCauseSummaryStatus::NoUnsafeDivergence
        } else if records.iter().all(|record| {
            matches!(
                record.cause,
                ChairmanUnsafeDivergenceCause::Unknown
                    | ChairmanUnsafeDivergenceCause::InsufficientEvidence
            )
        }) {
            ChairmanUnsafeDivergenceRootCauseSummaryStatus::Unknown
        } else {
            ChairmanUnsafeDivergenceRootCauseSummaryStatus::Actionable
        },
        paper_only: true,
    }
}

pub fn build_shadow_delta_tuning_policy(
    root_cause_summary: &ChairmanUnsafeDivergenceRootCauseSummary,
    base_policy: &ChairmanShadowGovernanceSimulationPolicy,
) -> ChairmanShadowDeltaTuningPolicy {
    let has_score_cause = root_cause_summary
        .by_cause
        .contains_key(&ChairmanUnsafeDivergenceCause::ExcessiveScoreDrift)
        || root_cause_summary
            .by_cause
            .contains_key(&ChairmanUnsafeDivergenceCause::ShadowOverReward)
        || root_cause_summary
            .by_cause
            .contains_key(&ChairmanUnsafeDivergenceCause::ShadowOverPenalty);
    let has_voice_cause = root_cause_summary
        .by_cause
        .contains_key(&ChairmanUnsafeDivergenceCause::ExcessiveVoiceDrift)
        || root_cause_summary
            .by_cause
            .contains_key(&ChairmanUnsafeDivergenceCause::RiskGuardOverDominance)
        || root_cause_summary
            .by_cause
            .contains_key(&ChairmanUnsafeDivergenceCause::TrendEntrySuppression)
        || root_cause_summary
            .by_cause
            .contains_key(&ChairmanUnsafeDivergenceCause::EvidenceRegimeUnderweight);
    ChairmanShadowDeltaTuningPolicy {
        policy_id: format!("{}-delta-tuning-policy", root_cause_summary.summary_id),
        base_score_delta_cap: base_policy.max_abs_score_delta_per_entry,
        tuned_score_delta_cap: if has_score_cause {
            (base_policy.max_abs_score_delta_per_entry * 0.7).max(0.01)
        } else {
            (base_policy.max_abs_score_delta_per_entry * 0.9).max(0.01)
        },
        base_voice_delta_cap: base_policy.max_abs_voice_delta_per_entry,
        tuned_voice_delta_cap: if has_voice_cause {
            (base_policy.max_abs_voice_delta_per_entry * 0.65).max(0.01)
        } else {
            (base_policy.max_abs_voice_delta_per_entry * 0.9).max(0.01)
        },
        risk_guard_max_voice_share: 0.45,
        trend_entry_min_voice_floor: 0.18,
        evidence_regime_min_voice_floor: 0.15,
        max_penalty_streak_per_member: 2,
        max_reward_streak_per_member: 2,
        require_min_evidence_for_high_delta: true,
        reduce_delta_on_insufficient_evidence: true,
        preserve_risk_first_bias: true,
        paper_only: true,
    }
}

pub fn build_tuned_chairman_shadow_governance_simulation_policy(
    base_policy: &ChairmanShadowGovernanceSimulationPolicy,
    tuning_policy: &ChairmanShadowDeltaTuningPolicy,
) -> Result<TunedChairmanShadowGovernanceSimulationPolicy, String> {
    if tuning_policy.tuned_score_delta_cap > tuning_policy.base_score_delta_cap
        || tuning_policy.tuned_voice_delta_cap > tuning_policy.base_voice_delta_cap
    {
        return Err(
            "chairman shadow governance tuning policy must not increase delta caps".to_string(),
        );
    }
    Ok(TunedChairmanShadowGovernanceSimulationPolicy {
        policy_id: format!("{}-tuned", tuning_policy.policy_id),
        base_policy_id: base_policy.policy_id.clone(),
        tuning_policy: tuning_policy.clone(),
        max_abs_score_delta_per_entry: tuning_policy.tuned_score_delta_cap,
        max_abs_voice_delta_per_entry: tuning_policy.tuned_voice_delta_cap,
        max_total_voice_delta_per_member: (base_policy.max_total_voice_delta_per_member
            * (tuning_policy.tuned_voice_delta_cap / tuning_policy.base_voice_delta_cap.max(1e-9)))
        .max(0.01),
        min_shadow_voice_weight: tuning_policy
            .trend_entry_min_voice_floor
            .min(tuning_policy.evidence_regime_min_voice_floor),
        max_shadow_voice_weight: tuning_policy.risk_guard_max_voice_share.clamp(
            tuning_policy
                .trend_entry_min_voice_floor
                .max(tuning_policy.evidence_regime_min_voice_floor),
            1.0,
        ),
        role_balance_enabled: true,
        risk_guard_dominance_cap_enabled: true,
        trend_entry_suppression_guard_enabled: true,
        evidence_regime_floor_enabled: true,
        actual_score_apply_allowed: false,
        actual_voice_apply_allowed: false,
        promotion_demotion_allowed: false,
        risk_governor_override_allowed: false,
        paper_only: true,
    })
}

pub fn explain_shadow_governance_policy_tuning(
    root_cause_summary: &ChairmanUnsafeDivergenceRootCauseSummary,
    tuning_policy: &ChairmanShadowDeltaTuningPolicy,
) -> ChairmanShadowPolicyTuningExplanation {
    ChairmanShadowPolicyTuningExplanation {
        explanation_id: format!("{}-explanation", tuning_policy.policy_id),
        root_cause_summary_id: root_cause_summary.summary_id.clone(),
        tuning_policy_id: tuning_policy.policy_id.clone(),
        changed_score_delta_cap: tuning_policy.tuned_score_delta_cap
            < tuning_policy.base_score_delta_cap,
        changed_voice_delta_cap: tuning_policy.tuned_voice_delta_cap
            < tuning_policy.base_voice_delta_cap,
        role_balance_changes: vec![
            format!(
                "RiskGuard max voice share capped at {:.2}",
                tuning_policy.risk_guard_max_voice_share
            ),
            format!(
                "TrendEntry min voice floor set to {:.2}",
                tuning_policy.trend_entry_min_voice_floor
            ),
            format!(
                "EvidenceRegime min voice floor set to {:.2}",
                tuning_policy.evidence_regime_min_voice_floor
            ),
        ],
        risk_first_preserved: tuning_policy.preserve_risk_first_bias,
        human_readable_summary: format!(
            "Unsafe divergence was analyzed. Shadow score cap {:.3}->{:.3} and voice cap {:.3}->{:.3} were tightened. RiskGuard dominance is capped while TrendEntry/EvidenceRegime floors preserve risk-first balance. No actual governance mutation happened.",
            tuning_policy.base_score_delta_cap,
            tuning_policy.tuned_score_delta_cap,
            tuning_policy.base_voice_delta_cap,
            tuning_policy.tuned_voice_delta_cap
        ),
        paper_only: true,
    }
}

fn apply_role_balance_to_snapshot(
    snapshot: &mut ChairmanShadowGovernanceHistorySnapshot,
    tuned_policy: &TunedChairmanShadowGovernanceSimulationPolicy,
) {
    for state in &mut snapshot.member_states {
        match state.role {
            IndependentMemberRole::RiskGuard => {
                state.shadow_voice_weight = state
                    .shadow_voice_weight
                    .min(tuned_policy.tuning_policy.risk_guard_max_voice_share);
            }
            IndependentMemberRole::TrendEntry => {
                state.shadow_voice_weight = state
                    .shadow_voice_weight
                    .max(tuned_policy.tuning_policy.trend_entry_min_voice_floor);
            }
            IndependentMemberRole::EvidenceRegime => {
                state.shadow_voice_weight = state
                    .shadow_voice_weight
                    .max(tuned_policy.tuning_policy.evidence_regime_min_voice_floor);
            }
        }
    }
    let total = snapshot
        .member_states
        .iter()
        .map(|state| state.shadow_voice_weight)
        .sum::<f64>();
    if total > f64::EPSILON {
        for state in &mut snapshot.member_states {
            state.shadow_voice_weight = clamp_unit(state.shadow_voice_weight / total);
        }
    }
}

fn apply_tuned_policy_to_history_store(
    history_store: &ChairmanShadowGovernanceHistoryStore,
    tuned_policy: &TunedChairmanShadowGovernanceSimulationPolicy,
) -> ChairmanShadowGovernanceHistoryStore {
    let score_ratio = tuned_policy.max_abs_score_delta_per_entry
        / tuned_policy.tuning_policy.base_score_delta_cap.max(1e-9);
    let voice_ratio = tuned_policy.max_abs_voice_delta_per_entry
        / tuned_policy.tuning_policy.base_voice_delta_cap.max(1e-9);
    let snapshots = history_store
        .snapshots
        .iter()
        .cloned()
        .map(|mut snapshot| {
            for state in &mut snapshot.member_states {
                state.shadow_score = clamp_unit(
                    state.actual_score_snapshot
                        + (state.shadow_score - state.actual_score_snapshot) * score_ratio,
                );
                state.shadow_voice_weight = clamp_unit(
                    state.actual_voice_weight_snapshot
                        + (state.shadow_voice_weight - state.actual_voice_weight_snapshot)
                            * voice_ratio,
                );
            }
            apply_role_balance_to_snapshot(&mut snapshot, tuned_policy);
            snapshot
        })
        .collect::<Vec<_>>();
    let mut store = ChairmanShadowGovernanceHistoryStore {
        store_id: format!("{}-tuned", history_store.store_id),
        snapshots,
        snapshot_count: 0,
        latest_snapshot_id: None,
        paper_only: true,
    };
    normalize_shadow_governance_history_store(&mut store);
    store
}

fn build_shadow_store_from_history_snapshot(
    snapshot: &ChairmanShadowGovernanceHistorySnapshot,
    store_id: String,
) -> ChairmanShadowGovernanceStateStore {
    ChairmanShadowGovernanceStateStore {
        store_id,
        member_states: snapshot.member_states.clone(),
        member_count: snapshot.member_states.len(),
        latest_run_id: Some(snapshot.run_id.clone()),
        update_count: 1,
        paper_only: true,
    }
}

fn build_harness_result_from_history_store(
    base_result: &ChairmanShadowGovernanceMultiRunHarnessResult,
    current_state_result: &ChairmanShadowGovernanceStateRunResult,
    actual_member_states: &[MemberStateSnapshot],
    history_store: ChairmanShadowGovernanceHistoryStore,
    wrote_history_store: bool,
    history_store_path: Option<String>,
) -> Result<ChairmanShadowGovernanceMultiRunHarnessResult, String> {
    let criteria = PaperGovernanceTrialCriteria {
        criteria_id: format!("{}-paper-governance-trial-criteria", base_result.run_id),
        min_history_snapshots: base_result.requested_run_count.max(1),
        ..default_paper_governance_trial_criteria()
    };
    let latest_snapshot = latest_shadow_governance_history_snapshot(&history_store)
        .ok_or_else(|| "tuned shadow governance history store requires snapshots".to_string())?;
    let shadow_store = build_shadow_store_from_history_snapshot(
        latest_snapshot,
        format!("{}-shadow-store", history_store.store_id),
    );
    let (_, summary) = compare_actual_vs_shadow_governance(actual_member_states, &shadow_store);
    let divergence =
        diagnose_actual_vs_shadow_divergence(&summary, &shadow_store, &history_store, &criteria);
    let stability = compute_shadow_governance_history_stability(&history_store);
    let gate = evaluate_paper_governance_trial_gate_v2(
        &history_store,
        &divergence,
        &stability,
        &current_state_result.apply_result,
        &criteria,
    );
    let provisional = ChairmanShadowGovernanceHistoryRunResult {
        run_id: base_result.run_id.clone(),
        accumulation_result: ChairmanShadowGovernanceHistoryAccumulationResult {
            run_id: base_result.run_id.clone(),
            previous_snapshot_count: base_result.previous_snapshot_count,
            appended_snapshot_count: history_store
                .snapshot_count
                .saturating_sub(base_result.previous_snapshot_count),
            new_snapshot_count: history_store.snapshot_count,
            latest_snapshot_id: history_store.latest_snapshot_id.clone(),
            wrote_history_store,
            accumulation_status: ChairmanShadowGovernanceHistoryAccumulationStatus::Accumulated,
            warnings: Vec::new(),
            paper_only: true,
        },
        history_store: history_store.clone(),
        divergence_diagnosis: divergence.clone(),
        stability_metrics: stability.clone(),
        trial_criteria: criteria.clone(),
        trial_gate_v2: gate.clone(),
        safety_guard: default_history_safety_guard(),
        owner_summary: None,
        run_status: ChairmanShadowGovernanceHistoryRunStatus::PassedWithWarnings,
        paper_only: true,
    };
    let safety_guard = evaluate_chairman_shadow_governance_history_safety(
        &provisional,
        current_state_result,
        actual_member_states,
        Some(actual_member_states),
        !wrote_history_store,
    );
    Ok(ChairmanShadowGovernanceMultiRunHarnessResult {
        run_id: base_result.run_id.clone(),
        requested_run_count: base_result.requested_run_count,
        completed_run_count: base_result.completed_run_count,
        previous_snapshot_count: base_result.previous_snapshot_count,
        appended_snapshot_count: history_store
            .snapshot_count
            .saturating_sub(base_result.previous_snapshot_count),
        final_snapshot_count: history_store.snapshot_count,
        wrote_history_store,
        history_store_path,
        history_store,
        per_run_results: base_result.per_run_results.clone(),
        aggregate_divergence_diagnosis: divergence,
        aggregate_stability_metrics: stability,
        aggregate_fairness_status: current_state_result
            .apply_result
            .fairness_check
            .fairness_status,
        aggregate_risk_first_status: current_state_result
            .apply_result
            .risk_first_check
            .risk_first_status,
        paper_governance_trial_gate_v2: gate.clone(),
        safety_guard: safety_guard.clone(),
        harness_status: if safety_guard.guard_status
            == ChairmanShadowGovernanceHistorySafetyGuardStatus::Violated
        {
            ChairmanShadowGovernanceMultiRunHarnessStatus::Failed
        } else if matches!(
            gate.gate_status,
            PaperGovernanceTrialGateV2Status::NeedsMoreShadowHistory
                | PaperGovernanceTrialGateV2Status::NeedsMoreEvidence
                | PaperGovernanceTrialGateV2Status::ReadyWithWarnings
        ) {
            ChairmanShadowGovernanceMultiRunHarnessStatus::PassedWithWarnings
        } else {
            ChairmanShadowGovernanceMultiRunHarnessStatus::Passed
        },
        paper_only: true,
    })
}

pub fn evaluate_chairman_role_balance(
    shadow_store: &ChairmanShadowGovernanceStateStore,
    tuning_policy: &ChairmanShadowDeltaTuningPolicy,
) -> ChairmanRoleBalanceCheck {
    let total_voice = shadow_store
        .member_states
        .iter()
        .map(|state| state.shadow_voice_weight)
        .sum::<f64>()
        .max(f64::EPSILON);
    let role_share = |role: IndependentMemberRole| {
        shadow_store
            .member_states
            .iter()
            .filter(|state| state.role == role)
            .map(|state| state.shadow_voice_weight)
            .sum::<f64>()
            / total_voice
    };
    let trend_entry_voice_share = role_share(IndependentMemberRole::TrendEntry);
    let risk_guard_voice_share = role_share(IndependentMemberRole::RiskGuard);
    let evidence_regime_voice_share = role_share(IndependentMemberRole::EvidenceRegime);
    let risk_guard_over_cap =
        risk_guard_voice_share > tuning_policy.risk_guard_max_voice_share + 0.01;
    let trend_entry_below_floor =
        trend_entry_voice_share + 0.01 < tuning_policy.trend_entry_min_voice_floor;
    let evidence_regime_below_floor =
        evidence_regime_voice_share + 0.01 < tuning_policy.evidence_regime_min_voice_floor;
    let mut warnings = Vec::new();
    if risk_guard_voice_share > tuning_policy.risk_guard_max_voice_share - 0.02 {
        warnings.push("RiskGuard voice share is close to the tuned cap".to_string());
    }
    if trend_entry_voice_share < tuning_policy.trend_entry_min_voice_floor + 0.02 {
        warnings.push("TrendEntry voice share is close to the tuned floor".to_string());
    }
    if evidence_regime_voice_share < tuning_policy.evidence_regime_min_voice_floor + 0.02 {
        warnings.push("EvidenceRegime voice share is close to the tuned floor".to_string());
    }
    ChairmanRoleBalanceCheck {
        check_id: format!("{}-role-balance", shadow_store.store_id),
        trend_entry_voice_share,
        risk_guard_voice_share,
        evidence_regime_voice_share,
        risk_guard_over_cap,
        trend_entry_below_floor,
        evidence_regime_below_floor,
        balance_status: if risk_guard_over_cap
            || trend_entry_below_floor
            || evidence_regime_below_floor
        {
            ChairmanRoleBalanceStatus::Imbalanced
        } else if warnings.is_empty() {
            ChairmanRoleBalanceStatus::Balanced
        } else {
            ChairmanRoleBalanceStatus::BalancedWithWarnings
        },
        warnings,
        paper_only: true,
    }
}

fn gate_v2_rank(status: PaperGovernanceTrialGateV2Status) -> usize {
    match status {
        PaperGovernanceTrialGateV2Status::ReadyForPaperTrialDesign => 0,
        PaperGovernanceTrialGateV2Status::ReadyWithWarnings => 1,
        PaperGovernanceTrialGateV2Status::NeedsMoreEvidence => 2,
        PaperGovernanceTrialGateV2Status::NeedsMoreShadowHistory => 3,
        PaperGovernanceTrialGateV2Status::BlockedByFairness => 4,
        PaperGovernanceTrialGateV2Status::BlockedByRiskViolation => 5,
        PaperGovernanceTrialGateV2Status::BlockedBySafety => 6,
        PaperGovernanceTrialGateV2Status::BlockedByDivergence => 7,
    }
}

pub fn recheck_paper_governance_trial_gate_after_tuning(
    previous_gate: &PaperGovernanceTrialGateV2,
    tuned_result: &TunedChairmanShadowGovernanceMultiRunResult,
    role_balance_check: &ChairmanRoleBalanceCheck,
) -> TunedPaperGovernanceTrialGateRecheck {
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    let gate_status = if tuned_result.safety_guard.guard_status
        == ChairmanShadowGovernanceMultiRunSafetyGuardStatus::Violated
    {
        blockers.push("shadow governance tuning safety guard was violated".to_string());
        TunedPaperGovernanceTrialGateRecheckStatus::BlockedBySafety
    } else if role_balance_check.balance_status == ChairmanRoleBalanceStatus::Imbalanced {
        blockers.push("shadow governance role balance remains imbalanced after tuning".to_string());
        TunedPaperGovernanceTrialGateRecheckStatus::BlockedByRoleImbalance
    } else {
        match tuned_result.readiness_v3.readiness_status {
            PaperGovernanceTrialDesignReadinessV3Status::ReadyForPaperGovernanceTrialDesign => {
                TunedPaperGovernanceTrialGateRecheckStatus::ReadyForPaperTrialDesign
            }
            PaperGovernanceTrialDesignReadinessV3Status::ReadyWithWarnings => {
                warnings
                    .push("shadow governance tuning improved readiness with warnings".to_string());
                TunedPaperGovernanceTrialGateRecheckStatus::ReadyWithWarnings
            }
            PaperGovernanceTrialDesignReadinessV3Status::NeedsMoreEvidence => {
                TunedPaperGovernanceTrialGateRecheckStatus::NeedsMoreEvidence
            }
            PaperGovernanceTrialDesignReadinessV3Status::NeedsMoreShadowHistory => {
                TunedPaperGovernanceTrialGateRecheckStatus::NeedsMoreShadowHistory
            }
            PaperGovernanceTrialDesignReadinessV3Status::BlockedByDivergence => {
                blockers
                    .push("shadow governance divergence remains unsafe after tuning".to_string());
                TunedPaperGovernanceTrialGateRecheckStatus::BlockedByDivergence
            }
            PaperGovernanceTrialDesignReadinessV3Status::BlockedByFairness => {
                TunedPaperGovernanceTrialGateRecheckStatus::BlockedByFairness
            }
            PaperGovernanceTrialDesignReadinessV3Status::BlockedByRiskViolation => {
                TunedPaperGovernanceTrialGateRecheckStatus::BlockedByRiskViolation
            }
            PaperGovernanceTrialDesignReadinessV3Status::BlockedBySafety
            | PaperGovernanceTrialDesignReadinessV3Status::BlockedByHistoryQuality => {
                TunedPaperGovernanceTrialGateRecheckStatus::BlockedBySafety
            }
        }
    };
    let mapped_rank = match gate_status {
        TunedPaperGovernanceTrialGateRecheckStatus::ReadyForPaperTrialDesign => 0,
        TunedPaperGovernanceTrialGateRecheckStatus::ReadyWithWarnings => 1,
        TunedPaperGovernanceTrialGateRecheckStatus::NeedsMoreEvidence => 2,
        TunedPaperGovernanceTrialGateRecheckStatus::NeedsMoreShadowHistory => 3,
        TunedPaperGovernanceTrialGateRecheckStatus::BlockedByRoleImbalance => 4,
        TunedPaperGovernanceTrialGateRecheckStatus::BlockedByFairness => 5,
        TunedPaperGovernanceTrialGateRecheckStatus::BlockedByRiskViolation => 6,
        TunedPaperGovernanceTrialGateRecheckStatus::BlockedBySafety => 7,
        TunedPaperGovernanceTrialGateRecheckStatus::BlockedByDivergence => 8,
    };
    TunedPaperGovernanceTrialGateRecheck {
        previous_gate_status: previous_gate.gate_status,
        tuned_gate_status: tuned_result.readiness_v3.readiness_status,
        previous_divergence_status: previous_gate.divergence_status,
        tuned_divergence_status: tuned_result.divergence_trend_summary.trend_status,
        previous_role_balance_status: None,
        tuned_role_balance_status: role_balance_check.balance_status,
        readiness_improved: mapped_rank < gate_v2_rank(previous_gate.gate_status),
        ready_for_paper_trial_design: matches!(
            gate_status,
            TunedPaperGovernanceTrialGateRecheckStatus::ReadyForPaperTrialDesign
                | TunedPaperGovernanceTrialGateRecheckStatus::ReadyWithWarnings
        ),
        gate_status,
        blockers,
        warnings,
        paper_only: true,
    }
}

fn divergence_status_from_gate_status(
    status: PaperGovernanceTrialGateV2Status,
) -> ActualVsShadowDivergenceDiagnosisStatus {
    match status {
        PaperGovernanceTrialGateV2Status::BlockedByDivergence => {
            ActualVsShadowDivergenceDiagnosisStatus::UnsafeDivergence
        }
        PaperGovernanceTrialGateV2Status::NeedsMoreShadowHistory => {
            ActualVsShadowDivergenceDiagnosisStatus::NeedsMoreHistory
        }
        PaperGovernanceTrialGateV2Status::ReadyWithWarnings
        | PaperGovernanceTrialGateV2Status::NeedsMoreEvidence => {
            ActualVsShadowDivergenceDiagnosisStatus::AcceptableWithWarnings
        }
        PaperGovernanceTrialGateV2Status::ReadyForPaperTrialDesign => {
            ActualVsShadowDivergenceDiagnosisStatus::AcceptableDivergence
        }
        PaperGovernanceTrialGateV2Status::BlockedByFairness
        | PaperGovernanceTrialGateV2Status::BlockedByRiskViolation
        | PaperGovernanceTrialGateV2Status::BlockedBySafety => {
            ActualVsShadowDivergenceDiagnosisStatus::Blocked
        }
    }
}

pub fn build_owner_shadow_governance_tuning_summary(
    tuned_result: &TunedChairmanShadowGovernanceMultiRunResult,
    gate_recheck: &TunedPaperGovernanceTrialGateRecheck,
) -> OwnerShadowGovernanceTuningSummary {
    OwnerShadowGovernanceTuningSummary {
        summary_id: format!("{}-owner-summary", tuned_result.run_id),
        root_cause_status: tuned_result.root_cause_summary.summary_status,
        dominant_causes: tuned_result.root_cause_summary.dominant_causes.clone(),
        tuning_actions: tuned_result
            .root_cause_summary
            .recommended_tuning_actions
            .clone(),
        before_gate_status: tuned_result.before_gate_status,
        after_gate_status: gate_recheck.gate_status,
        role_balance_status: gate_recheck.tuned_role_balance_status,
        readiness_improved: gate_recheck.readiness_improved,
        message: "Unsafe divergence was analyzed. Only shadow policy caps were tuned. Actual score and voice did not change. Risk-first behavior remains preserved. Paper governance trial remains gated if unsafe divergence remains."
            .to_string(),
        shadow_only: true,
        no_actual_score_mutation: true,
        no_actual_voice_mutation: true,
        no_promotion_demotion: true,
        no_risk_override: true,
        not_trade_signal: true,
        paper_only: true,
    }
}

pub fn evaluate_chairman_shadow_governance_tuning_safety(
    tuning_run_result: &ChairmanShadowGovernanceTuningRunResult,
    before_state: &ChairmanShadowGovernanceStateRunResult,
    after_state: Option<&ChairmanShadowGovernanceStateRunResult>,
) -> ChairmanShadowGovernanceTuningSafetyGuard {
    let after_state = after_state.unwrap_or(before_state);
    let actual_score_mutation_detected = before_state.safety_guard.actual_score_mutation_detected
        || after_state.safety_guard.actual_score_mutation_detected;
    let actual_voice_mutation_detected = before_state.safety_guard.actual_voice_mutation_detected
        || after_state.safety_guard.actual_voice_mutation_detected;
    let promotion_demotion_detected = before_state.safety_guard.promotion_execution_detected
        || before_state.safety_guard.demotion_execution_detected
        || after_state.safety_guard.promotion_execution_detected
        || after_state.safety_guard.demotion_execution_detected;
    let risk_governor_override_detected = before_state.safety_guard.risk_governor_override_detected
        || after_state.safety_guard.risk_governor_override_detected;
    let committee_decision_mutation_detected = before_state
        .safety_guard
        .committee_decision_mutation_detected
        || after_state
            .safety_guard
            .committee_decision_mutation_detected;
    let trade_signal_detected = before_state.safety_guard.trade_signal_detected
        || after_state.safety_guard.trade_signal_detected;
    let order_detected =
        before_state.safety_guard.order_detected || after_state.safety_guard.order_detected;
    let broker_order_account_detected = before_state.safety_guard.broker_order_account_detected
        || after_state.safety_guard.broker_order_account_detected;
    let delta_cap_increased_without_justification =
        tuning_run_result.tuned_policy.max_abs_score_delta_per_entry
            > tuning_run_result.tuning_policy.base_score_delta_cap
            || tuning_run_result.tuned_policy.max_abs_voice_delta_per_entry
                > tuning_run_result.tuning_policy.base_voice_delta_cap;
    let risk_first_disabled_detected = !tuning_run_result
        .tuned_policy
        .tuning_policy
        .preserve_risk_first_bias;
    let role_balance_disabled_detected = !tuning_run_result.tuned_policy.role_balance_enabled
        || !tuning_run_result
            .tuned_policy
            .risk_guard_dominance_cap_enabled
        || !tuning_run_result
            .tuned_policy
            .trend_entry_suppression_guard_enabled
        || !tuning_run_result.tuned_policy.evidence_regime_floor_enabled;
    let unsafe_gate_open_detected = tuning_run_result.gate_recheck.ready_for_paper_trial_design
        && matches!(
            tuning_run_result
                .tuned_multi_run_result
                .divergence_trend_summary
                .trend_status,
            ActualVsShadowDivergenceTrendStatus::Unsafe
                | ActualVsShadowDivergenceTrendStatus::Worsening
        );
    let mut violations = Vec::new();
    if actual_score_mutation_detected {
        violations.push("shadow governance tuning mutated actual score".to_string());
    }
    if actual_voice_mutation_detected {
        violations.push("shadow governance tuning mutated actual voice".to_string());
    }
    if promotion_demotion_detected {
        violations.push("shadow governance tuning executed promotion or demotion".to_string());
    }
    if risk_governor_override_detected {
        violations.push("shadow governance tuning overrode Risk Governor".to_string());
    }
    if committee_decision_mutation_detected {
        violations.push("shadow governance tuning changed committee decision".to_string());
    }
    if trade_signal_detected {
        violations.push("shadow governance tuning created a trade signal".to_string());
    }
    if order_detected {
        violations.push("shadow governance tuning created an order".to_string());
    }
    if broker_order_account_detected {
        violations.push("shadow governance tuning touched broker/order/account".to_string());
    }
    if delta_cap_increased_without_justification {
        violations.push(
            "shadow governance tuning increased delta caps without justification".to_string(),
        );
    }
    if risk_first_disabled_detected {
        violations.push("shadow governance tuning disabled risk-first behavior".to_string());
    }
    if role_balance_disabled_detected {
        violations.push("shadow governance tuning disabled role balance controls".to_string());
    }
    if unsafe_gate_open_detected {
        violations.push(
            "shadow governance tuning opened the gate while divergence stayed unsafe".to_string(),
        );
    }
    ChairmanShadowGovernanceTuningSafetyGuard {
        actual_score_mutation_detected,
        actual_voice_mutation_detected,
        promotion_demotion_detected,
        risk_governor_override_detected,
        committee_decision_mutation_detected,
        trade_signal_detected,
        order_detected,
        broker_order_account_detected,
        delta_cap_increased_without_justification,
        risk_first_disabled_detected,
        role_balance_disabled_detected,
        unsafe_gate_open_detected,
        guard_status: if violations.is_empty() {
            ChairmanShadowGovernanceTuningSafetyGuardStatus::Preserved
        } else {
            ChairmanShadowGovernanceTuningSafetyGuardStatus::Violated
        },
        violations,
        paper_only: true,
    }
}

pub fn run_tuned_chairman_shadow_governance_multi_run(
    current_shadow_state_result: &ChairmanShadowGovernanceStateRunResult,
    actual_member_states: &[MemberStateSnapshot],
    previous_history: &ChairmanShadowGovernanceHistoryStore,
    base_policy: &ChairmanShadowGovernanceSimulationPolicy,
    config: &TunedChairmanShadowGovernanceMultiRunConfig,
) -> Result<TunedChairmanShadowGovernanceMultiRunResult, String> {
    if !config.paper_only {
        return Err("tuned chairman shadow governance multi-run must stay paper_only".to_string());
    }
    if config.run_count == 0 {
        return Err(
            "tuned chairman shadow governance multi-run count must be positive".to_string(),
        );
    }
    if !config.apply_tuned_policy {
        return Err(
            "tuned chairman shadow governance multi-run requires apply_tuned_policy=true"
                .to_string(),
        );
    }
    if !config.dry_run && config.write_history_store && config.output_history_store_path.is_none() {
        return Err(
            "tuned chairman shadow governance multi-run requires output_history_store_path when write_history_store=true"
                .to_string(),
        );
    }
    if let Some(path) = config.base_history_store_path.as_ref() {
        validate_local_json_path(
            Path::new(path),
            "tuned chairman shadow governance base history store path",
        )?;
    }
    if let Some(path) = config.output_history_store_path.as_ref() {
        validate_local_json_path(
            Path::new(path),
            "tuned chairman shadow governance history output path",
        )?;
    }
    let shadow_store = current_shadow_state_result
        .shadow_store_after
        .as_ref()
        .or(current_shadow_state_result.shadow_store_before.as_ref())
        .ok_or_else(|| "shadow governance tuning requires current shadow store".to_string())?;
    let criteria = PaperGovernanceTrialCriteria {
        criteria_id: format!("{}-paper-governance-trial-criteria", config.run_id),
        min_history_snapshots: config.run_count.max(1),
        ..default_paper_governance_trial_criteria()
    };
    let previous_diagnosis = diagnose_actual_vs_shadow_divergence(
        &current_shadow_state_result.actual_vs_shadow_summary,
        shadow_store,
        previous_history,
        &criteria,
    );
    let previous_stability = compute_shadow_governance_history_stability(previous_history);
    let previous_gate = evaluate_paper_governance_trial_gate_v2(
        previous_history,
        &previous_diagnosis,
        &previous_stability,
        &current_shadow_state_result.apply_result,
        &criteria,
    );
    let root_cause_records = analyze_unsafe_governance_divergence_causes(
        &previous_diagnosis,
        previous_history,
        base_policy,
    );
    let root_cause_summary = summarize_unsafe_governance_divergence_causes(&root_cause_records);
    let tuning_policy = build_shadow_delta_tuning_policy(&root_cause_summary, base_policy);
    let tuned_policy =
        build_tuned_chairman_shadow_governance_simulation_policy(base_policy, &tuning_policy)?;
    let tuning_explanation =
        explain_shadow_governance_policy_tuning(&root_cause_summary, &tuning_policy);
    let base_harness_result = run_chairman_shadow_governance_multi_run_harness(
        current_shadow_state_result,
        actual_member_states,
        &ChairmanShadowGovernanceMultiRunHarnessConfig {
            run_id: config.run_id.clone(),
            enabled: config.enabled,
            run_count: config.run_count,
            min_snapshots_required: config.run_count.max(1),
            history_store_input_path: config.base_history_store_path.clone(),
            history_store_output_path: config.output_history_store_path.clone(),
            simulation_ledger_input_path: None,
            simulation_ledger_output_path: None,
            output_path: None,
            dry_run: true,
            write_history_store: false,
            emit_owner_summary: false,
            paper_only: true,
        },
    )?;
    let tuned_history_store =
        apply_tuned_policy_to_history_store(&base_harness_result.history_store, &tuned_policy);
    let mut wrote_history_store = false;
    if !config.dry_run && config.write_history_store {
        if let Some(path) = config.output_history_store_path.as_ref() {
            save_chairman_shadow_governance_history_store_to_local_json(
                Path::new(path),
                &tuned_history_store,
            )?;
            wrote_history_store = true;
        }
    }
    let tuned_harness_result = build_harness_result_from_history_store(
        &base_harness_result,
        current_shadow_state_result,
        actual_member_states,
        tuned_history_store,
        wrote_history_store,
        config.output_history_store_path.clone(),
    )?;
    let placeholder = PaperGovernanceTrialDesignReadinessV3 {
        readiness_id: format!("{}-placeholder", config.run_id),
        history_quality_status: ShadowGovernanceHistoryQualityStatus::Valid,
        divergence_trend_status: ActualVsShadowDivergenceTrendStatus::InsufficientHistory,
        stability_status: tuned_harness_result
            .aggregate_stability_metrics
            .stability_status,
        fairness_status: current_shadow_state_result
            .apply_result
            .fairness_check
            .fairness_status,
        risk_first_status: current_shadow_state_result
            .apply_result
            .risk_first_check
            .risk_first_status,
        safety_status: ChairmanShadowGovernanceMultiRunSafetyGuardStatus::Preserved,
        min_history_met: false,
        divergence_reducing_or_stable: false,
        fairness_ok: false,
        risk_first_ok: false,
        safety_ok: false,
        ready_for_paper_governance_trial_design: false,
        readiness_status: PaperGovernanceTrialDesignReadinessV3Status::NeedsMoreShadowHistory,
        blockers: Vec::new(),
        warnings: Vec::new(),
        paper_only: true,
    };
    let provisional_safety = evaluate_chairman_shadow_governance_multi_run_safety(
        &tuned_harness_result,
        &placeholder,
        current_shadow_state_result,
        actual_member_states,
        Some(actual_member_states),
        config.dry_run,
    );
    let divergence_trend_summary =
        summarize_actual_vs_shadow_divergence_trend(&tuned_harness_result.history_store);
    let history_quality_check = check_shadow_governance_history_quality(
        &tuned_harness_result.history_store,
        config.run_count.max(1),
    );
    let readiness_v3 = evaluate_paper_governance_trial_design_readiness_v3(
        &history_quality_check,
        &divergence_trend_summary,
        &tuned_harness_result.aggregate_stability_metrics,
        &current_shadow_state_result.apply_result,
        &provisional_safety,
        config.run_count.max(1),
    );
    let safety_guard = evaluate_chairman_shadow_governance_multi_run_safety(
        &tuned_harness_result,
        &readiness_v3,
        current_shadow_state_result,
        actual_member_states,
        Some(actual_member_states),
        config.dry_run,
    );
    let before_rank = gate_v2_rank(previous_gate.gate_status);
    let after_rank = match readiness_v3.readiness_status {
        PaperGovernanceTrialDesignReadinessV3Status::ReadyForPaperGovernanceTrialDesign => 0,
        PaperGovernanceTrialDesignReadinessV3Status::ReadyWithWarnings => 1,
        PaperGovernanceTrialDesignReadinessV3Status::NeedsMoreEvidence => 2,
        PaperGovernanceTrialDesignReadinessV3Status::NeedsMoreShadowHistory => 3,
        PaperGovernanceTrialDesignReadinessV3Status::BlockedByFairness => 4,
        PaperGovernanceTrialDesignReadinessV3Status::BlockedByRiskViolation => 5,
        PaperGovernanceTrialDesignReadinessV3Status::BlockedBySafety => 6,
        PaperGovernanceTrialDesignReadinessV3Status::BlockedByHistoryQuality => 7,
        PaperGovernanceTrialDesignReadinessV3Status::BlockedByDivergence => 8,
    };
    Ok(TunedChairmanShadowGovernanceMultiRunResult {
        run_id: config.run_id.clone(),
        root_cause_summary,
        tuning_policy,
        tuned_policy,
        tuning_explanation,
        multi_run_harness_result: tuned_harness_result,
        divergence_trend_summary,
        readiness_v3: readiness_v3.clone(),
        before_gate_status: previous_gate.gate_status,
        after_gate_status: readiness_v3.readiness_status,
        improvement_status: if safety_guard.guard_status
            == ChairmanShadowGovernanceMultiRunSafetyGuardStatus::Violated
        {
            TunedChairmanShadowGovernanceImprovementStatus::Blocked
        } else if after_rank < before_rank {
            if matches!(
                readiness_v3.readiness_status,
                PaperGovernanceTrialDesignReadinessV3Status::ReadyWithWarnings
                    | PaperGovernanceTrialDesignReadinessV3Status::NeedsMoreEvidence
            ) {
                TunedChairmanShadowGovernanceImprovementStatus::ImprovedWithWarnings
            } else {
                TunedChairmanShadowGovernanceImprovementStatus::Improved
            }
        } else if after_rank == before_rank {
            TunedChairmanShadowGovernanceImprovementStatus::NoChange
        } else {
            TunedChairmanShadowGovernanceImprovementStatus::Worse
        },
        safety_guard,
        paper_only: true,
    })
}

pub fn chairman_shadow_governance_tuning_requested_from_flags(
    enabled: bool,
    dry_run: bool,
    tuned_history_output_path: Option<&String>,
    tuning_result_output_path: Option<&String>,
    write_tuned_history: bool,
) -> bool {
    enabled
        || !dry_run
        || tuned_history_output_path.is_some()
        || tuning_result_output_path.is_some()
        || write_tuned_history
}

pub fn run_chairman_shadow_governance_tuning(
    current_shadow_state_result: &ChairmanShadowGovernanceStateRunResult,
    actual_member_states: &[MemberStateSnapshot],
    previous_history: &ChairmanShadowGovernanceHistoryStore,
    config: &ChairmanShadowGovernanceTuningRunConfig,
) -> Result<ChairmanShadowGovernanceTuningRunResult, String> {
    if !config.paper_only {
        return Err("chairman shadow governance tuning run must stay paper_only".to_string());
    }
    if config.run_count == 0 {
        return Err("chairman shadow governance tuning run count must be positive".to_string());
    }
    if !config.dry_run
        && config.write_tuned_history
        && config.tuned_history_store_output_path.is_none()
    {
        return Err(
            "chairman shadow governance tuning run requires tuned_history_store_output_path when write_tuned_history=true"
                .to_string(),
        );
    }
    if let Some(path) = config.base_history_store_path.as_ref() {
        validate_local_json_path(
            Path::new(path),
            "chairman shadow governance tuning base history store path",
        )?;
    }
    if let Some(path) = config.tuned_history_store_output_path.as_ref() {
        validate_local_json_path(
            Path::new(path),
            "chairman shadow governance tuning tuned history output path",
        )?;
    }
    if let Some(path) = config.tuning_result_output_path.as_ref() {
        validate_local_json_path(
            Path::new(path),
            "chairman shadow governance tuning result output path",
        )?;
    }
    let tuned_multi_run_result = run_tuned_chairman_shadow_governance_multi_run(
        current_shadow_state_result,
        actual_member_states,
        previous_history,
        &default_chairman_shadow_governance_simulation_policy(),
        &TunedChairmanShadowGovernanceMultiRunConfig {
            run_id: config.run_id.clone(),
            enabled: config.enabled,
            run_count: config.run_count,
            base_history_store_path: config.base_history_store_path.clone(),
            output_history_store_path: config.tuned_history_store_output_path.clone(),
            dry_run: config.dry_run,
            write_history_store: config.write_tuned_history,
            apply_tuned_policy: true,
            paper_only: true,
        },
    )?;
    let latest_snapshot = latest_shadow_governance_history_snapshot(
        &tuned_multi_run_result
            .multi_run_harness_result
            .history_store,
    )
    .ok_or_else(|| "shadow governance tuning requires tuned history snapshots".to_string())?;
    let shadow_store = build_shadow_store_from_history_snapshot(
        latest_snapshot,
        format!("{}-tuned-shadow-store", config.run_id),
    );
    let role_balance_check =
        evaluate_chairman_role_balance(&shadow_store, &tuned_multi_run_result.tuning_policy);
    let previous_gate = PaperGovernanceTrialGateV2 {
        gate_id: format!("{}-previous-gate", config.run_id),
        history_snapshot_count: previous_history.snapshot_count,
        min_history_snapshots: config.run_count.max(1),
        divergence_status: divergence_status_from_gate_status(
            tuned_multi_run_result.before_gate_status,
        ),
        stability_status: ShadowGovernanceHistoryStabilityStatus::Stable,
        fairness_status: current_shadow_state_result
            .apply_result
            .fairness_check
            .fairness_status,
        risk_first_status: current_shadow_state_result
            .apply_result
            .risk_first_check
            .risk_first_status,
        safety_status: ChairmanShadowGovernanceApplySafetyGuardStatus::Preserved,
        ready_for_paper_governance_trial: false,
        trial_allowed_operations: vec![PaperGovernanceTrialAllowedOperation::None],
        forbidden_operations: vec![
            PaperGovernanceTrialForbiddenOperation::ActualScoreMutation,
            PaperGovernanceTrialForbiddenOperation::ActualVoiceMutation,
            PaperGovernanceTrialForbiddenOperation::PromotionDemotionExecution,
            PaperGovernanceTrialForbiddenOperation::RiskGovernorOverride,
            PaperGovernanceTrialForbiddenOperation::CommitteeDecisionMutation,
            PaperGovernanceTrialForbiddenOperation::TradingOrderAccount,
        ],
        gate_status: tuned_multi_run_result.before_gate_status,
        blockers: Vec::new(),
        warnings: Vec::new(),
        paper_only: true,
    };
    let gate_recheck = recheck_paper_governance_trial_gate_after_tuning(
        &previous_gate,
        &tuned_multi_run_result,
        &role_balance_check,
    );
    let mut result = ChairmanShadowGovernanceTuningRunResult {
        run_id: config.run_id.clone(),
        root_cause_summary: tuned_multi_run_result.root_cause_summary.clone(),
        tuning_policy: tuned_multi_run_result.tuning_policy.clone(),
        tuned_policy: tuned_multi_run_result.tuned_policy.clone(),
        tuning_explanation: tuned_multi_run_result.tuning_explanation.clone(),
        tuned_multi_run_result,
        role_balance_check,
        gate_recheck,
        owner_summary: None,
        tuning_safety_guard: ChairmanShadowGovernanceTuningSafetyGuard {
            actual_score_mutation_detected: false,
            actual_voice_mutation_detected: false,
            promotion_demotion_detected: false,
            risk_governor_override_detected: false,
            committee_decision_mutation_detected: false,
            trade_signal_detected: false,
            order_detected: false,
            broker_order_account_detected: false,
            delta_cap_increased_without_justification: false,
            risk_first_disabled_detected: false,
            role_balance_disabled_detected: false,
            unsafe_gate_open_detected: false,
            guard_status: ChairmanShadowGovernanceTuningSafetyGuardStatus::Preserved,
            violations: Vec::new(),
            paper_only: true,
        },
        run_status: ChairmanShadowGovernanceTuningRunStatus::PassedWithWarnings,
        paper_only: true,
    };
    result.tuning_safety_guard = evaluate_chairman_shadow_governance_tuning_safety(
        &result,
        current_shadow_state_result,
        Some(current_shadow_state_result),
    );
    if config.emit_owner_summary {
        result.owner_summary = Some(build_owner_shadow_governance_tuning_summary(
            &result.tuned_multi_run_result,
            &result.gate_recheck,
        ));
    }
    result.run_status = if result.tuning_safety_guard.guard_status
        == ChairmanShadowGovernanceTuningSafetyGuardStatus::Violated
    {
        ChairmanShadowGovernanceTuningRunStatus::Failed
    } else if config.dry_run
        || !result.gate_recheck.readiness_improved
        || matches!(
            result.gate_recheck.gate_status,
            TunedPaperGovernanceTrialGateRecheckStatus::ReadyWithWarnings
                | TunedPaperGovernanceTrialGateRecheckStatus::NeedsMoreEvidence
                | TunedPaperGovernanceTrialGateRecheckStatus::NeedsMoreShadowHistory
        )
    {
        ChairmanShadowGovernanceTuningRunStatus::PassedWithWarnings
    } else {
        ChairmanShadowGovernanceTuningRunStatus::Passed
    };
    if !config.dry_run {
        if let Some(path) = config.tuning_result_output_path.as_ref() {
            write_safe_json(Path::new(path), &result)?;
        }
    }
    Ok(result)
}

fn maybe_run_chairman_shadow_governance_tuning_for_batch_result(
    run_id: String,
    enabled: bool,
    dry_run: bool,
    run_count: usize,
    base_history_store_path: Option<&String>,
    tuned_history_store_output_path: Option<&String>,
    tuning_result_output_path: Option<&String>,
    write_tuned_history: bool,
    emit_owner_summary: bool,
    actual_member_states: &[MemberStateSnapshot],
    batch_result: &mut BatchCommitteeCycleResult,
) -> Result<Option<ChairmanShadowGovernanceTuningRunResult>, String> {
    if !chairman_shadow_governance_tuning_requested_from_flags(
        enabled,
        dry_run,
        tuned_history_store_output_path,
        tuning_result_output_path,
        write_tuned_history,
    ) {
        return Ok(None);
    }
    let current_state_result = batch_result
        .chairman_shadow_governance_state_run_result
        .clone()
        .ok_or_else(|| {
            "chairman shadow governance tuning requires current shadow governance state result"
                .to_string()
        })?;
    let previous_history = if let Some(path) = base_history_store_path {
        if Path::new(path).exists() {
            load_chairman_shadow_governance_history_store_from_local_json(Path::new(path))?
        } else {
            batch_result
                .chairman_shadow_governance_history_store
                .clone()
                .unwrap_or(ChairmanShadowGovernanceHistoryStore {
                    store_id: format!("{}-history-store", run_id),
                    snapshots: Vec::new(),
                    snapshot_count: 0,
                    latest_snapshot_id: None,
                    paper_only: true,
                })
        }
    } else {
        batch_result
            .chairman_shadow_governance_history_store
            .clone()
            .unwrap_or(ChairmanShadowGovernanceHistoryStore {
                store_id: format!("{}-history-store", run_id),
                snapshots: Vec::new(),
                snapshot_count: 0,
                latest_snapshot_id: None,
                paper_only: true,
            })
    };
    let result = run_chairman_shadow_governance_tuning(
        &current_state_result,
        actual_member_states,
        &previous_history,
        &ChairmanShadowGovernanceTuningRunConfig {
            run_id,
            enabled,
            base_history_store_path: base_history_store_path.cloned(),
            tuned_history_store_output_path: tuned_history_store_output_path.cloned(),
            tuning_result_output_path: tuning_result_output_path.cloned(),
            run_count,
            dry_run,
            write_tuned_history,
            emit_owner_summary,
            paper_only: true,
        },
    )?;
    batch_result.chairman_unsafe_divergence_root_cause_summary =
        Some(result.root_cause_summary.clone());
    batch_result.chairman_shadow_delta_tuning_policy = Some(result.tuning_policy.clone());
    batch_result.tuned_chairman_shadow_governance_simulation_policy =
        Some(result.tuned_policy.clone());
    batch_result.chairman_shadow_policy_tuning_explanation =
        Some(result.tuning_explanation.clone());
    batch_result.tuned_chairman_shadow_governance_multi_run_result =
        Some(result.tuned_multi_run_result.clone());
    batch_result.chairman_shadow_governance_history_store = Some(
        result
            .tuned_multi_run_result
            .multi_run_harness_result
            .history_store
            .clone(),
    );
    batch_result.actual_vs_shadow_divergence_trend_summary = Some(
        result
            .tuned_multi_run_result
            .divergence_trend_summary
            .clone(),
    );
    batch_result.paper_governance_trial_design_readiness_v3 =
        Some(result.tuned_multi_run_result.readiness_v3.clone());
    batch_result.chairman_role_balance_check = Some(result.role_balance_check.clone());
    batch_result.tuned_paper_governance_trial_gate_recheck = Some(result.gate_recheck.clone());
    batch_result.owner_shadow_governance_tuning_summary = result.owner_summary.clone();
    batch_result.chairman_shadow_governance_tuning_safety_guard =
        Some(result.tuning_safety_guard.clone());
    batch_result.chairman_shadow_governance_tuning_run_result = Some(result.clone());
    Ok(Some(result))
}

fn paper_governance_gate_status_from_readiness_v3(
    status: PaperGovernanceTrialDesignReadinessV3Status,
) -> PaperGovernanceTrialGateV2Status {
    match status {
        PaperGovernanceTrialDesignReadinessV3Status::ReadyForPaperGovernanceTrialDesign => {
            PaperGovernanceTrialGateV2Status::ReadyForPaperTrialDesign
        }
        PaperGovernanceTrialDesignReadinessV3Status::ReadyWithWarnings => {
            PaperGovernanceTrialGateV2Status::ReadyWithWarnings
        }
        PaperGovernanceTrialDesignReadinessV3Status::NeedsMoreShadowHistory
        | PaperGovernanceTrialDesignReadinessV3Status::BlockedByHistoryQuality => {
            PaperGovernanceTrialGateV2Status::NeedsMoreShadowHistory
        }
        PaperGovernanceTrialDesignReadinessV3Status::NeedsMoreEvidence => {
            PaperGovernanceTrialGateV2Status::NeedsMoreEvidence
        }
        PaperGovernanceTrialDesignReadinessV3Status::BlockedByDivergence => {
            PaperGovernanceTrialGateV2Status::BlockedByDivergence
        }
        PaperGovernanceTrialDesignReadinessV3Status::BlockedByFairness => {
            PaperGovernanceTrialGateV2Status::BlockedByFairness
        }
        PaperGovernanceTrialDesignReadinessV3Status::BlockedByRiskViolation => {
            PaperGovernanceTrialGateV2Status::BlockedByRiskViolation
        }
        PaperGovernanceTrialDesignReadinessV3Status::BlockedBySafety => {
            PaperGovernanceTrialGateV2Status::BlockedBySafety
        }
    }
}

fn conservative_voice_tuned_gate_rank(status: ConservativeVoiceTunedGateRecheckV2Status) -> usize {
    match status {
        ConservativeVoiceTunedGateRecheckV2Status::ReadyForPaperTrialDesign => 0,
        ConservativeVoiceTunedGateRecheckV2Status::ReadyWithWarnings => 1,
        ConservativeVoiceTunedGateRecheckV2Status::NeedsMoreEvidence => 2,
        ConservativeVoiceTunedGateRecheckV2Status::NeedsMoreShadowHistory => 3,
        ConservativeVoiceTunedGateRecheckV2Status::BlockedByRoleFloor => 4,
        ConservativeVoiceTunedGateRecheckV2Status::BlockedByFairness => 5,
        ConservativeVoiceTunedGateRecheckV2Status::BlockedByRiskViolation => 6,
        ConservativeVoiceTunedGateRecheckV2Status::BlockedBySafety => 7,
        ConservativeVoiceTunedGateRecheckV2Status::BlockedByDivergence => 8,
    }
}

fn role_voice_share(
    snapshot: &ChairmanShadowGovernanceHistorySnapshot,
    role: IndependentMemberRole,
) -> f64 {
    let total_voice = snapshot
        .member_states
        .iter()
        .map(|state| state.shadow_voice_weight)
        .sum::<f64>()
        .max(f64::EPSILON);
    snapshot
        .member_states
        .iter()
        .filter(|state| state.role == role)
        .map(|state| state.shadow_voice_weight)
        .sum::<f64>()
        / total_voice
}

fn first_member_for_role(
    snapshot: &ChairmanShadowGovernanceHistorySnapshot,
    role: IndependentMemberRole,
) -> Option<&ChairmanShadowMemberGovernanceState> {
    snapshot
        .member_states
        .iter()
        .find(|state| state.role == role)
}

fn summarize_remaining_voice_drift_records(
    analysis_id: String,
    mut records: Vec<RemainingVoiceDriftRecord>,
) -> RemainingVoiceDriftAnalysisResult {
    records.sort_by(|left, right| left.record_id.cmp(&right.record_id));
    let mut dominant_causes = BTreeMap::new();
    let mut recommended_actions = BTreeSet::new();
    for record in &records {
        *dominant_causes.entry(record.cause).or_insert(0usize) += 1;
        recommended_actions.insert(record.recommended_action);
    }
    let mut ranked_causes = dominant_causes.into_iter().collect::<Vec<_>>();
    ranked_causes.sort_by(|(left_cause, left_count), (right_cause, right_count)| {
        right_count
            .cmp(left_count)
            .then_with(|| left_cause.cmp(right_cause))
    });
    let dominant_causes = ranked_causes
        .into_iter()
        .take(3)
        .map(|(cause, _)| cause)
        .collect::<Vec<_>>();
    let high_severity_count = records
        .iter()
        .filter(|record| record.severity == ActualVsShadowDivergenceSeverity::High)
        .count();
    let record_count = records.len();
    let analysis_status = if records.is_empty() {
        RemainingVoiceDriftAnalysisStatus::NoUnsafeVoiceDrift
    } else if records
        .iter()
        .all(|record| record.cause == RemainingVoiceDriftCause::InsufficientHistory)
    {
        RemainingVoiceDriftAnalysisStatus::NeedsMoreEvidence
    } else if records.iter().all(|record| {
        matches!(
            record.cause,
            RemainingVoiceDriftCause::Unknown | RemainingVoiceDriftCause::MixedSignalHistory
        )
    }) {
        RemainingVoiceDriftAnalysisStatus::Unknown
    } else {
        RemainingVoiceDriftAnalysisStatus::Actionable
    };
    RemainingVoiceDriftAnalysisResult {
        analysis_id,
        records,
        record_count,
        high_severity_count,
        dominant_causes,
        recommended_actions: if recommended_actions.is_empty() {
            vec![RemainingVoiceDriftRecommendedAction::KeepObserving]
        } else {
            recommended_actions.into_iter().collect()
        },
        analysis_status,
        paper_only: true,
    }
}

pub fn analyze_remaining_voice_drift_after_tuning(
    tuned_result: &TunedChairmanShadowGovernanceMultiRunResult,
    previous_history: &ChairmanShadowGovernanceHistoryStore,
    policy: &ChairmanShadowDeltaTuningPolicy,
) -> RemainingVoiceDriftAnalysisResult {
    let analysis_id = format!("{}-remaining-voice-drift", tuned_result.run_id);
    let Some(latest_snapshot) = latest_shadow_governance_history_snapshot(
        &tuned_result.multi_run_harness_result.history_store,
    ) else {
        return summarize_remaining_voice_drift_records(
            analysis_id,
            vec![RemainingVoiceDriftRecord {
                record_id: format!("{}-insufficient-history", tuned_result.run_id),
                member_id: None,
                role: None,
                cause: RemainingVoiceDriftCause::InsufficientHistory,
                observed_voice_gap: 0.0,
                observed_voice_share: None,
                severity: ActualVsShadowDivergenceSeverity::Low,
                recommended_action: RemainingVoiceDriftRecommendedAction::RequireMoreEvidence,
                paper_only: true,
            }],
        );
    };
    let mut records = Vec::new();
    let snapshot_count = tuned_result
        .multi_run_harness_result
        .history_store
        .snapshot_count;
    let trend_share = role_voice_share(latest_snapshot, IndependentMemberRole::TrendEntry);
    let risk_share = role_voice_share(latest_snapshot, IndependentMemberRole::RiskGuard);
    let evidence_share = role_voice_share(latest_snapshot, IndependentMemberRole::EvidenceRegime);
    if snapshot_count
        < tuned_result
            .multi_run_harness_result
            .requested_run_count
            .max(2)
    {
        records.push(RemainingVoiceDriftRecord {
            record_id: format!("{}-insufficient-history", tuned_result.run_id),
            member_id: None,
            role: None,
            cause: RemainingVoiceDriftCause::InsufficientHistory,
            observed_voice_gap: latest_snapshot.actual_vs_shadow_summary.max_voice_gap,
            observed_voice_share: None,
            severity: ActualVsShadowDivergenceSeverity::Medium,
            recommended_action: RemainingVoiceDriftRecommendedAction::RequireMoreEvidence,
            paper_only: true,
        });
    }
    if risk_share > policy.risk_guard_max_voice_share + 0.02 {
        records.push(RemainingVoiceDriftRecord {
            record_id: format!("{}-risk-guard-dominance", tuned_result.run_id),
            member_id: first_member_for_role(latest_snapshot, IndependentMemberRole::RiskGuard)
                .map(|state| state.member_id.clone()),
            role: Some(ChairmanUnsafeDivergenceRole::RiskGuard),
            cause: RemainingVoiceDriftCause::RiskGuardOverDominance,
            observed_voice_gap: risk_share - policy.risk_guard_max_voice_share,
            observed_voice_share: Some(risk_share),
            severity: ActualVsShadowDivergenceSeverity::High,
            recommended_action: RemainingVoiceDriftRecommendedAction::LowerRiskGuardCap,
            paper_only: true,
        });
    }
    if trend_share + 0.01 < policy.trend_entry_min_voice_floor {
        records.push(RemainingVoiceDriftRecord {
            record_id: format!("{}-trend-entry-floor", tuned_result.run_id),
            member_id: first_member_for_role(latest_snapshot, IndependentMemberRole::TrendEntry)
                .map(|state| state.member_id.clone()),
            role: Some(ChairmanUnsafeDivergenceRole::TrendEntry),
            cause: RemainingVoiceDriftCause::TrendEntrySuppression,
            observed_voice_gap: trend_share - policy.trend_entry_min_voice_floor,
            observed_voice_share: Some(trend_share),
            severity: ActualVsShadowDivergenceSeverity::High,
            recommended_action: RemainingVoiceDriftRecommendedAction::RaiseTrendEntryFloor,
            paper_only: true,
        });
    }
    if evidence_share + 0.01 < policy.evidence_regime_min_voice_floor {
        records.push(RemainingVoiceDriftRecord {
            record_id: format!("{}-evidence-floor", tuned_result.run_id),
            member_id: first_member_for_role(
                latest_snapshot,
                IndependentMemberRole::EvidenceRegime,
            )
            .map(|state| state.member_id.clone()),
            role: Some(ChairmanUnsafeDivergenceRole::EvidenceRegime),
            cause: RemainingVoiceDriftCause::EvidenceRegimeUnderweight,
            observed_voice_gap: evidence_share - policy.evidence_regime_min_voice_floor,
            observed_voice_share: Some(evidence_share),
            severity: ActualVsShadowDivergenceSeverity::High,
            recommended_action: RemainingVoiceDriftRecommendedAction::RaiseEvidenceRegimeFloor,
            paper_only: true,
        });
    }
    if let Some(compounding_state) = latest_snapshot.member_states.iter().max_by_key(|state| {
        state
            .shadow_voice_increase_count
            .max(state.shadow_voice_decrease_count)
    }) {
        if compounding_state.shadow_voice_increase_count > policy.max_reward_streak_per_member
            || compounding_state.shadow_voice_decrease_count > policy.max_penalty_streak_per_member
        {
            records.push(RemainingVoiceDriftRecord {
                record_id: format!("{}-compounding-brake", compounding_state.member_id),
                member_id: Some(compounding_state.member_id.clone()),
                role: Some(match compounding_state.role {
                    IndependentMemberRole::TrendEntry => ChairmanUnsafeDivergenceRole::TrendEntry,
                    IndependentMemberRole::RiskGuard => ChairmanUnsafeDivergenceRole::RiskGuard,
                    IndependentMemberRole::EvidenceRegime => {
                        ChairmanUnsafeDivergenceRole::EvidenceRegime
                    }
                }),
                cause: RemainingVoiceDriftCause::RepeatedVoiceDeltaCompounding,
                observed_voice_gap: compounding_state.shadow_voice_weight
                    - compounding_state.actual_voice_weight_snapshot,
                observed_voice_share: Some(compounding_state.shadow_voice_weight),
                severity: if compounding_state.shadow_voice_increase_count
                    >= policy.max_reward_streak_per_member + 2
                    || compounding_state.shadow_voice_decrease_count
                        >= policy.max_penalty_streak_per_member + 2
                {
                    ActualVsShadowDivergenceSeverity::High
                } else {
                    ActualVsShadowDivergenceSeverity::Medium
                },
                recommended_action: RemainingVoiceDriftRecommendedAction::AddCompoundingBrake,
                paper_only: true,
            });
        }
    }
    if tuned_result.divergence_trend_summary.trend_status
        == ActualVsShadowDivergenceTrendStatus::Unsafe
        || tuned_result.divergence_trend_summary.trend_status
            == ActualVsShadowDivergenceTrendStatus::Worsening
        || latest_snapshot.actual_vs_shadow_summary.max_voice_gap
            > policy.tuned_voice_delta_cap + 0.02
    {
        records.push(RemainingVoiceDriftRecord {
            record_id: format!("{}-voice-cap", tuned_result.run_id),
            member_id: None,
            role: None,
            cause: RemainingVoiceDriftCause::VoiceCapStillTooHigh,
            observed_voice_gap: latest_snapshot.actual_vs_shadow_summary.max_voice_gap,
            observed_voice_share: None,
            severity: ActualVsShadowDivergenceSeverity::Medium,
            recommended_action: RemainingVoiceDriftRecommendedAction::ReduceVoiceCapAgain,
            paper_only: true,
        });
    }
    if latest_snapshot.actual_vs_shadow_summary.max_voice_gap > policy.tuned_voice_delta_cap + 0.02
        && previous_history.snapshot_count
            < tuned_result.multi_run_harness_result.requested_run_count
    {
        records.push(RemainingVoiceDriftRecord {
            record_id: format!("{}-low-evidence-high-delta", tuned_result.run_id),
            member_id: None,
            role: None,
            cause: RemainingVoiceDriftCause::LowEvidenceHighDelta,
            observed_voice_gap: latest_snapshot.actual_vs_shadow_summary.max_voice_gap,
            observed_voice_share: None,
            severity: ActualVsShadowDivergenceSeverity::Medium,
            recommended_action: RemainingVoiceDriftRecommendedAction::RequireMoreEvidence,
            paper_only: true,
        });
    }
    if (trend_share + risk_share + evidence_share - 1.0).abs() > 0.05 || risk_share + 0.01 < 0.18 {
        records.push(RemainingVoiceDriftRecord {
            record_id: format!("{}-role-floor-imbalance", tuned_result.run_id),
            member_id: None,
            role: None,
            cause: RemainingVoiceDriftCause::RoleFloorImbalance,
            observed_voice_gap: trend_share + risk_share + evidence_share - 1.0,
            observed_voice_share: None,
            severity: ActualVsShadowDivergenceSeverity::Medium,
            recommended_action: RemainingVoiceDriftRecommendedAction::KeepObserving,
            paper_only: true,
        });
    }
    if tuned_result.divergence_trend_summary.reducing_count > 0
        && tuned_result.divergence_trend_summary.increasing_count > 0
    {
        records.push(RemainingVoiceDriftRecord {
            record_id: format!("{}-mixed-signal-history", tuned_result.run_id),
            member_id: None,
            role: None,
            cause: RemainingVoiceDriftCause::MixedSignalHistory,
            observed_voice_gap: latest_snapshot.actual_vs_shadow_summary.max_voice_gap,
            observed_voice_share: None,
            severity: ActualVsShadowDivergenceSeverity::Low,
            recommended_action: RemainingVoiceDriftRecommendedAction::RequireMoreEvidence,
            paper_only: true,
        });
    }
    summarize_remaining_voice_drift_records(analysis_id, records)
}

pub fn build_conservative_voice_tuning_v2_policy(
    remaining_voice_drift_analysis: &RemainingVoiceDriftAnalysisResult,
    previous_tuning_policy: &ChairmanShadowDeltaTuningPolicy,
) -> Result<ConservativeVoiceTuningV2Policy, String> {
    let actionable = remaining_voice_drift_analysis.analysis_status
        == RemainingVoiceDriftAnalysisStatus::Actionable;
    let reduce_voice_cap = actionable
        || remaining_voice_drift_analysis
            .recommended_actions
            .contains(&RemainingVoiceDriftRecommendedAction::ReduceVoiceCapAgain);
    let lower_risk_guard_cap = remaining_voice_drift_analysis
        .dominant_causes
        .contains(&RemainingVoiceDriftCause::RiskGuardOverDominance);
    let raise_trend_floor = remaining_voice_drift_analysis
        .dominant_causes
        .contains(&RemainingVoiceDriftCause::TrendEntrySuppression);
    let raise_evidence_floor = remaining_voice_drift_analysis
        .dominant_causes
        .iter()
        .any(|cause| {
            matches!(
                cause,
                RemainingVoiceDriftCause::EvidenceRegimeUnderweight
                    | RemainingVoiceDriftCause::LowEvidenceHighDelta
            )
        });
    let policy = ConservativeVoiceTuningV2Policy {
        policy_id: format!(
            "{}-voice-tuning-v2",
            remaining_voice_drift_analysis.analysis_id
        ),
        previous_voice_delta_cap: previous_tuning_policy.tuned_voice_delta_cap,
        tuned_voice_delta_cap_v2: if reduce_voice_cap {
            (previous_tuning_policy.tuned_voice_delta_cap * 0.8).max(0.005)
        } else {
            (previous_tuning_policy.tuned_voice_delta_cap * 0.92).max(0.005)
        },
        risk_guard_min_voice_share: 0.20,
        risk_guard_max_voice_share: if lower_risk_guard_cap {
            (previous_tuning_policy.risk_guard_max_voice_share - 0.05).max(0.30)
        } else {
            previous_tuning_policy.risk_guard_max_voice_share.min(0.45)
        },
        trend_entry_min_voice_share: if raise_trend_floor {
            (previous_tuning_policy.trend_entry_min_voice_floor + 0.03).min(0.30)
        } else {
            previous_tuning_policy.trend_entry_min_voice_floor.max(0.18)
        },
        evidence_regime_min_voice_share: if raise_evidence_floor {
            (previous_tuning_policy.evidence_regime_min_voice_floor + 0.03).min(0.28)
        } else {
            previous_tuning_policy
                .evidence_regime_min_voice_floor
                .max(0.15)
        },
        compounding_brake_enabled: true,
        max_consecutive_voice_increases_per_member: previous_tuning_policy
            .max_reward_streak_per_member
            .saturating_sub(1)
            .max(1),
        max_consecutive_voice_decreases_per_member: previous_tuning_policy
            .max_penalty_streak_per_member
            .saturating_sub(1)
            .max(1),
        dampen_low_evidence_delta: true,
        low_evidence_dampening_factor: 0.45,
        preserve_risk_first: true,
        actual_voice_apply_allowed: false,
        actual_score_apply_allowed: false,
        promotion_demotion_allowed: false,
        risk_governor_override_allowed: false,
        paper_only: true,
    };
    if policy.tuned_voice_delta_cap_v2 > policy.previous_voice_delta_cap {
        return Err("conservative voice tuning v2 must not increase voice cap".to_string());
    }
    if policy.actual_voice_apply_allowed
        || policy.actual_score_apply_allowed
        || policy.promotion_demotion_allowed
        || policy.risk_governor_override_allowed
    {
        return Err(
            "conservative voice tuning v2 must keep all actual governance apply flags false"
                .to_string(),
        );
    }
    if !policy.preserve_risk_first {
        return Err("conservative voice tuning v2 must preserve risk-first".to_string());
    }
    if policy.trend_entry_min_voice_share <= 0.0
        || policy.risk_guard_min_voice_share <= 0.0
        || policy.evidence_regime_min_voice_share <= 0.0
    {
        return Err("conservative voice tuning v2 role floors must be positive".to_string());
    }
    if policy.risk_guard_max_voice_share <= policy.risk_guard_min_voice_share {
        return Err(
            "conservative voice tuning v2 RiskGuard cap must preserve a positive risk-first role"
                .to_string(),
        );
    }
    Ok(policy)
}

fn build_role_voice_floor_policy(
    policy: &ConservativeVoiceTuningV2Policy,
) -> ChairmanRoleVoiceFloorPolicy {
    ChairmanRoleVoiceFloorPolicy {
        policy_id: format!("{}-role-floor-policy", policy.policy_id),
        trend_entry_min_voice_share: policy.trend_entry_min_voice_share,
        risk_guard_min_voice_share: policy.risk_guard_min_voice_share,
        evidence_regime_min_voice_share: policy.evidence_regime_min_voice_share,
        risk_guard_max_voice_share: policy.risk_guard_max_voice_share,
        total_share_target: 1.0,
        paper_only: true,
    }
}

pub fn evaluate_role_voice_floor_policy(
    shadow_store: &ChairmanShadowGovernanceStateStore,
    floor_policy: &ChairmanRoleVoiceFloorPolicy,
) -> ChairmanRoleVoiceFloorCheck {
    let total_voice = shadow_store
        .member_states
        .iter()
        .map(|state| state.shadow_voice_weight)
        .sum::<f64>()
        .max(f64::EPSILON);
    let role_share = |role: IndependentMemberRole| {
        shadow_store
            .member_states
            .iter()
            .filter(|state| state.role == role)
            .map(|state| state.shadow_voice_weight)
            .sum::<f64>()
            / total_voice
    };
    let trend_entry_share = role_share(IndependentMemberRole::TrendEntry);
    let risk_guard_share = role_share(IndependentMemberRole::RiskGuard);
    let evidence_regime_share = role_share(IndependentMemberRole::EvidenceRegime);
    let trend_entry_floor_met =
        trend_entry_share + 0.01 >= floor_policy.trend_entry_min_voice_share;
    let risk_guard_floor_met = risk_guard_share + 0.01 >= floor_policy.risk_guard_min_voice_share;
    let evidence_regime_floor_met =
        evidence_regime_share + 0.01 >= floor_policy.evidence_regime_min_voice_share;
    let risk_guard_cap_met = risk_guard_share <= floor_policy.risk_guard_max_voice_share + 0.01;
    let mut warnings = Vec::new();
    if trend_entry_share < floor_policy.trend_entry_min_voice_share + 0.02 {
        warnings.push("TrendEntry voice share is close to the conservative floor".to_string());
    }
    if evidence_regime_share < floor_policy.evidence_regime_min_voice_share + 0.02 {
        warnings.push("EvidenceRegime voice share is close to the conservative floor".to_string());
    }
    if risk_guard_share > floor_policy.risk_guard_max_voice_share - 0.02 {
        warnings.push("RiskGuard voice share is close to the conservative cap".to_string());
    }
    ChairmanRoleVoiceFloorCheck {
        check_id: format!("{}-role-floor-check", shadow_store.store_id),
        trend_entry_share,
        risk_guard_share,
        evidence_regime_share,
        trend_entry_floor_met,
        risk_guard_floor_met,
        evidence_regime_floor_met,
        risk_guard_cap_met,
        floor_status: if trend_entry_floor_met
            && risk_guard_floor_met
            && evidence_regime_floor_met
            && risk_guard_cap_met
        {
            if warnings.is_empty() {
                ChairmanRoleVoiceFloorStatus::Met
            } else {
                ChairmanRoleVoiceFloorStatus::MetWithWarnings
            }
        } else {
            ChairmanRoleVoiceFloorStatus::Violated
        },
        warnings,
        paper_only: true,
    }
}

fn build_shadow_voice_deltas_from_state_run_result(
    current_shadow_state_result: &ChairmanShadowGovernanceStateRunResult,
) -> Vec<ChairmanShadowVoiceDelta> {
    let role_by_member = current_shadow_state_result
        .shadow_store_after
        .as_ref()
        .or(current_shadow_state_result.shadow_store_before.as_ref())
        .map(|store| {
            store
                .member_states
                .iter()
                .map(|state| (state.member_id.clone(), state.role))
                .collect::<BTreeMap<_, _>>()
        })
        .unwrap_or_default();
    let mut deltas = current_shadow_state_result
        .apply_result
        .before_after_standings
        .iter()
        .map(|standing| {
            let delta_kind = if standing.voice_delta_applied > 0.0 {
                ChairmanShadowVoiceDeltaKind::Increase
            } else if standing.voice_delta_applied < 0.0 {
                ChairmanShadowVoiceDeltaKind::Decrease
            } else if standing.standing_change == SimulatedMemberStandingStatus::NeedsMoreEvidence {
                ChairmanShadowVoiceDeltaKind::NeedsMoreEvidence
            } else {
                ChairmanShadowVoiceDeltaKind::Neutral
            };
            let reason = if standing.voice_delta_applied > 0.0 {
                ChairmanShadowVoiceDeltaReason::RiskSavedLoss
            } else if standing.voice_delta_applied < 0.0 {
                ChairmanShadowVoiceDeltaReason::OverconfidentRisk
            } else {
                ChairmanShadowVoiceDeltaReason::NeedsMoreEvidence
            };
            let role = role_by_member
                .get(&standing.member_id)
                .copied()
                .unwrap_or(IndependentMemberRole::EvidenceRegime);
            let abs_delta = standing.voice_delta_applied.abs();
            let confidence = if abs_delta >= 0.08 {
                SourceConfidence::ReviewRequired
            } else if abs_delta >= 0.05 {
                SourceConfidence::Low
            } else if role == IndependentMemberRole::RiskGuard {
                SourceConfidence::High
            } else {
                SourceConfidence::Medium
            };
            ChairmanShadowVoiceDelta {
                delta_id: format!(
                    "{}-voice-v2-delta-{}",
                    current_shadow_state_result.run_id, standing.member_id
                ),
                source_ledger_entry_id: current_shadow_state_result
                    .state_ledger
                    .latest_entry_id
                    .clone()
                    .unwrap_or_else(|| current_shadow_state_result.run_id.clone()),
                member_id: standing.member_id.clone(),
                symbol: None,
                market_scope: None,
                delta_kind,
                proposed_voice_delta: standing.voice_delta_applied,
                reason,
                confidence,
                shadow_only: true,
                no_actual_voice_mutation: true,
                paper_only: true,
            }
        })
        .collect::<Vec<_>>();
    deltas.sort_by(|left, right| left.delta_id.cmp(&right.delta_id));
    deltas
}

pub fn apply_voice_delta_compounding_brake(
    voice_deltas: &[ChairmanShadowVoiceDelta],
    history_store: &ChairmanShadowGovernanceHistoryStore,
    policy: &ConservativeVoiceTuningV2Policy,
) -> (
    Vec<ChairmanShadowVoiceDelta>,
    Vec<VoiceDeltaCompoundingBrakeResult>,
) {
    let latest_counts = latest_shadow_governance_history_snapshot(history_store)
        .map(|snapshot| {
            snapshot
                .member_states
                .iter()
                .map(|state| {
                    (
                        state.member_id.clone(),
                        (
                            state.shadow_voice_increase_count,
                            state.shadow_voice_decrease_count,
                        ),
                    )
                })
                .collect::<BTreeMap<_, _>>()
        })
        .unwrap_or_default();
    let mut dampened_deltas = Vec::new();
    let mut by_member = BTreeMap::<String, VoiceDeltaCompoundingBrakeResult>::new();
    for delta in voice_deltas.iter().cloned() {
        let (increase_count, decrease_count) = latest_counts
            .get(&delta.member_id)
            .copied()
            .unwrap_or((0, 0));
        let mut factor: f64 = 1.0;
        let mut reason = "voice delta stayed within conservative compounding limits".to_string();
        if policy.compounding_brake_enabled {
            if delta.proposed_voice_delta > 0.0
                && increase_count > policy.max_consecutive_voice_increases_per_member
            {
                factor = 0.5;
                reason = format!(
                    "repeated positive voice deltas exceeded conservative limit {}",
                    policy.max_consecutive_voice_increases_per_member
                );
            } else if delta.proposed_voice_delta < 0.0
                && decrease_count > policy.max_consecutive_voice_decreases_per_member
            {
                factor = 0.5;
                reason = format!(
                    "repeated negative voice deltas exceeded conservative limit {}",
                    policy.max_consecutive_voice_decreases_per_member
                );
            }
            if delta.reason == ChairmanShadowVoiceDeltaReason::RiskSavedLoss
                && delta.confidence == SourceConfidence::High
                && factor < 1.0
            {
                factor = factor.max(0.7);
                reason = "risk-saved-loss kept less dampening but remained bounded".to_string();
            }
        }
        let mut dampened = delta.clone();
        dampened.proposed_voice_delta *= factor;
        dampened_deltas.push(dampened.clone());
        let entry =
            by_member
                .entry(delta.member_id.clone())
                .or_insert(VoiceDeltaCompoundingBrakeResult {
                    member_id: delta.member_id.clone(),
                    original_voice_delta_total: 0.0,
                    dampened_voice_delta_total: 0.0,
                    consecutive_increase_count: increase_count,
                    consecutive_decrease_count: decrease_count,
                    brake_applied: false,
                    reason: reason.clone(),
                    paper_only: true,
                });
        entry.original_voice_delta_total += delta.proposed_voice_delta;
        entry.dampened_voice_delta_total += dampened.proposed_voice_delta;
        entry.brake_applied |= (factor - 1.0).abs() > f64::EPSILON;
        if entry.brake_applied {
            entry.reason = reason.clone();
        }
    }
    let results = by_member.into_values().collect::<Vec<_>>();
    (dampened_deltas, results)
}

pub fn apply_evidence_based_voice_dampening(
    voice_delta: &ChairmanShadowVoiceDelta,
    evidence_confidence: SourceConfidence,
    policy: &ConservativeVoiceTuningV2Policy,
) -> (ChairmanShadowVoiceDelta, EvidenceBasedVoiceDampeningResult) {
    let multiplier = match evidence_confidence {
        SourceConfidence::High => 1.0,
        SourceConfidence::Medium => 0.85,
        SourceConfidence::Low | SourceConfidence::ReviewRequired => {
            if policy.dampen_low_evidence_delta {
                policy.low_evidence_dampening_factor
            } else {
                1.0
            }
        }
    };
    let output_delta = (voice_delta.proposed_voice_delta * multiplier).clamp(
        -policy.tuned_voice_delta_cap_v2,
        policy.tuned_voice_delta_cap_v2,
    );
    let dampened = ChairmanShadowVoiceDelta {
        proposed_voice_delta: output_delta,
        ..voice_delta.clone()
    };
    (
        dampened.clone(),
        EvidenceBasedVoiceDampeningResult {
            member_id: voice_delta.member_id.clone(),
            input_delta: voice_delta.proposed_voice_delta,
            output_delta,
            evidence_confidence,
            dampening_applied: (output_delta - voice_delta.proposed_voice_delta).abs() > 1e-9,
            reason: match evidence_confidence {
                SourceConfidence::High => {
                    "high-confidence voice delta remained bounded by the conservative v2 cap"
                        .to_string()
                }
                SourceConfidence::Medium => {
                    "medium-confidence voice delta received a light conservative dampening"
                        .to_string()
                }
                SourceConfidence::Low => {
                    "low-confidence voice delta was dampened by the conservative evidence guard"
                        .to_string()
                }
                SourceConfidence::ReviewRequired => {
                    "review-required voice delta was heavily dampened by the conservative evidence guard"
                        .to_string()
                }
            },
            paper_only: true,
        },
    )
}

fn apply_role_voice_floor_policy_to_snapshot(
    snapshot: &mut ChairmanShadowGovernanceHistorySnapshot,
    floor_policy: &ChairmanRoleVoiceFloorPolicy,
) {
    let enforce_once = |states: &mut [ChairmanShadowMemberGovernanceState]| {
        for state in states.iter_mut() {
            match state.role {
                IndependentMemberRole::TrendEntry => {
                    state.shadow_voice_weight = state
                        .shadow_voice_weight
                        .max(floor_policy.trend_entry_min_voice_share);
                }
                IndependentMemberRole::RiskGuard => {
                    state.shadow_voice_weight = state
                        .shadow_voice_weight
                        .max(floor_policy.risk_guard_min_voice_share)
                        .min(floor_policy.risk_guard_max_voice_share);
                }
                IndependentMemberRole::EvidenceRegime => {
                    state.shadow_voice_weight = state
                        .shadow_voice_weight
                        .max(floor_policy.evidence_regime_min_voice_share);
                }
            }
            state.shadow_voice_weight = clamp_unit(state.shadow_voice_weight);
        }
        let total = states
            .iter()
            .map(|state| state.shadow_voice_weight)
            .sum::<f64>()
            .max(f64::EPSILON);
        let ratio = floor_policy.total_share_target / total;
        for state in states.iter_mut() {
            state.shadow_voice_weight = clamp_unit(state.shadow_voice_weight * ratio);
        }
    };
    enforce_once(&mut snapshot.member_states);
    enforce_once(&mut snapshot.member_states);
}

fn apply_voice_tuning_v2_to_history_store(
    history_store: &ChairmanShadowGovernanceHistoryStore,
    policy: &ConservativeVoiceTuningV2Policy,
    floor_policy: &ChairmanRoleVoiceFloorPolicy,
    dampened_voice_deltas: &[ChairmanShadowVoiceDelta],
) -> ChairmanShadowGovernanceHistoryStore {
    let cap_ratio = (policy.tuned_voice_delta_cap_v2 / policy.previous_voice_delta_cap.max(1e-9))
        .clamp(0.0, 1.0);
    let mut per_member_cap = BTreeMap::<String, f64>::new();
    for delta in dampened_voice_deltas {
        let entry = per_member_cap
            .entry(delta.member_id.clone())
            .or_insert(policy.tuned_voice_delta_cap_v2);
        *entry = (*entry).min(delta.proposed_voice_delta.abs().max(0.001));
    }
    let snapshots = history_store
        .snapshots
        .iter()
        .cloned()
        .map(|mut snapshot| {
            for state in &mut snapshot.member_states {
                let current_gap = state.shadow_voice_weight - state.actual_voice_weight_snapshot;
                let member_cap = per_member_cap
                    .get(&state.member_id)
                    .copied()
                    .unwrap_or(policy.tuned_voice_delta_cap_v2)
                    .max(0.001);
                let dampened_gap = (current_gap * cap_ratio).clamp(-member_cap, member_cap);
                state.shadow_voice_weight =
                    clamp_unit(state.actual_voice_weight_snapshot + dampened_gap);
            }
            apply_role_voice_floor_policy_to_snapshot(&mut snapshot, floor_policy);
            snapshot
        })
        .collect::<Vec<_>>();
    let mut store = ChairmanShadowGovernanceHistoryStore {
        store_id: format!("{}-voice-v2", history_store.store_id),
        snapshots,
        snapshot_count: 0,
        latest_snapshot_id: None,
        paper_only: true,
    };
    normalize_shadow_governance_history_store(&mut store);
    store
}

pub fn run_conservative_voice_tuned_multi_run_v2(
    current_shadow_state_result: &ChairmanShadowGovernanceStateRunResult,
    actual_member_states: &[MemberStateSnapshot],
    previous_history: &ChairmanShadowGovernanceHistoryStore,
    previous_tuned_result: Option<&ChairmanShadowGovernanceTuningRunResult>,
    config: &ConservativeVoiceTunedMultiRunV2Config,
) -> Result<ConservativeVoiceTunedMultiRunV2Result, String> {
    if !config.paper_only {
        return Err("conservative voice tuned multi-run v2 must stay paper_only".to_string());
    }
    if config.run_count == 0 {
        return Err("conservative voice tuned multi-run v2 run_count must be positive".to_string());
    }
    if !config.dry_run && config.write_tuned_history && config.tuned_history_output_path.is_none() {
        return Err(
            "conservative voice tuned multi-run v2 requires tuned_history_output_path when write_tuned_history=true"
                .to_string(),
        );
    }
    if let Some(path) = config.tuned_history_output_path.as_ref() {
        validate_local_json_path(
            Path::new(path),
            "conservative voice tuned multi-run v2 history output path",
        )?;
    }
    let baseline = if let Some(previous_tuned_result) = previous_tuned_result {
        previous_tuned_result.clone()
    } else {
        run_chairman_shadow_governance_tuning(
            current_shadow_state_result,
            actual_member_states,
            previous_history,
            &ChairmanShadowGovernanceTuningRunConfig {
                run_id: format!("{}-baseline", config.run_id),
                enabled: true,
                base_history_store_path: None,
                tuned_history_store_output_path: None,
                tuning_result_output_path: None,
                run_count: config.run_count,
                dry_run: true,
                write_tuned_history: false,
                emit_owner_summary: false,
                paper_only: true,
            },
        )?
    };
    let remaining_voice_drift_analysis = analyze_remaining_voice_drift_after_tuning(
        &baseline.tuned_multi_run_result,
        previous_history,
        &baseline.tuning_policy,
    );
    let voice_tuning_v2_policy = build_conservative_voice_tuning_v2_policy(
        &remaining_voice_drift_analysis,
        &baseline.tuning_policy,
    )?;
    let role_floor_policy = build_role_voice_floor_policy(&voice_tuning_v2_policy);
    let base_voice_deltas =
        build_shadow_voice_deltas_from_state_run_result(current_shadow_state_result);
    let (braked_voice_deltas, compounding_brake_results) = apply_voice_delta_compounding_brake(
        &base_voice_deltas,
        &baseline
            .tuned_multi_run_result
            .multi_run_harness_result
            .history_store,
        &voice_tuning_v2_policy,
    );
    let mut evidence_dampening_results = Vec::new();
    let dampened_voice_deltas = braked_voice_deltas
        .iter()
        .map(|voice_delta| {
            let (dampened_delta, result) = apply_evidence_based_voice_dampening(
                voice_delta,
                voice_delta.confidence,
                &voice_tuning_v2_policy,
            );
            evidence_dampening_results.push(result);
            dampened_delta
        })
        .collect::<Vec<_>>();
    let tuned_history_store = apply_voice_tuning_v2_to_history_store(
        &baseline
            .tuned_multi_run_result
            .multi_run_harness_result
            .history_store,
        &voice_tuning_v2_policy,
        &role_floor_policy,
        &dampened_voice_deltas,
    );
    let mut wrote_tuned_history = false;
    if !config.dry_run && config.write_tuned_history {
        if let Some(path) = config.tuned_history_output_path.as_ref() {
            save_chairman_shadow_governance_history_store_to_local_json(
                Path::new(path),
                &tuned_history_store,
            )?;
            wrote_tuned_history = true;
        }
    }
    let tuned_multi_run_result = build_harness_result_from_history_store(
        &baseline.tuned_multi_run_result.multi_run_harness_result,
        current_shadow_state_result,
        actual_member_states,
        tuned_history_store,
        wrote_tuned_history,
        config.tuned_history_output_path.clone(),
    )?;
    let placeholder = PaperGovernanceTrialDesignReadinessV3 {
        readiness_id: format!("{}-voice-v2-placeholder", config.run_id),
        history_quality_status: ShadowGovernanceHistoryQualityStatus::Valid,
        divergence_trend_status: ActualVsShadowDivergenceTrendStatus::InsufficientHistory,
        stability_status: tuned_multi_run_result
            .aggregate_stability_metrics
            .stability_status,
        fairness_status: current_shadow_state_result
            .apply_result
            .fairness_check
            .fairness_status,
        risk_first_status: current_shadow_state_result
            .apply_result
            .risk_first_check
            .risk_first_status,
        safety_status: ChairmanShadowGovernanceMultiRunSafetyGuardStatus::Preserved,
        min_history_met: false,
        divergence_reducing_or_stable: false,
        fairness_ok: false,
        risk_first_ok: false,
        safety_ok: false,
        ready_for_paper_governance_trial_design: false,
        readiness_status: PaperGovernanceTrialDesignReadinessV3Status::NeedsMoreShadowHistory,
        blockers: Vec::new(),
        warnings: Vec::new(),
        paper_only: true,
    };
    let provisional_safety = evaluate_chairman_shadow_governance_multi_run_safety(
        &tuned_multi_run_result,
        &placeholder,
        current_shadow_state_result,
        actual_member_states,
        Some(actual_member_states),
        config.dry_run,
    );
    let divergence_trend_summary =
        summarize_actual_vs_shadow_divergence_trend(&tuned_multi_run_result.history_store);
    let history_quality_check = check_shadow_governance_history_quality(
        &tuned_multi_run_result.history_store,
        config.run_count.max(1),
    );
    let readiness_v3 = evaluate_paper_governance_trial_design_readiness_v3(
        &history_quality_check,
        &divergence_trend_summary,
        &tuned_multi_run_result.aggregate_stability_metrics,
        &current_shadow_state_result.apply_result,
        &provisional_safety,
        config.run_count.max(1),
    );
    let final_safety = evaluate_chairman_shadow_governance_multi_run_safety(
        &tuned_multi_run_result,
        &readiness_v3,
        current_shadow_state_result,
        actual_member_states,
        Some(actual_member_states),
        config.dry_run,
    );
    let latest_snapshot =
        latest_shadow_governance_history_snapshot(&tuned_multi_run_result.history_store)
            .ok_or_else(|| {
                "conservative voice tuned multi-run v2 requires tuned history snapshots".to_string()
            })?;
    let shadow_store = build_shadow_store_from_history_snapshot(
        latest_snapshot,
        format!("{}-voice-v2-shadow-store", config.run_id),
    );
    let role_floor_check = evaluate_role_voice_floor_policy(&shadow_store, &role_floor_policy);
    let previous_gate_status = paper_governance_gate_status_from_readiness_v3(
        baseline.tuned_multi_run_result.after_gate_status,
    );
    let tuned_v2_gate_status =
        paper_governance_gate_status_from_readiness_v3(readiness_v3.readiness_status);
    let before_rank = gate_v2_rank(previous_gate_status);
    let after_rank = gate_v2_rank(tuned_v2_gate_status);
    Ok(ConservativeVoiceTunedMultiRunV2Result {
        run_id: config.run_id.clone(),
        remaining_voice_drift_analysis,
        voice_tuning_v2_policy,
        role_floor_policy,
        role_floor_check,
        compounding_brake_results,
        evidence_dampening_results,
        tuned_multi_run_result,
        previous_gate_status,
        tuned_v2_gate_status,
        previous_divergence_status: baseline
            .tuned_multi_run_result
            .divergence_trend_summary
            .trend_status,
        tuned_v2_divergence_status: divergence_trend_summary.trend_status,
        risk_first_preserved: current_shadow_state_result
            .apply_result
            .risk_first_check
            .risk_first_status
            != ChairmanRiskFirstGovernanceStatus::Violated,
        safety_status: final_safety.guard_status,
        improvement_status: if final_safety.guard_status
            == ChairmanShadowGovernanceMultiRunSafetyGuardStatus::Violated
        {
            ConservativeVoiceTunedMultiRunV2ImprovementStatus::Blocked
        } else if after_rank < before_rank {
            if matches!(
                tuned_v2_gate_status,
                PaperGovernanceTrialGateV2Status::ReadyWithWarnings
                    | PaperGovernanceTrialGateV2Status::NeedsMoreEvidence
                    | PaperGovernanceTrialGateV2Status::NeedsMoreShadowHistory
            ) {
                ConservativeVoiceTunedMultiRunV2ImprovementStatus::ImprovedWithWarnings
            } else {
                ConservativeVoiceTunedMultiRunV2ImprovementStatus::Improved
            }
        } else if after_rank == before_rank {
            ConservativeVoiceTunedMultiRunV2ImprovementStatus::NoChange
        } else {
            ConservativeVoiceTunedMultiRunV2ImprovementStatus::Worse
        },
        paper_only: true,
    })
}

pub fn evaluate_conservative_voice_tuning_v2_safety(
    v2_result: &ConservativeVoiceTunedMultiRunV2Result,
    console_section: &OwnerGovernanceConsoleSectionV1,
    before_state: &ChairmanShadowGovernanceStateRunResult,
    after_state: Option<&ChairmanShadowGovernanceStateRunResult>,
) -> ConservativeVoiceTuningV2SafetyGuard {
    let after_state = after_state.unwrap_or(before_state);
    let actual_score_mutation_detected = before_state.safety_guard.actual_score_mutation_detected
        || after_state.safety_guard.actual_score_mutation_detected;
    let actual_voice_mutation_detected = before_state.safety_guard.actual_voice_mutation_detected
        || after_state.safety_guard.actual_voice_mutation_detected;
    let promotion_demotion_detected = before_state.safety_guard.promotion_execution_detected
        || before_state.safety_guard.demotion_execution_detected
        || after_state.safety_guard.promotion_execution_detected
        || after_state.safety_guard.demotion_execution_detected;
    let risk_governor_override_detected = before_state.safety_guard.risk_governor_override_detected
        || after_state.safety_guard.risk_governor_override_detected;
    let committee_decision_mutation_detected = before_state
        .safety_guard
        .committee_decision_mutation_detected
        || after_state
            .safety_guard
            .committee_decision_mutation_detected;
    let trade_signal_detected = before_state.safety_guard.trade_signal_detected
        || after_state.safety_guard.trade_signal_detected;
    let order_detected =
        before_state.safety_guard.order_detected || after_state.safety_guard.order_detected;
    let broker_order_account_detected = before_state.safety_guard.broker_order_account_detected
        || after_state.safety_guard.broker_order_account_detected;
    let voice_cap_increased_detected = v2_result.voice_tuning_v2_policy.tuned_voice_delta_cap_v2
        > v2_result.voice_tuning_v2_policy.previous_voice_delta_cap;
    let risk_first_disabled_detected = !v2_result.voice_tuning_v2_policy.preserve_risk_first;
    let role_floor_disabled_detected = v2_result.role_floor_policy.trend_entry_min_voice_share
        <= 0.0
        || v2_result.role_floor_policy.risk_guard_min_voice_share <= 0.0
        || v2_result.role_floor_policy.evidence_regime_min_voice_share <= 0.0
        || v2_result.role_floor_policy.risk_guard_max_voice_share
            <= v2_result.role_floor_policy.risk_guard_min_voice_share;
    let owner_console_action_detected = !console_section.read_only
        || !console_section.no_actions
        || !console_section.no_score_mutation
        || !console_section.no_voice_mutation
        || !console_section.no_trade_signal;
    let unsafe_gate_open_detected = matches!(
        v2_result.tuned_v2_gate_status,
        PaperGovernanceTrialGateV2Status::ReadyForPaperTrialDesign
            | PaperGovernanceTrialGateV2Status::ReadyWithWarnings
    ) && matches!(
        v2_result.tuned_v2_divergence_status,
        ActualVsShadowDivergenceTrendStatus::Unsafe
            | ActualVsShadowDivergenceTrendStatus::Worsening
    );
    let mut violations = Vec::new();
    if actual_score_mutation_detected {
        violations.push("conservative voice tuning v2 mutated actual score".to_string());
    }
    if actual_voice_mutation_detected {
        violations.push("conservative voice tuning v2 mutated actual voice".to_string());
    }
    if promotion_demotion_detected {
        violations.push("conservative voice tuning v2 executed promotion or demotion".to_string());
    }
    if risk_governor_override_detected {
        violations.push("conservative voice tuning v2 overrode Risk Governor".to_string());
    }
    if committee_decision_mutation_detected {
        violations.push("conservative voice tuning v2 changed committee decision".to_string());
    }
    if trade_signal_detected {
        violations.push("conservative voice tuning v2 created a trade signal".to_string());
    }
    if order_detected {
        violations.push("conservative voice tuning v2 created an order".to_string());
    }
    if broker_order_account_detected {
        violations.push("conservative voice tuning v2 touched broker/order/account".to_string());
    }
    if voice_cap_increased_detected {
        violations.push("conservative voice tuning v2 increased the voice cap".to_string());
    }
    if risk_first_disabled_detected {
        violations.push("conservative voice tuning v2 disabled risk-first behavior".to_string());
    }
    if role_floor_disabled_detected {
        violations.push("conservative voice tuning v2 disabled role floor protection".to_string());
    }
    if owner_console_action_detected {
        violations.push("owner governance console section exposed a mutation action".to_string());
    }
    if unsafe_gate_open_detected {
        violations.push(
            "conservative voice tuning v2 opened the gate while unsafe divergence remained"
                .to_string(),
        );
    }
    ConservativeVoiceTuningV2SafetyGuard {
        actual_score_mutation_detected,
        actual_voice_mutation_detected,
        promotion_demotion_detected,
        risk_governor_override_detected,
        committee_decision_mutation_detected,
        trade_signal_detected,
        order_detected,
        broker_order_account_detected,
        voice_cap_increased_detected,
        risk_first_disabled_detected,
        role_floor_disabled_detected,
        owner_console_action_detected,
        unsafe_gate_open_detected,
        guard_status: if violations.is_empty() {
            ConservativeVoiceTuningV2SafetyGuardStatus::Preserved
        } else {
            ConservativeVoiceTuningV2SafetyGuardStatus::Violated
        },
        violations,
        paper_only: true,
    }
}

pub fn recheck_paper_governance_gate_with_voice_tuning_v2(
    v2_result: &ConservativeVoiceTunedMultiRunV2Result,
    role_floor_check: &ChairmanRoleVoiceFloorCheck,
    safety_guard: &ConservativeVoiceTuningV2SafetyGuard,
) -> ConservativeVoiceTunedGateRecheckV2 {
    let mut blockers = Vec::new();
    let mut warnings = role_floor_check.warnings.clone();
    let gate_status = if safety_guard.guard_status
        == ConservativeVoiceTuningV2SafetyGuardStatus::Violated
    {
        blockers.push("conservative voice tuning v2 safety guard was violated".to_string());
        ConservativeVoiceTunedGateRecheckV2Status::BlockedBySafety
    } else if !v2_result.risk_first_preserved {
        blockers.push("risk-first behavior was not preserved".to_string());
        ConservativeVoiceTunedGateRecheckV2Status::BlockedByRiskViolation
    } else if role_floor_check.floor_status == ChairmanRoleVoiceFloorStatus::Violated {
        blockers
            .push("role floor rebalance remains violated after conservative tuning".to_string());
        ConservativeVoiceTunedGateRecheckV2Status::BlockedByRoleFloor
    } else if matches!(
        v2_result.tuned_v2_divergence_status,
        ActualVsShadowDivergenceTrendStatus::Unsafe
            | ActualVsShadowDivergenceTrendStatus::Worsening
    ) || v2_result.remaining_voice_drift_analysis.analysis_status
        == RemainingVoiceDriftAnalysisStatus::Actionable
    {
        blockers.push("unsafe voice drift remains after conservative tuning v2".to_string());
        ConservativeVoiceTunedGateRecheckV2Status::BlockedByDivergence
    } else {
        match v2_result.tuned_v2_gate_status {
            PaperGovernanceTrialGateV2Status::ReadyForPaperTrialDesign => {
                ConservativeVoiceTunedGateRecheckV2Status::ReadyForPaperTrialDesign
            }
            PaperGovernanceTrialGateV2Status::ReadyWithWarnings => {
                warnings.push(
                    "conservative voice tuning v2 improved readiness with warnings".to_string(),
                );
                ConservativeVoiceTunedGateRecheckV2Status::ReadyWithWarnings
            }
            PaperGovernanceTrialGateV2Status::NeedsMoreEvidence => {
                ConservativeVoiceTunedGateRecheckV2Status::NeedsMoreEvidence
            }
            PaperGovernanceTrialGateV2Status::NeedsMoreShadowHistory => {
                ConservativeVoiceTunedGateRecheckV2Status::NeedsMoreShadowHistory
            }
            PaperGovernanceTrialGateV2Status::BlockedByFairness => {
                ConservativeVoiceTunedGateRecheckV2Status::BlockedByFairness
            }
            PaperGovernanceTrialGateV2Status::BlockedByRiskViolation => {
                ConservativeVoiceTunedGateRecheckV2Status::BlockedByRiskViolation
            }
            PaperGovernanceTrialGateV2Status::BlockedBySafety => {
                ConservativeVoiceTunedGateRecheckV2Status::BlockedBySafety
            }
            PaperGovernanceTrialGateV2Status::BlockedByDivergence => {
                blockers
                    .push("unsafe voice drift remains after conservative tuning v2".to_string());
                ConservativeVoiceTunedGateRecheckV2Status::BlockedByDivergence
            }
        }
    };
    ConservativeVoiceTunedGateRecheckV2 {
        previous_gate_status: v2_result.previous_gate_status,
        tuned_v2_gate_status: v2_result.tuned_v2_gate_status,
        previous_divergence_status: v2_result.previous_divergence_status,
        tuned_v2_divergence_status: v2_result.tuned_v2_divergence_status,
        role_floor_status: role_floor_check.floor_status,
        risk_first_preserved: v2_result.risk_first_preserved,
        readiness_improved: conservative_voice_tuned_gate_rank(gate_status)
            < conservative_voice_tuned_gate_rank(match v2_result.previous_gate_status {
                PaperGovernanceTrialGateV2Status::ReadyForPaperTrialDesign => {
                    ConservativeVoiceTunedGateRecheckV2Status::ReadyForPaperTrialDesign
                }
                PaperGovernanceTrialGateV2Status::ReadyWithWarnings => {
                    ConservativeVoiceTunedGateRecheckV2Status::ReadyWithWarnings
                }
                PaperGovernanceTrialGateV2Status::NeedsMoreEvidence => {
                    ConservativeVoiceTunedGateRecheckV2Status::NeedsMoreEvidence
                }
                PaperGovernanceTrialGateV2Status::NeedsMoreShadowHistory => {
                    ConservativeVoiceTunedGateRecheckV2Status::NeedsMoreShadowHistory
                }
                PaperGovernanceTrialGateV2Status::BlockedByFairness => {
                    ConservativeVoiceTunedGateRecheckV2Status::BlockedByFairness
                }
                PaperGovernanceTrialGateV2Status::BlockedByRiskViolation => {
                    ConservativeVoiceTunedGateRecheckV2Status::BlockedByRiskViolation
                }
                PaperGovernanceTrialGateV2Status::BlockedBySafety => {
                    ConservativeVoiceTunedGateRecheckV2Status::BlockedBySafety
                }
                PaperGovernanceTrialGateV2Status::BlockedByDivergence => {
                    ConservativeVoiceTunedGateRecheckV2Status::BlockedByDivergence
                }
            }),
        gate_status,
        blockers,
        warnings,
        paper_only: true,
    }
}

pub fn build_owner_governance_console_section_v1(
    v2_result: &ConservativeVoiceTunedMultiRunV2Result,
    gate_recheck: &ConservativeVoiceTunedGateRecheckV2,
) -> OwnerGovernanceConsoleSectionV1 {
    OwnerGovernanceConsoleSectionV1 {
        section_id: format!("{}-owner-console-v1", v2_result.run_id),
        governance_mode: OwnerGovernanceMode::ShadowOnly,
        current_gate_status: gate_recheck.gate_status,
        unsafe_divergence_status: v2_result.tuned_v2_divergence_status,
        dominant_voice_drift_causes: v2_result
            .remaining_voice_drift_analysis
            .dominant_causes
            .clone(),
        voice_cap_before: v2_result.voice_tuning_v2_policy.previous_voice_delta_cap,
        voice_cap_after: v2_result.voice_tuning_v2_policy.tuned_voice_delta_cap_v2,
        role_floor_status: gate_recheck.role_floor_status,
        risk_first_status: if gate_recheck.risk_first_preserved {
            if gate_recheck.gate_status
                == ConservativeVoiceTunedGateRecheckV2Status::ReadyWithWarnings
            {
                ChairmanRiskFirstGovernanceStatus::PreservedWithWarnings
            } else {
                ChairmanRiskFirstGovernanceStatus::Preserved
            }
        } else {
            ChairmanRiskFirstGovernanceStatus::Violated
        },
        safety_status: match gate_recheck.gate_status {
            ConservativeVoiceTunedGateRecheckV2Status::BlockedBySafety
            | ConservativeVoiceTunedGateRecheckV2Status::BlockedByRiskViolation => {
                OwnerGovernanceConsoleSafetyStatus::Blocked
            }
            ConservativeVoiceTunedGateRecheckV2Status::ReadyWithWarnings
            | ConservativeVoiceTunedGateRecheckV2Status::NeedsMoreEvidence
            | ConservativeVoiceTunedGateRecheckV2Status::NeedsMoreShadowHistory => {
                OwnerGovernanceConsoleSafetyStatus::Warning
            }
            _ => OwnerGovernanceConsoleSafetyStatus::Preserved,
        },
        next_allowed_step: match gate_recheck.gate_status {
            ConservativeVoiceTunedGateRecheckV2Status::ReadyForPaperTrialDesign => {
                OwnerGovernanceNextAllowedStep::PaperTrialDesignOnly
            }
            ConservativeVoiceTunedGateRecheckV2Status::NeedsMoreEvidence
            | ConservativeVoiceTunedGateRecheckV2Status::NeedsMoreShadowHistory => {
                OwnerGovernanceNextAllowedStep::CollectMoreEvidence
            }
            ConservativeVoiceTunedGateRecheckV2Status::BlockedByDivergence
            | ConservativeVoiceTunedGateRecheckV2Status::BlockedByRoleFloor
            | ConservativeVoiceTunedGateRecheckV2Status::ReadyWithWarnings => {
                OwnerGovernanceNextAllowedStep::KeepTuning
            }
            ConservativeVoiceTunedGateRecheckV2Status::BlockedByFairness
            | ConservativeVoiceTunedGateRecheckV2Status::BlockedByRiskViolation
            | ConservativeVoiceTunedGateRecheckV2Status::BlockedBySafety => {
                OwnerGovernanceNextAllowedStep::Blocked
            }
        },
        owner_message: format!(
            "Rust-only owner governance console summary: gate={:?}, remaining_voice_drift={:?}, voice_cap {:.3}->{:.3}. Read-only only; no score mutation, no voice mutation, no trade signal.",
            gate_recheck.gate_status,
            v2_result.remaining_voice_drift_analysis.analysis_status,
            v2_result.voice_tuning_v2_policy.previous_voice_delta_cap,
            v2_result.voice_tuning_v2_policy.tuned_voice_delta_cap_v2
        ),
        read_only: true,
        no_actions: true,
        no_score_mutation: true,
        no_voice_mutation: true,
        no_trade_signal: true,
        paper_only: true,
    }
}

pub fn run_conservative_voice_tuning_v2(
    current_shadow_state_result: &ChairmanShadowGovernanceStateRunResult,
    actual_member_states: &[MemberStateSnapshot],
    previous_history: &ChairmanShadowGovernanceHistoryStore,
    previous_tuned_result: Option<&ChairmanShadowGovernanceTuningRunResult>,
    config: &ConservativeVoiceTuningV2RunConfig,
) -> Result<ConservativeVoiceTuningV2RunResult, String> {
    if !config.paper_only {
        return Err("conservative voice tuning v2 run must stay paper_only".to_string());
    }
    if config.run_count == 0 {
        return Err("conservative voice tuning v2 run_count must be positive".to_string());
    }
    if !config.dry_run
        && config.write_tuned_history
        && config.tuned_v2_history_output_path.is_none()
    {
        return Err(
            "conservative voice tuning v2 run requires tuned_v2_history_output_path when write_tuned_history=true"
                .to_string(),
        );
    }
    for (path, label) in [
        (
            config.previous_history_path.as_ref(),
            "conservative voice tuning v2 previous_history_path",
        ),
        (
            config.previous_tuning_result_path.as_ref(),
            "conservative voice tuning v2 previous_tuning_result_path",
        ),
        (
            config.tuned_v2_history_output_path.as_ref(),
            "conservative voice tuning v2 tuned_v2_history_output_path",
        ),
        (
            config.tuning_v2_result_output_path.as_ref(),
            "conservative voice tuning v2 tuning_v2_result_output_path",
        ),
    ] {
        if let Some(path) = path {
            validate_local_json_path(Path::new(path), label)?;
        }
    }
    let loaded_previous_history = if let Some(path) = config.previous_history_path.as_ref() {
        if Path::new(path).exists() {
            Some(load_chairman_shadow_governance_history_store_from_local_json(Path::new(path))?)
        } else {
            None
        }
    } else {
        None
    };
    let previous_history = loaded_previous_history.as_ref().unwrap_or(previous_history);
    let loaded_previous_tuning = if let Some(path) = config.previous_tuning_result_path.as_ref() {
        if Path::new(path).exists() {
            Some(
                serde_json::from_str::<ChairmanShadowGovernanceTuningRunResult>(
                    &std::fs::read_to_string(path)
                        .map_err(|error| format!("failed to read {path}: {error}"))?,
                )
                .map_err(|error| {
                    format!(
                        "failed to deserialize conservative voice tuning v2 previous tuning result {path}: {error}"
                    )
                })?,
            )
        } else {
            None
        }
    } else {
        None
    };
    let previous_tuned_result = loaded_previous_tuning.as_ref().or(previous_tuned_result);
    let v2_result = run_conservative_voice_tuned_multi_run_v2(
        current_shadow_state_result,
        actual_member_states,
        previous_history,
        previous_tuned_result,
        &ConservativeVoiceTunedMultiRunV2Config {
            run_id: config.run_id.clone(),
            enabled: config.enabled,
            run_count: config.run_count.max(1),
            dry_run: config.dry_run,
            write_tuned_history: config.write_tuned_history,
            tuned_history_output_path: config.tuned_v2_history_output_path.clone(),
            paper_only: true,
        },
    )?;
    let provisional_gate_recheck = ConservativeVoiceTunedGateRecheckV2 {
        previous_gate_status: v2_result.previous_gate_status,
        tuned_v2_gate_status: v2_result.tuned_v2_gate_status,
        previous_divergence_status: v2_result.previous_divergence_status,
        tuned_v2_divergence_status: v2_result.tuned_v2_divergence_status,
        role_floor_status: v2_result.role_floor_check.floor_status,
        risk_first_preserved: v2_result.risk_first_preserved,
        readiness_improved: false,
        gate_status: ConservativeVoiceTunedGateRecheckV2Status::NeedsMoreEvidence,
        blockers: Vec::new(),
        warnings: v2_result.role_floor_check.warnings.clone(),
        paper_only: true,
    };
    let provisional_console =
        build_owner_governance_console_section_v1(&v2_result, &provisional_gate_recheck);
    let mut safety_guard = evaluate_conservative_voice_tuning_v2_safety(
        &v2_result,
        &provisional_console,
        current_shadow_state_result,
        Some(current_shadow_state_result),
    );
    let gate_recheck_v2 = recheck_paper_governance_gate_with_voice_tuning_v2(
        &v2_result,
        &v2_result.role_floor_check,
        &safety_guard,
    );
    let mut result = ConservativeVoiceTuningV2RunResult {
        run_id: config.run_id.clone(),
        v2_result,
        gate_recheck_v2,
        owner_console_section: None,
        safety_guard: ConservativeVoiceTuningV2SafetyGuard {
            actual_score_mutation_detected: false,
            actual_voice_mutation_detected: false,
            promotion_demotion_detected: false,
            risk_governor_override_detected: false,
            committee_decision_mutation_detected: false,
            trade_signal_detected: false,
            order_detected: false,
            broker_order_account_detected: false,
            voice_cap_increased_detected: false,
            risk_first_disabled_detected: false,
            role_floor_disabled_detected: false,
            owner_console_action_detected: false,
            unsafe_gate_open_detected: false,
            guard_status: ConservativeVoiceTuningV2SafetyGuardStatus::Preserved,
            violations: Vec::new(),
            paper_only: true,
        },
        run_status: ConservativeVoiceTuningV2RunStatus::PassedWithWarnings,
        paper_only: true,
    };
    if config.emit_owner_console_section {
        result.owner_console_section = Some(build_owner_governance_console_section_v1(
            &result.v2_result,
            &result.gate_recheck_v2,
        ));
    }
    let console_section = result.owner_console_section.clone().unwrap_or_else(|| {
        build_owner_governance_console_section_v1(&result.v2_result, &result.gate_recheck_v2)
    });
    safety_guard = evaluate_conservative_voice_tuning_v2_safety(
        &result.v2_result,
        &console_section,
        current_shadow_state_result,
        Some(current_shadow_state_result),
    );
    result.safety_guard = safety_guard.clone();
    result.gate_recheck_v2 = recheck_paper_governance_gate_with_voice_tuning_v2(
        &result.v2_result,
        &result.v2_result.role_floor_check,
        &safety_guard,
    );
    if config.emit_owner_console_section {
        result.owner_console_section = Some(build_owner_governance_console_section_v1(
            &result.v2_result,
            &result.gate_recheck_v2,
        ));
    }
    result.run_status = if result.safety_guard.guard_status
        == ConservativeVoiceTuningV2SafetyGuardStatus::Violated
    {
        ConservativeVoiceTuningV2RunStatus::Failed
    } else if matches!(
        result.gate_recheck_v2.gate_status,
        ConservativeVoiceTunedGateRecheckV2Status::ReadyForPaperTrialDesign
    ) && result.gate_recheck_v2.readiness_improved
    {
        ConservativeVoiceTuningV2RunStatus::Passed
    } else {
        ConservativeVoiceTuningV2RunStatus::PassedWithWarnings
    };
    if !config.dry_run {
        if let Some(path) = config.tuning_v2_result_output_path.as_ref() {
            write_safe_json(Path::new(path), &result)?;
        }
    }
    Ok(result)
}

pub fn conservative_voice_tuning_v2_requested_from_flags(
    enabled: bool,
    dry_run: bool,
    history_output_path: Option<&String>,
    result_output_path: Option<&String>,
    write_tuned_history: bool,
    owner_console_section_enabled: bool,
) -> bool {
    enabled
        || !dry_run
        || history_output_path.is_some()
        || result_output_path.is_some()
        || write_tuned_history
        || (enabled && owner_console_section_enabled)
}

fn maybe_run_conservative_voice_tuning_v2_for_batch_result(
    run_id: String,
    enabled: bool,
    dry_run: bool,
    run_count: usize,
    history_output_path: Option<&String>,
    result_output_path: Option<&String>,
    write_tuned_history: bool,
    owner_console_section_enabled: bool,
    actual_member_states: &[MemberStateSnapshot],
    batch_result: &mut BatchCommitteeCycleResult,
) -> Result<Option<ConservativeVoiceTuningV2RunResult>, String> {
    if !conservative_voice_tuning_v2_requested_from_flags(
        enabled,
        dry_run,
        history_output_path,
        result_output_path,
        write_tuned_history,
        owner_console_section_enabled,
    ) {
        return Ok(None);
    }
    let current_state_result = batch_result
        .chairman_shadow_governance_state_run_result
        .clone()
        .ok_or_else(|| {
            "conservative voice tuning v2 requires current shadow governance state result"
                .to_string()
        })?;
    let previous_history = batch_result
        .chairman_shadow_governance_history_store
        .clone()
        .unwrap_or(ChairmanShadowGovernanceHistoryStore {
            store_id: format!("{}-history-store", run_id),
            snapshots: Vec::new(),
            snapshot_count: 0,
            latest_snapshot_id: None,
            paper_only: true,
        });
    let previous_tuned_result = batch_result
        .chairman_shadow_governance_tuning_run_result
        .clone();
    let result = run_conservative_voice_tuning_v2(
        &current_state_result,
        actual_member_states,
        &previous_history,
        previous_tuned_result.as_ref(),
        &ConservativeVoiceTuningV2RunConfig {
            run_id,
            enabled,
            run_count,
            previous_history_path: None,
            previous_tuning_result_path: None,
            tuned_v2_history_output_path: history_output_path.cloned(),
            tuning_v2_result_output_path: result_output_path.cloned(),
            dry_run,
            write_tuned_history,
            emit_owner_console_section: owner_console_section_enabled,
            paper_only: true,
        },
    )?;
    batch_result.remaining_voice_drift_analysis_result =
        Some(result.v2_result.remaining_voice_drift_analysis.clone());
    batch_result.conservative_voice_tuning_v2_policy =
        Some(result.v2_result.voice_tuning_v2_policy.clone());
    batch_result.chairman_role_voice_floor_policy =
        Some(result.v2_result.role_floor_policy.clone());
    batch_result.chairman_role_voice_floor_check = Some(result.v2_result.role_floor_check.clone());
    batch_result.voice_delta_compounding_brake_results =
        result.v2_result.compounding_brake_results.clone();
    batch_result.evidence_based_voice_dampening_results =
        result.v2_result.evidence_dampening_results.clone();
    batch_result.conservative_voice_tuned_multi_run_v2_result = Some(result.v2_result.clone());
    batch_result.conservative_voice_tuned_gate_recheck_v2 = Some(result.gate_recheck_v2.clone());
    batch_result.owner_governance_console_section_v1 = result.owner_console_section.clone();
    batch_result.conservative_voice_tuning_v2_safety_guard = Some(result.safety_guard.clone());
    batch_result.conservative_voice_tuning_v2_run_result = Some(result.clone());
    batch_result.chairman_shadow_governance_history_store = Some(
        result
            .v2_result
            .tuned_multi_run_result
            .history_store
            .clone(),
    );
    batch_result.actual_vs_shadow_divergence_trend_summary =
        Some(summarize_actual_vs_shadow_divergence_trend(
            &result.v2_result.tuned_multi_run_result.history_store,
        ));
    Ok(Some(result))
}

fn paper_governance_trial_member_role_from(
    role: IndependentMemberRole,
) -> PaperGovernanceTrialMemberRole {
    match role {
        IndependentMemberRole::TrendEntry => PaperGovernanceTrialMemberRole::TrendEntry,
        IndependentMemberRole::RiskGuard => PaperGovernanceTrialMemberRole::RiskGuard,
        IndependentMemberRole::EvidenceRegime => PaperGovernanceTrialMemberRole::EvidenceRegime,
    }
}

fn paper_governance_trial_role_for_member(
    member_id: &str,
    shadow_store: Option<&ChairmanShadowGovernanceStateStore>,
) -> PaperGovernanceTrialMemberRole {
    shadow_store
        .and_then(|store| get_shadow_member_state(store, member_id))
        .map(|state| paper_governance_trial_member_role_from(state.role))
        .unwrap_or_else(|| {
            paper_governance_trial_member_role_from(classify_shadow_governance_member_role(
                member_id,
            ))
        })
}

fn source_confidence_rank(confidence: SourceConfidence) -> u8 {
    match confidence {
        SourceConfidence::Low => 0,
        SourceConfidence::Medium => 1,
        SourceConfidence::High => 2,
        SourceConfidence::ReviewRequired => 3,
    }
}

fn worst_source_confidence(values: impl IntoIterator<Item = SourceConfidence>) -> SourceConfidence {
    let collected = values.into_iter().collect::<Vec<_>>();
    if collected.contains(&SourceConfidence::ReviewRequired) {
        SourceConfidence::ReviewRequired
    } else {
        collected
            .into_iter()
            .min_by_key(|confidence| source_confidence_rank(*confidence))
            .unwrap_or(SourceConfidence::Medium)
    }
}

fn confidence_meets_minimum(
    confidence: SourceConfidence,
    minimum: SourceConfidence,
    allow_review_required: bool,
) -> bool {
    if confidence == SourceConfidence::ReviewRequired && !allow_review_required {
        return false;
    }
    source_confidence_rank(confidence) >= source_confidence_rank(minimum)
}

fn paper_trial_candidate_reason_from_score(
    reason: ChairmanShadowScoreDeltaReason,
) -> PaperGovernanceTrialCandidateReason {
    match reason {
        ChairmanShadowScoreDeltaReason::HelpfulDissent => {
            PaperGovernanceTrialCandidateReason::HelpfulDissent
        }
        ChairmanShadowScoreDeltaReason::RiskVetoAligned => {
            PaperGovernanceTrialCandidateReason::RiskVetoAligned
        }
        ChairmanShadowScoreDeltaReason::OverconfidentBadCall => {
            PaperGovernanceTrialCandidateReason::OverconfidentBadCall
        }
        ChairmanShadowScoreDeltaReason::EvidenceWeakness => {
            PaperGovernanceTrialCandidateReason::EvidenceWeakness
        }
        ChairmanShadowScoreDeltaReason::ObserverAgreement => {
            PaperGovernanceTrialCandidateReason::ObserverAgreement
        }
        ChairmanShadowScoreDeltaReason::ObserverDisagreement => {
            PaperGovernanceTrialCandidateReason::ObserverDisagreement
        }
        ChairmanShadowScoreDeltaReason::OwnerOpinionAligned => {
            PaperGovernanceTrialCandidateReason::ObserverAgreement
        }
        ChairmanShadowScoreDeltaReason::OwnerOpinionNotFollowedSafely => {
            PaperGovernanceTrialCandidateReason::RoleBalanceAdjustment
        }
        ChairmanShadowScoreDeltaReason::NeedsMoreEvidence => {
            PaperGovernanceTrialCandidateReason::NeedsMoreEvidence
        }
    }
}

fn paper_trial_candidate_reason_from_voice(
    reason: ChairmanShadowVoiceDeltaReason,
) -> PaperGovernanceTrialCandidateReason {
    match reason {
        ChairmanShadowVoiceDeltaReason::HelpfulDissent => {
            PaperGovernanceTrialCandidateReason::HelpfulDissent
        }
        ChairmanShadowVoiceDeltaReason::RiskSavedLoss => {
            PaperGovernanceTrialCandidateReason::RiskVetoAligned
        }
        ChairmanShadowVoiceDeltaReason::OverconfidentRisk => {
            PaperGovernanceTrialCandidateReason::OverconfidentBadCall
        }
        ChairmanShadowVoiceDeltaReason::RepeatedEvidenceWeakness => {
            PaperGovernanceTrialCandidateReason::EvidenceWeakness
        }
        ChairmanShadowVoiceDeltaReason::ConsistentObserverAgreement => {
            PaperGovernanceTrialCandidateReason::ObserverAgreement
        }
        ChairmanShadowVoiceDeltaReason::SevereObserverDisagreement => {
            PaperGovernanceTrialCandidateReason::ObserverDisagreement
        }
        ChairmanShadowVoiceDeltaReason::NeedsMoreEvidence => {
            PaperGovernanceTrialCandidateReason::NeedsMoreEvidence
        }
    }
}

fn effective_paper_trial_score_cap(
    policy: &PaperGovernanceTrialEligibilityPolicy,
    tuned_result: &ConservativeVoiceTuningV2RunResult,
) -> f64 {
    let _ = tuned_result;
    policy
        .max_score_delta_per_member
        .min(default_chairman_shadow_governance_simulation_policy().max_abs_score_delta_per_entry)
}

fn effective_paper_trial_voice_cap(
    policy: &PaperGovernanceTrialEligibilityPolicy,
    tuned_result: &ConservativeVoiceTuningV2RunResult,
) -> f64 {
    policy.max_voice_delta_per_member.min(
        tuned_result
            .v2_result
            .voice_tuning_v2_policy
            .tuned_voice_delta_cap_v2
            .min(
                default_chairman_shadow_governance_simulation_policy()
                    .max_total_voice_delta_per_member,
            ),
    )
}

pub fn default_paper_governance_trial_eligibility_policy() -> PaperGovernanceTrialEligibilityPolicy
{
    PaperGovernanceTrialEligibilityPolicy {
        policy_id: "paper-governance-trial-eligibility-policy".to_string(),
        require_tuned_gate_not_blocked: true,
        require_safety_preserved: true,
        require_fairness_not_blocked: true,
        require_risk_first_not_blocked: true,
        require_no_actual_mutation: true,
        allow_score_delta_trial: true,
        allow_voice_delta_trial: true,
        allow_promotion_demotion_trial: false,
        allow_risk_governor_override_trial: false,
        max_score_delta_per_member: 0.08,
        max_voice_delta_per_member: 0.05,
        min_candidate_confidence: SourceConfidence::Medium,
        allow_review_required_candidates: false,
        paper_only: true,
    }
}

pub fn validate_paper_governance_trial_eligibility_policy(
    policy: &PaperGovernanceTrialEligibilityPolicy,
) -> Result<(), String> {
    if !policy.paper_only {
        return Err("paper governance trial eligibility policy must stay paper_only".to_string());
    }
    reject_unsafe_owner_feedback_string(&policy.policy_id)?;
    if policy.allow_promotion_demotion_trial {
        return Err(
            "paper governance trial eligibility policy must keep promotion/demotion disabled"
                .to_string(),
        );
    }
    if policy.allow_risk_governor_override_trial {
        return Err(
            "paper governance trial eligibility policy must keep Risk Governor override disabled"
                .to_string(),
        );
    }
    if !(0.0..=1.0).contains(&policy.max_score_delta_per_member)
        || !(0.0..=1.0).contains(&policy.max_voice_delta_per_member)
    {
        return Err(
            "paper governance trial eligibility policy delta caps must be within 0..=1".to_string(),
        );
    }
    Ok(())
}

pub fn select_paper_governance_trial_candidates(
    shadow_simulation_result: &ChairmanShadowGovernanceSimulationResult,
    tuned_policy_result: &ConservativeVoiceTuningV2RunResult,
    eligibility_policy: &PaperGovernanceTrialEligibilityPolicy,
) -> Result<PaperGovernanceTrialCandidateSelectionResult, String> {
    validate_paper_governance_trial_eligibility_policy(eligibility_policy)?;
    let gate_blocker = match tuned_policy_result.gate_recheck_v2.gate_status {
        ConservativeVoiceTunedGateRecheckV2Status::ReadyForPaperTrialDesign
        | ConservativeVoiceTunedGateRecheckV2Status::ReadyWithWarnings => None,
        status => Some(format!("tuned paper trial gate blocked: {status:?}")),
    };
    let safety_blocker = (eligibility_policy.require_safety_preserved
        && tuned_policy_result.safety_guard.guard_status
            == ConservativeVoiceTuningV2SafetyGuardStatus::Violated)
        .then_some("conservative voice tuning v2 safety guard is violated".to_string());
    let fairness_blocker = (eligibility_policy.require_fairness_not_blocked
        && matches!(
            tuned_policy_result
                .v2_result
                .tuned_multi_run_result
                .aggregate_fairness_status,
            ChairmanGovernanceFairnessStatus::Unfair
        ))
    .then_some("tuned shadow governance fairness is blocked".to_string());
    let risk_blocker = (eligibility_policy.require_risk_first_not_blocked
        && !tuned_policy_result.gate_recheck_v2.risk_first_preserved)
        .then_some("tuned shadow governance risk-first protection is not preserved".to_string());
    let mutation_blocker = (eligibility_policy.require_no_actual_mutation
        && (tuned_policy_result
            .v2_result
            .voice_tuning_v2_policy
            .actual_score_apply_allowed
            || tuned_policy_result
                .v2_result
                .voice_tuning_v2_policy
                .actual_voice_apply_allowed
            || tuned_policy_result
                .v2_result
                .voice_tuning_v2_policy
                .promotion_demotion_allowed
            || tuned_policy_result
                .v2_result
                .voice_tuning_v2_policy
                .risk_governor_override_allowed))
        .then_some("tuned shadow governance policy allows actual mutation".to_string());
    let global_blocker = gate_blocker
        .or(safety_blocker)
        .or(fairness_blocker)
        .or(risk_blocker)
        .or(mutation_blocker);
    let score_cap = effective_paper_trial_score_cap(eligibility_policy, tuned_policy_result);
    let voice_cap = effective_paper_trial_voice_cap(eligibility_policy, tuned_policy_result);
    let mut grouped =
        BTreeMap::<String, (Vec<ChairmanShadowScoreDelta>, Vec<ChairmanShadowVoiceDelta>)>::new();
    for delta in &shadow_simulation_result.score_deltas {
        grouped
            .entry(delta.member_id.clone())
            .or_default()
            .0
            .push(delta.clone());
    }
    for delta in &shadow_simulation_result.voice_deltas {
        grouped
            .entry(delta.member_id.clone())
            .or_default()
            .1
            .push(delta.clone());
    }
    let mut candidates = Vec::new();
    for (member_id, (mut score_deltas, mut voice_deltas)) in grouped {
        score_deltas.sort_by(|left, right| left.delta_id.cmp(&right.delta_id));
        voice_deltas.sort_by(|left, right| left.delta_id.cmp(&right.delta_id));
        let score_total = score_deltas
            .iter()
            .filter(|delta| delta.delta_kind != ChairmanShadowScoreDeltaKind::NeedsMoreEvidence)
            .map(|delta| delta.proposed_score_delta)
            .sum::<f64>();
        let voice_total = voice_deltas
            .iter()
            .filter(|delta| delta.delta_kind != ChairmanShadowVoiceDeltaKind::NeedsMoreEvidence)
            .map(|delta| delta.proposed_voice_delta)
            .sum::<f64>();
        let confidences = score_deltas
            .iter()
            .map(|delta| delta.confidence)
            .chain(voice_deltas.iter().map(|delta| delta.confidence))
            .collect::<Vec<_>>();
        let confidence = worst_source_confidence(confidences);
        let source_score = score_deltas.first();
        let source_voice = voice_deltas.first();
        let needs_more_evidence = score_deltas.iter().all(|delta| {
            delta.delta_kind == ChairmanShadowScoreDeltaKind::NeedsMoreEvidence
                || delta.proposed_score_delta.abs() <= f64::EPSILON
        }) && voice_deltas.iter().all(|delta| {
            delta.delta_kind == ChairmanShadowVoiceDeltaKind::NeedsMoreEvidence
                || delta.proposed_voice_delta.abs() <= f64::EPSILON
        });
        let reason = source_score
            .map(|delta| paper_trial_candidate_reason_from_score(delta.reason))
            .or_else(|| {
                source_voice.map(|delta| paper_trial_candidate_reason_from_voice(delta.reason))
            })
            .unwrap_or(PaperGovernanceTrialCandidateReason::NeedsMoreEvidence);
        let mut candidate = PaperGovernanceTrialCandidate {
            candidate_id: format!(
                "{}-paper-trial-candidate",
                member_id.replace('/', "-").replace(' ', "-")
            ),
            source_shadow_delta_id: source_score
                .map(|delta| delta.delta_id.clone())
                .or_else(|| source_voice.map(|delta| delta.delta_id.clone())),
            source_governance_ledger_entry_id: source_score
                .map(|delta| delta.source_ledger_entry_id.clone())
                .or_else(|| source_voice.map(|delta| delta.source_ledger_entry_id.clone())),
            member_id: member_id.clone(),
            symbol: source_score
                .and_then(|delta| delta.symbol.clone())
                .or_else(|| source_voice.and_then(|delta| delta.symbol.clone())),
            market_scope: source_score
                .and_then(|delta| delta.market_scope)
                .or_else(|| source_voice.and_then(|delta| delta.market_scope)),
            candidate_kind: PaperGovernanceTrialCandidateKind::Rejected,
            proposed_score_delta: (score_total.abs() > f64::EPSILON).then_some(score_total),
            proposed_voice_delta: (voice_total.abs() > f64::EPSILON).then_some(voice_total),
            confidence,
            reason,
            eligible: false,
            rejection_reason: None,
            paper_only: true,
        };
        if needs_more_evidence {
            candidate.candidate_kind = PaperGovernanceTrialCandidateKind::NeedsMoreEvidence;
            candidate.rejection_reason = Some("needs more evidence".to_string());
        } else if let Some(reason) = global_blocker.as_ref() {
            candidate.candidate_kind = PaperGovernanceTrialCandidateKind::Rejected;
            candidate.rejection_reason = Some(reason.clone());
        } else if !confidence_meets_minimum(
            candidate.confidence,
            eligibility_policy.min_candidate_confidence,
            eligibility_policy.allow_review_required_candidates,
        ) {
            candidate.candidate_kind = PaperGovernanceTrialCandidateKind::Rejected;
            candidate.rejection_reason = Some(format!(
                "candidate confidence {:?} is below minimum {:?}",
                candidate.confidence, eligibility_policy.min_candidate_confidence
            ));
        } else if candidate
            .proposed_score_delta
            .is_some_and(|delta| delta.abs() > score_cap + f64::EPSILON)
        {
            candidate.candidate_kind = PaperGovernanceTrialCandidateKind::Rejected;
            candidate.rejection_reason = Some("score delta exceeds paper trial cap".to_string());
        } else if candidate
            .proposed_voice_delta
            .is_some_and(|delta| delta.abs() > voice_cap + f64::EPSILON)
        {
            candidate.candidate_kind = PaperGovernanceTrialCandidateKind::Rejected;
            candidate.rejection_reason = Some("voice delta exceeds paper trial cap".to_string());
        } else if !eligibility_policy.allow_score_delta_trial
            && candidate.proposed_score_delta.is_some()
        {
            candidate.candidate_kind = PaperGovernanceTrialCandidateKind::Rejected;
            candidate.rejection_reason = Some("score delta trial is disabled".to_string());
        } else if !eligibility_policy.allow_voice_delta_trial
            && candidate.proposed_voice_delta.is_some()
        {
            candidate.candidate_kind = PaperGovernanceTrialCandidateKind::Rejected;
            candidate.rejection_reason = Some("voice delta trial is disabled".to_string());
        } else {
            candidate.candidate_kind = match (
                candidate.proposed_score_delta.is_some(),
                candidate.proposed_voice_delta.is_some(),
            ) {
                (true, true) => PaperGovernanceTrialCandidateKind::CombinedScoreVoiceTrial,
                (true, false) => PaperGovernanceTrialCandidateKind::ScoreDeltaTrial,
                (false, true) => PaperGovernanceTrialCandidateKind::VoiceDeltaTrial,
                (false, false) => PaperGovernanceTrialCandidateKind::NeedsMoreEvidence,
            };
            candidate.eligible = !matches!(
                candidate.candidate_kind,
                PaperGovernanceTrialCandidateKind::NeedsMoreEvidence
                    | PaperGovernanceTrialCandidateKind::Rejected
            );
            if !candidate.eligible {
                candidate.rejection_reason = Some("needs more evidence".to_string());
            }
        }
        candidates.push(candidate);
    }
    candidates.sort_by(|left, right| left.member_id.cmp(&right.member_id));
    let eligible_candidate_count = candidates
        .iter()
        .filter(|candidate| candidate.eligible)
        .count();
    let rejected_candidate_count = candidates
        .iter()
        .filter(|candidate| candidate.candidate_kind == PaperGovernanceTrialCandidateKind::Rejected)
        .count();
    let needs_more_evidence_count = candidates
        .iter()
        .filter(|candidate| {
            candidate.candidate_kind == PaperGovernanceTrialCandidateKind::NeedsMoreEvidence
        })
        .count();
    Ok(PaperGovernanceTrialCandidateSelectionResult {
        selection_id: format!("{}-paper-trial-selection", tuned_policy_result.run_id),
        input_candidate_count: candidates.len(),
        eligible_candidate_count,
        rejected_candidate_count,
        needs_more_evidence_count,
        candidates,
        selection_status: if global_blocker.is_some() {
            PaperGovernanceTrialCandidateSelectionStatus::Blocked
        } else if eligible_candidate_count == 0 {
            PaperGovernanceTrialCandidateSelectionStatus::NoEligibleCandidates
        } else if rejected_candidate_count > 0 || needs_more_evidence_count > 0 {
            PaperGovernanceTrialCandidateSelectionStatus::SelectedWithWarnings
        } else {
            PaperGovernanceTrialCandidateSelectionStatus::Selected
        },
        paper_only: true,
    })
}

fn init_paper_governance_trial_member_state(
    actual_member_state: &MemberStateSnapshot,
    shadow_store: Option<&ChairmanShadowGovernanceStateStore>,
) -> PaperGovernanceTrialMemberState {
    let shadow_state = shadow_store
        .and_then(|store| get_shadow_member_state(store, &actual_member_state.member_id));
    PaperGovernanceTrialMemberState {
        member_id: actual_member_state.member_id.clone(),
        role: paper_governance_trial_role_for_member(&actual_member_state.member_id, shadow_store),
        actual_score_snapshot: actual_member_state.score,
        actual_voice_snapshot: actual_member_state.voice_weight,
        shadow_score_snapshot: shadow_state.map(|state| state.shadow_score),
        shadow_voice_snapshot: shadow_state.map(|state| state.shadow_voice_weight),
        paper_trial_score: actual_member_state.score,
        paper_trial_voice_weight: actual_member_state.voice_weight,
        applied_trial_score_delta: 0.0,
        applied_trial_voice_delta: 0.0,
        trial_reward_count: 0,
        trial_penalty_count: 0,
        trial_voice_increase_count: 0,
        trial_voice_decrease_count: 0,
        paper_only: true,
    }
}

pub fn normalize_paper_governance_trial_state_store(store: &mut PaperGovernanceTrialStateStore) {
    let mut seen = BTreeSet::new();
    store
        .member_states
        .sort_by(|left, right| left.member_id.cmp(&right.member_id));
    store
        .member_states
        .retain(|state| seen.insert(state.member_id.clone()));
    store.member_count = store.member_states.len();
}

fn validate_paper_governance_trial_state_store(
    store: &PaperGovernanceTrialStateStore,
) -> Result<(), String> {
    if !store.paper_only {
        return Err("paper governance trial state store must stay paper_only".to_string());
    }
    reject_unsafe_owner_feedback_string(&store.store_id)?;
    if value_contains_debug_marker(
        store,
        &[
            "broker".to_string(),
            "order".to_string(),
            "account".to_string(),
            "trade".to_string(),
            "live".to_string(),
        ],
    ) {
        return Err(
            "paper governance trial state store contains forbidden live-execution wording"
                .to_string(),
        );
    }
    for state in &store.member_states {
        if !state.paper_only {
            return Err(format!(
                "paper governance trial member state {} must stay paper_only",
                state.member_id
            ));
        }
        reject_unsafe_owner_feedback_string(&state.member_id)?;
    }
    Ok(())
}

pub fn initialize_paper_governance_trial_state_store(
    actual_member_states: &[MemberStateSnapshot],
    shadow_store: Option<&ChairmanShadowGovernanceStateStore>,
) -> PaperGovernanceTrialStateStore {
    let mut store = PaperGovernanceTrialStateStore {
        store_id: "paper-governance-trial-state-store".to_string(),
        member_states: actual_member_states
            .iter()
            .map(|state| init_paper_governance_trial_member_state(state, shadow_store))
            .collect(),
        member_count: actual_member_states.len(),
        latest_run_id: None,
        update_count: 0,
        paper_only: true,
    };
    normalize_paper_governance_trial_state_store(&mut store);
    store
}

pub fn load_paper_governance_trial_state_store_from_local_json(
    path: &Path,
) -> Result<PaperGovernanceTrialStateStore, String> {
    validate_local_json_path(path, "paper governance trial state path")?;
    let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
    let mut store: PaperGovernanceTrialStateStore =
        serde_json::from_str(&text).map_err(|err| err.to_string())?;
    validate_paper_governance_trial_state_store(&store)?;
    normalize_paper_governance_trial_state_store(&mut store);
    validate_paper_governance_trial_state_store(&store)?;
    Ok(store)
}

pub fn save_paper_governance_trial_state_store_to_local_json(
    path: &Path,
    store: &PaperGovernanceTrialStateStore,
) -> Result<(), String> {
    validate_local_json_path(path, "paper governance trial state path")?;
    let mut normalized = store.clone();
    normalize_paper_governance_trial_state_store(&mut normalized);
    validate_paper_governance_trial_state_store(&normalized)?;
    write_safe_json(path, &normalized)
}

fn normalize_paper_trial_voice_weights(store: &mut PaperGovernanceTrialStateStore) {
    if store.member_states.is_empty() {
        return;
    }
    for state in &mut store.member_states {
        state.paper_trial_voice_weight = state.paper_trial_voice_weight.max(0.0);
    }
    let total = store
        .member_states
        .iter()
        .map(|state| state.paper_trial_voice_weight)
        .sum::<f64>();
    if total <= f64::EPSILON {
        let equal_weight = 1.0 / store.member_states.len() as f64;
        for state in &mut store.member_states {
            state.paper_trial_voice_weight = equal_weight;
            state.applied_trial_voice_delta =
                state.paper_trial_voice_weight - state.actual_voice_snapshot;
        }
        return;
    }
    for state in &mut store.member_states {
        state.paper_trial_voice_weight /= total;
        state.applied_trial_voice_delta =
            state.paper_trial_voice_weight - state.actual_voice_snapshot;
    }
}

pub fn apply_paper_governance_trial_candidates(
    store: &mut PaperGovernanceTrialStateStore,
    candidates: &[PaperGovernanceTrialCandidate],
    policy: &PaperGovernanceTrialEligibilityPolicy,
) -> Result<PaperGovernanceTrialApplyResult, String> {
    validate_paper_governance_trial_eligibility_policy(policy)?;
    validate_paper_governance_trial_state_store(store)?;
    if !policy.allow_score_delta_trial && !policy.allow_voice_delta_trial {
        return Ok(PaperGovernanceTrialApplyResult {
            run_id: store
                .latest_run_id
                .clone()
                .unwrap_or_else(|| "paper-governance-trial-blocked".to_string()),
            input_candidate_count: candidates.len(),
            applied_candidate_count: 0,
            updated_member_count: 0,
            score_delta_apply_count: 0,
            voice_delta_apply_count: 0,
            before_after_standings: Vec::new(),
            apply_status: PaperGovernanceTrialApplyStatus::Blocked,
            no_actual_score_mutation: true,
            no_actual_voice_mutation: true,
            no_promotion_demotion: true,
            no_risk_governor_override: true,
            paper_only: true,
        });
    }
    let eligible_by_member = candidates
        .iter()
        .filter(|candidate| candidate.eligible)
        .map(|candidate| (candidate.member_id.clone(), candidate))
        .collect::<BTreeMap<_, _>>();
    let mut before_after_standings = Vec::new();
    let mut applied_candidate_count = 0;
    let mut score_delta_apply_count = 0;
    let mut voice_delta_apply_count = 0;
    let mut updated_member_count = 0;
    for state in &mut store.member_states {
        let paper_trial_score_before = state.paper_trial_score;
        let paper_trial_voice_before = state.paper_trial_voice_weight;
        if let Some(candidate) = eligible_by_member.get(&state.member_id) {
            let mut touched = false;
            if policy.allow_score_delta_trial {
                if let Some(score_delta) = candidate.proposed_score_delta {
                    let bounded = score_delta.clamp(
                        -policy.max_score_delta_per_member,
                        policy.max_score_delta_per_member,
                    );
                    state.paper_trial_score += bounded;
                    state.applied_trial_score_delta += bounded;
                    if bounded > 0.0 {
                        state.trial_reward_count += 1;
                    } else if bounded < 0.0 {
                        state.trial_penalty_count += 1;
                    }
                    if bounded.abs() > f64::EPSILON {
                        touched = true;
                        score_delta_apply_count += 1;
                    }
                }
            }
            if policy.allow_voice_delta_trial {
                if let Some(voice_delta) = candidate.proposed_voice_delta {
                    let bounded = voice_delta.clamp(
                        -policy.max_voice_delta_per_member,
                        policy.max_voice_delta_per_member,
                    );
                    state.paper_trial_voice_weight += bounded;
                    state.applied_trial_voice_delta += bounded;
                    if bounded > 0.0 {
                        state.trial_voice_increase_count += 1;
                    } else if bounded < 0.0 {
                        state.trial_voice_decrease_count += 1;
                    }
                    if bounded.abs() > f64::EPSILON {
                        touched = true;
                        voice_delta_apply_count += 1;
                    }
                }
            }
            if touched {
                applied_candidate_count += 1;
                updated_member_count += 1;
            }
        }
        before_after_standings.push(PaperTrialBeforeAfterStanding {
            member_id: state.member_id.clone(),
            paper_trial_score_before,
            paper_trial_score_after: state.paper_trial_score,
            paper_trial_voice_before,
            paper_trial_voice_after: state.paper_trial_voice_weight,
            score_delta_applied: state.paper_trial_score - paper_trial_score_before,
            voice_delta_applied: state.paper_trial_voice_weight - paper_trial_voice_before,
            paper_only: true,
        });
    }
    if voice_delta_apply_count > 0 {
        normalize_paper_trial_voice_weights(store);
        for standing in &mut before_after_standings {
            if let Some(state) = store
                .member_states
                .iter()
                .find(|state| state.member_id == standing.member_id)
            {
                standing.paper_trial_score_after = state.paper_trial_score;
                standing.paper_trial_voice_after = state.paper_trial_voice_weight;
                standing.score_delta_applied =
                    standing.paper_trial_score_after - standing.paper_trial_score_before;
                standing.voice_delta_applied =
                    standing.paper_trial_voice_after - standing.paper_trial_voice_before;
            }
        }
    }
    store.update_count += usize::from(applied_candidate_count > 0);
    normalize_paper_governance_trial_state_store(store);
    Ok(PaperGovernanceTrialApplyResult {
        run_id: store
            .latest_run_id
            .clone()
            .unwrap_or_else(|| "paper-governance-trial-apply".to_string()),
        input_candidate_count: candidates.len(),
        applied_candidate_count,
        updated_member_count,
        score_delta_apply_count,
        voice_delta_apply_count,
        before_after_standings,
        apply_status: if candidates.is_empty() || applied_candidate_count == 0 {
            PaperGovernanceTrialApplyStatus::NoCandidatesApplied
        } else if applied_candidate_count
            < candidates
                .iter()
                .filter(|candidate| candidate.eligible)
                .count()
        {
            PaperGovernanceTrialApplyStatus::AppliedToPaperTrialWithWarnings
        } else {
            PaperGovernanceTrialApplyStatus::AppliedToPaperTrial
        },
        no_actual_score_mutation: true,
        no_actual_voice_mutation: true,
        no_promotion_demotion: true,
        no_risk_governor_override: true,
        paper_only: true,
    })
}

pub fn compare_actual_shadow_paper_governance(
    actual_member_states: &[MemberStateSnapshot],
    shadow_store: Option<&ChairmanShadowGovernanceStateStore>,
    paper_trial_store: &PaperGovernanceTrialStateStore,
) -> (
    Vec<ActualShadowPaperGovernanceComparison>,
    ActualShadowPaperGovernanceComparisonSummary,
) {
    let comparisons = actual_member_states
        .iter()
        .map(|actual| {
            let shadow =
                shadow_store.and_then(|store| get_shadow_member_state(store, &actual.member_id));
            let paper = paper_trial_store
                .member_states
                .iter()
                .find(|state| state.member_id == actual.member_id);
            let paper_trial_score = paper
                .map(|state| state.paper_trial_score)
                .unwrap_or(actual.score);
            let paper_trial_voice = paper
                .map(|state| state.paper_trial_voice_weight)
                .unwrap_or(actual.voice_weight);
            let shadow_score = shadow.map(|state| state.shadow_score);
            let shadow_voice = shadow.map(|state| state.shadow_voice_weight);
            let actual_to_paper_score_gap = paper_trial_score - actual.score;
            let actual_to_paper_voice_gap = paper_trial_voice - actual.voice_weight;
            let shadow_to_paper_score_gap =
                shadow_score.map(|shadow_score| paper_trial_score - shadow_score);
            let shadow_to_paper_voice_gap =
                shadow_voice.map(|shadow_voice| paper_trial_voice - shadow_voice);
            let comparison_status = if paper_trial_store.update_count == 0 {
                ActualShadowPaperGovernanceComparisonStatus::NeedsMoreHistory
            } else if shadow_to_paper_score_gap
                .zip(shadow_to_paper_voice_gap)
                .is_some_and(|(score_gap, voice_gap)| {
                    score_gap.abs() <= 0.05 && voice_gap.abs() <= 0.05
                })
            {
                ActualShadowPaperGovernanceComparisonStatus::PaperTrialCloseToShadow
            } else if actual_to_paper_score_gap.abs() <= 0.05
                && actual_to_paper_voice_gap.abs() <= 0.05
            {
                ActualShadowPaperGovernanceComparisonStatus::PaperTrialCloseToActual
            } else {
                ActualShadowPaperGovernanceComparisonStatus::PaperTrialDiverged
            };
            ActualShadowPaperGovernanceComparison {
                comparison_id: format!("{}-actual-shadow-paper", actual.member_id),
                member_id: actual.member_id.clone(),
                actual_score: actual.score,
                shadow_score,
                paper_trial_score,
                actual_voice: actual.voice_weight,
                shadow_voice,
                paper_trial_voice,
                actual_to_paper_score_gap,
                shadow_to_paper_score_gap,
                actual_to_paper_voice_gap,
                shadow_to_paper_voice_gap,
                comparison_status,
                paper_only: true,
            }
        })
        .collect::<Vec<_>>();
    let paper_trial_diverged_count = comparisons
        .iter()
        .filter(|comparison| {
            comparison.comparison_status
                == ActualShadowPaperGovernanceComparisonStatus::PaperTrialDiverged
        })
        .count();
    let close_to_shadow_count = comparisons
        .iter()
        .filter(|comparison| {
            comparison.comparison_status
                == ActualShadowPaperGovernanceComparisonStatus::PaperTrialCloseToShadow
        })
        .count();
    let close_to_actual_count = comparisons
        .iter()
        .filter(|comparison| {
            comparison.comparison_status
                == ActualShadowPaperGovernanceComparisonStatus::PaperTrialCloseToActual
        })
        .count();
    let max_score_gap = comparisons
        .iter()
        .map(|comparison| comparison.actual_to_paper_score_gap.abs())
        .fold(0.0, f64::max);
    let max_voice_gap = comparisons
        .iter()
        .map(|comparison| comparison.actual_to_paper_voice_gap.abs())
        .fold(0.0, f64::max);
    let summary = ActualShadowPaperGovernanceComparisonSummary {
        summary_id: format!("{}-actual-shadow-paper-summary", paper_trial_store.store_id),
        member_count: comparisons.len(),
        paper_trial_diverged_count,
        close_to_shadow_count,
        close_to_actual_count,
        max_score_gap,
        max_voice_gap,
        summary_status: if paper_trial_store.update_count == 0 {
            ActualVsShadowGovernanceSummaryStatus::InsufficientHistory
        } else if paper_trial_diverged_count > 0 {
            ActualVsShadowGovernanceSummaryStatus::Diverged
        } else if close_to_actual_count > 0 {
            ActualVsShadowGovernanceSummaryStatus::StableWithWarnings
        } else {
            ActualVsShadowGovernanceSummaryStatus::Stable
        },
        paper_only: true,
    };
    (comparisons, summary)
}

pub fn compare_committee_voice_distribution_under_paper_trial(
    actual_member_states: &[MemberStateSnapshot],
    paper_trial_store: &PaperGovernanceTrialStateStore,
) -> PaperGovernanceTrialCommitteeComparisonResult {
    if actual_member_states.is_empty() {
        return PaperGovernanceTrialCommitteeComparisonResult {
            comparison_id: format!("{}-committee-voice-comparison", paper_trial_store.store_id),
            records: Vec::new(),
            record_count: 0,
            estimated_voice_shift_count: 0,
            comparison_status: PaperGovernanceTrialCommitteeComparisonStatus::Blocked,
            paper_only: true,
        };
    }
    let records = actual_member_states
        .iter()
        .map(|state| {
            let paper_state = paper_trial_store
                .member_states
                .iter()
                .find(|member_state| member_state.member_id == state.member_id);
            let paper_trial_voice_weight = paper_state
                .map(|member_state| member_state.paper_trial_voice_weight)
                .unwrap_or(state.voice_weight);
            let comparison_note = if (paper_trial_voice_weight - state.voice_weight).abs() <= 0.01 {
                "paper trial keeps effective committee voice unchanged".to_string()
            } else if paper_trial_voice_weight > state.voice_weight {
                "paper trial would increase hypothetical committee voice".to_string()
            } else {
                "paper trial would decrease hypothetical committee voice".to_string()
            };
            PaperGovernanceTrialCommitteeComparisonRecord {
                record_id: format!("{}-paper-trial-voice", state.member_id),
                member_id: Some(state.member_id.clone()),
                actual_voice_weight: state.voice_weight,
                paper_trial_voice_weight,
                actual_vote_weight_contribution: Some(state.voice_weight),
                paper_trial_vote_weight_contribution: Some(paper_trial_voice_weight),
                comparison_note,
                paper_only: true,
            }
        })
        .collect::<Vec<_>>();
    let estimated_voice_shift_count = records
        .iter()
        .filter(|record| {
            (record.paper_trial_voice_weight - record.actual_voice_weight).abs() > 0.01
        })
        .count();
    PaperGovernanceTrialCommitteeComparisonResult {
        comparison_id: format!("{}-committee-voice-comparison", paper_trial_store.store_id),
        record_count: records.len(),
        records,
        estimated_voice_shift_count,
        comparison_status: if paper_trial_store.update_count == 0 {
            PaperGovernanceTrialCommitteeComparisonStatus::ComparedWithWarnings
        } else if estimated_voice_shift_count == 0 {
            PaperGovernanceTrialCommitteeComparisonStatus::NoChange
        } else {
            PaperGovernanceTrialCommitteeComparisonStatus::Compared
        },
        paper_only: true,
    }
}

pub fn evaluate_paper_governance_trial_safety(
    trial_result: &PaperGovernanceTrialRunResult,
    before_actual_state: &[MemberStateSnapshot],
    after_actual_state: Option<&[MemberStateSnapshot]>,
    batch_before: &BatchCommitteeCycleResult,
    batch_after: Option<&BatchCommitteeCycleResult>,
) -> PaperGovernanceTrialSafetyGuard {
    let after_actual_state = after_actual_state.unwrap_or(before_actual_state);
    let after_batch = batch_after.unwrap_or(batch_before);
    let actual_score_snapshot = |states: &[MemberStateSnapshot]| {
        states
            .iter()
            .map(|state| (state.member_id.clone(), state.score))
            .collect::<BTreeMap<_, _>>()
    };
    let actual_voice_snapshot = |states: &[MemberStateSnapshot]| {
        states
            .iter()
            .map(|state| (state.member_id.clone(), state.voice_weight))
            .collect::<BTreeMap<_, _>>()
    };
    let promotion_snapshot = |updates: &[MemberScoreUpdate]| {
        updates
            .iter()
            .filter(|update| update.promoted || update.demoted)
            .map(|update| update.member_id.clone())
            .collect::<BTreeSet<_>>()
    };
    let risk_snapshot = |decisions: &[ChairmanDecision]| {
        decisions
            .iter()
            .map(|decision| (decision.decision_id.clone(), decision.risk_governor_status))
            .collect::<BTreeMap<_, _>>()
    };
    let live_decision_markers = vec![
        trial_result.run_id.clone(),
        "paper-trial-live".to_string(),
        "paper-governance-live".to_string(),
    ];
    let actual_score_mutation_detected =
        actual_score_snapshot(before_actual_state) != actual_score_snapshot(after_actual_state);
    let actual_voice_mutation_detected =
        actual_voice_snapshot(before_actual_state) != actual_voice_snapshot(after_actual_state);
    let promotion_demotion_detected = promotion_snapshot(&batch_before.score_updates)
        != promotion_snapshot(&after_batch.score_updates);
    let risk_governor_override_detected = risk_snapshot(&batch_before.chairman_decisions)
        != risk_snapshot(&after_batch.chairman_decisions);
    let committee_decision_mutation_detected = batch_before.committee_sessions
        != after_batch.committee_sessions
        || batch_before.chairman_decisions != after_batch.chairman_decisions;
    let member_opinion_mutation_detected =
        batch_before.member_opinions != after_batch.member_opinions;
    let trade_markers = [
        format!("{}-paper-trial-trade", trial_result.run_id),
        "trade-signal".to_string(),
    ];
    let order_markers = [
        format!("{}-paper-trial-order", trial_result.run_id),
        "order".to_string(),
    ];
    let broker_order_account_markers = [
        "broker".to_string(),
        "order".to_string(),
        "account".to_string(),
    ];
    let trade_signal_detected =
        value_contains_debug_marker(&after_batch.committee_sessions, &trade_markers)
            && !value_contains_debug_marker(&batch_before.committee_sessions, &trade_markers);
    let order_detected = value_contains_debug_marker(&after_batch.event_queue, &order_markers)
        && !value_contains_debug_marker(&batch_before.event_queue, &order_markers);
    let broker_order_account_detected =
        value_contains_debug_marker(after_batch, &broker_order_account_markers)
            && !value_contains_debug_marker(batch_before, &broker_order_account_markers);
    let paper_trial_used_as_live_decision_detected =
        (value_contains_debug_marker(&after_batch.chairman_decisions, &live_decision_markers)
            && !value_contains_debug_marker(
                &batch_before.chairman_decisions,
                &live_decision_markers,
            ))
            || (value_contains_debug_marker(
                &after_batch.committee_sessions,
                &live_decision_markers,
            ) && !value_contains_debug_marker(
                &batch_before.committee_sessions,
                &live_decision_markers,
            ));
    let mut violations = Vec::new();
    if actual_score_mutation_detected {
        violations.push("paper governance trial mutated actual score".to_string());
    }
    if actual_voice_mutation_detected {
        violations.push("paper governance trial mutated actual voice".to_string());
    }
    if promotion_demotion_detected {
        violations.push("paper governance trial executed promotion or demotion".to_string());
    }
    if risk_governor_override_detected {
        violations.push("paper governance trial overrode Risk Governor".to_string());
    }
    if committee_decision_mutation_detected {
        violations.push("paper governance trial changed committee decisions".to_string());
    }
    if member_opinion_mutation_detected {
        violations.push("paper governance trial changed member opinions".to_string());
    }
    if trade_signal_detected {
        violations.push("paper governance trial created a trade signal".to_string());
    }
    if order_detected {
        violations.push("paper governance trial created an order".to_string());
    }
    if broker_order_account_detected {
        violations.push("paper governance trial touched broker/order/account".to_string());
    }
    if paper_trial_used_as_live_decision_detected {
        violations
            .push("paper governance trial was referenced as a live decision source".to_string());
    }
    PaperGovernanceTrialSafetyGuard {
        actual_score_mutation_detected,
        actual_voice_mutation_detected,
        promotion_demotion_detected,
        risk_governor_override_detected,
        committee_decision_mutation_detected,
        member_opinion_mutation_detected,
        trade_signal_detected,
        order_detected,
        broker_order_account_detected,
        paper_trial_used_as_live_decision_detected,
        guard_status: if violations.is_empty() {
            PaperGovernanceTrialSafetyGuardStatus::Preserved
        } else {
            PaperGovernanceTrialSafetyGuardStatus::Violated
        },
        violations,
        paper_only: true,
    }
}

pub fn evaluate_paper_governance_trial_readiness(
    candidate_selection: &PaperGovernanceTrialCandidateSelectionResult,
    trial_apply: &PaperGovernanceTrialApplyResult,
    comparison_summary: &ActualShadowPaperGovernanceComparisonSummary,
    committee_comparison: Option<&PaperGovernanceTrialCommitteeComparisonResult>,
    safety_guard: &PaperGovernanceTrialSafetyGuard,
) -> PaperGovernanceTrialReadinessResult {
    let committee_status = committee_comparison
        .map(|comparison| comparison.comparison_status)
        .unwrap_or(PaperGovernanceTrialCommitteeComparisonStatus::ComparedWithWarnings);
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    if safety_guard.guard_status == PaperGovernanceTrialSafetyGuardStatus::Violated {
        blockers.push("paper trial safety guard violated".to_string());
    }
    match candidate_selection.selection_status {
        PaperGovernanceTrialCandidateSelectionStatus::Blocked => {
            blockers.push("paper trial candidate selection blocked".to_string());
        }
        PaperGovernanceTrialCandidateSelectionStatus::NoEligibleCandidates => {
            blockers.push("paper trial has no eligible governance candidates".to_string());
        }
        PaperGovernanceTrialCandidateSelectionStatus::SelectedWithWarnings => {
            warnings.push("paper trial candidate selection has warnings".to_string());
        }
        PaperGovernanceTrialCandidateSelectionStatus::Selected => {}
    }
    if comparison_summary.summary_status == ActualVsShadowGovernanceSummaryStatus::Diverged {
        blockers.push("paper trial diverged from actual/shadow standing".to_string());
    } else if comparison_summary.summary_status
        == ActualVsShadowGovernanceSummaryStatus::InsufficientHistory
    {
        warnings.push("paper trial needs more shadow history".to_string());
    } else if comparison_summary.summary_status
        == ActualVsShadowGovernanceSummaryStatus::StableWithWarnings
    {
        warnings.push("paper trial comparison is stable with warnings".to_string());
    }
    if matches!(
        committee_status,
        PaperGovernanceTrialCommitteeComparisonStatus::ComparedWithWarnings
    ) {
        warnings.push("committee voice comparison was emitted with warnings".to_string());
    } else if committee_status == PaperGovernanceTrialCommitteeComparisonStatus::Blocked {
        blockers.push("committee voice comparison is blocked".to_string());
    }
    let readiness_status = if safety_guard.guard_status
        == PaperGovernanceTrialSafetyGuardStatus::Violated
    {
        PaperGovernanceTrialReadinessStatus::BlockedBySafety
    } else if candidate_selection.selection_status
        == PaperGovernanceTrialCandidateSelectionStatus::Blocked
        || comparison_summary.summary_status == ActualVsShadowGovernanceSummaryStatus::Diverged
        || trial_apply.apply_status == PaperGovernanceTrialApplyStatus::Blocked
    {
        PaperGovernanceTrialReadinessStatus::BlockedByDivergence
    } else if candidate_selection.selection_status
        == PaperGovernanceTrialCandidateSelectionStatus::NoEligibleCandidates
    {
        PaperGovernanceTrialReadinessStatus::NeedsMoreCandidates
    } else if comparison_summary.summary_status
        == ActualVsShadowGovernanceSummaryStatus::InsufficientHistory
    {
        PaperGovernanceTrialReadinessStatus::NeedsMoreShadowHistory
    } else if trial_apply.apply_status == PaperGovernanceTrialApplyStatus::AppliedToPaperTrial
        && committee_status != PaperGovernanceTrialCommitteeComparisonStatus::ComparedWithWarnings
        && comparison_summary.summary_status == ActualVsShadowGovernanceSummaryStatus::Stable
    {
        PaperGovernanceTrialReadinessStatus::ReadyForRepeatedPaperTrial
    } else {
        PaperGovernanceTrialReadinessStatus::ReadyWithWarnings
    };
    PaperGovernanceTrialReadinessResult {
        readiness_id: format!("{}-readiness", candidate_selection.selection_id),
        candidate_selection_status: candidate_selection.selection_status,
        trial_apply_status: trial_apply.apply_status,
        actual_shadow_paper_comparison_status: comparison_summary.summary_status,
        committee_comparison_status: committee_status,
        safety_guard_status: safety_guard.guard_status,
        ready_for_repeated_paper_trial: readiness_status
            == PaperGovernanceTrialReadinessStatus::ReadyForRepeatedPaperTrial,
        readiness_status,
        blockers,
        warnings,
        paper_only: true,
    }
}

pub fn build_owner_paper_governance_trial_summary(
    trial_result: &PaperGovernanceTrialRunResult,
) -> OwnerPaperGovernanceTrialSummary {
    OwnerPaperGovernanceTrialSummary {
        summary_id: format!("{}-owner-paper-trial-summary", trial_result.run_id),
        candidate_count: trial_result.candidate_selection.eligible_candidate_count,
        applied_candidate_count: trial_result.trial_apply_result.applied_candidate_count,
        updated_member_count: trial_result.trial_apply_result.updated_member_count,
        comparison_status: trial_result.actual_shadow_paper_comparison.summary_status,
        readiness_status: trial_result.readiness_result.readiness_status,
        message: "Governance candidates were applied only to paper trial state. Actual member score and voice did not change. Committee decisions and Risk Governor were not changed. This is not live governance."
            .to_string(),
        paper_trial_only: true,
        no_actual_score_mutation: true,
        no_actual_voice_mutation: true,
        no_promotion_demotion: true,
        no_risk_override: true,
        no_committee_decision_change: true,
        not_trade_signal: true,
        paper_only: true,
    }
}

pub fn run_paper_governance_trial_sandbox(
    actual_member_states: &[MemberStateSnapshot],
    shadow_store: Option<&ChairmanShadowGovernanceStateStore>,
    tuned_governance_result: &ConservativeVoiceTuningV2RunResult,
    batch_result: &BatchCommitteeCycleResult,
    config: &PaperGovernanceTrialRunConfig,
) -> Result<PaperGovernanceTrialRunResult, String> {
    if !config.paper_only {
        return Err("paper governance trial run must stay paper_only".to_string());
    }
    for (path, label) in [
        (
            config.trial_state_input_path.as_ref(),
            "paper governance trial state input path",
        ),
        (
            config.trial_state_output_path.as_ref(),
            "paper governance trial state output path",
        ),
    ] {
        if let Some(path) = path {
            validate_local_json_path(Path::new(path), label)?;
        }
    }
    if !config.dry_run && config.trial_state_output_path.is_none() {
        return Err(
            "paper governance trial requires trial_state_output_path when dry_run=false"
                .to_string(),
        );
    }
    let simulation_result = batch_result
        .chairman_shadow_governance_simulation_result
        .as_ref()
        .ok_or_else(|| {
            "paper governance trial requires chairman shadow governance simulation result"
                .to_string()
        })?;
    let eligibility_policy = default_paper_governance_trial_eligibility_policy();
    let candidate_selection = select_paper_governance_trial_candidates(
        simulation_result,
        tuned_governance_result,
        &PaperGovernanceTrialEligibilityPolicy {
            max_score_delta_per_member: effective_paper_trial_score_cap(
                &eligibility_policy,
                tuned_governance_result,
            ),
            max_voice_delta_per_member: effective_paper_trial_voice_cap(
                &eligibility_policy,
                tuned_governance_result,
            ),
            ..eligibility_policy.clone()
        },
    )?;
    let mut trial_store = if let Some(path) = config.trial_state_input_path.as_ref() {
        if Path::new(path).exists() {
            load_paper_governance_trial_state_store_from_local_json(Path::new(path))?
        } else {
            initialize_paper_governance_trial_state_store(actual_member_states, shadow_store)
        }
    } else {
        initialize_paper_governance_trial_state_store(actual_member_states, shadow_store)
    };
    let trial_store_before = Some(trial_store.clone());
    trial_store.latest_run_id = Some(config.run_id.clone());
    let trial_apply_result = if config.apply_trial_candidates {
        apply_paper_governance_trial_candidates(
            &mut trial_store,
            &candidate_selection.candidates,
            &PaperGovernanceTrialEligibilityPolicy {
                max_score_delta_per_member: effective_paper_trial_score_cap(
                    &eligibility_policy,
                    tuned_governance_result,
                ),
                max_voice_delta_per_member: effective_paper_trial_voice_cap(
                    &eligibility_policy,
                    tuned_governance_result,
                ),
                ..eligibility_policy.clone()
            },
        )?
    } else {
        PaperGovernanceTrialApplyResult {
            run_id: config.run_id.clone(),
            input_candidate_count: candidate_selection.input_candidate_count,
            applied_candidate_count: 0,
            updated_member_count: 0,
            score_delta_apply_count: 0,
            voice_delta_apply_count: 0,
            before_after_standings: Vec::new(),
            apply_status: PaperGovernanceTrialApplyStatus::NoCandidatesApplied,
            no_actual_score_mutation: true,
            no_actual_voice_mutation: true,
            no_promotion_demotion: true,
            no_risk_governor_override: true,
            paper_only: true,
        }
    };
    let (_comparisons, actual_shadow_paper_comparison) =
        compare_actual_shadow_paper_governance(actual_member_states, shadow_store, &trial_store);
    let committee_voice_comparison = config.compare_committee_voice_distribution.then(|| {
        compare_committee_voice_distribution_under_paper_trial(actual_member_states, &trial_store)
    });
    let committee_readiness_comparison = committee_voice_comparison.clone().or_else(|| {
        Some(PaperGovernanceTrialCommitteeComparisonResult {
            comparison_id: format!("{}-committee-voice-comparison", config.run_id),
            records: Vec::new(),
            record_count: 0,
            estimated_voice_shift_count: 0,
            comparison_status: PaperGovernanceTrialCommitteeComparisonStatus::ComparedWithWarnings,
            paper_only: true,
        })
    });
    let mut provisional = PaperGovernanceTrialRunResult {
        run_id: config.run_id.clone(),
        candidate_selection: candidate_selection.clone(),
        trial_store_before,
        trial_apply_result: trial_apply_result.clone(),
        trial_store_after: Some(trial_store.clone()),
        actual_shadow_paper_comparison: actual_shadow_paper_comparison.clone(),
        committee_voice_comparison: committee_voice_comparison.clone(),
        readiness_result: PaperGovernanceTrialReadinessResult {
            readiness_id: format!("{}-paper-trial-readiness", config.run_id),
            candidate_selection_status: candidate_selection.selection_status,
            trial_apply_status: trial_apply_result.apply_status,
            actual_shadow_paper_comparison_status: actual_shadow_paper_comparison.summary_status,
            committee_comparison_status: committee_readiness_comparison
                .as_ref()
                .map(|comparison| comparison.comparison_status)
                .unwrap_or(PaperGovernanceTrialCommitteeComparisonStatus::ComparedWithWarnings),
            safety_guard_status: PaperGovernanceTrialSafetyGuardStatus::Preserved,
            ready_for_repeated_paper_trial: false,
            readiness_status: PaperGovernanceTrialReadinessStatus::ReadyWithWarnings,
            blockers: Vec::new(),
            warnings: Vec::new(),
            paper_only: true,
        },
        safety_guard: PaperGovernanceTrialSafetyGuard {
            actual_score_mutation_detected: false,
            actual_voice_mutation_detected: false,
            promotion_demotion_detected: false,
            risk_governor_override_detected: false,
            committee_decision_mutation_detected: false,
            member_opinion_mutation_detected: false,
            trade_signal_detected: false,
            order_detected: false,
            broker_order_account_detected: false,
            paper_trial_used_as_live_decision_detected: false,
            guard_status: PaperGovernanceTrialSafetyGuardStatus::Preserved,
            violations: Vec::new(),
            paper_only: true,
        },
        owner_summary: None,
        run_status: PaperGovernanceTrialRunStatus::PassedWithWarnings,
        paper_only: true,
    };
    let safety_guard = evaluate_paper_governance_trial_safety(
        &provisional,
        actual_member_states,
        Some(actual_member_states),
        batch_result,
        Some(batch_result),
    );
    provisional.safety_guard = safety_guard.clone();
    provisional.readiness_result = evaluate_paper_governance_trial_readiness(
        &provisional.candidate_selection,
        &provisional.trial_apply_result,
        &provisional.actual_shadow_paper_comparison,
        committee_readiness_comparison.as_ref(),
        &provisional.safety_guard,
    );
    if config.emit_owner_summary {
        provisional.owner_summary = Some(build_owner_paper_governance_trial_summary(&provisional));
    }
    provisional.run_status = if provisional.safety_guard.guard_status
        == PaperGovernanceTrialSafetyGuardStatus::Violated
    {
        PaperGovernanceTrialRunStatus::Failed
    } else if provisional.readiness_result.readiness_status
        == PaperGovernanceTrialReadinessStatus::ReadyForRepeatedPaperTrial
    {
        PaperGovernanceTrialRunStatus::Passed
    } else {
        PaperGovernanceTrialRunStatus::PassedWithWarnings
    };
    if !config.dry_run {
        if let Some(path) = config.trial_state_output_path.as_ref() {
            save_paper_governance_trial_state_store_to_local_json(Path::new(path), &trial_store)?;
        }
    }
    Ok(provisional)
}

pub fn default_counterfactual_committee_replay_policy() -> CounterfactualCommitteeReplayPolicy {
    CounterfactualCommitteeReplayPolicy {
        policy_id: "default-counterfactual-committee-replay-policy".to_string(),
        use_paper_trial_voice_weights: true,
        use_actual_member_opinions: true,
        use_actual_event_queue: true,
        use_actual_risk_governor_result: true,
        allow_chairman_decision_mutation: false,
        allow_committee_session_mutation: false,
        allow_risk_governor_mutation: false,
        allow_trade_signal: false,
        allow_order: false,
        paper_only: true,
    }
}

pub fn validate_counterfactual_committee_replay_policy(
    policy: &CounterfactualCommitteeReplayPolicy,
) -> Result<(), String> {
    if !policy.paper_only {
        return Err("counterfactual committee replay policy must stay paper_only".to_string());
    }
    if !policy.use_paper_trial_voice_weights
        || !policy.use_actual_member_opinions
        || !policy.use_actual_event_queue
        || !policy.use_actual_risk_governor_result
    {
        return Err(
            "counterfactual committee replay policy must use paper voice weights and actual committee inputs"
                .to_string(),
        );
    }
    if policy.allow_chairman_decision_mutation
        || policy.allow_committee_session_mutation
        || policy.allow_risk_governor_mutation
        || policy.allow_trade_signal
        || policy.allow_order
    {
        return Err(
            "counterfactual committee replay policy must remain comparison-only without mutation or trading"
                .to_string(),
        );
    }
    reject_unsafe_owner_feedback_string(&policy.policy_id)?;
    Ok(())
}

fn default_paper_governance_trial_ledger() -> PaperGovernanceTrialLedger {
    PaperGovernanceTrialLedger {
        ledger_id: "paper-governance-trial-ledger".to_string(),
        entries: Vec::new(),
        entry_count: 0,
        latest_entry_id: None,
        paper_only: true,
    }
}

pub fn normalize_paper_governance_trial_ledger(ledger: &mut PaperGovernanceTrialLedger) {
    let mut deduped = BTreeMap::new();
    for entry in &ledger.entries {
        deduped
            .entry(entry.entry_id.clone())
            .or_insert_with(|| entry.clone());
    }
    ledger.entries = deduped.into_values().collect();
    ledger
        .entries
        .sort_by(|left, right| left.entry_id.cmp(&right.entry_id));
    ledger.entry_count = ledger.entries.len();
    ledger.latest_entry_id = ledger.entries.last().map(|entry| entry.entry_id.clone());
}

fn validate_paper_governance_trial_ledger(
    ledger: &PaperGovernanceTrialLedger,
) -> Result<(), String> {
    if !ledger.paper_only {
        return Err("paper governance trial ledger must stay paper_only".to_string());
    }
    reject_unsafe_owner_feedback_string(&ledger.ledger_id)?;
    if value_contains_debug_marker(
        ledger,
        &[
            "broker".to_string(),
            "order".to_string(),
            "account".to_string(),
            "trade".to_string(),
            "live".to_string(),
        ],
    ) {
        return Err(
            "paper governance trial ledger contains forbidden live-execution wording".to_string(),
        );
    }
    for entry in &ledger.entries {
        if !entry.paper_only {
            return Err(format!(
                "paper governance trial ledger entry {} must stay paper_only",
                entry.entry_id
            ));
        }
        reject_unsafe_owner_feedback_string(&entry.entry_id)?;
        reject_unsafe_owner_feedback_string(&entry.run_id)?;
    }
    Ok(())
}

pub fn load_paper_governance_trial_ledger_from_local_json(
    path: &Path,
) -> Result<PaperGovernanceTrialLedger, String> {
    validate_local_json_path(path, "paper governance trial ledger path")?;
    let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
    let mut ledger: PaperGovernanceTrialLedger =
        serde_json::from_str(&text).map_err(|err| err.to_string())?;
    validate_paper_governance_trial_ledger(&ledger)?;
    normalize_paper_governance_trial_ledger(&mut ledger);
    validate_paper_governance_trial_ledger(&ledger)?;
    Ok(ledger)
}

pub fn save_paper_governance_trial_ledger_to_local_json(
    path: &Path,
    ledger: &PaperGovernanceTrialLedger,
) -> Result<(), String> {
    validate_local_json_path(path, "paper governance trial ledger path")?;
    let mut normalized = ledger.clone();
    normalize_paper_governance_trial_ledger(&mut normalized);
    validate_paper_governance_trial_ledger(&normalized)?;
    write_safe_json(path, &normalized)
}

pub fn append_paper_governance_trial_ledger_entry(
    ledger: &mut PaperGovernanceTrialLedger,
    entry: PaperGovernanceTrialLedgerEntry,
) -> Result<(), String> {
    validate_paper_governance_trial_ledger(ledger)?;
    ledger.entries.push(entry);
    normalize_paper_governance_trial_ledger(ledger);
    validate_paper_governance_trial_ledger(ledger)
}

pub fn latest_paper_governance_trial_entry(
    ledger: &PaperGovernanceTrialLedger,
) -> Option<&PaperGovernanceTrialLedgerEntry> {
    ledger.entries.last()
}

fn paper_trial_voice_weight_maps(
    paper_trial_state_store: &PaperGovernanceTrialStateStore,
) -> (BTreeMap<String, f64>, BTreeMap<String, f64>) {
    let actual = paper_trial_state_store
        .member_states
        .iter()
        .map(|state| (state.member_id.clone(), state.actual_voice_snapshot))
        .collect::<BTreeMap<_, _>>();
    let paper = paper_trial_state_store
        .member_states
        .iter()
        .map(|state| (state.member_id.clone(), state.paper_trial_voice_weight))
        .collect::<BTreeMap<_, _>>();
    (actual, paper)
}

fn counterfactual_bucket_for_actual_action(
    action: ChairmanFinalAction,
) -> CounterfactualCommitteeReplayAction {
    match action {
        ChairmanFinalAction::PaperBuy => CounterfactualCommitteeReplayAction::PaperTrialWouldBuy,
        ChairmanFinalAction::PaperHold | ChairmanFinalAction::PaperSell => {
            CounterfactualCommitteeReplayAction::PaperTrialWouldHold
        }
        ChairmanFinalAction::PaperNoTrade => {
            CounterfactualCommitteeReplayAction::PaperTrialWouldNoTrade
        }
        ChairmanFinalAction::NeedMoreEvidence => {
            CounterfactualCommitteeReplayAction::PaperTrialWouldNeedMoreEvidence
        }
        ChairmanFinalAction::RiskVetoed => {
            CounterfactualCommitteeReplayAction::PaperTrialWouldRiskVeto
        }
    }
}

fn counterfactual_action_is_defensive(action: CounterfactualCommitteeReplayAction) -> bool {
    matches!(
        action,
        CounterfactualCommitteeReplayAction::PaperTrialWouldNoTrade
            | CounterfactualCommitteeReplayAction::PaperTrialWouldNeedMoreEvidence
            | CounterfactualCommitteeReplayAction::PaperTrialWouldRiskVeto
    )
}

fn actual_action_is_aggressive(action: ChairmanFinalAction) -> bool {
    matches!(
        action,
        ChairmanFinalAction::PaperBuy | ChairmanFinalAction::PaperSell
    )
}

fn paper_trial_voice_concentration_index(store: &PaperGovernanceTrialStateStore) -> f64 {
    let total = store
        .member_states
        .iter()
        .map(|state| state.paper_trial_voice_weight.max(0.0))
        .sum::<f64>();
    if total <= f64::EPSILON {
        return 0.0;
    }
    store
        .member_states
        .iter()
        .map(|state| state.paper_trial_voice_weight.max(0.0) / total)
        .fold(0.0, f64::max)
}

fn role_paper_voice_share(
    store: &PaperGovernanceTrialStateStore,
    role: PaperGovernanceTrialMemberRole,
) -> f64 {
    let total = store
        .member_states
        .iter()
        .map(|state| state.paper_trial_voice_weight.max(0.0))
        .sum::<f64>();
    if total <= f64::EPSILON {
        return 0.0;
    }
    store
        .member_states
        .iter()
        .filter(|state| state.role == role)
        .map(|state| state.paper_trial_voice_weight.max(0.0))
        .sum::<f64>()
        / total
}

fn average_role_voice_drop(
    store: &PaperGovernanceTrialStateStore,
    role: PaperGovernanceTrialMemberRole,
) -> f64 {
    let relevant = store
        .member_states
        .iter()
        .filter(|state| state.role == role)
        .map(|state| (state.actual_voice_snapshot - state.paper_trial_voice_weight).max(0.0))
        .collect::<Vec<_>>();
    if relevant.is_empty() {
        0.0
    } else {
        relevant.iter().sum::<f64>() / relevant.len() as f64
    }
}

fn default_empty_counterfactual_committee_replay_result(
    replay_id: String,
) -> CounterfactualCommitteeReplayResult {
    CounterfactualCommitteeReplayResult {
        replay_id,
        record_count: 0,
        changed_count: 0,
        risk_alignment_improved_count: 0,
        risk_alignment_worsened_count: 0,
        no_trade_bias_count: 0,
        evidence_caution_count: 0,
        replay_records: Vec::new(),
        replay_status: CounterfactualCommitteeReplayStatus::NoComparableEvents,
        no_actual_decision_mutation: true,
        no_risk_governor_mutation: true,
        paper_only: true,
    }
}

pub fn run_counterfactual_committee_replay(
    batch_result: &BatchCommitteeCycleResult,
    paper_trial_state_store: &PaperGovernanceTrialStateStore,
    policy: &CounterfactualCommitteeReplayPolicy,
) -> Result<CounterfactualCommitteeReplayResult, String> {
    validate_counterfactual_committee_replay_policy(policy)?;
    validate_paper_governance_trial_state_store(paper_trial_state_store)?;
    let (actual_voice_weights, paper_voice_weights) =
        paper_trial_voice_weight_maps(paper_trial_state_store);
    let mut replay_records = Vec::new();
    let mut replay_status = CounterfactualCommitteeReplayStatus::Compared;
    for session in &batch_result.committee_sessions {
        if session.member_opinions.is_empty() {
            continue;
        }
        let actual_decision = batch_result
            .chairman_decisions
            .iter()
            .find(|decision| decision.session_id == session.session_id);
        let actual_chairman_action = actual_decision.map(|decision| decision.final_action);
        let actual_risk_governor_status =
            actual_decision.map(|decision| decision.risk_governor_status);
        let mut weighted_buy = 0.0;
        let mut weighted_hold = 0.0;
        let mut weighted_no_trade = 0.0;
        let mut weighted_need_more_evidence = 0.0;
        let mut max_voice_shift = ("".to_string(), 0.0, 0.0, 0.0);
        for opinion in &session.member_opinions {
            let actual_voice = *actual_voice_weights.get(&opinion.member_id).unwrap_or(&1.0);
            let paper_voice = *paper_voice_weights
                .get(&opinion.member_id)
                .unwrap_or(&actual_voice);
            let effective_voice = if policy.use_paper_trial_voice_weights {
                paper_voice
            } else {
                actual_voice
            };
            let weight = (effective_voice.max(0.0) + 0.0001) * opinion.confidence.max(0.0);
            match opinion.stance {
                MemberStance::BuyProposal => weighted_buy += weight,
                MemberStance::SellProposal | MemberStance::Hold => weighted_hold += weight,
                MemberStance::NoTrade => weighted_no_trade += weight,
                MemberStance::NeedMoreEvidence => weighted_need_more_evidence += weight,
            }
            let shift = (paper_voice - actual_voice).abs();
            if shift > max_voice_shift.3 {
                max_voice_shift = (opinion.member_id.clone(), actual_voice, paper_voice, shift);
            }
        }
        let total_weight =
            weighted_buy + weighted_hold + weighted_no_trade + weighted_need_more_evidence;
        let counterfactual_action = if policy.use_actual_risk_governor_result
            && actual_risk_governor_status == Some(RiskGovernorStatus::Vetoed)
        {
            CounterfactualCommitteeReplayAction::PaperTrialWouldRiskVeto
        } else if total_weight <= f64::EPSILON {
            replay_status = CounterfactualCommitteeReplayStatus::ComparedWithWarnings;
            CounterfactualCommitteeReplayAction::Unknown
        } else if weighted_buy > weighted_no_trade.max(weighted_need_more_evidence)
            && weighted_buy > weighted_hold
            && weighted_buy / total_weight >= 0.45
        {
            CounterfactualCommitteeReplayAction::PaperTrialWouldBuy
        } else if weighted_no_trade >= weighted_need_more_evidence.max(weighted_hold)
            && weighted_no_trade / total_weight >= 0.30
        {
            CounterfactualCommitteeReplayAction::PaperTrialWouldNoTrade
        } else if weighted_need_more_evidence >= weighted_hold.max(weighted_buy)
            && weighted_need_more_evidence / total_weight >= 0.25
        {
            CounterfactualCommitteeReplayAction::PaperTrialWouldNeedMoreEvidence
        } else if weighted_hold > 0.0 {
            CounterfactualCommitteeReplayAction::PaperTrialWouldHold
        } else {
            replay_status = CounterfactualCommitteeReplayStatus::ComparedWithWarnings;
            CounterfactualCommitteeReplayAction::Unknown
        };
        let changed = actual_chairman_action
            .map(counterfactual_bucket_for_actual_action)
            .is_some_and(|actual| actual != counterfactual_action);
        let counterfactual_risk_alignment =
            match (actual_risk_governor_status, actual_chairman_action) {
                (Some(RiskGovernorStatus::Vetoed), _)
                    if counterfactual_action
                        == CounterfactualCommitteeReplayAction::PaperTrialWouldBuy =>
                {
                    CounterfactualRiskAlignment::Worse
                }
                (Some(RiskGovernorStatus::NeedsReview), _)
                    if counterfactual_action
                        == CounterfactualCommitteeReplayAction::PaperTrialWouldBuy =>
                {
                    CounterfactualRiskAlignment::Worse
                }
                (_, Some(actual_action))
                    if changed
                        && actual_action_is_aggressive(actual_action)
                        && counterfactual_action_is_defensive(counterfactual_action) =>
                {
                    CounterfactualRiskAlignment::BetterAligned
                }
                (_, Some(actual_action))
                    if changed
                        && !actual_action_is_aggressive(actual_action)
                        && counterfactual_action
                            == CounterfactualCommitteeReplayAction::PaperTrialWouldBuy =>
                {
                    CounterfactualRiskAlignment::Worse
                }
                (Some(_), Some(actual_action))
                    if counterfactual_bucket_for_actual_action(actual_action)
                        == counterfactual_action =>
                {
                    CounterfactualRiskAlignment::Same
                }
                _ => CounterfactualRiskAlignment::Unknown,
            };
        let voice_weight_shift_summary = if max_voice_shift.3 <= 0.01 {
            "paper trial voice weights stay close to actual".to_string()
        } else {
            format!(
                "{} voice shifted from {:.3} to {:.3}",
                max_voice_shift.0, max_voice_shift.1, max_voice_shift.2
            )
        };
        replay_records.push(CounterfactualCommitteeReplayRecord {
            record_id: format!("{}-counterfactual", session.session_id),
            event_id: Some(session.event.event_id.clone()),
            symbol: Some(session.event.symbol.clone()),
            market_scope: Some(session.event.market_scope),
            actual_chairman_action,
            counterfactual_action,
            actual_risk_governor_status,
            counterfactual_risk_alignment,
            voice_weight_shift_summary,
            changed,
            paper_only: true,
        });
    }
    if replay_records.is_empty() {
        return Ok(default_empty_counterfactual_committee_replay_result(
            format!("{}-counterfactual-replay", batch_result.batch_id),
        ));
    }
    let changed_count = replay_records
        .iter()
        .filter(|record| record.changed)
        .count();
    let risk_alignment_improved_count = replay_records
        .iter()
        .filter(|record| {
            record.counterfactual_risk_alignment == CounterfactualRiskAlignment::BetterAligned
        })
        .count();
    let risk_alignment_worsened_count = replay_records
        .iter()
        .filter(|record| record.counterfactual_risk_alignment == CounterfactualRiskAlignment::Worse)
        .count();
    let no_trade_bias_count = replay_records
        .iter()
        .filter(|record| {
            record.counterfactual_action
                == CounterfactualCommitteeReplayAction::PaperTrialWouldNoTrade
                && record.actual_chairman_action != Some(ChairmanFinalAction::PaperNoTrade)
                && record.actual_chairman_action != Some(ChairmanFinalAction::RiskVetoed)
        })
        .count();
    let evidence_caution_count = replay_records
        .iter()
        .filter(|record| {
            record.counterfactual_action
                == CounterfactualCommitteeReplayAction::PaperTrialWouldNeedMoreEvidence
                && record.actual_chairman_action != Some(ChairmanFinalAction::NeedMoreEvidence)
        })
        .count();
    Ok(CounterfactualCommitteeReplayResult {
        replay_id: format!("{}-counterfactual-replay", batch_result.batch_id),
        record_count: replay_records.len(),
        changed_count,
        risk_alignment_improved_count,
        risk_alignment_worsened_count,
        no_trade_bias_count,
        evidence_caution_count,
        replay_status,
        replay_records,
        no_actual_decision_mutation: true,
        no_risk_governor_mutation: true,
        paper_only: true,
    })
}

pub fn compute_paper_governance_effectiveness_metrics(
    ledger: &PaperGovernanceTrialLedger,
    counterfactual_replay_result: &CounterfactualCommitteeReplayResult,
    paper_trial_state_store: &PaperGovernanceTrialStateStore,
) -> PaperGovernanceEffectivenessMetrics {
    let record_count = counterfactual_replay_result.record_count.max(1) as f64;
    let risk_alignment_improvement_rate =
        counterfactual_replay_result.risk_alignment_improved_count as f64 / record_count;
    let risk_alignment_worsening_rate =
        counterfactual_replay_result.risk_alignment_worsened_count as f64 / record_count;
    let evidence_caution_rate =
        counterfactual_replay_result.evidence_caution_count as f64 / record_count;
    let no_trade_bias_rate = counterfactual_replay_result.no_trade_bias_count as f64 / record_count;
    let overconfident_call_reduction_count = counterfactual_replay_result
        .replay_records
        .iter()
        .filter(|record| {
            record.actual_chairman_action == Some(ChairmanFinalAction::PaperBuy)
                && counterfactual_action_is_defensive(record.counterfactual_action)
        })
        .count();
    let helpful_dissent_rewarded_count = counterfactual_replay_result
        .replay_records
        .iter()
        .filter(|record| {
            record.counterfactual_risk_alignment == CounterfactualRiskAlignment::BetterAligned
                && counterfactual_action_is_defensive(record.counterfactual_action)
        })
        .count();
    let voice_concentration_index = paper_trial_voice_concentration_index(paper_trial_state_store);
    let trend_entry_suppression_score = average_role_voice_drop(
        paper_trial_state_store,
        PaperGovernanceTrialMemberRole::TrendEntry,
    );
    let evidence_regime_underweight_score = average_role_voice_drop(
        paper_trial_state_store,
        PaperGovernanceTrialMemberRole::EvidenceRegime,
    );
    let risk_guard_dominance_score = role_paper_voice_share(
        paper_trial_state_store,
        PaperGovernanceTrialMemberRole::RiskGuard,
    );
    let effectiveness_status =
        if ledger.entry_count == 0 || counterfactual_replay_result.record_count == 0 {
            PaperGovernanceEffectivenessStatus::InsufficientHistory
        } else if risk_alignment_worsening_rate > 0.20
            || voice_concentration_index > 0.65
            || risk_guard_dominance_score > 0.65
        {
            PaperGovernanceEffectivenessStatus::Risky
        } else if risk_alignment_improvement_rate > 0.0
            || overconfident_call_reduction_count > 0
            || helpful_dissent_rewarded_count > 0
        {
            if no_trade_bias_rate > 0.50
                || voice_concentration_index > 0.45
                || trend_entry_suppression_score > 0.08
                || evidence_regime_underweight_score > 0.08
            {
                PaperGovernanceEffectivenessStatus::EffectiveWithWarnings
            } else {
                PaperGovernanceEffectivenessStatus::Effective
            }
        } else if evidence_caution_rate > 0.0 || no_trade_bias_rate > 0.0 {
            PaperGovernanceEffectivenessStatus::EffectiveWithWarnings
        } else {
            PaperGovernanceEffectivenessStatus::Neutral
        };
    PaperGovernanceEffectivenessMetrics {
        metrics_id: format!("{}-paper-governance-effectiveness", ledger.ledger_id),
        trial_entry_count: ledger.entry_count,
        counterfactual_changed_count: counterfactual_replay_result.changed_count,
        risk_alignment_improvement_rate,
        risk_alignment_worsening_rate,
        evidence_caution_rate,
        no_trade_bias_rate,
        overconfident_call_reduction_count,
        helpful_dissent_rewarded_count,
        voice_concentration_index,
        trend_entry_suppression_score,
        evidence_regime_underweight_score,
        risk_guard_dominance_score,
        effectiveness_status,
        paper_only: true,
    }
}

pub fn evaluate_paper_governance_risk_first_effectiveness(
    metrics: &PaperGovernanceEffectivenessMetrics,
    replay_result: &CounterfactualCommitteeReplayResult,
) -> PaperGovernanceRiskFirstEffectivenessCheck {
    let risk_alignment_improved = metrics.risk_alignment_improvement_rate
        > metrics.risk_alignment_worsening_rate
        && replay_result.risk_alignment_improved_count > 0;
    let risk_alignment_worsened = replay_result.risk_alignment_worsened_count > 0;
    let reckless_buy_reduced = metrics.overconfident_call_reduction_count > 0;
    let risk_guard_dominance_detected = metrics.risk_guard_dominance_score > 0.45;
    let excessive_no_trade_bias_detected = metrics.no_trade_bias_rate > 0.60;
    let helpful_risk_dissent_preserved = metrics.helpful_dissent_rewarded_count > 0
        || (risk_alignment_improved && !risk_guard_dominance_detected);
    let mut warnings = Vec::new();
    if risk_guard_dominance_detected {
        warnings.push("RiskGuard paper voice is approaching dangerous dominance".to_string());
    }
    if excessive_no_trade_bias_detected {
        warnings.push("paper governance replay is showing excessive no-trade bias".to_string());
    }
    if !helpful_risk_dissent_preserved {
        warnings.push("helpful risk dissent is not clearly preserved yet".to_string());
    }
    let risk_first_status = if replay_result.record_count == 0 {
        PaperGovernanceRiskFirstStatus::InsufficientData
    } else if risk_alignment_worsened {
        PaperGovernanceRiskFirstStatus::Violated
    } else if warnings.is_empty() && (risk_alignment_improved || reckless_buy_reduced) {
        PaperGovernanceRiskFirstStatus::Preserved
    } else {
        PaperGovernanceRiskFirstStatus::PreservedWithWarnings
    };
    PaperGovernanceRiskFirstEffectivenessCheck {
        check_id: format!("{}-risk-first", metrics.metrics_id),
        risk_alignment_improved,
        risk_alignment_worsened,
        reckless_buy_reduced,
        helpful_risk_dissent_preserved,
        risk_guard_dominance_detected,
        excessive_no_trade_bias_detected,
        risk_first_status,
        warnings,
        paper_only: true,
    }
}

fn numeric_trend_direction(
    first: f64,
    last: f64,
    lower_is_better: bool,
) -> PaperGovernanceTrialLedgerTrendDirection {
    if (last - first).abs() <= 0.02 {
        PaperGovernanceTrialLedgerTrendDirection::Stable
    } else if lower_is_better {
        if last < first {
            PaperGovernanceTrialLedgerTrendDirection::Improving
        } else {
            PaperGovernanceTrialLedgerTrendDirection::Worsening
        }
    } else if last > first {
        PaperGovernanceTrialLedgerTrendDirection::Improving
    } else {
        PaperGovernanceTrialLedgerTrendDirection::Worsening
    }
}

pub fn compute_paper_governance_trial_ledger_trend(
    ledger: &PaperGovernanceTrialLedger,
) -> PaperGovernanceTrialLedgerTrend {
    if ledger.entry_count < 2 {
        return PaperGovernanceTrialLedgerTrend {
            trend_id: format!("{}-trend", ledger.ledger_id),
            entry_count: ledger.entry_count,
            changed_count_series: ledger
                .entries
                .iter()
                .map(|entry| entry.counterfactual_changed_count)
                .collect(),
            readiness_status_series: ledger
                .entries
                .iter()
                .map(|entry| entry.readiness_status)
                .collect(),
            risk_alignment_series: ledger
                .entries
                .iter()
                .map(|entry| {
                    entry.risk_alignment_improvement_rate - entry.risk_alignment_worsening_rate
                })
                .collect(),
            voice_concentration_series: ledger
                .entries
                .iter()
                .map(|entry| entry.voice_concentration_index)
                .collect(),
            effectiveness_trend: PaperGovernanceTrialLedgerTrendDirection::InsufficientHistory,
            risk_alignment_trend: PaperGovernanceTrialLedgerTrendDirection::InsufficientHistory,
            voice_concentration_trend:
                PaperGovernanceTrialLedgerTrendDirection::InsufficientHistory,
            trend_status: PaperGovernanceTrialLedgerTrendStatus::InsufficientHistory,
            paper_only: true,
        };
    }
    let changed_count_series = ledger
        .entries
        .iter()
        .map(|entry| entry.counterfactual_changed_count)
        .collect::<Vec<_>>();
    let readiness_status_series = ledger
        .entries
        .iter()
        .map(|entry| entry.readiness_status)
        .collect::<Vec<_>>();
    let risk_alignment_series = ledger
        .entries
        .iter()
        .map(|entry| entry.risk_alignment_improvement_rate - entry.risk_alignment_worsening_rate)
        .collect::<Vec<_>>();
    let voice_concentration_series = ledger
        .entries
        .iter()
        .map(|entry| entry.voice_concentration_index)
        .collect::<Vec<_>>();
    let first_effectiveness_score = ledger
        .entries
        .first()
        .map(|entry| {
            entry.risk_alignment_improvement_rate
                - entry.risk_alignment_worsening_rate
                - entry.voice_concentration_index * 0.5
        })
        .unwrap_or(0.0);
    let last_effectiveness_score = ledger
        .entries
        .last()
        .map(|entry| {
            entry.risk_alignment_improvement_rate
                - entry.risk_alignment_worsening_rate
                - entry.voice_concentration_index * 0.5
        })
        .unwrap_or(0.0);
    let effectiveness_trend =
        numeric_trend_direction(first_effectiveness_score, last_effectiveness_score, false);
    let risk_alignment_trend = numeric_trend_direction(
        *risk_alignment_series.first().unwrap_or(&0.0),
        *risk_alignment_series.last().unwrap_or(&0.0),
        false,
    );
    let voice_concentration_trend = numeric_trend_direction(
        *voice_concentration_series.first().unwrap_or(&0.0),
        *voice_concentration_series.last().unwrap_or(&0.0),
        true,
    );
    let trend_status = if matches!(
        effectiveness_trend,
        PaperGovernanceTrialLedgerTrendDirection::Worsening
    ) || matches!(
        voice_concentration_trend,
        PaperGovernanceTrialLedgerTrendDirection::Worsening
    ) {
        PaperGovernanceTrialLedgerTrendStatus::UsefulWithWarnings
    } else {
        PaperGovernanceTrialLedgerTrendStatus::Useful
    };
    PaperGovernanceTrialLedgerTrend {
        trend_id: format!("{}-trend", ledger.ledger_id),
        entry_count: ledger.entry_count,
        changed_count_series,
        readiness_status_series,
        risk_alignment_series,
        voice_concentration_series,
        effectiveness_trend,
        risk_alignment_trend,
        voice_concentration_trend,
        trend_status,
        paper_only: true,
    }
}

pub fn evaluate_paper_governance_trial_safety_v2(
    trial_run_result: &PaperGovernanceTrialRunResult,
    replay_result: &CounterfactualCommitteeReplayResult,
    batch_before: &BatchCommitteeCycleResult,
    batch_after: Option<&BatchCommitteeCycleResult>,
) -> PaperGovernanceTrialSafetyGuardV2 {
    let after_batch = batch_after.unwrap_or(batch_before);
    let reference_store = trial_run_result
        .trial_store_after
        .as_ref()
        .or(trial_run_result.trial_store_before.as_ref());
    let after_store = after_batch
        .paper_governance_trial_state_store
        .as_ref()
        .or_else(|| {
            after_batch
                .paper_governance_trial_run_result
                .as_ref()
                .and_then(|run| {
                    run.trial_store_after
                        .as_ref()
                        .or(run.trial_store_before.as_ref())
                })
        })
        .or(reference_store);
    let actual_score_snapshot = |store: &PaperGovernanceTrialStateStore| {
        store
            .member_states
            .iter()
            .map(|state| (state.member_id.clone(), state.actual_score_snapshot))
            .collect::<BTreeMap<_, _>>()
    };
    let actual_voice_snapshot = |store: &PaperGovernanceTrialStateStore| {
        store
            .member_states
            .iter()
            .map(|state| (state.member_id.clone(), state.actual_voice_snapshot))
            .collect::<BTreeMap<_, _>>()
    };
    let risk_snapshot = |decisions: &[ChairmanDecision]| {
        decisions
            .iter()
            .map(|decision| (decision.decision_id.clone(), decision.risk_governor_status))
            .collect::<BTreeMap<_, _>>()
    };
    let live_decision_markers = vec![
        trial_run_result.run_id.clone(),
        replay_result.replay_id.clone(),
        "paper-trial-live".to_string(),
        "counterfactual-live".to_string(),
    ];
    let trade_markers = [
        format!("{}-paper-trial-trade", trial_run_result.run_id),
        format!("{}-counterfactual-trade", replay_result.replay_id),
        "trade-signal".to_string(),
    ];
    let order_markers = [
        format!("{}-paper-trial-order", trial_run_result.run_id),
        format!("{}-counterfactual-order", replay_result.replay_id),
        "order".to_string(),
    ];
    let broker_order_account_markers = [
        "broker".to_string(),
        "order".to_string(),
        "account".to_string(),
    ];
    let actual_score_mutation_detected =
        reference_store
            .zip(after_store)
            .is_some_and(|(before_store, after_store)| {
                actual_score_snapshot(before_store) != actual_score_snapshot(after_store)
            });
    let actual_voice_mutation_detected =
        reference_store
            .zip(after_store)
            .is_some_and(|(before_store, after_store)| {
                actual_voice_snapshot(before_store) != actual_voice_snapshot(after_store)
            });
    let committee_decision_mutation_detected =
        batch_before.committee_sessions != after_batch.committee_sessions;
    let chairman_decision_mutation_detected =
        batch_before.chairman_decisions != after_batch.chairman_decisions;
    let risk_governor_mutation_detected = risk_snapshot(&batch_before.chairman_decisions)
        != risk_snapshot(&after_batch.chairman_decisions);
    let member_opinion_mutation_detected =
        batch_before.member_opinions != after_batch.member_opinions;
    let trade_signal_detected =
        value_contains_debug_marker(&after_batch.committee_sessions, &trade_markers)
            && !value_contains_debug_marker(&batch_before.committee_sessions, &trade_markers);
    let order_detected = value_contains_debug_marker(&after_batch.event_queue, &order_markers)
        && !value_contains_debug_marker(&batch_before.event_queue, &order_markers);
    let broker_order_account_detected =
        value_contains_debug_marker(after_batch, &broker_order_account_markers)
            && !value_contains_debug_marker(batch_before, &broker_order_account_markers);
    let paper_trial_used_as_live_decision_detected =
        (value_contains_debug_marker(&after_batch.chairman_decisions, &live_decision_markers)
            && !value_contains_debug_marker(
                &batch_before.chairman_decisions,
                &live_decision_markers,
            ))
            || (value_contains_debug_marker(
                &after_batch.committee_sessions,
                &live_decision_markers,
            ) && !value_contains_debug_marker(
                &batch_before.committee_sessions,
                &live_decision_markers,
            ));
    let mut violations = Vec::new();
    if actual_score_mutation_detected {
        violations.push("paper governance evaluation mutated actual score".to_string());
    }
    if actual_voice_mutation_detected {
        violations.push("paper governance evaluation mutated actual voice".to_string());
    }
    if committee_decision_mutation_detected {
        violations.push("paper governance evaluation mutated committee session".to_string());
    }
    if chairman_decision_mutation_detected {
        violations.push("paper governance evaluation mutated ChairmanDecision".to_string());
    }
    if risk_governor_mutation_detected {
        violations.push("paper governance evaluation mutated Risk Governor".to_string());
    }
    if member_opinion_mutation_detected {
        violations.push("paper governance evaluation mutated member opinions".to_string());
    }
    if paper_trial_used_as_live_decision_detected {
        violations.push("paper governance evaluation was referenced as live decision".to_string());
    }
    if trade_signal_detected {
        violations.push("paper governance evaluation created a trade signal".to_string());
    }
    if order_detected {
        violations.push("paper governance evaluation created an order".to_string());
    }
    if broker_order_account_detected {
        violations.push("paper governance evaluation touched broker/order/account".to_string());
    }
    PaperGovernanceTrialSafetyGuardV2 {
        actual_score_mutation_detected,
        actual_voice_mutation_detected,
        committee_decision_mutation_detected,
        chairman_decision_mutation_detected,
        risk_governor_mutation_detected,
        member_opinion_mutation_detected,
        paper_trial_used_as_live_decision_detected,
        trade_signal_detected,
        order_detected,
        broker_order_account_detected,
        guard_status: if violations.is_empty() {
            PaperGovernanceTrialSafetyGuardStatus::Preserved
        } else {
            PaperGovernanceTrialSafetyGuardStatus::Violated
        },
        violations,
        paper_only: true,
    }
}

pub fn evaluate_paper_governance_continuation_gate(
    ledger: &PaperGovernanceTrialLedger,
    replay_result: &CounterfactualCommitteeReplayResult,
    metrics: &PaperGovernanceEffectivenessMetrics,
    risk_check: &PaperGovernanceRiskFirstEffectivenessCheck,
    safety_guard: &PaperGovernanceTrialSafetyGuardV2,
) -> PaperGovernanceContinuationGate {
    let min_trial_entries_required = 2;
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    if safety_guard.guard_status == PaperGovernanceTrialSafetyGuardStatus::Violated {
        blockers.push("paper governance evaluation safety guard v2 was violated".to_string());
    }
    if ledger.entry_count < min_trial_entries_required {
        blockers.push("paper governance trial needs more ledger history".to_string());
    }
    if metrics.risk_alignment_worsening_rate > 0.0
        || risk_check.risk_first_status == PaperGovernanceRiskFirstStatus::Violated
        || metrics.effectiveness_status == PaperGovernanceEffectivenessStatus::Risky
    {
        blockers.push("paper governance replay shows risk regression".to_string());
    }
    if metrics.voice_concentration_index > 0.65 || risk_check.risk_guard_dominance_detected {
        blockers.push("paper governance voice concentration is too high".to_string());
    }
    if replay_result.replay_status == CounterfactualCommitteeReplayStatus::ComparedWithWarnings {
        warnings.push("counterfactual replay completed with warnings".to_string());
    }
    if metrics.no_trade_bias_rate > 0.50 {
        warnings.push("paper governance replay is leaning toward no-trade bias".to_string());
    }
    if matches!(
        risk_check.risk_first_status,
        PaperGovernanceRiskFirstStatus::PreservedWithWarnings
    ) {
        warnings.extend(risk_check.warnings.clone());
    }
    let readiness_status = if safety_guard.guard_status
        == PaperGovernanceTrialSafetyGuardStatus::Violated
    {
        PaperGovernanceContinuationGateReadinessStatus::BlockedBySafety
    } else if ledger.entry_count < min_trial_entries_required {
        PaperGovernanceContinuationGateReadinessStatus::NeedsMoreTrialHistory
    } else if metrics.risk_alignment_worsening_rate > 0.0
        || risk_check.risk_first_status == PaperGovernanceRiskFirstStatus::Violated
        || metrics.effectiveness_status == PaperGovernanceEffectivenessStatus::Risky
    {
        PaperGovernanceContinuationGateReadinessStatus::BlockedByRiskRegression
    } else if metrics.voice_concentration_index > 0.65 || risk_check.risk_guard_dominance_detected {
        PaperGovernanceContinuationGateReadinessStatus::BlockedByVoiceConcentration
    } else if metrics.effectiveness_status == PaperGovernanceEffectivenessStatus::Neutral {
        PaperGovernanceContinuationGateReadinessStatus::NeedsPolicyTuning
    } else if warnings.is_empty()
        && metrics.effectiveness_status == PaperGovernanceEffectivenessStatus::Effective
        && risk_check.risk_first_status == PaperGovernanceRiskFirstStatus::Preserved
    {
        PaperGovernanceContinuationGateReadinessStatus::ContinuePaperTrial
    } else {
        PaperGovernanceContinuationGateReadinessStatus::ContinuePaperTrialWithWarnings
    };
    PaperGovernanceContinuationGate {
        gate_id: format!("{}-continuation-gate", ledger.ledger_id),
        trial_ledger_status: if ledger.entry_count >= min_trial_entries_required {
            "ready".to_string()
        } else {
            "needs_more_history".to_string()
        },
        counterfactual_replay_status: replay_result.replay_status,
        effectiveness_status: metrics.effectiveness_status,
        risk_first_status: risk_check.risk_first_status,
        safety_status: safety_guard.guard_status,
        min_trial_entries_required,
        actual_trial_entries: ledger.entry_count,
        continue_paper_governance_trial: matches!(
            readiness_status,
            PaperGovernanceContinuationGateReadinessStatus::ContinuePaperTrial
                | PaperGovernanceContinuationGateReadinessStatus::ContinuePaperTrialWithWarnings
        ),
        readiness_status,
        blockers,
        warnings,
        paper_only: true,
    }
}

pub fn build_owner_paper_governance_trial_evaluation_summary(
    evaluation_run_result: &PaperGovernanceTrialEvaluationRunResult,
) -> OwnerPaperGovernanceTrialEvaluationSummary {
    OwnerPaperGovernanceTrialEvaluationSummary {
        summary_id: format!(
            "{}-owner-paper-trial-evaluation-summary",
            evaluation_run_result.run_id
        ),
        trial_entry_count: evaluation_run_result.trial_ledger.entry_count,
        counterfactual_changed_count: evaluation_run_result
            .counterfactual_replay_result
            .as_ref()
            .map(|result| result.changed_count)
            .unwrap_or(0),
        effectiveness_status: evaluation_run_result.effectiveness_metrics.effectiveness_status,
        risk_first_status: evaluation_run_result.risk_first_check.risk_first_status,
        continuation_gate_status: evaluation_run_result.continuation_gate.readiness_status,
        trend_status: evaluation_run_result.trial_ledger_trend.trend_status,
        message: "Paper governance trial was evaluated only in comparison mode. Actual score and voice did not change. Committee decisions and Risk Governor were not changed. This is not live governance or trading."
            .to_string(),
        paper_trial_only: true,
        no_actual_score_mutation: true,
        no_actual_voice_mutation: true,
        no_committee_decision_change: true,
        no_risk_override: true,
        not_trade_signal: true,
        paper_only: true,
    }
}

fn paper_trial_ledger_entry_from_run(
    trial_run_result: &PaperGovernanceTrialRunResult,
    voice_concentration_index: f64,
) -> PaperGovernanceTrialLedgerEntry {
    PaperGovernanceTrialLedgerEntry {
        entry_id: format!("{}-ledger-entry", trial_run_result.run_id),
        run_id: trial_run_result.run_id.clone(),
        trial_state_id: trial_run_result
            .trial_store_after
            .as_ref()
            .or(trial_run_result.trial_store_before.as_ref())
            .map(|store| store.store_id.clone()),
        candidate_count: trial_run_result
            .candidate_selection
            .eligible_candidate_count,
        applied_candidate_count: trial_run_result.trial_apply_result.applied_candidate_count,
        updated_member_count: trial_run_result.trial_apply_result.updated_member_count,
        actual_shadow_paper_comparison_status: trial_run_result
            .actual_shadow_paper_comparison
            .summary_status,
        committee_voice_comparison_status: trial_run_result
            .committee_voice_comparison
            .as_ref()
            .map(|comparison| comparison.comparison_status)
            .unwrap_or(PaperGovernanceTrialCommitteeComparisonStatus::ComparedWithWarnings),
        readiness_status: trial_run_result.readiness_result.readiness_status,
        safety_status: trial_run_result.safety_guard.guard_status,
        counterfactual_changed_count: 0,
        risk_alignment_improvement_rate: 0.0,
        risk_alignment_worsening_rate: 0.0,
        voice_concentration_index,
        paper_only: true,
    }
}

pub fn run_paper_governance_trial_evaluation(
    paper_trial_run_result: &PaperGovernanceTrialRunResult,
    batch_result: &BatchCommitteeCycleResult,
    config: &PaperGovernanceTrialEvaluationRunConfig,
) -> Result<PaperGovernanceTrialEvaluationRunResult, String> {
    if !config.paper_only {
        return Err("paper governance trial evaluation run must stay paper_only".to_string());
    }
    for (path, label) in [
        (
            config.trial_ledger_input_path.as_ref(),
            "paper governance trial ledger input path",
        ),
        (
            config.trial_ledger_output_path.as_ref(),
            "paper governance trial ledger output path",
        ),
    ] {
        if let Some(path) = path {
            validate_local_json_path(Path::new(path), label)?;
        }
    }
    if !config.dry_run && config.trial_ledger_output_path.is_none() {
        return Err(
            "paper governance trial evaluation requires trial_ledger_output_path when dry_run=false"
                .to_string(),
        );
    }
    let paper_trial_state_store = paper_trial_run_result
        .trial_store_after
        .as_ref()
        .or(paper_trial_run_result.trial_store_before.as_ref())
        .ok_or_else(|| {
            "paper governance trial evaluation requires paper trial state store".to_string()
        })?;
    let mut trial_ledger = if let Some(path) = config.trial_ledger_input_path.as_ref() {
        if Path::new(path).exists() {
            load_paper_governance_trial_ledger_from_local_json(Path::new(path))?
        } else {
            default_paper_governance_trial_ledger()
        }
    } else {
        default_paper_governance_trial_ledger()
    };
    let voice_concentration_index = paper_trial_voice_concentration_index(paper_trial_state_store);
    if config.append_ledger_entry {
        append_paper_governance_trial_ledger_entry(
            &mut trial_ledger,
            paper_trial_ledger_entry_from_run(paper_trial_run_result, voice_concentration_index),
        )?;
    }
    let replay_policy = default_counterfactual_committee_replay_policy();
    let counterfactual_replay_result = if config.run_counterfactual_replay {
        Some(run_counterfactual_committee_replay(
            batch_result,
            paper_trial_state_store,
            &replay_policy,
        )?)
    } else {
        None
    };
    let replay_for_metrics = counterfactual_replay_result.clone().unwrap_or_else(|| {
        default_empty_counterfactual_committee_replay_result(format!(
            "{}-counterfactual-replay",
            config.run_id
        ))
    });
    let effectiveness_metrics = compute_paper_governance_effectiveness_metrics(
        &trial_ledger,
        &replay_for_metrics,
        paper_trial_state_store,
    );
    if config.append_ledger_entry {
        if let Some(entry) = trial_ledger.entries.last_mut() {
            entry.counterfactual_changed_count = replay_for_metrics.changed_count;
            entry.risk_alignment_improvement_rate =
                effectiveness_metrics.risk_alignment_improvement_rate;
            entry.risk_alignment_worsening_rate =
                effectiveness_metrics.risk_alignment_worsening_rate;
            entry.voice_concentration_index = effectiveness_metrics.voice_concentration_index;
        }
        normalize_paper_governance_trial_ledger(&mut trial_ledger);
    }
    let risk_first_check = evaluate_paper_governance_risk_first_effectiveness(
        &effectiveness_metrics,
        &replay_for_metrics,
    );
    let trial_ledger_trend = compute_paper_governance_trial_ledger_trend(&trial_ledger);
    let safety_guard_v2 = evaluate_paper_governance_trial_safety_v2(
        paper_trial_run_result,
        &replay_for_metrics,
        batch_result,
        Some(batch_result),
    );
    let continuation_gate = evaluate_paper_governance_continuation_gate(
        &trial_ledger,
        &replay_for_metrics,
        &effectiveness_metrics,
        &risk_first_check,
        &safety_guard_v2,
    );
    let mut evaluation_run_result = PaperGovernanceTrialEvaluationRunResult {
        run_id: config.run_id.clone(),
        trial_ledger,
        counterfactual_replay_result,
        effectiveness_metrics,
        risk_first_check,
        trial_ledger_trend,
        continuation_gate,
        safety_guard_v2,
        owner_summary: None,
        run_status: PaperGovernanceTrialRunStatus::PassedWithWarnings,
        paper_only: true,
    };
    if config.emit_owner_summary {
        evaluation_run_result.owner_summary = Some(
            build_owner_paper_governance_trial_evaluation_summary(&evaluation_run_result),
        );
    }
    evaluation_run_result.run_status = if evaluation_run_result.safety_guard_v2.guard_status
        == PaperGovernanceTrialSafetyGuardStatus::Violated
        || matches!(
            evaluation_run_result.continuation_gate.readiness_status,
            PaperGovernanceContinuationGateReadinessStatus::BlockedByRiskRegression
                | PaperGovernanceContinuationGateReadinessStatus::BlockedByVoiceConcentration
                | PaperGovernanceContinuationGateReadinessStatus::BlockedBySafety
        ) {
        PaperGovernanceTrialRunStatus::Failed
    } else if matches!(
        evaluation_run_result.continuation_gate.readiness_status,
        PaperGovernanceContinuationGateReadinessStatus::ContinuePaperTrial
    ) && evaluation_run_result
        .effectiveness_metrics
        .effectiveness_status
        == PaperGovernanceEffectivenessStatus::Effective
        && evaluation_run_result.risk_first_check.risk_first_status
            == PaperGovernanceRiskFirstStatus::Preserved
    {
        PaperGovernanceTrialRunStatus::Passed
    } else {
        PaperGovernanceTrialRunStatus::PassedWithWarnings
    };
    if !config.dry_run {
        if let Some(path) = config.trial_ledger_output_path.as_ref() {
            save_paper_governance_trial_ledger_to_local_json(
                Path::new(path),
                &evaluation_run_result.trial_ledger,
            )?;
        }
    }
    Ok(evaluation_run_result)
}

pub fn paper_governance_trial_evaluation_requested_from_flags(
    enabled: bool,
    dry_run: bool,
    trial_ledger_input_path: Option<&String>,
    trial_ledger_output_path: Option<&String>,
    append_ledger_entry: bool,
    run_counterfactual_replay: bool,
    emit_owner_summary: bool,
) -> bool {
    enabled
        || !dry_run
        || trial_ledger_input_path.is_some()
        || trial_ledger_output_path.is_some()
        || (enabled && (append_ledger_entry || run_counterfactual_replay || emit_owner_summary))
}

fn maybe_run_paper_governance_trial_evaluation_for_batch_result(
    run_id: String,
    enabled: bool,
    dry_run: bool,
    trial_ledger_input_path: Option<&String>,
    trial_ledger_output_path: Option<&String>,
    append_ledger_entry: bool,
    run_counterfactual_replay: bool,
    emit_owner_summary: bool,
    batch_result: &mut BatchCommitteeCycleResult,
) -> Result<Option<PaperGovernanceTrialEvaluationRunResult>, String> {
    if !paper_governance_trial_evaluation_requested_from_flags(
        enabled,
        dry_run,
        trial_ledger_input_path,
        trial_ledger_output_path,
        append_ledger_entry,
        run_counterfactual_replay,
        emit_owner_summary,
    ) {
        return Ok(None);
    }
    let trial_run_result = batch_result
        .paper_governance_trial_run_result
        .clone()
        .ok_or_else(|| {
            "paper governance trial evaluation requires paper governance trial run result"
                .to_string()
        })?;
    let replay_policy = default_counterfactual_committee_replay_policy();
    let result = run_paper_governance_trial_evaluation(
        &trial_run_result,
        batch_result,
        &PaperGovernanceTrialEvaluationRunConfig {
            run_id,
            enabled,
            trial_ledger_input_path: trial_ledger_input_path.cloned(),
            trial_ledger_output_path: trial_ledger_output_path.cloned(),
            dry_run,
            append_ledger_entry,
            run_counterfactual_replay,
            emit_owner_summary,
            paper_only: true,
        },
    )?;
    batch_result.paper_governance_trial_ledger = Some(result.trial_ledger.clone());
    batch_result.counterfactual_committee_replay_policy = Some(replay_policy);
    batch_result.counterfactual_committee_replay_result =
        result.counterfactual_replay_result.clone();
    batch_result.paper_governance_effectiveness_metrics =
        Some(result.effectiveness_metrics.clone());
    batch_result.paper_governance_risk_first_effectiveness_check =
        Some(result.risk_first_check.clone());
    batch_result.paper_governance_continuation_gate = Some(result.continuation_gate.clone());
    batch_result.paper_governance_trial_ledger_trend = Some(result.trial_ledger_trend.clone());
    batch_result.paper_governance_trial_safety_guard_v2 = Some(result.safety_guard_v2.clone());
    batch_result.owner_paper_governance_trial_evaluation_summary = result.owner_summary.clone();
    batch_result.paper_governance_trial_evaluation_run_result = Some(result.clone());
    Ok(Some(result))
}

pub fn evaluate_paper_governance_risk_regression(
    per_cycle_results: &[PerCyclePaperGovernanceTrialResult],
    aggregate_metrics: &PaperGovernanceEffectivenessMetrics,
) -> PaperGovernanceRiskRegressionWatchdog {
    if per_cycle_results.len() < 2 {
        return PaperGovernanceRiskRegressionWatchdog {
            watchdog_id: "paper-governance-risk-regression-watchdog".to_string(),
            record_count: 1,
            high_severity_count: 0,
            regression_detected: false,
            dominant_signals: vec![PaperGovernanceRiskRegressionSignal::InsufficientHistory],
            watchdog_status: PaperGovernanceRiskRegressionWatchdogStatus::InsufficientHistory,
            records: vec![PaperGovernanceRiskRegressionRecord {
                record_id: "paper-governance-risk-regression-history".to_string(),
                cycle_index: None,
                signal: PaperGovernanceRiskRegressionSignal::InsufficientHistory,
                severity: PaperGovernanceAlertSeverity::Low,
                risk_alignment_worsening_rate: aggregate_metrics.risk_alignment_worsening_rate,
                no_trade_bias_rate: aggregate_metrics.no_trade_bias_rate,
                evidence_caution_rate: aggregate_metrics.evidence_caution_rate,
                reason:
                    "multi-cycle paper trial needs more history before regression can be judged"
                        .to_string(),
                recommended_action:
                    PaperGovernanceRiskRegressionRecommendedAction::NeedsMoreHistory,
                paper_only: true,
            }],
            paper_only: true,
        };
    }
    let first = per_cycle_results.first().expect("first cycle result");
    let last = per_cycle_results.last().expect("last cycle result");
    let mut records = Vec::new();
    if last.risk_alignment_worsening_rate > first.risk_alignment_worsening_rate + 0.02
        || aggregate_metrics.risk_alignment_worsening_rate > 0.0
    {
        records.push(PaperGovernanceRiskRegressionRecord {
            record_id: "paper-governance-risk-alignment-worsened".to_string(),
            cycle_index: Some(last.cycle_index),
            signal: PaperGovernanceRiskRegressionSignal::RiskAlignmentWorsened,
            severity: PaperGovernanceAlertSeverity::High,
            risk_alignment_worsening_rate: aggregate_metrics.risk_alignment_worsening_rate,
            no_trade_bias_rate: aggregate_metrics.no_trade_bias_rate,
            evidence_caution_rate: aggregate_metrics.evidence_caution_rate,
            reason: "risk alignment worsening increased across paper trial cycles".to_string(),
            recommended_action:
                PaperGovernanceRiskRegressionRecommendedAction::TightenRiskFirstPolicy,
            paper_only: true,
        });
    }
    if last.counterfactual_changed_count > first.counterfactual_changed_count
        && aggregate_metrics.risk_alignment_worsening_rate > 0.0
    {
        records.push(PaperGovernanceRiskRegressionRecord {
            record_id: "paper-governance-reckless-buy-increase".to_string(),
            cycle_index: Some(last.cycle_index),
            signal: PaperGovernanceRiskRegressionSignal::RecklessBuyIncreased,
            severity: PaperGovernanceAlertSeverity::High,
            risk_alignment_worsening_rate: aggregate_metrics.risk_alignment_worsening_rate,
            no_trade_bias_rate: aggregate_metrics.no_trade_bias_rate,
            evidence_caution_rate: aggregate_metrics.evidence_caution_rate,
            reason: "counterfactual changes are increasing while risk alignment worsens"
                .to_string(),
            recommended_action: PaperGovernanceRiskRegressionRecommendedAction::ReduceTrendVoice,
            paper_only: true,
        });
    }
    if aggregate_metrics.risk_alignment_worsening_rate > 0.0
        && aggregate_metrics.overconfident_call_reduction_count == 0
        && aggregate_metrics.evidence_caution_rate == 0.0
    {
        records.push(PaperGovernanceRiskRegressionRecord {
            record_id: "paper-governance-risk-veto-ignored".to_string(),
            cycle_index: Some(last.cycle_index),
            signal: PaperGovernanceRiskRegressionSignal::RiskVetoIgnoredCounterfactual,
            severity: PaperGovernanceAlertSeverity::Medium,
            risk_alignment_worsening_rate: aggregate_metrics.risk_alignment_worsening_rate,
            no_trade_bias_rate: aggregate_metrics.no_trade_bias_rate,
            evidence_caution_rate: aggregate_metrics.evidence_caution_rate,
            reason: "counterfactual replay is worsening risk alignment without additional caution"
                .to_string(),
            recommended_action:
                PaperGovernanceRiskRegressionRecommendedAction::IncreaseEvidenceRequirement,
            paper_only: true,
        });
    }
    if aggregate_metrics.helpful_dissent_rewarded_count == 0
        && aggregate_metrics.trend_entry_suppression_score > 0.08
    {
        records.push(PaperGovernanceRiskRegressionRecord {
            record_id: "paper-governance-helpful-dissent-suppressed".to_string(),
            cycle_index: Some(last.cycle_index),
            signal: PaperGovernanceRiskRegressionSignal::HelpfulDissentSuppressed,
            severity: PaperGovernanceAlertSeverity::Medium,
            risk_alignment_worsening_rate: aggregate_metrics.risk_alignment_worsening_rate,
            no_trade_bias_rate: aggregate_metrics.no_trade_bias_rate,
            evidence_caution_rate: aggregate_metrics.evidence_caution_rate,
            reason: "helpful dissent is not being rewarded while TrendEntry is being suppressed"
                .to_string(),
            recommended_action:
                PaperGovernanceRiskRegressionRecommendedAction::IncreaseEvidenceRequirement,
            paper_only: true,
        });
    }
    if aggregate_metrics.no_trade_bias_rate > 0.60 {
        records.push(PaperGovernanceRiskRegressionRecord {
            record_id: "paper-governance-excessive-no-trade-bias".to_string(),
            cycle_index: Some(last.cycle_index),
            signal: PaperGovernanceRiskRegressionSignal::ExcessiveNoTradeBias,
            severity: PaperGovernanceAlertSeverity::Medium,
            risk_alignment_worsening_rate: aggregate_metrics.risk_alignment_worsening_rate,
            no_trade_bias_rate: aggregate_metrics.no_trade_bias_rate,
            evidence_caution_rate: aggregate_metrics.evidence_caution_rate,
            reason: "paper governance replay is leaning too far toward no-trade outcomes"
                .to_string(),
            recommended_action: PaperGovernanceRiskRegressionRecommendedAction::ContinuePaperTrial,
            paper_only: true,
        });
    }
    if records.is_empty() {
        records.push(PaperGovernanceRiskRegressionRecord {
            record_id: "paper-governance-no-regression".to_string(),
            cycle_index: Some(last.cycle_index),
            signal: PaperGovernanceRiskRegressionSignal::NoRegression,
            severity: PaperGovernanceAlertSeverity::Low,
            risk_alignment_worsening_rate: aggregate_metrics.risk_alignment_worsening_rate,
            no_trade_bias_rate: aggregate_metrics.no_trade_bias_rate,
            evidence_caution_rate: aggregate_metrics.evidence_caution_rate,
            reason: "multi-cycle paper trial did not surface a clear risk regression".to_string(),
            recommended_action: PaperGovernanceRiskRegressionRecommendedAction::ContinuePaperTrial,
            paper_only: true,
        });
    }
    let high_severity_count = records
        .iter()
        .filter(|record| record.severity == PaperGovernanceAlertSeverity::High)
        .count();
    let dominant_signals = records
        .iter()
        .map(|record| record.signal)
        .collect::<Vec<_>>();
    let regression_detected = records.iter().any(|record| {
        matches!(
            record.signal,
            PaperGovernanceRiskRegressionSignal::RiskAlignmentWorsened
                | PaperGovernanceRiskRegressionSignal::RecklessBuyIncreased
                | PaperGovernanceRiskRegressionSignal::RiskVetoIgnoredCounterfactual
                | PaperGovernanceRiskRegressionSignal::HelpfulDissentSuppressed
        )
    });
    let watchdog_status = if regression_detected {
        PaperGovernanceRiskRegressionWatchdogStatus::RegressionDetected
    } else if records
        .iter()
        .any(|record| record.signal == PaperGovernanceRiskRegressionSignal::ExcessiveNoTradeBias)
    {
        PaperGovernanceRiskRegressionWatchdogStatus::ClearWithWarnings
    } else {
        PaperGovernanceRiskRegressionWatchdogStatus::Clear
    };
    PaperGovernanceRiskRegressionWatchdog {
        watchdog_id: "paper-governance-risk-regression-watchdog".to_string(),
        record_count: records.len(),
        high_severity_count,
        regression_detected,
        dominant_signals,
        watchdog_status,
        records,
        paper_only: true,
    }
}

pub fn evaluate_paper_governance_voice_concentration(
    per_cycle_results: &[PerCyclePaperGovernanceTrialResult],
    paper_trial_state_store: &PaperGovernanceTrialStateStore,
) -> PaperGovernanceVoiceConcentrationWatchdog {
    if per_cycle_results.len() < 2 {
        return PaperGovernanceVoiceConcentrationWatchdog {
            watchdog_id: "paper-governance-voice-concentration-watchdog".to_string(),
            record_count: 1,
            high_severity_count: 0,
            concentration_detected: false,
            dominant_signals: vec![PaperGovernanceVoiceConcentrationSignal::InsufficientHistory],
            watchdog_status: PaperGovernanceVoiceConcentrationWatchdogStatus::InsufficientHistory,
            records: vec![PaperGovernanceVoiceConcentrationRecord {
                record_id: "paper-governance-voice-history".to_string(),
                member_id: None,
                role: None,
                signal: PaperGovernanceVoiceConcentrationSignal::InsufficientHistory,
                voice_concentration_index: paper_trial_voice_concentration_index(
                    paper_trial_state_store,
                ),
                member_voice_share: None,
                severity: PaperGovernanceAlertSeverity::Low,
                recommended_action:
                    PaperGovernanceVoiceConcentrationRecommendedAction::NeedsMoreHistory,
                paper_only: true,
            }],
            paper_only: true,
        };
    }
    let mut records = Vec::new();
    let risk_guard_share = role_paper_voice_share(
        paper_trial_state_store,
        PaperGovernanceTrialMemberRole::RiskGuard,
    );
    let trend_entry_drop = average_role_voice_drop(
        paper_trial_state_store,
        PaperGovernanceTrialMemberRole::TrendEntry,
    );
    let evidence_regime_drop = average_role_voice_drop(
        paper_trial_state_store,
        PaperGovernanceTrialMemberRole::EvidenceRegime,
    );
    let voice_concentration_index = paper_trial_voice_concentration_index(paper_trial_state_store);
    if risk_guard_share > 0.45 {
        records.push(PaperGovernanceVoiceConcentrationRecord {
            record_id: "paper-governance-risk-guard-dominance".to_string(),
            member_id: None,
            role: Some(PaperGovernanceTrialMemberRole::RiskGuard),
            signal: PaperGovernanceVoiceConcentrationSignal::RiskGuardDominance,
            voice_concentration_index,
            member_voice_share: Some(risk_guard_share),
            severity: if risk_guard_share > 0.55 {
                PaperGovernanceAlertSeverity::High
            } else {
                PaperGovernanceAlertSeverity::Medium
            },
            recommended_action:
                PaperGovernanceVoiceConcentrationRecommendedAction::CapDominantMember,
            paper_only: true,
        });
    }
    if trend_entry_drop > 0.08 {
        records.push(PaperGovernanceVoiceConcentrationRecord {
            record_id: "paper-governance-trend-entry-suppression".to_string(),
            member_id: None,
            role: Some(PaperGovernanceTrialMemberRole::TrendEntry),
            signal: PaperGovernanceVoiceConcentrationSignal::TrendEntrySuppression,
            voice_concentration_index,
            member_voice_share: None,
            severity: PaperGovernanceAlertSeverity::Medium,
            recommended_action:
                PaperGovernanceVoiceConcentrationRecommendedAction::RaiseSuppressedRoleFloor,
            paper_only: true,
        });
    }
    if evidence_regime_drop > 0.08 {
        records.push(PaperGovernanceVoiceConcentrationRecord {
            record_id: "paper-governance-evidence-regime-underweight".to_string(),
            member_id: None,
            role: Some(PaperGovernanceTrialMemberRole::EvidenceRegime),
            signal: PaperGovernanceVoiceConcentrationSignal::EvidenceRegimeUnderweight,
            voice_concentration_index,
            member_voice_share: None,
            severity: PaperGovernanceAlertSeverity::Medium,
            recommended_action:
                PaperGovernanceVoiceConcentrationRecommendedAction::RebalanceEvidenceRegime,
            paper_only: true,
        });
    }
    if voice_concentration_index > 0.65 {
        let dominant_member = paper_trial_state_store
            .member_states
            .iter()
            .max_by(|left, right| {
                left.paper_trial_voice_weight
                    .partial_cmp(&right.paper_trial_voice_weight)
                    .unwrap_or(std::cmp::Ordering::Equal)
            });
        records.push(PaperGovernanceVoiceConcentrationRecord {
            record_id: "paper-governance-single-member-dominance".to_string(),
            member_id: dominant_member.map(|state| state.member_id.clone()),
            role: dominant_member.map(|state| state.role),
            signal: PaperGovernanceVoiceConcentrationSignal::SingleMemberDominance,
            voice_concentration_index,
            member_voice_share: dominant_member.map(|state| state.paper_trial_voice_weight),
            severity: PaperGovernanceAlertSeverity::High,
            recommended_action:
                PaperGovernanceVoiceConcentrationRecommendedAction::CapDominantMember,
            paper_only: true,
        });
    }
    if records.is_empty() {
        records.push(PaperGovernanceVoiceConcentrationRecord {
            record_id: "paper-governance-healthy-distribution".to_string(),
            member_id: None,
            role: None,
            signal: PaperGovernanceVoiceConcentrationSignal::HealthyDistribution,
            voice_concentration_index,
            member_voice_share: None,
            severity: PaperGovernanceAlertSeverity::Low,
            recommended_action:
                PaperGovernanceVoiceConcentrationRecommendedAction::ContinueObservation,
            paper_only: true,
        });
    }
    let high_severity_count = records
        .iter()
        .filter(|record| record.severity == PaperGovernanceAlertSeverity::High)
        .count();
    let dominant_signals = records
        .iter()
        .map(|record| record.signal)
        .collect::<Vec<_>>();
    let concentration_detected = records.iter().any(|record| {
        matches!(
            record.signal,
            PaperGovernanceVoiceConcentrationSignal::RiskGuardDominance
                | PaperGovernanceVoiceConcentrationSignal::TrendEntrySuppression
                | PaperGovernanceVoiceConcentrationSignal::EvidenceRegimeUnderweight
                | PaperGovernanceVoiceConcentrationSignal::SingleMemberDominance
        )
    });
    let watchdog_status = if records.iter().any(|record| {
        record.signal == PaperGovernanceVoiceConcentrationSignal::SingleMemberDominance
            || (record.signal == PaperGovernanceVoiceConcentrationSignal::RiskGuardDominance
                && record.severity == PaperGovernanceAlertSeverity::High)
    }) {
        PaperGovernanceVoiceConcentrationWatchdogStatus::Concentrated
    } else if concentration_detected {
        PaperGovernanceVoiceConcentrationWatchdogStatus::HealthyWithWarnings
    } else {
        PaperGovernanceVoiceConcentrationWatchdogStatus::Healthy
    };
    PaperGovernanceVoiceConcentrationWatchdog {
        watchdog_id: "paper-governance-voice-concentration-watchdog".to_string(),
        record_count: records.len(),
        high_severity_count,
        concentration_detected,
        dominant_signals,
        watchdog_status,
        records,
        paper_only: true,
    }
}

pub fn build_paper_governance_policy_feedback(
    risk_watchdog: &PaperGovernanceRiskRegressionWatchdog,
    voice_watchdog: &PaperGovernanceVoiceConcentrationWatchdog,
    continuation_gate: &PaperGovernanceMultiCycleContinuationGate,
) -> PaperGovernancePolicyFeedbackSummary {
    let mut records = Vec::new();
    for record in &risk_watchdog.records {
        let feedback_kind = match record.signal {
            PaperGovernanceRiskRegressionSignal::RiskAlignmentWorsened => {
                PaperGovernancePolicyFeedbackKind::TightenRiskFirstPolicy
            }
            PaperGovernanceRiskRegressionSignal::RecklessBuyIncreased => {
                PaperGovernancePolicyFeedbackKind::ReduceVoiceCap
            }
            PaperGovernanceRiskRegressionSignal::RiskVetoIgnoredCounterfactual
            | PaperGovernanceRiskRegressionSignal::HelpfulDissentSuppressed => {
                PaperGovernancePolicyFeedbackKind::AddEvidenceRequirement
            }
            PaperGovernanceRiskRegressionSignal::ExcessiveNoTradeBias => {
                PaperGovernancePolicyFeedbackKind::AddNoTradeBiasCap
            }
            PaperGovernanceRiskRegressionSignal::NoRegression => {
                PaperGovernancePolicyFeedbackKind::ContinuePaperTrial
            }
            PaperGovernanceRiskRegressionSignal::InsufficientHistory => {
                PaperGovernancePolicyFeedbackKind::NeedsMoreHistory
            }
        };
        records.push(PaperGovernancePolicyFeedbackRecord {
            feedback_id: format!("risk-feedback-{}", records.len() + 1),
            source_watchdog: PaperGovernancePolicyFeedbackSourceWatchdog::RiskRegression,
            feedback_kind,
            severity: record.severity,
            reason: record.reason.clone(),
            recommended_next_sprint_action: match feedback_kind {
                PaperGovernancePolicyFeedbackKind::ContinuePaperTrial => {
                    PaperGovernancePolicyFeedbackNextSprintAction::ContinuePaperTrial
                }
                PaperGovernancePolicyFeedbackKind::NeedsMoreHistory => {
                    PaperGovernancePolicyFeedbackNextSprintAction::CollectMoreEvidence
                }
                _ => PaperGovernancePolicyFeedbackNextSprintAction::TuneShadowPolicyAgain,
            },
            paper_only: true,
        });
    }
    for record in &voice_watchdog.records {
        let feedback_kind = match record.signal {
            PaperGovernanceVoiceConcentrationSignal::RiskGuardDominance
            | PaperGovernanceVoiceConcentrationSignal::SingleMemberDominance => {
                PaperGovernancePolicyFeedbackKind::ReduceRiskGuardCap
            }
            PaperGovernanceVoiceConcentrationSignal::TrendEntrySuppression => {
                PaperGovernancePolicyFeedbackKind::ProtectTrendEntryFloor
            }
            PaperGovernanceVoiceConcentrationSignal::EvidenceRegimeUnderweight => {
                PaperGovernancePolicyFeedbackKind::IncreaseEvidenceRegimeFloor
            }
            PaperGovernanceVoiceConcentrationSignal::HealthyDistribution => {
                PaperGovernancePolicyFeedbackKind::ContinuePaperTrial
            }
            PaperGovernanceVoiceConcentrationSignal::InsufficientHistory => {
                PaperGovernancePolicyFeedbackKind::NeedsMoreHistory
            }
        };
        records.push(PaperGovernancePolicyFeedbackRecord {
            feedback_id: format!("voice-feedback-{}", records.len() + 1),
            source_watchdog: PaperGovernancePolicyFeedbackSourceWatchdog::VoiceConcentration,
            feedback_kind,
            severity: record.severity,
            reason: format!("voice watchdog flagged {:?}", record.signal),
            recommended_next_sprint_action: match feedback_kind {
                PaperGovernancePolicyFeedbackKind::ContinuePaperTrial => {
                    PaperGovernancePolicyFeedbackNextSprintAction::ContinuePaperTrial
                }
                PaperGovernancePolicyFeedbackKind::NeedsMoreHistory => {
                    PaperGovernancePolicyFeedbackNextSprintAction::CollectMoreEvidence
                }
                _ => PaperGovernancePolicyFeedbackNextSprintAction::TuneShadowPolicyAgain,
            },
            paper_only: true,
        });
    }
    if matches!(
        continuation_gate.readiness_status,
        PaperGovernanceMultiCycleContinuationGateReadinessStatus::NeedsMoreHistory
    ) {
        records.push(PaperGovernancePolicyFeedbackRecord {
            feedback_id: format!("gate-feedback-{}", records.len() + 1),
            source_watchdog: PaperGovernancePolicyFeedbackSourceWatchdog::ContinuationGate,
            feedback_kind: PaperGovernancePolicyFeedbackKind::NeedsMoreHistory,
            severity: PaperGovernanceAlertSeverity::Low,
            reason: "multi-cycle continuation gate still needs more history".to_string(),
            recommended_next_sprint_action:
                PaperGovernancePolicyFeedbackNextSprintAction::CollectMoreEvidence,
            paper_only: true,
        });
    }
    if records.is_empty() {
        records.push(PaperGovernancePolicyFeedbackRecord {
            feedback_id: "gate-feedback-continue".to_string(),
            source_watchdog: PaperGovernancePolicyFeedbackSourceWatchdog::ContinuationGate,
            feedback_kind: PaperGovernancePolicyFeedbackKind::ContinuePaperTrial,
            severity: PaperGovernanceAlertSeverity::Low,
            reason: "paper governance can continue in paper-only mode".to_string(),
            recommended_next_sprint_action:
                PaperGovernancePolicyFeedbackNextSprintAction::ContinuePaperTrial,
            paper_only: true,
        });
    }
    let high_severity_count = records
        .iter()
        .filter(|record| record.severity == PaperGovernanceAlertSeverity::High)
        .count();
    let dominant_feedback = records
        .iter()
        .max_by_key(|record| match record.severity {
            PaperGovernanceAlertSeverity::Low => 0,
            PaperGovernanceAlertSeverity::Medium => 1,
            PaperGovernanceAlertSeverity::High => 2,
        })
        .map(|record| record.feedback_kind);
    let feedback_status = if matches!(
        continuation_gate.readiness_status,
        PaperGovernanceMultiCycleContinuationGateReadinessStatus::BlockedByRiskRegression
            | PaperGovernanceMultiCycleContinuationGateReadinessStatus::BlockedByVoiceConcentration
            | PaperGovernanceMultiCycleContinuationGateReadinessStatus::BlockedBySafety
    ) || high_severity_count > 0
    {
        PaperGovernancePolicyFeedbackStatus::BlockActualGovernance
    } else if records.iter().any(|record| {
        !matches!(
            record.feedback_kind,
            PaperGovernancePolicyFeedbackKind::ContinuePaperTrial
                | PaperGovernancePolicyFeedbackKind::NeedsMoreHistory
        )
    }) {
        PaperGovernancePolicyFeedbackStatus::TunePolicy
    } else if records
        .iter()
        .any(|record| record.feedback_kind == PaperGovernancePolicyFeedbackKind::NeedsMoreHistory)
    {
        PaperGovernancePolicyFeedbackStatus::CollectMoreEvidence
    } else {
        PaperGovernancePolicyFeedbackStatus::ContinueTrial
    };
    PaperGovernancePolicyFeedbackSummary {
        summary_id: "paper-governance-policy-feedback".to_string(),
        feedback_count: records.len(),
        high_severity_count,
        dominant_feedback,
        feedback_status,
        records,
        paper_only: true,
    }
}

fn build_multi_cycle_continuation_gate_from_parts(
    cycle_count: usize,
    risk_watchdog: &PaperGovernanceRiskRegressionWatchdog,
    voice_watchdog: &PaperGovernanceVoiceConcentrationWatchdog,
    aggregate_metrics: &PaperGovernanceEffectivenessMetrics,
    aggregate_risk_first_check: &PaperGovernanceRiskFirstEffectivenessCheck,
    safety_status: PaperGovernanceTrialSafetyGuardStatus,
) -> PaperGovernanceMultiCycleContinuationGate {
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    if safety_status == PaperGovernanceTrialSafetyGuardStatus::Violated {
        blockers.push("paper governance multi-cycle safety was violated".to_string());
    }
    if risk_watchdog.watchdog_status
        == PaperGovernanceRiskRegressionWatchdogStatus::RegressionDetected
    {
        blockers.push("paper governance multi-cycle risk regression was detected".to_string());
    }
    if voice_watchdog.watchdog_status
        == PaperGovernanceVoiceConcentrationWatchdogStatus::Concentrated
    {
        blockers.push("paper governance multi-cycle voice concentration is unsafe".to_string());
    }
    if cycle_count < 2 {
        warnings.push("paper governance multi-cycle history is still shallow".to_string());
    }
    if matches!(
        risk_watchdog.watchdog_status,
        PaperGovernanceRiskRegressionWatchdogStatus::ClearWithWarnings
    ) {
        warnings.push("risk regression watchdog emitted warnings".to_string());
    }
    if matches!(
        voice_watchdog.watchdog_status,
        PaperGovernanceVoiceConcentrationWatchdogStatus::HealthyWithWarnings
    ) {
        warnings.push("voice concentration watchdog emitted warnings".to_string());
    }
    if matches!(
        aggregate_risk_first_check.risk_first_status,
        PaperGovernanceRiskFirstStatus::PreservedWithWarnings
            | PaperGovernanceRiskFirstStatus::InsufficientData
    ) {
        warnings.extend(aggregate_risk_first_check.warnings.clone());
    }
    let readiness_status = if safety_status == PaperGovernanceTrialSafetyGuardStatus::Violated {
        PaperGovernanceMultiCycleContinuationGateReadinessStatus::BlockedBySafety
    } else if risk_watchdog.watchdog_status
        == PaperGovernanceRiskRegressionWatchdogStatus::RegressionDetected
    {
        PaperGovernanceMultiCycleContinuationGateReadinessStatus::BlockedByRiskRegression
    } else if voice_watchdog.watchdog_status
        == PaperGovernanceVoiceConcentrationWatchdogStatus::Concentrated
    {
        PaperGovernanceMultiCycleContinuationGateReadinessStatus::BlockedByVoiceConcentration
    } else if cycle_count < 2 {
        PaperGovernanceMultiCycleContinuationGateReadinessStatus::NeedsMoreHistory
    } else if aggregate_metrics.effectiveness_status == PaperGovernanceEffectivenessStatus::Neutral
        || matches!(
            aggregate_risk_first_check.risk_first_status,
            PaperGovernanceRiskFirstStatus::PreservedWithWarnings
                | PaperGovernanceRiskFirstStatus::InsufficientData
        )
    {
        PaperGovernanceMultiCycleContinuationGateReadinessStatus::NeedsPolicyTuning
    } else if warnings.is_empty() {
        PaperGovernanceMultiCycleContinuationGateReadinessStatus::ContinuePaperTrial
    } else {
        PaperGovernanceMultiCycleContinuationGateReadinessStatus::ContinueWithWarnings
    };
    PaperGovernanceMultiCycleContinuationGate {
        gate_id: "paper-governance-multi-cycle-continuation-gate".to_string(),
        cycle_count,
        risk_regression_status: risk_watchdog.watchdog_status,
        voice_concentration_status: voice_watchdog.watchdog_status,
        effectiveness_status: aggregate_metrics.effectiveness_status,
        risk_first_status: aggregate_risk_first_check.risk_first_status,
        safety_status,
        continue_paper_trial: matches!(
            readiness_status,
            PaperGovernanceMultiCycleContinuationGateReadinessStatus::ContinuePaperTrial
                | PaperGovernanceMultiCycleContinuationGateReadinessStatus::ContinueWithWarnings
        ),
        readiness_status,
        blockers,
        warnings,
        paper_only: true,
    }
}

pub fn evaluate_paper_governance_multi_cycle_continuation_gate(
    multi_cycle_result: &PaperGovernanceTrialMultiCycleResult,
) -> PaperGovernanceMultiCycleContinuationGate {
    build_multi_cycle_continuation_gate_from_parts(
        multi_cycle_result.completed_cycle_count,
        &multi_cycle_result.risk_regression_watchdog,
        &multi_cycle_result.voice_concentration_watchdog,
        &multi_cycle_result.aggregate_effectiveness_metrics,
        &multi_cycle_result.aggregate_risk_first_check,
        multi_cycle_result.safety_guard.guard_status,
    )
}

pub fn prove_paper_governance_trial_ledger_write(
    multi_cycle_result: &PaperGovernanceTrialMultiCycleResult,
    ledger_path: &Path,
) -> Result<PaperGovernanceTrialLedgerWriteProof, String> {
    validate_local_json_path(ledger_path, "paper governance trial multicycle ledger path")?;
    let ledger_exists_after_write = ledger_path.exists();
    let (entry_count, paper_only_count, unsafe_entry_count) = if ledger_exists_after_write {
        let ledger = load_paper_governance_trial_ledger_from_local_json(ledger_path)?;
        let paper_only_count = ledger
            .entries
            .iter()
            .filter(|entry| entry.paper_only)
            .count();
        let unsafe_entry_count = ledger.entries.len().saturating_sub(paper_only_count);
        (ledger.entry_count, paper_only_count, unsafe_entry_count)
    } else {
        (0, 0, 0)
    };
    let proof_status = if multi_cycle_result.wrote_ledger && !ledger_exists_after_write {
        PaperGovernanceTrialLedgerWriteProofStatus::Failed
    } else if unsafe_entry_count > 0 {
        PaperGovernanceTrialLedgerWriteProofStatus::Failed
    } else if entry_count < multi_cycle_result.final_ledger_entry_count {
        PaperGovernanceTrialLedgerWriteProofStatus::ProvenWithWarnings
    } else {
        PaperGovernanceTrialLedgerWriteProofStatus::Proven
    };
    Ok(PaperGovernanceTrialLedgerWriteProof {
        proof_id: format!("{}-ledger-write-proof", multi_cycle_result.run_id),
        expected_output_path: ledger_path.display().to_string(),
        wrote_ledger: multi_cycle_result.wrote_ledger,
        ledger_exists_after_write,
        entry_count,
        paper_only_count,
        unsafe_entry_count,
        proof_status,
        paper_only: true,
    })
}

fn default_multi_cycle_safety_guard() -> PaperGovernanceMultiCycleSafetyGuard {
    PaperGovernanceMultiCycleSafetyGuard {
        actual_score_mutation_detected: false,
        actual_voice_mutation_detected: false,
        committee_decision_mutation_detected: false,
        chairman_decision_mutation_detected: false,
        risk_governor_mutation_detected: false,
        member_opinion_mutation_detected: false,
        paper_trial_used_as_live_decision_detected: false,
        trade_signal_detected: false,
        order_detected: false,
        broker_order_account_detected: false,
        ledger_write_when_dry_run_detected: false,
        unsafe_continuation_gate_open_detected: false,
        guard_status: PaperGovernanceTrialSafetyGuardStatus::Preserved,
        violations: Vec::new(),
        paper_only: true,
    }
}

pub fn build_owner_paper_governance_multi_cycle_summary(
    multi_cycle_result: &PaperGovernanceTrialMultiCycleResult,
    continuation_gate: &PaperGovernanceMultiCycleContinuationGate,
) -> OwnerPaperGovernanceMultiCycleSummary {
    OwnerPaperGovernanceMultiCycleSummary {
        summary_id: format!("{}-owner-paper-trial-multicycle-summary", multi_cycle_result.run_id),
        completed_cycle_count: multi_cycle_result.completed_cycle_count,
        final_ledger_entry_count: multi_cycle_result.final_ledger_entry_count,
        risk_regression_status: multi_cycle_result.risk_regression_watchdog.watchdog_status,
        voice_concentration_status: multi_cycle_result.voice_concentration_watchdog.watchdog_status,
        policy_feedback_status: multi_cycle_result.policy_feedback.feedback_status,
        continuation_gate_status: continuation_gate.readiness_status,
        message: "Paper governance was evaluated across multiple cycles. Actual score and voice did not change. Committee decisions and Risk Governor were not changed. Risk regression and voice concentration are still gating actual governance."
            .to_string(),
        paper_trial_only: true,
        no_actual_score_mutation: true,
        no_actual_voice_mutation: true,
        no_committee_decision_change: true,
        no_risk_override: true,
        not_trade_signal: true,
        paper_only: true,
    }
}

pub fn evaluate_paper_governance_multi_cycle_safety(
    multi_cycle_result: &PaperGovernanceTrialMultiCycleResult,
    batch_before: &BatchCommitteeCycleResult,
    batch_after: Option<&BatchCommitteeCycleResult>,
) -> PaperGovernanceMultiCycleSafetyGuard {
    let after_batch = batch_after.unwrap_or(batch_before);
    let actual_score_snapshot = |store: Option<&PaperGovernanceTrialStateStore>| {
        store.map(|store| {
            store
                .member_states
                .iter()
                .map(|state| (state.member_id.clone(), state.actual_score_snapshot))
                .collect::<BTreeMap<_, _>>()
        })
    };
    let actual_voice_snapshot = |store: Option<&PaperGovernanceTrialStateStore>| {
        store.map(|store| {
            store
                .member_states
                .iter()
                .map(|state| (state.member_id.clone(), state.actual_voice_snapshot))
                .collect::<BTreeMap<_, _>>()
        })
    };
    let risk_snapshot = |decisions: &[ChairmanDecision]| {
        decisions
            .iter()
            .map(|decision| (decision.decision_id.clone(), decision.risk_governor_status))
            .collect::<BTreeMap<_, _>>()
    };
    let live_markers = vec![
        multi_cycle_result.run_id.clone(),
        "paper-trial-live".to_string(),
        "counterfactual-live".to_string(),
    ];
    let trade_markers = ["trade-signal".to_string()];
    let order_markers = ["order".to_string()];
    let broker_markers = [
        "broker".to_string(),
        "order".to_string(),
        "account".to_string(),
    ];
    let actual_score_mutation_detected =
        actual_score_snapshot(batch_before.paper_governance_trial_state_store.as_ref())
            != actual_score_snapshot(after_batch.paper_governance_trial_state_store.as_ref());
    let actual_voice_mutation_detected =
        actual_voice_snapshot(batch_before.paper_governance_trial_state_store.as_ref())
            != actual_voice_snapshot(after_batch.paper_governance_trial_state_store.as_ref());
    let committee_decision_mutation_detected =
        batch_before.committee_sessions != after_batch.committee_sessions;
    let chairman_decision_mutation_detected =
        batch_before.chairman_decisions != after_batch.chairman_decisions;
    let risk_governor_mutation_detected = risk_snapshot(&batch_before.chairman_decisions)
        != risk_snapshot(&after_batch.chairman_decisions);
    let member_opinion_mutation_detected =
        batch_before.member_opinions != after_batch.member_opinions;
    let paper_trial_used_as_live_decision_detected =
        value_contains_debug_marker(&after_batch.chairman_decisions, &live_markers)
            && !value_contains_debug_marker(&batch_before.chairman_decisions, &live_markers);
    let trade_signal_detected =
        value_contains_debug_marker(&after_batch.committee_sessions, &trade_markers)
            && !value_contains_debug_marker(&batch_before.committee_sessions, &trade_markers);
    let order_detected = value_contains_debug_marker(&after_batch.event_queue, &order_markers)
        && !value_contains_debug_marker(&batch_before.event_queue, &order_markers);
    let broker_order_account_detected = value_contains_debug_marker(after_batch, &broker_markers)
        && !value_contains_debug_marker(batch_before, &broker_markers);
    let ledger_write_when_dry_run_detected =
        multi_cycle_result.dry_run && multi_cycle_result.wrote_ledger;
    let unsafe_continuation_gate_open_detected = multi_cycle_result
        .aggregate_continuation_gate
        .continue_paper_trial
        && (multi_cycle_result.risk_regression_watchdog.watchdog_status
            == PaperGovernanceRiskRegressionWatchdogStatus::RegressionDetected
            || multi_cycle_result
                .voice_concentration_watchdog
                .watchdog_status
                == PaperGovernanceVoiceConcentrationWatchdogStatus::Concentrated
            || multi_cycle_result
                .aggregate_effectiveness_metrics
                .effectiveness_status
                == PaperGovernanceEffectivenessStatus::Risky
            || ledger_write_when_dry_run_detected);
    let mut violations = Vec::new();
    if actual_score_mutation_detected {
        violations.push("paper governance multicycle mutated actual score".to_string());
    }
    if actual_voice_mutation_detected {
        violations.push("paper governance multicycle mutated actual voice".to_string());
    }
    if committee_decision_mutation_detected {
        violations.push("paper governance multicycle mutated committee session".to_string());
    }
    if chairman_decision_mutation_detected {
        violations.push("paper governance multicycle mutated ChairmanDecision".to_string());
    }
    if risk_governor_mutation_detected {
        violations.push("paper governance multicycle mutated Risk Governor".to_string());
    }
    if member_opinion_mutation_detected {
        violations.push("paper governance multicycle mutated member opinions".to_string());
    }
    if paper_trial_used_as_live_decision_detected {
        violations.push("paper governance multicycle was referenced as live decision".to_string());
    }
    if trade_signal_detected {
        violations.push("paper governance multicycle created a trade signal".to_string());
    }
    if order_detected {
        violations.push("paper governance multicycle created an order".to_string());
    }
    if broker_order_account_detected {
        violations.push("paper governance multicycle touched broker/order/account".to_string());
    }
    if ledger_write_when_dry_run_detected {
        violations.push("paper governance multicycle wrote ledger during dry-run".to_string());
    }
    if unsafe_continuation_gate_open_detected {
        violations
            .push("paper governance multicycle continuation gate opened unsafely".to_string());
    }
    PaperGovernanceMultiCycleSafetyGuard {
        actual_score_mutation_detected,
        actual_voice_mutation_detected,
        committee_decision_mutation_detected,
        chairman_decision_mutation_detected,
        risk_governor_mutation_detected,
        member_opinion_mutation_detected,
        paper_trial_used_as_live_decision_detected,
        trade_signal_detected,
        order_detected,
        broker_order_account_detected,
        ledger_write_when_dry_run_detected,
        unsafe_continuation_gate_open_detected,
        guard_status: if violations.is_empty() {
            PaperGovernanceTrialSafetyGuardStatus::Preserved
        } else {
            PaperGovernanceTrialSafetyGuardStatus::Violated
        },
        violations,
        paper_only: true,
    }
}

fn paper_governance_trial_multicycle_entry_from_run(
    trial_run_result: &PaperGovernanceTrialRunResult,
    run_id: &str,
    cycle_index: usize,
    voice_concentration_index: f64,
) -> PaperGovernanceTrialLedgerEntry {
    let mut entry = paper_trial_ledger_entry_from_run(trial_run_result, voice_concentration_index);
    entry.entry_id = format!("{run_id}-cycle-{}-ledger-entry", cycle_index + 1);
    entry.run_id = format!("{run_id}-cycle-{}", cycle_index + 1);
    entry
}

pub fn run_paper_governance_trial_multi_cycle(
    paper_trial_run_result: &PaperGovernanceTrialRunResult,
    batch_result: &BatchCommitteeCycleResult,
    config: &PaperGovernanceTrialMultiCycleConfig,
) -> Result<PaperGovernanceTrialMultiCycleResult, String> {
    if !config.paper_only {
        return Err("paper governance trial multicycle run must stay paper_only".to_string());
    }
    if config.cycle_count == 0 {
        return Err("paper governance trial multicycle requires positive cycle_count".to_string());
    }
    for (path, label) in [
        (
            config.ledger_input_path.as_ref(),
            "paper governance multicycle ledger input path",
        ),
        (
            config.ledger_output_path.as_ref(),
            "paper governance multicycle ledger output path",
        ),
        (
            config.output_path.as_ref(),
            "paper governance multicycle output path",
        ),
    ] {
        if let Some(path) = path {
            validate_local_json_path(Path::new(path), label)?;
        }
    }
    if !config.dry_run && config.append_ledger_entries && config.ledger_output_path.is_none() {
        return Err(
            "paper governance trial multicycle requires ledger_output_path when dry_run=false and append_ledger_entries=true"
                .to_string(),
        );
    }
    let paper_trial_state_store = paper_trial_run_result
        .trial_store_after
        .as_ref()
        .or(paper_trial_run_result.trial_store_before.as_ref())
        .ok_or_else(|| {
            "paper governance trial multicycle requires paper trial state store".to_string()
        })?;
    let voice_concentration_index = paper_trial_voice_concentration_index(paper_trial_state_store);
    let mut ledger = if let Some(path) = config.ledger_input_path.as_ref() {
        if Path::new(path).exists() {
            load_paper_governance_trial_ledger_from_local_json(Path::new(path))?
        } else {
            default_paper_governance_trial_ledger()
        }
    } else {
        default_paper_governance_trial_ledger()
    };
    let previous_ledger_entry_count = ledger.entry_count;
    let mut per_cycle_results = Vec::new();
    let mut aggregate_effectiveness_metrics = PaperGovernanceEffectivenessMetrics {
        metrics_id: format!("{}-aggregate-effectiveness", config.run_id),
        trial_entry_count: ledger.entry_count,
        counterfactual_changed_count: 0,
        risk_alignment_improvement_rate: 0.0,
        risk_alignment_worsening_rate: 0.0,
        evidence_caution_rate: 0.0,
        no_trade_bias_rate: 0.0,
        overconfident_call_reduction_count: 0,
        helpful_dissent_rewarded_count: 0,
        voice_concentration_index,
        trend_entry_suppression_score: average_role_voice_drop(
            paper_trial_state_store,
            PaperGovernanceTrialMemberRole::TrendEntry,
        ),
        evidence_regime_underweight_score: average_role_voice_drop(
            paper_trial_state_store,
            PaperGovernanceTrialMemberRole::EvidenceRegime,
        ),
        risk_guard_dominance_score: role_paper_voice_share(
            paper_trial_state_store,
            PaperGovernanceTrialMemberRole::RiskGuard,
        ),
        effectiveness_status: PaperGovernanceEffectivenessStatus::InsufficientHistory,
        paper_only: true,
    };
    let mut aggregate_risk_first_check = PaperGovernanceRiskFirstEffectivenessCheck {
        check_id: format!("{}-aggregate-risk-first", config.run_id),
        risk_alignment_improved: false,
        risk_alignment_worsened: false,
        reckless_buy_reduced: false,
        helpful_risk_dissent_preserved: false,
        risk_guard_dominance_detected: false,
        excessive_no_trade_bias_detected: false,
        risk_first_status: PaperGovernanceRiskFirstStatus::InsufficientData,
        warnings: Vec::new(),
        paper_only: true,
    };
    let mut appended_entry_count = 0usize;
    for cycle_index in 0..config.cycle_count {
        let replay_result = if config.run_counterfactual_replay {
            run_counterfactual_committee_replay(
                batch_result,
                paper_trial_state_store,
                &default_counterfactual_committee_replay_policy(),
            )?
        } else {
            default_empty_counterfactual_committee_replay_result(format!(
                "{}-cycle-{}-counterfactual-replay",
                config.run_id,
                cycle_index + 1
            ))
        };
        if config.append_ledger_entries {
            append_paper_governance_trial_ledger_entry(
                &mut ledger,
                paper_governance_trial_multicycle_entry_from_run(
                    paper_trial_run_result,
                    &config.run_id,
                    cycle_index,
                    voice_concentration_index,
                ),
            )?;
            appended_entry_count += 1;
        }
        let cycle_metrics = compute_paper_governance_effectiveness_metrics(
            &ledger,
            &replay_result,
            paper_trial_state_store,
        );
        if config.append_ledger_entries {
            if let Some(entry) = ledger.entries.last_mut() {
                entry.counterfactual_changed_count = replay_result.changed_count;
                entry.risk_alignment_improvement_rate =
                    cycle_metrics.risk_alignment_improvement_rate;
                entry.risk_alignment_worsening_rate = cycle_metrics.risk_alignment_worsening_rate;
                entry.voice_concentration_index = cycle_metrics.voice_concentration_index;
            }
            normalize_paper_governance_trial_ledger(&mut ledger);
        }
        let cycle_risk_first =
            evaluate_paper_governance_risk_first_effectiveness(&cycle_metrics, &replay_result);
        let cycle_safety = evaluate_paper_governance_trial_safety_v2(
            paper_trial_run_result,
            &replay_result,
            batch_result,
            Some(batch_result),
        );
        let aggregate_cycle_gate = evaluate_paper_governance_continuation_gate(
            &ledger,
            &replay_result,
            &cycle_metrics,
            &cycle_risk_first,
            &cycle_safety,
        );
        per_cycle_results.push(PerCyclePaperGovernanceTrialResult {
            cycle_index: cycle_index + 1,
            ledger_entry_id: ledger.latest_entry_id.clone(),
            counterfactual_changed_count: replay_result.changed_count,
            risk_alignment_improvement_rate: cycle_metrics.risk_alignment_improvement_rate,
            risk_alignment_worsening_rate: cycle_metrics.risk_alignment_worsening_rate,
            voice_concentration_index: cycle_metrics.voice_concentration_index,
            no_trade_bias_rate: cycle_metrics.no_trade_bias_rate,
            continuation_gate_status: aggregate_cycle_gate.readiness_status,
            safety_status: cycle_safety.guard_status,
            paper_only: true,
        });
        aggregate_effectiveness_metrics = cycle_metrics;
        aggregate_risk_first_check = cycle_risk_first;
    }
    let risk_regression_watchdog = evaluate_paper_governance_risk_regression(
        &per_cycle_results,
        &aggregate_effectiveness_metrics,
    );
    let voice_concentration_watchdog =
        evaluate_paper_governance_voice_concentration(&per_cycle_results, paper_trial_state_store);
    let provisional_gate = build_multi_cycle_continuation_gate_from_parts(
        per_cycle_results.len(),
        &risk_regression_watchdog,
        &voice_concentration_watchdog,
        &aggregate_effectiveness_metrics,
        &aggregate_risk_first_check,
        PaperGovernanceTrialSafetyGuardStatus::Preserved,
    );
    let mut result = PaperGovernanceTrialMultiCycleResult {
        run_id: config.run_id.clone(),
        requested_cycle_count: config.cycle_count,
        completed_cycle_count: per_cycle_results.len(),
        previous_ledger_entry_count,
        appended_entry_count,
        final_ledger_entry_count: ledger.entry_count,
        per_cycle_results,
        aggregate_effectiveness_metrics,
        aggregate_risk_first_check,
        aggregate_continuation_gate: provisional_gate.clone(),
        risk_regression_watchdog,
        voice_concentration_watchdog,
        policy_feedback: PaperGovernancePolicyFeedbackSummary {
            summary_id: "paper-governance-policy-feedback".to_string(),
            feedback_count: 0,
            high_severity_count: 0,
            dominant_feedback: None,
            feedback_status: PaperGovernancePolicyFeedbackStatus::InsufficientHistory,
            records: Vec::new(),
            paper_only: true,
        },
        safety_guard: default_multi_cycle_safety_guard(),
        ledger_write_proof: None,
        owner_summary: None,
        run_status: PaperGovernanceTrialRunStatus::PassedWithWarnings,
        dry_run: config.dry_run,
        wrote_ledger: false,
        ledger_output_path: config.ledger_output_path.clone(),
        paper_only: true,
    };
    result.policy_feedback = build_paper_governance_policy_feedback(
        &result.risk_regression_watchdog,
        &result.voice_concentration_watchdog,
        &result.aggregate_continuation_gate,
    );
    if !config.dry_run && config.append_ledger_entries {
        if let Some(path) = config.ledger_output_path.as_ref() {
            save_paper_governance_trial_ledger_to_local_json(Path::new(path), &ledger)?;
            result.wrote_ledger = true;
        }
    }
    result.safety_guard =
        evaluate_paper_governance_multi_cycle_safety(&result, batch_result, Some(batch_result));
    result.aggregate_continuation_gate = build_multi_cycle_continuation_gate_from_parts(
        result.completed_cycle_count,
        &result.risk_regression_watchdog,
        &result.voice_concentration_watchdog,
        &result.aggregate_effectiveness_metrics,
        &result.aggregate_risk_first_check,
        result.safety_guard.guard_status,
    );
    result.policy_feedback = build_paper_governance_policy_feedback(
        &result.risk_regression_watchdog,
        &result.voice_concentration_watchdog,
        &result.aggregate_continuation_gate,
    );
    if !config.dry_run && config.append_ledger_entries {
        if let Some(path) = config.ledger_output_path.as_ref() {
            result.ledger_write_proof = Some(prove_paper_governance_trial_ledger_write(
                &result,
                Path::new(path),
            )?);
        }
    }
    if config.emit_owner_summary {
        result.owner_summary = Some(build_owner_paper_governance_multi_cycle_summary(
            &result,
            &result.aggregate_continuation_gate,
        ));
    }
    result.run_status = if result.safety_guard.guard_status
        == PaperGovernanceTrialSafetyGuardStatus::Violated
        || matches!(
            result.aggregate_continuation_gate.readiness_status,
            PaperGovernanceMultiCycleContinuationGateReadinessStatus::BlockedByRiskRegression
                | PaperGovernanceMultiCycleContinuationGateReadinessStatus::BlockedByVoiceConcentration
                | PaperGovernanceMultiCycleContinuationGateReadinessStatus::BlockedBySafety
        )
    {
        PaperGovernanceTrialRunStatus::Failed
    } else if result.aggregate_continuation_gate.readiness_status
        == PaperGovernanceMultiCycleContinuationGateReadinessStatus::ContinuePaperTrial
        && result.policy_feedback.feedback_status
            == PaperGovernancePolicyFeedbackStatus::ContinueTrial
    {
        PaperGovernanceTrialRunStatus::Passed
    } else {
        PaperGovernanceTrialRunStatus::PassedWithWarnings
    };
    if !config.dry_run {
        if let Some(path) = config.output_path.as_ref() {
            write_safe_json(Path::new(path), &result)?;
        }
    }
    Ok(result)
}

pub fn paper_governance_trial_multicycle_requested_from_flags(
    enabled: bool,
    dry_run: bool,
    cycle_count: usize,
    append_ledger_entries: bool,
    ledger_output_path: Option<&String>,
    output_path: Option<&String>,
    emit_owner_summary: bool,
) -> bool {
    enabled
        || !dry_run
        || ledger_output_path.is_some()
        || output_path.is_some()
        || (enabled && (cycle_count > 1 || append_ledger_entries || emit_owner_summary))
}

fn maybe_run_paper_governance_trial_multi_cycle_for_batch_result(
    run_id: String,
    enabled: bool,
    dry_run: bool,
    cycle_count: usize,
    append_ledger_entries: bool,
    ledger_input_path: Option<&String>,
    ledger_output_path: Option<&String>,
    output_path: Option<&String>,
    emit_owner_summary: bool,
    batch_result: &mut BatchCommitteeCycleResult,
) -> Result<Option<PaperGovernanceTrialMultiCycleResult>, String> {
    if !paper_governance_trial_multicycle_requested_from_flags(
        enabled,
        dry_run,
        cycle_count,
        append_ledger_entries,
        ledger_output_path,
        output_path,
        emit_owner_summary,
    ) {
        return Ok(None);
    }
    let trial_run_result = batch_result
        .paper_governance_trial_run_result
        .clone()
        .ok_or_else(|| {
            "paper governance trial multicycle requires paper governance trial run result"
                .to_string()
        })?;
    let result = run_paper_governance_trial_multi_cycle(
        &trial_run_result,
        batch_result,
        &PaperGovernanceTrialMultiCycleConfig {
            run_id,
            enabled,
            cycle_count,
            ledger_input_path: ledger_input_path.cloned(),
            ledger_output_path: ledger_output_path.cloned(),
            output_path: output_path.cloned(),
            dry_run,
            append_ledger_entries,
            run_counterfactual_replay: true,
            emit_owner_summary,
            paper_only: true,
        },
    )?;
    batch_result.paper_governance_trial_ledger_write_proof = result.ledger_write_proof.clone();
    batch_result.paper_governance_risk_regression_watchdog =
        Some(result.risk_regression_watchdog.clone());
    batch_result.paper_governance_voice_concentration_watchdog =
        Some(result.voice_concentration_watchdog.clone());
    batch_result.paper_governance_policy_feedback_summary = Some(result.policy_feedback.clone());
    batch_result.paper_governance_multi_cycle_continuation_gate =
        Some(result.aggregate_continuation_gate.clone());
    batch_result.owner_paper_governance_multi_cycle_summary = result.owner_summary.clone();
    batch_result.paper_governance_multi_cycle_safety_guard = Some(result.safety_guard.clone());
    batch_result.paper_governance_trial_multi_cycle_result = Some(result.clone());
    Ok(Some(result))
}

fn governance_feedback_kind_label(kind: GovernancePolicyFeedbackKindV2) -> String {
    format!("{kind:?}")
}

fn governance_feedback_source_label(source: GovernancePolicyFeedbackSource) -> String {
    format!("{source:?}")
}

fn increment_btree_counter(map: &mut BTreeMap<String, usize>, key: String) {
    *map.entry(key).or_insert(0) += 1;
}

fn governance_feedback_kind_from_risk_signal(
    signal: PaperGovernanceRiskRegressionSignal,
) -> GovernancePolicyFeedbackKindV2 {
    match signal {
        PaperGovernanceRiskRegressionSignal::RiskAlignmentWorsened => {
            GovernancePolicyFeedbackKindV2::TightenRiskFirstPolicy
        }
        PaperGovernanceRiskRegressionSignal::RecklessBuyIncreased => {
            GovernancePolicyFeedbackKindV2::ReduceVoiceCap
        }
        PaperGovernanceRiskRegressionSignal::RiskVetoIgnoredCounterfactual
        | PaperGovernanceRiskRegressionSignal::HelpfulDissentSuppressed => {
            GovernancePolicyFeedbackKindV2::AddEvidenceRequirement
        }
        PaperGovernanceRiskRegressionSignal::ExcessiveNoTradeBias => {
            GovernancePolicyFeedbackKindV2::AddNoTradeBiasCap
        }
        PaperGovernanceRiskRegressionSignal::InsufficientHistory => {
            GovernancePolicyFeedbackKindV2::NeedsMoreHistory
        }
        PaperGovernanceRiskRegressionSignal::NoRegression => {
            GovernancePolicyFeedbackKindV2::ContinuePaperTrial
        }
    }
}

fn governance_feedback_kind_from_voice_signal(
    signal: PaperGovernanceVoiceConcentrationSignal,
) -> GovernancePolicyFeedbackKindV2 {
    match signal {
        PaperGovernanceVoiceConcentrationSignal::RiskGuardDominance
        | PaperGovernanceVoiceConcentrationSignal::SingleMemberDominance => {
            GovernancePolicyFeedbackKindV2::ReduceRiskGuardCap
        }
        PaperGovernanceVoiceConcentrationSignal::TrendEntrySuppression => {
            GovernancePolicyFeedbackKindV2::ProtectTrendEntryFloor
        }
        PaperGovernanceVoiceConcentrationSignal::EvidenceRegimeUnderweight => {
            GovernancePolicyFeedbackKindV2::IncreaseEvidenceRegimeFloor
        }
        PaperGovernanceVoiceConcentrationSignal::HealthyDistribution => {
            GovernancePolicyFeedbackKindV2::ContinuePaperTrial
        }
        PaperGovernanceVoiceConcentrationSignal::InsufficientHistory => {
            GovernancePolicyFeedbackKindV2::NeedsMoreHistory
        }
    }
}

fn governance_feedback_kind_from_owner_feedback(
    feedback: &OwnerFeedback,
) -> GovernancePolicyFeedbackKindV2 {
    match feedback.feedback_type {
        OwnerFeedbackType::RiskConcern | OwnerFeedbackType::Disagree => {
            GovernancePolicyFeedbackKindV2::TightenRiskFirstPolicy
        }
        OwnerFeedbackType::EvidenceRequest => GovernancePolicyFeedbackKindV2::NeedsMoreEvidence,
        OwnerFeedbackType::ReconsiderationRequest => {
            GovernancePolicyFeedbackKindV2::BlockActualGovernance
        }
        OwnerFeedbackType::WatchlistRequest | OwnerFeedbackType::PaperOutcomeLabel => {
            GovernancePolicyFeedbackKindV2::ContinuePaperTrial
        }
        OwnerFeedbackType::Comment => GovernancePolicyFeedbackKindV2::AddEvidenceRequirement,
    }
}

pub fn ingest_governance_policy_feedback(
    multi_cycle_result: &PaperGovernanceTrialMultiCycleResult,
    owner_feedback: Option<&[OwnerFeedback]>,
) -> GovernancePolicyFeedbackIngestionResult {
    let mut records = Vec::new();
    let mut by_kind = BTreeMap::new();
    let mut by_source = BTreeMap::new();
    for record in &multi_cycle_result.risk_regression_watchdog.records {
        let feedback_kind = governance_feedback_kind_from_risk_signal(record.signal);
        records.push(GovernancePolicyFeedbackRecordV2 {
            feedback_id: format!("risk-{}", record.record_id),
            source: GovernancePolicyFeedbackSource::RiskRegressionWatchdog,
            feedback_kind,
            severity: record.severity,
            member_id: None,
            role: None,
            reason: record.reason.clone(),
            paper_only: true,
        });
        increment_btree_counter(&mut by_kind, governance_feedback_kind_label(feedback_kind));
        increment_btree_counter(
            &mut by_source,
            governance_feedback_source_label(
                GovernancePolicyFeedbackSource::RiskRegressionWatchdog,
            ),
        );
    }
    for record in &multi_cycle_result.voice_concentration_watchdog.records {
        let feedback_kind = governance_feedback_kind_from_voice_signal(record.signal);
        records.push(GovernancePolicyFeedbackRecordV2 {
            feedback_id: format!("voice-{}", record.record_id),
            source: GovernancePolicyFeedbackSource::VoiceConcentrationWatchdog,
            feedback_kind,
            severity: record.severity,
            member_id: record.member_id.clone(),
            role: record.role,
            reason: format!("voice watchdog flagged {:?}", record.signal),
            paper_only: true,
        });
        increment_btree_counter(&mut by_kind, governance_feedback_kind_label(feedback_kind));
        increment_btree_counter(
            &mut by_source,
            governance_feedback_source_label(
                GovernancePolicyFeedbackSource::VoiceConcentrationWatchdog,
            ),
        );
    }
    for blocker in &multi_cycle_result.aggregate_continuation_gate.blockers {
        let feedback_kind = GovernancePolicyFeedbackKindV2::BlockActualGovernance;
        records.push(GovernancePolicyFeedbackRecordV2 {
            feedback_id: format!("gate-blocker-{}", records.len() + 1),
            source: GovernancePolicyFeedbackSource::MultiCycleContinuationGate,
            feedback_kind,
            severity: PaperGovernanceAlertSeverity::High,
            member_id: None,
            role: None,
            reason: blocker.clone(),
            paper_only: true,
        });
        increment_btree_counter(&mut by_kind, governance_feedback_kind_label(feedback_kind));
        increment_btree_counter(
            &mut by_source,
            governance_feedback_source_label(
                GovernancePolicyFeedbackSource::MultiCycleContinuationGate,
            ),
        );
    }
    for warning in &multi_cycle_result.aggregate_continuation_gate.warnings {
        let feedback_kind = if multi_cycle_result.completed_cycle_count < 2 {
            GovernancePolicyFeedbackKindV2::NeedsMoreHistory
        } else {
            GovernancePolicyFeedbackKindV2::ContinuePaperTrial
        };
        records.push(GovernancePolicyFeedbackRecordV2 {
            feedback_id: format!("gate-warning-{}", records.len() + 1),
            source: GovernancePolicyFeedbackSource::MultiCycleContinuationGate,
            feedback_kind,
            severity: PaperGovernanceAlertSeverity::Low,
            member_id: None,
            role: None,
            reason: warning.clone(),
            paper_only: true,
        });
        increment_btree_counter(&mut by_kind, governance_feedback_kind_label(feedback_kind));
        increment_btree_counter(
            &mut by_source,
            governance_feedback_source_label(
                GovernancePolicyFeedbackSource::MultiCycleContinuationGate,
            ),
        );
    }
    if multi_cycle_result
        .aggregate_effectiveness_metrics
        .no_trade_bias_rate
        > 0.60
    {
        let feedback_kind = GovernancePolicyFeedbackKindV2::AddNoTradeBiasCap;
        records.push(GovernancePolicyFeedbackRecordV2 {
            feedback_id: format!("metrics-no-trade-{}", records.len() + 1),
            source: GovernancePolicyFeedbackSource::EffectivenessMetrics,
            feedback_kind,
            severity: PaperGovernanceAlertSeverity::Medium,
            member_id: None,
            role: None,
            reason: "effectiveness metrics show excessive no-trade bias".to_string(),
            paper_only: true,
        });
        increment_btree_counter(&mut by_kind, governance_feedback_kind_label(feedback_kind));
        increment_btree_counter(
            &mut by_source,
            governance_feedback_source_label(GovernancePolicyFeedbackSource::EffectivenessMetrics),
        );
    }
    if multi_cycle_result
        .aggregate_effectiveness_metrics
        .evidence_regime_underweight_score
        > 0.08
    {
        let feedback_kind = GovernancePolicyFeedbackKindV2::IncreaseEvidenceRegimeFloor;
        records.push(GovernancePolicyFeedbackRecordV2 {
            feedback_id: format!("metrics-evidence-{}", records.len() + 1),
            source: GovernancePolicyFeedbackSource::EffectivenessMetrics,
            feedback_kind,
            severity: PaperGovernanceAlertSeverity::Medium,
            member_id: None,
            role: Some(PaperGovernanceTrialMemberRole::EvidenceRegime),
            reason: "effectiveness metrics show evidence regime underweight".to_string(),
            paper_only: true,
        });
        increment_btree_counter(&mut by_kind, governance_feedback_kind_label(feedback_kind));
        increment_btree_counter(
            &mut by_source,
            governance_feedback_source_label(GovernancePolicyFeedbackSource::EffectivenessMetrics),
        );
    }
    if matches!(
        multi_cycle_result
            .aggregate_risk_first_check
            .risk_first_status,
        PaperGovernanceRiskFirstStatus::Violated
    ) {
        let feedback_kind = GovernancePolicyFeedbackKindV2::TightenRiskFirstPolicy;
        records.push(GovernancePolicyFeedbackRecordV2 {
            feedback_id: format!("risk-first-{}", records.len() + 1),
            source: GovernancePolicyFeedbackSource::RiskFirstCheck,
            feedback_kind,
            severity: PaperGovernanceAlertSeverity::High,
            member_id: None,
            role: None,
            reason: "risk-first preservation check failed during paper-only evaluation".to_string(),
            paper_only: true,
        });
        increment_btree_counter(&mut by_kind, governance_feedback_kind_label(feedback_kind));
        increment_btree_counter(
            &mut by_source,
            governance_feedback_source_label(GovernancePolicyFeedbackSource::RiskFirstCheck),
        );
    }
    if let Some(feedback) = owner_feedback {
        for item in feedback {
            let feedback_kind = governance_feedback_kind_from_owner_feedback(item);
            records.push(GovernancePolicyFeedbackRecordV2 {
                feedback_id: format!("owner-{}", item.feedback_id),
                source: GovernancePolicyFeedbackSource::OwnerFeedback,
                feedback_kind,
                severity: match item.priority {
                    OwnerFeedbackPriority::High => PaperGovernanceAlertSeverity::High,
                    OwnerFeedbackPriority::Normal => PaperGovernanceAlertSeverity::Medium,
                    OwnerFeedbackPriority::Low => PaperGovernanceAlertSeverity::Low,
                },
                member_id: item.target_member_id.clone(),
                role: None,
                reason: item.text.clone(),
                paper_only: true,
            });
            increment_btree_counter(&mut by_kind, governance_feedback_kind_label(feedback_kind));
            increment_btree_counter(
                &mut by_source,
                governance_feedback_source_label(GovernancePolicyFeedbackSource::OwnerFeedback),
            );
        }
    }
    let high_severity_count = records
        .iter()
        .filter(|record| record.severity == PaperGovernanceAlertSeverity::High)
        .count();
    let dominant_feedback =
        by_kind
            .iter()
            .max_by_key(|(_, count)| **count)
            .and_then(|(kind, _)| match kind.as_str() {
                "TightenRiskFirstPolicy" => {
                    Some(GovernancePolicyFeedbackKindV2::TightenRiskFirstPolicy)
                }
                "ReduceVoiceCap" => Some(GovernancePolicyFeedbackKindV2::ReduceVoiceCap),
                "AddNoTradeBiasCap" => Some(GovernancePolicyFeedbackKindV2::AddNoTradeBiasCap),
                "AddEvidenceRequirement" => {
                    Some(GovernancePolicyFeedbackKindV2::AddEvidenceRequirement)
                }
                "IncreaseEvidenceRegimeFloor" => {
                    Some(GovernancePolicyFeedbackKindV2::IncreaseEvidenceRegimeFloor)
                }
                "ReduceRiskGuardCap" => Some(GovernancePolicyFeedbackKindV2::ReduceRiskGuardCap),
                "ProtectTrendEntryFloor" => {
                    Some(GovernancePolicyFeedbackKindV2::ProtectTrendEntryFloor)
                }
                "ContinuePaperTrial" => Some(GovernancePolicyFeedbackKindV2::ContinuePaperTrial),
                "NeedsMoreHistory" => Some(GovernancePolicyFeedbackKindV2::NeedsMoreHistory),
                "NeedsMoreEvidence" => Some(GovernancePolicyFeedbackKindV2::NeedsMoreEvidence),
                "BlockActualGovernance" => {
                    Some(GovernancePolicyFeedbackKindV2::BlockActualGovernance)
                }
                _ => None,
            });
    let ingestion_status = if records.is_empty() {
        GovernancePolicyFeedbackIngestionStatus::NoFeedback
    } else if multi_cycle_result.safety_guard.guard_status
        == PaperGovernanceTrialSafetyGuardStatus::Violated
        || records.iter().any(|record| {
            record.feedback_kind == GovernancePolicyFeedbackKindV2::BlockActualGovernance
        })
    {
        GovernancePolicyFeedbackIngestionStatus::Unsafe
    } else if high_severity_count > 0
        || records.iter().any(|record| {
            matches!(
                record.feedback_kind,
                GovernancePolicyFeedbackKindV2::NeedsMoreHistory
                    | GovernancePolicyFeedbackKindV2::NeedsMoreEvidence
            )
        })
    {
        GovernancePolicyFeedbackIngestionStatus::IngestedWithWarnings
    } else {
        GovernancePolicyFeedbackIngestionStatus::Ingested
    };
    GovernancePolicyFeedbackIngestionResult {
        ingestion_id: format!(
            "{}-governance-feedback-ingestion",
            multi_cycle_result.run_id
        ),
        feedback_count: records.len(),
        high_severity_count,
        by_kind,
        by_source,
        dominant_feedback,
        ingestion_status,
        records,
        paper_only: true,
    }
}

fn governance_proposal_scenario(
    proposal: &GovernanceTuningProposalCandidate,
) -> GovernancePolicyABScenario {
    if proposal.actions.len() > 1 {
        GovernancePolicyABScenario::CompositeConservative
    } else if proposal
        .actions
        .contains(&GovernanceTuningProposalAction::CapRiskGuardShare)
    {
        GovernancePolicyABScenario::RiskGuardCapped
    } else if proposal
        .actions
        .contains(&GovernanceTuningProposalAction::RaiseTrendEntryFloor)
    {
        GovernancePolicyABScenario::TrendProtected
    } else if proposal
        .actions
        .contains(&GovernanceTuningProposalAction::RaiseEvidenceRegimeFloor)
    {
        GovernancePolicyABScenario::EvidenceRegimeProtected
    } else if proposal
        .actions
        .contains(&GovernanceTuningProposalAction::AddNoTradeBiasBrake)
    {
        GovernancePolicyABScenario::NoTradeBiasBraked
    } else if proposal
        .actions
        .contains(&GovernanceTuningProposalAction::ReduceVoiceDeltaCap)
    {
        GovernancePolicyABScenario::ConservativeVoiceCap
    } else {
        GovernancePolicyABScenario::BaselineCurrentPolicy
    }
}

fn governance_proposal_is_conservative(
    proposal: &GovernanceTuningProposalCandidate,
    current_policy: &ConservativeVoiceTuningV2Policy,
) -> bool {
    if proposal.actual_apply_allowed || !proposal.risk_first_preserved {
        return false;
    }
    if proposal
        .proposed_voice_delta_cap
        .is_some_and(|cap| cap > current_policy.tuned_voice_delta_cap_v2 + f64::EPSILON)
    {
        return false;
    }
    if proposal
        .proposed_risk_guard_max_share
        .is_some_and(|share| share > current_policy.risk_guard_max_voice_share + f64::EPSILON)
    {
        return false;
    }
    if proposal
        .proposed_trend_entry_min_share
        .is_some_and(|share| share + f64::EPSILON < current_policy.trend_entry_min_voice_share)
    {
        return false;
    }
    if proposal
        .proposed_evidence_regime_min_share
        .is_some_and(|share| share + f64::EPSILON < current_policy.evidence_regime_min_voice_share)
    {
        return false;
    }
    true
}

fn governance_proposal_from_feedback_record(
    record: &GovernancePolicyFeedbackRecordV2,
    current_policy: &ConservativeVoiceTuningV2Policy,
) -> GovernanceTuningProposalCandidate {
    let mut actions = Vec::new();
    let mut proposed_score_delta_cap = None;
    let mut proposed_voice_delta_cap = None;
    let mut proposed_risk_guard_max_share = None;
    let mut proposed_trend_entry_min_share = None;
    let mut proposed_evidence_regime_min_share = None;
    let mut proposed_no_trade_bias_cap = None;
    let mut proposed_min_evidence_confidence = SourceConfidence::Medium;
    match record.feedback_kind {
        GovernancePolicyFeedbackKindV2::TightenRiskFirstPolicy => {
            actions.push(GovernanceTuningProposalAction::ReduceScoreDeltaCap);
            actions.push(GovernanceTuningProposalAction::IncreaseRiskDissentRewardOnlyWhenVerified);
            proposed_score_delta_cap = Some(current_policy.tuned_voice_delta_cap_v2 * 0.80);
        }
        GovernancePolicyFeedbackKindV2::ReduceVoiceCap => {
            actions.push(GovernanceTuningProposalAction::ReduceVoiceDeltaCap);
            proposed_voice_delta_cap = Some(current_policy.tuned_voice_delta_cap_v2 * 0.85);
        }
        GovernancePolicyFeedbackKindV2::AddNoTradeBiasCap => {
            actions.push(GovernanceTuningProposalAction::AddNoTradeBiasBrake);
            proposed_no_trade_bias_cap = Some(0.60);
        }
        GovernancePolicyFeedbackKindV2::AddEvidenceRequirement => {
            actions.push(GovernanceTuningProposalAction::AddEvidenceRequirement);
            actions.push(GovernanceTuningProposalAction::ReduceLowConfidenceDelta);
            proposed_min_evidence_confidence = SourceConfidence::High;
        }
        GovernancePolicyFeedbackKindV2::IncreaseEvidenceRegimeFloor => {
            actions.push(GovernanceTuningProposalAction::RaiseEvidenceRegimeFloor);
            proposed_evidence_regime_min_share =
                Some((current_policy.evidence_regime_min_voice_share + 0.03).min(0.35));
            proposed_min_evidence_confidence = SourceConfidence::High;
        }
        GovernancePolicyFeedbackKindV2::ReduceRiskGuardCap => {
            actions.push(GovernanceTuningProposalAction::CapRiskGuardShare);
            proposed_risk_guard_max_share =
                Some((current_policy.risk_guard_max_voice_share * 0.90).max(0.40));
        }
        GovernancePolicyFeedbackKindV2::ProtectTrendEntryFloor => {
            actions.push(GovernanceTuningProposalAction::RaiseTrendEntryFloor);
            proposed_trend_entry_min_share =
                Some((current_policy.trend_entry_min_voice_share + 0.03).min(0.35));
        }
        GovernancePolicyFeedbackKindV2::ContinuePaperTrial => {
            actions.push(GovernanceTuningProposalAction::KeepPolicyUnchanged);
        }
        GovernancePolicyFeedbackKindV2::NeedsMoreHistory
        | GovernancePolicyFeedbackKindV2::NeedsMoreEvidence => {
            actions.push(GovernanceTuningProposalAction::NeedsMoreHistory);
            proposed_min_evidence_confidence = SourceConfidence::ReviewRequired;
        }
        GovernancePolicyFeedbackKindV2::BlockActualGovernance => {
            actions.push(GovernanceTuningProposalAction::KeepPolicyUnchanged);
            proposed_min_evidence_confidence = SourceConfidence::ReviewRequired;
        }
    }
    if record.reason.to_ascii_lowercase().contains("increase cap")
        || record.reason.to_ascii_lowercase().contains("raise cap")
    {
        proposed_voice_delta_cap = Some(current_policy.tuned_voice_delta_cap_v2 * 1.10);
    }
    let mut proposal = GovernanceTuningProposalCandidate {
        proposal_id: format!(
            "governance-proposal-{}-{}",
            governance_feedback_kind_label(record.feedback_kind).to_ascii_lowercase(),
            record
                .role
                .map(|role| format!("{role:?}").to_ascii_lowercase())
                .unwrap_or_else(|| "global".to_string())
        ),
        source_feedback_ids: vec![record.feedback_id.clone()],
        actions,
        target_role: record.role,
        proposed_score_delta_cap,
        proposed_voice_delta_cap,
        proposed_risk_guard_max_share,
        proposed_trend_entry_min_share,
        proposed_evidence_regime_min_share,
        proposed_no_trade_bias_cap,
        proposed_min_evidence_confidence,
        conservative: true,
        risk_first_preserved: current_policy.preserve_risk_first,
        actual_apply_allowed: false,
        paper_only: true,
    };
    proposal.conservative = governance_proposal_is_conservative(&proposal, current_policy)
        && proposal.paper_only
        && !matches!(
            record.feedback_kind,
            GovernancePolicyFeedbackKindV2::BlockActualGovernance
        );
    proposal
}

pub fn generate_governance_tuning_proposals(
    feedback_ingestion: &GovernancePolicyFeedbackIngestionResult,
    current_policy: &ConservativeVoiceTuningV2Policy,
) -> GovernanceTuningProposalGenerationResult {
    let mut candidates = Vec::new();
    let mut rejected_candidate_count = 0usize;
    for record in &feedback_ingestion.records {
        let proposal = governance_proposal_from_feedback_record(record, current_policy);
        if proposal.conservative {
            candidates.push(proposal);
        } else {
            rejected_candidate_count += 1;
        }
    }
    if candidates.is_empty() && feedback_ingestion.feedback_count == 0 {
        candidates.push(GovernanceTuningProposalCandidate {
            proposal_id: "governance-proposal-keep-unchanged".to_string(),
            source_feedback_ids: Vec::new(),
            actions: vec![GovernanceTuningProposalAction::KeepPolicyUnchanged],
            target_role: None,
            proposed_score_delta_cap: None,
            proposed_voice_delta_cap: None,
            proposed_risk_guard_max_share: None,
            proposed_trend_entry_min_share: None,
            proposed_evidence_regime_min_share: None,
            proposed_no_trade_bias_cap: None,
            proposed_min_evidence_confidence: SourceConfidence::ReviewRequired,
            conservative: true,
            risk_first_preserved: current_policy.preserve_risk_first,
            actual_apply_allowed: false,
            paper_only: true,
        });
    }
    candidates.sort_by(|left, right| left.proposal_id.cmp(&right.proposal_id));
    candidates.dedup_by(|left, right| left.proposal_id == right.proposal_id);
    let conservative_candidate_count = candidates
        .iter()
        .filter(|candidate| candidate.conservative)
        .count();
    let generation_status = if candidates.is_empty() {
        GovernanceTuningProposalGenerationStatus::NoCandidates
    } else if rejected_candidate_count > 0
        || feedback_ingestion.ingestion_status == GovernancePolicyFeedbackIngestionStatus::Unsafe
    {
        GovernanceTuningProposalGenerationStatus::GeneratedWithWarnings
    } else {
        GovernanceTuningProposalGenerationStatus::Generated
    };
    GovernanceTuningProposalGenerationResult {
        generation_id: format!(
            "{}-governance-proposal-generation",
            current_policy.policy_id
        ),
        candidate_count: candidates.len(),
        conservative_candidate_count,
        rejected_candidate_count,
        candidates,
        generation_status,
        paper_only: true,
    }
}

fn default_governance_tuning_proposal_ledger() -> GovernanceTuningProposalLedger {
    GovernanceTuningProposalLedger {
        ledger_id: "governance-tuning-proposal-ledger".to_string(),
        entries: Vec::new(),
        entry_count: 0,
        latest_entry_id: None,
        paper_only: true,
    }
}

pub fn normalize_governance_tuning_proposal_ledger(ledger: &mut GovernanceTuningProposalLedger) {
    ledger
        .entries
        .sort_by(|left, right| left.entry_id.cmp(&right.entry_id));
    ledger
        .entries
        .dedup_by(|left, right| left.proposal_id == right.proposal_id);
    ledger.entry_count = ledger.entries.len();
    ledger.latest_entry_id = ledger.entries.last().map(|entry| entry.entry_id.clone());
}

pub fn append_governance_tuning_proposal_entries(
    ledger: &mut GovernanceTuningProposalLedger,
    entries: Vec<GovernanceTuningProposalLedgerEntry>,
) -> Result<(), String> {
    ledger.entries.extend(entries);
    normalize_governance_tuning_proposal_ledger(ledger);
    Ok(())
}

pub fn load_governance_tuning_proposal_ledger_from_local_json(
    path: &Path,
) -> Result<GovernanceTuningProposalLedger, String> {
    validate_local_json_path(path, "governance tuning proposal ledger path")?;
    let text = std::fs::read_to_string(path)
        .map_err(|err| format!("failed to read governance tuning proposal ledger: {err}"))?;
    let mut ledger: GovernanceTuningProposalLedger = serde_json::from_str(&text)
        .map_err(|err| format!("failed to parse governance tuning proposal ledger: {err}"))?;
    normalize_governance_tuning_proposal_ledger(&mut ledger);
    Ok(ledger)
}

pub fn save_governance_tuning_proposal_ledger_to_local_json(
    path: &Path,
    ledger: &GovernanceTuningProposalLedger,
) -> Result<(), String> {
    validate_local_json_path(path, "governance tuning proposal ledger path")?;
    write_safe_json(path, ledger)
}

fn governance_risk_status_score(status: PaperGovernanceRiskRegressionWatchdogStatus) -> i32 {
    match status {
        PaperGovernanceRiskRegressionWatchdogStatus::Clear => 3,
        PaperGovernanceRiskRegressionWatchdogStatus::ClearWithWarnings => 2,
        PaperGovernanceRiskRegressionWatchdogStatus::InsufficientHistory => 1,
        PaperGovernanceRiskRegressionWatchdogStatus::RegressionDetected => 0,
    }
}

fn governance_voice_status_score(status: PaperGovernanceVoiceConcentrationWatchdogStatus) -> i32 {
    match status {
        PaperGovernanceVoiceConcentrationWatchdogStatus::Healthy => 3,
        PaperGovernanceVoiceConcentrationWatchdogStatus::HealthyWithWarnings => 2,
        PaperGovernanceVoiceConcentrationWatchdogStatus::InsufficientHistory => 1,
        PaperGovernanceVoiceConcentrationWatchdogStatus::Concentrated => 0,
    }
}

fn projected_risk_status(
    cycle_count: usize,
    worsening_rate: f64,
    no_trade_bias_rate: f64,
) -> PaperGovernanceRiskRegressionWatchdogStatus {
    if cycle_count < 2 {
        PaperGovernanceRiskRegressionWatchdogStatus::InsufficientHistory
    } else if worsening_rate > 0.0 {
        PaperGovernanceRiskRegressionWatchdogStatus::RegressionDetected
    } else if no_trade_bias_rate > 0.60 {
        PaperGovernanceRiskRegressionWatchdogStatus::ClearWithWarnings
    } else {
        PaperGovernanceRiskRegressionWatchdogStatus::Clear
    }
}

fn projected_voice_status(
    cycle_count: usize,
    voice_concentration_index: f64,
) -> PaperGovernanceVoiceConcentrationWatchdogStatus {
    if cycle_count < 2 {
        PaperGovernanceVoiceConcentrationWatchdogStatus::InsufficientHistory
    } else if voice_concentration_index > 0.65 {
        PaperGovernanceVoiceConcentrationWatchdogStatus::Concentrated
    } else if voice_concentration_index > 0.50 {
        PaperGovernanceVoiceConcentrationWatchdogStatus::HealthyWithWarnings
    } else {
        PaperGovernanceVoiceConcentrationWatchdogStatus::Healthy
    }
}

pub fn compare_governance_tuning_proposals_ab(
    proposals: &[GovernanceTuningProposalCandidate],
    baseline_policy: &ConservativeVoiceTuningV2Policy,
    paper_trial_multi_cycle_result: &PaperGovernanceTrialMultiCycleResult,
) -> GovernancePolicyABComparisonResult {
    let baseline_risk_regression_status = paper_trial_multi_cycle_result
        .risk_regression_watchdog
        .watchdog_status;
    let baseline_voice_concentration_status = paper_trial_multi_cycle_result
        .voice_concentration_watchdog
        .watchdog_status;
    let baseline_no_trade_bias_rate = paper_trial_multi_cycle_result
        .aggregate_effectiveness_metrics
        .no_trade_bias_rate;
    let baseline_risk_alignment_worsening_rate = paper_trial_multi_cycle_result
        .aggregate_effectiveness_metrics
        .risk_alignment_worsening_rate;
    let baseline_voice_concentration_index = paper_trial_multi_cycle_result
        .aggregate_effectiveness_metrics
        .voice_concentration_index;
    let mut records = Vec::new();
    for proposal in proposals {
        let mut proposal_no_trade_bias_rate = baseline_no_trade_bias_rate;
        let mut proposal_risk_alignment_worsening_rate = baseline_risk_alignment_worsening_rate;
        let mut proposal_voice_concentration_index = baseline_voice_concentration_index;
        for action in &proposal.actions {
            match action {
                GovernanceTuningProposalAction::ReduceVoiceDeltaCap => {
                    proposal_voice_concentration_index =
                        (proposal_voice_concentration_index - 0.08).max(0.0);
                    proposal_risk_alignment_worsening_rate =
                        (proposal_risk_alignment_worsening_rate - 0.04).max(0.0);
                }
                GovernanceTuningProposalAction::ReduceScoreDeltaCap => {
                    proposal_risk_alignment_worsening_rate =
                        (proposal_risk_alignment_worsening_rate - 0.03).max(0.0);
                }
                GovernanceTuningProposalAction::CapRiskGuardShare => {
                    proposal_voice_concentration_index =
                        (proposal_voice_concentration_index - 0.12).max(0.0);
                    proposal_risk_alignment_worsening_rate =
                        (proposal_risk_alignment_worsening_rate - 0.02).max(0.0);
                }
                GovernanceTuningProposalAction::RaiseTrendEntryFloor => {
                    proposal_voice_concentration_index =
                        (proposal_voice_concentration_index - 0.06).max(0.0);
                    proposal_risk_alignment_worsening_rate =
                        (proposal_risk_alignment_worsening_rate - 0.02).max(0.0);
                }
                GovernanceTuningProposalAction::RaiseEvidenceRegimeFloor => {
                    proposal_voice_concentration_index =
                        (proposal_voice_concentration_index - 0.05).max(0.0);
                    proposal_risk_alignment_worsening_rate =
                        (proposal_risk_alignment_worsening_rate - 0.03).max(0.0);
                }
                GovernanceTuningProposalAction::AddNoTradeBiasBrake => {
                    proposal_no_trade_bias_rate = (proposal_no_trade_bias_rate - 0.18).max(0.0);
                }
                GovernanceTuningProposalAction::AddEvidenceRequirement => {
                    proposal_risk_alignment_worsening_rate =
                        (proposal_risk_alignment_worsening_rate - 0.04).max(0.0);
                    proposal_no_trade_bias_rate = (proposal_no_trade_bias_rate + 0.05).min(1.0);
                }
                GovernanceTuningProposalAction::ReduceLowConfidenceDelta => {
                    proposal_risk_alignment_worsening_rate =
                        (proposal_risk_alignment_worsening_rate - 0.02).max(0.0);
                    proposal_no_trade_bias_rate = (proposal_no_trade_bias_rate + 0.02).min(1.0);
                }
                GovernanceTuningProposalAction::IncreaseRiskDissentRewardOnlyWhenVerified => {
                    proposal_risk_alignment_worsening_rate =
                        (proposal_risk_alignment_worsening_rate - 0.03).max(0.0);
                }
                GovernanceTuningProposalAction::KeepPolicyUnchanged
                | GovernanceTuningProposalAction::NeedsMoreHistory => {}
            }
        }
        if let Some(cap) = proposal.proposed_risk_guard_max_share {
            if cap < baseline_policy.risk_guard_max_voice_share {
                proposal_voice_concentration_index =
                    (proposal_voice_concentration_index - 0.05).max(0.0);
            }
        }
        let proposal_is_unsafe_for_ab = !proposal.conservative
            || !proposal.risk_first_preserved
            || proposal
                .proposed_voice_delta_cap
                .is_some_and(|cap| cap > baseline_policy.tuned_voice_delta_cap_v2 + f64::EPSILON)
            || proposal.proposed_risk_guard_max_share.is_some_and(|share| {
                share > baseline_policy.risk_guard_max_voice_share + f64::EPSILON
            });
        if proposal_is_unsafe_for_ab {
            proposal_risk_alignment_worsening_rate =
                (proposal_risk_alignment_worsening_rate + 0.05).min(1.0);
            proposal_voice_concentration_index =
                (proposal_voice_concentration_index + 0.05).min(1.0);
        }
        let proposal_risk_regression_status = projected_risk_status(
            paper_trial_multi_cycle_result.completed_cycle_count,
            proposal_risk_alignment_worsening_rate,
            proposal_no_trade_bias_rate,
        );
        let proposal_voice_concentration_status = projected_voice_status(
            paper_trial_multi_cycle_result.completed_cycle_count,
            proposal_voice_concentration_index,
        );
        let worsened = proposal_is_unsafe_for_ab
            || governance_risk_status_score(proposal_risk_regression_status)
                < governance_risk_status_score(baseline_risk_regression_status)
            || governance_voice_status_score(proposal_voice_concentration_status)
                < governance_voice_status_score(baseline_voice_concentration_status)
            || proposal_risk_alignment_worsening_rate
                > baseline_risk_alignment_worsening_rate + 0.01
            || proposal_voice_concentration_index > baseline_voice_concentration_index + 0.01
            || proposal_no_trade_bias_rate > baseline_no_trade_bias_rate + 0.05;
        let improved = !worsened
            && (governance_risk_status_score(proposal_risk_regression_status)
                > governance_risk_status_score(baseline_risk_regression_status)
                || governance_voice_status_score(proposal_voice_concentration_status)
                    > governance_voice_status_score(baseline_voice_concentration_status)
                || proposal_risk_alignment_worsening_rate
                    < baseline_risk_alignment_worsening_rate - 0.01
                || proposal_voice_concentration_index < baseline_voice_concentration_index - 0.01
                || proposal_no_trade_bias_rate < baseline_no_trade_bias_rate - 0.05);
        records.push(GovernancePolicyABComparisonRecord {
            record_id: format!(
                "{}-ab-{}",
                paper_trial_multi_cycle_result.run_id, proposal.proposal_id
            ),
            proposal_id: proposal.proposal_id.clone(),
            scenario: governance_proposal_scenario(proposal),
            baseline_risk_regression_status,
            proposal_risk_regression_status,
            baseline_voice_concentration_status,
            proposal_voice_concentration_status,
            baseline_no_trade_bias_rate,
            proposal_no_trade_bias_rate,
            baseline_risk_alignment_worsening_rate,
            proposal_risk_alignment_worsening_rate,
            baseline_voice_concentration_index,
            proposal_voice_concentration_index,
            improved,
            worsened,
            paper_only: true,
        });
    }
    records.sort_by(|left, right| left.proposal_id.cmp(&right.proposal_id));
    let improved_count = records.iter().filter(|record| record.improved).count();
    let worsened_count = records.iter().filter(|record| record.worsened).count();
    let neutral_count = records
        .len()
        .saturating_sub(improved_count + worsened_count);
    let best_proposal_id = records
        .iter()
        .filter(|record| record.improved && !record.worsened)
        .min_by(|left, right| {
            left.proposal_risk_alignment_worsening_rate
                .partial_cmp(&right.proposal_risk_alignment_worsening_rate)
                .unwrap_or(std::cmp::Ordering::Equal)
                .then_with(|| {
                    left.proposal_voice_concentration_index
                        .partial_cmp(&right.proposal_voice_concentration_index)
                        .unwrap_or(std::cmp::Ordering::Equal)
                })
        })
        .map(|record| record.proposal_id.clone());
    let comparison_status = if records.is_empty() {
        GovernancePolicyABComparisonStatus::Failed
    } else if improved_count == 0 {
        GovernancePolicyABComparisonStatus::NoImprovement
    } else if worsened_count > 0 {
        GovernancePolicyABComparisonStatus::ComparedWithWarnings
    } else {
        GovernancePolicyABComparisonStatus::Compared
    };
    GovernancePolicyABComparisonResult {
        comparison_id: format!(
            "{}-governance-policy-ab",
            paper_trial_multi_cycle_result.run_id
        ),
        baseline_policy_id: baseline_policy.policy_id.clone(),
        proposal_count: proposals.len(),
        record_count: records.len(),
        improved_count,
        worsened_count,
        neutral_count,
        best_proposal_id,
        comparison_status,
        records,
        paper_only: true,
    }
}

pub fn rank_governance_tuning_proposals(
    ab_result: &GovernancePolicyABComparisonResult,
    feedback_ingestion: &GovernancePolicyFeedbackIngestionResult,
) -> GovernanceTuningProposalRankingResult {
    let mut ranked_proposals = ab_result
        .records
        .iter()
        .map(|record| {
            let safety_score = if record.worsened { 0.0 } else { 1.0 };
            let risk_first_score = (record.baseline_risk_alignment_worsening_rate
                - record.proposal_risk_alignment_worsening_rate)
                * 100.0;
            let concentration_score = (record.baseline_voice_concentration_index
                - record.proposal_voice_concentration_index)
                * 100.0;
            let no_trade_bias_score =
                (record.baseline_no_trade_bias_rate - record.proposal_no_trade_bias_rate) * 100.0;
            let evidence_balance_score = match record.scenario {
                GovernancePolicyABScenario::EvidenceRegimeProtected => 12.0,
                GovernancePolicyABScenario::CompositeConservative => 8.0,
                _ => 0.0,
            };
            let role_balance_score = match record.scenario {
                GovernancePolicyABScenario::RiskGuardCapped
                | GovernancePolicyABScenario::TrendProtected
                | GovernancePolicyABScenario::EvidenceRegimeProtected
                | GovernancePolicyABScenario::CompositeConservative => 10.0,
                _ => 0.0,
            };
            let total_score = safety_score * 30.0
                + risk_first_score * 1.5
                + concentration_score
                + no_trade_bias_score * 0.8
                + evidence_balance_score
                + role_balance_score;
            let rank_status = if record.worsened || total_score < 0.0 {
                GovernanceTuningProposalRankStatus::Rejected
            } else if !record.improved
                && matches!(
                    feedback_ingestion.dominant_feedback,
                    Some(
                        GovernancePolicyFeedbackKindV2::NeedsMoreHistory
                            | GovernancePolicyFeedbackKindV2::NeedsMoreEvidence
                    )
                )
            {
                GovernanceTuningProposalRankStatus::NeedsMoreEvidence
            } else if record.improved {
                GovernanceTuningProposalRankStatus::Acceptable
            } else {
                GovernanceTuningProposalRankStatus::NeedsMoreEvidence
            };
            GovernanceTuningProposalRank {
                proposal_id: record.proposal_id.clone(),
                safety_score,
                risk_first_score,
                concentration_score,
                no_trade_bias_score,
                evidence_balance_score,
                role_balance_score,
                total_score,
                rank: 0,
                rank_status,
                reason: if record.worsened {
                    "proposal worsened paper-only A/B comparison".to_string()
                } else if record.improved {
                    "proposal improved paper-only A/B comparison".to_string()
                } else {
                    "proposal needs more evidence before recommendation".to_string()
                },
                paper_only: true,
            }
        })
        .collect::<Vec<_>>();
    ranked_proposals.sort_by(|left, right| {
        right
            .total_score
            .partial_cmp(&left.total_score)
            .unwrap_or(std::cmp::Ordering::Equal)
            .then_with(|| left.proposal_id.cmp(&right.proposal_id))
    });
    for (index, rank) in ranked_proposals.iter_mut().enumerate() {
        rank.rank = index + 1;
    }
    if let Some(best) = ranked_proposals.first_mut() {
        if best.rank_status == GovernanceTuningProposalRankStatus::Acceptable
            && best.total_score > 0.0
        {
            best.rank_status = GovernanceTuningProposalRankStatus::Recommended;
        }
    }
    let recommended_proposal_id = ranked_proposals
        .iter()
        .find(|rank| rank.rank_status == GovernanceTuningProposalRankStatus::Recommended)
        .map(|rank| rank.proposal_id.clone());
    let rejected_count = ranked_proposals
        .iter()
        .filter(|rank| rank.rank_status == GovernanceTuningProposalRankStatus::Rejected)
        .count();
    let needs_more_evidence_count = ranked_proposals
        .iter()
        .filter(|rank| rank.rank_status == GovernanceTuningProposalRankStatus::NeedsMoreEvidence)
        .count();
    let ranking_status = if recommended_proposal_id.is_some() && rejected_count == 0 {
        GovernanceTuningProposalRankingStatus::RecommendationAvailable
    } else if recommended_proposal_id.is_some() {
        GovernanceTuningProposalRankingStatus::RecommendationWithWarnings
    } else if needs_more_evidence_count > 0
        || feedback_ingestion.ingestion_status
            == GovernancePolicyFeedbackIngestionStatus::NoFeedback
    {
        GovernanceTuningProposalRankingStatus::InsufficientEvidence
    } else {
        GovernanceTuningProposalRankingStatus::NoSafeRecommendation
    };
    GovernanceTuningProposalRankingResult {
        ranking_id: format!("{}-governance-proposal-ranking", ab_result.comparison_id),
        ranked_proposals,
        recommended_proposal_id,
        rejected_count,
        needs_more_evidence_count,
        ranking_status,
        paper_only: true,
    }
}

fn default_governance_tuning_proposal_safety_guard(
    proposals: &[GovernanceTuningProposalCandidate],
    ab_result: &GovernancePolicyABComparisonResult,
    ranking_result: &GovernanceTuningProposalRankingResult,
    baseline_policy: Option<&ConservativeVoiceTuningV2Policy>,
) -> GovernanceTuningProposalSafetyGuard {
    let cap_increase_detected = proposals.iter().any(|proposal| {
        baseline_policy.is_some_and(|policy| {
            proposal
                .proposed_voice_delta_cap
                .is_some_and(|cap| cap > policy.tuned_voice_delta_cap_v2 + f64::EPSILON)
                || proposal
                    .proposed_risk_guard_max_share
                    .is_some_and(|share| share > policy.risk_guard_max_voice_share + f64::EPSILON)
        })
    });
    let risk_first_disabled_detected = proposals
        .iter()
        .any(|proposal| !proposal.risk_first_preserved);
    let unsafe_recommendation_detected = ranking_result
        .recommended_proposal_id
        .as_ref()
        .is_some_and(|proposal_id| {
            ranking_result
                .ranked_proposals
                .iter()
                .find(|rank| &rank.proposal_id == proposal_id)
                .is_none_or(|rank| {
                    rank.rank_status != GovernanceTuningProposalRankStatus::Recommended
                })
                || ab_result
                    .records
                    .iter()
                    .find(|record| &record.proposal_id == proposal_id)
                    .is_none_or(|record| record.worsened || !record.improved)
        });
    let mut violations = Vec::new();
    if cap_increase_detected {
        violations.push("governance tuning proposal increased a cap unsafely".to_string());
    }
    if risk_first_disabled_detected {
        violations.push("governance tuning proposal disabled risk-first preservation".to_string());
    }
    if unsafe_recommendation_detected {
        violations.push("governance tuning recommendation is unsafe".to_string());
    }
    GovernanceTuningProposalSafetyGuard {
        actual_score_mutation_detected: false,
        actual_voice_mutation_detected: false,
        policy_applied_to_actual_state_detected: false,
        committee_decision_mutation_detected: false,
        risk_governor_override_detected: false,
        trade_signal_detected: false,
        order_detected: false,
        broker_order_account_detected: false,
        cap_increase_detected,
        risk_first_disabled_detected,
        unsafe_recommendation_detected,
        guard_status: if violations.is_empty() {
            PaperGovernanceTrialSafetyGuardStatus::Preserved
        } else {
            PaperGovernanceTrialSafetyGuardStatus::Violated
        },
        violations,
        paper_only: true,
    }
}

pub fn evaluate_governance_tuning_proposal_safety(
    proposals: &[GovernanceTuningProposalCandidate],
    ab_result: &GovernancePolicyABComparisonResult,
    ranking_result: &GovernanceTuningProposalRankingResult,
    before_state: &BatchCommitteeCycleResult,
    after_state: Option<&BatchCommitteeCycleResult>,
) -> GovernanceTuningProposalSafetyGuard {
    let after_state = after_state.unwrap_or(before_state);
    let actual_score_snapshot = |store: Option<&PaperGovernanceTrialStateStore>| {
        store.map(|store| {
            store
                .member_states
                .iter()
                .map(|state| (state.member_id.clone(), state.actual_score_snapshot))
                .collect::<BTreeMap<_, _>>()
        })
    };
    let actual_voice_snapshot = |store: Option<&PaperGovernanceTrialStateStore>| {
        store.map(|store| {
            store
                .member_states
                .iter()
                .map(|state| (state.member_id.clone(), state.actual_voice_snapshot))
                .collect::<BTreeMap<_, _>>()
        })
    };
    let risk_snapshot = |decisions: &[ChairmanDecision]| {
        decisions
            .iter()
            .map(|decision| (decision.decision_id.clone(), decision.risk_governor_status))
            .collect::<BTreeMap<_, _>>()
    };
    let mut guard = default_governance_tuning_proposal_safety_guard(
        proposals,
        ab_result,
        ranking_result,
        before_state.conservative_voice_tuning_v2_policy.as_ref(),
    );
    guard.actual_score_mutation_detected =
        actual_score_snapshot(before_state.paper_governance_trial_state_store.as_ref())
            != actual_score_snapshot(after_state.paper_governance_trial_state_store.as_ref());
    guard.actual_voice_mutation_detected =
        actual_voice_snapshot(before_state.paper_governance_trial_state_store.as_ref())
            != actual_voice_snapshot(after_state.paper_governance_trial_state_store.as_ref());
    guard.policy_applied_to_actual_state_detected = before_state
        .conservative_voice_tuning_v2_policy
        != after_state.conservative_voice_tuning_v2_policy
        || before_state.chairman_role_voice_floor_policy
            != after_state.chairman_role_voice_floor_policy
        || proposals
            .iter()
            .any(|proposal| proposal.actual_apply_allowed);
    guard.committee_decision_mutation_detected = before_state.committee_sessions
        != after_state.committee_sessions
        || before_state.chairman_decisions != after_state.chairman_decisions;
    guard.risk_governor_override_detected = risk_snapshot(&before_state.chairman_decisions)
        != risk_snapshot(&after_state.chairman_decisions);
    guard.trade_signal_detected = value_contains_debug_marker(
        &after_state.committee_sessions,
        &["trade-signal".to_string()],
    ) && !value_contains_debug_marker(
        &before_state.committee_sessions,
        &["trade-signal".to_string()],
    );
    guard.order_detected =
        value_contains_debug_marker(&after_state.event_queue, &["order".to_string()])
            && !value_contains_debug_marker(&before_state.event_queue, &["order".to_string()]);
    guard.broker_order_account_detected = value_contains_debug_marker(
        after_state,
        &[
            "broker".to_string(),
            "order".to_string(),
            "account".to_string(),
        ],
    ) && !value_contains_debug_marker(
        before_state,
        &[
            "broker".to_string(),
            "order".to_string(),
            "account".to_string(),
        ],
    );
    if guard.actual_score_mutation_detected {
        guard
            .violations
            .push("governance tuning proposal mutated actual score".to_string());
    }
    if guard.actual_voice_mutation_detected {
        guard
            .violations
            .push("governance tuning proposal mutated actual voice".to_string());
    }
    if guard.policy_applied_to_actual_state_detected {
        guard
            .violations
            .push("governance tuning proposal was applied to actual policy state".to_string());
    }
    if guard.committee_decision_mutation_detected {
        guard
            .violations
            .push("governance tuning proposal mutated committee decision".to_string());
    }
    if guard.risk_governor_override_detected {
        guard
            .violations
            .push("governance tuning proposal overrode Risk Governor".to_string());
    }
    if guard.trade_signal_detected {
        guard
            .violations
            .push("governance tuning proposal created trade signal".to_string());
    }
    if guard.order_detected {
        guard
            .violations
            .push("governance tuning proposal created order".to_string());
    }
    if guard.broker_order_account_detected {
        guard
            .violations
            .push("governance tuning proposal touched broker/order/account".to_string());
    }
    guard.guard_status = if guard.violations.is_empty() {
        PaperGovernanceTrialSafetyGuardStatus::Preserved
    } else {
        PaperGovernanceTrialSafetyGuardStatus::Violated
    };
    guard
}

pub fn evaluate_governance_tuning_recommendation_gate(
    feedback: &GovernancePolicyFeedbackIngestionResult,
    proposals: &GovernanceTuningProposalGenerationResult,
    ab_result: &GovernancePolicyABComparisonResult,
    ranking: &GovernanceTuningProposalRankingResult,
    safety_guard: &GovernanceTuningProposalSafetyGuard,
) -> GovernanceTuningRecommendationGate {
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    if safety_guard.guard_status == PaperGovernanceTrialSafetyGuardStatus::Violated {
        blockers.push("governance tuning safety guard was violated".to_string());
    }
    if feedback.ingestion_status == GovernancePolicyFeedbackIngestionStatus::Unsafe {
        blockers.push("feedback ingestion marked governance policy state as unsafe".to_string());
    }
    if feedback
        .dominant_feedback
        .is_some_and(|kind| kind == GovernancePolicyFeedbackKindV2::NeedsMoreHistory)
    {
        warnings.push("governance tuning feedback still needs more paper history".to_string());
    }
    if matches!(
        ranking.ranking_status,
        GovernanceTuningProposalRankingStatus::RecommendationWithWarnings
            | GovernanceTuningProposalRankingStatus::InsufficientEvidence
    ) {
        warnings.push("proposal ranking emitted warnings".to_string());
    }
    let gate_status = if safety_guard.guard_status
        == PaperGovernanceTrialSafetyGuardStatus::Violated
    {
        GovernanceTuningRecommendationGateStatus::BlockedBySafety
    } else if feedback
        .dominant_feedback
        .is_some_and(|kind| kind == GovernancePolicyFeedbackKindV2::NeedsMoreHistory)
    {
        GovernanceTuningRecommendationGateStatus::NeedsMoreHistory
    } else if matches!(
        ranking.ranking_status,
        GovernanceTuningProposalRankingStatus::InsufficientEvidence
    ) {
        GovernanceTuningRecommendationGateStatus::NeedsMoreEvidence
    } else if let Some(recommended_proposal_id) = ranking.recommended_proposal_id.as_ref() {
        if ranking.ranking_status == GovernanceTuningProposalRankingStatus::RecommendationAvailable
        {
            GovernanceTuningRecommendationGateStatus::RecommendationReady
        } else if ranking.ranking_status
            == GovernanceTuningProposalRankingStatus::RecommendationWithWarnings
            && ab_result
                .best_proposal_id
                .as_ref()
                .is_some_and(|proposal_id| proposal_id == recommended_proposal_id)
        {
            GovernanceTuningRecommendationGateStatus::RecommendationReadyWithWarnings
        } else {
            GovernanceTuningRecommendationGateStatus::NoSafeRecommendation
        }
    } else {
        GovernanceTuningRecommendationGateStatus::NoSafeRecommendation
    };
    GovernanceTuningRecommendationGate {
        gate_id: format!("{}-governance-tuning-gate", ab_result.comparison_id),
        feedback_status: feedback.ingestion_status,
        proposal_generation_status: proposals.generation_status,
        ab_comparison_status: ab_result.comparison_status,
        ranking_status: ranking.ranking_status,
        safety_status: safety_guard.guard_status,
        recommended_proposal_id: ranking.recommended_proposal_id.clone(),
        recommendation_available: matches!(
            gate_status,
            GovernanceTuningRecommendationGateStatus::RecommendationReady
                | GovernanceTuningRecommendationGateStatus::RecommendationReadyWithWarnings
        ),
        gate_status,
        blockers,
        warnings,
        paper_only: true,
    }
}

pub fn build_owner_governance_policy_recommendation_summary(
    gate: &GovernanceTuningRecommendationGate,
    ranking: &GovernanceTuningProposalRankingResult,
    feedback: &GovernancePolicyFeedbackIngestionResult,
) -> OwnerGovernancePolicyRecommendationSummary {
    OwnerGovernancePolicyRecommendationSummary {
        summary_id: format!("{}-owner-governance-policy-summary", gate.gate_id),
        feedback_count: feedback.feedback_count,
        dominant_feedback: feedback.dominant_feedback,
        candidate_count: ranking.ranked_proposals.len(),
        proposal_candidate_count: ranking.ranked_proposals.len(),
        recommended_proposal_id: gate.recommended_proposal_id.clone(),
        recommendation_status: gate.gate_status,
        recommendation_gate_status: gate.gate_status,
        safety_guard_status: gate.safety_status,
        recommendation_reason: if gate.recommendation_available {
            "paper-only governance tuning recommendation is ready".to_string()
        } else {
            "paper-only governance tuning recommendation is still blocked or deferred".to_string()
        },
        message: "Policy feedback was converted into conservative tuning proposals. The recommendation is not applied yet. Actual score, voice, decisions, and trading remain unchanged."
            .to_string(),
        recommendation_only: true,
        no_actual_policy_apply: true,
        no_score_mutation: true,
        no_voice_mutation: true,
        no_committee_decision_change: true,
        not_trade_signal: true,
        paper_only: true,
    }
}

pub fn run_governance_policy_feedback_tuning(
    multi_cycle_result: &PaperGovernanceTrialMultiCycleResult,
    baseline_policy: &ConservativeVoiceTuningV2Policy,
    config: &GovernancePolicyFeedbackTuningRunConfig,
) -> Result<GovernancePolicyFeedbackTuningRunResult, String> {
    if !config.paper_only {
        return Err("governance policy feedback tuning run must stay paper_only".to_string());
    }
    for (path, label) in [
        (
            config.proposal_ledger_input_path.as_ref(),
            "governance tuning proposal ledger input path",
        ),
        (
            config.proposal_ledger_output_path.as_ref(),
            "governance tuning proposal ledger output path",
        ),
        (
            config.output_path.as_ref(),
            "governance policy feedback tuning output path",
        ),
    ] {
        if let Some(path) = path {
            validate_local_json_path(Path::new(path), label)?;
        }
    }
    if !config.dry_run
        && config.write_proposal_ledger
        && config.proposal_ledger_output_path.is_none()
    {
        return Err(
            "governance policy feedback tuning requires proposal_ledger_output_path when dry_run=false and write_proposal_ledger=true"
                .to_string(),
        );
    }
    let feedback_ingestion = ingest_governance_policy_feedback(multi_cycle_result, None);
    let proposal_generation =
        generate_governance_tuning_proposals(&feedback_ingestion, baseline_policy);
    let mut proposal_ledger = if let Some(path) = config.proposal_ledger_input_path.as_ref() {
        if Path::new(path).exists() {
            load_governance_tuning_proposal_ledger_from_local_json(Path::new(path))?
        } else {
            default_governance_tuning_proposal_ledger()
        }
    } else {
        default_governance_tuning_proposal_ledger()
    };
    append_governance_tuning_proposal_entries(
        &mut proposal_ledger,
        proposal_generation
            .candidates
            .iter()
            .map(|proposal| GovernanceTuningProposalLedgerEntry {
                entry_id: format!("{}-ledger-entry", proposal.proposal_id),
                proposal_id: proposal.proposal_id.clone(),
                source_feedback_count: proposal.source_feedback_ids.len(),
                actions: proposal.actions.clone(),
                conservative: proposal.conservative,
                risk_first_preserved: proposal.risk_first_preserved,
                evaluation_status: Some(
                    GovernanceTuningProposalLedgerEvaluationStatus::NotEvaluated,
                ),
                paper_only: true,
            })
            .collect(),
    )?;
    let ab_comparison = compare_governance_tuning_proposals_ab(
        &proposal_generation.candidates,
        baseline_policy,
        multi_cycle_result,
    );
    for entry in &mut proposal_ledger.entries {
        entry.evaluation_status = ab_comparison
            .records
            .iter()
            .find(|record| record.proposal_id == entry.proposal_id)
            .map(|record| {
                if record.worsened {
                    GovernanceTuningProposalLedgerEvaluationStatus::Rejected
                } else if record.improved {
                    GovernanceTuningProposalLedgerEvaluationStatus::Evaluated
                } else {
                    GovernanceTuningProposalLedgerEvaluationStatus::EvaluatedWithWarnings
                }
            });
    }
    normalize_governance_tuning_proposal_ledger(&mut proposal_ledger);
    let ranking = rank_governance_tuning_proposals(&ab_comparison, &feedback_ingestion);
    let safety_guard = default_governance_tuning_proposal_safety_guard(
        &proposal_generation.candidates,
        &ab_comparison,
        &ranking,
        Some(baseline_policy),
    );
    let recommendation_gate = evaluate_governance_tuning_recommendation_gate(
        &feedback_ingestion,
        &proposal_generation,
        &ab_comparison,
        &ranking,
        &safety_guard,
    );
    let owner_summary = config.emit_owner_summary.then(|| {
        build_owner_governance_policy_recommendation_summary(
            &recommendation_gate,
            &ranking,
            &feedback_ingestion,
        )
    });
    let mut result = GovernancePolicyFeedbackTuningRunResult {
        run_id: config.run_id.clone(),
        feedback_ingestion,
        proposal_generation,
        proposal_ledger,
        ab_comparison,
        ranking,
        recommendation_gate,
        safety_guard,
        owner_summary,
        run_status: PaperGovernanceTrialRunStatus::PassedWithWarnings,
        paper_only: true,
    };
    result.run_status = if result.safety_guard.guard_status
        == PaperGovernanceTrialSafetyGuardStatus::Violated
        || matches!(
            result.recommendation_gate.gate_status,
            GovernanceTuningRecommendationGateStatus::BlockedBySafety
                | GovernanceTuningRecommendationGateStatus::NoSafeRecommendation
        ) {
        PaperGovernanceTrialRunStatus::Failed
    } else if result.recommendation_gate.gate_status
        == GovernanceTuningRecommendationGateStatus::RecommendationReady
    {
        PaperGovernanceTrialRunStatus::Passed
    } else {
        PaperGovernanceTrialRunStatus::PassedWithWarnings
    };
    if !config.dry_run {
        if config.write_proposal_ledger {
            if let Some(path) = config.proposal_ledger_output_path.as_ref() {
                save_governance_tuning_proposal_ledger_to_local_json(
                    Path::new(path),
                    &result.proposal_ledger,
                )?;
            }
        }
        if let Some(path) = config.output_path.as_ref() {
            write_safe_json(Path::new(path), &result)?;
        }
    }
    Ok(result)
}

pub fn governance_policy_feedback_tuning_requested_from_flags(
    enabled: bool,
    dry_run: bool,
    write_proposal_ledger: bool,
    proposal_ledger_output_path: Option<&String>,
    output_path: Option<&String>,
    emit_owner_summary: bool,
) -> bool {
    enabled
        || !dry_run
        || proposal_ledger_output_path.is_some()
        || output_path.is_some()
        || (enabled && (write_proposal_ledger || emit_owner_summary))
}

fn current_conservative_voice_tuning_policy(
    batch_result: &BatchCommitteeCycleResult,
) -> Result<ConservativeVoiceTuningV2Policy, String> {
    batch_result
        .conservative_voice_tuning_v2_policy
        .clone()
        .or_else(|| {
            batch_result
                .conservative_voice_tuning_v2_run_result
                .as_ref()
                .map(|run| run.v2_result.voice_tuning_v2_policy.clone())
        })
        .ok_or_else(|| {
            "governance policy feedback tuning requires conservative voice tuning v2 policy"
                .to_string()
        })
}

fn maybe_run_governance_policy_feedback_tuning_for_batch_result(
    run_id: String,
    enabled: bool,
    dry_run: bool,
    write_proposal_ledger: bool,
    proposal_ledger_output_path: Option<&String>,
    output_path: Option<&String>,
    emit_owner_summary: bool,
    batch_result: &mut BatchCommitteeCycleResult,
) -> Result<Option<GovernancePolicyFeedbackTuningRunResult>, String> {
    if !governance_policy_feedback_tuning_requested_from_flags(
        enabled,
        dry_run,
        write_proposal_ledger,
        proposal_ledger_output_path,
        output_path,
        emit_owner_summary,
    ) {
        return Ok(None);
    }
    let multi_cycle_result = batch_result
        .paper_governance_trial_multi_cycle_result
        .clone()
        .ok_or_else(|| {
            "governance policy feedback tuning requires paper governance trial multicycle result"
                .to_string()
        })?;
    let baseline_policy = current_conservative_voice_tuning_policy(batch_result)?;
    let mut result = run_governance_policy_feedback_tuning(
        &multi_cycle_result,
        &baseline_policy,
        &GovernancePolicyFeedbackTuningRunConfig {
            run_id,
            enabled,
            proposal_ledger_input_path: proposal_ledger_output_path.cloned(),
            proposal_ledger_output_path: proposal_ledger_output_path.cloned(),
            output_path: output_path.cloned(),
            dry_run,
            write_proposal_ledger,
            emit_owner_summary,
            paper_only: true,
        },
    )?;
    result.safety_guard = evaluate_governance_tuning_proposal_safety(
        &result.proposal_generation.candidates,
        &result.ab_comparison,
        &result.ranking,
        batch_result,
        Some(batch_result),
    );
    result.recommendation_gate = evaluate_governance_tuning_recommendation_gate(
        &result.feedback_ingestion,
        &result.proposal_generation,
        &result.ab_comparison,
        &result.ranking,
        &result.safety_guard,
    );
    if emit_owner_summary {
        result.owner_summary = Some(build_owner_governance_policy_recommendation_summary(
            &result.recommendation_gate,
            &result.ranking,
            &result.feedback_ingestion,
        ));
    }
    batch_result.governance_policy_feedback_ingestion_result =
        Some(result.feedback_ingestion.clone());
    batch_result.governance_tuning_proposal_generation_result =
        Some(result.proposal_generation.clone());
    batch_result.governance_tuning_proposal_ledger = Some(result.proposal_ledger.clone());
    batch_result.governance_policy_ab_comparison_result = Some(result.ab_comparison.clone());
    batch_result.governance_tuning_proposal_ranking_result = Some(result.ranking.clone());
    batch_result.governance_tuning_proposal_safety_guard = Some(result.safety_guard.clone());
    batch_result.governance_tuning_recommendation_gate = Some(result.recommendation_gate.clone());
    batch_result.owner_governance_policy_recommendation_summary = result.owner_summary.clone();
    batch_result.governance_policy_feedback_tuning_run_result = Some(result.clone());
    Ok(Some(result))
}

fn default_governance_recommendation_stability_ledger() -> GovernanceRecommendationStabilityLedger {
    GovernanceRecommendationStabilityLedger {
        ledger_id: "governance-recommendation-stability-ledger".to_string(),
        entries: Vec::new(),
        entry_count: 0,
        latest_entry_id: None,
        paper_only: true,
    }
}

pub fn normalize_governance_recommendation_stability_ledger(
    ledger: &mut GovernanceRecommendationStabilityLedger,
) {
    ledger
        .entries
        .sort_by(|left, right| left.entry_id.cmp(&right.entry_id));
    ledger
        .entries
        .dedup_by(|left, right| left.entry_id == right.entry_id);
    ledger.entry_count = ledger.entries.len();
    ledger.latest_entry_id = ledger.entries.last().map(|entry| entry.entry_id.clone());
}

pub fn append_governance_recommendation_ledger_entry(
    ledger: &mut GovernanceRecommendationStabilityLedger,
    entry: GovernanceRecommendationLedgerEntry,
) -> Result<(), String> {
    ledger.entries.push(entry);
    normalize_governance_recommendation_stability_ledger(ledger);
    Ok(())
}

pub fn latest_governance_recommendation_entry(
    ledger: &GovernanceRecommendationStabilityLedger,
) -> Option<&GovernanceRecommendationLedgerEntry> {
    ledger.entries.last()
}

pub fn load_governance_recommendation_stability_ledger_from_local_json(
    path: &Path,
) -> Result<GovernanceRecommendationStabilityLedger, String> {
    validate_local_json_path(path, "governance recommendation stability ledger path")?;
    let text = std::fs::read_to_string(path)
        .map_err(|err| format!("failed to read governance recommendation ledger: {err}"))?;
    let mut ledger: GovernanceRecommendationStabilityLedger = serde_json::from_str(&text)
        .map_err(|err| format!("failed to parse governance recommendation ledger: {err}"))?;
    normalize_governance_recommendation_stability_ledger(&mut ledger);
    Ok(ledger)
}

pub fn save_governance_recommendation_stability_ledger_to_local_json(
    path: &Path,
    ledger: &GovernanceRecommendationStabilityLedger,
) -> Result<(), String> {
    validate_local_json_path(path, "governance recommendation stability ledger path")?;
    write_safe_json(path, ledger)
}

fn governance_recommendation_entry_from_tuning_run(
    tuning_run_result: &GovernancePolicyFeedbackTuningRunResult,
) -> GovernanceRecommendationLedgerEntry {
    let ranking_entry = tuning_run_result
        .ranking
        .recommended_proposal_id
        .as_ref()
        .and_then(|proposal_id| {
            tuning_run_result
                .ranking
                .ranked_proposals
                .iter()
                .find(|rank| &rank.proposal_id == proposal_id)
        })
        .or_else(|| tuning_run_result.ranking.ranked_proposals.first());
    let comparison_entry = tuning_run_result
        .ranking
        .recommended_proposal_id
        .as_ref()
        .and_then(|proposal_id| {
            tuning_run_result
                .ab_comparison
                .records
                .iter()
                .find(|record| &record.proposal_id == proposal_id)
        })
        .or_else(|| tuning_run_result.ab_comparison.records.first());
    GovernanceRecommendationLedgerEntry {
        entry_id: format!("{}-recommendation-entry", tuning_run_result.run_id),
        run_id: tuning_run_result.run_id.clone(),
        recommendation_gate_status: tuning_run_result.recommendation_gate.gate_status,
        recommended_proposal_id: tuning_run_result
            .recommendation_gate
            .recommended_proposal_id
            .clone(),
        ranking_status: tuning_run_result.ranking.ranking_status,
        ab_comparison_status: tuning_run_result.ab_comparison.comparison_status,
        feedback_status: tuning_run_result.feedback_ingestion.ingestion_status,
        safety_status: tuning_run_result.safety_guard.guard_status,
        dominant_feedback: tuning_run_result.feedback_ingestion.dominant_feedback,
        risk_regression_score: comparison_entry
            .map(|record| 1.0 - record.proposal_risk_alignment_worsening_rate),
        voice_concentration_score: comparison_entry
            .map(|record| 1.0 - record.proposal_voice_concentration_index),
        no_trade_bias_score: comparison_entry
            .map(|record| 1.0 - record.proposal_no_trade_bias_rate),
        risk_first_score: ranking_entry.map(|rank| (rank.risk_first_score / 100.0).clamp(0.0, 1.0)),
        paper_only: true,
    }
}

pub fn compute_governance_recommendation_stability_metrics(
    ledger: &GovernanceRecommendationStabilityLedger,
) -> GovernanceRecommendationStabilityMetrics {
    let recommended_proposal_series = ledger
        .entries
        .iter()
        .map(|entry| entry.recommended_proposal_id.clone())
        .collect::<Vec<_>>();
    let mut recommendation_flip_count = 0usize;
    for pair in recommended_proposal_series.windows(2) {
        if pair[0] != pair[1] {
            recommendation_flip_count += 1;
        }
    }
    let recommendation_flip_rate = if ledger.entry_count > 1 {
        recommendation_flip_count as f64 / (ledger.entry_count - 1) as f64
    } else {
        0.0
    };
    let needs_more_evidence_count = ledger
        .entries
        .iter()
        .filter(|entry| {
            matches!(
                entry.recommendation_gate_status,
                GovernanceTuningRecommendationGateStatus::NeedsMoreEvidence
                    | GovernanceTuningRecommendationGateStatus::NeedsMoreHistory
            )
        })
        .count();
    let blocked_by_safety_count = ledger
        .entries
        .iter()
        .filter(|entry| {
            entry.recommendation_gate_status
                == GovernanceTuningRecommendationGateStatus::BlockedBySafety
        })
        .count();
    let no_safe_recommendation_count = ledger
        .entries
        .iter()
        .filter(|entry| {
            entry.recommendation_gate_status
                == GovernanceTuningRecommendationGateStatus::NoSafeRecommendation
        })
        .count();
    let mut dominant_counter = BTreeMap::<String, usize>::new();
    for proposal_id in recommended_proposal_series.iter().flatten() {
        increment_btree_counter(&mut dominant_counter, proposal_id.clone());
    }
    let dominant_recommended_proposal_id = dominant_counter
        .iter()
        .max_by_key(|(_, count)| **count)
        .map(|(proposal_id, _)| proposal_id.clone());
    let same_recommendation_streak = recommended_proposal_series
        .iter()
        .rev()
        .take_while(|proposal_id| {
            *proposal_id == &recommended_proposal_series.last().cloned().unwrap_or(None)
        })
        .count();
    let stability_status = if ledger.entry_count
        < default_governance_recommendation_min_entries_required()
    {
        GovernanceRecommendationStabilityStatus::NeedsMoreHistory
    } else if blocked_by_safety_count > 0 {
        GovernanceRecommendationStabilityStatus::BlockedBySafety
    } else if needs_more_evidence_count * 2 >= ledger.entry_count {
        GovernanceRecommendationStabilityStatus::NeedsMoreEvidence
    } else if recommendation_flip_rate > 0.34 {
        GovernanceRecommendationStabilityStatus::Unstable
    } else if same_recommendation_streak >= default_governance_recommendation_min_entries_required()
    {
        GovernanceRecommendationStabilityStatus::StableRecommendation
    } else if same_recommendation_streak >= 2 {
        GovernanceRecommendationStabilityStatus::StableWithWarnings
    } else {
        GovernanceRecommendationStabilityStatus::Unstable
    };
    GovernanceRecommendationStabilityMetrics {
        metrics_id: "governance-recommendation-stability-metrics".to_string(),
        entry_count: ledger.entry_count,
        recommended_proposal_series,
        recommendation_flip_count,
        recommendation_flip_rate,
        needs_more_evidence_count,
        blocked_by_safety_count,
        no_safe_recommendation_count,
        same_recommendation_streak,
        dominant_recommended_proposal_id,
        stability_status,
        paper_only: true,
    }
}

pub fn compute_governance_recommendation_convergence_detail(
    ledger: &GovernanceRecommendationStabilityLedger,
    policy: &GovernanceRecommendationConvergencePolicy,
) -> GovernanceRecommendationConvergenceDetail {
    let metrics = compute_governance_recommendation_stability_metrics(ledger);
    let mut dominant_counter = BTreeMap::<String, usize>::new();
    for proposal_id in metrics.recommended_proposal_series.iter().flatten() {
        increment_btree_counter(&mut dominant_counter, proposal_id.clone());
    }
    let (dominant_recommended_proposal_id, dominant_recommendation_count) = dominant_counter
        .iter()
        .max_by(|left, right| left.1.cmp(right.1).then_with(|| right.0.cmp(left.0)))
        .map(|(proposal_id, count)| (Some(proposal_id.clone()), *count))
        .unwrap_or((None, 0));
    let dominant_recommendation_ratio = if metrics.entry_count == 0 {
        0.0
    } else {
        dominant_recommendation_count as f64 / metrics.entry_count as f64
    };
    let trailing_streak_proposal_id = metrics
        .recommended_proposal_series
        .last()
        .cloned()
        .unwrap_or(None);
    let trailing_streak_count = metrics
        .recommended_proposal_series
        .iter()
        .rev()
        .take_while(|proposal_id| *proposal_id == &trailing_streak_proposal_id)
        .count();
    let convergence_status = if metrics.entry_count < policy.min_entries_required {
        GovernanceRecommendationConvergenceStatus::InsufficientHistory
    } else if metrics.blocked_by_safety_count > policy.max_safety_block_count {
        GovernanceRecommendationConvergenceStatus::BlockedBySafety
    } else if metrics.needs_more_evidence_count > 0
        && metrics.needs_more_evidence_count * 2 >= metrics.entry_count
    {
        GovernanceRecommendationConvergenceStatus::NeedsMoreEvidence
    } else if dominant_recommendation_ratio >= policy.min_dominant_recommendation_ratio
        && metrics.recommendation_flip_rate <= policy.max_flip_rate
        && metrics.no_safe_recommendation_count == 0
        && dominant_recommended_proposal_id.is_some()
    {
        let trailing_matches_dominant =
            trailing_streak_proposal_id == dominant_recommended_proposal_id;
        if metrics.needs_more_evidence_count == 0
            && trailing_matches_dominant
            && trailing_streak_count >= 2
        {
            GovernanceRecommendationConvergenceStatus::Converged
        } else {
            GovernanceRecommendationConvergenceStatus::ConvergedWithWarnings
        }
    } else {
        GovernanceRecommendationConvergenceStatus::NotConverged
    };
    GovernanceRecommendationConvergenceDetail {
        detail_id: "governance-recommendation-convergence-detail".to_string(),
        entry_count: metrics.entry_count,
        min_entries_required: policy.min_entries_required,
        dominant_recommended_proposal_id,
        dominant_recommendation_count,
        dominant_recommendation_ratio,
        trailing_streak_proposal_id,
        trailing_streak_count,
        flip_count: metrics.recommendation_flip_count,
        flip_rate: metrics.recommendation_flip_rate,
        needs_more_evidence_count: metrics.needs_more_evidence_count,
        blocked_by_safety_count: metrics.blocked_by_safety_count,
        no_safe_recommendation_count: metrics.no_safe_recommendation_count,
        convergence_status,
        paper_only: true,
    }
}

pub fn analyze_governance_recommendation_convergence(
    ledger: &GovernanceRecommendationStabilityLedger,
    policy: &GovernanceRecommendationConvergencePolicy,
) -> GovernanceRecommendationConvergenceAnalysis {
    let detail = compute_governance_recommendation_convergence_detail(ledger, policy);
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    if detail.entry_count < policy.min_entries_required {
        blockers.push("recommendation history is too short".to_string());
    }
    if detail.blocked_by_safety_count > policy.max_safety_block_count {
        blockers.push("safety blocks are still present in recommendation history".to_string());
    }
    if detail.flip_rate > policy.max_flip_rate {
        blockers.push("recommendation flips too frequently".to_string());
    }
    if detail.convergence_status == GovernanceRecommendationConvergenceStatus::NeedsMoreEvidence {
        blockers.push("repeated needs-more-evidence prevents convergence".to_string());
    }
    if detail.dominant_recommendation_ratio < policy.min_dominant_recommendation_ratio {
        warnings.push("no dominant recommendation has emerged yet".to_string());
    }
    if detail.entry_count >= policy.min_entries_required && detail.trailing_streak_count < 2 {
        warnings.push("trailing recommendation streak is still short".to_string());
    }
    if policy.allow_needs_more_evidence_warnings && detail.needs_more_evidence_count > 0 {
        warnings.push("needs-more-evidence still appears in recommendation history".to_string());
    }
    GovernanceRecommendationConvergenceAnalysis {
        analysis_id: "governance-recommendation-convergence-analysis".to_string(),
        entry_count: detail.entry_count,
        required_min_entries: policy.min_entries_required,
        dominant_recommended_proposal_id: detail.dominant_recommended_proposal_id,
        dominant_recommendation_ratio: detail.dominant_recommendation_ratio,
        flip_rate: detail.flip_rate,
        safety_block_count: detail.blocked_by_safety_count,
        evidence_gap_count: detail.needs_more_evidence_count,
        convergence_status: detail.convergence_status,
        blockers,
        warnings,
        paper_only: true,
    }
}

fn governance_trend_direction(series: &[f64]) -> GovernanceRecommendationTrendDirection {
    if series.len() < 2 {
        return GovernanceRecommendationTrendDirection::InsufficientHistory;
    }
    let first = *series.first().unwrap_or(&0.0);
    let last = *series.last().unwrap_or(&0.0);
    if last > first + 0.02 {
        GovernanceRecommendationTrendDirection::Improving
    } else if last + 0.02 < first {
        GovernanceRecommendationTrendDirection::Worsening
    } else {
        GovernanceRecommendationTrendDirection::Stable
    }
}

pub fn compute_governance_recommendation_effectiveness_trend(
    ledger: &GovernanceRecommendationStabilityLedger,
) -> GovernanceRecommendationEffectivenessTrend {
    let risk_regression_score_series = ledger
        .entries
        .iter()
        .filter_map(|entry| entry.risk_regression_score)
        .collect::<Vec<_>>();
    let voice_concentration_score_series = ledger
        .entries
        .iter()
        .filter_map(|entry| entry.voice_concentration_score)
        .collect::<Vec<_>>();
    let no_trade_bias_score_series = ledger
        .entries
        .iter()
        .filter_map(|entry| entry.no_trade_bias_score)
        .collect::<Vec<_>>();
    let risk_first_score_series = ledger
        .entries
        .iter()
        .filter_map(|entry| entry.risk_first_score)
        .collect::<Vec<_>>();
    let risk_regression_trend = governance_trend_direction(&risk_regression_score_series);
    let voice_concentration_trend = governance_trend_direction(&voice_concentration_score_series);
    let no_trade_bias_trend = governance_trend_direction(&no_trade_bias_score_series);
    let effectiveness_trend_status = if ledger.entry_count < 2 {
        GovernanceRecommendationEffectivenessTrendStatus::InsufficientHistory
    } else if risk_regression_trend == GovernanceRecommendationTrendDirection::Worsening
        || voice_concentration_trend == GovernanceRecommendationTrendDirection::Worsening
        || no_trade_bias_trend == GovernanceRecommendationTrendDirection::Worsening
    {
        if risk_regression_trend == GovernanceRecommendationTrendDirection::Improving
            || voice_concentration_trend == GovernanceRecommendationTrendDirection::Improving
            || no_trade_bias_trend == GovernanceRecommendationTrendDirection::Improving
        {
            GovernanceRecommendationEffectivenessTrendStatus::Mixed
        } else {
            GovernanceRecommendationEffectivenessTrendStatus::Worsening
        }
    } else if risk_regression_trend == GovernanceRecommendationTrendDirection::Improving {
        GovernanceRecommendationEffectivenessTrendStatus::Improving
    } else {
        GovernanceRecommendationEffectivenessTrendStatus::Stable
    };
    GovernanceRecommendationEffectivenessTrend {
        trend_id: "governance-recommendation-effectiveness-trend".to_string(),
        entry_count: ledger.entry_count,
        risk_regression_score_series,
        voice_concentration_score_series,
        no_trade_bias_score_series,
        risk_first_score_series,
        risk_regression_trend,
        voice_concentration_trend,
        no_trade_bias_trend,
        effectiveness_trend_status,
        paper_only: true,
    }
}

pub fn evaluate_governance_policy_apply_readiness_blocker(
    stability_metrics: &GovernanceRecommendationStabilityMetrics,
    convergence_analysis: &GovernanceRecommendationConvergenceAnalysis,
    effectiveness_trend: &GovernanceRecommendationEffectivenessTrend,
    safety_status: PaperGovernanceTrialSafetyGuardStatus,
) -> GovernancePolicyApplyReadinessBlocker {
    let min_history_met =
        stability_metrics.entry_count >= convergence_analysis.required_min_entries;
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    if !min_history_met {
        blockers.push("recommendation history is not long enough".to_string());
    }
    if safety_status == PaperGovernanceTrialSafetyGuardStatus::Violated {
        blockers.push("recommendation stability safety guard was violated".to_string());
    }
    if convergence_analysis.convergence_status
        == GovernanceRecommendationConvergenceStatus::BlockedBySafety
    {
        blockers.push("convergence is blocked by safety history".to_string());
    }
    if matches!(
        effectiveness_trend.voice_concentration_trend,
        GovernanceRecommendationTrendDirection::Worsening
    ) {
        warnings.push("voice concentration trend is worsening".to_string());
    }
    let readiness_status = if safety_status == PaperGovernanceTrialSafetyGuardStatus::Violated {
        GovernancePolicyApplyReadinessStatus::BlockedBySafety
    } else if !min_history_met {
        GovernancePolicyApplyReadinessStatus::NeedsMoreHistory
    } else if matches!(
        stability_metrics.stability_status,
        GovernanceRecommendationStabilityStatus::NeedsMoreEvidence
    ) || convergence_analysis.evidence_gap_count > 0
        || matches!(
            convergence_analysis.convergence_status,
            GovernanceRecommendationConvergenceStatus::NeedsMoreEvidence
        )
    {
        GovernancePolicyApplyReadinessStatus::NeedsMoreEvidence
    } else if matches!(
        stability_metrics.stability_status,
        GovernanceRecommendationStabilityStatus::Unstable
    ) || matches!(
        convergence_analysis.convergence_status,
        GovernanceRecommendationConvergenceStatus::NotConverged
            | GovernanceRecommendationConvergenceStatus::InsufficientHistory
    ) {
        GovernancePolicyApplyReadinessStatus::BlockedByInstability
    } else if matches!(
        effectiveness_trend.risk_regression_trend,
        GovernanceRecommendationTrendDirection::Worsening
    ) || matches!(
        effectiveness_trend.effectiveness_trend_status,
        GovernanceRecommendationEffectivenessTrendStatus::Worsening
    ) {
        GovernancePolicyApplyReadinessStatus::BlockedByRiskRegression
    } else if matches!(
        effectiveness_trend.voice_concentration_trend,
        GovernanceRecommendationTrendDirection::Worsening
    ) {
        GovernancePolicyApplyReadinessStatus::BlockedByVoiceConcentration
    } else if !warnings.is_empty()
        || matches!(
            stability_metrics.stability_status,
            GovernanceRecommendationStabilityStatus::StableWithWarnings
        )
        || matches!(
            convergence_analysis.convergence_status,
            GovernanceRecommendationConvergenceStatus::ConvergedWithWarnings
        )
        || matches!(
            effectiveness_trend.effectiveness_trend_status,
            GovernanceRecommendationEffectivenessTrendStatus::Mixed
        )
    {
        GovernancePolicyApplyReadinessStatus::RecommendationStableWithWarnings
    } else {
        GovernancePolicyApplyReadinessStatus::RecommendationStableForReview
    };
    GovernancePolicyApplyReadinessBlocker {
        blocker_id: "governance-policy-apply-readiness-blocker".to_string(),
        convergence_status: convergence_analysis.convergence_status,
        stability_status: stability_metrics.stability_status,
        effectiveness_trend_status: effectiveness_trend.effectiveness_trend_status,
        safety_status,
        min_history_met,
        recommended_proposal_id: stability_metrics.dominant_recommended_proposal_id.clone(),
        policy_apply_allowed: false,
        readiness_status,
        blockers,
        warnings,
        paper_only: true,
    }
}

fn default_governance_recommendation_stability_safety_guard(
    run_result: &GovernanceRecommendationStabilityRunResult,
) -> GovernanceRecommendationStabilitySafetyGuard {
    let actual_policy_apply_detected = run_result.apply_readiness_blocker.policy_apply_allowed;
    let unsafe_recommendation_marked_stable = matches!(
        run_result.apply_readiness_blocker.readiness_status,
        GovernancePolicyApplyReadinessStatus::RecommendationStableForReview
            | GovernancePolicyApplyReadinessStatus::RecommendationStableWithWarnings
    ) && matches!(
        run_result.stability_metrics.stability_status,
        GovernanceRecommendationStabilityStatus::Unstable
            | GovernanceRecommendationStabilityStatus::NeedsMoreEvidence
            | GovernanceRecommendationStabilityStatus::BlockedBySafety
    );
    let unstable_recommendation_marked_ready = matches!(
        run_result.apply_readiness_blocker.readiness_status,
        GovernancePolicyApplyReadinessStatus::RecommendationStableForReview
            | GovernancePolicyApplyReadinessStatus::RecommendationStableWithWarnings
    ) && !matches!(
        run_result.convergence_analysis.convergence_status,
        GovernanceRecommendationConvergenceStatus::Converged
            | GovernanceRecommendationConvergenceStatus::ConvergedWithWarnings
    );
    let ledger_write_when_dry_run_detected = run_result.dry_run && run_result.wrote_ledger;
    let mut violations = Vec::new();
    if actual_policy_apply_detected {
        violations.push("governance recommendation opened actual policy apply".to_string());
    }
    if unsafe_recommendation_marked_stable {
        violations.push("unsafe recommendation was marked stable".to_string());
    }
    if unstable_recommendation_marked_ready {
        violations.push("unstable recommendation was marked ready".to_string());
    }
    if ledger_write_when_dry_run_detected {
        violations.push("recommendation ledger was written during dry-run".to_string());
    }
    GovernanceRecommendationStabilitySafetyGuard {
        actual_policy_apply_detected,
        actual_score_mutation_detected: false,
        actual_voice_mutation_detected: false,
        committee_decision_mutation_detected: false,
        chairman_decision_mutation_detected: false,
        risk_governor_override_detected: false,
        trade_signal_detected: false,
        order_detected: false,
        broker_order_account_detected: false,
        unsafe_recommendation_marked_stable,
        unstable_recommendation_marked_ready,
        ledger_write_when_dry_run_detected,
        guard_status: if violations.is_empty() {
            PaperGovernanceTrialSafetyGuardStatus::Preserved
        } else {
            PaperGovernanceTrialSafetyGuardStatus::Violated
        },
        violations,
        paper_only: true,
    }
}

pub fn evaluate_governance_recommendation_stability_safety(
    run_result: &GovernanceRecommendationStabilityRunResult,
    batch_before: &BatchCommitteeCycleResult,
    batch_after: Option<&BatchCommitteeCycleResult>,
) -> GovernanceRecommendationStabilitySafetyGuard {
    let batch_after = batch_after.unwrap_or(batch_before);
    let actual_score_snapshot = |store: Option<&PaperGovernanceTrialStateStore>| {
        store.map(|store| {
            store
                .member_states
                .iter()
                .map(|state| (state.member_id.clone(), state.actual_score_snapshot))
                .collect::<BTreeMap<_, _>>()
        })
    };
    let actual_voice_snapshot = |store: Option<&PaperGovernanceTrialStateStore>| {
        store.map(|store| {
            store
                .member_states
                .iter()
                .map(|state| (state.member_id.clone(), state.actual_voice_snapshot))
                .collect::<BTreeMap<_, _>>()
        })
    };
    let risk_snapshot = |decisions: &[ChairmanDecision]| {
        decisions
            .iter()
            .map(|decision| (decision.decision_id.clone(), decision.risk_governor_status))
            .collect::<BTreeMap<_, _>>()
    };
    let mut guard = default_governance_recommendation_stability_safety_guard(run_result);
    guard.actual_policy_apply_detected = guard.actual_policy_apply_detected
        || batch_before.conservative_voice_tuning_v2_policy
            != batch_after.conservative_voice_tuning_v2_policy
        || batch_before.chairman_role_voice_floor_policy
            != batch_after.chairman_role_voice_floor_policy;
    guard.actual_score_mutation_detected =
        actual_score_snapshot(batch_before.paper_governance_trial_state_store.as_ref())
            != actual_score_snapshot(batch_after.paper_governance_trial_state_store.as_ref());
    guard.actual_voice_mutation_detected =
        actual_voice_snapshot(batch_before.paper_governance_trial_state_store.as_ref())
            != actual_voice_snapshot(batch_after.paper_governance_trial_state_store.as_ref());
    guard.committee_decision_mutation_detected =
        batch_before.committee_sessions != batch_after.committee_sessions;
    guard.chairman_decision_mutation_detected =
        batch_before.chairman_decisions != batch_after.chairman_decisions;
    guard.risk_governor_override_detected = risk_snapshot(&batch_before.chairman_decisions)
        != risk_snapshot(&batch_after.chairman_decisions);
    guard.trade_signal_detected = value_contains_debug_marker(
        &batch_after.committee_sessions,
        &["trade-signal".to_string()],
    ) && !value_contains_debug_marker(
        &batch_before.committee_sessions,
        &["trade-signal".to_string()],
    );
    guard.order_detected =
        value_contains_debug_marker(&batch_after.event_queue, &["order".to_string()])
            && !value_contains_debug_marker(&batch_before.event_queue, &["order".to_string()]);
    guard.broker_order_account_detected = value_contains_debug_marker(
        batch_after,
        &[
            "broker".to_string(),
            "order".to_string(),
            "account".to_string(),
        ],
    ) && !value_contains_debug_marker(
        batch_before,
        &[
            "broker".to_string(),
            "order".to_string(),
            "account".to_string(),
        ],
    );
    if guard.actual_policy_apply_detected {
        guard
            .violations
            .push("governance recommendation was applied to actual policy".to_string());
    }
    if guard.actual_score_mutation_detected {
        guard
            .violations
            .push("governance recommendation stability mutated actual score".to_string());
    }
    if guard.actual_voice_mutation_detected {
        guard
            .violations
            .push("governance recommendation stability mutated actual voice".to_string());
    }
    if guard.committee_decision_mutation_detected {
        guard
            .violations
            .push("governance recommendation stability mutated committee decision".to_string());
    }
    if guard.chairman_decision_mutation_detected {
        guard
            .violations
            .push("governance recommendation stability mutated chairman decision".to_string());
    }
    if guard.risk_governor_override_detected {
        guard
            .violations
            .push("governance recommendation stability overrode Risk Governor".to_string());
    }
    if guard.trade_signal_detected {
        guard
            .violations
            .push("governance recommendation stability created trade signal".to_string());
    }
    if guard.order_detected {
        guard
            .violations
            .push("governance recommendation stability created order".to_string());
    }
    if guard.broker_order_account_detected {
        guard
            .violations
            .push("governance recommendation stability touched broker/order/account".to_string());
    }
    guard.guard_status = if guard.violations.is_empty() {
        PaperGovernanceTrialSafetyGuardStatus::Preserved
    } else {
        PaperGovernanceTrialSafetyGuardStatus::Violated
    };
    guard
}

pub fn prove_governance_recommendation_ledger_write(
    run_result: &GovernanceRecommendationStabilityRunResult,
    ledger_path: &Path,
) -> Result<GovernanceRecommendationLedgerWriteProof, String> {
    validate_local_json_path(
        ledger_path,
        "governance recommendation stability ledger path",
    )?;
    let ledger_exists_after_write = ledger_path.exists();
    let (entry_count, paper_only_count, unsafe_entry_count) = if ledger_exists_after_write {
        let ledger = load_governance_recommendation_stability_ledger_from_local_json(ledger_path)?;
        let paper_only_count = ledger
            .entries
            .iter()
            .filter(|entry| entry.paper_only)
            .count();
        let unsafe_entry_count = ledger.entries.len().saturating_sub(paper_only_count);
        (ledger.entry_count, paper_only_count, unsafe_entry_count)
    } else {
        (0, 0, 0)
    };
    let proof_status = if run_result.wrote_ledger && !ledger_exists_after_write {
        GovernanceRecommendationLedgerWriteProofStatus::Failed
    } else if unsafe_entry_count > 0 {
        GovernanceRecommendationLedgerWriteProofStatus::Failed
    } else if entry_count < run_result.ledger.entry_count {
        GovernanceRecommendationLedgerWriteProofStatus::ProvenWithWarnings
    } else {
        GovernanceRecommendationLedgerWriteProofStatus::Proven
    };
    Ok(GovernanceRecommendationLedgerWriteProof {
        proof_id: format!("{}-recommendation-ledger-proof", run_result.run_id),
        expected_output_path: ledger_path.display().to_string(),
        wrote_ledger: run_result.wrote_ledger,
        ledger_exists_after_write,
        entry_count,
        paper_only_count,
        unsafe_entry_count,
        proof_status,
        paper_only: true,
    })
}

pub fn build_owner_governance_recommendation_stability_summary(
    run_result: &GovernanceRecommendationStabilityRunResult,
) -> OwnerGovernanceRecommendationStabilitySummary {
    OwnerGovernanceRecommendationStabilitySummary {
        summary_id: format!("{}-owner-recommendation-stability-summary", run_result.run_id),
        entry_count: run_result.ledger.entry_count,
        recommendation_entry_count: run_result.ledger.entry_count,
        dominant_recommended_proposal_id: run_result
            .stability_metrics
            .dominant_recommended_proposal_id
            .clone(),
        recommendation_flip_rate: run_result.stability_metrics.recommendation_flip_rate,
        convergence_status: run_result.convergence_analysis.convergence_status,
        effectiveness_trend_status: run_result.effectiveness_trend.effectiveness_trend_status,
        apply_readiness_status: run_result.apply_readiness_blocker.readiness_status,
        safety_guard_status: run_result.safety_guard.guard_status,
        policy_apply_allowed: false,
        message: "Governance recommendation was tracked across paper cycles. The recommendation is not applied yet. Actual score, voice, decisions, and trading remain unchanged. Stable recommendation only means ready for review, not execution."
            .to_string(),
        recommendation_only: true,
        no_actual_policy_apply: true,
        no_score_mutation: true,
        no_voice_mutation: true,
        no_committee_decision_change: true,
        no_risk_override: true,
        not_trade_signal: true,
        paper_only: true,
    }
}

pub fn run_governance_recommendation_stability_tracking(
    tuning_run_result: &GovernancePolicyFeedbackTuningRunResult,
    batch_result: &BatchCommitteeCycleResult,
    config: &GovernanceRecommendationStabilityRunConfig,
) -> Result<GovernanceRecommendationStabilityRunResult, String> {
    if !config.paper_only {
        return Err("governance recommendation stability run must stay paper_only".to_string());
    }
    for (path, label) in [
        (
            config.ledger_input_path.as_ref(),
            "governance recommendation stability ledger input path",
        ),
        (
            config.ledger_output_path.as_ref(),
            "governance recommendation stability ledger output path",
        ),
        (
            config.output_path.as_ref(),
            "governance recommendation stability output path",
        ),
    ] {
        if let Some(path) = path {
            validate_local_json_path(Path::new(path), label)?;
        }
    }
    if config.min_entries_required == 0 {
        return Err(
            "governance recommendation stability requires positive min_entries_required"
                .to_string(),
        );
    }
    if !config.dry_run && config.append_ledger_entry && config.ledger_output_path.is_none() {
        return Err(
            "governance recommendation stability requires ledger_output_path when dry_run=false and append_ledger_entry=true"
                .to_string(),
        );
    }
    let mut ledger = if let Some(path) = config.ledger_input_path.as_ref() {
        if Path::new(path).exists() {
            load_governance_recommendation_stability_ledger_from_local_json(Path::new(path))?
        } else {
            default_governance_recommendation_stability_ledger()
        }
    } else {
        default_governance_recommendation_stability_ledger()
    };
    let entry = governance_recommendation_entry_from_tuning_run(tuning_run_result);
    append_governance_recommendation_ledger_entry(&mut ledger, entry.clone())?;
    let stability_metrics = compute_governance_recommendation_stability_metrics(&ledger);
    let convergence_analysis = analyze_governance_recommendation_convergence(
        &ledger,
        &GovernanceRecommendationConvergencePolicy {
            min_entries_required: config.min_entries_required,
            min_dominant_recommendation_ratio: 0.67,
            max_flip_rate: 0.34,
            max_safety_block_count: 0,
            allow_needs_more_evidence_warnings: true,
            paper_only: true,
        },
    );
    let effectiveness_trend = compute_governance_recommendation_effectiveness_trend(&ledger);
    let provisional_readiness = evaluate_governance_policy_apply_readiness_blocker(
        &stability_metrics,
        &convergence_analysis,
        &effectiveness_trend,
        PaperGovernanceTrialSafetyGuardStatus::Preserved,
    );
    let mut result = GovernanceRecommendationStabilityRunResult {
        run_id: config.run_id.clone(),
        ledger,
        appended_entry: Some(entry),
        stability_metrics,
        convergence_analysis,
        effectiveness_trend,
        apply_readiness_blocker: provisional_readiness,
        safety_guard: GovernanceRecommendationStabilitySafetyGuard {
            actual_policy_apply_detected: false,
            actual_score_mutation_detected: false,
            actual_voice_mutation_detected: false,
            committee_decision_mutation_detected: false,
            chairman_decision_mutation_detected: false,
            risk_governor_override_detected: false,
            trade_signal_detected: false,
            order_detected: false,
            broker_order_account_detected: false,
            unsafe_recommendation_marked_stable: false,
            unstable_recommendation_marked_ready: false,
            ledger_write_when_dry_run_detected: false,
            guard_status: PaperGovernanceTrialSafetyGuardStatus::Preserved,
            violations: Vec::new(),
            paper_only: true,
        },
        write_proof: None,
        owner_summary: None,
        run_status: PaperGovernanceTrialRunStatus::PassedWithWarnings,
        dry_run: config.dry_run,
        wrote_ledger: false,
        ledger_output_path: config.ledger_output_path.clone(),
        paper_only: true,
    };
    result.safety_guard = evaluate_governance_recommendation_stability_safety(
        &result,
        batch_result,
        Some(batch_result),
    );
    result.apply_readiness_blocker = evaluate_governance_policy_apply_readiness_blocker(
        &result.stability_metrics,
        &result.convergence_analysis,
        &result.effectiveness_trend,
        result.safety_guard.guard_status,
    );
    if !config.dry_run && config.append_ledger_entry {
        if let Some(path) = config.ledger_output_path.as_ref() {
            save_governance_recommendation_stability_ledger_to_local_json(
                Path::new(path),
                &result.ledger,
            )?;
            result.wrote_ledger = true;
        }
    }
    if !config.dry_run && result.wrote_ledger {
        if let Some(path) = config.ledger_output_path.as_ref() {
            result.write_proof = Some(prove_governance_recommendation_ledger_write(
                &result,
                Path::new(path),
            )?);
        }
    }
    if config.emit_owner_summary {
        result.owner_summary = Some(build_owner_governance_recommendation_stability_summary(
            &result,
        ));
    }
    result.run_status = if result.safety_guard.guard_status
        == PaperGovernanceTrialSafetyGuardStatus::Violated
        || matches!(
            result.apply_readiness_blocker.readiness_status,
            GovernancePolicyApplyReadinessStatus::BlockedBySafety
                | GovernancePolicyApplyReadinessStatus::BlockedByRiskRegression
                | GovernancePolicyApplyReadinessStatus::BlockedByInstability
        ) {
        PaperGovernanceTrialRunStatus::Failed
    } else if result.apply_readiness_blocker.readiness_status
        == GovernancePolicyApplyReadinessStatus::RecommendationStableForReview
    {
        PaperGovernanceTrialRunStatus::Passed
    } else {
        PaperGovernanceTrialRunStatus::PassedWithWarnings
    };
    if !config.dry_run {
        if let Some(path) = config.output_path.as_ref() {
            write_safe_json(Path::new(path), &result)?;
        }
    }
    Ok(result)
}

pub fn governance_recommendation_stability_requested_from_flags(
    enabled: bool,
    dry_run: bool,
    append_ledger_entry: bool,
    ledger_input_path: Option<&String>,
    ledger_output_path: Option<&String>,
    output_path: Option<&String>,
    emit_owner_summary: bool,
) -> bool {
    enabled
        || !dry_run
        || ledger_input_path.is_some()
        || ledger_output_path.is_some()
        || output_path.is_some()
        || (enabled && (append_ledger_entry || emit_owner_summary))
}

fn maybe_run_governance_recommendation_stability_for_batch_result(
    run_id: String,
    enabled: bool,
    dry_run: bool,
    append_ledger_entry: bool,
    ledger_input_path: Option<&String>,
    ledger_output_path: Option<&String>,
    min_entries_required: usize,
    emit_owner_summary: bool,
    output_path: Option<&String>,
    batch_result: &mut BatchCommitteeCycleResult,
) -> Result<Option<GovernanceRecommendationStabilityRunResult>, String> {
    if !governance_recommendation_stability_requested_from_flags(
        enabled,
        dry_run,
        append_ledger_entry,
        ledger_input_path,
        ledger_output_path,
        output_path,
        emit_owner_summary,
    ) {
        return Ok(None);
    }
    let tuning_run_result = batch_result
        .governance_policy_feedback_tuning_run_result
        .clone()
        .ok_or_else(|| {
            "governance recommendation stability requires governance policy feedback tuning run result"
                .to_string()
        })?;
    let result = run_governance_recommendation_stability_tracking(
        &tuning_run_result,
        batch_result,
        &GovernanceRecommendationStabilityRunConfig {
            run_id,
            enabled,
            ledger_input_path: ledger_input_path.cloned(),
            ledger_output_path: ledger_output_path.cloned(),
            output_path: output_path.cloned(),
            dry_run,
            append_ledger_entry,
            min_entries_required,
            emit_owner_summary,
            paper_only: true,
        },
    )?;
    batch_result.governance_recommendation_stability_ledger = Some(result.ledger.clone());
    batch_result.governance_recommendation_stability_metrics =
        Some(result.stability_metrics.clone());
    batch_result.governance_recommendation_convergence_analysis =
        Some(result.convergence_analysis.clone());
    batch_result.governance_recommendation_effectiveness_trend =
        Some(result.effectiveness_trend.clone());
    batch_result.governance_policy_apply_readiness_blocker =
        Some(result.apply_readiness_blocker.clone());
    batch_result.governance_recommendation_stability_safety_guard =
        Some(result.safety_guard.clone());
    batch_result.governance_recommendation_ledger_write_proof = result.write_proof.clone();
    batch_result.owner_governance_recommendation_stability_summary = result.owner_summary.clone();
    batch_result.governance_recommendation_stability_run_result = Some(result.clone());
    Ok(Some(result))
}

fn default_governance_recommendation_multi_run_safety_guard()
-> GovernanceRecommendationMultiRunSafetyGuard {
    GovernanceRecommendationMultiRunSafetyGuard {
        actual_policy_apply_detected: false,
        actual_score_mutation_detected: false,
        actual_voice_mutation_detected: false,
        committee_decision_mutation_detected: false,
        chairman_decision_mutation_detected: false,
        risk_governor_override_detected: false,
        trade_signal_detected: false,
        order_detected: false,
        broker_order_account_detected: false,
        policy_apply_allowed_true_detected: false,
        review_packet_marked_apply_ready_detected: false,
        ledger_write_when_dry_run_detected: false,
        unsafe_trial_gate_open_detected: false,
        guard_status: PaperGovernanceTrialSafetyGuardStatus::Preserved,
        violations: Vec::new(),
        paper_only: true,
    }
}

pub fn build_stable_governance_recommendation_review_packet(
    convergence_detail: &GovernanceRecommendationConvergenceDetail,
    effectiveness_trend: &GovernanceRecommendationEffectivenessTrend,
    apply_readiness_blocker: &GovernancePolicyApplyReadinessBlocker,
) -> StableGovernanceRecommendationReviewPacket {
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    if matches!(
        convergence_detail.convergence_status,
        GovernanceRecommendationConvergenceStatus::BlockedBySafety
    ) || matches!(
        apply_readiness_blocker.readiness_status,
        GovernancePolicyApplyReadinessStatus::BlockedBySafety
            | GovernancePolicyApplyReadinessStatus::BlockedByRiskRegression
            | GovernancePolicyApplyReadinessStatus::BlockedByVoiceConcentration
            | GovernancePolicyApplyReadinessStatus::BlockedByInstability
    ) {
        blockers.push("recommendation is blocked for review packet promotion".to_string());
    }
    if matches!(
        convergence_detail.convergence_status,
        GovernanceRecommendationConvergenceStatus::InsufficientHistory
            | GovernanceRecommendationConvergenceStatus::NeedsMoreEvidence
            | GovernanceRecommendationConvergenceStatus::NotConverged
    ) {
        warnings.push("recommendation is not fully converged yet".to_string());
    }
    if matches!(
        effectiveness_trend.voice_concentration_trend,
        GovernanceRecommendationTrendDirection::Worsening
    ) {
        warnings.push("voice concentration trend still needs review".to_string());
    }
    let review_status = if !blockers.is_empty() {
        StableGovernanceRecommendationReviewPacketStatus::Blocked
    } else if matches!(
        convergence_detail.convergence_status,
        GovernanceRecommendationConvergenceStatus::InsufficientHistory
            | GovernanceRecommendationConvergenceStatus::NeedsMoreEvidence
            | GovernanceRecommendationConvergenceStatus::NotConverged
    ) || convergence_detail
        .dominant_recommended_proposal_id
        .is_none()
    {
        StableGovernanceRecommendationReviewPacketStatus::NotReady
    } else if matches!(
        convergence_detail.convergence_status,
        GovernanceRecommendationConvergenceStatus::ConvergedWithWarnings
    ) || matches!(
        apply_readiness_blocker.readiness_status,
        GovernancePolicyApplyReadinessStatus::RecommendationStableWithWarnings
    ) || matches!(
        effectiveness_trend.effectiveness_trend_status,
        GovernanceRecommendationEffectivenessTrendStatus::Mixed
    ) {
        StableGovernanceRecommendationReviewPacketStatus::ReadyForOwnerReviewWithWarnings
    } else {
        StableGovernanceRecommendationReviewPacketStatus::ReadyForOwnerReview
    };
    StableGovernanceRecommendationReviewPacket {
        packet_id: "stable-governance-recommendation-review-packet".to_string(),
        recommended_proposal_id: convergence_detail.dominant_recommended_proposal_id.clone(),
        convergence_detail: convergence_detail.clone(),
        effectiveness_trend: effectiveness_trend.clone(),
        risk_regression_summary: format!(
            "risk regression trend: {:?}",
            effectiveness_trend.risk_regression_trend
        ),
        voice_concentration_summary: format!(
            "voice concentration trend: {:?}",
            effectiveness_trend.voice_concentration_trend
        ),
        no_trade_bias_summary: format!(
            "no-trade bias trend: {:?}",
            effectiveness_trend.no_trade_bias_trend
        ),
        evidence_balance_summary: if convergence_detail.needs_more_evidence_count > 0 {
            format!(
                "needs-more-evidence remained in {} entries",
                convergence_detail.needs_more_evidence_count
            )
        } else {
            "recommendation evidence is balanced enough for review".to_string()
        },
        risk_first_preserved: effectiveness_trend
            .risk_first_score_series
            .last()
            .copied()
            .unwrap_or(0.0)
            >= 0.5,
        policy_apply_allowed: false,
        review_status,
        blockers,
        warnings,
        paper_only: true,
    }
}

pub fn analyze_governance_recommendation_evidence_gaps(
    stability_metrics: &GovernanceRecommendationStabilityMetrics,
    convergence_detail: &GovernanceRecommendationConvergenceDetail,
    effectiveness_trend: &GovernanceRecommendationEffectivenessTrend,
) -> GovernanceRecommendationEvidenceGapSummary {
    let mut gaps = Vec::new();
    if convergence_detail.entry_count < convergence_detail.min_entries_required {
        gaps.push(GovernanceRecommendationEvidenceGapRecord {
            gap_id: "recommendation-gap-too-few-entries".to_string(),
            gap_kind: GovernanceRecommendationEvidenceGapKind::TooFewEntries,
            severity: GovernanceRecommendationEvidenceGapSeverity::High,
            reason: "recommendation history is shorter than required minimum".to_string(),
            recommended_collection_action:
                GovernanceRecommendationCollectionAction::CollectMorePaperCycles,
            paper_only: true,
        });
    }
    if convergence_detail.needs_more_evidence_count > 0 {
        gaps.push(GovernanceRecommendationEvidenceGapRecord {
            gap_id: "recommendation-gap-needs-more-evidence".to_string(),
            gap_kind: GovernanceRecommendationEvidenceGapKind::RepeatedNeedsMoreEvidence,
            severity: if convergence_detail.needs_more_evidence_count * 2
                >= convergence_detail.entry_count
            {
                GovernanceRecommendationEvidenceGapSeverity::High
            } else {
                GovernanceRecommendationEvidenceGapSeverity::Medium
            },
            reason: "needs-more-evidence repeated across recommendation history".to_string(),
            recommended_collection_action:
                GovernanceRecommendationCollectionAction::CollectMorePaperCycles,
            paper_only: true,
        });
    }
    if matches!(
        stability_metrics.stability_status,
        GovernanceRecommendationStabilityStatus::Unstable
    ) || matches!(
        convergence_detail.convergence_status,
        GovernanceRecommendationConvergenceStatus::NotConverged
    ) {
        gaps.push(GovernanceRecommendationEvidenceGapRecord {
            gap_id: "recommendation-gap-unstable".to_string(),
            gap_kind: GovernanceRecommendationEvidenceGapKind::UnstableRecommendation,
            severity: GovernanceRecommendationEvidenceGapSeverity::Medium,
            reason: "recommendation still flips too much or lacks enough dominance".to_string(),
            recommended_collection_action:
                GovernanceRecommendationCollectionAction::CollectMorePaperCycles,
            paper_only: true,
        });
    }
    if !matches!(
        effectiveness_trend.risk_regression_trend,
        GovernanceRecommendationTrendDirection::Improving
    ) {
        gaps.push(GovernanceRecommendationEvidenceGapRecord {
            gap_id: "recommendation-gap-risk-regression".to_string(),
            gap_kind: GovernanceRecommendationEvidenceGapKind::LowRiskRegressionSignal,
            severity: if matches!(
                effectiveness_trend.risk_regression_trend,
                GovernanceRecommendationTrendDirection::Worsening
            ) {
                GovernanceRecommendationEvidenceGapSeverity::High
            } else {
                GovernanceRecommendationEvidenceGapSeverity::Medium
            },
            reason: "risk regression improvement signal is not strong enough".to_string(),
            recommended_collection_action:
                GovernanceRecommendationCollectionAction::CollectRiskRegressionEvidence,
            paper_only: true,
        });
    }
    if matches!(
        effectiveness_trend.voice_concentration_trend,
        GovernanceRecommendationTrendDirection::Worsening
            | GovernanceRecommendationTrendDirection::InsufficientHistory
    ) {
        gaps.push(GovernanceRecommendationEvidenceGapRecord {
            gap_id: "recommendation-gap-voice-concentration".to_string(),
            gap_kind: GovernanceRecommendationEvidenceGapKind::WeakVoiceConcentrationSignal,
            severity: GovernanceRecommendationEvidenceGapSeverity::Medium,
            reason: "voice concentration signal is still weak or worsening".to_string(),
            recommended_collection_action:
                GovernanceRecommendationCollectionAction::CollectVoiceConcentrationEvidence,
            paper_only: true,
        });
    }
    if matches!(
        effectiveness_trend.no_trade_bias_trend,
        GovernanceRecommendationTrendDirection::Worsening
            | GovernanceRecommendationTrendDirection::InsufficientHistory
    ) {
        gaps.push(GovernanceRecommendationEvidenceGapRecord {
            gap_id: "recommendation-gap-no-trade-bias".to_string(),
            gap_kind: GovernanceRecommendationEvidenceGapKind::NoTradeBiasAmbiguous,
            severity: GovernanceRecommendationEvidenceGapSeverity::Medium,
            reason: "no-trade bias evidence remains ambiguous".to_string(),
            recommended_collection_action:
                GovernanceRecommendationCollectionAction::CollectNoTradeBiasEvidence,
            paper_only: true,
        });
    }
    if effectiveness_trend.risk_first_score_series.is_empty()
        || effectiveness_trend
            .risk_first_score_series
            .last()
            .copied()
            .unwrap_or(0.0)
            < 0.5
    {
        gaps.push(GovernanceRecommendationEvidenceGapRecord {
            gap_id: "recommendation-gap-risk-first".to_string(),
            gap_kind: GovernanceRecommendationEvidenceGapKind::MissingRiskFirstEvidence,
            severity: GovernanceRecommendationEvidenceGapSeverity::Medium,
            reason: "risk-first preservation evidence is still weak".to_string(),
            recommended_collection_action:
                GovernanceRecommendationCollectionAction::CollectRiskFirstEvidence,
            paper_only: true,
        });
    }
    let high_severity_count = gaps
        .iter()
        .filter(|gap| gap.severity == GovernanceRecommendationEvidenceGapSeverity::High)
        .count();
    let mut dominant_gaps = gaps.iter().map(|gap| gap.gap_kind).collect::<Vec<_>>();
    dominant_gaps.sort();
    dominant_gaps.dedup();
    let mut collection_actions = gaps
        .iter()
        .map(|gap| gap.recommended_collection_action)
        .collect::<Vec<_>>();
    collection_actions.sort();
    collection_actions.dedup();
    let gap_status = if gaps
        .iter()
        .any(|gap| gap.gap_kind == GovernanceRecommendationEvidenceGapKind::TooFewEntries)
    {
        GovernanceRecommendationEvidenceGapStatus::InsufficientHistory
    } else if gaps.iter().any(|gap| {
        gap.gap_kind == GovernanceRecommendationEvidenceGapKind::RepeatedNeedsMoreEvidence
    }) {
        GovernanceRecommendationEvidenceGapStatus::NeedsMoreEvidence
    } else if gaps.is_empty() {
        GovernanceRecommendationEvidenceGapStatus::NoMajorGap
    } else {
        GovernanceRecommendationEvidenceGapStatus::HasGaps
    };
    GovernanceRecommendationEvidenceGapSummary {
        summary_id: "governance-recommendation-evidence-gap-summary".to_string(),
        gap_count: gaps.len(),
        high_severity_count,
        dominant_gaps,
        collection_actions,
        gap_status,
        gaps,
        paper_only: true,
    }
}

pub fn evaluate_governance_policy_apply_trial_gate(
    review_packet: &StableGovernanceRecommendationReviewPacket,
    stability_metrics: &GovernanceRecommendationStabilityMetrics,
    convergence_detail: &GovernanceRecommendationConvergenceDetail,
    safety_guard: &GovernanceRecommendationMultiRunSafetyGuard,
) -> GovernancePolicyApplyTrialGate {
    let mut blockers = Vec::new();
    let mut warnings = review_packet.warnings.clone();
    if safety_guard.guard_status == PaperGovernanceTrialSafetyGuardStatus::Violated {
        blockers.push("multi-run safety guard was violated".to_string());
    }
    if review_packet.policy_apply_allowed {
        blockers.push("review packet attempted to enable policy apply".to_string());
    }
    let gate_status =
        if safety_guard.guard_status == PaperGovernanceTrialSafetyGuardStatus::Violated {
            GovernancePolicyApplyTrialGateStatus::BlockedBySafety
        } else if review_packet.policy_apply_allowed {
            GovernancePolicyApplyTrialGateStatus::ApplyForbidden
        } else if convergence_detail.entry_count < convergence_detail.min_entries_required {
            GovernancePolicyApplyTrialGateStatus::NeedsMoreHistory
        } else if matches!(
            convergence_detail.convergence_status,
            GovernanceRecommendationConvergenceStatus::NeedsMoreEvidence
        ) || matches!(
            stability_metrics.stability_status,
            GovernanceRecommendationStabilityStatus::NeedsMoreEvidence
        ) {
            GovernancePolicyApplyTrialGateStatus::NeedsMoreEvidence
        } else if matches!(
            review_packet.effectiveness_trend.risk_regression_trend,
            GovernanceRecommendationTrendDirection::Worsening
        ) || matches!(
            review_packet.effectiveness_trend.effectiveness_trend_status,
            GovernanceRecommendationEffectivenessTrendStatus::Worsening
        ) {
            GovernancePolicyApplyTrialGateStatus::BlockedByRiskRegression
        } else if matches!(
            review_packet.effectiveness_trend.voice_concentration_trend,
            GovernanceRecommendationTrendDirection::Worsening
        ) {
            GovernancePolicyApplyTrialGateStatus::BlockedByVoiceConcentration
        } else if matches!(
            convergence_detail.convergence_status,
            GovernanceRecommendationConvergenceStatus::BlockedBySafety
        ) {
            GovernancePolicyApplyTrialGateStatus::BlockedBySafety
        } else if matches!(
            convergence_detail.convergence_status,
            GovernanceRecommendationConvergenceStatus::InsufficientHistory
                | GovernanceRecommendationConvergenceStatus::NotConverged
        ) || matches!(
            stability_metrics.stability_status,
            GovernanceRecommendationStabilityStatus::Unstable
        ) {
            GovernancePolicyApplyTrialGateStatus::BlockedByInstability
        } else if review_packet.review_status
            == StableGovernanceRecommendationReviewPacketStatus::ReadyForOwnerReview
        {
            GovernancePolicyApplyTrialGateStatus::ReadyForPolicyApplyTrialDesign
        } else if matches!(
            review_packet.review_status,
            StableGovernanceRecommendationReviewPacketStatus::ReadyForOwnerReviewWithWarnings
        ) {
            GovernancePolicyApplyTrialGateStatus::ReadyForReviewOnly
        } else {
            GovernancePolicyApplyTrialGateStatus::ApplyForbidden
        };
    if matches!(
        gate_status,
        GovernancePolicyApplyTrialGateStatus::ReadyForReviewOnly
    ) {
        warnings.push("gate remains review-only in Sprint 201".to_string());
    }
    GovernancePolicyApplyTrialGate {
        gate_id: "governance-policy-apply-trial-gate".to_string(),
        convergence_status: convergence_detail.convergence_status,
        effectiveness_trend_status: review_packet.effectiveness_trend.effectiveness_trend_status,
        safety_status: safety_guard.guard_status,
        review_packet_status: review_packet.review_status,
        policy_apply_allowed: false,
        ready_for_policy_apply_trial_design: matches!(
            gate_status,
            GovernancePolicyApplyTrialGateStatus::ReadyForPolicyApplyTrialDesign
        ),
        gate_status,
        blockers,
        warnings,
        paper_only: true,
    }
}

pub fn build_owner_governance_recommendation_review_summary(
    review_packet: &StableGovernanceRecommendationReviewPacket,
    trial_gate: &GovernancePolicyApplyTrialGate,
    evidence_gap_summary: &GovernanceRecommendationEvidenceGapSummary,
    completed_run_count: usize,
    final_ledger_entry_count: usize,
    safety_guard_status: PaperGovernanceTrialSafetyGuardStatus,
) -> OwnerGovernanceRecommendationReviewSummary {
    OwnerGovernanceRecommendationReviewSummary {
        summary_id: "owner-governance-recommendation-review-summary".to_string(),
        completed_run_count,
        final_ledger_entry_count,
        dominant_recommended_proposal_id: review_packet.recommended_proposal_id.clone(),
        recommended_proposal_id: review_packet.recommended_proposal_id.clone(),
        convergence_status: review_packet.convergence_detail.convergence_status,
        dominant_recommendation_ratio: review_packet
            .convergence_detail
            .dominant_recommendation_ratio,
        trailing_streak_count: review_packet.convergence_detail.trailing_streak_count,
        effectiveness_trend_status: review_packet.effectiveness_trend.effectiveness_trend_status,
        evidence_gap_status: evidence_gap_summary.gap_status,
        apply_trial_gate_status: trial_gate.gate_status,
        policy_apply_allowed: false,
        safety_guard_status,
        message: "Recommendation stability was evaluated across repeated paper cycles. The recommendation is for review only. Actual policy, score, voice, decisions, and trading remain unchanged. Owner opinion may review the recommendation, but it does not force application."
            .to_string(),
        recommendation_only: true,
        review_only: true,
        no_actual_policy_apply: true,
        no_score_mutation: true,
        no_voice_mutation: true,
        no_committee_decision_change: true,
        no_risk_override: true,
        not_trade_signal: true,
        paper_only: true,
    }
}

pub fn evaluate_governance_recommendation_multi_run_safety(
    multi_run_result: &GovernanceRecommendationMultiRunResult,
    batch_before: &BatchCommitteeCycleResult,
    batch_after: Option<&BatchCommitteeCycleResult>,
) -> GovernanceRecommendationMultiRunSafetyGuard {
    let batch_after = batch_after.unwrap_or(batch_before);
    let actual_score_snapshot = |store: Option<&PaperGovernanceTrialStateStore>| {
        store.map(|store| {
            store
                .member_states
                .iter()
                .map(|state| (state.member_id.clone(), state.actual_score_snapshot))
                .collect::<BTreeMap<_, _>>()
        })
    };
    let actual_voice_snapshot = |store: Option<&PaperGovernanceTrialStateStore>| {
        store.map(|store| {
            store
                .member_states
                .iter()
                .map(|state| (state.member_id.clone(), state.actual_voice_snapshot))
                .collect::<BTreeMap<_, _>>()
        })
    };
    let risk_snapshot = |decisions: &[ChairmanDecision]| {
        decisions
            .iter()
            .map(|decision| (decision.decision_id.clone(), decision.risk_governor_status))
            .collect::<BTreeMap<_, _>>()
    };
    let mut guard = default_governance_recommendation_multi_run_safety_guard();
    guard.actual_policy_apply_detected = batch_before.conservative_voice_tuning_v2_policy
        != batch_after.conservative_voice_tuning_v2_policy
        || batch_before.chairman_role_voice_floor_policy
            != batch_after.chairman_role_voice_floor_policy;
    guard.actual_score_mutation_detected =
        actual_score_snapshot(batch_before.paper_governance_trial_state_store.as_ref())
            != actual_score_snapshot(batch_after.paper_governance_trial_state_store.as_ref());
    guard.actual_voice_mutation_detected =
        actual_voice_snapshot(batch_before.paper_governance_trial_state_store.as_ref())
            != actual_voice_snapshot(batch_after.paper_governance_trial_state_store.as_ref());
    guard.committee_decision_mutation_detected =
        batch_before.committee_sessions != batch_after.committee_sessions;
    guard.chairman_decision_mutation_detected =
        batch_before.chairman_decisions != batch_after.chairman_decisions;
    guard.risk_governor_override_detected = risk_snapshot(&batch_before.chairman_decisions)
        != risk_snapshot(&batch_after.chairman_decisions);
    guard.trade_signal_detected = value_contains_debug_marker(
        &batch_after.committee_sessions,
        &["trade-signal".to_string()],
    ) && !value_contains_debug_marker(
        &batch_before.committee_sessions,
        &["trade-signal".to_string()],
    );
    guard.order_detected =
        value_contains_debug_marker(&batch_after.event_queue, &["order".to_string()])
            && !value_contains_debug_marker(&batch_before.event_queue, &["order".to_string()]);
    guard.broker_order_account_detected = value_contains_debug_marker(
        batch_after,
        &[
            "broker".to_string(),
            "order".to_string(),
            "account".to_string(),
        ],
    ) && !value_contains_debug_marker(
        batch_before,
        &[
            "broker".to_string(),
            "order".to_string(),
            "account".to_string(),
        ],
    );
    guard.policy_apply_allowed_true_detected =
        multi_run_result.apply_trial_gate.policy_apply_allowed
            || multi_run_result.review_packet.policy_apply_allowed;
    guard.review_packet_marked_apply_ready_detected =
        multi_run_result.review_packet.policy_apply_allowed;
    guard.ledger_write_when_dry_run_detected =
        multi_run_result.dry_run && multi_run_result.wrote_ledger;
    guard.unsafe_trial_gate_open_detected = multi_run_result
        .apply_trial_gate
        .ready_for_policy_apply_trial_design
        && (!matches!(
            multi_run_result.review_packet.review_status,
            StableGovernanceRecommendationReviewPacketStatus::ReadyForOwnerReview
                | StableGovernanceRecommendationReviewPacketStatus::ReadyForOwnerReviewWithWarnings
        ) || !matches!(
            multi_run_result.convergence_detail.convergence_status,
            GovernanceRecommendationConvergenceStatus::Converged
                | GovernanceRecommendationConvergenceStatus::ConvergedWithWarnings
        ) || guard.policy_apply_allowed_true_detected);
    if guard.actual_policy_apply_detected {
        guard
            .violations
            .push("governance recommendation multi-run triggered actual policy apply".to_string());
    }
    if guard.actual_score_mutation_detected {
        guard
            .violations
            .push("governance recommendation multi-run mutated actual score".to_string());
    }
    if guard.actual_voice_mutation_detected {
        guard
            .violations
            .push("governance recommendation multi-run mutated actual voice".to_string());
    }
    if guard.committee_decision_mutation_detected {
        guard
            .violations
            .push("governance recommendation multi-run mutated committee decision".to_string());
    }
    if guard.chairman_decision_mutation_detected {
        guard
            .violations
            .push("governance recommendation multi-run mutated chairman decision".to_string());
    }
    if guard.risk_governor_override_detected {
        guard
            .violations
            .push("governance recommendation multi-run overrode Risk Governor".to_string());
    }
    if guard.trade_signal_detected {
        guard
            .violations
            .push("governance recommendation multi-run created trade signal".to_string());
    }
    if guard.order_detected {
        guard
            .violations
            .push("governance recommendation multi-run created order".to_string());
    }
    if guard.broker_order_account_detected {
        guard
            .violations
            .push("governance recommendation multi-run touched broker/order/account".to_string());
    }
    if guard.policy_apply_allowed_true_detected {
        guard
            .violations
            .push("governance recommendation multi-run opened policy_apply_allowed".to_string());
    }
    if guard.review_packet_marked_apply_ready_detected {
        guard
            .violations
            .push("review packet was misused as apply-ready".to_string());
    }
    if guard.ledger_write_when_dry_run_detected {
        guard
            .violations
            .push("recommendation ledger was written during dry-run".to_string());
    }
    if guard.unsafe_trial_gate_open_detected {
        guard
            .violations
            .push("policy apply trial gate opened unsafely".to_string());
    }
    guard.guard_status = if guard.violations.is_empty() {
        PaperGovernanceTrialSafetyGuardStatus::Preserved
    } else {
        PaperGovernanceTrialSafetyGuardStatus::Violated
    };
    guard
}

pub fn governance_recommendation_multirun_requested_from_flags(
    enabled: bool,
    dry_run: bool,
    run_count: usize,
    append_ledger_entries: bool,
    ledger_input_path: Option<&String>,
    ledger_output_path: Option<&String>,
    output_path: Option<&String>,
    emit_owner_summary: bool,
) -> bool {
    enabled
        || !dry_run
        || run_count != default_governance_recommendation_multi_run_count()
        || ledger_input_path.is_some()
        || ledger_output_path.is_some()
        || output_path.is_some()
        || (enabled && (append_ledger_entries || emit_owner_summary))
}

pub fn run_governance_recommendation_multi_run_stability(
    tuning_run_result: &GovernancePolicyFeedbackTuningRunResult,
    batch_result: &BatchCommitteeCycleResult,
    config: &GovernanceRecommendationMultiRunConfig,
) -> Result<GovernanceRecommendationMultiRunResult, String> {
    if !config.paper_only {
        return Err("governance recommendation multi-run must stay paper_only".to_string());
    }
    for (path, label) in [
        (
            config.ledger_input_path.as_ref(),
            "governance recommendation multirun ledger input path",
        ),
        (
            config.ledger_output_path.as_ref(),
            "governance recommendation multirun ledger output path",
        ),
        (
            config.output_path.as_ref(),
            "governance recommendation multirun output path",
        ),
    ] {
        if let Some(path) = path {
            validate_local_json_path(Path::new(path), label)?;
        }
    }
    if config.run_count == 0 {
        return Err("governance recommendation multirun requires positive run_count".to_string());
    }
    if config.min_entries_required == 0 {
        return Err(
            "governance recommendation multirun requires positive min_entries_required".to_string(),
        );
    }
    if !config.dry_run && config.append_ledger_entries && config.ledger_output_path.is_none() {
        return Err(
            "governance recommendation multirun requires ledger_output_path when dry_run=false and append_ledger_entries=true"
                .to_string(),
        );
    }
    let mut ledger = if let Some(path) = config.ledger_input_path.as_ref() {
        if Path::new(path).exists() {
            load_governance_recommendation_stability_ledger_from_local_json(Path::new(path))?
        } else {
            default_governance_recommendation_stability_ledger()
        }
    } else {
        default_governance_recommendation_stability_ledger()
    };
    let previous_ledger_entry_count = ledger.entry_count;
    let policy = GovernanceRecommendationConvergencePolicy {
        min_entries_required: config.min_entries_required,
        min_dominant_recommendation_ratio: 0.67,
        max_flip_rate: 0.34,
        max_safety_block_count: 0,
        allow_needs_more_evidence_warnings: true,
        paper_only: true,
    };
    let mut per_run_results = Vec::new();
    for run_index in 0..config.run_count {
        let mut entry = governance_recommendation_entry_from_tuning_run(tuning_run_result);
        entry.entry_id = format!(
            "{}-entry-{:04}",
            config.run_id,
            previous_ledger_entry_count + run_index + 1
        );
        entry.run_id = format!("{}-run-{:02}", config.run_id, run_index + 1);
        append_governance_recommendation_ledger_entry(&mut ledger, entry.clone())?;
        let stability_metrics = compute_governance_recommendation_stability_metrics(&ledger);
        let convergence_analysis = analyze_governance_recommendation_convergence(&ledger, &policy);
        let effectiveness_trend = compute_governance_recommendation_effectiveness_trend(&ledger);
        let apply_readiness_blocker = evaluate_governance_policy_apply_readiness_blocker(
            &stability_metrics,
            &convergence_analysis,
            &effectiveness_trend,
            entry.safety_status,
        );
        per_run_results.push(PerRunGovernanceRecommendationResult {
            run_index: run_index + 1,
            entry_id: Some(entry.entry_id),
            recommendation_gate_status: entry.recommendation_gate_status,
            recommended_proposal_id: entry.recommended_proposal_id,
            convergence_status: convergence_analysis.convergence_status,
            effectiveness_trend_status: effectiveness_trend.effectiveness_trend_status,
            apply_readiness_status: apply_readiness_blocker.readiness_status,
            safety_status: entry.safety_status,
            paper_only: true,
        });
    }
    let stability_metrics = compute_governance_recommendation_stability_metrics(&ledger);
    let convergence_analysis = analyze_governance_recommendation_convergence(&ledger, &policy);
    let convergence_detail = compute_governance_recommendation_convergence_detail(&ledger, &policy);
    let effectiveness_trend = compute_governance_recommendation_effectiveness_trend(&ledger);
    let apply_readiness_blocker = evaluate_governance_policy_apply_readiness_blocker(
        &stability_metrics,
        &convergence_analysis,
        &effectiveness_trend,
        PaperGovernanceTrialSafetyGuardStatus::Preserved,
    );
    let review_packet = build_stable_governance_recommendation_review_packet(
        &convergence_detail,
        &effectiveness_trend,
        &apply_readiness_blocker,
    );
    let evidence_gap_summary = analyze_governance_recommendation_evidence_gaps(
        &stability_metrics,
        &convergence_detail,
        &effectiveness_trend,
    );
    let provisional_safety_guard = default_governance_recommendation_multi_run_safety_guard();
    let provisional_trial_gate = evaluate_governance_policy_apply_trial_gate(
        &review_packet,
        &stability_metrics,
        &convergence_detail,
        &provisional_safety_guard,
    );
    let mut result = GovernanceRecommendationMultiRunResult {
        run_id: config.run_id.clone(),
        requested_run_count: config.run_count,
        completed_run_count: per_run_results.len(),
        previous_ledger_entry_count,
        appended_entry_count: ledger
            .entry_count
            .saturating_sub(previous_ledger_entry_count),
        final_ledger_entry_count: ledger.entry_count,
        ledger,
        per_run_results,
        stability_metrics,
        convergence_analysis,
        convergence_detail,
        effectiveness_trend,
        review_packet,
        apply_readiness_blocker,
        apply_trial_gate: provisional_trial_gate,
        evidence_gap_summary,
        safety_guard: provisional_safety_guard,
        write_proof: None,
        owner_summary: None,
        run_status: PaperGovernanceTrialRunStatus::PassedWithWarnings,
        dry_run: config.dry_run,
        wrote_ledger: false,
        ledger_output_path: config.ledger_output_path.clone(),
        paper_only: true,
    };
    if !config.dry_run && config.append_ledger_entries {
        if let Some(path) = config.ledger_output_path.as_ref() {
            save_governance_recommendation_stability_ledger_to_local_json(
                Path::new(path),
                &result.ledger,
            )?;
            result.wrote_ledger = true;
        }
    }
    if !config.dry_run && result.wrote_ledger {
        if let Some(path) = config.ledger_output_path.as_ref() {
            result.write_proof = Some(prove_governance_recommendation_ledger_write(
                &GovernanceRecommendationStabilityRunResult {
                    run_id: result.run_id.clone(),
                    ledger: result.ledger.clone(),
                    appended_entry: result.ledger.entries.last().cloned(),
                    stability_metrics: result.stability_metrics.clone(),
                    convergence_analysis: result.convergence_analysis.clone(),
                    effectiveness_trend: result.effectiveness_trend.clone(),
                    apply_readiness_blocker: result.apply_readiness_blocker.clone(),
                    safety_guard: GovernanceRecommendationStabilitySafetyGuard {
                        actual_policy_apply_detected: false,
                        actual_score_mutation_detected: false,
                        actual_voice_mutation_detected: false,
                        committee_decision_mutation_detected: false,
                        chairman_decision_mutation_detected: false,
                        risk_governor_override_detected: false,
                        trade_signal_detected: false,
                        order_detected: false,
                        broker_order_account_detected: false,
                        unsafe_recommendation_marked_stable: false,
                        unstable_recommendation_marked_ready: false,
                        ledger_write_when_dry_run_detected: false,
                        guard_status: PaperGovernanceTrialSafetyGuardStatus::Preserved,
                        violations: Vec::new(),
                        paper_only: true,
                    },
                    write_proof: None,
                    owner_summary: None,
                    run_status: PaperGovernanceTrialRunStatus::PassedWithWarnings,
                    dry_run: result.dry_run,
                    wrote_ledger: result.wrote_ledger,
                    ledger_output_path: result.ledger_output_path.clone(),
                    paper_only: true,
                },
                Path::new(path),
            )?);
        }
    }
    result.safety_guard = evaluate_governance_recommendation_multi_run_safety(
        &result,
        batch_result,
        Some(batch_result),
    );
    result.apply_trial_gate = evaluate_governance_policy_apply_trial_gate(
        &result.review_packet,
        &result.stability_metrics,
        &result.convergence_detail,
        &result.safety_guard,
    );
    result.safety_guard = evaluate_governance_recommendation_multi_run_safety(
        &result,
        batch_result,
        Some(batch_result),
    );
    result.apply_trial_gate = evaluate_governance_policy_apply_trial_gate(
        &result.review_packet,
        &result.stability_metrics,
        &result.convergence_detail,
        &result.safety_guard,
    );
    if config.emit_owner_summary {
        result.owner_summary = Some(build_owner_governance_recommendation_review_summary(
            &result.review_packet,
            &result.apply_trial_gate,
            &result.evidence_gap_summary,
            result.completed_run_count,
            result.final_ledger_entry_count,
            result.safety_guard.guard_status,
        ));
    }
    result.run_status = if result.safety_guard.guard_status
        == PaperGovernanceTrialSafetyGuardStatus::Violated
        || matches!(
            result.apply_trial_gate.gate_status,
            GovernancePolicyApplyTrialGateStatus::BlockedBySafety
                | GovernancePolicyApplyTrialGateStatus::BlockedByRiskRegression
                | GovernancePolicyApplyTrialGateStatus::BlockedByVoiceConcentration
                | GovernancePolicyApplyTrialGateStatus::BlockedByInstability
        ) {
        PaperGovernanceTrialRunStatus::Failed
    } else if result.apply_trial_gate.gate_status
        == GovernancePolicyApplyTrialGateStatus::ReadyForPolicyApplyTrialDesign
    {
        PaperGovernanceTrialRunStatus::Passed
    } else {
        PaperGovernanceTrialRunStatus::PassedWithWarnings
    };
    if !config.dry_run {
        if let Some(path) = config.output_path.as_ref() {
            write_safe_json(Path::new(path), &result)?;
        }
    }
    Ok(result)
}

fn maybe_run_governance_recommendation_multi_run_for_batch_result(
    run_id: String,
    enabled: bool,
    dry_run: bool,
    run_count: usize,
    append_ledger_entries: bool,
    ledger_input_path: Option<&String>,
    ledger_output_path: Option<&String>,
    min_entries_required: usize,
    emit_owner_summary: bool,
    output_path: Option<&String>,
    batch_result: &mut BatchCommitteeCycleResult,
) -> Result<Option<GovernanceRecommendationMultiRunResult>, String> {
    if !governance_recommendation_multirun_requested_from_flags(
        enabled,
        dry_run,
        run_count,
        append_ledger_entries,
        ledger_input_path,
        ledger_output_path,
        output_path,
        emit_owner_summary,
    ) {
        return Ok(None);
    }
    let tuning_run_result = batch_result
        .governance_policy_feedback_tuning_run_result
        .clone()
        .ok_or_else(|| {
            "governance recommendation multirun requires governance policy feedback tuning run result"
                .to_string()
        })?;
    let result = run_governance_recommendation_multi_run_stability(
        &tuning_run_result,
        batch_result,
        &GovernanceRecommendationMultiRunConfig {
            run_id,
            enabled,
            run_count,
            min_entries_required,
            ledger_input_path: ledger_input_path.cloned(),
            ledger_output_path: ledger_output_path.cloned(),
            output_path: output_path.cloned(),
            dry_run,
            append_ledger_entries,
            emit_owner_summary,
            paper_only: true,
        },
    )?;
    batch_result.governance_recommendation_stability_ledger = Some(result.ledger.clone());
    batch_result.governance_recommendation_stability_metrics =
        Some(result.stability_metrics.clone());
    batch_result.governance_recommendation_convergence_analysis =
        Some(result.convergence_analysis.clone());
    batch_result.governance_recommendation_effectiveness_trend =
        Some(result.effectiveness_trend.clone());
    batch_result.governance_policy_apply_readiness_blocker =
        Some(result.apply_readiness_blocker.clone());
    batch_result.governance_recommendation_ledger_write_proof = result.write_proof.clone();
    batch_result.governance_recommendation_convergence_detail =
        Some(result.convergence_detail.clone());
    batch_result.stable_governance_recommendation_review_packet =
        Some(result.review_packet.clone());
    batch_result.governance_policy_apply_trial_gate = Some(result.apply_trial_gate.clone());
    batch_result.governance_recommendation_evidence_gap_summary =
        Some(result.evidence_gap_summary.clone());
    batch_result.owner_governance_recommendation_review_summary = result.owner_summary.clone();
    batch_result.governance_recommendation_multi_run_safety_guard =
        Some(result.safety_guard.clone());
    batch_result.governance_recommendation_multi_run_result = Some(result.clone());
    Ok(Some(result))
}

pub fn analyze_governance_recommendation_null_cause(
    multirun_result: &GovernanceRecommendationMultiRunResult,
    evidence_gap_summary: &GovernanceRecommendationEvidenceGapSummary,
) -> GovernanceRecommendationNullCauseSummary {
    let dominant_proposal_id = multirun_result
        .convergence_detail
        .dominant_recommended_proposal_id
        .clone();
    let null_detected = dominant_proposal_id.is_none();
    let mut causes = Vec::new();
    if null_detected {
        if multirun_result.convergence_detail.entry_count
            < multirun_result.convergence_detail.min_entries_required
        {
            causes.push(GovernanceRecommendationNullCauseRecord {
                record_id: "recommendation-null-insufficient-history".to_string(),
                run_id: Some(multirun_result.run_id.clone()),
                cause: GovernanceRecommendationNullCause::InsufficientHistory,
                severity: GovernanceRecommendationEvidenceGapSeverity::High,
                evidence_gap_kind: Some(GovernanceRecommendationEvidenceGapKind::TooFewEntries),
                reason: "recommendation history is shorter than the minimum required".to_string(),
                recommended_closure_action:
                    GovernanceRecommendationCollectionAction::CollectMorePaperCycles,
                paper_only: true,
            });
        }
        if multirun_result.convergence_detail.needs_more_evidence_count > 0 {
            causes.push(GovernanceRecommendationNullCauseRecord {
                record_id: "recommendation-null-needs-more-evidence".to_string(),
                run_id: Some(multirun_result.run_id.clone()),
                cause: GovernanceRecommendationNullCause::RepeatedNeedsMoreEvidence,
                severity: GovernanceRecommendationEvidenceGapSeverity::High,
                evidence_gap_kind: Some(
                    GovernanceRecommendationEvidenceGapKind::RepeatedNeedsMoreEvidence,
                ),
                reason: "needs-more-evidence repeated across recommendation history".to_string(),
                recommended_closure_action:
                    GovernanceRecommendationCollectionAction::ContinueMultirun,
                paper_only: true,
            });
        }
        if multirun_result
            .stability_metrics
            .no_safe_recommendation_count
            > 0
        {
            causes.push(GovernanceRecommendationNullCauseRecord {
                record_id: "recommendation-null-no-safe-proposal".to_string(),
                run_id: Some(multirun_result.run_id.clone()),
                cause: GovernanceRecommendationNullCause::NoSafeProposal,
                severity: GovernanceRecommendationEvidenceGapSeverity::High,
                evidence_gap_kind: None,
                reason: "no-safe recommendation appeared in recommendation history".to_string(),
                recommended_closure_action:
                    GovernanceRecommendationCollectionAction::KeepReviewOnly,
                paper_only: true,
            });
        }
        let mut proposal_counter = BTreeMap::<String, usize>::new();
        for proposal_id in multirun_result
            .stability_metrics
            .recommended_proposal_series
            .iter()
            .flatten()
        {
            increment_btree_counter(&mut proposal_counter, proposal_id.clone());
        }
        let max_count = proposal_counter.values().copied().max().unwrap_or(0);
        if max_count > 0
            && proposal_counter
                .values()
                .filter(|count| **count == max_count)
                .count()
                > 1
        {
            causes.push(GovernanceRecommendationNullCauseRecord {
                record_id: "recommendation-null-tied-scores".to_string(),
                run_id: Some(multirun_result.run_id.clone()),
                cause: GovernanceRecommendationNullCause::TiedProposalScores,
                severity: GovernanceRecommendationEvidenceGapSeverity::Medium,
                evidence_gap_kind: None,
                reason: "multiple proposals share the same dominant recommendation count"
                    .to_string(),
                recommended_closure_action:
                    GovernanceRecommendationCollectionAction::ContinueMultirun,
                paper_only: true,
            });
        }
        for gap in &evidence_gap_summary.gaps {
            let mapped_cause = match gap.gap_kind {
                GovernanceRecommendationEvidenceGapKind::LowRiskRegressionSignal => {
                    Some(GovernanceRecommendationNullCause::LowRiskEvidence)
                }
                GovernanceRecommendationEvidenceGapKind::WeakVoiceConcentrationSignal => {
                    Some(GovernanceRecommendationNullCause::LowVoiceEvidence)
                }
                GovernanceRecommendationEvidenceGapKind::NoTradeBiasAmbiguous => {
                    Some(GovernanceRecommendationNullCause::LowNoTradeBiasEvidence)
                }
                GovernanceRecommendationEvidenceGapKind::MissingRiskFirstEvidence => {
                    Some(GovernanceRecommendationNullCause::LowRiskFirstEvidence)
                }
                GovernanceRecommendationEvidenceGapKind::TooFewEntries
                | GovernanceRecommendationEvidenceGapKind::RepeatedNeedsMoreEvidence
                | GovernanceRecommendationEvidenceGapKind::UnstableRecommendation
                | GovernanceRecommendationEvidenceGapKind::Unknown => None,
            };
            if let Some(cause) = mapped_cause {
                causes.push(GovernanceRecommendationNullCauseRecord {
                    record_id: format!("recommendation-null-gap-{cause:?}"),
                    run_id: Some(multirun_result.run_id.clone()),
                    cause,
                    severity: gap.severity,
                    evidence_gap_kind: Some(gap.gap_kind),
                    reason: gap.reason.clone(),
                    recommended_closure_action: gap.recommended_collection_action,
                    paper_only: true,
                });
            }
        }
        if matches!(
            multirun_result.convergence_detail.convergence_status,
            GovernanceRecommendationConvergenceStatus::BlockedBySafety
        ) || matches!(
            multirun_result.apply_trial_gate.gate_status,
            GovernancePolicyApplyTrialGateStatus::BlockedBySafety
        ) {
            causes.push(GovernanceRecommendationNullCauseRecord {
                record_id: "recommendation-null-safety-block".to_string(),
                run_id: Some(multirun_result.run_id.clone()),
                cause: GovernanceRecommendationNullCause::SafetyBlock,
                severity: GovernanceRecommendationEvidenceGapSeverity::High,
                evidence_gap_kind: None,
                reason: "safety block prevents recommendation materialization".to_string(),
                recommended_closure_action:
                    GovernanceRecommendationCollectionAction::KeepReviewOnly,
                paper_only: true,
            });
        }
    }
    let high_severity_count = causes
        .iter()
        .filter(|record| record.severity == GovernanceRecommendationEvidenceGapSeverity::High)
        .count();
    let mut dominant_causes = causes.iter().map(|record| record.cause).collect::<Vec<_>>();
    dominant_causes.sort();
    dominant_causes.dedup();
    let mut recommended_closure_actions = causes
        .iter()
        .map(|record| record.recommended_closure_action)
        .collect::<Vec<_>>();
    recommended_closure_actions.sort();
    recommended_closure_actions.dedup();
    let summary_status = if !null_detected {
        GovernanceRecommendationNullCauseSummaryStatus::NoNull
    } else if dominant_causes.contains(&GovernanceRecommendationNullCause::SafetyBlock) {
        GovernanceRecommendationNullCauseSummaryStatus::BlockedBySafety
    } else if dominant_causes.contains(&GovernanceRecommendationNullCause::InsufficientHistory) {
        GovernanceRecommendationNullCauseSummaryStatus::NeedsMoreHistory
    } else if dominant_causes
        .contains(&GovernanceRecommendationNullCause::RepeatedNeedsMoreEvidence)
    {
        GovernanceRecommendationNullCauseSummaryStatus::NeedsMoreEvidence
    } else {
        GovernanceRecommendationNullCauseSummaryStatus::Actionable
    };
    GovernanceRecommendationNullCauseSummary {
        summary_id: "governance-recommendation-null-cause-summary".to_string(),
        dominant_proposal_id,
        null_detected,
        cause_count: causes.len(),
        high_severity_count,
        dominant_causes,
        recommended_closure_actions,
        summary_status,
        causes,
        paper_only: true,
    }
}

pub fn validate_governance_recommendation_support_evidence(
    record: &GovernanceRecommendationSupportEvidenceRecord,
) -> Result<(), String> {
    if !record.paper_only {
        return Err("governance recommendation support evidence must stay paper_only".to_string());
    }
    if record.reason.trim().is_empty() {
        return Err("governance recommendation support evidence reason is required".to_string());
    }
    if !record.support_score.is_finite() || record.support_score.abs() > 100.0 {
        return Err(
            "governance recommendation support evidence score must be finite and bounded"
                .to_string(),
        );
    }
    if matches!(
        record.evidence_kind,
        GovernanceRecommendationSupportEvidenceKind::ReviewRequired
    ) && !matches!(
        record.confidence,
        GovernanceRecommendationSupportEvidenceConfidence::ReviewRequired
    ) {
        return Err("ReviewRequired evidence must use ReviewRequired confidence".to_string());
    }
    if matches!(
        record.confidence,
        GovernanceRecommendationSupportEvidenceConfidence::ReviewRequired
    ) && record.support_score > 0.0
    {
        return Err("ReviewRequired evidence cannot count as positive final support".to_string());
    }
    Ok(())
}

pub fn build_governance_recommendation_support_evidence(
    multirun_result: &GovernanceRecommendationMultiRunResult,
    tuning_run_result: &GovernancePolicyFeedbackTuningRunResult,
    evidence_gap_summary: &GovernanceRecommendationEvidenceGapSummary,
) -> Result<GovernanceRecommendationSupportEvidenceSet, String> {
    let mut records = Vec::new();
    for proposal in &tuning_run_result.proposal_generation.candidates {
        let rank = tuning_run_result
            .ranking
            .ranked_proposals
            .iter()
            .find(|rank| rank.proposal_id == proposal.proposal_id);
        let ab_record = tuning_run_result
            .ab_comparison
            .records
            .iter()
            .find(|record| record.proposal_id == proposal.proposal_id);
        if let Some(record) = ab_record {
            if record.proposal_risk_alignment_worsening_rate
                < record.baseline_risk_alignment_worsening_rate
            {
                records.push(GovernanceRecommendationSupportEvidenceRecord {
                    evidence_id: format!("{}-risk-support", proposal.proposal_id),
                    source_run_id: Some(multirun_result.run_id.clone()),
                    source_ledger_entry_id: multirun_result.ledger.latest_entry_id.clone(),
                    proposal_id: Some(proposal.proposal_id.clone()),
                    evidence_kind:
                        GovernanceRecommendationSupportEvidenceKind::RiskRegressionImprovement,
                    member_id: None,
                    role: proposal.target_role,
                    confidence: GovernanceRecommendationSupportEvidenceConfidence::High,
                    support_score: 12.0,
                    reason: "proposal improved risk regression over baseline".to_string(),
                    paper_only: true,
                });
            }
            if record.proposal_voice_concentration_index < record.baseline_voice_concentration_index
            {
                records.push(GovernanceRecommendationSupportEvidenceRecord {
                    evidence_id: format!("{}-voice-support", proposal.proposal_id),
                    source_run_id: Some(multirun_result.run_id.clone()),
                    source_ledger_entry_id: multirun_result.ledger.latest_entry_id.clone(),
                    proposal_id: Some(proposal.proposal_id.clone()),
                    evidence_kind:
                        GovernanceRecommendationSupportEvidenceKind::VoiceConcentrationReduction,
                    member_id: None,
                    role: proposal.target_role,
                    confidence: GovernanceRecommendationSupportEvidenceConfidence::High,
                    support_score: 10.0,
                    reason: "proposal reduced voice concentration over baseline".to_string(),
                    paper_only: true,
                });
            }
            if record.proposal_no_trade_bias_rate < record.baseline_no_trade_bias_rate {
                records.push(GovernanceRecommendationSupportEvidenceRecord {
                    evidence_id: format!("{}-no-trade-support", proposal.proposal_id),
                    source_run_id: Some(multirun_result.run_id.clone()),
                    source_ledger_entry_id: multirun_result.ledger.latest_entry_id.clone(),
                    proposal_id: Some(proposal.proposal_id.clone()),
                    evidence_kind:
                        GovernanceRecommendationSupportEvidenceKind::NoTradeBiasReduction,
                    member_id: None,
                    role: proposal.target_role,
                    confidence: GovernanceRecommendationSupportEvidenceConfidence::Medium,
                    support_score: 6.0,
                    reason: "proposal reduced no-trade bias over baseline".to_string(),
                    paper_only: true,
                });
            }
        }
        if let Some(rank) = rank {
            if rank.evidence_balance_score >= 55.0 {
                records.push(GovernanceRecommendationSupportEvidenceRecord {
                    evidence_id: format!("{}-evidence-balance", proposal.proposal_id),
                    source_run_id: Some(multirun_result.run_id.clone()),
                    source_ledger_entry_id: multirun_result.ledger.latest_entry_id.clone(),
                    proposal_id: Some(proposal.proposal_id.clone()),
                    evidence_kind:
                        GovernanceRecommendationSupportEvidenceKind::EvidenceBalanceImprovement,
                    member_id: None,
                    role: proposal.target_role,
                    confidence: GovernanceRecommendationSupportEvidenceConfidence::Medium,
                    support_score: 5.0,
                    reason: "ranking preserved evidence balance".to_string(),
                    paper_only: true,
                });
            }
            if proposal.risk_first_preserved || rank.risk_first_score >= 55.0 {
                records.push(GovernanceRecommendationSupportEvidenceRecord {
                    evidence_id: format!("{}-risk-first", proposal.proposal_id),
                    source_run_id: Some(multirun_result.run_id.clone()),
                    source_ledger_entry_id: multirun_result.ledger.latest_entry_id.clone(),
                    proposal_id: Some(proposal.proposal_id.clone()),
                    evidence_kind: GovernanceRecommendationSupportEvidenceKind::RiskFirstPreserved,
                    member_id: None,
                    role: proposal.target_role,
                    confidence: GovernanceRecommendationSupportEvidenceConfidence::High,
                    support_score: 10.0,
                    reason: "proposal preserved risk-first constraints".to_string(),
                    paper_only: true,
                });
            }
            if rank.role_balance_score >= 50.0 {
                records.push(GovernanceRecommendationSupportEvidenceRecord {
                    evidence_id: format!("{}-role-balance", proposal.proposal_id),
                    source_run_id: Some(multirun_result.run_id.clone()),
                    source_ledger_entry_id: multirun_result.ledger.latest_entry_id.clone(),
                    proposal_id: Some(proposal.proposal_id.clone()),
                    evidence_kind:
                        GovernanceRecommendationSupportEvidenceKind::RoleBalancePreserved,
                    member_id: None,
                    role: proposal.target_role,
                    confidence: GovernanceRecommendationSupportEvidenceConfidence::Medium,
                    support_score: 4.0,
                    reason: "proposal retained enough role-balance support".to_string(),
                    paper_only: true,
                });
            }
            if multirun_result.safety_guard.guard_status
                == PaperGovernanceTrialSafetyGuardStatus::Preserved
            {
                records.push(GovernanceRecommendationSupportEvidenceRecord {
                    evidence_id: format!("{}-safety", proposal.proposal_id),
                    source_run_id: Some(multirun_result.run_id.clone()),
                    source_ledger_entry_id: multirun_result.ledger.latest_entry_id.clone(),
                    proposal_id: Some(proposal.proposal_id.clone()),
                    evidence_kind: GovernanceRecommendationSupportEvidenceKind::SafetyPreserved,
                    member_id: None,
                    role: proposal.target_role,
                    confidence: GovernanceRecommendationSupportEvidenceConfidence::High,
                    support_score: 15.0,
                    reason: "proposal stayed within paper-only safety constraints".to_string(),
                    paper_only: true,
                });
            }
            if rank.rank_status == GovernanceTuningProposalRankStatus::NeedsMoreEvidence
                || evidence_gap_summary.gap_status
                    == GovernanceRecommendationEvidenceGapStatus::NeedsMoreEvidence
            {
                records.push(GovernanceRecommendationSupportEvidenceRecord {
                    evidence_id: format!("{}-review-required", proposal.proposal_id),
                    source_run_id: Some(multirun_result.run_id.clone()),
                    source_ledger_entry_id: multirun_result.ledger.latest_entry_id.clone(),
                    proposal_id: Some(proposal.proposal_id.clone()),
                    evidence_kind: GovernanceRecommendationSupportEvidenceKind::ReviewRequired,
                    member_id: None,
                    role: proposal.target_role,
                    confidence: GovernanceRecommendationSupportEvidenceConfidence::ReviewRequired,
                    support_score: -10.0,
                    reason: "proposal still requires review before final support".to_string(),
                    paper_only: true,
                });
            }
        } else {
            records.push(GovernanceRecommendationSupportEvidenceRecord {
                evidence_id: format!("{}-insufficient-evidence", proposal.proposal_id),
                source_run_id: Some(multirun_result.run_id.clone()),
                source_ledger_entry_id: multirun_result.ledger.latest_entry_id.clone(),
                proposal_id: Some(proposal.proposal_id.clone()),
                evidence_kind: GovernanceRecommendationSupportEvidenceKind::InsufficientEvidence,
                member_id: None,
                role: proposal.target_role,
                confidence: GovernanceRecommendationSupportEvidenceConfidence::Low,
                support_score: -5.0,
                reason: "proposal ranking evidence was missing".to_string(),
                paper_only: true,
            });
        }
    }
    for record in &records {
        validate_governance_recommendation_support_evidence(record)?;
    }
    let high_confidence_count = records
        .iter()
        .filter(|record| {
            record.confidence == GovernanceRecommendationSupportEvidenceConfidence::High
        })
        .count();
    let medium_confidence_count = records
        .iter()
        .filter(|record| {
            record.confidence == GovernanceRecommendationSupportEvidenceConfidence::Medium
        })
        .count();
    let low_confidence_count = records
        .iter()
        .filter(|record| {
            record.confidence == GovernanceRecommendationSupportEvidenceConfidence::Low
        })
        .count();
    let review_required_count = records
        .iter()
        .filter(|record| {
            record.confidence == GovernanceRecommendationSupportEvidenceConfidence::ReviewRequired
        })
        .count();
    Ok(GovernanceRecommendationSupportEvidenceSet {
        evidence_set_id: "governance-recommendation-support-evidence-set".to_string(),
        record_count: records.len(),
        records,
        high_confidence_count,
        medium_confidence_count,
        low_confidence_count,
        review_required_count,
        paper_only: true,
    })
}

pub fn build_governance_recommendation_evidence_closure_queue(
    null_cause_summary: &GovernanceRecommendationNullCauseSummary,
    evidence_gap_summary: &GovernanceRecommendationEvidenceGapSummary,
) -> GovernanceRecommendationEvidenceClosureQueue {
    let mut tasks = Vec::new();
    for cause in &null_cause_summary.causes {
        let (task_kind, priority) = match cause.recommended_closure_action {
            GovernanceRecommendationCollectionAction::CollectRiskRegressionEvidence => (
                GovernanceRecommendationEvidenceClosureTaskKind::CollectRiskRegressionEvidence,
                GovernanceRecommendationEvidenceClosureTaskPriority::High,
            ),
            GovernanceRecommendationCollectionAction::CollectVoiceConcentrationEvidence => (
                GovernanceRecommendationEvidenceClosureTaskKind::CollectVoiceConcentrationEvidence,
                GovernanceRecommendationEvidenceClosureTaskPriority::High,
            ),
            GovernanceRecommendationCollectionAction::CollectNoTradeBiasEvidence => (
                GovernanceRecommendationEvidenceClosureTaskKind::CollectNoTradeBiasEvidence,
                GovernanceRecommendationEvidenceClosureTaskPriority::Normal,
            ),
            GovernanceRecommendationCollectionAction::CollectRiskFirstEvidence => (
                GovernanceRecommendationEvidenceClosureTaskKind::CollectRiskFirstEvidence,
                GovernanceRecommendationEvidenceClosureTaskPriority::High,
            ),
            GovernanceRecommendationCollectionAction::CollectRoleBalanceEvidence => (
                GovernanceRecommendationEvidenceClosureTaskKind::CollectRoleBalanceEvidence,
                GovernanceRecommendationEvidenceClosureTaskPriority::Normal,
            ),
            GovernanceRecommendationCollectionAction::CollectMorePaperCycles
            | GovernanceRecommendationCollectionAction::ContinueMultirun => (
                GovernanceRecommendationEvidenceClosureTaskKind::CollectMorePaperCycles,
                GovernanceRecommendationEvidenceClosureTaskPriority::Normal,
            ),
            GovernanceRecommendationCollectionAction::KeepReviewOnly => (
                GovernanceRecommendationEvidenceClosureTaskKind::ManualReviewNeeded,
                GovernanceRecommendationEvidenceClosureTaskPriority::High,
            ),
            GovernanceRecommendationCollectionAction::KeepObserving => (
                GovernanceRecommendationEvidenceClosureTaskKind::KeepObserving,
                GovernanceRecommendationEvidenceClosureTaskPriority::Low,
            ),
        };
        tasks.push(GovernanceRecommendationEvidenceClosureTask {
            task_id: format!("{}-{task_kind:?}", cause.record_id),
            task_kind,
            target_proposal_id: null_cause_summary.dominant_proposal_id.clone(),
            target_role: None,
            priority,
            reason: cause.reason.clone(),
            paper_only: true,
        });
    }
    for gap in &evidence_gap_summary.gaps {
        let (task_kind, priority) = match gap.recommended_collection_action {
            GovernanceRecommendationCollectionAction::CollectRiskRegressionEvidence => (
                GovernanceRecommendationEvidenceClosureTaskKind::CollectRiskRegressionEvidence,
                GovernanceRecommendationEvidenceClosureTaskPriority::High,
            ),
            GovernanceRecommendationCollectionAction::CollectVoiceConcentrationEvidence => (
                GovernanceRecommendationEvidenceClosureTaskKind::CollectVoiceConcentrationEvidence,
                GovernanceRecommendationEvidenceClosureTaskPriority::High,
            ),
            GovernanceRecommendationCollectionAction::CollectNoTradeBiasEvidence => (
                GovernanceRecommendationEvidenceClosureTaskKind::CollectNoTradeBiasEvidence,
                GovernanceRecommendationEvidenceClosureTaskPriority::Normal,
            ),
            GovernanceRecommendationCollectionAction::CollectRiskFirstEvidence => (
                GovernanceRecommendationEvidenceClosureTaskKind::CollectRiskFirstEvidence,
                GovernanceRecommendationEvidenceClosureTaskPriority::High,
            ),
            GovernanceRecommendationCollectionAction::CollectRoleBalanceEvidence => (
                GovernanceRecommendationEvidenceClosureTaskKind::CollectRoleBalanceEvidence,
                GovernanceRecommendationEvidenceClosureTaskPriority::Normal,
            ),
            GovernanceRecommendationCollectionAction::CollectMorePaperCycles
            | GovernanceRecommendationCollectionAction::ContinueMultirun => (
                GovernanceRecommendationEvidenceClosureTaskKind::CollectMorePaperCycles,
                GovernanceRecommendationEvidenceClosureTaskPriority::Normal,
            ),
            GovernanceRecommendationCollectionAction::KeepReviewOnly => (
                GovernanceRecommendationEvidenceClosureTaskKind::ManualReviewNeeded,
                GovernanceRecommendationEvidenceClosureTaskPriority::High,
            ),
            GovernanceRecommendationCollectionAction::KeepObserving => (
                GovernanceRecommendationEvidenceClosureTaskKind::KeepObserving,
                GovernanceRecommendationEvidenceClosureTaskPriority::Low,
            ),
        };
        tasks.push(GovernanceRecommendationEvidenceClosureTask {
            task_id: format!("{}-{task_kind:?}", gap.gap_id),
            task_kind,
            target_proposal_id: null_cause_summary.dominant_proposal_id.clone(),
            target_role: None,
            priority,
            reason: gap.reason.clone(),
            paper_only: true,
        });
    }
    tasks.sort_by(|left, right| left.task_id.cmp(&right.task_id));
    tasks.dedup_by(|left, right| left.task_id == right.task_id);
    let high_priority_count = tasks
        .iter()
        .filter(|task| task.priority == GovernanceRecommendationEvidenceClosureTaskPriority::High)
        .count();
    GovernanceRecommendationEvidenceClosureQueue {
        queue_id: "governance-recommendation-evidence-closure-queue".to_string(),
        task_count: tasks.len(),
        tasks,
        high_priority_count,
        paper_only: true,
    }
}

pub fn score_governance_proposal_with_support(
    proposal: &GovernanceTuningProposalCandidate,
    ranking: &GovernanceTuningProposalRankingResult,
    support_evidence_set: &GovernanceRecommendationSupportEvidenceSet,
) -> GovernanceProposalSupportScore {
    let base_rank_score = ranking
        .ranked_proposals
        .iter()
        .find(|rank| rank.proposal_id == proposal.proposal_id)
        .map(|rank| rank.total_score)
        .unwrap_or_default();
    let confidence_multiplier =
        |confidence: GovernanceRecommendationSupportEvidenceConfidence| match confidence {
            GovernanceRecommendationSupportEvidenceConfidence::High => 1.0,
            GovernanceRecommendationSupportEvidenceConfidence::Medium => 0.6,
            GovernanceRecommendationSupportEvidenceConfidence::Low => 0.25,
            GovernanceRecommendationSupportEvidenceConfidence::ReviewRequired => 0.0,
        };
    let records = support_evidence_set
        .records
        .iter()
        .filter(|record| record.proposal_id.as_deref() == Some(proposal.proposal_id.as_str()))
        .collect::<Vec<_>>();
    let support_by_kind = |kind: GovernanceRecommendationSupportEvidenceKind| -> f64 {
        records
            .iter()
            .filter(|record| record.evidence_kind == kind)
            .map(|record| record.support_score * confidence_multiplier(record.confidence))
            .sum()
    };
    let risk_regression_support =
        support_by_kind(GovernanceRecommendationSupportEvidenceKind::RiskRegressionImprovement);
    let voice_concentration_support =
        support_by_kind(GovernanceRecommendationSupportEvidenceKind::VoiceConcentrationReduction);
    let no_trade_bias_support =
        support_by_kind(GovernanceRecommendationSupportEvidenceKind::NoTradeBiasReduction);
    let risk_first_support =
        support_by_kind(GovernanceRecommendationSupportEvidenceKind::RiskFirstPreserved);
    let role_balance_support =
        support_by_kind(GovernanceRecommendationSupportEvidenceKind::RoleBalancePreserved);
    let safety_support =
        support_by_kind(GovernanceRecommendationSupportEvidenceKind::SafetyPreserved);
    let support_evidence_score = records
        .iter()
        .map(|record| record.support_score * confidence_multiplier(record.confidence))
        .sum::<f64>();
    let review_required_present = records.iter().any(|record| {
        record.confidence == GovernanceRecommendationSupportEvidenceConfidence::ReviewRequired
            || record.evidence_kind == GovernanceRecommendationSupportEvidenceKind::ReviewRequired
    });
    let total_support_adjusted_score = base_rank_score + support_evidence_score;
    let support_status = if safety_support <= 0.0 || risk_first_support <= 0.0 {
        GovernanceProposalSupportStatus::Unsupported
    } else if review_required_present || support_evidence_score < 8.0 {
        GovernanceProposalSupportStatus::WeakSupport
    } else if support_evidence_score >= 24.0
        && risk_regression_support > 0.0
        && voice_concentration_support > 0.0
    {
        GovernanceProposalSupportStatus::Supported
    } else if support_evidence_score >= 12.0 {
        GovernanceProposalSupportStatus::SupportedWithWarnings
    } else {
        GovernanceProposalSupportStatus::WeakSupport
    };
    GovernanceProposalSupportScore {
        proposal_id: proposal.proposal_id.clone(),
        base_rank_score,
        support_evidence_score,
        risk_regression_support,
        voice_concentration_support,
        no_trade_bias_support,
        risk_first_support,
        role_balance_support,
        safety_support,
        total_support_adjusted_score,
        support_status,
        paper_only: true,
    }
}

pub fn materialize_dominant_governance_recommendation_candidate(
    convergence_detail: &GovernanceRecommendationConvergenceDetail,
    proposal_scores: &[GovernanceProposalSupportScore],
    support_evidence_set: &GovernanceRecommendationSupportEvidenceSet,
    policy: &GovernanceRecommendationConvergencePolicy,
) -> DominantGovernanceRecommendationCandidate {
    let selected_from_convergence = convergence_detail
        .dominant_recommended_proposal_id
        .is_some();
    let proposal_id = convergence_detail
        .dominant_recommended_proposal_id
        .clone()
        .or_else(|| {
            proposal_scores
                .iter()
                .filter(|score| {
                    matches!(
                        score.support_status,
                        GovernanceProposalSupportStatus::Supported
                            | GovernanceProposalSupportStatus::SupportedWithWarnings
                    )
                })
                .max_by(|left, right| {
                    left.total_support_adjusted_score
                        .partial_cmp(&right.total_support_adjusted_score)
                        .unwrap_or(std::cmp::Ordering::Equal)
                        .then_with(|| right.proposal_id.cmp(&left.proposal_id))
                })
                .map(|score| score.proposal_id.clone())
        });
    let Some(proposal_id) = proposal_id else {
        return DominantGovernanceRecommendationCandidate {
            candidate_id: "dominant-governance-recommendation-candidate".to_string(),
            proposal_id: None,
            support_score: 0.0,
            dominant_ratio: convergence_detail.dominant_recommendation_ratio,
            trailing_streak_count: convergence_detail.trailing_streak_count,
            evidence_status: DominantGovernanceRecommendationEvidenceStatus::Insufficient,
            candidate_status: DominantGovernanceRecommendationCandidateStatus::NoCandidate,
            reason: "no dominant proposal was available to materialize".to_string(),
            policy_apply_allowed: false,
            paper_only: true,
        };
    };
    let proposal_score = proposal_scores
        .iter()
        .find(|score| score.proposal_id == proposal_id)
        .cloned();
    let review_required_present = support_evidence_set.records.iter().any(|record| {
        record.proposal_id.as_deref() == Some(proposal_id.as_str())
            && (record.confidence
                == GovernanceRecommendationSupportEvidenceConfidence::ReviewRequired
                || record.evidence_kind
                    == GovernanceRecommendationSupportEvidenceKind::ReviewRequired)
    });
    let Some(proposal_score) = proposal_score else {
        return DominantGovernanceRecommendationCandidate {
            candidate_id: format!("{proposal_id}-dominant-candidate"),
            proposal_id: Some(proposal_id),
            support_score: 0.0,
            dominant_ratio: convergence_detail.dominant_recommendation_ratio,
            trailing_streak_count: convergence_detail.trailing_streak_count,
            evidence_status: DominantGovernanceRecommendationEvidenceStatus::Insufficient,
            candidate_status: DominantGovernanceRecommendationCandidateStatus::NoCandidate,
            reason: "dominant proposal did not have support scoring".to_string(),
            policy_apply_allowed: false,
            paper_only: true,
        };
    };
    let evidence_status = if proposal_score.support_status
        == GovernanceProposalSupportStatus::Supported
        && !review_required_present
    {
        DominantGovernanceRecommendationEvidenceStatus::Sufficient
    } else if proposal_score.support_status
        == GovernanceProposalSupportStatus::SupportedWithWarnings
        && !review_required_present
    {
        DominantGovernanceRecommendationEvidenceStatus::SufficientWithWarnings
    } else if proposal_score.support_status == GovernanceProposalSupportStatus::WeakSupport {
        DominantGovernanceRecommendationEvidenceStatus::Weak
    } else {
        DominantGovernanceRecommendationEvidenceStatus::Insufficient
    };
    let (candidate_status, reason) = if matches!(
        convergence_detail.convergence_status,
        GovernanceRecommendationConvergenceStatus::BlockedBySafety
    ) || proposal_score.safety_support <= 0.0
    {
        (
            DominantGovernanceRecommendationCandidateStatus::BlockedBySafety,
            "candidate lacks safety support for materialization".to_string(),
        )
    } else if selected_from_convergence
        && convergence_detail.dominant_recommendation_ratio
            < policy.min_dominant_recommendation_ratio
    {
        (
            DominantGovernanceRecommendationCandidateStatus::NeedsMoreEvidence,
            "dominant recommendation ratio is still below the materialization threshold"
                .to_string(),
        )
    } else if !selected_from_convergence {
        match evidence_status {
            DominantGovernanceRecommendationEvidenceStatus::Sufficient
            | DominantGovernanceRecommendationEvidenceStatus::SufficientWithWarnings => (
                DominantGovernanceRecommendationCandidateStatus::MaterializedWithWarnings,
                "support-aware ranking materialized a review-only candidate while ledger dominance is still null"
                    .to_string(),
            ),
            DominantGovernanceRecommendationEvidenceStatus::Weak
            | DominantGovernanceRecommendationEvidenceStatus::Insufficient => (
                DominantGovernanceRecommendationCandidateStatus::NoCandidate,
                "ledger dominance is null and support evidence is still insufficient".to_string(),
            ),
        }
    } else {
        match evidence_status {
            DominantGovernanceRecommendationEvidenceStatus::Sufficient => (
                DominantGovernanceRecommendationCandidateStatus::Materialized,
                "dominant proposal was materialized with sufficient support".to_string(),
            ),
            DominantGovernanceRecommendationEvidenceStatus::SufficientWithWarnings => (
                DominantGovernanceRecommendationCandidateStatus::MaterializedWithWarnings,
                "dominant proposal was materialized with warnings".to_string(),
            ),
            DominantGovernanceRecommendationEvidenceStatus::Weak
            | DominantGovernanceRecommendationEvidenceStatus::Insufficient => (
                DominantGovernanceRecommendationCandidateStatus::NeedsMoreEvidence,
                "dominant proposal still needs more support evidence".to_string(),
            ),
        }
    };
    DominantGovernanceRecommendationCandidate {
        candidate_id: format!("{proposal_id}-dominant-candidate"),
        proposal_id: Some(proposal_id),
        support_score: proposal_score.total_support_adjusted_score,
        dominant_ratio: convergence_detail.dominant_recommendation_ratio,
        trailing_streak_count: convergence_detail.trailing_streak_count,
        evidence_status,
        candidate_status,
        reason,
        policy_apply_allowed: false,
        paper_only: true,
    }
}

pub fn evaluate_governance_review_packet_completeness(
    review_packet: &StableGovernanceRecommendationReviewPacket,
    dominant_candidate: &DominantGovernanceRecommendationCandidate,
    evidence_gap_summary: &GovernanceRecommendationEvidenceGapSummary,
) -> GovernanceReviewPacketCompletenessGate {
    let mut blockers = Vec::new();
    let mut warnings = review_packet.warnings.clone();
    let gate_status = if matches!(
        dominant_candidate.candidate_status,
        DominantGovernanceRecommendationCandidateStatus::BlockedBySafety
    ) {
        blockers.push("dominant candidate is blocked by safety".to_string());
        GovernanceReviewPacketCompletenessGateStatus::BlockedBySafety
    } else if evidence_gap_summary.gap_status
        == GovernanceRecommendationEvidenceGapStatus::InsufficientHistory
    {
        blockers.push("review packet still needs more history".to_string());
        GovernanceReviewPacketCompletenessGateStatus::NeedsMoreHistory
    } else if matches!(
        dominant_candidate.candidate_status,
        DominantGovernanceRecommendationCandidateStatus::NeedsMoreEvidence
            | DominantGovernanceRecommendationCandidateStatus::NoCandidate
    ) || matches!(
        evidence_gap_summary.gap_status,
        GovernanceRecommendationEvidenceGapStatus::NeedsMoreEvidence
            | GovernanceRecommendationEvidenceGapStatus::HasGaps
    ) {
        blockers.push("review packet still needs more evidence".to_string());
        GovernanceReviewPacketCompletenessGateStatus::NeedsMoreEvidence
    } else if matches!(
        dominant_candidate.candidate_status,
        DominantGovernanceRecommendationCandidateStatus::Materialized
    ) && review_packet.review_status
        == StableGovernanceRecommendationReviewPacketStatus::ReadyForOwnerReview
    {
        GovernanceReviewPacketCompletenessGateStatus::CompleteForReview
    } else {
        warnings.push("review packet is complete only with warnings".to_string());
        GovernanceReviewPacketCompletenessGateStatus::CompleteForReviewWithWarnings
    };
    GovernanceReviewPacketCompletenessGate {
        gate_id: "governance-review-packet-completeness-gate".to_string(),
        review_packet_status: review_packet.review_status,
        dominant_candidate_status: dominant_candidate.candidate_status,
        support_evidence_status: dominant_candidate.evidence_status,
        evidence_gap_status: evidence_gap_summary.gap_status,
        owner_summary_ready: matches!(
            gate_status,
            GovernanceReviewPacketCompletenessGateStatus::CompleteForReview
                | GovernanceReviewPacketCompletenessGateStatus::CompleteForReviewWithWarnings
        ),
        packet_complete: matches!(
            gate_status,
            GovernanceReviewPacketCompletenessGateStatus::CompleteForReview
                | GovernanceReviewPacketCompletenessGateStatus::CompleteForReviewWithWarnings
        ),
        gate_status,
        blockers,
        warnings,
        paper_only: true,
    }
}

fn default_governance_recommendation_materialization_safety_guard()
-> GovernanceRecommendationMaterializationSafetyGuard {
    GovernanceRecommendationMaterializationSafetyGuard {
        policy_apply_allowed_true_detected: false,
        actual_policy_apply_detected: false,
        actual_score_mutation_detected: false,
        actual_voice_mutation_detected: false,
        committee_decision_mutation_detected: false,
        chairman_decision_mutation_detected: false,
        risk_governor_override_detected: false,
        trade_signal_detected: false,
        order_detected: false,
        broker_order_account_detected: false,
        weak_evidence_materialized_detected: false,
        unsafe_candidate_materialized_detected: false,
        guard_status: PaperGovernanceTrialSafetyGuardStatus::Preserved,
        violations: Vec::new(),
        paper_only: true,
    }
}

pub fn evaluate_governance_recommendation_materialization_safety(
    materialization_result: &GovernanceRecommendationMaterializationRunResult,
    batch_before: &BatchCommitteeCycleResult,
    batch_after: Option<&BatchCommitteeCycleResult>,
) -> GovernanceRecommendationMaterializationSafetyGuard {
    let batch_after = batch_after.unwrap_or(batch_before);
    let actual_score_snapshot = |store: Option<&PaperGovernanceTrialStateStore>| {
        store.map(|store| {
            store
                .member_states
                .iter()
                .map(|state| (state.member_id.clone(), state.actual_score_snapshot))
                .collect::<BTreeMap<_, _>>()
        })
    };
    let actual_voice_snapshot = |store: Option<&PaperGovernanceTrialStateStore>| {
        store.map(|store| {
            store
                .member_states
                .iter()
                .map(|state| (state.member_id.clone(), state.actual_voice_snapshot))
                .collect::<BTreeMap<_, _>>()
        })
    };
    let risk_snapshot = |decisions: &[ChairmanDecision]| {
        decisions
            .iter()
            .map(|decision| (decision.decision_id.clone(), decision.risk_governor_status))
            .collect::<BTreeMap<_, _>>()
    };
    let mut guard = default_governance_recommendation_materialization_safety_guard();
    guard.policy_apply_allowed_true_detected = materialization_result
        .dominant_candidate
        .policy_apply_allowed
        || materialization_result
            .owner_summary
            .as_ref()
            .map(|summary| summary.policy_apply_allowed)
            .unwrap_or(false);
    guard.actual_policy_apply_detected = batch_before.conservative_voice_tuning_v2_policy
        != batch_after.conservative_voice_tuning_v2_policy
        || batch_before.chairman_role_voice_floor_policy
            != batch_after.chairman_role_voice_floor_policy;
    guard.actual_score_mutation_detected =
        actual_score_snapshot(batch_before.paper_governance_trial_state_store.as_ref())
            != actual_score_snapshot(batch_after.paper_governance_trial_state_store.as_ref());
    guard.actual_voice_mutation_detected =
        actual_voice_snapshot(batch_before.paper_governance_trial_state_store.as_ref())
            != actual_voice_snapshot(batch_after.paper_governance_trial_state_store.as_ref());
    guard.committee_decision_mutation_detected =
        batch_before.committee_sessions != batch_after.committee_sessions;
    guard.chairman_decision_mutation_detected =
        batch_before.chairman_decisions != batch_after.chairman_decisions;
    guard.risk_governor_override_detected = risk_snapshot(&batch_before.chairman_decisions)
        != risk_snapshot(&batch_after.chairman_decisions);
    guard.trade_signal_detected = value_contains_debug_marker(
        &batch_after.committee_sessions,
        &["trade-signal".to_string()],
    ) && !value_contains_debug_marker(
        &batch_before.committee_sessions,
        &["trade-signal".to_string()],
    );
    guard.order_detected =
        value_contains_debug_marker(&batch_after.event_queue, &["order".to_string()])
            && !value_contains_debug_marker(&batch_before.event_queue, &["order".to_string()]);
    guard.broker_order_account_detected = value_contains_debug_marker(
        batch_after,
        &[
            "broker".to_string(),
            "order".to_string(),
            "account".to_string(),
        ],
    ) && !value_contains_debug_marker(
        batch_before,
        &[
            "broker".to_string(),
            "order".to_string(),
            "account".to_string(),
        ],
    );
    guard.weak_evidence_materialized_detected = matches!(
        materialization_result.dominant_candidate.candidate_status,
        DominantGovernanceRecommendationCandidateStatus::Materialized
            | DominantGovernanceRecommendationCandidateStatus::MaterializedWithWarnings
    ) && matches!(
        materialization_result.dominant_candidate.evidence_status,
        DominantGovernanceRecommendationEvidenceStatus::Weak
            | DominantGovernanceRecommendationEvidenceStatus::Insufficient
    );
    guard.unsafe_candidate_materialized_detected = matches!(
        materialization_result.dominant_candidate.candidate_status,
        DominantGovernanceRecommendationCandidateStatus::Materialized
            | DominantGovernanceRecommendationCandidateStatus::MaterializedWithWarnings
    ) && !matches!(
        materialization_result
            .review_packet_completeness_gate
            .gate_status,
        GovernanceReviewPacketCompletenessGateStatus::CompleteForReview
            | GovernanceReviewPacketCompletenessGateStatus::CompleteForReviewWithWarnings
    );
    if guard.policy_apply_allowed_true_detected {
        guard
            .violations
            .push("materialization opened policy_apply_allowed".to_string());
    }
    if guard.actual_policy_apply_detected {
        guard
            .violations
            .push("materialization triggered actual policy apply".to_string());
    }
    if guard.actual_score_mutation_detected {
        guard
            .violations
            .push("materialization mutated actual score".to_string());
    }
    if guard.actual_voice_mutation_detected {
        guard
            .violations
            .push("materialization mutated actual voice".to_string());
    }
    if guard.committee_decision_mutation_detected {
        guard
            .violations
            .push("materialization mutated committee decision".to_string());
    }
    if guard.chairman_decision_mutation_detected {
        guard
            .violations
            .push("materialization mutated chairman decision".to_string());
    }
    if guard.risk_governor_override_detected {
        guard
            .violations
            .push("materialization overrode Risk Governor".to_string());
    }
    if guard.trade_signal_detected {
        guard
            .violations
            .push("materialization created trade signal".to_string());
    }
    if guard.order_detected {
        guard
            .violations
            .push("materialization created order".to_string());
    }
    if guard.broker_order_account_detected {
        guard
            .violations
            .push("materialization touched broker/order/account".to_string());
    }
    if guard.weak_evidence_materialized_detected {
        guard
            .violations
            .push("weak evidence was materialized as dominant candidate".to_string());
    }
    if guard.unsafe_candidate_materialized_detected {
        guard
            .violations
            .push("unsafe candidate was materialized".to_string());
    }
    guard.guard_status = if guard.violations.is_empty() {
        PaperGovernanceTrialSafetyGuardStatus::Preserved
    } else {
        PaperGovernanceTrialSafetyGuardStatus::Violated
    };
    guard
}

pub fn build_owner_governance_recommendation_materialization_summary(
    run_result: &GovernanceRecommendationMaterializationRunResult,
) -> OwnerGovernanceRecommendationMaterializationSummary {
    OwnerGovernanceRecommendationMaterializationSummary {
        summary_id: "owner-governance-recommendation-materialization-summary".to_string(),
        null_detected: run_result.null_cause_summary.null_detected,
        dominant_candidate_status: run_result.dominant_candidate.candidate_status,
        dominant_proposal_id: run_result.dominant_candidate.proposal_id.clone(),
        support_evidence_status: run_result.dominant_candidate.evidence_status,
        evidence_closure_task_count: run_result.evidence_closure_queue.task_count,
        review_packet_gate_status: run_result.review_packet_completeness_gate.gate_status,
        message: "Recommendation evidence was reviewed. Dominant proposal was materialized only if support was sufficient. This remains review-only. No policy, score, voice, decision, or trading behavior changed."
            .to_string(),
        review_only: true,
        recommendation_only: true,
        policy_apply_allowed: false,
        no_actual_policy_apply: true,
        no_score_mutation: true,
        no_voice_mutation: true,
        no_committee_decision_change: true,
        no_risk_override: true,
        not_trade_signal: true,
        paper_only: true,
    }
}

fn normalize_support_evidence_set(
    evidence_set_id: String,
    mut records: Vec<GovernanceRecommendationSupportEvidenceRecord>,
) -> GovernanceRecommendationSupportEvidenceSet {
    records.sort_by(|left, right| left.evidence_id.cmp(&right.evidence_id));
    let high_confidence_count = records
        .iter()
        .filter(|record| {
            record.confidence == GovernanceRecommendationSupportEvidenceConfidence::High
        })
        .count();
    let medium_confidence_count = records
        .iter()
        .filter(|record| {
            record.confidence == GovernanceRecommendationSupportEvidenceConfidence::Medium
        })
        .count();
    let low_confidence_count = records
        .iter()
        .filter(|record| {
            record.confidence == GovernanceRecommendationSupportEvidenceConfidence::Low
        })
        .count();
    let review_required_count = records
        .iter()
        .filter(|record| {
            record.confidence == GovernanceRecommendationSupportEvidenceConfidence::ReviewRequired
        })
        .count();
    GovernanceRecommendationSupportEvidenceSet {
        evidence_set_id,
        record_count: records.len(),
        records,
        high_confidence_count,
        medium_confidence_count,
        low_confidence_count,
        review_required_count,
        paper_only: true,
    }
}

fn normalized_json_key_marker(text: &str) -> String {
    text.chars()
        .filter_map(|ch| {
            if ch.is_ascii_alphanumeric() {
                Some(ch.to_ascii_lowercase())
            } else {
                None
            }
        })
        .collect()
}

fn json_value_has_key_containing(value: &serde_json::Value, needle: &str) -> bool {
    let needle_lower = needle.to_ascii_lowercase();
    let needle_marker = normalized_json_key_marker(needle);
    match value {
        serde_json::Value::Object(map) => map.iter().any(|(key, value)| {
            let key_lower = key.to_ascii_lowercase();
            let key_marker = normalized_json_key_marker(key);
            key_lower.contains(&needle_lower)
                || key_marker.contains(&needle_marker)
                || json_value_has_key_containing(value, needle)
        }),
        serde_json::Value::Array(values) => values
            .iter()
            .any(|value| json_value_has_key_containing(value, needle)),
        _ => false,
    }
}

fn json_value_has_forbidden_support_fixture_key(value: &serde_json::Value) -> bool {
    [
        "policy_apply",
        "broker",
        "account",
        "order",
        "live",
        "real_pnl",
    ]
    .iter()
    .any(|needle| json_value_has_key_containing(value, needle))
}

fn support_fixture_text_has_forbidden_terms(text: &str) -> bool {
    let lower = text.to_ascii_lowercase();
    let normalized = normalized_json_key_marker(text);
    [
        "broker",
        "account",
        "order",
        "trade signal",
        "live execution",
        "live trading",
        "real pnl",
        "policy apply",
    ]
    .iter()
    .any(|term| lower.contains(term) || normalized.contains(&normalized_json_key_marker(term)))
}

pub fn load_governance_recommendation_support_evidence_fixture_from_local_json(
    path: &Path,
) -> Result<GovernanceRecommendationSupportEvidenceFixtureFile, String> {
    validate_local_json_path(
        path,
        "governance recommendation support evidence fixture path",
    )?;
    let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
    let value: serde_json::Value = serde_json::from_str(&text).map_err(|err| err.to_string())?;
    if json_value_has_forbidden_support_fixture_key(&value) {
        return Err(
            "support evidence fixture must not include broker/order/account/live, real PnL, or policy apply fields"
                .to_string(),
        );
    }
    let fixture: GovernanceRecommendationSupportEvidenceFixtureFile =
        serde_json::from_value(value).map_err(|err| err.to_string())?;
    validate_governance_recommendation_support_evidence_fixture(&fixture)?;
    Ok(fixture)
}

pub fn validate_governance_recommendation_support_evidence_fixture(
    fixture: &GovernanceRecommendationSupportEvidenceFixtureFile,
) -> Result<(), String> {
    if !fixture.paper_only {
        return Err("support evidence fixture must stay paper_only".to_string());
    }
    if fixture.fixture_id.trim().is_empty() || fixture.schema_version.trim().is_empty() {
        return Err("support evidence fixture requires fixture_id and schema_version".to_string());
    }
    for record in &fixture.records {
        if !record.paper_only {
            return Err("support evidence fixture records must stay paper_only".to_string());
        }
        if record.fixture_record_id.trim().is_empty() || record.reason.trim().is_empty() {
            return Err("support evidence fixture records require id and reason".to_string());
        }
        if !record.support_score.is_finite() || record.support_score.abs() > 100.0 {
            return Err(
                "support evidence fixture support_score must be finite and bounded".to_string(),
            );
        }
        if record.confidence == GovernanceRecommendationSupportEvidenceConfidence::ReviewRequired
            && record.support_score > 0.0
        {
            return Err("ReviewRequired fixture evidence cannot become final support".to_string());
        }
        if record.evidence_kind == GovernanceRecommendationSupportEvidenceKind::ReviewRequired
            && record.confidence
                != GovernanceRecommendationSupportEvidenceConfidence::ReviewRequired
        {
            return Err(
                "ReviewRequired fixture evidence must use ReviewRequired confidence".to_string(),
            );
        }
        for text in [
            record.fixture_record_id.as_str(),
            record.proposal_id.as_deref().unwrap_or_default(),
            record.member_id.as_deref().unwrap_or_default(),
            record.reason.as_str(),
        ] {
            if support_fixture_text_has_forbidden_terms(text) {
                return Err("support evidence fixture contains broker/order/account or live execution terms".to_string());
            }
        }
    }
    Ok(())
}

pub fn convert_support_fixture_to_evidence_set(
    fixture: &GovernanceRecommendationSupportEvidenceFixtureFile,
) -> Result<GovernanceRecommendationSupportEvidenceSet, String> {
    validate_governance_recommendation_support_evidence_fixture(fixture)?;
    let mut records = Vec::new();
    for record in &fixture.records {
        let evidence = GovernanceRecommendationSupportEvidenceRecord {
            evidence_id: record.fixture_record_id.clone(),
            source_run_id: Some(fixture.fixture_id.clone()),
            source_ledger_entry_id: None,
            proposal_id: record.proposal_id.clone(),
            evidence_kind: record.evidence_kind,
            member_id: record.member_id.clone(),
            role: record.role,
            confidence: record.confidence,
            support_score: record.support_score,
            reason: record.reason.clone(),
            paper_only: true,
        };
        validate_governance_recommendation_support_evidence(&evidence)?;
        records.push(evidence);
    }
    Ok(normalize_support_evidence_set(
        format!("{}-support-evidence-set", fixture.fixture_id),
        records,
    ))
}

pub fn merge_governance_support_evidence(
    existing_evidence_set: &GovernanceRecommendationSupportEvidenceSet,
    fixture_evidence_set: &GovernanceRecommendationSupportEvidenceSet,
) -> GovernanceRecommendationSupportEvidenceMergeResult {
    let mut merged = existing_evidence_set.records.clone();
    let mut seen = merged
        .iter()
        .map(|record| {
            format!(
                "{}|{:?}|{:?}|{:?}|{:?}",
                record.evidence_id,
                record.proposal_id,
                record.evidence_kind,
                record.role,
                record.confidence
            )
        })
        .collect::<BTreeSet<_>>();
    let mut duplicate_count = 0usize;
    let mut rejected_count = 0usize;
    for record in &fixture_evidence_set.records {
        if validate_governance_recommendation_support_evidence(record).is_err() {
            rejected_count += 1;
            continue;
        }
        let key = format!(
            "{}|{:?}|{:?}|{:?}|{:?}",
            record.evidence_id,
            record.proposal_id,
            record.evidence_kind,
            record.role,
            record.confidence
        );
        if seen.insert(key) {
            merged.push(record.clone());
        } else {
            duplicate_count += 1;
        }
    }
    let merged_evidence_set = normalize_support_evidence_set(
        "merged-governance-support-evidence-set".to_string(),
        merged,
    );
    let merge_status = if rejected_count > 0 {
        GovernanceRecommendationSupportEvidenceMergeStatus::MergedWithWarnings
    } else if merged_evidence_set.record_count == existing_evidence_set.record_count {
        GovernanceRecommendationSupportEvidenceMergeStatus::NoChange
    } else {
        GovernanceRecommendationSupportEvidenceMergeStatus::Merged
    };
    GovernanceRecommendationSupportEvidenceMergeResult {
        existing_count: existing_evidence_set.record_count,
        fixture_count: fixture_evidence_set.record_count,
        merged_count: merged_evidence_set.record_count,
        duplicate_count,
        rejected_count,
        merged_evidence_set,
        merge_status,
        paper_only: true,
    }
}

pub fn default_governance_recommendation_materialization_support_policy()
-> GovernanceRecommendationMaterializationSupportPolicy {
    GovernanceRecommendationMaterializationSupportPolicy {
        policy_id: "default-governance-recommendation-materialization-support-policy".to_string(),
        min_total_support_score: 40.0,
        min_high_or_medium_evidence_count: 4,
        require_risk_first_support: true,
        require_safety_support: true,
        require_role_balance_support: true,
        allow_review_required_support: false,
        allow_low_confidence_only_materialization: false,
        allow_policy_apply: false,
        paper_only: true,
    }
}

pub fn validate_governance_recommendation_materialization_support_policy(
    policy: &GovernanceRecommendationMaterializationSupportPolicy,
) -> Result<(), String> {
    if policy.policy_id.trim().is_empty() {
        return Err("materialization support policy id is required".to_string());
    }
    if !policy.paper_only || policy.allow_policy_apply {
        return Err(
            "materialization support policy must stay paper_only and disallow policy apply"
                .to_string(),
        );
    }
    if !policy.min_total_support_score.is_finite() || policy.min_total_support_score <= 0.0 {
        return Err(
            "materialization support policy support threshold must be positive".to_string(),
        );
    }
    if policy.min_high_or_medium_evidence_count == 0 {
        return Err(
            "materialization support policy must require medium/high support evidence".to_string(),
        );
    }
    if !policy.require_safety_support
        || !policy.require_risk_first_support
        || !policy.require_role_balance_support
    {
        return Err(
            "materialization support policy must require safety, risk-first, and role-balance support"
                .to_string(),
        );
    }
    if policy.allow_review_required_support {
        return Err(
            "materialization support policy cannot allow ReviewRequired final support".to_string(),
        );
    }
    if policy.allow_low_confidence_only_materialization {
        return Err(
            "materialization support policy cannot allow low-confidence-only materialization"
                .to_string(),
        );
    }
    Ok(())
}

fn proposal_support_facts(
    proposal_id: &str,
    support_evidence_set: &GovernanceRecommendationSupportEvidenceSet,
) -> (
    usize,
    usize,
    bool,
    bool,
    bool,
    bool,
    bool,
    Vec<GovernanceRecommendationMissingRequiredSupport>,
) {
    let records = support_evidence_set
        .records
        .iter()
        .filter(|record| record.proposal_id.as_deref() == Some(proposal_id))
        .collect::<Vec<_>>();
    let high_or_medium_count = records
        .iter()
        .filter(|record| {
            matches!(
                record.confidence,
                GovernanceRecommendationSupportEvidenceConfidence::High
                    | GovernanceRecommendationSupportEvidenceConfidence::Medium
            ) && record.support_score > 0.0
                && record.evidence_kind
                    != GovernanceRecommendationSupportEvidenceKind::ReviewRequired
        })
        .count();
    let positive_count = records
        .iter()
        .filter(|record| {
            record.support_score > 0.0
                && record.evidence_kind
                    != GovernanceRecommendationSupportEvidenceKind::ReviewRequired
                && record.confidence
                    != GovernanceRecommendationSupportEvidenceConfidence::ReviewRequired
        })
        .count();
    let risk_first_support_present = records.iter().any(|record| {
        record.evidence_kind == GovernanceRecommendationSupportEvidenceKind::RiskFirstPreserved
            && record.support_score > 0.0
            && record.confidence
                != GovernanceRecommendationSupportEvidenceConfidence::ReviewRequired
    });
    let safety_support_present = records.iter().any(|record| {
        record.evidence_kind == GovernanceRecommendationSupportEvidenceKind::SafetyPreserved
            && record.support_score > 0.0
            && record.confidence
                != GovernanceRecommendationSupportEvidenceConfidence::ReviewRequired
    });
    let role_balance_support_present = records.iter().any(|record| {
        record.evidence_kind == GovernanceRecommendationSupportEvidenceKind::RoleBalancePreserved
            && record.support_score > 0.0
            && record.confidence
                != GovernanceRecommendationSupportEvidenceConfidence::ReviewRequired
    });
    let review_required_present = records.iter().any(|record| {
        record.evidence_kind == GovernanceRecommendationSupportEvidenceKind::ReviewRequired
            || record.confidence
                == GovernanceRecommendationSupportEvidenceConfidence::ReviewRequired
    });
    let low_confidence_only = positive_count > 0 && high_or_medium_count == 0;
    let mut missing = Vec::new();
    if !risk_first_support_present {
        missing.push(GovernanceRecommendationMissingRequiredSupport::RiskFirstSupport);
    }
    if !safety_support_present {
        missing.push(GovernanceRecommendationMissingRequiredSupport::SafetySupport);
    }
    if !role_balance_support_present {
        missing.push(GovernanceRecommendationMissingRequiredSupport::RoleBalanceSupport);
    }
    if high_or_medium_count == 0 {
        missing.push(GovernanceRecommendationMissingRequiredSupport::MediumOrHighConfidenceSupport);
    }
    (
        records.len(),
        high_or_medium_count,
        risk_first_support_present,
        safety_support_present,
        role_balance_support_present,
        review_required_present,
        low_confidence_only,
        missing,
    )
}

pub fn materialize_dominant_governance_recommendation_candidate_v2(
    convergence_detail: &GovernanceRecommendationConvergenceDetail,
    proposal_scores: &[GovernanceProposalSupportScore],
    support_evidence_set: &GovernanceRecommendationSupportEvidenceSet,
    support_policy: &GovernanceRecommendationMaterializationSupportPolicy,
) -> DominantGovernanceRecommendationCandidateV2 {
    if validate_governance_recommendation_materialization_support_policy(support_policy).is_err() {
        return DominantGovernanceRecommendationCandidateV2 {
            candidate_id: "dominant-governance-recommendation-candidate-v2".to_string(),
            proposal_id: None,
            support_score: 0.0,
            support_evidence_count: 0,
            support_high_or_medium_evidence_count: 0,
            risk_first_support_present: false,
            safety_support_present: false,
            role_balance_support_present: false,
            dominant_ratio: Some(convergence_detail.dominant_recommendation_ratio),
            trailing_streak_count: Some(convergence_detail.trailing_streak_count),
            evidence_status: DominantGovernanceRecommendationEvidenceStatus::Insufficient,
            candidate_status: DominantGovernanceRecommendationCandidateStatus::NoCandidate,
            reason: "materialization support policy is invalid".to_string(),
            policy_apply_allowed: false,
            review_only: true,
            paper_only: true,
        };
    }
    let selected_score = convergence_detail
        .dominant_recommended_proposal_id
        .as_ref()
        .and_then(|proposal_id| {
            proposal_scores
                .iter()
                .find(|score| &score.proposal_id == proposal_id)
        })
        .or_else(|| {
            proposal_scores.iter().max_by(|left, right| {
                left.support_evidence_score
                    .partial_cmp(&right.support_evidence_score)
                    .unwrap_or(std::cmp::Ordering::Equal)
                    .then_with(|| right.proposal_id.cmp(&left.proposal_id))
            })
        });
    let Some(score) = selected_score else {
        return DominantGovernanceRecommendationCandidateV2 {
            candidate_id: "dominant-governance-recommendation-candidate-v2".to_string(),
            proposal_id: None,
            support_score: 0.0,
            support_evidence_count: 0,
            support_high_or_medium_evidence_count: 0,
            risk_first_support_present: false,
            safety_support_present: false,
            role_balance_support_present: false,
            dominant_ratio: Some(convergence_detail.dominant_recommendation_ratio),
            trailing_streak_count: Some(convergence_detail.trailing_streak_count),
            evidence_status: DominantGovernanceRecommendationEvidenceStatus::Insufficient,
            candidate_status: DominantGovernanceRecommendationCandidateStatus::NoCandidate,
            reason: "no proposal support score was available".to_string(),
            policy_apply_allowed: false,
            review_only: true,
            paper_only: true,
        };
    };
    let (
        support_evidence_count,
        support_high_or_medium_evidence_count,
        risk_first_support_present,
        safety_support_present,
        role_balance_support_present,
        review_required_present,
        low_confidence_only,
        missing_required_support,
    ) = proposal_support_facts(&score.proposal_id, support_evidence_set);
    let support_threshold_met =
        score.support_evidence_score >= support_policy.min_total_support_score;
    let count_threshold_met =
        support_high_or_medium_evidence_count >= support_policy.min_high_or_medium_evidence_count;
    let required_support_met = missing_required_support.is_empty();
    let low_only_allowed =
        support_policy.allow_low_confidence_only_materialization || !low_confidence_only;
    let evidence_status =
        if support_threshold_met && count_threshold_met && required_support_met && low_only_allowed
        {
            if convergence_detail
                .dominant_recommended_proposal_id
                .is_none()
                || review_required_present
                || low_confidence_only
            {
                DominantGovernanceRecommendationEvidenceStatus::SufficientWithWarnings
            } else {
                DominantGovernanceRecommendationEvidenceStatus::Sufficient
            }
        } else if score.support_evidence_score > 0.0 {
            DominantGovernanceRecommendationEvidenceStatus::Weak
        } else {
            DominantGovernanceRecommendationEvidenceStatus::Insufficient
        };
    let (candidate_status, reason) = if !safety_support_present {
        (
            DominantGovernanceRecommendationCandidateStatus::BlockedBySafety,
            "candidate is missing required safety support".to_string(),
        )
    } else if matches!(
        evidence_status,
        DominantGovernanceRecommendationEvidenceStatus::Sufficient
            | DominantGovernanceRecommendationEvidenceStatus::SufficientWithWarnings
    ) {
        if convergence_detail
            .dominant_recommended_proposal_id
            .is_some()
            && evidence_status == DominantGovernanceRecommendationEvidenceStatus::Sufficient
        {
            (
                DominantGovernanceRecommendationCandidateStatus::Materialized,
                "candidate V2 materialized for review only with sufficient support".to_string(),
            )
        } else {
            (
                DominantGovernanceRecommendationCandidateStatus::MaterializedWithWarnings,
                "candidate V2 materialized for review only with support warnings".to_string(),
            )
        }
    } else if score.support_evidence_score > 0.0 {
        (
            DominantGovernanceRecommendationCandidateStatus::NeedsMoreEvidence,
            "candidate V2 still needs stronger support evidence".to_string(),
        )
    } else {
        (
            DominantGovernanceRecommendationCandidateStatus::NoCandidate,
            "candidate V2 has no sufficient support evidence".to_string(),
        )
    };
    DominantGovernanceRecommendationCandidateV2 {
        candidate_id: format!("{}-dominant-candidate-v2", score.proposal_id),
        proposal_id: Some(score.proposal_id.clone()),
        support_score: score.support_evidence_score,
        support_evidence_count,
        support_high_or_medium_evidence_count,
        risk_first_support_present,
        safety_support_present,
        role_balance_support_present,
        dominant_ratio: Some(convergence_detail.dominant_recommendation_ratio),
        trailing_streak_count: Some(convergence_detail.trailing_streak_count),
        evidence_status,
        candidate_status,
        reason,
        policy_apply_allowed: false,
        review_only: true,
        paper_only: true,
    }
}

fn missing_required_support_for_candidate_v2(
    candidate: &DominantGovernanceRecommendationCandidateV2,
    support_policy: &GovernanceRecommendationMaterializationSupportPolicy,
) -> Vec<GovernanceRecommendationMissingRequiredSupport> {
    let mut missing = Vec::new();
    if support_policy.require_risk_first_support && !candidate.risk_first_support_present {
        missing.push(GovernanceRecommendationMissingRequiredSupport::RiskFirstSupport);
    }
    if support_policy.require_safety_support && !candidate.safety_support_present {
        missing.push(GovernanceRecommendationMissingRequiredSupport::SafetySupport);
    }
    if support_policy.require_role_balance_support && !candidate.role_balance_support_present {
        missing.push(GovernanceRecommendationMissingRequiredSupport::RoleBalanceSupport);
    }
    if candidate.support_high_or_medium_evidence_count
        < support_policy.min_high_or_medium_evidence_count
    {
        missing.push(GovernanceRecommendationMissingRequiredSupport::MediumOrHighConfidenceSupport);
    }
    missing.sort();
    missing.dedup();
    missing
}

pub fn evaluate_governance_review_packet_completeness_v2(
    candidate_v2: &DominantGovernanceRecommendationCandidateV2,
    support_policy: &GovernanceRecommendationMaterializationSupportPolicy,
    evidence_gap_summary: &GovernanceRecommendationEvidenceGapSummary,
) -> GovernanceReviewPacketCompletenessGateV2 {
    let missing_required_support =
        missing_required_support_for_candidate_v2(candidate_v2, support_policy);
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    let gate_status = if candidate_v2.candidate_status
        == DominantGovernanceRecommendationCandidateStatus::BlockedBySafety
        || missing_required_support
            .contains(&GovernanceRecommendationMissingRequiredSupport::SafetySupport)
    {
        blockers.push("candidate V2 is blocked by missing safety support".to_string());
        GovernanceReviewPacketCompletenessGateStatus::BlockedBySafety
    } else if evidence_gap_summary.gap_status
        == GovernanceRecommendationEvidenceGapStatus::InsufficientHistory
    {
        blockers.push("review packet V2 needs more history".to_string());
        GovernanceReviewPacketCompletenessGateStatus::NeedsMoreHistory
    } else if matches!(
        candidate_v2.candidate_status,
        DominantGovernanceRecommendationCandidateStatus::NoCandidate
            | DominantGovernanceRecommendationCandidateStatus::NeedsMoreEvidence
    ) || !missing_required_support.is_empty()
    {
        blockers.push("review packet V2 needs more support evidence".to_string());
        GovernanceReviewPacketCompletenessGateStatus::NeedsMoreEvidence
    } else if candidate_v2.candidate_status
        == DominantGovernanceRecommendationCandidateStatus::Materialized
    {
        GovernanceReviewPacketCompletenessGateStatus::CompleteForReview
    } else {
        warnings.push("review packet V2 is complete for review with warnings only".to_string());
        GovernanceReviewPacketCompletenessGateStatus::CompleteForReviewWithWarnings
    };
    GovernanceReviewPacketCompletenessGateV2 {
        gate_id: "governance-review-packet-completeness-gate-v2".to_string(),
        candidate_status: candidate_v2.candidate_status,
        support_evidence_status: candidate_v2.evidence_status,
        support_score: candidate_v2.support_score,
        support_evidence_count: candidate_v2.support_evidence_count,
        missing_required_support,
        owner_summary_ready: matches!(
            gate_status,
            GovernanceReviewPacketCompletenessGateStatus::CompleteForReview
                | GovernanceReviewPacketCompletenessGateStatus::CompleteForReviewWithWarnings
        ),
        packet_complete: matches!(
            gate_status,
            GovernanceReviewPacketCompletenessGateStatus::CompleteForReview
                | GovernanceReviewPacketCompletenessGateStatus::CompleteForReviewWithWarnings
        ),
        gate_status,
        blockers,
        warnings,
        policy_apply_allowed: false,
        paper_only: true,
    }
}

fn default_governance_recommendation_materialization_safety_guard_v2()
-> GovernanceRecommendationMaterializationSafetyGuardV2 {
    GovernanceRecommendationMaterializationSafetyGuardV2 {
        policy_apply_allowed_true_detected: false,
        actual_policy_apply_detected: false,
        actual_score_mutation_detected: false,
        actual_voice_mutation_detected: false,
        committee_decision_mutation_detected: false,
        chairman_decision_mutation_detected: false,
        risk_governor_override_detected: false,
        trade_signal_detected: false,
        order_detected: false,
        broker_order_account_detected: false,
        weak_evidence_materialized_detected: false,
        review_required_materialized_detected: false,
        missing_safety_support_materialized_detected: false,
        missing_risk_first_support_materialized_detected: false,
        guard_status: PaperGovernanceTrialSafetyGuardStatus::Preserved,
        violations: Vec::new(),
        paper_only: true,
    }
}

pub fn evaluate_governance_recommendation_materialization_safety_v2(
    verify_result: &GovernanceRecommendationMaterializationVerifyResult,
    candidate_v2: &DominantGovernanceRecommendationCandidateV2,
    support_evidence_set: &GovernanceRecommendationSupportEvidenceSet,
    batch_before: &BatchCommitteeCycleResult,
    batch_after: Option<&BatchCommitteeCycleResult>,
) -> GovernanceRecommendationMaterializationSafetyGuardV2 {
    let batch_after = batch_after.unwrap_or(batch_before);
    let actual_score_snapshot = |store: Option<&PaperGovernanceTrialStateStore>| {
        store.map(|store| {
            store
                .member_states
                .iter()
                .map(|state| (state.member_id.clone(), state.actual_score_snapshot))
                .collect::<BTreeMap<_, _>>()
        })
    };
    let actual_voice_snapshot = |store: Option<&PaperGovernanceTrialStateStore>| {
        store.map(|store| {
            store
                .member_states
                .iter()
                .map(|state| (state.member_id.clone(), state.actual_voice_snapshot))
                .collect::<BTreeMap<_, _>>()
        })
    };
    let risk_snapshot = |decisions: &[ChairmanDecision]| {
        decisions
            .iter()
            .map(|decision| (decision.decision_id.clone(), decision.risk_governor_status))
            .collect::<BTreeMap<_, _>>()
    };
    let materialized = matches!(
        candidate_v2.candidate_status,
        DominantGovernanceRecommendationCandidateStatus::Materialized
            | DominantGovernanceRecommendationCandidateStatus::MaterializedWithWarnings
    );
    let mut guard = default_governance_recommendation_materialization_safety_guard_v2();
    guard.policy_apply_allowed_true_detected =
        verify_result.policy_apply_allowed || candidate_v2.policy_apply_allowed;
    guard.actual_policy_apply_detected = batch_before.conservative_voice_tuning_v2_policy
        != batch_after.conservative_voice_tuning_v2_policy
        || batch_before.chairman_role_voice_floor_policy
            != batch_after.chairman_role_voice_floor_policy;
    guard.actual_score_mutation_detected =
        actual_score_snapshot(batch_before.paper_governance_trial_state_store.as_ref())
            != actual_score_snapshot(batch_after.paper_governance_trial_state_store.as_ref());
    guard.actual_voice_mutation_detected =
        actual_voice_snapshot(batch_before.paper_governance_trial_state_store.as_ref())
            != actual_voice_snapshot(batch_after.paper_governance_trial_state_store.as_ref());
    guard.committee_decision_mutation_detected =
        batch_before.committee_sessions != batch_after.committee_sessions;
    guard.chairman_decision_mutation_detected =
        batch_before.chairman_decisions != batch_after.chairman_decisions;
    guard.risk_governor_override_detected = risk_snapshot(&batch_before.chairman_decisions)
        != risk_snapshot(&batch_after.chairman_decisions);
    guard.trade_signal_detected = value_contains_debug_marker(
        &batch_after.committee_sessions,
        &["trade-signal".to_string()],
    ) && !value_contains_debug_marker(
        &batch_before.committee_sessions,
        &["trade-signal".to_string()],
    );
    guard.order_detected =
        value_contains_debug_marker(&batch_after.event_queue, &["order".to_string()])
            && !value_contains_debug_marker(&batch_before.event_queue, &["order".to_string()]);
    guard.broker_order_account_detected = value_contains_debug_marker(
        batch_after,
        &[
            "broker".to_string(),
            "order".to_string(),
            "account".to_string(),
        ],
    ) && !value_contains_debug_marker(
        batch_before,
        &[
            "broker".to_string(),
            "order".to_string(),
            "account".to_string(),
        ],
    );
    guard.weak_evidence_materialized_detected = materialized
        && matches!(
            candidate_v2.evidence_status,
            DominantGovernanceRecommendationEvidenceStatus::Weak
                | DominantGovernanceRecommendationEvidenceStatus::Insufficient
        );
    guard.review_required_materialized_detected = materialized
        && candidate_v2
            .proposal_id
            .as_ref()
            .is_some_and(|proposal_id| {
                let proposal_records = support_evidence_set
                    .records
                    .iter()
                    .filter(|record| record.proposal_id.as_deref() == Some(proposal_id.as_str()))
                    .collect::<Vec<_>>();
                let review_required_present = proposal_records.iter().any(|record| {
                    record.proposal_id.as_deref() == Some(proposal_id.as_str())
                    && (record.evidence_kind
                        == GovernanceRecommendationSupportEvidenceKind::ReviewRequired
                        || record.confidence
                            == GovernanceRecommendationSupportEvidenceConfidence::ReviewRequired)
                });
                let positive_non_review_support = proposal_records.iter().any(|record| {
                    record.support_score > 0.0
                        && record.evidence_kind
                            != GovernanceRecommendationSupportEvidenceKind::ReviewRequired
                        && record.confidence
                            != GovernanceRecommendationSupportEvidenceConfidence::ReviewRequired
                });
                review_required_present && !positive_non_review_support
            });
    guard.missing_safety_support_materialized_detected =
        materialized && !candidate_v2.safety_support_present;
    guard.missing_risk_first_support_materialized_detected =
        materialized && !candidate_v2.risk_first_support_present;
    if guard.policy_apply_allowed_true_detected {
        guard
            .violations
            .push("support materialization opened policy_apply_allowed".to_string());
    }
    if guard.actual_policy_apply_detected {
        guard
            .violations
            .push("support materialization applied governance policy".to_string());
    }
    if guard.actual_score_mutation_detected {
        guard
            .violations
            .push("support materialization mutated actual score".to_string());
    }
    if guard.actual_voice_mutation_detected {
        guard
            .violations
            .push("support materialization mutated actual voice".to_string());
    }
    if guard.committee_decision_mutation_detected {
        guard
            .violations
            .push("support materialization mutated committee decision".to_string());
    }
    if guard.chairman_decision_mutation_detected {
        guard
            .violations
            .push("support materialization mutated chairman decision".to_string());
    }
    if guard.risk_governor_override_detected {
        guard
            .violations
            .push("support materialization overrode Risk Governor".to_string());
    }
    if guard.trade_signal_detected {
        guard
            .violations
            .push("support materialization created trade signal".to_string());
    }
    if guard.order_detected {
        guard
            .violations
            .push("support materialization created order".to_string());
    }
    if guard.broker_order_account_detected {
        guard
            .violations
            .push("support materialization touched broker/order/account".to_string());
    }
    if guard.weak_evidence_materialized_detected {
        guard
            .violations
            .push("weak evidence was materialized by candidate V2".to_string());
    }
    if guard.review_required_materialized_detected {
        guard
            .violations
            .push("ReviewRequired evidence was materialized by candidate V2".to_string());
    }
    if guard.missing_safety_support_materialized_detected {
        guard
            .violations
            .push("candidate V2 materialized without safety support".to_string());
    }
    if guard.missing_risk_first_support_materialized_detected {
        guard
            .violations
            .push("candidate V2 materialized without risk-first support".to_string());
    }
    guard.guard_status = if guard.violations.is_empty() {
        PaperGovernanceTrialSafetyGuardStatus::Preserved
    } else {
        PaperGovernanceTrialSafetyGuardStatus::Violated
    };
    guard
}

pub fn build_owner_governance_materialization_review_summary_v2(
    verify_result: &GovernanceRecommendationMaterializationVerifyResult,
    candidate_v2: &DominantGovernanceRecommendationCandidateV2,
    gate_v2: &GovernanceReviewPacketCompletenessGateV2,
) -> OwnerGovernanceRecommendationMaterializationReviewSummaryV2 {
    OwnerGovernanceRecommendationMaterializationReviewSummaryV2 {
        summary_id: "owner-governance-recommendation-materialization-review-summary-v2"
            .to_string(),
        candidate_status: candidate_v2.candidate_status,
        proposal_id: candidate_v2.proposal_id.clone(),
        support_score: verify_result.support_score,
        support_evidence_count: candidate_v2.support_evidence_count,
        review_packet_status: gate_v2.gate_status,
        missing_required_support: gate_v2.missing_required_support.clone(),
        message: "A recommendation candidate was materialized for review only. Support evidence was sufficient for review, not application. Policy apply remains disabled. Score, voice, decisions, Risk Governor, and trading remain unchanged."
            .to_string(),
        review_only: true,
        recommendation_only: true,
        policy_apply_allowed: false,
        no_actual_policy_apply: true,
        no_score_mutation: true,
        no_voice_mutation: true,
        no_committee_decision_change: true,
        no_risk_override: true,
        not_trade_signal: true,
        paper_only: true,
    }
}

fn build_governance_recommendation_materialization_verify_result(
    verify_id: String,
    fixture_loaded: bool,
    fixture_valid: bool,
    merge_result: &GovernanceRecommendationSupportEvidenceMergeResult,
    candidate_v2: &DominantGovernanceRecommendationCandidateV2,
    gate_v2: &GovernanceReviewPacketCompletenessGateV2,
) -> GovernanceRecommendationMaterializationVerifyResult {
    let mut warnings = gate_v2.warnings.clone();
    if fixture_loaded && fixture_valid {
        warnings.push("support fixture loaded; result remains review-only".to_string());
    }
    if candidate_v2.candidate_status
        == DominantGovernanceRecommendationCandidateStatus::MaterializedWithWarnings
        || gate_v2.gate_status
            == GovernanceReviewPacketCompletenessGateStatus::CompleteForReviewWithWarnings
    {
        warnings.push("materialization completed with review-only warnings".to_string());
    }
    let verify_status = if gate_v2.gate_status
        == GovernanceReviewPacketCompletenessGateStatus::BlockedBySafety
        || candidate_v2.policy_apply_allowed
    {
        PaperGovernanceTrialRunStatus::Failed
    } else if gate_v2.gate_status == GovernanceReviewPacketCompletenessGateStatus::CompleteForReview
    {
        PaperGovernanceTrialRunStatus::Passed
    } else {
        PaperGovernanceTrialRunStatus::PassedWithWarnings
    };
    GovernanceRecommendationMaterializationVerifyResult {
        verify_id,
        fixture_loaded,
        fixture_valid,
        merged_support_count: merge_result.merged_count,
        materialized_candidate_status: candidate_v2.candidate_status,
        review_packet_gate_status: gate_v2.gate_status,
        support_score: candidate_v2.support_score,
        policy_apply_allowed: false,
        verify_status,
        warnings,
        paper_only: true,
    }
}

pub fn governance_recommendation_support_materialization_requested_from_flags(
    enabled: bool,
    dry_run: bool,
    support_evidence_fixture_path: Option<&String>,
    output_path: Option<&String>,
    emit_owner_summary: bool,
) -> bool {
    enabled
        || !dry_run
        || support_evidence_fixture_path.is_some_and(|path| !path.trim().is_empty())
        || output_path.is_some()
        || (enabled && emit_owner_summary)
}

pub fn run_governance_recommendation_support_materialization(
    tuning_result: &GovernancePolicyFeedbackTuningRunResult,
    multirun_result: &GovernanceRecommendationMultiRunResult,
    config: &GovernanceRecommendationSupportMaterializationRunConfig,
    batch_result: &BatchCommitteeCycleResult,
) -> Result<GovernanceRecommendationSupportMaterializationRunResult, String> {
    if !config.paper_only {
        return Err(
            "governance recommendation support materialization must stay paper_only".to_string(),
        );
    }
    if let Some(path) = config
        .support_evidence_fixture_path
        .as_ref()
        .filter(|path| !path.trim().is_empty())
    {
        validate_local_json_path(
            Path::new(path),
            "governance recommendation support evidence fixture path",
        )?;
    }
    if let Some(path) = config.output_path.as_ref() {
        validate_local_json_path(
            Path::new(path),
            "governance recommendation support materialization output path",
        )?;
    }
    let generated_support = build_governance_recommendation_support_evidence(
        multirun_result,
        tuning_result,
        &multirun_result.evidence_gap_summary,
    )?;
    let fixture = if let Some(path) = config
        .support_evidence_fixture_path
        .as_ref()
        .filter(|path| !path.trim().is_empty())
    {
        Some(
            load_governance_recommendation_support_evidence_fixture_from_local_json(Path::new(
                path,
            ))?,
        )
    } else {
        None
    };
    let fixture_support = if let Some(fixture) = fixture.as_ref() {
        convert_support_fixture_to_evidence_set(fixture)?
    } else {
        normalize_support_evidence_set("empty-support-fixture-set".to_string(), Vec::new())
    };
    let support_merge_result =
        merge_governance_support_evidence(&generated_support, &fixture_support);
    let support_policy = default_governance_recommendation_materialization_support_policy();
    validate_governance_recommendation_materialization_support_policy(&support_policy)?;
    let mut proposal_support_scores = tuning_result
        .proposal_generation
        .candidates
        .iter()
        .map(|proposal| {
            score_governance_proposal_with_support(
                proposal,
                &tuning_result.ranking,
                &support_merge_result.merged_evidence_set,
            )
        })
        .collect::<Vec<_>>();
    proposal_support_scores.sort_by(|left, right| {
        right
            .support_evidence_score
            .partial_cmp(&left.support_evidence_score)
            .unwrap_or(std::cmp::Ordering::Equal)
            .then_with(|| left.proposal_id.cmp(&right.proposal_id))
    });
    let candidate_v2 = materialize_dominant_governance_recommendation_candidate_v2(
        &multirun_result.convergence_detail,
        &proposal_support_scores,
        &support_merge_result.merged_evidence_set,
        &support_policy,
    );
    let review_packet_gate_v2 = evaluate_governance_review_packet_completeness_v2(
        &candidate_v2,
        &support_policy,
        &multirun_result.evidence_gap_summary,
    );
    let verify_result = build_governance_recommendation_materialization_verify_result(
        format!("{}-verify", config.run_id),
        fixture.is_some(),
        fixture.is_some(),
        &support_merge_result,
        &candidate_v2,
        &review_packet_gate_v2,
    );
    let owner_summary = if config.emit_owner_summary {
        Some(build_owner_governance_materialization_review_summary_v2(
            &verify_result,
            &candidate_v2,
            &review_packet_gate_v2,
        ))
    } else {
        None
    };
    let safety_guard_v2 = evaluate_governance_recommendation_materialization_safety_v2(
        &verify_result,
        &candidate_v2,
        &support_merge_result.merged_evidence_set,
        batch_result,
        Some(batch_result),
    );
    let run_status = if safety_guard_v2.guard_status
        == PaperGovernanceTrialSafetyGuardStatus::Violated
        || verify_result.verify_status == PaperGovernanceTrialRunStatus::Failed
    {
        PaperGovernanceTrialRunStatus::Failed
    } else {
        verify_result.verify_status
    };
    let mut result = GovernanceRecommendationSupportMaterializationRunResult {
        run_id: config.run_id.clone(),
        fixture_validation_result: fixture.clone(),
        support_merge_result,
        support_policy,
        candidate_v2,
        review_packet_gate_v2,
        verify_result,
        owner_summary,
        safety_guard_v2,
        run_status,
        dry_run: config.dry_run,
        wrote_output: false,
        paper_only: true,
    };
    if !config.dry_run {
        if let Some(path) = config.output_path.as_ref() {
            result.wrote_output = true;
            write_safe_json(Path::new(path), &result)?;
        }
    }
    Ok(result)
}

pub fn run_governance_recommendation_materialization_verify(
    tuning_result: &GovernancePolicyFeedbackTuningRunResult,
    multirun_result: &GovernanceRecommendationMultiRunResult,
    config: &GovernanceRecommendationSupportMaterializationRunConfig,
    batch_result: &BatchCommitteeCycleResult,
) -> Result<GovernanceRecommendationMaterializationVerifyResult, String> {
    Ok(run_governance_recommendation_support_materialization(
        tuning_result,
        multirun_result,
        &GovernanceRecommendationSupportMaterializationRunConfig {
            dry_run: true,
            emit_owner_summary: false,
            output_path: None,
            ..config.clone()
        },
        batch_result,
    )?
    .verify_result)
}

pub fn governance_recommendation_materialization_requested_from_flags(
    enabled: bool,
    dry_run: bool,
    support_evidence_output_path: Option<&String>,
    closure_queue_output_path: Option<&String>,
    materialization_output_path: Option<&String>,
    emit_owner_summary: bool,
) -> bool {
    enabled
        || !dry_run
        || support_evidence_output_path.is_some()
        || closure_queue_output_path.is_some()
        || materialization_output_path.is_some()
        || (enabled && emit_owner_summary)
}

pub fn run_governance_recommendation_materialization(
    multirun_result: &GovernanceRecommendationMultiRunResult,
    tuning_run_result: &GovernancePolicyFeedbackTuningRunResult,
    review_packet: &StableGovernanceRecommendationReviewPacket,
    config: &GovernanceRecommendationMaterializationRunConfig,
    batch_result: &BatchCommitteeCycleResult,
) -> Result<GovernanceRecommendationMaterializationRunResult, String> {
    if !config.paper_only {
        return Err("governance recommendation materialization must stay paper_only".to_string());
    }
    for (path, label) in [
        (
            config.support_evidence_output_path.as_ref(),
            "governance recommendation support evidence output path",
        ),
        (
            config.closure_queue_output_path.as_ref(),
            "governance recommendation closure queue output path",
        ),
        (
            config.materialization_output_path.as_ref(),
            "governance recommendation materialization output path",
        ),
    ] {
        if let Some(path) = path {
            validate_local_json_path(Path::new(path), label)?;
        }
    }
    let null_cause_summary = analyze_governance_recommendation_null_cause(
        multirun_result,
        &multirun_result.evidence_gap_summary,
    );
    let support_evidence_set = build_governance_recommendation_support_evidence(
        multirun_result,
        tuning_run_result,
        &multirun_result.evidence_gap_summary,
    )?;
    let evidence_closure_queue = build_governance_recommendation_evidence_closure_queue(
        &null_cause_summary,
        &multirun_result.evidence_gap_summary,
    );
    let mut proposal_support_scores = tuning_run_result
        .proposal_generation
        .candidates
        .iter()
        .map(|proposal| {
            score_governance_proposal_with_support(
                proposal,
                &tuning_run_result.ranking,
                &support_evidence_set,
            )
        })
        .collect::<Vec<_>>();
    proposal_support_scores.sort_by(|left, right| {
        right
            .total_support_adjusted_score
            .partial_cmp(&left.total_support_adjusted_score)
            .unwrap_or(std::cmp::Ordering::Equal)
            .then_with(|| left.proposal_id.cmp(&right.proposal_id))
    });
    let dominant_candidate = materialize_dominant_governance_recommendation_candidate(
        &multirun_result.convergence_detail,
        &proposal_support_scores,
        &support_evidence_set,
        &GovernanceRecommendationConvergencePolicy {
            min_entries_required: multirun_result.convergence_analysis.required_min_entries,
            min_dominant_recommendation_ratio: 0.67,
            max_flip_rate: 0.34,
            max_safety_block_count: 0,
            allow_needs_more_evidence_warnings: true,
            paper_only: true,
        },
    );
    let review_packet_completeness_gate = evaluate_governance_review_packet_completeness(
        review_packet,
        &dominant_candidate,
        &multirun_result.evidence_gap_summary,
    );
    let mut result = GovernanceRecommendationMaterializationRunResult {
        run_id: config.run_id.clone(),
        null_cause_summary,
        support_evidence_set,
        evidence_closure_queue,
        proposal_support_scores,
        dominant_candidate,
        review_packet_completeness_gate,
        owner_summary: None,
        safety_guard: default_governance_recommendation_materialization_safety_guard(),
        run_status: PaperGovernanceTrialRunStatus::PassedWithWarnings,
        dry_run: config.dry_run,
        wrote_support_evidence: false,
        wrote_closure_queue: false,
        wrote_materialization_output: false,
        paper_only: true,
    };
    if config.emit_owner_summary {
        result.owner_summary =
            Some(build_owner_governance_recommendation_materialization_summary(&result));
    }
    result.safety_guard = evaluate_governance_recommendation_materialization_safety(
        &result,
        batch_result,
        Some(batch_result),
    );
    result.run_status = if result.safety_guard.guard_status
        == PaperGovernanceTrialSafetyGuardStatus::Violated
        || result.review_packet_completeness_gate.gate_status
            == GovernanceReviewPacketCompletenessGateStatus::BlockedBySafety
    {
        PaperGovernanceTrialRunStatus::Failed
    } else if result.review_packet_completeness_gate.gate_status
        == GovernanceReviewPacketCompletenessGateStatus::CompleteForReview
    {
        PaperGovernanceTrialRunStatus::Passed
    } else {
        PaperGovernanceTrialRunStatus::PassedWithWarnings
    };
    if !config.dry_run {
        if let Some(path) = config.support_evidence_output_path.as_ref() {
            write_safe_json(Path::new(path), &result.support_evidence_set)?;
            result.wrote_support_evidence = true;
        }
        if let Some(path) = config.closure_queue_output_path.as_ref() {
            write_safe_json(Path::new(path), &result.evidence_closure_queue)?;
            result.wrote_closure_queue = true;
        }
        if let Some(path) = config.materialization_output_path.as_ref() {
            result.wrote_materialization_output = true;
            write_safe_json(Path::new(path), &result)?;
        }
    }
    Ok(result)
}

fn maybe_run_governance_recommendation_materialization_for_batch_result(
    run_id: String,
    enabled: bool,
    dry_run: bool,
    support_evidence_output_path: Option<&String>,
    closure_queue_output_path: Option<&String>,
    materialization_output_path: Option<&String>,
    emit_owner_summary: bool,
    batch_result: &mut BatchCommitteeCycleResult,
) -> Result<Option<GovernanceRecommendationMaterializationRunResult>, String> {
    if !governance_recommendation_materialization_requested_from_flags(
        enabled,
        dry_run,
        support_evidence_output_path,
        closure_queue_output_path,
        materialization_output_path,
        emit_owner_summary,
    ) {
        return Ok(None);
    }
    let multirun_result = batch_result
        .governance_recommendation_multi_run_result
        .clone()
        .ok_or_else(|| {
            "governance recommendation materialization requires multirun result".to_string()
        })?;
    let tuning_run_result = batch_result
        .governance_policy_feedback_tuning_run_result
        .clone()
        .ok_or_else(|| {
            "governance recommendation materialization requires tuning result".to_string()
        })?;
    let review_packet = batch_result
        .stable_governance_recommendation_review_packet
        .clone()
        .ok_or_else(|| {
            "governance recommendation materialization requires stable review packet".to_string()
        })?;
    let result = run_governance_recommendation_materialization(
        &multirun_result,
        &tuning_run_result,
        &review_packet,
        &GovernanceRecommendationMaterializationRunConfig {
            run_id,
            enabled,
            support_evidence_output_path: support_evidence_output_path.cloned(),
            closure_queue_output_path: closure_queue_output_path.cloned(),
            materialization_output_path: materialization_output_path.cloned(),
            dry_run,
            emit_owner_summary,
            paper_only: true,
        },
        batch_result,
    )?;
    batch_result.governance_recommendation_null_cause_summary =
        Some(result.null_cause_summary.clone());
    batch_result.governance_recommendation_support_evidence_set =
        Some(result.support_evidence_set.clone());
    batch_result.governance_recommendation_evidence_closure_queue =
        Some(result.evidence_closure_queue.clone());
    batch_result.governance_proposal_support_scores = Some(result.proposal_support_scores.clone());
    batch_result.dominant_governance_recommendation_candidate =
        Some(result.dominant_candidate.clone());
    batch_result.governance_review_packet_completeness_gate =
        Some(result.review_packet_completeness_gate.clone());
    batch_result.governance_recommendation_materialization_safety_guard =
        Some(result.safety_guard.clone());
    batch_result.owner_governance_recommendation_materialization_summary =
        result.owner_summary.clone();
    batch_result.governance_recommendation_materialization_run_result = Some(result.clone());
    Ok(Some(result))
}

fn maybe_run_governance_recommendation_support_materialization_for_batch_result(
    run_id: String,
    enabled: bool,
    dry_run: bool,
    support_evidence_fixture_path: Option<&String>,
    output_path: Option<&String>,
    emit_owner_summary: bool,
    batch_result: &mut BatchCommitteeCycleResult,
) -> Result<Option<GovernanceRecommendationSupportMaterializationRunResult>, String> {
    if !governance_recommendation_support_materialization_requested_from_flags(
        enabled,
        dry_run,
        support_evidence_fixture_path,
        output_path,
        emit_owner_summary,
    ) {
        return Ok(None);
    }
    let multirun_result = batch_result
        .governance_recommendation_multi_run_result
        .clone()
        .ok_or_else(|| {
            "governance recommendation support materialization requires multirun result".to_string()
        })?;
    let tuning_run_result = batch_result
        .governance_policy_feedback_tuning_run_result
        .clone()
        .ok_or_else(|| {
            "governance recommendation support materialization requires tuning result".to_string()
        })?;
    let result = run_governance_recommendation_support_materialization(
        &tuning_run_result,
        &multirun_result,
        &GovernanceRecommendationSupportMaterializationRunConfig {
            run_id,
            enabled,
            support_evidence_fixture_path: support_evidence_fixture_path
                .filter(|path| !path.trim().is_empty())
                .cloned(),
            output_path: output_path.cloned(),
            dry_run,
            emit_owner_summary,
            paper_only: true,
        },
        batch_result,
    )?;
    batch_result.governance_recommendation_support_evidence_fixture =
        result.fixture_validation_result.clone();
    batch_result.governance_recommendation_support_evidence_merge_result =
        Some(result.support_merge_result.clone());
    batch_result.governance_recommendation_support_evidence_set =
        Some(result.support_merge_result.merged_evidence_set.clone());
    batch_result.governance_recommendation_materialization_support_policy =
        Some(result.support_policy.clone());
    batch_result.dominant_governance_recommendation_candidate_v2 =
        Some(result.candidate_v2.clone());
    batch_result.governance_review_packet_completeness_gate_v2 =
        Some(result.review_packet_gate_v2.clone());
    batch_result.governance_recommendation_materialization_verify_result =
        Some(result.verify_result.clone());
    batch_result.owner_governance_recommendation_materialization_review_summary_v2 =
        result.owner_summary.clone();
    batch_result.governance_recommendation_materialization_safety_guard_v2 =
        Some(result.safety_guard_v2.clone());
    batch_result.governance_recommendation_support_materialization_run_result =
        Some(result.clone());
    Ok(Some(result))
}

pub fn governance_recommendation_owner_review_requested_from_flags(
    enabled: bool,
    dry_run: bool,
    owner_review_text: Option<&String>,
    owner_review_input_path: Option<&String>,
    review_ledger_output_path: Option<&String>,
    design_draft_output_path: Option<&String>,
    output_path: Option<&String>,
    emit_owner_summary: bool,
    verify_enabled: bool,
    verify_expected_intent: Option<OwnerGovernanceReviewIntent>,
    verify_require_design_draft: bool,
    owner_review_samples_path: Option<&String>,
    run_firewall_regression: bool,
) -> bool {
    enabled
        || !dry_run
        || owner_review_text
            .map(|text| !text.trim().is_empty())
            .unwrap_or(false)
        || owner_review_input_path.is_some()
        || review_ledger_output_path.is_some()
        || design_draft_output_path.is_some()
        || output_path.is_some()
        || (enabled && emit_owner_summary)
        || verify_enabled
        || verify_expected_intent.is_some()
        || verify_require_design_draft
        || owner_review_samples_path
            .map(|path| !path.trim().is_empty())
            .unwrap_or(false)
        || run_firewall_regression
}

fn governance_recommendation_review_packet_status_from_support_run(
    materialization_result: &GovernanceRecommendationSupportMaterializationRunResult,
) -> GovernanceRecommendationReviewPacketStatus {
    if materialization_result.safety_guard_v2.guard_status
        == PaperGovernanceTrialSafetyGuardStatus::Violated
        || materialization_result.review_packet_gate_v2.gate_status
            == GovernanceReviewPacketCompletenessGateStatus::BlockedBySafety
    {
        GovernanceRecommendationReviewPacketStatus::BlockedBySafety
    } else if materialization_result.review_packet_gate_v2.gate_status
        == GovernanceReviewPacketCompletenessGateStatus::CompleteForReview
        || materialization_result.review_packet_gate_v2.gate_status
            == GovernanceReviewPacketCompletenessGateStatus::CompleteForReviewWithWarnings
    {
        if materialization_result.candidate_v2.candidate_status
            == DominantGovernanceRecommendationCandidateStatus::MaterializedWithWarnings
            || !materialization_result
                .review_packet_gate_v2
                .warnings
                .is_empty()
        {
            GovernanceRecommendationReviewPacketStatus::CompleteForReviewWithWarnings
        } else {
            GovernanceRecommendationReviewPacketStatus::CompleteForReview
        }
    } else {
        GovernanceRecommendationReviewPacketStatus::NeedsMoreEvidence
    }
}

fn count_support_evidence_kind(
    materialization_result: &GovernanceRecommendationSupportMaterializationRunResult,
    kind: GovernanceRecommendationSupportEvidenceKind,
) -> usize {
    materialization_result
        .support_merge_result
        .merged_evidence_set
        .records
        .iter()
        .filter(|record| record.evidence_kind == kind)
        .count()
}

pub fn build_governance_recommendation_review_packet(
    materialization_result: &GovernanceRecommendationSupportMaterializationRunResult,
) -> GovernanceRecommendationReviewPacket {
    let candidate = &materialization_result.candidate_v2;
    let proposal_label = candidate
        .proposal_id
        .clone()
        .unwrap_or_else(|| "no-dominant-proposal".to_string());
    let risk_count = count_support_evidence_kind(
        materialization_result,
        GovernanceRecommendationSupportEvidenceKind::RiskRegressionImprovement,
    );
    let voice_count = count_support_evidence_kind(
        materialization_result,
        GovernanceRecommendationSupportEvidenceKind::VoiceConcentrationReduction,
    );
    let no_trade_count = count_support_evidence_kind(
        materialization_result,
        GovernanceRecommendationSupportEvidenceKind::NoTradeBiasReduction,
    );
    let role_balance_count = count_support_evidence_kind(
        materialization_result,
        GovernanceRecommendationSupportEvidenceKind::RoleBalancePreserved,
    );
    let review_packet_status =
        governance_recommendation_review_packet_status_from_support_run(materialization_result);
    GovernanceRecommendationReviewPacket {
        packet_id: format!("review-packet-{}", candidate.candidate_id),
        candidate_id: candidate.candidate_id.clone(),
        proposal_id: candidate.proposal_id.clone(),
        support_score: candidate.support_score,
        support_evidence_count: candidate.support_evidence_count,
        risk_first_support_present: candidate.risk_first_support_present,
        safety_support_present: candidate.safety_support_present,
        role_balance_support_present: candidate.role_balance_support_present,
        review_packet_status,
        recommendation_summary: format!(
            "{proposal_label} remains review-only with support score {:.2} across {} evidence records",
            candidate.support_score, candidate.support_evidence_count
        ),
        risk_summary: if candidate.risk_first_support_present {
            format!(
                "risk-first support preserved with {risk_count} risk regression evidence records"
            )
        } else {
            "risk-first support is still missing for paper trial design".to_string()
        },
        voice_concentration_summary: if voice_count > 0 {
            format!("voice concentration mitigation evidence present in {voice_count} records")
        } else {
            "voice concentration mitigation evidence is still thin".to_string()
        },
        no_trade_bias_summary: if no_trade_count > 0 {
            format!("no-trade bias reduction evidence present in {no_trade_count} records")
        } else {
            "no-trade bias reduction evidence is still missing".to_string()
        },
        role_balance_summary: if candidate.role_balance_support_present {
            format!("role balance preserved with {role_balance_count} supporting records")
        } else {
            "role balance preservation evidence is still missing".to_string()
        },
        evidence_summary: format!(
            "support score {:.2}; total evidence {}; medium/high {}; review-required {}",
            candidate.support_score,
            candidate.support_evidence_count,
            candidate.support_high_or_medium_evidence_count,
            materialization_result
                .support_merge_result
                .merged_evidence_set
                .review_required_count
        ),
        policy_apply_allowed: false,
        review_only: true,
        paper_only: true,
    }
}

pub fn load_governance_recommendation_review_packet_from_local_json(
    path: &Path,
) -> Result<GovernanceRecommendationReviewPacket, String> {
    validate_local_json_path(path, "governance recommendation review packet path")?;
    let text = std::fs::read_to_string(path)
        .map_err(|err| format!("failed to read governance recommendation review packet: {err}"))?;
    serde_json::from_str(&text)
        .map_err(|err| format!("failed to parse governance recommendation review packet: {err}"))
}

pub fn load_owner_governance_review_input_from_local_json(
    path: &Path,
) -> Result<OwnerGovernanceReviewInput, String> {
    validate_local_json_path(path, "owner governance review input path")?;
    let text = std::fs::read_to_string(path)
        .map_err(|err| format!("failed to read owner governance review input: {err}"))?;
    serde_json::from_str(&text)
        .map_err(|err| format!("failed to parse owner governance review input: {err}"))
}

fn normalize_owner_governance_review_text(raw_text: &str) -> String {
    raw_text.split_whitespace().collect::<Vec<_>>().join(" ")
}

fn owner_governance_review_contains_any(text: &str, terms: &[&str]) -> bool {
    terms.iter().any(|term| text.contains(term))
}

fn owner_governance_review_contains_apply_negation(text: &str) -> bool {
    owner_governance_review_contains_any(
        text,
        &[
            "do not apply",
            "don't apply",
            "no actual apply",
            "no policy apply",
            "policy apply remains locked",
            "실제 적용은 하지마",
            "실제 적용 하지마",
            "실제 적용하지마",
            "실제 적용은 하지 말",
            "실제 적용 하지 말",
            "실제 반영하지마",
            "실제 반영 하지마",
            "적용은 하지마",
            "적용하지마",
            "적용 하지마",
        ],
    )
}

fn detect_owner_governance_review_unsafe_terms(normalized_text: &str) -> Vec<String> {
    let lower = normalized_text.to_lowercase();
    let mut terms = Vec::new();
    let apply_negated = owner_governance_review_contains_apply_negation(&lower);
    let candidates = [
        (
            "force-apply",
            &["force apply", "강제 적용", "강행 적용"][..],
        ),
        (
            "apply-now",
            &["apply now", "즉시 적용", "바로 적용", "실제 적용"][..],
        ),
        (
            "live-enable",
            &["live apply", "live enable", "실거래", "실제 반영"][..],
        ),
        (
            "trade-now",
            &["trade now", "buy now", "sell now", "매수", "매도"][..],
        ),
        (
            "order-submit",
            &[
                "order",
                "submit order",
                "place order",
                "execute",
                "주문 실행",
                "주문 넣어",
            ][..],
        ),
        (
            "broker-account",
            &["broker", "account", "브로커", "계좌"][..],
        ),
        ("leverage", &["leverage", "레버리지"][..]),
        (
            "guaranteed-profit",
            &[
                "guaranteed profit",
                "guaranteed profits",
                "확정 수익",
                "보장 수익",
            ][..],
        ),
    ];
    for (label, keywords) in candidates {
        if apply_negated && matches!(label, "force-apply" | "apply-now" | "live-enable") {
            continue;
        }
        if owner_governance_review_contains_any(&lower, keywords) {
            terms.push(label.to_string());
        }
    }
    terms.sort();
    terms.dedup();
    terms
}

fn owner_governance_review_intent_from_text(normalized_text: &str) -> OwnerGovernanceReviewIntent {
    let lower = normalized_text.to_lowercase();
    if owner_governance_review_contains_any(
        &lower,
        &["reject", "rejected", "거부", "기각", "반려", "반대"],
    ) {
        OwnerGovernanceReviewIntent::RejectRecommendation
    } else if owner_governance_review_contains_any(
        &lower,
        &[
            "more evidence",
            "need evidence",
            "collect more evidence",
            "추가 증거",
            "더 많은 증거",
            "추가 근거",
            "근거 더",
            "증거가 부족",
            "증거 부족",
            "근거가 부족",
            "근거 부족",
            "더 모으",
            "다시 모으",
        ],
    ) {
        OwnerGovernanceReviewIntent::AskForMoreEvidence
    } else if owner_governance_review_contains_any(
        &lower,
        &["risk concern", "risk", "위험", "리스크"],
    ) {
        OwnerGovernanceReviewIntent::RiskConcern
    } else if owner_governance_review_contains_any(
        &lower,
        &[
            "voice concentration",
            "voice share",
            "발언 집중",
            "목소리 집중",
            "voice bias",
        ],
    ) {
        OwnerGovernanceReviewIntent::VoiceConcentrationConcern
    } else if owner_governance_review_contains_any(
        &lower,
        &[
            "no-trade bias",
            "no trade bias",
            "무거래",
            "거래 없음 편향",
            "거래 편향",
        ],
    ) {
        OwnerGovernanceReviewIntent::NoTradeBiasConcern
    } else if owner_governance_review_contains_any(
        &lower,
        &[
            "evidence concern",
            "evidence gap",
            "증거 부족",
            "근거 부족",
            "evidence",
        ],
    ) {
        OwnerGovernanceReviewIntent::EvidenceConcern
    } else if owner_governance_review_contains_any(
        &lower,
        &[
            "approve paper trial",
            "paper trial design ok",
            "approve for paper trial design",
            "trial design approved",
            "paper trial design",
            "paper-only trial",
            "paper trial",
            "paper only",
            "페이퍼 트라이얼",
            "종이 설계",
            "설계안 진행",
            "드래프트 진행",
        ],
    ) {
        OwnerGovernanceReviewIntent::ApproveForPaperTrialDesign
    } else if owner_governance_review_contains_any(&lower, &["why", "왜", "설명", "이유"]) {
        OwnerGovernanceReviewIntent::AskWhy
    } else if normalized_text.is_empty() {
        OwnerGovernanceReviewIntent::Unknown
    } else {
        OwnerGovernanceReviewIntent::Comment
    }
}

pub fn parse_owner_governance_review_input(
    input: &OwnerGovernanceReviewInput,
) -> OwnerGovernanceReviewParseResult {
    let normalized_summary = normalize_owner_governance_review_text(&input.raw_text);
    let unsafe_terms_detected = detect_owner_governance_review_unsafe_terms(&normalized_summary);
    let mut intent = owner_governance_review_intent_from_text(&normalized_summary);
    if intent == OwnerGovernanceReviewIntent::Unknown
        && input.parsed_intent != OwnerGovernanceReviewIntent::Unknown
    {
        intent = input.parsed_intent;
    }
    OwnerGovernanceReviewParseResult {
        input_id: input.input_id.clone(),
        intent,
        safe: unsafe_terms_detected.is_empty(),
        unsafe_reason: if unsafe_terms_detected.is_empty() {
            None
        } else {
            Some(format!(
                "owner review contains execution-only terms: {}",
                unsafe_terms_detected.join(", ")
            ))
        },
        normalized_summary: if normalized_summary.is_empty() {
            input.owner_summary.clone()
        } else {
            normalized_summary
        },
        paper_only: true,
    }
}

pub fn parse_owner_governance_review_text(raw_text: &str) -> OwnerGovernanceReviewParseResult {
    let normalized_summary = normalize_owner_governance_review_text(raw_text);
    let input = OwnerGovernanceReviewInput {
        input_id: "owner-governance-review-text".to_string(),
        raw_text: raw_text.to_string(),
        parsed_intent: owner_governance_review_intent_from_text(&normalized_summary),
        target_candidate_id: None,
        target_proposal_id: None,
        owner_summary: normalized_summary,
        unsafe_terms_detected: Vec::new(),
        paper_only: true,
    };
    parse_owner_governance_review_input(&input)
}

fn owner_governance_review_reason_from_intent(
    intent: Option<OwnerGovernanceReviewIntent>,
    default_reason: ChairmanGovernanceReviewReason,
) -> ChairmanGovernanceReviewReason {
    match intent {
        Some(OwnerGovernanceReviewIntent::RejectRecommendation) => {
            ChairmanGovernanceReviewReason::OwnerRejected
        }
        Some(OwnerGovernanceReviewIntent::AskForMoreEvidence) => {
            ChairmanGovernanceReviewReason::OwnerAskedForMoreEvidence
        }
        Some(OwnerGovernanceReviewIntent::RiskConcern) => {
            ChairmanGovernanceReviewReason::RiskConcernRequiresMoreEvidence
        }
        Some(OwnerGovernanceReviewIntent::VoiceConcentrationConcern) => {
            ChairmanGovernanceReviewReason::VoiceConcentrationConcern
        }
        Some(OwnerGovernanceReviewIntent::NoTradeBiasConcern) => {
            ChairmanGovernanceReviewReason::NoTradeBiasConcern
        }
        _ => default_reason,
    }
}

pub fn evaluate_chairman_governance_review(
    review_packet: &GovernanceRecommendationReviewPacket,
    owner_review_input: Option<&OwnerGovernanceReviewInput>,
    owner_review_parse_result: Option<&OwnerGovernanceReviewParseResult>,
    materialization_result: &GovernanceRecommendationSupportMaterializationRunResult,
) -> ChairmanGovernanceReviewEvaluation {
    let owner_input_id = owner_review_input.map(|input| input.input_id.clone());
    let safety_blocked = review_packet.review_packet_status
        == GovernanceRecommendationReviewPacketStatus::BlockedBySafety
        || materialization_result.safety_guard_v2.guard_status
            == PaperGovernanceTrialSafetyGuardStatus::Violated;
    let (chairman_decision, reason, explanation, paper_trial_design_allowed) = if safety_blocked {
        (
            ChairmanGovernanceReviewDecision::BlockedBySafety,
            ChairmanGovernanceReviewReason::SafetyBlocked,
            "safety guard is still locked; recommendation stays paper-only review".to_string(),
            false,
        )
    } else if let Some(parse_result) = owner_review_parse_result {
        if !parse_result.safe {
            (
                ChairmanGovernanceReviewDecision::KeepReviewOnly,
                ChairmanGovernanceReviewReason::OwnerApprovedButSafetyStillLocked,
                "unsafe owner execution wording was ignored; review remains paper-only and review-only"
                    .to_string(),
                false,
            )
        } else if parse_result.intent == OwnerGovernanceReviewIntent::RejectRecommendation {
            (
                ChairmanGovernanceReviewDecision::RejectRecommendation,
                ChairmanGovernanceReviewReason::OwnerRejected,
                "owner rejected the recommendation; no paper trial design draft will be produced"
                    .to_string(),
                false,
            )
        } else if review_packet.review_packet_status
            == GovernanceRecommendationReviewPacketStatus::NeedsMoreEvidence
        {
            let reason = owner_governance_review_reason_from_intent(
                Some(parse_result.intent),
                ChairmanGovernanceReviewReason::InsufficientSupport,
            );
            (
                ChairmanGovernanceReviewDecision::NeedsMoreEvidence,
                reason,
                "support packet still needs more evidence before paper trial design".to_string(),
                false,
            )
        } else if matches!(
            parse_result.intent,
            OwnerGovernanceReviewIntent::AskForMoreEvidence
                | OwnerGovernanceReviewIntent::RiskConcern
                | OwnerGovernanceReviewIntent::EvidenceConcern
                | OwnerGovernanceReviewIntent::NoTradeBiasConcern
                | OwnerGovernanceReviewIntent::VoiceConcentrationConcern
        ) {
            let reason = owner_governance_review_reason_from_intent(
                Some(parse_result.intent),
                ChairmanGovernanceReviewReason::InsufficientSupport,
            );
            (
                ChairmanGovernanceReviewDecision::NeedsMoreEvidence,
                reason,
                "owner requested more paper evidence before any trial design draft".to_string(),
                false,
            )
        } else if parse_result.intent == OwnerGovernanceReviewIntent::ApproveForPaperTrialDesign {
            (
                ChairmanGovernanceReviewDecision::AcceptForPaperTrialDesign,
                ChairmanGovernanceReviewReason::SufficientSupport,
                "support is sufficient for a paper-only trial design draft; actual policy apply remains locked"
                    .to_string(),
                true,
            )
        } else {
            (
                ChairmanGovernanceReviewDecision::KeepReviewOnly,
                ChairmanGovernanceReviewReason::SufficientSupport,
                "support is reviewable, but without explicit owner approval it stays review-only"
                    .to_string(),
                false,
            )
        }
    } else if review_packet.review_packet_status
        == GovernanceRecommendationReviewPacketStatus::NeedsMoreEvidence
    {
        (
            ChairmanGovernanceReviewDecision::NeedsMoreEvidence,
            ChairmanGovernanceReviewReason::InsufficientSupport,
            "support packet does not yet meet the threshold for paper trial design".to_string(),
            false,
        )
    } else {
        (
            ChairmanGovernanceReviewDecision::KeepReviewOnly,
            ChairmanGovernanceReviewReason::SufficientSupport,
            "support is sufficient, but no owner review was supplied so the recommendation remains review-only"
                .to_string(),
            false,
        )
    };
    ChairmanGovernanceReviewEvaluation {
        evaluation_id: format!("chairman-review-{}", review_packet.packet_id),
        review_packet_id: review_packet.packet_id.clone(),
        owner_review_input_id: owner_input_id,
        chairman_decision,
        reason,
        explanation,
        policy_apply_allowed: false,
        paper_trial_design_allowed,
        paper_only: true,
    }
}

pub fn build_paper_policy_trial_design_draft(
    review_packet: &GovernanceRecommendationReviewPacket,
    evaluation: &ChairmanGovernanceReviewEvaluation,
) -> Option<PaperPolicyTrialDesignDraft> {
    if !evaluation.paper_trial_design_allowed {
        return None;
    }
    Some(PaperPolicyTrialDesignDraft {
        draft_id: format!("paper-trial-design-{}", review_packet.candidate_id),
        source_candidate_id: review_packet.candidate_id.clone(),
        source_proposal_id: review_packet.proposal_id.clone(),
        trial_scope: PaperPolicyTrialScope::PaperTrialStateOnly,
        allowed_operations: vec![
            PaperPolicyTrialAllowedOperation::ApplyPolicyToPaperTrialState,
            PaperPolicyTrialAllowedOperation::CompareCounterfactualCommittee,
            PaperPolicyTrialAllowedOperation::RecordPaperLedger,
        ],
        forbidden_operations: vec![
            PaperPolicyTrialForbiddenOperation::ApplyPolicyToActualState,
            PaperPolicyTrialForbiddenOperation::MutateScore,
            PaperPolicyTrialForbiddenOperation::MutateVoice,
            PaperPolicyTrialForbiddenOperation::PromoteDemote,
            PaperPolicyTrialForbiddenOperation::OverrideRiskGovernor,
            PaperPolicyTrialForbiddenOperation::MutateCommitteeDecision,
            PaperPolicyTrialForbiddenOperation::TradeOrderAccount,
        ],
        proposed_policy_changes: vec![
            review_packet.recommendation_summary.clone(),
            "limit changes to paper trial state snapshots and counterfactual comparisons".to_string(),
        ],
        risk_controls: vec![
            review_packet.risk_summary.clone(),
            "stop the draft if risk-first or safety support disappears".to_string(),
        ],
        voice_concentration_controls: vec![
            review_packet.voice_concentration_summary.clone(),
            "halt the paper trial if chairman or committee voice concentration regresses".to_string(),
        ],
        no_trade_bias_controls: vec![
            review_packet.no_trade_bias_summary.clone(),
            "do not convert the draft into orders, broker actions, or account mutations".to_string(),
        ],
        evidence_requirements: vec![
            review_packet.evidence_summary.clone(),
            "collect follow-up paper evidence for each trial cycle before reconsidering apply readiness"
                .to_string(),
        ],
        min_trial_cycles: 3,
        stop_conditions: vec![
            "safety guard violation".to_string(),
            "risk-first support missing".to_string(),
            "voice concentration regression".to_string(),
            "role-balance support missing".to_string(),
            "trade/order/account side effect detected".to_string(),
        ],
        design_status: if review_packet.review_packet_status
            == GovernanceRecommendationReviewPacketStatus::CompleteForReviewWithWarnings
        {
            PaperPolicyTrialDesignStatus::DraftedWithWarnings
        } else {
            PaperPolicyTrialDesignStatus::Drafted
        },
        paper_only: true,
    })
}

fn default_governance_recommendation_review_decision_ledger()
-> GovernanceRecommendationReviewDecisionLedger {
    GovernanceRecommendationReviewDecisionLedger {
        ledger_id: "governance-recommendation-review-decision-ledger".to_string(),
        entries: Vec::new(),
        entry_count: 0,
        latest_entry_id: None,
        paper_only: true,
    }
}

pub fn normalize_governance_recommendation_review_decision_ledger(
    ledger: &mut GovernanceRecommendationReviewDecisionLedger,
) {
    ledger
        .entries
        .sort_by(|left, right| left.entry_id.cmp(&right.entry_id));
    ledger
        .entries
        .dedup_by(|left, right| left.entry_id == right.entry_id);
    ledger.entry_count = ledger.entries.len();
    ledger.latest_entry_id = ledger.entries.last().map(|entry| entry.entry_id.clone());
}

pub fn append_governance_recommendation_review_decision_ledger_entry(
    ledger: &mut GovernanceRecommendationReviewDecisionLedger,
    entry: GovernanceRecommendationReviewDecisionLedgerEntry,
) -> Result<(), String> {
    ledger.entries.push(entry);
    normalize_governance_recommendation_review_decision_ledger(ledger);
    Ok(())
}

pub fn load_governance_recommendation_review_decision_ledger_from_local_json(
    path: &Path,
) -> Result<GovernanceRecommendationReviewDecisionLedger, String> {
    validate_local_json_path(path, "governance recommendation review ledger path")?;
    let text = std::fs::read_to_string(path)
        .map_err(|err| format!("failed to read governance recommendation review ledger: {err}"))?;
    let mut ledger: GovernanceRecommendationReviewDecisionLedger = serde_json::from_str(&text)
        .map_err(|err| format!("failed to parse governance recommendation review ledger: {err}"))?;
    normalize_governance_recommendation_review_decision_ledger(&mut ledger);
    Ok(ledger)
}

pub fn save_governance_recommendation_review_decision_ledger_to_local_json(
    path: &Path,
    ledger: &GovernanceRecommendationReviewDecisionLedger,
) -> Result<(), String> {
    validate_local_json_path(path, "governance recommendation review ledger path")?;
    write_safe_json(path, ledger)
}

pub fn evaluate_governance_policy_apply_firewall(
    review_packet: &GovernanceRecommendationReviewPacket,
    owner_review_input: Option<&OwnerGovernanceReviewInput>,
    owner_review_parse_result: Option<&OwnerGovernanceReviewParseResult>,
    paper_trial_design_draft: Option<&PaperPolicyTrialDesignDraft>,
    materialization_result: &GovernanceRecommendationSupportMaterializationRunResult,
    evaluation: &ChairmanGovernanceReviewEvaluation,
) -> GovernancePolicyApplyFirewall {
    let actual_policy_apply_detected = materialization_result.verify_result.policy_apply_allowed
        || materialization_result.candidate_v2.policy_apply_allowed
        || materialization_result.support_policy.allow_policy_apply
        || materialization_result
            .safety_guard_v2
            .policy_apply_allowed_true_detected
        || review_packet.policy_apply_allowed
        || evaluation.policy_apply_allowed;
    let actual_score_mutation_detected = materialization_result
        .safety_guard_v2
        .actual_score_mutation_detected;
    let actual_voice_mutation_detected = materialization_result
        .safety_guard_v2
        .actual_voice_mutation_detected;
    let committee_decision_mutation_detected = materialization_result
        .safety_guard_v2
        .committee_decision_mutation_detected;
    let chairman_decision_mutation_detected = materialization_result
        .safety_guard_v2
        .chairman_decision_mutation_detected;
    let risk_governor_override_detected = materialization_result
        .safety_guard_v2
        .risk_governor_override_detected;
    let trade_signal_detected = materialization_result.safety_guard_v2.trade_signal_detected;
    let order_detected = materialization_result.safety_guard_v2.order_detected;
    let broker_order_account_detected = materialization_result
        .safety_guard_v2
        .broker_order_account_detected;
    let owner_forced_apply_detected = owner_review_parse_result
        .map(|result| !result.safe)
        .unwrap_or(false)
        || owner_review_input
            .map(|input| !input.unsafe_terms_detected.is_empty())
            .unwrap_or(false);
    let mut violations = Vec::new();
    if actual_policy_apply_detected {
        violations.push("actual policy apply must remain disabled".to_string());
    }
    if actual_score_mutation_detected {
        violations.push("actual score mutation detected".to_string());
    }
    if actual_voice_mutation_detected {
        violations.push("actual voice mutation detected".to_string());
    }
    if committee_decision_mutation_detected {
        violations.push("committee decision mutation detected".to_string());
    }
    if chairman_decision_mutation_detected {
        violations.push("chairman decision mutation detected".to_string());
    }
    if risk_governor_override_detected {
        violations.push("risk governor override detected".to_string());
    }
    if trade_signal_detected {
        violations.push("trade signal detected".to_string());
    }
    if order_detected {
        violations.push("order side effect detected".to_string());
    }
    if broker_order_account_detected {
        violations.push("broker/order/account side effect detected".to_string());
    }
    if owner_forced_apply_detected {
        violations.push("owner attempted to force apply outside paper-only review".to_string());
    }
    GovernancePolicyApplyFirewall {
        firewall_id: format!("governance-policy-firewall-{}", review_packet.candidate_id),
        policy_apply_allowed: false,
        paper_trial_design_allowed: paper_trial_design_draft.is_some()
            && evaluation.paper_trial_design_allowed,
        actual_policy_apply_detected,
        actual_score_mutation_detected,
        actual_voice_mutation_detected,
        committee_decision_mutation_detected,
        chairman_decision_mutation_detected,
        risk_governor_override_detected,
        trade_signal_detected,
        order_detected,
        broker_order_account_detected,
        owner_forced_apply_detected,
        firewall_status: if violations.is_empty() {
            GovernancePolicyApplyFirewallStatus::Preserved
        } else {
            GovernancePolicyApplyFirewallStatus::Violated
        },
        violations,
        paper_only: true,
    }
}

pub fn build_owner_governance_review_summary(
    review_packet: &GovernanceRecommendationReviewPacket,
    owner_review_parse_result: Option<&OwnerGovernanceReviewParseResult>,
    evaluation: &ChairmanGovernanceReviewEvaluation,
) -> OwnerGovernanceReviewSummary {
    let message = if evaluation.paper_trial_design_allowed {
        "paper-only trial design draft accepted; actual policy apply stays disabled".to_string()
    } else {
        format!(
            "chairman decision {:?}; recommendation remains review-only",
            evaluation.chairman_decision
        )
    };
    OwnerGovernanceReviewSummary {
        summary_id: format!(
            "owner-governance-review-summary-{}",
            review_packet.candidate_id
        ),
        candidate_id: review_packet.candidate_id.clone(),
        proposal_id: review_packet.proposal_id.clone(),
        owner_intent: owner_review_parse_result.map(|result| result.intent),
        chairman_review_decision: evaluation.chairman_decision,
        paper_trial_design_allowed: evaluation.paper_trial_design_allowed,
        policy_apply_allowed: false,
        explanation: evaluation.explanation.clone(),
        message,
        review_only: true,
        paper_trial_design_only: true,
        no_actual_policy_apply: true,
        no_score_mutation: true,
        no_voice_mutation: true,
        no_committee_decision_change: true,
        no_risk_override: true,
        not_trade_signal: true,
        paper_only: true,
    }
}

pub fn run_governance_recommendation_owner_review(
    materialization_result: &GovernanceRecommendationSupportMaterializationRunResult,
    owner_review_input: Option<&OwnerGovernanceReviewInput>,
    config: &GovernanceRecommendationOwnerReviewRunConfig,
) -> Result<GovernanceRecommendationOwnerReviewRunResult, String> {
    let review_packet = if let Some(path) = config
        .review_packet_input_path
        .as_ref()
        .filter(|path| !path.trim().is_empty())
    {
        load_governance_recommendation_review_packet_from_local_json(Path::new(path))?
    } else {
        build_governance_recommendation_review_packet(materialization_result)
    };
    let loaded_owner_input = if let Some(input) = owner_review_input.cloned() {
        Some(input)
    } else if let Some(path) = config
        .owner_review_input_path
        .as_ref()
        .filter(|path| !path.trim().is_empty())
    {
        Some(load_owner_governance_review_input_from_local_json(
            Path::new(path),
        )?)
    } else if let Some(text) = config
        .owner_review_text
        .as_ref()
        .filter(|text| !text.trim().is_empty())
    {
        let normalized_summary = normalize_owner_governance_review_text(text);
        let parsed_intent = owner_governance_review_intent_from_text(&normalized_summary);
        let unsafe_terms_detected =
            detect_owner_governance_review_unsafe_terms(&normalized_summary);
        Some(OwnerGovernanceReviewInput {
            input_id: format!("owner-review-{}", config.run_id),
            raw_text: text.clone(),
            parsed_intent,
            target_candidate_id: Some(review_packet.candidate_id.clone()),
            target_proposal_id: review_packet.proposal_id.clone(),
            owner_summary: if normalized_summary.is_empty() {
                "owner review input provided without summary".to_string()
            } else {
                normalized_summary
            },
            unsafe_terms_detected,
            paper_only: true,
        })
    } else {
        None
    };
    let owner_review_parse_result = loaded_owner_input
        .as_ref()
        .map(parse_owner_governance_review_input);
    let chairman_review_evaluation = evaluate_chairman_governance_review(
        &review_packet,
        loaded_owner_input.as_ref(),
        owner_review_parse_result.as_ref(),
        materialization_result,
    );
    let paper_policy_trial_design_draft =
        build_paper_policy_trial_design_draft(&review_packet, &chairman_review_evaluation);
    let policy_apply_firewall = evaluate_governance_policy_apply_firewall(
        &review_packet,
        loaded_owner_input.as_ref(),
        owner_review_parse_result.as_ref(),
        paper_policy_trial_design_draft.as_ref(),
        materialization_result,
        &chairman_review_evaluation,
    );
    let mut review_decision_ledger = if let Some(path) = config
        .review_ledger_input_path
        .as_ref()
        .filter(|path| !path.trim().is_empty())
    {
        load_governance_recommendation_review_decision_ledger_from_local_json(Path::new(path))?
    } else {
        default_governance_recommendation_review_decision_ledger()
    };
    append_governance_recommendation_review_decision_ledger_entry(
        &mut review_decision_ledger,
        GovernanceRecommendationReviewDecisionLedgerEntry {
            entry_id: format!("{}-entry-{}", config.run_id, review_packet.candidate_id),
            review_packet_id: review_packet.packet_id.clone(),
            candidate_id: review_packet.candidate_id.clone(),
            proposal_id: review_packet.proposal_id.clone(),
            owner_intent: owner_review_parse_result
                .as_ref()
                .map(|result| result.intent),
            chairman_review_decision: chairman_review_evaluation.chairman_decision,
            paper_trial_design_allowed: chairman_review_evaluation.paper_trial_design_allowed,
            policy_apply_allowed: false,
            explanation: chairman_review_evaluation.explanation.clone(),
            paper_only: true,
        },
    )?;
    let owner_summary = if config.emit_owner_summary {
        Some(build_owner_governance_review_summary(
            &review_packet,
            owner_review_parse_result.as_ref(),
            &chairman_review_evaluation,
        ))
    } else {
        None
    };
    let run_status =
        if policy_apply_firewall.firewall_status == GovernancePolicyApplyFirewallStatus::Violated {
            PaperGovernanceTrialRunStatus::Failed
        } else if chairman_review_evaluation.paper_trial_design_allowed
            && review_packet.review_packet_status
                == GovernanceRecommendationReviewPacketStatus::CompleteForReview
        {
            PaperGovernanceTrialRunStatus::Passed
        } else {
            PaperGovernanceTrialRunStatus::PassedWithWarnings
        };
    let result = GovernanceRecommendationOwnerReviewRunResult {
        run_id: config.run_id.clone(),
        review_packet,
        owner_review_parse_result,
        chairman_review_evaluation,
        paper_policy_trial_design_draft,
        policy_apply_firewall,
        review_decision_ledger: Some(review_decision_ledger.clone()),
        owner_summary,
        run_status,
        paper_only: true,
    };
    if !config.dry_run {
        if let Some(path) = config
            .review_ledger_output_path
            .as_ref()
            .filter(|path| !path.trim().is_empty())
        {
            save_governance_recommendation_review_decision_ledger_to_local_json(
                Path::new(path),
                &review_decision_ledger,
            )?;
        }
        if let Some(path) = config
            .design_draft_output_path
            .as_ref()
            .filter(|path| !path.trim().is_empty())
        {
            validate_local_json_path(
                Path::new(path),
                "paper policy trial design draft output path",
            )?;
            if let Some(draft) = result.paper_policy_trial_design_draft.as_ref() {
                write_safe_json(Path::new(path), draft)?;
            }
        }
        if let Some(path) = config
            .output_path
            .as_ref()
            .filter(|path| !path.trim().is_empty())
        {
            validate_local_json_path(
                Path::new(path),
                "governance recommendation owner review output path",
            )?;
            write_safe_json(Path::new(path), &result)?;
        }
    }
    Ok(result)
}

fn governance_owner_review_mutation_state(
    firewall: &GovernancePolicyApplyFirewall,
) -> (bool, bool, bool, bool) {
    (
        !firewall.actual_score_mutation_detected,
        !firewall.actual_voice_mutation_detected,
        !firewall.committee_decision_mutation_detected,
        !firewall.risk_governor_override_detected,
    )
}

pub fn verify_governance_owner_review_run(
    owner_review_run_result: &GovernanceRecommendationOwnerReviewRunResult,
    verify_config: &GovernanceOwnerReviewVerifyConfig,
) -> Result<GovernanceOwnerReviewVerifyResult, String> {
    let owner_review_intent = owner_review_run_result
        .owner_review_parse_result
        .as_ref()
        .map(|result| result.intent)
        .unwrap_or(OwnerGovernanceReviewIntent::Unknown);
    let mut warnings = Vec::new();
    let mut review_ledger_written = false;
    let mut design_draft_written = false;
    if let Some(path) = verify_config
        .config_path
        .as_ref()
        .filter(|path| !path.trim().is_empty())
    {
        validate_local_json_or_toml_path(
            Path::new(path),
            "governance owner review verify config path",
        )?;
        let config = MinimalAiCommitteeCycleConfig::from_toml_path(Path::new(path))?;
        if !config.governance_recommendation_owner_review_dry_run {
            review_ledger_written = config
                .governance_recommendation_review_ledger_output_path
                .as_ref()
                .is_some_and(|output| Path::new(output).exists());
            design_draft_written = config
                .governance_recommendation_design_draft_output_path
                .as_ref()
                .is_some_and(|output| Path::new(output).exists());
        }
    }
    let (no_score_mutation, no_voice_mutation, no_committee_decision_change, no_risk_override) =
        governance_owner_review_mutation_state(&owner_review_run_result.policy_apply_firewall);
    let mut failed = false;
    if owner_review_intent != verify_config.expected_owner_intent {
        failed = true;
        warnings.push(format!(
            "expected owner intent {:?} but got {:?}",
            verify_config.expected_owner_intent, owner_review_intent
        ));
    }
    if verify_config.require_design_draft
        && owner_review_run_result
            .paper_policy_trial_design_draft
            .is_none()
    {
        failed = true;
        warnings.push("design draft was required but missing".to_string());
    }
    if verify_config.require_policy_apply_locked
        && owner_review_run_result
            .chairman_review_evaluation
            .policy_apply_allowed
    {
        failed = true;
        warnings.push("policy_apply_allowed must remain false".to_string());
    }
    if verify_config.require_firewall_preserved
        && owner_review_run_result
            .policy_apply_firewall
            .firewall_status
            != GovernancePolicyApplyFirewallStatus::Preserved
    {
        failed = true;
        warnings.push("policy apply firewall was not preserved".to_string());
    }
    if verify_config.require_no_mutation
        && (!no_score_mutation
            || !no_voice_mutation
            || !no_committee_decision_change
            || !no_risk_override)
    {
        failed = true;
        warnings.push("mutation lock was not preserved".to_string());
    }
    let verify_status = if failed {
        PaperGovernanceTrialRunStatus::Failed
    } else if warnings.is_empty() {
        PaperGovernanceTrialRunStatus::Passed
    } else {
        PaperGovernanceTrialRunStatus::PassedWithWarnings
    };
    Ok(GovernanceOwnerReviewVerifyResult {
        verify_id: verify_config.verify_id.clone(),
        owner_review_intent,
        chairman_review_decision: owner_review_run_result
            .chairman_review_evaluation
            .chairman_decision,
        paper_trial_design_allowed: owner_review_run_result
            .chairman_review_evaluation
            .paper_trial_design_allowed,
        policy_apply_allowed: false,
        review_ledger_written,
        design_draft_written,
        firewall_status: owner_review_run_result
            .policy_apply_firewall
            .firewall_status,
        no_score_mutation,
        no_voice_mutation,
        no_committee_decision_change,
        no_risk_override,
        verify_status,
        warnings,
        paper_only: true,
    })
}

pub fn prove_paper_policy_trial_design_draft_write(
    owner_review_run_result: &GovernanceRecommendationOwnerReviewRunResult,
    output_path: &Path,
) -> Result<PaperPolicyTrialDesignDraftWriteProof, String> {
    validate_local_json_path(
        output_path,
        "paper policy trial design draft write proof path",
    )?;
    let wrote_design_draft = owner_review_run_result
        .paper_policy_trial_design_draft
        .is_some();
    let design_draft_exists_after_write = output_path.exists();
    let mut proof_status = GovernanceWriteProofStatus::Proven;
    let (
        draft,
        draft_id,
        paper_only,
        allowed_operation_count,
        forbidden_operation_count,
        unsafe_allowed_operation_detected,
    ) = if design_draft_exists_after_write {
        let text = std::fs::read_to_string(output_path)
            .map_err(|err| format!("failed to read paper design draft proof file: {err}"))?;
        let value: serde_json::Value = serde_json::from_str(&text)
            .map_err(|err| format!("failed to parse paper design draft proof value: {err}"))?;
        let draft_id = value
            .get("draft_id")
            .and_then(|value| value.as_str())
            .map(|value| value.to_string());
        let paper_only = value
            .get("paper_only")
            .and_then(|value| value.as_bool())
            .unwrap_or(true);
        let allowed_operation_count = value
            .get("allowed_operations")
            .and_then(|ops| ops.as_array())
            .map(|ops| ops.len())
            .unwrap_or(0);
        let forbidden_operation_count = value
            .get("forbidden_operations")
            .and_then(|ops| ops.as_array())
            .map(|ops| ops.len())
            .unwrap_or(0);
        let unsafe_allowed_operation_detected = value
            .get("allowed_operations")
            .and_then(|ops| ops.as_array())
            .is_some_and(|ops| {
                ops.iter().filter_map(|op| op.as_str()).any(|op| {
                    matches!(
                        op,
                        "ApplyPolicyToActualState"
                            | "TradeOrderAccount"
                            | "MutateScore"
                            | "MutateVoice"
                            | "MutateCommitteeDecision"
                            | "OverrideRiskGovernor"
                    )
                })
            });
        if unsafe_allowed_operation_detected {
            (
                None,
                draft_id,
                paper_only,
                allowed_operation_count,
                forbidden_operation_count,
                unsafe_allowed_operation_detected,
            )
        } else {
            let draft = Some(
                serde_json::from_value::<PaperPolicyTrialDesignDraft>(value).map_err(|err| {
                    format!("failed to parse paper design draft proof file: {err}")
                })?,
            );
            (
                draft,
                draft_id,
                paper_only,
                allowed_operation_count,
                forbidden_operation_count,
                unsafe_allowed_operation_detected,
            )
        }
    } else {
        let draft = owner_review_run_result
            .paper_policy_trial_design_draft
            .clone();
        let draft_id = draft.as_ref().map(|draft| draft.draft_id.clone());
        let paper_only = draft.as_ref().map(|draft| draft.paper_only).unwrap_or(true);
        let allowed_operation_count = draft
            .as_ref()
            .map(|draft| draft.allowed_operations.len())
            .unwrap_or(0);
        let forbidden_operation_count = draft
            .as_ref()
            .map(|draft| draft.forbidden_operations.len())
            .unwrap_or(0);
        (
            draft,
            draft_id,
            paper_only,
            allowed_operation_count,
            forbidden_operation_count,
            false,
        )
    };
    if wrote_design_draft && !design_draft_exists_after_write {
        proof_status = GovernanceWriteProofStatus::Failed;
    }
    if draft
        .as_ref()
        .is_some_and(|draft| !draft.paper_only || draft.allowed_operations.is_empty())
        || unsafe_allowed_operation_detected
    {
        proof_status = GovernanceWriteProofStatus::Failed;
    }
    Ok(PaperPolicyTrialDesignDraftWriteProof {
        proof_id: format!(
            "design-draft-write-proof-{}",
            owner_review_run_result.run_id
        ),
        expected_output_path: output_path.to_string_lossy().to_string(),
        wrote_design_draft,
        design_draft_exists_after_write,
        draft_id,
        paper_only,
        forbidden_operation_count,
        allowed_operation_count,
        proof_status,
    })
}

pub fn prove_governance_review_decision_ledger_write(
    owner_review_run_result: &GovernanceRecommendationOwnerReviewRunResult,
    output_path: &Path,
) -> Result<GovernanceReviewDecisionLedgerWriteProof, String> {
    validate_local_json_path(output_path, "governance review decision ledger proof path")?;
    let wrote_review_ledger = owner_review_run_result.review_decision_ledger.is_some();
    let review_ledger_exists_after_write = output_path.exists();
    let mut proof_status = GovernanceWriteProofStatus::Proven;
    let ledger = if review_ledger_exists_after_write {
        load_governance_recommendation_review_decision_ledger_from_local_json(output_path)?
    } else {
        owner_review_run_result
            .review_decision_ledger
            .clone()
            .unwrap_or_else(default_governance_recommendation_review_decision_ledger)
    };
    if wrote_review_ledger && !review_ledger_exists_after_write {
        proof_status = GovernanceWriteProofStatus::Failed;
    }
    let entry_count = ledger.entries.len();
    let paper_only_count = ledger
        .entries
        .iter()
        .filter(|entry| entry.paper_only)
        .count();
    let policy_apply_allowed_true_count = ledger
        .entries
        .iter()
        .filter(|entry| entry.policy_apply_allowed)
        .count();
    let unsafe_entry_count = ledger
        .entries
        .iter()
        .filter(|entry| !detect_owner_governance_review_unsafe_terms(&entry.explanation).is_empty())
        .count();
    if paper_only_count != entry_count
        || policy_apply_allowed_true_count > 0
        || unsafe_entry_count > 0
    {
        proof_status = GovernanceWriteProofStatus::Failed;
    }
    Ok(GovernanceReviewDecisionLedgerWriteProof {
        proof_id: format!(
            "review-ledger-write-proof-{}",
            owner_review_run_result.run_id
        ),
        expected_output_path: output_path.to_string_lossy().to_string(),
        wrote_review_ledger,
        review_ledger_exists_after_write,
        entry_count,
        paper_only_count,
        policy_apply_allowed_true_count,
        unsafe_entry_count,
        proof_status,
        paper_only: ledger.paper_only,
    })
}

pub fn load_governance_owner_review_samples_from_local_json(
    path: &Path,
) -> Result<GovernanceOwnerReviewSamplesFixture, String> {
    validate_local_json_path(path, "governance owner review samples path")?;
    let text = std::fs::read_to_string(path)
        .map_err(|err| format!("failed to read governance owner review samples: {err}"))?;
    serde_json::from_str(&text)
        .map_err(|err| format!("failed to parse governance owner review samples: {err}"))
}

pub fn validate_governance_owner_review_samples(
    fixture: &GovernanceOwnerReviewSamplesFixture,
) -> Result<(), String> {
    if !fixture.paper_only {
        return Err("governance owner review samples must remain paper_only=true".to_string());
    }
    if fixture.samples.is_empty() {
        return Err("governance owner review samples cannot be empty".to_string());
    }
    for sample in &fixture.samples {
        if sample.sample_id.trim().is_empty() {
            return Err("governance owner review sample_id cannot be empty".to_string());
        }
        if sample.raw_text.trim().is_empty() {
            return Err(format!(
                "governance owner review sample {} cannot have empty raw_text",
                sample.sample_id
            ));
        }
        if !sample.paper_only {
            return Err(format!(
                "governance owner review sample {} must remain paper_only=true",
                sample.sample_id
            ));
        }
    }
    Ok(())
}

pub fn run_owner_review_parser_sample_tests(
    fixture: &GovernanceOwnerReviewSamplesFixture,
) -> Result<GovernanceOwnerReviewSampleFixtureResult, String> {
    validate_governance_owner_review_samples(fixture)?;
    let mut failed_sample_ids = Vec::new();
    for sample in &fixture.samples {
        let parsed = parse_owner_governance_review_text(&sample.raw_text);
        let reason_matches = match sample.expected_reason.as_ref() {
            None => true,
            Some(expected) => parsed
                .unsafe_reason
                .as_ref()
                .is_some_and(|reason| reason.contains(expected)),
        };
        if parsed.intent != sample.expected_intent
            || parsed.safe != sample.expected_safe
            || !reason_matches
        {
            failed_sample_ids.push(sample.sample_id.clone());
        }
    }
    let failed_count = failed_sample_ids.len();
    Ok(GovernanceOwnerReviewSampleFixtureResult {
        fixture_id: fixture.fixture_id.clone(),
        sample_count: fixture.samples.len(),
        passed_count: fixture.samples.len().saturating_sub(failed_count),
        failed_sample_ids,
        run_status: if failed_count == 0 {
            PaperGovernanceTrialRunStatus::Passed
        } else {
            PaperGovernanceTrialRunStatus::Failed
        },
        paper_only: true,
    })
}

