pub fn run_governance_owner_review_firewall_regression(
    samples: &[GovernanceOwnerReviewSample],
) -> GovernanceOwnerReviewFirewallRegressionResult {
    let mut safe_paper_trial_approval_preserved = false;
    let mut forced_apply_detected = false;
    let mut forced_order_detected = false;
    let mut leverage_detected = false;
    let mut guaranteed_profit_detected = false;
    let mut broker_account_detected = false;
    for sample in samples {
        let parsed = parse_owner_governance_review_text(&sample.raw_text);
        let unsafe_reason = parsed.unsafe_reason.clone().unwrap_or_default();
        if sample.expected_intent == OwnerGovernanceReviewIntent::ApproveForPaperTrialDesign
            && parsed.intent == OwnerGovernanceReviewIntent::ApproveForPaperTrialDesign
            && parsed.safe
        {
            safe_paper_trial_approval_preserved = true;
        }
        if !parsed.safe
            && (unsafe_reason.contains("force-apply") || unsafe_reason.contains("apply-now"))
        {
            forced_apply_detected = true;
        }
        if !parsed.safe && unsafe_reason.contains("order-submit") {
            forced_order_detected = true;
        }
        if !parsed.safe && unsafe_reason.contains("leverage") {
            leverage_detected = true;
        }
        if !parsed.safe && unsafe_reason.contains("guaranteed-profit") {
            guaranteed_profit_detected = true;
        }
        if !parsed.safe && unsafe_reason.contains("broker-account") {
            broker_account_detected = true;
        }
    }
    let policy_apply_allowed_false_preserved = true;
    GovernanceOwnerReviewFirewallRegressionResult {
        regression_id: "governance-owner-review-firewall-regression".to_string(),
        forced_apply_detected,
        forced_order_detected,
        leverage_detected,
        guaranteed_profit_detected,
        broker_account_detected,
        safe_paper_trial_approval_preserved,
        policy_apply_allowed_false_preserved,
        regression_status: if safe_paper_trial_approval_preserved
            && forced_apply_detected
            && forced_order_detected
            && leverage_detected
            && guaranteed_profit_detected
            && broker_account_detected
            && policy_apply_allowed_false_preserved
        {
            PaperGovernanceTrialRunStatus::Passed
        } else {
            PaperGovernanceTrialRunStatus::Failed
        },
        paper_only: true,
    }
}

pub fn run_governance_recommendation_owner_review_v2(
    materialization_result: &GovernanceRecommendationSupportMaterializationRunResult,
    owner_review_input: Option<&OwnerGovernanceReviewInput>,
    config: &GovernanceRecommendationOwnerReviewRunConfig,
) -> Result<GovernanceRecommendationOwnerReviewRunV2Result, String> {
    let owner_review_run_result = run_governance_recommendation_owner_review(
        materialization_result,
        owner_review_input,
        config,
    )?;
    let mut verify_result = if let Some(verify_config) = config.verify_config.as_ref() {
        Some(verify_governance_owner_review_run(
            &owner_review_run_result,
            verify_config,
        )?)
    } else {
        None
    };
    if let Some(result) = verify_result.as_mut() {
        if !config.dry_run {
            result.review_ledger_written = config
                .review_ledger_output_path
                .as_ref()
                .is_some_and(|path| Path::new(path).exists());
            result.design_draft_written = config
                .design_draft_output_path
                .as_ref()
                .is_some_and(|path| Path::new(path).exists());
            if config
                .verify_config
                .as_ref()
                .is_some_and(|cfg| cfg.require_design_draft)
                && !result.design_draft_written
            {
                result.verify_status = PaperGovernanceTrialRunStatus::Failed;
                result
                    .warnings
                    .push("design draft write proof expected a written draft".to_string());
            }
        }
    }
    let design_draft_write_proof = if !config.dry_run {
        config
            .design_draft_output_path
            .as_ref()
            .filter(|path| !path.trim().is_empty())
            .map(|path| {
                prove_paper_policy_trial_design_draft_write(
                    &owner_review_run_result,
                    Path::new(path),
                )
            })
            .transpose()?
    } else {
        None
    };
    let review_ledger_write_proof = if !config.dry_run {
        config
            .review_ledger_output_path
            .as_ref()
            .filter(|path| !path.trim().is_empty())
            .map(|path| {
                prove_governance_review_decision_ledger_write(
                    &owner_review_run_result,
                    Path::new(path),
                )
            })
            .transpose()?
    } else {
        None
    };
    let sample_fixture = if let Some(path) = config
        .owner_review_samples_path
        .as_ref()
        .filter(|path| !path.trim().is_empty())
    {
        Some(load_governance_owner_review_samples_from_local_json(
            Path::new(path),
        )?)
    } else {
        None
    };
    let sample_fixture_result = sample_fixture
        .as_ref()
        .map(run_owner_review_parser_sample_tests)
        .transpose()?;
    let firewall_regression_result = if config.run_firewall_regression {
        let regression_fixture = sample_fixture
            .clone()
            .unwrap_or_else(default_governance_owner_review_firewall_regression_samples);
        Some(run_governance_owner_review_firewall_regression(
            &regression_fixture.samples,
        ))
    } else {
        None
    };
    let has_failure = owner_review_run_result.run_status == PaperGovernanceTrialRunStatus::Failed
        || verify_result
            .as_ref()
            .is_some_and(|result| result.verify_status == PaperGovernanceTrialRunStatus::Failed)
        || design_draft_write_proof
            .as_ref()
            .is_some_and(|proof| proof.proof_status == GovernanceWriteProofStatus::Failed)
        || review_ledger_write_proof
            .as_ref()
            .is_some_and(|proof| proof.proof_status == GovernanceWriteProofStatus::Failed)
        || sample_fixture_result
            .as_ref()
            .is_some_and(|result| result.run_status == PaperGovernanceTrialRunStatus::Failed)
        || firewall_regression_result.as_ref().is_some_and(|result| {
            result.regression_status == PaperGovernanceTrialRunStatus::Failed
        });
    let has_warning = owner_review_run_result.run_status
        == PaperGovernanceTrialRunStatus::PassedWithWarnings
        || verify_result.as_ref().is_some_and(|result| {
            result.verify_status == PaperGovernanceTrialRunStatus::PassedWithWarnings
        })
        || design_draft_write_proof.as_ref().is_some_and(|proof| {
            proof.proof_status == GovernanceWriteProofStatus::ProvenWithWarnings
        })
        || review_ledger_write_proof.as_ref().is_some_and(|proof| {
            proof.proof_status == GovernanceWriteProofStatus::ProvenWithWarnings
        });
    Ok(GovernanceRecommendationOwnerReviewRunV2Result {
        run_id: config.run_id.clone(),
        owner_review_run_result,
        verify_result,
        design_draft_write_proof,
        review_ledger_write_proof,
        sample_fixture_result,
        firewall_regression_result,
        run_status: if has_failure {
            PaperGovernanceTrialRunStatus::Failed
        } else if has_warning {
            PaperGovernanceTrialRunStatus::PassedWithWarnings
        } else {
            PaperGovernanceTrialRunStatus::Passed
        },
        paper_only: true,
    })
}

fn maybe_run_governance_recommendation_owner_review_for_batch_result(
    run_id: String,
    enabled: bool,
    dry_run: bool,
    owner_review_text: Option<&String>,
    owner_review_input_path: Option<&String>,
    review_ledger_output_path: Option<&String>,
    design_draft_output_path: Option<&String>,
    output_path: Option<&String>,
    emit_owner_summary: bool,
    verify_enabled: bool,
    verify_expected_intent: Option<OwnerGovernanceReviewIntent>,
    verify_require_design_draft: bool,
    owner_review_samples_path: Option<&String>,
    run_firewall_regression: bool,
    batch_result: &mut BatchCommitteeCycleResult,
) -> Result<Option<GovernanceRecommendationOwnerReviewRunV2Result>, String> {
    if !governance_recommendation_owner_review_requested_from_flags(
        enabled,
        dry_run,
        owner_review_text,
        owner_review_input_path,
        review_ledger_output_path,
        design_draft_output_path,
        output_path,
        emit_owner_summary,
        verify_enabled,
        verify_expected_intent,
        verify_require_design_draft,
        owner_review_samples_path,
        run_firewall_regression,
    ) {
        return Ok(None);
    }
    let materialization_result = batch_result
        .governance_recommendation_support_materialization_run_result
        .clone()
        .ok_or_else(|| {
            "governance recommendation owner review requires support materialization result"
                .to_string()
        })?;
    let owner_review_input = if let Some(path) =
        owner_review_input_path.filter(|path| !path.trim().is_empty())
    {
        Some(load_owner_governance_review_input_from_local_json(
            Path::new(path),
        )?)
    } else if let Some(text) = owner_review_text.filter(|text| !text.trim().is_empty()) {
        let normalized_summary = normalize_owner_governance_review_text(text);
        Some(OwnerGovernanceReviewInput {
            input_id: format!("owner-review-{}", run_id),
            raw_text: text.clone(),
            parsed_intent: owner_governance_review_intent_from_text(&normalized_summary),
            target_candidate_id: Some(materialization_result.candidate_v2.candidate_id.clone()),
            target_proposal_id: materialization_result.candidate_v2.proposal_id.clone(),
            owner_summary: if normalized_summary.is_empty() {
                "owner review input provided without summary".to_string()
            } else {
                normalized_summary.clone()
            },
            unsafe_terms_detected: detect_owner_governance_review_unsafe_terms(&normalized_summary),
            paper_only: true,
        })
    } else {
        None
    };
    let result = run_governance_recommendation_owner_review_v2(
        &materialization_result,
        owner_review_input.as_ref(),
        &GovernanceRecommendationOwnerReviewRunConfig {
            run_id,
            enabled,
            review_packet_input_path: None,
            owner_review_text: owner_review_text.cloned(),
            owner_review_input_path: owner_review_input_path.cloned(),
            review_ledger_input_path: None,
            review_ledger_output_path: review_ledger_output_path.cloned(),
            design_draft_output_path: design_draft_output_path.cloned(),
            output_path: output_path.cloned(),
            dry_run,
            emit_owner_summary,
            verify_config: if verify_enabled
                || verify_expected_intent.is_some()
                || verify_require_design_draft
            {
                Some(GovernanceOwnerReviewVerifyConfig {
                    verify_id: "governance-owner-review-verify".to_string(),
                    config_path: None,
                    expected_owner_intent: verify_expected_intent
                        .unwrap_or(OwnerGovernanceReviewIntent::Unknown),
                    require_design_draft: verify_require_design_draft,
                    require_policy_apply_locked: true,
                    require_firewall_preserved: true,
                    require_no_mutation: true,
                    paper_only: true,
                })
            } else {
                None
            },
            owner_review_samples_path: owner_review_samples_path.cloned(),
            run_firewall_regression,
            paper_only: true,
        },
    )?;
    batch_result.governance_recommendation_review_packet =
        Some(result.owner_review_run_result.review_packet.clone());
    batch_result.owner_governance_review_input = owner_review_input;
    batch_result.owner_governance_review_parse_result = result
        .owner_review_run_result
        .owner_review_parse_result
        .clone();
    batch_result.chairman_governance_review_evaluation = Some(
        result
            .owner_review_run_result
            .chairman_review_evaluation
            .clone(),
    );
    batch_result.paper_policy_trial_design_draft = result
        .owner_review_run_result
        .paper_policy_trial_design_draft
        .clone();
    batch_result.governance_policy_apply_firewall =
        Some(result.owner_review_run_result.policy_apply_firewall.clone());
    batch_result.governance_recommendation_review_decision_ledger = result
        .owner_review_run_result
        .review_decision_ledger
        .clone();
    batch_result.owner_governance_review_summary =
        result.owner_review_run_result.owner_summary.clone();
    batch_result.governance_recommendation_owner_review_run_result =
        Some(result.owner_review_run_result.clone());
    batch_result.governance_owner_review_verify_result = result.verify_result.clone();
    batch_result.paper_policy_trial_design_draft_write_proof =
        result.design_draft_write_proof.clone();
    batch_result.governance_review_decision_ledger_write_proof =
        result.review_ledger_write_proof.clone();
    batch_result.governance_owner_review_sample_fixture_result =
        result.sample_fixture_result.clone();
    batch_result.governance_owner_review_firewall_regression_result =
        result.firewall_regression_result.clone();
    batch_result.governance_recommendation_owner_review_run_v2_result = Some(result.clone());
    Ok(Some(result))
}

pub fn paper_policy_trial_plan_requested_from_flags(
    enabled: bool,
    dry_run: bool,
    write_output: bool,
    design_draft_input_path: Option<&String>,
    _output_path: Option<&String>,
    _emit_owner_summary: bool,
) -> bool {
    enabled
        || !dry_run
        || write_output
        || design_draft_input_path
            .map(|path| !path.trim().is_empty())
            .unwrap_or(false)
}

