pub fn build_paper_policy_trial_plan_from_design_draft(
    draft: &PaperPolicyTrialDesignDraft,
) -> PaperPolicyTrialPlan {
    PaperPolicyTrialPlan {
        plan_id: format!("paper-policy-trial-plan-{}", draft.source_candidate_id),
        source_design_draft_id: draft.draft_id.clone(),
        source_candidate_id: Some(draft.source_candidate_id.clone()),
        source_proposal_id: draft.source_proposal_id.clone(),
        trial_mode: PaperPolicyTrialMode::PaperOnly,
        policy_apply_allowed: false,
        actual_score_mutation_allowed: false,
        actual_voice_mutation_allowed: false,
        committee_decision_mutation_allowed: false,
        risk_governor_override_allowed: false,
        trade_order_account_allowed: false,
        trial_cycles: draft.min_trial_cycles.max(3),
        scenario_matrix_id: None,
        success_metric_contract_id: None,
        failure_metric_contract_id: None,
        stop_condition_contract_id: None,
        paper_only: true,
    }
}

pub fn validate_paper_policy_trial_plan(
    plan: &PaperPolicyTrialPlan,
) -> PaperPolicyTrialPlanValidationResult {
    let mut blockers = Vec::new();
    if plan.trial_mode != PaperPolicyTrialMode::PaperOnly {
        blockers.push("trial_mode must remain PaperOnly".to_string());
    }
    if plan.policy_apply_allowed {
        blockers.push("policy_apply_allowed must remain false".to_string());
    }
    if plan.actual_score_mutation_allowed {
        blockers.push("actual score mutation must remain disabled".to_string());
    }
    if plan.actual_voice_mutation_allowed {
        blockers.push("actual voice mutation must remain disabled".to_string());
    }
    if plan.committee_decision_mutation_allowed {
        blockers.push("committee decision mutation must remain disabled".to_string());
    }
    if plan.risk_governor_override_allowed {
        blockers.push("risk governor override must remain disabled".to_string());
    }
    if plan.trade_order_account_allowed {
        blockers.push("trade/order/account must remain disabled".to_string());
    }
    if !plan.paper_only {
        blockers.push("paper_only must remain true".to_string());
    }
    let warnings = if plan.trial_cycles < 3 {
        vec!["trial_cycles is below the conservative default of 3".to_string()]
    } else {
        Vec::new()
    };
    PaperPolicyTrialPlanValidationResult {
        plan_id: plan.plan_id.clone(),
        valid: blockers.is_empty(),
        policy_apply_allowed_false: !plan.policy_apply_allowed,
        actual_mutation_disabled: !plan.actual_score_mutation_allowed
            && !plan.actual_voice_mutation_allowed
            && !plan.committee_decision_mutation_allowed,
        risk_governor_override_disabled: !plan.risk_governor_override_allowed,
        trade_order_account_disabled: !plan.trade_order_account_allowed,
        paper_only: plan.paper_only,
        validation_status: if !blockers.is_empty() {
            PaperPolicyTrialPlanValidationStatus::Invalid
        } else if warnings.is_empty() {
            PaperPolicyTrialPlanValidationStatus::Valid
        } else {
            PaperPolicyTrialPlanValidationStatus::ValidWithWarnings
        },
        blockers,
        warnings,
    }
}

