pub fn validate_paper_policy_trial_scenario_matrix(
    matrix: &PaperPolicyTrialScenarioMatrix,
) -> PaperPolicyTrialScenarioMatrixValidationResult {
    let mut blockers = Vec::new();
    if !matrix.includes_korea_short_long {
        blockers.push("scenario matrix must include Korea short/long contracts".to_string());
    }
    if !matrix.includes_us_short_long {
        blockers.push("scenario matrix must include US short/long contracts".to_string());
    }
    if !matrix.includes_crypto_short_long {
        blockers.push("scenario matrix must include Crypto short/long contracts".to_string());
    }
    if !matrix.includes_risk_veto_case {
        blockers.push("scenario matrix must include risk veto case".to_string());
    }
    if !matrix.includes_evidence_gap_case {
        blockers.push("scenario matrix must include evidence gap case".to_string());
    }
    if !matrix.includes_owner_reference_case {
        blockers.push("scenario matrix must include owner reference case".to_string());
    }
    if !matrix.paper_only {
        blockers.push("scenario matrix must remain paper_only=true".to_string());
    }
    PaperPolicyTrialScenarioMatrixValidationResult {
        matrix_id: matrix.matrix_id.clone(),
        valid: blockers.is_empty(),
        validation_status: if blockers.is_empty() {
            PaperPolicyTrialPlanValidationStatus::Valid
        } else {
            PaperPolicyTrialPlanValidationStatus::Invalid
        },
        blockers,
        warnings: Vec::new(),
        paper_only: true,
    }
}

fn default_paper_policy_trial_success_metric_contract() -> PaperPolicyTrialSuccessMetricContract {
    PaperPolicyTrialSuccessMetricContract {
        contract_id: "paper-policy-trial-success-metrics".to_string(),
        required_metrics: vec![
            PaperPolicyTrialSuccessMetric::RiskGovernorAlignmentImproved,
            PaperPolicyTrialSuccessMetric::OwnerExplanationGenerated,
            PaperPolicyTrialSuccessMetric::CommitteeDecisionUnchangedActual,
        ],
        optional_metrics: vec![
            PaperPolicyTrialSuccessMetric::RiskRegressionReduced,
            PaperPolicyTrialSuccessMetric::HelpfulDissentPreserved,
            PaperPolicyTrialSuccessMetric::EvidenceCautionImproved,
            PaperPolicyTrialSuccessMetric::OverconfidentCallReduced,
            PaperPolicyTrialSuccessMetric::VoiceConcentrationControlled,
            PaperPolicyTrialSuccessMetric::NoTradeBiasControlled,
        ],
        minimum_required_pass_count: 3,
        paper_only: true,
    }
}

pub fn evaluate_paper_policy_trial_success_metrics(
    plan: &PaperPolicyTrialPlan,
    _previous_trial_results: Option<&PaperGovernanceTrialRunResult>,
) -> PaperPolicyTrialSuccessMetricEvaluation {
    let contract = default_paper_policy_trial_success_metric_contract();
    let mut passed_metrics = Vec::new();
    if !plan.policy_apply_allowed {
        passed_metrics.push(PaperPolicyTrialSuccessMetric::RiskGovernorAlignmentImproved);
        passed_metrics.push(PaperPolicyTrialSuccessMetric::CommitteeDecisionUnchangedActual);
    }
    if plan.paper_only {
        passed_metrics.push(PaperPolicyTrialSuccessMetric::OwnerExplanationGenerated);
        passed_metrics.push(PaperPolicyTrialSuccessMetric::RiskRegressionReduced);
        passed_metrics.push(PaperPolicyTrialSuccessMetric::HelpfulDissentPreserved);
        passed_metrics.push(PaperPolicyTrialSuccessMetric::VoiceConcentrationControlled);
        passed_metrics.push(PaperPolicyTrialSuccessMetric::NoTradeBiasControlled);
    }
    let pass_count = passed_metrics.len();
    let success_status = if pass_count >= contract.minimum_required_pass_count {
        PaperPolicyTrialSuccessStatus::Passed
    } else {
        PaperPolicyTrialSuccessStatus::InsufficientData
    };
    PaperPolicyTrialSuccessMetricEvaluation {
        contract_id: contract.contract_id.clone(),
        passed_metrics,
        failed_metrics: Vec::new(),
        warning_metrics: Vec::new(),
        pass_count,
        success_status,
        paper_only: true,
    }
}

fn default_paper_policy_trial_failure_metric_contract() -> PaperPolicyTrialFailureMetricContract {
    PaperPolicyTrialFailureMetricContract {
        contract_id: "paper-policy-trial-failure-metrics".to_string(),
        blocking_failure_metrics: vec![
            PaperPolicyTrialFailureMetric::AnyActualMutationDetected,
            PaperPolicyTrialFailureMetric::AnyTradeOrderAccountDetected,
        ],
        warning_failure_metrics: vec![
            PaperPolicyTrialFailureMetric::OwnerOpinionForcedApply,
            PaperPolicyTrialFailureMetric::VoiceConcentrationTooHigh,
        ],
        paper_only: true,
    }
}

pub fn evaluate_paper_policy_trial_failure_metrics(
    plan: &PaperPolicyTrialPlan,
    safety_guard: Option<&GovernancePolicyApplyFirewall>,
    _previous_trial_results: Option<&PaperGovernanceTrialRunResult>,
) -> PaperPolicyTrialFailureMetricEvaluation {
    let contract = default_paper_policy_trial_failure_metric_contract();
    let mut blocking_failures = Vec::new();
    let mut warning_failures = Vec::new();
    if plan.actual_score_mutation_allowed
        || plan.actual_voice_mutation_allowed
        || plan.committee_decision_mutation_allowed
        || plan.risk_governor_override_allowed
        || safety_guard.is_some_and(|guard| {
            guard.actual_score_mutation_detected
                || guard.actual_voice_mutation_detected
                || guard.committee_decision_mutation_detected
                || guard.risk_governor_override_detected
        })
    {
        blocking_failures.push(PaperPolicyTrialFailureMetric::AnyActualMutationDetected);
    }
    if plan.trade_order_account_allowed
        || safety_guard.is_some_and(|guard| {
            guard.trade_signal_detected
                || guard.order_detected
                || guard.broker_order_account_detected
        })
    {
        blocking_failures.push(PaperPolicyTrialFailureMetric::AnyTradeOrderAccountDetected);
    }
    if safety_guard.is_some_and(|guard| guard.owner_forced_apply_detected) {
        warning_failures.push(PaperPolicyTrialFailureMetric::OwnerOpinionForcedApply);
    }
    let failure_status = if !blocking_failures.is_empty() {
        PaperPolicyTrialFailureStatus::Blocked
    } else if !warning_failures.is_empty() {
        PaperPolicyTrialFailureStatus::ClearWithWarnings
    } else {
        PaperPolicyTrialFailureStatus::Clear
    };
    PaperPolicyTrialFailureMetricEvaluation {
        contract_id: contract.contract_id.clone(),
        blocking_failures: blocking_failures.clone(),
        warning_failures: warning_failures.clone(),
        failure_status,
        paper_only: true,
    }
}

fn default_paper_policy_trial_stop_condition_contract() -> PaperPolicyTrialStopConditionContract {
    PaperPolicyTrialStopConditionContract {
        contract_id: "paper-policy-trial-stop-conditions".to_string(),
        stop_conditions: vec![
            PaperPolicyTrialStopCondition::RiskRegressionDetected,
            PaperPolicyTrialStopCondition::ActualMutationDetected,
            PaperPolicyTrialStopCondition::TradeOrderAccountDetected,
            PaperPolicyTrialStopCondition::OwnerForcedApplyDetected,
        ],
        max_allowed_warning_cycles: 1,
        paper_only: true,
    }
}

pub fn evaluate_paper_policy_trial_stop_conditions(
    plan: &PaperPolicyTrialPlan,
    failure_eval: &PaperPolicyTrialFailureMetricEvaluation,
    _trend_eval: Option<&PaperGovernanceTrialRunResult>,
) -> PaperPolicyTrialStopConditionEvaluation {
    let contract = default_paper_policy_trial_stop_condition_contract();
    let mut triggered_conditions = Vec::new();
    if plan.actual_score_mutation_allowed
        || plan.actual_voice_mutation_allowed
        || plan.committee_decision_mutation_allowed
    {
        triggered_conditions.push(PaperPolicyTrialStopCondition::ActualMutationDetected);
    }
    if plan.trade_order_account_allowed {
        triggered_conditions.push(PaperPolicyTrialStopCondition::TradeOrderAccountDetected);
    }
    if failure_eval
        .warning_failures
        .contains(&PaperPolicyTrialFailureMetric::OwnerOpinionForcedApply)
    {
        triggered_conditions.push(PaperPolicyTrialStopCondition::OwnerForcedApplyDetected);
    }
    if failure_eval.failure_status == PaperPolicyTrialFailureStatus::Blocked {
        triggered_conditions.push(PaperPolicyTrialStopCondition::RiskRegressionDetected);
    }
    PaperPolicyTrialStopConditionEvaluation {
        contract_id: contract.contract_id,
        stop_required: !triggered_conditions.is_empty(),
        stop_status: if triggered_conditions.is_empty() {
            PaperPolicyTrialStopStatus::Continue
        } else {
            PaperPolicyTrialStopStatus::Stop
        },
        triggered_conditions,
        paper_only: true,
    }
}

pub fn run_paper_policy_trial_plan_dry_run_validation(
    plan: &PaperPolicyTrialPlan,
    scenario_matrix: &PaperPolicyTrialScenarioMatrix,
    safety_guard: Option<&GovernancePolicyApplyFirewall>,
) -> PaperPolicyTrialDryRunValidationResult {
    let plan_validation = validate_paper_policy_trial_plan(plan);
    let scenario_matrix_validation = validate_paper_policy_trial_scenario_matrix(scenario_matrix);
    let success_metric_evaluation = evaluate_paper_policy_trial_success_metrics(plan, None);
    let failure_metric_evaluation =
        evaluate_paper_policy_trial_failure_metrics(plan, safety_guard, None);
    let stop_condition_evaluation =
        evaluate_paper_policy_trial_stop_conditions(plan, &failure_metric_evaluation, None);
    let policy_apply_firewall_status = if safety_guard
        .map(|guard| guard.firewall_status)
        .unwrap_or(GovernancePolicyApplyFirewallStatus::Preserved)
        == GovernancePolicyApplyFirewallStatus::Violated
        || plan.policy_apply_allowed
    {
        GovernancePolicyApplyFirewallStatus::Violated
    } else {
        GovernancePolicyApplyFirewallStatus::Preserved
    };
    let dry_run_status = if plan_validation.validation_status
        == PaperPolicyTrialPlanValidationStatus::Invalid
        || scenario_matrix_validation.validation_status
            == PaperPolicyTrialPlanValidationStatus::Invalid
        || failure_metric_evaluation.failure_status == PaperPolicyTrialFailureStatus::Blocked
        || stop_condition_evaluation.stop_required
        || policy_apply_firewall_status == GovernancePolicyApplyFirewallStatus::Violated
    {
        PaperGovernanceTrialRunStatus::Failed
    } else if success_metric_evaluation.success_status == PaperPolicyTrialSuccessStatus::Passed {
        PaperGovernanceTrialRunStatus::Passed
    } else {
        PaperGovernanceTrialRunStatus::PassedWithWarnings
    };
    PaperPolicyTrialDryRunValidationResult {
        validation_id: format!("paper-policy-trial-dry-run-{}", plan.plan_id),
        plan_validation,
        scenario_matrix_validation,
        success_metric_evaluation,
        failure_metric_evaluation,
        stop_condition_evaluation,
        policy_apply_firewall_status,
        dry_run_status,
        paper_only: true,
    }
}

pub fn prove_paper_policy_trial_plan_write(
    plan: &PaperPolicyTrialPlan,
    output_path: &Path,
) -> Result<PaperPolicyTrialPlanWriteProof, String> {
    validate_local_json_path(output_path, "paper policy trial plan output path")?;
    let wrote_trial_plan = true;
    let trial_plan_exists_after_write = output_path.exists();
    let loaded_plan = if trial_plan_exists_after_write {
        let text = std::fs::read_to_string(output_path)
            .map_err(|err| format!("failed to read paper policy trial plan proof file: {err}"))?;
        serde_json::from_str::<PaperPolicyTrialPlan>(&text)
            .map_err(|err| format!("failed to parse paper policy trial plan proof file: {err}"))?
    } else {
        plan.clone()
    };
    let forbidden_flag_count = [
        loaded_plan.policy_apply_allowed,
        loaded_plan.actual_score_mutation_allowed,
        loaded_plan.actual_voice_mutation_allowed,
        loaded_plan.committee_decision_mutation_allowed,
        loaded_plan.risk_governor_override_allowed,
        loaded_plan.trade_order_account_allowed,
    ]
    .iter()
    .filter(|flag| **flag)
    .count();
    Ok(PaperPolicyTrialPlanWriteProof {
        proof_id: format!("paper-policy-trial-plan-write-proof-{}", plan.plan_id),
        expected_output_path: output_path.to_string_lossy().to_string(),
        wrote_trial_plan,
        trial_plan_exists_after_write,
        plan_id: Some(loaded_plan.plan_id.clone()),
        paper_only: loaded_plan.paper_only,
        policy_apply_allowed: loaded_plan.policy_apply_allowed,
        forbidden_flag_count,
        proof_status: if (!trial_plan_exists_after_write && wrote_trial_plan)
            || loaded_plan.policy_apply_allowed
            || forbidden_flag_count > 0
            || !loaded_plan.paper_only
        {
            GovernanceWriteProofStatus::Failed
        } else {
            GovernanceWriteProofStatus::Proven
        },
    })
}

pub fn build_owner_paper_policy_trial_plan_summary(
    plan: &PaperPolicyTrialPlan,
    dry_run_validation: &PaperPolicyTrialDryRunValidationResult,
) -> OwnerPaperPolicyTrialPlanSummary {
    let scenario_matrix = build_default_paper_policy_trial_scenario_matrix();
    let success_contract = default_paper_policy_trial_success_metric_contract();
    let failure_contract = default_paper_policy_trial_failure_metric_contract();
    let stop_contract = default_paper_policy_trial_stop_condition_contract();
    OwnerPaperPolicyTrialPlanSummary {
        summary_id: format!("owner-paper-policy-trial-plan-summary-{}", plan.plan_id),
        plan_id: plan.plan_id.clone(),
        scenario_count: scenario_matrix.scenario_count,
        success_metric_count: success_contract.required_metrics.len()
            + success_contract.optional_metrics.len(),
        failure_metric_count: failure_contract.blocking_failure_metrics.len()
            + failure_contract.warning_failure_metrics.len(),
        stop_condition_count: stop_contract.stop_conditions.len(),
        dry_run_status: dry_run_validation.dry_run_status,
        message: "Paper policy trial plan was built for evaluation only. Policy apply remains locked. Actual score, voice, decisions, Risk Governor, and trading remain unchanged. Stop conditions will stop only the paper trial.".to_string(),
        paper_trial_only: true,
        policy_apply_allowed: false,
        no_actual_policy_apply: true,
        no_score_mutation: true,
        no_voice_mutation: true,
        no_committee_decision_change: true,
        no_risk_override: true,
        not_trade_signal: true,
        paper_only: true,
    }
}

pub fn run_paper_policy_trial_plan_builder(
    design_draft: &PaperPolicyTrialDesignDraft,
    config: &PaperPolicyTrialPlanRunConfig,
) -> Result<PaperPolicyTrialPlanRunResult, String> {
    let mut trial_plan = build_paper_policy_trial_plan_from_design_draft(design_draft);
    let scenario_matrix = build_default_paper_policy_trial_scenario_matrix();
    let success_metric_contract = default_paper_policy_trial_success_metric_contract();
    let failure_metric_contract = default_paper_policy_trial_failure_metric_contract();
    let stop_condition_contract = default_paper_policy_trial_stop_condition_contract();
    trial_plan.scenario_matrix_id = Some(scenario_matrix.matrix_id.clone());
    trial_plan.success_metric_contract_id = Some(success_metric_contract.contract_id.clone());
    trial_plan.failure_metric_contract_id = Some(failure_metric_contract.contract_id.clone());
    trial_plan.stop_condition_contract_id = Some(stop_condition_contract.contract_id.clone());
    let dry_run_validation =
        run_paper_policy_trial_plan_dry_run_validation(&trial_plan, &scenario_matrix, None);
    let mut trial_plan_write_proof = None;
    if !config.dry_run
        && config.write_trial_plan
        && let Some(path) = config
            .trial_plan_output_path
            .as_ref()
            .filter(|path| !path.trim().is_empty())
    {
        validate_local_json_path(Path::new(path), "paper policy trial plan output path")?;
        write_safe_json(Path::new(path), &trial_plan)?;
        trial_plan_write_proof = Some(prove_paper_policy_trial_plan_write(
            &trial_plan,
            Path::new(path),
        )?);
    }
    let owner_summary = if config.emit_owner_summary {
        Some(build_owner_paper_policy_trial_plan_summary(
            &trial_plan,
            &dry_run_validation,
        ))
    } else {
        None
    };
    let run_status = if dry_run_validation.dry_run_status == PaperGovernanceTrialRunStatus::Failed
        || trial_plan_write_proof
            .as_ref()
            .is_some_and(|proof| proof.proof_status == GovernanceWriteProofStatus::Failed)
    {
        PaperGovernanceTrialRunStatus::Failed
    } else if dry_run_validation.dry_run_status == PaperGovernanceTrialRunStatus::Passed {
        PaperGovernanceTrialRunStatus::Passed
    } else {
        PaperGovernanceTrialRunStatus::PassedWithWarnings
    };
    Ok(PaperPolicyTrialPlanRunResult {
        run_id: config.run_id.clone(),
        trial_plan,
        scenario_matrix,
        success_metric_contract,
        failure_metric_contract,
        stop_condition_contract,
        dry_run_validation,
        trial_plan_write_proof,
        owner_summary,
        run_status,
        paper_only: true,
    })
}

fn maybe_run_paper_policy_trial_plan_for_batch_result(
    run_id: String,
    enabled: bool,
    dry_run: bool,
    write_trial_plan: bool,
    design_draft_input_path: Option<&String>,
    trial_plan_output_path: Option<&String>,
    emit_owner_summary: bool,
    batch_result: &mut BatchCommitteeCycleResult,
) -> Result<Option<PaperPolicyTrialPlanRunResult>, String> {
    if !paper_policy_trial_plan_requested_from_flags(
        enabled,
        dry_run,
        write_trial_plan,
        design_draft_input_path,
        trial_plan_output_path,
        emit_owner_summary,
    ) {
        return Ok(None);
    }
    let design_draft =
        if let Some(path) = design_draft_input_path.filter(|path| !path.trim().is_empty()) {
            load_paper_policy_trial_design_draft_from_local_json(Path::new(path))?
        } else {
            batch_result
                .paper_policy_trial_design_draft
                .clone()
                .ok_or_else(|| {
                    "paper policy trial plan requires paper policy trial design draft".to_string()
                })?
        };
    let result = run_paper_policy_trial_plan_builder(
        &design_draft,
        &PaperPolicyTrialPlanRunConfig {
            run_id,
            enabled,
            design_draft_input_path: design_draft_input_path.cloned(),
            trial_plan_output_path: trial_plan_output_path.cloned(),
            dry_run,
            write_trial_plan,
            emit_owner_summary,
            paper_only: true,
        },
    )?;
    batch_result.paper_policy_trial_plan = Some(result.trial_plan.clone());
    batch_result.paper_policy_trial_plan_validation_result =
        Some(result.dry_run_validation.plan_validation.clone());
    batch_result.paper_policy_trial_scenario_matrix = Some(result.scenario_matrix.clone());
    batch_result.paper_policy_trial_success_metric_contract =
        Some(result.success_metric_contract.clone());
    batch_result.paper_policy_trial_failure_metric_contract =
        Some(result.failure_metric_contract.clone());
    batch_result.paper_policy_trial_stop_condition_contract =
        Some(result.stop_condition_contract.clone());
    batch_result.paper_policy_trial_dry_run_validation_result =
        Some(result.dry_run_validation.clone());
    batch_result.paper_policy_trial_plan_write_proof = result.trial_plan_write_proof.clone();
    batch_result.owner_paper_policy_trial_plan_summary = result.owner_summary.clone();
    batch_result.paper_policy_trial_plan_run_result = Some(result.clone());
    Ok(Some(result))
}

pub fn paper_policy_trial_scenario_execution_requested_from_flags(
    enabled: bool,
    dry_run: bool,
    write_scenario_ledger: bool,
    plan_input_path: Option<&String>,
    scenario_matrix_input_path: Option<&String>,
    scenario_ledger_input_path: Option<&String>,
    _scenario_ledger_output_path: Option<&String>,
    max_scenarios: usize,
    stop_on_first_blocking_condition: bool,
    emit_owner_summary: bool,
) -> bool {
    enabled
        || !dry_run
        || write_scenario_ledger
        || plan_input_path
            .map(|path| !path.trim().is_empty())
            .unwrap_or(false)
        || scenario_matrix_input_path
            .map(|path| !path.trim().is_empty())
            .unwrap_or(false)
        || scenario_ledger_input_path
            .map(|path| !path.trim().is_empty())
            .unwrap_or(false)
        || max_scenarios != default_paper_policy_trial_scenario_execution_max_scenarios()
        || !stop_on_first_blocking_condition
        || (enabled && emit_owner_summary)
}

fn default_paper_policy_trial_scenario_result_ledger() -> PaperPolicyTrialScenarioResultLedger {
    PaperPolicyTrialScenarioResultLedger {
        ledger_id: "paper-policy-trial-scenario-result-ledger".to_string(),
        entries: Vec::new(),
        entry_count: 0,
        latest_entry_id: None,
        paper_only: true,
    }
}

pub fn normalize_paper_policy_trial_scenario_result_ledger(
    ledger: &mut PaperPolicyTrialScenarioResultLedger,
) {
    let mut deduped = BTreeMap::new();
    for entry in &ledger.entries {
        deduped
            .entry(entry.entry_id.clone())
            .or_insert_with(|| entry.clone());
    }
    ledger.entries = deduped.into_values().collect();
    ledger
        .entries
        .sort_by(|left, right| left.entry_id.cmp(&right.entry_id));
    ledger.entry_count = ledger.entries.len();
    ledger.latest_entry_id = ledger.entries.last().map(|entry| entry.entry_id.clone());
}

fn validate_paper_policy_trial_scenario_result_ledger(
    ledger: &PaperPolicyTrialScenarioResultLedger,
) -> Result<(), String> {
    if !ledger.paper_only {
        return Err("paper policy trial scenario result ledger must stay paper_only".to_string());
    }
    reject_unsafe_owner_feedback_string(&ledger.ledger_id)?;
    if value_contains_debug_marker(
        ledger,
        &[
            "broker".to_string(),
            "order".to_string(),
            "account".to_string(),
            "trade".to_string(),
            "live".to_string(),
        ],
    ) {
        return Err(
            "paper policy trial scenario result ledger contains forbidden live-execution wording"
                .to_string(),
        );
    }
    for entry in &ledger.entries {
        if !entry.paper_only {
            return Err(format!(
                "paper policy trial scenario result ledger entry {} must stay paper_only",
                entry.entry_id
            ));
        }
        reject_unsafe_owner_feedback_string(&entry.entry_id)?;
        reject_unsafe_owner_feedback_string(&entry.run_id)?;
        reject_unsafe_owner_feedback_string(&entry.scenario_id)?;
    }
    Ok(())
}

pub fn load_paper_policy_trial_scenario_result_ledger_from_local_json(
    path: &Path,
) -> Result<PaperPolicyTrialScenarioResultLedger, String> {
    validate_local_json_path(path, "paper policy trial scenario result ledger path")?;
    let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
    let mut ledger: PaperPolicyTrialScenarioResultLedger =
        serde_json::from_str(&text).map_err(|err| err.to_string())?;
    validate_paper_policy_trial_scenario_result_ledger(&ledger)?;
    normalize_paper_policy_trial_scenario_result_ledger(&mut ledger);
    validate_paper_policy_trial_scenario_result_ledger(&ledger)?;
    Ok(ledger)
}

pub fn save_paper_policy_trial_scenario_result_ledger_to_local_json(
    path: &Path,
    ledger: &PaperPolicyTrialScenarioResultLedger,
) -> Result<(), String> {
    validate_local_json_path(path, "paper policy trial scenario result ledger path")?;
    let mut normalized = ledger.clone();
    normalize_paper_policy_trial_scenario_result_ledger(&mut normalized);
    validate_paper_policy_trial_scenario_result_ledger(&normalized)?;
    write_safe_json(path, &normalized)
}

pub fn append_paper_policy_trial_scenario_result_entries(
    ledger: &mut PaperPolicyTrialScenarioResultLedger,
    entries: &[PaperPolicyTrialScenarioResultLedgerEntry],
) -> Result<(), String> {
    validate_paper_policy_trial_scenario_result_ledger(ledger)?;
    ledger.entries.extend_from_slice(entries);
    normalize_paper_policy_trial_scenario_result_ledger(ledger);
    validate_paper_policy_trial_scenario_result_ledger(ledger)
}

pub fn latest_paper_policy_trial_scenario_result_entries(
    ledger: &PaperPolicyTrialScenarioResultLedger,
    limit: usize,
) -> Vec<PaperPolicyTrialScenarioResultLedgerEntry> {
    if limit == 0 || limit >= ledger.entries.len() {
        return ledger.entries.clone();
    }
    ledger.entries[ledger.entries.len().saturating_sub(limit)..].to_vec()
}

fn build_paper_policy_trial_scenario_execution_config_from_run(
    config: &PaperPolicyTrialScenarioExecutionRunConfig,
) -> PaperPolicyTrialScenarioExecutionConfig {
    PaperPolicyTrialScenarioExecutionConfig {
        run_id: config.run_id.clone(),
        enabled: config.enabled,
        plan_input_path: config.plan_input_path.clone(),
        scenario_matrix_input_path: config.scenario_matrix_input_path.clone(),
        scenario_result_ledger_output_path: config.scenario_result_ledger_output_path.clone(),
        max_scenarios: config.max_scenarios,
        dry_run: config.dry_run,
        write_scenario_ledger: config.write_scenario_ledger,
        stop_on_first_blocking_condition: config.stop_on_first_blocking_condition,
        emit_owner_summary: config.emit_owner_summary,
        paper_only: true,
    }
}

fn build_paper_policy_trial_success_evaluation_for_scenario(
    plan: &PaperPolicyTrialPlan,
    scenario: &PaperPolicyTrialScenario,
    contract: &PaperPolicyTrialSuccessMetricContract,
) -> PaperPolicyTrialSuccessMetricEvaluation {
    let mut passed_metrics = Vec::new();
    let mut failed_metrics = Vec::new();
    for metric in &contract.required_metrics {
        let metric_passed = match metric {
            PaperPolicyTrialSuccessMetric::RiskGovernorAlignmentImproved => {
                !plan.policy_apply_allowed && !plan.risk_governor_override_allowed
            }
            PaperPolicyTrialSuccessMetric::OwnerExplanationGenerated => {
                !matches!(
                    scenario.scenario_kind,
                    PaperPolicyTrialScenarioKind::OwnerRiskConcern
                        | PaperPolicyTrialScenarioKind::OwnerEvidenceRequest
                ) || !plan.policy_apply_allowed
            }
            PaperPolicyTrialSuccessMetric::CommitteeDecisionUnchangedActual => {
                !plan.committee_decision_mutation_allowed
            }
            _ => plan.paper_only,
        };
        if metric_passed {
            passed_metrics.push(*metric);
        } else {
            failed_metrics.push(*metric);
        }
    }
    let mut warning_metrics = Vec::new();
    for metric in &contract.optional_metrics {
        let metric_passed = match metric {
            PaperPolicyTrialSuccessMetric::VoiceConcentrationControlled => {
                !plan.actual_voice_mutation_allowed
            }
            PaperPolicyTrialSuccessMetric::NoTradeBiasControlled => {
                !plan.trade_order_account_allowed
            }
            PaperPolicyTrialSuccessMetric::EvidenceCautionImproved => {
                !matches!(
                    scenario.scenario_kind,
                    PaperPolicyTrialScenarioKind::EvidenceGap
                ) || plan.paper_only
            }
            _ => plan.paper_only,
        };
        if metric_passed {
            passed_metrics.push(*metric);
        } else {
            warning_metrics.push(*metric);
        }
    }
    let required_pass_count = contract
        .required_metrics
        .iter()
        .filter(|metric| passed_metrics.contains(metric))
        .count();
    let success_status = if !failed_metrics.is_empty() {
        PaperPolicyTrialSuccessStatus::Failed
    } else if required_pass_count >= contract.minimum_required_pass_count {
        if warning_metrics.is_empty() {
            PaperPolicyTrialSuccessStatus::Passed
        } else {
            PaperPolicyTrialSuccessStatus::PassedWithWarnings
        }
    } else {
        PaperPolicyTrialSuccessStatus::InsufficientData
    };
    PaperPolicyTrialSuccessMetricEvaluation {
        contract_id: contract.contract_id.clone(),
        passed_metrics,
        failed_metrics,
        warning_metrics,
        pass_count: required_pass_count,
        success_status,
        paper_only: true,
    }
}

fn build_paper_policy_trial_failure_evaluation_for_scenario(
    plan: &PaperPolicyTrialPlan,
    scenario: &PaperPolicyTrialScenario,
    contract: &PaperPolicyTrialFailureMetricContract,
) -> PaperPolicyTrialFailureMetricEvaluation {
    let mut blocking_failures = Vec::new();
    let mut warning_failures = Vec::new();
    if plan.policy_apply_allowed
        || plan.actual_score_mutation_allowed
        || plan.actual_voice_mutation_allowed
        || plan.committee_decision_mutation_allowed
        || plan.risk_governor_override_allowed
    {
        blocking_failures.push(PaperPolicyTrialFailureMetric::AnyActualMutationDetected);
    }
    if plan.trade_order_account_allowed {
        blocking_failures.push(PaperPolicyTrialFailureMetric::AnyTradeOrderAccountDetected);
    }
    if matches!(
        scenario.scenario_kind,
        PaperPolicyTrialScenarioKind::OwnerRiskConcern
            | PaperPolicyTrialScenarioKind::OwnerEvidenceRequest
    ) && plan.policy_apply_allowed
    {
        warning_failures.push(PaperPolicyTrialFailureMetric::OwnerOpinionForcedApply);
    }
    if plan.actual_voice_mutation_allowed {
        warning_failures.push(PaperPolicyTrialFailureMetric::VoiceConcentrationTooHigh);
    }
    let failure_status = if !blocking_failures.is_empty() {
        PaperPolicyTrialFailureStatus::Blocked
    } else if !warning_failures.is_empty() {
        PaperPolicyTrialFailureStatus::ClearWithWarnings
    } else {
        PaperPolicyTrialFailureStatus::Clear
    };
    PaperPolicyTrialFailureMetricEvaluation {
        contract_id: contract.contract_id.clone(),
        blocking_failures,
        warning_failures,
        failure_status,
        paper_only: true,
    }
}

fn build_paper_policy_trial_stop_evaluation_for_scenario(
    plan: &PaperPolicyTrialPlan,
    failure_eval: &PaperPolicyTrialFailureMetricEvaluation,
    contract: &PaperPolicyTrialStopConditionContract,
) -> PaperPolicyTrialStopConditionEvaluation {
    let mut triggered_conditions = Vec::new();
    if failure_eval
        .blocking_failures
        .contains(&PaperPolicyTrialFailureMetric::AnyActualMutationDetected)
    {
        triggered_conditions.push(PaperPolicyTrialStopCondition::ActualMutationDetected);
        triggered_conditions.push(PaperPolicyTrialStopCondition::RiskRegressionDetected);
    }
    if plan.risk_governor_override_allowed {
        triggered_conditions.push(PaperPolicyTrialStopCondition::RiskGovernorOverrideDetected);
    }
    if failure_eval
        .blocking_failures
        .contains(&PaperPolicyTrialFailureMetric::AnyTradeOrderAccountDetected)
    {
        triggered_conditions.push(PaperPolicyTrialStopCondition::TradeOrderAccountDetected);
    }
    if failure_eval
        .warning_failures
        .contains(&PaperPolicyTrialFailureMetric::OwnerOpinionForcedApply)
    {
        triggered_conditions.push(PaperPolicyTrialStopCondition::OwnerForcedApplyDetected);
    }
    if failure_eval
        .warning_failures
        .contains(&PaperPolicyTrialFailureMetric::VoiceConcentrationTooHigh)
    {
        triggered_conditions.push(PaperPolicyTrialStopCondition::VoiceConcentrationExceeded);
    }
    let stop_required = triggered_conditions.iter().any(|condition| {
        matches!(
            condition,
            PaperPolicyTrialStopCondition::RiskRegressionDetected
                | PaperPolicyTrialStopCondition::ActualMutationDetected
                | PaperPolicyTrialStopCondition::RiskGovernorOverrideDetected
                | PaperPolicyTrialStopCondition::TradeOrderAccountDetected
        )
    });
    PaperPolicyTrialStopConditionEvaluation {
        contract_id: contract.contract_id.clone(),
        triggered_conditions,
        stop_required,
        stop_status: if stop_required {
            PaperPolicyTrialStopStatus::Stop
        } else if failure_eval.failure_status == PaperPolicyTrialFailureStatus::ClearWithWarnings {
            PaperPolicyTrialStopStatus::ContinueWithWarnings
        } else {
            PaperPolicyTrialStopStatus::Continue
        },
        paper_only: true,
    }
}

fn skipped_paper_policy_trial_scenario_execution_result(
    scenario: &PaperPolicyTrialScenario,
    success_contract: &PaperPolicyTrialSuccessMetricContract,
    failure_contract: &PaperPolicyTrialFailureMetricContract,
    stop_contract: &PaperPolicyTrialStopConditionContract,
) -> PaperPolicyTrialScenarioExecutionResult {
    PaperPolicyTrialScenarioExecutionResult {
        scenario_id: scenario.scenario_id.clone(),
        scenario_kind: scenario.scenario_kind,
        market_scope: scenario.market_scope.clone(),
        symbol: scenario.symbol.clone(),
        success_metric_evaluation: PaperPolicyTrialSuccessMetricEvaluation {
            contract_id: success_contract.contract_id.clone(),
            passed_metrics: Vec::new(),
            failed_metrics: Vec::new(),
            warning_metrics: Vec::new(),
            pass_count: 0,
            success_status: PaperPolicyTrialSuccessStatus::InsufficientData,
            paper_only: true,
        },
        failure_metric_evaluation: PaperPolicyTrialFailureMetricEvaluation {
            contract_id: failure_contract.contract_id.clone(),
            blocking_failures: Vec::new(),
            warning_failures: Vec::new(),
            failure_status: PaperPolicyTrialFailureStatus::Clear,
            paper_only: true,
        },
        stop_condition_evaluation: PaperPolicyTrialStopConditionEvaluation {
            contract_id: stop_contract.contract_id.clone(),
            triggered_conditions: Vec::new(),
            stop_required: false,
            stop_status: PaperPolicyTrialStopStatus::Continue,
            paper_only: true,
        },
        risk_first_status: PaperPolicyTrialScenarioRiskFirstStatus::InsufficientData,
        voice_balance_status: PaperPolicyTrialScenarioVoiceBalanceStatus::InsufficientData,
        owner_reference_status: PaperPolicyTrialScenarioOwnerReferenceStatus::NotApplicable,
        execution_status: PaperPolicyTrialScenarioExecutionStatus::Skipped,
        warnings: vec!["scenario execution was skipped".to_string()],
        paper_only: true,
    }
}

pub fn execute_paper_policy_trial_scenario(
    plan: &PaperPolicyTrialPlan,
    scenario: &PaperPolicyTrialScenario,
    success_contract: &PaperPolicyTrialSuccessMetricContract,
    failure_contract: &PaperPolicyTrialFailureMetricContract,
    stop_contract: &PaperPolicyTrialStopConditionContract,
    _context: &PaperPolicyTrialScenarioExecutionConfig,
) -> PaperPolicyTrialScenarioExecutionResult {
    let success_metric_evaluation =
        build_paper_policy_trial_success_evaluation_for_scenario(plan, scenario, success_contract);
    let failure_metric_evaluation =
        build_paper_policy_trial_failure_evaluation_for_scenario(plan, scenario, failure_contract);
    let stop_condition_evaluation = build_paper_policy_trial_stop_evaluation_for_scenario(
        plan,
        &failure_metric_evaluation,
        stop_contract,
    );
    let risk_first_status = if failure_metric_evaluation.failure_status
        == PaperPolicyTrialFailureStatus::Blocked
        || stop_condition_evaluation
            .triggered_conditions
            .contains(&PaperPolicyTrialStopCondition::RiskRegressionDetected)
    {
        PaperPolicyTrialScenarioRiskFirstStatus::Violated
    } else {
        PaperPolicyTrialScenarioRiskFirstStatus::Preserved
    };
    let voice_balance_status = if plan.actual_voice_mutation_allowed {
        PaperPolicyTrialScenarioVoiceBalanceStatus::Imbalanced
    } else {
        PaperPolicyTrialScenarioVoiceBalanceStatus::Balanced
    };
    let owner_reference_status = if matches!(
        scenario.scenario_kind,
        PaperPolicyTrialScenarioKind::OwnerRiskConcern
            | PaperPolicyTrialScenarioKind::OwnerEvidenceRequest
    ) {
        if plan.policy_apply_allowed {
            PaperPolicyTrialScenarioOwnerReferenceStatus::Failed
        } else {
            PaperPolicyTrialScenarioOwnerReferenceStatus::Explained
        }
    } else {
        PaperPolicyTrialScenarioOwnerReferenceStatus::NotApplicable
    };
    let mut warnings = Vec::new();
    if success_metric_evaluation.success_status == PaperPolicyTrialSuccessStatus::PassedWithWarnings
    {
        warnings.push("scenario success metrics completed with warnings".to_string());
    }
    if failure_metric_evaluation.failure_status == PaperPolicyTrialFailureStatus::ClearWithWarnings
    {
        warnings.push("scenario failure metrics reported warnings".to_string());
    }
    if stop_condition_evaluation.stop_status == PaperPolicyTrialStopStatus::ContinueWithWarnings {
        warnings.push("scenario stop monitor reported warnings".to_string());
    }
    let execution_status =
        if failure_metric_evaluation.failure_status == PaperPolicyTrialFailureStatus::Blocked {
            PaperPolicyTrialScenarioExecutionStatus::Blocked
        } else if stop_condition_evaluation.stop_status == PaperPolicyTrialStopStatus::Stop {
            PaperPolicyTrialScenarioExecutionStatus::Stopped
        } else if warnings.is_empty() {
            PaperPolicyTrialScenarioExecutionStatus::Executed
        } else {
            PaperPolicyTrialScenarioExecutionStatus::ExecutedWithWarnings
        };
    PaperPolicyTrialScenarioExecutionResult {
        scenario_id: scenario.scenario_id.clone(),
        scenario_kind: scenario.scenario_kind,
        market_scope: scenario.market_scope.clone(),
        symbol: scenario.symbol.clone(),
        success_metric_evaluation,
        failure_metric_evaluation,
        stop_condition_evaluation,
        risk_first_status,
        voice_balance_status,
        owner_reference_status,
        execution_status,
        warnings,
        paper_only: true,
    }
}

fn paper_policy_trial_scenario_ledger_entries_from_results(
    run_id: &str,
    results: &[PaperPolicyTrialScenarioExecutionResult],
) -> Vec<PaperPolicyTrialScenarioResultLedgerEntry> {
    results
        .iter()
        .map(|result| PaperPolicyTrialScenarioResultLedgerEntry {
            entry_id: format!("{run_id}-{}", result.scenario_id),
            run_id: run_id.to_string(),
            scenario_id: result.scenario_id.clone(),
            scenario_kind: result.scenario_kind,
            market_scope: result.market_scope.clone(),
            symbol: result.symbol.clone(),
            execution_status: result.execution_status,
            success_status: result.success_metric_evaluation.success_status,
            failure_status: result.failure_metric_evaluation.failure_status,
            stop_status: result.stop_condition_evaluation.stop_status,
            risk_first_status: result.risk_first_status,
            voice_balance_status: result.voice_balance_status,
            owner_reference_status: result.owner_reference_status,
            triggered_stop_conditions: result
                .stop_condition_evaluation
                .triggered_conditions
                .clone(),
            paper_only: true,
        })
        .collect()
}

pub fn monitor_paper_policy_trial_stop_conditions(
    scenario_results: &[PaperPolicyTrialScenarioExecutionResult],
) -> PaperPolicyTrialStopConditionRuntimeMonitor {
    let mut triggered_conditions = Vec::new();
    let mut triggered_stop_count = 0;
    let mut blocking_stop_count = 0;
    let mut warning_stop_count = 0;
    for result in scenario_results {
        if !result
            .stop_condition_evaluation
            .triggered_conditions
            .is_empty()
        {
            triggered_stop_count += 1;
        }
        for condition in &result.stop_condition_evaluation.triggered_conditions {
            if !triggered_conditions.contains(condition) {
                triggered_conditions.push(*condition);
            }
            if matches!(
                condition,
                PaperPolicyTrialStopCondition::RiskRegressionDetected
                    | PaperPolicyTrialStopCondition::ActualMutationDetected
                    | PaperPolicyTrialStopCondition::RiskGovernorOverrideDetected
                    | PaperPolicyTrialStopCondition::TradeOrderAccountDetected
            ) {
                blocking_stop_count += 1;
            } else {
                warning_stop_count += 1;
            }
        }
    }
    let monitor_status = if scenario_results.is_empty() {
        PaperPolicyTrialStopConditionRuntimeMonitorStatus::Failed
    } else if blocking_stop_count > 0 {
        PaperPolicyTrialStopConditionRuntimeMonitorStatus::StopRequired
    } else if warning_stop_count > 0 {
        PaperPolicyTrialStopConditionRuntimeMonitorStatus::ClearWithWarnings
    } else {
        PaperPolicyTrialStopConditionRuntimeMonitorStatus::Clear
    };
    PaperPolicyTrialStopConditionRuntimeMonitor {
        monitor_id: "paper-policy-trial-stop-condition-runtime-monitor".to_string(),
        scenario_count: scenario_results.len(),
        triggered_stop_count,
        blocking_stop_count,
        warning_stop_count,
        triggered_conditions,
        monitor_status,
        paper_only: true,
    }
}

pub fn compute_paper_policy_trial_scenario_aggregate_metrics(
    scenario_results: &[PaperPolicyTrialScenarioExecutionResult],
) -> PaperPolicyTrialScenarioAggregateMetrics {
    let scenario_count = scenario_results.len();
    let executed_count = scenario_results
        .iter()
        .filter(|result| {
            matches!(
                result.execution_status,
                PaperPolicyTrialScenarioExecutionStatus::Executed
                    | PaperPolicyTrialScenarioExecutionStatus::ExecutedWithWarnings
            )
        })
        .count();
    let stopped_count = scenario_results
        .iter()
        .filter(|result| {
            result.execution_status == PaperPolicyTrialScenarioExecutionStatus::Stopped
        })
        .count();
    let blocked_count = scenario_results
        .iter()
        .filter(|result| {
            result.execution_status == PaperPolicyTrialScenarioExecutionStatus::Blocked
        })
        .count();
    let success_pass_count = scenario_results
        .iter()
        .filter(|result| {
            matches!(
                result.success_metric_evaluation.success_status,
                PaperPolicyTrialSuccessStatus::Passed
                    | PaperPolicyTrialSuccessStatus::PassedWithWarnings
            )
        })
        .count();
    let failure_block_count = scenario_results
        .iter()
        .filter(|result| {
            result.failure_metric_evaluation.failure_status
                == PaperPolicyTrialFailureStatus::Blocked
        })
        .count();
    let risk_first_preserved_count = scenario_results
        .iter()
        .filter(|result| {
            matches!(
                result.risk_first_status,
                PaperPolicyTrialScenarioRiskFirstStatus::Preserved
                    | PaperPolicyTrialScenarioRiskFirstStatus::PreservedWithWarnings
            )
        })
        .count();
    let risk_first_violated_count = scenario_results
        .iter()
        .filter(|result| {
            result.risk_first_status == PaperPolicyTrialScenarioRiskFirstStatus::Violated
        })
        .count();
    let voice_imbalance_count = scenario_results
        .iter()
        .filter(|result| {
            result.voice_balance_status == PaperPolicyTrialScenarioVoiceBalanceStatus::Imbalanced
        })
        .count();
    let owner_explanation_count = scenario_results
        .iter()
        .filter(|result| {
            matches!(
                result.owner_reference_status,
                PaperPolicyTrialScenarioOwnerReferenceStatus::Explained
                    | PaperPolicyTrialScenarioOwnerReferenceStatus::ExplainedWithWarnings
            )
        })
        .count();
    let aggregate_status = if scenario_count == 0 {
        PaperPolicyTrialScenarioAggregateStatus::InsufficientData
    } else if blocked_count > 0 || failure_block_count > 0 || risk_first_violated_count > 0 {
        PaperPolicyTrialScenarioAggregateStatus::Failed
    } else if stopped_count > 0
        || scenario_results.iter().any(|result| {
            matches!(
                result.execution_status,
                PaperPolicyTrialScenarioExecutionStatus::ExecutedWithWarnings
                    | PaperPolicyTrialScenarioExecutionStatus::Skipped
            )
        })
    {
        PaperPolicyTrialScenarioAggregateStatus::PassedWithWarnings
    } else {
        PaperPolicyTrialScenarioAggregateStatus::Passed
    };
    PaperPolicyTrialScenarioAggregateMetrics {
        metrics_id: "paper-policy-trial-scenario-aggregate-metrics".to_string(),
        scenario_count,
        executed_count,
        stopped_count,
        blocked_count,
        success_pass_count,
        failure_block_count,
        risk_first_preserved_count,
        risk_first_violated_count,
        voice_imbalance_count,
        owner_explanation_count,
        aggregate_status,
        paper_only: true,
    }
}

pub fn evaluate_paper_policy_trial_scenario_coverage_quality(
    matrix: &PaperPolicyTrialScenarioMatrix,
    scenario_results: &[PaperPolicyTrialScenarioExecutionResult],
) -> PaperPolicyTrialScenarioCoverageQuality {
    let executed_kinds = scenario_results
        .iter()
        .filter(|result| {
            result.execution_status != PaperPolicyTrialScenarioExecutionStatus::Skipped
        })
        .map(|result| result.scenario_kind)
        .collect::<Vec<_>>();
    let korea_short_long_covered = matrix.includes_korea_short_long
        && executed_kinds.contains(&PaperPolicyTrialScenarioKind::KoreaShortTerm)
        && executed_kinds.contains(&PaperPolicyTrialScenarioKind::KoreaLongTerm);
    let us_short_long_covered = matrix.includes_us_short_long
        && executed_kinds.contains(&PaperPolicyTrialScenarioKind::UsShortTerm)
        && executed_kinds.contains(&PaperPolicyTrialScenarioKind::UsLongTerm);
    let crypto_short_long_covered = matrix.includes_crypto_short_long
        && executed_kinds.contains(&PaperPolicyTrialScenarioKind::CryptoShortTerm)
        && executed_kinds.contains(&PaperPolicyTrialScenarioKind::CryptoLongTerm);
    let risk_veto_covered = matrix.includes_risk_veto_case
        && executed_kinds.contains(&PaperPolicyTrialScenarioKind::HighRiskVeto);
    let evidence_gap_covered = matrix.includes_evidence_gap_case
        && executed_kinds.contains(&PaperPolicyTrialScenarioKind::EvidenceGap);
    let owner_reference_covered = matrix.includes_owner_reference_case
        && (executed_kinds.contains(&PaperPolicyTrialScenarioKind::OwnerRiskConcern)
            || executed_kinds.contains(&PaperPolicyTrialScenarioKind::OwnerEvidenceRequest));
    let high_risk_case_covered =
        executed_kinds.contains(&PaperPolicyTrialScenarioKind::HighRiskVeto);
    let negative_trend_case_covered =
        executed_kinds.contains(&PaperPolicyTrialScenarioKind::NegativeTrend);
    let mut missing_coverage = Vec::new();
    if !korea_short_long_covered {
        missing_coverage.push("korea short/long".to_string());
    }
    if !us_short_long_covered {
        missing_coverage.push("us short/long".to_string());
    }
    if !crypto_short_long_covered {
        missing_coverage.push("crypto short/long".to_string());
    }
    if !risk_veto_covered {
        missing_coverage.push("risk veto".to_string());
    }
    if !evidence_gap_covered {
        missing_coverage.push("evidence gap".to_string());
    }
    if !owner_reference_covered {
        missing_coverage.push("owner reference".to_string());
    }
    if !high_risk_case_covered {
        missing_coverage.push("high risk case".to_string());
    }
    if !negative_trend_case_covered {
        missing_coverage.push("negative trend case".to_string());
    }
    let coverage_status = if missing_coverage.is_empty() {
        if scenario_results.iter().any(|result| {
            result.execution_status == PaperPolicyTrialScenarioExecutionStatus::ExecutedWithWarnings
        }) {
            PaperPolicyTrialScenarioCoverageStatus::CompleteWithWarnings
        } else {
            PaperPolicyTrialScenarioCoverageStatus::Complete
        }
    } else {
        PaperPolicyTrialScenarioCoverageStatus::Incomplete
    };
    PaperPolicyTrialScenarioCoverageQuality {
        quality_id: format!("{}-coverage-quality", matrix.matrix_id),
        scenario_count: scenario_results.len(),
        korea_short_long_covered,
        us_short_long_covered,
        crypto_short_long_covered,
        risk_veto_covered,
        evidence_gap_covered,
        owner_reference_covered,
        high_risk_case_covered,
        negative_trend_case_covered,
        coverage_status,
        missing_coverage,
        paper_only: true,
    }
}

pub fn evaluate_paper_policy_trial_execution_gate(
    plan_validation: &PaperPolicyTrialPlanValidationResult,
    coverage_quality: &PaperPolicyTrialScenarioCoverageQuality,
    aggregate_metrics: &PaperPolicyTrialScenarioAggregateMetrics,
    stop_monitor: &PaperPolicyTrialStopConditionRuntimeMonitor,
    safety_guard: &PaperPolicyTrialScenarioExecutionSafetyGuard,
) -> PaperPolicyTrialExecutionGate {
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    if plan_validation.validation_status == PaperPolicyTrialPlanValidationStatus::Invalid {
        blockers.push("paper policy trial scenario execution plan validation failed".to_string());
    }
    if safety_guard.guard_status == PaperGovernanceTrialSafetyGuardStatus::Violated {
        blockers
            .push("paper policy trial scenario execution safety guard was violated".to_string());
    }
    if stop_monitor.monitor_status
        == PaperPolicyTrialStopConditionRuntimeMonitorStatus::StopRequired
    {
        blockers
            .push("paper policy trial stop monitor requires stopping the paper trial".to_string());
    }
    if coverage_quality.coverage_status == PaperPolicyTrialScenarioCoverageStatus::Incomplete {
        blockers.push("paper policy trial scenario coverage is incomplete".to_string());
    }
    if aggregate_metrics.aggregate_status == PaperPolicyTrialScenarioAggregateStatus::Failed {
        blockers.push("paper policy trial aggregate metrics failed".to_string());
    } else if aggregate_metrics.aggregate_status
        == PaperPolicyTrialScenarioAggregateStatus::InsufficientData
    {
        blockers.push("paper policy trial aggregate metrics are insufficient".to_string());
    }
    if plan_validation.validation_status == PaperPolicyTrialPlanValidationStatus::ValidWithWarnings
    {
        warnings.extend(plan_validation.warnings.clone());
    }
    if coverage_quality.coverage_status
        == PaperPolicyTrialScenarioCoverageStatus::CompleteWithWarnings
    {
        warnings.extend(coverage_quality.missing_coverage.clone());
    }
    if aggregate_metrics.aggregate_status
        == PaperPolicyTrialScenarioAggregateStatus::PassedWithWarnings
    {
        warnings.push("paper policy trial aggregate metrics completed with warnings".to_string());
    }
    if stop_monitor.monitor_status
        == PaperPolicyTrialStopConditionRuntimeMonitorStatus::ClearWithWarnings
    {
        warnings.push("paper policy trial stop monitor completed with warnings".to_string());
    }
    let gate_status = if safety_guard.guard_status
        == PaperGovernanceTrialSafetyGuardStatus::Violated
    {
        PaperPolicyTrialExecutionGateStatus::BlockedBySafety
    } else if stop_monitor.monitor_status
        == PaperPolicyTrialStopConditionRuntimeMonitorStatus::StopRequired
    {
        PaperPolicyTrialExecutionGateStatus::BlockedByStopCondition
    } else if plan_validation.validation_status == PaperPolicyTrialPlanValidationStatus::Invalid
        || aggregate_metrics.aggregate_status == PaperPolicyTrialScenarioAggregateStatus::Failed
    {
        PaperPolicyTrialExecutionGateStatus::Failed
    } else if coverage_quality.coverage_status == PaperPolicyTrialScenarioCoverageStatus::Incomplete
        || aggregate_metrics.aggregate_status
            == PaperPolicyTrialScenarioAggregateStatus::InsufficientData
    {
        PaperPolicyTrialExecutionGateStatus::NeedsMoreScenarios
    } else if warnings.is_empty() {
        PaperPolicyTrialExecutionGateStatus::ReadyForRepeatedPaperExecution
    } else {
        PaperPolicyTrialExecutionGateStatus::ReadyWithWarnings
    };
    PaperPolicyTrialExecutionGate {
        gate_id: format!("{}-execution-gate", plan_validation.plan_id),
        plan_validation_status: plan_validation.validation_status,
        scenario_coverage_status: coverage_quality.coverage_status,
        aggregate_status: aggregate_metrics.aggregate_status,
        stop_monitor_status: stop_monitor.monitor_status,
        safety_status: safety_guard.guard_status,
        ready_for_repeated_paper_execution: matches!(
            gate_status,
            PaperPolicyTrialExecutionGateStatus::ReadyForRepeatedPaperExecution
                | PaperPolicyTrialExecutionGateStatus::ReadyWithWarnings
        ),
        gate_status,
        blockers,
        warnings,
        paper_only: true,
    }
}

fn build_paper_policy_trial_scenario_execution_safety_guard_from_parts(
    plan: &PaperPolicyTrialPlan,
    dry_run: bool,
    wrote_scenario_ledger: bool,
    batch_before: Option<&BatchCommitteeCycleWithStateResult>,
    batch_after: Option<&BatchCommitteeCycleWithStateResult>,
) -> PaperPolicyTrialScenarioExecutionSafetyGuard {
    let after = batch_after.or(batch_before);
    let (actual_score_mutation_detected, actual_voice_mutation_detected) =
        if let (Some(before), Some(after)) = (batch_before, after) {
            let before_states = before
                .state_update
                .updated_member_states
                .iter()
                .map(|state| (state.member_id.clone(), (state.score, state.voice_weight)))
                .collect::<BTreeMap<_, _>>();
            let after_states = after
                .state_update
                .updated_member_states
                .iter()
                .map(|state| (state.member_id.clone(), (state.score, state.voice_weight)))
                .collect::<BTreeMap<_, _>>();
            let mut score_changed = before_states.len() != after_states.len();
            let mut voice_changed = before_states.len() != after_states.len();
            for (member_id, (score, voice_weight)) in &before_states {
                match after_states.get(member_id) {
                    Some((after_score, after_voice_weight)) => {
                        if score != after_score {
                            score_changed = true;
                        }
                        if voice_weight != after_voice_weight {
                            voice_changed = true;
                        }
                    }
                    None => {
                        score_changed = true;
                        voice_changed = true;
                    }
                }
            }
            (score_changed, voice_changed)
        } else {
            (false, false)
        };
    let committee_decision_mutation_detected = plan.committee_decision_mutation_allowed
        || if let (Some(before), Some(after)) = (batch_before, after) {
            before.batch_result.committee_sessions != after.batch_result.committee_sessions
        } else {
            false
        };
    let chairman_decision_mutation_detected =
        if let (Some(before), Some(after)) = (batch_before, after) {
            before.batch_result.chairman_decisions != after.batch_result.chairman_decisions
        } else {
            false
        };
    let member_opinion_mutation_detected =
        if let (Some(before), Some(after)) = (batch_before, after) {
            before.batch_result.member_opinions != after.batch_result.member_opinions
        } else {
            false
        };
    let actual_policy_apply_detected = plan.policy_apply_allowed;
    let actual_score_mutation_detected =
        plan.actual_score_mutation_allowed || actual_score_mutation_detected;
    let actual_voice_mutation_detected =
        plan.actual_voice_mutation_allowed || actual_voice_mutation_detected;
    let risk_governor_override_detected = plan.risk_governor_override_allowed;
    let trade_signal_detected = plan.trade_order_account_allowed;
    let order_detected = plan.trade_order_account_allowed;
    let broker_order_account_detected = plan.trade_order_account_allowed;
    let scenario_ledger_write_when_dry_run_detected = dry_run && wrote_scenario_ledger;
    let paper_scenario_used_as_live_decision_detected = actual_policy_apply_detected
        || committee_decision_mutation_detected
        || chairman_decision_mutation_detected;
    let mut violations = Vec::new();
    if actual_policy_apply_detected {
        violations.push("actual policy apply was detected".to_string());
    }
    if actual_score_mutation_detected {
        violations.push("actual score mutation was detected".to_string());
    }
    if actual_voice_mutation_detected {
        violations.push("actual voice mutation was detected".to_string());
    }
    if committee_decision_mutation_detected {
        violations.push("committee decision mutation was detected".to_string());
    }
    if chairman_decision_mutation_detected {
        violations.push("chairman decision mutation was detected".to_string());
    }
    if risk_governor_override_detected {
        violations.push("risk governor override was detected".to_string());
    }
    if member_opinion_mutation_detected {
        violations.push("member opinion mutation was detected".to_string());
    }
    if trade_signal_detected || order_detected || broker_order_account_detected {
        violations.push("trade/order/account path was detected".to_string());
    }
    if scenario_ledger_write_when_dry_run_detected {
        violations.push("scenario ledger write was detected during dry run".to_string());
    }
    if paper_scenario_used_as_live_decision_detected {
        violations.push("paper scenario was used as a live decision".to_string());
    }
    PaperPolicyTrialScenarioExecutionSafetyGuard {
        actual_policy_apply_detected,
        actual_score_mutation_detected,
        actual_voice_mutation_detected,
        committee_decision_mutation_detected,
        chairman_decision_mutation_detected,
        risk_governor_override_detected,
        member_opinion_mutation_detected,
        trade_signal_detected,
        order_detected,
        broker_order_account_detected,
        scenario_ledger_write_when_dry_run_detected,
        paper_scenario_used_as_live_decision_detected,
        guard_status: if violations.is_empty() {
            PaperGovernanceTrialSafetyGuardStatus::Preserved
        } else {
            PaperGovernanceTrialSafetyGuardStatus::Violated
        },
        violations,
        paper_only: true,
    }
}

pub fn evaluate_paper_policy_trial_scenario_execution_safety(
    run_result: &PaperPolicyTrialScenarioExecutionRunResult,
    batch_before: &BatchCommitteeCycleWithStateResult,
    batch_after: Option<&BatchCommitteeCycleWithStateResult>,
) -> PaperPolicyTrialScenarioExecutionSafetyGuard {
    build_paper_policy_trial_scenario_execution_safety_guard_from_parts(
        &run_result.plan,
        run_result.dry_run,
        run_result.wrote_scenario_ledger,
        Some(batch_before),
        batch_after,
    )
}

pub fn prove_paper_policy_trial_scenario_ledger_write(
    run_result: &PaperPolicyTrialScenarioExecutionRunResult,
    ledger_path: &Path,
) -> Result<PaperPolicyTrialScenarioLedgerWriteProof, String> {
    validate_local_json_path(ledger_path, "paper policy trial scenario ledger path")?;
    let scenario_ledger_exists_after_write = ledger_path.exists();
    let (entry_count, paper_only_count, unsafe_entry_count) = if scenario_ledger_exists_after_write
    {
        let ledger = load_paper_policy_trial_scenario_result_ledger_from_local_json(ledger_path)?;
        let paper_only_count = ledger
            .entries
            .iter()
            .filter(|entry| entry.paper_only)
            .count();
        let unsafe_entry_count = ledger.entries.len().saturating_sub(paper_only_count);
        (ledger.entry_count, paper_only_count, unsafe_entry_count)
    } else {
        (0, 0, 0)
    };
    let proof_status = if run_result.wrote_scenario_ledger && !scenario_ledger_exists_after_write {
        PaperGovernanceTrialLedgerWriteProofStatus::Failed
    } else if unsafe_entry_count > 0 {
        PaperGovernanceTrialLedgerWriteProofStatus::Failed
    } else if entry_count < run_result.scenario_result_ledger.entry_count {
        PaperGovernanceTrialLedgerWriteProofStatus::ProvenWithWarnings
    } else {
        PaperGovernanceTrialLedgerWriteProofStatus::Proven
    };
    Ok(PaperPolicyTrialScenarioLedgerWriteProof {
        proof_id: format!("{}-scenario-ledger-write-proof", run_result.run_id),
        expected_output_path: ledger_path.display().to_string(),
        wrote_scenario_ledger: run_result.wrote_scenario_ledger,
        scenario_ledger_exists_after_write,
        entry_count,
        paper_only_count,
        unsafe_entry_count,
        proof_status,
        paper_only: true,
    })
}

pub fn build_owner_paper_policy_trial_scenario_execution_summary(
    run_result: &PaperPolicyTrialScenarioExecutionRunResult,
) -> OwnerPaperPolicyTrialScenarioExecutionSummary {
    OwnerPaperPolicyTrialScenarioExecutionSummary {
        summary_id: format!("{}-owner-paper-policy-trial-scenario-summary", run_result.run_id),
        scenario_count: run_result.scenario_results.len(),
        executed_count: run_result.aggregate_metrics.executed_count,
        stopped_count: run_result.aggregate_metrics.stopped_count,
        blocked_count: run_result.aggregate_metrics.blocked_count,
        aggregate_status: run_result.aggregate_metrics.aggregate_status,
        stop_monitor_status: run_result.stop_condition_monitor.monitor_status,
        execution_gate_status: run_result.execution_gate.gate_status,
        message: "Paper policy trial scenarios were executed only in paper mode. Actual score, voice, decisions, Risk Governor, and trading remain unchanged. Stop conditions apply only to the paper trial.".to_string(),
        paper_trial_only: true,
        no_actual_policy_apply: true,
        no_score_mutation: true,
        no_voice_mutation: true,
        no_committee_decision_change: true,
        no_risk_override: true,
        not_trade_signal: true,
        paper_only: true,
    }
}

fn paper_policy_trial_scenario_execution_run_status(
    execution_gate: &PaperPolicyTrialExecutionGate,
    safety_guard: &PaperPolicyTrialScenarioExecutionSafetyGuard,
    write_proof: Option<&PaperPolicyTrialScenarioLedgerWriteProof>,
) -> PaperGovernanceTrialRunStatus {
    if safety_guard.guard_status == PaperGovernanceTrialSafetyGuardStatus::Violated
        || matches!(
            execution_gate.gate_status,
            PaperPolicyTrialExecutionGateStatus::BlockedBySafety
                | PaperPolicyTrialExecutionGateStatus::BlockedByStopCondition
                | PaperPolicyTrialExecutionGateStatus::Failed
        )
        || write_proof.is_some_and(|proof| {
            proof.proof_status == PaperGovernanceTrialLedgerWriteProofStatus::Failed
        })
    {
        PaperGovernanceTrialRunStatus::Failed
    } else if matches!(
        execution_gate.gate_status,
        PaperPolicyTrialExecutionGateStatus::ReadyWithWarnings
            | PaperPolicyTrialExecutionGateStatus::NeedsMoreScenarios
    ) || write_proof.is_some_and(|proof| {
        proof.proof_status == PaperGovernanceTrialLedgerWriteProofStatus::ProvenWithWarnings
    }) {
        PaperGovernanceTrialRunStatus::PassedWithWarnings
    } else {
        PaperGovernanceTrialRunStatus::Passed
    }
}

pub fn run_paper_policy_trial_scenario_execution(
    plan: &PaperPolicyTrialPlan,
    matrix: &PaperPolicyTrialScenarioMatrix,
    config: &PaperPolicyTrialScenarioExecutionRunConfig,
) -> Result<PaperPolicyTrialScenarioExecutionRunResult, String> {
    let execution_config = build_paper_policy_trial_scenario_execution_config_from_run(config);
    let success_contract = default_paper_policy_trial_success_metric_contract();
    let failure_contract = default_paper_policy_trial_failure_metric_contract();
    let stop_contract = default_paper_policy_trial_stop_condition_contract();
    let plan_validation = validate_paper_policy_trial_plan(plan);
    let mut scenario_results = Vec::new();
    let capped_count = matrix.scenarios.len().min(config.max_scenarios);
    let mut stop_requested = false;
    for (index, scenario) in matrix.scenarios.iter().enumerate() {
        if stop_requested || index >= capped_count {
            scenario_results.push(skipped_paper_policy_trial_scenario_execution_result(
                scenario,
                &success_contract,
                &failure_contract,
                &stop_contract,
            ));
            continue;
        }
        let scenario_result = execute_paper_policy_trial_scenario(
            plan,
            scenario,
            &success_contract,
            &failure_contract,
            &stop_contract,
            &execution_config,
        );
        if config.stop_on_first_blocking_condition
            && matches!(
                scenario_result.execution_status,
                PaperPolicyTrialScenarioExecutionStatus::Blocked
                    | PaperPolicyTrialScenarioExecutionStatus::Stopped
            )
        {
            stop_requested = true;
        }
        scenario_results.push(scenario_result);
    }
    let scenario_entries =
        paper_policy_trial_scenario_ledger_entries_from_results(&config.run_id, &scenario_results);
    let mut scenario_result_ledger = if let Some(path) = config
        .scenario_result_ledger_input_path
        .as_ref()
        .filter(|path| !path.trim().is_empty())
    {
        load_paper_policy_trial_scenario_result_ledger_from_local_json(Path::new(path))?
    } else {
        default_paper_policy_trial_scenario_result_ledger()
    };
    append_paper_policy_trial_scenario_result_entries(
        &mut scenario_result_ledger,
        &scenario_entries,
    )?;
    let aggregate_metrics =
        compute_paper_policy_trial_scenario_aggregate_metrics(&scenario_results);
    let coverage_quality =
        evaluate_paper_policy_trial_scenario_coverage_quality(matrix, &scenario_results);
    let stop_condition_monitor = monitor_paper_policy_trial_stop_conditions(&scenario_results);
    let safety_guard = build_paper_policy_trial_scenario_execution_safety_guard_from_parts(
        plan,
        config.dry_run,
        false,
        None,
        None,
    );
    let execution_gate = evaluate_paper_policy_trial_execution_gate(
        &plan_validation,
        &coverage_quality,
        &aggregate_metrics,
        &stop_condition_monitor,
        &safety_guard,
    );
    let mut wrote_scenario_ledger = false;
    let mut write_proof = None;
    if !config.dry_run && config.write_scenario_ledger {
        let output_path = config
            .scenario_result_ledger_output_path
            .as_ref()
            .filter(|path| !path.trim().is_empty())
            .ok_or_else(|| {
                "paper policy trial scenario ledger output path is required when writing ledger"
                    .to_string()
            })?;
        save_paper_policy_trial_scenario_result_ledger_to_local_json(
            Path::new(output_path),
            &scenario_result_ledger,
        )?;
        wrote_scenario_ledger = true;
    }
    let mut result = PaperPolicyTrialScenarioExecutionRunResult {
        run_id: config.run_id.clone(),
        plan: plan.clone(),
        scenario_matrix: matrix.clone(),
        scenario_results,
        scenario_result_ledger,
        aggregate_metrics,
        coverage_quality,
        stop_condition_monitor,
        execution_gate,
        safety_guard,
        write_proof: None,
        owner_summary: None,
        run_status: PaperGovernanceTrialRunStatus::Passed,
        dry_run: config.dry_run,
        wrote_scenario_ledger,
        paper_only: true,
    };
    result.safety_guard = build_paper_policy_trial_scenario_execution_safety_guard_from_parts(
        &result.plan,
        result.dry_run,
        result.wrote_scenario_ledger,
        None,
        None,
    );
    result.execution_gate = evaluate_paper_policy_trial_execution_gate(
        &plan_validation,
        &result.coverage_quality,
        &result.aggregate_metrics,
        &result.stop_condition_monitor,
        &result.safety_guard,
    );
    if result.wrote_scenario_ledger {
        if let Some(output_path) = config
            .scenario_result_ledger_output_path
            .as_ref()
            .filter(|path| !path.trim().is_empty())
        {
            write_proof = Some(prove_paper_policy_trial_scenario_ledger_write(
                &result,
                Path::new(output_path),
            )?);
        }
    }
    result.write_proof = write_proof;
    if config.emit_owner_summary {
        result.owner_summary = Some(build_owner_paper_policy_trial_scenario_execution_summary(
            &result,
        ));
    }
    result.run_status = paper_policy_trial_scenario_execution_run_status(
        &result.execution_gate,
        &result.safety_guard,
        result.write_proof.as_ref(),
    );
    Ok(result)
}

fn maybe_run_paper_policy_trial_scenario_execution_for_stateful_result(
    run_id: String,
    enabled: bool,
    dry_run: bool,
    write_scenario_ledger: bool,
    plan_input_path: Option<&String>,
    scenario_matrix_input_path: Option<&String>,
    scenario_ledger_input_path: Option<&String>,
    scenario_ledger_output_path: Option<&String>,
    max_scenarios: usize,
    stop_on_first_blocking_condition: bool,
    emit_owner_summary: bool,
    stateful_result: &mut BatchCommitteeCycleWithStateResult,
) -> Result<Option<PaperPolicyTrialScenarioExecutionRunResult>, String> {
    if !paper_policy_trial_scenario_execution_requested_from_flags(
        enabled,
        dry_run,
        write_scenario_ledger,
        plan_input_path,
        scenario_matrix_input_path,
        scenario_ledger_input_path,
        scenario_ledger_output_path,
        max_scenarios,
        stop_on_first_blocking_condition,
        emit_owner_summary,
    ) {
        return Ok(None);
    }
    let plan = if let Some(path) = plan_input_path.filter(|path| !path.trim().is_empty()) {
        load_paper_policy_trial_plan_from_local_json(Path::new(path))?
    } else {
        stateful_result
            .batch_result
            .paper_policy_trial_plan
            .clone()
            .ok_or_else(|| {
                "paper policy trial scenario execution requires trial plan".to_string()
            })?
    };
    let scenario_matrix =
        if let Some(path) = scenario_matrix_input_path.filter(|path| !path.trim().is_empty()) {
            load_paper_policy_trial_scenario_matrix_from_local_json(Path::new(path))?
        } else {
            stateful_result
                .batch_result
                .paper_policy_trial_scenario_matrix
                .clone()
                .unwrap_or_else(build_default_paper_policy_trial_scenario_matrix)
        };
    let before_snapshot = stateful_result.clone();
    let mut result = run_paper_policy_trial_scenario_execution(
        &plan,
        &scenario_matrix,
        &PaperPolicyTrialScenarioExecutionRunConfig {
            run_id,
            enabled,
            plan_input_path: plan_input_path.cloned(),
            scenario_matrix_input_path: scenario_matrix_input_path.cloned(),
            scenario_result_ledger_input_path: scenario_ledger_input_path.cloned(),
            scenario_result_ledger_output_path: scenario_ledger_output_path.cloned(),
            max_scenarios,
            dry_run,
            write_scenario_ledger,
            stop_on_first_blocking_condition,
            emit_owner_summary,
            paper_only: true,
        },
    )?;
    stateful_result
        .batch_result
        .paper_policy_trial_scenario_result_ledger = Some(result.scenario_result_ledger.clone());
    stateful_result
        .batch_result
        .paper_policy_trial_stop_condition_runtime_monitor =
        Some(result.stop_condition_monitor.clone());
    stateful_result
        .batch_result
        .paper_policy_trial_scenario_aggregate_metrics = Some(result.aggregate_metrics.clone());
    stateful_result
        .batch_result
        .paper_policy_trial_scenario_coverage_quality = Some(result.coverage_quality.clone());
    stateful_result
        .batch_result
        .paper_policy_trial_execution_gate = Some(result.execution_gate.clone());
    stateful_result
        .batch_result
        .paper_policy_trial_scenario_execution_safety_guard = Some(result.safety_guard.clone());
    stateful_result
        .batch_result
        .paper_policy_trial_scenario_ledger_write_proof = result.write_proof.clone();
    stateful_result
        .batch_result
        .owner_paper_policy_trial_scenario_execution_summary = result.owner_summary.clone();
    stateful_result
        .batch_result
        .paper_policy_trial_scenario_execution_run_result = Some(result.clone());
    let after_snapshot = stateful_result.clone();
    result.safety_guard = evaluate_paper_policy_trial_scenario_execution_safety(
        &result,
        &before_snapshot,
        Some(&after_snapshot),
    );
    result.execution_gate = evaluate_paper_policy_trial_execution_gate(
        &validate_paper_policy_trial_plan(&result.plan),
        &result.coverage_quality,
        &result.aggregate_metrics,
        &result.stop_condition_monitor,
        &result.safety_guard,
    );
    result.run_status = paper_policy_trial_scenario_execution_run_status(
        &result.execution_gate,
        &result.safety_guard,
        result.write_proof.as_ref(),
    );
    if emit_owner_summary {
        result.owner_summary = Some(build_owner_paper_policy_trial_scenario_execution_summary(
            &result,
        ));
    }
    stateful_result
        .batch_result
        .paper_policy_trial_execution_gate = Some(result.execution_gate.clone());
    stateful_result
        .batch_result
        .paper_policy_trial_scenario_execution_safety_guard = Some(result.safety_guard.clone());
    stateful_result
        .batch_result
        .owner_paper_policy_trial_scenario_execution_summary = result.owner_summary.clone();
    stateful_result
        .batch_result
        .paper_policy_trial_scenario_execution_run_result = Some(result.clone());
    Ok(Some(result))
}

pub fn paper_policy_trial_repeated_scenario_requested_from_flags(
    enabled: bool,
    dry_run: bool,
    repeat_count: usize,
    append_scenario_ledger: bool,
    scenario_ledger_input_path: Option<&String>,
    _scenario_ledger_output_path: Option<&String>,
    stop_on_repeated_blocking_condition: bool,
    emit_owner_summary: bool,
) -> bool {
    enabled
        || !dry_run
        || repeat_count != default_paper_policy_trial_repeated_scenario_count()
        || append_scenario_ledger
        || scenario_ledger_input_path
            .map(|path| !path.trim().is_empty())
            .unwrap_or(false)
        || !stop_on_repeated_blocking_condition
        || (enabled && emit_owner_summary)
}

pub fn paper_policy_trial_outcome_scorecard_requested_from_flags(
    enabled: bool,
    dry_run: bool,
    write_scorecard: bool,
    scenario_ledger_input_path: Option<&String>,
    _scorecard_output_path: Option<&String>,
    emit_owner_summary: bool,
) -> bool {
    enabled
        || !dry_run
        || write_scorecard
        || scenario_ledger_input_path
            .map(|path| !path.trim().is_empty())
            .unwrap_or(false)
        || (enabled && emit_owner_summary)
}

fn scenario_execution_status_severity(status: PaperPolicyTrialScenarioExecutionStatus) -> u8 {
    match status {
        PaperPolicyTrialScenarioExecutionStatus::Executed => 0,
        PaperPolicyTrialScenarioExecutionStatus::ExecutedWithWarnings
        | PaperPolicyTrialScenarioExecutionStatus::Skipped => 1,
        PaperPolicyTrialScenarioExecutionStatus::Stopped => 2,
        PaperPolicyTrialScenarioExecutionStatus::Blocked => 3,
    }
}

fn scenario_success_status_severity(status: PaperPolicyTrialSuccessStatus) -> u8 {
    match status {
        PaperPolicyTrialSuccessStatus::Passed => 0,
        PaperPolicyTrialSuccessStatus::PassedWithWarnings
        | PaperPolicyTrialSuccessStatus::InsufficientData => 1,
        PaperPolicyTrialSuccessStatus::Failed => 2,
    }
}

fn scenario_failure_status_severity(status: PaperPolicyTrialFailureStatus) -> u8 {
    match status {
        PaperPolicyTrialFailureStatus::Clear => 0,
        PaperPolicyTrialFailureStatus::ClearWithWarnings => 1,
        PaperPolicyTrialFailureStatus::Blocked => 2,
    }
}

fn scenario_stop_status_severity(status: PaperPolicyTrialStopStatus) -> u8 {
    match status {
        PaperPolicyTrialStopStatus::Continue => 0,
        PaperPolicyTrialStopStatus::ContinueWithWarnings => 1,
        PaperPolicyTrialStopStatus::Stop => 2,
    }
}

fn scenario_risk_first_status_severity(status: PaperPolicyTrialScenarioRiskFirstStatus) -> u8 {
    match status {
        PaperPolicyTrialScenarioRiskFirstStatus::Preserved => 0,
        PaperPolicyTrialScenarioRiskFirstStatus::PreservedWithWarnings
        | PaperPolicyTrialScenarioRiskFirstStatus::InsufficientData => 1,
        PaperPolicyTrialScenarioRiskFirstStatus::Violated => 2,
    }
}

fn scenario_voice_balance_status_severity(
    status: PaperPolicyTrialScenarioVoiceBalanceStatus,
) -> u8 {
    match status {
        PaperPolicyTrialScenarioVoiceBalanceStatus::Balanced => 0,
        PaperPolicyTrialScenarioVoiceBalanceStatus::BalancedWithWarnings
        | PaperPolicyTrialScenarioVoiceBalanceStatus::InsufficientData => 1,
        PaperPolicyTrialScenarioVoiceBalanceStatus::Imbalanced => 2,
    }
}

fn paper_policy_trial_trend_status_for_entries(
    entries: &[&PaperPolicyTrialScenarioResultLedgerEntry],
) -> PaperPolicyTrialScenarioTrendStatus {
    if entries.len() < 2 {
        return PaperPolicyTrialScenarioTrendStatus::InsufficientHistory;
    }
    let severity = |entry: &PaperPolicyTrialScenarioResultLedgerEntry| {
        scenario_execution_status_severity(entry.execution_status)
            .max(scenario_success_status_severity(entry.success_status))
            .max(scenario_failure_status_severity(entry.failure_status))
            .max(scenario_stop_status_severity(entry.stop_status))
            .max(scenario_risk_first_status_severity(entry.risk_first_status))
            .max(scenario_voice_balance_status_severity(
                entry.voice_balance_status,
            ))
    };
    let first = severity(entries[0]);
    let last = severity(entries[entries.len().saturating_sub(1)]);
    let stable = entries
        .windows(2)
        .all(|window| severity(window[0]) == severity(window[1]));
    if last < first {
        PaperPolicyTrialScenarioTrendStatus::Improving
    } else if last > first {
        PaperPolicyTrialScenarioTrendStatus::Worsening
    } else if stable {
        PaperPolicyTrialScenarioTrendStatus::Stable
    } else {
        PaperPolicyTrialScenarioTrendStatus::Mixed
    }
}

pub fn compute_paper_policy_trial_scenario_trend_summary(
    scenario_ledger: &PaperPolicyTrialScenarioResultLedger,
) -> PaperPolicyTrialScenarioTrendSummary {
    let mut grouped = BTreeMap::<String, Vec<&PaperPolicyTrialScenarioResultLedgerEntry>>::new();
    for entry in &scenario_ledger.entries {
        grouped
            .entry(format!("{:?}", entry.scenario_kind))
            .or_default()
            .push(entry);
    }
    let mut records = Vec::new();
    for entries in grouped.values() {
        let first = entries[0];
        records.push(PaperPolicyTrialScenarioTrendRecord {
            record_id: format!("{}-trend", first.scenario_id),
            scenario_kind: first.scenario_kind,
            execution_status_series: entries.iter().map(|entry| entry.execution_status).collect(),
            success_status_series: entries.iter().map(|entry| entry.success_status).collect(),
            failure_status_series: entries.iter().map(|entry| entry.failure_status).collect(),
            stop_status_series: entries.iter().map(|entry| entry.stop_status).collect(),
            risk_first_status_series: entries
                .iter()
                .map(|entry| entry.risk_first_status)
                .collect(),
            voice_balance_status_series: entries
                .iter()
                .map(|entry| entry.voice_balance_status)
                .collect(),
            trend_status: paper_policy_trial_trend_status_for_entries(entries),
            paper_only: true,
        });
    }
    let improving_count = records
        .iter()
        .filter(|record| record.trend_status == PaperPolicyTrialScenarioTrendStatus::Improving)
        .count();
    let stable_count = records
        .iter()
        .filter(|record| record.trend_status == PaperPolicyTrialScenarioTrendStatus::Stable)
        .count();
    let worsening_count = records
        .iter()
        .filter(|record| record.trend_status == PaperPolicyTrialScenarioTrendStatus::Worsening)
        .count();
    let mixed_count = records
        .iter()
        .filter(|record| record.trend_status == PaperPolicyTrialScenarioTrendStatus::Mixed)
        .count();
    let trend_status = if records.is_empty()
        || records.iter().all(|record| {
            record.trend_status == PaperPolicyTrialScenarioTrendStatus::InsufficientHistory
        }) {
        PaperPolicyTrialScenarioTrendStatus::InsufficientHistory
    } else if worsening_count > 0 {
        PaperPolicyTrialScenarioTrendStatus::Worsening
    } else if mixed_count > 0 {
        PaperPolicyTrialScenarioTrendStatus::Mixed
    } else if improving_count > 0 && stable_count == 0 {
        PaperPolicyTrialScenarioTrendStatus::Improving
    } else {
        PaperPolicyTrialScenarioTrendStatus::Stable
    };
    PaperPolicyTrialScenarioTrendSummary {
        summary_id: format!("{}-scenario-trend-summary", scenario_ledger.ledger_id),
        scenario_count: records.len(),
        record_count: records.len(),
        improving_count,
        stable_count,
        worsening_count,
        mixed_count,
        trend_status,
        records,
        paper_only: true,
    }
}

fn stop_condition_to_recurrence_kind(
    condition: PaperPolicyTrialStopCondition,
) -> PaperPolicyTrialStopRecurrenceKind {
    match condition {
        PaperPolicyTrialStopCondition::RiskRegressionDetected => {
            PaperPolicyTrialStopRecurrenceKind::RiskRegressionRepeated
        }
        PaperPolicyTrialStopCondition::VoiceConcentrationExceeded => {
            PaperPolicyTrialStopRecurrenceKind::VoiceConcentrationRepeated
        }
        PaperPolicyTrialStopCondition::ActualMutationDetected
        | PaperPolicyTrialStopCondition::RiskGovernorOverrideDetected => {
            PaperPolicyTrialStopRecurrenceKind::ActualMutationRepeated
        }
        PaperPolicyTrialStopCondition::TradeOrderAccountDetected => {
            PaperPolicyTrialStopRecurrenceKind::TradeOrderAccountRepeated
        }
        PaperPolicyTrialStopCondition::OwnerForcedApplyDetected => {
            PaperPolicyTrialStopRecurrenceKind::OwnerForcedApplyRepeated
        }
        PaperPolicyTrialStopCondition::EvidenceQualityTooLow
        | PaperPolicyTrialStopCondition::InsufficientEvidence => {
            PaperPolicyTrialStopRecurrenceKind::EvidenceQualityRepeated
        }
        PaperPolicyTrialStopCondition::NoTradeBiasExceeded => {
            PaperPolicyTrialStopRecurrenceKind::EvidenceQualityRepeated
        }
    }
}

pub fn summarize_paper_policy_trial_stop_recurrence(
    scenario_ledger: &PaperPolicyTrialScenarioResultLedger,
) -> PaperPolicyTrialStopRecurrenceSummary {
    if scenario_ledger.entry_count < 2 {
        return PaperPolicyTrialStopRecurrenceSummary {
            summary_id: format!("{}-stop-recurrence-summary", scenario_ledger.ledger_id),
            recurrence_count: 0,
            high_severity_count: 0,
            dominant_stop_kinds: vec![PaperPolicyTrialStopRecurrenceKind::InsufficientHistory],
            recurrence_status: PaperPolicyTrialStopRecurrenceStatus::InsufficientHistory,
            records: Vec::new(),
            paper_only: true,
        };
    }
    let mut grouped = BTreeMap::<
        String,
        (
            PaperPolicyTrialStopRecurrenceKind,
            Option<PaperPolicyTrialScenarioKind>,
            usize,
        ),
    >::new();
    for entry in &scenario_ledger.entries {
        for condition in &entry.triggered_stop_conditions {
            let kind = stop_condition_to_recurrence_kind(*condition);
            let key = format!("{:?}-{:?}", kind, entry.scenario_kind);
            let record = grouped
                .entry(key)
                .or_insert((kind, Some(entry.scenario_kind), 0));
            record.2 += 1;
        }
    }
    let mut records = Vec::new();
    for (kind, scenario_kind, recurrence_count) in grouped.into_values() {
        if recurrence_count < 2 {
            continue;
        }
        let severity = match kind {
            PaperPolicyTrialStopRecurrenceKind::ActualMutationRepeated
            | PaperPolicyTrialStopRecurrenceKind::TradeOrderAccountRepeated
            | PaperPolicyTrialStopRecurrenceKind::RiskRegressionRepeated => {
                PaperGovernanceAlertSeverity::High
            }
            PaperPolicyTrialStopRecurrenceKind::VoiceConcentrationRepeated
            | PaperPolicyTrialStopRecurrenceKind::OwnerForcedApplyRepeated => {
                if recurrence_count >= 3 {
                    PaperGovernanceAlertSeverity::High
                } else {
                    PaperGovernanceAlertSeverity::Medium
                }
            }
            PaperPolicyTrialStopRecurrenceKind::EvidenceQualityRepeated => {
                PaperGovernanceAlertSeverity::Medium
            }
            _ => PaperGovernanceAlertSeverity::Low,
        };
        let recommended_action = match kind {
            PaperPolicyTrialStopRecurrenceKind::ActualMutationRepeated
            | PaperPolicyTrialStopRecurrenceKind::TradeOrderAccountRepeated => {
                PaperPolicyTrialStopRecurrenceRecommendedAction::StopPaperTrial
            }
            PaperPolicyTrialStopRecurrenceKind::RiskRegressionRepeated
            | PaperPolicyTrialStopRecurrenceKind::VoiceConcentrationRepeated => {
                PaperPolicyTrialStopRecurrenceRecommendedAction::TunePolicy
            }
            PaperPolicyTrialStopRecurrenceKind::OwnerForcedApplyRepeated
            | PaperPolicyTrialStopRecurrenceKind::EvidenceQualityRepeated => {
                PaperPolicyTrialStopRecurrenceRecommendedAction::CollectMoreEvidence
            }
            _ => PaperPolicyTrialStopRecurrenceRecommendedAction::ContinuePaperTrial,
        };
        records.push(PaperPolicyTrialStopRecurrenceRecord {
            record_id: format!("{:?}-{:?}-recurrence", kind, scenario_kind),
            scenario_kind,
            stop_kind: kind,
            recurrence_count,
            severity,
            recommended_action,
            paper_only: true,
        });
    }
    if records.is_empty() {
        return PaperPolicyTrialStopRecurrenceSummary {
            summary_id: format!("{}-stop-recurrence-summary", scenario_ledger.ledger_id),
            recurrence_count: 0,
            high_severity_count: 0,
            dominant_stop_kinds: vec![PaperPolicyTrialStopRecurrenceKind::NoRepeatedStop],
            recurrence_status: PaperPolicyTrialStopRecurrenceStatus::Clear,
            records: vec![PaperPolicyTrialStopRecurrenceRecord {
                record_id: "no-repeated-stop".to_string(),
                scenario_kind: None,
                stop_kind: PaperPolicyTrialStopRecurrenceKind::NoRepeatedStop,
                recurrence_count: 0,
                severity: PaperGovernanceAlertSeverity::Low,
                recommended_action: PaperPolicyTrialStopRecurrenceRecommendedAction::KeepObserving,
                paper_only: true,
            }],
            paper_only: true,
        };
    }
    let high_severity_count = records
        .iter()
        .filter(|record| record.severity == PaperGovernanceAlertSeverity::High)
        .count();
    let max_recurrence = records
        .iter()
        .map(|record| record.recurrence_count)
        .max()
        .unwrap_or(0);
    let dominant_stop_kinds = records
        .iter()
        .filter(|record| record.recurrence_count == max_recurrence)
        .map(|record| record.stop_kind)
        .collect::<Vec<_>>();
    let recurrence_status = if high_severity_count > 0 {
        PaperPolicyTrialStopRecurrenceStatus::RecurrentStops
    } else {
        PaperPolicyTrialStopRecurrenceStatus::ClearWithWarnings
    };
    PaperPolicyTrialStopRecurrenceSummary {
        summary_id: format!("{}-stop-recurrence-summary", scenario_ledger.ledger_id),
        recurrence_count: records.len(),
        high_severity_count,
        dominant_stop_kinds,
        recurrence_status,
        records,
        paper_only: true,
    }
}

fn scenario_trend_status_for_kind(
    trend_summary: &PaperPolicyTrialScenarioTrendSummary,
    kind: PaperPolicyTrialScenarioKind,
) -> PaperPolicyTrialScenarioTrendStatus {
    trend_summary
        .records
        .iter()
        .find(|record| record.scenario_kind == kind)
        .map(|record| record.trend_status)
        .unwrap_or(PaperPolicyTrialScenarioTrendStatus::InsufficientHistory)
}

pub fn compute_paper_policy_trial_risk_first_scenario_trend(
    scenario_ledger: &PaperPolicyTrialScenarioResultLedger,
) -> PaperPolicyTrialRiskFirstScenarioTrend {
    let trend_summary = compute_paper_policy_trial_scenario_trend_summary(scenario_ledger);
    let risk_alignment_worsening_count = scenario_ledger
        .entries
        .iter()
        .filter(|entry| {
            entry.risk_first_status == PaperPolicyTrialScenarioRiskFirstStatus::Violated
                || entry
                    .triggered_stop_conditions
                    .contains(&PaperPolicyTrialStopCondition::RiskRegressionDetected)
        })
        .count();
    let reckless_buy_warning_count = scenario_ledger
        .entries
        .iter()
        .filter(|entry| {
            entry.scenario_kind == PaperPolicyTrialScenarioKind::NegativeTrend
                && matches!(
                    entry.execution_status,
                    PaperPolicyTrialScenarioExecutionStatus::Blocked
                        | PaperPolicyTrialScenarioExecutionStatus::Stopped
                )
        })
        .count();
    let helpful_dissent_preserved_count = scenario_ledger
        .entries
        .iter()
        .filter(|entry| {
            matches!(
                entry.scenario_kind,
                PaperPolicyTrialScenarioKind::HighRiskVeto
                    | PaperPolicyTrialScenarioKind::OwnerRiskConcern
            ) && entry.risk_first_status == PaperPolicyTrialScenarioRiskFirstStatus::Preserved
        })
        .count();
    let mut warnings = Vec::new();
    let risk_first_trend_status = if scenario_ledger.entry_count < 2 {
        PaperPolicyTrialRiskFirstTrendStatus::InsufficientHistory
    } else if risk_alignment_worsening_count > 0 {
        warnings.push("risk alignment worsening was detected in repeated scenarios".to_string());
        PaperPolicyTrialRiskFirstTrendStatus::Worsening
    } else if reckless_buy_warning_count > 0 {
        warnings.push("negative trend scenario shows repeated reckless-buy warnings".to_string());
        PaperPolicyTrialRiskFirstTrendStatus::PreservedWithWarnings
    } else {
        PaperPolicyTrialRiskFirstTrendStatus::Preserved
    };
    PaperPolicyTrialRiskFirstScenarioTrend {
        trend_id: format!("{}-risk-first-scenario-trend", scenario_ledger.ledger_id),
        risk_veto_scenario_status: scenario_trend_status_for_kind(
            &trend_summary,
            PaperPolicyTrialScenarioKind::HighRiskVeto,
        ),
        high_risk_scenario_status: scenario_trend_status_for_kind(
            &trend_summary,
            PaperPolicyTrialScenarioKind::HighRiskVeto,
        ),
        negative_trend_scenario_status: scenario_trend_status_for_kind(
            &trend_summary,
            PaperPolicyTrialScenarioKind::NegativeTrend,
        ),
        evidence_gap_scenario_status: scenario_trend_status_for_kind(
            &trend_summary,
            PaperPolicyTrialScenarioKind::EvidenceGap,
        ),
        reckless_buy_warning_count,
        risk_alignment_worsening_count,
        helpful_dissent_preserved_count,
        risk_first_trend_status,
        warnings,
        paper_only: true,
    }
}

pub fn compute_paper_policy_trial_coverage_stability(
    per_repeat_results: &[PerRepeatPaperPolicyTrialScenarioExecutionResult],
) -> PaperPolicyTrialCoverageStability {
    let repeat_count = per_repeat_results.len();
    let coverage_complete_count = per_repeat_results
        .iter()
        .filter(|result| result.coverage_status == PaperPolicyTrialScenarioCoverageStatus::Complete)
        .count();
    let coverage_warning_count = per_repeat_results
        .iter()
        .filter(|result| {
            result.coverage_status == PaperPolicyTrialScenarioCoverageStatus::CompleteWithWarnings
        })
        .count();
    let coverage_failure_count = per_repeat_results
        .iter()
        .filter(|result| {
            result.coverage_status == PaperPolicyTrialScenarioCoverageStatus::Incomplete
        })
        .count();
    let missing_coverage_recurrence = if coverage_failure_count > 0 {
        vec!["coverage incomplete".to_string()]
    } else {
        Vec::new()
    };
    let coverage_stability_status = if repeat_count < 2 {
        PaperPolicyTrialCoverageStabilityStatus::InsufficientHistory
    } else if coverage_failure_count > 0 {
        PaperPolicyTrialCoverageStabilityStatus::UnstableCoverage
    } else if coverage_warning_count > 0 {
        PaperPolicyTrialCoverageStabilityStatus::StableWithWarnings
    } else {
        PaperPolicyTrialCoverageStabilityStatus::StableComplete
    };
    PaperPolicyTrialCoverageStability {
        stability_id: "paper-policy-trial-coverage-stability".to_string(),
        repeat_count,
        coverage_complete_count,
        coverage_warning_count,
        coverage_failure_count,
        missing_coverage_recurrence,
        coverage_stability_status,
        paper_only: true,
    }
}

pub fn build_paper_policy_scenario_feedback(
    trend_summary: &PaperPolicyTrialScenarioTrendSummary,
    stop_summary: &PaperPolicyTrialStopRecurrenceSummary,
    risk_trend: &PaperPolicyTrialRiskFirstScenarioTrend,
    coverage_stability: &PaperPolicyTrialCoverageStability,
) -> PaperPolicyScenarioFeedbackSummary {
    let mut records = Vec::new();
    if trend_summary.trend_status == PaperPolicyTrialScenarioTrendStatus::Stable
        && stop_summary.recurrence_status == PaperPolicyTrialStopRecurrenceStatus::Clear
        && risk_trend.risk_first_trend_status == PaperPolicyTrialRiskFirstTrendStatus::Preserved
        && coverage_stability.coverage_stability_status
            == PaperPolicyTrialCoverageStabilityStatus::StableComplete
    {
        records.push(PaperPolicyScenarioFeedbackRecord {
            feedback_id: "scenario-feedback-continue".to_string(),
            source: PaperPolicyScenarioFeedbackSource::ScenarioTrend,
            feedback_kind: PaperPolicyScenarioFeedbackKind::ContinueRepeatedPaperExecution,
            severity: PaperGovernanceAlertSeverity::Low,
            reason: "Repeated paper scenario execution is stable and safe.".to_string(),
            paper_only: true,
        });
    }
    if stop_summary.recurrence_status == PaperPolicyTrialStopRecurrenceStatus::RecurrentStops {
        records.push(PaperPolicyScenarioFeedbackRecord {
            feedback_id: "scenario-feedback-stop".to_string(),
            source: PaperPolicyScenarioFeedbackSource::StopRecurrence,
            feedback_kind: PaperPolicyScenarioFeedbackKind::StopPaperTrial,
            severity: PaperGovernanceAlertSeverity::High,
            reason: "Repeated blocking stops were detected in paper scenarios.".to_string(),
            paper_only: true,
        });
    }
    if risk_trend.risk_first_trend_status == PaperPolicyTrialRiskFirstTrendStatus::Worsening {
        records.push(PaperPolicyScenarioFeedbackRecord {
            feedback_id: "scenario-feedback-risk".to_string(),
            source: PaperPolicyScenarioFeedbackSource::RiskFirstTrend,
            feedback_kind: PaperPolicyScenarioFeedbackKind::TuneRiskPolicy,
            severity: PaperGovernanceAlertSeverity::High,
            reason: "Risk-first scenario trend is worsening.".to_string(),
            paper_only: true,
        });
    }
    if coverage_stability.coverage_stability_status
        == PaperPolicyTrialCoverageStabilityStatus::UnstableCoverage
    {
        records.push(PaperPolicyScenarioFeedbackRecord {
            feedback_id: "scenario-feedback-coverage".to_string(),
            source: PaperPolicyScenarioFeedbackSource::CoverageStability,
            feedback_kind: PaperPolicyScenarioFeedbackKind::AddMoreRiskVetoScenarios,
            severity: PaperGovernanceAlertSeverity::Medium,
            reason: "Coverage is unstable across repeated paper scenario execution.".to_string(),
            paper_only: true,
        });
    }
    if records.is_empty() {
        records.push(PaperPolicyScenarioFeedbackRecord {
            feedback_id: "scenario-feedback-history".to_string(),
            source: PaperPolicyScenarioFeedbackSource::ScenarioTrend,
            feedback_kind: PaperPolicyScenarioFeedbackKind::NeedsMoreHistory,
            severity: PaperGovernanceAlertSeverity::Low,
            reason: "More repeated paper history is needed before tuning.".to_string(),
            paper_only: true,
        });
    }
    let high_severity_count = records
        .iter()
        .filter(|record| record.severity == PaperGovernanceAlertSeverity::High)
        .count();
    let dominant_feedback = records
        .iter()
        .max_by_key(|record| match record.severity {
            PaperGovernanceAlertSeverity::Low => 0,
            PaperGovernanceAlertSeverity::Medium => 1,
            PaperGovernanceAlertSeverity::High => 2,
        })
        .map(|record| record.feedback_kind);
    let feedback_status = if records
        .iter()
        .any(|record| record.feedback_kind == PaperPolicyScenarioFeedbackKind::StopPaperTrial)
    {
        PaperPolicyScenarioFeedbackStatus::StopTrial
    } else if records
        .iter()
        .any(|record| record.feedback_kind == PaperPolicyScenarioFeedbackKind::NeedsMoreHistory)
        && records.len() == 1
    {
        PaperPolicyScenarioFeedbackStatus::NeedsMoreHistory
    } else if records.iter().any(|record| {
        matches!(
            record.feedback_kind,
            PaperPolicyScenarioFeedbackKind::AddMoreRiskVetoScenarios
                | PaperPolicyScenarioFeedbackKind::AddEvidenceRequirement
                | PaperPolicyScenarioFeedbackKind::AddOwnerExplanationCase
        )
    }) {
        PaperPolicyScenarioFeedbackStatus::CollectMoreEvidence
    } else if records.iter().any(|record| {
        matches!(
            record.feedback_kind,
            PaperPolicyScenarioFeedbackKind::TuneRiskPolicy
                | PaperPolicyScenarioFeedbackKind::TuneVoiceBalance
        )
    }) {
        PaperPolicyScenarioFeedbackStatus::TunePolicy
    } else {
        PaperPolicyScenarioFeedbackStatus::ContinueTrial
    };
    PaperPolicyScenarioFeedbackSummary {
        summary_id: "paper-policy-scenario-feedback-summary".to_string(),
        feedback_count: records.len(),
        high_severity_count,
        dominant_feedback,
        feedback_status,
        records,
        paper_only: true,
    }
}

pub fn evaluate_paper_policy_repeated_execution_gate(
    trend_summary: &PaperPolicyTrialScenarioTrendSummary,
    stop_summary: &PaperPolicyTrialStopRecurrenceSummary,
    risk_trend: &PaperPolicyTrialRiskFirstScenarioTrend,
    coverage_stability: &PaperPolicyTrialCoverageStability,
    safety_guard: &PaperPolicyRepeatedScenarioExecutionSafetyGuard,
) -> PaperPolicyRepeatedExecutionGate {
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    if safety_guard.guard_status == PaperGovernanceTrialSafetyGuardStatus::Violated {
        blockers.push("paper policy repeated scenario safety guard was violated".to_string());
    }
    if stop_summary.recurrence_status == PaperPolicyTrialStopRecurrenceStatus::RecurrentStops {
        blockers.push("paper policy repeated scenario stop recurrence is blocking".to_string());
    }
    if risk_trend.risk_first_trend_status == PaperPolicyTrialRiskFirstTrendStatus::Worsening {
        blockers.push("paper policy repeated scenario risk-first trend is worsening".to_string());
    }
    if trend_summary.trend_status == PaperPolicyTrialScenarioTrendStatus::InsufficientHistory
        || coverage_stability.coverage_stability_status
            == PaperPolicyTrialCoverageStabilityStatus::InsufficientHistory
    {
        warnings.push("paper policy repeated scenario needs more history".to_string());
    }
    if coverage_stability.coverage_stability_status
        == PaperPolicyTrialCoverageStabilityStatus::StableWithWarnings
    {
        warnings.push("coverage stability completed with warnings".to_string());
    }
    if coverage_stability.coverage_stability_status
        == PaperPolicyTrialCoverageStabilityStatus::UnstableCoverage
    {
        warnings.push("coverage stability is unstable".to_string());
    }
    let gate_status = if safety_guard.guard_status
        == PaperGovernanceTrialSafetyGuardStatus::Violated
    {
        PaperPolicyRepeatedExecutionGateStatus::BlockedBySafety
    } else if stop_summary.recurrence_status == PaperPolicyTrialStopRecurrenceStatus::RecurrentStops
    {
        PaperPolicyRepeatedExecutionGateStatus::BlockedByRecurrentStops
    } else if risk_trend.risk_first_trend_status == PaperPolicyTrialRiskFirstTrendStatus::Worsening
    {
        PaperPolicyRepeatedExecutionGateStatus::BlockedByRiskRegression
    } else if trend_summary.trend_status == PaperPolicyTrialScenarioTrendStatus::InsufficientHistory
        || coverage_stability.coverage_stability_status
            == PaperPolicyTrialCoverageStabilityStatus::InsufficientHistory
    {
        PaperPolicyRepeatedExecutionGateStatus::NeedsMoreHistory
    } else if coverage_stability.coverage_stability_status
        == PaperPolicyTrialCoverageStabilityStatus::UnstableCoverage
        || trend_summary.trend_status == PaperPolicyTrialScenarioTrendStatus::Mixed
    {
        PaperPolicyRepeatedExecutionGateStatus::NeedsPolicyTuning
    } else if warnings.is_empty() {
        PaperPolicyRepeatedExecutionGateStatus::ContinueRepeatedPaperExecution
    } else {
        PaperPolicyRepeatedExecutionGateStatus::ContinueWithWarnings
    };
    PaperPolicyRepeatedExecutionGate {
        gate_id: "paper-policy-repeated-execution-gate".to_string(),
        scenario_trend_status: trend_summary.trend_status,
        stop_recurrence_status: stop_summary.recurrence_status,
        risk_first_trend_status: risk_trend.risk_first_trend_status,
        coverage_stability_status: coverage_stability.coverage_stability_status,
        safety_status: safety_guard.guard_status,
        continue_repeated_paper_execution: matches!(
            gate_status,
            PaperPolicyRepeatedExecutionGateStatus::ContinueRepeatedPaperExecution
                | PaperPolicyRepeatedExecutionGateStatus::ContinueWithWarnings
        ),
        gate_status,
        blockers,
        warnings,
        paper_only: true,
    }
}

fn build_paper_policy_repeated_scenario_execution_safety_guard_from_parts(
    repeated_result: &PaperPolicyTrialRepeatedScenarioExecutionResult,
    continue_repeated_paper_execution: bool,
    batch_before: Option<&BatchCommitteeCycleWithStateResult>,
    batch_after: Option<&BatchCommitteeCycleWithStateResult>,
) -> PaperPolicyRepeatedScenarioExecutionSafetyGuard {
    let after = batch_after.or(batch_before);
    let actual_policy_apply_detected = repeated_result
        .repeat_run_results
        .iter()
        .any(|run| run.safety_guard.actual_policy_apply_detected);
    let actual_score_mutation_detected = repeated_result
        .repeat_run_results
        .iter()
        .any(|run| run.safety_guard.actual_score_mutation_detected)
        || if let (Some(before), Some(after)) = (batch_before, after) {
            before.state_update.updated_member_states != after.state_update.updated_member_states
        } else {
            false
        };
    let actual_voice_mutation_detected = repeated_result
        .repeat_run_results
        .iter()
        .any(|run| run.safety_guard.actual_voice_mutation_detected);
    let committee_decision_mutation_detected = repeated_result
        .repeat_run_results
        .iter()
        .any(|run| run.safety_guard.committee_decision_mutation_detected)
        || if let (Some(before), Some(after)) = (batch_before, after) {
            before.batch_result.committee_sessions != after.batch_result.committee_sessions
        } else {
            false
        };
    let chairman_decision_mutation_detected = repeated_result
        .repeat_run_results
        .iter()
        .any(|run| run.safety_guard.chairman_decision_mutation_detected)
        || if let (Some(before), Some(after)) = (batch_before, after) {
            before.batch_result.chairman_decisions != after.batch_result.chairman_decisions
        } else {
            false
        };
    let risk_governor_override_detected = repeated_result
        .repeat_run_results
        .iter()
        .any(|run| run.safety_guard.risk_governor_override_detected);
    let trade_signal_detected = repeated_result
        .repeat_run_results
        .iter()
        .any(|run| run.safety_guard.trade_signal_detected);
    let order_detected = repeated_result
        .repeat_run_results
        .iter()
        .any(|run| run.safety_guard.order_detected);
    let broker_order_account_detected = repeated_result
        .repeat_run_results
        .iter()
        .any(|run| run.safety_guard.broker_order_account_detected);
    let scenario_ledger_write_when_dry_run_detected =
        repeated_result.dry_run && repeated_result.wrote_ledger;
    let repeated_execution_used_as_live_decision_detected = actual_policy_apply_detected
        || committee_decision_mutation_detected
        || chairman_decision_mutation_detected
        || repeated_result.repeat_run_results.iter().any(|run| {
            run.safety_guard
                .paper_scenario_used_as_live_decision_detected
        });
    let unsafe_gate_open_detected = continue_repeated_paper_execution
        && (actual_policy_apply_detected
            || actual_score_mutation_detected
            || actual_voice_mutation_detected
            || committee_decision_mutation_detected
            || chairman_decision_mutation_detected
            || risk_governor_override_detected
            || trade_signal_detected
            || order_detected
            || broker_order_account_detected
            || repeated_result.stop_recurrence_summary.recurrence_status
                == PaperPolicyTrialStopRecurrenceStatus::RecurrentStops
            || repeated_result
                .risk_first_scenario_trend
                .risk_first_trend_status
                == PaperPolicyTrialRiskFirstTrendStatus::Worsening);
    let mut violations = Vec::new();
    if actual_policy_apply_detected {
        violations.push("actual policy apply was detected".to_string());
    }
    if actual_score_mutation_detected {
        violations.push("actual score mutation was detected".to_string());
    }
    if actual_voice_mutation_detected {
        violations.push("actual voice mutation was detected".to_string());
    }
    if committee_decision_mutation_detected {
        violations.push("committee decision mutation was detected".to_string());
    }
    if chairman_decision_mutation_detected {
        violations.push("chairman decision mutation was detected".to_string());
    }
    if risk_governor_override_detected {
        violations.push("risk governor override was detected".to_string());
    }
    if trade_signal_detected || order_detected || broker_order_account_detected {
        violations.push("trade/order/account path was detected".to_string());
    }
    if scenario_ledger_write_when_dry_run_detected {
        violations.push("scenario ledger write was detected during dry run".to_string());
    }
    if repeated_execution_used_as_live_decision_detected {
        violations.push("repeated execution was used as a live decision".to_string());
    }
    if unsafe_gate_open_detected {
        violations.push("unsafe repeated execution gate was opened".to_string());
    }
    PaperPolicyRepeatedScenarioExecutionSafetyGuard {
        actual_policy_apply_detected,
        actual_score_mutation_detected,
        actual_voice_mutation_detected,
        committee_decision_mutation_detected,
        chairman_decision_mutation_detected,
        risk_governor_override_detected,
        trade_signal_detected,
        order_detected,
        broker_order_account_detected,
        scenario_ledger_write_when_dry_run_detected,
        repeated_execution_used_as_live_decision_detected,
        unsafe_gate_open_detected,
        guard_status: if violations.is_empty() {
            PaperGovernanceTrialSafetyGuardStatus::Preserved
        } else {
            PaperGovernanceTrialSafetyGuardStatus::Violated
        },
        violations,
        paper_only: true,
    }
}

pub fn evaluate_paper_policy_repeated_scenario_execution_safety(
    repeated_result: &PaperPolicyTrialRepeatedScenarioExecutionResult,
    batch_before: &BatchCommitteeCycleWithStateResult,
    batch_after: Option<&BatchCommitteeCycleWithStateResult>,
) -> PaperPolicyRepeatedScenarioExecutionSafetyGuard {
    build_paper_policy_repeated_scenario_execution_safety_guard_from_parts(
        repeated_result,
        repeated_result
            .repeated_execution_gate
            .continue_repeated_paper_execution,
        Some(batch_before),
        batch_after,
    )
}

pub fn prove_paper_policy_repeated_scenario_ledger_write(
    repeated_result: &PaperPolicyTrialRepeatedScenarioExecutionResult,
    ledger_path: &Path,
) -> Result<PaperPolicyRepeatedScenarioLedgerWriteProof, String> {
    validate_local_json_path(ledger_path, "paper policy repeated scenario ledger path")?;
    let ledger_exists_after_write = ledger_path.exists();
    let (entry_count, paper_only_count, unsafe_entry_count) = if ledger_exists_after_write {
        let ledger = load_paper_policy_trial_scenario_result_ledger_from_local_json(ledger_path)?;
        let paper_only_count = ledger
            .entries
            .iter()
            .filter(|entry| entry.paper_only)
            .count();
        let unsafe_entry_count = ledger.entries.len().saturating_sub(paper_only_count);
        (ledger.entry_count, paper_only_count, unsafe_entry_count)
    } else {
        (0, 0, 0)
    };
    let proof_status = if repeated_result.wrote_ledger && !ledger_exists_after_write {
        PaperGovernanceTrialLedgerWriteProofStatus::Failed
    } else if unsafe_entry_count > 0 {
        PaperGovernanceTrialLedgerWriteProofStatus::Failed
    } else if entry_count < repeated_result.final_ledger_entry_count {
        PaperGovernanceTrialLedgerWriteProofStatus::ProvenWithWarnings
    } else {
        PaperGovernanceTrialLedgerWriteProofStatus::Proven
    };
    Ok(PaperPolicyRepeatedScenarioLedgerWriteProof {
        proof_id: format!(
            "{}-repeated-scenario-ledger-write-proof",
            repeated_result.run_id
        ),
        expected_output_path: ledger_path.display().to_string(),
        wrote_ledger: repeated_result.wrote_ledger,
        ledger_exists_after_write,
        entry_count,
        paper_only_count,
        unsafe_entry_count,
        proof_status,
        paper_only: true,
    })
}

pub fn build_owner_paper_policy_repeated_scenario_summary(
    repeated_result: &PaperPolicyTrialRepeatedScenarioExecutionResult,
) -> OwnerPaperPolicyRepeatedScenarioSummary {
    OwnerPaperPolicyRepeatedScenarioSummary {
        summary_id: format!("{}-owner-paper-policy-repeated-scenario-summary", repeated_result.run_id),
        completed_repeat_count: repeated_result.completed_repeat_count,
        final_ledger_entry_count: repeated_result.final_ledger_entry_count,
        scenario_trend_status: repeated_result.scenario_trend_summary.trend_status,
        stop_recurrence_status: repeated_result.stop_recurrence_summary.recurrence_status,
        risk_first_trend_status: repeated_result.risk_first_scenario_trend.risk_first_trend_status,
        coverage_stability_status: repeated_result.coverage_stability.coverage_stability_status,
        repeated_execution_gate_status: repeated_result.repeated_execution_gate.gate_status,
        message: "Paper policy trial scenarios were repeated only in paper mode. Actual score, voice, committee decisions, Risk Governor, and trading remain unchanged. The gate only controls whether more paper scenario execution is allowed.".to_string(),
        paper_trial_only: true,
        no_actual_policy_apply: true,
        no_score_mutation: true,
        no_voice_mutation: true,
        no_committee_decision_change: true,
        no_risk_override: true,
        not_trade_signal: true,
        paper_only: true,
    }
}

fn repeated_scenario_run_status(
    gate: &PaperPolicyRepeatedExecutionGate,
    safety_guard: &PaperPolicyRepeatedScenarioExecutionSafetyGuard,
    write_proof: Option<&PaperPolicyRepeatedScenarioLedgerWriteProof>,
) -> PaperGovernanceTrialRunStatus {
    if safety_guard.guard_status == PaperGovernanceTrialSafetyGuardStatus::Violated
        || matches!(
            gate.gate_status,
            PaperPolicyRepeatedExecutionGateStatus::BlockedByRecurrentStops
                | PaperPolicyRepeatedExecutionGateStatus::BlockedByRiskRegression
                | PaperPolicyRepeatedExecutionGateStatus::BlockedBySafety
        )
        || write_proof.is_some_and(|proof| {
            proof.proof_status == PaperGovernanceTrialLedgerWriteProofStatus::Failed
        })
    {
        PaperGovernanceTrialRunStatus::Failed
    } else if matches!(
        gate.gate_status,
        PaperPolicyRepeatedExecutionGateStatus::ContinueWithWarnings
            | PaperPolicyRepeatedExecutionGateStatus::NeedsMoreHistory
            | PaperPolicyRepeatedExecutionGateStatus::NeedsPolicyTuning
    ) || write_proof.is_some_and(|proof| {
        proof.proof_status == PaperGovernanceTrialLedgerWriteProofStatus::ProvenWithWarnings
    }) {
        PaperGovernanceTrialRunStatus::PassedWithWarnings
    } else {
        PaperGovernanceTrialRunStatus::Passed
    }
}

pub fn run_repeated_paper_policy_trial_scenario_execution(
    plan: &PaperPolicyTrialPlan,
    matrix: &PaperPolicyTrialScenarioMatrix,
    config: &PaperPolicyTrialRepeatedScenarioExecutionConfig,
) -> Result<PaperPolicyTrialRepeatedScenarioExecutionResult, String> {
    let mut final_scenario_ledger = if let Some(path) = config
        .scenario_ledger_input_path
        .as_ref()
        .filter(|path| !path.trim().is_empty())
    {
        load_paper_policy_trial_scenario_result_ledger_from_local_json(Path::new(path))?
    } else {
        default_paper_policy_trial_scenario_result_ledger()
    };
    let previous_ledger_entry_count = final_scenario_ledger.entry_count;
    let mut per_repeat_results = Vec::new();
    let mut repeat_run_results = Vec::new();
    for repeat_index in 0..config.repeat_count {
        let run = run_paper_policy_trial_scenario_execution(
            plan,
            matrix,
            &PaperPolicyTrialScenarioExecutionRunConfig {
                run_id: format!("{}-repeat-{}", config.run_id, repeat_index + 1),
                enabled: true,
                plan_input_path: None,
                scenario_matrix_input_path: None,
                scenario_result_ledger_input_path: None,
                scenario_result_ledger_output_path: None,
                max_scenarios: matrix.scenario_count.max(1),
                dry_run: true,
                write_scenario_ledger: false,
                stop_on_first_blocking_condition: config.stop_on_repeated_blocking_condition,
                emit_owner_summary: false,
                paper_only: true,
            },
        )?;
        append_paper_policy_trial_scenario_result_entries(
            &mut final_scenario_ledger,
            &run.scenario_result_ledger.entries,
        )?;
        per_repeat_results.push(PerRepeatPaperPolicyTrialScenarioExecutionResult {
            repeat_index: repeat_index + 1,
            scenario_count: run.scenario_results.len(),
            executed_count: run.aggregate_metrics.executed_count,
            stopped_count: run.aggregate_metrics.stopped_count,
            blocked_count: run.aggregate_metrics.blocked_count,
            aggregate_status: run.aggregate_metrics.aggregate_status,
            coverage_status: run.coverage_quality.coverage_status,
            stop_monitor_status: run.stop_condition_monitor.monitor_status,
            execution_gate_status: run.execution_gate.gate_status,
            safety_status: run.safety_guard.guard_status,
            paper_only: true,
        });
        let stop_requested = config.stop_on_repeated_blocking_condition
            && matches!(
                run.execution_gate.gate_status,
                PaperPolicyTrialExecutionGateStatus::BlockedBySafety
                    | PaperPolicyTrialExecutionGateStatus::BlockedByStopCondition
                    | PaperPolicyTrialExecutionGateStatus::Failed
            );
        repeat_run_results.push(run);
        if stop_requested {
            break;
        }
    }
    let completed_repeat_count = per_repeat_results.len();
    let appended_entry_count = final_scenario_ledger
        .entry_count
        .saturating_sub(previous_ledger_entry_count);
    let final_ledger_entry_count = final_scenario_ledger.entry_count;
    let scenario_trend_summary =
        compute_paper_policy_trial_scenario_trend_summary(&final_scenario_ledger);
    let stop_recurrence_summary =
        summarize_paper_policy_trial_stop_recurrence(&final_scenario_ledger);
    let risk_first_scenario_trend =
        compute_paper_policy_trial_risk_first_scenario_trend(&final_scenario_ledger);
    let coverage_stability = compute_paper_policy_trial_coverage_stability(&per_repeat_results);
    let policy_feedback = build_paper_policy_scenario_feedback(
        &scenario_trend_summary,
        &stop_recurrence_summary,
        &risk_first_scenario_trend,
        &coverage_stability,
    );
    let mut result = PaperPolicyTrialRepeatedScenarioExecutionResult {
        run_id: config.run_id.clone(),
        requested_repeat_count: config.repeat_count,
        completed_repeat_count,
        previous_ledger_entry_count,
        appended_entry_count,
        final_ledger_entry_count,
        per_repeat_results,
        repeat_run_results,
        scenario_trend_summary,
        stop_recurrence_summary,
        risk_first_scenario_trend,
        coverage_stability,
        policy_feedback,
        repeated_execution_gate: PaperPolicyRepeatedExecutionGate {
            gate_id: "paper-policy-repeated-execution-gate".to_string(),
            scenario_trend_status: PaperPolicyTrialScenarioTrendStatus::InsufficientHistory,
            stop_recurrence_status: PaperPolicyTrialStopRecurrenceStatus::InsufficientHistory,
            risk_first_trend_status: PaperPolicyTrialRiskFirstTrendStatus::InsufficientHistory,
            coverage_stability_status: PaperPolicyTrialCoverageStabilityStatus::InsufficientHistory,
            safety_status: PaperGovernanceTrialSafetyGuardStatus::Preserved,
            continue_repeated_paper_execution: false,
            gate_status: PaperPolicyRepeatedExecutionGateStatus::NeedsMoreHistory,
            blockers: Vec::new(),
            warnings: Vec::new(),
            paper_only: true,
        },
        safety_guard: PaperPolicyRepeatedScenarioExecutionSafetyGuard {
            actual_policy_apply_detected: false,
            actual_score_mutation_detected: false,
            actual_voice_mutation_detected: false,
            committee_decision_mutation_detected: false,
            chairman_decision_mutation_detected: false,
            risk_governor_override_detected: false,
            trade_signal_detected: false,
            order_detected: false,
            broker_order_account_detected: false,
            scenario_ledger_write_when_dry_run_detected: false,
            repeated_execution_used_as_live_decision_detected: false,
            unsafe_gate_open_detected: false,
            guard_status: PaperGovernanceTrialSafetyGuardStatus::Preserved,
            violations: Vec::new(),
            paper_only: true,
        },
        write_proof: None,
        owner_summary: None,
        run_status: PaperGovernanceTrialRunStatus::Passed,
        dry_run: config.dry_run,
        wrote_ledger: false,
        final_scenario_ledger,
        paper_only: true,
    };
    result.safety_guard = build_paper_policy_repeated_scenario_execution_safety_guard_from_parts(
        &result, false, None, None,
    );
    result.repeated_execution_gate = evaluate_paper_policy_repeated_execution_gate(
        &result.scenario_trend_summary,
        &result.stop_recurrence_summary,
        &result.risk_first_scenario_trend,
        &result.coverage_stability,
        &result.safety_guard,
    );
    result.safety_guard = build_paper_policy_repeated_scenario_execution_safety_guard_from_parts(
        &result,
        result
            .repeated_execution_gate
            .continue_repeated_paper_execution,
        None,
        None,
    );
    result.repeated_execution_gate = evaluate_paper_policy_repeated_execution_gate(
        &result.scenario_trend_summary,
        &result.stop_recurrence_summary,
        &result.risk_first_scenario_trend,
        &result.coverage_stability,
        &result.safety_guard,
    );
    if !config.dry_run && config.append_scenario_ledger {
        let output_path = config
            .scenario_ledger_output_path
            .as_ref()
            .filter(|path| !path.trim().is_empty())
            .ok_or_else(|| {
                "paper policy repeated scenario ledger output path is required when appending ledger"
                    .to_string()
            })?;
        save_paper_policy_trial_scenario_result_ledger_to_local_json(
            Path::new(output_path),
            &result.final_scenario_ledger,
        )?;
        result.wrote_ledger = true;
        result.write_proof = Some(prove_paper_policy_repeated_scenario_ledger_write(
            &result,
            Path::new(output_path),
        )?);
        result.safety_guard =
            build_paper_policy_repeated_scenario_execution_safety_guard_from_parts(
                &result,
                result
                    .repeated_execution_gate
                    .continue_repeated_paper_execution,
                None,
                None,
            );
        result.repeated_execution_gate = evaluate_paper_policy_repeated_execution_gate(
            &result.scenario_trend_summary,
            &result.stop_recurrence_summary,
            &result.risk_first_scenario_trend,
            &result.coverage_stability,
            &result.safety_guard,
        );
    }
    if config.emit_owner_summary {
        result.owner_summary = Some(build_owner_paper_policy_repeated_scenario_summary(&result));
    }
    result.run_status = repeated_scenario_run_status(
        &result.repeated_execution_gate,
        &result.safety_guard,
        result.write_proof.as_ref(),
    );
    Ok(result)
}

fn maybe_run_repeated_paper_policy_trial_scenario_execution_for_stateful_result(
    run_id: String,
    enabled: bool,
    repeat_count: usize,
    dry_run: bool,
    append_scenario_ledger: bool,
    scenario_ledger_input_path: Option<&String>,
    scenario_ledger_output_path: Option<&String>,
    stop_on_repeated_blocking_condition: bool,
    emit_owner_summary: bool,
    stateful_result: &mut BatchCommitteeCycleWithStateResult,
) -> Result<Option<PaperPolicyTrialRepeatedScenarioExecutionResult>, String> {
    if !paper_policy_trial_repeated_scenario_requested_from_flags(
        enabled,
        dry_run,
        repeat_count,
        append_scenario_ledger,
        scenario_ledger_input_path,
        scenario_ledger_output_path,
        stop_on_repeated_blocking_condition,
        emit_owner_summary,
    ) {
        return Ok(None);
    }
    let plan = stateful_result
        .batch_result
        .paper_policy_trial_plan
        .clone()
        .ok_or_else(|| {
            "repeated paper policy trial scenario execution requires trial plan".to_string()
        })?;
    let matrix = stateful_result
        .batch_result
        .paper_policy_trial_scenario_matrix
        .clone()
        .unwrap_or_else(build_default_paper_policy_trial_scenario_matrix);
    let before_snapshot = stateful_result.clone();
    let mut result = run_repeated_paper_policy_trial_scenario_execution(
        &plan,
        &matrix,
        &PaperPolicyTrialRepeatedScenarioExecutionConfig {
            run_id,
            enabled,
            repeat_count,
            scenario_ledger_input_path: scenario_ledger_input_path.cloned(),
            scenario_ledger_output_path: scenario_ledger_output_path.cloned(),
            dry_run,
            append_scenario_ledger,
            stop_on_repeated_blocking_condition,
            emit_owner_summary,
            paper_only: true,
        },
    )?;
    stateful_result
        .batch_result
        .paper_policy_trial_scenario_result_ledger = Some(result.final_scenario_ledger.clone());
    stateful_result
        .batch_result
        .paper_policy_trial_scenario_trend_summary = Some(result.scenario_trend_summary.clone());
    stateful_result
        .batch_result
        .paper_policy_trial_stop_recurrence_summary = Some(result.stop_recurrence_summary.clone());
    stateful_result
        .batch_result
        .paper_policy_trial_risk_first_scenario_trend =
        Some(result.risk_first_scenario_trend.clone());
    stateful_result
        .batch_result
        .paper_policy_trial_coverage_stability = Some(result.coverage_stability.clone());
    stateful_result
        .batch_result
        .paper_policy_scenario_feedback_summary = Some(result.policy_feedback.clone());
    stateful_result
        .batch_result
        .paper_policy_repeated_execution_gate = Some(result.repeated_execution_gate.clone());
    stateful_result
        .batch_result
        .paper_policy_repeated_scenario_execution_safety_guard = Some(result.safety_guard.clone());
    stateful_result
        .batch_result
        .paper_policy_repeated_scenario_ledger_write_proof = result.write_proof.clone();
    stateful_result
        .batch_result
        .owner_paper_policy_repeated_scenario_summary = result.owner_summary.clone();
    stateful_result
        .batch_result
        .paper_policy_trial_repeated_scenario_execution_result = Some(result.clone());
    let after_snapshot = stateful_result.clone();
    result.safety_guard = evaluate_paper_policy_repeated_scenario_execution_safety(
        &result,
        &before_snapshot,
        Some(&after_snapshot),
    );
    result.repeated_execution_gate = evaluate_paper_policy_repeated_execution_gate(
        &result.scenario_trend_summary,
        &result.stop_recurrence_summary,
        &result.risk_first_scenario_trend,
        &result.coverage_stability,
        &result.safety_guard,
    );
    if emit_owner_summary {
        result.owner_summary = Some(build_owner_paper_policy_repeated_scenario_summary(&result));
    }
    result.run_status = repeated_scenario_run_status(
        &result.repeated_execution_gate,
        &result.safety_guard,
        result.write_proof.as_ref(),
    );
    stateful_result
        .batch_result
        .paper_policy_repeated_execution_gate = Some(result.repeated_execution_gate.clone());
    stateful_result
        .batch_result
        .paper_policy_repeated_scenario_execution_safety_guard = Some(result.safety_guard.clone());
    stateful_result
        .batch_result
        .owner_paper_policy_repeated_scenario_summary = result.owner_summary.clone();
    stateful_result
        .batch_result
        .paper_policy_trial_repeated_scenario_execution_result = Some(result.clone());
    Ok(Some(result))
}

fn paper_policy_trial_scenario_kind_key(kind: PaperPolicyTrialScenarioKind) -> String {
    format!("{:?}", kind)
}

fn required_paper_policy_trial_scenario_kinds(
    scenario_matrix: &PaperPolicyTrialScenarioMatrix,
) -> Vec<PaperPolicyTrialScenarioKind> {
    let mut seen = BTreeSet::new();
    let mut kinds = Vec::new();
    for scenario in &scenario_matrix.scenarios {
        let key = paper_policy_trial_scenario_kind_key(scenario.scenario_kind);
        if seen.insert(key) {
            kinds.push(scenario.scenario_kind);
        }
    }
    kinds
}

fn paper_policy_trial_scenario_entry_is_unsafe(
    entry: &PaperPolicyTrialScenarioResultLedgerEntry,
) -> bool {
    !entry.paper_only
        || entry.triggered_stop_conditions.iter().any(|condition| {
            matches!(
                condition,
                PaperPolicyTrialStopCondition::ActualMutationDetected
                    | PaperPolicyTrialStopCondition::RiskGovernorOverrideDetected
                    | PaperPolicyTrialStopCondition::TradeOrderAccountDetected
                    | PaperPolicyTrialStopCondition::OwnerForcedApplyDetected
            )
        })
}

fn round_score(score: f64) -> f64 {
    (score * 100.0).round() / 100.0
}

fn average_score(values: &[f64]) -> f64 {
    if values.is_empty() {
        0.0
    } else {
        round_score(values.iter().sum::<f64>() / values.len() as f64)
    }
}

fn clamp_score(score: f64) -> f64 {
    score.clamp(0.0, 100.0)
}

fn ledger_repeat_count_estimate(
    ledger: &PaperPolicyTrialScenarioResultLedger,
    scenario_matrix: &PaperPolicyTrialScenarioMatrix,
) -> usize {
    let required_kinds = required_paper_policy_trial_scenario_kinds(scenario_matrix);
    if required_kinds.is_empty() {
        return 0;
    }
    required_kinds
        .iter()
        .map(|kind| {
            ledger
                .entries
                .iter()
                .filter(|entry| entry.scenario_kind == *kind)
                .count()
        })
        .min()
        .unwrap_or(0)
}

pub fn evaluate_paper_policy_scenario_ledger_quality(
    ledger: &PaperPolicyTrialScenarioResultLedger,
    required_scenario_matrix: &PaperPolicyTrialScenarioMatrix,
) -> PaperPolicyScenarioLedgerQualityEvaluation {
    let required_kinds = required_paper_policy_trial_scenario_kinds(required_scenario_matrix);
    let mut scenario_kind_seen = BTreeSet::new();
    let mut unique_entry_keys = BTreeSet::new();
    let mut duplicate_entry_count = 0;
    let mut unsafe_entry_count = 0;
    let mut paper_only_entry_count = 0;
    let mut transient_readiness_warning_count = 0;
    for entry in &ledger.entries {
        scenario_kind_seen.insert(paper_policy_trial_scenario_kind_key(entry.scenario_kind));
        if !unique_entry_keys.insert(format!(
            "{}::{}::{}",
            entry.run_id,
            entry.scenario_id,
            paper_policy_trial_scenario_kind_key(entry.scenario_kind)
        )) {
            duplicate_entry_count += 1;
        }
        if paper_policy_trial_scenario_entry_is_unsafe(entry) {
            unsafe_entry_count += 1;
        }
        if entry.paper_only {
            paper_only_entry_count += 1;
        }
        if entry.execution_status == PaperPolicyTrialScenarioExecutionStatus::Skipped
            || entry.success_status == PaperPolicyTrialSuccessStatus::InsufficientData
        {
            transient_readiness_warning_count += 1;
        }
    }
    let missing_scenarios = required_kinds
        .iter()
        .copied()
        .filter(|kind| {
            !ledger
                .entries
                .iter()
                .any(|entry| entry.scenario_kind == *kind)
        })
        .collect::<Vec<_>>();
    let repeat_count_estimate = ledger_repeat_count_estimate(ledger, required_scenario_matrix);
    let mut warnings = Vec::new();
    let mut blockers = Vec::new();
    if duplicate_entry_count > 0 {
        warnings.push("duplicate scenario ledger entries were detected".to_string());
    }
    if transient_readiness_warning_count > 0 {
        warnings.push("transient readiness or insufficient-data entries were detected".to_string());
    }
    if repeat_count_estimate < 2 {
        warnings.push("repeated scenario history is still shallow".to_string());
    }
    if !missing_scenarios.is_empty() {
        blockers.push("required scenario kinds are missing from the repeated ledger".to_string());
    }
    if unsafe_entry_count > 0 {
        blockers.push("unsafe repeated scenario ledger entries were detected".to_string());
    }
    let quality_status = if unsafe_entry_count > 0 {
        PaperPolicyScenarioLedgerQualityStatus::Unsafe
    } else if !missing_scenarios.is_empty() {
        PaperPolicyScenarioLedgerQualityStatus::Incomplete
    } else if repeat_count_estimate < 2 {
        PaperPolicyScenarioLedgerQualityStatus::InsufficientHistory
    } else if duplicate_entry_count > 0 || transient_readiness_warning_count > 0 {
        PaperPolicyScenarioLedgerQualityStatus::ValidWithWarnings
    } else {
        PaperPolicyScenarioLedgerQualityStatus::Valid
    };
    PaperPolicyScenarioLedgerQualityEvaluation {
        evaluation_id: format!("{}-quality-evaluation", ledger.ledger_id),
        ledger_entry_count: ledger.entry_count,
        scenario_kind_count: scenario_kind_seen.len(),
        repeat_count_estimate,
        duplicate_entry_count,
        missing_scenario_kind_count: missing_scenarios.len(),
        unsafe_entry_count,
        paper_only_entry_count,
        transient_readiness_warning_count,
        quality_status,
        missing_scenarios,
        warnings,
        blockers,
        paper_only: true,
    }
}

fn scenario_execution_score(status: PaperPolicyTrialScenarioExecutionStatus) -> f64 {
    match status {
        PaperPolicyTrialScenarioExecutionStatus::Executed => 100.0,
        PaperPolicyTrialScenarioExecutionStatus::ExecutedWithWarnings => 85.0,
        PaperPolicyTrialScenarioExecutionStatus::Stopped => 50.0,
        PaperPolicyTrialScenarioExecutionStatus::Blocked => 15.0,
        PaperPolicyTrialScenarioExecutionStatus::Skipped => 35.0,
    }
}

fn scenario_success_score(status: PaperPolicyTrialSuccessStatus) -> f64 {
    match status {
        PaperPolicyTrialSuccessStatus::Passed => 100.0,
        PaperPolicyTrialSuccessStatus::PassedWithWarnings => 80.0,
        PaperPolicyTrialSuccessStatus::Failed => 20.0,
        PaperPolicyTrialSuccessStatus::InsufficientData => 40.0,
    }
}

fn scenario_risk_first_score(status: PaperPolicyTrialScenarioRiskFirstStatus) -> f64 {
    match status {
        PaperPolicyTrialScenarioRiskFirstStatus::Preserved => 100.0,
        PaperPolicyTrialScenarioRiskFirstStatus::PreservedWithWarnings => 80.0,
        PaperPolicyTrialScenarioRiskFirstStatus::Violated => 15.0,
        PaperPolicyTrialScenarioRiskFirstStatus::InsufficientData => 40.0,
    }
}

fn scenario_voice_balance_score(status: PaperPolicyTrialScenarioVoiceBalanceStatus) -> f64 {
    match status {
        PaperPolicyTrialScenarioVoiceBalanceStatus::Balanced => 100.0,
        PaperPolicyTrialScenarioVoiceBalanceStatus::BalancedWithWarnings => 80.0,
        PaperPolicyTrialScenarioVoiceBalanceStatus::Imbalanced => 35.0,
        PaperPolicyTrialScenarioVoiceBalanceStatus::InsufficientData => 45.0,
    }
}

fn scenario_stop_cleanliness_score(status: PaperPolicyTrialStopStatus) -> f64 {
    match status {
        PaperPolicyTrialStopStatus::Continue => 100.0,
        PaperPolicyTrialStopStatus::ContinueWithWarnings => 65.0,
        PaperPolicyTrialStopStatus::Stop => 20.0,
    }
}

fn owner_reference_scenario_kind(kind: PaperPolicyTrialScenarioKind) -> bool {
    matches!(
        kind,
        PaperPolicyTrialScenarioKind::OwnerRiskConcern
            | PaperPolicyTrialScenarioKind::OwnerEvidenceRequest
    )
}

fn owner_reference_score_for_entry(
    scenario_kind: PaperPolicyTrialScenarioKind,
    status: PaperPolicyTrialScenarioOwnerReferenceStatus,
) -> f64 {
    match status {
        PaperPolicyTrialScenarioOwnerReferenceStatus::Explained => 100.0,
        PaperPolicyTrialScenarioOwnerReferenceStatus::ExplainedWithWarnings => 75.0,
        PaperPolicyTrialScenarioOwnerReferenceStatus::Failed => 20.0,
        PaperPolicyTrialScenarioOwnerReferenceStatus::NotApplicable => {
            if owner_reference_scenario_kind(scenario_kind) {
                35.0
            } else {
                80.0
            }
        }
    }
}

fn evidence_quality_score_for_entry(entry: &PaperPolicyTrialScenarioResultLedgerEntry) -> f64 {
    let mut score: f64 = match entry.failure_status {
        PaperPolicyTrialFailureStatus::Clear => 85.0,
        PaperPolicyTrialFailureStatus::ClearWithWarnings => 65.0,
        PaperPolicyTrialFailureStatus::Blocked => 25.0,
    };
    if entry.triggered_stop_conditions.iter().any(|condition| {
        matches!(
            condition,
            PaperPolicyTrialStopCondition::EvidenceQualityTooLow
                | PaperPolicyTrialStopCondition::InsufficientEvidence
        )
    }) {
        score = score.min(20.0);
    }
    if entry.scenario_kind == PaperPolicyTrialScenarioKind::EvidenceGap
        && entry.failure_status == PaperPolicyTrialFailureStatus::Clear
        && entry.stop_status == PaperPolicyTrialStopStatus::Continue
    {
        score += 10.0;
    }
    clamp_score(score)
}

fn no_trade_bias_score_for_entry(entry: &PaperPolicyTrialScenarioResultLedgerEntry) -> f64 {
    let mut score = 70.0;
    if entry
        .triggered_stop_conditions
        .contains(&PaperPolicyTrialStopCondition::NoTradeBiasExceeded)
    {
        score -= 45.0;
    }
    if entry.scenario_kind == PaperPolicyTrialScenarioKind::PositiveTrend
        && matches!(
            entry.execution_status,
            PaperPolicyTrialScenarioExecutionStatus::Blocked
                | PaperPolicyTrialScenarioExecutionStatus::Stopped
        )
    {
        score -= 25.0;
    }
    if matches!(
        entry.scenario_kind,
        PaperPolicyTrialScenarioKind::HighRiskVeto
            | PaperPolicyTrialScenarioKind::NegativeTrend
            | PaperPolicyTrialScenarioKind::OwnerRiskConcern
    ) && entry.risk_first_status == PaperPolicyTrialScenarioRiskFirstStatus::Preserved
    {
        score += 10.0;
    }
    clamp_score(score)
}

fn insufficient_paper_policy_trial_scenario_outcome_score(
    scenario_kind: PaperPolicyTrialScenarioKind,
    entry_count: usize,
    reason: &str,
) -> PaperPolicyScenarioOutcomeScore {
    PaperPolicyScenarioOutcomeScore {
        score_id: format!(
            "paper-policy-scenario-outcome-{}",
            paper_policy_trial_scenario_kind_key(scenario_kind)
        ),
        scenario_kind,
        entry_count,
        success_score: 0.0,
        risk_first_score: 0.0,
        evidence_quality_score: 0.0,
        owner_explanation_score: 0.0,
        no_trade_bias_score: 0.0,
        voice_balance_score: 0.0,
        stop_cleanliness_score: 0.0,
        total_score: 0.0,
        outcome_status: PaperPolicyScenarioOutcomeStatus::InsufficientData,
        warnings: vec![reason.to_string()],
        paper_only: true,
    }
}

pub fn score_paper_policy_trial_scenario_outcome(
    entries_for_scenario: &[PaperPolicyTrialScenarioResultLedgerEntry],
) -> PaperPolicyScenarioOutcomeScore {
    let Some(first_entry) = entries_for_scenario.first() else {
        return insufficient_paper_policy_trial_scenario_outcome_score(
            PaperPolicyTrialScenarioKind::KoreaShortTerm,
            0,
            "scenario ledger entries are missing",
        );
    };
    if entries_for_scenario.len() < 2 {
        return insufficient_paper_policy_trial_scenario_outcome_score(
            first_entry.scenario_kind,
            entries_for_scenario.len(),
            "scenario needs repeated ledger history before scoring",
        );
    }
    let success_score = average_score(
        &entries_for_scenario
            .iter()
            .map(|entry| {
                (scenario_execution_score(entry.execution_status)
                    + scenario_success_score(entry.success_status))
                    / 2.0
            })
            .collect::<Vec<_>>(),
    );
    let risk_first_score = average_score(
        &entries_for_scenario
            .iter()
            .map(|entry| scenario_risk_first_score(entry.risk_first_status))
            .collect::<Vec<_>>(),
    );
    let evidence_quality_score = average_score(
        &entries_for_scenario
            .iter()
            .map(evidence_quality_score_for_entry)
            .collect::<Vec<_>>(),
    );
    let owner_explanation_score = average_score(
        &entries_for_scenario
            .iter()
            .map(|entry| {
                owner_reference_score_for_entry(entry.scenario_kind, entry.owner_reference_status)
            })
            .collect::<Vec<_>>(),
    );
    let no_trade_bias_score = average_score(
        &entries_for_scenario
            .iter()
            .map(no_trade_bias_score_for_entry)
            .collect::<Vec<_>>(),
    );
    let voice_balance_score = average_score(
        &entries_for_scenario
            .iter()
            .map(|entry| scenario_voice_balance_score(entry.voice_balance_status))
            .collect::<Vec<_>>(),
    );
    let stop_cleanliness_score = average_score(
        &entries_for_scenario
            .iter()
            .map(|entry| scenario_stop_cleanliness_score(entry.stop_status))
            .collect::<Vec<_>>(),
    );
    let total_score = round_score(
        success_score * 0.15
            + risk_first_score * 0.25
            + evidence_quality_score * 0.15
            + owner_explanation_score * 0.10
            + no_trade_bias_score * 0.10
            + voice_balance_score * 0.10
            + stop_cleanliness_score * 0.15,
    );
    let unsafe_detected = entries_for_scenario
        .iter()
        .any(paper_policy_trial_scenario_entry_is_unsafe);
    let outcome_status = if unsafe_detected {
        PaperPolicyScenarioOutcomeStatus::Unsafe
    } else if total_score >= 85.0 && risk_first_score >= 80.0 && stop_cleanliness_score >= 75.0 {
        PaperPolicyScenarioOutcomeStatus::Strong
    } else if total_score >= 70.0 && risk_first_score >= 65.0 && stop_cleanliness_score >= 60.0 {
        PaperPolicyScenarioOutcomeStatus::Acceptable
    } else {
        PaperPolicyScenarioOutcomeStatus::Weak
    };
    let mut warnings = Vec::new();
    if risk_first_score < 65.0 {
        warnings.push("risk-first preservation is weak".to_string());
    }
    if stop_cleanliness_score < 65.0 {
        warnings.push("stop-condition cleanliness is weak".to_string());
    }
    if evidence_quality_score < 65.0 {
        warnings.push("evidence quality is weak".to_string());
    }
    if owner_explanation_score < 65.0 && owner_reference_scenario_kind(first_entry.scenario_kind) {
        warnings.push("owner-reference explanation is weak".to_string());
    }
    if no_trade_bias_score < 60.0 {
        warnings.push("no-trade bias grew too high".to_string());
    }
    if voice_balance_score < 65.0 {
        warnings.push("voice balance is weak".to_string());
    }
    if unsafe_detected {
        warnings.push("unsafe scenario ledger entry was detected".to_string());
    }
    PaperPolicyScenarioOutcomeScore {
        score_id: format!(
            "paper-policy-scenario-outcome-{}",
            paper_policy_trial_scenario_kind_key(first_entry.scenario_kind)
        ),
        scenario_kind: first_entry.scenario_kind,
        entry_count: entries_for_scenario.len(),
        success_score,
        risk_first_score,
        evidence_quality_score,
        owner_explanation_score,
        no_trade_bias_score,
        voice_balance_score,
        stop_cleanliness_score,
        total_score,
        outcome_status,
        warnings,
        paper_only: true,
    }
}

pub fn build_paper_policy_trial_outcome_scorecard(
    ledger: &PaperPolicyTrialScenarioResultLedger,
    scenario_matrix: &PaperPolicyTrialScenarioMatrix,
) -> PaperPolicyTrialOutcomeScorecard {
    let ledger_quality = evaluate_paper_policy_scenario_ledger_quality(ledger, scenario_matrix);
    let scenario_scores = required_paper_policy_trial_scenario_kinds(scenario_matrix)
        .into_iter()
        .map(|scenario_kind| {
            let entries = ledger
                .entries
                .iter()
                .filter(|entry| entry.scenario_kind == scenario_kind)
                .cloned()
                .collect::<Vec<_>>();
            if entries.is_empty() {
                insufficient_paper_policy_trial_scenario_outcome_score(
                    scenario_kind,
                    0,
                    "scenario is missing from the repeated ledger",
                )
            } else {
                score_paper_policy_trial_scenario_outcome(&entries)
            }
        })
        .collect::<Vec<_>>();
    let strong_count = scenario_scores
        .iter()
        .filter(|score| score.outcome_status == PaperPolicyScenarioOutcomeStatus::Strong)
        .count();
    let acceptable_count = scenario_scores
        .iter()
        .filter(|score| score.outcome_status == PaperPolicyScenarioOutcomeStatus::Acceptable)
        .count();
    let weak_count = scenario_scores
        .iter()
        .filter(|score| score.outcome_status == PaperPolicyScenarioOutcomeStatus::Weak)
        .count();
    let unsafe_count = scenario_scores
        .iter()
        .filter(|score| score.outcome_status == PaperPolicyScenarioOutcomeStatus::Unsafe)
        .count();
    let aggregate_risk_first_score = average_score(
        &scenario_scores
            .iter()
            .map(|score| score.risk_first_score)
            .collect::<Vec<_>>(),
    );
    let aggregate_evidence_quality_score = average_score(
        &scenario_scores
            .iter()
            .map(|score| score.evidence_quality_score)
            .collect::<Vec<_>>(),
    );
    let aggregate_owner_explanation_score = average_score(
        &scenario_scores
            .iter()
            .map(|score| score.owner_explanation_score)
            .collect::<Vec<_>>(),
    );
    let aggregate_no_trade_bias_score = average_score(
        &scenario_scores
            .iter()
            .map(|score| score.no_trade_bias_score)
            .collect::<Vec<_>>(),
    );
    let aggregate_voice_balance_score = average_score(
        &scenario_scores
            .iter()
            .map(|score| score.voice_balance_score)
            .collect::<Vec<_>>(),
    );
    let aggregate_stop_cleanliness_score = average_score(
        &scenario_scores
            .iter()
            .map(|score| score.stop_cleanliness_score)
            .collect::<Vec<_>>(),
    );
    let aggregate_total_score = average_score(
        &scenario_scores
            .iter()
            .map(|score| score.total_score)
            .collect::<Vec<_>>(),
    );
    let scorecard_status = if ledger_quality.quality_status
        == PaperPolicyScenarioLedgerQualityStatus::Unsafe
        || unsafe_count > 0
    {
        PaperPolicyTrialOutcomeScorecardStatus::Unsafe
    } else if scenario_scores.is_empty()
        || ledger_quality.quality_status
            == PaperPolicyScenarioLedgerQualityStatus::InsufficientHistory
        || scenario_scores
            .iter()
            .all(|score| score.outcome_status == PaperPolicyScenarioOutcomeStatus::InsufficientData)
    {
        PaperPolicyTrialOutcomeScorecardStatus::InsufficientData
    } else if weak_count > 0
        || ledger_quality.quality_status == PaperPolicyScenarioLedgerQualityStatus::Incomplete
    {
        PaperPolicyTrialOutcomeScorecardStatus::Weak
    } else if strong_count == scenario_scores.len()
        && ledger_quality.quality_status == PaperPolicyScenarioLedgerQualityStatus::Valid
        && aggregate_total_score >= 85.0
    {
        PaperPolicyTrialOutcomeScorecardStatus::Strong
    } else if ledger_quality.quality_status == PaperPolicyScenarioLedgerQualityStatus::Valid
        && aggregate_total_score >= 80.0
    {
        PaperPolicyTrialOutcomeScorecardStatus::Acceptable
    } else {
        PaperPolicyTrialOutcomeScorecardStatus::AcceptableWithWarnings
    };
    PaperPolicyTrialOutcomeScorecard {
        scorecard_id: format!("{}-outcome-scorecard", ledger.ledger_id),
        ledger_quality,
        scenario_scores,
        scenario_count: required_paper_policy_trial_scenario_kinds(scenario_matrix).len(),
        strong_count,
        acceptable_count,
        weak_count,
        unsafe_count,
        aggregate_risk_first_score,
        aggregate_evidence_quality_score,
        aggregate_owner_explanation_score,
        aggregate_no_trade_bias_score,
        aggregate_voice_balance_score,
        aggregate_stop_cleanliness_score,
        aggregate_total_score,
        scorecard_status,
        paper_only: true,
    }
}

fn push_weak_scenario_record(
    records: &mut Vec<PaperPolicyWeakScenarioRecord>,
    scenario_kind: PaperPolicyTrialScenarioKind,
    cause: PaperPolicyWeakScenarioCause,
    severity: PaperPolicyWeakScenarioSeverity,
    reason: &str,
    recommended_action: PaperPolicyWeakScenarioRecommendedAction,
) {
    records.push(PaperPolicyWeakScenarioRecord {
        record_id: format!(
            "weak-{}-{:?}-{:?}",
            paper_policy_trial_scenario_kind_key(scenario_kind),
            cause,
            severity
        ),
        scenario_kind,
        cause,
        severity,
        reason: reason.to_string(),
        recommended_action,
        paper_only: true,
    });
}

pub fn analyze_weak_paper_policy_scenarios(
    scorecard: &PaperPolicyTrialOutcomeScorecard,
) -> PaperPolicyWeakScenarioAnalysis {
    let mut records = Vec::new();
    for scenario_score in &scorecard.scenario_scores {
        if scenario_score.outcome_status == PaperPolicyScenarioOutcomeStatus::Unsafe {
            push_weak_scenario_record(
                &mut records,
                scenario_score.scenario_kind,
                PaperPolicyWeakScenarioCause::Unknown,
                PaperPolicyWeakScenarioSeverity::High,
                "unsafe scenario outcome was detected",
                PaperPolicyWeakScenarioRecommendedAction::StopPaperTrial,
            );
            continue;
        }
        if scenario_score.outcome_status == PaperPolicyScenarioOutcomeStatus::InsufficientData
            || scenario_score.entry_count < 2
        {
            push_weak_scenario_record(
                &mut records,
                scenario_score.scenario_kind,
                PaperPolicyWeakScenarioCause::InsufficientScenarioHistory,
                PaperPolicyWeakScenarioSeverity::Medium,
                "scenario ledger history is still insufficient",
                PaperPolicyWeakScenarioRecommendedAction::AddScenarioCoverage,
            );
            continue;
        }
        if scenario_score.risk_first_score < 65.0 {
            push_weak_scenario_record(
                &mut records,
                scenario_score.scenario_kind,
                PaperPolicyWeakScenarioCause::RiskFirstWeakness,
                PaperPolicyWeakScenarioSeverity::High,
                "risk-first preservation score is too low",
                PaperPolicyWeakScenarioRecommendedAction::TunePolicy,
            );
        }
        if scenario_score.evidence_quality_score < 65.0 {
            push_weak_scenario_record(
                &mut records,
                scenario_score.scenario_kind,
                PaperPolicyWeakScenarioCause::EvidenceQualityWeakness,
                PaperPolicyWeakScenarioSeverity::Medium,
                "evidence quality score is too low",
                PaperPolicyWeakScenarioRecommendedAction::CollectMoreEvidence,
            );
        }
        if scenario_score.owner_explanation_score < 65.0 {
            push_weak_scenario_record(
                &mut records,
                scenario_score.scenario_kind,
                PaperPolicyWeakScenarioCause::OwnerExplanationWeakness,
                PaperPolicyWeakScenarioSeverity::High,
                "owner-reference explanation score is too low",
                PaperPolicyWeakScenarioRecommendedAction::ImproveOwnerExplanation,
            );
        }
        if scenario_score.no_trade_bias_score < 60.0 {
            push_weak_scenario_record(
                &mut records,
                scenario_score.scenario_kind,
                PaperPolicyWeakScenarioCause::NoTradeBiasTooHigh,
                PaperPolicyWeakScenarioSeverity::Medium,
                "no-trade bias is too dominant",
                PaperPolicyWeakScenarioRecommendedAction::TunePolicy,
            );
        }
        if scenario_score.voice_balance_score < 65.0 {
            push_weak_scenario_record(
                &mut records,
                scenario_score.scenario_kind,
                PaperPolicyWeakScenarioCause::VoiceBalanceWeakness,
                PaperPolicyWeakScenarioSeverity::Medium,
                "voice balance score is too low",
                PaperPolicyWeakScenarioRecommendedAction::TunePolicy,
            );
        }
        if scenario_score.stop_cleanliness_score < 65.0 {
            push_weak_scenario_record(
                &mut records,
                scenario_score.scenario_kind,
                PaperPolicyWeakScenarioCause::StopConditionWarning,
                if scenario_score.stop_cleanliness_score < 40.0 {
                    PaperPolicyWeakScenarioSeverity::High
                } else {
                    PaperPolicyWeakScenarioSeverity::Medium
                },
                "stop-condition cleanliness is weak",
                PaperPolicyWeakScenarioRecommendedAction::TunePolicy,
            );
        }
    }
    let high_severity_count = records
        .iter()
        .filter(|record| record.severity == PaperPolicyWeakScenarioSeverity::High)
        .count();
    let mut cause_counts = BTreeMap::<String, (PaperPolicyWeakScenarioCause, usize)>::new();
    let mut action_seen = BTreeSet::new();
    let mut recommended_actions = Vec::new();
    for record in &records {
        let key = format!("{:?}", record.cause);
        cause_counts
            .entry(key)
            .and_modify(|(_, count)| *count += 1)
            .or_insert((record.cause, 1));
        if action_seen.insert(format!("{:?}", record.recommended_action)) {
            recommended_actions.push(record.recommended_action);
        }
    }
    let max_cause_count = cause_counts
        .values()
        .map(|(_, count)| *count)
        .max()
        .unwrap_or(0);
    let dominant_causes = cause_counts
        .into_values()
        .filter(|(_, count)| *count == max_cause_count && *count > 0)
        .map(|(cause, _)| cause)
        .collect::<Vec<_>>();
    let analysis_status = if records.iter().any(|record| {
        record.recommended_action == PaperPolicyWeakScenarioRecommendedAction::StopPaperTrial
    }) {
        PaperPolicyWeakScenarioAnalysisStatus::Unsafe
    } else if records.is_empty() {
        PaperPolicyWeakScenarioAnalysisStatus::NoMajorWeakness
    } else if records.iter().all(|record| {
        matches!(
            record.recommended_action,
            PaperPolicyWeakScenarioRecommendedAction::CollectMoreEvidence
                | PaperPolicyWeakScenarioRecommendedAction::AddScenarioCoverage
                | PaperPolicyWeakScenarioRecommendedAction::ImproveOwnerExplanation
        )
    }) {
        PaperPolicyWeakScenarioAnalysisStatus::NeedsMoreEvidence
    } else {
        PaperPolicyWeakScenarioAnalysisStatus::HasWeaknesses
    };
    PaperPolicyWeakScenarioAnalysis {
        analysis_id: format!("{}-weak-scenario-analysis", scorecard.scorecard_id),
        weak_record_count: records.len(),
        high_severity_count,
        dominant_causes,
        recommended_actions,
        analysis_status,
        records,
        paper_only: true,
    }
}

pub fn recommend_paper_policy_trial_continuation(
    scorecard: &PaperPolicyTrialOutcomeScorecard,
    weak_analysis: &PaperPolicyWeakScenarioAnalysis,
    repeated_execution_gate: &PaperPolicyRepeatedExecutionGate,
) -> PaperPolicyTrialContinuationRecommendation {
    let (recommendation_kind, next_recommended_action, reason) = if repeated_execution_gate
        .safety_status
        == PaperGovernanceTrialSafetyGuardStatus::Violated
        || repeated_execution_gate.gate_status
            == PaperPolicyRepeatedExecutionGateStatus::BlockedBySafety
    {
        (
            PaperPolicyTrialContinuationRecommendationKind::BlockedBySafety,
            PaperPolicyTrialContinuationNextAction::StopTrialAndReview,
            "safety remains blocked for paper-trial continuation".to_string(),
        )
    } else if matches!(
        scorecard.scorecard_status,
        PaperPolicyTrialOutcomeScorecardStatus::Unsafe
    ) || weak_analysis.analysis_status == PaperPolicyWeakScenarioAnalysisStatus::Unsafe
    {
        (
            PaperPolicyTrialContinuationRecommendationKind::StopPaperTrial,
            PaperPolicyTrialContinuationNextAction::StopTrialAndReview,
            "unsafe outcome scorecard requires stopping the paper trial".to_string(),
        )
    } else if matches!(
        scorecard.ledger_quality.quality_status,
        PaperPolicyScenarioLedgerQualityStatus::InsufficientHistory
    ) || weak_analysis.analysis_status
        == PaperPolicyWeakScenarioAnalysisStatus::NeedsMoreEvidence
    {
        (
            PaperPolicyTrialContinuationRecommendationKind::CollectMoreEvidence,
            PaperPolicyTrialContinuationNextAction::CollectScenarioEvidence,
            "more repeated evidence is needed before tuning".to_string(),
        )
    } else if matches!(
        scorecard.scorecard_status,
        PaperPolicyTrialOutcomeScorecardStatus::Strong
            | PaperPolicyTrialOutcomeScorecardStatus::Acceptable
    ) && weak_analysis.analysis_status
        == PaperPolicyWeakScenarioAnalysisStatus::NoMajorWeakness
        && repeated_execution_gate.continue_repeated_paper_execution
    {
        (
            PaperPolicyTrialContinuationRecommendationKind::ContinueRepeatedPaperExecution,
            PaperPolicyTrialContinuationNextAction::ContinueRepeatedScenarioExecution,
            "repeated paper execution remains safe and outcome quality is acceptable".to_string(),
        )
    } else if scorecard.scorecard_status
        == PaperPolicyTrialOutcomeScorecardStatus::AcceptableWithWarnings
        || matches!(
            repeated_execution_gate.gate_status,
            PaperPolicyRepeatedExecutionGateStatus::ContinueWithWarnings
                | PaperPolicyRepeatedExecutionGateStatus::NeedsMoreHistory
        )
    {
        (
            PaperPolicyTrialContinuationRecommendationKind::ContinueWithWarnings,
            PaperPolicyTrialContinuationNextAction::ContinueRepeatedScenarioExecution,
            "paper-only continuation is acceptable but warnings remain".to_string(),
        )
    } else {
        (
            PaperPolicyTrialContinuationRecommendationKind::TunePolicyBeforeMoreTrials,
            if weak_analysis.records.iter().any(|record| {
                record.cause == PaperPolicyWeakScenarioCause::OwnerExplanationWeakness
            }) {
                PaperPolicyTrialContinuationNextAction::ImproveOwnerExplanation
            } else {
                PaperPolicyTrialContinuationNextAction::FeedBackToPolicyTuning
            },
            "weak scenarios should be tuned before more paper trials".to_string(),
        )
    };
    PaperPolicyTrialContinuationRecommendation {
        recommendation_id: format!("{}-continuation-recommendation", scorecard.scorecard_id),
        recommendation_kind,
        scorecard_status: scorecard.scorecard_status,
        weak_scenario_status: weak_analysis.analysis_status,
        ledger_quality_status: scorecard.ledger_quality.quality_status,
        risk_first_score: scorecard.aggregate_risk_first_score,
        voice_balance_score: scorecard.aggregate_voice_balance_score,
        no_trade_bias_score: scorecard.aggregate_no_trade_bias_score,
        stop_cleanliness_score: scorecard.aggregate_stop_cleanliness_score,
        reason,
        next_recommended_action,
        policy_apply_allowed: false,
        paper_only: true,
    }
}

pub fn build_paper_policy_outcome_evidence_task_queue(
    weak_analysis: &PaperPolicyWeakScenarioAnalysis,
    continuation_recommendation: &PaperPolicyTrialContinuationRecommendation,
) -> PaperPolicyOutcomeEvidenceTaskQueue {
    let mut tasks = Vec::new();
    let mut task_keys = BTreeSet::new();
    for record in &weak_analysis.records {
        let (task_kind, priority) = match record.cause {
            PaperPolicyWeakScenarioCause::RiskFirstWeakness => (
                PaperPolicyOutcomeEvidenceTaskKind::CollectRiskScenarioEvidence,
                PaperPolicyOutcomeEvidenceTaskPriority::High,
            ),
            PaperPolicyWeakScenarioCause::EvidenceQualityWeakness => (
                PaperPolicyOutcomeEvidenceTaskKind::CollectEvidenceGapScenarioEvidence,
                PaperPolicyOutcomeEvidenceTaskPriority::Normal,
            ),
            PaperPolicyWeakScenarioCause::OwnerExplanationWeakness => (
                PaperPolicyOutcomeEvidenceTaskKind::CollectOwnerExplanationEvidence,
                PaperPolicyOutcomeEvidenceTaskPriority::High,
            ),
            PaperPolicyWeakScenarioCause::NoTradeBiasTooHigh => (
                PaperPolicyOutcomeEvidenceTaskKind::CollectNoTradeBiasEvidence,
                PaperPolicyOutcomeEvidenceTaskPriority::Normal,
            ),
            PaperPolicyWeakScenarioCause::VoiceBalanceWeakness => (
                PaperPolicyOutcomeEvidenceTaskKind::CollectVoiceBalanceEvidence,
                PaperPolicyOutcomeEvidenceTaskPriority::Normal,
            ),
            PaperPolicyWeakScenarioCause::InsufficientScenarioHistory => (
                PaperPolicyOutcomeEvidenceTaskKind::AddMoreRepeatedRuns,
                PaperPolicyOutcomeEvidenceTaskPriority::Normal,
            ),
            PaperPolicyWeakScenarioCause::StopConditionWarning
            | PaperPolicyWeakScenarioCause::Unknown => (
                PaperPolicyOutcomeEvidenceTaskKind::ManualReview,
                if record.severity == PaperPolicyWeakScenarioSeverity::High {
                    PaperPolicyOutcomeEvidenceTaskPriority::High
                } else {
                    PaperPolicyOutcomeEvidenceTaskPriority::Normal
                },
            ),
        };
        let task_key = format!(
            "{:?}-{}",
            task_kind,
            paper_policy_trial_scenario_kind_key(record.scenario_kind)
        );
        if task_keys.insert(task_key.clone()) {
            tasks.push(PaperPolicyOutcomeEvidenceTask {
                task_id: format!("paper-policy-outcome-task-{}", task_key),
                scenario_kind: Some(record.scenario_kind),
                task_kind,
                priority,
                reason: record.reason.clone(),
                paper_only: true,
            });
        }
    }
    if matches!(
        continuation_recommendation.recommendation_kind,
        PaperPolicyTrialContinuationRecommendationKind::CollectMoreEvidence
            | PaperPolicyTrialContinuationRecommendationKind::ContinueWithWarnings
    ) && task_keys.insert("add-more-repeated-runs".to_string())
    {
        tasks.push(PaperPolicyOutcomeEvidenceTask {
            task_id: "paper-policy-outcome-task-add-more-runs".to_string(),
            scenario_kind: None,
            task_kind: PaperPolicyOutcomeEvidenceTaskKind::AddMoreRepeatedRuns,
            priority: PaperPolicyOutcomeEvidenceTaskPriority::Normal,
            reason: "more repeated paper runs are needed before the next policy decision"
                .to_string(),
            paper_only: true,
        });
    }
    let high_priority_count = tasks
        .iter()
        .filter(|task| task.priority == PaperPolicyOutcomeEvidenceTaskPriority::High)
        .count();
    PaperPolicyOutcomeEvidenceTaskQueue {
        queue_id: "paper-policy-outcome-evidence-task-queue".to_string(),
        task_count: tasks.len(),
        high_priority_count,
        tasks,
        paper_only: true,
    }
}

fn member_score_changed(before: &[MemberStateSnapshot], after: &[MemberStateSnapshot]) -> bool {
    let before_scores = before
        .iter()
        .map(|state| (state.member_id.clone(), state.score))
        .collect::<BTreeMap<_, _>>();
    let after_scores = after
        .iter()
        .map(|state| (state.member_id.clone(), state.score))
        .collect::<BTreeMap<_, _>>();
    before_scores != after_scores
}

fn member_voice_changed(before: &[MemberStateSnapshot], after: &[MemberStateSnapshot]) -> bool {
    let before_voices = before
        .iter()
        .map(|state| (state.member_id.clone(), state.voice_weight))
        .collect::<BTreeMap<_, _>>();
    let after_voices = after
        .iter()
        .map(|state| (state.member_id.clone(), state.voice_weight))
        .collect::<BTreeMap<_, _>>();
    before_voices != after_voices
}

fn risk_governor_decision_status_changed(
    before: &[ChairmanDecision],
    after: &[ChairmanDecision],
) -> bool {
    let before_statuses = before
        .iter()
        .map(|decision| (decision.decision_id.clone(), decision.risk_governor_status))
        .collect::<BTreeMap<_, _>>();
    let after_statuses = after
        .iter()
        .map(|decision| (decision.decision_id.clone(), decision.risk_governor_status))
        .collect::<BTreeMap<_, _>>();
    before_statuses != after_statuses
}

fn build_paper_policy_outcome_scorecard_safety_guard_from_parts(
    scorecard: &PaperPolicyTrialOutcomeScorecard,
    recommendation: &PaperPolicyTrialContinuationRecommendation,
    batch_before: Option<&BatchCommitteeCycleWithStateResult>,
    batch_after: Option<&BatchCommitteeCycleWithStateResult>,
) -> PaperPolicyOutcomeScorecardSafetyGuard {
    let after = batch_after.or(batch_before);
    let actual_policy_apply_detected = recommendation.policy_apply_allowed;
    let actual_score_mutation_detected = if let (Some(before), Some(after)) = (batch_before, after)
    {
        member_score_changed(
            &before.state_update.updated_member_states,
            &after.state_update.updated_member_states,
        )
    } else {
        false
    };
    let actual_voice_mutation_detected = if let (Some(before), Some(after)) = (batch_before, after)
    {
        member_voice_changed(
            &before.state_update.updated_member_states,
            &after.state_update.updated_member_states,
        )
    } else {
        false
    };
    let committee_decision_mutation_detected =
        if let (Some(before), Some(after)) = (batch_before, after) {
            before.batch_result.committee_sessions != after.batch_result.committee_sessions
        } else {
            false
        };
    let chairman_decision_mutation_detected =
        if let (Some(before), Some(after)) = (batch_before, after) {
            before.batch_result.chairman_decisions != after.batch_result.chairman_decisions
        } else {
            false
        };
    let risk_governor_override_detected = if let (Some(before), Some(after)) = (batch_before, after)
    {
        risk_governor_decision_status_changed(
            &before.batch_result.chairman_decisions,
            &after.batch_result.chairman_decisions,
        )
    } else {
        false
    };
    let trade_signal_detected = if let (Some(before), Some(after)) = (batch_before, after) {
        value_has_new_debug_marker(
            &before.batch_result.committee_sessions,
            &after.batch_result.committee_sessions,
            &["trade-signal".to_string()],
        )
    } else {
        false
    };
    let order_detected = if let (Some(before), Some(after)) = (batch_before, after) {
        value_has_new_debug_marker(
            &before.batch_result.event_queue,
            &after.batch_result.event_queue,
            &[
                "order".to_string(),
                "order_id".to_string(),
                "submit order".to_string(),
                "execute order".to_string(),
                "order-side-effect".to_string(),
            ],
        )
    } else {
        false
    };
    let broker_order_account_detected = if let (Some(before), Some(after)) = (batch_before, after) {
        let markers = [
            "broker".to_string(),
            "account".to_string(),
            "account_id".to_string(),
            "broker-account".to_string(),
        ];
        value_has_new_debug_marker(
            &before.batch_result.event_queue,
            &after.batch_result.event_queue,
            &markers,
        ) || value_has_new_debug_marker(
            &before.batch_result.committee_sessions,
            &after.batch_result.committee_sessions,
            &markers,
        ) || value_has_new_debug_marker(
            &before.batch_result.chairman_decisions,
            &after.batch_result.chairman_decisions,
            &markers,
        )
    } else {
        false
    };
    let scorecard_used_as_live_decision_detected = actual_policy_apply_detected
        || committee_decision_mutation_detected
        || chairman_decision_mutation_detected
        || risk_governor_override_detected
        || trade_signal_detected
        || order_detected
        || broker_order_account_detected;
    let policy_apply_allowed_true_detected = recommendation.policy_apply_allowed;
    let mut violations = Vec::new();
    if actual_policy_apply_detected {
        violations.push("outcome recommendation allowed actual policy apply".to_string());
    }
    if actual_score_mutation_detected {
        violations.push("outcome scorecard mutated actual member scores".to_string());
    }
    if actual_voice_mutation_detected {
        violations.push("outcome scorecard mutated actual member voices".to_string());
    }
    if committee_decision_mutation_detected {
        violations.push("outcome scorecard changed committee decisions".to_string());
    }
    if chairman_decision_mutation_detected {
        violations.push("outcome scorecard changed chairman decisions".to_string());
    }
    if risk_governor_override_detected {
        violations.push("outcome scorecard overrode the Risk Governor".to_string());
    }
    if trade_signal_detected || order_detected || broker_order_account_detected {
        violations.push("outcome scorecard touched trade/order/account paths".to_string());
    }
    if scorecard_used_as_live_decision_detected {
        violations.push("outcome scorecard was used as a live decision".to_string());
    }
    if policy_apply_allowed_true_detected {
        violations.push("policy_apply_allowed became true".to_string());
    }
    if !scorecard.paper_only {
        violations.push("outcome scorecard lost paper_only protection".to_string());
    }
    PaperPolicyOutcomeScorecardSafetyGuard {
        actual_policy_apply_detected,
        actual_score_mutation_detected,
        actual_voice_mutation_detected,
        committee_decision_mutation_detected,
        chairman_decision_mutation_detected,
        risk_governor_override_detected,
        trade_signal_detected,
        order_detected,
        broker_order_account_detected,
        scorecard_used_as_live_decision_detected,
        policy_apply_allowed_true_detected,
        guard_status: if violations.is_empty() {
            PaperGovernanceTrialSafetyGuardStatus::Preserved
        } else {
            PaperGovernanceTrialSafetyGuardStatus::Violated
        },
        violations,
        paper_only: true,
    }
}

pub fn evaluate_paper_policy_outcome_scorecard_safety(
    scorecard: &PaperPolicyTrialOutcomeScorecard,
    recommendation: &PaperPolicyTrialContinuationRecommendation,
    batch_before: &BatchCommitteeCycleWithStateResult,
    batch_after: Option<&BatchCommitteeCycleWithStateResult>,
) -> PaperPolicyOutcomeScorecardSafetyGuard {
    build_paper_policy_outcome_scorecard_safety_guard_from_parts(
        scorecard,
        recommendation,
        Some(batch_before),
        batch_after,
    )
}

fn save_paper_policy_trial_outcome_scorecard_to_local_json(
    path: &Path,
    scorecard: &PaperPolicyTrialOutcomeScorecard,
) -> Result<(), String> {
    validate_local_json_path(path, "paper policy trial outcome scorecard path")?;
    if !scorecard.paper_only {
        return Err("paper policy trial outcome scorecard must stay paper_only".to_string());
    }
    write_safe_json(path, scorecard)
}

fn load_paper_policy_trial_outcome_scorecard_from_local_json(
    path: &Path,
) -> Result<PaperPolicyTrialOutcomeScorecard, String> {
    validate_local_json_path(path, "paper policy trial outcome scorecard path")?;
    let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
    let scorecard: PaperPolicyTrialOutcomeScorecard =
        serde_json::from_str(&text).map_err(|err| err.to_string())?;
    if !scorecard.paper_only || !scorecard.ledger_quality.paper_only {
        return Err("paper policy trial outcome scorecard must stay paper_only".to_string());
    }
    Ok(scorecard)
}

pub fn prove_paper_policy_trial_outcome_scorecard_write(
    run_result: &PaperPolicyTrialOutcomeScorecardRunResult,
    output_path: &Path,
) -> Result<PaperPolicyTrialOutcomeScorecardWriteProof, String> {
    validate_local_json_path(output_path, "paper policy trial outcome scorecard path")?;
    let scorecard_exists_after_write = output_path.exists();
    let unsafe_record_count = if scorecard_exists_after_write {
        load_paper_policy_trial_outcome_scorecard_from_local_json(output_path)?
            .scenario_scores
            .iter()
            .filter(|score| score.outcome_status == PaperPolicyScenarioOutcomeStatus::Unsafe)
            .count()
    } else {
        0
    };
    let proof_status = if run_result.wrote_scorecard && !scorecard_exists_after_write {
        PaperGovernanceTrialLedgerWriteProofStatus::Failed
    } else if run_result.continuation_recommendation.policy_apply_allowed {
        PaperGovernanceTrialLedgerWriteProofStatus::Failed
    } else if unsafe_record_count > 0 {
        PaperGovernanceTrialLedgerWriteProofStatus::ProvenWithWarnings
    } else {
        PaperGovernanceTrialLedgerWriteProofStatus::Proven
    };
    Ok(PaperPolicyTrialOutcomeScorecardWriteProof {
        proof_id: format!("{}-outcome-scorecard-write-proof", run_result.run_id),
        expected_output_path: output_path.display().to_string(),
        wrote_scorecard: run_result.wrote_scorecard,
        scorecard_exists_after_write,
        policy_apply_allowed: run_result.continuation_recommendation.policy_apply_allowed,
        unsafe_record_count,
        proof_status,
        paper_only: true,
    })
}

pub fn build_owner_paper_policy_trial_outcome_summary(
    run_result: &PaperPolicyTrialOutcomeScorecardRunResult,
) -> OwnerPaperPolicyTrialOutcomeSummary {
    OwnerPaperPolicyTrialOutcomeSummary {
        summary_id: format!("{}-owner-paper-policy-trial-outcome-summary", run_result.run_id),
        ledger_entry_count: run_result.ledger_quality.ledger_entry_count,
        scorecard_status: run_result.scorecard.scorecard_status,
        continuation_recommendation: run_result
            .continuation_recommendation
            .recommendation_kind,
        weak_scenario_count: run_result.weak_scenario_analysis.weak_record_count,
        evidence_task_count: run_result.evidence_task_queue.task_count,
        message: "Paper trial outcomes were scored only for evaluation. No governance policy was applied. Actual score, voice, decisions, Risk Governor, and trading remain unchanged. The recommendation only controls whether to continue paper trials or tune policy.".to_string(),
        paper_trial_only: true,
        policy_apply_allowed: false,
        no_actual_policy_apply: true,
        no_score_mutation: true,
        no_voice_mutation: true,
        no_committee_decision_change: true,
        no_risk_override: true,
        not_trade_signal: true,
        paper_only: true,
    }
}

fn paper_policy_trial_outcome_scorecard_run_status(
    run_result: &PaperPolicyTrialOutcomeScorecardRunResult,
) -> PaperGovernanceTrialRunStatus {
    if run_result.safety_guard.guard_status == PaperGovernanceTrialSafetyGuardStatus::Violated
        || run_result.ledger_quality.quality_status
            == PaperPolicyScenarioLedgerQualityStatus::Unsafe
        || run_result.scorecard.scorecard_status == PaperPolicyTrialOutcomeScorecardStatus::Unsafe
        || run_result.write_proof.as_ref().is_some_and(|proof| {
            proof.proof_status == PaperGovernanceTrialLedgerWriteProofStatus::Failed
        })
    {
        PaperGovernanceTrialRunStatus::Failed
    } else if run_result.scorecard.scorecard_status
        != PaperPolicyTrialOutcomeScorecardStatus::Strong
        || run_result.weak_scenario_analysis.analysis_status
            != PaperPolicyWeakScenarioAnalysisStatus::NoMajorWeakness
        || run_result.continuation_recommendation.recommendation_kind
            != PaperPolicyTrialContinuationRecommendationKind::ContinueRepeatedPaperExecution
        || run_result.ledger_quality.quality_status != PaperPolicyScenarioLedgerQualityStatus::Valid
        || run_result.write_proof.as_ref().is_some_and(|proof| {
            proof.proof_status == PaperGovernanceTrialLedgerWriteProofStatus::ProvenWithWarnings
        })
    {
        PaperGovernanceTrialRunStatus::PassedWithWarnings
    } else {
        PaperGovernanceTrialRunStatus::Passed
    }
}

fn infer_paper_policy_trial_coverage_stability_from_ledger(
    ledger: &PaperPolicyTrialScenarioResultLedger,
    scenario_matrix: &PaperPolicyTrialScenarioMatrix,
) -> PaperPolicyTrialCoverageStability {
    let required_kinds = required_paper_policy_trial_scenario_kinds(scenario_matrix);
    if required_kinds.is_empty() {
        return PaperPolicyTrialCoverageStability {
            stability_id: "paper-policy-ledger-inferred-coverage-stability".to_string(),
            repeat_count: 0,
            coverage_complete_count: 0,
            coverage_warning_count: 0,
            coverage_failure_count: 0,
            missing_coverage_recurrence: Vec::new(),
            coverage_stability_status: PaperPolicyTrialCoverageStabilityStatus::InsufficientHistory,
            paper_only: true,
        };
    }
    let counts = required_kinds
        .iter()
        .map(|kind| {
            (
                *kind,
                ledger
                    .entries
                    .iter()
                    .filter(|entry| entry.scenario_kind == *kind)
                    .count(),
            )
        })
        .collect::<Vec<_>>();
    let repeat_count = counts.iter().map(|(_, count)| *count).max().unwrap_or(0);
    let coverage_complete_count = counts.iter().map(|(_, count)| *count).min().unwrap_or(0);
    let missing_coverage_recurrence = counts
        .iter()
        .filter(|(_, count)| *count == 0)
        .map(|(kind, _)| paper_policy_trial_scenario_kind_key(*kind))
        .collect::<Vec<_>>();
    let coverage_warning_count = repeat_count.saturating_sub(coverage_complete_count);
    let coverage_failure_count = if missing_coverage_recurrence.is_empty() {
        0
    } else {
        1
    };
    let coverage_stability_status = if repeat_count < 2 {
        PaperPolicyTrialCoverageStabilityStatus::InsufficientHistory
    } else if coverage_failure_count > 0 {
        PaperPolicyTrialCoverageStabilityStatus::UnstableCoverage
    } else if coverage_warning_count > 0 {
        PaperPolicyTrialCoverageStabilityStatus::StableWithWarnings
    } else {
        PaperPolicyTrialCoverageStabilityStatus::StableComplete
    };
    PaperPolicyTrialCoverageStability {
        stability_id: format!("{}-inferred-coverage-stability", ledger.ledger_id),
        repeat_count,
        coverage_complete_count,
        coverage_warning_count,
        coverage_failure_count,
        missing_coverage_recurrence,
        coverage_stability_status,
        paper_only: true,
    }
}

fn infer_repeated_execution_gate_for_outcome_scorecard(
    ledger: &PaperPolicyTrialScenarioResultLedger,
    scenario_matrix: &PaperPolicyTrialScenarioMatrix,
) -> PaperPolicyRepeatedExecutionGate {
    let scenario_trend_summary = compute_paper_policy_trial_scenario_trend_summary(ledger);
    let stop_recurrence_summary = summarize_paper_policy_trial_stop_recurrence(ledger);
    let risk_first_scenario_trend = compute_paper_policy_trial_risk_first_scenario_trend(ledger);
    let coverage_stability =
        infer_paper_policy_trial_coverage_stability_from_ledger(ledger, scenario_matrix);
    let safety_guard = PaperPolicyRepeatedScenarioExecutionSafetyGuard {
        actual_policy_apply_detected: false,
        actual_score_mutation_detected: false,
        actual_voice_mutation_detected: false,
        committee_decision_mutation_detected: false,
        chairman_decision_mutation_detected: false,
        risk_governor_override_detected: false,
        trade_signal_detected: false,
        order_detected: false,
        broker_order_account_detected: false,
        scenario_ledger_write_when_dry_run_detected: false,
        repeated_execution_used_as_live_decision_detected: false,
        unsafe_gate_open_detected: false,
        guard_status: PaperGovernanceTrialSafetyGuardStatus::Preserved,
        violations: Vec::new(),
        paper_only: true,
    };
    evaluate_paper_policy_repeated_execution_gate(
        &scenario_trend_summary,
        &stop_recurrence_summary,
        &risk_first_scenario_trend,
        &coverage_stability,
        &safety_guard,
    )
}

pub fn run_paper_policy_trial_outcome_scorecard(
    scenario_ledger: &PaperPolicyTrialScenarioResultLedger,
    scenario_matrix: &PaperPolicyTrialScenarioMatrix,
    repeated_execution_gate: &PaperPolicyRepeatedExecutionGate,
    config: &PaperPolicyTrialOutcomeScorecardRunConfig,
) -> Result<PaperPolicyTrialOutcomeScorecardRunResult, String> {
    let scorecard = build_paper_policy_trial_outcome_scorecard(scenario_ledger, scenario_matrix);
    let weak_scenario_analysis = analyze_weak_paper_policy_scenarios(&scorecard);
    let continuation_recommendation = recommend_paper_policy_trial_continuation(
        &scorecard,
        &weak_scenario_analysis,
        repeated_execution_gate,
    );
    let evidence_task_queue = build_paper_policy_outcome_evidence_task_queue(
        &weak_scenario_analysis,
        &continuation_recommendation,
    );
    let mut wrote_scorecard = false;
    if !config.dry_run && config.write_scorecard {
        let output_path = config
            .scorecard_output_path
            .as_ref()
            .filter(|path| !path.trim().is_empty())
            .ok_or_else(|| {
                "paper policy trial outcome scorecard output path is required when writing scorecard"
                    .to_string()
            })?;
        save_paper_policy_trial_outcome_scorecard_to_local_json(
            Path::new(output_path),
            &scorecard,
        )?;
        wrote_scorecard = true;
    }
    let safety_guard = build_paper_policy_outcome_scorecard_safety_guard_from_parts(
        &scorecard,
        &continuation_recommendation,
        None,
        None,
    );
    let mut result = PaperPolicyTrialOutcomeScorecardRunResult {
        run_id: config.run_id.clone(),
        ledger_quality: scorecard.ledger_quality.clone(),
        scorecard,
        weak_scenario_analysis,
        continuation_recommendation,
        evidence_task_queue,
        safety_guard,
        write_proof: None,
        owner_summary: None,
        run_status: PaperGovernanceTrialRunStatus::Passed,
        dry_run: config.dry_run,
        wrote_scorecard,
        paper_only: true,
    };
    if result.wrote_scorecard {
        if let Some(output_path) = config
            .scorecard_output_path
            .as_ref()
            .filter(|path| !path.trim().is_empty())
        {
            result.write_proof = Some(prove_paper_policy_trial_outcome_scorecard_write(
                &result,
                Path::new(output_path),
            )?);
        }
    }
    if config.emit_owner_summary {
        result.owner_summary = Some(build_owner_paper_policy_trial_outcome_summary(&result));
    }
    result.run_status = paper_policy_trial_outcome_scorecard_run_status(&result);
    Ok(result)
}

fn maybe_run_paper_policy_trial_outcome_scorecard_for_stateful_result(
    run_id: String,
    enabled: bool,
    dry_run: bool,
    write_scorecard: bool,
    scenario_ledger_input_path: Option<&String>,
    scorecard_output_path: Option<&String>,
    emit_owner_summary: bool,
    stateful_result: &mut BatchCommitteeCycleWithStateResult,
) -> Result<Option<PaperPolicyTrialOutcomeScorecardRunResult>, String> {
    if !paper_policy_trial_outcome_scorecard_requested_from_flags(
        enabled,
        dry_run,
        write_scorecard,
        scenario_ledger_input_path,
        scorecard_output_path,
        emit_owner_summary,
    ) {
        return Ok(None);
    }
    let scenario_matrix = stateful_result
        .batch_result
        .paper_policy_trial_scenario_matrix
        .clone()
        .unwrap_or_else(build_default_paper_policy_trial_scenario_matrix);
    let ledger_from_input = scenario_ledger_input_path
        .filter(|path| !path.trim().is_empty())
        .map(|path| load_paper_policy_trial_scenario_result_ledger_from_local_json(Path::new(path)))
        .transpose()?;
    let scenario_ledger = if let Some(ledger) = ledger_from_input {
        ledger
    } else if let Some(repeated_result) = stateful_result
        .batch_result
        .paper_policy_trial_repeated_scenario_execution_result
        .as_ref()
    {
        repeated_result.final_scenario_ledger.clone()
    } else {
        stateful_result
            .batch_result
            .paper_policy_trial_scenario_result_ledger
            .clone()
            .ok_or_else(|| {
                "paper policy trial outcome scorecard requires repeated scenario ledger".to_string()
            })?
    };
    let repeated_execution_gate = if scenario_ledger_input_path
        .map(|path| !path.trim().is_empty())
        .unwrap_or(false)
    {
        infer_repeated_execution_gate_for_outcome_scorecard(&scenario_ledger, &scenario_matrix)
    } else {
        stateful_result
            .batch_result
            .paper_policy_repeated_execution_gate
            .clone()
            .unwrap_or_else(|| {
                infer_repeated_execution_gate_for_outcome_scorecard(
                    &scenario_ledger,
                    &scenario_matrix,
                )
            })
    };
    let before_snapshot = stateful_result.clone();
    let mut result = run_paper_policy_trial_outcome_scorecard(
        &scenario_ledger,
        &scenario_matrix,
        &repeated_execution_gate,
        &PaperPolicyTrialOutcomeScorecardRunConfig {
            run_id,
            enabled,
            scenario_ledger_input_path: scenario_ledger_input_path.cloned(),
            scorecard_output_path: scorecard_output_path.cloned(),
            dry_run,
            write_scorecard,
            emit_owner_summary,
            paper_only: true,
        },
    )?;
    stateful_result
        .batch_result
        .paper_policy_scenario_ledger_quality_evaluation = Some(result.ledger_quality.clone());
    stateful_result
        .batch_result
        .paper_policy_trial_outcome_scorecard = Some(result.scorecard.clone());
    stateful_result
        .batch_result
        .paper_policy_weak_scenario_analysis = Some(result.weak_scenario_analysis.clone());
    stateful_result
        .batch_result
        .paper_policy_trial_continuation_recommendation =
        Some(result.continuation_recommendation.clone());
    stateful_result
        .batch_result
        .paper_policy_outcome_evidence_task_queue = Some(result.evidence_task_queue.clone());
    stateful_result
        .batch_result
        .paper_policy_outcome_scorecard_safety_guard = Some(result.safety_guard.clone());
    stateful_result
        .batch_result
        .paper_policy_trial_outcome_scorecard_write_proof = result.write_proof.clone();
    stateful_result
        .batch_result
        .owner_paper_policy_trial_outcome_summary = result.owner_summary.clone();
    stateful_result
        .batch_result
        .paper_policy_trial_outcome_scorecard_run_result = Some(result.clone());
    let after_snapshot = stateful_result.clone();
    result.safety_guard = evaluate_paper_policy_outcome_scorecard_safety(
        &result.scorecard,
        &result.continuation_recommendation,
        &before_snapshot,
        Some(&after_snapshot),
    );
    result.run_status = paper_policy_trial_outcome_scorecard_run_status(&result);
    if emit_owner_summary {
        result.owner_summary = Some(build_owner_paper_policy_trial_outcome_summary(&result));
    }
    stateful_result
        .batch_result
        .paper_policy_outcome_scorecard_safety_guard = Some(result.safety_guard.clone());
    stateful_result
        .batch_result
        .owner_paper_policy_trial_outcome_summary = result.owner_summary.clone();
    stateful_result
        .batch_result
        .paper_policy_trial_outcome_scorecard_run_result = Some(result.clone());
    Ok(Some(result))
}

pub fn paper_policy_outcome_feedback_bridge_requested_from_flags(
    enabled: bool,
    dry_run: bool,
    append_continuation_ledger: bool,
    continuation_ledger_input_path: Option<&String>,
    _continuation_ledger_output_path: Option<&String>,
    _feedback_output_path: Option<&String>,
    emit_owner_summary: bool,
) -> bool {
    enabled
        || !dry_run
        || append_continuation_ledger
        || continuation_ledger_input_path
            .map(|path| !path.trim().is_empty())
            .unwrap_or(false)
        || (enabled && emit_owner_summary)
}

fn governance_feedback_severity_from_weakness(
    severity: PaperPolicyWeakScenarioSeverity,
) -> PaperGovernanceAlertSeverity {
    match severity {
        PaperPolicyWeakScenarioSeverity::Low => PaperGovernanceAlertSeverity::Low,
        PaperPolicyWeakScenarioSeverity::Medium => PaperGovernanceAlertSeverity::Medium,
        PaperPolicyWeakScenarioSeverity::High => PaperGovernanceAlertSeverity::High,
    }
}

fn governance_feedback_kind_from_weak_cause(
    cause: PaperPolicyWeakScenarioCause,
) -> GovernancePolicyFeedbackKindV3 {
    match cause {
        PaperPolicyWeakScenarioCause::RiskFirstWeakness => {
            GovernancePolicyFeedbackKindV3::TuneRiskPolicy
        }
        PaperPolicyWeakScenarioCause::EvidenceQualityWeakness => {
            GovernancePolicyFeedbackKindV3::ImproveEvidenceQuality
        }
        PaperPolicyWeakScenarioCause::OwnerExplanationWeakness => {
            GovernancePolicyFeedbackKindV3::ImproveOwnerExplanation
        }
        PaperPolicyWeakScenarioCause::NoTradeBiasTooHigh => {
            GovernancePolicyFeedbackKindV3::TuneNoTradeBias
        }
        PaperPolicyWeakScenarioCause::VoiceBalanceWeakness => {
            GovernancePolicyFeedbackKindV3::TuneVoiceBalance
        }
        PaperPolicyWeakScenarioCause::StopConditionWarning
        | PaperPolicyWeakScenarioCause::InsufficientScenarioHistory
        | PaperPolicyWeakScenarioCause::Unknown => {
            GovernancePolicyFeedbackKindV3::CollectMoreEvidence
        }
    }
}

fn governance_feedback_severity_from_recommendation(
    recommendation: PaperPolicyTrialContinuationRecommendationKind,
) -> PaperGovernanceAlertSeverity {
    match recommendation {
        PaperPolicyTrialContinuationRecommendationKind::ContinueRepeatedPaperExecution => {
            PaperGovernanceAlertSeverity::Low
        }
        PaperPolicyTrialContinuationRecommendationKind::ContinueWithWarnings
        | PaperPolicyTrialContinuationRecommendationKind::CollectMoreEvidence => {
            PaperGovernanceAlertSeverity::Medium
        }
        PaperPolicyTrialContinuationRecommendationKind::TunePolicyBeforeMoreTrials
        | PaperPolicyTrialContinuationRecommendationKind::StopPaperTrial
        | PaperPolicyTrialContinuationRecommendationKind::BlockedBySafety => {
            PaperGovernanceAlertSeverity::High
        }
    }
}

fn governance_feedback_kind_from_recommendation(
    recommendation: &PaperPolicyTrialContinuationRecommendation,
    weak_analysis: &PaperPolicyWeakScenarioAnalysis,
) -> GovernancePolicyFeedbackKindV3 {
    match recommendation.recommendation_kind {
        PaperPolicyTrialContinuationRecommendationKind::ContinueRepeatedPaperExecution => {
            GovernancePolicyFeedbackKindV3::ContinueRepeatedPaperExecution
        }
        PaperPolicyTrialContinuationRecommendationKind::ContinueWithWarnings => {
            GovernancePolicyFeedbackKindV3::MaintainCurrentPaperPolicy
        }
        PaperPolicyTrialContinuationRecommendationKind::TunePolicyBeforeMoreTrials => weak_analysis
            .records
            .first()
            .map(|record| governance_feedback_kind_from_weak_cause(record.cause))
            .filter(|kind| *kind != GovernancePolicyFeedbackKindV3::CollectMoreEvidence)
            .unwrap_or(GovernancePolicyFeedbackKindV3::TuneRiskPolicy),
        PaperPolicyTrialContinuationRecommendationKind::CollectMoreEvidence => {
            GovernancePolicyFeedbackKindV3::CollectMoreEvidence
        }
        PaperPolicyTrialContinuationRecommendationKind::StopPaperTrial
        | PaperPolicyTrialContinuationRecommendationKind::BlockedBySafety => {
            GovernancePolicyFeedbackKindV3::BlockActualGovernance
        }
    }
}

fn governance_feedback_kind_from_evidence_task(
    task_kind: PaperPolicyOutcomeEvidenceTaskKind,
) -> GovernancePolicyFeedbackKindV3 {
    match task_kind {
        PaperPolicyOutcomeEvidenceTaskKind::CollectRiskScenarioEvidence => {
            GovernancePolicyFeedbackKindV3::TuneRiskPolicy
        }
        PaperPolicyOutcomeEvidenceTaskKind::CollectEvidenceGapScenarioEvidence => {
            GovernancePolicyFeedbackKindV3::ImproveEvidenceQuality
        }
        PaperPolicyOutcomeEvidenceTaskKind::CollectOwnerExplanationEvidence => {
            GovernancePolicyFeedbackKindV3::ImproveOwnerExplanation
        }
        PaperPolicyOutcomeEvidenceTaskKind::CollectNoTradeBiasEvidence => {
            GovernancePolicyFeedbackKindV3::TuneNoTradeBias
        }
        PaperPolicyOutcomeEvidenceTaskKind::CollectVoiceBalanceEvidence => {
            GovernancePolicyFeedbackKindV3::TuneVoiceBalance
        }
        PaperPolicyOutcomeEvidenceTaskKind::AddMoreRepeatedRuns
        | PaperPolicyOutcomeEvidenceTaskKind::ManualReview => {
            GovernancePolicyFeedbackKindV3::CollectMoreEvidence
        }
    }
}

fn governance_feedback_severity_from_task_priority(
    priority: PaperPolicyOutcomeEvidenceTaskPriority,
) -> PaperGovernanceAlertSeverity {
    match priority {
        PaperPolicyOutcomeEvidenceTaskPriority::Low => PaperGovernanceAlertSeverity::Low,
        PaperPolicyOutcomeEvidenceTaskPriority::Normal => PaperGovernanceAlertSeverity::Medium,
        PaperPolicyOutcomeEvidenceTaskPriority::High => PaperGovernanceAlertSeverity::High,
    }
}

pub fn build_governance_feedback_from_outcome_scorecard(
    scorecard: &PaperPolicyTrialOutcomeScorecard,
    continuation_recommendation: &PaperPolicyTrialContinuationRecommendation,
    weak_analysis: &PaperPolicyWeakScenarioAnalysis,
    evidence_queue: &PaperPolicyOutcomeEvidenceTaskQueue,
) -> Vec<GovernancePolicyFeedbackRecordV3> {
    let mut feedback_records = Vec::new();
    if scorecard.scorecard_status == PaperPolicyTrialOutcomeScorecardStatus::Strong
        && weak_analysis.weak_record_count == 0
    {
        feedback_records.push(GovernancePolicyFeedbackRecordV3 {
            feedback_id: format!(
                "{}-continue-repeated-paper-execution",
                scorecard.scorecard_id
            ),
            source: GovernancePolicyFeedbackSourceV3::OutcomeScorecard,
            feedback_kind: GovernancePolicyFeedbackKindV3::ContinueRepeatedPaperExecution,
            severity: PaperGovernanceAlertSeverity::Low,
            scenario_kind: None,
            scorecard_status: Some(scorecard.scorecard_status),
            aggregate_score: Some(scorecard.aggregate_total_score),
            reason: "strong paper-only outcome scorecard with no major weak scenarios".to_string(),
            advisory_only: true,
            policy_apply_allowed: false,
            paper_only: true,
        });
        feedback_records.push(GovernancePolicyFeedbackRecordV3 {
            feedback_id: format!("{}-maintain-current-paper-policy", scorecard.scorecard_id),
            source: GovernancePolicyFeedbackSourceV3::OutcomeScorecard,
            feedback_kind: GovernancePolicyFeedbackKindV3::MaintainCurrentPaperPolicy,
            severity: PaperGovernanceAlertSeverity::Low,
            scenario_kind: None,
            scorecard_status: Some(scorecard.scorecard_status),
            aggregate_score: Some(scorecard.aggregate_total_score),
            reason: "paper-only trial quality is strong enough to keep the current policy locked for more paper cycles".to_string(),
            advisory_only: true,
            policy_apply_allowed: false,
            paper_only: true,
        });
    } else if matches!(
        scorecard.scorecard_status,
        PaperPolicyTrialOutcomeScorecardStatus::Unsafe
    ) {
        feedback_records.push(GovernancePolicyFeedbackRecordV3 {
            feedback_id: format!("{}-stop-paper-trial", scorecard.scorecard_id),
            source: GovernancePolicyFeedbackSourceV3::OutcomeScorecard,
            feedback_kind: GovernancePolicyFeedbackKindV3::StopPaperTrial,
            severity: PaperGovernanceAlertSeverity::High,
            scenario_kind: None,
            scorecard_status: Some(scorecard.scorecard_status),
            aggregate_score: Some(scorecard.aggregate_total_score),
            reason: "unsafe paper-only outcome scorecard should stop the current paper trial"
                .to_string(),
            advisory_only: true,
            policy_apply_allowed: false,
            paper_only: true,
        });
        feedback_records.push(GovernancePolicyFeedbackRecordV3 {
            feedback_id: format!("{}-block-actual-governance", scorecard.scorecard_id),
            source: GovernancePolicyFeedbackSourceV3::OutcomeScorecard,
            feedback_kind: GovernancePolicyFeedbackKindV3::BlockActualGovernance,
            severity: PaperGovernanceAlertSeverity::High,
            scenario_kind: None,
            scorecard_status: Some(scorecard.scorecard_status),
            aggregate_score: Some(scorecard.aggregate_total_score),
            reason: "unsafe paper-only outcome scorecard must keep actual governance blocked"
                .to_string(),
            advisory_only: true,
            policy_apply_allowed: false,
            paper_only: true,
        });
    } else {
        feedback_records.push(GovernancePolicyFeedbackRecordV3 {
            feedback_id: format!("{}-keep-policy-locked", scorecard.scorecard_id),
            source: GovernancePolicyFeedbackSourceV3::OutcomeScorecard,
            feedback_kind: GovernancePolicyFeedbackKindV3::KeepPolicyApplyLocked,
            severity: PaperGovernanceAlertSeverity::Medium,
            scenario_kind: None,
            scorecard_status: Some(scorecard.scorecard_status),
            aggregate_score: Some(scorecard.aggregate_total_score),
            reason: "outcome scorecard remains advisory-only and keeps policy application locked"
                .to_string(),
            advisory_only: true,
            policy_apply_allowed: false,
            paper_only: true,
        });
    }
    feedback_records.push(GovernancePolicyFeedbackRecordV3 {
        feedback_id: format!(
            "{}-continuation-recommendation",
            continuation_recommendation.recommendation_id
        ),
        source: GovernancePolicyFeedbackSourceV3::ContinuationRecommendation,
        feedback_kind: governance_feedback_kind_from_recommendation(
            continuation_recommendation,
            weak_analysis,
        ),
        severity: governance_feedback_severity_from_recommendation(
            continuation_recommendation.recommendation_kind,
        ),
        scenario_kind: None,
        scorecard_status: Some(scorecard.scorecard_status),
        aggregate_score: Some(scorecard.aggregate_total_score),
        reason: continuation_recommendation.reason.clone(),
        advisory_only: true,
        policy_apply_allowed: false,
        paper_only: true,
    });
    for weak_record in &weak_analysis.records {
        feedback_records.push(GovernancePolicyFeedbackRecordV3 {
            feedback_id: format!(
                "{}-{}",
                weak_record.record_id,
                paper_policy_trial_scenario_kind_key(weak_record.scenario_kind)
            ),
            source: GovernancePolicyFeedbackSourceV3::WeakScenarioAnalysis,
            feedback_kind: governance_feedback_kind_from_weak_cause(weak_record.cause),
            severity: governance_feedback_severity_from_weakness(weak_record.severity),
            scenario_kind: Some(weak_record.scenario_kind),
            scorecard_status: Some(scorecard.scorecard_status),
            aggregate_score: Some(scorecard.aggregate_total_score),
            reason: weak_record.reason.clone(),
            advisory_only: true,
            policy_apply_allowed: false,
            paper_only: true,
        });
    }
    for task in &evidence_queue.tasks {
        feedback_records.push(GovernancePolicyFeedbackRecordV3 {
            feedback_id: format!("{}-feedback", task.task_id),
            source: GovernancePolicyFeedbackSourceV3::OutcomeEvidenceTaskQueue,
            feedback_kind: governance_feedback_kind_from_evidence_task(task.task_kind),
            severity: governance_feedback_severity_from_task_priority(task.priority),
            scenario_kind: task.scenario_kind,
            scorecard_status: Some(scorecard.scorecard_status),
            aggregate_score: Some(scorecard.aggregate_total_score),
            reason: task.reason.clone(),
            advisory_only: true,
            policy_apply_allowed: false,
            paper_only: true,
        });
    }
    feedback_records
}

fn count_feedback_kind(
    feedback_records: &[GovernancePolicyFeedbackRecordV3],
    kind: GovernancePolicyFeedbackKindV3,
) -> usize {
    feedback_records
        .iter()
        .filter(|record| record.feedback_kind == kind)
        .count()
}

fn dominant_governance_feedback_kind(
    feedback_records: &[GovernancePolicyFeedbackRecordV3],
) -> Option<GovernancePolicyFeedbackKindV3> {
    let blocking_kinds = [
        GovernancePolicyFeedbackKindV3::BlockActualGovernance,
        GovernancePolicyFeedbackKindV3::StopPaperTrial,
    ];
    for kind in blocking_kinds {
        if feedback_records
            .iter()
            .any(|record| record.feedback_kind == kind)
        {
            return Some(kind);
        }
    }
    let high_severity_tuning_kinds = [
        GovernancePolicyFeedbackKindV3::TuneRiskPolicy,
        GovernancePolicyFeedbackKindV3::TuneVoiceBalance,
        GovernancePolicyFeedbackKindV3::TuneNoTradeBias,
        GovernancePolicyFeedbackKindV3::ImproveEvidenceQuality,
        GovernancePolicyFeedbackKindV3::ImproveOwnerExplanation,
    ];
    for kind in high_severity_tuning_kinds {
        if feedback_records.iter().any(|record| {
            record.feedback_kind == kind && record.severity == PaperGovernanceAlertSeverity::High
        }) {
            return Some(kind);
        }
    }
    let kinds = [
        GovernancePolicyFeedbackKindV3::TuneRiskPolicy,
        GovernancePolicyFeedbackKindV3::TuneVoiceBalance,
        GovernancePolicyFeedbackKindV3::TuneNoTradeBias,
        GovernancePolicyFeedbackKindV3::ImproveEvidenceQuality,
        GovernancePolicyFeedbackKindV3::ImproveOwnerExplanation,
        GovernancePolicyFeedbackKindV3::CollectMoreEvidence,
        GovernancePolicyFeedbackKindV3::ContinueRepeatedPaperExecution,
        GovernancePolicyFeedbackKindV3::MaintainCurrentPaperPolicy,
        GovernancePolicyFeedbackKindV3::KeepPolicyApplyLocked,
    ];
    let mut best_kind = None;
    let mut best_count = 0;
    for kind in kinds {
        let count = count_feedback_kind(feedback_records, kind);
        if count > best_count {
            best_count = count;
            best_kind = Some(kind);
        }
    }
    best_kind
}

pub fn summarize_governance_outcome_feedback(
    feedback_records: &[GovernancePolicyFeedbackRecordV3],
) -> GovernanceOutcomeFeedbackSummary {
    let high_severity_count = feedback_records
        .iter()
        .filter(|record| record.severity == PaperGovernanceAlertSeverity::High)
        .count();
    let continue_repeated_count = count_feedback_kind(
        feedback_records,
        GovernancePolicyFeedbackKindV3::ContinueRepeatedPaperExecution,
    );
    let tuning_needed_count = [
        GovernancePolicyFeedbackKindV3::TuneRiskPolicy,
        GovernancePolicyFeedbackKindV3::TuneVoiceBalance,
        GovernancePolicyFeedbackKindV3::TuneNoTradeBias,
        GovernancePolicyFeedbackKindV3::ImproveEvidenceQuality,
        GovernancePolicyFeedbackKindV3::ImproveOwnerExplanation,
    ]
    .into_iter()
    .map(|kind| count_feedback_kind(feedback_records, kind))
    .sum();
    let evidence_needed_count = count_feedback_kind(
        feedback_records,
        GovernancePolicyFeedbackKindV3::CollectMoreEvidence,
    );
    let block_count = [
        GovernancePolicyFeedbackKindV3::BlockActualGovernance,
        GovernancePolicyFeedbackKindV3::StopPaperTrial,
    ]
    .into_iter()
    .map(|kind| count_feedback_kind(feedback_records, kind))
    .sum();
    let summary_status = if block_count > 0 {
        GovernanceOutcomeFeedbackSummaryStatus::Blocked
    } else if evidence_needed_count > 0 && tuning_needed_count == 0 {
        GovernanceOutcomeFeedbackSummaryStatus::EvidenceNeeded
    } else if tuning_needed_count > 0 {
        GovernanceOutcomeFeedbackSummaryStatus::TuningRecommended
    } else if high_severity_count > 0 || evidence_needed_count > 0 {
        GovernanceOutcomeFeedbackSummaryStatus::ContinueWithWarnings
    } else {
        GovernanceOutcomeFeedbackSummaryStatus::ContinueRecommended
    };
    GovernanceOutcomeFeedbackSummary {
        summary_id: format!("outcome-feedback-summary-{}", feedback_records.len()),
        feedback_count: feedback_records.len(),
        high_severity_count,
        dominant_feedback: dominant_governance_feedback_kind(feedback_records),
        continue_repeated_count,
        tuning_needed_count,
        evidence_needed_count,
        block_count,
        summary_status,
        policy_apply_allowed: false,
        paper_only: true,
    }
}

fn normalize_paper_policy_trial_continuation_ledger(
    ledger_id: String,
    entries: Vec<PaperPolicyTrialContinuationLedgerEntry>,
) -> PaperPolicyTrialContinuationLedger {
    let mut seen = BTreeSet::new();
    let normalized_entries = entries
        .into_iter()
        .filter(|entry| seen.insert(entry.entry_id.clone()))
        .map(|mut entry| {
            entry.policy_apply_allowed = false;
            entry.paper_only = true;
            entry
        })
        .collect::<Vec<_>>();
    let latest_entry_id = normalized_entries
        .last()
        .map(|entry| entry.entry_id.clone());
    let entry_count = normalized_entries.len();
    PaperPolicyTrialContinuationLedger {
        ledger_id,
        entries: normalized_entries,
        entry_count,
        latest_entry_id,
        paper_only: true,
    }
}

fn default_paper_policy_trial_continuation_ledger(
    run_id: &str,
) -> PaperPolicyTrialContinuationLedger {
    normalize_paper_policy_trial_continuation_ledger(
        format!("{}-paper-policy-trial-continuation-ledger", run_id),
        Vec::new(),
    )
}

fn load_paper_policy_trial_continuation_ledger_from_local_json(
    path: &Path,
) -> Result<PaperPolicyTrialContinuationLedger, String> {
    validate_local_json_path(path, "paper policy trial continuation ledger path")?;
    let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
    let ledger: PaperPolicyTrialContinuationLedger =
        serde_json::from_str(&text).map_err(|err| err.to_string())?;
    if !ledger.paper_only
        || ledger
            .entries
            .iter()
            .any(|entry| !entry.paper_only || entry.policy_apply_allowed)
    {
        return Err("paper policy trial continuation ledger must stay paper_only".to_string());
    }
    Ok(normalize_paper_policy_trial_continuation_ledger(
        ledger.ledger_id,
        ledger.entries,
    ))
}

fn save_paper_policy_trial_continuation_ledger_to_local_json(
    path: &Path,
    ledger: &PaperPolicyTrialContinuationLedger,
) -> Result<(), String> {
    validate_local_json_path(path, "paper policy trial continuation ledger path")?;
    if !ledger.paper_only
        || ledger
            .entries
            .iter()
            .any(|entry| !entry.paper_only || entry.policy_apply_allowed)
    {
        return Err("paper policy trial continuation ledger must stay paper_only".to_string());
    }
    write_safe_json(path, ledger)
}

fn append_paper_policy_trial_continuation_ledger(
    ledger: &PaperPolicyTrialContinuationLedger,
    entry: PaperPolicyTrialContinuationLedgerEntry,
) -> PaperPolicyTrialContinuationLedger {
    let mut entries = ledger.entries.clone();
    entries.push(entry);
    normalize_paper_policy_trial_continuation_ledger(ledger.ledger_id.clone(), entries)
}

fn latest_paper_policy_trial_continuation_ledger_entry(
    ledger: &PaperPolicyTrialContinuationLedger,
) -> Option<&PaperPolicyTrialContinuationLedgerEntry> {
    ledger.entries.last()
}

fn build_paper_policy_trial_continuation_ledger_entry(
    run_id: &str,
    outcome_scorecard_result: &PaperPolicyTrialOutcomeScorecardRunResult,
) -> PaperPolicyTrialContinuationLedgerEntry {
    PaperPolicyTrialContinuationLedgerEntry {
        entry_id: format!("{}-continuation-ledger-entry", run_id),
        run_id: Some(run_id.to_string()),
        scorecard_status: outcome_scorecard_result.scorecard.scorecard_status,
        aggregate_total_score: outcome_scorecard_result.scorecard.aggregate_total_score,
        continuation_recommendation: outcome_scorecard_result
            .continuation_recommendation
            .recommendation_kind,
        next_recommended_action: outcome_scorecard_result
            .continuation_recommendation
            .next_recommended_action,
        weak_scenario_count: outcome_scorecard_result
            .weak_scenario_analysis
            .weak_record_count,
        evidence_task_count: outcome_scorecard_result.evidence_task_queue.task_count,
        safety_status: outcome_scorecard_result.safety_guard.guard_status,
        policy_apply_allowed: false,
        paper_only: true,
    }
}

fn count_continuation_recommendation(
    ledger: &PaperPolicyTrialContinuationLedger,
    recommendation: PaperPolicyTrialContinuationRecommendationKind,
) -> usize {
    ledger
        .entries
        .iter()
        .filter(|entry| entry.continuation_recommendation == recommendation)
        .count()
}

fn dominant_continuation_recommendation(
    ledger: &PaperPolicyTrialContinuationLedger,
) -> Option<PaperPolicyTrialContinuationRecommendationKind> {
    let recommendations = [
        PaperPolicyTrialContinuationRecommendationKind::ContinueRepeatedPaperExecution,
        PaperPolicyTrialContinuationRecommendationKind::ContinueWithWarnings,
        PaperPolicyTrialContinuationRecommendationKind::TunePolicyBeforeMoreTrials,
        PaperPolicyTrialContinuationRecommendationKind::CollectMoreEvidence,
        PaperPolicyTrialContinuationRecommendationKind::StopPaperTrial,
        PaperPolicyTrialContinuationRecommendationKind::BlockedBySafety,
    ];
    let mut best_kind = None;
    let mut best_count = 0;
    for kind in recommendations {
        let count = count_continuation_recommendation(ledger, kind);
        if count > best_count {
            best_count = count;
            best_kind = Some(kind);
        }
    }
    best_kind
}

pub fn summarize_paper_policy_trial_continuation_stability(
    ledger: &PaperPolicyTrialContinuationLedger,
) -> PaperPolicyTrialContinuationStabilitySummary {
    let continue_count = count_continuation_recommendation(
        ledger,
        PaperPolicyTrialContinuationRecommendationKind::ContinueRepeatedPaperExecution,
    );
    let tune_count = count_continuation_recommendation(
        ledger,
        PaperPolicyTrialContinuationRecommendationKind::TunePolicyBeforeMoreTrials,
    );
    let evidence_count = count_continuation_recommendation(
        ledger,
        PaperPolicyTrialContinuationRecommendationKind::CollectMoreEvidence,
    );
    let stop_count = count_continuation_recommendation(
        ledger,
        PaperPolicyTrialContinuationRecommendationKind::StopPaperTrial,
    );
    let block_count = count_continuation_recommendation(
        ledger,
        PaperPolicyTrialContinuationRecommendationKind::BlockedBySafety,
    );
    let continue_streak = ledger
        .entries
        .iter()
        .rev()
        .take_while(|entry| {
            entry.continuation_recommendation
                == PaperPolicyTrialContinuationRecommendationKind::ContinueRepeatedPaperExecution
        })
        .count();
    let recommendation_flip_count = ledger
        .entries
        .windows(2)
        .filter(|window| {
            window[0].continuation_recommendation != window[1].continuation_recommendation
        })
        .count();
    let latest_entry = latest_paper_policy_trial_continuation_ledger_entry(ledger);
    let stability_status = if ledger.entry_count < 2 {
        PaperPolicyTrialContinuationStabilityStatus::NeedsMoreHistory
    } else if ledger
        .entries
        .iter()
        .any(|entry| !entry.paper_only || entry.policy_apply_allowed)
        || block_count > 0
        || latest_entry.is_some_and(|entry| {
            entry.continuation_recommendation
                == PaperPolicyTrialContinuationRecommendationKind::BlockedBySafety
        })
    {
        PaperPolicyTrialContinuationStabilityStatus::Blocked
    } else if continue_count == ledger.entry_count && recommendation_flip_count == 0 {
        PaperPolicyTrialContinuationStabilityStatus::StableContinue
    } else if recommendation_flip_count > 0
        && (tune_count > 0 || evidence_count > 0 || stop_count > 0)
    {
        PaperPolicyTrialContinuationStabilityStatus::UnstableRecommendation
    } else if tune_count > 0 || evidence_count > 0 || stop_count > 0 {
        PaperPolicyTrialContinuationStabilityStatus::TuningNeeded
    } else {
        PaperPolicyTrialContinuationStabilityStatus::ContinueWithWarnings
    };
    PaperPolicyTrialContinuationStabilitySummary {
        summary_id: format!("{}-continuation-stability", ledger.ledger_id),
        entry_count: ledger.entry_count,
        continue_count,
        continue_streak,
        tune_count,
        evidence_count,
        stop_count,
        block_count,
        recommendation_flip_count,
        dominant_recommendation: dominant_continuation_recommendation(ledger),
        stability_status,
        policy_apply_allowed: false,
        paper_only: true,
    }
}

fn recommended_tuning_focus_from_summary(
    summary: &GovernanceOutcomeFeedbackSummary,
    stability: &PaperPolicyTrialContinuationStabilitySummary,
) -> GovernanceOutcomeFeedbackRecommendedTuningFocus {
    if matches!(
        summary.summary_status,
        GovernanceOutcomeFeedbackSummaryStatus::Blocked
    ) || matches!(
        stability.stability_status,
        PaperPolicyTrialContinuationStabilityStatus::Blocked
    ) {
        return GovernanceOutcomeFeedbackRecommendedTuningFocus::SafetyBlock;
    }
    match summary.dominant_feedback {
        Some(GovernancePolicyFeedbackKindV3::TuneRiskPolicy) => {
            GovernanceOutcomeFeedbackRecommendedTuningFocus::RiskPolicy
        }
        Some(GovernancePolicyFeedbackKindV3::TuneVoiceBalance) => {
            GovernanceOutcomeFeedbackRecommendedTuningFocus::VoiceBalance
        }
        Some(GovernancePolicyFeedbackKindV3::TuneNoTradeBias) => {
            GovernanceOutcomeFeedbackRecommendedTuningFocus::NoTradeBias
        }
        Some(GovernancePolicyFeedbackKindV3::ImproveEvidenceQuality)
        | Some(GovernancePolicyFeedbackKindV3::CollectMoreEvidence) => {
            GovernanceOutcomeFeedbackRecommendedTuningFocus::EvidenceQuality
        }
        Some(GovernancePolicyFeedbackKindV3::ImproveOwnerExplanation) => {
            GovernanceOutcomeFeedbackRecommendedTuningFocus::OwnerExplanation
        }
        _ => GovernanceOutcomeFeedbackRecommendedTuningFocus::None,
    }
}

pub fn build_governance_outcome_feedback_tuning_input(
    feedback_summary: &GovernanceOutcomeFeedbackSummary,
    continuation_stability: &PaperPolicyTrialContinuationStabilitySummary,
) -> GovernanceOutcomeFeedbackTuningInput {
    let recommended_tuning_focus =
        recommended_tuning_focus_from_summary(feedback_summary, continuation_stability);
    let should_stop_paper_trial = matches!(
        feedback_summary.summary_status,
        GovernanceOutcomeFeedbackSummaryStatus::Blocked
    ) || matches!(
        continuation_stability.stability_status,
        PaperPolicyTrialContinuationStabilityStatus::Blocked
    );
    let should_collect_more_evidence = matches!(
        feedback_summary.summary_status,
        GovernanceOutcomeFeedbackSummaryStatus::EvidenceNeeded
    ) || continuation_stability.evidence_count > 0;
    let should_continue_paper_execution = !should_stop_paper_trial
        && matches!(
            feedback_summary.summary_status,
            GovernanceOutcomeFeedbackSummaryStatus::ContinueRecommended
                | GovernanceOutcomeFeedbackSummaryStatus::ContinueWithWarnings
        )
        && matches!(
            continuation_stability.stability_status,
            PaperPolicyTrialContinuationStabilityStatus::StableContinue
                | PaperPolicyTrialContinuationStabilityStatus::ContinueWithWarnings
                | PaperPolicyTrialContinuationStabilityStatus::NeedsMoreHistory
        );
    let can_generate_tuning_proposal = !should_stop_paper_trial
        && !matches!(
            recommended_tuning_focus,
            GovernanceOutcomeFeedbackRecommendedTuningFocus::None
                | GovernanceOutcomeFeedbackRecommendedTuningFocus::SafetyBlock
        );
    GovernanceOutcomeFeedbackTuningInput {
        input_id: format!("{}-tuning-input", feedback_summary.summary_id),
        source_feedback_summary_id: feedback_summary.summary_id.clone(),
        continuation_stability_status: continuation_stability.stability_status,
        recommended_tuning_focus,
        can_generate_tuning_proposal,
        should_continue_paper_execution,
        should_collect_more_evidence,
        should_stop_paper_trial,
        policy_apply_allowed: false,
        paper_only: true,
    }
}

fn evidence_backlog_kind_from_task(
    task_kind: PaperPolicyOutcomeEvidenceTaskKind,
) -> PaperPolicyOutcomeEvidenceBacklogKind {
    match task_kind {
        PaperPolicyOutcomeEvidenceTaskKind::CollectRiskScenarioEvidence => {
            PaperPolicyOutcomeEvidenceBacklogKind::RiskScenarioEvidence
        }
        PaperPolicyOutcomeEvidenceTaskKind::CollectEvidenceGapScenarioEvidence => {
            PaperPolicyOutcomeEvidenceBacklogKind::EvidenceGapEvidence
        }
        PaperPolicyOutcomeEvidenceTaskKind::CollectOwnerExplanationEvidence => {
            PaperPolicyOutcomeEvidenceBacklogKind::OwnerExplanationEvidence
        }
        PaperPolicyOutcomeEvidenceTaskKind::CollectNoTradeBiasEvidence => {
            PaperPolicyOutcomeEvidenceBacklogKind::NoTradeBiasEvidence
        }
        PaperPolicyOutcomeEvidenceTaskKind::CollectVoiceBalanceEvidence => {
            PaperPolicyOutcomeEvidenceBacklogKind::VoiceBalanceEvidence
        }
        PaperPolicyOutcomeEvidenceTaskKind::AddMoreRepeatedRuns => {
            PaperPolicyOutcomeEvidenceBacklogKind::RepeatedRunEvidence
        }
        PaperPolicyOutcomeEvidenceTaskKind::ManualReview => {
            PaperPolicyOutcomeEvidenceBacklogKind::ManualReview
        }
    }
}

pub fn build_paper_policy_outcome_evidence_backlog(
    evidence_queue: &PaperPolicyOutcomeEvidenceTaskQueue,
) -> PaperPolicyOutcomeEvidenceBacklog {
    let items = evidence_queue
        .tasks
        .iter()
        .map(|task| PaperPolicyOutcomeEvidenceBacklogItem {
            item_id: format!("{}-backlog", task.task_id),
            source_task_id: task.task_id.clone(),
            scenario_kind: task.scenario_kind,
            backlog_kind: evidence_backlog_kind_from_task(task.task_kind),
            priority: task.priority,
            reason: task.reason.clone(),
            paper_only: true,
        })
        .collect::<Vec<_>>();
    let high_priority_count = items
        .iter()
        .filter(|item| item.priority == PaperPolicyOutcomeEvidenceTaskPriority::High)
        .count();
    PaperPolicyOutcomeEvidenceBacklog {
        backlog_id: format!("{}-evidence-backlog", evidence_queue.queue_id),
        item_count: items.len(),
        items,
        high_priority_count,
        paper_only: true,
    }
}

fn build_paper_policy_outcome_feedback_bridge_safety_guard_from_parts(
    run_result: &PaperPolicyOutcomeFeedbackBridgeRunResult,
    batch_before: Option<&BatchCommitteeCycleWithStateResult>,
    batch_after: Option<&BatchCommitteeCycleWithStateResult>,
) -> PaperPolicyOutcomeFeedbackBridgeSafetyGuard {
    let after = batch_after.or(batch_before);
    let policy_apply_allowed_true_detected = run_result.feedback_summary.policy_apply_allowed
        || run_result.tuning_input.policy_apply_allowed
        || run_result
            .feedback_records
            .iter()
            .any(|record| record.policy_apply_allowed)
        || run_result
            .continuation_ledger
            .entries
            .iter()
            .any(|entry| entry.policy_apply_allowed);
    let actual_policy_apply_detected = policy_apply_allowed_true_detected;
    let actual_score_mutation_detected = if let (Some(before), Some(after)) = (batch_before, after)
    {
        member_score_changed(
            &before.state_update.updated_member_states,
            &after.state_update.updated_member_states,
        )
    } else {
        false
    };
    let actual_voice_mutation_detected = if let (Some(before), Some(after)) = (batch_before, after)
    {
        member_voice_changed(
            &before.state_update.updated_member_states,
            &after.state_update.updated_member_states,
        )
    } else {
        false
    };
    let committee_decision_mutation_detected =
        if let (Some(before), Some(after)) = (batch_before, after) {
            before.batch_result.committee_sessions != after.batch_result.committee_sessions
        } else {
            false
        };
    let chairman_decision_mutation_detected =
        if let (Some(before), Some(after)) = (batch_before, after) {
            before.batch_result.chairman_decisions != after.batch_result.chairman_decisions
        } else {
            false
        };
    let risk_governor_override_detected = if let (Some(before), Some(after)) = (batch_before, after)
    {
        risk_governor_decision_status_changed(
            &before.batch_result.chairman_decisions,
            &after.batch_result.chairman_decisions,
        )
    } else {
        false
    };
    let trade_signal_detected = if let (Some(before), Some(after)) = (batch_before, after) {
        value_has_new_debug_marker(
            &before.batch_result.committee_sessions,
            &after.batch_result.committee_sessions,
            &["trade-signal".to_string()],
        )
    } else {
        false
    };
    let order_detected = if let (Some(before), Some(after)) = (batch_before, after) {
        value_has_new_debug_marker(
            &before.batch_result.event_queue,
            &after.batch_result.event_queue,
            &[
                "order".to_string(),
                "order_id".to_string(),
                "submit order".to_string(),
                "execute order".to_string(),
                "order-side-effect".to_string(),
            ],
        )
    } else {
        false
    };
    let broker_order_account_detected = if let (Some(before), Some(after)) = (batch_before, after) {
        let markers = [
            "broker".to_string(),
            "account".to_string(),
            "account_id".to_string(),
            "broker-account".to_string(),
        ];
        value_has_new_debug_marker(
            &before.batch_result.event_queue,
            &after.batch_result.event_queue,
            &markers,
        ) || value_has_new_debug_marker(
            &before.batch_result.committee_sessions,
            &after.batch_result.committee_sessions,
            &markers,
        ) || value_has_new_debug_marker(
            &before.batch_result.chairman_decisions,
            &after.batch_result.chairman_decisions,
            &markers,
        )
    } else {
        false
    };
    let feedback_used_as_live_decision_detected = actual_policy_apply_detected
        || committee_decision_mutation_detected
        || chairman_decision_mutation_detected
        || risk_governor_override_detected
        || trade_signal_detected
        || order_detected
        || broker_order_account_detected;
    let ledger_write_when_dry_run_detected = run_result.dry_run && run_result.wrote_ledger;
    let mut violations = Vec::new();
    if policy_apply_allowed_true_detected {
        violations.push("outcome feedback bridge enabled policy_apply_allowed".to_string());
    }
    if actual_policy_apply_detected {
        violations.push("outcome feedback bridge allowed actual policy apply".to_string());
    }
    if actual_score_mutation_detected {
        violations.push("outcome feedback bridge mutated actual member scores".to_string());
    }
    if actual_voice_mutation_detected {
        violations.push("outcome feedback bridge mutated actual member voices".to_string());
    }
    if committee_decision_mutation_detected {
        violations.push("outcome feedback bridge changed committee decisions".to_string());
    }
    if chairman_decision_mutation_detected {
        violations.push("outcome feedback bridge changed chairman decisions".to_string());
    }
    if risk_governor_override_detected {
        violations.push("outcome feedback bridge overrode the Risk Governor".to_string());
    }
    if trade_signal_detected || order_detected || broker_order_account_detected {
        violations.push("outcome feedback bridge touched trade/order/account paths".to_string());
    }
    if feedback_used_as_live_decision_detected {
        violations.push("outcome feedback bridge was used as a live decision".to_string());
    }
    if ledger_write_when_dry_run_detected {
        violations.push("dry-run outcome feedback bridge wrote continuation ledger".to_string());
    }
    if run_result
        .feedback_records
        .iter()
        .any(|record| !record.advisory_only || !record.paper_only)
        || !run_result.feedback_summary.paper_only
        || !run_result.continuation_ledger.paper_only
        || !run_result.continuation_stability.paper_only
        || !run_result.tuning_input.paper_only
        || !run_result.evidence_backlog.paper_only
        || !run_result.paper_only
    {
        violations.push("outcome feedback bridge lost paper-only advisory protections".to_string());
    }
    PaperPolicyOutcomeFeedbackBridgeSafetyGuard {
        policy_apply_allowed_true_detected,
        actual_policy_apply_detected,
        actual_score_mutation_detected,
        actual_voice_mutation_detected,
        committee_decision_mutation_detected,
        chairman_decision_mutation_detected,
        risk_governor_override_detected,
        trade_signal_detected,
        order_detected,
        broker_order_account_detected,
        feedback_used_as_live_decision_detected,
        ledger_write_when_dry_run_detected,
        guard_status: if violations.is_empty() {
            PaperGovernanceTrialSafetyGuardStatus::Preserved
        } else {
            PaperGovernanceTrialSafetyGuardStatus::Violated
        },
        violations,
        paper_only: true,
    }
}

pub fn evaluate_paper_policy_outcome_feedback_bridge_safety(
    run_result: &PaperPolicyOutcomeFeedbackBridgeRunResult,
    batch_before: &BatchCommitteeCycleWithStateResult,
    batch_after: Option<&BatchCommitteeCycleWithStateResult>,
) -> PaperPolicyOutcomeFeedbackBridgeSafetyGuard {
    build_paper_policy_outcome_feedback_bridge_safety_guard_from_parts(
        run_result,
        Some(batch_before),
        batch_after,
    )
}

pub fn prove_paper_policy_trial_continuation_ledger_write(
    run_result: &PaperPolicyOutcomeFeedbackBridgeRunResult,
    output_path: &Path,
) -> Result<PaperPolicyTrialContinuationLedgerWriteProof, String> {
    validate_local_json_path(output_path, "paper policy trial continuation ledger path")?;
    let ledger_exists_after_write = output_path.exists();
    let stored_ledger = if ledger_exists_after_write {
        let text = fs::read_to_string(output_path).map_err(|err| err.to_string())?;
        Some(
            serde_json::from_str::<PaperPolicyTrialContinuationLedger>(&text)
                .map_err(|err| err.to_string())?,
        )
    } else {
        None
    };
    let policy_apply_allowed_true_count = stored_ledger
        .as_ref()
        .map(|ledger| {
            ledger
                .entries
                .iter()
                .filter(|entry| entry.policy_apply_allowed)
                .count()
        })
        .unwrap_or(0);
    let unsafe_entry_count = stored_ledger
        .as_ref()
        .map(|ledger| {
            ledger
                .entries
                .iter()
                .filter(|entry| {
                    !entry.paper_only
                        || entry.safety_status == PaperGovernanceTrialSafetyGuardStatus::Violated
                })
                .count()
        })
        .unwrap_or(0);
    let paper_only_count = stored_ledger
        .as_ref()
        .map(|ledger| {
            ledger
                .entries
                .iter()
                .filter(|entry| entry.paper_only)
                .count()
        })
        .unwrap_or(0);
    let entry_count = stored_ledger
        .as_ref()
        .map(|ledger| ledger.entry_count)
        .unwrap_or(0);
    let proof_status = if run_result.wrote_ledger && !ledger_exists_after_write {
        PaperGovernanceTrialLedgerWriteProofStatus::Failed
    } else if policy_apply_allowed_true_count > 0 {
        PaperGovernanceTrialLedgerWriteProofStatus::Failed
    } else if unsafe_entry_count > 0 {
        PaperGovernanceTrialLedgerWriteProofStatus::ProvenWithWarnings
    } else {
        PaperGovernanceTrialLedgerWriteProofStatus::Proven
    };
    Ok(PaperPolicyTrialContinuationLedgerWriteProof {
        proof_id: format!("{}-continuation-ledger-write-proof", run_result.run_id),
        expected_output_path: output_path.display().to_string(),
        wrote_ledger: run_result.wrote_ledger,
        ledger_exists_after_write,
        entry_count,
        paper_only_count,
        policy_apply_allowed_true_count,
        unsafe_entry_count,
        proof_status,
        paper_only: true,
    })
}

pub fn build_owner_paper_policy_outcome_feedback_summary(
    run_result: &PaperPolicyOutcomeFeedbackBridgeRunResult,
) -> OwnerPaperPolicyOutcomeFeedbackSummary {
    OwnerPaperPolicyOutcomeFeedbackSummary {
        summary_id: format!("{}-owner-paper-policy-outcome-feedback-summary", run_result.run_id),
        feedback_summary_status: run_result.feedback_summary.summary_status,
        continuation_stability_status: run_result.continuation_stability.stability_status,
        tuning_focus: run_result.tuning_input.recommended_tuning_focus,
        should_continue_paper_execution: run_result.tuning_input.should_continue_paper_execution,
        should_collect_more_evidence: run_result.tuning_input.should_collect_more_evidence,
        should_stop_paper_trial: run_result.tuning_input.should_stop_paper_trial,
        evidence_backlog_count: run_result.evidence_backlog.item_count,
        message: "Outcome feedback bridge converted paper-only scorecard results into advisory governance feedback. No actual governance policy was applied. Actual member score, voice, committee decisions, Risk Governor, and trading remain unchanged while the next paper-cycle tuning direction stays advisory only.".to_string(),
        paper_trial_only: true,
        policy_apply_allowed: false,
        no_actual_policy_apply: true,
        no_score_mutation: true,
        no_voice_mutation: true,
        no_committee_decision_change: true,
        no_risk_override: true,
        not_trade_signal: true,
        paper_only: true,
    }
}

fn paper_policy_outcome_feedback_bridge_run_status(
    run_result: &PaperPolicyOutcomeFeedbackBridgeRunResult,
) -> PaperGovernanceTrialRunStatus {
    if run_result.safety_guard.guard_status == PaperGovernanceTrialSafetyGuardStatus::Violated
        || run_result.feedback_summary.summary_status
            == GovernanceOutcomeFeedbackSummaryStatus::Blocked
        || run_result.write_proof.as_ref().is_some_and(|proof| {
            proof.proof_status == PaperGovernanceTrialLedgerWriteProofStatus::Failed
        })
    {
        PaperGovernanceTrialRunStatus::Failed
    } else if run_result.feedback_summary.summary_status
        != GovernanceOutcomeFeedbackSummaryStatus::ContinueRecommended
        || run_result.continuation_stability.stability_status
            != PaperPolicyTrialContinuationStabilityStatus::StableContinue
        || run_result.evidence_backlog.item_count > 0
        || run_result.write_proof.as_ref().is_some_and(|proof| {
            proof.proof_status == PaperGovernanceTrialLedgerWriteProofStatus::ProvenWithWarnings
        })
    {
        PaperGovernanceTrialRunStatus::PassedWithWarnings
    } else {
        PaperGovernanceTrialRunStatus::Passed
    }
}

pub fn run_paper_policy_outcome_feedback_bridge(
    outcome_scorecard_result: &PaperPolicyTrialOutcomeScorecardRunResult,
    config: &PaperPolicyOutcomeFeedbackBridgeRunConfig,
) -> Result<PaperPolicyOutcomeFeedbackBridgeRunResult, String> {
    let feedback_records = build_governance_feedback_from_outcome_scorecard(
        &outcome_scorecard_result.scorecard,
        &outcome_scorecard_result.continuation_recommendation,
        &outcome_scorecard_result.weak_scenario_analysis,
        &outcome_scorecard_result.evidence_task_queue,
    );
    let feedback_summary = summarize_governance_outcome_feedback(&feedback_records);
    let base_ledger = config
        .continuation_ledger_input_path
        .as_ref()
        .filter(|path| !path.trim().is_empty())
        .map(|path| load_paper_policy_trial_continuation_ledger_from_local_json(Path::new(path)))
        .transpose()?
        .unwrap_or_else(|| default_paper_policy_trial_continuation_ledger(&config.run_id));
    let continuation_ledger = append_paper_policy_trial_continuation_ledger(
        &base_ledger,
        build_paper_policy_trial_continuation_ledger_entry(
            &config.run_id,
            outcome_scorecard_result,
        ),
    );
    let continuation_stability =
        summarize_paper_policy_trial_continuation_stability(&continuation_ledger);
    let tuning_input =
        build_governance_outcome_feedback_tuning_input(&feedback_summary, &continuation_stability);
    let evidence_backlog =
        build_paper_policy_outcome_evidence_backlog(&outcome_scorecard_result.evidence_task_queue);
    let mut result = PaperPolicyOutcomeFeedbackBridgeRunResult {
        run_id: config.run_id.clone(),
        feedback_records,
        feedback_summary,
        continuation_ledger,
        continuation_stability,
        tuning_input,
        evidence_backlog,
        safety_guard: PaperPolicyOutcomeFeedbackBridgeSafetyGuard {
            policy_apply_allowed_true_detected: false,
            actual_policy_apply_detected: false,
            actual_score_mutation_detected: false,
            actual_voice_mutation_detected: false,
            committee_decision_mutation_detected: false,
            chairman_decision_mutation_detected: false,
            risk_governor_override_detected: false,
            trade_signal_detected: false,
            order_detected: false,
            broker_order_account_detected: false,
            feedback_used_as_live_decision_detected: false,
            ledger_write_when_dry_run_detected: false,
            guard_status: PaperGovernanceTrialSafetyGuardStatus::Preserved,
            violations: Vec::new(),
            paper_only: true,
        },
        write_proof: None,
        owner_summary: None,
        run_status: PaperGovernanceTrialRunStatus::Passed,
        dry_run: config.dry_run,
        wrote_ledger: false,
        paper_only: true,
    };
    result.safety_guard =
        build_paper_policy_outcome_feedback_bridge_safety_guard_from_parts(&result, None, None);
    if !config.dry_run && config.append_continuation_ledger {
        let output_path = config
            .continuation_ledger_output_path
            .as_ref()
            .filter(|path| !path.trim().is_empty())
            .ok_or_else(|| {
                "paper policy outcome feedback bridge ledger output path is required when appending ledger"
                    .to_string()
            })?;
        save_paper_policy_trial_continuation_ledger_to_local_json(
            Path::new(output_path),
            &result.continuation_ledger,
        )?;
        result.wrote_ledger = true;
        result.write_proof = Some(prove_paper_policy_trial_continuation_ledger_write(
            &result,
            Path::new(output_path),
        )?);
    }
    if config.emit_owner_summary {
        result.owner_summary = Some(build_owner_paper_policy_outcome_feedback_summary(&result));
    }
    result.run_status = paper_policy_outcome_feedback_bridge_run_status(&result);
    if !config.dry_run {
        if let Some(output_path) = config
            .feedback_output_path
            .as_ref()
            .filter(|path| !path.trim().is_empty())
        {
            validate_local_json_path(
                Path::new(output_path),
                "paper policy outcome feedback bridge output path",
            )?;
            write_safe_json(Path::new(output_path), &result)?;
        }
    }
    Ok(result)
}

fn maybe_run_paper_policy_outcome_feedback_bridge_for_stateful_result(
    run_id: String,
    enabled: bool,
    dry_run: bool,
    append_continuation_ledger: bool,
    continuation_ledger_input_path: Option<&String>,
    continuation_ledger_output_path: Option<&String>,
    feedback_output_path: Option<&String>,
    emit_owner_summary: bool,
    stateful_result: &mut BatchCommitteeCycleWithStateResult,
) -> Result<Option<PaperPolicyOutcomeFeedbackBridgeRunResult>, String> {
    if !paper_policy_outcome_feedback_bridge_requested_from_flags(
        enabled,
        dry_run,
        append_continuation_ledger,
        continuation_ledger_input_path,
        continuation_ledger_output_path,
        feedback_output_path,
        emit_owner_summary,
    ) {
        return Ok(None);
    }
    let outcome_scorecard_result = stateful_result
        .batch_result
        .paper_policy_trial_outcome_scorecard_run_result
        .clone()
        .ok_or_else(|| {
            "paper policy outcome feedback bridge requires outcome scorecard result".to_string()
        })?;
    let before_snapshot = stateful_result.clone();
    let mut result = run_paper_policy_outcome_feedback_bridge(
        &outcome_scorecard_result,
        &PaperPolicyOutcomeFeedbackBridgeRunConfig {
            run_id,
            enabled,
            continuation_ledger_input_path: continuation_ledger_input_path.cloned(),
            continuation_ledger_output_path: continuation_ledger_output_path.cloned(),
            feedback_output_path: feedback_output_path.cloned(),
            dry_run,
            append_continuation_ledger,
            emit_owner_summary,
            paper_only: true,
        },
    )?;
    stateful_result
        .batch_result
        .governance_policy_feedback_records_v3 = Some(result.feedback_records.clone());
    stateful_result
        .batch_result
        .governance_outcome_feedback_summary = Some(result.feedback_summary.clone());
    stateful_result
        .batch_result
        .paper_policy_trial_continuation_ledger = Some(result.continuation_ledger.clone());
    stateful_result
        .batch_result
        .paper_policy_trial_continuation_stability_summary =
        Some(result.continuation_stability.clone());
    stateful_result
        .batch_result
        .governance_outcome_feedback_tuning_input = Some(result.tuning_input.clone());
    stateful_result
        .batch_result
        .paper_policy_outcome_evidence_backlog = Some(result.evidence_backlog.clone());
    stateful_result
        .batch_result
        .paper_policy_outcome_feedback_bridge_safety_guard = Some(result.safety_guard.clone());
    stateful_result
        .batch_result
        .paper_policy_trial_continuation_ledger_write_proof = result.write_proof.clone();
    stateful_result
        .batch_result
        .owner_paper_policy_outcome_feedback_summary = result.owner_summary.clone();
    stateful_result
        .batch_result
        .paper_policy_outcome_feedback_bridge_run_result = Some(result.clone());
    let after_snapshot = stateful_result.clone();
    result.safety_guard = evaluate_paper_policy_outcome_feedback_bridge_safety(
        &result,
        &before_snapshot,
        Some(&after_snapshot),
    );
    if emit_owner_summary {
        result.owner_summary = Some(build_owner_paper_policy_outcome_feedback_summary(&result));
    }
    result.run_status = paper_policy_outcome_feedback_bridge_run_status(&result);
    stateful_result
        .batch_result
        .paper_policy_outcome_feedback_bridge_safety_guard = Some(result.safety_guard.clone());
    stateful_result
        .batch_result
        .owner_paper_policy_outcome_feedback_summary = result.owner_summary.clone();
    stateful_result
        .batch_result
        .paper_policy_outcome_feedback_bridge_run_result = Some(result.clone());
    Ok(Some(result))
}

pub fn governance_outcome_feedback_reentry_requested_from_flags(
    enabled: bool,
    dry_run: bool,
    _output_path: Option<&String>,
    emit_owner_summary: bool,
) -> bool {
    enabled || !dry_run || (enabled && emit_owner_summary)
}

pub fn build_governance_outcome_feedback_reentry_input(
    feedback_bridge_result: &PaperPolicyOutcomeFeedbackBridgeRunResult,
) -> GovernanceOutcomeFeedbackReentryInput {
    GovernanceOutcomeFeedbackReentryInput {
        input_id: format!("{}-reentry-input", feedback_bridge_result.run_id),
        source_feedback_summary_id: feedback_bridge_result.feedback_summary.summary_id.clone(),
        source_tuning_input_id: feedback_bridge_result.tuning_input.input_id.clone(),
        continuation_stability_status: feedback_bridge_result
            .continuation_stability
            .stability_status,
        tuning_focus: feedback_bridge_result.tuning_input.recommended_tuning_focus,
        should_continue_paper_execution: feedback_bridge_result
            .tuning_input
            .should_continue_paper_execution,
        should_collect_more_evidence: feedback_bridge_result
            .tuning_input
            .should_collect_more_evidence,
        should_stop_paper_trial: feedback_bridge_result.tuning_input.should_stop_paper_trial,
        evidence_backlog_count: feedback_bridge_result.evidence_backlog.item_count,
        advisory_only: true,
        policy_apply_allowed: false,
        paper_only: true,
    }
}

fn governance_reentry_feedback_record(
    input_id: &str,
    suffix: &str,
    feedback_kind: GovernancePolicyFeedbackKindV2,
    severity: PaperGovernanceAlertSeverity,
    reason: &str,
) -> GovernancePolicyFeedbackRecordV2 {
    GovernancePolicyFeedbackRecordV2 {
        feedback_id: format!("{input_id}-{suffix}"),
        source: GovernancePolicyFeedbackSource::ManualReview,
        feedback_kind,
        severity,
        member_id: None,
        role: None,
        reason: reason.to_string(),
        paper_only: true,
    }
}

pub fn adapt_outcome_feedback_to_governance_policy_feedback(
    reentry_input: &GovernanceOutcomeFeedbackReentryInput,
) -> GovernanceFeedbackReentryAdapterResult {
    let mut emitted_feedback_records = Vec::new();
    let mut skipped_count = 0usize;
    match reentry_input.tuning_focus {
        GovernanceOutcomeFeedbackRecommendedTuningFocus::None => {
            if reentry_input.should_continue_paper_execution {
                emitted_feedback_records.push(governance_reentry_feedback_record(
                    &reentry_input.input_id,
                    "continue-paper-trial",
                    GovernancePolicyFeedbackKindV2::ContinuePaperTrial,
                    PaperGovernanceAlertSeverity::Low,
                    "strong outcome feedback recommends continuing paper trial with current policy locked",
                ));
            } else if reentry_input.should_collect_more_evidence {
                emitted_feedback_records.push(governance_reentry_feedback_record(
                    &reentry_input.input_id,
                    "needs-more-evidence",
                    GovernancePolicyFeedbackKindV2::NeedsMoreEvidence,
                    PaperGovernanceAlertSeverity::Medium,
                    "outcome feedback requires more paper-only evidence before refreshing recommendation",
                ));
            } else {
                skipped_count += 1;
            }
        }
        GovernanceOutcomeFeedbackRecommendedTuningFocus::RiskPolicy => {
            emitted_feedback_records.push(governance_reentry_feedback_record(
                &reentry_input.input_id,
                "tighten-risk-first-policy",
                GovernancePolicyFeedbackKindV2::TightenRiskFirstPolicy,
                PaperGovernanceAlertSeverity::High,
                "outcome feedback re-entry detected risk weakness and requests tighter risk-first policy",
            ));
        }
        GovernanceOutcomeFeedbackRecommendedTuningFocus::VoiceBalance => {
            emitted_feedback_records.push(governance_reentry_feedback_record(
                &reentry_input.input_id,
                "reduce-voice-cap",
                GovernancePolicyFeedbackKindV2::ReduceVoiceCap,
                PaperGovernanceAlertSeverity::Medium,
                "outcome feedback re-entry detected voice balance weakness and requests a more conservative voice cap",
            ));
        }
        GovernanceOutcomeFeedbackRecommendedTuningFocus::NoTradeBias => {
            emitted_feedback_records.push(governance_reentry_feedback_record(
                &reentry_input.input_id,
                "add-no-trade-bias-cap",
                GovernancePolicyFeedbackKindV2::AddNoTradeBiasCap,
                PaperGovernanceAlertSeverity::Medium,
                "outcome feedback re-entry detected no-trade bias weakness and requests a brake",
            ));
        }
        GovernanceOutcomeFeedbackRecommendedTuningFocus::EvidenceQuality => {
            emitted_feedback_records.push(governance_reentry_feedback_record(
                &reentry_input.input_id,
                "add-evidence-requirement",
                GovernancePolicyFeedbackKindV2::AddEvidenceRequirement,
                PaperGovernanceAlertSeverity::High,
                "outcome feedback re-entry detected evidence weakness and requests higher evidence requirements",
            ));
            emitted_feedback_records.push(governance_reentry_feedback_record(
                &reentry_input.input_id,
                "increase-evidence-regime-floor",
                GovernancePolicyFeedbackKindV2::IncreaseEvidenceRegimeFloor,
                PaperGovernanceAlertSeverity::Medium,
                "outcome feedback re-entry requests a stronger evidence regime floor",
            ));
        }
        GovernanceOutcomeFeedbackRecommendedTuningFocus::OwnerExplanation => {
            emitted_feedback_records.push(governance_reentry_feedback_record(
                &reentry_input.input_id,
                "owner-explanation-evidence",
                GovernancePolicyFeedbackKindV2::AddEvidenceRequirement,
                PaperGovernanceAlertSeverity::Medium,
                "outcome feedback re-entry detected weak owner explanation and requests stronger supporting evidence",
            ));
        }
        GovernanceOutcomeFeedbackRecommendedTuningFocus::SafetyBlock => {
            emitted_feedback_records.push(governance_reentry_feedback_record(
                &reentry_input.input_id,
                "block-actual-governance",
                GovernancePolicyFeedbackKindV2::BlockActualGovernance,
                PaperGovernanceAlertSeverity::High,
                "outcome feedback re-entry is blocked by safety and must keep actual governance locked",
            ));
        }
    }
    if reentry_input.should_collect_more_evidence
        && !emitted_feedback_records
            .iter()
            .any(|record| record.feedback_kind == GovernancePolicyFeedbackKindV2::NeedsMoreEvidence)
        && reentry_input.tuning_focus
            != GovernanceOutcomeFeedbackRecommendedTuningFocus::SafetyBlock
    {
        emitted_feedback_records.push(governance_reentry_feedback_record(
            &reentry_input.input_id,
            "collect-more-evidence",
            GovernancePolicyFeedbackKindV2::NeedsMoreEvidence,
            PaperGovernanceAlertSeverity::Medium,
            "outcome feedback re-entry still needs more paper-only evidence",
        ));
    }
    let adapter_status = if emitted_feedback_records
        .iter()
        .any(|record| record.feedback_kind == GovernancePolicyFeedbackKindV2::BlockActualGovernance)
    {
        GovernanceFeedbackReentryAdapterStatus::Blocked
    } else if emitted_feedback_records.is_empty() {
        GovernanceFeedbackReentryAdapterStatus::NoActionNeeded
    } else if emitted_feedback_records.len() > 1 || skipped_count > 0 {
        GovernanceFeedbackReentryAdapterStatus::AdaptedWithWarnings
    } else {
        GovernanceFeedbackReentryAdapterStatus::Adapted
    };
    GovernanceFeedbackReentryAdapterResult {
        adapter_id: format!("{}-feedback-reentry-adapter", reentry_input.input_id),
        input_count: 1,
        emitted_feedback_count: emitted_feedback_records.len(),
        emitted_feedback_records,
        skipped_count,
        adapter_status,
        paper_only: true,
    }
}

fn dominant_governance_feedback_kind_v2(
    records: &[GovernancePolicyFeedbackRecordV2],
) -> Option<GovernancePolicyFeedbackKindV2> {
    let kinds = [
        GovernancePolicyFeedbackKindV2::BlockActualGovernance,
        GovernancePolicyFeedbackKindV2::TightenRiskFirstPolicy,
        GovernancePolicyFeedbackKindV2::ReduceVoiceCap,
        GovernancePolicyFeedbackKindV2::AddNoTradeBiasCap,
        GovernancePolicyFeedbackKindV2::AddEvidenceRequirement,
        GovernancePolicyFeedbackKindV2::IncreaseEvidenceRegimeFloor,
        GovernancePolicyFeedbackKindV2::ReduceRiskGuardCap,
        GovernancePolicyFeedbackKindV2::ProtectTrendEntryFloor,
        GovernancePolicyFeedbackKindV2::ContinuePaperTrial,
        GovernancePolicyFeedbackKindV2::NeedsMoreEvidence,
        GovernancePolicyFeedbackKindV2::NeedsMoreHistory,
    ];
    let mut best_kind = None;
    let mut best_count = 0usize;
    for kind in kinds {
        let count = records
            .iter()
            .filter(|record| record.feedback_kind == kind)
            .count();
        if count > best_count {
            best_count = count;
            best_kind = Some(kind);
        }
    }
    best_kind
}

fn governance_feedback_ingestion_from_records(
    ingestion_id: String,
    records: Vec<GovernancePolicyFeedbackRecordV2>,
) -> GovernancePolicyFeedbackIngestionResult {
    let mut by_kind = BTreeMap::new();
    let mut by_source = BTreeMap::new();
    let mut high_severity_count = 0usize;
    for record in &records {
        increment_btree_counter(
            &mut by_kind,
            governance_feedback_kind_label(record.feedback_kind),
        );
        increment_btree_counter(
            &mut by_source,
            governance_feedback_source_label(record.source),
        );
        if record.severity == PaperGovernanceAlertSeverity::High {
            high_severity_count += 1;
        }
    }
    let dominant_feedback = dominant_governance_feedback_kind_v2(&records);
    let ingestion_status = if records.is_empty() {
        GovernancePolicyFeedbackIngestionStatus::NoFeedback
    } else if records
        .iter()
        .any(|record| record.feedback_kind == GovernancePolicyFeedbackKindV2::BlockActualGovernance)
    {
        GovernancePolicyFeedbackIngestionStatus::Unsafe
    } else if high_severity_count > 0 {
        GovernancePolicyFeedbackIngestionStatus::IngestedWithWarnings
    } else {
        GovernancePolicyFeedbackIngestionStatus::Ingested
    };
    GovernancePolicyFeedbackIngestionResult {
        ingestion_id,
        feedback_count: records.len(),
        high_severity_count,
        by_kind,
        by_source,
        dominant_feedback,
        ingestion_status,
        records,
        paper_only: true,
    }
}

fn governance_feedback_v2_from_paper_feedback(
    record: &PaperGovernancePolicyFeedbackRecord,
) -> GovernancePolicyFeedbackRecordV2 {
    let source = match record.source_watchdog {
        PaperGovernancePolicyFeedbackSourceWatchdog::RiskRegression => {
            GovernancePolicyFeedbackSource::RiskRegressionWatchdog
        }
        PaperGovernancePolicyFeedbackSourceWatchdog::VoiceConcentration => {
            GovernancePolicyFeedbackSource::VoiceConcentrationWatchdog
        }
        PaperGovernancePolicyFeedbackSourceWatchdog::ContinuationGate => {
            GovernancePolicyFeedbackSource::MultiCycleContinuationGate
        }
        PaperGovernancePolicyFeedbackSourceWatchdog::EffectivenessMetrics => {
            GovernancePolicyFeedbackSource::EffectivenessMetrics
        }
    };
    let feedback_kind = match record.feedback_kind {
        PaperGovernancePolicyFeedbackKind::TightenRiskFirstPolicy => {
            GovernancePolicyFeedbackKindV2::TightenRiskFirstPolicy
        }
        PaperGovernancePolicyFeedbackKind::ReduceVoiceCap => {
            GovernancePolicyFeedbackKindV2::ReduceVoiceCap
        }
        PaperGovernancePolicyFeedbackKind::AddNoTradeBiasCap => {
            GovernancePolicyFeedbackKindV2::AddNoTradeBiasCap
        }
        PaperGovernancePolicyFeedbackKind::AddEvidenceRequirement => {
            GovernancePolicyFeedbackKindV2::AddEvidenceRequirement
        }
        PaperGovernancePolicyFeedbackKind::IncreaseEvidenceRegimeFloor => {
            GovernancePolicyFeedbackKindV2::IncreaseEvidenceRegimeFloor
        }
        PaperGovernancePolicyFeedbackKind::ReduceRiskGuardCap => {
            GovernancePolicyFeedbackKindV2::ReduceRiskGuardCap
        }
        PaperGovernancePolicyFeedbackKind::ProtectTrendEntryFloor => {
            GovernancePolicyFeedbackKindV2::ProtectTrendEntryFloor
        }
        PaperGovernancePolicyFeedbackKind::ContinuePaperTrial => {
            GovernancePolicyFeedbackKindV2::ContinuePaperTrial
        }
        PaperGovernancePolicyFeedbackKind::NeedsMoreHistory => {
            GovernancePolicyFeedbackKindV2::NeedsMoreHistory
        }
    };
    GovernancePolicyFeedbackRecordV2 {
        feedback_id: format!("{}-v2", record.feedback_id),
        source,
        feedback_kind,
        severity: record.severity,
        member_id: None,
        role: None,
        reason: record.reason.clone(),
        paper_only: true,
    }
}

pub fn merge_governance_policy_feedback_records(
    existing_feedback: &[GovernancePolicyFeedbackRecordV2],
    reentry_feedback: &[GovernancePolicyFeedbackRecordV2],
) -> MergedGovernancePolicyFeedbackSet {
    let mut seen = BTreeSet::new();
    let mut records = existing_feedback
        .iter()
        .chain(reentry_feedback.iter())
        .filter_map(|record| {
            let key = format!(
                "{}::{}::{}::{}::{}",
                governance_feedback_source_label(record.source),
                governance_feedback_kind_label(record.feedback_kind),
                record.reason,
                record.member_id.clone().unwrap_or_default(),
                record
                    .role
                    .map(|role| format!("{role:?}"))
                    .unwrap_or_default()
            );
            if seen.insert(key) {
                Some(record.clone())
            } else {
                None
            }
        })
        .collect::<Vec<_>>();
    records.sort_by(|left, right| {
        left.feedback_id
            .cmp(&right.feedback_id)
            .then_with(|| left.reason.cmp(&right.reason))
    });
    let mut source_distribution = BTreeMap::new();
    let mut high_severity_count = 0usize;
    for record in &records {
        increment_btree_counter(
            &mut source_distribution,
            governance_feedback_source_label(record.source),
        );
        if record.severity == PaperGovernanceAlertSeverity::High {
            high_severity_count += 1;
        }
    }
    let dominant_feedback = dominant_governance_feedback_kind_v2(&records);
    let merge_status = if records.is_empty() {
        MergedGovernancePolicyFeedbackSetStatus::NoFeedback
    } else if records
        .iter()
        .any(|record| record.feedback_kind == GovernancePolicyFeedbackKindV2::BlockActualGovernance)
    {
        MergedGovernancePolicyFeedbackSetStatus::Blocked
    } else if high_severity_count > 0
        || records.len() < existing_feedback.len() + reentry_feedback.len()
    {
        MergedGovernancePolicyFeedbackSetStatus::MergedWithWarnings
    } else {
        MergedGovernancePolicyFeedbackSetStatus::Merged
    };
    MergedGovernancePolicyFeedbackSet {
        set_id: format!("merged-governance-feedback-set-{}", records.len()),
        record_count: records.len(),
        high_severity_count,
        source_distribution,
        dominant_feedback,
        merge_status,
        records,
        policy_apply_allowed: false,
        paper_only: true,
    }
}

fn default_governance_outcome_feedback_reentry_policy() -> ConservativeVoiceTuningV2Policy {
    ConservativeVoiceTuningV2Policy {
        policy_id: "default-governance-outcome-feedback-reentry-policy".to_string(),
        previous_voice_delta_cap: 0.10,
        tuned_voice_delta_cap_v2: 0.08,
        risk_guard_min_voice_share: 0.20,
        risk_guard_max_voice_share: 0.45,
        trend_entry_min_voice_share: 0.18,
        evidence_regime_min_voice_share: 0.16,
        compounding_brake_enabled: true,
        max_consecutive_voice_increases_per_member: 1,
        max_consecutive_voice_decreases_per_member: 3,
        dampen_low_evidence_delta: true,
        low_evidence_dampening_factor: 0.50,
        preserve_risk_first: true,
        actual_voice_apply_allowed: false,
        actual_score_apply_allowed: false,
        promotion_demotion_allowed: false,
        risk_governor_override_allowed: false,
        paper_only: true,
    }
}

fn proxy_latest_paper_trial_results_from_feedback_bridge(
    feedback_bridge_result: &PaperPolicyOutcomeFeedbackBridgeRunResult,
) -> PaperGovernanceTrialMultiCycleResult {
    let completed_cycle_count = feedback_bridge_result
        .continuation_ledger
        .entry_count
        .max(2);
    let focus = feedback_bridge_result.tuning_input.recommended_tuning_focus;
    let risk_alignment_worsening_rate = match focus {
        GovernanceOutcomeFeedbackRecommendedTuningFocus::RiskPolicy
        | GovernanceOutcomeFeedbackRecommendedTuningFocus::SafetyBlock => 0.18,
        GovernanceOutcomeFeedbackRecommendedTuningFocus::EvidenceQuality
        | GovernanceOutcomeFeedbackRecommendedTuningFocus::OwnerExplanation => 0.08,
        _ => 0.0,
    };
    let voice_concentration_index = match focus {
        GovernanceOutcomeFeedbackRecommendedTuningFocus::VoiceBalance => 0.72,
        GovernanceOutcomeFeedbackRecommendedTuningFocus::SafetyBlock => 0.60,
        _ => 0.38,
    };
    let no_trade_bias_rate = match focus {
        GovernanceOutcomeFeedbackRecommendedTuningFocus::NoTradeBias => 0.72,
        GovernanceOutcomeFeedbackRecommendedTuningFocus::SafetyBlock => 0.60,
        _ => 0.24,
    };
    let risk_regression_status = projected_risk_status(
        completed_cycle_count,
        risk_alignment_worsening_rate,
        no_trade_bias_rate,
    );
    let voice_concentration_status =
        projected_voice_status(completed_cycle_count, voice_concentration_index);
    let effectiveness_status =
        if focus == GovernanceOutcomeFeedbackRecommendedTuningFocus::SafetyBlock {
            PaperGovernanceEffectivenessStatus::Risky
        } else if risk_alignment_worsening_rate > 0.0
            || voice_concentration_index > 0.50
            || no_trade_bias_rate > 0.60
        {
            PaperGovernanceEffectivenessStatus::EffectiveWithWarnings
        } else {
            PaperGovernanceEffectivenessStatus::Effective
        };
    let policy_feedback_status = if feedback_bridge_result.tuning_input.should_stop_paper_trial {
        PaperGovernancePolicyFeedbackStatus::BlockActualGovernance
    } else if feedback_bridge_result
        .tuning_input
        .should_collect_more_evidence
    {
        PaperGovernancePolicyFeedbackStatus::CollectMoreEvidence
    } else if focus == GovernanceOutcomeFeedbackRecommendedTuningFocus::None {
        PaperGovernancePolicyFeedbackStatus::ContinueTrial
    } else {
        PaperGovernancePolicyFeedbackStatus::TunePolicy
    };
    let dominant_paper_feedback = match policy_feedback_status {
        PaperGovernancePolicyFeedbackStatus::ContinueTrial => {
            Some(PaperGovernancePolicyFeedbackKind::ContinuePaperTrial)
        }
        PaperGovernancePolicyFeedbackStatus::TunePolicy => match focus {
            GovernanceOutcomeFeedbackRecommendedTuningFocus::RiskPolicy => {
                Some(PaperGovernancePolicyFeedbackKind::TightenRiskFirstPolicy)
            }
            GovernanceOutcomeFeedbackRecommendedTuningFocus::VoiceBalance => {
                Some(PaperGovernancePolicyFeedbackKind::ReduceVoiceCap)
            }
            GovernanceOutcomeFeedbackRecommendedTuningFocus::NoTradeBias => {
                Some(PaperGovernancePolicyFeedbackKind::AddNoTradeBiasCap)
            }
            _ => Some(PaperGovernancePolicyFeedbackKind::AddEvidenceRequirement),
        },
        PaperGovernancePolicyFeedbackStatus::CollectMoreEvidence => {
            Some(PaperGovernancePolicyFeedbackKind::NeedsMoreHistory)
        }
        PaperGovernancePolicyFeedbackStatus::BlockActualGovernance
        | PaperGovernancePolicyFeedbackStatus::InsufficientHistory => None,
    };
    let continuation_status = if feedback_bridge_result.tuning_input.should_stop_paper_trial {
        PaperGovernanceMultiCycleContinuationGateReadinessStatus::BlockedBySafety
    } else if feedback_bridge_result
        .tuning_input
        .should_continue_paper_execution
    {
        PaperGovernanceMultiCycleContinuationGateReadinessStatus::ContinuePaperTrial
    } else if feedback_bridge_result
        .tuning_input
        .should_collect_more_evidence
    {
        PaperGovernanceMultiCycleContinuationGateReadinessStatus::NeedsMoreHistory
    } else {
        PaperGovernanceMultiCycleContinuationGateReadinessStatus::NeedsPolicyTuning
    };
    PaperGovernanceTrialMultiCycleResult {
        run_id: format!("{}-proxy-paper-trial-result", feedback_bridge_result.run_id),
        requested_cycle_count: completed_cycle_count,
        completed_cycle_count,
        previous_ledger_entry_count: completed_cycle_count.saturating_sub(1),
        appended_entry_count: 1,
        final_ledger_entry_count: completed_cycle_count,
        per_cycle_results: vec![PerCyclePaperGovernanceTrialResult {
            cycle_index: completed_cycle_count,
            ledger_entry_id: feedback_bridge_result
                .continuation_ledger
                .latest_entry_id
                .clone(),
            counterfactual_changed_count: 0,
            risk_alignment_improvement_rate: 0.0,
            risk_alignment_worsening_rate,
            voice_concentration_index,
            no_trade_bias_rate,
            continuation_gate_status: if feedback_bridge_result
                .tuning_input
                .should_continue_paper_execution
            {
                PaperGovernanceContinuationGateReadinessStatus::ContinuePaperTrial
            } else if feedback_bridge_result
                .tuning_input
                .should_collect_more_evidence
            {
                PaperGovernanceContinuationGateReadinessStatus::NeedsMoreTrialHistory
            } else if feedback_bridge_result.tuning_input.should_stop_paper_trial {
                PaperGovernanceContinuationGateReadinessStatus::BlockedBySafety
            } else {
                PaperGovernanceContinuationGateReadinessStatus::NeedsPolicyTuning
            },
            safety_status: PaperGovernanceTrialSafetyGuardStatus::Preserved,
            paper_only: true,
        }],
        aggregate_effectiveness_metrics: PaperGovernanceEffectivenessMetrics {
            metrics_id: format!("{}-proxy-effectiveness", feedback_bridge_result.run_id),
            trial_entry_count: completed_cycle_count,
            counterfactual_changed_count: 0,
            risk_alignment_improvement_rate: 0.0,
            risk_alignment_worsening_rate,
            evidence_caution_rate: if feedback_bridge_result
                .tuning_input
                .should_collect_more_evidence
            {
                0.60
            } else {
                0.20
            },
            no_trade_bias_rate,
            overconfident_call_reduction_count: 0,
            helpful_dissent_rewarded_count: 0,
            voice_concentration_index,
            trend_entry_suppression_score: if focus
                == GovernanceOutcomeFeedbackRecommendedTuningFocus::VoiceBalance
            {
                0.12
            } else {
                0.04
            },
            evidence_regime_underweight_score: if matches!(
                focus,
                GovernanceOutcomeFeedbackRecommendedTuningFocus::EvidenceQuality
                    | GovernanceOutcomeFeedbackRecommendedTuningFocus::OwnerExplanation
            ) {
                0.16
            } else {
                0.05
            },
            risk_guard_dominance_score: if focus
                == GovernanceOutcomeFeedbackRecommendedTuningFocus::VoiceBalance
            {
                0.55
            } else {
                0.38
            },
            effectiveness_status,
            paper_only: true,
        },
        aggregate_risk_first_check: PaperGovernanceRiskFirstEffectivenessCheck {
            check_id: format!("{}-proxy-risk-first", feedback_bridge_result.run_id),
            risk_alignment_improved: false,
            risk_alignment_worsened: risk_alignment_worsening_rate > 0.0,
            reckless_buy_reduced: false,
            helpful_risk_dissent_preserved: true,
            risk_guard_dominance_detected: focus
                == GovernanceOutcomeFeedbackRecommendedTuningFocus::VoiceBalance,
            excessive_no_trade_bias_detected: focus
                == GovernanceOutcomeFeedbackRecommendedTuningFocus::NoTradeBias,
            risk_first_status: if focus
                == GovernanceOutcomeFeedbackRecommendedTuningFocus::RiskPolicy
            {
                PaperGovernanceRiskFirstStatus::Violated
            } else if risk_alignment_worsening_rate > 0.0 {
                PaperGovernanceRiskFirstStatus::PreservedWithWarnings
            } else {
                PaperGovernanceRiskFirstStatus::Preserved
            },
            warnings: Vec::new(),
            paper_only: true,
        },
        aggregate_continuation_gate: PaperGovernanceMultiCycleContinuationGate {
            gate_id: format!("{}-proxy-continuation-gate", feedback_bridge_result.run_id),
            cycle_count: completed_cycle_count,
            risk_regression_status,
            voice_concentration_status,
            effectiveness_status,
            risk_first_status: if focus
                == GovernanceOutcomeFeedbackRecommendedTuningFocus::RiskPolicy
            {
                PaperGovernanceRiskFirstStatus::Violated
            } else {
                PaperGovernanceRiskFirstStatus::Preserved
            },
            safety_status: PaperGovernanceTrialSafetyGuardStatus::Preserved,
            continue_paper_trial: feedback_bridge_result
                .tuning_input
                .should_continue_paper_execution,
            readiness_status: continuation_status,
            blockers: Vec::new(),
            warnings: Vec::new(),
            paper_only: true,
        },
        risk_regression_watchdog: PaperGovernanceRiskRegressionWatchdog {
            watchdog_id: format!("{}-proxy-risk-watchdog", feedback_bridge_result.run_id),
            record_count: 0,
            high_severity_count: if risk_regression_status
                == PaperGovernanceRiskRegressionWatchdogStatus::RegressionDetected
            {
                1
            } else {
                0
            },
            regression_detected: risk_regression_status
                == PaperGovernanceRiskRegressionWatchdogStatus::RegressionDetected,
            dominant_signals: if risk_regression_status
                == PaperGovernanceRiskRegressionWatchdogStatus::RegressionDetected
            {
                vec![PaperGovernanceRiskRegressionSignal::RiskAlignmentWorsened]
            } else {
                vec![PaperGovernanceRiskRegressionSignal::NoRegression]
            },
            records: Vec::new(),
            watchdog_status: risk_regression_status,
            paper_only: true,
        },
        voice_concentration_watchdog: PaperGovernanceVoiceConcentrationWatchdog {
            watchdog_id: format!("{}-proxy-voice-watchdog", feedback_bridge_result.run_id),
            record_count: 0,
            high_severity_count: if voice_concentration_status
                == PaperGovernanceVoiceConcentrationWatchdogStatus::Concentrated
            {
                1
            } else {
                0
            },
            concentration_detected: voice_concentration_status
                == PaperGovernanceVoiceConcentrationWatchdogStatus::Concentrated,
            dominant_signals: if voice_concentration_status
                == PaperGovernanceVoiceConcentrationWatchdogStatus::Concentrated
            {
                vec![PaperGovernanceVoiceConcentrationSignal::RiskGuardDominance]
            } else {
                vec![PaperGovernanceVoiceConcentrationSignal::HealthyDistribution]
            },
            records: Vec::new(),
            watchdog_status: voice_concentration_status,
            paper_only: true,
        },
        policy_feedback: PaperGovernancePolicyFeedbackSummary {
            summary_id: format!("{}-proxy-policy-feedback", feedback_bridge_result.run_id),
            feedback_count: usize::from(dominant_paper_feedback.is_some()),
            high_severity_count: usize::from(
                feedback_bridge_result.tuning_input.should_stop_paper_trial
                    || focus == GovernanceOutcomeFeedbackRecommendedTuningFocus::RiskPolicy,
            ),
            dominant_feedback: dominant_paper_feedback,
            feedback_status: policy_feedback_status,
            records: Vec::new(),
            paper_only: true,
        },
        safety_guard: PaperGovernanceMultiCycleSafetyGuard {
            actual_score_mutation_detected: false,
            actual_voice_mutation_detected: false,
            committee_decision_mutation_detected: false,
            chairman_decision_mutation_detected: false,
            risk_governor_mutation_detected: false,
            member_opinion_mutation_detected: false,
            paper_trial_used_as_live_decision_detected: false,
            trade_signal_detected: false,
            order_detected: false,
            broker_order_account_detected: false,
            ledger_write_when_dry_run_detected: false,
            unsafe_continuation_gate_open_detected: false,
            guard_status: PaperGovernanceTrialSafetyGuardStatus::Preserved,
            violations: Vec::new(),
            paper_only: true,
        },
        ledger_write_proof: None,
        owner_summary: None,
        run_status: PaperGovernanceTrialRunStatus::PassedWithWarnings,
        dry_run: true,
        wrote_ledger: false,
        ledger_output_path: None,
        paper_only: true,
    }
}

pub fn generate_governance_reentry_tuning_proposals(
    merged_feedback_set: &MergedGovernancePolicyFeedbackSet,
    baseline_policy: &ConservativeVoiceTuningV2Policy,
) -> GovernanceReentryProposalGenerationResult {
    if merged_feedback_set.merge_status == MergedGovernancePolicyFeedbackSetStatus::Blocked {
        return GovernanceReentryProposalGenerationResult {
            generation_id: format!("{}-reentry-proposal-generation", merged_feedback_set.set_id),
            merged_feedback_set_id: merged_feedback_set.set_id.clone(),
            proposal_count: 0,
            conservative_proposal_count: 0,
            keep_policy_count: 0,
            tuning_proposal_count: 0,
            rejected_proposal_count: 0,
            proposals: Vec::new(),
            generation_status: GovernanceReentryProposalGenerationStatus::Blocked,
            paper_only: true,
        };
    }
    let generation = generate_governance_tuning_proposals(
        &governance_feedback_ingestion_from_records(
            format!("{}-merged-ingestion", merged_feedback_set.set_id),
            merged_feedback_set.records.clone(),
        ),
        baseline_policy,
    );
    let keep_policy_count = generation
        .candidates
        .iter()
        .filter(|proposal| {
            proposal.actions.len() == 1
                && proposal.actions[0] == GovernanceTuningProposalAction::KeepPolicyUnchanged
        })
        .count();
    let tuning_proposal_count = generation
        .candidates
        .len()
        .saturating_sub(keep_policy_count);
    let generation_status = if generation.candidates.is_empty() {
        GovernanceReentryProposalGenerationStatus::NoProposalNeeded
    } else if keep_policy_count == generation.candidates.len() {
        GovernanceReentryProposalGenerationStatus::KeepPolicyRecommended
    } else if generation.rejected_candidate_count > 0
        || merged_feedback_set.merge_status
            == MergedGovernancePolicyFeedbackSetStatus::MergedWithWarnings
        || generation.generation_status
            == GovernanceTuningProposalGenerationStatus::GeneratedWithWarnings
    {
        GovernanceReentryProposalGenerationStatus::GeneratedWithWarnings
    } else {
        GovernanceReentryProposalGenerationStatus::Generated
    };
    GovernanceReentryProposalGenerationResult {
        generation_id: format!("{}-reentry-proposal-generation", generation.generation_id),
        merged_feedback_set_id: merged_feedback_set.set_id.clone(),
        proposal_count: generation.candidates.len(),
        conservative_proposal_count: generation.conservative_candidate_count,
        keep_policy_count,
        tuning_proposal_count,
        rejected_proposal_count: generation.rejected_candidate_count,
        proposals: generation.candidates,
        generation_status,
        paper_only: true,
    }
}

pub fn compare_governance_reentry_proposals_ab(
    proposals: &[GovernanceTuningProposalCandidate],
    baseline_policy: &ConservativeVoiceTuningV2Policy,
    latest_paper_trial_results: &PaperGovernanceTrialMultiCycleResult,
) -> GovernanceReentryABComparisonResult {
    if proposals.is_empty() {
        return GovernanceReentryABComparisonResult {
            comparison_id: "governance-reentry-ab-comparison-empty".to_string(),
            proposal_count: 0,
            compared_count: 0,
            improved_count: 0,
            worsened_count: 0,
            keep_policy_count: 0,
            best_proposal_id: None,
            comparison_status: GovernanceReentryABComparisonStatus::NoComparisonNeeded,
            records: Vec::new(),
            paper_only: true,
        };
    }
    let base_comparison = compare_governance_tuning_proposals_ab(
        proposals,
        baseline_policy,
        latest_paper_trial_results,
    );
    let keep_policy_proposal = proposals.iter().find(|proposal| {
        proposal.actions.len() == 1
            && proposal.actions[0] == GovernanceTuningProposalAction::KeepPolicyUnchanged
    });
    let keep_policy_count = proposals
        .iter()
        .filter(|proposal| {
            proposal.actions.len() == 1
                && proposal.actions[0] == GovernanceTuningProposalAction::KeepPolicyUnchanged
        })
        .count();
    let keep_policy_best = keep_policy_proposal.is_some()
        && (keep_policy_count == proposals.len()
            || (base_comparison.worsened_count == 0 && base_comparison.improved_count == 0));
    GovernanceReentryABComparisonResult {
        comparison_id: format!("{}-reentry-ab-comparison", base_comparison.comparison_id),
        proposal_count: proposals.len(),
        compared_count: base_comparison.record_count,
        improved_count: base_comparison.improved_count,
        worsened_count: base_comparison.worsened_count,
        keep_policy_count,
        best_proposal_id: if keep_policy_best {
            keep_policy_proposal.map(|proposal| proposal.proposal_id.clone())
        } else {
            base_comparison.best_proposal_id
        },
        comparison_status: if keep_policy_best {
            GovernanceReentryABComparisonStatus::KeepPolicyBest
        } else if base_comparison.record_count == 0 {
            GovernanceReentryABComparisonStatus::NoComparisonNeeded
        } else if base_comparison.worsened_count > 0
            || base_comparison.comparison_status
                == GovernancePolicyABComparisonStatus::ComparedWithWarnings
        {
            GovernanceReentryABComparisonStatus::ComparedWithWarnings
        } else {
            GovernanceReentryABComparisonStatus::Compared
        },
        records: base_comparison.records,
        paper_only: true,
    }
}

fn governance_reentry_ab_status_to_v2(
    status: GovernanceReentryABComparisonStatus,
) -> GovernancePolicyABComparisonStatus {
    match status {
        GovernanceReentryABComparisonStatus::Compared
        | GovernanceReentryABComparisonStatus::KeepPolicyBest => {
            GovernancePolicyABComparisonStatus::Compared
        }
        GovernanceReentryABComparisonStatus::ComparedWithWarnings => {
            GovernancePolicyABComparisonStatus::ComparedWithWarnings
        }
        GovernanceReentryABComparisonStatus::NoComparisonNeeded => {
            GovernancePolicyABComparisonStatus::NoImprovement
        }
        GovernanceReentryABComparisonStatus::Blocked => GovernancePolicyABComparisonStatus::Failed,
    }
}

pub fn rank_governance_reentry_proposals(
    comparison_result: &GovernanceReentryABComparisonResult,
    merged_feedback_set: &MergedGovernancePolicyFeedbackSet,
    proposals: &[GovernanceTuningProposalCandidate],
) -> GovernanceReentryProposalRankingResult {
    if merged_feedback_set.merge_status == MergedGovernancePolicyFeedbackSetStatus::Blocked {
        return GovernanceReentryProposalRankingResult {
            ranking_id: format!("{}-reentry-ranking", comparison_result.comparison_id),
            ranked_proposals: Vec::new(),
            recommended_proposal_id: None,
            recommended_action: GovernanceReentryRecommendedAction::BlockActualGovernance,
            ranking_status: GovernanceReentryProposalRankingStatus::Blocked,
            policy_apply_allowed: false,
            paper_only: true,
        };
    }
    if comparison_result.comparison_status == GovernanceReentryABComparisonStatus::KeepPolicyBest {
        let recommended_proposal_id = comparison_result.best_proposal_id.clone().or_else(|| {
            proposals
                .iter()
                .find(|proposal| {
                    proposal.actions.len() == 1
                        && proposal.actions[0]
                            == GovernanceTuningProposalAction::KeepPolicyUnchanged
                })
                .map(|proposal| proposal.proposal_id.clone())
        });
        let ranked_proposals = recommended_proposal_id
            .as_ref()
            .map(|proposal_id| {
                vec![GovernanceTuningProposalRank {
                    proposal_id: proposal_id.clone(),
                    safety_score: 100.0,
                    risk_first_score: 100.0,
                    concentration_score: 100.0,
                    no_trade_bias_score: 100.0,
                    evidence_balance_score: 100.0,
                    role_balance_score: 100.0,
                    total_score: 100.0,
                    rank: 1,
                    rank_status: GovernanceTuningProposalRankStatus::Recommended,
                    reason: "keep current policy unchanged while continuing paper trial"
                        .to_string(),
                    paper_only: true,
                }]
            })
            .unwrap_or_default();
        return GovernanceReentryProposalRankingResult {
            ranking_id: format!("{}-reentry-ranking", comparison_result.comparison_id),
            ranked_proposals,
            recommended_proposal_id,
            recommended_action: GovernanceReentryRecommendedAction::KeepPolicy,
            ranking_status: GovernanceReentryProposalRankingStatus::KeepPolicyRecommended,
            policy_apply_allowed: false,
            paper_only: true,
        };
    }
    let base_ranking = rank_governance_tuning_proposals(
        &GovernancePolicyABComparisonResult {
            comparison_id: comparison_result.comparison_id.clone(),
            baseline_policy_id: "reentry-baseline-policy".to_string(),
            proposal_count: comparison_result.proposal_count,
            record_count: comparison_result.records.len(),
            improved_count: comparison_result.improved_count,
            worsened_count: comparison_result.worsened_count,
            neutral_count: comparison_result.records.len().saturating_sub(
                comparison_result.improved_count + comparison_result.worsened_count,
            ),
            best_proposal_id: comparison_result.best_proposal_id.clone(),
            comparison_status: governance_reentry_ab_status_to_v2(
                comparison_result.comparison_status,
            ),
            records: comparison_result.records.clone(),
            paper_only: true,
        },
        &governance_feedback_ingestion_from_records(
            format!(
                "{}-reentry-ranking-ingestion",
                comparison_result.comparison_id
            ),
            merged_feedback_set.records.clone(),
        ),
    );
    let recommended_proposal_id = base_ranking.recommended_proposal_id.clone();
    let recommended_action = if let Some(proposal_id) = recommended_proposal_id.as_ref() {
        if proposals.iter().any(|proposal| {
            &proposal.proposal_id == proposal_id
                && proposal.actions.len() == 1
                && proposal.actions[0] == GovernanceTuningProposalAction::KeepPolicyUnchanged
        }) {
            GovernanceReentryRecommendedAction::KeepPolicy
        } else {
            GovernanceReentryRecommendedAction::TunePolicy
        }
    } else if merged_feedback_set.dominant_feedback.is_some_and(|kind| {
        matches!(
            kind,
            GovernancePolicyFeedbackKindV2::NeedsMoreEvidence
                | GovernancePolicyFeedbackKindV2::NeedsMoreHistory
        )
    }) {
        GovernanceReentryRecommendedAction::CollectMoreEvidence
    } else {
        GovernanceReentryRecommendedAction::ContinuePaperTrial
    };
    let ranking_status = if recommended_proposal_id.is_some()
        && recommended_action == GovernanceReentryRecommendedAction::TunePolicy
        && base_ranking.ranking_status
            == GovernanceTuningProposalRankingStatus::RecommendationWithWarnings
    {
        GovernanceReentryProposalRankingStatus::RecommendationWithWarnings
    } else if recommended_proposal_id.is_some() {
        GovernanceReentryProposalRankingStatus::RecommendationAvailable
    } else if recommended_action == GovernanceReentryRecommendedAction::CollectMoreEvidence {
        GovernanceReentryProposalRankingStatus::NeedsMoreEvidence
    } else {
        GovernanceReentryProposalRankingStatus::RecommendationWithWarnings
    };
    GovernanceReentryProposalRankingResult {
        ranking_id: format!("{}-reentry-ranking", base_ranking.ranking_id),
        ranked_proposals: base_ranking.ranked_proposals,
        recommended_proposal_id,
        recommended_action,
        ranking_status,
        policy_apply_allowed: false,
        paper_only: true,
    }
}

pub fn evaluate_governance_recommendation_apply_gate_lock(
    ranking: &GovernanceReentryProposalRankingResult,
    merged_feedback_set: &MergedGovernancePolicyFeedbackSet,
) -> GovernanceRecommendationApplyGateLock {
    let mut violations = Vec::new();
    if ranking.policy_apply_allowed {
        violations.push("reentry ranking opened policy_apply_allowed".to_string());
    }
    if merged_feedback_set
        .records
        .iter()
        .any(|record| record.feedback_kind == GovernancePolicyFeedbackKindV2::BlockActualGovernance)
        && matches!(
            ranking.recommended_action,
            GovernanceReentryRecommendedAction::KeepPolicy
                | GovernanceReentryRecommendedAction::ContinuePaperTrial
        )
    {
        violations.push("unsafe keep-policy recommendation under safety block".to_string());
    }
    let lock_status = if !violations.is_empty() {
        GovernanceRecommendationApplyGateLockStatus::Violated
    } else if matches!(
        ranking.ranking_status,
        GovernanceReentryProposalRankingStatus::RecommendationWithWarnings
            | GovernanceReentryProposalRankingStatus::NeedsMoreEvidence
    ) {
        GovernanceRecommendationApplyGateLockStatus::LockedWithWarnings
    } else {
        GovernanceRecommendationApplyGateLockStatus::Locked
    };
    GovernanceRecommendationApplyGateLock {
        lock_id: format!("{}-apply-gate-lock", ranking.ranking_id),
        policy_apply_allowed: false,
        recommended_action: ranking.recommended_action,
        recommended_proposal_id: ranking.recommended_proposal_id.clone(),
        apply_locked: true,
        reason: match ranking.recommended_action {
            GovernanceReentryRecommendedAction::KeepPolicy => {
                "strong paper-only outcome feedback recommends keeping policy unchanged".to_string()
            }
            GovernanceReentryRecommendedAction::TunePolicy => {
                "paper-only outcome feedback recommends a conservative tuning proposal".to_string()
            }
            GovernanceReentryRecommendedAction::ContinuePaperTrial => {
                "paper-only outcome feedback recommends continuing the trial only".to_string()
            }
            GovernanceReentryRecommendedAction::CollectMoreEvidence => {
                "paper-only outcome feedback still needs more evidence before recommendation refresh"
                    .to_string()
            }
            GovernanceReentryRecommendedAction::BlockActualGovernance => {
                "safety feedback keeps actual governance blocked".to_string()
            }
        },
        lock_status,
        violations,
        paper_only: true,
    }
}

fn feedback_summary_status_from_reentry_input(
    reentry_input: &GovernanceOutcomeFeedbackReentryInput,
) -> GovernanceOutcomeFeedbackSummaryStatus {
    if reentry_input.should_stop_paper_trial
        || reentry_input.tuning_focus
            == GovernanceOutcomeFeedbackRecommendedTuningFocus::SafetyBlock
    {
        GovernanceOutcomeFeedbackSummaryStatus::Blocked
    } else if reentry_input.should_collect_more_evidence
        && reentry_input.tuning_focus == GovernanceOutcomeFeedbackRecommendedTuningFocus::None
    {
        GovernanceOutcomeFeedbackSummaryStatus::EvidenceNeeded
    } else if reentry_input.tuning_focus != GovernanceOutcomeFeedbackRecommendedTuningFocus::None {
        GovernanceOutcomeFeedbackSummaryStatus::TuningRecommended
    } else if reentry_input.should_continue_paper_execution {
        GovernanceOutcomeFeedbackSummaryStatus::ContinueRecommended
    } else {
        GovernanceOutcomeFeedbackSummaryStatus::ContinueWithWarnings
    }
}

pub fn build_owner_governance_recommendation_pipeline_refresh_summary(
    refresh_result: &GovernanceRecommendationPipelineRefreshResult,
) -> OwnerGovernanceRecommendationPipelineRefreshSummary {
    OwnerGovernanceRecommendationPipelineRefreshSummary {
            summary_id: format!("{}-owner-refresh-summary", refresh_result.refresh_id),
            feedback_summary_status: feedback_summary_status_from_reentry_input(
                &refresh_result.reentry_input,
            ),
            tuning_focus: refresh_result.reentry_input.tuning_focus,
            recommended_action: refresh_result.ranking.recommended_action,
            recommended_proposal_id: refresh_result.ranking.recommended_proposal_id.clone(),
            apply_locked: true,
            message: "Outcome feedback was routed back into the recommendation pipeline. The result is recommendation-only. Policy apply remains locked. Actual score, voice, decisions, Risk Governor, and trading remain unchanged."
                .to_string(),
            recommendation_only: true,
            no_actual_policy_apply: true,
            no_score_mutation: true,
            no_voice_mutation: true,
            no_committee_decision_change: true,
            no_risk_override: true,
            not_trade_signal: true,
            paper_only: true,
        }
}

fn governance_recommendation_pipeline_refresh_status(
    proposal_generation: &GovernanceReentryProposalGenerationResult,
    ranking: &GovernanceReentryProposalRankingResult,
    apply_gate_lock: &GovernanceRecommendationApplyGateLock,
) -> GovernanceRecommendationPipelineRefreshStatus {
    if proposal_generation.generation_status == GovernanceReentryProposalGenerationStatus::Blocked
        || ranking.ranking_status == GovernanceReentryProposalRankingStatus::Blocked
        || apply_gate_lock.lock_status == GovernanceRecommendationApplyGateLockStatus::Violated
    {
        GovernanceRecommendationPipelineRefreshStatus::Blocked
    } else if proposal_generation.generation_status
        == GovernanceReentryProposalGenerationStatus::NoProposalNeeded
        || ranking.ranking_status == GovernanceReentryProposalRankingStatus::KeepPolicyRecommended
    {
        GovernanceRecommendationPipelineRefreshStatus::NoActionNeeded
    } else if matches!(
        proposal_generation.generation_status,
        GovernanceReentryProposalGenerationStatus::GeneratedWithWarnings
    ) || matches!(
        ranking.ranking_status,
        GovernanceReentryProposalRankingStatus::RecommendationWithWarnings
            | GovernanceReentryProposalRankingStatus::NeedsMoreEvidence
    ) || matches!(
        apply_gate_lock.lock_status,
        GovernanceRecommendationApplyGateLockStatus::LockedWithWarnings
    ) {
        GovernanceRecommendationPipelineRefreshStatus::RefreshedWithWarnings
    } else {
        GovernanceRecommendationPipelineRefreshStatus::Refreshed
    }
}

pub fn refresh_governance_recommendation_pipeline_from_outcome_feedback(
    feedback_bridge_result: &PaperPolicyOutcomeFeedbackBridgeRunResult,
    baseline_policy: &ConservativeVoiceTuningV2Policy,
    latest_paper_trial_results: &PaperGovernanceTrialMultiCycleResult,
    config: &GovernanceOutcomeFeedbackReentryRunConfig,
) -> Result<GovernanceRecommendationPipelineRefreshResult, String> {
    if !config.paper_only {
        return Err("governance outcome feedback reentry refresh must stay paper_only".to_string());
    }
    let reentry_input = build_governance_outcome_feedback_reentry_input(feedback_bridge_result);
    let adapter_result = adapt_outcome_feedback_to_governance_policy_feedback(&reentry_input);
    let existing_feedback = latest_paper_trial_results
        .policy_feedback
        .records
        .iter()
        .map(governance_feedback_v2_from_paper_feedback)
        .collect::<Vec<_>>();
    let merged_feedback_set = merge_governance_policy_feedback_records(
        &existing_feedback,
        &adapter_result.emitted_feedback_records,
    );
    let proposal_generation =
        generate_governance_reentry_tuning_proposals(&merged_feedback_set, baseline_policy);
    let ab_comparison =
        if merged_feedback_set.merge_status == MergedGovernancePolicyFeedbackSetStatus::Blocked {
            GovernanceReentryABComparisonResult {
                comparison_id: format!(
                    "{}-reentry-ab-comparison",
                    proposal_generation.generation_id
                ),
                proposal_count: proposal_generation.proposals.len(),
                compared_count: 0,
                improved_count: 0,
                worsened_count: 0,
                keep_policy_count: proposal_generation.keep_policy_count,
                best_proposal_id: None,
                comparison_status: GovernanceReentryABComparisonStatus::Blocked,
                records: Vec::new(),
                paper_only: true,
            }
        } else {
            compare_governance_reentry_proposals_ab(
                &proposal_generation.proposals,
                baseline_policy,
                latest_paper_trial_results,
            )
        };
    let ranking = rank_governance_reentry_proposals(
        &ab_comparison,
        &merged_feedback_set,
        &proposal_generation.proposals,
    );
    let apply_gate_lock =
        evaluate_governance_recommendation_apply_gate_lock(&ranking, &merged_feedback_set);
    let mut refresh_result = GovernanceRecommendationPipelineRefreshResult {
        refresh_id: format!("{}-recommendation-pipeline-refresh", config.run_id),
        reentry_input,
        adapter_result,
        merged_feedback_set,
        proposal_generation,
        ab_comparison,
        ranking,
        apply_gate_lock,
        owner_summary: None,
        refresh_status: GovernanceRecommendationPipelineRefreshStatus::Refreshed,
        paper_only: true,
    };
    if config.emit_owner_summary {
        refresh_result.owner_summary =
            Some(build_owner_governance_recommendation_pipeline_refresh_summary(&refresh_result));
    }
    refresh_result.refresh_status = governance_recommendation_pipeline_refresh_status(
        &refresh_result.proposal_generation,
        &refresh_result.ranking,
        &refresh_result.apply_gate_lock,
    );
    Ok(refresh_result)
}

fn governance_recommendation_entry_from_reentry_refresh(
    refresh_result: &GovernanceRecommendationPipelineRefreshResult,
) -> GovernanceRecommendationLedgerEntry {
    let best_rank = refresh_result
        .ranking
        .ranked_proposals
        .iter()
        .find(|rank| {
            refresh_result
                .ranking
                .recommended_proposal_id
                .as_ref()
                .is_some_and(|proposal_id| proposal_id == &rank.proposal_id)
        })
        .or_else(|| refresh_result.ranking.ranked_proposals.first());
    GovernanceRecommendationLedgerEntry {
        entry_id: format!("{}-recommendation-ledger-entry", refresh_result.refresh_id),
        run_id: refresh_result.refresh_id.clone(),
        recommendation_gate_status: match refresh_result.ranking.ranking_status {
            GovernanceReentryProposalRankingStatus::RecommendationAvailable
            | GovernanceReentryProposalRankingStatus::KeepPolicyRecommended => {
                GovernanceTuningRecommendationGateStatus::RecommendationReady
            }
            GovernanceReentryProposalRankingStatus::RecommendationWithWarnings => {
                GovernanceTuningRecommendationGateStatus::RecommendationReadyWithWarnings
            }
            GovernanceReentryProposalRankingStatus::NeedsMoreEvidence => {
                GovernanceTuningRecommendationGateStatus::NeedsMoreEvidence
            }
            GovernanceReentryProposalRankingStatus::Blocked => {
                GovernanceTuningRecommendationGateStatus::BlockedBySafety
            }
        },
        recommended_proposal_id: refresh_result.ranking.recommended_proposal_id.clone(),
        ranking_status: match refresh_result.ranking.ranking_status {
            GovernanceReentryProposalRankingStatus::RecommendationAvailable
            | GovernanceReentryProposalRankingStatus::KeepPolicyRecommended => {
                GovernanceTuningProposalRankingStatus::RecommendationAvailable
            }
            GovernanceReentryProposalRankingStatus::RecommendationWithWarnings => {
                GovernanceTuningProposalRankingStatus::RecommendationWithWarnings
            }
            GovernanceReentryProposalRankingStatus::NeedsMoreEvidence => {
                GovernanceTuningProposalRankingStatus::InsufficientEvidence
            }
            GovernanceReentryProposalRankingStatus::Blocked => {
                GovernanceTuningProposalRankingStatus::NoSafeRecommendation
            }
        },
        ab_comparison_status: governance_reentry_ab_status_to_v2(
            refresh_result.ab_comparison.comparison_status,
        ),
        feedback_status: if refresh_result.merged_feedback_set.merge_status
            == MergedGovernancePolicyFeedbackSetStatus::Blocked
        {
            GovernancePolicyFeedbackIngestionStatus::Unsafe
        } else if refresh_result.merged_feedback_set.merge_status
            == MergedGovernancePolicyFeedbackSetStatus::NoFeedback
        {
            GovernancePolicyFeedbackIngestionStatus::NoFeedback
        } else if refresh_result.merged_feedback_set.merge_status
            == MergedGovernancePolicyFeedbackSetStatus::MergedWithWarnings
        {
            GovernancePolicyFeedbackIngestionStatus::IngestedWithWarnings
        } else {
            GovernancePolicyFeedbackIngestionStatus::Ingested
        },
        safety_status: if refresh_result.apply_gate_lock.lock_status
            == GovernanceRecommendationApplyGateLockStatus::Violated
        {
            PaperGovernanceTrialSafetyGuardStatus::Violated
        } else {
            PaperGovernanceTrialSafetyGuardStatus::Preserved
        },
        dominant_feedback: refresh_result.merged_feedback_set.dominant_feedback,
        risk_regression_score: best_rank.map(|rank| rank.safety_score),
        voice_concentration_score: best_rank.map(|rank| rank.concentration_score),
        no_trade_bias_score: best_rank.map(|rank| rank.no_trade_bias_score),
        risk_first_score: best_rank.map(|rank| rank.risk_first_score),
        paper_only: true,
    }
}

fn build_governance_feedback_reentry_safety_guard_from_parts(
    refresh_result: &GovernanceRecommendationPipelineRefreshResult,
    batch_before: Option<&BatchCommitteeCycleWithStateResult>,
    batch_after: Option<&BatchCommitteeCycleWithStateResult>,
) -> GovernanceFeedbackReentrySafetyGuard {
    let after = batch_after.or(batch_before);
    let policy_apply_allowed_true_detected = refresh_result.apply_gate_lock.policy_apply_allowed
        || refresh_result.ranking.policy_apply_allowed;
    let actual_policy_path_changed = if let (Some(before), Some(after)) = (batch_before, after) {
        before.batch_result.conservative_voice_tuning_v2_policy
            != after.batch_result.conservative_voice_tuning_v2_policy
            || before.batch_result.chairman_role_voice_floor_policy
                != after.batch_result.chairman_role_voice_floor_policy
    } else {
        false
    };
    let actual_policy_apply_detected =
        policy_apply_allowed_true_detected || actual_policy_path_changed;
    let actual_score_mutation_detected = if let (Some(before), Some(after)) = (batch_before, after)
    {
        member_score_changed(
            &before.state_update.updated_member_states,
            &after.state_update.updated_member_states,
        )
    } else {
        false
    };
    let actual_voice_mutation_detected = if let (Some(before), Some(after)) = (batch_before, after)
    {
        member_voice_changed(
            &before.state_update.updated_member_states,
            &after.state_update.updated_member_states,
        )
    } else {
        false
    };
    let committee_decision_mutation_detected =
        if let (Some(before), Some(after)) = (batch_before, after) {
            before.batch_result.committee_sessions != after.batch_result.committee_sessions
        } else {
            false
        };
    let chairman_decision_mutation_detected =
        if let (Some(before), Some(after)) = (batch_before, after) {
            before.batch_result.chairman_decisions != after.batch_result.chairman_decisions
        } else {
            false
        };
    let risk_governor_override_detected = if let (Some(before), Some(after)) = (batch_before, after)
    {
        risk_governor_decision_status_changed(
            &before.batch_result.chairman_decisions,
            &after.batch_result.chairman_decisions,
        )
    } else {
        false
    };
    let trade_signal_detected = if let (Some(before), Some(after)) = (batch_before, after) {
        value_has_new_debug_marker(
            &before.batch_result.committee_sessions,
            &after.batch_result.committee_sessions,
            &["trade-signal".to_string()],
        )
    } else {
        false
    };
    let order_detected = if let (Some(before), Some(after)) = (batch_before, after) {
        value_has_new_debug_marker(
            &before.batch_result.event_queue,
            &after.batch_result.event_queue,
            &[
                "order".to_string(),
                "order_id".to_string(),
                "submit order".to_string(),
                "execute order".to_string(),
            ],
        )
    } else {
        false
    };
    let broker_order_account_detected = if let (Some(before), Some(after)) = (batch_before, after) {
        value_has_new_debug_marker(
            &before.batch_result.event_queue,
            &after.batch_result.event_queue,
            &[
                "broker".to_string(),
                "order".to_string(),
                "account".to_string(),
            ],
        ) || value_has_new_debug_marker(
            &before.batch_result.committee_sessions,
            &after.batch_result.committee_sessions,
            &[
                "broker".to_string(),
                "order".to_string(),
                "account".to_string(),
            ],
        )
    } else {
        false
    };
    let unsafe_keep_policy_recommendation_detected = refresh_result
        .merged_feedback_set
        .records
        .iter()
        .any(|record| {
            record.feedback_kind == GovernancePolicyFeedbackKindV2::BlockActualGovernance
        })
        && matches!(
            refresh_result.ranking.recommended_action,
            GovernanceReentryRecommendedAction::KeepPolicy
                | GovernanceReentryRecommendedAction::ContinuePaperTrial
        );
    let feedback_used_as_live_decision_detected = actual_policy_apply_detected
        || committee_decision_mutation_detected
        || chairman_decision_mutation_detected
        || risk_governor_override_detected
        || trade_signal_detected
        || order_detected
        || broker_order_account_detected;
    let mut violations = Vec::new();
    if policy_apply_allowed_true_detected {
        violations.push("feedback reentry opened policy_apply_allowed".to_string());
    }
    if actual_policy_apply_detected {
        violations.push("feedback reentry applied governance policy".to_string());
    }
    if actual_score_mutation_detected {
        violations.push("feedback reentry mutated actual score".to_string());
    }
    if actual_voice_mutation_detected {
        violations.push("feedback reentry mutated actual voice".to_string());
    }
    if committee_decision_mutation_detected {
        violations.push("feedback reentry mutated committee decision".to_string());
    }
    if chairman_decision_mutation_detected {
        violations.push("feedback reentry mutated chairman decision".to_string());
    }
    if risk_governor_override_detected {
        violations.push("feedback reentry overrode Risk Governor".to_string());
    }
    if trade_signal_detected || order_detected || broker_order_account_detected {
        violations.push("feedback reentry touched trade/order/account paths".to_string());
    }
    if feedback_used_as_live_decision_detected {
        violations.push("feedback reentry was used as a live decision".to_string());
    }
    if unsafe_keep_policy_recommendation_detected {
        violations.push("feedback reentry kept policy under a safety block".to_string());
    }
    GovernanceFeedbackReentrySafetyGuard {
        policy_apply_allowed_true_detected,
        actual_policy_apply_detected,
        actual_score_mutation_detected,
        actual_voice_mutation_detected,
        committee_decision_mutation_detected,
        chairman_decision_mutation_detected,
        risk_governor_override_detected,
        trade_signal_detected,
        order_detected,
        broker_order_account_detected,
        feedback_used_as_live_decision_detected,
        unsafe_keep_policy_recommendation_detected,
        guard_status: if violations.is_empty() {
            PaperGovernanceTrialSafetyGuardStatus::Preserved
        } else {
            PaperGovernanceTrialSafetyGuardStatus::Violated
        },
        violations,
        paper_only: true,
    }
}

pub fn evaluate_governance_feedback_reentry_safety(
    refresh_result: &GovernanceRecommendationPipelineRefreshResult,
    batch_before: &BatchCommitteeCycleWithStateResult,
    batch_after: Option<&BatchCommitteeCycleWithStateResult>,
) -> GovernanceFeedbackReentrySafetyGuard {
    build_governance_feedback_reentry_safety_guard_from_parts(
        refresh_result,
        Some(batch_before),
        batch_after,
    )
}

pub fn run_governance_outcome_feedback_reentry(
    feedback_bridge_result: &PaperPolicyOutcomeFeedbackBridgeRunResult,
    baseline_policy: &ConservativeVoiceTuningV2Policy,
    latest_paper_trial_results: &PaperGovernanceTrialMultiCycleResult,
    config: &GovernanceOutcomeFeedbackReentryRunConfig,
) -> Result<GovernanceOutcomeFeedbackReentryRunResult, String> {
    if !config.paper_only {
        return Err("governance outcome feedback reentry run must stay paper_only".to_string());
    }
    if let Some(path) = config.output_path.as_ref() {
        validate_local_json_path(
            Path::new(path),
            "governance outcome feedback reentry output path",
        )?;
    }
    let mut refresh_result = refresh_governance_recommendation_pipeline_from_outcome_feedback(
        feedback_bridge_result,
        baseline_policy,
        latest_paper_trial_results,
        config,
    )?;
    if config.emit_owner_summary {
        refresh_result.owner_summary =
            Some(build_owner_governance_recommendation_pipeline_refresh_summary(&refresh_result));
    }
    let safety_guard =
        build_governance_feedback_reentry_safety_guard_from_parts(&refresh_result, None, None);
    let run_status = if safety_guard.guard_status == PaperGovernanceTrialSafetyGuardStatus::Violated
        || refresh_result.refresh_status == GovernanceRecommendationPipelineRefreshStatus::Blocked
    {
        PaperGovernanceTrialRunStatus::Failed
    } else if refresh_result.refresh_status
        == GovernanceRecommendationPipelineRefreshStatus::Refreshed
        || refresh_result.refresh_status
            == GovernanceRecommendationPipelineRefreshStatus::NoActionNeeded
    {
        PaperGovernanceTrialRunStatus::Passed
    } else {
        PaperGovernanceTrialRunStatus::PassedWithWarnings
    };
    let owner_summary = if config.emit_owner_summary {
        Some(build_owner_governance_recommendation_pipeline_refresh_summary(&refresh_result))
    } else {
        None
    };
    let result = GovernanceOutcomeFeedbackReentryRunResult {
        run_id: config.run_id.clone(),
        refresh_result,
        safety_guard,
        owner_summary,
        run_status,
        paper_only: true,
    };
    if !config.dry_run {
        if let Some(path) = config.output_path.as_ref() {
            write_safe_json(Path::new(path), &result)?;
        }
    }
    Ok(result)
}

fn maybe_run_governance_outcome_feedback_reentry_for_stateful_result(
    run_id: String,
    enabled: bool,
    dry_run: bool,
    output_path: Option<&String>,
    emit_owner_summary: bool,
    stateful_result: &mut BatchCommitteeCycleWithStateResult,
) -> Result<Option<GovernanceOutcomeFeedbackReentryRunResult>, String> {
    if !governance_outcome_feedback_reentry_requested_from_flags(
        enabled,
        dry_run,
        output_path,
        emit_owner_summary,
    ) {
        return Ok(None);
    }
    let feedback_bridge_result = stateful_result
        .batch_result
        .paper_policy_outcome_feedback_bridge_run_result
        .clone()
        .ok_or_else(|| {
            "governance outcome feedback reentry requires outcome feedback bridge result"
                .to_string()
        })?;
    let baseline_policy = stateful_result
        .batch_result
        .conservative_voice_tuning_v2_policy
        .clone()
        .unwrap_or_else(default_governance_outcome_feedback_reentry_policy);
    let latest_paper_trial_results = stateful_result
        .batch_result
        .paper_governance_trial_multi_cycle_result
        .clone()
        .unwrap_or_else(|| {
            proxy_latest_paper_trial_results_from_feedback_bridge(&feedback_bridge_result)
        });
    let before_snapshot = stateful_result.clone();
    let mut result = run_governance_outcome_feedback_reentry(
        &feedback_bridge_result,
        &baseline_policy,
        &latest_paper_trial_results,
        &GovernanceOutcomeFeedbackReentryRunConfig {
            run_id,
            enabled,
            output_path: output_path.cloned(),
            dry_run,
            emit_owner_summary,
            paper_only: true,
        },
    )?;
    stateful_result
        .batch_result
        .governance_outcome_feedback_reentry_input =
        Some(result.refresh_result.reentry_input.clone());
    stateful_result
        .batch_result
        .governance_feedback_reentry_adapter_result =
        Some(result.refresh_result.adapter_result.clone());
    stateful_result
        .batch_result
        .merged_governance_policy_feedback_set =
        Some(result.refresh_result.merged_feedback_set.clone());
    stateful_result
        .batch_result
        .governance_reentry_proposal_generation_result =
        Some(result.refresh_result.proposal_generation.clone());
    stateful_result
        .batch_result
        .governance_reentry_ab_comparison_result =
        Some(result.refresh_result.ab_comparison.clone());
    stateful_result
        .batch_result
        .governance_reentry_proposal_ranking_result = Some(result.refresh_result.ranking.clone());
    stateful_result
        .batch_result
        .governance_recommendation_apply_gate_lock =
        Some(result.refresh_result.apply_gate_lock.clone());
    stateful_result
        .batch_result
        .owner_governance_recommendation_pipeline_refresh_summary = result.owner_summary.clone();
    stateful_result
        .batch_result
        .governance_recommendation_pipeline_refresh_result = Some(result.refresh_result.clone());
    stateful_result
        .batch_result
        .governance_feedback_reentry_safety_guard = Some(result.safety_guard.clone());
    stateful_result
        .batch_result
        .governance_outcome_feedback_reentry_run_result = Some(result.clone());
    let mut recommendation_ledger = stateful_result
        .batch_result
        .governance_recommendation_stability_ledger
        .clone()
        .unwrap_or_else(default_governance_recommendation_stability_ledger);
    append_governance_recommendation_ledger_entry(
        &mut recommendation_ledger,
        governance_recommendation_entry_from_reentry_refresh(&result.refresh_result),
    )?;
    let recommendation_metrics =
        compute_governance_recommendation_stability_metrics(&recommendation_ledger);
    stateful_result
        .batch_result
        .governance_recommendation_stability_ledger = Some(recommendation_ledger);
    stateful_result
        .batch_result
        .governance_recommendation_stability_metrics = Some(recommendation_metrics);
    let after_snapshot = stateful_result.clone();
    result.safety_guard = evaluate_governance_feedback_reentry_safety(
        &result.refresh_result,
        &before_snapshot,
        Some(&after_snapshot),
    );
    result.run_status = if result.safety_guard.guard_status
        == PaperGovernanceTrialSafetyGuardStatus::Violated
        || result.refresh_result.refresh_status
            == GovernanceRecommendationPipelineRefreshStatus::Blocked
    {
        PaperGovernanceTrialRunStatus::Failed
    } else if result.refresh_result.refresh_status
        == GovernanceRecommendationPipelineRefreshStatus::Refreshed
        || result.refresh_result.refresh_status
            == GovernanceRecommendationPipelineRefreshStatus::NoActionNeeded
    {
        PaperGovernanceTrialRunStatus::Passed
    } else {
        PaperGovernanceTrialRunStatus::PassedWithWarnings
    };
    if emit_owner_summary {
        result.owner_summary = Some(
            build_owner_governance_recommendation_pipeline_refresh_summary(&result.refresh_result),
        );
    }
    stateful_result
        .batch_result
        .governance_feedback_reentry_safety_guard = Some(result.safety_guard.clone());
    stateful_result
        .batch_result
        .owner_governance_recommendation_pipeline_refresh_summary = result.owner_summary.clone();
    stateful_result
        .batch_result
        .governance_outcome_feedback_reentry_run_result = Some(result.clone());
    Ok(Some(result))
}

pub fn governance_keep_policy_review_requested_from_flags(
    enabled: bool,
    dry_run: bool,
    owner_review_text: Option<&String>,
    append_ledger: bool,
    ledger_input_path: Option<&String>,
    ledger_output_path: Option<&String>,
    output_path: Option<&String>,
    emit_owner_summary: bool,
) -> bool {
    enabled
        || !dry_run
        || (enabled
            && (owner_review_text.is_some_and(|text| !text.trim().is_empty())
                || append_ledger
                || ledger_input_path.is_some()
                || ledger_output_path.is_some()
                || output_path.is_some()
                || emit_owner_summary))
}

fn inferred_keep_policy_scorecard_status(
    feedback_bridge_result: Option<&PaperPolicyOutcomeFeedbackBridgeRunResult>,
) -> Option<PaperPolicyTrialOutcomeScorecardStatus> {
    let bridge = feedback_bridge_result?;
    if bridge.tuning_input.should_stop_paper_trial {
        Some(PaperPolicyTrialOutcomeScorecardStatus::Unsafe)
    } else if bridge.tuning_input.can_generate_tuning_proposal {
        Some(PaperPolicyTrialOutcomeScorecardStatus::Weak)
    } else if bridge.tuning_input.should_collect_more_evidence {
        Some(PaperPolicyTrialOutcomeScorecardStatus::AcceptableWithWarnings)
    } else if bridge.feedback_summary.summary_status
        == GovernanceOutcomeFeedbackSummaryStatus::ContinueRecommended
        && bridge.evidence_backlog.item_count == 0
    {
        Some(PaperPolicyTrialOutcomeScorecardStatus::Strong)
    } else {
        Some(PaperPolicyTrialOutcomeScorecardStatus::Acceptable)
    }
}

fn governance_keep_policy_future_tuning_triggers() -> Vec<String> {
    vec![
        "risk weakness".to_string(),
        "voice concentration".to_string(),
        "no-trade bias".to_string(),
        "evidence weakness".to_string(),
        "owner explanation weakness".to_string(),
        "safety block".to_string(),
    ]
}

pub fn build_governance_keep_policy_review_packet(
    refresh_result: &GovernanceRecommendationPipelineRefreshResult,
    feedback_bridge_result: Option<&PaperPolicyOutcomeFeedbackBridgeRunResult>,
) -> GovernanceKeepPolicyReviewPacket {
    let scorecard_status = inferred_keep_policy_scorecard_status(feedback_bridge_result);
    let no_weak_follow_up = feedback_bridge_result
        .map(|bridge| bridge.evidence_backlog.item_count == 0)
        .unwrap_or(false);
    let rationale_summary = match refresh_result.ranking.recommended_action {
        GovernanceReentryRecommendedAction::KeepPolicy => {
            "Current recommendation is to keep policy unchanged while review remains paper-only."
                .to_string()
        }
        GovernanceReentryRecommendedAction::ContinuePaperTrial => {
            "Current recommendation is to continue paper trial only with policy apply locked."
                .to_string()
        }
        GovernanceReentryRecommendedAction::TunePolicy => {
            "Current packet is review-only and may prepare a future tuning review without applying policy."
                .to_string()
        }
        GovernanceReentryRecommendedAction::CollectMoreEvidence => {
            "Current packet stays review-only until more paper-only evidence is collected."
                .to_string()
        }
        GovernanceReentryRecommendedAction::BlockActualGovernance => {
            "Current packet remains blocked by safety and cannot unlock actual governance."
                .to_string()
        }
    };
    let why_no_tuning_needed = match refresh_result.ranking.recommended_action {
        GovernanceReentryRecommendedAction::KeepPolicy => {
            if scorecard_status == Some(PaperPolicyTrialOutcomeScorecardStatus::Strong)
                && no_weak_follow_up
            {
                "The scorecard remained strong and the weak-scenario follow-up count stayed at zero, so keeping policy is currently safer than tuning.".to_string()
            } else if refresh_result.reentry_input.tuning_focus
                == GovernanceOutcomeFeedbackRecommendedTuningFocus::None
            {
                "No dominant tuning weakness is active, so keeping policy is safer than introducing unnecessary tuning.".to_string()
            } else {
                "The recommendation remains review-only and does not justify policy tuning yet."
                    .to_string()
            }
        }
        GovernanceReentryRecommendedAction::ContinuePaperTrial => {
            "Paper-only continuation is safer than tuning or applying policy at this stage."
                .to_string()
        }
        GovernanceReentryRecommendedAction::TunePolicy => {
            "Any future tuning still requires separate paper-only review and remains apply-locked."
                .to_string()
        }
        GovernanceReentryRecommendedAction::CollectMoreEvidence => {
            "More evidence is required before any tuning review should replace the current keep-policy stance."
                .to_string()
        }
        GovernanceReentryRecommendedAction::BlockActualGovernance => {
            "Safety stays ahead of tuning; actual governance remains blocked until the safety issue is cleared."
                .to_string()
        }
    };
    GovernanceKeepPolicyReviewPacket {
        packet_id: format!("{}-keep-policy-review-packet", refresh_result.refresh_id),
        source_refresh_id: refresh_result.refresh_id.clone(),
        recommended_action: refresh_result.ranking.recommended_action,
        recommended_proposal_id: refresh_result.ranking.recommended_proposal_id.clone(),
        scorecard_status,
        continuation_stability_status: Some(
            refresh_result.reentry_input.continuation_stability_status,
        ),
        tuning_focus: Some(refresh_result.reentry_input.tuning_focus),
        rationale_summary,
        why_no_tuning_needed,
        future_tuning_triggers: governance_keep_policy_future_tuning_triggers(),
        policy_apply_allowed: false,
        review_only: true,
        paper_only: true,
    }
}

pub fn build_keep_policy_rationale(
    review_packet: &GovernanceKeepPolicyReviewPacket,
    scorecard: Option<&PaperPolicyTrialOutcomeScorecard>,
    weak_analysis: Option<&PaperPolicyWeakScenarioAnalysis>,
    safety_guard: Option<&GovernanceFeedbackReentrySafetyGuard>,
) -> GovernanceKeepPolicyRationale {
    let scorecard_status = scorecard
        .map(|scorecard| scorecard.scorecard_status)
        .or(review_packet.scorecard_status);
    let weak_count = weak_analysis.map(|analysis| analysis.weak_record_count);
    let scorecard_reason = if matches!(
        scorecard_status,
        Some(PaperPolicyTrialOutcomeScorecardStatus::Strong)
    ) {
        Some("The latest paper-only outcome scorecard remained strong enough to avoid unnecessary tuning.".to_string())
    } else {
        None
    };
    let risk_first_reason = if review_packet.recommended_action
        == GovernanceReentryRecommendedAction::KeepPolicy
        && review_packet.tuning_focus == Some(GovernanceOutcomeFeedbackRecommendedTuningFocus::None)
    {
        Some("Risk-first stayed preserved, so keeping the current policy is safer than forcing a tune.".to_string())
    } else {
        None
    };
    let weak_scenario_reason = if weak_count == Some(0)
        || (weak_count.is_none()
            && review_packet
                .why_no_tuning_needed
                .to_ascii_lowercase()
                .contains("weak-scenario"))
    {
        Some(
            "Weak scenario count remained at zero, so no immediate tuning trigger was activated."
                .to_string(),
        )
    } else {
        None
    };
    let safety_reason = if safety_guard
        .is_some_and(|guard| guard.guard_status == PaperGovernanceTrialSafetyGuardStatus::Violated)
    {
        "Safety guard remains the hard stop; review stays apply-locked and advisory-only."
            .to_string()
    } else {
        "Policy apply remains locked, and the review stays paper-only with no live decision path."
            .to_string()
    };
    let no_trade_bias_reason = Some(
        "Future tuning should be reconsidered if no-trade bias worsens and paper evidence stops improving."
            .to_string(),
    );
    let voice_balance_reason = Some(
        "Future tuning should be reconsidered if voice concentration regresses or role balance weakens."
            .to_string(),
    );
    let owner_explanation_reason = Some(
        "Future tuning should be reconsidered if owner-facing explanation quality weakens."
            .to_string(),
    );
    let human_readable_summary = [
        scorecard_reason.clone(),
        weak_scenario_reason.clone(),
        risk_first_reason.clone(),
        Some(safety_reason.clone()),
        no_trade_bias_reason.clone(),
        voice_balance_reason.clone(),
        owner_explanation_reason.clone(),
    ]
    .into_iter()
    .flatten()
    .collect::<Vec<_>>()
    .join(" ");
    GovernanceKeepPolicyRationale {
        rationale_id: format!("{}-rationale", review_packet.packet_id),
        scorecard_reason,
        risk_first_reason,
        weak_scenario_reason,
        safety_reason,
        no_trade_bias_reason,
        voice_balance_reason,
        owner_explanation_reason,
        human_readable_summary,
        paper_only: true,
    }
}

fn keep_policy_review_contains_any(text: &str, terms: &[&str]) -> bool {
    terms.iter().any(|term| text.contains(term))
}

fn owner_keep_policy_review_intent_from_text(raw_text: &str) -> OwnerKeepPolicyReviewIntent {
    let lower = raw_text.to_lowercase();
    if keep_policy_review_contains_any(&lower, &["reject", "거부", "반대", "기각"]) {
        OwnerKeepPolicyReviewIntent::RejectKeepPolicy
    } else if keep_policy_review_contains_any(
        &lower,
        &["왜", "이유", "설명해줘", "explain", "why keep"],
    ) {
        OwnerKeepPolicyReviewIntent::AskWhyKeepPolicy
    } else if keep_policy_review_contains_any(
        &lower,
        &[
            "more evidence",
            "need evidence",
            "추가 증거",
            "더 모아",
            "근거를 더",
            "추가 근거",
        ],
    ) {
        OwnerKeepPolicyReviewIntent::AskForMoreEvidence
    } else if keep_policy_review_contains_any(&lower, &["risk", "리스크", "위험"])
        && keep_policy_review_contains_any(&lower, &["tune", "review", "검토", "조정"])
    {
        OwnerKeepPolicyReviewIntent::AskToTuneRiskPolicy
    } else if keep_policy_review_contains_any(
        &lower,
        &["voice balance", "voice", "보이스", "발언", "목소리"],
    ) && keep_policy_review_contains_any(&lower, &["tune", "review", "걱정", "검토"])
    {
        OwnerKeepPolicyReviewIntent::AskToTuneVoiceBalance
    } else if keep_policy_review_contains_any(
        &lower,
        &[
            "keep policy",
            "정책 유지",
            "유지가 맞아",
            "유지가 맞다",
            "지금은 정책 유지",
        ],
    ) {
        OwnerKeepPolicyReviewIntent::AgreeToKeepPolicy
    } else if keep_policy_review_contains_any(
        &lower,
        &[
            "continue paper trial",
            "paper trial로 보자",
            "계속 paper trial",
            "계속 페이퍼",
            "continue trial",
        ],
    ) {
        OwnerKeepPolicyReviewIntent::AskToContinuePaperTrial
    } else {
        OwnerKeepPolicyReviewIntent::Unknown
    }
}

pub fn parse_owner_keep_policy_review_input(
    input: &OwnerKeepPolicyReviewInput,
) -> OwnerKeepPolicyReviewParseResult {
    let normalized_summary = normalize_owner_governance_review_text(&input.raw_text);
    let unsafe_terms_detected = detect_owner_governance_review_unsafe_terms(&normalized_summary);
    let mut intent = owner_keep_policy_review_intent_from_text(&normalized_summary);
    if intent == OwnerKeepPolicyReviewIntent::Unknown
        && input.parsed_intent != OwnerKeepPolicyReviewIntent::Unknown
    {
        intent = input.parsed_intent;
    }
    OwnerKeepPolicyReviewParseResult {
        input_id: input.input_id.clone(),
        intent,
        safe: unsafe_terms_detected.is_empty(),
        unsafe_reason: if unsafe_terms_detected.is_empty() {
            None
        } else {
            Some(format!(
                "owner keep-policy review contains execution-only terms: {}",
                unsafe_terms_detected.join(", ")
            ))
        },
        normalized_summary: if normalized_summary.is_empty() {
            input.normalized_summary.clone()
        } else {
            normalized_summary
        },
        paper_only: true,
    }
}

pub fn parse_owner_keep_policy_review_text(raw_text: &str) -> OwnerKeepPolicyReviewParseResult {
    let normalized_summary = normalize_owner_governance_review_text(raw_text);
    let input = OwnerKeepPolicyReviewInput {
        input_id: "owner-keep-policy-review-text".to_string(),
        raw_text: raw_text.to_string(),
        parsed_intent: owner_keep_policy_review_intent_from_text(&normalized_summary),
        target_packet_id: None,
        unsafe_terms_detected: detect_owner_governance_review_unsafe_terms(&normalized_summary),
        normalized_summary,
        paper_only: true,
    };
    parse_owner_keep_policy_review_input(&input)
}

fn keep_policy_review_reason_from_packet(
    review_packet: &GovernanceKeepPolicyReviewPacket,
) -> ChairmanKeepPolicyReviewReason {
    if review_packet
        .why_no_tuning_needed
        .to_ascii_lowercase()
        .contains("weak-scenario")
    {
        ChairmanKeepPolicyReviewReason::NoWeakScenario
    } else if review_packet.recommended_action == GovernanceReentryRecommendedAction::KeepPolicy
        && review_packet.tuning_focus == Some(GovernanceOutcomeFeedbackRecommendedTuningFocus::None)
    {
        ChairmanKeepPolicyReviewReason::RiskFirstPreserved
    } else {
        ChairmanKeepPolicyReviewReason::StrongScorecard
    }
}

pub fn evaluate_keep_policy_recommendation_with_owner_review(
    review_packet: &GovernanceKeepPolicyReviewPacket,
    owner_review: Option<&OwnerKeepPolicyReviewParseResult>,
    safety_guard: Option<&GovernanceFeedbackReentrySafetyGuard>,
) -> ChairmanKeepPolicyReviewEvaluation {
    let safety_blocked = review_packet.recommended_action
        == GovernanceReentryRecommendedAction::BlockActualGovernance
        || safety_guard.is_some_and(|guard| {
            guard.guard_status == PaperGovernanceTrialSafetyGuardStatus::Violated
        });
    let owner_review_input_id = owner_review.map(|review| review.input_id.clone());
    let (chairman_decision, reason, explanation) = if safety_blocked {
        (
            ChairmanKeepPolicyReviewDecision::BlockedBySafety,
            ChairmanKeepPolicyReviewReason::SafetyBlocked,
            "Safety remains locked, so the keep-policy packet cannot move beyond review-only."
                .to_string(),
        )
    } else if let Some(review) = owner_review {
        if !review.safe {
            (
                ChairmanKeepPolicyReviewDecision::BlockedBySafety,
                ChairmanKeepPolicyReviewReason::SafetyBlocked,
                "Unsafe owner apply/trading wording was ignored and the recommendation stays blocked."
                    .to_string(),
            )
        } else {
            match review.intent {
                OwnerKeepPolicyReviewIntent::AgreeToKeepPolicy => (
                    ChairmanKeepPolicyReviewDecision::KeepPolicyForNow,
                    keep_policy_review_reason_from_packet(review_packet),
                    "Owner agreement supports keeping policy unchanged while apply lock remains in place."
                        .to_string(),
                ),
                OwnerKeepPolicyReviewIntent::AskWhyKeepPolicy => (
                    if review_packet.recommended_action
                        == GovernanceReentryRecommendedAction::ContinuePaperTrial
                    {
                        ChairmanKeepPolicyReviewDecision::ContinuePaperTrial
                    } else {
                        ChairmanKeepPolicyReviewDecision::KeepPolicyForNow
                    },
                    ChairmanKeepPolicyReviewReason::OwnerAskedWhy,
                    format!(
                        "{} {}",
                        review_packet.rationale_summary, review_packet.why_no_tuning_needed
                    ),
                ),
                OwnerKeepPolicyReviewIntent::AskForMoreEvidence => (
                    ChairmanKeepPolicyReviewDecision::NeedsMoreEvidence,
                    ChairmanKeepPolicyReviewReason::OwnerAskedMoreEvidence,
                    "Owner requested more evidence, so the packet stays review-only until paper-only evidence deepens."
                        .to_string(),
                ),
                OwnerKeepPolicyReviewIntent::AskToTuneRiskPolicy
                | OwnerKeepPolicyReviewIntent::AskToTuneVoiceBalance => (
                    ChairmanKeepPolicyReviewDecision::PrepareTuningReview,
                    ChairmanKeepPolicyReviewReason::OwnerRequestedTuningReview,
                    "Owner requested a tuning review, so the next step is a paper-only tuning review rather than apply."
                        .to_string(),
                ),
                OwnerKeepPolicyReviewIntent::AskToContinuePaperTrial => (
                    ChairmanKeepPolicyReviewDecision::ContinuePaperTrial,
                    ChairmanKeepPolicyReviewReason::StrongScorecard,
                    "Chairman keeps the packet in paper-only continuation mode with policy apply still locked."
                        .to_string(),
                ),
                OwnerKeepPolicyReviewIntent::RejectKeepPolicy => (
                    ChairmanKeepPolicyReviewDecision::RejectRecommendation,
                    ChairmanKeepPolicyReviewReason::OwnerRejected,
                    "Owner rejected the keep-policy recommendation, so it remains review-only and unapplied."
                        .to_string(),
                ),
                OwnerKeepPolicyReviewIntent::Unknown => match review_packet.recommended_action {
                    GovernanceReentryRecommendedAction::CollectMoreEvidence => (
                        ChairmanKeepPolicyReviewDecision::NeedsMoreEvidence,
                        ChairmanKeepPolicyReviewReason::InsufficientEvidence,
                        "The review packet still lacks enough evidence to justify changing the recommendation."
                            .to_string(),
                    ),
                    GovernanceReentryRecommendedAction::ContinuePaperTrial => (
                        ChairmanKeepPolicyReviewDecision::ContinuePaperTrial,
                        ChairmanKeepPolicyReviewReason::StrongScorecard,
                        "Without a contradictory safe owner request, the packet remains paper-only continuation."
                            .to_string(),
                    ),
                    GovernanceReentryRecommendedAction::TunePolicy => (
                        ChairmanKeepPolicyReviewDecision::PrepareTuningReview,
                        ChairmanKeepPolicyReviewReason::OwnerRequestedTuningReview,
                        "The packet can prepare a tuning review, but still cannot apply policy."
                            .to_string(),
                    ),
                    _ => (
                        ChairmanKeepPolicyReviewDecision::KeepPolicyForNow,
                        keep_policy_review_reason_from_packet(review_packet),
                        "The packet remains review-only and keeps the current policy unchanged for now."
                            .to_string(),
                    ),
                },
            }
        }
    } else {
        match review_packet.recommended_action {
            GovernanceReentryRecommendedAction::CollectMoreEvidence => (
                ChairmanKeepPolicyReviewDecision::NeedsMoreEvidence,
                ChairmanKeepPolicyReviewReason::InsufficientEvidence,
                "The packet still needs more paper-only evidence before a stronger keep-policy conclusion."
                    .to_string(),
            ),
            GovernanceReentryRecommendedAction::ContinuePaperTrial => (
                ChairmanKeepPolicyReviewDecision::ContinuePaperTrial,
                ChairmanKeepPolicyReviewReason::StrongScorecard,
                "The packet supports continuing paper trial only while keeping policy locked."
                    .to_string(),
            ),
            GovernanceReentryRecommendedAction::TunePolicy => (
                ChairmanKeepPolicyReviewDecision::PrepareTuningReview,
                ChairmanKeepPolicyReviewReason::InsufficientEvidence,
                "A separate tuning review may be prepared, but no policy apply is allowed."
                    .to_string(),
            ),
            _ => (
                ChairmanKeepPolicyReviewDecision::KeepPolicyForNow,
                keep_policy_review_reason_from_packet(review_packet),
                "The packet supports keeping policy unchanged for now while everything remains review-only."
                    .to_string(),
            ),
        }
    };
    ChairmanKeepPolicyReviewEvaluation {
        evaluation_id: format!("{}-chairman-keep-policy-review", review_packet.packet_id),
        review_packet_id: review_packet.packet_id.clone(),
        owner_review_input_id,
        chairman_decision,
        reason,
        explanation,
        policy_apply_allowed: false,
        paper_only: true,
    }
}

fn default_governance_continuation_decision_ledger() -> GovernanceContinuationDecisionLedger {
    GovernanceContinuationDecisionLedger {
        ledger_id: "governance-continuation-decision-ledger".to_string(),
        entries: Vec::new(),
        entry_count: 0,
        latest_entry_id: None,
        paper_only: true,
    }
}

pub fn normalize_governance_continuation_decision_ledger(
    ledger: &mut GovernanceContinuationDecisionLedger,
) {
    ledger
        .entries
        .sort_by(|left, right| left.entry_id.cmp(&right.entry_id));
    ledger
        .entries
        .dedup_by(|left, right| left.entry_id == right.entry_id);
    ledger.entry_count = ledger.entries.len();
    ledger.latest_entry_id = ledger.entries.last().map(|entry| entry.entry_id.clone());
}

pub fn append_governance_continuation_decision_entry(
    ledger: &mut GovernanceContinuationDecisionLedger,
    entry: GovernanceContinuationDecisionLedgerEntry,
) -> Result<(), String> {
    ledger.entries.push(entry);
    normalize_governance_continuation_decision_ledger(ledger);
    Ok(())
}

pub fn load_governance_continuation_decision_ledger_from_local_json(
    path: &Path,
) -> Result<GovernanceContinuationDecisionLedger, String> {
    validate_local_json_path(path, "governance continuation decision ledger path")?;
    let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
    let mut ledger = serde_json::from_str::<GovernanceContinuationDecisionLedger>(&text)
        .map_err(|err| err.to_string())?;
    normalize_governance_continuation_decision_ledger(&mut ledger);
    Ok(ledger)
}

pub fn save_governance_continuation_decision_ledger_to_local_json(
    path: &Path,
    ledger: &GovernanceContinuationDecisionLedger,
) -> Result<(), String> {
    validate_local_json_path(path, "governance continuation decision ledger path")?;
    write_safe_json(path, ledger)
}

fn dominant_governance_continuation_decision(
    ledger: &GovernanceContinuationDecisionLedger,
) -> Option<ChairmanKeepPolicyReviewDecision> {
    let ordered = [
        ChairmanKeepPolicyReviewDecision::BlockedBySafety,
        ChairmanKeepPolicyReviewDecision::KeepPolicyForNow,
        ChairmanKeepPolicyReviewDecision::ContinuePaperTrial,
        ChairmanKeepPolicyReviewDecision::PrepareTuningReview,
        ChairmanKeepPolicyReviewDecision::NeedsMoreEvidence,
        ChairmanKeepPolicyReviewDecision::RejectRecommendation,
    ];
    let mut best_decision = None;
    let mut best_count = 0usize;
    for decision in ordered {
        let count = ledger
            .entries
            .iter()
            .filter(|entry| entry.chairman_decision == decision)
            .count();
        if count > best_count {
            best_count = count;
            best_decision = Some(decision);
        }
    }
    best_decision
}

pub fn compute_governance_continuation_decision_stability(
    ledger: &GovernanceContinuationDecisionLedger,
) -> GovernanceContinuationDecisionStability {
    let keep_policy_count = ledger
        .entries
        .iter()
        .filter(|entry| {
            entry.chairman_decision == ChairmanKeepPolicyReviewDecision::KeepPolicyForNow
        })
        .count();
    let continue_paper_trial_count = ledger
        .entries
        .iter()
        .filter(|entry| {
            entry.chairman_decision == ChairmanKeepPolicyReviewDecision::ContinuePaperTrial
        })
        .count();
    let tuning_review_count = ledger
        .entries
        .iter()
        .filter(|entry| {
            entry.chairman_decision == ChairmanKeepPolicyReviewDecision::PrepareTuningReview
        })
        .count();
    let needs_more_evidence_count = ledger
        .entries
        .iter()
        .filter(|entry| {
            entry.chairman_decision == ChairmanKeepPolicyReviewDecision::NeedsMoreEvidence
        })
        .count();
    let blocked_by_safety_count = ledger
        .entries
        .iter()
        .filter(|entry| {
            entry.chairman_decision == ChairmanKeepPolicyReviewDecision::BlockedBySafety
        })
        .count();
    let decision_flip_count = ledger
        .entries
        .windows(2)
        .filter(|window| window[0].chairman_decision != window[1].chairman_decision)
        .count();
    let dominant_decision = dominant_governance_continuation_decision(ledger);
    let stability_status = if ledger.entry_count < 2 {
        GovernanceContinuationDecisionStabilityStatus::NeedsMoreHistory
    } else if blocked_by_safety_count > 0 {
        GovernanceContinuationDecisionStabilityStatus::BlockedBySafety
    } else if keep_policy_count == ledger.entry_count && decision_flip_count == 0 {
        GovernanceContinuationDecisionStabilityStatus::StableKeepPolicy
    } else if continue_paper_trial_count == ledger.entry_count && decision_flip_count == 0 {
        GovernanceContinuationDecisionStabilityStatus::StableContinuePaperTrial
    } else {
        GovernanceContinuationDecisionStabilityStatus::Mixed
    };
    GovernanceContinuationDecisionStability {
        stability_id: format!("{}-stability", ledger.ledger_id),
        entry_count: ledger.entry_count,
        keep_policy_count,
        continue_paper_trial_count,
        tuning_review_count,
        needs_more_evidence_count,
        blocked_by_safety_count,
        dominant_decision,
        decision_flip_count,
        stability_status,
        policy_apply_allowed: false,
        paper_only: true,
    }
}

fn count_governance_continuation_decision(
    ledger: &GovernanceContinuationDecisionLedger,
    decision: ChairmanKeepPolicyReviewDecision,
) -> usize {
    ledger
        .entries
        .iter()
        .filter(|entry| entry.chairman_decision == decision)
        .count()
}

fn trailing_governance_continuation_decision_streak(
    ledger: &GovernanceContinuationDecisionLedger,
) -> usize {
    let Some(last_decision) = ledger.entries.last().map(|entry| entry.chairman_decision) else {
        return 0;
    };
    ledger
        .entries
        .iter()
        .rev()
        .take_while(|entry| entry.chairman_decision == last_decision)
        .count()
}

fn governance_continuation_decision_dominant_ratio(
    ledger: &GovernanceContinuationDecisionLedger,
    dominant_decision: Option<ChairmanKeepPolicyReviewDecision>,
) -> f64 {
    if ledger.entry_count == 0 {
        return 0.0;
    }
    let Some(dominant_decision) = dominant_decision else {
        return 0.0;
    };
    count_governance_continuation_decision(ledger, dominant_decision) as f64
        / ledger.entry_count as f64
}

fn governance_continuation_decision_streak_for(
    ledger: &GovernanceContinuationDecisionLedger,
    decision: ChairmanKeepPolicyReviewDecision,
) -> usize {
    ledger
        .entries
        .iter()
        .rev()
        .take_while(|entry| entry.chairman_decision == decision)
        .count()
}

pub fn compute_governance_continuation_decision_stability_v2(
    ledger: &GovernanceContinuationDecisionLedger,
    min_entries_required: usize,
) -> GovernanceContinuationDecisionStabilityV2 {
    let keep_policy_count = count_governance_continuation_decision(
        ledger,
        ChairmanKeepPolicyReviewDecision::KeepPolicyForNow,
    );
    let continue_paper_trial_count = count_governance_continuation_decision(
        ledger,
        ChairmanKeepPolicyReviewDecision::ContinuePaperTrial,
    );
    let tuning_review_count = count_governance_continuation_decision(
        ledger,
        ChairmanKeepPolicyReviewDecision::PrepareTuningReview,
    );
    let needs_more_evidence_count = count_governance_continuation_decision(
        ledger,
        ChairmanKeepPolicyReviewDecision::NeedsMoreEvidence,
    );
    let blocked_by_safety_count = count_governance_continuation_decision(
        ledger,
        ChairmanKeepPolicyReviewDecision::BlockedBySafety,
    );
    let decision_flip_count = ledger
        .entries
        .windows(2)
        .filter(|window| window[0].chairman_decision != window[1].chairman_decision)
        .count();
    let dominant_decision = dominant_governance_continuation_decision(ledger);
    let dominant_decision_ratio =
        governance_continuation_decision_dominant_ratio(ledger, dominant_decision);
    let trailing_decision_streak = trailing_governance_continuation_decision_streak(ledger);
    let stability_status = if ledger.entry_count < min_entries_required {
        GovernanceContinuationDecisionStabilityV2Status::NeedsMoreHistory
    } else if blocked_by_safety_count > 0 {
        GovernanceContinuationDecisionStabilityV2Status::BlockedBySafety
    } else if keep_policy_count == ledger.entry_count && decision_flip_count == 0 {
        GovernanceContinuationDecisionStabilityV2Status::StableKeepPolicy
    } else if continue_paper_trial_count == ledger.entry_count && decision_flip_count == 0 {
        GovernanceContinuationDecisionStabilityV2Status::StableContinuePaperTrial
    } else if needs_more_evidence_count == ledger.entry_count && decision_flip_count == 0 {
        GovernanceContinuationDecisionStabilityV2Status::NeedsMoreEvidence
    } else if tuning_review_count == ledger.entry_count && decision_flip_count == 0 {
        GovernanceContinuationDecisionStabilityV2Status::StableWithWarnings
    } else {
        GovernanceContinuationDecisionStabilityV2Status::Mixed
    };
    GovernanceContinuationDecisionStabilityV2 {
        stability_id: format!("{}-stability-v2", ledger.ledger_id),
        entry_count: ledger.entry_count,
        min_entries_required,
        keep_policy_count,
        continue_paper_trial_count,
        tuning_review_count,
        needs_more_evidence_count,
        blocked_by_safety_count,
        dominant_decision,
        dominant_decision_ratio,
        trailing_decision_streak,
        decision_flip_count,
        stability_status,
        policy_apply_allowed: false,
        paper_only: true,
    }
}

pub fn compute_governance_continuation_decision_trend(
    ledger: &GovernanceContinuationDecisionLedger,
) -> GovernanceContinuationDecisionTrend {
    let keep_policy_streak = governance_continuation_decision_streak_for(
        ledger,
        ChairmanKeepPolicyReviewDecision::KeepPolicyForNow,
    );
    let continue_paper_trial_streak = governance_continuation_decision_streak_for(
        ledger,
        ChairmanKeepPolicyReviewDecision::ContinuePaperTrial,
    );
    let needs_more_evidence_streak = governance_continuation_decision_streak_for(
        ledger,
        ChairmanKeepPolicyReviewDecision::NeedsMoreEvidence,
    );
    let prepare_tuning_streak = governance_continuation_decision_streak_for(
        ledger,
        ChairmanKeepPolicyReviewDecision::PrepareTuningReview,
    );
    let blocked_by_safety_count = count_governance_continuation_decision(
        ledger,
        ChairmanKeepPolicyReviewDecision::BlockedBySafety,
    );
    let trend_status = if ledger.entry_count < 2 {
        GovernanceContinuationDecisionTrendStatus::InsufficientHistory
    } else if blocked_by_safety_count > 0 {
        GovernanceContinuationDecisionTrendStatus::SafetyBlockTrend
    } else if keep_policy_streak >= 2 {
        GovernanceContinuationDecisionTrendStatus::StableKeepPolicyTrend
    } else if continue_paper_trial_streak >= 2 {
        GovernanceContinuationDecisionTrendStatus::StableContinueTrend
    } else if needs_more_evidence_streak >= 2 {
        GovernanceContinuationDecisionTrendStatus::EvidenceGapTrend
    } else if prepare_tuning_streak >= 2 {
        GovernanceContinuationDecisionTrendStatus::TuningReviewTrend
    } else {
        GovernanceContinuationDecisionTrendStatus::MixedTrend
    };
    GovernanceContinuationDecisionTrend {
        trend_id: format!("{}-trend", ledger.ledger_id),
        entry_count: ledger.entry_count,
        decision_series: ledger
            .entries
            .iter()
            .map(|entry| entry.chairman_decision)
            .collect(),
        keep_policy_streak,
        continue_paper_trial_streak,
        needs_more_evidence_streak,
        prepare_tuning_streak,
        blocked_by_safety_count,
        trend_status,
        paper_only: true,
    }
}

pub fn evaluate_stable_keep_policy_review_gate(
    stability_v2: &GovernanceContinuationDecisionStabilityV2,
    trend: &GovernanceContinuationDecisionTrend,
    apply_lock_regression: &GovernanceKeepPolicyMultiRunApplyLockRegression,
) -> StableKeepPolicyReviewGate {
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    let gate_status = if apply_lock_regression.regression_status
        == GovernanceKeepPolicyMultiRunApplyLockRegressionStatus::Failed
    {
        blockers.push("apply lock regression reported a violation".to_string());
        StableKeepPolicyReviewGateStatus::ApplyLockViolated
    } else {
        match stability_v2.stability_status {
            GovernanceContinuationDecisionStabilityV2Status::NeedsMoreHistory => {
                blockers
                    .push("continuation history is shorter than the minimum required".to_string());
                StableKeepPolicyReviewGateStatus::NeedsMoreHistory
            }
            GovernanceContinuationDecisionStabilityV2Status::NeedsMoreEvidence => {
                blockers.push("repeated needs-more-evidence decisions still dominate".to_string());
                StableKeepPolicyReviewGateStatus::NeedsMoreEvidence
            }
            GovernanceContinuationDecisionStabilityV2Status::BlockedBySafety => {
                blockers.push("safety block exists in continuation review history".to_string());
                StableKeepPolicyReviewGateStatus::BlockedBySafety
            }
            GovernanceContinuationDecisionStabilityV2Status::Mixed => {
                blockers.push("continuation review decisions flipped across runs".to_string());
                StableKeepPolicyReviewGateStatus::MixedDecisions
            }
            GovernanceContinuationDecisionStabilityV2Status::StableKeepPolicy => {
                if trend.trend_status
                    == GovernanceContinuationDecisionTrendStatus::StableKeepPolicyTrend
                {
                    StableKeepPolicyReviewGateStatus::StableKeepPolicyConfirmed
                } else {
                    warnings.push(
                        "keep-policy dominates, but the trailing trend is not yet a keep-policy trend"
                            .to_string(),
                    );
                    StableKeepPolicyReviewGateStatus::StableKeepPolicyWithWarnings
                }
            }
            GovernanceContinuationDecisionStabilityV2Status::StableContinuePaperTrial => {
                warnings.push(
                    "continuation review remains stable for continued paper trial, not a keep-policy confirmation"
                        .to_string(),
                );
                StableKeepPolicyReviewGateStatus::StableKeepPolicyWithWarnings
            }
            GovernanceContinuationDecisionStabilityV2Status::StableWithWarnings => {
                warnings.push(
                    "continuation review stabilized with warnings and stays review-only"
                        .to_string(),
                );
                StableKeepPolicyReviewGateStatus::StableKeepPolicyWithWarnings
            }
        }
    };
    let stable_keep_policy_confirmed =
        gate_status == StableKeepPolicyReviewGateStatus::StableKeepPolicyConfirmed;
    StableKeepPolicyReviewGate {
        gate_id: format!("{}-gate", stability_v2.stability_id),
        stability_status: stability_v2.stability_status,
        trend_status: trend.trend_status,
        apply_lock_status: apply_lock_regression.regression_status,
        min_entries_required: stability_v2.min_entries_required,
        entry_count: stability_v2.entry_count,
        stable_keep_policy_confirmed,
        gate_status,
        blockers,
        warnings,
        policy_apply_allowed: false,
        paper_only: true,
    }
}

fn build_governance_keep_policy_apply_lock_regression_from_parts(
    review_packet: &GovernanceKeepPolicyReviewPacket,
    owner_review: Option<&OwnerKeepPolicyReviewParseResult>,
    chairman_eval: &ChairmanKeepPolicyReviewEvaluation,
    batch_before: Option<&BatchCommitteeCycleWithStateResult>,
    batch_after: Option<&BatchCommitteeCycleWithStateResult>,
) -> GovernanceKeepPolicyApplyLockRegression {
    let after = batch_after.or(batch_before);
    let policy_apply_allowed_true_detected =
        review_packet.policy_apply_allowed || chairman_eval.policy_apply_allowed;
    let actual_policy_apply_detected = if let (Some(before), Some(after)) = (batch_before, after) {
        before.batch_result.conservative_voice_tuning_v2_policy
            != after.batch_result.conservative_voice_tuning_v2_policy
            || before.batch_result.chairman_role_voice_floor_policy
                != after.batch_result.chairman_role_voice_floor_policy
    } else {
        false
    };
    let actual_score_mutation_detected = if let (Some(before), Some(after)) = (batch_before, after)
    {
        member_score_changed(
            &before.state_update.updated_member_states,
            &after.state_update.updated_member_states,
        )
    } else {
        false
    };
    let actual_voice_mutation_detected = if let (Some(before), Some(after)) = (batch_before, after)
    {
        member_voice_changed(
            &before.state_update.updated_member_states,
            &after.state_update.updated_member_states,
        )
    } else {
        false
    };
    let committee_decision_mutation_detected =
        if let (Some(before), Some(after)) = (batch_before, after) {
            before.batch_result.committee_sessions != after.batch_result.committee_sessions
        } else {
            false
        };
    let chairman_decision_mutation_detected =
        if let (Some(before), Some(after)) = (batch_before, after) {
            before.batch_result.chairman_decisions != after.batch_result.chairman_decisions
        } else {
            false
        };
    let risk_governor_override_detected = if let (Some(before), Some(after)) = (batch_before, after)
    {
        risk_governor_decision_status_changed(
            &before.batch_result.chairman_decisions,
            &after.batch_result.chairman_decisions,
        )
    } else {
        false
    };
    let owner_forced_apply_detected = owner_review.is_some_and(|review| !review.safe);
    let trade_signal_detected = if let (Some(before), Some(after)) = (batch_before, after) {
        value_has_new_debug_marker(
            &before.batch_result.committee_sessions,
            &after.batch_result.committee_sessions,
            &["trade-signal".to_string()],
        )
    } else {
        false
    };
    let order_detected = if let (Some(before), Some(after)) = (batch_before, after) {
        value_has_new_debug_marker(
            &before.batch_result.event_queue,
            &after.batch_result.event_queue,
            &[
                "order".to_string(),
                "order_id".to_string(),
                "submit order".to_string(),
                "execute order".to_string(),
            ],
        )
    } else {
        false
    };
    let broker_order_account_detected = if let (Some(before), Some(after)) = (batch_before, after) {
        value_has_new_debug_marker(
            &before.batch_result.event_queue,
            &after.batch_result.event_queue,
            &[
                "broker".to_string(),
                "order".to_string(),
                "account".to_string(),
            ],
        ) || value_has_new_debug_marker(
            &before.batch_result.committee_sessions,
            &after.batch_result.committee_sessions,
            &[
                "broker".to_string(),
                "order".to_string(),
                "account".to_string(),
            ],
        )
    } else {
        false
    };
    let mut violations = Vec::new();
    if policy_apply_allowed_true_detected {
        violations.push("keep-policy review opened policy_apply_allowed".to_string());
    }
    if actual_policy_apply_detected {
        violations.push("keep-policy review triggered actual policy apply".to_string());
    }
    if actual_score_mutation_detected {
        violations.push("keep-policy review mutated actual score".to_string());
    }
    if actual_voice_mutation_detected {
        violations.push("keep-policy review mutated actual voice".to_string());
    }
    if committee_decision_mutation_detected {
        violations.push("keep-policy review mutated committee decision".to_string());
    }
    if chairman_decision_mutation_detected {
        violations.push("keep-policy review mutated chairman decision".to_string());
    }
    if risk_governor_override_detected {
        violations.push("keep-policy review overrode Risk Governor".to_string());
    }
    if owner_forced_apply_detected {
        violations.push("owner attempted to force apply during keep-policy review".to_string());
    }
    if trade_signal_detected || order_detected || broker_order_account_detected {
        violations.push("keep-policy review touched trade/order/account paths".to_string());
    }
    GovernanceKeepPolicyApplyLockRegression {
        regression_id: format!("{}-apply-lock-regression", review_packet.packet_id),
        policy_apply_allowed_true_detected,
        actual_policy_apply_detected,
        actual_score_mutation_detected,
        actual_voice_mutation_detected,
        committee_decision_mutation_detected,
        chairman_decision_mutation_detected,
        risk_governor_override_detected,
        owner_forced_apply_detected,
        trade_signal_detected,
        order_detected,
        broker_order_account_detected,
        regression_status: if violations.is_empty() {
            GovernanceKeepPolicyApplyLockRegressionStatus::Passed
        } else {
            GovernanceKeepPolicyApplyLockRegressionStatus::Failed
        },
        violations,
        paper_only: true,
    }
}

pub fn run_keep_policy_apply_lock_regression(
    review_packet: &GovernanceKeepPolicyReviewPacket,
    owner_review: Option<&OwnerKeepPolicyReviewParseResult>,
    chairman_eval: &ChairmanKeepPolicyReviewEvaluation,
    batch_before: &BatchCommitteeCycleWithStateResult,
    batch_after: Option<&BatchCommitteeCycleWithStateResult>,
) -> GovernanceKeepPolicyApplyLockRegression {
    build_governance_keep_policy_apply_lock_regression_from_parts(
        review_packet,
        owner_review,
        chairman_eval,
        Some(batch_before),
        batch_after,
    )
}

