fn prove_governance_continuation_decision_ledger_write_with_flag(
    wrote_ledger: bool,
    ledger_path: &Path,
) -> Result<GovernanceContinuationDecisionLedgerWriteProof, String> {
    validate_local_json_path(ledger_path, "governance continuation decision ledger path")?;
    let ledger_exists_after_write = ledger_path.exists();
    let stored_ledger = if ledger_exists_after_write {
        let text = fs::read_to_string(ledger_path).map_err(|err| err.to_string())?;
        Some(
            serde_json::from_str::<GovernanceContinuationDecisionLedger>(&text)
                .map_err(|err| err.to_string())?,
        )
    } else {
        None
    };
    let entry_count = stored_ledger
        .as_ref()
        .map(|ledger| ledger.entry_count)
        .unwrap_or(0);
    let paper_only_count = stored_ledger
        .as_ref()
        .map(|ledger| {
            ledger
                .entries
                .iter()
                .filter(|entry| entry.paper_only)
                .count()
        })
        .unwrap_or(0);
    let policy_apply_allowed_true_count = stored_ledger
        .as_ref()
        .map(|ledger| {
            ledger
                .entries
                .iter()
                .filter(|entry| entry.policy_apply_allowed)
                .count()
        })
        .unwrap_or(0);
    let unsafe_entry_count = stored_ledger
        .as_ref()
        .map(|ledger| {
            ledger
                .entries
                .iter()
                .filter(|entry| {
                    !entry.paper_only || entry.policy_apply_allowed || !entry.apply_locked
                })
                .count()
        })
        .unwrap_or(0);
    let proof_status = if wrote_ledger && !ledger_exists_after_write {
        PaperGovernanceTrialLedgerWriteProofStatus::Failed
    } else if policy_apply_allowed_true_count > 0 {
        PaperGovernanceTrialLedgerWriteProofStatus::Failed
    } else if unsafe_entry_count > 0 {
        PaperGovernanceTrialLedgerWriteProofStatus::ProvenWithWarnings
    } else {
        PaperGovernanceTrialLedgerWriteProofStatus::Proven
    };
    Ok(GovernanceContinuationDecisionLedgerWriteProof {
        proof_id: format!(
            "{}-continuation-ledger-write-proof",
            ledger_path
                .file_stem()
                .and_then(|stem| stem.to_str())
                .unwrap_or("governance-continuation")
        ),
        expected_output_path: ledger_path.display().to_string(),
        wrote_ledger,
        ledger_exists_after_write,
        entry_count,
        paper_only_count,
        policy_apply_allowed_true_count,
        unsafe_entry_count,
        proof_status,
        paper_only: true,
    })
}

pub fn prove_governance_continuation_decision_ledger_write(
    run_result: &GovernanceKeepPolicyReviewRunResult,
    ledger_path: &Path,
) -> Result<GovernanceContinuationDecisionLedgerWriteProof, String> {
    let wrote_ledger = run_result
        .write_proof
        .as_ref()
        .map(|proof| proof.wrote_ledger)
        .unwrap_or(false);
    prove_governance_continuation_decision_ledger_write_with_flag(wrote_ledger, ledger_path)
}

pub fn prove_governance_continuation_decision_ledger_write_v2(
    multirun_result: &GovernanceKeepPolicyReviewMultiRunResult,
    ledger_path: &Path,
) -> Result<GovernanceContinuationDecisionLedgerWriteProofV2, String> {
    validate_local_json_path(ledger_path, "governance continuation decision ledger path")?;
    let ledger_exists_after_write = ledger_path.exists();
    let stored_ledger = if ledger_exists_after_write {
        let text = fs::read_to_string(ledger_path).map_err(|err| err.to_string())?;
        Some(
            serde_json::from_str::<GovernanceContinuationDecisionLedger>(&text)
                .map_err(|err| err.to_string())?,
        )
    } else {
        None
    };
    let entry_count = stored_ledger
        .as_ref()
        .map(|ledger| ledger.entry_count)
        .unwrap_or(0);
    let paper_only_count = stored_ledger
        .as_ref()
        .map(|ledger| {
            ledger
                .entries
                .iter()
                .filter(|entry| entry.paper_only)
                .count()
        })
        .unwrap_or(0);
    let policy_apply_allowed_true_count = stored_ledger
        .as_ref()
        .map(|ledger| {
            ledger
                .entries
                .iter()
                .filter(|entry| entry.policy_apply_allowed)
                .count()
        })
        .unwrap_or(0);
    let unsafe_entry_count = stored_ledger
        .as_ref()
        .map(|ledger| {
            ledger
                .entries
                .iter()
                .filter(|entry| {
                    !entry.paper_only || entry.policy_apply_allowed || !entry.apply_locked
                })
                .count()
        })
        .unwrap_or(0);
    let duplicate_normalized_count = stored_ledger
        .as_ref()
        .map(|ledger| {
            let mut seen = BTreeSet::new();
            let mut duplicates = 0usize;
            for entry in &ledger.entries {
                if !seen.insert(entry.entry_id.clone()) {
                    duplicates += 1;
                }
            }
            duplicates
        })
        .unwrap_or(0);
    let proof_status = if multirun_result.wrote_ledger && !ledger_exists_after_write {
        PaperGovernanceTrialLedgerWriteProofStatus::Failed
    } else if policy_apply_allowed_true_count > 0 {
        PaperGovernanceTrialLedgerWriteProofStatus::Failed
    } else if unsafe_entry_count > 0 || duplicate_normalized_count > 0 {
        PaperGovernanceTrialLedgerWriteProofStatus::ProvenWithWarnings
    } else {
        PaperGovernanceTrialLedgerWriteProofStatus::Proven
    };
    Ok(GovernanceContinuationDecisionLedgerWriteProofV2 {
        proof_id: format!(
            "{}-continuation-ledger-write-proof-v2",
            ledger_path
                .file_stem()
                .and_then(|stem| stem.to_str())
                .unwrap_or("governance-continuation")
        ),
        expected_output_path: ledger_path.display().to_string(),
        wrote_ledger: multirun_result.wrote_ledger,
        ledger_exists_after_write,
        entry_count,
        paper_only_count,
        policy_apply_allowed_true_count,
        unsafe_entry_count,
        duplicate_normalized_count,
        proof_status,
        paper_only: true,
    })
}

fn governance_keep_policy_review_run_status(
    apply_lock_regression: &GovernanceKeepPolicyApplyLockRegression,
    chairman_evaluation: &ChairmanKeepPolicyReviewEvaluation,
) -> PaperGovernanceTrialRunStatus {
    if apply_lock_regression.regression_status
        == GovernanceKeepPolicyApplyLockRegressionStatus::Failed
        || chairman_evaluation.chairman_decision
            == ChairmanKeepPolicyReviewDecision::BlockedBySafety
    {
        PaperGovernanceTrialRunStatus::Failed
    } else if matches!(
        chairman_evaluation.chairman_decision,
        ChairmanKeepPolicyReviewDecision::KeepPolicyForNow
            | ChairmanKeepPolicyReviewDecision::ContinuePaperTrial
    ) {
        PaperGovernanceTrialRunStatus::Passed
    } else {
        PaperGovernanceTrialRunStatus::PassedWithWarnings
    }
}

pub fn run_governance_keep_policy_review(
    refresh_result: &GovernanceRecommendationPipelineRefreshResult,
    feedback_bridge_result: Option<&PaperPolicyOutcomeFeedbackBridgeRunResult>,
    owner_review: Option<&str>,
    config: &GovernanceKeepPolicyReviewRunConfig,
) -> Result<GovernanceKeepPolicyReviewRunResult, String> {
    if !config.paper_only {
        return Err("governance keep-policy review must stay paper_only".to_string());
    }
    if let Some(path) = config.continuation_ledger_input_path.as_ref() {
        validate_local_json_path(
            Path::new(path),
            "governance continuation decision ledger input path",
        )?;
    }
    if let Some(path) = config.continuation_ledger_output_path.as_ref() {
        validate_local_json_path(
            Path::new(path),
            "governance continuation decision ledger output path",
        )?;
    }
    if let Some(path) = config.output_path.as_ref() {
        validate_local_json_path(Path::new(path), "governance keep-policy review output path")?;
    }
    let review_packet =
        build_governance_keep_policy_review_packet(refresh_result, feedback_bridge_result);
    let reentry_safety_guard =
        build_governance_feedback_reentry_safety_guard_from_parts(refresh_result, None, None);
    let rationale =
        build_keep_policy_rationale(&review_packet, None, None, Some(&reentry_safety_guard));
    let owner_review_parse_result = owner_review
        .or(config.owner_review_text.as_deref())
        .filter(|text| !text.trim().is_empty())
        .map(parse_owner_keep_policy_review_text);
    let chairman_evaluation = evaluate_keep_policy_recommendation_with_owner_review(
        &review_packet,
        owner_review_parse_result.as_ref(),
        Some(&reentry_safety_guard),
    );
    let mut continuation_ledger = if let Some(path) = config.continuation_ledger_input_path.as_ref()
    {
        load_governance_continuation_decision_ledger_from_local_json(Path::new(path))?
    } else {
        default_governance_continuation_decision_ledger()
    };
    append_governance_continuation_decision_entry(
        &mut continuation_ledger,
        GovernanceContinuationDecisionLedgerEntry {
            entry_id: format!("{}-continuation-entry", config.run_id),
            run_id: Some(config.run_id.clone()),
            review_packet_id: review_packet.packet_id.clone(),
            owner_intent: owner_review_parse_result
                .as_ref()
                .map(|review| review.intent),
            chairman_decision: chairman_evaluation.chairman_decision,
            recommended_action: review_packet.recommended_action,
            policy_apply_allowed: false,
            apply_locked: true,
            reason: chairman_evaluation.explanation.clone(),
            paper_only: true,
        },
    )?;
    let continuation_stability =
        compute_governance_continuation_decision_stability(&continuation_ledger);
    let apply_lock_regression = build_governance_keep_policy_apply_lock_regression_from_parts(
        &review_packet,
        owner_review_parse_result.as_ref(),
        &chairman_evaluation,
        None,
        None,
    );
    let mut result = GovernanceKeepPolicyReviewRunResult {
        run_id: config.run_id.clone(),
        review_packet,
        rationale,
        owner_review_parse_result,
        chairman_evaluation,
        continuation_ledger,
        continuation_stability,
        apply_lock_regression,
        write_proof: None,
        owner_summary: None,
        run_status: PaperGovernanceTrialRunStatus::PassedWithWarnings,
        paper_only: true,
    };
    if !config.dry_run && config.append_ledger {
        if let Some(path) = config.continuation_ledger_output_path.as_ref() {
            save_governance_continuation_decision_ledger_to_local_json(
                Path::new(path),
                &result.continuation_ledger,
            )?;
            result.write_proof = Some(
                prove_governance_continuation_decision_ledger_write_with_flag(
                    true,
                    Path::new(path),
                )?,
            );
        }
    }
    result.run_status = governance_keep_policy_review_run_status(
        &result.apply_lock_regression,
        &result.chairman_evaluation,
    );
    if config.emit_owner_summary {
        result.owner_summary = Some(build_owner_governance_keep_policy_review_summary(&result));
    }
    if !config.dry_run {
        if let Some(path) = config.output_path.as_ref() {
            write_safe_json(Path::new(path), &result)?;
        }
    }
    Ok(result)
}

pub fn governance_keep_policy_review_multirun_requested_from_flags(
    enabled: bool,
    dry_run: bool,
    run_count: usize,
    owner_review_text: Option<&String>,
    append_ledger: bool,
    ledger_input_path: Option<&String>,
    ledger_output_path: Option<&String>,
    output_path: Option<&String>,
    emit_owner_summary: bool,
) -> bool {
    enabled
        || !dry_run
        || (enabled
            && (run_count != default_governance_keep_policy_review_multirun_count()
                || owner_review_text.is_some_and(|text| !text.trim().is_empty())
                || append_ledger
                || ledger_input_path.is_some()
                || ledger_output_path.is_some()
                || output_path.is_some()
                || emit_owner_summary))
}

fn build_governance_keep_policy_multirun_apply_lock_regression_from_parts(
    per_run_results: &[PerRunKeepPolicyReviewResult],
    owner_review_parse_result: Option<&OwnerKeepPolicyReviewParseResult>,
    continuation_ledger: &GovernanceContinuationDecisionLedger,
    dry_run: bool,
    wrote_ledger: bool,
    batch_before: Option<&BatchCommitteeCycleWithStateResult>,
    batch_after: Option<&BatchCommitteeCycleWithStateResult>,
) -> GovernanceKeepPolicyMultiRunApplyLockRegression {
    let after = batch_after.or(batch_before);
    let policy_apply_allowed_true_detected = per_run_results
        .iter()
        .any(|result| result.policy_apply_allowed)
        || continuation_ledger
            .entries
            .iter()
            .any(|entry| entry.policy_apply_allowed);
    let actual_policy_apply_detected = if let (Some(before), Some(after)) = (batch_before, after) {
        before.batch_result.conservative_voice_tuning_v2_policy
            != after.batch_result.conservative_voice_tuning_v2_policy
            || before.batch_result.chairman_role_voice_floor_policy
                != after.batch_result.chairman_role_voice_floor_policy
    } else {
        false
    };
    let actual_score_mutation_detected = if let (Some(before), Some(after)) = (batch_before, after)
    {
        member_score_changed(
            &before.state_update.updated_member_states,
            &after.state_update.updated_member_states,
        )
    } else {
        false
    };
    let actual_voice_mutation_detected = if let (Some(before), Some(after)) = (batch_before, after)
    {
        member_voice_changed(
            &before.state_update.updated_member_states,
            &after.state_update.updated_member_states,
        )
    } else {
        false
    };
    let committee_decision_mutation_detected =
        if let (Some(before), Some(after)) = (batch_before, after) {
            before.batch_result.committee_sessions != after.batch_result.committee_sessions
        } else {
            false
        };
    let chairman_decision_mutation_detected =
        if let (Some(before), Some(after)) = (batch_before, after) {
            before.batch_result.chairman_decisions != after.batch_result.chairman_decisions
        } else {
            false
        };
    let risk_governor_override_detected = if let (Some(before), Some(after)) = (batch_before, after)
    {
        risk_governor_decision_status_changed(
            &before.batch_result.chairman_decisions,
            &after.batch_result.chairman_decisions,
        )
    } else {
        false
    };
    let owner_forced_apply_detected = owner_review_parse_result.is_some_and(|review| !review.safe);
    let trade_signal_detected = if let (Some(before), Some(after)) = (batch_before, after) {
        value_has_new_debug_marker(
            &before.batch_result.committee_sessions,
            &after.batch_result.committee_sessions,
            &["trade-signal".to_string()],
        )
    } else {
        false
    };
    let order_detected = if let (Some(before), Some(after)) = (batch_before, after) {
        value_has_new_debug_marker(
            &before.batch_result.event_queue,
            &after.batch_result.event_queue,
            &[
                "order".to_string(),
                "order_id".to_string(),
                "submit order".to_string(),
                "execute order".to_string(),
            ],
        )
    } else {
        false
    };
    let broker_order_account_detected = if let (Some(before), Some(after)) = (batch_before, after) {
        value_has_new_debug_marker(
            &before.batch_result.event_queue,
            &after.batch_result.event_queue,
            &[
                "broker".to_string(),
                "order".to_string(),
                "account".to_string(),
            ],
        ) || value_has_new_debug_marker(
            &before.batch_result.committee_sessions,
            &after.batch_result.committee_sessions,
            &[
                "broker".to_string(),
                "order".to_string(),
                "account".to_string(),
            ],
        )
    } else {
        false
    };
    let ledger_write_when_dry_run_detected = dry_run && wrote_ledger;
    let stable_keep_policy_used_as_live_readiness_detected = false;
    let mut violations = Vec::new();
    if policy_apply_allowed_true_detected {
        violations.push("keep-policy multirun opened policy_apply_allowed".to_string());
    }
    if actual_policy_apply_detected {
        violations.push("keep-policy multirun triggered actual policy apply".to_string());
    }
    if actual_score_mutation_detected {
        violations.push("keep-policy multirun mutated actual score".to_string());
    }
    if actual_voice_mutation_detected {
        violations.push("keep-policy multirun mutated actual voice".to_string());
    }
    if committee_decision_mutation_detected {
        violations.push("keep-policy multirun mutated committee decision".to_string());
    }
    if chairman_decision_mutation_detected {
        violations.push("keep-policy multirun mutated chairman decision".to_string());
    }
    if risk_governor_override_detected {
        violations.push("keep-policy multirun overrode Risk Governor".to_string());
    }
    if owner_forced_apply_detected {
        violations.push("owner attempted to force apply during keep-policy multirun".to_string());
    }
    if trade_signal_detected {
        violations.push("keep-policy multirun touched trade signal paths".to_string());
    }
    if order_detected {
        violations.push("keep-policy multirun touched order paths".to_string());
    }
    if broker_order_account_detected {
        violations.push("keep-policy multirun touched broker/order/account paths".to_string());
    }
    if ledger_write_when_dry_run_detected {
        violations.push("keep-policy multirun wrote ledger during dry-run".to_string());
    }
    if stable_keep_policy_used_as_live_readiness_detected {
        violations.push("StableKeepPolicy was treated as live readiness".to_string());
    }
    GovernanceKeepPolicyMultiRunApplyLockRegression {
        regression_id: format!("{}-apply-lock-regression", continuation_ledger.ledger_id),
        policy_apply_allowed_true_detected,
        actual_policy_apply_detected,
        actual_score_mutation_detected,
        actual_voice_mutation_detected,
        committee_decision_mutation_detected,
        chairman_decision_mutation_detected,
        risk_governor_override_detected,
        owner_forced_apply_detected,
        trade_signal_detected,
        order_detected,
        broker_order_account_detected,
        ledger_write_when_dry_run_detected,
        stable_keep_policy_used_as_live_readiness_detected,
        regression_status: if violations.is_empty() {
            GovernanceKeepPolicyMultiRunApplyLockRegressionStatus::Passed
        } else {
            GovernanceKeepPolicyMultiRunApplyLockRegressionStatus::Failed
        },
        violations,
        paper_only: true,
    }
}

pub fn run_keep_policy_multirun_apply_lock_regression(
    multirun_result: &GovernanceKeepPolicyReviewMultiRunResult,
    batch_before: &BatchCommitteeCycleWithStateResult,
    batch_after: Option<&BatchCommitteeCycleWithStateResult>,
) -> GovernanceKeepPolicyMultiRunApplyLockRegression {
    build_governance_keep_policy_multirun_apply_lock_regression_from_parts(
        &multirun_result.per_run_results,
        multirun_result.owner_review_parse_result.as_ref(),
        &multirun_result.continuation_ledger,
        multirun_result.dry_run,
        multirun_result.wrote_ledger,
        Some(batch_before),
        batch_after,
    )
}

fn governance_keep_policy_review_multirun_run_status(
    gate: &StableKeepPolicyReviewGate,
    regression: &GovernanceKeepPolicyMultiRunApplyLockRegression,
) -> PaperGovernanceTrialRunStatus {
    if regression.regression_status == GovernanceKeepPolicyMultiRunApplyLockRegressionStatus::Failed
        || matches!(
            gate.gate_status,
            StableKeepPolicyReviewGateStatus::ApplyLockViolated
                | StableKeepPolicyReviewGateStatus::BlockedBySafety
        )
    {
        PaperGovernanceTrialRunStatus::Failed
    } else if gate.gate_status == StableKeepPolicyReviewGateStatus::StableKeepPolicyConfirmed {
        PaperGovernanceTrialRunStatus::Passed
    } else {
        PaperGovernanceTrialRunStatus::PassedWithWarnings
    }
}

pub fn run_governance_keep_policy_review_multirun(
    refresh_result: &GovernanceRecommendationPipelineRefreshResult,
    feedback_bridge_result: Option<&PaperPolicyOutcomeFeedbackBridgeRunResult>,
    owner_review: Option<&str>,
    config: &GovernanceKeepPolicyReviewMultiRunConfig,
) -> Result<GovernanceKeepPolicyReviewMultiRunResult, String> {
    if !config.paper_only {
        return Err("governance keep-policy review multirun must stay paper_only".to_string());
    }
    for (path, label) in [
        (
            config.continuation_ledger_input_path.as_ref(),
            "governance continuation decision ledger input path",
        ),
        (
            config.continuation_ledger_output_path.as_ref(),
            "governance continuation decision ledger output path",
        ),
        (
            config.output_path.as_ref(),
            "governance keep-policy review multirun output path",
        ),
    ] {
        if let Some(path) = path {
            validate_local_json_path(Path::new(path), label)?;
        }
    }
    if config.run_count == 0 {
        return Err(
            "governance keep-policy review multirun requires positive run_count".to_string(),
        );
    }
    if !config.dry_run && config.append_ledger && config.continuation_ledger_output_path.is_none() {
        return Err(
            "governance keep-policy review multirun requires continuation_ledger_output_path when dry_run=false and append_ledger=true"
                .to_string(),
        );
    }
    let owner_review_parse_result = owner_review
        .or(config.owner_review_text.as_deref())
        .filter(|text| !text.trim().is_empty())
        .map(parse_owner_keep_policy_review_text);
    let reentry_safety_guard =
        build_governance_feedback_reentry_safety_guard_from_parts(refresh_result, None, None);
    let mut continuation_ledger = if let Some(path) = config.continuation_ledger_input_path.as_ref()
    {
        if Path::new(path).exists() {
            load_governance_continuation_decision_ledger_from_local_json(Path::new(path))?
        } else {
            default_governance_continuation_decision_ledger()
        }
    } else {
        default_governance_continuation_decision_ledger()
    };
    let previous_ledger_entry_count = continuation_ledger.entry_count;
    let mut per_run_results = Vec::new();
    for run_index in 0..config.run_count {
        let review_packet =
            build_governance_keep_policy_review_packet(refresh_result, feedback_bridge_result);
        let chairman_evaluation = evaluate_keep_policy_recommendation_with_owner_review(
            &review_packet,
            owner_review_parse_result.as_ref(),
            Some(&reentry_safety_guard),
        );
        let entry_id = format!(
            "{}-entry-{:04}",
            config.run_id,
            previous_ledger_entry_count + run_index + 1
        );
        append_governance_continuation_decision_entry(
            &mut continuation_ledger,
            GovernanceContinuationDecisionLedgerEntry {
                entry_id: entry_id.clone(),
                run_id: Some(format!("{}-run-{:02}", config.run_id, run_index + 1)),
                review_packet_id: review_packet.packet_id.clone(),
                owner_intent: owner_review_parse_result
                    .as_ref()
                    .map(|review| review.intent),
                chairman_decision: chairman_evaluation.chairman_decision,
                recommended_action: review_packet.recommended_action,
                policy_apply_allowed: false,
                apply_locked: true,
                reason: chairman_evaluation.explanation.clone(),
                paper_only: true,
            },
        )?;
        let per_run_regression = build_governance_keep_policy_apply_lock_regression_from_parts(
            &review_packet,
            owner_review_parse_result.as_ref(),
            &chairman_evaluation,
            None,
            None,
        );
        per_run_results.push(PerRunKeepPolicyReviewResult {
            run_index: run_index + 1,
            entry_id: Some(entry_id),
            owner_intent: owner_review_parse_result
                .as_ref()
                .map(|review| review.intent),
            chairman_decision: chairman_evaluation.chairman_decision,
            policy_apply_allowed: false,
            apply_locked: true,
            regression_status: per_run_regression.regression_status,
            paper_only: true,
        });
    }
    let enhanced_stability = compute_governance_continuation_decision_stability_v2(
        &continuation_ledger,
        default_governance_keep_policy_review_min_entries_required(),
    );
    let decision_trend = compute_governance_continuation_decision_trend(&continuation_ledger);
    let apply_lock_regression =
        build_governance_keep_policy_multirun_apply_lock_regression_from_parts(
            &per_run_results,
            owner_review_parse_result.as_ref(),
            &continuation_ledger,
            config.dry_run,
            false,
            None,
            None,
        );
    let stable_keep_policy_review_gate = evaluate_stable_keep_policy_review_gate(
        &enhanced_stability,
        &decision_trend,
        &apply_lock_regression,
    );
    let mut result = GovernanceKeepPolicyReviewMultiRunResult {
        run_id: config.run_id.clone(),
        requested_run_count: config.run_count,
        completed_run_count: per_run_results.len(),
        previous_ledger_entry_count,
        appended_entry_count: continuation_ledger
            .entry_count
            .saturating_sub(previous_ledger_entry_count),
        final_ledger_entry_count: continuation_ledger.entry_count,
        per_run_results,
        continuation_ledger,
        enhanced_stability,
        decision_trend,
        stable_keep_policy_review_gate,
        apply_lock_regression,
        owner_review_parse_result,
        write_proof: None,
        owner_summary: None,
        run_status: PaperGovernanceTrialRunStatus::PassedWithWarnings,
        dry_run: config.dry_run,
        wrote_ledger: false,
        ledger_output_path: config.continuation_ledger_output_path.clone(),
        paper_only: true,
    };
    if !config.dry_run && config.append_ledger {
        if let Some(path) = config.continuation_ledger_output_path.as_ref() {
            save_governance_continuation_decision_ledger_to_local_json(
                Path::new(path),
                &result.continuation_ledger,
            )?;
            result.wrote_ledger = true;
        }
    }
    if !config.dry_run && result.wrote_ledger {
        if let Some(path) = config.continuation_ledger_output_path.as_ref() {
            result.write_proof = Some(prove_governance_continuation_decision_ledger_write_v2(
                &result,
                Path::new(path),
            )?);
        }
    }
    if config.emit_owner_summary {
        result.owner_summary = Some(build_owner_governance_keep_policy_multirun_summary(
            &result,
            &result.stable_keep_policy_review_gate,
        ));
    }
    result.run_status = governance_keep_policy_review_multirun_run_status(
        &result.stable_keep_policy_review_gate,
        &result.apply_lock_regression,
    );
    if !config.dry_run {
        if let Some(path) = config.output_path.as_ref() {
            write_safe_json(Path::new(path), &result)?;
        }
    }
    Ok(result)
}

fn maybe_run_governance_keep_policy_review_for_stateful_result(
    run_id: String,
    enabled: bool,
    dry_run: bool,
    owner_review_text: Option<&String>,
    append_ledger: bool,
    ledger_input_path: Option<&String>,
    ledger_output_path: Option<&String>,
    output_path: Option<&String>,
    emit_owner_summary: bool,
    stateful_result: &mut BatchCommitteeCycleWithStateResult,
) -> Result<Option<GovernanceKeepPolicyReviewRunResult>, String> {
    if !governance_keep_policy_review_requested_from_flags(
        enabled,
        dry_run,
        owner_review_text,
        append_ledger,
        ledger_input_path,
        ledger_output_path,
        output_path,
        emit_owner_summary,
    ) {
        return Ok(None);
    }
    let refresh_result = stateful_result
        .batch_result
        .governance_recommendation_pipeline_refresh_result
        .clone()
        .ok_or_else(|| {
            "governance keep-policy review requires governance recommendation pipeline refresh result"
                .to_string()
        })?;
    let feedback_bridge_result = stateful_result
        .batch_result
        .paper_policy_outcome_feedback_bridge_run_result
        .clone();
    let before_snapshot = stateful_result.clone();
    let mut result = run_governance_keep_policy_review(
        &refresh_result,
        feedback_bridge_result.as_ref(),
        owner_review_text.map(|text| text.as_str()),
        &GovernanceKeepPolicyReviewRunConfig {
            run_id,
            enabled,
            owner_review_text: owner_review_text.cloned(),
            continuation_ledger_input_path: ledger_input_path.cloned(),
            continuation_ledger_output_path: ledger_output_path.cloned(),
            output_path: output_path.cloned(),
            dry_run,
            append_ledger,
            emit_owner_summary,
            paper_only: true,
        },
    )?;
    stateful_result
        .batch_result
        .governance_keep_policy_review_packet = Some(result.review_packet.clone());
    stateful_result
        .batch_result
        .governance_keep_policy_rationale = Some(result.rationale.clone());
    stateful_result
        .batch_result
        .owner_keep_policy_review_parse_result = result.owner_review_parse_result.clone();
    stateful_result
        .batch_result
        .chairman_keep_policy_review_evaluation = Some(result.chairman_evaluation.clone());
    stateful_result
        .batch_result
        .governance_continuation_decision_ledger = Some(result.continuation_ledger.clone());
    stateful_result
        .batch_result
        .governance_continuation_decision_stability = Some(result.continuation_stability.clone());
    stateful_result
        .batch_result
        .governance_keep_policy_apply_lock_regression = Some(result.apply_lock_regression.clone());
    stateful_result
        .batch_result
        .governance_continuation_decision_ledger_write_proof = result.write_proof.clone();
    stateful_result
        .batch_result
        .owner_governance_keep_policy_review_summary = result.owner_summary.clone();
    stateful_result
        .batch_result
        .governance_keep_policy_review_run_result = Some(result.clone());
    let after_snapshot = stateful_result.clone();
    result.apply_lock_regression = run_keep_policy_apply_lock_regression(
        &result.review_packet,
        result.owner_review_parse_result.as_ref(),
        &result.chairman_evaluation,
        &before_snapshot,
        Some(&after_snapshot),
    );
    result.run_status = governance_keep_policy_review_run_status(
        &result.apply_lock_regression,
        &result.chairman_evaluation,
    );
    if emit_owner_summary {
        result.owner_summary = Some(build_owner_governance_keep_policy_review_summary(&result));
    }
    stateful_result
        .batch_result
        .governance_keep_policy_apply_lock_regression = Some(result.apply_lock_regression.clone());
    stateful_result
        .batch_result
        .owner_governance_keep_policy_review_summary = result.owner_summary.clone();
    stateful_result
        .batch_result
        .governance_keep_policy_review_run_result = Some(result.clone());
    Ok(Some(result))
}

fn maybe_run_governance_keep_policy_review_multirun_for_stateful_result(
    run_id: String,
    enabled: bool,
    dry_run: bool,
    run_count: usize,
    owner_review_text: Option<&String>,
    append_ledger: bool,
    ledger_input_path: Option<&String>,
    ledger_output_path: Option<&String>,
    output_path: Option<&String>,
    emit_owner_summary: bool,
    stateful_result: &mut BatchCommitteeCycleWithStateResult,
) -> Result<Option<GovernanceKeepPolicyReviewMultiRunResult>, String> {
    if !governance_keep_policy_review_multirun_requested_from_flags(
        enabled,
        dry_run,
        run_count,
        owner_review_text,
        append_ledger,
        ledger_input_path,
        ledger_output_path,
        output_path,
        emit_owner_summary,
    ) {
        return Ok(None);
    }
    let refresh_result = stateful_result
        .batch_result
        .governance_recommendation_pipeline_refresh_result
        .clone()
        .ok_or_else(|| {
            "governance keep-policy review multirun requires governance recommendation pipeline refresh result"
                .to_string()
        })?;
    let feedback_bridge_result = stateful_result
        .batch_result
        .paper_policy_outcome_feedback_bridge_run_result
        .clone();
    let before_snapshot = stateful_result.clone();
    let mut result = run_governance_keep_policy_review_multirun(
        &refresh_result,
        feedback_bridge_result.as_ref(),
        owner_review_text.map(|text| text.as_str()),
        &GovernanceKeepPolicyReviewMultiRunConfig {
            run_id,
            enabled,
            run_count,
            continuation_ledger_input_path: ledger_input_path.cloned(),
            continuation_ledger_output_path: ledger_output_path.cloned(),
            output_path: output_path.cloned(),
            owner_review_text: owner_review_text.cloned(),
            dry_run,
            append_ledger,
            emit_owner_summary,
            paper_only: true,
        },
    )?;
    stateful_result
        .batch_result
        .governance_continuation_decision_ledger = Some(result.continuation_ledger.clone());
    stateful_result
        .batch_result
        .owner_keep_policy_review_parse_result = result.owner_review_parse_result.clone();
    stateful_result
        .batch_result
        .governance_continuation_decision_stability_v2 = Some(result.enhanced_stability.clone());
    stateful_result
        .batch_result
        .governance_continuation_decision_trend = Some(result.decision_trend.clone());
    stateful_result.batch_result.stable_keep_policy_review_gate =
        Some(result.stable_keep_policy_review_gate.clone());
    stateful_result
        .batch_result
        .governance_keep_policy_multirun_apply_lock_regression =
        Some(result.apply_lock_regression.clone());
    stateful_result
        .batch_result
        .governance_continuation_decision_ledger_write_proof_v2 = result.write_proof.clone();
    stateful_result
        .batch_result
        .owner_governance_keep_policy_multirun_summary = result.owner_summary.clone();
    stateful_result
        .batch_result
        .governance_keep_policy_review_multirun_result = Some(result.clone());
    let after_snapshot = stateful_result.clone();
    result.apply_lock_regression = run_keep_policy_multirun_apply_lock_regression(
        &result,
        &before_snapshot,
        Some(&after_snapshot),
    );
    result.stable_keep_policy_review_gate = evaluate_stable_keep_policy_review_gate(
        &result.enhanced_stability,
        &result.decision_trend,
        &result.apply_lock_regression,
    );
    if emit_owner_summary {
        result.owner_summary = Some(build_owner_governance_keep_policy_multirun_summary(
            &result,
            &result.stable_keep_policy_review_gate,
        ));
    }
    result.run_status = governance_keep_policy_review_multirun_run_status(
        &result.stable_keep_policy_review_gate,
        &result.apply_lock_regression,
    );
    stateful_result
        .batch_result
        .governance_keep_policy_multirun_apply_lock_regression =
        Some(result.apply_lock_regression.clone());
    stateful_result.batch_result.stable_keep_policy_review_gate =
        Some(result.stable_keep_policy_review_gate.clone());
    stateful_result
        .batch_result
        .owner_governance_keep_policy_multirun_summary = result.owner_summary.clone();
    stateful_result
        .batch_result
        .governance_keep_policy_review_multirun_result = Some(result.clone());
    Ok(Some(result))
}

